import heapq as _mobile_heapq

class _MobileVar:
    def __init__(self, master=None, value=None, *a, **k):
        self._value = value
        self._traces = []
    def get(self): return self._value
    def set(self, value):
        self._value = value
        for cb in list(self._traces):
            try: cb(None, None, None)
            except Exception: pass
    def trace_add(self, mode, callback):
        self._traces.append(callback); return str(id(callback))
    def trace(self, *a):
        if a and callable(a[-1]): self._traces.append(a[-1])
        return str(len(self._traces))

