def http_json(url, params=None, timeout=10):
    if params:
        url += ('&' if '?' in url else '?') + urllib.parse.urlencode(params)
    req = urllib.request.Request(url, headers={'Accept': 'application/json', 'User-Agent': 'ChartKingPythonV22/2.0', 'Cache-Control': 'no-cache'})
    with urllib.request.urlopen(req, timeout=timeout) as r:
        return json.loads(r.read().decode('utf-8'))

def parse_iso(s):
    if not s:
        return 0.0
    try:
        return datetime.fromisoformat(s.replace('Z', '+00:00')).timestamp()
    except Exception:
        return 0.0

def money(v):
    try:
        return '${:,.2f}'.format(float(v))
    except Exception:
        return '--'

def cents(v):
    try:
        return '{:.1f}¢'.format(float(v) * 100)
    except Exception:
        return '--'

