    def _start_bookmap_bridge_listener(self):
        if self.bookmap_thread and self.bookmap_thread.is_alive():
            return
        self.bookmap_thread = threading.Thread(target=self._bookmap_udp_worker, name='ChartKing-BookmapBridge', daemon=True)
        self.bookmap_thread.start()

    def _bookmap_udp_worker(self):
        """Receive local-only JSON datagrams emitted by the Bookmap addon."""
        sock = None
        try:
            sock = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
            sock.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
            sock.bind(('127.0.0.1', int(self.bookmap_udp_port)))
            sock.settimeout(0.75)
            self.bookmap_socket = sock
        except Exception as exc:
            self.bookmap_status_var.set(f'BOOKMAP BRIDGE ERROR: {exc}')
            return
        while True:
            try:
                raw, _addr = sock.recvfrom(65535)
            except socket.timeout:
                continue
            except Exception:
                break
            try:
                event = json.loads(raw.decode('utf-8', errors='ignore'))
                self._ingest_bookmap_event(event)
            except Exception:
                self.bookmap_parse_errors += 1

    def _ingest_bookmap_micro_candle(self, seconds, event_ts, price, size):
        """
        DISPLAY ONLY: aggregate every native Bookmap execution into exact 3s/5s
        OHLCV bars. This deliberately does not touch any decision state.
        """
        seconds = int(seconds)
        if seconds not in (3, 5):
            return
        rows = getattr(self, 'bookmap_micro_candles', {}).get(seconds)
        if rows is None:
            return
        ts = float(event_ts)
        px = float(price)
        sz = max(0.0, float(size or 0.0))
        bucket = int(ts // seconds) * seconds
        # Bookmap normally arrives in order. Handle a small late print without
        # changing the close of a newer execution.
        target = None
        for row in reversed(rows):
            rt = int(row.get('time', 0))
            if rt == bucket:
                target = row
                break
            if rt < bucket:
                break
        if target is None:
            if rows and bucket < int(rows[-1].get('time', 0)):
                # Rare late print for a bucket already aged out / never observed.
                # Do not corrupt chronological order of the visual candle deque.
                return
            target = {
                'time': bucket, 'open': px, 'high': px, 'low': px, 'close': px,
                'volume': sz, '_first_ts': ts, '_last_ts': ts,
                '_trade_count': 1, '_open_source': 'BOOKMAP EXECUTION',
                '_live_source': 'BOOKMAP EXECUTIONS'
            }
            rows.append(target)
            return
        target['high'] = max(float(target.get('high', px)), px)
        target['low'] = min(float(target.get('low', px)), px)
        target['volume'] = float(target.get('volume', 0.0) or 0.0) + sz
        target['_trade_count'] = int(target.get('_trade_count', 0) or 0) + 1
        first_ts = float(target.get('_first_ts', ts) or ts)
        last_ts = float(target.get('_last_ts', ts) or ts)
        if ts < first_ts:
            target['open'] = px
            target['_first_ts'] = ts
        if ts >= last_ts:
            target['close'] = px
            target['_last_ts'] = ts

    def _ingest_bookmap_event(self, event):
        if not isinstance(event, dict):
            return
        kind = str(event.get('type', '')).lower().strip()
        now = time.time()
        event_ts = float(event.get('ts', now) or now)
        if event_ts > 1e+16:
            event_ts /= 1000000000.0
        elif event_ts > 1000000000000.0:
            event_ts /= 1000.0
        with self.bookmap_lock:
            self.bookmap_connected = True
            self.bookmap_last_event_ts = now
            self.bookmap_events_received += 1
            if kind == 'hello':
                self.bookmap_alias = str(event.get('alias', '--'))
                self.bookmap_pips = event.get('pips')
                self.bookmap_multiplier = event.get('multiplier')
                return
            if kind == 'bbo':
                self.bookmap_bbo = {'bid': self._web_safe_number(event.get('bid')), 'bid_size': self._web_safe_number(event.get('bid_size'), 0.0), 'ask': self._web_safe_number(event.get('ask')), 'ask_size': self._web_safe_number(event.get('ask_size'), 0.0), 'ts': event_ts}
                return
            if kind == 'depth':
                side = str(event.get('side', '')).lower()
                price = self._web_safe_number(event.get('price'))
                size = self._web_safe_number(event.get('size'), 0.0)
                if price is None:
                    return
                book = self.bookmap_bids if side == 'bid' else self.bookmap_asks
                old = book.get(float(price))
                if size is None or float(size) <= 0:
                    book.pop(float(price), None)
                else:
                    first_seen = float(old.get('first_seen', now)) if old and float(size) >= float(old.get('size', 0.0)) * 0.45 else now
                    book[float(price)] = {'size': float(size), 'first_seen': first_seen, 'updated': now}
                if len(book) > 5000:
                    # Never call effective_live_price() while holding the
                    # Bookmap mutex.  The native implementation may acquire
                    # this same lock and deadlock the receiver + Tk reader.
                    live = self.current_spot
                    if live is None:
                        bid = self.bookmap_bbo.get('bid')
                        ask = self.bookmap_bbo.get('ask')
                        if bid is not None and ask is not None:
                            live = (float(bid) + float(ask)) / 2.0
                    if live is not None:
                        keep = sorted(book.items(), key=lambda kv: abs(kv[0] - float(live)))[:2500]
                        book.clear()
                        book.update(keep)
                return
            if kind == 'trade':
                price = self._web_safe_number(event.get('price'))
                size = self._web_safe_number(event.get('size'), 0.0)
                aggressor = str(event.get('aggressor', 'unknown')).lower()
                if price is not None and size is not None and (float(size) > 0):
                    self.bookmap_trades.append({'ts': event_ts, 'received': now, 'price': float(price), 'size': float(size), 'aggressor': aggressor})
                    # Raw visual micro bars only; no authority over the 15m brain.
                    self._ingest_bookmap_micro_candle(3, event_ts, float(price), float(size))
                    self._ingest_bookmap_micro_candle(5, event_ts, float(price), float(size))
                return
            if kind in ('mbo_send', 'mbo_replace', 'mbo_cancel'):
                self.bookmap_mbo_available = True
                oid = str(event.get('order_id', ''))
                if not oid:
                    return
                prior = self.bookmap_mbo_orders.get(oid)
                if kind == 'mbo_cancel':
                    if prior:
                        lifespan = max(0.0, now - float(prior.get('first_seen', now)))
                        self.bookmap_cancel_events.append({**prior, 'order_id': oid, 'cancel_ts': now, 'lifespan': lifespan})
                    self.bookmap_mbo_orders.pop(oid, None)
                    return
                side = str(event.get('side', prior.get('side') if prior else '')).lower()
                price = self._web_safe_number(event.get('price'))
                size = self._web_safe_number(event.get('size'), 0.0)
                if price is None or size is None or float(size) <= 0:
                    return
                first_seen = float(prior.get('first_seen', now)) if prior else now
                updates = int(prior.get('updates', 0)) + 1 if prior else 0
                row = {'side': side, 'price': float(price), 'size': float(size), 'first_seen': first_seen, 'updated': now, 'updates': updates}
                self.bookmap_mbo_orders[oid] = row
                self.bookmap_mbo_events.append({'type': kind, 'order_id': oid, **row})

    @staticmethod
    def _bookmap_median(values, default=0.0):
        vals = sorted((float(x) for x in values if x is not None and float(x) >= 0))
        if not vals:
            return float(default)
        n = len(vals)
        mid = n // 2
        return vals[mid] if n % 2 else (vals[mid - 1] + vals[mid]) / 2.0

    def _bookmap_learning_read(self, signature, now=None, force=False):
        """
        Compare the current Bookmap signature with CLOSED historical rounds.

        This is empirical memory, not neural retraining. It only contributes a
        small capped adjustment after enough similar resolved examples exist.
        """
        now = float(now or time.time())
        if not force and self.bookmap_learning_last and (now - self._last_bookmap_learning_calc < self.bookmap_learning_cache_interval):
            return dict(self.bookmap_learning_last)
        self._last_bookmap_learning_calc = now
        direction = str(signature.get('direction', 'NEUTRAL')).upper()
        if direction not in ('UP', 'DOWN'):
            out = {'ready': False, 'n': 0, 'win_rate': None, 'bias': 0.0, 'label': 'WHALE MEMORY: waiting for directional signature'}
            self.bookmap_learning_last = out
            return dict(out)
        try:
            with self.stockpile_db_lock:
                with self._stockpile_connect() as conn:
                    rows = conn.execute("\n                        SELECT\n                            bucket, samples, avg_signed, max_abs_signed,\n                            avg_likelihood, avg_confidence,\n                            max_bid_wall_ratio, max_ask_wall_ratio,\n                            avg_trade_imbalance,\n                            buyer_absorption_count,\n                            seller_absorption_count,\n                            final_side\n                        FROM bookmap_whale_rounds\n                        WHERE closed=1\n                          AND final_side IN ('UP','DOWN')\n                          AND samples >= 3\n                        ORDER BY bucket DESC\n                        LIMIT 450\n                    ").fetchall()
        except Exception as exc:
            out = {'ready': False, 'n': 0, 'win_rate': None, 'bias': 0.0, 'label': f'WHALE MEMORY DB: {exc}'}
            self.bookmap_learning_last = out
            return dict(out)
        if not rows:
            out = {'ready': False, 'n': 0, 'win_rate': None, 'bias': 0.0, 'label': 'WHALE MEMORY: collecting resolved Bookmap rounds'}
            self.bookmap_learning_last = out
            return dict(out)
        cur_signed = float(signature.get('signed_score', 0.0) or 0.0)
        cur_bid = float(signature.get('bid_wall_ratio', 0.0) or 0.0)
        cur_ask = float(signature.get('ask_wall_ratio', 0.0) or 0.0)
        cur_imb = float(signature.get('trade_imbalance', 0.0) or 0.0)
        cur_abs = str(signature.get('absorption', 'NONE'))
        candidates = []
        for row in rows:
            bucket, samples, avg_signed, max_abs_signed, avg_likelihood, avg_confidence, max_bid, max_ask, avg_imb, buyer_abs_count, seller_abs_count, final_side = row
            sign_penalty = 0.0
            if cur_signed and float(avg_signed or 0.0):
                if (cur_signed > 0) != (float(avg_signed) > 0):
                    sign_penalty = 1.25
            distance = abs(float(avg_signed or 0.0) - cur_signed) / 34.0 + abs(float(max_bid or 0.0) - cur_bid) / 7.0 + abs(float(max_ask or 0.0) - cur_ask) / 7.0 + abs(float(avg_imb or 0.0) - cur_imb) / 0.65 + sign_penalty
            if cur_abs == 'BUYER ABSORPTION':
                distance += 0.0 if int(buyer_abs_count or 0) > 0 else 0.35
            elif cur_abs == 'SELLER ABSORPTION':
                distance += 0.0 if int(seller_abs_count or 0) > 0 else 0.35
            similarity = math.exp(-max(0.0, distance))
            if similarity >= 0.08:
                candidates.append((similarity, str(final_side), int(samples or 0), int(bucket)))
        candidates.sort(key=lambda x: x[0], reverse=True)
        candidates = candidates[:40]
        if len(candidates) < 5:
            out = {'ready': False, 'n': len(candidates), 'win_rate': None, 'bias': 0.0, 'label': f'WHALE MEMORY: {len(candidates)} similar resolved rounds'}
            self.bookmap_learning_last = out
            return dict(out)
        total_w = sum((x[0] for x in candidates))
        wins_w = sum((sim for sim, final_side, _samples, _bucket in candidates if final_side == direction))
        win_rate = wins_w / max(total_w, 1e-09)
        direction_sign = 1.0 if direction == 'UP' else -1.0
        reliability_edge = (win_rate - 0.5) * 2.0
        sample_factor = min(1.0, len(candidates) / 18.0)
        bias = direction_sign * max(-7.0, min(7.0, reliability_edge * 7.0 * sample_factor))
        out = {'ready': True, 'n': len(candidates), 'win_rate': win_rate, 'bias': bias, 'direction': direction, 'label': f'WHALE MEMORY: {direction} analogs {win_rate * 100:.0f}% resolved {direction} • n={len(candidates)}'}
        self.bookmap_learning_last = out
        return dict(out)

    def _bookmap_persist_learning_sample(self, read, sig=None, now=None):
        """Persist one low-frequency Bookmap snapshot for later resolution."""
        if not read or not read.get('ready'):
            return
        now = float(now or time.time())
        if now - self._last_bookmap_learning_sample < self.bookmap_learning_sample_interval:
            return
        self._last_bookmap_learning_sample = now
        try:
            candles = getattr(self, '_last_analysis_candles', None) or []
            if candles:
                bucket = int(candles[-1]['time']) // 900 * 900
            else:
                bucket = int(now // 900) * 900
            slot = int(max(0.0, now - bucket) // self.bookmap_learning_sample_interval)
            live, _ = self.effective_live_price()
            target, _ = self.effective_target()
            target_delta = float(live) - float(target) if live is not None and target is not None else None
            chart_side = 'WAIT'
            chart_strength = 0.0
            if sig:
                net = float(sig.get('current_net', 0.0) or 0.0) * 0.55 + float(sig.get('fast_net', 0.0) or 0.0) * 0.3 + float(sig.get('pro_net', 0.0) or 0.0) * 0.15
                chart_side = 'UP' if net > 0.35 else 'DOWN' if net < -0.35 else 'MIXED'
                chart_strength = min(10.0, abs(net))
            bid = read.get('bid_wall') or {}
            ask = read.get('ask_wall') or {}
            with self.stockpile_db_lock:
                with self._stockpile_connect() as conn:
                    conn.execute('\n                        INSERT OR REPLACE INTO bookmap_whale_samples (\n                            bucket,sample_slot,ts,\n                            signed_score,direction,likelihood,confidence,\n                            bid_wall_ratio,ask_wall_ratio,\n                            trade_imbalance,absorption,\n                            live_price,target_delta,\n                            chart_side,chart_strength\n                        ) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)\n                    ', (int(bucket), int(slot), now, float(read.get('signed_score', 0.0) or 0.0), str(read.get('direction', 'NEUTRAL')), float(read.get('likelihood', 0.0) or 0.0), float(read.get('confidence', 0.0) or 0.0), float(bid.get('ratio', 0.0) or 0.0), float(ask.get('ratio', 0.0) or 0.0), float(read.get('trade_imbalance', 0.0) or 0.0), str(read.get('absorption', 'NONE')), None if live is None else float(live), target_delta, chart_side, float(chart_strength)))
        except Exception:
            pass

    def _bookmap_finalize_learning_round(self, bucket, final_side, final_price):
        """Aggregate the resolved round into persistent Whale Memory."""
        try:
            with self.stockpile_db_lock:
                with self._stockpile_connect() as conn:
                    row = conn.execute("\n                        SELECT\n                            COUNT(*),\n                            AVG(signed_score),\n                            MAX(ABS(signed_score)),\n                            AVG(likelihood),\n                            AVG(confidence),\n                            MAX(bid_wall_ratio),\n                            MAX(ask_wall_ratio),\n                            AVG(trade_imbalance),\n                            SUM(CASE WHEN absorption='BUYER ABSORPTION' THEN 1 ELSE 0 END),\n                            SUM(CASE WHEN absorption='SELLER ABSORPTION' THEN 1 ELSE 0 END)\n                        FROM bookmap_whale_samples\n                        WHERE bucket=?\n                    ", (int(bucket),)).fetchone()
                    if not row or int(row[0] or 0) <= 0:
                        return
                    samples, avg_signed, max_abs_signed, avg_likelihood, avg_confidence, max_bid, max_ask, avg_imb, buyer_abs, seller_abs = row
                    conn.execute('\n                        INSERT INTO bookmap_whale_rounds (\n                            bucket,samples,avg_signed,max_abs_signed,\n                            avg_likelihood,avg_confidence,\n                            max_bid_wall_ratio,max_ask_wall_ratio,\n                            avg_trade_imbalance,\n                            buyer_absorption_count,seller_absorption_count,\n                            final_side,final_price,closed\n                        ) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,1)\n                        ON CONFLICT(bucket) DO UPDATE SET\n                            samples=excluded.samples,\n                            avg_signed=excluded.avg_signed,\n                            max_abs_signed=excluded.max_abs_signed,\n                            avg_likelihood=excluded.avg_likelihood,\n                            avg_confidence=excluded.avg_confidence,\n                            max_bid_wall_ratio=excluded.max_bid_wall_ratio,\n                            max_ask_wall_ratio=excluded.max_ask_wall_ratio,\n                            avg_trade_imbalance=excluded.avg_trade_imbalance,\n                            buyer_absorption_count=excluded.buyer_absorption_count,\n                            seller_absorption_count=excluded.seller_absorption_count,\n                            final_side=excluded.final_side,\n                            final_price=excluded.final_price,\n                            closed=1\n                    ', (int(bucket), int(samples), float(avg_signed or 0.0), float(max_abs_signed or 0.0), float(avg_likelihood or 0.0), float(avg_confidence or 0.0), float(max_bid or 0.0), float(max_ask or 0.0), float(avg_imb or 0.0), int(buyer_abs or 0), int(seller_abs or 0), str(final_side), float(final_price)))
            self.bookmap_learning_last = {}
            self._last_bookmap_learning_calc = 0.0
        except Exception:
            pass

    def _bookmap_chart_fusion(self, sig, candles=None, whale=None):
        """
        Fuse Bookmap with chart evidence without double-counting it as a
        standalone oracle. Whale pressure earns maximum authority only when
        live chart structure corroborates the same side.
        """
        whale = dict(whale or self._bookmap_whale_read())
        if not whale.get('ready'):
            return {'ready': False, 'state': 'WAIT', 'direction': 'WAIT', 'decision_weight': 0.0, 'chart_confirmations': 0, 'label': 'WHALE + CHART FUSION: waiting'}
        wd = str(whale.get('direction', 'NEUTRAL')).upper()
        if wd not in ('UP', 'DOWN'):
            return {'ready': True, 'state': 'NEUTRAL', 'direction': 'NEUTRAL', 'decision_weight': 0.0, 'chart_confirmations': 0, 'label': 'WHALE + CHART FUSION: no directional whale edge'}
        sign = 1.0 if wd == 'UP' else -1.0
        cache = getattr(self, 'chart_commentary_cache', {}) or {}
        commentary_key = tuple((str((cache.get(tf) or {}).get('bias', '')) for tf in ('15s', '30s', '1m', '5m', '15m')))
        candle_tail = None
        if candles:
            try:
                last_c = candles[-1]
                candle_tail = (int(last_c.get('time', 0) or 0), round(float(last_c.get('close', 0.0) or 0.0), 2))
            except Exception:
                candle_tail = None
        fusion_key = (wd, round(float(whale.get('signed_score', 0.0) or 0.0), 1), int(whale.get('event_count', 0) or 0), round(float((sig or {}).get('current_net', 0.0) or 0.0), 2), round(float((sig or {}).get('fast_net', 0.0) or 0.0), 2), round(float((sig or {}).get('pro_net', 0.0) or 0.0), 2), candle_tail, commentary_key)
        if fusion_key == getattr(self, 'bookmap_fusion_cache_key', None) and getattr(self, 'bookmap_fusion_cache_value', None):
            return dict(self.bookmap_fusion_cache_value)
        confirmations = 0
        contradictions = 0
        reasons = []
        if sig:
            for key, label, threshold in (('current_net', 'current', 1.0), ('fast_net', 'fast', 1.0), ('pro_net', 'pro', 1.0)):
                value = float(sig.get(key, 0.0) or 0.0)
                if value * sign >= threshold:
                    confirmations += 1
                    reasons.append(label)
                elif value * sign <= -threshold:
                    contradictions += 1
        for tf in ('15s', '30s', '1m', '5m', '15m'):
            bias = str((cache.get(tf) or {}).get('bias', '')).upper()
            if wd in bias:
                confirmations += 1
                reasons.append(tf)
            elif ('UP' in bias or 'DOWN' in bias) and wd not in bias:
                contradictions += 1
        try:
            pattern = self._confidence_pattern_guard(sig or {}, candles or getattr(self, '_last_analysis_candles', []) or [], lock_side='WAIT')
        except Exception:
            pattern = {}
        if str(pattern.get('direction', 'WAIT')).upper() == wd:
            if bool(pattern.get('confirmed', False)):
                confirmations += 2
                reasons.append('pattern')
            elif float(pattern.get('score', 0.0) or 0.0) >= 72:
                confirmations += 1
        learned = whale.get('learning') or {}
        learned_wr = learned.get('win_rate')
        learned_multiplier = 1.0
        if learned.get('ready') and learned_wr is not None:
            learned_multiplier = max(0.78, min(1.18, 0.82 + float(learned_wr) * 0.42))
        base = abs(float(whale.get('signed_score', 0.0) or 0.0)) / 11.0
        if confirmations >= 4 and contradictions <= 1:
            state = 'ALIGNED'
            multiplier = 1.32
        elif confirmations >= 2 and contradictions <= 2:
            state = 'LEAN ALIGNED'
            multiplier = 1.08
        elif contradictions >= 4:
            state = 'CONFLICT'
            multiplier = 0.38
        else:
            state = 'MIXED'
            multiplier = 0.68
        decision_weight = sign * min(8.5, base * multiplier * learned_multiplier)
        label = f'WHALE + CHART FUSION: {state} {wd} • {confirmations} confirms / {contradictions} conflicts • weight {decision_weight:+.1f}/10'
        out = {'ready': True, 'state': state, 'direction': wd, 'decision_weight': decision_weight, 'chart_confirmations': confirmations, 'chart_contradictions': contradictions, 'reasons': reasons[-6:], 'label': label}
        self.bookmap_fusion_cache_key = fusion_key
        self.bookmap_fusion_cache_value = dict(out)
        return out

    def _bookmap_capture_heatmap(self, read=None, now=None, force=False):
        """
        Capture Bookmap depth history for the mini heatmap.

        Uses Bookmap's own local reference price. If the provider has not yet
        emitted usable depth levels, recent Bookmap trades are shown as a
        clearly-labeled FLOW TAPE fallback rather than an endless blank card.
        """
        now = float(now or time.time())
        if not force and now - self._last_bookmap_heatmap_capture < self.bookmap_heatmap_interval:
            return False
        self._last_bookmap_heatmap_capture = now
        ref, ref_source = self._bookmap_reference_price(now)
        if ref is None:
            return False
        ref = float(ref)
        window = max(350.0, ref * 0.006)
        with self.bookmap_lock:
            bids = {p: dict(v) for p, v in self.bookmap_bids.items()
                    if 0.0 <= ref - float(p) <= window}
            asks = {p: dict(v) for p, v in self.bookmap_asks.items()
                    if 0.0 <= float(p) - ref <= window}
            trades = [dict(t) for t in self.bookmap_trades
                      if now - float(t.get('received', t.get('ts', 0.0)) or 0.0) <= 13.0]
        rows = []
        for side, book in (('bid', bids), ('ask', asks)):
            for price, row in book.items():
                price = float(price)
                size = float(row.get('size', 0.0) or 0.0)
                if abs(price - ref) <= window and size > 0:
                    rows.append((side, price, size))
        mode = 'DEPTH'
        compact = []
        if rows:
            median = max(1e-09, self._bookmap_median([r[2] for r in rows], 1.0))
            for side, price, size in rows:
                ratio = size / median
                if ratio >= 0.45:
                    compact.append((side, price, min(14.0, ratio)))
            bid_levels = sorted((r for r in compact if r[0] == 'bid'), key=lambda r: (-float(r[2]), abs(float(r[1]) - ref)))[:28]
            ask_levels = sorted((r for r in compact if r[0] == 'ask'), key=lambda r: (-float(r[2]), abs(float(r[1]) - ref)))[:28]
            compact = bid_levels + ask_levels
        else:
            mode = 'TRADE TAPE'
            recent = [t for t in trades if now - float(t.get('received', 0.0) or 0.0) <= 12.0 and abs(float(t.get('price', ref)) - ref) <= window]
            if recent:
                sizes = [float(t.get('size', 0.0) or 0.0) for t in recent]
                median = max(1e-09, self._bookmap_median(sizes, 1.0))
                for t in recent[-60:]:
                    side = 'trade_buy' if str(t.get('aggressor', '')).lower() == 'buy' else 'trade_sell'
                    compact.append((side, float(t['price']), min(14.0, float(t.get('size', 0.0) or 0.0) / median)))
        if not compact:
            return False
        self.bookmap_heatmap_history.append({'ts': now, 'live': ref, 'window': window, 'levels': compact, 'mode': mode, 'source': ref_source})
        return True

    def _bookmap_heatmap_is_visible(self):
        if getattr(self, 'web_only_mode', False):
            return False
        try:
            canvas = getattr(self, 'bookmap_heatmap_canvas', None)
            if canvas is None or not canvas.winfo_ismapped():
                return False
            root_top = self.root.winfo_rooty()
            root_bottom = root_top + self.root.winfo_height()
            top = canvas.winfo_rooty()
            bottom = top + canvas.winfo_height()
            return bottom >= root_top - 60 and top <= root_bottom + 60
        except Exception:
            return True

    def _draw_bookmap_heatmap(self, force=False):
        canvas = getattr(self, 'bookmap_heatmap_canvas', None)
        if canvas is None:
            return
        now = time.time()
        if not force and now < getattr(self, '_scroll_active_until', 0.0):
            return
        if not force and (not self._bookmap_heatmap_is_visible()):
            return
        if not force and now - self._last_bookmap_heatmap_draw < self.bookmap_heatmap_draw_interval:
            return
        history = list(self.bookmap_heatmap_history)
        if not history:
            render_key = ('empty',)
        else:
            latest = history[-1]
            render_key = (len(history), round(float(latest.get('live', 0.0) or 0.0), 1), str(latest.get('mode', '')), str((self.bookmap_whale_last or {}).get('direction', 'NEUTRAL')), round(float((self.bookmap_whale_last or {}).get('likelihood', 0.0) or 0.0)), int(canvas.winfo_width()), int(canvas.winfo_height()))
        if not force and render_key == self._last_bookmap_heatmap_render_key:
            return
        self._last_bookmap_heatmap_draw = now
        self._last_bookmap_heatmap_render_key = render_key
        try:
            w = max(260, int(canvas.winfo_width()))
            h = max(150, int(canvas.winfo_height()))
            canvas.delete('all')
            canvas.create_rectangle(0, 0, w, h, fill=VOID, outline=PINK_EDGE)
            if not history:
                canvas.create_text(10, 10, text='WAITING FOR FIRST BOOKMAP DEPTH / TRADE SNAPSHOT...', fill=MUTED, anchor='nw', font=('Cascadia Mono', 8, 'bold'))
                return
            if len(history) > 36:
                step = (len(history) - 1) / 35.0
                sampled = []
                used = set()
                for j in range(36):
                    i = min(len(history) - 1, int(round(j * step)))
                    if i not in used:
                        sampled.append(history[i])
                        used.add(i)
                history = sampled
            latest = history[-1]
            center = float(latest['live'])
            window = float(latest.get('window', max(180.0, center * 0.0032)))
            hi = center + window
            lo = center - window
            left = 42
            right = 8
            top = 18
            bottom = 20
            pw = max(1, w - left - right)
            ph = max(1, h - top - bottom)

            def yy(price):
                return top + (hi - float(price)) / (hi - lo) * ph
            for j in range(5):
                price = hi - (hi - lo) * j / 4
                y = yy(price)
                canvas.create_line(left, y, w - right, y, fill='#1b0d18')
                canvas.create_text(left - 5, y, text=f'{price:,.0f}', fill=MUTED, anchor='e', font=('Cascadia Mono', 7))
            bid_palette = ('#12211d', '#18362c', '#225443', '#34765a', '#49aa7d', '#66f2bd')
            ask_palette = ('#23101a', '#381326', '#5a1a38', '#85224f', '#bd2d6c', '#ff3d8f')
            n = max(1, len(history))
            col_w = max(2.0, pw / n)
            live_pts = []
            for i, snap in enumerate(history):
                x1 = left + i * col_w
                x2 = min(w - right, x1 + col_w + 1)
                levels = sorted(snap.get('levels', []), key=lambda r: float(r[2] or 0.0), reverse=True)[:56]
                for side, price, ratio in levels:
                    if not lo <= float(price) <= hi:
                        continue
                    intensity = max(0, min(5, int((float(ratio) - 0.55) / 1.45)))
                    if side in ('bid', 'trade_buy'):
                        color = bid_palette[max(1, intensity) if side == 'trade_buy' else intensity]
                    else:
                        color = ask_palette[max(1, intensity) if side == 'trade_sell' else intensity]
                    y = yy(price)
                    canvas.create_rectangle(x1, y - 2, x2, y + 2, fill=color, outline='')
                live_pts.extend((x1 + col_w / 2, yy(snap['live'])))
            if len(live_pts) >= 4:
                canvas.create_line(*live_pts, fill=TEXT, width=2)
            whale = self.bookmap_whale_last or {}
            direction = str(whale.get('direction', 'NEUTRAL'))
            likelihood = float(whale.get('likelihood', 0.0) or 0.0)
            col = GREEN if direction == 'UP' else RED if direction == 'DOWN' else PINK2
            canvas.create_text(left + 4, 5, text=f"BOOKMAP {latest.get('mode', 'DEPTH')} // WHALE {direction} {likelihood:.0f}/100", fill=col, anchor='nw', font=('Cascadia Mono', 7, 'bold'))
        except Exception:
            pass

    def _bookmap_reference_price(self, now=None):
        """
        Use Bookmap's own market as the reference for Bookmap depth.

        This avoids filtering out valid Bookmap liquidity merely because the
        public spot quote mesh is on a slightly different venue/instrument.
        """
        now = float(now or time.time())
        with self.bookmap_lock:
            bbo = dict(self.bookmap_bbo)
            trades = list(self.bookmap_trades)[-20:]
            bids = list(self.bookmap_bids.keys())
            asks = list(self.bookmap_asks.keys())
        for trade in reversed(trades):
            if now - float(trade.get('received', 0.0) or 0.0) <= 4.0:
                try:
                    return (float(trade['price']), 'BOOKMAP TRADE')
                except Exception:
                    pass
        bid = bbo.get('bid')
        ask = bbo.get('ask')
        if bid is not None and ask is not None:
            try:
                return ((float(bid) + float(ask)) / 2.0, 'BOOKMAP BBO')
            except Exception:
                pass
        if bids and asks:
            try:
                best_bid = max((float(x) for x in bids))
                best_ask = min((float(x) for x in asks))
                if best_bid <= best_ask:
                    return ((best_bid + best_ask) / 2.0, 'BOOKMAP DEPTH MID')
            except Exception:
                pass
        live, source = self.effective_live_price()
        if live is not None:
            return (float(live), f'CHART FALLBACK {source}')
        return (None, 'WAIT')

    def _bookmap_whale_read(self, now=None, force=False):
        """
        Estimate LARGE-PLAYER / whale-like pressure from Bookmap order-flow.

        This does not identify a person or wallet. It looks for relative order
        size, persistent liquidity walls, aggressive trade imbalance,
        absorption, MBO persistence, and fast large-order cancellations.
        """
        now = float(now or time.time())
        if not force and self.bookmap_whale_last and (now - self._last_bookmap_whale_calc < self.bookmap_whale_calc_interval):
            return dict(self.bookmap_whale_last)
        self._last_bookmap_whale_calc = now
        with self.bookmap_lock:
            age = now - float(self.bookmap_last_event_ts or 0.0)
            alias = str(self.bookmap_alias)
            bbo = dict(self.bookmap_bbo)
            _ref = self.current_spot
            if _ref is None:
                _bid = bbo.get('bid')
                _ask = bbo.get('ask')
                if _bid is not None and _ask is not None:
                    _ref = (float(_bid) + float(_ask)) / 2.0
            if _ref is not None:
                _copy_window = max(450.0, float(_ref) * 0.0065)
                bids = {p: dict(v) for p, v in self.bookmap_bids.items()
                        if 0.0 <= float(_ref) - float(p) <= _copy_window}
                asks = {p: dict(v) for p, v in self.bookmap_asks.items()
                        if 0.0 <= float(p) - float(_ref) <= _copy_window}
            else:
                bids = {p: dict(v) for p, v in self.bookmap_bids.items()}
                asks = {p: dict(v) for p, v in self.bookmap_asks.items()}
            trades = [dict(t) for t in self.bookmap_trades
                      if now - float(t.get('received', t.get('ts', 0.0)) or 0.0) <= 65.0]
            # V21.56 snapshots only the decision-relevant active MBO working
            # set.  The old code copied an unbounded order map on Tk's UI
            # thread every ~300 ms, which eventually froze the entire window.
            mbo = _v256_mbo_snapshot_locked(self, now, _ref)
            cancels = [dict(c) for c in self.bookmap_cancel_events
                       if now - float(c.get('cancel_ts', 0.0) or 0.0) <= 20.0]
            mbo_available = bool(self.bookmap_mbo_available)
            event_count = int(self.bookmap_events_received)
        if age > 3.0 or event_count < 2:
            out = {'ready': False, 'connected': age <= 3.0 and event_count > 0, 'age': age, 'alias': alias, 'direction': 'WAIT', 'likelihood': 0.0, 'confidence': 0.0, 'signed_score': 0.0, 'label': 'BOOKMAP WAITING', 'detail': 'Attach the Chart King Bookmap Bridge to a BTC instrument.', 'mbo_available': mbo_available}
            self.bookmap_whale_last = out
            return dict(out)
        live, bookmap_price_source = self._bookmap_reference_price(now)
        if live is None:
            bid = bbo.get('bid')
            ask = bbo.get('ask')
            if bid is not None and ask is not None:
                live = (float(bid) + float(ask)) / 2.0
            elif trades:
                live = float(trades[-1]['price'])
        if live is None:
            out = {'ready': False, 'connected': True, 'age': age, 'alias': alias, 'direction': 'WAIT', 'likelihood': 0.0, 'confidence': 0.0, 'signed_score': 0.0, 'label': 'BOOKMAP BUILDING', 'detail': 'Waiting for a usable BTC price reference.', 'mbo_available': mbo_available}
            self.bookmap_whale_last = out
            return dict(out)
        live = float(live)
        depth_window = max(250.0, live * 0.0045)
        near_bids = [(p, v) for p, v in bids.items() if 0 <= live - p <= depth_window]
        near_asks = [(p, v) for p, v in asks.items() if 0 <= p - live <= depth_window]
        depth_sizes = [v['size'] for _, v in near_bids + near_asks if v.get('size', 0) > 0]
        depth_median = max(1e-09, self._bookmap_median(depth_sizes, 1.0))

        def best_wall(rows, side):
            best = None
            for price, row in rows:
                size = float(row.get('size', 0.0))
                ratio = size / depth_median
                distance = abs(price - live)
                proximity = max(0.2, 1.0 - distance / max(depth_window, 1.0))
                persistence = max(0.0, now - float(row.get('first_seen', now)))
                persistence_bonus = min(1.45, 1.0 + persistence / 18.0)
                wall_score = ratio * proximity * persistence_bonus
                item = {'side': side, 'price': float(price), 'size': size, 'ratio': ratio, 'distance': distance, 'persistence': persistence, 'wall_score': wall_score}
                if best is None or item['wall_score'] > best['wall_score']:
                    best = item
            return best
        bid_wall = best_wall(near_bids, 'BID')
        ask_wall = best_wall(near_asks, 'ASK')
        recent60 = [t for t in trades if now - float(t.get('received', 0)) <= 60.0]
        recent15 = [t for t in recent60 if now - float(t.get('received', 0)) <= 15.0]
        trade_median = max(1e-09, self._bookmap_median([t['size'] for t in recent60], 1.0))
        buy_vol = sum((t['size'] for t in recent15 if t.get('aggressor') == 'buy'))
        sell_vol = sum((t['size'] for t in recent15 if t.get('aggressor') == 'sell'))
        total_aggr = buy_vol + sell_vol
        trade_imbalance = (buy_vol - sell_vol) / max(total_aggr, 1e-09)
        large_trades = [t for t in recent15 if t['size'] / trade_median >= 4.0]
        largest_trade_ratio = max([t['size'] / trade_median for t in recent15] or [0.0])
        mbo_rows = list(mbo.values())
        mbo_median = max(1e-09, self._bookmap_median([r.get('size', 0) for r in mbo_rows], 1.0))
        persistent_large = []
        for r in mbo_rows:
            ratio = float(r.get('size', 0.0)) / mbo_median
            age_order = now - float(r.get('first_seen', now))
            if ratio >= 4.0 and age_order >= 1.25:
                persistent_large.append({**r, 'ratio': ratio, 'age': age_order})
        big_bid_mbo = [r for r in persistent_large if r.get('side') == 'bid']
        big_ask_mbo = [r for r in persistent_large if r.get('side') == 'ask']
        max_bid_mbo = max([r['ratio'] for r in big_bid_mbo] or [0.0])
        max_ask_mbo = max([r['ratio'] for r in big_ask_mbo] or [0.0])
        recent_cancels = [c for c in cancels if now - float(c.get('cancel_ts', 0)) <= 15.0]
        cancel_sizes = [c.get('size', 0) for c in recent_cancels]
        cancel_median = max(1e-09, self._bookmap_median(cancel_sizes, mbo_median))
        spoof_bid = 0.0
        spoof_ask = 0.0
        for c in recent_cancels:
            ratio = float(c.get('size', 0.0)) / cancel_median
            if ratio >= 4.0 and float(c.get('lifespan', 99)) <= 2.0:
                if c.get('side') == 'bid':
                    spoof_bid = max(spoof_bid, ratio)
                elif c.get('side') == 'ask':
                    spoof_ask = max(spoof_ask, ratio)
        absorption = 'NONE'
        absorption_strength = 0.0
        if len(recent15) >= 4 and total_aggr > 0:
            first_trade = float(recent15[0]['price'])
            last_trade = float(recent15[-1]['price'])
            move_pct = abs(last_trade - first_trade) / max(live, 1.0)
            if buy_vol >= sell_vol * 1.8 and move_pct <= 0.00035:
                absorption = 'SELLER ABSORPTION'
                absorption_strength = min(1.0, buy_vol / max(sell_vol, trade_median) / 4.0)
            elif sell_vol >= buy_vol * 1.8 and move_pct <= 0.00035:
                absorption = 'BUYER ABSORPTION'
                absorption_strength = min(1.0, sell_vol / max(buy_vol, trade_median) / 4.0)
        signed = 0.0
        reasons = []
        categories = 0

        def contribute(value, reason, category=True):
            nonlocal signed, categories
            if abs(value) < 0.01:
                return
            signed += float(value)
            reasons.append(reason)
            if category:
                categories += 1
        if bid_wall and bid_wall['ratio'] >= 2.5:
            val = min(24.0, (bid_wall['ratio'] - 2.0) * 4.4)
            contribute(val, f"persistent BID wall x{bid_wall['ratio']:.1f} @ {money(bid_wall['price'])}")
        if ask_wall and ask_wall['ratio'] >= 2.5:
            val = min(24.0, (ask_wall['ratio'] - 2.0) * 4.4)
            contribute(-val, f"persistent ASK wall x{ask_wall['ratio']:.1f} @ {money(ask_wall['price'])}")
        if abs(trade_imbalance) >= 0.18 and total_aggr >= trade_median * 4:
            val = min(22.0, abs(trade_imbalance) * 27.0)
            contribute(val if trade_imbalance > 0 else -val, f"aggressive flow {('BUY' if trade_imbalance > 0 else 'SELL')} {abs(trade_imbalance) * 100:.0f}%")
        if max_bid_mbo >= 4.0:
            contribute(min(18.0, (max_bid_mbo - 3.0) * 3.0), f'large persistent MBO bid x{max_bid_mbo:.1f}')
        if max_ask_mbo >= 4.0:
            contribute(-min(18.0, (max_ask_mbo - 3.0) * 3.0), f'large persistent MBO ask x{max_ask_mbo:.1f}')
        if absorption == 'BUYER ABSORPTION':
            contribute(16.0 * absorption_strength, 'buyer absorption under sell aggression')
        elif absorption == 'SELLER ABSORPTION':
            contribute(-16.0 * absorption_strength, 'seller absorption under buy aggression')
        if spoof_ask >= 4.0:
            contribute(min(8.0, (spoof_ask - 3.0) * 1.4), f'ASK wall fast-cancel signature x{spoof_ask:.1f}')
        if spoof_bid >= 4.0:
            contribute(-min(8.0, (spoof_bid - 3.0) * 1.4), f'BID wall fast-cancel signature x{spoof_bid:.1f}')
        if largest_trade_ratio >= 5.0:
            reasons.append(f'large print x{largest_trade_ratio:.1f} recent-trade median')
        signed = max(-100.0, min(100.0, signed))
        raw_direction = 'UP' if signed >= 10.0 else 'DOWN' if signed <= -10.0 else 'NEUTRAL'
        learning = self._bookmap_learning_read({'direction': raw_direction, 'signed_score': signed, 'bid_wall_ratio': float((bid_wall or {}).get('ratio', 0.0) or 0.0), 'ask_wall_ratio': float((ask_wall or {}).get('ratio', 0.0) or 0.0), 'trade_imbalance': trade_imbalance, 'absorption': absorption}, now=now)
        if learning.get('ready'):
            learned_bias = float(learning.get('bias', 0.0) or 0.0)
            signed = max(-100.0, min(100.0, signed + learned_bias))
            if abs(learned_bias) >= 1.0:
                reasons.append(f"Whale Memory {learning.get('win_rate', 0) * 100:.0f}% on {learning.get('n', 0)} similar rounds")
        direction = 'UP' if signed >= 10.0 else 'DOWN' if signed <= -10.0 else 'NEUTRAL'
        activity = 0.0
        activity += min(18.0, max(bid_wall['ratio'] if bid_wall else 0.0, ask_wall['ratio'] if ask_wall else 0.0) * 2.0)
        activity += min(12.0, largest_trade_ratio * 1.2)
        activity += min(12.0, max(max_bid_mbo, max_ask_mbo) * 1.2)
        activity += min(8.0, len(large_trades) * 2.0)
        likelihood = max(0.0, min(99.0, 18.0 + abs(signed) * 0.62 + activity))
        data_modes = 0
        if near_bids or near_asks:
            data_modes += 1
        if recent60:
            data_modes += 1
        if mbo_available and mbo_rows:
            data_modes += 1
        confidence = max(0.0, min(98.0, 32.0 + data_modes * 15.0 + min(25.0, categories * 6.0) + min(12.0, abs(signed) * 0.12)))
        if direction in ('UP', 'DOWN') and likelihood >= 72 and (confidence >= 60):
            label = f'LIKELY WHALE {direction} • {likelihood:.0f}/100'
        elif direction in ('UP', 'DOWN') and likelihood >= 52:
            label = f'WHALE PRESSURE {direction} • {likelihood:.0f}/100'
        else:
            label = f'NO CLEAR WHALE EDGE • activity {likelihood:.0f}/100'
        out = {'ready': True, 'connected': True, 'age': age, 'alias': alias, 'direction': direction, 'likelihood': likelihood, 'confidence': confidence, 'signed_score': signed, 'categories': categories, 'label': label, 'detail': ' • '.join(reasons[-6:]) if reasons else 'No outsized relative order-flow cluster yet.', 'bid_wall': bid_wall, 'ask_wall': ask_wall, 'buy_volume_15s': buy_vol, 'sell_volume_15s': sell_vol, 'trade_imbalance': trade_imbalance, 'large_trade_count': len(large_trades), 'largest_trade_ratio': largest_trade_ratio, 'absorption': absorption, 'mbo_available': mbo_available, 'persistent_mbo_bids': len(big_bid_mbo), 'persistent_mbo_asks': len(big_ask_mbo), 'max_bid_mbo_ratio': max_bid_mbo, 'max_ask_mbo_ratio': max_ask_mbo, 'spoof_bid_cancel_ratio': spoof_bid, 'spoof_ask_cancel_ratio': spoof_ask, 'event_count': event_count, 'bookmap_reference_price': live, 'bookmap_price_source': bookmap_price_source, 'depth_bid_levels': len(near_bids), 'depth_ask_levels': len(near_asks), 'learning': learning}
        self.bookmap_whale_last = out
        return dict(out)

    def _bookmap_wave_read(self, now=None, whale=None, force=False):
        """
        V7.3 Richie-style wave reader.

        Detects a developing directional *wave* rather than reacting to one
        print. It combines:
          - aggressive executed-flow imbalance (2s + 6s),
          - short-horizon price impulse / acceleration,
          - nearby bid-vs-ask depth pressure,
          - the existing whale-pressure score as confirmation.

        The output is deliberately separate from the V97 decision brain. The
        latch uses sub-second / ~1s persistence so it can react quickly without
        becoming a one-tick UP/DOWN roulette display.
        """
        now = float(now or time.time())
        if not force and self.bookmap_wave_last and (now - self._last_bookmap_wave_calc < self.bookmap_wave_calc_interval):
            return dict(self.bookmap_wave_last)
        self._last_bookmap_wave_calc = now
        with self.bookmap_lock:
            age = now - float(self.bookmap_last_event_ts or 0.0)
            trades = [dict(t) for t in self.bookmap_trades
                      if now - float(t.get('received', t.get('ts', 0.0)) or 0.0) <= 7.0]
            bbo = dict(self.bookmap_bbo)
            _ref = self.current_spot
            if _ref is None:
                _bid = bbo.get('bid')
                _ask = bbo.get('ask')
                if _bid is not None and _ask is not None:
                    _ref = (float(_bid) + float(_ask)) / 2.0
            if _ref is not None:
                _copy_window = max(100.0, float(_ref) * 0.0018)
                bids = {p: dict(v) for p, v in self.bookmap_bids.items()
                        if 0.0 <= float(_ref) - float(p) <= _copy_window}
                asks = {p: dict(v) for p, v in self.bookmap_asks.items()
                        if 0.0 <= float(p) - float(_ref) <= _copy_window}
            else:
                bids = {p: dict(v) for p, v in self.bookmap_bids.items()}
                asks = {p: dict(v) for p, v in self.bookmap_asks.items()}
        if age > 3.0 or len(trades) < 3:
            out = {'ready': False, 'direction': 'WAIT', 'raw_direction': 'WAIT', 'phase': 'BUILDING', 'strength': 0.0, 'signed_score': 0.0, 'flip_risk': 0.0, 'detail': 'Waiting for enough native Bookmap trades to form a wave.'}
            self.bookmap_wave_last = out
            return dict(out)

        def received(t):
            return float(t.get('received', t.get('ts', 0.0)) or 0.0)
        recent6 = [t for t in trades if now - received(t) <= 6.0]
        recent2 = [t for t in recent6 if now - received(t) <= 2.0]
        prior2 = [t for t in recent6 if 2.0 < now - received(t) <= 4.0]
        if len(recent6) < 3:
            out = {'ready': False, 'direction': 'WAIT', 'raw_direction': 'WAIT', 'phase': 'BUILDING', 'strength': 0.0, 'signed_score': 0.0, 'flip_risk': 0.0, 'detail': 'Collecting the first 6-second Bookmap wave window.'}
            self.bookmap_wave_last = out
            return dict(out)
        live = None
        try:
            live, _src = self._bookmap_reference_price(now)
        except Exception:
            live = None
        if live is None:
            bid = bbo.get('bid')
            ask = bbo.get('ask')
            if bid is not None and ask is not None:
                live = (float(bid) + float(ask)) / 2.0
            elif recent6:
                live = float(recent6[-1].get('price', 0.0) or 0.0)
        if not live:
            live = float(recent6[-1].get('price', 1.0) or 1.0)
        live = max(1.0, float(live))

        def flow(rows):
            buy = sum((float(t.get('size', 0.0) or 0.0) for t in rows if t.get('aggressor') == 'buy'))
            sell = sum((float(t.get('size', 0.0) or 0.0) for t in rows if t.get('aggressor') == 'sell'))
            total = buy + sell
            imb = (buy - sell) / max(total, 1e-09)
            return (buy, sell, imb, total)
        buy2, sell2, imb2, total2 = flow(recent2)
        buy6, sell6, imb6, total6 = flow(recent6)
        prices6 = [float(t.get('price', live) or live) for t in recent6]
        prices2 = [float(t.get('price', live) or live) for t in recent2]
        prior_prices = [float(t.get('price', live) or live) for t in prior2]
        move6_bp = (prices6[-1] - prices6[0]) / live * 10000.0 if len(prices6) >= 2 else 0.0
        move2_bp = (prices2[-1] - prices2[0]) / live * 10000.0 if len(prices2) >= 2 else 0.0
        prior2_bp = (prior_prices[-1] - prior_prices[0]) / live * 10000.0 if len(prior_prices) >= 2 else 0.0
        accel_bp = move2_bp - prior2_bp
        depth_window = max(65.0, live * 0.0012)
        near_bid_size = sum((float(v.get('size', 0.0) or 0.0) for p, v in bids.items() if 0.0 <= live - float(p) <= depth_window))
        near_ask_size = sum((float(v.get('size', 0.0) or 0.0) for p, v in asks.items() if 0.0 <= float(p) - live <= depth_window))
        depth_total = near_bid_size + near_ask_size
        depth_imb = (near_bid_size - near_ask_size) / max(depth_total, 1e-09)
        if whale is None:
            try:
                whale = self._bookmap_whale_read(now=now)
            except Exception:
                whale = {}
        whale = whale or {}
        whale_signed = float(whale.get('signed_score', 0.0) or 0.0)
        score = 0.0
        score += max(-34.0, min(34.0, imb2 * 34.0))
        score += max(-18.0, min(18.0, imb6 * 18.0))
        score += max(-17.0, min(17.0, move2_bp * 6.0))
        score += max(-10.0, min(10.0, move6_bp * 2.1))
        score += max(-9.0, min(9.0, accel_bp * 3.0))
        score += max(-8.0, min(8.0, depth_imb * 8.0))
        score += max(-8.0, min(8.0, whale_signed * 0.08))
        score = max(-100.0, min(100.0, score))
        strength = abs(score)
        raw_direction = 'UP' if score >= 18.0 else 'DOWN' if score <= -18.0 else 'NEUTRAL'
        latched = str(getattr(self, 'bookmap_wave_latched', 'NEUTRAL'))
        candidate = getattr(self, 'bookmap_wave_candidate', None)
        candidate_since = float(getattr(self, 'bookmap_wave_candidate_since', 0.0) or 0.0)
        if raw_direction in ('UP', 'DOWN') and raw_direction != latched:
            if candidate != raw_direction:
                self.bookmap_wave_candidate = raw_direction
                self.bookmap_wave_candidate_since = now
                candidate_since = now
            promote = 0.55 if strength >= 68.0 else 0.9 if strength >= 48.0 else 1.15
            if now - candidate_since >= promote:
                previous = latched
                self.bookmap_wave_latched = raw_direction
                latched = raw_direction
                self.bookmap_wave_candidate = None
                self.bookmap_wave_candidate_since = 0.0
                if previous in ('UP', 'DOWN') and previous != latched:
                    self.bookmap_wave_last_flip_ts = now
        elif raw_direction == latched:
            self.bookmap_wave_candidate = None
            self.bookmap_wave_candidate_since = 0.0
        elif raw_direction == 'NEUTRAL':
            if candidate != 'NEUTRAL':
                self.bookmap_wave_candidate = 'NEUTRAL'
                self.bookmap_wave_candidate_since = now
            elif now - float(self.bookmap_wave_candidate_since or now) >= 1.45 and strength < 12.0:
                self.bookmap_wave_latched = 'NEUTRAL'
                latched = 'NEUTRAL'
                self.bookmap_wave_candidate = None
                self.bookmap_wave_candidate_since = 0.0
        opposing = latched in ('UP', 'DOWN') and raw_direction in ('UP', 'DOWN') and (raw_direction != latched)
        same_flow = latched == 'UP' and imb2 > 0 or (latched == 'DOWN' and imb2 < 0)
        same_move = latched == 'UP' and move2_bp > 0 or (latched == 'DOWN' and move2_bp < 0)
        losing_flow = latched in ('UP', 'DOWN') and (not same_flow)
        losing_move = latched in ('UP', 'DOWN') and (not same_move)
        flip_risk = 0.0
        if latched in ('UP', 'DOWN'):
            if opposing:
                flip_risk += 44.0 + min(32.0, strength * 0.38)
            if losing_flow:
                flip_risk += min(18.0, abs(imb2) * 24.0)
            if losing_move:
                flip_risk += min(16.0, abs(move2_bp) * 5.0)
            if latched == 'UP' and accel_bp < 0 or (latched == 'DOWN' and accel_bp > 0):
                flip_risk += min(18.0, abs(accel_bp) * 4.0)
        flip_risk = max(0.0, min(99.0, flip_risk))
        direction = latched if latched in ('UP', 'DOWN') else raw_direction
        if opposing and flip_risk >= 58.0:
            phase = 'FLIP WATCH'
        elif direction in ('UP', 'DOWN') and strength >= 70.0 and same_flow and same_move:
            phase = 'SURGE'
        elif direction in ('UP', 'DOWN') and strength >= 44.0:
            phase = 'PUSH'
        elif direction in ('UP', 'DOWN') and flip_risk >= 38.0:
            phase = 'EXHAUSTING'
        elif direction in ('UP', 'DOWN'):
            phase = 'BUILDING'
        else:
            phase = 'BALANCED'
        detail = f'2s flow {imb2 * 100:+.0f}% • 6s flow {imb6 * 100:+.0f}% • 2s impulse {move2_bp:+.2f}bp • accel {accel_bp:+.2f}bp • depth {depth_imb * 100:+.0f}%'
        out = {'ready': True, 'direction': direction, 'raw_direction': raw_direction, 'phase': phase, 'strength': strength, 'signed_score': score, 'flip_risk': flip_risk, 'flow_2s': imb2, 'flow_6s': imb6, 'move_2s_bp': move2_bp, 'move_6s_bp': move6_bp, 'accel_bp': accel_bp, 'depth_imbalance': depth_imb, 'buy_2s': buy2, 'sell_2s': sell2, 'whale_signed': whale_signed, 'detail': detail, 'ts': now}
        self.bookmap_wave_last = out
        self.bookmap_wave_history.append({'ts': now, 'score': score, 'direction': direction, 'phase': phase, 'strength': strength, 'flip_risk': flip_risk})
        return dict(out)

    def _bookmap_fast_warmup_read(self, now=None, force=False):
        """
        Native Bookmap startup read before full V97 history is available.

        V8.0 rule: market data can move fast, but the defended lock and its
        survival/risk meters must behave like a persistent thesis, not a tape
        translator. Opposing pressure must persist before it materially attacks
        the lock.
        """
        now = float(now or time.time())
        if not force and self.bookmap_warmup_last and (now - float(self.bookmap_warmup_last.get('ts', 0.0) or 0.0) < self.bookmap_warmup_interval):
            return dict(self.bookmap_warmup_last)
        wave = self._bookmap_wave_read(now=now)
        whale = self._bookmap_whale_read(now=now)
        live, live_source = self.effective_live_price()
        if live is None or not wave.get('ready'):
            out = {'ready': False, 'ts': now, 'live': live, 'source': live_source, 'favored': 'WAIT', 'signed': 0.0, 'up': float(getattr(self, 'up_confidence_value', 50.0) or 50.0), 'down': float(getattr(self, 'down_confidence_value', 50.0) or 50.0), 'risk': float(getattr(self, 'trend_reversal_risk_value', 0.0) or 0.0), 'survival': float(getattr(self, 'flip_survival_value', 96.0) or 96.0), 'reason': 'Waiting for native Bookmap executed flow.'}
            self.bookmap_warmup_last = out
            return dict(out)
        wave_norm = max(-1.0, min(1.0, float(wave.get('signed_score', 0.0) or 0.0) / 100.0))
        whale_norm = max(-1.0, min(1.0, float(whale.get('signed_score', 0.0) or 0.0) / 80.0))
        depth_norm = max(-1.0, min(1.0, float(wave.get('depth_imbalance', 0.0) or 0.0)))
        flow_norm = max(-1.0, min(1.0, float(wave.get('flow_2s', 0.0) or 0.0)))
        impulse_norm = math.tanh(float(wave.get('move_2s_bp', 0.0) or 0.0) / 1.6)
        signed = wave_norm * 0.5 + flow_norm * 0.2 + whale_norm * 0.14 + depth_norm * 0.1 + impulse_norm * 0.06
        signed = max(-1.0, min(1.0, signed))
        raw_up = max(5.0, min(95.0, 50.0 + signed * 45.0))
        prev_up = float(getattr(self, 'up_confidence_value', 50.0) or 50.0)
        delta = raw_up - prev_up
        alpha = 0.24 if abs(delta) >= 14.0 else 0.14
        up = max(5.0, min(95.0, prev_up + delta * alpha))
        down = 100.0 - up
        prev_truth = dict(getattr(self, 'last_direction_truth', {}) or {})
        prev_favored = str(prev_truth.get('raw_favored', 'WAIT')).upper()
        raw_favored = 'UP' if up >= 55.0 else 'DOWN' if down >= 55.0 else 'WAIT'
        if prev_favored in ('UP', 'DOWN') and raw_favored in ('UP', 'DOWN') and (raw_favored != prev_favored):
            if abs(up - down) < 14.0:
                favored = prev_favored
            else:
                favored = raw_favored
        else:
            favored = raw_favored
        sticky = self._sticky_survival_lock_snapshot()
        defended = str((sticky or {}).get('lock_side', 'WAIT')).upper()
        if defended not in ('UP', 'DOWN'):
            risk = max(0.0, float(getattr(self, 'trend_reversal_risk_value', 0.0) or 0.0) * 0.92)
            survival = min(99.0, max(90.0, float(getattr(self, 'flip_survival_value', 96.0) or 96.0)))
            attack_age = 0.0
        else:
            opposite_now = defended == 'UP' and signed <= -0.18 or (defended == 'DOWN' and signed >= 0.18)
            wave_dir = str(wave.get('raw_direction', wave.get('direction', 'NEUTRAL'))).upper()
            wave_against = wave_dir in ('UP', 'DOWN') and wave_dir != defended
            wave_risk = float(wave.get('flip_risk', 0.0) or 0.0)
            whale_dir = str(whale.get('direction', 'NEUTRAL')).upper()
            whale_likelihood = float(whale.get('likelihood', 0.0) or 0.0)
            whale_against = whale_dir in ('UP', 'DOWN') and whale_dir != defended and (whale_likelihood >= 58.0)
            attack_now = opposite_now and (wave_against or wave_risk >= 55.0 or whale_against)
            attack_side = 'DOWN' if defended == 'UP' else 'UP'
            prev_attack_side = str(getattr(self, '_warmup_attack_side', 'WAIT'))
            if attack_now:
                if prev_attack_side != attack_side:
                    self._warmup_attack_side = attack_side
                    self._warmup_attack_since = now
                attack_age = max(0.0, now - float(getattr(self, '_warmup_attack_since', now) or now))
            else:
                self._warmup_attack_side = 'WAIT'
                self._warmup_attack_since = 0.0
                attack_age = 0.0
            raw_risk = 4.0
            if attack_now:
                raw_risk += min(18.0, abs(signed) * 28.0)
                if attack_age >= 1.25:
                    raw_risk += 18.0 + min(20.0, wave_risk * 0.22)
                if attack_age >= 2.4:
                    raw_risk += 18.0
                if whale_against and attack_age >= 1.25:
                    raw_risk += min(12.0, (whale_likelihood - 55.0) * 0.25)
            else:
                raw_risk += min(7.0, wave_risk * 0.08)
            raw_risk = max(0.0, min(99.0, raw_risk))
            prev_risk = float(getattr(self, 'trend_reversal_risk_value', 0.0) or 0.0)
            if raw_risk > prev_risk:
                risk_alpha = 0.16 if attack_age < 1.25 else 0.26 if attack_age < 2.4 else 0.38
            else:
                risk_alpha = 0.1
            risk = max(0.0, min(99.0, prev_risk + (raw_risk - prev_risk) * risk_alpha))
            raw_survival = max(1.0, min(99.0, 100.0 - risk))
            prev_survival = float(getattr(self, 'flip_survival_value', 96.0) or 96.0)
            if raw_survival < prev_survival:
                surv_alpha = 0.14 if attack_age < 1.25 else 0.24 if attack_age < 2.4 else 0.34
            else:
                surv_alpha = 0.1
            survival = max(1.0, min(99.0, prev_survival + (raw_survival - prev_survival) * surv_alpha))
        whale_dir = str(whale.get('direction', 'NEUTRAL')).upper()
        whale_likelihood = float(whale.get('likelihood', 0.0) or 0.0)
        reason = f"Bookmap warmup • wave {float(wave.get('signed_score', 0.0)):+.0f} • 2s flow {float(wave.get('flow_2s', 0.0)) * 100:+.0f}% • whale {whale_dir} {whale_likelihood:.0f}/100 • attack persistence {attack_age:.1f}s"
        out = {'ready': True, 'ts': now, 'live': float(live), 'source': live_source, 'favored': favored, 'signed': signed, 'up': up, 'down': down, 'risk': risk, 'survival': survival, 'wave': wave, 'whale': whale, 'defended': defended, 'attack_age': attack_age, 'reason': reason}
        self.bookmap_warmup_last = out
        return dict(out)

    def _bookmap_opening_lock_tick(self, warm, now=None):
        """Start looking for an OPEN/NOW lock immediately after Bookmap data arrives."""
        now = float(now or time.time())
        bucket = int(now // 900) * 900
        if self.opening_lock_bucket != bucket:
            self.opening_lock_bucket = bucket
            self.opening_lock_snapshot = None
            self.opening_lock_candidate = None
            self.opening_lock_candidate_since = 0.0
            self.opening_lock_var.set('OPEN LOCK: BUILDING FROM BOOKMAP')
        if self.opening_lock_snapshot:
            return dict(self.opening_lock_snapshot)
        if not warm or not warm.get('ready'):
            return None
        live = float(warm.get('live', 0.0) or 0.0)
        signed = float(warm.get('signed', 0.0) or 0.0)
        score = signed * 8.0
        reasons = [f'live Bookmap evidence {signed:+.2f}']
        try:
            target, target_source = self.effective_target()
        except Exception:
            target, target_source = (None, '')
        if target is not None and live > 0:
            target = float(target)
            range_ref = 25.0
            if self.btc_15m:
                c = self.btc_15m[-1]
                range_ref = max(25.0, float(c.get('high', live)) - float(c.get('low', live)), abs(live - float(c.get('open', live))))
            target_z = max(-2.0, min(2.0, (live - target) / range_ref))
            score += target_z * 2.0
            reasons.append(f'target geometry {target_z:+.2f}')
        candidate = 'UP' if score >= 2.6 else 'DOWN' if score <= -2.6 else None
        if candidate is None:
            self.opening_lock_candidate = None
            self.opening_lock_candidate_since = 0.0
            self.opening_lock_var.set(f"OPEN LOCK: BUILDING • {warm.get('favored', 'WAIT')} {max(float(warm.get('up', 50)), float(warm.get('down', 50))):.0f}/100")
            return None
        if self.opening_lock_candidate != candidate:
            self.opening_lock_candidate = candidate
            self.opening_lock_candidate_since = now
            self.opening_lock_var.set(f'OPEN LOCK: CANDIDATE {candidate} • VERIFYING')
            return None
        required = 1.25 if abs(score) >= 6.0 else 2.0
        if now - float(self.opening_lock_candidate_since or now) < required:
            return None
        snap = {'time': now, 'price': live, 'lock_side': candidate, 'lock_remaining': 'OPEN', 'lock_minute': 0, 'forecast_score': score, 'forecast_threshold': 2.0, 'forecast_reasons': ' • '.join(reasons[-6:]), 'source': 'BOOKMAP OPEN/NOW'}
        self.opening_lock_snapshot = snap
        self.opening_lock_candidate = None
        self.opening_lock_candidate_since = 0.0
        self.opening_lock_var.set(f'OPEN LOCK: {candidate} @ {money(live)} • score {score:+.1f}')
        self._checkpoint_status_summary()
        return dict(snap)

    def _bookmap_warmup_checkpoint_tick(self, warm, now=None):
        """
        Freeze the normal 11/10/9/8/2 minute-left locks at the COUNTDOWN mark.

        Example: the 11m lock fires when the timer crosses 11:00 remaining,
        which is 4 minutes after the 15m market opened -- never 11 minutes after
        the bot launched and never 11 elapsed minutes into the market.
        """
        now = float(now or time.time())
        if not warm or not warm.get('ready'):
            return []
        bucket = int(now // 900) * 900
        elapsed_min = max(0.0, (now - bucket) / 60.0)
        remaining_min = max(0.0, 15.0 - elapsed_min)
        if self.checkpoint_bucket != bucket:
            self.checkpoint_bucket = bucket
            self.checkpoint_snapshot = None
            self.checkpoint_snapshots = {}
            self.checkpoint_health_states = {}
            self.checkpoint_missed = set()
            if elapsed_min > 0.2:
                for threshold in self.checkpoint_thresholds:
                    if remaining_min < float(threshold) - 0.03:
                        self.checkpoint_missed.add(int(threshold))
            self._checkpoint_status_summary()
        created = []
        live = float(warm.get('live', 0.0) or 0.0)
        favored = str(warm.get('favored', 'WAIT'))
        if favored not in ('UP', 'DOWN'):
            favored = 'UP' if float(warm.get('signed', 0.0) or 0.0) >= 0 else 'DOWN'
        for threshold in self.checkpoint_thresholds:
            threshold = int(threshold)
            if threshold in self.checkpoint_snapshots or threshold in self.checkpoint_missed:
                continue
            if remaining_min <= float(threshold):
                strength = max(float(warm.get('up', 50.0)), float(warm.get('down', 50.0)))
                score = float(warm.get('signed', 0.0) or 0.0) * 10.0
                snap = {'time': now, 'price': live, 'current_call': 'GREEN LEAN' if favored == 'UP' else 'RED LEAN', 'next_call': favored, 'lock_side': favored, 'lock_remaining': threshold, 'lock_minute': 15 - threshold, 'forecast_score': score, 'forecast_threshold': 0.0, 'forecast_reasons': f"Native Bookmap live checkpoint at {threshold:02d}:00 LEFT • {warm.get('reason', '')} • evidence {strength:.0f}/100", 'fast_net': score, 'pro_net': score, 'current_net': score, 'rsi': 50.0, 'adx': 0.0, 'atr': 1.0, 'vwap': None, 'range_pos': 0.5, 'risk': 'BOOKMAP STARTUP CONTEXT', 'source': 'BOOKMAP COUNTDOWN WARMUP'}
                self.checkpoint_snapshots[threshold] = snap
                created.append(threshold)
                if threshold == self._current_lock_minute():
                    self.checkpoint_snapshot = snap
                    self.lock_minute_status_var.set(f'VIEWING {threshold}m LEFT • {favored} • FROZEN AT {threshold:02d}:00 countdown • {money(live)}')
                    self.lock_forecast_why_var.set(f"LOCK FORECAST WHY: {snap.get('forecast_reasons', '--')}")
        self._sync_selected_checkpoint_snapshot()
        self._checkpoint_status_summary()
        return created

    def _update_startup_feature_stack(self, warm):
        if not warm or not warm.get('ready'):
            return
        side = str((self._sticky_survival_lock_snapshot() or {}).get('lock_side', 'WAIT')).upper()
        favored = str(warm.get('favored', 'WAIT')).upper()
        up = float(warm.get('up', 50.0) or 50.0)
        down = float(warm.get('down', 50.0) or 50.0)
        risk = float(warm.get('risk', 0.0) or 0.0)
        survival = float(warm.get('survival', 96.0) or 96.0)
        live = warm.get('live')
        wave = warm.get('wave') or {}
        whale = warm.get('whale') or {}
        phase = str(wave.get('phase', 'BUILDING')).upper()
        strength = float(wave.get('strength', 0.0) or 0.0)
        flow2 = float(wave.get('flow_2s', 0.0) or 0.0) * 100.0
        current = favored if favored in ('UP', 'DOWN') else 'WAIT'
        next_side = side if side in ('UP', 'DOWN') else current
        self._set_var_if_changed(self.current_bias_var, f'CURRENT: {current} • BOOKMAP LIVE')
        self._set_var_if_changed(self.next_bias_var, f'NEXT CANDLE: {next_side} LEAN • wave {phase} {strength:.0f}/100')
        self._set_var_if_changed(self.conf_var, f'UP {up:.0f}/100 • DOWN {down:.0f}/100 • survival {survival:.0f}')
        self._set_var_if_changed(self.action_var, f'DEFEND {side} LOCK' if side in ('UP', 'DOWN') else 'BUILDING REAL LOCK')
        self._set_var_if_changed(self.why_var, str(warm.get('reason', 'Bookmap live evidence')))
        lock_text = 'LOCK BUILDING'
        snap = self._sticky_survival_lock_snapshot()
        if snap:
            lock_text = f"{snap.get('lock_side', 'WAIT')} @ {money(snap.get('price'))}"
        self._set_var_if_changed(self.checkpoint_var, f'LOCK READ: {lock_text}')
        self._set_var_if_changed(self.finish_projection_var, f'END-OF-15M: {next_side} while survival {survival:.0f}/100 • breakout risk {risk:.0f}/100')
        self._set_var_if_changed(self.early_next_last_var, f'EARLY NEXT-15M: {next_side} • confidence {up:.0f}/{down:.0f}')
        self._set_var_if_changed(self.projected_path_var, f'PROJECTED PATH: {next_side} • Richie wave {phase} {strength:.0f}/100 • 2s flow {flow2:+.0f}%')
        self._set_var_if_changed(self.expected_move_var, f"LIVE IMPULSE: {float(wave.get('move_2s_bp', 0.0) or 0.0):+.2f} bp / 2s • flow {flow2:+.0f}%")
        self._set_var_if_changed(self.scorecard_var, f'LOCK {side} • SURVIVAL {survival:.0f} • RISK {risk:.0f} • WAVE {phase} {strength:.0f}')
        self._set_var_if_changed(self.pro_score_var, f'PRO SCORE: {next_side} • hard-lock survival {survival:.0f}/100')
        self._set_var_if_changed(self.candle_source_var, 'CANDLE SOURCE: BOOKMAP executed trades • live native warmup')
        try:
            target, _ = self.effective_target()
        except Exception:
            target = None
        if target is not None and live is not None:
            delta = float(live) - float(target)
            target_side = 'ABOVE' if delta >= 0 else 'BELOW'
            self._set_var_if_changed(self.target_read_var, f'TARGET READ: BTC {target_side} by ${abs(delta):,.0f} • lock {side}')
            self._set_var_if_changed(self.target_edge_var, f'TARGET EDGE: {delta:+,.0f} USD from target')
            self._set_var_if_changed(self.target_reachability_var, f'TARGET GEOMETRY: live {money(live)} • target {money(target)}')
        yes = self.kalshi_yes_price()
        if yes is not None:
            self._set_var_if_changed(self.kalshi_alignment_var, f'KALSHI LIVE: YES {yes * 100:.1f}¢ • hard lock {side}')
        ob = getattr(self, 'orderbook', {}) or {}
        imb = float(ob.get('imbalance', 0.0) or 0.0) * 100.0
        self._set_var_if_changed(self.orderbook_var, f"BOOKMAP DEPTH: imbalance {imb:+.0f}% • bid {ob.get('best_bid', '--')} • ask {ob.get('best_ask', '--')}")
        self._set_var_if_changed(self.whale_pressure_var, f"WHALE PRESSURE: {str(whale.get('direction', 'NEUTRAL')).upper()} {float(whale.get('likelihood', 0.0) or 0.0):.0f}/100")

    def _update_bookmap_warmup_meters(self, warm):
        """Paint startup meters without relabeling the defended side from noise."""
        if not warm or not warm.get('ready'):
            return
        up = float(warm.get('up', 50.0) or 50.0)
        down = float(warm.get('down', 50.0) or 50.0)
        risk = float(warm.get('risk', 0.0) or 0.0)
        survival = float(warm.get('survival', 96.0) or 96.0)
        favored = str(warm.get('favored', 'WAIT'))
        sticky = self._sticky_survival_lock_snapshot()
        defended = str((sticky or {}).get('lock_side', 'WAIT')).upper()
        self.up_confidence_value = up
        self.down_confidence_value = down
        self._set_var_if_changed(self.up_confidence_var, f'UP CONFIDENCE {up:.0f}/100')
        self._set_var_if_changed(self.down_confidence_var, f'DOWN CONFIDENCE {down:.0f}/100')
        self._set_var_if_changed(self.confidence_regime_var, 'CONFIDENCE REGIME: BOOKMAP LIVE WARMUP')
        self._set_var_if_changed(self.confidence_edge_var, f"{favored} • {warm.get('reason', '')}")
        self.last_direction_truth = {'up': up, 'down': down, 'raw_favored': favored, 'edge': f'{favored} • BOOKMAP LIVE', 'reason': warm.get('reason', ''), 'regime': 'BOOKMAP LIVE WARMUP'}
        self._draw_confidence_bars()
        self.trend_reversal_risk_value = risk
        self._set_var_if_changed(self.trend_reversal_risk_var, f'FLIP / BREAKOUT RISK {risk:.0f}/100')
        wave = warm.get('wave') or {}
        phase = str(wave.get('phase', 'BUILDING'))
        if defended in ('UP', 'DOWN'):
            status = f'BOOKMAP LIVE • defending {defended} LOCK • {phase}'
            detail = f"{defended} stays the defended side • opposing pressure only changes risk/survival • {warm.get('reason', '')}"
        else:
            status = f'BOOKMAP LIVE • LOCK BUILDING • {phase}'
            detail = f"No defended side until OPEN/NOW freezes • {warm.get('reason', '')}"
        self._set_var_if_changed(self.trend_reversal_status_var, status)
        self._set_var_if_changed(self.trend_reversal_detail_var, detail)
        self._draw_trend_risk_bar()
        self.flip_survival_value = survival
        label = 'VERY SAFE' if survival >= 82 else 'SAFE' if survival >= 68 else 'WATCH' if survival >= 48 else 'DANGER'
        self._set_var_if_changed(self.flip_survival_var, f'FLIP SURVIVAL {survival:.0f}/100 • {label}')
        if defended in ('UP', 'DOWN'):
            surv_detail = f"Defending {defended} LOCK • side is HARD-LATCHED for this round • wave flip risk {float(wave.get('flip_risk', 0.0)):.0f}/100"
        else:
            surv_detail = 'LOCK BUILDING • survival side will latch only after a real OPEN/NOW read'
        self._set_var_if_changed(self.flip_survival_detail_var, surv_detail)
        self._draw_flip_survival_bar()
        opening = self._bookmap_opening_lock_tick(warm)
        self._bookmap_warmup_checkpoint_tick(warm)
        if opening:
            self._set_var_if_changed(self.reversal_status_var, f"OPEN LOCKED {opening.get('lock_side', 'WAIT')}")
            self._set_var_if_changed(self.reversal_action_var, f"Persistent Bookmap lock @ {money(opening.get('price'))}; timed locks still freeze independently at countdown marks.")
            self._set_var_if_changed(self.lock_pick_var, f"OPEN/NOW • {opening.get('lock_side', 'WAIT')} • {money(opening.get('price'))}")
        elif not self._selected_checkpoint_snapshot():
            self._set_var_if_changed(self.reversal_status_var, 'OPEN LOCK BUILDING NOW')
            self._set_var_if_changed(self.reversal_action_var, 'Reading immediately; waiting for persistent evidence before freezing a side.')
            self._set_var_if_changed(self.lock_pick_var, 'OPEN/NOW • evaluating persistent flow')
        self._update_startup_feature_stack(warm)

    def _auto_paper_unified_tick(self, warm=None, sig=None, candles=None, now=None, mode='LIVE'):
        if not self.auto_paper_enabled_var.get():
            self.auto_paper_live_score = None
            self._set_var_if_changed(self.auto_paper_score_var, 'AUTO PAPER: OFF')
            self._set_var_if_changed(self.auto_paper_reason_var, 'Enable AUTO PAPER to simulate qualified entries from the hard lock.')
            self.auto_paper_candidate_side = None
            self.auto_paper_candidate_since = 0.0
            return False
        if self.paper_active_trade is not None:
            self._set_var_if_changed(self.auto_paper_score_var, 'AUTO PAPER: managing active paper trade')
            self._set_var_if_changed(self.auto_paper_reason_var, 'Current paper trade is active; waiting for its exit before another entry.')
            return False
        now = float(now or time.time())
        if now - float(getattr(self, 'auto_paper_last_eval', 0.0) or 0.0) < 0.22:
            return False
        self.auto_paper_last_eval = now
        bucket = int(now // 900) * 900
        if self.auto_paper_last_bucket == bucket:
            self._set_var_if_changed(self.auto_paper_score_var, 'AUTO PAPER: already traded this 15m market')
            self._set_var_if_changed(self.auto_paper_reason_var, 'One automatic paper entry maximum per 15-minute market.')
            return False
        lock = self._sticky_survival_lock_snapshot() or getattr(self, 'opening_lock_snapshot', None) or self._selected_checkpoint_snapshot()
        side = str((lock or {}).get('lock_side', 'WAIT')).upper()
        if side not in ('UP', 'DOWN'):
            self.auto_paper_candidate_side = None
            self.auto_paper_candidate_since = 0.0
            self.auto_paper_live_score = 0.0
            self._set_var_if_changed(self.auto_paper_score_var, 'AUTO PAPER: waiting for a frozen lock')
            self._set_var_if_changed(self.auto_paper_reason_var, 'No hard-latched OPEN/NOW or checkpoint side exists yet.')
            return False
        up = float(getattr(self, 'up_confidence_value', 50.0) or 50.0)
        down = float(getattr(self, 'down_confidence_value', 50.0) or 50.0)
        directional = up if side == 'UP' else down
        opposite = down if side == 'UP' else up
        margin = directional - opposite
        survival = float(getattr(self, 'flip_survival_value', 50.0) or 50.0)
        risk = float(getattr(self, 'trend_reversal_risk_value', 50.0) or 50.0)
        warm = dict(warm or {})
        if not warm and getattr(self, 'bookmap_connected', False):
            try:
                warm = self._bookmap_fast_warmup_read(now=now)
            except Exception:
                warm = {}
        wave = warm.get('wave') or getattr(self, 'bookmap_wave_last', {}) or {}
        wave_dir = str(wave.get('raw_direction', wave.get('direction', 'NEUTRAL'))).upper()
        wave_strength = float(wave.get('strength', 0.0) or 0.0)
        wave_phase = str(wave.get('phase', 'BUILDING')).upper()
        score = 0.52 * directional + 0.3 * survival + 0.18 * (100.0 - risk)
        if wave_dir == side:
            score += min(5.0, wave_strength * 0.05)
        elif wave_dir in ('UP', 'DOWN') and wave_dir != side and (wave_phase in ('SURGE', 'FLIP WATCH')):
            score -= 5.0
        score = max(0.0, min(100.0, score))
        threshold = self._auto_paper_threshold()
        self.auto_paper_live_score = score
        contract_px, _yes_px, quote_source, quote_age = self._kalshi_paper_price(side, 'ENTER', max_age=3.0)
        quote_text = 'NO FRESH ASK' if contract_px is None else f'{contract_px * 100:.1f}¢ {quote_source} age {quote_age:.2f}s'
        self._set_var_if_changed(self.auto_paper_score_var, f'AUTO PAPER {side}: {score:.0f}/100 • trigger {threshold:.0f} • live ask {quote_text}')
        if contract_px is None:
            self.auto_paper_candidate_side = None
            self.auto_paper_candidate_since = 0.0
            self._set_var_if_changed(self.auto_paper_reason_var, 'Hard lock is ready, but Kalshi executable ASK is stale/missing. No imaginary fill.')
            return False
        healthy = score >= threshold and survival >= 55.0 and (risk <= 58.0)
        if not healthy:
            self.auto_paper_candidate_side = None
            self.auto_paper_candidate_since = 0.0
            self._set_var_if_changed(self.auto_paper_reason_var, f'{side} hard lock • confidence {directional:.0f} vs {opposite:.0f} • survival {survival:.0f} • risk {risk:.0f} • waiting for score {threshold:.0f}')
            return False
        if self.auto_paper_candidate_side != side:
            self.auto_paper_candidate_side = side
            self.auto_paper_candidate_since = now
            self._set_var_if_changed(self.auto_paper_reason_var, f'{side} hard-lock AUTO PAPER candidate • live Kalshi ask {contract_px * 100:.1f}¢ • confirming 0.8s')
            return False
        held = now - float(self.auto_paper_candidate_since or now)
        if held < 0.8:
            self._set_var_if_changed(self.auto_paper_reason_var, f'{side} hard-lock candidate held {held:.1f}/0.8s • survival {survival:.0f} • risk {risk:.0f}')
            return False
        lock2 = self._sticky_survival_lock_snapshot() or getattr(self, 'opening_lock_snapshot', None) or self._selected_checkpoint_snapshot()
        if str((lock2 or {}).get('lock_side', 'WAIT')).upper() != side:
            self.auto_paper_candidate_side = None
            self.auto_paper_candidate_since = 0.0
            return False
        fresh_px, _fresh_yes, _fresh_source, _fresh_age = self._kalshi_paper_price(side, 'ENTER', max_age=3.0)
        if fresh_px is None:
            self._set_var_if_changed(self.auto_paper_reason_var, 'Candidate confirmed but Kalshi ASK went stale before fill; waiting for fresh quote.')
            return False
        opened = self._paper_open(side, entry_source='AUTO', auto_score=score, auto_reason=f'HARD LOCK {side} • survival {survival:.0f} • risk {risk:.0f} • confidence {directional:.0f}')
        if opened:
            self.auto_paper_last_bucket = bucket
            self._set_var_if_changed(self.auto_paper_reason_var, f'AUTO PAPER ENTERED {side} @ LIVE KALSHI ASK • score {score:.0f}/100')
        self.auto_paper_candidate_side = None
        self.auto_paper_candidate_since = 0.0
        return bool(opened)

    def _auto_paper_warmup_tick(self, warm, now=None):
        return self._auto_paper_unified_tick(warm=warm, now=now, mode='BOOKMAP')

    def _set_var_if_changed(self, var, value):
        """Avoid needless Tk label invalidation / geometry work."""
        try:
            text = str(value)
            if var.get() != text:
                var.set(text)
        except Exception:
            try:
                var.set(str(value))
            except Exception:
                pass

    def _update_bookmap_panel(self, read=None):
        read = dict(read or self._bookmap_whale_read())
        captured = self._bookmap_capture_heatmap(read)
        if captured and (not self.web_only_mode):
            self._draw_bookmap_heatmap()
        if not read.get('ready'):
            latest_heat = self.bookmap_heatmap_history[-1] if self.bookmap_heatmap_history else {}
            mode = str(latest_heat.get('mode', 'BUILDING'))
            self._set_var_if_changed(self.whale_heatmap_caption_var, f'MINI HEATMAP: {len(self.bookmap_heatmap_history)} snapshots • {mode} • raw Bookmap feed still building whale statistics')
            self._set_var_if_changed(self.bookmap_status_var, f"BOOKMAP: waiting • UDP {self.bookmap_udp_port} • {read.get('detail', '')}")
            self._set_var_if_changed(self.whale_predictor_var, 'WHALE RADAR: WAITING')
            self._set_var_if_changed(self.whale_detail_var, str(read.get('detail', 'waiting')))
            self._set_var_if_changed(self.whale_wall_var, 'WALLS: bid -- • ask --')
            self._set_var_if_changed(self.whale_flow_var, 'FLOW: buy -- • sell -- • absorption --')
            self._set_var_if_changed(self.whale_mbo_var, 'MBO: waiting / provider dependent')
            return
        age = float(read.get('age', 0.0) or 0.0)
        alias = str(read.get('alias', '--'))
        self._set_var_if_changed(self.bookmap_status_var, f'BOOKMAP: LIVE • {alias} • age {age:.2f}s • UDP {self.bookmap_udp_port}')
        self._set_var_if_changed(self.whale_predictor_var, str(read.get('label', 'WHALE RADAR')))
        label = getattr(self, 'whale_predictor_label', None)
        if label is not None:
            direction = str(read.get('direction', 'NEUTRAL'))
            new_color = GREEN if direction == 'UP' else RED if direction == 'DOWN' else PINK2
            try:
                if str(label.cget('fg')) != str(new_color):
                    label.configure(fg=new_color)
            except Exception:
                pass
        self._set_var_if_changed(self.whale_detail_var, f"confidence {float(read.get('confidence', 0)):.0f}/100 • " + str(read.get('detail', '')))

        def wall_text(w):
            if not w:
                return '--'
            return f"{money(w.get('price'))} x{float(w.get('ratio', 0)):.1f} • {float(w.get('persistence', 0)):.1f}s"
        self._set_var_if_changed(self.whale_wall_var, f"WALLS: BID {wall_text(read.get('bid_wall'))} • ASK {wall_text(read.get('ask_wall'))}")
        self._set_var_if_changed(self.whale_flow_var, f"FLOW 15s: buy {float(read.get('buy_volume_15s', 0)):.0f} • sell {float(read.get('sell_volume_15s', 0)):.0f} • imbalance {float(read.get('trade_imbalance', 0)) * 100:+.0f}% • {read.get('absorption', 'NONE')}")
        if read.get('mbo_available'):
            mbo_text = f"MBO: persistent bid whales {int(read.get('persistent_mbo_bids', 0))} • ask whales {int(read.get('persistent_mbo_asks', 0))} • fast-cancel bid x{float(read.get('spoof_bid_cancel_ratio', 0)):.1f} • ask x{float(read.get('spoof_ask_cancel_ratio', 0)):.1f}"
        else:
            mbo_text = 'MBO: provider has not supplied order-by-order events • depth/trades still active'
        self._set_var_if_changed(self.whale_mbo_var, mbo_text)
        learning = read.get('learning') or {}
        self._set_var_if_changed(self.whale_learning_var, str(learning.get('label', 'WHALE MEMORY: collecting resolved Bookmap rounds')))
        fusion = self.bookmap_fusion_last or {}
        self._set_var_if_changed(self.whale_fusion_var, str(fusion.get('label', 'WHALE + CHART FUSION: building')))
        latest_heat = self.bookmap_heatmap_history[-1] if self.bookmap_heatmap_history else {}
        heat_mode = str(latest_heat.get('mode', 'BUILDING'))
        self._set_var_if_changed(self.whale_heatmap_caption_var, f"MINI HEATMAP: {len(self.bookmap_heatmap_history)} snapshots • {heat_mode} • Bookmap depth {int(read.get('depth_bid_levels', 0) or 0)} bid / {int(read.get('depth_ask_levels', 0) or 0)} ask • white = Bookmap BTC path")
        self._draw_bookmap_heatmap()

    def _reference_settlement_model(self, sig=None, update_persistence=True):
        """
        V82 presentation/gating layer inspired by the supplied reference UI.

        YES = UP / closes above the target side of the BTC15M contract.
        NO  = DOWN / closes below the target side.

        The outcome percentages mirror Chart King's canonical directional
        confidence. A separate model-confidence score describes how much the
        underlying evidence stack agrees with itself. Conservative model ranges
        widen when model confidence is lower.
        """
        conf = dict(getattr(self, 'last_direction_truth', {}) or {})
        yes_pct = max(0.0, min(100.0, float(conf.get('up', self.up_confidence_value) or 50.0)))
        no_pct = max(0.0, min(100.0, float(conf.get('down', self.down_confidence_value) or 50.0)))
        predictive = dict(getattr(self, 'predictive_edge_last', {}) or {})
        agreement = float(predictive.get('agreement', 50.0) or 50.0)
        disagreement = float(predictive.get('disagreement', 50.0) or 50.0)
        quality = float(predictive.get('quality', 55.0) or 55.0)
        directional_strength = max(yes_pct, no_pct)
        danger = float(conf.get('danger_score', getattr(self, 'confidence_danger_score', 0.0)) or 0.0)
        model_confidence = directional_strength * 0.38 + agreement * 0.3 + max(0.0, 100.0 - disagreement) * 0.18 + quality * 0.14
        if str(conf.get('regime', '')).startswith('HOLDING LAST VALID'):
            model_confidence -= 6.0
        if 38.0 <= danger < 60.0:
            model_confidence -= 5.0
        whale = self._bookmap_whale_read()
        fusion = self._bookmap_chart_fusion(sig or {}, getattr(self, '_last_analysis_candles', None) or [], whale=whale)
        if fusion.get('ready'):
            fstate = str(fusion.get('state', 'MIXED'))
            if fstate == 'ALIGNED':
                model_confidence += 4.0
            elif fstate == 'LEAN ALIGNED':
                model_confidence += 2.0
            elif fstate == 'CONFLICT':
                model_confidence -= 7.0
        model_confidence = max(35.0, min(98.0, model_confidence))
        half_width = 4.0 + (100.0 - model_confidence) * 0.19
        half_width += min(7.0, disagreement * 0.045)
        yes_low = max(1.0, yes_pct - half_width)
        yes_high = min(99.0, yes_pct + half_width)
        snap = self._selected_checkpoint_snapshot()
        frozen_side = 'WAIT'
        call_probability = 50.0
        confirmations = 0
        if snap:
            frozen_side = str(snap.get('lock_side', 'WAIT')).upper()
            score = abs(float(snap.get('forecast_score', 0.0) or 0.0))
            threshold = max(0.1, abs(float(snap.get('forecast_threshold', 1.0) or 1.0)))
            excess = max(0.0, score - threshold)
            call_probability = max(52.0, min(96.0, 62.0 + score * 2.0 + excess * 1.2))
            if frozen_side in ('UP', 'DOWN'):
                live_side = 'UP' if yes_pct > no_pct else 'DOWN'
                if live_side == frozen_side:
                    confirmations += 1
                lock_validation = conf.get('lock_validation') or {}
                if float(lock_validation.get('validation', 0.0) or 0.0) >= 70.0:
                    confirmations += 1
                all_tf_text = str(self.all_tf_consensus_var.get()).upper()
                if frozen_side in all_tf_text and 'MIXED' not in all_tf_text:
                    confirmations += 1
                danger_side = str(conf.get('danger_side', 'WAIT')).upper()
                if not (danger >= 68.0 and danger_side not in ('WAIT', frozen_side)):
                    confirmations += 1
        market_yes = self.kalshi_yes_price()
        buy_yes = None if market_yes is None else max(0.0, min(1.0, float(market_yes)))
        buy_no = None if buy_yes is None else 1.0 - buy_yes
        conservative_yes_edge = None
        conservative_no_edge = None
        if buy_yes is not None:
            conservative_yes_edge = yes_low - buy_yes * 100.0
            conservative_no_probability = 100.0 - yes_high
            conservative_no_edge = conservative_no_probability - buy_no * 100.0
        ev_candidate = str(predictive.get('ev_candidate', 'WAIT')).upper()
        candidate = ev_candidate if ev_candidate in ('UP', 'DOWN') else 'PASS'
        candidate_prob = yes_pct if candidate == 'UP' else no_pct if candidate == 'DOWN' else 50.0
        candidate_edge = conservative_yes_edge if candidate == 'UP' else conservative_no_edge if candidate == 'DOWN' else None
        data_ok = bool(sig and sig.get('ready') and predictive.get('ready'))
        uncertainty_ok = bool(model_confidence >= 60.0 and candidate_prob >= 58.0)
        price_ok = bool(candidate in ('UP', 'DOWN') and candidate_edge is not None and (candidate_edge >= 1.0))
        danger_side = str(conf.get('danger_side', 'WAIT')).upper()
        danger_blocks = bool(danger >= 50.0 and danger_side in ('UP', 'DOWN') and (candidate in ('UP', 'DOWN')) and (danger_side != candidate))
        raw_candidate = candidate if data_ok and uncertainty_ok and price_ok and (not danger_blocks) else 'PASS'
        now = time.time()
        if update_persistence and now - self.decision_last_eval >= 0.3:
            self.decision_last_eval = now
            if raw_candidate in ('UP', 'DOWN'):
                if self.decision_candidate_side == raw_candidate:
                    self.decision_candidate_streak = min(3, self.decision_candidate_streak + 1)
                else:
                    self.decision_candidate_side = raw_candidate
                    self.decision_candidate_streak = 1
            else:
                self.decision_candidate_side = 'PASS'
                self.decision_candidate_streak = 0
        persistence = int(self.decision_candidate_streak)
        decision = raw_candidate if raw_candidate in ('UP', 'DOWN') and persistence >= 3 else 'PASS'
        checks = {'data': data_ok, 'uncertainty': uncertainty_ok, 'price': price_ok, 'persistence': persistence >= 3}
        if decision == 'PASS':
            missing = [name for name, ok in checks.items() if not ok]
            if raw_candidate in ('UP', 'DOWN') and persistence < 3:
                decision_detail = f'{raw_candidate} is qualifying, but persistence is only {persistence}/3. Waiting for the read to hold.'
            elif missing:
                decision_detail = 'No side currently clears every data, uncertainty, price, and persistence check. Missing: ' + ', '.join(missing) + '.'
            else:
                decision_detail = 'No side currently clears the full decision gate.'
        else:
            decision_detail = f'{decision} clears data + uncertainty + conservative price edge + persistence. EV+ candidate is aligned with the settlement model.'
        regime = str(self.regime_var.get()) if hasattr(self, 'regime_var') else '--'
        scalp = str(self.scalp_expectancy_var.get()) if hasattr(self, 'scalp_expectancy_var') else '--'
        scalp_radar = f'{regime} • {scalp}'
        return {'yes_pct': yes_pct, 'no_pct': no_pct, 'yes_low': yes_low, 'yes_high': yes_high, 'model_confidence': model_confidence, 'frozen_side': frozen_side, 'call_probability': call_probability, 'confirmations': confirmations, 'buy_yes': buy_yes, 'buy_no': buy_no, 'conservative_yes_edge': conservative_yes_edge, 'conservative_no_edge': conservative_no_edge, 'raw_candidate': raw_candidate, 'decision': decision, 'decision_detail': decision_detail, 'persistence': persistence, 'checks': checks, 'scalp_radar': scalp_radar}

    def _draw_reference_probability_bars(self):
        model = dict(getattr(self, 'reference_model_last', {}) or {})
        yes_pct = float(model.get('yes_pct', 50.0) or 50.0)
        confidence = float(model.get('model_confidence', 50.0) or 50.0)
        c = getattr(self, 'settlement_model_canvas', None)
        if c is not None:
            try:
                w = max(240, c.winfo_width())
                h = max(20, c.winfo_height())
                c.delete('all')
                c.create_rectangle(0, 3, w, h - 3, fill=PANEL2, outline=PANEL2)
                split = w * max(0.0, min(1.0, yes_pct / 100.0))
                c.create_rectangle(0, 3, split, h - 3, fill=GREEN, outline=GREEN)
                c.create_rectangle(split, 3, w, h - 3, fill=RED, outline=RED)
                c.create_line(w * 0.5, 1, w * 0.5, h - 1, fill='#fff4fb', width=2)
                c.create_line(split, 0, split, h, fill='#ffffff', width=3)
            except Exception:
                pass
        q = getattr(self, 'settlement_quality_canvas', None)
        if q is not None:
            try:
                w = max(240, q.winfo_width())
                h = max(18, q.winfo_height())
                q.delete('all')
                q.create_rectangle(0, 3, w, h - 3, fill=PANEL2, outline=PANEL2)
                frac = max(0.0, min(1.0, confidence / 100.0))
                if confidence >= 78:
                    fill = GREEN
                elif confidence >= 60:
                    fill = PINK2
                else:
                    fill = RED
                q.create_rectangle(0, 3, w * frac, h - 3, fill=fill, outline=fill)
            except Exception:
                pass

    def _update_reference_settlement_panel(self, sig=None, update_persistence=True):
        model = self._reference_settlement_model(sig, update_persistence=update_persistence)
        self.reference_model_last = dict(model)
        yes_pct = float(model['yes_pct'])
        no_pct = float(model['no_pct'])
        model_conf = float(model['model_confidence'])
        self.settlement_yes_var.set(f'YES  {yes_pct:.0f}%')
        self.settlement_no_var.set(f'NO  {no_pct:.0f}%')
        self.settlement_range_var.set(f"Conservative YES range   {model['yes_low']:.0f}%–{model['yes_high']:.0f}%")
        self.settlement_quality_var.set(f'MODEL CONFIDENCE   {model_conf:.0f} / 100')
        decision = str(model.get('decision', 'PASS'))
        self.current_decision_var.set(decision if decision == 'PASS' else f'{decision} • EV+ CANDIDATE')
        try:
            self.current_decision_label.configure(fg=GREEN if decision == 'UP' else RED if decision == 'DOWN' else PINK2)
        except Exception:
            pass
        self.current_decision_detail_var.set(str(model.get('decision_detail', '')))
        self.decision_persistence_var.set(f"Persistence   {int(model.get('persistence', 0))} / 3")
        frozen = str(model.get('frozen_side', 'WAIT'))
        if frozen in ('UP', 'DOWN'):
            self.frozen_call_title_var.set(f'EARLY CALL {frozen}')
            self.frozen_call_detail_var.set('Frozen checkpoint call. Later model changes do not rewrite the historical call; live validation is shown elsewhere.')
            self.frozen_call_probability_var.set(f"Call probability   {float(model.get('call_probability', 50)):.1f}%")
            self.frozen_call_confirmation_var.set(f"Confirmation   {int(model.get('confirmations', 0))} / 4")
        else:
            self.frozen_call_title_var.set('EARLY CALL WAITING')
            self.frozen_call_detail_var.set('One checkpoint call may be frozen after persistent, verified evidence.')
            self.frozen_call_probability_var.set('Call probability   --')
            self.frozen_call_confirmation_var.set('Confirmation   0 / 4')
        self.frozen_call_record_var.set('Tracked record   ' + str(self.early_next_score_var.get()).replace('EARLY NEXT 15M: ', ''))
        by = model.get('buy_yes')
        bn = model.get('buy_no')
        ey = model.get('conservative_yes_edge')
        en = model.get('conservative_no_edge')
        self.kalshi_buy_yes_var.set('BUY YES   --' if by is None else f'BUY YES   {float(by) * 100:.0f}¢')
        self.kalshi_buy_no_var.set('BUY NO   --' if bn is None else f'BUY NO   {float(bn) * 100:.0f}¢')
        self.kalshi_yes_edge_var.set('Conservative YES edge   --' if ey is None else f'Conservative YES edge   {float(ey):+.1f}¢')
        self.kalshi_no_edge_var.set('Conservative NO edge   --' if en is None else f'Conservative NO edge   {float(en):+.1f}¢')
        self.scalp_radar_var.set('VOLATILITY SCALP RADAR • ' + str(model.get('scalp_radar', 'building')))
        self._draw_reference_probability_bars()

    def _chart_projected_path(self, candles, sig=None, chart_fvgs=None, trend_overlay=None):
        """Cheap 3-step projected path used only for visualization."""
        chart_fvgs = chart_fvgs or []
        trend_overlay = trend_overlay or {}
        if len(candles) < 4:
            last = float(candles[-1]['close']) if candles else 0.0
            return {'side': 'MIXED', 'strength': 0.0, 'prices': [last, last, last], 'reason': 'building'}
        closes = [float(r['close']) for r in candles]
        ranges = [max(0.01, float(r['high']) - float(r['low'])) for r in candles[-14:]]
        atr = max(0.01, self._median(ranges))
        slope = (closes[-1] - closes[-4]) / max(1.0, 3.0 * atr)
        score = max(-1.25, min(1.25, slope)) * 0.65
        reasons = []
        e9 = self.ema(closes, 9)[-1]
        e21 = self.ema(closes, 21)[-1]
        if e9 > e21:
            score += 0.28
            reasons.append('EMA9>21')
        elif e9 < e21:
            score -= 0.28
            reasons.append('EMA9<21')
        story = self.chart_interval_fvg_story(candles, chart_fvgs).upper()
        if 'CONTINUE UP' in story or 'PREPPING FOR UP' in story:
            score += 0.45
            reasons.append('FVG→UP')
        elif 'CONTINUE DOWN' in story or 'PREPPING FOR DOWN' in story:
            score -= 0.45
            reasons.append('FVG→DOWN')
        if sig:
            if sig.get('green'):
                score += 0.55
                reasons.append('15m model UP')
            elif sig.get('red'):
                score -= 0.55
                reasons.append('15m model DOWN')
            whale = self._bookmap_whale_read()
            fusion = self._bookmap_chart_fusion(sig, candles, whale=whale)
            whale_path = max(-1.0, min(1.0, float(fusion.get('decision_weight', 0.0) or 0.0) / 8.5))
            if abs(whale_path) >= 0.18:
                score += whale_path * 0.42
                reasons.append(f"Bookmap {fusion.get('state', 'MIXED')} {fusion.get('direction', 'WAIT')}")
            pat = sig.get('pattern') or {}
            if float(pat.get('score', 0.0) or 0.0) >= 70:
                score += 0.28 * float(pat.get('bias', 0.0) or 0.0)
                reasons.append(str(pat.get('name', 'pattern')))
        score = max(-2.0, min(2.0, score))
        side = 'UP' if score > 0.18 else 'DOWN' if score < -0.18 else 'MIXED'
        strength = min(100.0, abs(score) / 2.0 * 100.0)
        last = closes[-1]
        total_move = atr * max(0.22, min(1.35, abs(score) * 0.72))
        if side == 'DOWN':
            total_move *= -1.0
        elif side == 'MIXED':
            total_move = 0.0
        p1 = last + total_move * 0.34
        p2 = last + total_move * 0.58
        p3 = last + total_move
        if side == 'UP':
            p2 -= atr * 0.08
        elif side == 'DOWN':
            p2 += atr * 0.08
        return {'side': side, 'strength': strength, 'prices': [p1, p2, p3], 'reason': ' • '.join(reasons[-4:]) or 'recent candle slope'}

