        page_width_state = {'last_width': 0}

        def _page_canvas_width(event):
            width = int(getattr(event, 'width', 0) or 0)
            if width > 0 and abs(width - page_width_state['last_width']) >= 3:
                page_width_state['last_width'] = width
                page_canvas.itemconfigure(self.page_scroll_window, width=width)
                if getattr(self, '_v82_layout_frozen', False):
                    try:
                        self._v84_fit_horizontal_width(width)
                    except Exception:
                        pass
        page_canvas.bind('<Configure>', _page_canvas_width)
        wheel_state = {'remainder': 0.0}

        def _native_page_wheel(event):
            if getattr(self, 'canvas', None) is event.widget:
                return
            delta = float(getattr(event, 'delta', 0) or 0)
            if not delta:
                return
            wheel_state['remainder'] += -delta / 120.0 * 108.0
            step_px = int(wheel_state['remainder'])
            wheel_state['remainder'] -= step_px
            if step_px == 0:
                step_px = 1 if delta < 0 else -1
            try:
                page_canvas.yview_scroll(step_px, 'units')
                self._scroll_active_until = time.time() + 0.018
                page_canvas.update_idletasks()
            except Exception:
                pass
            return 'break'

        def _whole_page_wheel(event):
            return _native_page_wheel(event)
        self.root.bind('<MouseWheel>', _whole_page_wheel, add='+')
