        def toggle_connection_details():
            win = status_window.get('win')
            try:
                if win is not None and win.winfo_exists():
                    win.destroy()
                    status_window['win'] = None
                    status_btn.configure(text='STATUS ▾')
                    details_visible['value'] = False
                    return
            except Exception:
                pass
            win = tk.Toplevel(self.root)
            status_window['win'] = win
            details_visible['value'] = True
            status_btn.configure(text='STATUS ▴')
            win.title('Bookmap King // Connection Status')
            win.geometry('760x250')
            win.configure(bg=PANEL)
            win.transient(self.root)
            box = ttk.Frame(win, style='Card.TFrame', padding=14)
            box.pack(fill='both', expand=True)
            for title, var in (('KALSHI API AUTH', self.kalshi_auth_status_var), ('AUTO MARKET', self.auto_market_status_var), ('AUTO TARGET', self.auto_target_status_var), ('ODDS FEED', self.odds_feed_status_var), ('ROUND STATE', self.market_reset_var)):
                ttk.Label(box, text=title, style='Muted.Card.TLabel').pack(anchor='w')
                ttk.Label(box, textvariable=var, style='Card.TLabel', wraplength=710, justify='left').pack(anchor='w', pady=(0, 7))

            def _closed():
                status_window['win'] = None
                details_visible['value'] = False
                try:
                    status_btn.configure(text='STATUS ▾')
                except Exception:
                    pass
                win.destroy()
            win.protocol('WM_DELETE_WINDOW', _closed)
