    def _v82_walk_widgets(self, parent):
        """Yield descendants without touching Canvas drawing items."""
        for child in parent.winfo_children():
            yield child
            yield from self._v82_walk_widgets(child)

    def _v82_freeze_entire_page_layout(self):
        """
        V8.2 hard visual lock.

        Tk's pack/grid managers normally recalculate vertical positions whenever
        a wrapped StringVar becomes one line longer or shorter. That was the
        remaining source of the apparent automatic page movement/after-images.

        We temporarily reserve realistic wrapped-text space, let Tk calculate a
        complete layout once, snapshot every pack/grid-managed widget rectangle,
        then convert those widgets to fixed `place` geometry. Afterwards text
        updates cannot move buttons, cards, labels, charts, or scrollbars.
        """
        if getattr(self, '_v82_layout_frozen', False):
            return
        root = self.root
        page = getattr(self, 'page_frame', None)
        if page is None:
            return
        root.update_idletasks()
        saved = {}
        reserve = 'STABLE LIVE READOUT • pressure / lock / survival / breakout / target / momentum / confirmation / structure / liquidity'
        for widget in list(self._v82_walk_widgets(page)):
            try:
                cls = widget.winfo_class()
                if cls not in ('Label', 'TLabel'):
                    continue
                tv = str(widget.cget('textvariable') or '')
                wrap_raw = widget.cget('wraplength')
                wrap = int(float(wrap_raw or 0))
                if not tv or wrap <= 0:
                    continue
                if tv not in saved:
                    saved[tv] = root.getvar(tv)
                    root.setvar(tv, reserve)
            except Exception:
                continue
        root.update_idletasks()
        try:
            center_content = getattr(self, 'center_content', None)
            brain_content = getattr(self, 'brain_content', None)
            center_req = int(center_content.winfo_reqheight()) if center_content is not None else 0
            brain_req = int(brain_content.winfo_reqheight()) if brain_content is not None else 0
            full_body_height = max(900, center_req, brain_req) + 120
            self.center_scroll_canvas.configure(height=full_body_height)
            self.brain_canvas.configure(height=full_body_height)
            root.update_idletasks()
        except Exception:
            pass
        parents = [page] + list(self._v82_walk_widgets(page))
        parent_size = {}
        child_rect = {}
        allowed_unmanaged = {str(page), str(getattr(self, 'center_content', '')), str(getattr(self, 'brain_content', ''))}
        for parent in parents:
            try:
                if parent.winfo_manager() == '' and str(parent) not in allowed_unmanaged:
                    continue
                pw = max(1, int(parent.winfo_width()))
                ph = max(1, int(parent.winfo_height()))
                candidates = []
                overflow = False
                for child in parent.winfo_children():
                    mgr = child.winfo_manager()
                    if mgr not in ('pack', 'grid'):
                        continue
                    x = int(child.winfo_x())
                    y = int(child.winfo_y())
                    w = max(1, int(child.winfo_width()))
                    h = max(1, int(child.winfo_height()))
                    if x + w > pw + 3 or y + h > ph + 3:
                        overflow = True
                        break
                    candidates.append((child, mgr, x, y, w, h))
                if overflow:
                    continue
                parent_size[str(parent)] = (pw, ph)
                for child, mgr, x, y, w, h in candidates:
                    child_rect[str(child)] = (child, mgr, x, y, w, h)
            except Exception:
                continue
        for parent in parents:
            size = parent_size.get(str(parent))
            if not size:
                continue
            try:
                cls = parent.winfo_class()
            except Exception:
                cls = ''
            if cls in ('Frame', 'TFrame', 'Labelframe', 'TLabelframe'):
                try:
                    parent.configure(width=size[0], height=size[1])
                except Exception:
                    pass
                try:
                    parent.pack_propagate(False)
                except Exception:
                    pass
                try:
                    parent.grid_propagate(False)
                except Exception:
                    pass
        for _key, (child, mgr, x, y, w, h) in child_rect.items():
            try:
                if mgr == 'pack':
                    child.pack_forget()
                elif mgr == 'grid':
                    child.grid_forget()
                child.place(x=x, y=y, width=w, height=h)
            except Exception:
                pass
        for tv, value in saved.items():
            try:
                root.setvar(tv, value)
            except Exception:
                pass
        root.update_idletasks()
        try:
            pw, ph = parent_size.get(str(page), (page.winfo_width(), page.winfo_height()))
            self.page_canvas.itemconfigure(self.page_scroll_window, width=int(pw), height=int(ph))
            self.page_canvas.configure(scrollregion=(0, 0, int(pw), int(ph)))
            self._v82_page_scrollregion = (0, 0, int(pw), int(ph))
        except Exception:
            pass
        try:
            cc = getattr(self, 'center_scroll_window', None)
            canvas = getattr(self, 'center_scroll_canvas', None)
            if cc is not None and canvas is not None:
                bbox = canvas.bbox(cc)
                if bbox:
                    canvas.configure(scrollregion=bbox)
        except Exception:
            pass
        try:
            bw = getattr(self, 'brain_window', None)
            canvas = getattr(self, 'brain_canvas', None)
            if bw is not None and canvas is not None:
                bbox = canvas.bbox(bw)
                if bbox:
                    canvas.configure(scrollregion=bbox)
        except Exception:
            pass
        try:
            base_page_width = int(parent_size.get(str(page), (page.winfo_width(), 0))[0])
            self._v84_base_page_width = max(1, base_page_width)
            records = []
            for _key, (child, _mgr, x, y, w, h) in child_rect.items():
                try:
                    parent = child.master
                    base_parent_width = int(parent_size.get(str(parent), (parent.winfo_width(), 0))[0])
                    if base_parent_width <= 0:
                        continue
                    records.append({'child': child, 'parent': parent, 'parent_width': base_parent_width, 'x': int(x), 'width': int(w), 'depth': str(child).count('.')})
                except Exception:
                    continue
            records.sort(key=lambda row: row['depth'])
            self._v84_horizontal_records = records
            self._v84_last_fit_width = self._v84_base_page_width
        except Exception:
            self._v84_horizontal_records = []
        self._v82_layout_frozen = True

    def _v84_fit_horizontal_width(self, viewport_width=None):
        """
        V8.5 horizontal fit.

        V8.4 correctly widened the three BODY columns, but a canvas-window
        timing race left CENTER CONTENT and RIGHT/BRAIN CONTENT at their old
        startup widths.  That is why the app could be maximized while the
        actual chart stayed ~702px wide with a large blank strip beside it.

        This pass keeps every y/height pixel immutable (V8.2 stability) while
        propagating the new width through the canvas windows *during the same
        parent-first pass*.  Descendants therefore see the new center/right
        width immediately and stretch with their column.
        """
        if not getattr(self, '_v82_layout_frozen', False):
            return
        records = getattr(self, '_v84_horizontal_records', None) or []
        if not records:
            return
        if viewport_width is None:
            viewport_width = int(self.page_canvas.winfo_width() or 0)
        viewport_width = int(viewport_width or 0)
        if viewport_width <= 0:
            return
        last = int(getattr(self, '_v84_last_fit_width', 0) or 0)
        if abs(viewport_width - last) < 3:
            return
        try:
            self.page_canvas.itemconfigure(self.page_scroll_window, width=viewport_width)
            self.page_frame.configure(width=viewport_width)
        except Exception:
            pass
        assigned_widths = {str(self.page_frame): viewport_width}
        center_canvas = getattr(self, 'center_scroll_canvas', None)
        center_content = getattr(self, 'center_content', None)
        center_window = getattr(self, 'center_scroll_window', None)
        brain_canvas = getattr(self, 'brain_canvas', None)
        brain_content = getattr(self, 'brain_content', None)
        brain_window = getattr(self, 'brain_window', None)
        for row in records:
            child = row.get('child')
            parent = row.get('parent')
            try:
                if not child.winfo_exists() or not parent.winfo_exists():
                    continue
                parent_key = str(parent)
                current_parent_width = max(1, int(assigned_widths.get(parent_key, parent.winfo_width())))
                base_parent_width = max(1, int(row['parent_width']))
                ratio = current_parent_width / float(base_parent_width)
                new_x = int(round(int(row['x']) * ratio))
                new_w = max(1, int(round(int(row['width']) * ratio)))
                child.place_configure(x=new_x, width=new_w)
                assigned_widths[str(child)] = new_w
                if center_canvas is not None and child is center_canvas:
                    if center_window is not None:
                        center_canvas.itemconfigure(center_window, width=new_w)
                    if center_content is not None:
                        try:
                            center_content.configure(width=new_w)
                        except Exception:
                            pass
                        assigned_widths[str(center_content)] = new_w
                if brain_canvas is not None and child is brain_canvas:
                    if brain_window is not None:
                        brain_canvas.itemconfigure(brain_window, width=new_w)
                    if brain_content is not None:
                        try:
                            brain_content.configure(width=new_w)
                        except Exception:
                            pass
                        assigned_widths[str(brain_content)] = new_w
            except Exception:
                continue
        try:
            if center_canvas is not None and center_window is not None:
                cw = max(1, int(assigned_widths.get(str(center_canvas), center_canvas.winfo_width())))
                center_canvas.itemconfigure(center_window, width=cw)
                assigned_widths[str(center_content)] = cw
        except Exception:
            pass
        try:
            if brain_canvas is not None and brain_window is not None:
                bw = max(1, int(assigned_widths.get(str(brain_canvas), brain_canvas.winfo_width())))
                brain_canvas.itemconfigure(brain_window, width=bw)
                assigned_widths[str(brain_content)] = bw
        except Exception:
            pass
        try:
            region = getattr(self, '_v82_page_scrollregion', None)
            bottom = int(region[3]) if region and len(region) == 4 else int(self.page_frame.winfo_height())
            self.page_canvas.configure(scrollregion=(0, 0, viewport_width, bottom))
            self._v82_page_scrollregion = (0, 0, viewport_width, bottom)
        except Exception:
            pass
        self._v84_last_fit_width = viewport_width

    def _v82_update_live_chart_overlay(self, price=None, source=None):
        """Move only the live-price line/text; never rebuild the whole chart."""
        c = getattr(self, 'canvas', None)
        scale = getattr(self, '_v82_chart_scale', None)
        if c is None or not scale:
            return
        if price is None:
            try:
                price, source = self.effective_live_price()
            except Exception:
                return
        if price is None:
            return
        try:
            price = float(price)
            lo = float(scale['lo'])
            hi = float(scale['hi'])
            top = float(scale['top'])
            ph = float(scale['ph'])
            left = float(scale['left'])
            plot_right = float(scale['plot_right'])
            if hi <= lo:
                return
            yy = top + (hi - price) / (hi - lo) * ph
            yy = max(top, min(top + ph, yy))
            items = getattr(self, '_v82_live_overlay_items', None)
            valid = False
            if items:
                try:
                    valid = all((c.type(i) for i in items))
                except Exception:
                    valid = False
            if not valid:
                back = c.create_line(left, yy, plot_right, yy, fill='#2e1a2d', width=5, tags=('v82_live',))
                line = c.create_line(left, yy, plot_right, yy, fill=TEXT, dash=(2, 4), width=1, tags=('v82_live',))
                txt = c.create_text(plot_right - 3, yy - 11, text='', fill=TEXT, anchor='e', font=('Cascadia Mono', 7, 'bold'), tags=('v82_live',))
                items = (back, line, txt)
                self._v82_live_overlay_items = items
            back, line, txt = items
            c.coords(back, left, yy, plot_right, yy)
            c.coords(line, left, yy, plot_right, yy)
            c.coords(txt, plot_right - 3, yy - 11)
            c.itemconfigure(txt, text=f"LIVE {money(price)} // {source or 'BOOKMAP'}")
            c.tag_raise('v82_live')
        except Exception:
            pass

    def set_chart_timeframe(self, label):
        """
        Seamlessly switch only the center chart's candle interval.

        The V50 live quote mesh keeps running continuously.
        Kalshi/model state is not restarted.
        The Brain remains 15m so changing the visual chart does not alter
        the strategy logic underneath it.
        """
        if label not in self.chart_tf_options:
            return
        previous = self.chart_tf_var.get()
        if previous in self.tf_zoom_memory:
            self.tf_zoom_memory[previous] = self.visible_count
        self.chart_tf_var.set(label)
        self.chart_interval_seconds = self.chart_tf_options[label]
        self.visible_count = self.tf_zoom_memory.get(label, 40)
        self.zoom_var.set(f'Zoom: {self.visible_count} candles')
        if label == '15m':
            self.chart_tf_status_var.set('Chart 15m • model overlays ON')
        elif label in ('3s', '5s'):
            self.chart_tf_status_var.set(f'Chart {label} • RAW BOOKMAP EXECUTIONS • VISUAL ONLY • Brain remains 15m')
        elif label in ('15s', '30s'):
            self.chart_tf_status_var.set(f'Chart {label} • LIVE LOCAL QUOTES • Brain remains 15m')
        else:
            self.chart_tf_status_var.set(f'Chart {label} • Brain remains 15m')
        for tf, btn in getattr(self, 'tf_buttons', {}).items():
            if tf == label:
                btn.configure(bg=PINK_DARK, fg=TEXT)
            else:
                btn.configure(bg=PANEL2, fg=MUTED)
        self.chart_overlay_cache = {}
        self._last_chart_render_key = None
        self.draw_chart()
        try:
            self._draw_rsi_divergence_oscillator()
        except Exception:
            pass

    def _bind_zoom(self):
        self.canvas.bind('<MouseWheel>', self._mouse_zoom)
        self.canvas.bind('<Button-4>', lambda e: self.zoom(-1))
        self.canvas.bind('<Button-5>', lambda e: self.zoom(1))
        shortcut_map = {'q': '15s', 'w': '30s', '1': '1m', '3': '3m', '5': '5m', '2': '15m', '0': '30m', 'h': '1H', 'H': '4H'}

        def timeframe_shortcut(event):
            widget = self.root.focus_get()
            if isinstance(widget, (tk.Entry, tk.Text, ttk.Entry)):
                return
            tf = shortcut_map.get(event.char)
            if tf:
                self.set_chart_timeframe(tf)
        self.root.bind('<Key>', timeframe_shortcut)

    def _mouse_zoom(self, event):
        if event.delta > 0:
            self.zoom(-1)
        elif event.delta < 0:
            self.zoom(1)
        return 'break'

    def zoom(self, direction):
        factor = 0.85 if direction < 0 else 1.18
        self.visible_count = int(self.visible_count * factor)
        self.visible_count = max(self.min_visible, min(self.max_visible, self.visible_count))
        tf = self.chart_tf_var.get()
        if tf in self.tf_zoom_memory:
            self.tf_zoom_memory[tf] = self.visible_count
        self.zoom_var.set(f'Zoom: {self.visible_count} candles')
        self.draw_chart()

    def kalshi_yes_price(self):
        """
        Return best available YES probability proxy in [0,1].

        Supports current *_dollars fields, older integer-cent fields,
        previous quotes, and derivation from NO quotes.
        """
        m = self.kalshi_market or {}

        def parse_probability(raw):
            if raw in (None, ''):
                return None
            try:
                v = float(raw)
            except Exception:
                return None
            if 0.0 <= v <= 1.0:
                return v
            if 1.0 < v <= 100.0:
                return v / 100.0
            return None
        for key in ('last_price_dollars', 'last_price', 'previous_price_dollars', 'previous_price'):
            p = parse_probability(m.get(key))
            if p is not None:
                return p
        bid = None
        ask = None
        for key in ('yes_bid_dollars', 'yes_bid', 'previous_yes_bid_dollars'):
            bid = parse_probability(m.get(key))
            if bid is not None:
                break
        for key in ('yes_ask_dollars', 'yes_ask', 'previous_yes_ask_dollars'):
            ask = parse_probability(m.get(key))
            if ask is not None:
                break
        if bid is not None and ask is not None:
            return (bid + ask) / 2.0
        if bid is not None:
            return bid
        if ask is not None:
            return ask
        no_bid = None
        no_ask = None
        for key in ('no_bid_dollars', 'no_bid'):
            no_bid = parse_probability(m.get(key))
            if no_bid is not None:
                break
        for key in ('no_ask_dollars', 'no_ask'):
            no_ask = parse_probability(m.get(key))
            if no_ask is not None:
                break
        if no_bid is not None and no_ask is not None:
            return 1.0 - (no_bid + no_ask) / 2.0
        if no_ask is not None:
            return 1.0 - no_ask
        if no_bid is not None:
            return 1.0 - no_bid
        return None

    @staticmethod
    def _parse_book_rows(rows):
        parsed = []
        for row in rows or []:
            try:
                p = float(row[0])
                q = float(row[1])
            except Exception:
                continue
            if 0.0 <= p <= 1.0 and q >= 0:
                parsed.append((p, q))
        return parsed

    def _kalshi_orderbook_ws_headers(self):
        key_id = str(self.kalshi_key_id_text or '').strip()
        pem = str(self.kalshi_private_key_text or '').strip()
        if not key_id or not pem:
            raise RuntimeError('Submit Kalshi API Key ID + private key for live order-book WS')
        try:
            from cryptography.hazmat.primitives import hashes
            from cryptography.hazmat.primitives.asymmetric import padding
        except Exception:
            raise RuntimeError('cryptography package missing')
        private_key = self._load_private_key_from_text(pem)
        timestamp = str(int(time.time() * 1000))
        message = (timestamp + 'GET' + KALSHI_WS_PATH).encode('utf-8')
        signature = private_key.sign(message, padding.PSS(mgf=padding.MGF1(hashes.SHA256()), salt_length=padding.PSS.DIGEST_LENGTH), hashes.SHA256())
        return [f'KALSHI-ACCESS-KEY: {key_id}', f'KALSHI-ACCESS-TIMESTAMP: {timestamp}', f"KALSHI-ACCESS-SIGNATURE: {base64.b64encode(signature).decode('utf-8')}"]

    @staticmethod
    def _snapshot_level_dict(rows):
        result = {}
        for row in rows or []:
            try:
                p = float(row[0])
                q = float(row[1])
            except Exception:
                continue
            if 0.0 <= p <= 1.0 and q > 0:
                result[p] = q
        return result

    def _publish_kalshi_book_levels(self, ticker, yes_levels, no_levels, source):
        yes_rows = sorted([(float(p), float(q)) for p, q in yes_levels.items() if q > 0], key=lambda x: x[0])
        no_rows = sorted([(float(p), float(q)) for p, q in no_levels.items() if q > 0], key=lambda x: x[0])
        best_yes_bid = max((p for p, _q in yes_rows), default=None)
        best_no_bid = max((p for p, _q in no_rows), default=None)
        yes_ask = 1.0 - best_no_bid if best_no_bid is not None else None
        spread = yes_ask - best_yes_bid if yes_ask is not None and best_yes_bid is not None else None
        yes_near = [(p, q) for p, q in yes_rows if best_yes_bid is not None and p >= best_yes_bid - 0.05]
        no_near = [(p, q) for p, q in no_rows if best_no_bid is not None and p >= best_no_bid - 0.05]
        yes_depth = sum((q for _p, q in yes_near))
        no_depth = sum((q for _p, q in no_near))
        total = yes_depth + no_depth
        imbalance = (yes_depth - no_depth) / total if total > 0 else 0.0
        yes_wall = max(yes_near, key=lambda x: x[1], default=(None, 0.0))
        no_wall = max(no_near, key=lambda x: x[1], default=(None, 0.0))
        snap = {'ticker': ticker, 'ts': time.time(), 'source': source, 'best_yes_bid': best_yes_bid, 'best_no_bid': best_no_bid, 'yes_ask': yes_ask, 'spread': spread, 'yes_depth': yes_depth, 'no_depth': no_depth, 'imbalance': imbalance, 'yes_wall_price': yes_wall[0], 'yes_wall_qty': yes_wall[1], 'no_wall_price': no_wall[0], 'no_wall_qty': no_wall[1]}
        with self.kalshi_book_lock:
            self.kalshi_orderbook = snap
            self.kalshi_orderbook_ts = snap['ts']
            self.kalshi_orderbook_history.append(snap)
            cutoff = time.time() - 120.0
            self.kalshi_orderbook_history = [x for x in self.kalshi_orderbook_history[-800:] if x.get('ts', 0) >= cutoff and x.get('ticker') == ticker]

    def _start_kalshi_orderbook_ws(self):
        if self.kalshi_book_ws_thread and self.kalshi_book_ws_thread.is_alive():
            return
        self.kalshi_book_ws_thread = threading.Thread(target=self._kalshi_orderbook_ws_worker, daemon=True, name='ChartKingKalshiOrderBook')
        self.kalshi_book_ws_thread.start()

    def _kalshi_orderbook_ws_worker(self):
        try:
            import websocket
        except Exception as exc:
            self.kalshi_book_ws_error = f'websocket-client unavailable: {exc}'
            return
        while self.running:
            ticker = str((self.kalshi_market or {}).get('ticker') or self.kalshi_ticker or '').strip()
            if not ticker or not self.kalshi_key_id_text or (not self.kalshi_private_key_text):
                self.kalshi_book_ws_connected = False
                time.sleep(1.0)
                continue
            ws = None
            try:
                ws = websocket.create_connection(KALSHI_WS_URL, header=self._kalshi_orderbook_ws_headers(), timeout=10)
                ws.settimeout(5)
                ws.send(json.dumps({'id': 63, 'cmd': 'subscribe', 'params': {'channels': ['orderbook_delta'], 'market_ticker': ticker}}))
                self.kalshi_book_ws_connected = True
                self.kalshi_book_ws_ticker = ticker
                self.kalshi_book_ws_error = ''
                yes_levels = {}
                no_levels = {}
                while self.running:
                    current_ticker = str((self.kalshi_market or {}).get('ticker') or self.kalshi_ticker or '').strip()
                    if current_ticker and current_ticker != ticker:
                        break
                    try:
                        raw = ws.recv()
                    except Exception as exc:
                        if 'timed out' in str(exc).lower():
                            continue
                        raise
                    if not raw:
                        continue
                    message = json.loads(raw)
                    mtype = message.get('type')
                    msg = message.get('msg') or {}
                    if mtype == 'error':
                        raise RuntimeError(msg.get('msg') or f'Kalshi WS error: {msg}')
                    if mtype == 'orderbook_snapshot':
                        if msg.get('market_ticker') != ticker:
                            continue
                        yes_levels = self._snapshot_level_dict(msg.get('yes_dollars_fp') or msg.get('yes_dollars') or msg.get('yes') or [])
                        no_levels = self._snapshot_level_dict(msg.get('no_dollars_fp') or msg.get('no_dollars') or msg.get('no') or [])
                        self._publish_kalshi_book_levels(ticker, yes_levels, no_levels, 'KALSHI WS LIVE')
                        self.kalshi_book_ws_updates += 1
                        continue
                    if mtype == 'orderbook_delta':
                        if msg.get('market_ticker') != ticker:
                            continue
                        side = str(msg.get('side', '')).lower()
                        if side not in ('yes', 'no'):
                            continue
                        try:
                            price = float(msg.get('price_dollars') or msg.get('price'))
                            delta = float(msg.get('delta_fp') or msg.get('delta'))
                        except Exception:
                            continue
                        levels = yes_levels if side == 'yes' else no_levels
                        new_qty = float(levels.get(price, 0.0)) + delta
                        if new_qty <= 0:
                            levels.pop(price, None)
                        else:
                            levels[price] = new_qty
                        self._publish_kalshi_book_levels(ticker, yes_levels, no_levels, 'KALSHI WS LIVE')
                        self.kalshi_book_ws_updates += 1
            except Exception as exc:
                self.kalshi_book_ws_error = str(exc)
                self.kalshi_book_ws_connected = False
            finally:
                self.kalshi_book_ws_connected = False
                if ws is not None:
                    try:
                        ws.close()
                    except Exception:
                        pass
            time.sleep(1.2)

    def _fetch_kalshi_orderbook(self):
        """
        Public REST fallback.

        When the authenticated WebSocket is fresh, it remains authoritative.
        """
        if self.kalshi_book_ws_connected and time.time() - self.kalshi_orderbook_ts < 3.0:
            return
        ticker = str((self.kalshi_market or {}).get('ticker') or self.kalshi_ticker or '').strip()
        if not ticker:
            return
        try:
            data = self.kalshi_get('/markets/' + urllib.parse.quote(ticker) + '/orderbook')
            book = data.get('orderbook_fp') or data.get('orderbook') or {}
            yes_rows = self._parse_book_rows(book.get('yes_dollars') or book.get('yes') or [])
            no_rows = self._parse_book_rows(book.get('no_dollars') or book.get('no') or [])
            yes_levels = {float(p): float(q) for p, q in yes_rows if q > 0}
            no_levels = {float(p): float(q) for p, q in no_rows if q > 0}
            self._publish_kalshi_book_levels(ticker, yes_levels, no_levels, 'KALSHI REST FALLBACK')
            self.kalshi_orderbook_error = ''
        except Exception as exc:
            self.kalshi_orderbook_error = str(exc)

    def kalshi_orderbook_intelligence(self):
        with self.kalshi_book_lock:
            book = dict(self.kalshi_orderbook or {})
        now = time.time()
        age = now - float(book.get('ts', 0) or 0)
        if not book or age > 6.0:
            return {'ready': False, 'up_score': 50.0, 'down_score': 50.0, 'pressure': 'WAITING', 'source': 'WAITING', 'evidence': self.kalshi_book_ws_error or self.kalshi_orderbook_error or 'Kalshi book waiting'}
        imbalance = float(book.get('imbalance', 0.0) or 0.0)
        spread = book.get('spread')
        yes_bid = book.get('best_yes_bid')
        yes_depth = float(book.get('yes_depth', 0.0) or 0.0)
        no_depth = float(book.get('no_depth', 0.0) or 0.0)
        old = None
        for item in reversed(self.kalshi_orderbook_history):
            if now - float(item.get('ts', 0)) >= 8.0:
                old = item
                break
        imbalance_shift = 0.0
        bid_shift = 0.0
        if old:
            imbalance_shift = imbalance - float(old.get('imbalance', 0.0) or 0.0)
            if yes_bid is not None and old.get('best_yes_bid') is not None:
                bid_shift = float(yes_bid) - float(old.get('best_yes_bid'))
        up = 50.0
        down = 50.0
        evidence = []
        if imbalance >= 0.12:
            up += min(24.0, abs(imbalance) * 42.0)
            evidence.append('YES near-book depth dominates')
        elif imbalance <= -0.12:
            down += min(24.0, abs(imbalance) * 42.0)
            evidence.append('NO near-book depth dominates')
        if imbalance_shift >= 0.1:
            up += min(13.0, imbalance_shift * 45.0)
            evidence.append('YES depth strengthening')
        elif imbalance_shift <= -0.1:
            down += min(13.0, abs(imbalance_shift) * 45.0)
            evidence.append('NO depth strengthening')
        if bid_shift >= 0.02:
            up += 8.0
            evidence.append('YES best bid repricing upward')
        elif bid_shift <= -0.02:
            down += 8.0
            evidence.append('YES best bid repricing downward')
        if spread is not None and spread > 0.08:
            up -= 8.0
            down -= 8.0
            evidence.append('wide spread lowers book trust')
        elif spread is not None and spread <= 0.03:
            if up > down:
                up += 2.0
            elif down > up:
                down += 2.0
            evidence.append('tight spread')
        yes_wall_qty = float(book.get('yes_wall_qty', 0.0) or 0.0)
        no_wall_qty = float(book.get('no_wall_qty', 0.0) or 0.0)
        if yes_depth > 0 and yes_wall_qty / yes_depth >= 0.45:
            up += 5.0
            evidence.append('large YES bid wall')
        if no_depth > 0 and no_wall_qty / no_depth >= 0.45:
            down += 5.0
            evidence.append('large NO bid wall')
        up = max(0.0, min(100.0, up))
        down = max(0.0, min(100.0, down))
        pressure = 'UP PRESSURE' if up >= down + 10 else 'DOWN PRESSURE' if down >= up + 10 else 'BALANCED'
        return {'ready': True, 'source': book.get('source', 'UNKNOWN'), 'up_score': up, 'down_score': down, 'pressure': pressure, 'imbalance': imbalance, 'imbalance_shift': imbalance_shift, 'bid_shift': bid_shift, 'spread': spread, 'best_yes_bid': yes_bid, 'yes_ask': book.get('yes_ask'), 'yes_depth': yes_depth, 'no_depth': no_depth, 'evidence': ' • '.join(evidence[:5]) if evidence else 'balanced book'}

    def effective_target(self):
        """Manual target overrides auto-detected Kalshi target when enabled."""
        if self.use_manual_target_var.get():
            raw = self.manual_target_var.get().strip().replace('$', '').replace(',', '')
            try:
                value = float(raw)
                if value > 1000:
                    return (value, 'MANUAL')
            except Exception:
                pass
        if self.target_price:
            return (float(self.target_price), 'AUTO')
        return (None, 'NONE')

    def open_kalshi_auth_dialog(self):
        win = tk.Toplevel(self.root)
        win.title('Kalshi API Credentials')
        win.geometry('700x500')
        win.configure(bg=PANEL)
        win.transient(self.root)
        outer = ttk.Frame(win, style='Card.TFrame', padding=14)
        outer.pack(fill='both', expand=True)
        ttk.Label(outer, text='API Key ID', style='Strong.Card.TLabel').pack(anchor='w')
        ttk.Entry(outer, textvariable=self.kalshi_key_id_var, width=75).pack(fill='x', pady=(4, 10))
        ttk.Label(outer, text='Paste full RSA private-key PEM', style='Strong.Card.TLabel').pack(anchor='w')
        ttk.Label(outer, text='Stored in memory for this app session only.', style='Muted.Card.TLabel').pack(anchor='w', pady=(2, 5))
        key_text = tk.Text(outer, height=15, bg=PANEL2, fg=TEXT, insertbackground=TEXT, wrap='none', font=('Consolas', 9))
        key_text.pack(fill='both', expand=True)
        if self.kalshi_private_key_text:
            key_text.insert('1.0', self.kalshi_private_key_text)
        local_status = tk.StringVar(value=self.kalshi_auth_status_var.get())
        ttk.Label(outer, textvariable=local_status, style='Muted.Card.TLabel', wraplength=650).pack(anchor='w', pady=(10, 6))
        buttons = ttk.Frame(outer, style='Card.TFrame')
        buttons.pack(fill='x')
        submit_btn = ttk.Button(buttons, text='SUBMIT + VERIFY')
        submit_btn.pack(side='left')
        ttk.Button(buttons, text='CLOSE', command=win.destroy).pack(side='left', padx=6)

        def submit():
            key_id = self.kalshi_key_id_var.get().strip()
            pem = key_text.get('1.0', 'end').strip()
            if not key_id:
                local_status.set('Enter the Kalshi API Key ID.')
                return
            if 'PRIVATE KEY' not in pem:
                local_status.set('Paste the full private-key PEM text.')
                return
            self.kalshi_key_id_text = key_id
            self.kalshi_private_key_text = pem
            self.kalshi_credentials_verified = False
            self.kalshi_auth_status_var.set('Kalshi API: verifying…')
            local_status.set('Submitting signed read-only verification request…')
            submit_btn.configure(state='disabled')

            def worker():
                ok, message = self._verify_kalshi_credentials(key_id, pem)

                def finish():
                    self.kalshi_credentials_verified = ok
                    self.kalshi_auth_status_var.set(message)
                    local_status.set(message)
                    submit_btn.configure(state='normal')
                self.root.after(0, finish)
            threading.Thread(target=worker, daemon=True).start()
        submit_btn.configure(command=submit)

    def _load_private_key_from_text(self, pem_text):
        try:
            from cryptography.hazmat.primitives import serialization
        except Exception:
            raise RuntimeError('Missing cryptography package. Run: py -m pip install cryptography')
        return serialization.load_pem_private_key(pem_text.encode('utf-8'), password=None)

    def _kalshi_authenticated_get(self, path, params=None):
        """
        Signed read-only GET using the credentials already pasted into Chart King.

        Kalshi signs timestamp + GET + path, excluding query parameters.
        """
        if not self.kalshi_key_id_var.get().strip():
            raise RuntimeError('Kalshi API Key ID not submitted')
        if not self.kalshi_private_key_text:
            raise RuntimeError('Kalshi private key not submitted')
        try:
            from cryptography.hazmat.primitives import hashes
            from cryptography.hazmat.primitives.asymmetric import padding
        except Exception:
            raise RuntimeError('cryptography package missing')
        key_id = self.kalshi_key_id_var.get().strip()
        private_key = self._load_private_key_from_text(self.kalshi_private_key_text)
        timestamp = str(int(time.time() * 1000))
        full_path = '/trade-api/v2' + path
        message = f'{timestamp}GET{full_path}'.encode('utf-8')
        signature = private_key.sign(message, padding.PSS(mgf=padding.MGF1(hashes.SHA256()), salt_length=padding.PSS.DIGEST_LENGTH), hashes.SHA256())
        headers = {'Accept': 'application/json', 'User-Agent': 'ChartKingV62/1.0', 'KALSHI-ACCESS-KEY': key_id, 'KALSHI-ACCESS-TIMESTAMP': timestamp, 'KALSHI-ACCESS-SIGNATURE': base64.b64encode(signature).decode('utf-8')}
        url = KALSHI_BASE + path
        if params:
            url += '?' + urllib.parse.urlencode(params)
        req = urllib.request.Request(url, headers=headers, method='GET')
        with urllib.request.urlopen(req, timeout=6) as response:
            return json.loads(response.read().decode('utf-8'))

    def _verify_kalshi_credentials(self, key_id, pem_text):
        try:
            from cryptography.hazmat.primitives import hashes
            from cryptography.hazmat.primitives.asymmetric import padding
        except Exception:
            return (False, 'Kalshi API: cryptography package missing')
        try:
            private_key = self._load_private_key_from_text(pem_text)
            path = '/trade-api/v2/portfolio/balance'
            timestamp = str(int(time.time() * 1000))
            message = f'{timestamp}GET{path}'.encode('utf-8')
            signature = private_key.sign(message, padding.PSS(mgf=padding.MGF1(hashes.SHA256()), salt_length=padding.PSS.DIGEST_LENGTH), hashes.SHA256())
            headers = {'Accept': 'application/json', 'User-Agent': 'ChartKingV50/1.0', 'KALSHI-ACCESS-KEY': key_id, 'KALSHI-ACCESS-TIMESTAMP': timestamp, 'KALSHI-ACCESS-SIGNATURE': base64.b64encode(signature).decode('utf-8')}
            req = urllib.request.Request('https://external-api.kalshi.com' + path, headers=headers, method='GET')
            with urllib.request.urlopen(req, timeout=8) as response:
                body = json.loads(response.read().decode('utf-8'))
            balance = body.get('balance')
            if balance is not None:
                try:
                    dollars = float(balance) / 100.0
                    return (True, f'Kalshi API: VERIFIED ✓ • balance {money(dollars)}')
                except Exception:
                    pass
            return (True, 'Kalshi API: VERIFIED ✓ • authenticated request accepted')
        except urllib.error.HTTPError as exc:
            try:
                detail = exc.read().decode('utf-8', errors='replace')[:220]
            except Exception:
                detail = ''
            return (False, f'Kalshi API: FAILED ({exc.code}) • {detail or exc.reason}')
        except Exception as exc:
            return (False, f'Kalshi API: FAILED • {exc}')

    def browse_private_key(self):
        path = filedialog.askopenfilename(title='Select Kalshi private key PEM', filetypes=[('PEM files', '*.pem'), ('All files', '*.*')])
        if path:
            self.kalshi_private_key_path_var.set(path)

    def _kalshi_ws_headers(self):
        key_id = self.kalshi_key_id_var.get().strip()
        key_path = self.kalshi_private_key_path_var.get().strip()
        if not key_id:
            raise RuntimeError('Kalshi API Key ID is missing')
        if not self.kalshi_private_key_text.strip() and (not key_path):
            raise RuntimeError('Paste a Kalshi private key first')
        try:
            from cryptography.hazmat.primitives import serialization, hashes
            from cryptography.hazmat.primitives.asymmetric import padding
        except Exception:
            raise RuntimeError('Missing cryptography package. Run: py -m pip install cryptography websocket-client')
        if self.kalshi_private_key_text.strip():
            private_key = serialization.load_pem_private_key(self.kalshi_private_key_text.encode('utf-8'), password=None)
        else:
            with open(key_path, 'rb') as f:
                private_key = serialization.load_pem_private_key(f.read(), password=None)
        timestamp = str(int(time.time() * 1000))
        message = (timestamp + 'GET' + KALSHI_WS_PATH).encode('utf-8')
        signature = private_key.sign(message, padding.PSS(mgf=padding.MGF1(hashes.SHA256()), salt_length=padding.PSS.DIGEST_LENGTH), hashes.SHA256())
        return [f'KALSHI-ACCESS-KEY: {key_id}', f"KALSHI-ACCESS-SIGNATURE: {base64.b64encode(signature).decode('utf-8')}", f'KALSHI-ACCESS-TIMESTAMP: {timestamp}']

    def _start_brti_websocket(self):
        if self.brti_thread and self.brti_thread.is_alive():
            return
        self.brti_thread = threading.Thread(target=self._brti_websocket_worker, daemon=True)
        self.brti_thread.start()

    def _brti_websocket_worker(self):
        try:
            import websocket
        except Exception:
            self.brti_ws_error = 'Missing websocket-client. Run: py -m pip install websocket-client cryptography'
            return
        while self.running:
            ws = None
            try:
                headers = self._kalshi_ws_headers()
                ws = websocket.create_connection(KALSHI_WS_URL, header=headers, timeout=15)
                subscribe = {'id': 1, 'cmd': 'subscribe', 'params': {'channels': ['cfbenchmarks_value'], 'index_ids': ['BRTI']}}
                ws.send(json.dumps(subscribe))
                self.brti_ws_connected = True
                self.brti_ws_error = ''
                while self.running:
                    raw = ws.recv()
                    if raw is None:
                        continue
                    data = json.loads(raw)
                    mtype = data.get('type')
                    if mtype == 'error':
                        msg = data.get('msg', {})
                        raise RuntimeError(f"Kalshi WS error {msg.get('code')}: {msg.get('msg')}")
                    if mtype != 'cfbenchmarks_value':
                        continue
                    msg = data.get('msg', {})
                    if msg.get('index_id') != 'BRTI':
                        continue
                    upstream_raw = msg.get('data', '{}')
                    try:
                        upstream = json.loads(upstream_raw)
                        value = float(upstream['value'])
                        source_ts = int(upstream.get('time', msg.get('received_at', 0)))
                    except Exception:
                        continue
                    avg60 = msg.get('avg_60s_data') or {}
                    final60 = msg.get('last_60s_windowed_average_15min') or {}
                    packet = {'received': time.time(), 'price': value, 'source_ts_ms': source_ts, 'received_at': msg.get('received_at'), 'avg60': float(avg60['value']) if avg60.get('value') is not None else None, 'final_avg': float(final60['value']) if final60.get('value') is not None else None, 'final_window_size': int(final60.get('window_size', 0)) if final60 else 0}
                    while self.brti_queue.qsize() > 100:
                        try:
                            self.brti_queue.get_nowait()
                        except Exception:
                            break
                    try:
                        self.brti_queue.put_nowait(packet)
                    except queue.Full:
                        try:
                            self.brti_queue.get_nowait()
                        except Exception:
                            pass
                        try:
                            self.brti_queue.put_nowait(packet)
                        except Exception:
                            pass
            except Exception as e:
                self.brti_ws_connected = False
                self.brti_ws_error = str(e)
                time.sleep(1.0)
            finally:
                if ws is not None:
                    try:
                        ws.close()
                    except Exception:
                        pass
        self.brti_ws_connected = False

    def _drain_brti_ticks(self):
        updated = False
        latest = None
        while True:
            try:
                packet = self.brti_queue.get_nowait()
            except queue.Empty:
                break
            updated = True
            latest = packet
            self.brti_samples.append((packet['received'], packet['price']))
        if latest is not None:
            self.brti_price = latest['price']
            self.brti_tick_ts = latest['received']
            self.brti_received_at = latest['received_at'] or 0
            self.brti_avg60 = latest['avg60']
            self.brti_final_min_avg = latest['final_avg']
            self.brti_final_min_window_size = latest['final_window_size']
            self.brti_tick_count += 1
            self.current_spot = self.brti_price
            self.live_prices.append((latest['received'], self.brti_price))
        cutoff = time.time() - 3600
        if len(self.brti_samples) > 10000:
            self.brti_samples = [x for x in self.brti_samples if x[0] >= cutoff]
        if len(self.live_prices) > 15000:
            self.live_prices = [x for x in self.live_prices if x[0] >= cutoff]
        return updated

    def effective_live_price(self):
        now = time.time()
        if self.quote_mesh_price is not None and now - self.quote_mesh_last <= 3.0:
            return (float(self.quote_mesh_price), f'LIVE MESH {self.quote_mesh_source}')
        if self.kraken_price is not None and now - self.kraken_tick_ts <= 3.0:
            return (float(self.kraken_price), self.live_stream_source)
        if self.current_spot is not None:
            return (float(self.current_spot), 'LAST LIVE QUOTE')
        return (None, 'WAITING FOR BTC')

    def _start_public_quote_mesh(self):
        if self.quote_mesh_threads:
            return
        for name, target in (('COINBASE', self._quote_worker_coinbase), ('KRAKEN', self._quote_worker_kraken), ('BITSTAMP', self._quote_worker_bitstamp)):
            t = threading.Thread(target=target, name=f'BTCQuote-{name}', daemon=True)
            self.quote_mesh_threads.append(t)
            t.start()

    def _queue_mesh_quote(self, source, bid, ask, last=None):
        try:
            bid = float(bid)
            ask = float(ask)
            last = float(last) if last is not None else None
        except Exception:
            return
        if bid <= 0 or ask <= 0 or ask < bid:
            return
        packet = {'source': source, 'ts': time.time(), 'bid': bid, 'ask': ask, 'mid': (bid + ask) / 2.0, 'last': last}
        try:
            self.quote_mesh_queue.put_nowait(packet)
        except queue.Full:
            try:
                self.quote_mesh_queue.get_nowait()
            except Exception:
                pass
            try:
                self.quote_mesh_queue.put_nowait(packet)
            except Exception:
                pass

    def _quote_worker_coinbase(self):
        while self.live_feed_active:
            try:
                data = http_json('https://api.exchange.coinbase.com/products/BTC-USD/ticker', {'_': int(time.time() * 1000)}, timeout=3)
                p = float(data['price'])
                self._queue_mesh_quote('COINBASE', data.get('bid', p), data.get('ask', p), p)
            except Exception:
                pass
            time.sleep(1.0)

    def _quote_worker_kraken(self):
        while self.live_feed_active:
            try:
                data = http_json('https://api.kraken.com/0/public/Ticker', {'pair': 'XBTUSD', '_': int(time.time() * 1000)}, timeout=3)
                result = data.get('result') or {}
                if result:
                    row = next(iter(result.values()))
                    self._queue_mesh_quote('KRAKEN', row['b'][0], row['a'][0], row['c'][0])
            except Exception:
                pass
            time.sleep(1.0)

    def _quote_worker_bitstamp(self):
        while self.live_feed_active:
            try:
                data = http_json('https://www.bitstamp.net/api/v2/ticker/btcusd/', {'_': int(time.time() * 1000)}, timeout=3)
                self._queue_mesh_quote('BITSTAMP', data['bid'], data['ask'], data.get('last'))
            except Exception:
                pass
            time.sleep(1.0)

    def _drain_public_quote_mesh(self):
        while True:
            try:
                packet = self.quote_mesh_queue.get_nowait()
            except queue.Empty:
                break
            with self.quote_mesh_lock:
                self.quote_mesh[packet['source']] = packet
        now = time.time()
        with self.quote_mesh_lock:
            fresh = [q for q in self.quote_mesh.values() if now - q['ts'] <= 3.0]
        if not fresh:
            return False
        mids = sorted((q['mid'] for q in fresh))
        if len(mids) % 2:
            aggregate = mids[len(mids) // 2]
        else:
            aggregate = (mids[len(mids) // 2 - 1] + mids[len(mids) // 2]) / 2.0
        old = self.quote_mesh_price
        self.quote_mesh_price = float(aggregate)
        self.quote_mesh_last = now
        self.quote_mesh_updates += 1
        self.quote_mesh_source = '+'.join(sorted((q['source'] for q in fresh)))
        self.current_spot = self.quote_mesh_price
        changed = old is None or abs(self.quote_mesh_price - old) > 1e-06
        if changed:
            self.live_prices.append((now, self.quote_mesh_price))
            cutoff = now - 7200
            if len(self.live_prices) > 30000:
                self.live_prices = [x for x in self.live_prices if x[0] >= cutoff]
        return changed

    def _quote_mesh_diagnostic(self):
        now = time.time()
        with self.quote_mesh_lock:
            parts = []
            for name in ('COINBASE', 'KRAKEN', 'BITSTAMP'):
                q = self.quote_mesh.get(name)
                if q:
                    parts.append(f"{name} {q['mid']:,.2f} ({now - q['ts']:.1f}s)")
                else:
                    parts.append(f'{name} --')
        return ' • '.join(parts)

    def _start_permanent_live_stream(self):
        if self.live_stream_thread and self.live_stream_thread.is_alive():
            return
        self.live_feed_active = True
        self.live_stream_thread = threading.Thread(target=self._permanent_live_stream_worker, daemon=True)
        self.live_stream_thread.start()

    def _push_live_stream_quote(self, bid, ask, last=None, source='KRAKEN'):
        try:
            bid = float(bid)
            ask = float(ask)
            last = float(last) if last is not None else None
        except Exception:
            return
        if bid <= 0 or ask <= 0 or ask < bid:
            return
        packet = {'ts': time.time(), 'bid': bid, 'ask': ask, 'mid': (bid + ask) / 2.0, 'last': last, 'source': source}
        while self.live_stream_queue.qsize() > 200:
            try:
                self.live_stream_queue.get_nowait()
            except Exception:
                break
        try:
            self.live_stream_queue.put_nowait(packet)
        except Exception:
            pass

    def _permanent_live_stream_worker(self):
        """
        This loop NEVER depends on self.running.

        Primary:
          Kraken WebSocket v2 ticker with event_trigger='bbo',
          so updates publish when best bid/offer changes.

        Fallback:
          Kraken public REST ticker once per second.

        A Kalshi/context/history failure therefore cannot stop BTC motion.
        """
        try:
            import websocket as wsmod
        except Exception:
            wsmod = None
            self.live_ws_error = 'websocket-client not installed; REST fallback active'
        while self.live_feed_active:
            if wsmod is not None:
                ws = None
                try:
                    self.live_stream_source = 'KRAKEN BBO WS'
                    ws = wsmod.create_connection('wss://ws.kraken.com/v2', timeout=10)
                    ws.send(json.dumps({'method': 'subscribe', 'params': {'channel': 'ticker', 'symbol': ['BTC/USD'], 'event_trigger': 'bbo', 'snapshot': True}, 'req_id': 49}))
                    self.live_ws_connected = True
                    self.live_ws_error = ''
                    while self.live_feed_active:
                        raw = ws.recv()
                        if not raw:
                            continue
                        msg = json.loads(raw)
                        if msg.get('method') == 'subscribe':
                            result = msg.get('result') or {}
                            if result.get('success') is False:
                                raise RuntimeError(result.get('error') or 'Kraken subscription failed')
                            continue
                        if msg.get('channel') != 'ticker':
                            continue
                        if msg.get('type') not in ('snapshot', 'update'):
                            continue
                        rows = msg.get('data') or []
                        for row in rows:
                            if row.get('symbol') != 'BTC/USD':
                                continue
                            bid = row.get('bid')
                            ask = row.get('ask')
                            last = row.get('last')
                            if bid is None or ask is None:
                                continue
                            self.live_ws_last = time.time()
                            self._push_live_stream_quote(bid, ask, last, 'KRAKEN BBO WS')
                except Exception as exc:
                    self.live_ws_connected = False
                    self.live_ws_error = str(exc)
                finally:
                    if ws is not None:
                        try:
                            ws.close()
                        except Exception:
                            pass
            self.live_ws_connected = False
            self.live_stream_source = 'KRAKEN REST FALLBACK'
            fallback_until = time.time() + 5.0
            while self.live_feed_active and time.time() < fallback_until:
                try:
                    data = http_json('https://api.kraken.com/0/public/Ticker', {'pair': 'XBTUSD', '_': int(time.time() * 1000)}, timeout=3)
                    result = data.get('result') or {}
                    if result:
                        row = next(iter(result.values()))
                        bid = row['b'][0]
                        ask = row['a'][0]
                        last = row['c'][0]
                        self._push_live_stream_quote(bid, ask, last, 'KRAKEN REST FALLBACK')
                except Exception as exc:
                    self.live_ws_error = str(exc)
                time.sleep(1.0)

    def _drain_permanent_live_stream(self):
        latest = None
        applied = 0
        while True:
            try:
                latest = self.live_stream_queue.get_nowait()
                applied += 1
            except queue.Empty:
                break
        if latest is None:
            return False
        old_price = self.current_spot
        self.kraken_bid = latest['bid']
        self.kraken_ask = latest['ask']
        self.kraken_last = latest['last']
        self.kraken_price = latest['mid']
        self.kraken_tick_ts = latest['ts']
        self.kraken_tick_count += applied
        self.live_stream_source = latest['source']
        self.live_stream_updates += applied
        self.current_spot = float(latest['mid'])
        now = time.time()
        self.live_prices.append((now, self.current_spot))
        cutoff = now - 3600
        if len(self.live_prices) > 20000:
            self.live_prices = [x for x in self.live_prices if x[0] >= cutoff]
        return old_price is None or abs(self.current_spot - old_price) > 1e-06

    def _public_history_refresh_worker(self):
        while self.live_feed_active:
            try:
                self._fetch_1m_history()
            except Exception:
                pass
            try:
                self.btc_5m = self._fetch_tf_history(300)
            except Exception:
                pass
            try:
                self._fetch_btc_history()
            except Exception:
                pass
            time.sleep(15.0)

    def _preload_btc_context(self):
        """
        Load chart/indicator history without requiring a Kalshi ticker.
        Failures here cannot touch live_feed_active.
        """
        try:
            self._fetch_btc_history()
        except Exception as exc:
            self.last_error = f'15m history: {exc}'
        try:
            self._fetch_1m_history()
        except Exception:
            pass
        try:
            self.btc_5m = self._fetch_tf_history(300)
        except Exception:
            pass
        try:
            self.btc_1h = self._fetch_tf_history(3600)
        except Exception:
            pass
        try:
            self._stockpile_backfill_open_markets()
        except Exception:
            pass

    def _start_kraken_live(self):
        if self.kraken_thread and self.kraken_thread.is_alive():
            return
        self.kraken_thread = threading.Thread(target=self._kraken_live_worker, daemon=True)
        self.kraken_thread.start()

    def _kraken_live_worker(self):
        """
        Dedicated public Kraken ticker thread.

        It does not call Kalshi, Coinbase history, indicators, or the order book,
        so those cannot block the live number/candle.
        """
        url = 'https://api.kraken.com/0/public/Ticker'
        while self.running:
            try:
                stamp = int(time.time() * 1000)
                data = http_json(url, {'pair': 'XBTUSD', '_': stamp}, timeout=2)
                result = data.get('result') or {}
                if not result:
                    raise RuntimeError('Kraken returned no ticker result')
                row = next(iter(result.values()))
                bid = float(row['b'][0])
                ask = float(row['a'][0])
                last = float(row['c'][0])
                mid = (bid + ask) / 2.0
                packet = (time.time(), mid, bid, ask, last)
                while self.kraken_queue.qsize() > 30:
                    try:
                        self.kraken_queue.get_nowait()
                    except Exception:
                        break
                try:
                    self.kraken_queue.put_nowait(packet)
                except queue.Full:
                    try:
                        self.kraken_queue.get_nowait()
                    except Exception:
                        pass
                    try:
                        self.kraken_queue.put_nowait(packet)
                    except Exception:
                        pass
                self.kraken_error = ''
            except Exception as exc:
                self.kraken_error = str(exc)
            time.sleep(0.25)

    def _drain_kraken_live(self):
        latest = None
        count = 0
        while True:
            try:
                latest = self.kraken_queue.get_nowait()
                count += 1
            except queue.Empty:
                break
        if latest is None:
            return False
        ts, mid, bid, ask, last = latest
        self.kraken_price = float(mid)
        self.kraken_bid = float(bid)
        self.kraken_ask = float(ask)
        self.kraken_last = float(last)
        self.kraken_tick_ts = ts
        self.kraken_tick_count += count
        self.current_spot = self.kraken_price
        self.live_prices.append((ts, self.kraken_price))
        cutoff = time.time() - 3600
        if len(self.live_prices) > 12000:
            self.live_prices = [x for x in self.live_prices if x[0] >= cutoff]
        return True

    def kalshi_get(self, path, params=None):
        return http_json(KALSHI_BASE + path, params)

    def coinbase_get(self, path, params=None):
        return http_json(COINBASE_BASE + path, params)

    def _sanitize_ticker(self, raw):
        """
        Accept an exact ticker, a full individual Kalshi market URL,
        or copied text containing the ticker.
        """
        raw = raw.strip()
        if not raw:
            return ''
        upper = raw.upper()
        match = re.search('(KXBTC15M-[A-Z0-9-]+)', upper)
        if match:
            ticker = match.group(1)
            ticker = re.split('[/?#&=%\\s]', ticker)[0]
            return ticker
        generic = re.search('\\b([A-Z][A-Z0-9]{2,}(?:-[A-Z0-9]+){2,})\\b', upper)
        if generic:
            return generic.group(1)
        if 'KALSHI.COM' in upper or upper.startswith('HTTP'):
            return ''
        return upper

    @staticmethod
    def _parse_iso_ts(value):
        if not value:
            return None
        try:
            return datetime.fromisoformat(str(value).replace('Z', '+00:00')).timestamp()
        except Exception:
            return None

    def _discover_current_kalshi_market(self):
        """
        Discover the currently-live KXBTC15M market from Kalshi's public API.

        Selection:
        1) Prefer an OPEN market whose open_time <= now < close_time.
        2) Otherwise choose the open market with the nearest future close.
        """
        data = self.kalshi_get('/markets', {'series_ticker': 'KXBTC15M', 'status': 'open', 'limit': 50})
        markets = data.get('markets') or []
        if not markets:
            raise RuntimeError('Kalshi returned no open KXBTC15M markets')
        now = time.time()
        active = []
        future = []
        for m in markets:
            open_ts = self._parse_iso_ts(m.get('open_time'))
            close_ts = self._parse_iso_ts(m.get('close_time') or m.get('expected_expiration_time') or m.get('expiration_time'))
            if close_ts is not None and close_ts > now:
                future.append((close_ts, m))
            if open_ts is not None and close_ts is not None and (open_ts <= now < close_ts):
                active.append((close_ts, m))
        if active:
            active.sort(key=lambda x: x[0])
            return active[0][1]
        if future:
            future.sort(key=lambda x: x[0])
            return future[0][1]
        return markets[0]

    def _apply_kalshi_market(self, market, source='AUTO'):
        if not market:
            return False
        ticker = str(market.get('ticker') or '').strip().upper()
        if ticker:
            self.kalshi_ticker = ticker
            self.auto_market_last_ticker = ticker
            self.ticker_var.set(ticker)
        self.kalshi_market = market
        target = self._extract_target(market)
        if target:
            self.target_price = float(target)
            self.auto_target_status_var.set(f"AUTO TARGET: {money(target)} • {source} • {market.get('strike_type', 'numeric')}")
        else:
            self.auto_target_status_var.set(f"AUTO TARGET: not found in {ticker or 'market'}")
        yes = self.kalshi_yes_price()
        if yes is not None:
            self.odds_feed_status_var.set(f'ODDS FEED: LIVE • YES {yes * 100:.1f}¢ • {ticker}')
        else:
            self.odds_feed_status_var.set(f'ODDS FEED: market loaded but no usable quote yet • {ticker}')
        self.auto_market_status_var.set(f"AUTO MARKET: {ticker or 'loaded'} • {source}")
        self.auto_market_error = ''
        self.auto_market_last_refresh = time.time()
        return True

    def _refresh_auto_kalshi_market(self):
        """
        Try manual current ticker first when provided; automatically recover by
        discovering the live KXBTC15M market if the manual market is stale/invalid.
        """
        manual_ticker = self._sanitize_ticker(self.ticker_var.get())
        if not self.auto_market_enabled_var.get():
            if not manual_ticker:
                raise RuntimeError('Manual ticker required when auto market is off')
            market = self._get_kalshi_market(manual_ticker)
            self._apply_kalshi_market(market, 'MANUAL')
            return market
        if manual_ticker:
            try:
                market = self._get_kalshi_market(manual_ticker)
                if market and str(market.get('status', '')).lower() in ('open', 'active', ''):
                    close_ts = self._parse_iso_ts(market.get('close_time') or market.get('expected_expiration_time') or market.get('expiration_time'))
                    if close_ts is None or close_ts > time.time():
                        self._apply_kalshi_market(market, 'MANUAL/AUTO-VALIDATED')
                        return market
            except Exception:
                pass
        market = self._discover_current_kalshi_market()
        self._apply_kalshi_market(market, 'AUTO-DISCOVERED')
        return market

    def find_current_kalshi_market_now(self):
        self.auto_market_status_var.set('AUTO MARKET: searching...')

        def worker():
            try:
                market = self._refresh_auto_kalshi_market()
                msg = f"Found {market.get('ticker', 'current market')}\nTarget: {(money(self.target_price) if self.target_price else '--')}\nYES: {self.kalshi_yes_price() * 100:.1f}¢" if self.kalshi_yes_price() is not None else f"Found {market.get('ticker', 'current market')}"
                self.root.after(0, lambda: self.status_var.set('Auto current BTC 15m market loaded'))
            except Exception as exc:
                self.auto_market_error = str(exc)
                self.root.after(0, lambda e=str(exc): self.auto_market_status_var.set(f'AUTO MARKET ERROR: {e}'))
        threading.Thread(target=worker, daemon=True).start()

    def _get_kalshi_market(self, ticker):
        data = self.kalshi_get('/markets/' + urllib.parse.quote(ticker))
        return data.get('market', data)

    def _extract_target(self, market):
        """
        Extract numeric KXBTC15M target from Kalshi's market object.

        Numeric strike fields are authoritative when present.
        """
        if not market:
            return None
        strike_type = str(market.get('strike_type') or '').lower()
        ordered = []
        if strike_type in ('greater', 'greater_than', 'above'):
            ordered = ['floor_strike', 'functional_strike', 'cap_strike']
        elif strike_type in ('less', 'less_than', 'below'):
            ordered = ['cap_strike', 'functional_strike', 'floor_strike']
        else:
            ordered = ['floor_strike', 'functional_strike', 'cap_strike']
        for key in ordered:
            raw = market.get(key)
            try:
                f = float(str(raw).replace('$', '').replace(',', '').strip())
                if f > 1000:
                    return f
            except Exception:
                pass
        text = ' '.join((str(market.get(k, '')) for k in ('title', 'subtitle', 'yes_sub_title', 'no_sub_title', 'rules_primary', 'rules_secondary')))
        candidates = re.findall('\\$?\\s*([0-9]{2,3}(?:,[0-9]{3})+(?:\\.[0-9]+)?)', text)
        for candidate in candidates:
            try:
                f = float(candidate.replace(',', ''))
                if f > 1000:
                    return f
            except Exception:
                pass
        return None

    def _fetch_btc_history(self):
        raw = self.coinbase_get(f'/products/{PRODUCT}/candles', {'granularity': 900})
        rows = []
        for x in raw:
            if not isinstance(x, list) or len(x) < 6:
                continue
            rows.append({'time': int(x[0]), 'low': float(x[1]), 'high': float(x[2]), 'open': float(x[3]), 'close': float(x[4]), 'volume': float(x[5])})
        rows.sort(key=lambda x: x['time'])
        self.btc_15m = rows

    def _fetch_tf_history(self, granularity):
        raw = self.coinbase_get(f'/products/{PRODUCT}/candles', {'granularity': granularity})
        rows = []
        for x in raw:
            if not isinstance(x, list) or len(x) < 6:
                continue
            rows.append({'time': int(x[0]), 'low': float(x[1]), 'high': float(x[2]), 'open': float(x[3]), 'close': float(x[4]), 'volume': float(x[5])})
        rows.sort(key=lambda x: x['time'])
        return rows

    def _fetch_orderbook(self):
        data = self.coinbase_get(f'/products/{PRODUCT}/book', {'level': 2})
        bids = data.get('bids', [])[:25]
        asks = data.get('asks', [])[:25]

        def depth(rows):
            total = 0.0
            for row in rows:
                try:
                    total += float(row[1])
                except Exception:
                    pass
            return total
        bid_depth = depth(bids)
        ask_depth = depth(asks)
        total = bid_depth + ask_depth
        imbalance = (bid_depth - ask_depth) / total if total > 0 else 0.0
        best_bid = float(bids[0][0]) if bids else None
        best_ask = float(asks[0][0]) if asks else None
        spread = best_ask - best_bid if best_bid and best_ask else None
        self.orderbook = {'imbalance': imbalance, 'bid_depth': bid_depth, 'ask_depth': ask_depth, 'best_bid': best_bid, 'best_ask': best_ask, 'spread': spread}

    def _fetch_1m_history(self):
        raw = self.coinbase_get(f'/products/{PRODUCT}/candles', {'granularity': 60})
        rows = []
        for x in raw:
            if not isinstance(x, list) or len(x) < 6:
                continue
            rows.append({'time': int(x[0]), 'low': float(x[1]), 'high': float(x[2]), 'open': float(x[3]), 'close': float(x[4]), 'volume': float(x[5])})
        rows.sort(key=lambda x: x['time'])
        self.btc_1m = rows

    def _fetch_spot(self):
        data = self.coinbase_get(f'/products/{PRODUCT}/ticker')
        price = float(data['price'])
        self.current_spot = price
        self.coinbase_bid = float(data.get('bid', price))
        self.coinbase_ask = float(data.get('ask', price))
        self.live_prices.append((time.time(), price))
        cutoff = time.time() - 3600
        if len(self.live_prices) > 6000:
            self.live_prices = [x for x in self.live_prices if x[0] >= cutoff]

    def start_manual(self):
        if self.running:
            return
        ticker = self._sanitize_ticker(self.ticker_var.get())
        if not ticker and (not self.auto_market_enabled_var.get()):
            messagebox.showinfo('Kalshi ticker', 'Enter an individual KXBTC15M market ticker, or enable AUTO CURRENT BTC 15M.')
            return
        if ticker:
            self.kalshi_ticker = ticker
        self.running = True
        self.last_error = ''
        self.status_var.set('Starting V55 • auto market/target + live BTC...')
        self.worker = threading.Thread(target=self._worker_loop, daemon=True)
        self.worker.start()
        self._start_kalshi_orderbook_ws()

    def stop(self):
        self.running = False
        self.status_var.set('Model stopped • BTC live feed remains locked on')

    def _worker_loop(self):
        try:
            self._fetch_btc_history()
            self._fetch_1m_history()
            self.btc_5m = self._fetch_tf_history(300)
            self.btc_1h = self._fetch_tf_history(3600)
            self._fetch_spot()
            try:
                self._fetch_orderbook()
            except Exception:
                pass
            try:
                self._refresh_auto_kalshi_market()
            except Exception as exc:
                self.auto_market_error = str(exc)
                self.auto_market_status_var.set(f'AUTO MARKET: retrying • {exc}')
            last_1m_refresh = time.time()
            last_5m_refresh = time.time()
            last_1h_refresh = time.time()
            last_15m_refresh = time.time()
            last_book_refresh = 0.0
            last_kalshi_book_refresh = 0.0
            last_kalshi_refresh = 0.0
            while self.running:
                now = time.time()
                if now - last_1m_refresh >= 5:
                    try:
                        self._fetch_1m_history()
                    except Exception:
                        pass
                    last_1m_refresh = now
                if now - last_5m_refresh >= 10:
                    try:
                        self.btc_5m = self._fetch_tf_history(300)
                    except Exception:
                        pass
                    last_5m_refresh = now
                if now - last_1h_refresh >= 60:
                    try:
                        self.btc_1h = self._fetch_tf_history(3600)
                    except Exception:
                        pass
                    last_1h_refresh = now
                if now - last_book_refresh >= 1:
                    try:
                        self._fetch_orderbook()
                    except Exception:
                        pass
                    last_book_refresh = now
                if now - last_kalshi_book_refresh >= 1.5:
                    try:
                        self._fetch_kalshi_orderbook()
                    except Exception:
                        pass
                    last_kalshi_book_refresh = now
                if now - last_15m_refresh >= 45:
                    try:
                        self._fetch_btc_history()
                    except Exception:
                        pass
                    last_15m_refresh = now
                if now - last_kalshi_refresh >= 2.0:
                    try:
                        self._refresh_auto_kalshi_market()
                    except Exception as exc:
                        self.auto_market_error = str(exc)
                        self.odds_feed_status_var.set(f'ODDS FEED: retrying • {exc}')
                    last_kalshi_refresh = now
                self.last_update = now
                self.last_error = ''
                time.sleep(POLL_SECONDS)
        except Exception as e:
            self.last_error = 'Context worker: ' + str(e)

    def _current_15m_bucket(self):
        """
        Build the live 15m candle using the most authoritative available OPEN.

        Priority:
        1) Coinbase native current 15m candle open.
        2) Exact 1m candle whose timestamp == 15m bucket start.
        3) Previous 1m close immediately before bucket.
        4) Last-resort live seed.

        High/low/close are then rebuilt from all 1m rows in this bucket plus
        the freshest live spot samples.
        """
        now = time.time()
        bucket = int(now // 900) * 900
        bucket_end = bucket + 900
        existing15 = next((x for x in reversed(self.btc_15m) if int(x['time']) == bucket), None)
        one_rows = sorted([x for x in self.btc_1m if bucket <= int(x['time']) < bucket_end], key=lambda x: x['time'])
        exact_first_minute = next((x for x in one_rows if int(x['time']) == bucket), None)
        prior_1m = None
        prior_rows = [x for x in self.btc_1m if int(x['time']) < bucket]
        if prior_rows:
            prior_1m = max(prior_rows, key=lambda x: x['time'])
        if existing15:
            true_open = float(existing15['open'])
            open_source = 'BOOKMAP 15M'
        elif exact_first_minute:
            true_open = float(exact_first_minute['open'])
            open_source = 'EXACT 1M'
        elif prior_1m:
            true_open = float(prior_1m['close'])
            open_source = 'PRIOR 1M CLOSE'
        else:
            samples = [p for ts, p in self.live_prices if ts >= bucket]
            true_open = samples[0] if samples else self.current_spot or 0.0
            open_source = 'LIVE FALLBACK'
        highs = [true_open]
        lows = [true_open]
        closes = []
        volume = 0.0
        if existing15:
            highs.append(float(existing15['high']))
            lows.append(float(existing15['low']))
            closes.append(float(existing15['close']))
            volume = max(volume, float(existing15.get('volume', 0.0)))
        if one_rows:
            highs.extend((float(x['high']) for x in one_rows))
            lows.extend((float(x['low']) for x in one_rows))
            closes.append(float(one_rows[-1]['close']))
            volume = max(volume, sum((float(x.get('volume', 0.0)) for x in one_rows)))
        samples = [p for ts, p in self.live_prices if ts >= bucket]
        if samples:
            highs.append(max(samples))
            lows.append(min(samples))
            closes.append(samples[-1])
        if self.current_spot is not None:
            highs.append(float(self.current_spot))
            lows.append(float(self.current_spot))
            closes.append(float(self.current_spot))
        live_close = closes[-1] if closes else true_open
        live_price, live_source = self.effective_live_price()
        if live_price is not None:
            highs.append(float(live_price))
            lows.append(float(live_price))
            live_close = float(live_price)
        return {'time': bucket, 'open': true_open, 'high': max(highs), 'low': min(lows), 'close': live_close, 'volume': volume, '_open_source': open_source}

    def _resample_history(self, rows, seconds):
        """Aggregate lower-timeframe OHLC rows into a larger interval."""
        if not rows:
            return []
        buckets = {}
        for row in rows:
            ts = int(row['time'])
            bucket = ts // seconds * seconds
            if bucket not in buckets:
                buckets[bucket] = {'time': bucket, 'open': float(row['open']), 'high': float(row['high']), 'low': float(row['low']), 'close': float(row['close']), 'volume': float(row.get('volume', 0.0))}
            else:
                out = buckets[bucket]
                out['high'] = max(out['high'], float(row['high']))
                out['low'] = min(out['low'], float(row['low']))
                out['close'] = float(row['close'])
                out['volume'] += float(row.get('volume', 0.0))
        return [buckets[key] for key in sorted(buckets)]

    @staticmethod
    def _web_safe_number(value, default=None):
        try:
            value = float(value)
            if math.isfinite(value):
                return value
        except Exception:
            pass
        return default

    def _web_var(self, name, default='--'):
        try:
            var = getattr(self, name, None)
            if var is None:
                return default
            value = var.get()
            return value if value not in (None, '') else default
        except Exception:
            return default

