def _v86_sign_headers(self, method, api_path, content_type=False):
    if not getattr(self, 'kalshi_credentials_verified', False):
        raise RuntimeError('Kalshi credentials are not verified')
    key_id = str(self.kalshi_key_id_var.get()).strip()
    pem = str(getattr(self, 'kalshi_private_key_text', '') or '')
    if not key_id or 'PRIVATE KEY' not in pem:
        raise RuntimeError('Kalshi API Key ID/private key missing')
    try:
        from cryptography.hazmat.primitives import hashes
        from cryptography.hazmat.primitives.asymmetric import padding
    except Exception:
        raise RuntimeError('cryptography package missing')
    private_key = self._load_private_key_from_text(pem)
    ts = str(int(time.time() * 1000))
    method = str(method).upper()
    message = f'{ts}{method}{api_path}'.encode('utf-8')
    signature = private_key.sign(message, padding.PSS(mgf=padding.MGF1(hashes.SHA256()), salt_length=padding.PSS.DIGEST_LENGTH), hashes.SHA256())
    headers = {'Accept': 'application/json', 'User-Agent': 'BookmapKingV87/1.0', 'KALSHI-ACCESS-KEY': key_id, 'KALSHI-ACCESS-TIMESTAMP': ts, 'KALSHI-ACCESS-SIGNATURE': base64.b64encode(signature).decode('utf-8')}
    if content_type:
        headers['Content-Type'] = 'application/json'
    return headers

