def _bk_effective_live_price(self):
    now = time.time()
    if self.current_spot is not None:
        age = max(0.0, now - float(getattr(self, 'bookmap_last_event_ts', now) or now))
        return (float(self.current_spot), f'BOOKMAP EXECUTED TRADE ({age:.2f}s)')
    with self.bookmap_lock:
        bid = max(self.bookmap_bids) if self.bookmap_bids else None
        ask = min(self.bookmap_asks) if self.bookmap_asks else None
    if bid is not None and ask is not None and (ask >= bid):
        return ((float(bid) + float(ask)) / 2.0, 'BOOKMAP BBO MID')
    return (None, 'WAITING FOR BOOKMAP')

