def _bk_update_ohlc(rows, seconds, ts, price, size, max_rows=1600):
    bucket = int(float(ts) // int(seconds)) * int(seconds)
    if rows and int(rows[-1].get('time', -1)) == bucket:
        row = rows[-1]
        row['high'] = max(float(row['high']), float(price))
        row['low'] = min(float(row['low']), float(price))
        row['close'] = float(price)
        row['volume'] = float(row.get('volume', 0.0)) + float(size)
    else:
        rows.append({'time': bucket, 'open': float(price), 'high': float(price), 'low': float(price), 'close': float(price), 'volume': float(size)})
        if len(rows) > max_rows:
            del rows[:-max_rows]

def _bk_refresh_v97_candles(app, ts, price, size):
    _bk_update_ohlc(app.btc_1m, 60, ts, price, size, 1800)
    _bk_update_ohlc(app.btc_5m, 300, ts, price, size, 1200)
    _bk_update_ohlc(app.btc_15m, 900, ts, price, size, 900)
    _bk_update_ohlc(app.btc_1h, 3600, ts, price, size, 700)

def _bk_refresh_orderbook(app):
    with app.bookmap_lock:
        bids = sorted(((float(px), float(row.get('size', 0.0))) for px, row in app.bookmap_bids.items()), reverse=True)[:40]
        asks = sorted(((float(px), float(row.get('size', 0.0))) for px, row in app.bookmap_asks.items()))[:40]
    bid_depth = sum((sz for _, sz in bids))
    ask_depth = sum((sz for _, sz in asks))
    total = bid_depth + ask_depth
    best_bid = bids[0][0] if bids else None
    best_ask = asks[0][0] if asks else None
    app.orderbook = {'imbalance': (bid_depth - ask_depth) / total if total > 0 else 0.0, 'bid_depth': bid_depth, 'ask_depth': ask_depth, 'best_bid': best_bid, 'best_ask': best_ask, 'spread': best_ask - best_bid if best_bid is not None and best_ask is not None else None, 'source': 'BOOKMAP DEPTH'}
    if best_bid is not None and best_ask is not None:
        app.bookmap_bbo = {'bid': best_bid, 'bid_size': bids[0][1], 'ask': best_ask, 'ask_size': asks[0][1], 'ts': time.time()}

