def _bk_child_apply_event(app, root, event):
    try:
        kind = str(event.get('type', '')).lower()
        app._ingest_bookmap_event(event)
        if kind == 'trade':
            ts = float(event.get('ts', time.time()) or time.time())
            price = float(event.get('price'))
            size = float(event.get('size', 0.0) or 0.0)
            app.current_spot = price
            app.quote_mesh_last = ts
            app.quote_mesh_price = price
            app.quote_mesh_source = 'BOOKMAP EXECUTIONS'
            app.live_stream_source = 'BOOKMAP EXECUTIONS'
            app.kraken_tick_ts = ts
            app.kraken_price = price
            app.live_prices.append((ts, price))
            if len(app.live_prices) > 12000:
                cutoff = ts - 6 * 3600
                kept = [x for x in app.live_prices if x[0] >= cutoff]
                app.live_prices = kept[-12000:]
            _bk_refresh_v97_candles(app, ts, price, size)
        elif kind == 'depth':
            pass
        elif kind == 'hello':

            def _hello_ui():
                try:
                    app.running = True
                    app.status_var.set('BOOKMAP NATIVE LIVE • exact V97 engine active')
                    app.auto_market_status_var.set('BTC DATA SOURCE: BOOKMAP NATIVE')
                    app.price_source_var.set('BOOKMAP EXECUTED TRADES')
                except Exception:
                    pass
            root.after(0, _hello_ui)
        elif kind == 'shutdown':
            root.after(0, root.destroy)
    except Exception:
        try:
            Path.home().joinpath('Downloads', 'BOOKMAP_KING_V7_2_UI_EVENT_ERROR.txt').write_text(traceback.format_exc(), encoding='utf-8')
        except Exception:
            pass

def _bk_child_receiver(app, root):
    sock = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
    sock.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
    sock.bind((BK_UI_HOST, BK_DATA_PORT))
    sock.settimeout(0.5)
    _bk_send_control({'type': 'ready', 'pid': os.getpid(), 'ts': time.time()})
    while True:
        try:
            raw, _ = sock.recvfrom(65535)
        except socket.timeout:
            try:
                if not root.winfo_exists():
                    break
            except Exception:
                break
            continue
        except Exception:
            break
        try:
            event = json.loads(raw.decode('utf-8', errors='ignore'))
        except Exception:
            continue
        if str(event.get('type', '')).lower() == 'shutdown':
            try:
                root.after(0, root.destroy)
            except Exception:
                pass
            break
        _bk_child_apply_event(app, root, event)
    try:
        sock.close()
    except Exception:
        pass

