def _v19_safe_float(v, default=0.0):
    try:
        return float(v)
    except Exception:
        return float(default)

def _v19_side_from_signed(v, dead=0.0):
    v = float(v)
    if v > dead:
        return 'UP'
    if v < -dead:
        return 'DOWN'
    return 'NEUTRAL'

def _v19_tf_bundle(self):
    """Read 1m/5m/15m together. No Kalshi odds are consulted here."""
    result = {}
    for label, sec, count in (('1M', 60, 10), ('5M', 300, 8), ('15M', 900, 6)):
        try:
            rows = self._live_tf_candles(sec, count)
            stat = self._tf_micro_stats(rows)
        except Exception:
            rows = []
            stat = {'direction': 'MIXED', 'strength': 0.0, 'reversal_up': 0.0, 'reversal_down': 0.0, 'slope': 0.0}
        bull = bear = 0
        expansion = 0.0
        compression = 0.0
        rejection_up = 0.0
        rejection_down = 0.0
        clean = []
        for c in rows or []:
            try:
                o = float(c.get('open', c.get('o')))
                h = float(c.get('high', c.get('h')))
                l = float(c.get('low', c.get('l')))
                cl = float(c.get('close', c.get('c')))
                clean.append((o, h, l, cl))
            except Exception:
                pass
        if clean:
            recent = clean[-4:]
            bull = sum((1 for o, h, l, c in recent if c > o))
            bear = sum((1 for o, h, l, c in recent if c < o))
            ranges = [max(1e-09, h - l) for o, h, l, c in clean[-6:]]
            if len(ranges) >= 3:
                baseline = sum(ranges[:-1]) / max(1, len(ranges) - 1)
                expansion = min(2.0, ranges[-1] / max(baseline, 1e-09))
                compression = min(2.0, baseline / max(ranges[-1], 1e-09)) if ranges[-1] else 0.0
            o, h, l, c = clean[-1]
            rng = max(1e-09, h - l)
            body = abs(c - o)
            lower = min(o, c) - l
            upper = h - max(o, c)
            rejection_up = min(1.0, lower / max(body, rng * 0.12, 1e-09) / 3.0)
            rejection_down = min(1.0, upper / max(body, rng * 0.12, 1e-09) / 3.0)
        result[label] = {'direction': str(stat.get('direction', 'MIXED')).upper(), 'strength': _v19_safe_float(stat.get('strength')), 'reversal_up': _v19_safe_float(stat.get('reversal_up')), 'reversal_down': _v19_safe_float(stat.get('reversal_down')), 'slope': _v19_safe_float(stat.get('slope')), 'bull_seq': bull, 'bear_seq': bear, 'expansion': expansion, 'compression': compression, 'rejection_up': rejection_up, 'rejection_down': rejection_down, 'bars': len(clean)}
    signed = 0.0
    denom = 0.0
    for label, w in (('1M', 1.15), ('5M', 1.35), ('15M', 1.0)):
        d = result[label]['direction']
        s = min(100.0, result[label]['strength']) / 100.0
        if d == 'UP':
            signed += w * (0.45 + 0.55 * s)
        elif d == 'DOWN':
            signed -= w * (0.45 + 0.55 * s)
        denom += w
    result['consensus_signed'] = signed / max(denom, 1e-09)
    result['consensus_side'] = _v19_side_from_signed(result['consensus_signed'], 0.12)
    return result

def _v19_native_bookmap_metrics(self, now=None):
    """Native Bookmap order-flow facts derived from trades/depth/BBO, not Kalshi."""
    now = float(now or time.time())
    try:
        with self.bookmap_lock:
            trades = [dict(t) for t in self.bookmap_trades
                      if now - _v19_safe_float(t.get('received', t.get('ts', 0.0))) <= 65.0]
            bbo = dict(self.bookmap_bbo)
            _bid = _v19_safe_float(bbo.get('bid'))
            _ask = _v19_safe_float(bbo.get('ask'))
            _mid = (_bid + _ask) * 0.5 if _bid > 0 and _ask > 0 else _v19_safe_float(self.current_spot)
            if _mid > 0:
                _copy_window = max(80.0, _mid * 0.0015)
                bids = {float(p): dict(v) for p, v in self.bookmap_bids.items()
                        if 0.0 <= _mid - float(p) <= _copy_window}
                asks = {float(p): dict(v) for p, v in self.bookmap_asks.items()
                        if 0.0 <= float(p) - _mid <= _copy_window}
            else:
                bids = {float(p): dict(v) for p, v in self.bookmap_bids.items()}
                asks = {float(p): dict(v) for p, v in self.bookmap_asks.items()}
    except Exception:
        trades = []
        bids = {}
        asks = {}
        bbo = {}

    def rts(t):
        return _v19_safe_float(t.get('received', t.get('ts', 0.0)))

    def flow(window):
        rows = [t for t in trades if now - rts(t) <= window]
        buy = sum((_v19_safe_float(t.get('size')) for t in rows if str(t.get('aggressor', '')).lower() == 'buy'))
        sell = sum((_v19_safe_float(t.get('size')) for t in rows if str(t.get('aggressor', '')).lower() == 'sell'))
        total = buy + sell
        delta = buy - sell
        imb = delta / max(total, 1e-09)
        prices = [_v19_safe_float(t.get('price')) for t in rows if _v19_safe_float(t.get('price')) > 0]
        move = 0.0
        if len(prices) >= 2:
            mid = max(1.0, (prices[-1] + prices[0]) * 0.5)
            move = (prices[-1] - prices[0]) / mid * 10000.0
        return {'buy': buy, 'sell': sell, 'total': total, 'delta': delta, 'imbalance': imb, 'move_bp': move, 'n': len(rows)}
    f2 = flow(2.0)
    f5 = flow(5.0)
    f15 = flow(15.0)
    f60 = flow(60.0)
    bid = _v19_safe_float(bbo.get('bid'))
    ask = _v19_safe_float(bbo.get('ask'))
    mid = (bid + ask) * 0.5 if bid > 0 and ask > 0 else 0.0
    spread_bp = (ask - bid) / mid * 10000.0 if mid > 0 and ask >= bid else 0.0
    depth_window = max(40.0, mid * 0.0009) if mid else 60.0
    near_bids = [(p, _v19_safe_float(v.get('size'))) for p, v in bids.items() if mid and 0 <= mid - p <= depth_window]
    near_asks = [(p, _v19_safe_float(v.get('size'))) for p, v in asks.items() if mid and 0 <= p - mid <= depth_window]
    bid_depth = sum((s for p, s in near_bids))
    ask_depth = sum((s for p, s in near_asks))
    depth_imb = (bid_depth - ask_depth) / max(bid_depth + ask_depth, 1e-09)
    max_bid = max([s for p, s in near_bids] or [0.0])
    max_ask = max([s for p, s in near_asks] or [0.0])
    bid_conc = max_bid / max(bid_depth, 1e-09)
    ask_conc = max_ask / max(ask_depth, 1e-09)
    prev = getattr(self, '_v19_native_prev', None)
    quote_delta = 0.0
    quote_side = 'NEUTRAL'
    if isinstance(prev, dict) and now - _v19_safe_float(prev.get('ts')) <= 3.0:
        db = bid_depth - _v19_safe_float(prev.get('bid_depth'))
        da = ask_depth - _v19_safe_float(prev.get('ask_depth'))
        quote_delta = (db - da) / max(abs(db) + abs(da) + 0.15 * (bid_depth + ask_depth), 1e-09)
        quote_side = _v19_side_from_signed(quote_delta, 0.07)
    self._v19_native_prev = {'ts': now, 'bid_depth': bid_depth, 'ask_depth': ask_depth}
    absorb_side = 'NEUTRAL'
    absorb_strength = 0.0
    if f5['total'] > 0:
        aggression = abs(f5['imbalance'])
        stillness = max(0.0, 1.0 - min(1.0, abs(f5['move_bp']) / 2.0))
        absorb_strength = min(1.0, aggression * stillness * 1.4)
        if absorb_strength >= 0.25:
            absorb_side = 'DOWN' if f5['imbalance'] > 0 else 'UP'
    accel = f2['move_bp'] - f5['move_bp'] * 0.4
    sweep_signed = 0.5 * f2['imbalance'] + 0.3 * f5['imbalance'] + max(-1.0, min(1.0, f2['move_bp'] / 3.0)) * 0.2
    sweep_side = _v19_side_from_signed(sweep_signed, 0.22)
    sweep_strength = min(1.0, abs(sweep_signed))
    large_side = 'NEUTRAL'
    large_strength = 0.0
    concentration_delta = bid_conc - ask_conc
    if abs(concentration_delta) >= 0.08:
        large_side = 'UP' if concentration_delta > 0 else 'DOWN'
        large_strength = min(1.0, abs(concentration_delta) * 2.5)
    return {'ready': bool(trades or bids or asks), 'flow2': f2, 'flow5': f5, 'flow15': f15, 'flow60': f60, 'cvd_short': f15['delta'], 'cvd_long': f60['delta'], 'depth_imbalance': depth_imb, 'bid_depth': bid_depth, 'ask_depth': ask_depth, 'quote_delta': quote_delta, 'quote_side': quote_side, 'spread_bp': spread_bp, 'absorption_side': absorb_side, 'absorption_strength': absorb_strength, 'sweep_side': sweep_side, 'sweep_strength': sweep_strength, 'accel_bp': accel, 'large_side': large_side, 'large_strength': large_strength, 'bid_concentration': bid_conc, 'ask_concentration': ask_conc}

def _v19_regime(self, tf, native, wave):
    one = tf.get('1M', {})
    five = tf.get('5M', {})
    fifteen = tf.get('15M', {})
    dirs = [one.get('direction'), five.get('direction'), fifteen.get('direction')]
    aligned = max(dirs.count('UP'), dirs.count('DOWN'))
    flow = abs(_v19_safe_float(native.get('flow5', {}).get('imbalance')))
    move = abs(_v19_safe_float(native.get('flow5', {}).get('move_bp')))
    spread = _v19_safe_float(native.get('spread_bp'))
    wave_strength = abs(_v19_safe_float(wave.get('signed_score')))
    if spread > 3.0:
        return 'THIN/NOISY'
    if aligned >= 2 and (flow >= 0.18 or move >= 1.0 or wave_strength >= 42):
        return 'TRENDING'
    if one.get('direction') != five.get('direction') and max(one.get('strength', 0), five.get('strength', 0)) >= 55:
        return 'REVERSAL/PULLBACK'
    if flow < 0.1 and move < 0.6 and (wave_strength < 25):
        return 'RANGE'
    if flow >= 0.18 and move < 0.8:
        return 'ABSORPTION/BUILD'
    return 'TRANSITION'

def _v19_mm3_read(self, warm=None, sig=None, candles=None, now=None):
    """Future-looking independent trader. Direction logic never reads Kalshi odds."""
    now = float(now or time.time())
    sig = sig or getattr(self, 'last_signal', None) or {}
    warm = dict(warm or {})
    if not warm:
        try:
            warm = self._bookmap_fast_warmup_read(now=now, force=True) or {}
        except Exception:
            warm = {}
    wave = dict(warm.get('wave') or getattr(self, 'bookmap_wave_last', {}) or {})
    whale = dict(warm.get('whale') or {})
    if not whale:
        try:
            whale = dict(self._bookmap_whale_read(now=now) or {})
        except Exception:
            whale = {}
    tf = _v19_tf_bundle(self)
    native = _v19_native_bookmap_metrics(self, now=now)
    regime = _v19_regime(self, tf, native, wave)
    F = {}
    f2 = native.get('flow2', {})
    f5 = native.get('flow5', {})
    f15 = native.get('flow15', {})
    F['EXEC FLOW'] = max(-1.0, min(1.0, 0.48 * _v19_safe_float(f2.get('imbalance')) + 0.34 * _v19_safe_float(f5.get('imbalance')) + 0.18 * _v19_safe_float(f15.get('imbalance'))))
    move2 = _v19_safe_float(f2.get('move_bp'))
    move5 = _v19_safe_float(f5.get('move_bp'))
    accel = _v19_safe_float(native.get('accel_bp'))
    F['PRICE IMPULSE'] = max(-1.0, min(1.0, 0.48 * move2 / 2.2 + 0.32 * move5 / 3.5 + 0.2 * accel / 2.2))
    F['DEPTH'] = max(-1.0, min(1.0, _v19_safe_float(native.get('depth_imbalance'))))
    F['QUOTE DELTA'] = max(-1.0, min(1.0, _v19_safe_float(native.get('quote_delta')) * 1.4))
    F['CVD'] = max(-1.0, min(1.0, 0.62 * _v19_safe_float(f15.get('imbalance')) + 0.38 * _v19_safe_float(native.get('flow60', {}).get('imbalance'))))
    F['MTF CANDLES'] = max(-1.0, min(1.0, _v19_safe_float(tf.get('consensus_signed'))))
    F['WAVE'] = max(-1.0, min(1.0, _v19_safe_float(wave.get('signed_score')) / 75.0))
    whale_dir = str(whale.get('direction', 'NEUTRAL')).upper()
    whale_mag = max(_v19_safe_float(whale.get('likelihood')) / 100.0, abs(_v19_safe_float(whale.get('signed_score'))) / 85.0)
    F['WHALE'] = (1.0 if whale_dir == 'UP' else -1.0 if whale_dir == 'DOWN' else 0.0) * min(1.0, whale_mag)
    absorb = str(native.get('absorption_side', 'NEUTRAL'))
    F['ABSORPTION'] = (1 if absorb == 'UP' else -1 if absorb == 'DOWN' else 0) * _v19_safe_float(native.get('absorption_strength'))
    sweep = str(native.get('sweep_side', 'NEUTRAL'))
    F['SWEEP'] = (1 if sweep == 'UP' else -1 if sweep == 'DOWN' else 0) * _v19_safe_float(native.get('sweep_strength'))
    large = str(native.get('large_side', 'NEUTRAL'))
    F['LARGE LIQ'] = (1 if large == 'UP' else -1 if large == 'DOWN' else 0) * _v19_safe_float(native.get('large_strength'))
    patt = 0.0
    for label, w in (('1M', 0.46), ('5M', 0.36), ('15M', 0.18)):
        t = tf.get(label, {})
        seq = (min(3, int(t.get('bull_seq', 0))) - min(3, int(t.get('bear_seq', 0)))) / 3.0
        rej = _v19_safe_float(t.get('rejection_up')) - _v19_safe_float(t.get('rejection_down'))
        patt += w * (0.55 * seq + 0.45 * rej)
    F['CANDLE BEHAVIOR'] = max(-1.0, min(1.0, patt))
    weights = {'EXEC FLOW': 1.3, 'PRICE IMPULSE': 1.25, 'DEPTH': 0.8, 'QUOTE DELTA': 0.75, 'CVD': 0.85, 'MTF CANDLES': 1.1, 'WAVE': 1.0, 'WHALE': 0.85, 'ABSORPTION': 0.75, 'SWEEP': 0.85, 'LARGE LIQ': 0.55, 'CANDLE BEHAVIOR': 0.8}
    signed = sum((F[k] * weights[k] for k in F)) / max(sum(weights.values()), 1e-09)
    side = 'UP' if signed >= 0 else 'DOWN'
    sign = 1 if side == 'UP' else -1
    aligned = [k for k, v in F.items() if v * sign >= 0.22]
    opposing = [k for k, v in F.items() if v * sign <= -0.22]
    hard = [k for k, v in F.items() if v * sign >= 0.48]
    agreement = sum((max(0.0, v * sign) * weights[k] for k, v in F.items())) / max(sum((abs(v) * weights[k] for k, v in F.items())), 1e-09) * 100.0
    score = 50.0 + 58.0 * abs(signed) + min(8.0, len(hard) * 1.4) + min(5.0, max(0.0, agreement - 55.0) * 0.08)
    if regime in ('RANGE', 'THIN/NOISY'):
        score -= 7.0
    if len(opposing) >= 3:
        score -= 6.0
    score = max(0.0, min(99.0, score))
    hist = getattr(self, '_v19_mm_history', None)
    if not isinstance(hist, deque):
        hist = deque(maxlen=80)
        self._v19_mm_history = hist
    hist.append({'ts': now, 'signed': signed, 'side': side, 'score': score, 'risk': _v19_safe_float(getattr(self, 'trend_reversal_risk_value', 0.0)), 'surv': _v19_safe_float(getattr(self, 'flip_survival_value', 96.0))})
    recent = [x for x in hist if now - x['ts'] <= 3.0]
    trajectory = 0.0
    if len(recent) >= 2:
        trajectory = (recent[-1]['signed'] - recent[0]['signed']) / max(recent[-1]['ts'] - recent[0]['ts'], 0.25)
    future_signed = max(-1.0, min(1.0, signed + max(-0.22, min(0.22, trajectory * 0.4))))
    future_side = 'UP' if future_signed >= 0 else 'DOWN'
    lock = self._sticky_survival_lock_snapshot() or getattr(self, 'opening_lock_snapshot', None) or self._selected_checkpoint_snapshot() or {}
    lock_side = str(lock.get('lock_side', 'WAIT')).upper()
    survival = _v19_safe_float(getattr(self, 'flip_survival_value', 96.0), 96.0)
    risk = _v19_safe_float(getattr(self, 'trend_reversal_risk_value', 0.0), 0.0)
    trend = sig.get('trend_reversal') or {}
    bk_status = str(trend.get('status', '')).upper()
    bk_flip = str(trend.get('flip_to', '')).upper()
    defended = lock_side if lock_side in ('UP', 'DOWN') else None
    try:
        if self.paper_active_trade and str(self.paper_active_trade.get('direction', '')).upper() in ('UP', 'DOWN'):
            defended = str(self.paper_active_trade.get('direction')).upper()
    except Exception:
        pass
    flip_to = ('DOWN' if defended == 'UP' else 'UP') if defended in ('UP', 'DOWN') else None
    flip_prob = 0.0
    flip_families = []
    if flip_to:
        fs = 1 if flip_to == 'UP' else -1
        for k, v in F.items():
            if v * fs >= 0.22:
                flip_families.append(k)
        opp_strength = sum((max(0.0, v * fs) * weights[k] for k, v in F.items())) / max(sum(weights.values()), 1e-09)
        flip_prob = 18.0 + opp_strength * 68.0 + min(12.0, len(flip_families) * 1.6)
        if trajectory * fs > 0.035:
            flip_prob += 8.0
        if survival < 70:
            flip_prob += min(10.0, (70 - survival) * 0.25)
        if risk > 35:
            flip_prob += min(10.0, (risk - 35) * 0.2)
        flip_prob = max(0.0, min(99.0, flip_prob))
    fs = getattr(self, '_v19_flip_state', None)
    if not isinstance(fs, dict):
        fs = {}
    old_surv = _v19_safe_float(fs.get('last_survival'), survival)
    survival_slope = survival - old_surv
    old_flip = _v19_safe_float(fs.get('last_flip_prob'), flip_prob)
    flip_slope = flip_prob - old_flip
    recovery_peak = _v19_safe_float(fs.get('recovery_peak'), survival)
    failed = int(fs.get('failed_recoveries', 0) or 0)
    if survival > recovery_peak + 4.0:
        recovery_peak = survival
    if recovery_peak - survival >= 8.0 and flip_prob >= _V19_FLIP_FORMING:
        failed = min(5, failed + 1)
        recovery_peak = survival
    if flip_prob < 45 and survival >= 78:
        failed = max(0, failed - 1)
        recovery_peak = survival
    fs.update({'last_survival': survival, 'last_flip_prob': flip_prob, 'recovery_peak': recovery_peak, 'failed_recoveries': failed, 'ts': now})
    self._v19_flip_state = fs
    if not flip_to:
        flip_phase = 'NONE'
    elif flip_prob >= _V19_FLIP_CONFIRMED and len(flip_families) >= 4:
        flip_phase = 'CONFIRMED'
    elif flip_prob >= _V19_FLIP_LIKELY and len(flip_families) >= 3:
        flip_phase = 'LIKELY'
    elif flip_prob >= _V19_FLIP_FORMING and len(flip_families) >= 2:
        flip_phase = 'FORMING'
    elif flip_prob >= 45:
        flip_phase = 'WATCH'
    else:
        flip_phase = 'NONE'
    st = getattr(self, '_v19_mm_state', None)
    if not isinstance(st, dict):
        st = {}
    strong = score >= 82 and len(aligned) >= 3 and (len(opposing) <= 2)
    cand = str(st.get('candidate', 'WAIT'))
    since = _v19_safe_float(st.get('since'))
    if strong:
        if cand != side:
            cand = side
            since = now
    else:
        cand = 'WAIT'
        since = 0.0
    age = max(0.0, now - since) if since else 0.0
    st.update({'candidate': cand, 'since': since, 'last_side': side, 'last_score': score})
    self._v19_mm_state = st
    qualified = bool(score >= _V19_MIN_SCORE and len(aligned) >= _V19_MIN_FAMILIES and (age >= _V19_NORMAL_PERSIST) and (regime not in ('RANGE', 'THIN/NOISY')))
    straight = bool(score >= _V19_STRAIGHT_SCORE and len(aligned) >= _V19_STRAIGHT_FAMILIES and (len(opposing) == 0) and (age >= _V19_STRAIGHT_PERSIST) and ('EXEC FLOW' in aligned) and ('PRICE IMPULSE' in aligned) and (regime == 'TRENDING'))
    if lock_side in ('UP', 'DOWN') and side == lock_side:
        team_state = 'CONVERGED'
    elif lock_side in ('UP', 'DOWN') and flip_to == side and (flip_phase in ('FORMING', 'LIKELY', 'CONFIRMED')):
        team_state = 'MM LEADS FLIP'
    elif lock_side in ('UP', 'DOWN'):
        team_state = 'CONFLICT/WAIT'
    else:
        team_state = 'BK BUILDING / MM SCOUTING'
    return {'side': side, 'future_side': future_side, 'score': score, 'signed': signed, 'future_signed': future_signed, 'trajectory': trajectory, 'agreement': agreement, 'families': tuple(aligned), 'opposing_families': tuple(opposing), 'family_count': len(aligned), 'opposing_count': len(opposing), 'hard_families': tuple(hard), 'qualified': qualified, 'straight_shot': straight, 'age': age, 'regime': regime, 'lock_side': lock_side, 'bk_survival': survival, 'bk_risk': risk, 'bk_status': bk_status, 'bk_flip': bk_flip, 'flip_to': flip_to, 'flip_probability': flip_prob, 'flip_phase': flip_phase, 'flip_families': tuple(flip_families), 'flip_slope': flip_slope, 'survival_slope': survival_slope, 'failed_recoveries': failed, 'team_state': team_state, 'tf': tf, 'native': native, 'raw_families': F, 'reason': f"MM3 {side} {score:.0f}/100 • FUTURE {future_side} • {regime} • {len(aligned)} families • flip {flip_phase} {flip_prob:.0f}% → {flip_to or '--'} • TEAM {team_state}"}

def _v19_dynamic_entry_ceiling(mm):
    """Execution/value only. Direction has already been decided without Kalshi odds."""
    s = _v19_safe_float(mm.get('score'))
    fam = int(mm.get('family_count', 0) or 0)
    if s >= 97 and fam >= 6:
        return 0.75
    if s >= 95 and fam >= 5:
        return 0.72
    if s >= 93 and fam >= 5:
        return 0.69
    return 0.66

def _v19_auto_paper_unified_tick(self, warm=None, sig=None, candles=None, now=None, mode='LIVE'):
    if not self.auto_paper_enabled_var.get():
        self.auto_paper_live_score = None
        self._set_var_if_changed(self.auto_paper_score_var, 'AUTO PAPER: OFF')
        self._set_var_if_changed(self.auto_paper_reason_var, 'Enable AUTO PAPER to use V8.7 + TEAM MM3.')
        return False
    if self.paper_active_trade is not None:
        self._set_var_if_changed(self.auto_paper_score_var, 'AUTO PAPER: active trade • THESIS GUARDIAN ON')
        return False
    now = float(now or time.time())
    if now - _v19_safe_float(getattr(self, 'auto_paper_last_eval', 0.0)) < 0.12:
        return False
    self.auto_paper_last_eval = now
    bucket = int(now // 900) * 900
    if self.auto_paper_last_bucket == bucket:
        self._set_var_if_changed(self.auto_paper_score_var, 'AUTO PAPER: already traded this 15m market')
        return False
    mm = _v19_mm3_read(self, warm=warm, sig=sig, candles=candles, now=now)
    self._v19_last_mm = mm
    lock = self._sticky_survival_lock_snapshot() or getattr(self, 'opening_lock_snapshot', None) or self._selected_checkpoint_snapshot() or {}
    lock_side = str(lock.get('lock_side', 'WAIT')).upper()
    survival = _v19_safe_float(getattr(self, 'flip_survival_value', 96.0), 96.0)
    risk = _v19_safe_float(getattr(self, 'trend_reversal_risk_value', 0.0), 0.0)
    if lock_side not in ('UP', 'DOWN'):
        if not mm.get('straight_shot'):
            self._set_var_if_changed(self.auto_paper_score_var, f"SCOUTING • {mm['reason']}")
            self._set_var_if_changed(self.auto_paper_reason_var, 'No frozen BK lock yet; only a pristine future-looking straight shot may fire.')
            return False
        side = mm['side']
        reason = 'TEAM MM3 STRAIGHT SHOT BEFORE OPEN LOCK'
    else:
        side = lock_side
        if mm.get('flip_to') and mm.get('flip_to') != side and (mm.get('flip_phase') in ('FORMING', 'LIKELY', 'CONFIRMED')):
            self._set_var_if_changed(self.auto_paper_score_var, f"NO ENTRY • {side} lock • MM3 flip {mm['flip_phase']} {mm['flip_probability']:.0f}%")
            return False
        if survival < 60 or risk > 50:
            self._set_var_if_changed(self.auto_paper_score_var, f'NO ENTRY • BK {side} under attack • surv {survival:.0f} risk {risk:.0f}')
            return False
        if not (mm.get('qualified') and mm.get('side') == side and (mm.get('future_side') == side)):
            self._set_var_if_changed(self.auto_paper_score_var, f"WAIT • BK {side} • {mm['reason']}")
            return False
        reason = 'V8.7 BK + FUTURE MM3 CONVERGENCE'
    px, _yes, _src, _age = self._kalshi_paper_price(side, 'ENTER', max_age=3.0)
    if px is None:
        return False
    ceiling = min(_V19_MAX_ENTRY, _v19_dynamic_entry_ceiling(mm))
    if float(px) > ceiling:
        self._set_var_if_changed(self.auto_paper_reason_var, f'RIGHT THESIS / BAD PRICE • {side} {float(px) * 100:.1f}¢ > value cap {ceiling * 100:.0f}¢')
        return False
    mm2 = _v19_mm3_read(self, warm=None, sig=sig, candles=candles, now=time.time())
    self._v19_last_mm = mm2
    if mm2.get('side') != side or mm2.get('future_side') != side or (not (mm2.get('qualified') or (lock_side not in ('UP', 'DOWN') and mm2.get('straight_shot')))):
        self._set_var_if_changed(self.auto_paper_reason_var, 'Final future read weakened/changed • entry cancelled.')
        return False
    if mm2.get('flip_to') and mm2.get('flip_to') != side and (mm2.get('flip_phase') in ('FORMING', 'LIKELY', 'CONFIRMED')):
        return False
    px2, _y2, _s2, _a2 = self._kalshi_paper_price(side, 'ENTER', max_age=3.0)
    if px2 is None or float(px2) > min(_V19_MAX_ENTRY, _v19_dynamic_entry_ceiling(mm2)):
        return False
    opened = self._paper_open(side, entry_source='AUTO', auto_score=_v19_safe_float(mm2.get('score')), auto_reason=f"{reason} • {mm2.get('regime')} • {mm2.get('family_count')} causal families • no-odds direction")
    if opened:
        self.auto_paper_last_bucket = bucket
        self._set_var_if_changed(self.auto_paper_score_var, f"ENTERED {side} • MM3 {_v19_safe_float(mm2.get('score')):.0f}/100 • {mm2.get('family_count')} families")
        self._set_var_if_changed(self.auto_paper_reason_var, reason)
    return bool(opened)

def _v19_paper_auto_exit_tick(self):
    """Thesis Guardian: tolerate recoverable adversity; kill genuinely failed theses."""
    if not self.paper_active_trade:
        return
    trade = self.paper_active_trade
    direction = str(trade.get('direction', '')).upper()
    contract_now, yes_px, _src, _age = self._kalshi_paper_price(direction, 'EXIT', max_age=3.0)
    if contract_now is None or yes_px is None:
        return
    entry = _v19_safe_float(trade.get('entry_contract'), contract_now)
    delta = (float(contract_now) - entry) * 100.0
    sig = self.last_signal or {}
    trend = sig.get('trend_reversal') or {}
    status = str(trend.get('status', '')).upper()
    flip = str(trend.get('flip_to', '')).upper()
    opposite = 'DOWN' if direction == 'UP' else 'UP'
    if status == 'BREAKOUT CONFIRMED' and flip == opposite:
        self._paper_finalize_active(exit_yes=yes_px, reason=f'V8.7 STRUCTURAL BREAK • {opposite} confirmed')
        return
    mm = _v19_mm3_read(self, sig=sig, now=time.time())
    self._v19_last_mm = mm
    fp = _v19_safe_float(mm.get('flip_probability'))
    phase = str(mm.get('flip_phase', 'NONE'))
    failed = int(mm.get('failed_recoveries', 0) or 0)
    surv = _v19_safe_float(mm.get('bk_survival'), 96)
    risk = _v19_safe_float(mm.get('bk_risk'))
    ss = _v19_safe_float(mm.get('survival_slope'))
    fs = _v19_safe_float(mm.get('flip_slope'))
    fam = len(mm.get('flip_families') or ())
    peak = _v19_safe_float(trade.get('mfe_cents'))
    if float(contract_now) >= 0.85 and mm.get('flip_to') == opposite and (phase in ('FORMING', 'LIKELY', 'CONFIRMED')) and (fam >= 2):
        self._paper_finalize_active(exit_yes=yes_px, reason=f'MM3 BANK PROFIT • {contract_now * 100:.1f}¢ • {opposite} flip {phase} {fp:.0f}%')
        return
    if float(contract_now) >= 0.8 and mm.get('flip_to') == opposite and (phase in ('LIKELY', 'CONFIRMED')) and (fam >= 3):
        self._paper_finalize_active(exit_yes=yes_px, reason=f'MM3 PROFIT GUARD • {opposite} {phase} {fp:.0f}%')
        return
    if peak >= 25 and delta >= 6 and (mm.get('flip_to') == opposite) and (phase in ('LIKELY', 'CONFIRMED')):
        self._paper_finalize_active(exit_yes=yes_px, reason=f'MM3 GIVEBACK GUARD • MFE +{peak:.1f}¢ → +{delta:.1f}¢')
        return
    dead = mm.get('flip_to') == opposite and fam >= 4 and (phase == 'CONFIRMED' or (phase == 'LIKELY' and fp >= 84 and (failed >= 2 or (surv <= 48 and risk >= 58))) or (failed >= 3 and fp >= 74 and (surv <= 55)))
    if dead:
        self._paper_finalize_active(exit_yes=yes_px, reason=f'THESIS DEAD • {opposite} flip {phase} {fp:.0f}% • {fam} families • failed recoveries {failed}')
        return
    if mm.get('flip_to') == opposite and fam >= 3 and (fp >= 80) and (fs > 5) and (ss < -4) and (surv <= 58 or risk >= 58):
        self._paper_finalize_active(exit_yes=yes_px, reason=f'THESIS DETERIORATING FAST • flip +{fs:.0f} • survival {ss:.0f}')
        return

