        self._set_var_if_changed(self.team_mm_evidence_var, f"EVIDENCE: {fam} causal families [{', '.join(mm.get('families') or ()) or 'none'}] • opposing {int(mm.get('opposing_count', 0) or 0)} • 1M {tf.get('1M', {}).get('direction', '--')} / 5M {tf.get('5M', {}).get('direction', '--')} / 15M {tf.get('15M', {}).get('direction', '--')} • CVD15 {native.get('cvd_short', 0):+.1f} • depth {native.get('depth_imbalance', 0) * 100:+.0f}% • quoteΔ {native.get('quote_delta', 0) * 100:+.0f}%")
