def _v20_breakout_decision(raw_score, families, displacement, persistence, immediate=False):
    raw_score = max(0.0, min(100.0, float(raw_score)))
    families = max(0, int(families))
    displacement = float(displacement)
    persistence = max(0.0, float(persistence))
    if immediate or (raw_score >= 88 and families >= 5 and (displacement >= 0.03)):
        return ('CONFIRMED', 96.0)
    if raw_score >= 70 and families >= 3 and (displacement >= 0.05) and (persistence >= 0.22):
        return ('CONFIRMED', 92.0)
    if raw_score >= 78 and families >= 4 and (persistence >= 0.32):
        return ('CONFIRMED', 90.0)
    if raw_score >= 64 and families >= 3:
        return ('LIKELY', 76.0)
    if raw_score >= 50 and families >= 2:
        return ('FORMING', 60.0)
    if raw_score >= 34 and families >= 2:
        return ('WATCH', 42.0)
    return ('NONE', 0.0)

def _v20_survival_decision(previous, stage, score, structural=False, trend_confirmed=False):
    previous = max(5.0, min(100.0, float(previous)))
    score = max(0.0, min(100.0, float(score)))
    stage = str(stage or 'NONE').upper()
    if stage == 'CONFIRMED' or trend_confirmed:
        target = max(5.0, 18.0 - (max(score, 70.0) - 70.0) * 0.32)
        alpha = 0.9
        hard_cap = 14.0
    elif stage == 'LIKELY':
        target = max(24.0, 58.0 - (score - 60.0) * 1.0)
        alpha = 0.68
        hard_cap = 38.0
    elif stage == 'FORMING':
        target = max(46.0, 78.0 - (score - 45.0) * 0.75)
        alpha = 0.42
        hard_cap = 66.0
    elif stage == 'WATCH':
        target = max(68.0, 90.0 - (score - 30.0) * 0.45)
        alpha = 0.22
        hard_cap = 82.0
    elif structural:
        target = 64.0
        alpha = 0.3
        hard_cap = 72.0
    else:
        target = 96.0
        alpha = 0.14
        hard_cap = 100.0
    value = previous + (target - previous) * alpha
    if target < previous:
        value = min(value, hard_cap)
    return (max(5.0, min(100.0, value)), max(5.0, min(100.0, target)))

def _v20_lock_breakout_read(self, sig, candles, defense, consensus=None):
    lock = self._sticky_survival_lock_snapshot()
    if not lock:
        return {'ready': False, 'lock_side': 'WAIT', 'breakout_side': 'WAIT', 'score': 0.0, 'categories': 0, 'risk_floor': 0.0, 'confirmed': False, 'stage': 'NONE', 'detail': 'No active frozen checkpoint.'}
    lock_side = str(lock.get('lock_side', 'WAIT')).upper()
    if lock_side not in ('UP', 'DOWN'):
        return {'ready': False, 'lock_side': lock_side, 'breakout_side': 'WAIT', 'score': 0.0, 'categories': 0, 'risk_floor': 0.0, 'confirmed': False, 'stage': 'NONE', 'detail': 'Frozen checkpoint has no directional side.'}
    side = 'DOWN' if lock_side == 'UP' else 'UP'
    sign = 1.0 if side == 'UP' else -1.0
    consensus = consensus or self._multi_timeframe_trend_consensus()
    lock_health = sig.get('lock_health') or {}
    delta_atr = float(lock_health.get('delta_atr', 0.0) or 0.0)
    displacement = -delta_atr if lock_side == 'UP' else delta_atr
    current = sign * float(sig.get('current_net', 0.0) or 0.0)
    fast = sign * float(sig.get('fast_net', 0.0) or 0.0)
    pro = sign * float(sig.get('pro_net', 0.0) or 0.0)
    try:
        micro = self._micro_timeframe_read() or {}
    except Exception:
        micro = {}
    one = str((micro.get('one') or {}).get('direction', 'MIXED')).upper()
    five = str((micro.get('five') or {}).get('direction', 'MIXED')).upper()
    try:
        fc = self._candle_structure_forecast(candles) or {}
    except Exception:
        fc = {}
    fcs = float(fc.get('score', 0.0) or 0.0)
    forecast = fcs if side == 'UP' else -fcs
    mtf_dir = str(consensus.get('direction', 'MIXED')).upper()
    mtf_norm = float(consensus.get('normalized', 0.0) or 0.0)
    mtf = mtf_norm if side == 'UP' else -mtf_norm
    dscore = float(defense.get('score_up' if side == 'UP' else 'score_down', 0.0) or 0.0)
    cache = getattr(self, 'chart_commentary_cache', {}) or {}
    b15 = str((cache.get('15s') or {}).get('bias', '')).upper()
    b30 = str((cache.get('30s') or {}).get('bias', '')).upper()
    votes = []
    reasons = []
    disp_strength = max(0.0, min(1.0, (displacement + 0.02) / 0.3))
    if displacement >= 0.03:
        votes.append(('PRICE', disp_strength, 24.0))
        reasons.append(f'price {displacement:+.2f} ATR through {lock_side}')
    micro_strength = (0.55 if one == side else 0.0) + (0.75 if five == side else 0.0)
    if micro_strength > 0:
        votes.append(('STRUCTURE', min(1.0, micro_strength), 18.0))
        reasons.append(f'1m/5m {side}')
    model_strength = max(0.0, min(1.0, (max(current, 0) * 0.45 + max(fast, 0) * 0.35 + max(pro, 0) * 0.2) / 5.0))
    if model_strength >= 0.22:
        votes.append(('MODEL', model_strength, 18.0))
        reasons.append('live model/tape')
    fc_strength = max(0.0, min(1.0, forecast / 6.0))
    if fc_strength >= 0.28:
        votes.append(('CANDLE', fc_strength, 11.0))
        reasons.append('candle structure')
    mtf_strength = max(0.0, min(1.0, mtf / 0.55)) if mtf_dir == side else 0.0
    if mtf_strength >= 0.3:
        votes.append(('MTF', mtf_strength, 13.0))
        reasons.append('multi-TF rotation')
    def_strength = max(0.0, min(1.0, dscore / 6.0))
    if def_strength >= 0.35:
        votes.append(('PRESSURE', def_strength, 10.0))
        reasons.append('defense/pressure')
    fastpair = side in b15 and side in b30
    fastsingle = side in b15 or side in b30
    if fastpair:
        votes.append(('MICRO', 1.0, 10.0))
        reasons.append('15s+30s agree')
    elif fastsingle:
        votes.append(('MICRO', 0.38, 10.0))
    raw = sum((strength * weight for _, strength, weight in votes))
    if displacement >= 0.16:
        raw += 10.0
    elif displacement >= 0.08:
        raw += 5.0
    elif displacement <= -0.06:
        raw -= 10.0
    raw = max(0.0, min(100.0, raw))
    families = sum((1 for _, s, _ in votes if s >= 0.42))
    now = time.time()
    st = getattr(self, '_v20_break_state', {}) or {}
    key = lock_side + '>' + side
    prev_key = st.get('key')
    since = float(st.get('since', now) or now)
    if prev_key != key or raw < 34 or families < 2:
        since = now
    persistence = max(0.0, now - since)
    immediate = str(lock_health.get('status', '')).upper() == 'BREAKOUT CONFIRMED' and raw >= 55 and (families >= 3)
    stage, risk_floor = _v20_breakout_decision(raw, families, displacement, persistence, immediate)
    confirmed = stage == 'CONFIRMED'
    self._v20_break_state = {'key': key, 'since': since, 'stage': stage, 'score': raw, 'families': families, 'ts': now}
    return {'ready': True, 'lock_side': lock_side, 'breakout_side': side, 'score': raw, 'categories': families, 'risk_floor': risk_floor, 'confirmed': confirmed, 'stage': stage, 'detail': f'{lock_side} LOCK → {side} {stage} {raw:.0f}/100 • {families} independent families' + (' • ' + ' • '.join(reasons[:4]) if reasons else ''), 'against_delta_atr': displacement, 'one_dir': one, 'five_dir': five, 'forecast_against': forecast, 'mtf_dir': mtf_dir, 'mtf_against': mtf, 'defense_score': dscore, 'lock_health_status': str(lock_health.get('status', '')), 'fast_micro_pair': fastpair, 'accelerated_confirm': confirmed and persistence < 0.5}

def _v20_flip_survival_read(self, sig, candles, trend_state, lock_state=None):
    trend_state = trend_state or {}
    lb = trend_state.get('lock_breakout') or {}
    defended = 'WAIT'
    try:
        snap = self._sticky_survival_lock_snapshot() or {}
        defended = str(snap.get('lock_side', 'WAIT')).upper()
    except Exception:
        pass
    if defended not in ('UP', 'DOWN'):
        defended = str(trend_state.get('direction', 'WAIT')).upper()
    stage = str(lb.get('stage', 'NONE')).upper()
    score = float(lb.get('score', 0.0) or 0.0)
    against = str(lb.get('breakout_side', 'WAIT')).upper() in ('UP', 'DOWN') and str(lb.get('breakout_side')).upper() != defended
    if not against:
        stage = 'NONE'
        score = 0.0
    status = str(trend_state.get('status', '')).upper()
    flip = str(trend_state.get('flip_to', '')).upper()
    trend_confirmed = status == 'BREAKOUT CONFIRMED' and flip in ('UP', 'DOWN') and (flip != defended)
    structural = bool(trend_state.get('structural_break', False)) and (flip in ('UP', 'DOWN') and flip != defended)
    previous = float(getattr(self, 'flip_survival_smoothed', 96.0) or 96.0)
    value, target = _v20_survival_decision(previous, stage, score, structural, trend_confirmed)
    self.flip_survival_smoothed = value
    if value >= 92:
        label = 'VERY SAFE'
    elif value >= 82:
        label = 'SAFE'
    elif value >= 70:
        label = 'STILL HEALTHY'
    elif value >= 52:
        label = 'CAUTION'
    elif value >= 30:
        label = 'REAL DANGER'
    else:
        label = 'CRITICAL'
    detail = f'{defended} thesis • breakout {stage} {score:.0f}/100'
    if trend_confirmed:
        detail += ' • STRUCTURAL CONFIRMATION AGAINST THESIS'
    elif structural:
        detail += ' • structural damage'
    elif stage == 'NONE':
        detail += ' • no corroborated breakout'
    return {'value': value, 'target': target, 'label': label, 'side': defended, 'confirmed_against': bool(stage == 'CONFIRMED' or trend_confirmed), 'detail': detail, 'lock_attack_score': score}
ChartKingPro._lock_breakout_read = _v20_lock_breakout_read
