def _v211_series_stats(rows):
    """Turn [[timestamp_ms,value], ...] into robust recent direction/context."""
    clean = []
    for row in rows or []:
        try:
            if not isinstance(row, (list, tuple)) or len(row) < 2:
                continue
            ts = float(row[0])
            val = float(row[1])
            if math.isfinite(ts) and math.isfinite(val):
                clean.append((ts, val))
        except Exception:
            pass
    clean.sort(key=lambda x: x[0])
    if len(clean) < 3:
        return {'ready': False, 'signed': 0.0, 'strength': 0.0, 'last_ts': 0.0, 'latest': None, 'change1': 0.0, 'change3': 0.0, 'z': 0.0}
    vals = [v for _, v in clean]
    latest = vals[-1]
    d1 = vals[-1] - vals[-2]
    d3 = vals[-1] - vals[max(0, len(vals) - 4)]
    diffs = [vals[i] - vals[i - 1] for i in range(max(1, len(vals) - 31), len(vals))]
    mags = sorted((abs(x) for x in diffs if math.isfinite(x)))
    scale = (mags[len(mags) // 2] if mags else 0.0) or (sum(mags) / len(mags) if mags else 1.0) or 1.0
    z = 0.62 * (d1 / scale) + 0.38 * (d3 / (3.0 * scale))
    signed = max(-1.0, min(1.0, math.tanh(z / 1.7)))
    strength = min(100.0, abs(signed) * 100.0)
    return {'ready': True, 'signed': signed, 'strength': strength, 'last_ts': clean[-1][0] / 1000.0, 'latest': latest, 'change1': d1, 'change3': d3, 'z': z, 'n': len(clean)}

def _v211_find_json_roots():
    roots = []
    try:
        roots.append(Path(__file__).resolve().parent)
    except Exception:
        pass
    try:
        roots.append(Path.home() / 'Downloads')
    except Exception:
        pass
    out = []
    seen = set()
    for r in roots:
        try:
            rr = r.resolve()
            if str(rr) not in seen:
                seen.add(str(rr))
                out.append(rr)
        except Exception:
            pass
    return out

def _v211_load_named_json(names):
    """Return newest instance of each requested filename across addon dir + Downloads."""
    found = {}
    lowers = {n.lower(): n for n in names}
    for root in _v211_find_json_roots():
        try:
            for p in root.glob('*.json'):
                key = p.name.lower()
                if key not in lowers:
                    continue
                try:
                    mt = p.stat().st_mtime
                except Exception:
                    continue
                prev = found.get(key)
                if prev is None or mt > prev[0]:
                    found[key] = (mt, p)
        except Exception:
            pass
    out = {}
    for key, (mt, p) in found.items():
        try:
            out[key] = (p, json.loads(p.read_text(encoding='utf-8', errors='ignore')), mt)
        except Exception:
            pass
    return out

def _v211_generic_live_json_read(now=None):
    """Read additional fresh NewHedge/Battlefield exports that are not the four daily context files."""
    now = float(now or time.time())
    named = {'cvd-dollars.json', '3-month-annualized-basis.json', 'funding-rate.json', 'total-futures-open-interest.json'}
    tokens = ('newhedge', 'new_hedge', 'battlefield', 'liquidity', 'orderflow', 'order_flow', 'market_depth', 'marketdepth', 'wave', 'liquidation', 'long-short', 'long_short')
    files = []
    for root in _v211_find_json_roots():
        try:
            for p in root.glob('*.json'):
                if p.name.lower() in named:
                    continue
                if not any((t in p.name.lower() for t in tokens)):
                    continue
                try:
                    files.append((p.stat().st_mtime, p))
                except Exception:
                    pass
        except Exception:
            pass
    files.sort(reverse=True, key=lambda x: x[0])
    votes = []
    evidence = []
    newest_age = 99999.0
    for mt, p in files[:8]:
        age = max(0.0, now - mt)
        newest_age = min(newest_age, age)
        try:
            data = json.loads(p.read_text(encoding='utf-8', errors='ignore'))
        except Exception:
            continue
        stack = [('', data)]
        seen = 0
        while stack and seen < 1800:
            prefix, obj = stack.pop()
            seen += 1
            if isinstance(obj, dict):
                for k, v in list(obj.items())[:300]:
                    stack.append(((prefix + '.' + str(k)).strip('.'), v))
            elif isinstance(obj, list):
                if len(obj) > 12 and all((isinstance(x, (list, tuple)) and len(x) >= 2 for x in obj[:8])):
                    continue
                for i, v in enumerate(obj[:120]):
                    stack.append((f'{prefix}[{i}]', v))
            else:
                k = prefix.lower()
                try:
                    if isinstance(obj, bool):
                        continue
                    n = float(str(obj).replace('%', '').replace(',', ''))
                except Exception:
                    if isinstance(obj, str):
                        s = obj.lower()
                        d = (1 if any((x in s for x in ('bullish', 'up', 'buy', 'above', 'long'))) else 0) - (1 if any((x in s for x in ('bearish', 'down', 'sell', 'below', 'short'))) else 0)
                        if d:
                            votes.append((float(d), 0.65))
                            evidence.append(f"{p.stem}:{prefix.split('.')[-1]}")
                    continue
                if any((x in k for x in ('timestamp', 'epoch', 'price', 'target', 'strike', 'id', 'latency'))):
                    continue
                val = None
                if any((x in k for x in ('probability', 'prob', 'chance', 'confidence', 'bull_percent', 'bullish_percent', 'up_percent'))):
                    if 0 <= n <= 1:
                        val = (n - 0.5) * 2
                    elif 0 <= n <= 100:
                        val = (n - 50) / 50
                elif any((x in k for x in ('bear_percent', 'bearish_percent', 'down_percent'))):
                    if 0 <= n <= 1:
                        val = -(n - 0.5) * 2
                    elif 0 <= n <= 100:
                        val = -(n - 50) / 50
                elif any((x in k for x in ('delta', 'imbalance', 'pressure', 'momentum', 'flow', 'cvd', 'slope', 'velocity', 'accel', 'net', 'bias', 'score'))):
                    if -1.25 <= n <= 1.25:
                        val = n
                    elif -100 <= n <= 100:
                        val = n / 100
                    else:
                        val = math.tanh(n / 25.0)
                if val is not None and abs(val) >= 0.04:
                    votes.append((max(-1.0, min(1.0, val)), 1.0))
                    evidence.append(f"{p.stem}:{prefix.split('.')[-1]}")
    if not votes:
        return {'ready': False, 'signed': 0.0, 'strength': 0.0, 'quality': 0.0, 'age': newest_age, 'evidence': ()}
    vals = sorted(votes, key=lambda x: abs(x[0] * x[1]), reverse=True)[:20]
    signed = sum((v * w for v, w in vals)) / max(1e-09, sum((w for _, w in vals)))
    agree = sum((1 for v, _ in vals if v * (1 if signed >= 0 else -1) >= 0.1)) / len(vals)
    fresh = 1.0 if newest_age <= 10 else max(0.0, 1.0 - (newest_age - 10) / 180.0)
    quality = min(1.0, 0.45 + 0.55 * agree) * fresh
    signed = max(-1.0, min(1.0, signed * (0.8 + 0.45 * agree)))
    return {'ready': quality > 0.05, 'signed': signed, 'strength': abs(signed) * 100.0 * (0.7 + 0.3 * quality), 'quality': quality, 'age': newest_age, 'evidence': tuple(evidence[:6])}

def _v211_newhedge_future_read(self, now=None):
    """
    Multi-dataset NewHedge reader.
    Daily CVD/basis/funding/OI are REGIME context; fresh Battlefield/live JSON may carry more 15m authority.
    Never manufactures confidence simply because more files exist.
    """
    now = float(now or time.time())
    cache = getattr(self, '_v211_nh_cache', None)
    if isinstance(cache, dict) and now - float(cache.get('ts', 0) or 0) < 0.75 and cache.get('result'):
        return dict(cache['result'])
    datasets = _v211_load_named_json(('cvd-dollars.json', '3-month-annualized-basis.json', 'funding-rate.json', 'total-futures-open-interest.json'))
    components = []
    evidence = []
    last_ts = []
    cvd = datasets.get('cvd-dollars.json')
    if cvd:
        p, data, _ = cvd
        stats = [_v211_series_stats(v) for v in data.values() if isinstance(v, list)]
        stats = [s for s in stats if s.get('ready')]
        if stats:
            s = sum((x['signed'] for x in stats)) / len(stats)
            agree = sum((1 for x in stats if x['signed'] * (1 if s >= 0 else -1) >= 0.08)) / len(stats)
            s = max(-1.0, min(1.0, s * (0.72 + 0.48 * agree)))
            components.append(('CVD', s, 1.45))
            evidence.append(f'CVD {s:+.2f} ({len(stats)} venues)')
            last_ts += [x['last_ts'] for x in stats]
    basis = datasets.get('3-month-annualized-basis.json')
    if basis:
        p, data, _ = basis
        stats = [_v211_series_stats(v) for v in data.values() if isinstance(v, list)]
        stats = [s for s in stats if s.get('ready')]
        if stats:
            s = sum((x['signed'] for x in stats)) / len(stats)
            components.append(('BASIS', s, 0.85))
            evidence.append(f'BASIS {s:+.2f}')
            last_ts += [x['last_ts'] for x in stats]
    funding = datasets.get('funding-rate.json')
    if funding:
        p, data, _ = funding
        stats = [_v211_series_stats(v) for v in data.values() if isinstance(v, list)]
        stats = [s for s in stats if s.get('ready')]
        if stats:
            s = sum((x['signed'] for x in stats)) / len(stats)
            components.append(('FUNDING', s, 0.55))
            evidence.append(f'FUNDING Δ {s:+.2f}')
            last_ts += [x['last_ts'] for x in stats]
    oi = datasets.get('total-futures-open-interest.json')
    if oi:
        p, data, _ = oi
        os = _v211_series_stats(data.get('Total Futures Open Interest', []))
        ps = _v211_series_stats(data.get('BTC Price', []))
        if os.get('ready') and ps.get('ready'):
            price_s = ps['signed']
            oi_s = os['signed']
            if oi_s >= 0:
                s = price_s * (0.65 + 0.35 * abs(oi_s))
            else:
                s = price_s * 0.35
            components.append(('OI×PRICE', s, 1.05))
            evidence.append(f'OI×PRICE {s:+.2f}')
            last_ts += [os['last_ts'], ps['last_ts']]
    live = _v211_generic_live_json_read(now)
    if live.get('ready'):
        components.append(('LIVE_NEWHEDGE', float(live['signed']), 1.8 + 1.7 * float(live.get('quality', 0))))
        evidence.append(f"LIVE {float(live['signed']):+.2f} q{float(live.get('quality', 0)) * 100:.0f}%")
    if not components:
        out = {'ready': False, 'direction': 'WAIT', 'signed': 0.0, 'strength': 0.0, 'quality': 0.0, 'families': 0, 'age': 99999.0, 'evidence': (), 'reason': 'No readable NewHedge datasets in addon folder/Downloads'}
    else:
        denom = sum((w for _, _, w in components))
        signed = sum((v * w for _, v, w in components)) / max(denom, 1e-09)
        sign = 1 if signed >= 0 else -1
        agree = sum((1 for _, v, _ in components if v * sign >= 0.08)) / len(components)
        daily_age = max(0.0, now - max(last_ts)) if last_ts else 99999.0
        daily_fresh = 1.0 if daily_age <= 36 * 3600 else max(0.1, 1.0 - (daily_age - 36 * 3600) / (5 * 86400))
        live_q = float(live.get('quality', 0.0) or 0.0)
        quality = min(1.0, (0.24 + 0.34 * agree) * daily_fresh + 0.55 * live_q)
        signed = max(-1.0, min(1.0, signed * (0.85 + 0.35 * agree)))
        strength = min(100.0, abs(signed) * 100.0 * (0.72 + 0.28 * quality))
        direction = 'UP' if signed > 0.055 else 'DOWN' if signed < -0.055 else 'NEUTRAL'
        out = {'ready': True, 'direction': direction, 'signed': signed, 'strength': strength, 'quality': quality, 'families': len(components), 'age': min(daily_age, float(live.get('age', 99999.0) or 99999.0)), 'evidence': tuple(evidence[:8]), 'components': tuple(components), 'reason': f'{direction} {strength:.0f}% • {len(components)} NewHedge families • quality {quality * 100:.0f}%'}
    self._v211_nh_cache = {'ts': now, 'result': dict(out)}
    return out

def _v211_settlement_geometry(self, sig=None, candles=None, now=None):
    now = float(now or time.time())
    sig = sig or getattr(self, 'last_signal', None) or {}
    candles = candles or getattr(self, '_last_analysis_candles', None) or []
    try:
        live, _ = self.effective_live_price()
    except Exception:
        live = None
    try:
        target, _ = self.effective_target()
    except Exception:
        target = None
    remaining = max(1.0, 900.0 - now % 900.0)
    time_frac = max(0.0, min(1.0, remaining / 900.0))
    try:
        expected = abs(float(self._remaining_expected_move(sig, candles) or 0.0))
    except Exception:
        expected = 0.0
    if expected < 4.0:
        try:
            atr = abs(float(sig.get('atr', 0.0) or 0.0))
            expected = max(8.0, atr * math.sqrt(max(0.08, remaining / 60.0)))
        except Exception:
            expected = 18.0
    if live is None or target is None:
        return {'ready': False, 'signed': 0.0, 'live': live, 'target': target, 'remaining': remaining, 'expected': expected, 'distance': 0.0, 'difficulty': 0.0, 'time_frac': time_frac}
    distance = float(live) - float(target)
    z = distance / max(expected, 6.0)
    clock_gain = 0.68 + 1.62 * (1.0 - time_frac) ** 1.32
    signed = max(-1.0, min(1.0, math.tanh(z * clock_gain)))
    return {'ready': True, 'signed': signed, 'live': float(live), 'target': float(target), 'remaining': remaining, 'expected': expected, 'distance': distance, 'difficulty': abs(distance) / max(expected, 6.0), 'time_frac': time_frac}

def _v211_mm3_read(self, warm=None, sig=None, candles=None, now=None):
    """Answer the actual contract question: above or below target when this 15m round settles?"""
    now = float(now or time.time())
    sig = sig or getattr(self, 'last_signal', None) or {}
    candles = candles or getattr(self, '_last_analysis_candles', None) or []
    base = _V211_BASE_MM3(self, warm=warm, sig=sig, candles=candles, now=now)
    nh = _v211_newhedge_future_read(self, now)
    geo = _v211_settlement_geometry(self, sig, candles, now)
    base_signed = max(-1.0, min(1.0, _v19_safe_float(base.get('future_signed', base.get('signed', 0.0)))))
    tf = float(geo.get('time_frac', 1.0) or 1.0)
    w_base = 4.2
    w_geo = 0.85 + 2.45 * (1.0 - tf) if geo.get('ready') else 0.0
    nhq = max(0.0, min(1.0, _v19_safe_float(nh.get('quality')))) if nh.get('ready') else 0.0
    w_nh = 0.7 + 2.45 * nhq if nh.get('ready') else 0.0
    if int(nh.get('families', 0) or 0) >= 4 and _v19_safe_float(nh.get('strength')) >= 35:
        w_nh += 0.45
    signed = (w_base * base_signed + w_geo * _v19_safe_float(geo.get('signed')) + w_nh * _v19_safe_float(nh.get('signed'))) / max(w_base + w_geo + w_nh, 1e-09)
    signed = max(-1.0, min(1.0, signed))
    side = 'UP' if signed >= 0 else 'DOWN'
    score = max(50.0, min(99.0, 50.0 + 49.0 * abs(signed)))
    sign = 1 if side == 'UP' else -1
    convergence = 0
    if base_signed * sign >= 0.12:
        convergence += 1
    if geo.get('ready') and _v19_safe_float(geo.get('signed')) * sign >= 0.12:
        convergence += 1
    if nh.get('ready') and _v19_safe_float(nh.get('signed')) * sign >= 0.12:
        convergence += 1
    score = min(99.0, score + 3.0 * max(0, convergence - 1))
    out = dict(base)
    out.update({'future_side': side, 'settlement_side': side, 'settlement_score': score, 'settlement_signed': signed, 'newhedge': nh, 'settlement_geometry': geo, 'newhedge_weight': w_nh, 'geometry_weight': w_geo, 'base_future_signed': base_signed})
    out['reason'] = f"MM3 {out.get('side', 'WAIT')} {float(out.get('score', 0)):.0f}/100 • 15M WINNER {side} {score:.0f}/100 • BTC {geo.get('distance', 0):+.1f}$ vs target • {geo.get('remaining', 0) / 60:.1f}m left • NewHedge {nh.get('direction', 'WAIT')} {nh.get('strength', 0):.0f}%"
    return out

