def _v211_parse_candles(raw):
    rows = []
    for x in raw or []:
        if not isinstance(x, (list, tuple)) or len(x) < 6:
            continue
        try:
            rows.append({'time': int(float(x[0])), 'low': float(x[1]), 'high': float(x[2]), 'open': float(x[3]), 'close': float(x[4]), 'volume': float(x[5])})
        except Exception:
            pass
    rows.sort(key=lambda r: r['time'])
    return rows

def _v211_merge_seed(existing, seeded, max_rows=2200):
    merged = {int(r.get('time', 0)): dict(r) for r in seeded or [] if r.get('time') is not None}
    for r in existing or []:
        if r.get('time') is not None:
            merged[int(r['time'])] = dict(r)
    return [merged[k] for k in sorted(merged)][-int(max_rows):]

def _v211_public_candle_seed(granularity):
    url = f'https://api.exchange.coinbase.com/products/{PRODUCT}/candles'
    return _v211_parse_candles(http_json(url, {'granularity': int(granularity)}, timeout=5))

def _v211_public_recent_trade_seed():
    try:
        raw = http_json(f'https://api.exchange.coinbase.com/products/{PRODUCT}/trades', {'limit': 1000}, timeout=5)
    except Exception:
        return []
    out = []
    try:
        import datetime as _dt
    except Exception:
        return out
    for row in raw or []:
        try:
            ts = _dt.datetime.fromisoformat(str(row.get('time', '')).replace('Z', '+00:00')).timestamp()
            px = float(row.get('price'))
            if px > 0:
                out.append((float(ts), px))
        except Exception:
            pass
    out.sort(key=lambda x: x[0])
    return out

