def _v212_series_signal(rows):
    clean = []
    for row in rows or []:
        try:
            if isinstance(row, (list, tuple)) and len(row) >= 2:
                ts = float(row[0])
                v = float(row[1])
                if math.isfinite(ts) and math.isfinite(v):
                    clean.append((ts, v))
        except Exception:
            pass
    clean.sort(key=lambda x: x[0])
    if len(clean) < 5:
        return {'ready': False, 'signed': 0.0, 'strength': 0.0, 'last_ts': 0.0}
    vals = [v for _, v in clean]
    diffs = [vals[i] - vals[i - 1] for i in range(max(1, len(vals) - 45), len(vals))]
    mags = sorted((abs(x) for x in diffs if math.isfinite(x) and abs(x) > 0))
    scale = (mags[len(mags) // 2] if mags else 0.0) or (sum(mags) / len(mags) if mags else 1.0) or 1.0

    def impulse(back):
        j = max(0, len(vals) - 1 - int(back))
        return (vals[-1] - vals[j]) / (scale * max(1.0, back ** 0.58))
    z = 0.48 * impulse(1) + 0.32 * impulse(3) + 0.2 * impulse(7)
    signed = max(-1.0, min(1.0, math.tanh(z / 1.55)))
    return {'ready': True, 'signed': signed, 'strength': abs(signed) * 100.0, 'last_ts': clean[-1][0] / 1000.0, 'latest': vals[-1], 'z': z, 'n': len(clean)}

def _v212_newhedge_future_read(self, now=None):
    now = float(now or time.time())
    cache = getattr(self, '_v212_nh_cache', None)
    if isinstance(cache, dict) and now - float(cache.get('ts', 0) or 0) < 0.55 and cache.get('result'):
        return dict(cache['result'])
    ds = _v211_load_named_json(('cvd-dollars.json', '3-month-annualized-basis.json', 'funding-rate.json', 'total-futures-open-interest.json'))
    comps = []
    evidence = []
    timestamps = []

    def venue_family(filename, label, weight):
        pack = ds.get(filename)
        if not pack:
            return
        _p, data, _mt = pack
        stats = [_v212_series_signal(v) for v in data.values() if isinstance(v, list)] if isinstance(data, dict) else []
        stats = [s for s in stats if s.get('ready')]
        if not stats:
            return
        raw = sum((s['signed'] for s in stats)) / len(stats)
        side = 1 if raw >= 0 else -1
        breadth = sum((1 for s in stats if s['signed'] * side >= 0.08)) / len(stats)
        strong = sum((1 for s in stats if s['signed'] * side >= 0.28)) / len(stats)
        signed = max(-1.0, min(1.0, raw * (0.82 + 0.38 * breadth + 0.18 * strong)))
        comps.append((label, signed, weight * (0.82 + 0.28 * breadth)))
        evidence.append(f'{label} {signed:+.2f} breadth {breadth * 100:.0f}%')
        timestamps.extend((s['last_ts'] for s in stats))
    venue_family('cvd-dollars.json', 'CVD', 1.85)
    venue_family('3-month-annualized-basis.json', 'BASIS', 0.85)
    venue_family('funding-rate.json', 'FUNDINGΔ', 0.6)
    oi = ds.get('total-futures-open-interest.json')
    if oi:
        _p, data, _mt = oi
        os = _v212_series_signal(data.get('Total Futures Open Interest', []) if isinstance(data, dict) else [])
        ps = _v212_series_signal(data.get('BTC Price', []) if isinstance(data, dict) else [])
        if os.get('ready') and ps.get('ready'):
            oi_expand = max(0.0, os['signed'])
            signed = ps['signed'] * (0.42 + 0.58 * oi_expand) if os['signed'] >= 0 else ps['signed'] * 0.3
            signed = max(-1.0, min(1.0, signed))
            comps.append(('OI×PRICE', signed, 1.15))
            evidence.append(f'OI×PRICE {signed:+.2f}')
            timestamps += [os['last_ts'], ps['last_ts']]
    live = _v211_generic_live_json_read(now)
    if live.get('ready'):
        lq = max(0.0, min(1.0, float(live.get('quality', 0) or 0)))
        comps.append(('LIVE_NEWHEDGE', float(live.get('signed', 0) or 0), 2.15 + 2.1 * lq))
        evidence.append(f"LIVE {float(live.get('signed', 0)):+.2f} q{lq * 100:.0f}%")
    if not comps:
        out = {'ready': False, 'direction': 'WAIT', 'signed': 0.0, 'strength': 0.0, 'quality': 0.0, 'families': 0, 'age': 99999.0, 'evidence': (), 'reason': 'No readable NewHedge exports in addon folder/Downloads'}
    else:
        denom = sum((w for _, _, w in comps))
        raw = sum((v * w for _, v, w in comps)) / max(denom, 1e-09)
        sign = 1 if raw >= 0 else -1
        aligned = [c for c in comps if c[1] * sign >= 0.08]
        hard = [c for c in comps if c[1] * sign >= 0.28]
        agreement = len(aligned) / len(comps)
        age = max(0.0, now - max(timestamps)) if timestamps else float(live.get('age', 99999.0) or 99999.0)
        day_fresh = 1.0 if age <= 42 * 3600 else max(0.08, 1.0 - (age - 42 * 3600) / (6 * 86400))
        live_q = max(0.0, min(1.0, float(live.get('quality', 0) or 0)))
        quality = min(1.0, (0.38 + 0.38 * agreement + 0.12 * min(1, len(hard) / 2)) * day_fresh + 0.55 * live_q)
        boost = 1.0 + (0.1 if len(aligned) >= 3 else 0.0) + (0.1 if len(aligned) >= 4 else 0.0)
        signed = max(-1.0, min(1.0, raw * boost))
        strength = min(100.0, abs(signed) * 100.0 * (0.82 + 0.3 * quality) + min(12.0, max(0, len(aligned) - 2) * 4.0))
        direction = 'UP' if signed > 0.045 else 'DOWN' if signed < -0.045 else 'NEUTRAL'
        out = {'ready': True, 'direction': direction, 'signed': signed, 'strength': strength, 'quality': quality, 'families': len(comps), 'aligned_families': len(aligned), 'hard_families': len(hard), 'age': age, 'evidence': tuple(evidence[:8]), 'components': tuple(comps), 'reason': f'{direction} {strength:.0f}% strength • {len(aligned)}/{len(comps)} aligned • quality {quality * 100:.0f}%'}
    self._v212_nh_cache = {'ts': now, 'result': dict(out)}
    return out

def _v212_mm3_read(self, warm=None, sig=None, candles=None, now=None):
    now = float(now or time.time())
    sig = sig or getattr(self, 'last_signal', None) or {}
    candles = candles or getattr(self, '_last_analysis_candles', None) or []
    base = _V212_BASE_MM(self, warm=warm, sig=sig, candles=candles, now=now)
    nh = _v212_newhedge_future_read(self, now)
    geo = _v211_settlement_geometry(self, sig, candles, now)
    causal = max(-1.0, min(1.0, float(base.get('base_future_signed', base.get('future_signed', base.get('signed', 0.0))) or 0.0)))
    tf = max(0.0, min(1.0, float(geo.get('time_frac', 1.0) or 1.0)))
    w_causal = 4.65
    w_geo = 0.7 + 2.75 * (1.0 - tf) ** 1.18 if geo.get('ready') else 0.0
    nhq = max(0.0, min(1.0, float(nh.get('quality', 0) or 0))) if nh.get('ready') else 0.0
    nha = int(nh.get('aligned_families', 0) or 0)
    w_nh = 0.8 + 2.8 * nhq + 0.3 * max(0, nha - 2) if nh.get('ready') else 0.0
    numer = w_causal * causal + w_geo * float(geo.get('signed', 0) or 0) + w_nh * float(nh.get('signed', 0) or 0)
    denom = max(w_causal + w_geo + w_nh, 1e-09)
    signed = max(-1.0, min(1.0, numer / denom))
    sign = 1 if signed >= 0 else -1
    convergence = 0
    if causal * sign >= 0.12:
        convergence += 1
    if geo.get('ready') and float(geo.get('signed', 0) or 0) * sign >= 0.12:
        convergence += 1
    if nh.get('ready') and float(nh.get('signed', 0) or 0) * sign >= 0.12:
        convergence += 1
    if convergence >= 2:
        signed = max(-1.0, min(1.0, signed * (1.08 + 0.05 * (convergence - 2))))
    side = 'UP' if signed >= 0 else 'DOWN'
    score = max(50.0, min(99.0, 50.0 + 49.0 * abs(signed) + 2.5 * max(0, convergence - 1)))
    out = dict(base)
    out.update({'future_side': side, 'settlement_side': side, 'settlement_score': score, 'settlement_signed': signed, 'newhedge': nh, 'settlement_geometry': geo, 'newhedge_weight': w_nh, 'geometry_weight': w_geo, 'base_future_signed': causal, 'settlement_convergence': convergence})
    out['reason'] = f"15M WINNER {side} {score:.0f}/100 • causal {causal:+.2f} • target geometry {float(geo.get('signed', 0) or 0):+.2f} • NewHedge {nh.get('direction', 'WAIT')} {float(nh.get('strength', 0) or 0):.0f}% • convergence {convergence}/3"
    return out

def _v212_team_breakout_read(self, sig, candles, base_trend, now=None):
    """Break the OLD defended thesis when independent current evidence actually rotates."""
    now = float(now or time.time())
    lock = self._sticky_survival_lock_snapshot() or getattr(self, 'opening_lock_snapshot', None) or self._selected_checkpoint_snapshot() or {}
    defended = str(lock.get('lock_side', 'WAIT')).upper()
    if defended not in ('UP', 'DOWN'):
        return {'ready': False, 'defended': 'WAIT', 'attack': 'WAIT', 'stage': 'NONE', 'score': 0.0, 'families': 0, 'confirmed': False, 'detail': 'No frozen thesis to attack.'}
    attack = 'DOWN' if defended == 'UP' else 'UP'
    sign = 1 if attack == 'UP' else -1
    mm = _v212_mm3_read(self, sig=sig, candles=candles, now=now)
    raw = mm.get('raw_families') or {}
    nh = mm.get('newhedge') or {}
    geo = mm.get('settlement_geometry') or {}
    fam = []
    points = 0.0
    flow_keys = ('EXEC FLOW', 'PRICE IMPULSE', 'CVD', 'WAVE', 'WHALE', 'SWEEP', 'LARGE LIQ')
    vals = [float(raw.get(k, 0) or 0) * sign for k in flow_keys]
    causal = sum((max(-1.0, min(1.0, v)) for v in vals)) / max(1, len(vals))
    hard_flow = sum((1 for v in vals if v >= 0.28))
    if causal >= 0.1 or hard_flow >= 2:
        fam.append('BOOKMAP FLOW')
        points += min(28.0, 10.0 + causal * 26.0 + hard_flow * 2.0)
    lb = base_trend.get('lock_breakout') or {}
    lb_side = str(lb.get('breakout_side', 'WAIT')).upper()
    lb_stage = str(lb.get('stage', 'NONE')).upper()
    lb_score = float(lb.get('score', 0) or 0)
    mtf = float(raw.get('MTF CANDLES', 0) or 0) * sign
    candle = float(raw.get('CANDLE BEHAVIOR', 0) or 0) * sign
    if lb_side == attack and lb_stage in ('WATCH', 'FORMING', 'LIKELY', 'CONFIRMED') or max(mtf, candle) >= 0.18:
        fam.append('STRUCTURE')
        points += min(22.0, 8.0 + max(0, mtf, candle) * 16.0 + (8.0 if lb_stage == 'CONFIRMED' else 4.0 if lb_stage == 'LIKELY' else 0.0))
    fp = float(mm.get('flip_probability', 0) or 0)
    phase = str(mm.get('flip_phase', 'NONE')).upper()
    flip_to = str(mm.get('flip_to', 'WAIT')).upper()
    if flip_to == attack and (phase in ('FORMING', 'LIKELY', 'CONFIRMED') or fp >= 62):
        fam.append('MM3 FLIP')
        points += min(24.0, 7.0 + max(0, fp - 55) * 0.34 + (6.0 if phase == 'CONFIRMED' else 3.0 if phase == 'LIKELY' else 0.0))
    settle_side = str(mm.get('settlement_side', 'WAIT')).upper()
    settle_score = float(mm.get('settlement_score', 0) or 0)
    if settle_side == attack and settle_score >= 64:
        fam.append('15M WINNER')
        points += min(22.0, 8.0 + (settle_score - 60) * 0.45)
    nh_side = str(nh.get('direction', 'WAIT')).upper()
    nh_strength = float(nh.get('strength', 0) or 0)
    nhq = float(nh.get('quality', 0) or 0)
    if nh_side == attack and nh_strength >= 18 and (nhq >= 0.22):
        fam.append('NEWHEDGE')
        points += min(18.0, 5.0 + nh_strength * 0.13 + nhq * 4.0)
    gs = float(geo.get('signed', 0) or 0) * sign
    if geo.get('ready') and gs >= 0.14:
        fam.append('TARGET GEOMETRY')
        points += min(16.0, 5.0 + gs * 13.0)
    traj = float(mm.get('trajectory', 0) or 0) * sign
    if traj >= 0.022:
        fam.append('TRAJECTORY')
        points += min(12.0, 4.0 + traj * 75.0)
    n = len(fam)
    score = max(0.0, min(100.0, points + max(0, n - 2) * 3.0))
    state = getattr(self, '_v212_breakout_state', {})
    key = f'{defended}->{attack}'
    if state.get('key') != key or score < 38:
        state = {'key': key, 'since': now if score >= 38 else 0.0, 'last': score}
    elif not state.get('since') and score >= 38:
        state['since'] = now
    state['last'] = score
    self._v212_breakout_state = state
    age = max(0.0, now - float(state.get('since', 0) or now)) if state.get('since') else 0.0
    immediate = phase == 'CONFIRMED' and flip_to == attack and (n >= 3) and (score >= 64) or (hard_flow >= 4 and n >= 5 and (score >= 68))
    if immediate or (score >= 72 and n >= 4 and (age >= 0.55)) or (score >= 66 and n >= 5 and (age >= 0.35)):
        stage = 'CONFIRMED'
    elif score >= 58 and n >= 3:
        stage = 'LIKELY'
    elif score >= 45 and n >= 2:
        stage = 'FORMING'
    elif score >= 32 and n >= 2:
        stage = 'WATCH'
    else:
        stage = 'NONE'
    return {'ready': True, 'defended': defended, 'attack': attack, 'stage': stage, 'score': score, 'families': n, 'family_names': tuple(fam), 'confirmed': stage == 'CONFIRMED', 'age': age, 'mm': mm, 'detail': f"{defended} thesis → {attack} {stage} {score:.0f}/100 • {n} families [{', '.join(fam) or 'none'}]"}

def _v212_current_trend_reversal(self, sig, candles, defense):
    base = _V212_BASE_TREND(self, sig, candles, defense)
    try:
        team = _v212_team_breakout_read(self, sig, candles, base, time.time())
    except Exception as exc:
        base['team_breakout'] = {'ready': False, 'stage': 'NONE', 'score': 0, 'detail': f'team breakout unavailable: {exc}'}
        return base
    base['team_breakout'] = team
    if not team.get('ready'):
        return base
    stage = str(team.get('stage', 'NONE')).upper()
    attack = str(team.get('attack', 'WAIT')).upper()
    score = float(team.get('score', 0) or 0)
    if stage == 'CONFIRMED':
        base['status'] = 'BREAKOUT CONFIRMED'
        base['flip_to'] = attack
        base['breakout_basis'] = 'TEAM_REFEREE'
        base['risk'] = max(float(base.get('risk', 0) or 0), min(99.0, 88.0 + (score - 70) * 0.28))
        base['raw_risk'] = max(float(base.get('raw_risk', 0) or 0), base['risk'])
        self.trend_risk_smoothed = base['risk']
        base['detail'] = 'TEAM BREAKOUT CONFIRMED • ' + team['detail'] + ' • frozen lock has LOST veto power.'
    elif stage == 'LIKELY':
        base['risk'] = max(float(base.get('risk', 0) or 0), min(86.0, 64.0 + (score - 58) * 0.75))
        base['raw_risk'] = max(float(base.get('raw_risk', 0) or 0), base['risk'])
        if base.get('status') != 'BREAKOUT CONFIRMED':
            base['status'] = 'WATCH'
            base['flip_to'] = attack
            base['breakout_basis'] = 'TEAM_REFEREE'
        base['detail'] = 'TEAM BREAKOUT LIKELY • ' + team['detail']
    elif stage == 'FORMING':
        base['risk'] = max(float(base.get('risk', 0) or 0), min(70.0, 48.0 + (score - 45) * 0.7))
        base['raw_risk'] = max(float(base.get('raw_risk', 0) or 0), base['risk'])
        if base.get('status') == 'HEALTHY':
            base['status'] = 'WATCH'
            base['flip_to'] = attack
        base['detail'] = 'TEAM BREAKOUT FORMING • ' + team['detail']
    return base

