        self._set_var_if_changed(self.team_mm_evidence_var, f"NEW HEDGE families {int(nh.get('aligned_families', 0) or 0)}/{int(nh.get('families', 0) or 0)} aligned • authority {float(mm.get('newhedge_weight', 0) or 0):.2f}x • {' | '.join(nh.get('evidence') or ()) or nh.get('reason', 'waiting')}")
