def _v213_newhedge_payload_paths():
    roots = []
    try:
        roots.append(Path.home() / 'Downloads')
    except Exception:
        pass
    try:
        roots.append(Path(__file__).resolve().parent)
    except Exception:
        pass
    seen = []
    for r in roots:
        try:
            r.mkdir(parents=True, exist_ok=True)
            if str(r) not in [str(x) for x in seen]:
                seen.append(r)
        except Exception:
            pass
    return seen

def _v213_extract_json_payload(raw):
    raw = str(raw or '').strip()
    if not raw:
        return None
    try:
        return json.loads(raw)
    except Exception:
        pass
    candidates = []
    for a, b in (('{', '}'), ('[', ']')):
        i = raw.find(a)
        j = raw.rfind(b)
        if i >= 0 and j > i:
            candidates.append(raw[i:j + 1])
    for c in candidates:
        try:
            return json.loads(c)
        except Exception:
            pass
    return None

def _v213_store_newhedge_api_code(self, raw):
    raw = str(raw or '').strip()
    if not raw:
        return (False, 'Paste the NewHedge API/embed code first.')
    payload = _v213_extract_json_payload(raw)
    roots = _v213_newhedge_payload_paths()
    saved = []
    for root in roots:
        try:
            p = root / 'BOOKMAP_KING_NEWHEDGE_API_CODE.txt'
            p.write_text(raw, encoding='utf-8')
            saved.append(str(p))
        except Exception:
            pass
        if payload is not None:
            try:
                jp = root / 'newhedge-submitted-api.json'
                jp.write_text(json.dumps(payload, ensure_ascii=False, indent=2), encoding='utf-8')
                saved.append(str(jp))
            except Exception:
                pass
    self.newhedge_api_code_text = raw
    self.newhedge_api_payload_ready = payload is not None
    try:
        self._v212_nh_cache = {'ts': 0.0, 'result': {}}
    except Exception:
        pass
    if payload is not None:
        return (True, 'NewHedge API code submitted • JSON payload parsed and LIVE_NEWHEDGE input refreshed.')
    urls = re.findall('https?://[^\\\\s\\"\\\'<>]+', raw)
    if urls:
        return (True, 'NewHedge API/embed code saved • URL/code captured. JSON exports still remain active inputs.')
    return (True, 'NewHedge API/embed code saved • raw code retained. JSON exports still remain active inputs.')

def _v213_open_newhedge_api_dialog(self):
    win = tk.Toplevel(self.root)
    win.title('NewHedge API / Embed Code')
    win.geometry('820x610')
    try:
        win.configure(bg=PANEL)
        win.transient(self.root)
    except Exception:
        pass
    outer = ttk.Frame(win, style='Card.TFrame', padding=14)
    outer.pack(fill='both', expand=True)
    ttk.Label(outer, text='NEWHEDGE API / EMBED CODE', style='Title.Card.TLabel').pack(anchor='w')
    ttk.Label(outer, text='Paste the NewHedge code/export payload here. The bot does NOT execute pasted code; it extracts readable JSON/data and feeds it into NewHedge Future.', style='Muted.Card.TLabel', wraplength=760).pack(anchor='w', pady=(2, 8))
    box = tk.Text(outer, height=24, bg=PANEL2, fg=TEXT, insertbackground=TEXT, wrap='none', font=('Consolas', 9))
    box.pack(fill='both', expand=True)
    existing = str(getattr(self, 'newhedge_api_code_text', '') or '')
    if not existing:
        for root in _v213_newhedge_payload_paths():
            p = root / 'BOOKMAP_KING_NEWHEDGE_API_CODE.txt'
            try:
                if p.exists():
                    existing = p.read_text(encoding='utf-8', errors='ignore')
                    break
            except Exception:
                pass
    if existing:
        box.insert('1.0', existing)
    status = tk.StringVar(value='Ready — paste NewHedge code, then SUBMIT API CODE.')
    ttk.Label(outer, textvariable=status, style='Muted.Card.TLabel', wraplength=760).pack(anchor='w', pady=(8, 5))
    row = ttk.Frame(outer, style='Card.TFrame')
    row.pack(fill='x')
    submit = ttk.Button(row, text='SUBMIT API CODE')
    submit.pack(side='left')
    ttk.Button(row, text='CLOSE', command=win.destroy).pack(side='left', padx=6)

    def do_submit():
        try:
            ok, msg = _v213_store_newhedge_api_code(self, box.get('1.0', 'end').strip())
            status.set(msg)
            try:
                if hasattr(self, 'team_mm_future_var'):
                    self._set_var_if_changed(self.team_mm_future_var, 'NEWHEDGE FUTURE: API CODE SUBMITTED • refreshing multi-data read…')
            except Exception:
                pass
        except Exception as exc:
            status.set(f'NewHedge submit error: {exc}')
    submit.configure(command=do_submit)

def _v213_mount_newhedge_button(self):
    try:
        root = self.root
        stack = [root]
        api_btn = None
        while stack:
            w = stack.pop()
            try:
                children = list(w.winfo_children())
            except Exception:
                children = []
            for c in children:
                stack.append(c)
                try:
                    if isinstance(c, ttk.Button) and str(c.cget('text')).strip().upper() == 'API KEY':
                        api_btn = c
                        break
                except Exception:
                    pass
            if api_btn is not None:
                break
        if api_btn is None:
            return False
        parent = api_btn.master
        for child in list(parent.winfo_children()):
            try:
                info = child.grid_info()
                if not info:
                    continue
                col = int(info.get('column', 0))
                if col >= 7:
                    child.grid_configure(column=col + 1)
            except Exception:
                pass
        btn = ttk.Button(parent, text='NEWHEDGE API', command=lambda: _v213_open_newhedge_api_dialog(self), width=12)
        btn.grid(row=0, column=7, padx=(3, 2))
        self.newhedge_api_button = btn
        return True
    except Exception:
        return False
