    _V213_BASE_INIT(self, *args, **kwargs)
    self.newhedge_api_code_text = ''
    self.newhedge_api_payload_ready = False
    try:
        for root in _v213_newhedge_payload_paths():
            p = root / 'BOOKMAP_KING_NEWHEDGE_API_CODE.txt'
            if p.exists():
                self.newhedge_api_code_text = p.read_text(encoding='utf-8', errors='ignore')
                self.newhedge_api_payload_ready = _v213_extract_json_payload(self.newhedge_api_code_text) is not None
                break
    except Exception:
        pass
    try:
        _v213_mount_newhedge_button(self)
    except Exception:
        pass
    try:
        self.root.title('BOOKMAP KING V21.3 — V21.2 + NEWHEDGE SUBMIT API CODE')
    except Exception:
        pass
