def _v214_side_sign(side):
    return 1.0 if str(side).upper() == 'UP' else -1.0 if str(side).upper() == 'DOWN' else 0.0

def _v214_mm_stabilize(self, raw, now):
    """Expose the early read immediately, but require evidence persistence to move committed side."""
    raw = dict(raw or {})
    early = str(raw.get('settlement_side', raw.get('future_side', raw.get('side', 'WAIT')))).upper()
    if early not in ('UP', 'DOWN'):
        early = 'WAIT'
    score = float(raw.get('settlement_score', raw.get('score', 0)) or 0)
    conv = int(raw.get('settlement_convergence', 0) or 0)
    nh = raw.get('newhedge') or {}
    nh_side = str(nh.get('direction', 'WAIT')).upper()
    nh_strength = float(nh.get('strength', 0) or 0)
    straight = bool(raw.get('straight_shot'))
    state = getattr(self, '_v214_mm_commit_state', {}) or {}
    committed = str(state.get('committed', 'WAIT')).upper()
    candidate = str(state.get('candidate', 'WAIT')).upper()
    if committed not in ('UP', 'DOWN'):
        if early in ('UP', 'DOWN') and (score >= 66 or straight or conv >= 2):
            committed = early
            state = {'committed': committed, 'candidate': 'WAIT', 'candidate_since': 0.0, 'commit_ts': now}
        else:
            raw['early_side'] = early
            raw['early_score'] = score
            raw['committed_side'] = early
            return raw
    if early == committed or early == 'WAIT':
        state['candidate'] = 'WAIT'
        state['candidate_since'] = 0.0
    else:
        if candidate != early:
            state['candidate'] = early
            state['candidate_since'] = now
        age = max(0.0, now - float(state.get('candidate_since', now) or now))
        overwhelming = score >= 91 and conv >= 2 or (score >= 88 and nh_side == early and (nh_strength >= 20)) or straight
        strong = score >= 82 and conv >= 2
        needed = 0.35 if overwhelming else 0.75 if strong else 1.35 if score >= 74 else 2.1
        phase = str(raw.get('flip_phase', 'NONE')).upper()
        flip_to = str(raw.get('flip_to', 'WAIT')).upper()
        if phase == 'CONFIRMED' and flip_to == early and (score >= 78):
            needed = min(needed, 0.55)
        if age >= needed:
            committed = early
            state = {'committed': committed, 'candidate': 'WAIT', 'candidate_since': 0.0, 'commit_ts': now}
    self._v214_mm_commit_state = state
    raw['early_side'] = early
    raw['early_score'] = score
    raw['committed_side'] = committed
    raw['raw_settlement_side'] = early
    if committed in ('UP', 'DOWN'):
        raw['side'] = committed
        raw['future_side'] = committed
        raw['settlement_side'] = committed
        if early != committed:
            raw['qualified'] = False
            raw['straight_shot'] = False
            raw['reason'] = f'EARLY {early} {score:.0f}/100 detected • COMMITTED {committed} holding until confirmation • ' + str(raw.get('reason', ''))
    return raw

def _v214_mm3_read(self, warm=None, sig=None, candles=None, now=None):
    now = float(now or time.time())
    raw = _V214_BASE_MM(self, warm=warm, sig=sig, candles=candles, now=now)
    return _v214_mm_stabilize(self, raw, now)

def _v214_newhedge_thought_text(mm):
    mm = dict(mm or {})
    nh = mm.get('newhedge') or {}
    geo = mm.get('settlement_geometry') or {}
    side = str(mm.get('settlement_side', 'WAIT')).upper()
    early = str(mm.get('early_side', side)).upper()
    score = float(mm.get('settlement_score', 0) or 0)
    signed = float(mm.get('settlement_signed', 0) or 0)
    evidence = list(nh.get('evidence') or ())
    comps = list(nh.get('components') or ()) if isinstance(nh.get('components'), (list, tuple)) else []
    direction = str(nh.get('direction', 'WAIT')).upper()
    strength = float(nh.get('strength', 0) or 0)
    quality = float(nh.get('quality', 0) or 0) * 100
    distance = float(geo.get('distance', 0) or 0)
    remaining = float(geo.get('remaining', 0) or 0)
    expected = float(geo.get('expected_remaining_move', geo.get('expected_move', 0)) or 0)
    causal = float(mm.get('base_future_signed', 0) or 0)
    g = float(geo.get('signed', 0) or 0)
    conv = int(mm.get('settlement_convergence', 0) or 0)
    observations = 'WHAT NEWHEDGE SEES: ' + (' | '.join(evidence) if evidence else str(nh.get('reason', 'waiting for usable NewHedge data')))
    if comps:
        observations += ' | components: ' + ' ; '.join((str(x) for x in comps[:8]))
    interpretation = f'INTERPRETATION: NewHedge={direction} strength {strength:.0f}% / quality {quality:.0f}%. Bookmap causal pressure {causal:+.2f}; target geometry {g:+.2f}; {distance:+.1f}$ from target with {remaining / 60:.1f}m left. Independent convergence {conv}/3.'
    decision = f"15M DECISION: {side} {score:.0f}/100 (early read {early}) • fused score {signed:+.2f}. The model is choosing {('ABOVE' if side == 'UP' else 'BELOW' if side == 'DOWN' else 'WAIT')} at settlement because current causal flow, remaining target reachability, and NewHedge futures context are weighted together rather than any one source deciding alone."
    invalid = f'WHAT WOULD CHANGE IT: sustained opposing Bookmap execution/impulse, target geometry becoming unreachable in the current direction, or NewHedge families rotating with enough quality/strength to survive the Mastermind confirmation gate. Expected remaining travel context: {expected:+.1f}$.'
    return (observations, interpretation, decision, invalid)

def _v214_mount_thoughts(self):
    try:
        page = getattr(self, 'page_frame', None)
        if page is None:
            return False
        box = ttk.Frame(page, style='Card.TFrame', padding=10)
        box.pack(fill='x', padx=2, pady=(3, 6))
        self._v214_nh_box = box
        ttk.Label(box, text='NEWHEDGE // FULL INTERPRETATION', style='Title.Card.TLabel').pack(anchor='w')
        for var, strong in ((self.newhedge_observation_var, False), (self.newhedge_interpretation_var, False), (self.newhedge_decision_var, True), (self.newhedge_invalidation_var, False)):
            ttk.Label(box, textvariable=var, style='Strong.Card.TLabel' if strong else 'Muted.Card.TLabel', wraplength=1500, justify='left').pack(anchor='w', fill='x', pady=(2, 0))
        ttk.Label(box, textvariable=self.mastermind_stability_var, style='Strong.Card.TLabel', wraplength=1500, justify='left').pack(anchor='w', fill='x', pady=(5, 0))
        ttk.Label(box, textvariable=self.value_entry_var, style='Muted.Card.TLabel', wraplength=1500, justify='left').pack(anchor='w', fill='x', pady=(2, 0))
        nh_lock_shell = tk.Frame(box, bg=PANEL2, padx=10, pady=8, highlightthickness=2, highlightbackground=CYAN)
        nh_lock_shell.pack(fill='x', pady=(8, 4))
        tk.Label(nh_lock_shell, text='NEWHEDGE FORMULATED LOCK', bg=PANEL2, fg=CYAN, font=('Segoe UI Variable', 11, 'bold'), anchor='w').pack(fill='x')
        tk.Label(nh_lock_shell, textvariable=self.newhedge_lock_var, bg=PANEL2, fg=TEXT, font=('Segoe UI Variable', 10, 'bold'), anchor='w', justify='left', wraplength=1450).pack(fill='x', pady=(4, 0))
        tk.Label(nh_lock_shell, text='NO RUSH • NewHedge stays UNLOCKED / FORMULATING until its own feed agrees.', bg=PANEL2, fg=MUTED, font=('Segoe UI Variable', 9), anchor='w', justify='left', wraplength=1450).pack(fill='x', pady=(2, 0))
        self._v231_nh_lock_box = nh_lock_shell
        return True
    except Exception:
        return False

def _v214_consensus_read(self, mm=None, sig=None, candles=None, now=None):
    now = float(now or time.time())
    sig = sig or getattr(self, 'last_signal', None) or {}
    candles = candles or getattr(self, '_last_analysis_candles', None) or []
    mm = mm or _v214_mm3_read(self, sig=sig, candles=candles, now=now)
    lock = self._sticky_survival_lock_snapshot() or getattr(self, 'opening_lock_snapshot', None) or self._selected_checkpoint_snapshot() or {}
    bk = str(lock.get('lock_side', 'WAIT')).upper()
    mm_side = str(mm.get('settlement_side', 'WAIT')).upper()
    mm_score = float(mm.get('settlement_score', 0) or 0)
    early = str(mm.get('early_side', mm_side)).upper()
    trend = (sig or {}).get('trend_reversal') or {}
    team = trend.get('team_breakout') or {}
    status = str(trend.get('status', '')).upper()
    flip = str(trend.get('flip_to', 'WAIT')).upper()
    breakout_support = False
    breakout_note = 'neutral'
    if bk in ('UP', 'DOWN'):
        opposing = 'DOWN' if bk == 'UP' else 'UP'
        stage = str(team.get('stage', 'NONE')).upper()
        attack = str(team.get('attack', 'WAIT')).upper()
        breakout_support = not (attack == opposing and stage in ('FORMING', 'LIKELY', 'CONFIRMED'))
        if status == 'BREAKOUT CONFIRMED' and flip == bk:
            breakout_support = True
        breakout_note = f'{stage} {attack}' if team.get('ready') else status or 'CLEAR'
    full = bool(bk in ('UP', 'DOWN') and mm_side == bk and (mm_score >= 90) and breakout_support and (early == bk))
    return {'bookmap': bk, 'mastermind': mm_side, 'mastermind_score': mm_score, 'early': early, 'breakout_support': breakout_support, 'breakout_note': breakout_note, 'full_team': full, 'side': bk if full else mm_side}

def _v214_update_mastermind_panel(self, sig, candles):
    try:
        _V214_BASE_PANEL(self, sig, candles)
    except Exception:
        pass
    try:
        mm = _v214_mm3_read(self, sig=sig, candles=candles, now=time.time())
        self._v19_last_mm = mm
        obs, interp, decision, invalid = _v214_newhedge_thought_text(mm)
        self._set_var_if_changed(self.newhedge_observation_var, obs)
        self._set_var_if_changed(self.newhedge_interpretation_var, interp)
        self._set_var_if_changed(self.newhedge_decision_var, decision)
        self._set_var_if_changed(self.newhedge_invalidation_var, invalid)
        committed = str(mm.get('committed_side', mm.get('settlement_side', 'WAIT'))).upper()
        early = str(mm.get('early_side', committed)).upper()
        self._set_var_if_changed(self.mastermind_stability_var, f"MASTERMIND STABILITY: COMMITTED {committed} • EARLY READ {early} {float(mm.get('early_score', 0) or 0):.0f}/100 • {('candidate detected — waiting for persistence' if early != committed else 'aligned / stable')}")
        cons = _v214_consensus_read(self, mm=mm, sig=sig, candles=candles)
        self._set_var_if_changed(self.value_entry_var, f"VALUE ENTRY: ≤55¢ IDEAL • 56–65¢ GOOD • 66–75¢ FULL-TEAM ONLY • >75¢ HARD BLOCK • team {('ALL AGREE ' + cons['side'] if cons.get('full_team') else 'not unanimous')}")
    except Exception:
        pass

def _v214_value_ceiling(mm, consensus, straight=False):
    score = float((mm or {}).get('settlement_score', (mm or {}).get('score', 0)) or 0)
    fam = int((mm or {}).get('family_count', 0) or 0)
    if consensus and consensus.get('full_team') and (score >= 94):
        return 0.75
    if consensus and consensus.get('full_team'):
        return 0.72
    if straight and score >= 95:
        return 0.68
    if straight:
        return 0.64
    if score >= 95 and fam >= 5:
        return 0.65
    return 0.6

def _v214_auto_paper_tick(self, warm=None, sig=None, candles=None, now=None, mode='LIVE'):
    if not self.auto_paper_enabled_var.get():
        return _V214_BASE_AUTO(self, warm=warm, sig=sig, candles=candles, now=now, mode=mode)
    if self.paper_active_trade is not None:
        return _V214_BASE_AUTO(self, warm=warm, sig=sig, candles=candles, now=now, mode=mode)
    now = float(now or time.time())
    if now - float(getattr(self, '_v214_last_entry_eval', 0) or 0) < 0.1:
        return False
    self._v214_last_entry_eval = now
    bucket = int(now // 900) * 900
    if self.auto_paper_last_bucket == bucket:
        return False
    mm = _v214_mm3_read(self, warm=warm, sig=sig, candles=candles, now=now)
    self._v19_last_mm = mm
    cons = _v214_consensus_read(self, mm=mm, sig=sig, candles=candles, now=now)
    lock = self._sticky_survival_lock_snapshot() or getattr(self, 'opening_lock_snapshot', None) or self._selected_checkpoint_snapshot() or {}
    bk = str(lock.get('lock_side', 'WAIT')).upper()
    straight = bool(mm.get('straight_shot'))
    side = 'WAIT'
    lane = ''
    if straight and str(mm.get('settlement_side', 'WAIT')).upper() in ('UP', 'DOWN') and (str(mm.get('early_side', mm.get('settlement_side'))).upper() == str(mm.get('settlement_side')).upper()):
        side = str(mm.get('settlement_side')).upper()
        lane = 'EASY STRAIGHT-SHOT SNIPER'
    elif cons.get('full_team'):
        side = str(cons.get('side', 'WAIT')).upper()
        lane = 'FULL TEAM CONSENSUS'
    else:
        return _V214_BASE_AUTO(self, warm=warm, sig=sig, candles=candles, now=now, mode=mode)
    px, _, src, age = self._kalshi_paper_price(side, 'ENTER', max_age=3.0)
    if px is None:
        return False
    cap = min(_V214_HARD_MAX_ENTRY, _v214_value_ceiling(mm, cons, straight=straight))
    if float(px) > cap:
        self._set_var_if_changed(self.auto_paper_reason_var, f'{lane}: RIGHT SIDE / BAD VALUE • {side} {float(px) * 100:.1f}¢ > {cap * 100:.0f}¢ cap')
        return False
    mm2 = _v214_mm3_read(self, sig=sig, candles=candles, now=time.time())
    cons2 = _v214_consensus_read(self, mm=mm2, sig=sig, candles=candles, now=time.time())
    if str(mm2.get('settlement_side', 'WAIT')).upper() != side or str(mm2.get('early_side', side)).upper() != side:
        self._set_var_if_changed(self.auto_paper_reason_var, f'{lane}: final read changed • entry cancelled')
        return False
    if lane == 'FULL TEAM CONSENSUS' and (not cons2.get('full_team')):
        return False
    px2, _, _, _ = self._kalshi_paper_price(side, 'ENTER', max_age=3.0)
    if px2 is None or float(px2) > min(_V214_HARD_MAX_ENTRY, _v214_value_ceiling(mm2, cons2, straight=straight)):
        return False
    opened = self._paper_open(side, entry_source='AUTO', auto_score=float(mm2.get('settlement_score', 0) or 0), auto_reason=f'{lane} • V21.4 stable MM • value {float(px2) * 100:.1f}¢ • HARD MAX 75¢')
    if opened:
        self.auto_paper_last_bucket = bucket
        self._set_var_if_changed(self.auto_paper_score_var, f'ENTERED {side} • {lane} • {float(px2) * 100:.1f}¢')
        self._set_var_if_changed(self.auto_paper_reason_var, f'{lane} • team/value gate passed')
    return bool(opened)

def _v214_live_submit_entry(self, direction, paper_contract_px=None, reason='AUTO'):
    return False

def _v214_paper_open(self, direction, entry_source='MANUAL', auto_score=None, auto_reason=None):
    if str(entry_source).upper() == 'AUTO':
        try:
            px, _, _, _ = self._kalshi_paper_price(str(direction).upper(), 'ENTER', max_age=3.0)
        except Exception:
            px = None
        if px is None or float(px) > _V214_HARD_MAX_ENTRY:
            try:
                self._set_var_if_changed(self.auto_paper_reason_var, f'AUTO HARD BLOCK • executable {float(px) * 100:.1f}¢ > 75¢' if px is not None else 'AUTO HARD BLOCK • no executable ask')
            except Exception:
                pass
            return False
    return _V214_BASE_PAPER_OPEN(self, direction, entry_source=entry_source, auto_score=auto_score, auto_reason=auto_reason)
