def _v215_breakout_read(self, mm=None, sig=None, candles=None, now=None):
    """Read Breakout Man without consulting the frozen Bookmap King lock."""
    now = float(now or time.time())
    sig = sig or getattr(self, 'last_signal', None) or {}
    mm = mm or _v214_mm3_read(self, sig=sig, candles=candles, now=now)
    trend = (sig or {}).get('trend_reversal') or {}
    team = trend.get('team_breakout') or {}
    stage = str(team.get('stage', 'NONE')).upper()
    attack = str(team.get('attack', 'WAIT')).upper()
    score = float(team.get('score', team.get('risk', 0)) or 0)
    phase = str(mm.get('flip_phase', 'NONE')).upper()
    flip_to = str(mm.get('flip_to', 'WAIT')).upper()
    flip_p = float(mm.get('flip_probability', 0) or 0)
    if attack not in ('UP', 'DOWN') and flip_to in ('UP', 'DOWN') and (phase in ('FORMING', 'LIKELY', 'CONFIRMED')):
        attack = flip_to
        stage = phase
        score = max(score, flip_p)
    if attack not in ('UP', 'DOWN'):
        traj = float(mm.get('trajectory', 0) or 0)
        if abs(traj) >= 0.035:
            attack = 'UP' if traj > 0 else 'DOWN'
            stage = 'WATCH'
            score = max(score, min(70.0, abs(traj) * 900.0))
    return {'side': attack, 'stage': stage, 'score': score, 'ready': attack in ('UP', 'DOWN')}

def _v215_authority_read(self, mm=None, sig=None, candles=None, now=None):
    """ONLY NewHedge, stabilized Mastermind, and Breakout Man vote on entries."""
    now = float(now or time.time())
    sig = sig or getattr(self, 'last_signal', None) or {}
    mm = mm or _v214_mm3_read(self, sig=sig, candles=candles, now=now)
    nh = mm.get('newhedge') or {}
    nh_side = str(nh.get('direction', 'WAIT')).upper()
    nh_strength = float(nh.get('strength', 0) or 0)
    nh_quality = float(nh.get('quality', 0) or 0)
    mm_side = str(mm.get('settlement_side', 'WAIT')).upper()
    mm_early = str(mm.get('early_side', mm_side)).upper()
    mm_score = float(mm.get('settlement_score', mm.get('score', 0)) or 0)
    bo = _v215_breakout_read(self, mm=mm, sig=sig, candles=candles, now=now)
    bo_side = str(bo.get('side', 'WAIT')).upper()
    bo_stage = str(bo.get('stage', 'NONE')).upper()
    bo_score = float(bo.get('score', 0) or 0)
    votes = []
    if nh_side in ('UP', 'DOWN') and (nh_strength >= 12 or nh_quality >= 0.45):
        votes.append(('NEWHEDGE', nh_side, max(nh_strength, nh_quality * 100)))
    if mm_side in ('UP', 'DOWN') and mm_score >= 72:
        votes.append(('MASTERMIND', mm_side, mm_score))
    if bo_side in ('UP', 'DOWN') and bo_stage in ('FORMING', 'LIKELY', 'CONFIRMED'):
        votes.append(('BREAKOUT MAN', bo_side, max(bo_score, 60 if bo_stage == 'FORMING' else 76 if bo_stage == 'LIKELY' else 92)))
    up = [v for v in votes if v[1] == 'UP']
    dn = [v for v in votes if v[1] == 'DOWN']
    winning = up if len(up) > len(dn) else dn if len(dn) > len(up) else []
    side = winning[0][1] if winning else 'WAIT'
    agree = len(winning)
    all_three = agree == 3 and len(votes) == 3
    two_strong = agree >= 2 and all((v[2] >= 72 for v in winning))
    mm_transition = mm_early in ('UP', 'DOWN') and mm_side in ('UP', 'DOWN') and (mm_early != mm_side)
    independent_override = bool(nh_side == mm_side and bo_side == mm_side and (bo_stage in ('LIKELY', 'CONFIRMED')) and (nh_strength >= 18))
    stable_for_entry = not mm_transition or independent_override
    return {'side': side, 'agree': agree, 'all_three': all_three, 'two_strong': two_strong, 'stable_for_entry': stable_for_entry, 'newhedge': nh_side, 'newhedge_strength': nh_strength, 'newhedge_quality': nh_quality, 'mastermind': mm_side, 'mastermind_early': mm_early, 'mastermind_score': mm_score, 'breakout': bo_side, 'breakout_stage': bo_stage, 'breakout_score': bo_score, 'votes': votes}

def _v215_value_cap(mm, auth, straight=False):
    score = float((mm or {}).get('settlement_score', (mm or {}).get('score', 0)) or 0)
    if auth.get('all_three') and score >= 92:
        return 0.75
    if auth.get('all_three'):
        return 0.72
    if auth.get('two_strong') and score >= 88:
        return 0.68
    if straight and auth.get('agree', 0) >= 2:
        return 0.65
    if auth.get('two_strong'):
        return 0.64
    return 0.58

