_V216_BASE_STORE_NEWHEDGE = ChartKingPro._store_newhedge_api_code
_V216_BASE_INIT = ChartKingPro.__init__
_V216_BASE_NH_READ = _v212_newhedge_future_read
_V216_POLL_INTERVAL = 0.85
_V216_FETCH_TIMEOUT = 2.6
_V216_MAX_URLS = 4

def _v216_extract_urls(raw):
    raw = str(raw or '')
    if not raw:
        return []
    text = raw.replace('\\/', '/').replace('\\u0026', '&').replace('&amp;', '&')
    urls = re.findall('https?://[^\\s\\"\\\'<>`]+', text)
    out = []
    seen = set()
    for u in urls:
        u = u.rstrip('),;]}')
        low = u.lower()
        if any((x in low for x in ('.png', '.jpg', '.jpeg', '.gif', '.svg', '.css', '.woff', '.ico'))):
            continue
        if u not in seen:
            seen.add(u)
            out.append(u)
    out.sort(key=lambda u: (0 if any((x in u.lower() for x in ('api', 'data', 'market', 'metric', 'battle', 'liquid', 'order', 'flow', 'future', 'btc'))) else 1, len(u)))
    return out[:_V216_MAX_URLS]

def _v216_extract_headers(raw):
    """Conservative parser for common literal auth headers in pasted fetch snippets."""
    raw = str(raw or '')
    headers = {'Accept': 'application/json', 'User-Agent': 'BookmapKing-NewHedge/21.6', 'Cache-Control': 'no-cache'}
    patterns = {'Authorization': '[\\"\\\']Authorization[\\"\\\']\\s*:\\s*[\\"\\\']([^\\"\\\']+)', 'X-API-Key': '[\\"\\\'](?:X-API-Key|x-api-key)[\\"\\\']\\s*:\\s*[\\"\\\']([^\\"\\\']+)', 'Api-Key': '[\\"\\\'](?:Api-Key|api-key)[\\"\\\']\\s*:\\s*[\\"\\\']([^\\"\\\']+)'}
    for key, pat in patterns.items():
        m = re.search(pat, raw, flags=re.I)
        if m:
            headers[key] = m.group(1).strip()
    return headers

def _v216_parse_payload_bytes(body):
    if isinstance(body, bytes):
        body = body.decode('utf-8', errors='ignore')
    text = str(body or '').strip()
    if not text:
        return None
    try:
        return json.loads(text)
    except Exception:
        return _v213_extract_json_payload(text)

def _v216_payload_hash(payload):
    try:
        s = json.dumps(payload, sort_keys=True, separators=(',', ':'), ensure_ascii=False)
    except Exception:
        s = repr(payload)
    return hash(s)

def _v216_flatten_metrics(payload, max_nodes=3200):
    """Extract directional metrics from unknown NewHedge-style JSON without double-counting giant history arrays."""
    votes = []
    labels = []
    source_roots = set()
    stack = [('', payload)]
    seen = 0
    while stack and seen < max_nodes:
        prefix, obj = stack.pop()
        seen += 1
        if isinstance(obj, dict):
            for k, v in list(obj.items())[:450]:
                stack.append(((prefix + '.' + str(k)).strip('.'), v))
            continue
        if isinstance(obj, list):
            if len(obj) > 14 and all((isinstance(x, (list, tuple)) and len(x) >= 2 for x in obj[:8])):
                try:
                    a, b = (obj[-2], obj[-1])
                    va = float(a[1])
                    vb = float(b[1])
                    scale = max(abs(va), abs(vb), 1.0)
                    d = max(-1.0, min(1.0, (vb - va) / scale * 25.0))
                    if abs(d) >= 0.03:
                        votes.append((d, 0.75, prefix or 'series_delta'))
                        labels.append((prefix or 'series_delta').split('.')[-1])
                except Exception:
                    pass
                continue
            for i, v in enumerate(obj[:160]):
                stack.append((f'{prefix}[{i}]', v))
            continue
        key = prefix.lower()
        leaf = prefix.split('.')[-1].split('[')[0] if prefix else 'value'
        root = prefix.split('.')[0] if prefix else 'root'
        source_roots.add(root)
        if isinstance(obj, bool):
            continue
        if isinstance(obj, str):
            s = obj.strip().lower()
            bull = any((x in s for x in ('bullish', 'strong buy', 'buying', 'buyers', 'long bias', 'uptrend', 'above target', 'up')))
            bear = any((x in s for x in ('bearish', 'strong sell', 'selling', 'sellers', 'short bias', 'downtrend', 'below target', 'down')))
            if bull != bear and any((x in key for x in ('bias', 'direction', 'trend', 'signal', 'state', 'side', 'pressure', 'winner'))):
                v = 1.0 if bull else -1.0
                votes.append((v, 0.72, leaf))
                labels.append(leaf)
                continue
            try:
                n = float(s.replace('%', '').replace(',', ''))
            except Exception:
                continue
        else:
            try:
                n = float(obj)
            except Exception:
                continue
        if not math.isfinite(n):
            continue
        if any((x in key for x in ('timestamp', 'epoch', 'unix', 'price', 'target', 'strike', 'id', 'latency', 'time_ms', 'time_seconds'))):
            continue
        val = None
        weight = 1.0
        if any((x in key for x in ('bull_probability', 'bull_prob', 'bullish_probability', 'up_probability', 'up_prob', 'bull_percent', 'bullish_percent', 'up_percent', 'long_percent', 'long_ratio'))):
            if 0 <= n <= 1:
                val = (n - 0.5) * 2
            elif 0 <= n <= 100:
                val = (n - 50.0) / 50.0
            weight = 1.25
        elif any((x in key for x in ('bear_probability', 'bear_prob', 'bearish_probability', 'down_probability', 'down_prob', 'bear_percent', 'bearish_percent', 'down_percent', 'short_percent', 'short_ratio'))):
            if 0 <= n <= 1:
                val = -(n - 0.5) * 2
            elif 0 <= n <= 100:
                val = -(n - 50.0) / 50.0
            weight = 1.25
        elif any((x in key for x in ('probability', 'prob', 'chance', 'confidence'))):
            if any((x in key for x in ('up', 'bull', 'buy', 'long'))):
                val = (n - 0.5) * 2 if 0 <= n <= 1 else (n - 50.0) / 50.0 if 0 <= n <= 100 else None
            elif any((x in key for x in ('down', 'bear', 'sell', 'short'))):
                val = -((n - 0.5) * 2 if 0 <= n <= 1 else (n - 50.0) / 50.0 if 0 <= n <= 100 else 0)
            weight = 1.15
        elif any((x in key for x in ('delta', 'imbalance', 'pressure', 'momentum', 'flow', 'cvd', 'slope', 'velocity', 'accel', 'net', 'bias', 'score', 'strength', 'wall_balance', 'buy_sell'))):
            if -1.25 <= n <= 1.25:
                val = n
            elif -100 <= n <= 100:
                val = n / 100.0
            else:
                val = math.tanh(n / 25.0)
            weight = 1.0
        if val is not None:
            val = max(-1.0, min(1.0, float(val)))
            if abs(val) >= 0.025:
                votes.append((val, weight, leaf))
                labels.append(leaf)
    best = {}
    for v, w, label in votes:
        key = str(label).lower()
        cur = best.get(key)
        if cur is None or abs(v * w) > abs(cur[0] * cur[1]):
            best[key] = (v, w, label)
    vals = sorted(best.values(), key=lambda x: abs(x[0] * x[1]), reverse=True)[:28]
    return (vals, tuple(labels[:16]), len(source_roots))

def _v216_live_quality_from_state(state, now=None):
    now = float(now or time.time())
    payload = state.get('payload')
    if payload is None:
        return {'ready': False, 'signed': 0.0, 'strength': 0.0, 'quality': 0.0, 'age': 99999.0, 'evidence': (), 'coverage': 0, 'agreement': 0.0, 'poll_health': 0.0, 'update_health': 0.0}
    vals, labels, source_breadth = _v216_flatten_metrics(payload)
    last_ok = float(state.get('last_ok_ts', 0) or 0)
    age = max(0.0, now - last_ok) if last_ok else 99999.0
    successes = int(state.get('successes', 0) or 0)
    failures = int(state.get('failures', 0) or 0)
    total = successes + failures
    poll_health = successes / max(1, total)
    freshness = 1.0 if age <= 1.7 else max(0.0, 1.0 - (age - 1.7) / 8.0)
    coverage = min(1.0, len(vals) / 8.0)
    if not vals:
        q = 0.42 * freshness * poll_health
        return {'ready': False, 'signed': 0.0, 'strength': 0.0, 'quality': q, 'age': age, 'evidence': tuple(labels[:8]), 'coverage': 0, 'agreement': 0.0, 'poll_health': poll_health, 'update_health': 0.0}
    denom = sum((w for _, w, _ in vals))
    raw = sum((v * w for v, w, _ in vals)) / max(denom, 1e-09)
    sign = 1 if raw >= 0 else -1
    agree = sum((w for v, w, _ in vals if v * sign >= 0.08)) / max(denom, 1e-09)
    hard = sum((1 for v, _, _ in vals if v * sign >= 0.3))
    change_count = int(state.get('change_count', 0) or 0)
    samples = max(1, int(state.get('successes', 0) or 0))
    recent_changes = list(state.get('change_times') or ())
    recent_changes = [t for t in recent_changes if now - float(t) <= 30.0]
    update_health = min(1.0, 0.35 + len(recent_changes) / 6.0) if samples >= 2 else 0.25
    breadth = min(1.0, max(source_breadth, len({x[2] for x in vals})) / 8.0)
    quality = 0.24 * freshness + 0.2 * poll_health + 0.2 * coverage + 0.18 * agree + 0.1 * update_health + 0.08 * breadth
    if successes < 2:
        quality *= 0.72
    quality = max(0.0, min(1.0, quality))
    signed = max(-1.0, min(1.0, raw * (0.82 + 0.34 * agree + 0.1 * min(1.0, hard / 3.0))))
    strength = min(100.0, abs(signed) * 100.0 * (0.72 + 0.34 * quality) + min(10.0, hard * 2.0))
    direction = 'UP' if signed > 0.035 else 'DOWN' if signed < -0.035 else 'NEUTRAL'
    evidence = tuple((f'{label}:{v:+.2f}' for v, w, label in vals[:10]))
    return {'ready': bool(freshness > 0.2 and poll_health > 0.2 and (coverage >= 0.125) and (quality >= 0.28)), 'direction': direction, 'signed': signed, 'strength': strength, 'quality': quality, 'age': age, 'evidence': evidence, 'coverage': coverage, 'agreement': agree, 'poll_health': poll_health, 'update_health': update_health, 'hard_metrics': hard, 'metric_count': len(vals), 'source_breadth': source_breadth}

def _v216_fetch_url(url, headers):
    req = urllib.request.Request(url, headers=dict(headers or {}), method='GET')
    with urllib.request.urlopen(req, timeout=_V216_FETCH_TIMEOUT) as r:
        body = r.read()
        return _v216_parse_payload_bytes(body)

def _v216_nh_worker(self):
    while not getattr(self, '_v216_nh_stop', False):
        try:
            state = getattr(self, '_v216_nh_live_state', None)
            if not isinstance(state, dict):
                time.sleep(_V216_POLL_INTERVAL)
                continue
            urls = list(state.get('urls') or ())
            if not urls:
                time.sleep(_V216_POLL_INTERVAL)
                continue
            headers = dict(state.get('headers') or {})
            fetched = None
            used_url = None
            last_error = ''
            for url in urls:
                try:
                    payload = _v216_fetch_url(url, headers)
                    if payload is not None:
                        fetched = payload
                        used_url = url
                        break
                except Exception as exc:
                    last_error = f'{type(exc).__name__}: {exc}'
            now = time.time()
            with getattr(self, '_v216_nh_lock', threading.Lock()):
                st = self._v216_nh_live_state
                st['last_attempt_ts'] = now
                if fetched is not None:
                    h = _v216_payload_hash(fetched)
                    if h != st.get('payload_hash'):
                        st['payload_hash'] = h
                        st['change_count'] = int(st.get('change_count', 0) or 0) + 1
                        ct = deque(st.get('change_times') or (), maxlen=40)
                        ct.append(now)
                        st['change_times'] = ct
                    st['payload'] = fetched
                    st['last_ok_ts'] = now
                    st['successes'] = int(st.get('successes', 0) or 0) + 1
                    st['active_url'] = used_url
                    st['last_error'] = ''
                    try:
                        for root in _v213_newhedge_payload_paths():
                            (root / 'newhedge-live-connected.json').write_text(json.dumps(fetched, ensure_ascii=False), encoding='utf-8')
                    except Exception:
                        pass
                else:
                    st['failures'] = int(st.get('failures', 0) or 0) + 1
                    st['last_error'] = last_error or 'No readable JSON response'
            try:
                self._v212_nh_cache = {'ts': 0.0, 'result': {}}
            except Exception:
                pass
        except Exception:
            pass
        time.sleep(_V216_POLL_INTERVAL)

def _v216_start_nh_connection(self, raw=None):
    raw = str(raw if raw is not None else getattr(self, 'newhedge_api_code_text', '') or '')
    urls = _v216_extract_urls(raw)
    headers = _v216_extract_headers(raw)
    payload = _v213_extract_json_payload(raw)
    lock = getattr(self, '_v216_nh_lock', None)
    if lock is None:
        lock = threading.Lock()
        self._v216_nh_lock = lock
    with lock:
        self._v216_nh_live_state = {'urls': urls, 'headers': headers, 'payload': payload, 'payload_hash': _v216_payload_hash(payload) if payload is not None else None, 'last_ok_ts': time.time() if payload is not None else 0.0, 'last_attempt_ts': 0.0, 'successes': 0, 'failures': 0, 'change_count': 0, 'change_times': deque(maxlen=40), 'active_url': '', 'last_error': '', 'submitted_ts': time.time()}
    t = getattr(self, '_v216_nh_thread', None)
    if t is None or not t.is_alive():
        self._v216_nh_stop = False
        self._v216_nh_thread = threading.Thread(target=_v216_nh_worker, args=(self,), daemon=True, name='NewHedgeLiveConnector')
        self._v216_nh_thread.start()
    return (urls, payload is not None)

def _v216_store_newhedge_api_code(self, raw):
    ok, msg = _V216_BASE_STORE_NEWHEDGE(self, raw)
    if not ok:
        return (ok, msg)
    urls, has_payload = _v216_start_nh_connection(self, raw)
    try:
        self._v212_nh_cache = {'ts': 0.0, 'result': {}}
    except Exception:
        pass
    if urls:
        return (True, f'NewHedge LIVE CONNECTOR armed • polling {len(urls)} endpoint(s) every {_V216_POLL_INTERVAL:.2f}s • measuring real freshness/quality.')
    if has_payload:
        return (True, 'NewHedge snapshot parsed, but no pollable endpoint URL was found in the pasted code. Snapshot is usable context; live quality will stay conservative until a live endpoint is submitted.')
    return (True, 'NewHedge code saved, but no readable JSON payload or pollable API URL was found.')

def _v216_live_read(self, now=None):
    now = float(now or time.time())
    lock = getattr(self, '_v216_nh_lock', None)
    state = getattr(self, '_v216_nh_live_state', None)
    if not isinstance(state, dict):
        return {'ready': False, 'direction': 'WAIT', 'signed': 0.0, 'strength': 0.0, 'quality': 0.0, 'age': 99999.0, 'evidence': (), 'reason': 'NewHedge live connector not armed'}
    try:
        if lock is not None:
            with lock:
                snap = dict(state)
                snap['change_times'] = list(state.get('change_times') or ())
        else:
            snap = dict(state)
    except Exception:
        snap = dict(state)
    out = _v216_live_quality_from_state(snap, now)
    urls = list(snap.get('urls') or ())
    out['url_count'] = len(urls)
    out['active_url'] = snap.get('active_url', '')
    out['successes'] = int(snap.get('successes', 0) or 0)
    out['failures'] = int(snap.get('failures', 0) or 0)
    out['last_error'] = snap.get('last_error', '')
    if not urls:
        out['reason'] = 'STATIC SNAPSHOT • no pollable URL in submitted code'
    elif out.get('ready'):
        out['reason'] = f"LIVE {out.get('direction', 'WAIT')} {float(out.get('strength', 0)):.0f}% • quality {float(out.get('quality', 0)) * 100:.0f}% • age {float(out.get('age', 0)):.1f}s • metrics {int(out.get('metric_count', 0))} • agreement {float(out.get('agreement', 0)) * 100:.0f}%"
    else:
        err = str(out.get('last_error', '') or '')
        out['reason'] = f"CONNECTING • q {float(out.get('quality', 0)) * 100:.0f}% • age {float(out.get('age', 99999)):.1f}s • ok/fail {out.get('successes', 0)}/{out.get('failures', 0)}" + (f' • {err[:90]}' if err else '')
    return out

def _v216_newhedge_future_read(self, now=None):
    now = float(now or time.time())
    base = _V216_BASE_NH_READ(self, now)
    live = _v216_live_read(self, now)
    if not live.get('ready'):
        out = dict(base)
        out['live_connector'] = live
        if not out.get('ready'):
            out['reason'] = live.get('reason', out.get('reason', 'waiting'))
        return out
    lq = max(0.0, min(1.0, float(live.get('quality', 0) or 0)))
    ls = max(-1.0, min(1.0, float(live.get('signed', 0) or 0)))
    b_ready = bool(base.get('ready'))
    bs = max(-1.0, min(1.0, float(base.get('signed', 0) or 0))) if b_ready else 0.0
    bq = max(0.0, min(1.0, float(base.get('quality', 0) or 0))) if b_ready else 0.0
    w_live = 4.4 + 3.8 * lq
    w_base = 0.65 + 0.95 * bq if b_ready else 0.0
    signed = (ls * w_live + bs * w_base) / max(w_live + w_base, 1e-09)
    agreement = not b_ready or ls * bs >= 0
    if agreement and abs(bs) >= 0.08:
        signed *= 1.05
    signed = max(-1.0, min(1.0, signed))
