    out = dict(base)
    out.update({'ready': True, 'direction': direction, 'signed': signed, 'strength': strength, 'quality': quality, 'age': float(live.get('age', 0) or 0), 'evidence': tuple(evidence), 'live_connector': live, 'reason': f"LIVE {direction} {strength:.0f}% strength • quality {quality * 100:.0f}% • fresh {float(live.get('age', 0)):.1f}s • agreement {float(live.get('agreement', 0)) * 100:.0f}% • metrics {int(live.get('metric_count', 0) or 0)}"})
    return out
