def _v217_balanced_chunks(text, opener, closer, limit=48):
    out = []
    stack = 0
    start = None
    quote = None
    esc = False
    for i, ch in enumerate(str(text or '')):
        if quote:
            if esc:
                esc = False
            elif ch == '\\':
                esc = True
            elif ch == quote:
                quote = None
            continue
        if ch in ("'", '"', '`'):
            quote = ch
            continue
        if ch == opener:
            if stack == 0:
                start = i
            stack += 1
        elif ch == closer and stack:
            stack -= 1
            if stack == 0 and start is not None:
                out.append(text[start:i + 1])
                if len(out) >= limit:
                    break
                start = None
    return out

def _v217_decode_js_string(token):
    token = str(token or '').strip()
    if len(token) < 2:
        return token
    try:
        return _v217_ast.literal_eval(token)
    except Exception:
        pass
    q = token[0]
    if q in ("'", '"') and token[-1] == q:
        s = token[1:-1]
        try:
            return bytes(s, 'utf-8').decode('unicode_escape')
        except Exception:
            return s
    return token

def _v217_parse_jsish(candidate):
    c = str(candidate or '').strip().rstrip(';')
    if not c:
        return None
    try:
        return json.loads(c)
    except Exception:
        pass
    py = c
    py = re.sub('\\btrue\\b', 'True', py, flags=re.I)
    py = re.sub('\\bfalse\\b', 'False', py, flags=re.I)
    py = re.sub('\\bnull\\b', 'None', py, flags=re.I)
    py = re.sub('\\bundefined\\b', 'None', py, flags=re.I)
    py = re.sub('([{\\[,]\\s*)([A-Za-z_$][A-Za-z0-9_$.\\-]*)(\\s*:)', "\\1'\\2'\\3", py)
    try:
        obj = _v217_ast.literal_eval(py)
        if isinstance(obj, (dict, list, tuple)):
            return list(obj) if isinstance(obj, tuple) else obj
    except Exception:
        pass
    return None

def _v217_extract_embed_payloads(raw):
    raw = str(raw or '')
    if not raw.strip():
        return []
    text = _v217_html.unescape(raw.replace('\\/', '/').replace('\\u0026', '&'))
    payloads = []
    seen = set()

    def add(obj):
        if not isinstance(obj, (dict, list)):
            return
        try:
            key = json.dumps(obj, sort_keys=True, default=str, ensure_ascii=False)[:200000]
        except Exception:
            key = repr(obj)[:200000]
        if key in seen:
            return
        seen.add(key)
        payloads.append(obj)
    add(_v217_parse_jsish(text))
    for body in re.findall('<script\\b[^>]*>(.*?)</script\\s*>', text, flags=re.I | re.S):
        body = body.strip()
        add(_v217_parse_jsish(body))
        for a, b in (('{', '}'), ('[', ']')):
            for chunk in _v217_balanced_chunks(body, a, b, 24):
                add(_v217_parse_jsish(chunk))
    for m in re.finditer('JSON\\.parse\\s*\\(\\s*((?:"(?:\\\\.|[^"\\\\])*")|(?:\\\'(?:\\\\.|[^\\\'\\\\])*\\\'))\\s*\\)', text, flags=re.I | re.S):
        decoded = _v217_decode_js_string(m.group(1))
        add(_v217_parse_jsish(decoded))
    for m in re.finditer('(?:window\\.)?[A-Za-z_$][A-Za-z0-9_$.\\[\\]\\\'"]*\\s*=\\s*', text):
        tail = text[m.end():]
        tail = tail.lstrip()
        if not tail:
            continue
        if tail[0] == '{':
            chunks = _v217_balanced_chunks(tail, '{', '}', 1)
        elif tail[0] == '[':
            chunks = _v217_balanced_chunks(tail, '[', ']', 1)
        else:
            chunks = []
        for chunk in chunks:
            add(_v217_parse_jsish(chunk))
    for a, b in (('{', '}'), ('[', ']')):
        for chunk in _v217_balanced_chunks(text, a, b, 48):
            add(_v217_parse_jsish(chunk))
    return payloads

def _v217_merge_embed_payloads(payloads):
    payloads = [p for p in payloads if isinstance(p, (dict, list))]
    if not payloads:
        return None
    if len(payloads) == 1:
        return payloads[0]
    return {f'NEWHEDGE_EMBED_{i + 1}': p for i, p in enumerate(payloads[:24])}

def _v217_extract_json_payload(raw):
    return _v217_merge_embed_payloads(_v217_extract_embed_payloads(raw))
_v213_extract_json_payload = _v217_extract_json_payload

def _v217_find_json_roots():
    roots = []
    try:
        roots.append(Path(__file__).resolve().parent)
    except Exception:
        pass
    try:
        roots.append(Path.home() / 'Downloads')
    except Exception:
        pass
    out = []
    seen = set()
    for root in roots:
        candidates = [root, root / 'newhedge_samples', root / 'NewHedge', root / 'newhedge', root / 'battlefield']
        try:
            candidates += [p for p in root.iterdir() if p.is_dir() and any((t in p.name.lower() for t in ('newhedge', 'battle', 'hedge')))]
        except Exception:
            pass
        for p in candidates:
            try:
                rp = p.resolve()
                if rp.exists() and str(rp) not in seen:
                    seen.add(str(rp))
                    out.append(rp)
            except Exception:
                pass
    return out
