def _v217_embed_quality(payload, submitted_ts=None):
    state = {'payload': payload, 'last_ok_ts': float(submitted_ts or time.time()), 'successes': 3, 'failures': 0, 'change_count': 1, 'change_times': [float(submitted_ts or time.time())]}
    base = _v216_live_quality_from_state(state, time.time())
    coverage = float(base.get('coverage', 0) or 0)
    agreement = float(base.get('agreement', 0) or 0)
    breadth = min(1.0, float(base.get('source_breadth', 0) or 0) / 6.0)
    metric_count = int(base.get('metric_count', 0) or 0)
    embed_q = min(0.92, 0.22 + 0.34 * coverage + 0.28 * agreement + 0.16 * breadth + min(0.12, metric_count * 0.01))
    base['quality'] = max(float(base.get('quality', 0) or 0) * 0.55, embed_q)
    base['strength'] = min(100.0, abs(float(base.get('signed', 0) or 0)) * 100.0 * (0.76 + 0.3 * base['quality']) + min(8.0, int(base.get('hard_metrics', 0) or 0) * 1.5))
    base['ready'] = bool(metric_count >= 2 and base['quality'] >= 0.34)
    base['source_mode'] = 'EMBED'
    return base

def _v217_start_nh_connection(self, raw=None):
    raw = str(raw if raw is not None else getattr(self, 'newhedge_api_code_text', '') or '')
    payloads = _v217_extract_embed_payloads(raw)
    payload = _v217_merge_embed_payloads(payloads)
    urls = _v216_extract_urls(raw)
    headers = _v216_extract_headers(raw)
    now = time.time()
    lock = getattr(self, '_v216_nh_lock', None)
    if lock is None:
        lock = threading.Lock()
        self._v216_nh_lock = lock
    with lock:
        self._v216_nh_live_state = {'urls': urls, 'headers': headers, 'payload': payload, 'payload_hash': _v216_payload_hash(payload) if payload is not None else None, 'last_ok_ts': now if payload is not None else 0.0, 'last_attempt_ts': 0.0, 'successes': 3 if payload is not None else 0, 'failures': 0, 'change_count': 1 if payload is not None else 0, 'change_times': deque([now], maxlen=40) if payload is not None else deque(maxlen=40), 'active_url': '', 'last_error': '', 'submitted_ts': now, 'embed_payload_count': len(payloads), 'source_mode': 'EMBED' if payload is not None else 'URL' if urls else 'NONE'}
    if urls:
        t = getattr(self, '_v216_nh_thread', None)
        if t is None or not t.is_alive():
            self._v216_nh_stop = False
            self._v216_nh_thread = threading.Thread(target=_v216_nh_worker, args=(self,), daemon=True, name='NewHedgeLiveConnector')
            self._v216_nh_thread.start()
    return (urls, payload is not None)

def _v217_store_newhedge_api_code(self, raw):
    raw = str(raw or '').strip()
    if not raw:
        return (False, 'Paste the NewHedge API/embed code first.')
    payloads = _v217_extract_embed_payloads(raw)
    payload = _v217_merge_embed_payloads(payloads)
    roots = _v213_newhedge_payload_paths()
    for root in roots:
        try:
            (root / 'BOOKMAP_KING_NEWHEDGE_API_CODE.txt').write_text(raw, encoding='utf-8')
        except Exception:
            pass
        if payload is not None:
            try:
                (root / 'newhedge-submitted-api.json').write_text(json.dumps(payload, ensure_ascii=False, indent=2), encoding='utf-8')
            except Exception:
                pass
    self.newhedge_api_code_text = raw
    self.newhedge_api_payload_ready = payload is not None
    urls, has_payload = _v217_start_nh_connection(self, raw)
    try:
        self._v212_nh_cache = {'ts': 0.0, 'result': {}}
        self._v211_nh_cache = {'ts': 0.0, 'result': {}}
    except Exception:
        pass
    if has_payload:
        return (True, f'NewHedge EMBED CONNECTED • parsed {len(payloads)} embedded data block(s) • URL NOT REQUIRED • NewHedge Mind refreshing now.')
    if urls:
        return (True, f'NewHedge endpoint connector armed • {len(urls)} endpoint(s).')
    return (True, 'NewHedge code saved, but no usable embedded data block was detected. Existing NewHedge JSON exports remain active.')

def _v217_live_read(self, now=None):
    now = float(now or time.time())
    lock = getattr(self, '_v216_nh_lock', None)
    state = getattr(self, '_v216_nh_live_state', None)
    if not isinstance(state, dict):
        return {'ready': False, 'direction': 'WAIT', 'signed': 0.0, 'strength': 0.0, 'quality': 0.0, 'age': 99999.0, 'evidence': (), 'reason': 'NewHedge Mind not armed'}
    try:
        if lock is not None:
            with lock:
                snap = dict(state)
                snap['change_times'] = list(state.get('change_times') or ())
        else:
            snap = dict(state)
    except Exception:
        snap = dict(state)
    urls = list(snap.get('urls') or ())
    mode = str(snap.get('source_mode', '')).upper()
    if snap.get('payload') is not None and (not urls):
        out = _v217_embed_quality(snap.get('payload'), snap.get('submitted_ts'))
        out.update({'url_count': 0, 'active_url': '', 'successes': int(snap.get('successes', 0) or 0), 'failures': int(snap.get('failures', 0) or 0), 'last_error': '', 'embed_payload_count': int(snap.get('embed_payload_count', 1) or 1), 'reason': f"EMBED CONNECTED • {int(snap.get('embed_payload_count', 1) or 1)} block(s) • {out.get('direction', 'WAIT')} {float(out.get('strength', 0)):.0f}% • quality {float(out.get('quality', 0)) * 100:.0f}% • metrics {int(out.get('metric_count', 0) or 0)} • URL NOT REQUIRED"})
        return out
    out = _v216_live_read(self, now)
    if out.get('ready'):
        out['source_mode'] = 'URL'
    return out

def _v217_newhedge_future_read(self, now=None):
    now = float(now or time.time())
    base = _V216_BASE_NH_READ(self, now)
    live = _v217_live_read(self, now)
    if not live.get('ready'):
        out = dict(base)
        out['live_connector'] = live
        if not out.get('ready'):
            out['reason'] = live.get('reason', out.get('reason', 'waiting'))
        return out
    lq = max(0.0, min(1.0, float(live.get('quality', 0) or 0)))
    ls = max(-1.0, min(1.0, float(live.get('signed', 0) or 0)))
    b_ready = bool(base.get('ready'))
    bs = max(-1.0, min(1.0, float(base.get('signed', 0) or 0))) if b_ready else 0.0
    bq = max(0.0, min(1.0, float(base.get('quality', 0) or 0))) if b_ready else 0.0
    mode = str(live.get('source_mode', '')).upper()
    w_live = 3.7 + 3.0 * lq if mode == 'EMBED' else 4.4 + 3.8 * lq
    w_base = 0.75 + 1.05 * bq if b_ready else 0.0
    signed = (ls * w_live + bs * w_base) / max(w_live + w_base, 1e-09)
    agree = not b_ready or ls * bs >= 0
    if agree and b_ready and (abs(bs) >= 0.08):
        signed *= 1.05
    signed = max(-1.0, min(1.0, signed))
    quality = min(1.0, 0.74 * lq + 0.16 * bq + (0.1 if agree and b_ready else 0.0))
    strength = min(100.0, abs(signed) * 100.0 * (0.8 + 0.28 * quality) + min(8.0, float(live.get('hard_metrics', 0) or 0) * 1.3))
    direction = 'UP' if signed > 0.035 else 'DOWN' if signed < -0.035 else 'NEUTRAL'
    evidence = list(live.get('evidence') or ())[:8]
    for e in list(base.get('evidence') or ())[:4]:
        if len(evidence) >= 10:
            break
        evidence.append('REGIME ' + str(e))
    out = dict(base)
    out.update({'ready': True, 'direction': direction, 'signed': signed, 'strength': strength, 'quality': quality, 'families': max(int(base.get('families', 0) or 0), 1) + 1, 'aligned_families': int(base.get('aligned_families', 0) or 0) + (1 if abs(ls) >= 0.08 else 0), 'evidence': tuple(evidence), 'live_connector': live, 'reason': f"{mode or 'NEWHEDGE'} {direction} {strength:.0f}% • quality {quality * 100:.0f}% • URL NOT REQUIRED" if mode == 'EMBED' else live.get('reason', 'LIVE')})
    return out

def _v217_opening_read_tick(self, warm, now=None):
    """OPEN/NOW is deliberately NOT a lock. Show the live Bookmap opinion and let it flip."""
    now = float(now or time.time())
    bucket = int(now // 900) * 900
    if getattr(self, 'opening_lock_bucket', None) != bucket:
        self.opening_lock_bucket = bucket
        self.opening_lock_snapshot = None
        self.opening_lock_candidate = None
        self.opening_lock_candidate_since = 0.0
        try:
            self.opening_lock_var.set('OPEN READ: FLUID • waiting for Bookmap')
        except Exception:
            pass
    self.opening_lock_snapshot = None
    self.opening_lock_candidate = None
    self.opening_lock_candidate_since = 0.0
    if not warm or not warm.get('ready'):
        try:
            self.opening_lock_var.set('OPEN READ: FLUID • waiting for Bookmap')
        except Exception:
            pass
        return None
    favored = str(warm.get('favored', 'WAIT')).upper()
    up = float(warm.get('up', 50) or 50)
    down = float(warm.get('down', 50) or 50)
    signed = float(warm.get('signed', 0) or 0)
    try:
        self.opening_lock_var.set(f'OPEN READ: {favored} • UP {up:.0f} / DOWN {down:.0f} • {signed:+.2f} • FREE TO FLIP')
    except Exception:
        pass
    return None

def _v217_sticky_real_lock(self):
    """Only a real timed checkpoint may become the defended Bookmap lock."""
    now = time.time()
    bucket = int(now // 900) * 900
    if getattr(self, '_survival_lock_bucket', None) != bucket:
        self._survival_lock_bucket = bucket
        self._survival_lock_snapshot = None
    existing = getattr(self, '_survival_lock_snapshot', None)
    if existing and str(existing.get('lock_side', 'WAIT')).upper() in ('UP', 'DOWN'):
        return dict(existing)
    candidates = []
    selected = self._selected_checkpoint_snapshot()
    if selected:
        candidates.append(selected)
    snaps = getattr(self, 'checkpoint_snapshots', {}) or {}
    for remaining in sorted(snaps.keys(), reverse=True):
        snap = snaps.get(remaining)
        if snap and snap not in candidates:
            candidates.append(snap)
    for snap in candidates:
        side = str(snap.get('lock_side', 'WAIT')).upper()
        if side not in ('UP', 'DOWN'):
            continue
        latched = dict(snap)
        latched['lock_side'] = side
        latched['survival_latched_ts'] = now
        latched['survival_latched_bucket'] = bucket
        latched['source'] = str(latched.get('source') or 'REAL TIMED CHECKPOINT')
        self._survival_lock_snapshot = latched
        return dict(latched)
    return None

