_V218_FAST_METRICS = {'funding-rate': ('bitcoin_funding_rate_binance', 'bitcoin_funding_rate_bybit', 'bitcoin_funding_rate_okx'), 'liquidations': ('bitcoin_liquidations_binance_short', 'bitcoin_liquidations_bybit_short', 'bitcoin_liquidations_binance_long', 'bitcoin_liquidations_bybit_long'), 'total-futures-open-interest': ('oi_binance_futures', 'oi_bybit_futures', 'oi_okx_futures'), 'cvd-dollars': ('bitcoin_cvd_dollars_binance', 'bitcoin_cvd_dollars_bybit', 'bitcoin_cvd_dollars_okx')}
_V218_API_SLUG = {'funding-rate': 'funding-rate', 'liquidations': 'liquidations', 'total-futures-open-interest': 'futures-open-interest', 'cvd-dollars': 'cvd-dollars'}
_V218_RES_SECONDS = {'10mn': 600.0, '30mn': 1800.0, 'hour1': 3600.0, 'hour4': 14400.0, 'hour12': 43200.0, 'day1': 86400.0}

def _v218_parse_exact_embeds(raw):
    raw = str(raw or '')
    found = {}
    for tag in re.findall('<div\\b[^>]*>', raw, flags=re.I | re.S):
        cm = re.search('data-chart\\s*=\\s*([\'\\"])(.*?)\\1', tag, flags=re.I | re.S)
        km = re.search('data-session-key\\s*=\\s*([\'\\"])(.*?)\\1', tag, flags=re.I | re.S)
        if not cm or not km:
            continue
        chart = cm.group(2).strip().lower()
        key = km.group(2).strip()
        if chart not in _V218_CHART_METRICS:
            continue
        if not re.fullmatch('[A-Za-z0-9_-]{20,64}', key):
            continue
        found[chart] = key
    return tuple(((chart, found[chart]) for chart in _V218_CHART_METRICS if chart in found))

def _v218_pairs(payload):
    out = []
    if isinstance(payload, list):
        for item in payload:
            if isinstance(item, (list, tuple)) and len(item) >= 2:
                try:
                    out.append((float(item[0]), float(item[1])))
                except Exception:
                    pass
            elif isinstance(item, dict):
                ts = item.get('timestamp_ms', item.get('timestamp', item.get('time')))
                val = item.get('value', item.get('close', item.get('y')))
                try:
                    out.append((float(ts), float(val)))
                except Exception:
                    pass
    elif isinstance(payload, dict):
        for key in ('data', 'series', 'values', 'result'):
            if key in payload:
                nested = _v218_pairs(payload[key])
                if nested:
                    return nested
        for k, v in payload.items():
            try:
                out.append((float(k), float(v)))
            except Exception:
                pass
    out.sort(key=lambda p: p[0])
    return out

def _v218_metric_url(chart, metric, key):
    slug = _V218_API_SLUG[chart]
    params = {'api_token': key, 'resolution': '10mn', 'limit': '48'}
    return 'https://newhedge.io/api/v2/metrics/' + urllib.parse.quote(slug, safe='') + '/' + urllib.parse.quote(metric, safe='') + '?' + urllib.parse.urlencode(params)

def _v218_fetch_metric(chart, metric, key):
    started = time.perf_counter()
    req = urllib.request.Request(_v218_metric_url(chart, metric, key), headers={'Accept': 'application/json', 'User-Agent': 'BookmapKing-NewHedgeBridge/21.8', 'Cache-Control': 'no-cache', 'Pragma': 'no-cache'}, method='GET')
    try:
        with urllib.request.urlopen(req, timeout=_V218_TIMEOUT) as r:
            payload = json.loads(r.read().decode('utf-8'))
            return {'ok': True, 'chart': chart, 'metric': metric, 'resolution': str(r.headers.get('X-Newhedge-Resolution') or 'day1').strip(), 'available': str(r.headers.get('X-Newhedge-Available-Resolutions') or '').strip(), 'pairs': _v218_pairs(payload), 'status': int(getattr(r, 'status', 200) or 200), 'rtt_ms': (time.perf_counter() - started) * 1000.0, 'error': ''}
    except _v218_urlerr.HTTPError as exc:
        return {'ok': False, 'chart': chart, 'metric': metric, 'pairs': (), 'resolution': '--', 'available': '', 'status': int(getattr(exc, 'code', 0) or 0), 'rtt_ms': (time.perf_counter() - started) * 1000.0, 'error': f"HTTP {getattr(exc, 'code', '?')}"}
    except Exception as exc:
        return {'ok': False, 'chart': chart, 'metric': metric, 'pairs': (), 'resolution': '--', 'available': '', 'status': 0, 'rtt_ms': (time.perf_counter() - started) * 1000.0, 'error': str(exc)[:160]}

def _v218_signal_from_pairs(pairs):
    pairs = list(pairs or ())
    if len(pairs) < 3:
        return (0.0, 0.0)
    vals = [float(v) for _, v in pairs[-18:]]
    diffs = [vals[i] - vals[i - 1] for i in range(1, len(vals))]
    hist = diffs[:-1] or diffs
    mags = sorted((abs(x) for x in hist if abs(x) > 1e-12))
    med = mags[len(mags) // 2] if mags else max(abs(diffs[-1]), 1.0)
    fast = diffs[-1] / max(med, 1e-12)
    mid = sum(diffs[-3:]) / max(1, min(3, len(diffs))) / max(med, 1e-12)
    slow = sum(diffs[-7:]) / max(1, min(7, len(diffs))) / max(med, 1e-12)
    z = 0.55 * fast + 0.3 * mid + 0.15 * slow
    signed = max(-1.0, min(1.0, math.tanh(z / 2.0)))
    strength = min(1.0, abs(z) / 2.5)
    return (signed, strength)

def _v218_freshness(read, now):
    pairs = read.get('pairs') or ()
    if not pairs:
        return (0.0, 999999.0)
    ts = float(pairs[-1][0])
    if ts > 1000000000000.0:
        ts /= 1000.0
    age = max(0.0, float(now) - ts)
    bucket = _V218_RES_SECONDS.get(str(read.get('resolution') or 'day1'), 86400.0)
    if age <= bucket * 1.3:
        return (1.0, age)
    return (max(0.0, 1.0 - (age - bucket * 1.3) / (bucket * 2.2)), age)

def _v218_chart_read(chart, metric_reads, now):
    reads = [r for r in metric_reads if r.get('ok') and r.get('pairs')]
    wanted = max(1, len(_V218_CHART_METRICS.get(chart, ())))
    coverage = min(1.0, len(reads) / wanted)
    if not reads:
        return {'ready': False, 'chart': chart, 'signed': 0.0, 'strength': 0.0, 'coverage': 0.0, 'agreement': 0.0, 'freshness': 0.0, 'resolution': '--', 'metrics': 0, 'rtt_ms': 9999.0}
    signs, strengths, fresh, rtts, resolutions = ([], [], [], [], [])
    latest = {}
    for r in reads:
        s, st = _v218_signal_from_pairs(r.get('pairs') or ())
        f, _ = _v218_freshness(r, now)
        signs.append(s)
        strengths.append(st)
        fresh.append(f)
        rtts.append(float(r.get('rtt_ms', 9999) or 9999))
        resolutions.append(str(r.get('resolution') or 'day1'))
        latest[str(r.get('metric'))] = float((r.get('pairs') or ((0, 0),))[-1][1])
    pos = sum((1 for s in signs if s > 0.03))
    neg = sum((1 for s in signs if s < -0.03))
    active = max(1, pos + neg)
    agreement = max(pos, neg) / active
    avg_signal = sum(signs) / max(1, len(signs))
    avg_strength = sum(strengths) / max(1, len(strengths))
    if chart == 'liquidations':
        shorts = sum((abs(v) for m, v in latest.items() if m.endswith('_short')))
        longs = sum((abs(v) for m, v in latest.items() if m.endswith('_long')))
        total = shorts + longs
        signed = (shorts - longs) / total if total > 0 else avg_signal
        strength = min(1.0, max(avg_strength, abs(signed) * 1.35))
    elif chart == 'funding-rate':
        signed = max(-0.65, min(0.65, -avg_signal * 0.55))
        strength = min(0.7, avg_strength)
    elif chart == 'total-futures-open-interest':
        signed = max(-0.35, min(0.35, avg_signal * 0.35))
        strength = min(0.65, avg_strength)
    else:
        signed = max(-1.0, min(1.0, avg_signal))
        strength = min(1.0, max(avg_strength, abs(signed)))
    rank = {'10mn': 0, '30mn': 1, 'hour1': 2, 'hour4': 3, 'hour12': 4, 'day1': 5}
    resolution = min(resolutions, key=lambda x: rank.get(x, 99)) if resolutions else '--'
    return {'ready': True, 'chart': chart, 'signed': signed, 'strength': strength, 'coverage': coverage, 'agreement': agreement, 'freshness': sum(fresh) / max(1, len(fresh)), 'resolution': resolution, 'metrics': len(reads), 'rtt_ms': sum(rtts) / max(1, len(rtts))}

def _v218_is_rollover_window(now, resolution='10mn'):
    bucket = _V218_RES_SECONDS.get(str(resolution), 600.0)
    if bucket > 3600.0:
        return False
    rem = bucket - now % bucket
    since = now % bucket
    return rem <= _V218_FAST_WINDOW_BEFORE or since <= _V218_FAST_WINDOW_AFTER

def _v218_bridge_read(self, now=None):
    now = float(now or time.time())
    lock = getattr(self, '_v218_lock', None)
    try:
        if lock:
            with lock:
                st = dict(getattr(self, '_v218_bridge_state', {}) or {})
        else:
            st = dict(getattr(self, '_v218_bridge_state', {}) or {})
    except Exception:
        st = dict(getattr(self, '_v218_bridge_state', {}) or {})
    embeds = tuple(st.get('embeds') or ())
    cache = dict(st.get('metric_cache') or {})
    charts = {}
    for chart, _ in embeds:
        reads = [r for (c, _m), r in cache.items() if c == chart]
        charts[chart] = _v218_chart_read(chart, reads, now)
    ready = [v for v in charts.values() if v.get('ready')]
    chart_coverage = len(ready) / 4.0
    metric_total = sum((int(v.get('metrics', 0) or 0) for v in ready))
    metric_goal = sum((len(v) for v in _V218_CHART_METRICS.values()))
    metric_coverage = min(1.0, metric_total / max(1, metric_goal))
    freshness = sum((float(v.get('freshness', 0) or 0) for v in ready)) / max(1, len(ready))
    agreement = sum((float(v.get('agreement', 0) or 0) for v in ready)) / max(1, len(ready))
    rtt = sum((float(v.get('rtt_ms', 9999) or 9999) for v in ready)) / max(1, len(ready))
    latency_score = max(0.0, min(1.0, 1.0 - rtt / 1800.0))
    successes = int(st.get('successes', 0) or 0)
    failures = int(st.get('failures', 0) or 0)
    health = successes / max(1, successes + failures)
    warmup = min(1.0, int(st.get('poll_count', 0) or 0) / 3.0)
    quality = (0.28 * health + 0.24 * chart_coverage + 0.13 * metric_coverage + 0.17 * freshness + 0.1 * agreement + 0.08 * latency_score) * warmup
    quality = max(0.0, min(1.0, quality))
    cvd = charts.get('cvd-dollars', {})
    liq = charts.get('liquidations', {})
    fund = charts.get('funding-rate', {})
    oi = charts.get('total-futures-open-interest', {})
    signed = 0.54 * float(cvd.get('signed', 0) or 0) + 0.29 * float(liq.get('signed', 0) or 0) + 0.11 * float(fund.get('signed', 0) or 0) + 0.06 * float(oi.get('signed', 0) or 0)
    signed *= 0.9 + 0.18 * float(oi.get('strength', 0) or 0)
    signed = max(-1.0, min(1.0, signed))
    strength = min(100.0, abs(signed) * 100.0 * (0.78 + 0.3 * quality))
    direction = 'UP' if signed > 0.035 else 'DOWN' if signed < -0.035 else 'NEUTRAL'
    last_ok = float(st.get('last_ok_ts', 0) or 0)
    age = max(0.0, now - last_ok) if last_ok else 999999.0
    ready_flag = bool(len(ready) >= 3 and quality >= 0.42 and (age <= max(35.0, _V218_NORMAL_POLL * 3.0)))
    evidence = []
    for name in ('cvd-dollars', 'liquidations', 'funding-rate', 'total-futures-open-interest'):
        c = charts.get(name, {})
        if c.get('ready'):
            side = 'UP' if c.get('signed', 0) > 0.03 else 'DOWN' if c.get('signed', 0) < -0.03 else 'NEUTRAL'
            evidence.append(f"{name} {side} {float(c.get('strength', 0)) * 100:.0f}% • {c.get('resolution', '--')} • fresh {float(c.get('freshness', 0)) * 100:.0f}% • {int(c.get('metrics', 0))} metrics")
    return {'ready': ready_flag, 'direction': direction, 'signed': signed, 'strength': strength, 'quality': quality, 'age': age, 'health': health, 'chart_coverage': chart_coverage, 'metric_coverage': metric_coverage, 'freshness': freshness, 'agreement': agreement, 'rtt_ms': rtt, 'charts': charts, 'evidence': tuple(evidence), 'embed_count': len(embeds), 'last_error': str(st.get('last_error', '') or ''), 'poll_count': int(st.get('poll_count', 0) or 0), 'reason': f'EXACT EMBED BRIDGE • {len(ready)}/4 charts • quality {quality * 100:.0f}% • strength {strength:.0f}% • health {health * 100:.0f}% • RTT {rtt:.0f}ms'}

def _v218_bridge_worker(self):
    last_full = 0.0
    while not getattr(self, '_v218_stop', False):
        now = time.time()
        state = getattr(self, '_v218_bridge_state', {}) or {}
        embeds = tuple(state.get('embeds') or ())
        if not embeds:
            time.sleep(1.0)
            continue
        full = now - last_full >= _V218_FULL_SWEEP_SECONDS
        tasks = []
        for chart, key in embeds:
            metrics = _V218_CHART_METRICS[chart] if full else _V218_FAST_METRICS[chart]
            for metric in metrics:
                tasks.append((chart, metric, key))
        fetched = []
        try:
            with _v218_cf.ThreadPoolExecutor(max_workers=min(12, max(1, len(tasks))), thread_name_prefix='NH218') as ex:
                futs = [ex.submit(_v218_fetch_metric, *t) for t in tasks]
                for fut in _v218_cf.as_completed(futs, timeout=max(_V218_TIMEOUT * 2.0, 7.0)):
                    try:
                        fetched.append(fut.result())
                    except Exception:
                        pass
        except Exception:
            pass
        if full:
            last_full = now
        lock = getattr(self, '_v218_lock', None)
        if lock is None:
            self._v218_lock = threading.Lock()
            lock = self._v218_lock
        with lock:
            st = dict(getattr(self, '_v218_bridge_state', {}) or {})
            cache = dict(st.get('metric_cache') or {})
            for r in fetched:
                key = (r.get('chart'), r.get('metric'))
                if r.get('ok'):
                    cache[key] = r
            st['metric_cache'] = cache
            st['last_poll_ts'] = time.time()
            st['last_full_ts'] = last_full
            st['poll_count'] = int(st.get('poll_count', 0) or 0) + 1
            oks = sum((1 for r in fetched if r.get('ok')))
            fails = sum((1 for r in fetched if not r.get('ok')))
            st['successes'] = int(st.get('successes', 0) or 0) + oks
            st['failures'] = int(st.get('failures', 0) or 0) + fails
            if oks:
                st['last_ok_ts'] = time.time()
            if fetched:
                st['last_rtt_ms'] = sum((float(r.get('rtt_ms', 0) or 0) for r in fetched)) / len(fetched)
            errors = [r.get('error') for r in fetched if not r.get('ok') and r.get('error')]
            st['last_error'] = errors[0] if errors else ''
            self._v218_bridge_state = st
        snap = _v218_bridge_read(self, time.time())
        resolutions = [c.get('resolution') for c in snap.get('charts', {}).values() if c.get('ready')]
        rank = {'10mn': 0, '30mn': 1, 'hour1': 2, 'hour4': 3, 'hour12': 4, 'day1': 5}
        fastest = min(resolutions, key=lambda x: rank.get(x, 99)) if resolutions else '10mn'
        delay = _V218_FAST_POLL if _v218_is_rollover_window(time.time(), fastest) else _V218_NORMAL_POLL
        time.sleep(delay)

def _v218_start_bridge(self, raw):
    embeds = _v218_parse_exact_embeds(raw)
    if not embeds:
        return (False, 'No supported NewHedge data-chart/data-session-key embeds found.')
    if not hasattr(self, '_v218_lock'):
        self._v218_lock = threading.Lock()
    with self._v218_lock:
        self._v218_bridge_state = {'embeds': embeds, 'metric_cache': {}, 'last_poll_ts': 0.0, 'last_ok_ts': 0.0, 'successes': 0, 'failures': 0, 'poll_count': 0, 'last_error': '', 'submitted_ts': time.time()}
    t = getattr(self, '_v218_thread', None)
    if t is None or not t.is_alive():
        self._v218_stop = False
        self._v218_thread = threading.Thread(target=_v218_bridge_worker, args=(self,), daemon=True, name='NewHedgeExactEmbedBridge')
        self._v218_thread.start()
    names = ', '.join((c for c, _ in embeds))
    return (True, f'NewHedge EXACT EMBED BRIDGE ARMED • {len(embeds)}/4 unique charts: {names} • duplicate embeds removed.')

def _v218_store_newhedge_api_code(self, raw):
    raw = str(raw or '').strip()
    if not raw:
        return (False, 'Paste the NewHedge embeds first.')
    embeds = _v218_parse_exact_embeds(raw)
    if embeds:
        for root in _v213_newhedge_payload_paths():
            try:
                (root / 'BOOKMAP_KING_NEWHEDGE_API_CODE.txt').write_text(raw, encoding='utf-8')
            except Exception:
                pass
        self.newhedge_api_code_text = raw
        self.newhedge_api_payload_ready = True
        ok, msg = _v218_start_bridge(self, raw)
        try:
            self._v212_nh_cache = {'ts': 0.0, 'result': {}}
            self._v211_nh_cache = {'ts': 0.0, 'result': {}}
        except Exception:
            pass
        return (ok, msg)
    return _V218_BASE_STORE(self, raw)

def _v218_newhedge_future_read(self, now=None):
    now = float(now or time.time())
    bridge = _v218_bridge_read(self, now)
    base = _V218_BASE_NH_FUTURE(self, now)
    if not bridge.get('ready'):
        out = dict(base)
        out['exact_embed_bridge'] = bridge
        if not out.get('ready'):
            out['reason'] = bridge.get('reason', out.get('reason', 'waiting'))
        return out
    bq = float(bridge.get('quality', 0) or 0)
    bs = float(bridge.get('signed', 0) or 0)
    base_ready = bool(base.get('ready'))
    rs = float(base.get('signed', 0) or 0) if base_ready else 0.0
    rq = float(base.get('quality', 0) or 0) if base_ready else 0.0
    wb = 5.4 + 3.2 * bq
    wr = 0.65 + 1.05 * rq if base_ready else 0.0
    signed = (bs * wb + rs * wr) / max(1e-09, wb + wr)
    if base_ready and bs * rs > 0 and (abs(rs) >= 0.06):
        signed *= 1.05
    signed = max(-1.0, min(1.0, signed))
    quality = min(1.0, 0.82 * bq + 0.12 * rq + (0.06 if base_ready and bs * rs >= 0 else 0.0))
    strength = min(100.0, abs(signed) * 100.0 * (0.8 + 0.29 * quality))
    direction = 'UP' if signed > 0.035 else 'DOWN' if signed < -0.035 else 'NEUTRAL'
    evidence = list(bridge.get('evidence') or ())
    for e in list(base.get('evidence') or ())[:3]:
        if len(evidence) >= 10:
            break
        evidence.append('REGIME ' + str(e))
    out = dict(base)
    out.update({'ready': True, 'direction': direction, 'signed': signed, 'strength': strength, 'quality': quality, 'families': max(4, int(base.get('families', 0) or 0)), 'aligned_families': max(1, int(base.get('aligned_families', 0) or 0)), 'evidence': tuple(evidence), 'exact_embed_bridge': bridge, 'reason': f"EXACT EMBED MIND {direction} {strength:.0f}% • quality {quality * 100:.0f}% • {int(bridge.get('chart_coverage', 0) * 4)}/4 charts • RTT {float(bridge.get('rtt_ms', 0)):.0f}ms"})
    return out

def _v218_thought_text(mm):
    obs, interp, decision, invalid = _V218_BASE_THOUGHT(mm)
    nh = dict((mm or {}).get('newhedge') or {})
    br = dict(nh.get('exact_embed_bridge') or {})
    if br:
        status = 'CONNECTED' if br.get('ready') else 'WARMING'
        prefix = f"EXACT NEWHEDGE BRIDGE: {status} • {int(br.get('chart_coverage', 0) * 4)}/4 charts • quality {float(br.get('quality', 0)) * 100:.0f}% • strength {float(br.get('strength', 0)):.0f}% • health {float(br.get('health', 0)) * 100:.0f}% • freshness {float(br.get('freshness', 0)) * 100:.0f}% • agreement {float(br.get('agreement', 0)) * 100:.0f}% • RTT {float(br.get('rtt_ms', 0)):.0f}ms"
        obs = prefix + ' | ' + obs
    return (obs, interp, decision, invalid)

def _v218_init(self, *args, **kwargs):
    _V218_BASE_INIT(self, *args, **kwargs)
    if not hasattr(self, '_v218_lock'):
        self._v218_lock = threading.Lock()
    try:
        raw = str(getattr(self, 'newhedge_api_code_text', '') or '')
        if _v218_parse_exact_embeds(raw):
            _v218_start_bridge(self, raw)
    except Exception:
        pass
    try:
        self.root.title('BOOKMAP KING V21.8 — EXACT NEWHEDGE EMBED BRIDGE + FLUID REAL LOCKS')
    except Exception:
        pass
