def _v219_browser_candidates():
    env = _v219_os.environ
    local = env.get('LOCALAPPDATA', '')
    pf = env.get('PROGRAMFILES', 'C:\\Program Files')
    pfx = env.get('PROGRAMFILES(X86)', 'C:\\Program Files (x86)')
    raw = [Path(local) / 'Microsoft/Edge/Application/msedge.exe' if local else None, Path(pf) / 'Microsoft/Edge/Application/msedge.exe', Path(pfx) / 'Microsoft/Edge/Application/msedge.exe', Path(local) / 'Google/Chrome/Application/chrome.exe' if local else None, Path(pf) / 'Google/Chrome/Application/chrome.exe', Path(pfx) / 'Google/Chrome/Application/chrome.exe']
    out = []
    for p in raw:
        try:
            if p and p.exists() and (str(p) not in out):
                out.append(str(p))
        except Exception:
            pass
    return out

def _v219_capture_script():
    return "\n<script>\n(function(){\n  const CAP=[];\n  function push(kind,url,text,res,avail){\n    try{\n      if(typeof text!=='string') text=String(text||'');\n      const t=text.trim();\n      if(!t || (t[0]!=='[' && t[0]!=='{')) return;\n      const obj=JSON.parse(t);\n      CAP.push({kind:String(kind||''),url:String(url||''),data:obj,\n        resolution:String(res||''),available:String(avail||''),captured_at:Date.now()});\n      if(CAP.length>100) CAP.shift();\n      const el=document.getElementById('nh-capture');\n      if(el) el.textContent='__NH_CAPTURE__'+JSON.stringify(CAP);\n    }catch(e){}\n  }\n  try{\n    const OF=window.fetch;\n    if(OF){\n      window.fetch=async function(){\n        const r=await OF.apply(this,arguments);\n        try{\n          const req=arguments[0], u=(req&&req.url)||req||r.url||'';\n          const c=r.clone();\n          c.text().then(t=>push('fetch',u,t,\n            r.headers.get('X-Newhedge-Resolution')||'',\n            r.headers.get('X-Newhedge-Available-Resolutions')||'')).catch(()=>{});\n        }catch(e){}\n        return r;\n      };\n    }\n  }catch(e){}\n  try{\n    const XO=XMLHttpRequest.prototype.open, XS=XMLHttpRequest.prototype.send;\n    XMLHttpRequest.prototype.open=function(method,url){this.__nh_url=url;return XO.apply(this,arguments);};\n    XMLHttpRequest.prototype.send=function(){\n      this.addEventListener('load',()=>{try{\n        push('xhr',this.__nh_url||'',this.responseText||'',\n          this.getResponseHeader('X-Newhedge-Resolution')||'',\n          this.getResponseHeader('X-Newhedge-Available-Resolutions')||'');\n      }catch(e){}});\n      return XS.apply(this,arguments);\n    };\n  }catch(e){}\n  try{\n    const WS=window.WebSocket;\n    if(WS){\n      window.WebSocket=function(url,protocols){\n        const ws=protocols?new WS(url,protocols):new WS(url);\n        ws.addEventListener('message',(ev)=>{try{\n          push('ws',url,typeof ev.data==='string'?ev.data:'','','');\n        }catch(e){}});\n        return ws;\n      };\n      window.WebSocket.prototype=WS.prototype;\n    }\n  }catch(e){}\n})();\n</script>\n"

def _v219_embed_page(chart, session_key):
    chart = _v219_html.escape(str(chart), quote=True)
    session_key = _v219_html.escape(str(session_key), quote=True)
    return "<!doctype html><html><head><meta charset='utf-8'>" + _v219_capture_script() + "</head><body><pre id='nh-capture'>__NH_CAPTURE__[]</pre>" + f"<div id='nh-chart-loader' data-chart='{chart}' data-session-key='{session_key}'></div>" + "<script src='https://newhedge.io/chart-asset/embed'></script>" + '</body></html>'

class _V219Handler(_v219_http.BaseHTTPRequestHandler):

    def do_GET(self):
        token = self.path.split('?', 1)[0].strip('/').split('/')[-1]
        with _V219_CAPTURE_LOCK:
            page = _V219_CAPTURE_PAGES.get(token)
        if page is None:
            self.send_response(404)
            self.end_headers()
            return
        raw = page.encode('utf-8')
        self.send_response(200)
        self.send_header('Content-Type', 'text/html; charset=utf-8')
        self.send_header('Cache-Control', 'no-store')
        self.send_header('Content-Length', str(len(raw)))
        self.end_headers()
        self.wfile.write(raw)

    def log_message(self, fmt, *args):
        return

def _v219_start_local_server(self):
    server = getattr(self, '_v219_http_server', None)
    if server is not None:
        return int(getattr(self, '_v219_http_port', 0) or 0)
    try:
        server = _v219_http.ThreadingHTTPServer(('127.0.0.1', 0), _V219Handler)
        self._v219_http_server = server
        self._v219_http_port = int(server.server_address[1])
        threading.Thread(target=server.serve_forever, daemon=True, name='NH219LocalServer').start()
        return self._v219_http_port
    except Exception as exc:
        self._v219_server_error = str(exc)
        return 0

def _v219_extract_capture_from_dom(dom):
    dom = str(dom or '')
    m = re.search('__NH_CAPTURE__(\\[.*?\\])</pre>', dom, flags=re.S)
    if not m:
        return []
    try:
        data = json.loads(_v219_html.unescape(m.group(1)))
        return data if isinstance(data, list) else []
    except Exception:
        return []

def _v219_series_candidates(obj, depth=0):
    if depth > 6:
        return []
    out = []
    pairs = _v218_pairs(obj)
    if len(pairs) >= 3:
        out.append((len(pairs), pairs))
    if isinstance(obj, dict):
        for v in list(obj.values())[:60]:
            if isinstance(v, (dict, list)):
                out.extend(_v219_series_candidates(v, depth + 1))
    elif isinstance(obj, list) and (not pairs):
        for v in obj[:30]:
            if isinstance(v, (dict, list)):
                out.extend(_v219_series_candidates(v, depth + 1))
    return out

def _v219_capture_chart(self, browser, port, chart, session_key):
    token = _v219_uuid.uuid4().hex
    with _V219_CAPTURE_LOCK:
        _V219_CAPTURE_PAGES[token] = _v219_embed_page(chart, session_key)
    profile = Path(_v219_tempfile.gettempdir()) / ('bkm_nh_' + token)
    url = f'http://127.0.0.1:{port}/nh/{token}'
    args = [browser, '--headless=new', '--disable-gpu', '--no-first-run', '--no-default-browser-check', '--disable-background-networking', '--disable-renderer-backgrounding', '--disable-background-timer-throttling', f'--user-data-dir={profile}', f'--virtual-time-budget={_V219_DOM_BUDGET_MS}', '--dump-dom', url]
    started = time.perf_counter()
    try:
        cp = _v219_subprocess.run(args, capture_output=True, text=True, timeout=_V219_CAPTURE_TIMEOUT, creationflags=getattr(_v219_subprocess, 'CREATE_NO_WINDOW', 0))
        captures = _v219_extract_capture_from_dom(cp.stdout or '')
        candidates = []
        for cap in captures:
            if isinstance(cap, dict):
                for n, pairs in _v219_series_candidates(cap.get('data')):
                    candidates.append((n, pairs, cap))
        candidates.sort(key=lambda x: x[0], reverse=True)
        if not candidates:
            return {'ok': False, 'chart': chart, 'pairs': (), 'resolution': '--', 'rtt_ms': (time.perf_counter() - started) * 1000.0, 'captures': len(captures), 'error': 'embed rendered but no series captured • ' + (cp.stderr or '')[-180:]}
        n, pairs, cap = candidates[0]
        return {'ok': True, 'chart': chart, 'pairs': pairs, 'resolution': str(cap.get('resolution') or '--'), 'available': str(cap.get('available') or ''), 'capture_kind': str(cap.get('kind') or ''), 'capture_url': str(cap.get('url') or ''), 'captures': len(captures), 'candidate_series': len(candidates), 'rtt_ms': (time.perf_counter() - started) * 1000.0, 'error': ''}
    except Exception as exc:
        return {'ok': False, 'chart': chart, 'pairs': (), 'resolution': '--', 'rtt_ms': (time.perf_counter() - started) * 1000.0, 'captures': 0, 'error': str(exc)[:220]}
    finally:
        with _V219_CAPTURE_LOCK:
            _V219_CAPTURE_PAGES.pop(token, None)
        try:
            shutil.rmtree(profile, ignore_errors=True)
        except Exception:
            pass

def _v219_bridge_read(self, now=None):
    now = float(now or time.time())
    lock = getattr(self, '_v219_lock', None)
    try:
        if lock:
            with lock:
                st = dict(getattr(self, '_v219_state', {}) or {})
        else:
            st = dict(getattr(self, '_v219_state', {}) or {})
    except Exception:
        st = dict(getattr(self, '_v219_state', {}) or {})
    reads = dict(st.get('reads') or {})
    charts = {}
    for chart in _V218_CHART_METRICS:
        r = reads.get(chart) or {}
        charts[chart] = _v218_chart_read(chart, [r], now) if r.get('ok') and r.get('pairs') else {'ready': False, 'signed': 0.0, 'strength': 0.0, 'freshness': 0.0, 'resolution': '--', 'metrics': 0, 'rtt_ms': float(r.get('rtt_ms', 9999) or 9999)}
    ready = [v for v in charts.values() if v.get('ready')]
    coverage = len(ready) / 4.0
    succ = int(st.get('successes', 0) or 0)
    fail = int(st.get('failures', 0) or 0)
    health = succ / max(1, succ + fail)
    freshness = sum((float(v.get('freshness', 0) or 0) for v in ready)) / max(1, len(ready))
    warmup = min(1.0, int(st.get('cycles', 0) or 0) / 2.0)
    quality = max(0.0, min(1.0, (0.42 * health + 0.36 * coverage + 0.22 * freshness) * warmup))
    cvd = charts.get('cvd-dollars', {})
    liq = charts.get('liquidations', {})
    fund = charts.get('funding-rate', {})
    oi = charts.get('total-futures-open-interest', {})
    signed = 0.56 * float(cvd.get('signed', 0) or 0) + 0.3 * float(liq.get('signed', 0) or 0) + 0.09 * float(fund.get('signed', 0) or 0) + 0.05 * float(oi.get('signed', 0) or 0)
    signed = max(-1.0, min(1.0, signed * (0.92 + 0.16 * float(oi.get('strength', 0) or 0))))
    strength = min(100.0, abs(signed) * 100.0 * (0.8 + 0.28 * quality))
    direction = 'UP' if signed > 0.035 else 'DOWN' if signed < -0.035 else 'NEUTRAL'
    last_ok = float(st.get('last_ok_ts', 0) or 0)
    age = max(0.0, now - last_ok) if last_ok else 999999.0
    errors = [str((reads.get(c) or {}).get('error')) for c in _V218_CHART_METRICS if (reads.get(c) or {}).get('error')]
    evidence = []
    for c in _V218_CHART_METRICS:
        rr = reads.get(c) or {}
        cc = charts.get(c) or {}
        if cc.get('ready'):
            side = 'UP' if cc.get('signed', 0) > 0.03 else 'DOWN' if cc.get('signed', 0) < -0.03 else 'NEUTRAL'
            evidence.append(f"{c} {side} {float(cc.get('strength', 0)) * 100:.0f}% • {cc.get('resolution', '--')} • {rr.get('capture_kind', '?')}")
    return {'ready': bool(len(ready) >= 3 and quality >= 0.35 and (age <= 60)), 'direction': direction, 'signed': signed, 'strength': strength, 'quality': quality, 'chart_coverage': coverage, 'health': health, 'freshness': freshness, 'age': age, 'evidence': tuple(evidence), 'browser': Path(str(st.get('browser', '') or '')).name, 'last_error': errors[0] if errors else str(st.get('last_error', '') or ''), 'reason': f'TRUE EMBED SESSION • {len(ready)}/4 charts • quality {quality * 100:.0f}% • strength {strength:.0f}%'}

def _v219_worker(self):
    while not getattr(self, '_v219_stop', False):
        st = getattr(self, '_v219_state', {}) or {}
        embeds = tuple(st.get('embeds') or ())
        browser = str(st.get('browser', '') or '')
        port = int(getattr(self, '_v219_http_port', 0) or 0)
        if not embeds or not browser or (not port):
            time.sleep(1.0)
            continue
        results = []
        try:
            with _v218_cf.ThreadPoolExecutor(max_workers=4) as ex:
                futs = [ex.submit(_v219_capture_chart, self, browser, port, c, k) for c, k in embeds]
                for fut in _v218_cf.as_completed(futs, timeout=_V219_CAPTURE_TIMEOUT + 4):
                    try:
                        results.append(fut.result())
                    except Exception:
                        pass
        except Exception:
            pass
        lock = getattr(self, '_v219_lock', None) or threading.Lock()
        self._v219_lock = lock
        with lock:
            cur = dict(getattr(self, '_v219_state', {}) or {})
            reads = dict(cur.get('reads') or {})
            oks = fails = 0
            errs = []
            for r in results:
                if r.get('ok'):
                    reads[r.get('chart')] = r
                    oks += 1
                else:
                    fails += 1
                    if r.get('error'):
                        errs.append(str(r.get('error')))
            cur['reads'] = reads
            cur['cycles'] = int(cur.get('cycles', 0) or 0) + 1
            cur['successes'] = int(cur.get('successes', 0) or 0) + oks
            cur['failures'] = int(cur.get('failures', 0) or 0) + fails
            if oks:
                cur['last_ok_ts'] = time.time()
            cur['last_error'] = errs[0] if errs else ''
            self._v219_state = cur
        snap = _v219_bridge_read(self, time.time())
        time.sleep(3.0 if not snap.get('ready') or _v218_is_rollover_window(time.time(), '10mn') else 12.0)

def _v219_start_bridge(self, raw):
    embeds = _v218_parse_exact_embeds(raw)
    if not embeds:
        return (False, 'No supported exact NewHedge embeds found.')
    browsers = _v219_browser_candidates()
    if not browsers:
        return (False, 'TRUE EMBED BRIDGE: Microsoft Edge/Chrome executable not found.')
    port = _v219_start_local_server(self)
    if not port:
        return (False, 'TRUE EMBED BRIDGE: localhost capture server failed • ' + str(getattr(self, '_v219_server_error', 'unknown')))
    self._v219_lock = getattr(self, '_v219_lock', None) or threading.Lock()
    with self._v219_lock:
        self._v219_state = {'embeds': embeds, 'browser': browsers[0], 'reads': {}, 'cycles': 0, 'successes': 0, 'failures': 0, 'last_ok_ts': 0.0, 'last_error': ''}
    t = getattr(self, '_v219_thread', None)
    if t is None or not t.is_alive():
        self._v219_stop = False
        self._v219_thread = threading.Thread(target=_v219_worker, args=(self,), daemon=True, name='NHTrueEmbedBridge')
        self._v219_thread.start()
    return (True, f'TRUE EMBED BRIDGE ARMED • {len(embeds)}/4 charts • {Path(browsers[0]).name} • session-key kept as embed session, NOT api_token')

def _v219_store_newhedge_api_code(self, raw):
    raw = str(raw or '').strip()
    if not raw:
        return (False, 'Paste the NewHedge embeds first.')
    if _v218_parse_exact_embeds(raw):
        for root in _v213_newhedge_payload_paths():
            try:
                (root / 'BOOKMAP_KING_NEWHEDGE_API_CODE.txt').write_text(raw, encoding='utf-8')
            except Exception:
                pass
        self.newhedge_api_code_text = raw
        self.newhedge_api_payload_ready = True
        return _v219_start_bridge(self, raw)
    return _V219_BASE_STORE(self, raw)

def _v219_newhedge_future_read(self, now=None):
    now = float(now or time.time())
    br = _v219_bridge_read(self, now)
    try:
        base = _V216_BASE_NH_READ(self, now)
    except Exception:
        base = {}
    if not br.get('ready'):
        out = dict(base)
        out['true_embed_bridge'] = br
        if not out.get('ready'):
            out.update({'ready': False, 'direction': 'WAIT', 'signed': 0.0, 'strength': 0.0, 'quality': 0.0, 'reason': br.get('last_error') or br.get('reason', 'embed warming')})
        return out
    bq = float(br.get('quality', 0) or 0)
    bs = float(br.get('signed', 0) or 0)
    rr = bool(base.get('ready'))
    rs = float(base.get('signed', 0) or 0) if rr else 0.0
    rq = float(base.get('quality', 0) or 0) if rr else 0.0
    signed = (bs * (6.5 + 3 * bq) + rs * (0.65 + 0.8 * rq if rr else 0)) / max(1e-09, 6.5 + 3 * bq + (0.65 + 0.8 * rq if rr else 0))
    signed = max(-1.0, min(1.0, signed))
    quality = min(1.0, 0.9 * bq + 0.08 * rq + (0.02 if rr and bs * rs >= 0 else 0))
    strength = min(100.0, abs(signed) * 100.0 * (0.82 + 0.28 * quality))
    direction = 'UP' if signed > 0.035 else 'DOWN' if signed < -0.035 else 'NEUTRAL'
    out = dict(base)
    out.update({'ready': True, 'direction': direction, 'signed': signed, 'strength': strength, 'quality': quality, 'evidence': tuple(list(br.get('evidence') or ()) + list(base.get('evidence') or ())[:2]), 'true_embed_bridge': br, 'reason': f'TRUE EMBED MIND {direction} {strength:.0f}% • quality {quality * 100:.0f}%'})
    return out

def _v219_paper_authority(mm, auth):
    ms = str(auth.get('mastermind', 'WAIT')).upper()
    me = str(auth.get('mastermind_early', ms)).upper()
    mscore = float(auth.get('mastermind_score', 0) or 0)
    bs = str(auth.get('breakout', 'WAIT')).upper()
    stage = str(auth.get('breakout_stage', 'NONE')).upper()
    bscore = float(auth.get('breakout_score', 0) or 0)
    ns = str(auth.get('newhedge', 'WAIT')).upper()
    nq = float(auth.get('newhedge_quality', 0) or 0)
    nstr = float(auth.get('newhedge_strength', 0) or 0)
    if auth.get('all_three') and auth.get('stable_for_entry'):
        return (str(auth.get('side', 'WAIT')).upper(), '3/3 AUTHORITY')
    if auth.get('two_strong') and auth.get('stable_for_entry'):
        return (str(auth.get('side', 'WAIT')).upper(), '2/3 STRONG AUTHORITY')
    if ms in ('UP', 'DOWN') and me == ms and (mscore >= 78) and (bs == ms) and (stage in ('LIKELY', 'CONFIRMED')) and (bscore >= 74):
        return (ms, 'EASY MARKET • MM + BREAKOUT MAN')
    if bool(mm.get('straight_shot')) and ms in ('UP', 'DOWN') and (me == ms) and (mscore >= 82) and (bs == ms) and (stage in ('FORMING', 'LIKELY', 'CONFIRMED')) and (bscore >= 62):
        return (ms, 'STRAIGHT SHOT • MM + BREAKOUT MAN')
    if ns == ms and ms in ('UP', 'DOWN') and (me == ms) and (mscore >= 80) and (nq >= 0.38 or nstr >= 10):
        return (ms, 'NEWHEDGE + MASTERMIND')
    return ('WAIT', '')

def _v219_auto_paper_tick(self, warm=None, sig=None, candles=None, now=None, mode='LIVE'):
    if not self.auto_paper_enabled_var.get():
        return False
    if self.paper_active_trade is not None:
        try:
            return _V214_BASE_AUTO(self, warm=warm, sig=sig, candles=candles, now=now, mode=mode)
        except Exception:
            return False
    now = float(now or time.time())
    if now - float(getattr(self, '_v219_last_entry_eval', 0) or 0) < 0.1:
        return False
    self._v219_last_entry_eval = now
    bucket = int(now // 900) * 900
    if self.auto_paper_last_bucket == bucket:
        return False
    mm = _v214_mm3_read(self, warm=warm, sig=sig, candles=candles, now=now)
    self._v19_last_mm = mm
    auth = _v215_authority_read(self, mm=mm, sig=sig, candles=candles, now=now)
    side, lane = _v219_paper_authority(mm, auth)
    if side not in ('UP', 'DOWN'):
        try:
            self._set_var_if_changed(self.auto_paper_reason_var, f"WAIT • MM {auth['mastermind']} {auth['mastermind_score']:.0f} early {auth['mastermind_early']} • BO {auth['breakout']} {auth['breakout_stage']} {auth['breakout_score']:.0f} • NH {auth['newhedge']} q{auth['newhedge_quality'] * 100:.0f}%")
        except Exception:
            pass
        return False
    px, _, _, _ = self._kalshi_paper_price(side, 'ENTER', max_age=3.0)
    if px is None or float(px) > _V219_HARD_MAX_ENTRY:
        try:
            self._set_var_if_changed(self.auto_paper_reason_var, f'{lane}: ' + ('BLOCKED • no ask' if px is None else f'HARD BLOCK • {float(px) * 100:.1f}¢ > 75¢'))
        except Exception:
            pass
        return False
    mm2 = _v214_mm3_read(self, sig=sig, candles=candles, now=time.time())
    auth2 = _v215_authority_read(self, mm=mm2, sig=sig, candles=candles, now=time.time())
    side2, lane2 = _v219_paper_authority(mm2, auth2)
    if side2 != side:
        return False
    px2, _, _, _ = self._kalshi_paper_price(side, 'ENTER', max_age=3.0)
    if px2 is None or float(px2) > _V219_HARD_MAX_ENTRY:
        return False
    opened = self._paper_open(side, entry_source='AUTO', auto_score=float(mm2.get('settlement_score', 0) or 0), auto_reason=f'{lane2 or lane} • {float(px2) * 100:.1f}¢ • 75¢ HARD MAX')
    if opened:
        self.auto_paper_last_bucket = bucket
        try:
            self._set_var_if_changed(self.auto_paper_score_var, f'ENTERED {side} • {lane2 or lane} • {float(px2) * 100:.1f}¢')
            self._set_var_if_changed(self.auto_paper_reason_var, f"{lane2 or lane} • MM {auth2['mastermind']} • BO {auth2['breakout']} {auth2['breakout_stage']} • NH {auth2['newhedge']}")
        except Exception:
            pass
    return bool(opened)

def _v219_paper_open(self, direction, entry_source='MANUAL', auto_score=None, auto_reason=None):
    if str(entry_source).upper() == 'AUTO':
        try:
            px, _, _, _ = self._kalshi_paper_price(str(direction).upper(), 'ENTER', max_age=3.0)
        except Exception:
            px = None
        if px is None or float(px) > _V219_HARD_MAX_ENTRY:
            return False
    return _V219_BASE_PAPER_OPEN(self, direction, entry_source=entry_source, auto_score=auto_score, auto_reason=auto_reason)

def _v219_thought_text(mm):
    obs, interp, decision, invalid = _V219_BASE_THOUGHT(mm)
    br = dict(((mm or {}).get('newhedge') or {}).get('true_embed_bridge') or {})
    if br:
        obs = f"TRUE NEWHEDGE EMBED: {('CONNECTED' if br.get('ready') else 'DIAGNOSTIC')} • {int(br.get('chart_coverage', 0) * 4)}/4 charts • quality {float(br.get('quality', 0)) * 100:.0f}% • strength {float(br.get('strength', 0)):.0f}% • browser {br.get('browser', '--')} • error {str(br.get('last_error', '') or '--')[:120]} | " + obs
    return (obs, interp, decision, invalid)

def _v219_init(self, *args, **kwargs):
    _V219_BASE_INIT(self, *args, **kwargs)
    self._v219_lock = getattr(self, '_v219_lock', None) or threading.Lock()
    try:
        raw = str(getattr(self, 'newhedge_api_code_text', '') or '')
        if _v218_parse_exact_embeds(raw):
            _v219_start_bridge(self, raw)
    except Exception:
        pass
    try:
        self.root.title('BOOKMAP KING V21.9 — TRUE NEWHEDGE EMBED + PAPER ENTRY RESTORE')
    except Exception:
        pass
