def _v2110_embed_names(raw):
    raw = str(raw or '')
    names = []
    for m in re.finditer('data-chart\\s*=\\s*[\'\\"]([^\'\\"]+)[\'\\"]', raw, flags=re.I):
        name = m.group(1).strip().lower()
        if name and name not in names:
            names.append(name)
    return tuple(names)

def _v2110_store_newhedge_api_code(self, raw):
    raw = str(raw or '').strip()
    if not raw:
        return (False, 'Paste the NewHedge embeds/code first.')
    names = _v2110_embed_names(raw)
    payload = _v213_extract_json_payload(raw)
    for root in _v213_newhedge_payload_paths():
        try:
            (root / 'BOOKMAP_KING_NEWHEDGE_API_CODE.txt').write_text(raw, encoding='utf-8')
        except Exception:
            pass
        if payload is not None:
            try:
                (root / 'newhedge-submitted-api.json').write_text(json.dumps(payload, ensure_ascii=False, indent=2), encoding='utf-8')
            except Exception:
                pass
    self.newhedge_api_code_text = raw
    self.newhedge_api_payload_ready = payload is not None
    self._v2110_embed_charts = names
    try:
        self._v219_stop = True
        self._v218_stop = True
    except Exception:
        pass
    try:
        self._v212_nh_cache = {'ts': 0.0, 'result': {}}
        self._v211_nh_cache = {'ts': 0.0, 'result': {}}
    except Exception:
        pass
    if names:
        return (True, 'NewHedge embeds recognized: ' + ', '.join(names) + ' • known-good NewHedge reader restored • browser bridge OFF')
    if payload is not None:
        return (True, 'NewHedge JSON payload parsed • known-good NewHedge reader refreshed.')
    return (True, 'NewHedge code saved • known-good export/live-JSON reader active.')
