_V213_BASE_PAPER_FINALIZE = ChartKingPro._paper_finalize_active
_V213_HARD_MAX_ENTRY = 0.75
_V213_CANDLE_COUNT = 10
_V213_CANDLE_FEATURES = 6
_V213_CONTEXT_FEATURES = 8
_V213_FEATURE_COUNT = _V213_CANDLE_COUNT * _V213_CANDLE_FEATURES + _V213_CONTEXT_FEATURES
_V213_H1 = 24
_V213_H2 = 8
_V213_REPLAY_MAX = 320

def _v213_model_path():
    try:
        return Path.home() / 'Downloads' / 'BOOKMAP_KING_MASTERMIND_NEURAL.json'
    except Exception:
        return Path('BOOKMAP_KING_MASTERMIND_NEURAL.json')

def _v213_clamp(x, lo=-1.0, hi=1.0):
    try:
        return max(lo, min(hi, float(x)))
    except Exception:
        return 0.0

def _v213_sigmoid(x):
    x = max(-24.0, min(24.0, float(x)))
    return 1.0 / (1.0 + math.exp(-x))

def _v213_new_model(seed=21313):
    rng = random.Random(seed)

    def mat(rows, cols, scale):
        return [[rng.uniform(-scale, scale) for _ in range(cols)] for __ in range(rows)]
    return {'version': 2, 'feature_count': _V213_FEATURE_COUNT, 'w1': mat(_V213_H1, _V213_FEATURE_COUNT, 0.075), 'b1': [0.0] * _V213_H1, 'w2': mat(_V213_H2, _V213_H1, 0.075), 'b2': [0.0] * _V213_H2, 'w3': [rng.uniform(-0.075, 0.075) for _ in range(_V213_H2)], 'b3': 0.0, 'markets_trained': 0, 'snapshots_trained': 0, 'trade_reinforcements': 0, 'wins_seen': 0, 'losses_seen': 0, 'last_loss': None, 'replay': []}

def _v213_valid_model(m):
    try:
        return isinstance(m, dict) and int(m.get('feature_count', 0)) == _V213_FEATURE_COUNT and (len(m.get('w1', [])) == _V213_H1) and (len(m.get('w2', [])) == _V213_H2) and (len(m.get('w3', [])) == _V213_H2)
    except Exception:
        return False

def _v213_lazy_model(self):
    m = getattr(self, '_v213_neural_model', None)
    if _v213_valid_model(m):
        return m
    try:
        raw = json.loads(_v213_model_path().read_text(encoding='utf-8'))
        m = raw if _v213_valid_model(raw) else _v213_new_model()
    except Exception:
        m = _v213_new_model()
    self._v213_neural_model = m
    if not hasattr(self, '_v213_market_memory'):
        self._v213_market_memory = {}
    if not hasattr(self, '_v213_mm_commit'):
        self._v213_mm_commit = {}
    return m

def _v213_save_model(self):
    m = _v213_lazy_model(self)
    try:
        p = _v213_model_path()
        tmp = p.with_suffix('.json.tmp')
        tmp.write_text(json.dumps(m, ensure_ascii=False, separators=(',', ':')), encoding='utf-8')
        tmp.replace(p)
    except Exception:
        pass

def _v213_forward(m, x):
    h1 = []
    for row, b in zip(m['w1'], m['b1']):
        z = float(b) + sum((float(w) * float(v) for w, v in zip(row, x)))
        h1.append(math.tanh(z))
    h2 = []
    for row, b in zip(m['w2'], m['b2']):
        z = float(b) + sum((float(w) * float(v) for w, v in zip(row, h1)))
        h2.append(math.tanh(z))
    z3 = float(m['b3']) + sum((float(w) * float(v) for w, v in zip(m['w3'], h2)))
    return (_v213_sigmoid(z3), h1, h2)

def _v213_train_one(m, x, y, lr=0.01):
    y = 1.0 if y else 0.0
    p, h1, h2 = _v213_forward(m, x)
    dz3 = max(-1.0, min(1.0, p - y))
    old_w3 = list(m['w3'])
    old_w2 = [list(r) for r in m['w2']]
    for k in range(_V213_H2):
        g = dz3 * h2[k] + 0.00045 * float(m['w3'][k])
        m['w3'][k] = _v213_clamp(float(m['w3'][k]) - lr * g, -2.5, 2.5)
    m['b3'] = _v213_clamp(float(m['b3']) - lr * dz3, -2.5, 2.5)
    d2 = []
    for k in range(_V213_H2):
        dz = dz3 * old_w3[k] * (1.0 - h2[k] * h2[k])
        d2.append(dz)
        for j in range(_V213_H1):
            g = dz * h1[j] + 0.00035 * float(m['w2'][k][j])
            m['w2'][k][j] = _v213_clamp(float(m['w2'][k][j]) - lr * g, -2.5, 2.5)
        m['b2'][k] = _v213_clamp(float(m['b2'][k]) - lr * dz, -2.5, 2.5)
    for j in range(_V213_H1):
        dz = sum((d2[k] * old_w2[k][j] for k in range(_V213_H2)))
        dz *= 1.0 - h1[j] * h1[j]
        for i in range(_V213_FEATURE_COUNT):
            g = dz * float(x[i]) + 0.00025 * float(m['w1'][j][i])
            m['w1'][j][i] = _v213_clamp(float(m['w1'][j][i]) - lr * g, -2.5, 2.5)
        m['b1'][j] = _v213_clamp(float(m['b1'][j]) - lr * dz, -2.5, 2.5)
    loss = -(y * math.log(max(p, 1e-08)) + (1.0 - y) * math.log(max(1.0 - p, 1e-08)))
    m['last_loss'] = float(loss)
    m['snapshots_trained'] = int(m.get('snapshots_trained', 0) or 0) + 1
    return float(loss)

def _v213_replay_learn(self, examples, market_count=0, trade_reinforcement=False):
    m = _v213_lazy_model(self)
    valid = []
    for ex in examples or []:
        try:
            x = [float(v) for v in ex['x']]
            y = 1 if bool(ex['y']) else 0
            if len(x) == _V213_FEATURE_COUNT:
                valid.append({'x': x, 'y': y})
        except Exception:
            pass
    if not valid:
        return
    replay = list(m.get('replay') or [])
    replay.extend(valid)
    replay = replay[-_V213_REPLAY_MAX:]
    m['replay'] = replay
    losses = []
    for ex in valid:
        losses.append(_v213_train_one(m, ex['x'], ex['y'], lr=0.012 if not trade_reinforcement else 0.006))
    rng = random.Random(int(time.time()) // 15 + int(m.get('snapshots_trained', 0)))
    if replay:
        batch = [replay[rng.randrange(len(replay))] for _ in range(min(18, len(replay)))]
        for ex in batch:
            losses.append(_v213_train_one(m, ex['x'], ex['y'], lr=0.0045))
    if market_count:
        m['markets_trained'] = int(m.get('markets_trained', 0) or 0) + int(market_count)
        if valid[-1]['y']:
            m['wins_seen'] = int(m.get('wins_seen', 0) or 0) + 1
        else:
            m['losses_seen'] = int(m.get('losses_seen', 0) or 0) + 1
    if trade_reinforcement:
        m['trade_reinforcements'] = int(m.get('trade_reinforcements', 0) or 0) + 1
    if losses:
        m['last_loss'] = sum(losses) / len(losses)
    _v213_save_model(self)

def _v213_candle_features(candles, target=None, now=None, raw_mm=None, bo=None, nh=None):
    rows = list(candles or [])
    now = float(now or time.time())
    usable = []
    for c in rows[-40:]:
        try:
            usable.append({'time': float(c.get('time', 0) or 0), 'open': float(c['open']), 'high': float(c['high']), 'low': float(c['low']), 'close': float(c['close'])})
        except Exception:
            pass
    if not usable:
        return None
    recent = usable[-20:]
    ranges = [max(0.01, r['high'] - r['low']) for r in recent]
    atr = sum(ranges[-14:]) / max(1, min(14, len(ranges)))
    atr = max(0.01, atr)
    chosen = usable[-_V213_CANDLE_COUNT:]
    pad = _V213_CANDLE_COUNT - len(chosen)
    feats = [0.0] * (pad * _V213_CANDLE_FEATURES)
    prev_close = chosen[0]['open'] if chosen else usable[-1]['open']
    for c in chosen:
        rng = max(0.01, c['high'] - c['low'])
        body = (c['close'] - c['open']) / atr
        upper = (c['high'] - max(c['open'], c['close'])) / atr
        lower = (min(c['open'], c['close']) - c['low']) / atr
        rr = rng / atr
        loc = (c['close'] - c['low']) / rng * 2.0 - 1.0
        ret = (c['close'] - prev_close) / atr
        feats.extend([_v213_clamp(body), _v213_clamp(rr), _v213_clamp(upper), _v213_clamp(lower), _v213_clamp(loc), _v213_clamp(ret)])
        prev_close = c['close']
    last = usable[-1]
    if target is None:
        target_dist = 0.0
    else:
        try:
            target_dist = (last['close'] - float(target)) / atr
        except Exception:
            target_dist = 0.0
    bucket = int(now // 900) * 900
    elapsed = max(0.0, min(900.0, now - bucket))
    time_pos = elapsed / 450.0 - 1.0
    raw_mm = dict(raw_mm or {})
    bo = dict(bo or {})
    nh = dict(nh or {})
    bo_side = str(bo.get('side', 'WAIT')).upper()
    bo_signed = 1.0 if bo_side == 'UP' else -1.0 if bo_side == 'DOWN' else 0.0
    nh_signed = _v213_clamp(nh.get('signed', 0))
    mm_signed = _v213_clamp(raw_mm.get('settlement_signed', raw_mm.get('future_signed', 0)))
    trajectory = _v213_clamp(float(raw_mm.get('trajectory', 0) or 0) * 10.0)
    geo = dict(raw_mm.get('settlement_geometry') or {})
    geo_signed = _v213_clamp(geo.get('signed', 0))
    tail = usable[-5:]
    trend = _v213_clamp((tail[-1]['close'] - tail[0]['open']) / max(atr * 2.5, 0.01)) if tail else 0.0
    expansion = _v213_clamp(ranges[-1] / max(sum(ranges[-6:]) / max(1, min(6, len(ranges))), 0.01) - 1.0)
    feats.extend([_v213_clamp(target_dist / 3.0), _v213_clamp(time_pos), mm_signed, bo_signed, nh_signed, trajectory, geo_signed, _v213_clamp(0.65 * trend + 0.35 * expansion)])
    if len(feats) != _V213_FEATURE_COUNT:
        return None
    return feats

def _v213_model_probability(self, x):
    m = _v213_lazy_model(self)
    if not x or len(x) != _V213_FEATURE_COUNT:
        return (0.5, 0.0)
    p, _, _ = _v213_forward(m, x)
    n = int(m.get('markets_trained', 0) or 0)
    trust = min(0.9, 0.1 + n / 70.0)
    calibrated = 0.5 + (float(p) - 0.5) * trust
    return (max(0.01, min(0.99, calibrated)), trust)

def _v213_raw_side(raw):
    raw = dict(raw or {})
    side = str(raw.get('settlement_side', raw.get('future_side', raw.get('side', 'WAIT')))).upper()
    if side in ('UP', 'DOWN'):
        return side
    signed = float(raw.get('settlement_signed', raw.get('future_signed', 0)) or 0)
    if signed > 0.02:
        return 'UP'
    if signed < -0.02:
        return 'DOWN'
    return 'WAIT'

def _v213_mm3_read(self, warm=None, sig=None, candles=None, now=None):
    now = float(now or time.time())
    raw = dict(_V213_BASE_RAW_MM(self, warm=warm, sig=sig, candles=candles, now=now) or {})
    early = _v213_raw_side(raw)
    st = dict(getattr(self, '_v213_mm_commit', {}) or {})
    committed = str(st.get('committed', 'WAIT')).upper()
    candidate = str(st.get('candidate', 'WAIT')).upper()
    if committed not in ('UP', 'DOWN'):
        if early in ('UP', 'DOWN'):
            if candidate != early:
                st = {'committed': 'WAIT', 'candidate': early, 'candidate_since': now}
            age = max(0.0, now - float(st.get('candidate_since', now)))
            if age >= 0.42:
                committed = early
                st = {'committed': committed, 'candidate': 'WAIT', 'candidate_since': 0.0, 'commit_ts': now}
    elif early == committed or early == 'WAIT':
        st['candidate'] = 'WAIT'
        st['candidate_since'] = 0.0
    else:
        if candidate != early:
            st['candidate'] = early
            st['candidate_since'] = now
        age = max(0.0, now - float(st.get('candidate_since', now)))
        phase = str(raw.get('flip_phase', 'NONE')).upper()
        flip_to = str(raw.get('flip_to', 'WAIT')).upper()
        needed = 0.72 if phase == 'CONFIRMED' and flip_to == early else 1.05
        if bool(raw.get('straight_shot')):
            needed = min(needed, 0.55)
        if age >= needed:
            committed = early
            st = {'committed': committed, 'candidate': 'WAIT', 'candidate_since': 0.0, 'commit_ts': now}
    self._v213_mm_commit = st
    raw['early_side'] = early
    raw['committed_side'] = committed if committed in ('UP', 'DOWN') else early
    raw['raw_settlement_side'] = early
    raw['score_used_for_entry'] = False
    if committed in ('UP', 'DOWN'):
        raw['side'] = committed
        raw['future_side'] = committed
        raw['settlement_side'] = committed
    return raw

def _v213_market_learning_tick(self, raw_mm, sig=None, candles=None, now=None):
    now = float(now or time.time())
    candles = list(candles or getattr(self, '_last_analysis_candles', None) or [])
    if not candles:
        return
    m = _v213_lazy_model(self)
    bucket = int(now // 900) * 900
    try:
        target, _ = self.effective_target()
    except Exception:
        target = getattr(self, 'target_price', None)
    try:
        bo = _v215_breakout_read(self, mm=raw_mm, sig=sig, candles=candles, now=now)
    except Exception:
        bo = {}
    nh = dict(raw_mm.get('newhedge') or {})
    x = _v213_candle_features(candles, target=target, now=now, raw_mm=raw_mm, bo=bo, nh=nh)
    if x is None:
        return
    mem = getattr(self, '_v213_market_memory', None)
    if not isinstance(mem, dict):
        mem = {}
        self._v213_market_memory = mem
    current = mem.get(bucket)
    if current is None:
        current = {'bucket': bucket, 'target': float(target) if target is not None else None, 'snapshots': [], 'last_snap_ts': 0.0}
        mem[bucket] = current
    elif current.get('target') is None and target is not None:
        current['target'] = float(target)
    if now - float(current.get('last_snap_ts', 0) or 0) >= 45.0 and len(current['snapshots']) < 16:
        current['snapshots'].append({'ts': now, 'x': list(x)})
        current['last_snap_ts'] = now
    completed = [b for b in list(mem) if b < bucket]
    for b in sorted(completed):
        rec = mem.get(b) or {}
        tgt = rec.get('target')
        snaps = list(rec.get('snapshots') or [])
        close = None
        for c in candles:
            try:
                ct = float(c.get('time', 0) or 0)
                if b <= ct < b + 900:
                    close = float(c['close'])
            except Exception:
                pass
        if tgt is not None and close is not None and snaps:
            up = bool(close >= float(tgt))
            examples = [{'x': s['x'], 'y': 1 if up else 0} for s in snaps if len(s.get('x', [])) == _V213_FEATURE_COUNT]
            if examples:
                _v213_replay_learn(self, examples, market_count=1, trade_reinforcement=False)
                self._v213_last_learning = f"NEURAL LEARNED MARKET {time.strftime('%H:%M', time.localtime(b))} • {('UP' if up else 'DOWN')} • {len(examples)} chart snapshots • total {int(m.get('markets_trained', 0) or 0)} markets"
        mem.pop(b, None)
    for b in sorted(list(mem))[:-4]:
        mem.pop(b, None)

def _v213_convergence(self, mm, sig=None, candles=None, now=None):
    now = float(now or time.time())
    candles = list(candles or getattr(self, '_last_analysis_candles', None) or [])
    side = str(mm.get('settlement_side', 'WAIT')).upper()
    if side not in ('UP', 'DOWN'):
        return {'locked': False, 'side': 'WAIT', 'reason': 'MM has no persistent side'}
    try:
        target, _ = self.effective_target()
    except Exception:
        target = getattr(self, 'target_price', None)
    try:
        bo = _v215_breakout_read(self, mm=mm, sig=sig, candles=candles, now=now)
    except Exception:
        bo = {}
    nh = dict(mm.get('newhedge') or {})
    x = _v213_candle_features(candles, target=target, now=now, raw_mm=mm, bo=bo, nh=nh)
    p_up, trust = _v213_model_probability(self, x)
    neural_side = 'UP' if p_up >= 0.55 else 'DOWN' if p_up <= 0.45 else 'WAIT'
    neural_agree = neural_side == side
    neural_oppose = neural_side in ('UP', 'DOWN') and neural_side != side
    bo_side = str(bo.get('side', 'WAIT')).upper()
    bo_stage = str(bo.get('stage', 'NONE')).upper()
    bo_agree = bo_side == side and bo_stage in ('FORMING', 'LIKELY', 'CONFIRMED')
    bo_oppose = bo_side in ('UP', 'DOWN') and bo_side != side and (bo_stage in ('LIKELY', 'CONFIRMED'))
    nh_side = str(nh.get('direction', 'WAIT')).upper()
    nh_ready = bool(nh.get('ready'))
    nh_agree = nh_ready and nh_side == side
    nh_oppose = nh_ready and nh_side in ('UP', 'DOWN') and (nh_side != side) and (float(nh.get('quality', 0) or 0) >= 0.45)
    candle_side = 'WAIT'
    candle_strength = 0.0
    if x:
        cs = float(x[-1])
        candle_strength = abs(cs)
        if cs > 0.1:
            candle_side = 'UP'
        elif cs < -0.1:
            candle_side = 'DOWN'
    candle_agree = candle_side == side
    candle_oppose = candle_side in ('UP', 'DOWN') and candle_side != side and (candle_strength >= 0.28)
    flip_to = str(mm.get('flip_to', 'WAIT')).upper()
    flip_phase = str(mm.get('flip_phase', 'NONE')).upper()
    opposing = 'DOWN' if side == 'UP' else 'UP'
    if flip_to == opposing and flip_phase in ('LIKELY', 'CONFIRMED'):
        self._v213_entry_lock = {}
        return {'locked': False, 'side': side, 'reason': f'opposing MM flip {flip_phase}', 'p_up': p_up}
    votes = 0
    votes += 1 if candle_agree else 0
    votes += 1 if bo_agree else 0
    votes += 1 if nh_agree else 0
    votes += 1 if neural_agree else 0
    contradictions = 0
    contradictions += 1 if candle_oppose else 0
    contradictions += 1 if bo_oppose else 0
    contradictions += 1 if nh_oppose else 0
    contradictions += 1 if neural_oppose and trust >= 0.3 else 0
    state = dict(getattr(self, '_v213_entry_lock', {}) or {})
    signature = (side, candle_side, bo_side if bo_stage != 'NONE' else 'WAIT', nh_side if nh_ready else 'WAIT', neural_side)
    if state.get('side') != side or state.get('signature') != signature:
        state = {'side': side, 'signature': signature, 'since': now, 'samples': 1}
    else:
        state['samples'] = int(state.get('samples', 0) or 0) + 1
    self._v213_entry_lock = state
    held = max(0.0, now - float(state.get('since', now)))
    if votes >= 3 and contradictions == 0:
        needed = 0.42
    elif votes >= 2 and contradictions == 0:
        needed = 0.78
    elif votes >= 3 and contradictions == 1:
        needed = 1.1
    else:
        needed = 999.0
    if bool(mm.get('straight_shot')) and votes >= 2 and (contradictions == 0):
        needed = min(needed, 0.34)
    locked = held >= needed and int(state.get('samples', 0) or 0) >= 2
    prob_for_side = p_up if side == 'UP' else 1.0 - p_up
    return {'locked': bool(locked), 'side': side, 'votes': votes, 'contradictions': contradictions, 'held': held, 'needed': needed, 'p_up': p_up, 'neural_for_side': prob_for_side, 'neural_trust': trust, 'candle_side': candle_side, 'breakout_side': bo_side, 'breakout_stage': bo_stage, 'newhedge_side': nh_side if nh_ready else 'WAIT', 'neural_side': neural_side, 'reason': f"{votes}/4 independent agrees • {contradictions} oppose • held {held:.2f}/{(needed if needed < 900 else 0):.2f}s • candles {candle_side} • BO {bo_side} {bo_stage} • NH {(nh_side if nh_ready else 'WAIT')} • neural {prob_for_side * 100:.0f}% for {side}"}

def _v213_auto_paper_tick(self, warm=None, sig=None, candles=None, now=None, mode='LIVE'):
    now = float(now or time.time())
    candles = list(candles or getattr(self, '_last_analysis_candles', None) or [])
    _v213_lazy_model(self)
    try:
        raw_for_learning = _v213_mm3_read(self, warm=warm, sig=sig, candles=candles, now=now)
        _v213_market_learning_tick(self, raw_for_learning, sig=sig, candles=candles, now=now)
    except Exception:
        raw_for_learning = None
    if not self.auto_paper_enabled_var.get():
        return False
    if self.paper_active_trade is not None:
        try:
            return _V213_BASE_AUTO_FOR_ACTIVE(self, warm=warm, sig=sig, candles=candles, now=now, mode=mode)
        except Exception:
            return False
    if now - float(getattr(self, '_v213_last_entry_eval', 0) or 0) < 0.1:
        return False
    self._v213_last_entry_eval = now
    bucket = int(now // 900) * 900
    if self.auto_paper_last_bucket == bucket:
        return False
    mm = raw_for_learning or _v213_mm3_read(self, warm=warm, sig=sig, candles=candles, now=now)
    self._v19_last_mm = mm
    conv = _v213_convergence(self, mm, sig=sig, candles=candles, now=now)
    if not conv.get('locked'):
        try:
            m = _v213_lazy_model(self)
            self._set_var_if_changed(self.auto_paper_reason_var, 'WAIT • NO SCORE GATE • ' + conv.get('reason', 'evidence not converged'))
            self._set_var_if_changed(self.auto_paper_score_var, f"NEURAL MM • {int(m.get('markets_trained', 0) or 0)} markets learned • UP {float(conv.get('p_up', 0.5)) * 100:.0f}% / DOWN {(1 - float(conv.get('p_up', 0.5))) * 100:.0f}%")
        except Exception:
            pass
        return False
    side = str(conv.get('side', 'WAIT')).upper()
    px, _, _, _ = self._kalshi_paper_price(side, 'ENTER', max_age=3.0)
    if px is None:
        return False
    if float(px) > _V213_HARD_MAX_ENTRY:
        try:
            self._set_var_if_changed(self.auto_paper_reason_var, f'MM LEARNED LOCK {side} • HARD BLOCK {float(px) * 100:.1f}¢ > 75¢')
        except Exception:
            pass
        return False
    mm2 = _v213_mm3_read(self, sig=sig, candles=candles, now=time.time())
    conv2 = _v213_convergence(self, mm2, sig=sig, candles=candles, now=time.time())
    if not conv2.get('locked') or str(conv2.get('side', '')).upper() != side:
        return False
    px2, _, _, _ = self._kalshi_paper_price(side, 'ENTER', max_age=3.0)
    if px2 is None or float(px2) > _V213_HARD_MAX_ENTRY:
        return False
    opened = self._paper_open(side, entry_source='AUTO', auto_score=None, auto_reason=f"NEURAL MM CONVERGENCE • NO SCORE GATE • {conv2.get('reason', '')} • {float(px2) * 100:.1f}¢ • 75¢ HARD MAX")
    if opened:
        self.auto_paper_last_bucket = bucket
        try:
            target, _ = self.effective_target()
        except Exception:
            target = getattr(self, 'target_price', None)
        try:
            bo = _v215_breakout_read(self, mm=mm2, sig=sig, candles=candles, now=time.time())
        except Exception:
            bo = {}
        x = _v213_candle_features(candles, target=target, now=time.time(), raw_mm=mm2, bo=bo, nh=dict(mm2.get('newhedge') or {}))
        try:
            if isinstance(self.paper_active_trade, dict):
                self.paper_active_trade['_v213_neural_x'] = list(x) if x else None
                self.paper_active_trade['_v213_neural_side'] = side
                self.paper_active_trade['_v213_neural_p_up'] = float(conv2.get('p_up', 0.5))
        except Exception:
            pass
        try:
            self._set_var_if_changed(self.auto_paper_score_var, f'ENTERED {side} • LEARNED CONVERGENCE • NO SCORE GATE • {float(px2) * 100:.1f}¢')
            self._set_var_if_changed(self.auto_paper_reason_var, f"MM LOCK • {conv2.get('reason', '')}")
        except Exception:
            pass
    return bool(opened)

def _v213_paper_open(self, direction, entry_source='MANUAL', auto_score=None, auto_reason=None):
    if str(entry_source).upper() == 'AUTO':
        try:
            px, _, _, _ = self._kalshi_paper_price(str(direction).upper(), 'ENTER', max_age=3.0)
        except Exception:
            px = None
        if px is None or float(px) > _V213_HARD_MAX_ENTRY:
            return False
    return _V213_BASE_PAPER_OPEN(self, direction, entry_source=entry_source, auto_score=auto_score, auto_reason=auto_reason)

def _v213_paper_finalize(self, exit_yes=None, market_result=None, reason='CLOSED'):
    trade = dict(getattr(self, 'paper_active_trade', {}) or {})
    x = trade.get('_v213_neural_x')
    side = str(trade.get('_v213_neural_side', trade.get('direction', 'WAIT'))).upper()
    label_up = None
    mr = str(market_result).lower() if market_result is not None else None
    if mr in ('yes', 'no'):
        label_up = mr == 'yes'
    elif exit_yes is not None and side in ('UP', 'DOWN'):
        try:
            entry_contract = float(trade.get('entry_contract', 0.5))
            exit_contract = float(exit_yes) if side == 'UP' else 1.0 - float(exit_yes)
            trade_won = exit_contract > entry_contract
            label_up = trade_won if side == 'UP' else not trade_won
        except Exception:
            label_up = None
    result = _V213_BASE_PAPER_FINALIZE(self, exit_yes=exit_yes, market_result=market_result, reason=reason)
    if isinstance(x, list) and len(x) == _V213_FEATURE_COUNT and (label_up is not None):
        try:
            _v213_replay_learn(self, [{'x': x, 'y': 1 if label_up else 0}], market_count=0, trade_reinforcement=True)
            m = _v213_lazy_model(self)
            self._v213_last_learning = f"NEURAL REINFORCED FROM TRADE • {('UP' if label_up else 'DOWN')} pattern • {int(m.get('trade_reinforcements', 0) or 0)} trade reinforcements"
        except Exception:
            pass
    return result
ChartKingPro._auto_paper_unified_tick = _v213_auto_paper_tick
ChartKingPro._paper_open = _v213_paper_open
ChartKingPro._paper_finalize_active = _v213_paper_finalize
_v214_mm3_read = _v213_mm3_read
_V215_HARD_MAX_ENTRY = 0.75
_V215_BASE_MM_READER = _v213_mm3_read
_V215_BASE_ACTIVE_PAPER_TICK = _V213_BASE_AUTO_FOR_ACTIVE

def _v215_mm_reader_fast_commit(self, warm=None, sig=None, candles=None, now=None):
    """
    Scoreless persistent MM side reader.
    Faster initial commitment; only real directional disagreement can force a
    re-commit. Numeric MM score is diagnostic only.
    """
    now = float(now or time.time())
    raw = dict(_V213_BASE_RAW_MM(self, warm=warm, sig=sig, candles=candles, now=now) or {})
    early = _v213_raw_side(raw)
    st = dict(getattr(self, '_v215_mm_commit_state', {}) or {})
    committed = str(st.get('committed', 'WAIT')).upper()
    candidate = str(st.get('candidate', 'WAIT')).upper()
    if committed not in ('UP', 'DOWN'):
        if early in ('UP', 'DOWN'):
            if candidate != early:
                st = {'committed': 'WAIT', 'candidate': early, 'candidate_since': now, 'samples': 1}
            else:
                st['samples'] = int(st.get('samples', 0) or 0) + 1
            age = max(0.0, now - float(st.get('candidate_since', now)))
            if age >= 0.18 and int(st.get('samples', 0) or 0) >= 2:
                committed = early
                st = {'committed': committed, 'candidate': 'WAIT', 'candidate_since': 0.0, 'commit_ts': now, 'samples': 0}
    elif early == committed or early == 'WAIT':
        st['candidate'] = 'WAIT'
        st['candidate_since'] = 0.0
        st['samples'] = 0
    else:
        if candidate != early:
            st['candidate'] = early
            st['candidate_since'] = now
            st['samples'] = 1
        else:
            st['samples'] = int(st.get('samples', 0) or 0) + 1
        phase = str(raw.get('flip_phase', 'NONE')).upper()
        flip_to = str(raw.get('flip_to', 'WAIT')).upper()
        age = max(0.0, now - float(st.get('candidate_since', now)))
        if phase == 'CONFIRMED' and flip_to == early:
            needed = 0.34
        elif phase == 'LIKELY' and flip_to == early:
            needed = 0.48
        elif bool(raw.get('straight_shot')):
            needed = 0.42
        else:
            needed = 0.7
        if age >= needed and int(st.get('samples', 0) or 0) >= 2:
            committed = early
            st = {'committed': committed, 'candidate': 'WAIT', 'candidate_since': 0.0, 'commit_ts': now, 'samples': 0}
    self._v215_mm_commit_state = st
    chosen = committed if committed in ('UP', 'DOWN') else early
    raw['early_side'] = early
    raw['committed_side'] = chosen
    raw['raw_settlement_side'] = early
    raw['score_used_for_entry'] = False
    raw['entry_logic'] = 'SETUP_CONVERGENCE_NOT_SCORE'
    if chosen in ('UP', 'DOWN'):
        raw['side'] = chosen
        raw['future_side'] = chosen
        raw['settlement_side'] = chosen
    return raw

def _v215_setup_read(self, mm, sig=None, candles=None, now=None):
    """
    Determine whether the SETUP makes sense for MM's chosen side.

    No points are accumulated and there is no minimum score. Instead this
    identifies named evidence lanes and explicit contradictions.
    """
    now = float(now or time.time())
    candles = list(candles or getattr(self, '_last_analysis_candles', None) or [])
    side = str(mm.get('settlement_side', 'WAIT')).upper()
    if side not in ('UP', 'DOWN'):
        self._v215_entry_state = {}
        return {'ready': False, 'side': 'WAIT', 'lane': 'NO SIDE', 'reason': 'MM has no persistent side'}
    opposing = 'DOWN' if side == 'UP' else 'UP'
    try:
        target, _ = self.effective_target()
    except Exception:
        target = getattr(self, 'target_price', None)
    try:
        bo = _v215_breakout_read(self, mm=mm, sig=sig, candles=candles, now=now)
    except Exception:
        bo = {}
    nh = dict(mm.get('newhedge') or {})
    x = _v213_candle_features(candles, target=target, now=now, raw_mm=mm, bo=bo, nh=nh)
    p_up, neural_trust = _v213_model_probability(self, x)
    if p_up > 0.5:
        neural_side = 'UP'
    elif p_up < 0.5:
        neural_side = 'DOWN'
    else:
        neural_side = 'WAIT'
    candle_side = 'WAIT'
    candle_strength = 0.0
    if x:
        cs = float(x[-1])
        candle_strength = abs(cs)
        if cs > 0.04:
            candle_side = 'UP'
        elif cs < -0.04:
            candle_side = 'DOWN'
    bo_side = str(bo.get('side', 'WAIT')).upper()
    bo_stage = str(bo.get('stage', 'NONE')).upper()
    nh_ready = bool(nh.get('ready'))
    nh_side = str(nh.get('direction', 'WAIT')).upper() if nh_ready else 'WAIT'
    flip_to = str(mm.get('flip_to', 'WAIT')).upper()
    flip_phase = str(mm.get('flip_phase', 'NONE')).upper()
    hard_mm_flip = flip_to == opposing and flip_phase in ('LIKELY', 'CONFIRMED')
    hard_breakout = bo_side == opposing and bo_stage == 'CONFIRMED'
    if hard_mm_flip or hard_breakout:
        self._v215_entry_state = {}
        why = f'opposing MM flip {flip_phase}' if hard_mm_flip else f'opposing BREAKOUT MAN {bo_stage}'
        return {'ready': False, 'side': side, 'lane': 'HARD CONTRADICTION', 'reason': why, 'p_up': p_up}
    candle_agree = candle_side == side
    candle_oppose = candle_side == opposing and candle_strength >= 0.2
    bo_agree = bo_side == side and bo_stage in ('FORMING', 'LIKELY', 'CONFIRMED')
    bo_soft_oppose = bo_side == opposing and bo_stage == 'LIKELY'
    nh_agree = nh_ready and nh_side == side
    nh_oppose = nh_ready and nh_side == opposing
    neural_agree = neural_side == side
    neural_oppose = neural_side == opposing and neural_trust >= 0.3
    straight = bool(mm.get('straight_shot'))
    lane = None
    if straight and (not candle_oppose) and (not bo_soft_oppose):
        lane = 'STRAIGHT SHOT'
    elif candle_agree and bo_agree:
        lane = 'CANDLES + BREAKOUT'
    elif candle_agree and nh_agree:
        lane = 'CANDLES + NEWHEDGE'
    elif bo_agree and nh_agree and (not candle_oppose):
        lane = 'BREAKOUT + NEWHEDGE'
    elif candle_agree and neural_agree and (not bo_soft_oppose):
        lane = 'CANDLES + NEURAL'
    elif bo_side == side and bo_stage == 'CONFIRMED' and (not candle_oppose) and (not nh_oppose):
        lane = 'CONFIRMED BREAKOUT'
    elif nh_agree and neural_agree and (not candle_oppose) and (not bo_soft_oppose):
        lane = 'NEWHEDGE + LEARNED PATTERN'
    raw_side = str(mm.get('raw_settlement_side', mm.get('early_side', 'WAIT'))).upper()
    if lane is None and raw_side == side:
        if not candle_oppose and (not bo_soft_oppose) and (not nh_oppose):
            lane = 'CLEAN MM READ'
    if lane is None:
        soft = []
        if candle_oppose:
            soft.append('candles oppose')
        if bo_soft_oppose:
            soft.append('breakout likely opposite')
        if nh_oppose:
            soft.append('NewHedge opposite')
        if neural_oppose:
            soft.append('learner opposite')
        self._v215_entry_state = {}
        return {'ready': False, 'side': side, 'lane': 'WAITING FOR COHERENCE', 'reason': ', '.join(soft) if soft else 'setup pieces have not lined up yet', 'p_up': p_up, 'candle_side': candle_side, 'breakout_side': bo_side, 'breakout_stage': bo_stage, 'newhedge_side': nh_side, 'neural_side': neural_side}
    st = dict(getattr(self, '_v215_entry_state', {}) or {})
    if st.get('side') != side:
        st = {'side': side, 'since': now, 'samples': 1, 'lane': lane}
    else:
        st['samples'] = int(st.get('samples', 0) or 0) + 1
        st['lane'] = lane
    self._v215_entry_state = st
    held = max(0.0, now - float(st.get('since', now)))
    if lane in ('STRAIGHT SHOT', 'CONFIRMED BREAKOUT'):
        needed = 0.12
    elif lane in ('CANDLES + BREAKOUT', 'CANDLES + NEWHEDGE', 'BREAKOUT + NEWHEDGE'):
        needed = 0.2
    elif lane in ('CANDLES + NEURAL', 'NEWHEDGE + LEARNED PATTERN'):
        needed = 0.28
    else:
        needed = 0.38
    ready = held >= needed and int(st.get('samples', 0) or 0) >= 2
    prob_for_side = p_up if side == 'UP' else 1.0 - p_up
    return {'ready': bool(ready), 'side': side, 'lane': lane, 'held': held, 'needed': needed, 'p_up': p_up, 'neural_for_side': prob_for_side, 'neural_trust': neural_trust, 'candle_side': candle_side, 'breakout_side': bo_side, 'breakout_stage': bo_stage, 'newhedge_side': nh_side, 'neural_side': neural_side, 'reason': f'{lane} • MM {side} stayed coherent {held:.2f}s • candles {candle_side} • BO {bo_side} {bo_stage} • NH {nh_side} • learner sees {neural_side}'}

def _v215_auto_paper_tick(self, warm=None, sig=None, candles=None, now=None, mode='LIVE'):
    now = float(now or time.time())
    candles = list(candles or getattr(self, '_last_analysis_candles', None) or [])
    _v213_lazy_model(self)
    try:
        mm_for_learning = _v215_mm_reader_fast_commit(self, warm=warm, sig=sig, candles=candles, now=now)
        _v213_market_learning_tick(self, mm_for_learning, sig=sig, candles=candles, now=now)
    except Exception:
        mm_for_learning = None
    if not self.auto_paper_enabled_var.get():
        return False
    if self.paper_active_trade is not None:
        try:
            return _V215_BASE_ACTIVE_PAPER_TICK(self, warm=warm, sig=sig, candles=candles, now=now, mode=mode)
        except Exception:
            return False
    if now - float(getattr(self, '_v215_last_entry_eval', 0) or 0) < 0.08:
        return False
    self._v215_last_entry_eval = now
    bucket = int(now // 900) * 900
    if self.auto_paper_last_bucket == bucket:
        return False
    mm = mm_for_learning or _v215_mm_reader_fast_commit(self, warm=warm, sig=sig, candles=candles, now=now)
    self._v19_last_mm = mm
    setup = _v215_setup_read(self, mm, sig=sig, candles=candles, now=now)
    if not setup.get('ready'):
        try:
            self._set_var_if_changed(self.auto_paper_reason_var, 'MM WATCHING • NO SCORE GATE • ' + setup.get('reason', 'reading setup'))
            m = _v213_lazy_model(self)
            self._set_var_if_changed(self.auto_paper_score_var, f"MM ENTRY = SETUP READ • neural background learned {int(m.get('markets_trained', 0) or 0)} markets")
        except Exception:
            pass
        return False
    side = str(setup.get('side', 'WAIT')).upper()
    if side not in ('UP', 'DOWN'):
        return False
    px, _, _, _ = self._kalshi_paper_price(side, 'ENTER', max_age=3.0)
    if px is None:
        try:
            self._set_var_if_changed(self.auto_paper_reason_var, f"{setup.get('lane', 'MM SETUP')} {side} • waiting executable Kalshi ask")
        except Exception:
            pass
        return False
    if float(px) > _V215_HARD_MAX_ENTRY:
        try:
            self._set_var_if_changed(self.auto_paper_reason_var, f"{setup.get('lane', 'MM SETUP')} {side} • HARD BLOCK {float(px) * 100:.1f}¢ > 75¢")
        except Exception:
            pass
        return False
    t2 = time.time()
    mm2 = _v215_mm_reader_fast_commit(self, sig=sig, candles=candles, now=t2)
    setup2 = _v215_setup_read(self, mm2, sig=sig, candles=candles, now=t2)
    if not setup2.get('ready') or str(setup2.get('side', '')).upper() != side:
        return False
    px2, _, _, _ = self._kalshi_paper_price(side, 'ENTER', max_age=3.0)
    if px2 is None or float(px2) > _V215_HARD_MAX_ENTRY:
        return False
    opened = self._paper_open(side, entry_source='AUTO', auto_score=None, auto_reason=f"MM SAW IT / TOOK IT • {setup2.get('lane', 'SETUP')} • NO SCORE GATE • {setup2.get('reason', '')} • {float(px2) * 100:.1f}¢")
    if opened:
        self.auto_paper_last_bucket = bucket
        try:
            target, _ = self.effective_target()
        except Exception:
            target = getattr(self, 'target_price', None)
        try:
            bo = _v215_breakout_read(self, mm=mm2, sig=sig, candles=candles, now=time.time())
        except Exception:
            bo = {}
        x = _v213_candle_features(candles, target=target, now=time.time(), raw_mm=mm2, bo=bo, nh=dict(mm2.get('newhedge') or {}))
        try:
            if isinstance(self.paper_active_trade, dict):
                self.paper_active_trade['_v213_neural_x'] = list(x) if x else None
                self.paper_active_trade['_v213_neural_side'] = side
                self.paper_active_trade['_v213_neural_p_up'] = float(setup2.get('p_up', 0.5))
        except Exception:
            pass
        try:
            self._set_var_if_changed(self.auto_paper_score_var, f"ENTERED {side} • {setup2.get('lane', 'SETUP')} • NO SCORE GATE")
            self._set_var_if_changed(self.auto_paper_reason_var, f"MM SAW IT / TOOK IT • {setup2.get('reason', '')}")
        except Exception:
            pass
    return bool(opened)
