def _v216_live_toggle_requested(self):
    requested = bool(self.live_auto_enabled_var.get())
    if not requested:
        self.live_auto_status_var.set('LIVE AUTO: OFF • existing live position is NOT auto-closed')
        return
    if not getattr(self, 'kalshi_credentials_verified', False):
        self.live_auto_enabled_var.set(False)
        self.live_auto_status_var.set('LIVE AUTO: BLOCKED • verify Kalshi API credentials first')
        try:
            messagebox.showwarning('Live Auto Blocked', 'Connect/verify your Kalshi API key first. The key must have write permission.')
        except Exception:
            pass
        return
    stake = self._v86_live_stake()
    authority = _v216_authority_name(getattr(self, 'live_bet_brain_var', None), 'MASTERMIND')
    try:
        ok = messagebox.askyesno('Arm LIVE Kalshi Auto Trade?', f'LIVE AUTO authority: {authority}\n\nThat brain will independently choose real Kalshi entries.\nMax entry risk: ${stake:.2f} per 15-minute market\nOne live auto entry max per market.\nExecutable entry above 75¢ is hard-blocked.\n\nArm live trading now?')
    except Exception:
        ok = False
    if not ok:
        self.live_auto_enabled_var.set(False)
        self.live_auto_status_var.set('LIVE AUTO: OFF • arming cancelled')
        return
    self.live_trade_stake_var.set(f'{stake:.2f}')
    self.live_auto_status_var.set(f'LIVE AUTO: ARMED • {authority} has entry authority • max ${stake:.2f}/market')

def _v216_try_bookmap_paper(self, warm=None, sig=None, candles=None, now=None):
    now = float(now or time.time())
    if not self.auto_paper_enabled_var.get():
        return False
    if self.paper_active_trade is not None:
        return False
    bucket = int(now // 900) * 900
    if self.auto_paper_last_bucket == bucket:
        return False
    setup = _v216_bookmap_setup(self, warm=warm, now=now)
    if not setup.get('ready'):
        try:
            self._set_var_if_changed(self.auto_paper_reason_var, 'BOOKMAP KING WATCHING • ' + setup.get('reason', ''))
            self._set_var_if_changed(self.auto_paper_score_var, 'PAPER AUTHORITY: BOOKMAP KING • FLUID OPEN/NOW • NO OPEN LOCK')
        except Exception:
            pass
        return False
    side = str(setup.get('side', 'WAIT')).upper()
    px, _, _, _ = self._kalshi_paper_price(side, 'ENTER', max_age=3.0)
    if px is None:
        return False
    if float(px) > 0.75:
        try:
            self._set_var_if_changed(self.auto_paper_reason_var, f'BOOKMAP KING {side} • HARD BLOCK {float(px) * 100:.1f}¢ > 75¢')
        except Exception:
            pass
        return False
    setup2 = _v216_bookmap_setup(self, warm=None, now=time.time())
    if not setup2.get('ready') or str(setup2.get('side', '')).upper() != side:
        return False
    opened = self._paper_open(side, entry_source='AUTO', auto_score=None, auto_reason=f"BOOKMAP KING AUTHORITY • {setup2.get('lane', 'SETUP')} • {setup2.get('reason', '')} • NO OPEN LOCK")
    if opened:
        self.auto_paper_last_bucket = bucket
        try:
            self._set_var_if_changed(self.auto_paper_score_var, f"ENTERED {side} • BOOKMAP KING • {setup2.get('lane', 'SETUP')}")
            self._set_var_if_changed(self.auto_paper_reason_var, f"BOOKMAP KING TOOK IT • {setup2.get('reason', '')}")
        except Exception:
            pass
    return bool(opened)

def _v216_live_authority_tick(self, warm=None, sig=None, candles=None, now=None):
    now = float(now or time.time())
    if not self.live_auto_enabled_var.get():
        return False
    authority = _v216_authority_name(getattr(self, 'live_bet_brain_var', None), 'MASTERMIND')
    with self.live_trade_lock:
        live = dict(self.live_active_trade or {})
    if live:
        live_bucket = int(live.get('bucket', 0) or 0)
        current_bucket = int(now // 900) * 900
        if live_bucket and live_bucket < current_bucket:
            with self.live_trade_lock:
                self.live_active_trade = None
                self.live_order_inflight = False
            self._v86_live_set(f'LIVE AUTO: {authority} • prior market rolled/settled', 'LIVE POSITION: none')
            return False
        setup = _v216_authority_setup(self, authority, warm=warm, sig=sig, candles=candles, now=now)
        direction = str(live.get('direction', '')).upper()
        new_side = str(setup.get('side', 'WAIT')).upper()
        if setup.get('ready') and new_side in ('UP', 'DOWN') and (direction in ('UP', 'DOWN')) and (new_side != direction):
            return bool(self._v86_live_submit_exit(f"{authority} REVERSED • now {new_side} • {setup.get('lane', 'SETUP')}"))
        return False
    if getattr(self, 'live_order_inflight', False):
        return False
    setup = _v216_authority_setup(self, authority, warm=warm, sig=sig, candles=candles, now=now)
    if not setup.get('ready'):
        try:
            self._v86_live_set(f"LIVE AUTO: ARMED • {authority} watching • {setup.get('reason', 'reading setup')}")
        except Exception:
            pass
        return False
    side = str(setup.get('side', 'WAIT')).upper()
    if side not in ('UP', 'DOWN'):
        return False
    px, _, _, _ = self._kalshi_paper_price(side, 'ENTER', max_age=3.0)
    if px is None:
        self._v86_live_set(f'LIVE AUTO: {authority} wants {side} • waiting executable ask')
        return False
    if float(px) > 0.75:
        self._v86_live_set(f'LIVE AUTO: {authority} {side} HARD BLOCK • {float(px) * 100:.1f}¢ > 75¢')
        return False
    setup2 = _v216_authority_setup(self, authority, warm=None, sig=sig, candles=candles, now=time.time())
    if not setup2.get('ready') or str(setup2.get('side', '')).upper() != side:
        return False
    return bool(self._v86_live_submit_entry(side, reason=f"{authority} AUTHORITY • {setup2.get('lane', 'SETUP')} • {setup2.get('reason', '')}"))

def _v216_auto_tick(self, warm=None, sig=None, candles=None, now=None, mode='LIVE'):
    now = float(now or time.time())
    paper_authority = _v216_authority_name(getattr(self, 'paper_bet_brain_var', None), 'MASTERMIND')
    paper_result = False
    if self.paper_active_trade is not None:
        paper_result = bool(_V216_BASE_AUTO_TICK(self, warm=warm, sig=sig, candles=candles, now=now, mode=mode))
    elif paper_authority == 'MASTERMIND':
        paper_result = bool(_V216_BASE_AUTO_TICK(self, warm=warm, sig=sig, candles=candles, now=now, mode=mode))
    else:
        enabled = bool(self.auto_paper_enabled_var.get())
        try:
            if enabled:
                self.auto_paper_enabled_var.set(False)
            _V216_BASE_AUTO_TICK(self, warm=warm, sig=sig, candles=candles, now=now, mode=mode)
        finally:
            if enabled:
                self.auto_paper_enabled_var.set(True)
        if enabled:
            paper_result = bool(_v216_try_bookmap_paper(self, warm=warm, sig=sig, candles=candles, now=now))
    try:
        live_result = bool(_v216_live_authority_tick(self, warm=warm, sig=sig, candles=candles, now=now))
    except Exception:
        live_result = False
    return bool(paper_result or live_result)
