_V217_MAX_ENTRY = 0.75
_V217_SCORE_FILE = 'BOOKMAP_KING_DUAL_PAPER_SCORE.json'
_V217_LOG_FILE = 'BOOKMAP_KING_DUAL_PAPER_TRADES.jsonl'

def _v217_file(name):
    try:
        return Path.home() / 'Downloads' / str(name)
    except Exception:
        return Path(str(name))

def _v217_default_book():
    return {'MASTERMIND': {'active': None, 'last_entry_bucket': None, 'trades': 0, 'wins': 0, 'losses': 0, 'flats': 0, 'pnl': 0.0, 'last_result': 'NONE'}, 'BOOKMAP KING': {'active': None, 'last_entry_bucket': None, 'trades': 0, 'wins': 0, 'losses': 0, 'flats': 0, 'pnl': 0.0, 'last_result': 'NONE'}}

def _v217_book(self):
    book = getattr(self, '_v217_dual_paper', None)
    if isinstance(book, dict) and 'MASTERMIND' in book and ('BOOKMAP KING' in book):
        return book
    book = _v217_default_book()
    try:
        raw = json.loads(_v217_file(_V217_SCORE_FILE).read_text(encoding='utf-8'))
        if isinstance(raw, dict):
            for brain in ('MASTERMIND', 'BOOKMAP KING'):
                row = dict(raw.get(brain) or {})
                row['active'] = None
                book[brain].update(row)
                book[brain]['active'] = None
    except Exception:
        pass
    self._v217_dual_paper = book
    return book

def _v217_save_book(self):
    book = _v217_book(self)
    try:
        payload = {}
        for brain in ('MASTERMIND', 'BOOKMAP KING'):
            row = dict(book[brain])
            row['active'] = None
            payload[brain] = row
        p = _v217_file(_V217_SCORE_FILE)
        tmp = p.with_suffix('.json.tmp')
        tmp.write_text(json.dumps(payload, indent=2), encoding='utf-8')
        tmp.replace(p)
    except Exception:
        pass

def _v217_log(event):
    try:
        with _v217_file(_V217_LOG_FILE).open('a', encoding='utf-8') as fh:
            fh.write(json.dumps(event, separators=(',', ':')) + '\n')
    except Exception:
        pass

def _v217_score_line(self, brain):
    row = _v217_book(self)[brain]
    active = row.get('active')
    if active:
        state = f"ACTIVE {active.get('side', '?')} @ {float(active.get('entry_contract', 0)) * 100:.1f}¢"
    else:
        state = 'FLAT'
    pnl = float(row.get('pnl', 0.0) or 0.0)
    return f"{brain}: {int(row.get('wins', 0))}-{int(row.get('losses', 0))}-{int(row.get('flats', 0))} • {int(row.get('trades', 0))} trades • P/L {('+' if pnl >= 0 else '-')}${abs(pnl):.2f} • {state}"

def _v217_refresh_score_ui(self):
    try:
        self._set_var_if_changed(self.mm_paper_score_var, _v217_score_line(self, 'MASTERMIND'))
        self._set_var_if_changed(self.bk_paper_score_var, _v217_score_line(self, 'BOOKMAP KING'))
    except Exception:
        pass

def _v217_build_ui(self):
    _V217_PREV_BUILD_UI(self)
    if not hasattr(self, 'mm_paper_score_var'):
        self.mm_paper_score_var = tk.StringVar(value='MASTERMIND: 0-0-0 • FLAT')
    if not hasattr(self, 'bk_paper_score_var'):
        self.bk_paper_score_var = tk.StringVar(value='BOOKMAP KING: 0-0-0 • FLAT')
    paper_card = None
    try:
        stack = [self.root]
        while stack:
            w = stack.pop()
            try:
                kids = list(w.winfo_children())
            except Exception:
                kids = []
            stack.extend(kids)
            try:
                txt = str(w.cget('text'))
            except Exception:
                txt = ''
            if txt == 'AUTO PAPER TRADE':
                paper_card = w.master.master
                break
    except Exception:
        paper_card = None
    if paper_card is not None and (not getattr(self, '_v217_dual_ui_added', False)):
        self._v217_dual_ui_added = True
        try:
            for w in paper_card.winfo_children():
                for c in w.winfo_children():
                    try:
                        txt = str(c.cget('text'))
                    except Exception:
                        txt = ''
                    if txt == 'PAPER BRAIN':
                        w.pack_forget()
                        break
        except Exception:
            pass
        ttk.Label(paper_card, text='DUAL PAPER LEAGUE • BOTH BRAINS TRADE EVERY MARKET', style='Strong.Card.TLabel').pack(anchor='w', pady=(2, 2))
        ttk.Label(paper_card, textvariable=self.mm_paper_score_var, style='Muted.Card.TLabel').pack(anchor='w', pady=(0, 1))
        ttk.Label(paper_card, textvariable=self.bk_paper_score_var, style='Muted.Card.TLabel').pack(anchor='w', pady=(0, 4))
        ttk.Label(paper_card, text='LIVE BRAIN selector remains independent: MASTERMIND or BOOKMAP KING', style='Muted.Card.TLabel').pack(anchor='w', pady=(0, 4))
    _v217_book(self)
    _v217_refresh_score_ui(self)

def _v217_contract_price(self, side, action='ENTER'):
    try:
        px, _, _, _ = self._kalshi_paper_price(str(side).upper(), str(action).upper(), max_age=3.0)
        return None if px is None else float(px)
    except Exception:
        return None

def _v217_shadow_open(self, brain, setup, now=None):
    now = float(now or time.time())
    book = _v217_book(self)
    row = book[brain]
    if row.get('active') is not None:
        return False
    bucket = int(now // 900) * 900
    if row.get('last_entry_bucket') == bucket:
        return False
    side = str(setup.get('side', 'WAIT')).upper()
    if side not in ('UP', 'DOWN'):
        return False
    px = _v217_contract_price(self, side, 'ENTER')
    if px is None:
        return False
    if px > _V217_MAX_ENTRY:
        row['last_result'] = f'BLOCKED {px * 100:.1f}¢ > 75¢'
        return False
    try:
        stake = float(self._paper_parse_stake())
    except Exception:
        stake = 10.0
    if stake <= 0:
        stake = 10.0
    contracts = stake / max(px, 0.01)
    try:
        target, _ = self.effective_target()
    except Exception:
        target = getattr(self, 'target_price', None)
    trade = {'brain': brain, 'side': side, 'bucket': bucket, 'entry_ts': now, 'entry_contract': px, 'stake': stake, 'contracts': contracts, 'target': float(target) if target is not None else None, 'lane': str(setup.get('lane', 'SETUP')), 'reason': str(setup.get('reason', ''))}
    row['active'] = trade
    row['last_entry_bucket'] = bucket
    row['trades'] = int(row.get('trades', 0) or 0) + 1
    row['last_result'] = f"ENTER {side} {px * 100:.1f}¢ • {trade['lane']}"
    _v217_log({'event': 'ENTRY', 'ts': now, **trade})
    _v217_refresh_score_ui(self)
    return True

def _v217_shadow_close(self, brain, reason, now=None, settle_contract=None):
    now = float(now or time.time())
    book = _v217_book(self)
    row = book[brain]
    trade = dict(row.get('active') or {})
    if not trade:
        return False
    side = str(trade.get('side', 'WAIT')).upper()
    if settle_contract is None:
        px = _v217_contract_price(self, side, 'EXIT')
    else:
        px = float(settle_contract)
    if px is None:
        return False
    entry = float(trade.get('entry_contract', 0.0) or 0.0)
    contracts = float(trade.get('contracts', 0.0) or 0.0)
    pnl = contracts * (px - entry)
    if pnl > 0.005:
        result = 'WIN'
        row['wins'] = int(row.get('wins', 0) or 0) + 1
    elif pnl < -0.005:
        result = 'LOSS'
        row['losses'] = int(row.get('losses', 0) or 0) + 1
    else:
        result = 'FLAT'
        row['flats'] = int(row.get('flats', 0) or 0) + 1
    row['pnl'] = float(row.get('pnl', 0.0) or 0.0) + pnl
    row['last_result'] = f'{result} {pnl:+.2f} • exit {px * 100:.1f}¢ • {reason}'
    row['active'] = None
    _v217_log({'event': 'EXIT', 'ts': now, 'brain': brain, 'side': side, 'entry_contract': entry, 'exit_contract': px, 'pnl': pnl, 'result': result, 'reason': str(reason), 'bucket': trade.get('bucket'), 'lane': trade.get('lane')})
    _v217_save_book(self)
    _v217_refresh_score_ui(self)
    return True

def _v217_mm_aggressive_read(self, warm=None, sig=None, candles=None, now=None):
    """
    Mastermind may enter from its own persistent directional read.
    Helpers confirm/accelerate but do not impose a numeric permission threshold.
    """
    now = float(now or time.time())
    mm = _v215_mm_reader_fast_commit(self, warm=warm, sig=sig, candles=candles, now=now)
    side = str(mm.get('settlement_side', 'WAIT')).upper()
    if side not in ('UP', 'DOWN'):
        self._v217_mm_entry_state = {}
        return {'ready': False, 'side': 'WAIT', 'lane': 'MM WAIT', 'reason': 'Mastermind has no directional read', 'mm': mm}
    opposing = 'DOWN' if side == 'UP' else 'UP'
    flip_to = str(mm.get('flip_to', 'WAIT')).upper()
    flip_phase = str(mm.get('flip_phase', 'NONE')).upper()
    try:
        bo = _v215_breakout_read(self, mm=mm, sig=sig, candles=candles, now=now)
    except Exception:
        bo = {}
    bo_side = str(bo.get('side', 'WAIT')).upper()
    bo_stage = str(bo.get('stage', 'NONE')).upper()
    hard_oppose = flip_to == opposing and flip_phase in ('LIKELY', 'CONFIRMED') or (bo_side == opposing and bo_stage == 'CONFIRMED')
    if hard_oppose:
        self._v217_mm_entry_state = {}
        return {'ready': False, 'side': side, 'lane': 'MM OPPOSING BREAK', 'reason': f'flip {flip_to} {flip_phase} • BO {bo_side} {bo_stage}', 'mm': mm, 'bo': bo}
    nh = dict(mm.get('newhedge') or {})
    nh_side = str(nh.get('direction', 'WAIT')).upper() if nh.get('ready') else 'WAIT'
    try:
        target, _ = self.effective_target()
    except Exception:
        target = getattr(self, 'target_price', None)
    x = _v213_candle_features(list(candles or []), target=target, now=now, raw_mm=mm, bo=bo, nh=nh)
    p_up, _trust = _v213_model_probability(self, x)
    neural_side = 'UP' if p_up > 0.5 else 'DOWN' if p_up < 0.5 else 'WAIT'
    lane = 'MM OWN READ'
    if bool(mm.get('straight_shot')):
        lane = 'MM STRAIGHT SHOT'
    elif bo_side == side and bo_stage in ('FORMING', 'LIKELY', 'CONFIRMED'):
        lane = 'MM + EARLY BREAK'
    elif nh_side == side:
        lane = 'MM + NEWHEDGE'
    elif neural_side == side:
        lane = 'MM + LEARNED PATTERN'
    st = dict(getattr(self, '_v217_mm_entry_state', {}) or {})
    if st.get('side') != side:
        st = {'side': side, 'since': now, 'samples': 1}
    else:
        st['samples'] = int(st.get('samples', 0) or 0) + 1
    self._v217_mm_entry_state = st
    held = max(0.0, now - float(st.get('since', now)))
    needed = 0.1 if lane != 'MM OWN READ' else 0.24
    ready = held >= needed and int(st.get('samples', 0) or 0) >= 2
    return {'ready': bool(ready), 'side': side, 'lane': lane, 'held': held, 'needed': needed, 'reason': f'{lane} • {side} persisted {held:.2f}s • BO {bo_side} {bo_stage} • NH {nh_side} • neural {neural_side}', 'mm': mm, 'bo': bo}

def _v217_bk_aggressive_read(self, warm=None, now=None):
    """
    Bookmap King may enter from its fluid OPEN/NOW read.
    No opening lock and no confidence-score threshold.
    """
    now = float(now or time.time())
    warm = dict(warm or self._bookmap_fast_warmup_read(now=now) or {})
    if not warm.get('ready'):
        self._v217_bk_entry_state = {}
        return {'ready': False, 'side': 'WAIT', 'lane': 'BK WAIT', 'reason': 'waiting for Bookmap live flow', 'warm': warm}
    side = str(warm.get('favored', 'WAIT')).upper()
    if side not in ('UP', 'DOWN'):
        self._v217_bk_entry_state = {}
        return {'ready': False, 'side': 'WAIT', 'lane': 'BK WAIT', 'reason': 'OPEN/NOW has no side', 'warm': warm}
    opposing = 'DOWN' if side == 'UP' else 'UP'
    wave = dict(warm.get('wave') or {})
    whale = dict(warm.get('whale') or {})
    wave_side = str(wave.get('raw_direction', wave.get('direction', 'NEUTRAL'))).upper()
    whale_side = str(whale.get('direction', 'NEUTRAL')).upper()
    flow = float(wave.get('flow_2s', 0.0) or 0.0)
    flow_side = 'UP' if flow > 0 else 'DOWN' if flow < 0 else 'WAIT'
    wave_risk = float(wave.get('flip_risk', 0.0) or 0.0)
    whale_likelihood = float(whale.get('likelihood', 0.0) or 0.0)
    hard_oppose = wave_side == opposing and flow_side == opposing and (wave_risk >= 78.0) or (whale_side == opposing and whale_likelihood >= 88.0 and (wave_side == opposing))
    if hard_oppose:
        self._v217_bk_entry_state = {}
        return {'ready': False, 'side': side, 'lane': 'BK OPPOSING BREAK', 'reason': f'wave {wave_side} • flow {flow_side} • whale {whale_side}', 'warm': warm}
    if wave_side == side and flow_side == side:
        lane = 'BK WAVE + FLOW'
    elif wave_side == side or flow_side == side:
        lane = 'BK LIVE PRESSURE'
    elif whale_side == side:
        lane = 'BK WHALE READ'
    else:
        lane = 'BK OPEN/NOW READ'
    st = dict(getattr(self, '_v217_bk_entry_state', {}) or {})
    if st.get('side') != side:
        st = {'side': side, 'since': now, 'samples': 1}
    else:
        st['samples'] = int(st.get('samples', 0) or 0) + 1
    self._v217_bk_entry_state = st
    held = max(0.0, now - float(st.get('since', now)))
    needed = 0.1 if lane != 'BK OPEN/NOW READ' else 0.22
    ready = held >= needed and int(st.get('samples', 0) or 0) >= 2
    return {'ready': bool(ready), 'side': side, 'lane': lane, 'held': held, 'needed': needed, 'reason': f'{lane} • {side} persisted {held:.2f}s • wave {wave_side} • flow {flow_side} • whale {whale_side}', 'warm': warm}

def _v217_early_exit_signal(self, brain, active_side, warm=None, sig=None, candles=None, now=None):
    """
    EARLY opposing break detector. This is intentionally separate from entry.
    It can close a brain's position before that brain fully commits to the
    opposite side.
    """
    now = float(now or time.time())
    active_side = str(active_side).upper()
    opposing = 'DOWN' if active_side == 'UP' else 'UP'
    if brain == 'MASTERMIND':
        mm = _v215_mm_reader_fast_commit(self, warm=warm, sig=sig, candles=candles, now=now)
        try:
            bo = _v215_breakout_read(self, mm=mm, sig=sig, candles=candles, now=now)
        except Exception:
            bo = {}
        flip_to = str(mm.get('flip_to', 'WAIT')).upper()
        flip_phase = str(mm.get('flip_phase', 'NONE')).upper()
        raw_side = str(mm.get('raw_settlement_side', mm.get('early_side', 'WAIT'))).upper()
        bo_side = str(bo.get('side', 'WAIT')).upper()
        bo_stage = str(bo.get('stage', 'NONE')).upper()
        if flip_to == opposing and flip_phase in ('FORMING', 'LIKELY', 'CONFIRMED'):
            return (True, f'EARLY MM FLIP {opposing} {flip_phase}')
        if bo_side == opposing and bo_stage in ('FORMING', 'LIKELY', 'CONFIRMED'):
            return (True, f'EARLY BREAKOUT MAN {opposing} {bo_stage}')
        if raw_side == opposing:
            st = dict(getattr(self, '_v217_mm_exit_state', {}) or {})
            if st.get('side') != opposing:
                st = {'side': opposing, 'since': now, 'samples': 1}
            else:
                st['samples'] = int(st.get('samples', 0) or 0) + 1
            self._v217_mm_exit_state = st
            if now - float(st.get('since', now)) >= 0.18 and int(st.get('samples', 0)) >= 2:
                return (True, f'EARLY MM RAW REVERSAL {opposing}')
        else:
            self._v217_mm_exit_state = {}
        return (False, '')
    warm = dict(warm or self._bookmap_fast_warmup_read(now=now) or {})
    if not warm.get('ready'):
        return (False, '')
    favored = str(warm.get('favored', 'WAIT')).upper()
    wave = dict(warm.get('wave') or {})
    wave_side = str(wave.get('raw_direction', wave.get('direction', 'NEUTRAL'))).upper()
    flow = float(wave.get('flow_2s', 0.0) or 0.0)
    flow_side = 'UP' if flow > 0 else 'DOWN' if flow < 0 else 'WAIT'
    flip_risk = float(wave.get('flip_risk', 0.0) or 0.0)
    if wave_side == opposing and flow_side == opposing:
        return (True, f'EARLY BOOKMAP BREAK {opposing} • wave+flow')
    if favored == opposing and (wave_side == opposing or flow_side == opposing):
        st = dict(getattr(self, '_v217_bk_exit_state', {}) or {})
        if st.get('side') != opposing:
            st = {'side': opposing, 'since': now, 'samples': 1}
        else:
            st['samples'] = int(st.get('samples', 0) or 0) + 1
        self._v217_bk_exit_state = st
        if now - float(st.get('since', now)) >= 0.14 and int(st.get('samples', 0) or 0) >= 2:
            return (True, f'EARLY BOOKMAP OPEN/NOW FLIP {opposing}')
    else:
        self._v217_bk_exit_state = {}
    if flip_risk >= 86.0 and wave_side == opposing:
        return (True, f'EARLY BOOKMAP FLIP RISK {flip_risk:.0f}')
    return (False, '')

def _v217_roll_shadow_market(self, brain, candles=None, now=None):
    """
    Settle a still-open shadow paper trade when its 15m market has rolled.
    This uses final BTC-vs-captured-target as the local simulation label.
    """
    now = float(now or time.time())
    row = _v217_book(self)[brain]
    trade = dict(row.get('active') or {})
    if not trade:
        return False
    bucket = int(trade.get('bucket', 0) or 0)
    current = int(now // 900) * 900
    if not bucket or bucket >= current:
        return False
    target = trade.get('target')
    final_price = None
    for c in list(candles or []):
        try:
            ct = float(c.get('time', 0) or 0)
            if bucket <= ct < bucket + 900:
                final_price = float(c['close'])
        except Exception:
            pass
    if final_price is None:
        try:
            final_price = float(self.current_spot)
        except Exception:
            return False
    if target is None:
        return False
    settled_up = final_price >= float(target)
    side = str(trade.get('side', 'WAIT')).upper()
    won = side == 'UP' and settled_up or (side == 'DOWN' and (not settled_up))
    settle_contract = 1.0 if won else 0.0
    return _v217_shadow_close(self, brain, f'15M ROLLOVER • BTC {final_price:,.2f} vs target {float(target):,.2f}', now=now, settle_contract=settle_contract)

def _v217_dual_paper_tick(self, warm=None, sig=None, candles=None, now=None):
    now = float(now or time.time())
    candles = list(candles or getattr(self, '_last_analysis_candles', None) or [])
    if not self.auto_paper_enabled_var.get():
        _v217_refresh_score_ui(self)
        return False
    did = False
    book = _v217_book(self)
    for brain in ('MASTERMIND', 'BOOKMAP KING'):
        try:
            did = _v217_roll_shadow_market(self, brain, candles=candles, now=now) or did
        except Exception:
            pass
    for brain in ('MASTERMIND', 'BOOKMAP KING'):
        trade = dict(book[brain].get('active') or {})
        if trade:
            try:
                exit_now, reason = _v217_early_exit_signal(self, brain, trade.get('side'), warm=warm, sig=sig, candles=candles, now=now)
                if exit_now:
                    did = _v217_shadow_close(self, brain, reason, now=now) or did
            except Exception:
                pass
    if book['MASTERMIND'].get('active') is None:
        try:
            mm_setup = _v217_mm_aggressive_read(self, warm=warm, sig=sig, candles=candles, now=now)
            if mm_setup.get('ready'):
                did = _v217_shadow_open(self, 'MASTERMIND', mm_setup, now=now) or did
        except Exception:
            pass
    if book['BOOKMAP KING'].get('active') is None:
        try:
            bk_setup = _v217_bk_aggressive_read(self, warm=warm, now=now)
            if bk_setup.get('ready'):
                did = _v217_shadow_open(self, 'BOOKMAP KING', bk_setup, now=now) or did
        except Exception:
            pass
    _v217_refresh_score_ui(self)
    return did

def _v217_target_sniper_worker(self, bucket):
    """
    Rapid non-blocking market/target refresh burst.
    Stops as soon as the current bucket owns a captured target.
    """
    for attempt in range(18):
        if int(time.time() // 900) * 900 != int(bucket):
            return
        try:
            market = self._refresh_auto_kalshi_market()
            target = self._extract_target(market) if market else None
            ticker = str((market or {}).get('ticker') or '').strip().upper()
            if target:
                self.target_price = float(target)
                self._v217_target_captured_bucket = int(bucket)
                try:
                    self.root.after(0, lambda t=float(target), tkx=ticker: self.auto_target_status_var.set(f'AUTO TARGET: {money(t)} • SNIPED AT MARKET START • {tkx}'))
                except Exception:
                    pass
                return
        except Exception as exc:
            try:
                self._v217_target_last_error = str(exc)
            except Exception:
                pass
        time.sleep(0.28 if attempt < 8 else 0.55)

def _v217_target_sniper_tick(self, now=None):
    now = float(now or time.time())
    bucket = int(now // 900) * 900
    if getattr(self, '_v217_target_bucket', None) != bucket:
        self._v217_target_bucket = bucket
        self._v217_target_captured_bucket = None
        self._v217_target_sniper_running = False
        self.target_price = None
        try:
            self.auto_target_status_var.set('AUTO TARGET: SNIPING NEW 15M TARGET NOW...')
            self.auto_market_status_var.set('AUTO MARKET: NEW 15M • instant discovery...')
        except Exception:
            pass
    if getattr(self, '_v217_target_captured_bucket', None) == bucket:
        return
    if not getattr(self, '_v217_target_sniper_running', False):
        self._v217_target_sniper_running = True

        def runner():
            try:
                _v217_target_sniper_worker(self, bucket)
            finally:
                self._v217_target_sniper_running = False
        threading.Thread(target=runner, daemon=True).start()

def _v217_live_tick(self, warm=None, sig=None, candles=None, now=None):
    """
    Keep the V21.16 LIVE selector but add early-break autonomous selling for
    the selected live brain before waiting for a full reversal setup.
    """
    now = float(now or time.time())
    if not self.live_auto_enabled_var.get():
        return False
    authority = _v216_authority_name(getattr(self, 'live_bet_brain_var', None), 'MASTERMIND')
    with self.live_trade_lock:
        live = dict(self.live_active_trade or {})
    if live:
        direction = str(live.get('direction', 'WAIT')).upper()
        try:
            exit_now, reason = _v217_early_exit_signal(self, authority, direction, warm=warm, sig=sig, candles=candles, now=now)
        except Exception:
            exit_now, reason = (False, '')
        if exit_now:
            return bool(self._v86_live_submit_exit(f'{authority} EARLY BREAK EXIT • {reason}'))
    return bool(_V217_PREV_LIVE_TICK(self, warm=warm, sig=sig, candles=candles, now=now))

def _v217_master_tick(self, warm=None, sig=None, candles=None, now=None, mode='LIVE'):
    now = float(now or time.time())
    candles = list(candles or getattr(self, '_last_analysis_candles', None) or [])
    try:
        _v217_target_sniper_tick(self, now=now)
    except Exception:
        pass
    try:
        mm_learning = _v215_mm_reader_fast_commit(self, warm=warm, sig=sig, candles=candles, now=now)
        _v213_market_learning_tick(self, mm_learning, sig=sig, candles=candles, now=now)
    except Exception:
        pass
    paper_did = False
    try:
        paper_did = bool(_v217_dual_paper_tick(self, warm=warm, sig=sig, candles=candles, now=now))
    except Exception:
        paper_did = False
    live_did = False
    try:
        live_did = bool(_v217_live_tick(self, warm=warm, sig=sig, candles=candles, now=now))
    except Exception:
        live_did = False
    return bool(paper_did or live_did)
ChartKingPro._build_ui = _v217_build_ui
ChartKingPro._auto_paper_unified_tick = _v217_master_tick
_V218_BASE_BUILD_UI = ChartKingPro._build_ui

def _v218_build_ui(self):
    _V218_BASE_BUILD_UI(self)
    if not hasattr(self, 'live_bet_brain_var'):
        self.live_bet_brain_var = tk.StringVar(value='MASTERMIND')
    paper_card = None
    try:
        stack = [self.root]
        while stack:
            w = stack.pop()
            try:
                kids = list(w.winfo_children())
            except Exception:
                kids = []
            stack.extend(kids)
            try:
                txt = str(w.cget('text'))
            except Exception:
                txt = ''
            if txt == 'AUTO PAPER TRADE':
                paper_card = w.master.master
                break
    except Exception:
        paper_card = None
    if paper_card is None or getattr(self, '_v218_live_selector_added', False):
        return
    self._v218_live_selector_added = True
    row = ttk.Frame(paper_card, style='Card.TFrame')
    row.pack(fill='x', pady=(2, 6))
    ttk.Label(row, text='LIVE TRADE BRAIN', style='Strong.Card.TLabel').pack(side='left', padx=(0, 7))
    combo = ttk.Combobox(row, textvariable=self.live_bet_brain_var, values=('MASTERMIND', 'BOOKMAP KING'), state='readonly', width=15)
    combo.pack(side='left')
    if not hasattr(self, 'v218_live_selector_status_var'):
        self.v218_live_selector_status_var = tk.StringVar()

    def refresh(_event=None):
        brain = _v216_authority_name(self.live_bet_brain_var, 'MASTERMIND')
        try:
            self.v218_live_selector_status_var.set(f'LIVE AUTHORITY: {brain} • PAPER: BOTH BRAINS')
        except Exception:
            pass
        try:
            if self.live_auto_enabled_var.get():
                self._v86_live_set(f'LIVE AUTO: ARMED • {brain} has entry authority • max ${self._v86_live_stake():.2f}/market')
        except Exception:
            pass
    combo.bind('<<ComboboxSelected>>', refresh)
    ttk.Label(row, textvariable=self.v218_live_selector_status_var, style='Muted.Card.TLabel').pack(side='left', padx=(12, 0))
    refresh()
ChartKingPro._build_ui = _v218_build_ui
