def _v219_mm_final_read(self, warm=None, sig=None, candles=None, now=None):
    now = float(now or time.time())
    mm = _v215_mm_reader_fast_commit(self, warm=warm, sig=sig, candles=candles, now=now)
    side = str(mm.get('settlement_side', mm.get('future_side', mm.get('side', 'WAIT')))).upper()
    if side not in ('UP', 'DOWN'):
        self._v219_mm_final_state = {}
        return {'ready': False, 'side': 'WAIT', 'lane': 'MM NO FINAL SIDE', 'reason': 'Mastermind has not chosen a final-result side yet', 'mm': mm}
    opposing = 'DOWN' if side == 'UP' else 'UP'
    flip_to = str(mm.get('flip_to', 'WAIT')).upper()
    flip_phase = str(mm.get('flip_phase', 'NONE')).upper()
    if flip_to == opposing and flip_phase in ('LIKELY', 'CONFIRMED'):
        self._v219_mm_final_state = {}
        return {'ready': False, 'side': side, 'lane': 'MM TRUE OPPOSING FLIP', 'reason': f'opposing MM flip {opposing} {flip_phase}', 'mm': mm}
    try:
        bo = _v215_breakout_read(self, mm=mm, sig=sig, candles=candles, now=now)
    except Exception:
        bo = {}
    bo_side = str(bo.get('side', 'WAIT')).upper()
    bo_stage = str(bo.get('stage', 'NONE')).upper()
    if bo_side == opposing and bo_stage == 'CONFIRMED':
        self._v219_mm_final_state = {}
        return {'ready': False, 'side': side, 'lane': 'MM TRUE OPPOSING BREAK', 'reason': f'BREAKOUT MAN confirmed {opposing}', 'mm': mm, 'bo': bo}
    st = dict(getattr(self, '_v219_mm_final_state', {}) or {})
    if st.get('side') != side:
        st = {'side': side, 'since': now, 'samples': 1}
    else:
        st['samples'] = int(st.get('samples', 0) or 0) + 1
    self._v219_mm_final_state = st
    held = max(0.0, now - float(st.get('since', now)))
    ready = held >= _V219_ENTRY_HOLD and int(st.get('samples', 0) or 0) >= 2
    return {'ready': bool(ready), 'side': side, 'lane': 'MM TRUST FINAL RESULT', 'held': held, 'reason': f'Mastermind final-result read {side} persisted {held:.2f}s • no true opposing break', 'mm': mm, 'bo': bo}

def _v219_bk_final_read(self, warm=None, now=None):
    now = float(now or time.time())
    warm = dict(warm or self._bookmap_fast_warmup_read(now=now) or {})
    if not warm.get('ready'):
        self._v219_bk_final_state = {}
        return {'ready': False, 'side': 'WAIT', 'lane': 'BK NO LIVE READ', 'reason': 'Bookmap live read not ready', 'warm': warm}
    side = str(warm.get('favored', 'WAIT')).upper()
    if side not in ('UP', 'DOWN'):
        self._v219_bk_final_state = {}
        return {'ready': False, 'side': 'WAIT', 'lane': 'BK NO FINAL SIDE', 'reason': 'Bookmap OPEN/NOW has not chosen a side', 'warm': warm}
    opposing = 'DOWN' if side == 'UP' else 'UP'
    wave = dict(warm.get('wave') or {})
    whale = dict(warm.get('whale') or {})
    wave_side = str(wave.get('raw_direction', wave.get('direction', 'NEUTRAL'))).upper()
    flow = float(wave.get('flow_2s', 0.0) or 0.0)
    flow_side = 'UP' if flow > 0 else 'DOWN' if flow < 0 else 'WAIT'
    whale_side = str(whale.get('direction', 'NEUTRAL')).upper()
    wave_risk = float(wave.get('flip_risk', 0.0) or 0.0)
    whale_likelihood = float(whale.get('likelihood', 0.0) or 0.0)
    true_break_against = wave_side == opposing and flow_side == opposing and (wave_risk >= 84.0) or (wave_side == opposing and whale_side == opposing and (whale_likelihood >= 90.0))
    if true_break_against:
        self._v219_bk_final_state = {}
        return {'ready': False, 'side': side, 'lane': 'BK TRUE OPPOSING BREAK', 'reason': f'live flow breaking {opposing} • wave {wave_side} • flow {flow_side} • whale {whale_side}', 'warm': warm}
    st = dict(getattr(self, '_v219_bk_final_state', {}) or {})
    if st.get('side') != side:
        st = {'side': side, 'since': now, 'samples': 1}
    else:
        st['samples'] = int(st.get('samples', 0) or 0) + 1
    self._v219_bk_final_state = st
    held = max(0.0, now - float(st.get('since', now)))
    ready = held >= _V219_ENTRY_HOLD and int(st.get('samples', 0) or 0) >= 2
    return {'ready': bool(ready), 'side': side, 'lane': 'BK TRUST FINAL RESULT', 'held': held, 'reason': f'Bookmap final OPEN/NOW read {side} persisted {held:.2f}s • no true opposing live break', 'warm': warm}

def _v219_paper_heartbeat(self):
    """
    Independent 100ms paper execution loop.
    This is the key fix: paper collection no longer waits for the legacy unified
    auto-trade loop to happen to call us.
    """
    try:
        now = time.time()
        try:
            _v217_target_sniper_tick(self, now=now)
        except Exception:
            pass
        try:
            candles = list(getattr(self, '_last_analysis_candles', None) or [])
        except Exception:
            candles = []
        try:
            warm = self._bookmap_fast_warmup_read(now=now)
        except Exception:
            warm = None
        sig = None
        try:
            sig = getattr(self, '_last_signal', None)
        except Exception:
            pass
        book = _v217_book(self)
        for brain in ('MASTERMIND', 'BOOKMAP KING'):
            try:
                _v217_roll_shadow_market(self, brain, candles=candles, now=now)
            except Exception:
                pass
        for brain in ('MASTERMIND', 'BOOKMAP KING'):
            trade = dict(book[brain].get('active') or {})
            if not trade:
                continue
            try:
                exit_now, reason = _v217_early_exit_signal(self, brain, trade.get('side'), warm=warm, sig=sig, candles=candles, now=now)
                if exit_now:
                    _v217_shadow_close(self, brain, reason, now=now)
            except Exception:
                pass
        if book['MASTERMIND'].get('active') is None:
            try:
                setup = _v219_mm_final_read(self, warm=warm, sig=sig, candles=candles, now=now)
                if setup.get('ready'):
                    _v217_shadow_open(self, 'MASTERMIND', setup, now=now)
            except Exception:
                pass
        if book['BOOKMAP KING'].get('active') is None:
            try:
                setup = _v219_bk_final_read(self, warm=warm, now=now)
                if setup.get('ready'):
                    _v217_shadow_open(self, 'BOOKMAP KING', setup, now=now)
            except Exception:
                pass
        _v217_refresh_score_ui(self)
    finally:
        try:
            self.root.after(_V219_PAPER_HEARTBEAT_MS, lambda: _v219_paper_heartbeat(self))
        except Exception:
            pass
ChartKingPro._build_ui = _v219_build_ui
_V220_BASE_BUILD_UI = ChartKingPro._build_ui
_V220_BASE_SHADOW_CLOSE = _v217_shadow_close
_V220_MAX_ENTRY = 0.75

def _v220_paper_quote(self, side, action='ENTER'):
    """
    PAPER-ONLY quote resolver.
    Priority:
      1) actual executable Kalshi top-of-book
      2) current Kalshi market midpoint/last estimate
    LIVE order submission never calls this fallback.
    """
    side = str(side).upper()
    action = str(action).upper()
    try:
        px, yes_equiv, src, age = self._kalshi_paper_price(side, action, max_age=3.0)
        if px is not None and 0.0 < float(px) < 1.0:
            return (float(px), 'REAL BOOK ' + str(src), float(age), False)
    except Exception:
        pass
    yes = None
    try:
        yes = self.kalshi_yes_price()
    except Exception:
        try:
            yes = _v75_kalshi_yes_price(self)
        except Exception:
            yes = None
    try:
        yes = float(yes)
    except Exception:
        yes = None
    if yes is None or not 0.0 < yes < 1.0:
        return (None, 'NO KALSHI PAPER PRICE', 999.0, True)
    px = yes if side == 'UP' else 1.0 - yes
    if not 0.0 < px < 1.0:
        return (None, 'INVALID PAPER FALLBACK', 999.0, True)
    return (float(px), 'PAPER FALLBACK MID/LAST', 0.0, True)

def _v220_set_diag(self, brain, text):
    try:
        var = self.v220_mm_diag_var if brain == 'MASTERMIND' else self.v220_bk_diag_var
        self._set_var_if_changed(var, str(text))
    except Exception:
        pass

def _v220_build_ui(self):
    _V220_BASE_BUILD_UI(self)
    if not hasattr(self, 'v220_engine_diag_var'):
        self.v220_engine_diag_var = tk.StringVar(value='PAPER ENGINE: starting dedicated heartbeat...')
    if not hasattr(self, 'v220_mm_diag_var'):
        self.v220_mm_diag_var = tk.StringVar(value='MM EXEC: waiting for first read')
    if not hasattr(self, 'v220_bk_diag_var'):
        self.v220_bk_diag_var = tk.StringVar(value='BK EXEC: waiting for first read')
    paper_card = None
    try:
        stack = [self.root]
        while stack:
            w = stack.pop()
            try:
                kids = list(w.winfo_children())
            except Exception:
                kids = []
            stack.extend(kids)
            try:
                txt = str(w.cget('text'))
            except Exception:
                txt = ''
            if txt == 'DUAL PAPER LEAGUE • BOTH BRAINS TRADE EVERY MARKET':
                paper_card = w.master
                break
    except Exception:
        paper_card = None
    if paper_card is not None and (not getattr(self, '_v220_diag_ui_added', False)):
        self._v220_diag_ui_added = True
        ttk.Label(paper_card, textvariable=self.v220_engine_diag_var, style='Strong.Card.TLabel').pack(anchor='w', pady=(2, 1))
        ttk.Label(paper_card, textvariable=self.v220_mm_diag_var, style='Muted.Card.TLabel').pack(anchor='w', pady=(0, 1))
        ttk.Label(paper_card, textvariable=self.v220_bk_diag_var, style='Muted.Card.TLabel').pack(anchor='w', pady=(0, 4))

def _v220_shadow_open(self, brain, setup, now=None):
    """
    Independent paper fill. No silent returns: every blocking condition is
    exposed in that brain's diagnostic line.
    """
    now = float(now or time.time())
    book = _v217_book(self)
    row = book[brain]
    if row.get('active') is not None:
        _v220_set_diag(self, brain, 'ACTIVE • managing existing paper position')
        return False
    bucket = int(now // 900) * 900
    if row.get('last_entry_bucket') == bucket:
        _v220_set_diag(self, brain, 'DONE • already collected this 15m market')
        return False
    side = str(setup.get('side', 'WAIT')).upper()
    if side not in ('UP', 'DOWN'):
        _v220_set_diag(self, brain, 'BLOCK: NO FINAL SIDE • ' + str(setup.get('reason', '')))
        return False
    if not setup.get('ready'):
        held = float(setup.get('held', 0.0) or 0.0)
        _v220_set_diag(self, brain, f'READ {side} • persistence {held:.2f}s • ' + str(setup.get('reason', '')))
        return False
    px, qsrc, _age, fallback = _v220_paper_quote(self, side, 'ENTER')
    if px is None:
        row['last_result'] = 'WAITING FOR ANY KALSHI PAPER PRICE'
        _v220_set_diag(self, brain, f'READ {side} READY • BLOCK: NO KALSHI PRICE AT ALL')
        return False
    if float(px) > _V220_MAX_ENTRY:
        row['last_result'] = f'BLOCKED {px * 100:.1f}¢ > 75¢'
        _v220_set_diag(self, brain, f'READ {side} READY • HARD BLOCK {px * 100:.1f}¢ > 75¢ • {qsrc}')
        return False
    try:
        stake = float(self._paper_parse_stake())
    except Exception:
        stake = 10.0
    if not stake or stake <= 0:
        stake = 10.0
    contracts = stake / max(float(px), 0.01)
    try:
        target, _ = self.effective_target()
    except Exception:
        target = getattr(self, 'target_price', None)
    trade = {'brain': brain, 'side': side, 'bucket': bucket, 'entry_ts': now, 'entry_contract': float(px), 'stake': float(stake), 'contracts': float(contracts), 'target': float(target) if target is not None else None, 'lane': str(setup.get('lane', 'FINAL READ')), 'reason': str(setup.get('reason', '')), 'quote_source': qsrc, 'paper_quote_fallback': bool(fallback)}
    row['active'] = trade
    row['last_entry_bucket'] = bucket
    row['trades'] = int(row.get('trades', 0) or 0) + 1
    row['last_result'] = f"ENTER {side} {float(px) * 100:.1f}¢ • {trade['lane']} • {qsrc}"
    _v217_log({'event': 'ENTRY', 'ts': now, **trade})
    _v217_save_book(self)
    _v217_refresh_score_ui(self)
    _v220_set_diag(self, brain, f"ENTERED {side} @ {float(px) * 100:.1f}¢ • {qsrc} • {trade['lane']}")
    return True

def _v220_shadow_close(self, brain, reason, now=None, settle_contract=None):
    """
    Paper exits get the same paper-only quote fallback so a missing executable
    bid cannot strand a simulated position. Market-settlement closes remain exact
    0/1 labels.
    """
    now = float(now or time.time())
    if settle_contract is not None:
        return _V220_BASE_SHADOW_CLOSE(self, brain, reason, now=now, settle_contract=settle_contract)
    book = _v217_book(self)
    row = book[brain]
    trade = dict(row.get('active') or {})
    if not trade:
        return False
    side = str(trade.get('side', 'WAIT')).upper()
    px, qsrc, _age, fallback = _v220_paper_quote(self, side, 'EXIT')
    if px is None:
        _v220_set_diag(self, brain, f'EXIT SIGNAL • waiting for any paper price • {reason}')
        return False
    entry = float(trade.get('entry_contract', 0.0) or 0.0)
    contracts = float(trade.get('contracts', 0.0) or 0.0)
    pnl = contracts * (float(px) - entry)
    if pnl > 0.005:
        result = 'WIN'
        row['wins'] = int(row.get('wins', 0) or 0) + 1
    elif pnl < -0.005:
        result = 'LOSS'
        row['losses'] = int(row.get('losses', 0) or 0) + 1
    else:
        result = 'FLAT'
        row['flats'] = int(row.get('flats', 0) or 0) + 1
    row['pnl'] = float(row.get('pnl', 0.0) or 0.0) + pnl
    row['last_result'] = f'{result} {pnl:+.2f} • exit {float(px) * 100:.1f}¢ • {reason}'
    row['active'] = None
    _v217_log({'event': 'EXIT', 'ts': now, 'brain': brain, 'side': side, 'entry_contract': entry, 'exit_contract': float(px), 'pnl': pnl, 'result': result, 'reason': str(reason), 'quote_source': qsrc, 'paper_quote_fallback': bool(fallback), 'bucket': trade.get('bucket'), 'lane': trade.get('lane')})
    _v217_save_book(self)
    _v217_refresh_score_ui(self)
    _v220_set_diag(self, brain, f'{result} EXIT {float(px) * 100:.1f}¢ • {qsrc} • {reason}')
    return True

def _v220_paper_heartbeat(self):
    """
    Diagnostic + execution heartbeat. It duplicates no live-order behavior.
    """
    try:
        now = time.time()
        count = int(getattr(self, '_v220_heartbeat_count', 0) or 0) + 1
        self._v220_heartbeat_count = count
        try:
            ticker = _v75_current_ticker(self)
        except Exception:
            ticker = ''
        try:
            target, _ = self.effective_target()
        except Exception:
            target = getattr(self, 'target_price', None)
        try:
            self._set_var_if_changed(self.v220_engine_diag_var, f"PAPER ENGINE: LIVE #{count} • ticker {ticker or 'NONE'} • target {(money(target) if target is not None else 'NONE')}")
        except Exception:
            pass
        try:
            _v217_target_sniper_tick(self, now=now)
        except Exception:
            pass
        try:
            candles = list(getattr(self, '_last_analysis_candles', None) or [])
        except Exception:
            candles = []
        try:
            warm = self._bookmap_fast_warmup_read(now=now)
        except Exception as exc:
            warm = None
            _v220_set_diag(self, 'BOOKMAP KING', f'WARMUP ERROR: {exc}')
        try:
            sig = getattr(self, '_last_signal', None)
        except Exception:
            sig = None
        book = _v217_book(self)
        for brain in ('MASTERMIND', 'BOOKMAP KING'):
            try:
                _v217_roll_shadow_market(self, brain, candles=candles, now=now)
            except Exception:
                pass
        for brain in ('MASTERMIND', 'BOOKMAP KING'):
            trade = dict(book[brain].get('active') or {})
            if trade:
                try:
                    exit_now, reason = _v217_early_exit_signal(self, brain, trade.get('side'), warm=warm, sig=sig, candles=candles, now=now)
                    if exit_now:
                        _v220_shadow_close(self, brain, reason, now=now)
                    else:
                        _v220_set_diag(self, brain, f"ACTIVE {trade.get('side')} • waiting for early break/settlement")
                except Exception as exc:
                    _v220_set_diag(self, brain, f'EXIT CHECK ERROR: {exc}')
        if book['MASTERMIND'].get('active') is None:
            try:
                mm_setup = _v219_mm_final_read(self, warm=warm, sig=sig, candles=candles, now=now)
                if mm_setup.get('ready'):
                    _v220_shadow_open(self, 'MASTERMIND', mm_setup, now=now)
                else:
                    _v220_set_diag(self, 'MASTERMIND', f"READ {mm_setup.get('side', 'WAIT')} • " + str(mm_setup.get('reason', '')))
            except Exception as exc:
                _v220_set_diag(self, 'MASTERMIND', f'ENTRY ERROR: {exc}')
        if book['BOOKMAP KING'].get('active') is None:
            try:
                bk_setup = _v219_bk_final_read(self, warm=warm, now=now)
                if bk_setup.get('ready'):
                    _v220_shadow_open(self, 'BOOKMAP KING', bk_setup, now=now)
                else:
                    _v220_set_diag(self, 'BOOKMAP KING', f"READ {bk_setup.get('side', 'WAIT')} • " + str(bk_setup.get('reason', '')))
            except Exception as exc:
                _v220_set_diag(self, 'BOOKMAP KING', f'ENTRY ERROR: {exc}')
        _v217_refresh_score_ui(self)
    finally:
        try:
            self.root.after(100, lambda: _v220_paper_heartbeat(self))
        except Exception:
            pass

def _v220_start_heartbeat_from_ui(self):
    try:
        self._v219_paper_heartbeat_started = True
    except Exception:
        pass
    if not getattr(self, '_v220_heartbeat_started', False):
        self._v220_heartbeat_started = True
        try:
            self.root.after(300, lambda: _v220_paper_heartbeat(self))
        except Exception:
            pass
