ChartKingPro._build_ui = _v220_build_and_start
_v217_shadow_close = _v220_shadow_close
_V221_MAX_ENTRY = 0.75
_V221_HOLD_ENTRY = 0.14
_V221_HOLD_EXIT = 0.12

def _v221_nh_full_raw(self, sig=None, candles=None, now=None):
    """
    Read the SAME object used by NEWHEDGE // FULL INTERPRETATION.
    No parsing of display text: the panel and executor share one source object.
    """
    now = float(now or time.time())
    sig = sig or getattr(self, 'last_signal', None) or {}
    candles = list(candles or getattr(self, '_last_analysis_candles', None) or [])
    mm = _v214_mm3_read(self, sig=sig, candles=candles, now=now)
    obs, interp, decision, invalid = _v214_newhedge_thought_text(mm)
    side = str(mm.get('settlement_side', mm.get('future_side', mm.get('side', 'WAIT')))).upper()
    nh = dict(mm.get('newhedge') or {})
    return {'side': side if side in ('UP', 'DOWN') else 'WAIT', 'score': float(mm.get('settlement_score', mm.get('score', 0)) or 0), 'signed': float(mm.get('settlement_signed', 0) or 0), 'early': str(mm.get('early_side', side)).upper(), 'nh_direction': str(nh.get('direction', 'WAIT')).upper(), 'nh_strength': float(nh.get('strength', 0) or 0), 'nh_quality': float(nh.get('quality', 0) or 0), 'observations': obs, 'interpretation': interp, 'decision_text': decision, 'invalidation_text': invalid, 'mm': mm}

def _v221_nh_full_setup(self, sig=None, candles=None, now=None, state_name='_v221_nh_paper_state'):
    now = float(now or time.time())
    raw = _v221_nh_full_raw(self, sig=sig, candles=candles, now=now)
    side = str(raw.get('side', 'WAIT')).upper()
    if side not in ('UP', 'DOWN'):
        setattr(self, state_name, {})
        return {'ready': False, 'side': 'WAIT', 'lane': 'NEWHEDGE FULL WAIT', 'reason': 'Full Interpretation has no 15M decision yet', 'raw': raw}
    st = dict(getattr(self, state_name, {}) or {})
    if st.get('side') != side:
        st = {'side': side, 'since': now, 'samples': 1}
    else:
        st['samples'] = int(st.get('samples', 0) or 0) + 1
    setattr(self, state_name, st)
    held = max(0.0, now - float(st.get('since', now)))
    ready = held >= _V221_HOLD_ENTRY and int(st.get('samples', 0) or 0) >= 2
    return {'ready': bool(ready), 'side': side, 'lane': 'NEWHEDGE FULL 15M DECISION', 'held': held, 'reason': f"NEWHEDGE FULL says {side} • held {held:.2f}s • NH {raw.get('nh_direction')} {raw.get('nh_strength', 0):.0f}% • fused {raw.get('signed', 0):+.2f}", 'raw': raw}

def _v221_nh_full_exit(self, held_side, sig=None, candles=None, now=None, state_name='_v221_nh_exit_state'):
    now = float(now or time.time())
    held_side = str(held_side).upper()
    if held_side not in ('UP', 'DOWN'):
        return (False, '')
    raw = _v221_nh_full_raw(self, sig=sig, candles=candles, now=now)
    side = str(raw.get('side', 'WAIT')).upper()
    opposite = 'DOWN' if held_side == 'UP' else 'UP'
    if side != opposite:
        setattr(self, state_name, {})
        return (False, '')
    st = dict(getattr(self, state_name, {}) or {})
    if st.get('side') != opposite:
        st = {'side': opposite, 'since': now, 'samples': 1}
    else:
        st['samples'] = int(st.get('samples', 0) or 0) + 1
    setattr(self, state_name, st)
    held = max(0.0, now - float(st.get('since', now)))
    if held >= _V221_HOLD_EXIT and int(st.get('samples', 0) or 0) >= 2:
        return (True, f"NEWHEDGE FULL FLIPPED {opposite} • {held:.2f}s • NH {raw.get('nh_direction')} {raw.get('nh_strength', 0):.0f}%")
    return (False, '')

def _v221_current_ticker(self):
    try:
        return str((self.kalshi_market or {}).get('ticker') or self.kalshi_ticker or '').strip().upper()
    except Exception:
        return ''

def _v221_current_btc(self):
    try:
        p, _ = self.effective_live_price()
        return None if p is None else float(p)
    except Exception:
        return None

def _v221_insert_journal_open(self, trade):
    """
    Mirror a shadow-paper entry into the legacy persistent journal so the
    existing history/export system can see it.
    """
    try:
        side = str(trade.get('side', 'WAIT')).upper()
        entry_contract = float(trade.get('entry_contract', 0) or 0)
        entry_yes = entry_contract if side == 'UP' else 1.0 - entry_contract
        with self.stockpile_db_lock:
            with self._stockpile_connect() as conn:
                cur = conn.execute('\n                    INSERT INTO paper_trades (\n                        status, direction, entry_ts, market_ticker, bucket,\n                        target, entry_btc, entry_yes, entry_contract,\n                        stake, shares, entry_source, auto_reason\n                    ) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?)\n                ', ('OPEN', side, float(trade.get('entry_ts', time.time()) or time.time()), str(trade.get('ticker') or _v221_current_ticker(self)), int(trade.get('bucket', int(time.time() // 900) * 900) or 0), trade.get('target'), _v221_current_btc(self), entry_yes, entry_contract, float(trade.get('stake', 10.0) or 10.0), float(trade.get('contracts', 0.0) or 0.0), 'NH FULL AUTO', str(trade.get('reason', 'NEWHEDGE FULL 15M DECISION'))))
                return int(cur.lastrowid)
    except Exception as exc:
        try:
            self.paper_status_var.set(f'Paper journal mirror error: {exc}')
        except Exception:
            pass
        return None

def _v221_update_journal_close(self, journal_id, trade, exit_contract, pnl, result, reason):
    try:
        side = str(trade.get('side', 'WAIT')).upper()
        exit_yes = float(exit_contract) if side == 'UP' else 1.0 - float(exit_contract)
        with self.stockpile_db_lock:
            with self._stockpile_connect() as conn:
                conn.execute("\n                    UPDATE paper_trades\n                    SET status='CLOSED',\n                        exit_ts=?,\n                        exit_btc=?,\n                        exit_yes=?,\n                        exit_contract=?,\n                        pnl=?,\n                        result=?,\n                        exit_reason=?\n                    WHERE id=? AND status='OPEN'\n                ", (time.time(), _v221_current_btc(self), exit_yes, float(exit_contract), float(pnl), str(result), str(reason), int(journal_id)))
    except Exception as exc:
        try:
            self.paper_status_var.set(f'Paper journal close mirror error: {exc}')
        except Exception:
            pass

def _v221_shadow_open(self, ledger_name, setup, now=None):
    """
    One persistent shadow paper position per legacy ledger key.
    Authority is always NEWHEDGE FULL, regardless of ledger name.
    """
    now = float(now or time.time())
    book = _v217_book(self)
    row = book[ledger_name]
    if row.get('active') is not None:
        return False
    bucket = int(now // 900) * 900
    if row.get('last_entry_bucket') == bucket:
        _v220_set_diag(self, ledger_name, 'DONE • already sampled this 15m market')
        return False
    side = str(setup.get('side', 'WAIT')).upper()
    if not setup.get('ready') or side not in ('UP', 'DOWN'):
        _v220_set_diag(self, ledger_name, f"NH FULL READ {side} • {setup.get('reason', 'building')}")
        return False
    px, qsrc, _age, fallback = _v220_paper_quote(self, side, 'ENTER')
    if px is None:
        _v220_set_diag(self, ledger_name, f'NH FULL {side} READY • BLOCK: NO KALSHI PAPER PRICE')
        return False
    if float(px) > _V221_MAX_ENTRY:
        _v220_set_diag(self, ledger_name, f'NH FULL {side} READY • HARD BLOCK {float(px) * 100:.1f}¢ > 75¢')
        return False
    try:
        stake = float(self._paper_parse_stake())
    except Exception:
        stake = 10.0
    if not stake or stake <= 0:
        stake = 10.0
    try:
        target, _ = self.effective_target()
    except Exception:
        target = getattr(self, 'target_price', None)
    trade = {'brain': ledger_name, 'authority': 'NEWHEDGE FULL INTERPRETATION', 'side': side, 'bucket': bucket, 'entry_ts': now, 'entry_contract': float(px), 'stake': float(stake), 'contracts': float(stake) / max(float(px), 0.01), 'target': float(target) if target is not None else None, 'ticker': _v221_current_ticker(self), 'lane': 'NEWHEDGE FULL 15M DECISION', 'reason': str(setup.get('reason', '')), 'quote_source': qsrc, 'paper_quote_fallback': bool(fallback)}
    journal_id = _v221_insert_journal_open(self, trade)
    trade['journal_id'] = journal_id
    row['active'] = trade
    row['last_entry_bucket'] = bucket
    row['trades'] = int(row.get('trades', 0) or 0) + 1
    row['last_result'] = f'ENTER {side} {float(px) * 100:.1f}¢ • NEWHEDGE FULL • {qsrc}'
    _v217_log({'event': 'ENTRY', 'ts': now, **trade})
    _v217_save_book(self)
    _v217_refresh_score_ui(self)
    _v221_refresh_visible_paper(self)
    _v220_set_diag(self, ledger_name, f'ENTERED {side} @ {float(px) * 100:.1f}¢ • NEWHEDGE FULL • {qsrc}')
    return True

def _v221_shadow_close(self, ledger_name, reason, now=None, settle_contract=None):
    now = float(now or time.time())
    book = _v217_book(self)
    row = book[ledger_name]
    trade = dict(row.get('active') or {})
    if not trade:
        return False
    side = str(trade.get('side', 'WAIT')).upper()
    if settle_contract is None:
        px, qsrc, _age, fallback = _v220_paper_quote(self, side, 'EXIT')
        if px is None:
            _v220_set_diag(self, ledger_name, f'EXIT SIGNAL • waiting for paper quote • {reason}')
            return False
        exit_contract = float(px)
    else:
        exit_contract = float(settle_contract)
        qsrc = '15M SETTLEMENT'
        fallback = False
    entry = float(trade.get('entry_contract', 0.0) or 0.0)
    contracts = float(trade.get('contracts', 0.0) or 0.0)
    pnl = contracts * (exit_contract - entry)
    if pnl > 0.005:
        result = 'WIN'
        row['wins'] = int(row.get('wins', 0) or 0) + 1
    elif pnl < -0.005:
        result = 'LOSS'
        row['losses'] = int(row.get('losses', 0) or 0) + 1
    else:
        result = 'FLAT'
        row['flats'] = int(row.get('flats', 0) or 0) + 1
    row['pnl'] = float(row.get('pnl', 0.0) or 0.0) + pnl
    row['last_result'] = f'{result} {pnl:+.2f} • exit {exit_contract * 100:.1f}¢ • {reason}'
    row['active'] = None
    journal_id = trade.get('journal_id')
    if journal_id:
        _v221_update_journal_close(self, journal_id, trade, exit_contract, pnl, result, reason)
    _v217_log({'event': 'EXIT', 'ts': now, 'brain': ledger_name, 'authority': 'NEWHEDGE FULL INTERPRETATION', 'side': side, 'entry_contract': entry, 'exit_contract': exit_contract, 'pnl': pnl, 'result': result, 'reason': str(reason), 'quote_source': qsrc, 'paper_quote_fallback': bool(fallback), 'bucket': trade.get('bucket'), 'lane': trade.get('lane'), 'journal_id': journal_id})
    _v217_save_book(self)
    _v217_refresh_score_ui(self)
    _v221_refresh_visible_paper(self)
    try:
        self._refresh_paper_stats()
    except Exception:
        pass
    _v220_set_diag(self, ledger_name, f'{result} EXIT {exit_contract * 100:.1f}¢ • NEWHEDGE FULL • {reason}')
    return True

def _v221_roll_shadow_market(self, ledger_name, candles=None, now=None):
    now = float(now or time.time())
    row = _v217_book(self)[ledger_name]
    trade = dict(row.get('active') or {})
    if not trade:
        return False
    bucket = int(trade.get('bucket', 0) or 0)
    current = int(now // 900) * 900
    if not bucket or bucket >= current:
        return False
    target = trade.get('target')
    final_price = None
    for c in list(candles or []):
        try:
            ct = float(c.get('time', 0) or 0)
            if bucket <= ct < bucket + 900:
                final_price = float(c['close'])
        except Exception:
            pass
    if final_price is None:
        final_price = _v221_current_btc(self)
    if final_price is None or target is None:
        return False
    settled_up = float(final_price) >= float(target)
    side = str(trade.get('side', 'WAIT')).upper()
    won = side == 'UP' and settled_up or (side == 'DOWN' and (not settled_up))
    return _v221_shadow_close(self, ledger_name, f'15M ROLLOVER • BTC {float(final_price):,.2f} vs target {float(target):,.2f}', now=now, settle_contract=1.0 if won else 0.0)

def _v221_refresh_visible_paper(self):
    """
    Drive the EXISTING OPEN PAPER TRADES + HISTORY UI from the dual shadow book.
    """
    book = _v217_book(self)
    lines = []
    for ledger_name in ('MASTERMIND', 'BOOKMAP KING'):
        trade = dict(book[ledger_name].get('active') or {})
        if not trade:
            continue
        side = str(trade.get('side', 'WAIT')).upper()
        entry = float(trade.get('entry_contract', 0.0) or 0.0)
        mark, qsrc, _age, _fallback = _v220_paper_quote(self, side, 'EXIT')
        if mark is None:
            mark_text = 'mark --'
            pnl_text = 'P/L --'
        else:
            pnl = float(trade.get('contracts', 0.0) or 0.0) * (float(mark) - entry)
            mark_text = f'{float(mark) * 100:.1f}¢'
            pnl_text = f"{('+' if pnl >= 0 else '-')}${abs(pnl):.2f}"
        lines.append(f"OPEN • {ledger_name} LEDGER / NH FULL AUTH • {side} • {entry * 100:.1f}¢ → {mark_text} • {pnl_text} • {trade.get('ticker', '--')}")
    try:
        self.paper_active_var.set('\n'.join(lines) if lines else 'No active paper trade')
    except Exception:
        pass
    try:
        self._refresh_paper_stats()
    except Exception:
        pass

def _v221_paper_update_live_mark(self, force=False):
    _v221_refresh_visible_paper(self)

def _v221_paper_heartbeat(self):
    try:
        now = time.time()
        count = int(getattr(self, '_v221_heartbeat_count', 0) or 0) + 1
        self._v221_heartbeat_count = count
        try:
            _v217_target_sniper_tick(self, now=now)
        except Exception:
            pass
        try:
            candles = list(getattr(self, '_last_analysis_candles', None) or [])
        except Exception:
            candles = []
        try:
            sig = getattr(self, 'last_signal', None) or getattr(self, '_last_signal', None)
        except Exception:
            sig = None
        raw = _v221_nh_full_raw(self, sig=sig, candles=candles, now=now)
        try:
            ticker = _v221_current_ticker(self)
            target, _ = self.effective_target()
            self._set_var_if_changed(self.v220_engine_diag_var, f"PAPER ENGINE: LIVE #{count} • AUTHORITY NEWHEDGE FULL • DECISION {raw.get('side', 'WAIT')} • ticker {ticker or 'NONE'} • target {(money(target) if target is not None else 'NONE')}")
        except Exception:
            pass
        book = _v217_book(self)
        for ledger_name in ('MASTERMIND', 'BOOKMAP KING'):
            try:
                _v221_roll_shadow_market(self, ledger_name, candles=candles, now=now)
            except Exception:
                pass
        for ledger_name in ('MASTERMIND', 'BOOKMAP KING'):
            trade = dict(book[ledger_name].get('active') or {})
            if not trade:
                continue
            try:
                do_exit, reason = _v221_nh_full_exit(self, trade.get('side'), sig=sig, candles=candles, now=now, state_name=f"_v221_exit_{ledger_name.replace(' ', '_')}")
                if do_exit:
                    _v221_shadow_close(self, ledger_name, reason, now=now)
                else:
                    _v220_set_diag(self, ledger_name, f"ACTIVE {trade.get('side')} • NH FULL still holding")
            except Exception as exc:
                _v220_set_diag(self, ledger_name, f'NH FULL EXIT ERROR: {exc}')
        setup = _v221_nh_full_setup(self, sig=sig, candles=candles, now=now, state_name='_v221_nh_paper_state')
        for ledger_name in ('MASTERMIND', 'BOOKMAP KING'):
            if book[ledger_name].get('active') is None:
                try:
                    if setup.get('ready'):
                        _v221_shadow_open(self, ledger_name, setup, now=now)
                    else:
                        _v220_set_diag(self, ledger_name, f"NH FULL READ {setup.get('side', 'WAIT')} • {setup.get('reason', 'building')}")
                except Exception as exc:
                    _v220_set_diag(self, ledger_name, f'NH FULL ENTRY ERROR: {exc}')
        _v217_refresh_score_ui(self)
        _v221_refresh_visible_paper(self)
    finally:
        try:
            self.root.after(100, lambda: _v221_paper_heartbeat(self))
        except Exception:
            pass

def _v221_disable_old_v219_heartbeat(self):
    return None

def _v221_live_tick(self, warm=None, sig=None, candles=None, now=None):
    now = float(now or time.time())
    if not self.live_auto_enabled_var.get():
        return False
    candles = list(candles or getattr(self, '_last_analysis_candles', None) or [])
    sig = sig or getattr(self, 'last_signal', None) or getattr(self, '_last_signal', None)
    with self.live_trade_lock:
        live = dict(self.live_active_trade or {})
    if live:
        direction = str(live.get('direction', 'WAIT')).upper()
        do_exit, reason = _v221_nh_full_exit(self, direction, sig=sig, candles=candles, now=now, state_name='_v221_nh_live_exit_state')
        if do_exit:
            return bool(self._v86_live_submit_exit(f'NEWHEDGE FULL INTERPRETATION EXIT • {reason}'))
        try:
            self._v86_live_set(f'LIVE AUTO: ARMED • NEWHEDGE FULL holding {direction}')
        except Exception:
            pass
        return False
    if getattr(self, 'live_order_inflight', False):
        return False
    setup = _v221_nh_full_setup(self, sig=sig, candles=candles, now=now, state_name='_v221_nh_live_entry_state')
    if not setup.get('ready'):
        try:
            self._v86_live_set(f"LIVE AUTO: ARMED • NEWHEDGE FULL watching • {setup.get('reason', 'building')}")
        except Exception:
            pass
        return False
    side = str(setup.get('side', 'WAIT')).upper()
    if side not in ('UP', 'DOWN'):
        return False
    px, _, _, _ = self._kalshi_paper_price(side, 'ENTER', max_age=3.0)
    if px is None:
        self._v86_live_set(f'LIVE AUTO: NEWHEDGE FULL wants {side} • waiting executable ask')
        return False
    if float(px) > _V221_MAX_ENTRY:
        self._v86_live_set(f'LIVE AUTO: NEWHEDGE FULL {side} HARD BLOCK • {float(px) * 100:.1f}¢ > 75¢')
        return False
    setup2 = _v221_nh_full_setup(self, sig=sig, candles=candles, now=time.time(), state_name='_v221_nh_live_entry_state')
    if not setup2.get('ready') or str(setup2.get('side', '')).upper() != side:
        return False
    return bool(self._v86_live_submit_entry(side, reason=f"NEWHEDGE FULL INTERPRETATION AUTHORITY • {setup2.get('reason', '15M DECISION')}"))

def _v221_master_tick(self, warm=None, sig=None, candles=None, now=None, mode='LIVE'):
    """
    Main legacy callback now does background learning + target + NH FULL live.
    PAPER entry is owned ONLY by the dedicated V21.21 heartbeat.
    """
    now = float(now or time.time())
    candles = list(candles or getattr(self, '_last_analysis_candles', None) or [])
    sig = sig or getattr(self, 'last_signal', None) or getattr(self, '_last_signal', None)
    try:
        _v217_target_sniper_tick(self, now=now)
    except Exception:
        pass
    try:
        mm_learning = _v215_mm_reader_fast_commit(self, warm=warm, sig=sig, candles=candles, now=now)
        _v213_market_learning_tick(self, mm_learning, sig=sig, candles=candles, now=now)
    except Exception:
        pass
    try:
        return bool(_v221_live_tick(self, warm=warm, sig=sig, candles=candles, now=now))
    except Exception:
        return False

