_V222_ENTRY_HOLD = 0.1
_V222_EXIT_HOLD = 0.1
_V222_MAX_ENTRY = 0.75
_V222_SYNTH_PRICE = 0.5

def _v222_display_side(self):
    """Use the exact side visible in NEWHEDGE // FULL INTERPRETATION."""
    text = ''
    try:
        text = str(self.newhedge_decision_var.get() or '')
    except Exception:
        pass
    m = re.search('15M\\s+DECISION\\s*:\\s*(UP|DOWN)\\b', text, re.I)
    if m:
        return (m.group(1).upper(), text, 'VISIBLE PANEL')
    try:
        mm = _v214_mm3_read(self, sig=getattr(self, 'last_signal', None) or getattr(self, '_last_signal', None), candles=list(getattr(self, '_last_analysis_candles', None) or []), now=time.time())
        _, _, decision, _ = _v214_newhedge_thought_text(mm)
        m = re.search('15M\\s+DECISION\\s*:\\s*(UP|DOWN)\\b', str(decision), re.I)
        if m:
            return (m.group(1).upper(), str(decision), 'PANEL RENDER')
        nh = dict(mm.get('newhedge') or {})
        d = str(nh.get('direction', 'WAIT')).upper()
        if d in ('UP', 'DOWN'):
            return (d, f'NEWHEDGE FUSION {d}', 'NEWHEDGE FUSION')
    except Exception:
        pass
    return ('WAIT', text, 'NO DECISION')

def _v222_setup(self, now=None, state_name='_v222_paper_state'):
    now = float(now or time.time())
    side, text, source = _v222_display_side(self)
    if side not in ('UP', 'DOWN'):
        setattr(self, state_name, {})
        return {'ready': False, 'side': 'WAIT', 'reason': 'No NH Full UP/DOWN decision'}
    st = dict(getattr(self, state_name, {}) or {})
    if st.get('side') != side:
        st = {'side': side, 'since': now, 'samples': 1}
    else:
        st['samples'] = int(st.get('samples', 0) or 0) + 1
    setattr(self, state_name, st)
    held = max(0.0, now - float(st.get('since', now)))
    return {'ready': held >= _V222_ENTRY_HOLD and int(st.get('samples', 0)) >= 2, 'side': side, 'held': held, 'reason': f'{source} says {side} • {held:.2f}s', 'decision_text': text, 'decision_source': source}

def _v222_exit_signal(self, held_side, now=None, state_name='_v222_exit_state'):
    now = float(now or time.time())
    held_side = str(held_side).upper()
    opp = 'DOWN' if held_side == 'UP' else 'UP'
    side, _, source = _v222_display_side(self)
    if side != opp:
        setattr(self, state_name, {})
        return (False, '')
    st = dict(getattr(self, state_name, {}) or {})
    if st.get('side') != opp:
        st = {'side': opp, 'since': now, 'samples': 1}
    else:
        st['samples'] = int(st.get('samples', 0) or 0) + 1
    setattr(self, state_name, st)
    held = max(0.0, now - float(st.get('since', now)))
    if held >= _V222_EXIT_HOLD and int(st.get('samples', 0)) >= 2:
        return (True, f'{source} flipped {opp} • {held:.2f}s')
    return (False, '')

def _v222_paper_price(self, side, action='ENTER'):
    """Paper-only price cascade. Always returns a simulation price."""
    side = str(side).upper()
    try:
        px, _, src, age = self._kalshi_paper_price(side, action, max_age=3.0)
        if px is not None and 0 < float(px) < 1:
            return (float(px), f'REAL BOOK {src}', False)
    except Exception:
        pass
    try:
        yes = self.kalshi_yes_price()
        yes = float(yes) if yes is not None else None
        if yes is not None and 0 < yes < 1:
            px = yes if side == 'UP' else 1.0 - yes
            if 0 < px < 1:
                return (float(px), 'PAPER MID/LAST', True)
    except Exception:
        pass
    return (_V222_SYNTH_PRICE, 'PAPER SYNTHETIC 50C', True)

def _v222_schema(self):
    try:
        with self.stockpile_db_lock:
            with self._stockpile_connect() as conn:
                cols = {r[1] for r in conn.execute('PRAGMA table_info(paper_trades)').fetchall()}
                for col, ddl in (('bot_name', 'TEXT'), ('authority_name', 'TEXT'), ('quote_mode', 'TEXT')):
                    if col not in cols:
                        conn.execute(f'ALTER TABLE paper_trades ADD COLUMN {col} {ddl}')
    except Exception:
        pass

def _v222_insert_open(self, bot, trade):
    _v222_schema(self)
    try:
        side = trade['side']
        entry = float(trade['entry_contract'])
        entry_yes = entry if side == 'UP' else 1.0 - entry
        with self.stockpile_db_lock:
            with self._stockpile_connect() as conn:
                cur = conn.execute('\n                    INSERT INTO paper_trades (\n                        status,direction,entry_ts,market_ticker,bucket,target,\n                        entry_btc,entry_yes,entry_contract,stake,shares,\n                        entry_source,auto_reason,bot_name,authority_name,quote_mode\n                    ) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)\n                ', ('OPEN', side, trade['entry_ts'], trade.get('ticker'), trade['bucket'], trade.get('target'), _v221_current_btc(self), entry_yes, entry, trade['stake'], trade['contracts'], f'AUTO • {bot}', trade.get('reason', ''), bot, 'NEWHEDGE FULL INTERPRETATION', trade.get('quote_source', '')))
                return int(cur.lastrowid)
    except Exception as exc:
        try:
            self.paper_status_var.set(f'Paper journal OPEN error: {exc}')
        except Exception:
            pass
        return None

def _v222_update_close(self, trade, exit_contract, pnl, result, reason, qsrc):
    jid = trade.get('journal_id')
    if not jid:
        return
    try:
        side = trade['side']
        exit_yes = float(exit_contract) if side == 'UP' else 1.0 - float(exit_contract)
        with self.stockpile_db_lock:
            with self._stockpile_connect() as conn:
                conn.execute("\n                    UPDATE paper_trades SET\n                        status='CLOSED',exit_ts=?,exit_btc=?,exit_yes=?,\n                        exit_contract=?,pnl=?,result=?,exit_reason=?,\n                        bot_name=?,authority_name=?,quote_mode=?\n                    WHERE id=?\n                ", (time.time(), _v221_current_btc(self), exit_yes, float(exit_contract), float(pnl), result, reason, trade.get('bot_name'), 'NEWHEDGE FULL INTERPRETATION', qsrc, int(jid)))
    except Exception:
        pass

def _v222_open(self, bot, setup, now=None):
    now = float(now or time.time())
    book = _v217_book(self)
    row = book[bot]
    if row.get('active') is not None:
        return False
    bucket = int(now // 900) * 900
    if row.get('last_entry_bucket') == bucket:
        return False
    side = str(setup.get('side', 'WAIT')).upper()
    if not setup.get('ready') or side not in ('UP', 'DOWN'):
        return False
    px, qsrc, fallback = _v222_paper_price(self, side, 'ENTER')
    if float(px) > _V222_MAX_ENTRY:
        _v220_set_diag(self, bot, f'NH FULL {side} • BLOCK {px * 100:.1f}¢ >75¢')
        return False
    try:
        stake = float(self._paper_parse_stake())
    except Exception:
        stake = 10.0
    if stake <= 0:
        stake = 10.0
    try:
        target, _ = self.effective_target()
    except Exception:
        target = getattr(self, 'target_price', None)
    trade = {'bot_name': bot, 'side': side, 'bucket': bucket, 'entry_ts': now, 'entry_contract': float(px), 'stake': float(stake), 'contracts': float(stake) / max(float(px), 0.01), 'target': float(target) if target is not None else None, 'ticker': _v221_current_ticker(self), 'reason': setup.get('reason', ''), 'quote_source': qsrc, 'paper_quote_fallback': bool(fallback)}
    trade['journal_id'] = _v222_insert_open(self, bot, trade)
    row['active'] = trade
    row['last_entry_bucket'] = bucket
    row['trades'] = int(row.get('trades', 0) or 0) + 1
    row['last_result'] = f'ENTER {side} {px * 100:.1f}¢ • {qsrc}'
    _v217_log({'event': 'ENTRY', 'ts': now, **trade})
    _v217_save_book(self)
    _v217_refresh_score_ui(self)
    _v222_refresh_views(self)
    _v220_set_diag(self, bot, f'ENTERED {side} @ {px * 100:.1f}¢ • {qsrc}')
    return True

def _v222_close(self, bot, reason, now=None, settle_contract=None):
    now = float(now or time.time())
    row = _v217_book(self)[bot]
    trade = dict(row.get('active') or {})
    if not trade:
        return False
    if settle_contract is None:
        exit_c, qsrc, _ = _v222_paper_price(self, trade['side'], 'EXIT')
    else:
        exit_c, qsrc = (float(settle_contract), '15M SETTLEMENT')
    entry = float(trade['entry_contract'])
    pnl = float(trade['contracts']) * (float(exit_c) - entry)
    if pnl > 0.005:
        result = 'WIN'
        row['wins'] = int(row.get('wins', 0) or 0) + 1
    elif pnl < -0.005:
        result = 'LOSS'
        row['losses'] = int(row.get('losses', 0) or 0) + 1
    else:
        result = 'FLAT'
        row['flats'] = int(row.get('flats', 0) or 0) + 1
    row['pnl'] = float(row.get('pnl', 0) or 0) + pnl
    row['last_result'] = f'{result} {pnl:+.2f} • {reason}'
    row['active'] = None
    _v222_update_close(self, trade, exit_c, pnl, result, reason, qsrc)
    _v217_log({'event': 'EXIT', 'ts': now, 'brain': bot, 'bot_name': bot, 'authority': 'NEWHEDGE FULL INTERPRETATION', 'side': trade['side'], 'entry_contract': entry, 'exit_contract': float(exit_c), 'pnl': pnl, 'result': result, 'reason': reason, 'journal_id': trade.get('journal_id')})
    _v217_save_book(self)
    _v217_refresh_score_ui(self)
    _v222_refresh_views(self)
    return True

def _v222_roll(self, bot, candles=None, now=None):
    now = float(now or time.time())
    trade = dict(_v217_book(self)[bot].get('active') or {})
    if not trade:
        return False
    bucket = int(trade.get('bucket', 0) or 0)
    if not bucket or bucket >= int(now // 900) * 900:
        return False
    target = trade.get('target')
    final = None
    for c in list(candles or []):
        try:
            ct = float(c.get('time', 0) or 0)
            if bucket <= ct < bucket + 900:
                final = float(c['close'])
        except Exception:
            pass
    if final is None:
        final = _v221_current_btc(self)
    if final is None or target is None:
        return _v222_close(self, bot, '15M ROLLOVER • no settlement context', now=now, settle_contract=float(trade.get('entry_contract', 0.5)))
    up = float(final) >= float(target)
    won = trade['side'] == 'UP' and up or (trade['side'] == 'DOWN' and (not up))
    return _v222_close(self, bot, f'15M ROLLOVER • BTC {float(final):,.2f} vs target {float(target):,.2f}', now=now, settle_contract=1.0 if won else 0.0)

def _v222_refresh_views(self):
    """All OPEN rows + recent CLOSED rows with explicit bot identity."""
    _v222_schema(self)
    try:
        with self.stockpile_db_lock:
            with self._stockpile_connect() as conn:
                opens = conn.execute("\n                    SELECT id,COALESCE(bot_name,entry_source,'UNKNOWN'),direction,\n                           entry_contract,stake,market_ticker,authority_name,quote_mode\n                    FROM paper_trades WHERE status='OPEN'\n                    ORDER BY id DESC LIMIT 40\n                ").fetchall()
                recent = conn.execute("\n                    SELECT id,COALESCE(bot_name,entry_source,'UNKNOWN'),direction,\n                           result,pnl,entry_contract,exit_contract,market_ticker,\n                           exit_reason,authority_name\n                    FROM paper_trades WHERE status='CLOSED'\n                    ORDER BY id DESC LIMIT 20\n                ").fetchall()
    except Exception as exc:
        try:
            self.paper_active_var.set(f'Open trades error: {exc}')
            self.paper_recent_var.set(f'History error: {exc}')
        except Exception:
            pass
        return
    if opens:
        self.paper_active_var.set('\n'.join((f"#{r[0]} OPEN • {r[1]} • BET {r[2]} • {float(r[3] or 0) * 100:.1f}¢ • ${float(r[4] or 0):.2f} • {r[5] or '--'} • {r[6] or 'NH FULL'} • {r[7] or ''}" for r in opens)))
    else:
        self.paper_active_var.set('No active paper trades')
    if recent:
        lines = []
        for r in recent:
            pnl = float(r[4] or 0)
            lines.append(f"#{r[0]} {r[1]} • BET {r[2]} • {r[3] or '--'} • {float(r[5] or 0) * 100:.1f}¢→{float(r[6] or 0) * 100:.1f}¢ • {('+' if pnl >= 0 else '-')}${abs(pnl):.2f} • {r[7] or '--'} • {r[9] or 'NH FULL'} • {r[8] or ''}")
        self.paper_recent_var.set('\n'.join(lines))
    else:
        self.paper_recent_var.set('Recent paper trades: none')

