def _v222_live_tick(self, warm=None, sig=None, candles=None, now=None):
    """Same NH displayed side; real executable quote only."""
    now = float(now or time.time())
    if not self.live_auto_enabled_var.get():
        return False
    with self.live_trade_lock:
        live = dict(self.live_active_trade or {})
    if live:
        do_exit, reason = _v222_exit_signal(self, live.get('direction'), now=now, state_name='_v222_live_exit')
        if do_exit:
            return bool(self._v86_live_submit_exit(f'NEWHEDGE FULL DISPLAYED DECISION EXIT • {reason}'))
        return False
    if getattr(self, 'live_order_inflight', False):
        return False
    setup = _v222_setup(self, now=now, state_name='_v222_live_entry')
    if not setup.get('ready'):
        return False
    side = setup['side']
    px, _, _, _ = self._kalshi_paper_price(side, 'ENTER', max_age=3.0)
    if px is None:
        self._v86_live_set(f'LIVE AUTO: NH FULL {side} • waiting real ask')
        return False
    if float(px) > _V222_MAX_ENTRY:
        self._v86_live_set(f'LIVE AUTO: NH FULL {side} BLOCKED {float(px) * 100:.1f}¢ >75¢')
        return False
    side2, _, _ = _v222_display_side(self)
    if side2 != side:
        return False
    return bool(self._v86_live_submit_entry(side, reason='NEWHEDGE FULL DISPLAYED 15M DECISION AUTHORITY'))

