def _v223_hide_paper_league_ui(self):
    """Remove only the obsolete league banner/score block from the paper card."""
    try:
        mm_var = str(self.mm_paper_score_var) if hasattr(self, 'mm_paper_score_var') else ''
        bk_var = str(self.bk_paper_score_var) if hasattr(self, 'bk_paper_score_var') else ''
        stack = [self.root]
        while stack:
            w = stack.pop()
            try:
                stack.extend(list(w.winfo_children()))
            except Exception:
                pass
            try:
                txt = str(w.cget('text') or '')
            except Exception:
                txt = ''
            try:
                tv = str(w.cget('textvariable') or '')
            except Exception:
                tv = ''
            hide = txt == 'DUAL PAPER LEAGUE • BOTH BRAINS TRADE EVERY MARKET' or txt == 'LIVE BRAIN selector remains independent: MASTERMIND or BOOKMAP KING' or (mm_var and tv == mm_var) or (bk_var and tv == bk_var)
            if hide:
                try:
                    w.pack_forget()
                except Exception:
                    try:
                        w.grid_remove()
                    except Exception:
                        pass
    except Exception:
        pass

