_V224_MAX_ENTRY = 0.6
_V224_ENTRY_HOLD = 0.0

def _v224_setup(self, now=None, state_name='_v224_entry_state'):
    """
    Immediate NewHedge Full 15M decision.
    No confidence-score threshold and no extra persistence delay.
    """
    now = float(now or time.time())
    side, text, source = _v222_display_side(self)
    if side not in ('UP', 'DOWN'):
        setattr(self, state_name, {})
        return {'ready': False, 'side': 'WAIT', 'reason': 'Waiting for NewHedge Full 15M UP/DOWN decision', 'decision_text': text, 'decision_source': source}
    st = dict(getattr(self, state_name, {}) or {})
    if st.get('side') != side:
        st = {'side': side, 'since': now, 'samples': 1}
    else:
        st['samples'] = int(st.get('samples', 0) or 0) + 1
    setattr(self, state_name, st)
    return {'ready': True, 'side': side, 'held': max(0.0, now - float(st.get('since', now))), 'reason': f'{source} says {side} • IMMEDIATE VALUE ENTRY MODE', 'decision_text': text, 'decision_source': source}

def _v224_value_paper_price(self, side, action='ENTER'):
    """
    PAPER entry price:
    1) real executable book
    2) market midpoint/last
    3) synthetic 50c only if price is unavailable, never to disguise >60c
    """
    side = str(side).upper()
    try:
        px, _, src, age = self._kalshi_paper_price(side, action, max_age=3.0)
        if px is not None and 0 < float(px) < 1:
            return (float(px), f'REAL BOOK {src}', False)
    except Exception:
        pass
    try:
        yes = self.kalshi_yes_price()
        yes = float(yes) if yes is not None else None
        if yes is not None and 0 < yes < 1:
            px = yes if side == 'UP' else 1.0 - yes
            if 0 < px < 1:
                return (float(px), 'PAPER MID/LAST', True)
    except Exception:
        pass
    return (0.5, 'PAPER SYNTHETIC 50C • NO QUOTE', True)

def _v224_open(self, bot, setup, now=None):
    """
    Each bot gets one independent paper entry per 15m round.
    <=60c is a hard value ceiling.
    """
    now = float(now or time.time())
    book = _v217_book(self)
    row = book[bot]
    bucket = int(now // 900) * 900
    if row.get('active') is not None:
        return False
    if row.get('last_entry_bucket') == bucket:
        return False
    side = str(setup.get('side', 'WAIT')).upper()
    if not setup.get('ready') or side not in ('UP', 'DOWN'):
        return False
    px, qsrc, fallback = _v224_value_paper_price(self, side, 'ENTER')
    if float(px) > _V224_MAX_ENTRY:
        row['last_result'] = f'VALUE WAIT {side} {float(px) * 100:.1f}¢ > 60¢'
        _v220_set_diag(self, bot, f'NH FULL {side} • VALUE WAIT {float(px) * 100:.1f}¢ > 60¢')
        return False
    try:
        stake = float(self._paper_parse_stake())
    except Exception:
        stake = 10.0
    if stake <= 0:
        stake = 10.0
    try:
        target, _ = self.effective_target()
    except Exception:
        target = getattr(self, 'target_price', None)
    trade = {'bot_name': bot, 'side': side, 'bucket': bucket, 'entry_ts': now, 'entry_contract': float(px), 'stake': float(stake), 'contracts': float(stake) / max(float(px), 0.01), 'target': float(target) if target is not None else None, 'ticker': _v221_current_ticker(self), 'reason': setup.get('reason', ''), 'quote_source': qsrc, 'paper_quote_fallback': bool(fallback), 'value_rule': '<=60C'}
    trade['journal_id'] = _v222_insert_open(self, bot, trade)
    row['active'] = trade
    row['last_entry_bucket'] = bucket
    row['trades'] = int(row.get('trades', 0) or 0) + 1
    row['last_result'] = f'ENTER {side} {float(px) * 100:.1f}¢ • VALUE <=60C'
    _v217_log({'event': 'ENTRY', 'ts': now, **trade})
    _v217_save_book(self)
    _v217_refresh_score_ui(self)
    _v222_refresh_views(self)
    _v220_set_diag(self, bot, f'ENTERED {side} @ {float(px) * 100:.1f}¢ • <=60C RULE • {qsrc}')
    return True

