def _v226_authority_setup(self, authority, warm=None, sig=None, candles=None, now=None):
    authority = str(authority).upper()
    now = float(now or time.time())
    if authority == 'BOOKMAP KING':
        try:
            setup = _v216_bookmap_setup(self, warm=warm, now=now)
        except Exception:
            setup = {}
        out = dict(setup or {})
        side = str(out.get('side', 'WAIT')).upper()
        out['ready'] = bool(out.get('ready')) and side in ('UP', 'DOWN')
        out['authority'] = 'BOOKMAP KING'
        return out
    out = _v224_setup(self, now=now, state_name='_v226_newhedge_authority_state')
    out = dict(out or {})
    out['authority'] = 'NEWHEDGE'
    return out

def _v226_paper_open(self, bot, setup, now=None):
    """
    Same paper journal/open mechanics as V21.24, but 70c hard ceiling.
    """
    now = float(now or time.time())
    book = _v217_book(self)
    row = book[bot]
    bucket = int(now // 900) * 900
    if row.get('active') is not None:
        return False
    if row.get('last_entry_bucket') == bucket:
        return False
    side = str(setup.get('side', 'WAIT')).upper()
    if not setup.get('ready') or side not in ('UP', 'DOWN'):
        return False
    px, qsrc, fallback = _v224_value_paper_price(self, side, 'ENTER')
    if float(px) > _V226_MAX_ENTRY:
        row['last_result'] = f'VALUE WAIT {side} {float(px) * 100:.1f}¢ > 70¢'
        _v220_set_diag(self, bot, f"{setup.get('authority', 'AUTH')} {side} • VALUE WAIT {float(px) * 100:.1f}¢ > 70¢")
        return False
    try:
        stake = float(self._paper_parse_stake())
    except Exception:
        stake = 10.0
    if stake <= 0:
        stake = 10.0
    try:
        target, _ = self.effective_target()
    except Exception:
        target = getattr(self, 'target_price', None)
    trade = {'bot_name': bot, 'side': side, 'bucket': bucket, 'entry_ts': now, 'entry_contract': float(px), 'stake': float(stake), 'contracts': float(stake) / max(float(px), 0.01), 'target': float(target) if target is not None else None, 'ticker': _v221_current_ticker(self), 'reason': setup.get('reason', ''), 'quote_source': qsrc, 'paper_quote_fallback': bool(fallback), 'value_rule': '<=70C', 'authority': setup.get('authority', 'NEWHEDGE')}
    trade['journal_id'] = _v222_insert_open(self, bot, trade)
    row['active'] = trade
    row['last_entry_bucket'] = bucket
    row['trades'] = int(row.get('trades', 0) or 0) + 1
    row['last_result'] = f"ENTER {side} {float(px) * 100:.1f}¢ • {trade['authority']} • <=70C"
    _v217_log({'event': 'ENTRY', 'ts': now, **trade})
    _v217_save_book(self)
    _v217_refresh_score_ui(self)
    _v222_refresh_views(self)
    _v220_set_diag(self, bot, f"ENTERED {side} @ {float(px) * 100:.1f}¢ • {trade['authority']} • <=70C • {qsrc}")
    return True

def _v226_paper_heartbeat(self):
    try:
        now = time.time()
        count = int(getattr(self, '_v226_hb', 0) or 0) + 1
        self._v226_hb = count
        candles = list(getattr(self, '_last_analysis_candles', None) or [])
        try:
            paper_on = bool(self.auto_paper_enabled_var.get())
        except Exception:
            paper_on = False
        nh_setup = _v224_setup(self, now=now, state_name='_v226_paper_nh')
        nh_setup = dict(nh_setup or {})
        nh_setup['authority'] = 'NEWHEDGE'
        try:
            bk_setup = dict(_v216_bookmap_setup(self, warm=None, now=now) or {})
        except Exception:
            bk_setup = {}
        bk_setup['authority'] = 'BOOKMAP KING'
        try:
            self._set_var_if_changed(self.v220_engine_diag_var, f"PAPER V21.26 {('ON' if paper_on else 'OFF')} #{count} • NH {nh_setup.get('side', 'WAIT')} • BK {bk_setup.get('side', 'WAIT')} • HARD CAP <=70C")
        except Exception:
            pass
        book = _v217_book(self)
        for bot in ('MASTERMIND', 'BOOKMAP KING'):
            try:
                _v222_roll(self, bot, candles=candles, now=now)
            except Exception:
                pass
        for bot in ('MASTERMIND', 'BOOKMAP KING'):
            trade = dict(book[bot].get('active') or {})
            if trade:
                try:
                    do_exit, reason = _v222_exit_signal(self, trade['side'], now=now, state_name=f"_v226_exit_{bot.replace(' ', '_')}")
                    if do_exit:
                        _v222_close(self, bot, reason, now=now)
                except Exception:
                    pass
        if paper_on:
            if book['MASTERMIND'].get('active') is None and nh_setup.get('ready'):
                _v226_paper_open(self, 'MASTERMIND', nh_setup, now=now)
            if book['BOOKMAP KING'].get('active') is None and bk_setup.get('ready'):
                _v226_paper_open(self, 'BOOKMAP KING', bk_setup, now=now)
        _v217_refresh_score_ui(self)
        _v222_refresh_views(self)
    finally:
        try:
            self.root.after(100, lambda: _v226_paper_heartbeat(self))
        except Exception:
            pass

def _v226_live_preview_tick(self, warm=None, sig=None, candles=None, now=None):
    """
    Preview only. Shows exactly what would be attempted, but never sends money.
    """
    now = float(now or time.time())
    try:
        enabled = bool(self.live_auto_enabled_var.get())
    except Exception:
        enabled = False
    if not enabled:
        return False
    authority = _v226_authority_name(self)
    setup = _v226_authority_setup(self, authority, warm=warm, sig=sig, candles=candles, now=now)
    if not setup.get('ready'):
        self._v86_live_set(f'LIVE PREVIEW: {authority} • waiting for UP/DOWN setup')
        return False
    side = str(setup.get('side', 'WAIT')).upper()
    if side not in ('UP', 'DOWN'):
        self._v86_live_set(f'LIVE PREVIEW: {authority} • WAIT')
        return False
    px, _, _, _ = self._kalshi_paper_price(side, 'ENTER', max_age=3.0)
    if px is None:
        self._v86_live_set(f'LIVE PREVIEW: {authority} {side} • waiting real executable ask')
        return False
    px = float(px)
    if px > _V226_MAX_ENTRY:
        self._v86_live_set(f'LIVE PREVIEW: {authority} {side} • BLOCKED {px * 100:.1f}¢ > 70¢')
        return False
    try:
        stake = float(self._v86_live_stake())
    except Exception:
        stake = 10.0
    count = int(math.floor(stake / max(px, 0.01) + 1e-09))
    self._v86_live_set(f'LIVE PREVIEW: WOULD BUY {side} • {authority} • {count} contracts • {px * 100:.1f}¢ <=70¢', f'LIVE POSITION PREVIEW: no real order sent')
    return True

