def _v227_paper_price(self, side):
    """
    Guaranteed PAPER data price. This is simulation-only.
    """
    side = str(side).upper()
    try:
        px, _, src, age = self._kalshi_paper_price(side, 'ENTER', max_age=3.0)
        if px is not None:
            px = float(px)
            if 0 < px < 1:
                if px <= _V227_PAPER_CAP:
                    return (px, f'PAPER REAL QUOTE • {src}', False)
                return (_V227_PAPER_CAP, f'PAPER CAPPED SAMPLE 70C • observed {px * 100:.1f}¢', True)
    except Exception:
        pass
    try:
        yes = self.kalshi_yes_price()
        yes = float(yes) if yes is not None else None
        if yes is not None and 0 < yes < 1:
            px = yes if side == 'UP' else 1.0 - yes
            if px <= _V227_PAPER_CAP:
                return (float(px), 'PAPER MID/LAST', True)
            return (_V227_PAPER_CAP, f'PAPER CAPPED SAMPLE 70C • observed {float(px) * 100:.1f}¢', True)
    except Exception:
        pass
    return (0.5, 'PAPER SYNTHETIC 50C • NO QUOTE', True)

