def _v227_refresh_open_with_shadow(self):
    """
    Keep OPEN PAPER TRADES visible even if SQLite has a temporary failure.
    Existing DB view remains primary; active shadow trades are appended.
    """
    try:
        _v222_refresh_views(self)
    except Exception:
        pass
    try:
        book = _v217_book(self)
        shadow_lines = []
        for bot in ('MASTERMIND', 'BOOKMAP KING'):
            t = dict(book.get(bot, {}).get('active') or {})
            if not t:
                continue
            shadow_lines.append(f"{bot} • {t.get('side', 'WAIT')} • {float(t.get('entry_contract', 0)) * 100:.1f}¢ • ${float(t.get('stake', 0)):.2f} • {t.get('authority', bot)} • {t.get('quote_source', '')}")
        if shadow_lines and hasattr(self, 'v222_open_var'):
            current = str(self.v222_open_var.get() or '')
            missing = [ln for ln in shadow_lines if ln.split(' • ', 1)[0] not in current]
            if missing:
                merged = current.rstrip()
                if merged:
                    merged += '\n'
                merged += '\n'.join(missing)
                self.v222_open_var.set(merged)
    except Exception:
        pass

