def _v228_find_team_mm_box(self):
    root = getattr(self, 'page_frame', None)
    if root is None:
        return None

    def walk(widget):
        try:
            children = list(widget.winfo_children())
        except Exception:
            return None
        for child in children:
            try:
                if str(child.winfo_class()) in ('TLabel', 'Label'):
                    if str(child.cget('text') or '') == 'TEAM MASTERMIND FUTURE DESK':
                        return child.master
            except Exception:
                pass
            found = walk(child)
            if found is not None:
                return found
        return None
    return walk(root)

def _v228_reset_lock_state(state, bucket):
    return {'bucket': bucket, 'locked': 'WAIT', 'locked_ts': 0.0, 'candidate': 'WAIT', 'candidate_since': 0.0, 'flip_candidate': 'WAIT', 'flip_since': 0.0, 'last_reason': ''}

def _v228_formulate_newhedge_lock(self, mm, now=None):
    now = float(now or time.time())
    bucket = _v228_bucket(now)
    st = dict(getattr(self, '_v228_nh_lock_state', {}) or {})
    if st.get('bucket') != bucket:
        st = _v228_reset_lock_state(st, bucket)
    nh = dict((mm or {}).get('newhedge') or {})
    side = _v228_side(nh.get('direction'))
    strength = float(nh.get('strength', 0) or 0)
    quality = float(nh.get('quality', 0) or 0)
    aligned = int(nh.get('aligned_families', 0) or 0)
    families = int(nh.get('families', 0) or 0)
    evidence_count = len(tuple(nh.get('evidence') or ()))
    usable = side in ('UP', 'DOWN') and strength >= 38.0 and (quality >= 0.4) and (max(aligned, evidence_count) >= 2)
    strong = side in ('UP', 'DOWN') and strength >= 62.0 and (quality >= 0.58) and (max(aligned, evidence_count) >= 3)
    locked = _v228_side(st.get('locked'))
    if locked == 'WAIT':
        if usable:
            if _v228_side(st.get('candidate')) != side:
                st['candidate'] = side
                st['candidate_since'] = now
            age = max(0.0, now - float(st.get('candidate_since', now) or now))
            needed = 2.25 if strong else 4.5
            if age >= needed:
                st['locked'] = side
                st['locked_ts'] = now
                st['candidate'] = 'WAIT'
                st['candidate_since'] = 0.0
                st['last_reason'] = f'strength {strength:.0f}% • quality {quality * 100:.0f}% • {max(aligned, evidence_count)} evidence families'
        else:
            st['candidate'] = 'WAIT'
            st['candidate_since'] = 0.0
    else:
        opposite = 'DOWN' if locked == 'UP' else 'UP'
        flip_usable = side == opposite and strength >= 52.0 and (quality >= 0.5) and (max(aligned, evidence_count) >= 3)
        if flip_usable:
            if _v228_side(st.get('flip_candidate')) != opposite:
                st['flip_candidate'] = opposite
                st['flip_since'] = now
            flip_age = max(0.0, now - float(st.get('flip_since', now) or now))
            needed = 4.0 if strength >= 70 and quality >= 0.65 else 6.0
            if flip_age >= needed:
                st['locked'] = opposite
                st['locked_ts'] = now
                st['flip_candidate'] = 'WAIT'
                st['flip_since'] = 0.0
                st['last_reason'] = f'confirmed rotation • strength {strength:.0f}% • quality {quality * 100:.0f}%'
        else:
            st['flip_candidate'] = 'WAIT'
            st['flip_since'] = 0.0
    self._v228_nh_lock_state = st
    locked = _v228_side(st.get('locked'))
    if locked in ('UP', 'DOWN'):
        age = max(0.0, now - float(st.get('locked_ts', now) or now))
        text = f'NEWHEDGE LOCK: {locked} LOCKED • strength {strength:.0f}% • quality {quality * 100:.0f}% • {max(aligned, evidence_count)} evidence families • held {age:.1f}s'
        if _v228_side(st.get('flip_candidate')) in ('UP', 'DOWN'):
            fa = max(0.0, now - float(st.get('flip_since', now) or now))
            text += f" • opposite {_v228_side(st.get('flip_candidate'))} proving {fa:.1f}s"
    elif usable:
        age = max(0.0, now - float(st.get('candidate_since', now) or now))
        needed = 2.25 if strong else 4.5
        text = f'NEWHEDGE LOCK: FORMULATING {side} • {age:.1f}/{needed:.1f}s stable • strength {strength:.0f}% • quality {quality * 100:.0f}% • {max(aligned, evidence_count)} evidence families'
    else:
        text = f'NEWHEDGE LOCK: UNLOCKED • waiting for evidence to add up • current {side} • strength {strength:.0f}% • quality {quality * 100:.0f}%'
    return {'side': locked, 'text': text, 'state': st}

def _v228_formulate_mastermind_lock(self, mm, now=None):
    now = float(now or time.time())
    bucket = _v228_bucket(now)
    st = dict(getattr(self, '_v228_mm_lock_state', {}) or {})
    if st.get('bucket') != bucket:
        st = _v228_reset_lock_state(st, bucket)
    committed = _v228_side((mm or {}).get('committed_side', (mm or {}).get('settlement_side')))
    settle = _v228_side((mm or {}).get('settlement_side'))
    early = _v228_side((mm or {}).get('early_side', settle))
    score = float((mm or {}).get('settlement_score', (mm or {}).get('score', 0)) or 0)
    early_score = float((mm or {}).get('early_score', score) or 0)
    conv = int((mm or {}).get('settlement_convergence', 0) or 0)
    fam = int((mm or {}).get('family_count', 0) or 0)
    straight = bool((mm or {}).get('straight_shot'))
    side = committed if committed in ('UP', 'DOWN') else settle
    aligned = side in ('UP', 'DOWN') and settle == side and (early == side or early == 'WAIT' or early_score >= 84)
    usable = aligned and score >= 84.0 and (conv >= 2 or fam >= 4)
    strong = aligned and score >= 93.0 and (conv >= 2)
    locked = _v228_side(st.get('locked'))
    if locked == 'WAIT':
        if usable:
            if _v228_side(st.get('candidate')) != side:
                st['candidate'] = side
                st['candidate_since'] = now
            age = max(0.0, now - float(st.get('candidate_since', now) or now))
            needed = 1.50 if strong or straight else 3.10
            if age >= needed:
                st['locked'] = side
                st['locked_ts'] = now
                st['candidate'] = 'WAIT'
                st['candidate_since'] = 0.0
                st['last_reason'] = f'score {score:.0f}/100 • convergence {conv}/3 • families {fam}'
        else:
            st['candidate'] = 'WAIT'
            st['candidate_since'] = 0.0
    else:
        opposite = 'DOWN' if locked == 'UP' else 'UP'
        flip_ok = side == opposite and settle == opposite and (score >= 91.0) and (conv >= 2) and (early == opposite or early_score >= 90)
        if flip_ok:
            if _v228_side(st.get('flip_candidate')) != opposite:
                st['flip_candidate'] = opposite
                st['flip_since'] = now
            age = max(0.0, now - float(st.get('flip_since', now) or now))
            needed = 3.0 if score >= 96 else 4.8
            if age >= needed:
                st['locked'] = opposite
                st['locked_ts'] = now
                st['flip_candidate'] = 'WAIT'
                st['flip_since'] = 0.0
                st['last_reason'] = f'confirmed MM rotation • score {score:.0f}/100 • convergence {conv}/3'
        else:
            st['flip_candidate'] = 'WAIT'
            st['flip_since'] = 0.0
    self._v228_mm_lock_state = st
    locked = _v228_side(st.get('locked'))
    if locked in ('UP', 'DOWN'):
        age = max(0.0, now - float(st.get('locked_ts', now) or now))
        text = f'MASTERMIND LOCK: {locked} LOCKED • settlement {score:.0f}/100 • convergence {conv}/3 • families {fam} • held {age:.1f}s'
        if _v228_side(st.get('flip_candidate')) in ('UP', 'DOWN'):
            fa = max(0.0, now - float(st.get('flip_since', now) or now))
            text += f" • opposite {_v228_side(st.get('flip_candidate'))} proving {fa:.1f}s"
    elif usable:
        age = max(0.0, now - float(st.get('candidate_since', now) or now))
        needed = 1.50 if strong or straight else 3.10
        text = f'MASTERMIND LOCK: FORMULATING {side} • {age:.1f}/{needed:.1f}s stable • score {score:.0f}/100 • convergence {conv}/3 • families {fam}'
    else:
        text = f'MASTERMIND LOCK: UNLOCKED • letting the evidence formulate • committed {committed} • settlement {score:.0f}/100 • convergence {conv}/3'
    return {'side': locked, 'text': text, 'state': st}

def _v228_breakout_latch_update(self, trend_state, now=None):
    now = float(now or time.time())
    bucket = _v228_bucket(now)
    st = dict(getattr(self, '_v228_breakout_latch', {}) or {})
    if st.get('bucket') != bucket:
        st = {'bucket': bucket, 'active': False, 'side': 'WAIT', 'latched_ts': 0.0, 'score': 0.0, 'families': 0}
    trend = dict(trend_state or {})
    status = str(trend.get('status', '') or '').upper()
    flip_to = _v228_side(trend.get('flip_to'))
    risk = float(trend.get('risk', 0) or 0)
    team = dict(trend.get('team_breakout') or {})
    stage = str(team.get('stage', '') or '').upper()
    score = float(team.get('score', 0) or 0)
    families = int(team.get('families', 0) or 0)
    point_of_no_return = status == 'BREAKOUT CONFIRMED' and flip_to in ('UP', 'DOWN') and (stage == 'CONFIRMED' or risk >= 88.0)
    if point_of_no_return:
        if not st.get('active'):
            st.update({'active': True, 'side': flip_to, 'latched_ts': now, 'score': score, 'families': families})
        elif _v228_side(st.get('side')) != flip_to:
            st.update({'active': True, 'side': flip_to, 'latched_ts': now, 'score': score, 'families': families})
        else:
            st['score'] = max(float(st.get('score', 0) or 0), score)
            st['families'] = max(int(st.get('families', 0) or 0), families)
    self._v228_breakout_latch = st
    return st

def _v228_build_ui(self):
    if not hasattr(self, 'newhedge_lock_var'):
        self.newhedge_lock_var = tk.StringVar(value='NEWHEDGE LOCK: UNLOCKED • waiting for evidence to add up')
    if not hasattr(self, 'mastermind_lock_var'):
        self.mastermind_lock_var = tk.StringVar(value='MASTERMIND LOCK: UNLOCKED • letting the evidence formulate')
    if not hasattr(self, 'breakout_latch_var'):
        self.breakout_latch_var = tk.StringVar(value='BREAKOUT LATCH: monitoring for point of no return')
    _V228_BASE_BUILD_UI(self)
    try:
        nh_box = getattr(self, '_v214_nh_box', None)
        if nh_box is not None:
            ttk.Separator(nh_box).pack(fill='x', pady=(6, 4))
            ttk.Label(nh_box, textvariable=self.newhedge_lock_var, style='Strong.Card.TLabel', wraplength=1500, justify='left').pack(anchor='w', fill='x', pady=(1, 2))
    except Exception:
        pass
    try:
        mm_box = _v228_find_team_mm_box(self)
        if mm_box is not None:
            ttk.Separator(mm_box).pack(fill='x', pady=(5, 4))
            ttk.Label(mm_box, textvariable=self.mastermind_lock_var, style='Strong.Card.TLabel', wraplength=1500, justify='left').pack(anchor='w', fill='x', pady=(1, 2))
            ttk.Label(mm_box, textvariable=self.breakout_latch_var, style='Strong.Card.TLabel', wraplength=1500, justify='left').pack(anchor='w', fill='x', pady=(1, 0))
    except Exception:
        pass

def _v228_update_mastermind_panel(self, sig, candles):
    try:
        _V228_BASE_PANEL(self, sig, candles)
    except Exception:
        pass
    try:
        now = time.time()
        mm = _v214_mm3_read(self, sig=sig, candles=candles, now=now)
        nh_lock = _v228_formulate_newhedge_lock(self, mm, now=now)
        mm_lock = _v228_formulate_mastermind_lock(self, mm, now=now)
        if hasattr(self, 'newhedge_lock_var'):
            self._set_var_if_changed(self.newhedge_lock_var, nh_lock['text'])
        if hasattr(self, 'mastermind_lock_var'):
            self._set_var_if_changed(self.mastermind_lock_var, mm_lock['text'])
        trend = dict((sig or {}).get('trend_reversal') or {})
        latch = _v228_breakout_latch_update(self, trend, now=now)
        if hasattr(self, 'breakout_latch_var'):
            if latch.get('active'):
                age = max(0.0, now - float(latch.get('latched_ts', now) or now))
                self._set_var_if_changed(self.breakout_latch_var, f"BREAKOUT LATCH: {latch.get('side', 'WAIT')} • POINT OF NO RETURN • RED / CONFIRMED • held {age:.1f}s • opposite confirmation required to rotate")
            else:
                self._set_var_if_changed(self.breakout_latch_var, 'BREAKOUT LATCH: monitoring • not yet point of no return')
    except Exception:
        pass

def _v228_update_reversal_panel(self, d, lock_state=None, trend_state=None):
    trend_state = trend_state or {}
    try:
        _v228_breakout_latch_update(self, trend_state, now=time.time())
    except Exception:
        pass
    _V228_BASE_REVERSAL_PANEL(self, d, lock_state=lock_state, trend_state=trend_state)
    latch = dict(getattr(self, '_v228_breakout_latch', {}) or {})
    if not latch.get('active'):
        return
    side = _v228_side(latch.get('side'))
    if side not in ('UP', 'DOWN'):
        return
    self.trend_reversal_risk_value = max(92.0, float(getattr(self, 'trend_reversal_risk_value', 0) or 0))
    try:
        self.trend_reversal_risk_var.set(f'FLIP / BREAKOUT RISK {self.trend_reversal_risk_value:.0f}/100 • POINT OF NO RETURN')
        self.trend_reversal_status_var.set(f'BREAKOUT CONFIRMED • {side} • POINT OF NO RETURN LATCHED')
        age = max(0.0, time.time() - float(latch.get('latched_ts', time.time()) or time.time()))
        self.trend_reversal_detail_var.set(f'{side} breakout remains confirmed/red until an opposite breakout is itself CONFIRMED • latched {age:.1f}s')
        if getattr(self, 'trend_reversal_status_label', None) is not None:
            self.trend_reversal_status_label.configure(fg=RED)
        _v228_draw_trend_risk_bar(self)
    except Exception:
        pass

def _v228_draw_trend_risk_bar(self):
    latch = dict(getattr(self, '_v228_breakout_latch', {}) or {})
    if not latch.get('active'):
        return _V228_BASE_DRAW_RISK(self)
    canvas = getattr(self, 'trend_reversal_risk_canvas', None)
    if canvas is None:
        return
    try:
        w = max(canvas.winfo_width(), 240)
        h = max(canvas.winfo_height(), 24)
    except Exception:
        w, h = (280, 24)
    value = max(92.0, min(100.0, float(getattr(self, 'trend_reversal_risk_value', 92.0) or 92.0)))
    fill_w = (w - 2) * (value / 100.0)
    side = _v228_side(latch.get('side'))
    if not getattr(self, '_risk_bar_items', None):
        bg = canvas.create_rectangle(1, 1, w - 1, h - 1, fill=PANEL2, outline=PANEL2)
        fg = canvas.create_rectangle(1, 1, 1 + fill_w, h - 1, fill=RED, outline='')
        tx = canvas.create_text(w / 2, h / 2, text=f'BREAKOUT {side} • PONR {value:.0f}/100', fill=TEXT, font=('Segoe UI', 10, 'bold'))
        self._risk_bar_items = (bg, fg, tx)
    else:
        bg, fg, tx = self._risk_bar_items
        canvas.coords(bg, 1, 1, w - 1, h - 1)
        canvas.coords(fg, 1, 1, max(1, 1 + fill_w), h - 1)
        canvas.itemconfigure(fg, fill=RED, state='normal')
        canvas.coords(tx, w / 2, h / 2)
        canvas.itemconfigure(tx, text=f'BREAKOUT {side} • PONR {value:.0f}/100')
ChartKingPro._build_ui = _v228_build_ui
ChartKingPro._update_mastermind_panel = _v228_update_mastermind_panel
ChartKingPro._update_reversal_panel = _v228_update_reversal_panel
ChartKingPro._draw_trend_risk_bar = _v228_draw_trend_risk_bar
_V229_BASE_INIT = ChartKingPro.__init__
_V229_BASE_OPEN_LOCK = ChartKingPro._bookmap_opening_lock_tick
_V229_BASE_TEAM_BREAKOUT = _v212_team_breakout_read

def _v229_mount_lock_segments(self):
    """Mount unmistakable boxed lock segments after every legacy UI has mounted."""
    if getattr(self, '_v229_lock_segments_mounted', False):
        return True
    nh_box = getattr(self, '_v214_nh_box', None)
    mm_box = _v228_find_team_mm_box(self)
    if nh_box is None or mm_box is None:
        return False
    try:
        nh_seg = tk.Frame(nh_box, bg=PANEL2, highlightthickness=2, highlightbackground=CYAN, highlightcolor=CYAN, padx=10, pady=8)
        nh_seg.pack(fill='x', pady=(8, 3))
        tk.Label(nh_seg, text='NEWHEDGE FORMULATED LOCK', bg=PANEL2, fg=CYAN, font=('Segoe UI', 10, 'bold'), anchor='w').pack(fill='x')
        tk.Label(nh_seg, textvariable=self.newhedge_lock_var, bg=PANEL2, fg=TEXT, font=('Segoe UI', 10, 'bold'), anchor='w', justify='left', wraplength=1450).pack(fill='x', pady=(4, 0))
        tk.Label(nh_seg, text='Independent NewHedge lock • waits for its own evidence to mature • resets each 15m market', bg=PANEL2, fg=MUTED, font=('Segoe UI', 9), anchor='w', justify='left', wraplength=1450).pack(fill='x', pady=(2, 0))
        self._v229_nh_lock_segment = nh_seg
    except Exception:
        return False
    try:
        mm_seg = tk.Frame(mm_box, bg=PANEL2, highlightthickness=2, highlightbackground=CYAN, highlightcolor=CYAN, padx=10, pady=8)
        mm_seg.pack(fill='x', pady=(8, 3))
        tk.Label(mm_seg, text='MASTERMIND FORMULATED LOCK', bg=PANEL2, fg=CYAN, font=('Segoe UI', 10, 'bold'), anchor='w').pack(fill='x')
        tk.Label(mm_seg, textvariable=self.mastermind_lock_var, bg=PANEL2, fg=TEXT, font=('Segoe UI', 10, 'bold'), anchor='w', justify='left', wraplength=1450).pack(fill='x', pady=(4, 0))
        tk.Label(mm_seg, text='Independent Mastermind lock • settlement/convergence evidence must formulate first', bg=PANEL2, fg=MUTED, font=('Segoe UI', 9), anchor='w', justify='left', wraplength=1450).pack(fill='x', pady=(2, 0))
        self._v229_mm_lock_segment = mm_seg
    except Exception:
        try:
            nh_seg.destroy()
        except Exception:
            pass
        return False
    self._v229_lock_segments_mounted = True
    return True

def _v229_init(self, *args, **kwargs):
    _V229_BASE_INIT(self, *args, **kwargs)
    try:
        _v229_mount_lock_segments(self)
    except Exception:
        pass
    for delay in (60, 180, 400, 900):
        try:
            self.root.after(delay, lambda s=self: _v229_mount_lock_segments(s))
        except Exception:
            pass
    self._v229_open_state = {}
    self._v229_target_motion = []
    try:
        self.root.title('BOOKMAP KING V21.29 — VISIBLE LOCK BOXES + PATIENT OPEN LOCK + TARGET MOTION BREAKOUT')
    except Exception:
        pass

def _v229_bookmap_opening_lock_tick(self, warm, now=None):
    """
    OPEN LOCK with NO rush/deadline.

    It can remain BUILDING for as long as necessary. A side freezes only after:
      • native Bookmap evidence has a directional candidate,
      • Kalshi target geometry is not materially contradicting it,
      • Bookmap price movement is sufficiently stable in that direction,
      • the candidate survives enough samples/time for its observed quality.

    There is intentionally no maximum wait time.
    """
    now = float(now or time.time())
    bucket = int(now // 900) * 900
    if self.opening_lock_bucket != bucket:
        self.opening_lock_bucket = bucket
        self.opening_lock_snapshot = None
        self.opening_lock_candidate = None
        self.opening_lock_candidate_since = 0.0
        self._v229_open_state = {'bucket': bucket, 'candidate': 'WAIT', 'since': 0.0, 'samples': 0, 'ema': 0.0, 'flips': 0, 'last_live': None, 'last_ts': now, 'velocity_ema': 0.0, 'target_signed': 0.0}
        self.opening_lock_var.set('OPEN LOCK: BUILDING • NO DEADLINE • waiting for Bookmap evidence to mature')
    if self.opening_lock_snapshot:
        return dict(self.opening_lock_snapshot)
    if not warm or not warm.get('ready'):
        self.opening_lock_var.set('OPEN LOCK: BUILDING • NO DEADLINE • waiting for native Bookmap flow')
        return None
    live = float(warm.get('live', 0.0) or 0.0)
    signed = max(-1.0, min(1.0, float(warm.get('signed', 0.0) or 0.0)))
    st = dict(getattr(self, '_v229_open_state', {}) or {})
    if st.get('bucket') != bucket:
        st = {'bucket': bucket, 'candidate': 'WAIT', 'since': 0.0, 'samples': 0, 'ema': 0.0, 'flips': 0, 'last_live': None, 'last_ts': now, 'velocity_ema': 0.0, 'target_signed': 0.0}
    prev_live = st.get('last_live')
    prev_ts = float(st.get('last_ts', now) or now)
    dt = max(0.05, now - prev_ts)
    velocity = 0.0 if prev_live is None else (live - float(prev_live)) / dt
    velocity_ema = float(st.get('velocity_ema', 0.0) or 0.0) * 0.72 + velocity * 0.28
    target = None
    target_source = ''
    target_signed = 0.0
    target_distance = 0.0
    try:
        target, target_source = self.effective_target()
    except Exception:
        target, target_source = (None, '')
    range_ref = 25.0
    try:
        if self.btc_15m:
            c = self.btc_15m[-1]
            range_ref = max(25.0, float(c.get('high', live)) - float(c.get('low', live)), abs(live - float(c.get('open', live))))
    except Exception:
        pass
    if target is not None and live > 0:
        target = float(target)
        target_distance = live - target
        target_signed = max(-2.0, min(2.0, target_distance / max(range_ref, 1e-09)))
    velocity_norm = max(-1.0, min(1.0, velocity_ema / 12.0))
    composite = signed * 0.68 + max(-1.0, min(1.0, target_signed)) * 0.2 + velocity_norm * 0.12
    ema = float(st.get('ema', 0.0) or 0.0) * 0.74 + composite * 0.26
    candidate = 'UP' if ema >= 0.3 else 'DOWN' if ema <= -0.3 else 'WAIT'
    previous_candidate = str(st.get('candidate', 'WAIT')).upper()
    if candidate == 'WAIT':
        st['samples'] = max(0, int(st.get('samples', 0) or 0) - 1)
        st['ema'] = ema
        st['last_live'] = live
        st['last_ts'] = now
        st['velocity_ema'] = velocity_ema
        st['target_signed'] = target_signed
        self._v229_open_state = st
        self.opening_lock_candidate = None
        self.opening_lock_candidate_since = 0.0
        self.opening_lock_var.set(f'OPEN LOCK: BUILDING • NO DEADLINE • evidence {ema:+.2f} • target {target_distance:+.1f}$ • motion {velocity_ema:+.2f}$/s')
        return None
    if previous_candidate != candidate:
        if previous_candidate in ('UP', 'DOWN'):
            st['flips'] = int(st.get('flips', 0) or 0) + 1
        st['candidate'] = candidate
        st['since'] = now
        st['samples'] = 1
    else:
        st['samples'] = int(st.get('samples', 0) or 0) + 1
    st['ema'] = ema
    st['last_live'] = live
    st['last_ts'] = now
    st['velocity_ema'] = velocity_ema
    st['target_signed'] = target_signed
    self._v229_open_state = st
    self.opening_lock_candidate = candidate
    self.opening_lock_candidate_since = float(st.get('since', now) or now)
    age = max(0.0, now - float(st.get('since', now) or now))
    samples = int(st.get('samples', 0) or 0)
    flips = int(st.get('flips', 0) or 0)
    direction_sign = 1.0 if candidate == 'UP' else -1.0
    flow_support = signed * direction_sign
    target_support = target_signed * direction_sign if target is not None else 0.0
    motion_support = velocity_norm * direction_sign
    strength = abs(ema)

    # V21.42: slightly calmer normal lane than V21.41.
    required_age = 1.95
    if strength < 0.42:
        required_age += 1.30
    if strength < 0.35:
        required_age += 1.65
    required_age += min(5.0, flips * 0.70)
    required_samples = 6 + min(12, flips * 2)

    supports = 0
    if flow_support >= 0.24:
        supports += 1
    if target is None or target_support >= -0.12:
        supports += 1
    if motion_support >= -0.08:
        supports += 1
    if target is not None and target_support >= 0.18:
        supports += 1
    if motion_support >= 0.18:
        supports += 1

    # Structure context: entering a hostile order block should make Bookmap
    # prove the lock a little longer. A clean snipe is not allowed through a
    # hostile zone.
    try:
        structure_ctx = _v242_structure_context(self, now=now, live=live)
    except Exception:
        structure_ctx = {}
    ob_signed_up = float(structure_ctx.get('order_block_signed_up', 0.0) or 0.0)
    ob_support = ob_signed_up * direction_sign
    hostile_order_block = bool(structure_ctx.get('inside_order_block')) and ob_support <= -0.28
    if hostile_order_block:
        required_age += 0.90
        required_samples += 2

    # CLEAN SNIPE LANE:
    # still available for genuinely obvious straight shots, but only when
    # flow + evidence breadth + target + motion are aligned and there was no
    # candidate wobble or hostile order-block context.
    clean_snipe = (
        flips == 0
        and strength >= 0.48
        and flow_support >= 0.38
        and supports >= 4
        and (target is None or target_support >= 0.10)
        and motion_support >= 0.05
        and not hostile_order_block
    )
    if clean_snipe:
        required_age = min(required_age, 1.35)
        required_samples = min(required_samples, 4)

    mature = age >= required_age and samples >= required_samples and (abs(ema) >= 0.3) and (flow_support >= 0.2) and (supports >= 3)
    if not mature:
        self.opening_lock_var.set(f'OPEN LOCK: FORMULATING {candidate} • {"CLEAN SNIPE" if clean_snipe else "PATIENT"} • NO DEADLINE • {age:.1f}s / needs ≥{required_age:.1f}s • {samples}/{required_samples} samples • evidence {ema:+.2f} • target {target_distance:+.1f}$ • motion {velocity_ema:+.2f}$/s' + (' • HOSTILE ORDER BLOCK: PROVE IT' if hostile_order_block else ''))
        return None
    score = ema * 10.0
    reasons = [f'Bookmap flow {signed:+.2f}', f'target geometry {target_signed:+.2f}', f'Bookmap motion {velocity_ema:+.2f}$/s', f'{"CLEAN SNIPE" if clean_snipe else "PATIENT"} mature {age:.1f}s / {samples} samples', str(structure_ctx.get('summary', 'structure neutral'))]
    snap = {'time': now, 'price': live, 'lock_side': candidate, 'lock_remaining': 'OPEN', 'lock_minute': 0, 'forecast_score': score, 'forecast_threshold': 3.0, 'forecast_reasons': ' • '.join(reasons), 'source': 'BOOKMAP OPEN/NOW • PATIENT FORMULATION'}
    self.opening_lock_snapshot = snap
    self.opening_lock_candidate = None
    self.opening_lock_candidate_since = 0.0
    self.opening_lock_var.set(f'OPEN LOCK: {candidate} LOCKED @ {money(live)} • {"CLEAN SNIPE" if clean_snipe else "PATIENT LOCK"} • matured {age:.1f}s • {samples} samples • score {score:+.1f}')
    try:
        self._checkpoint_status_summary()
    except Exception:
        pass
    return dict(snap)

def _v229_target_motion_snapshot(self, now=None):
    """
    Track Bookmap price relative to the Kalshi target and its short-horizon motion.
    Returns causal movement facts only; no synthetic prices.
    """
    now = float(now or time.time())
    try:
        live, live_source = self.effective_live_price()
    except Exception:
        live, live_source = (None, '')
    try:
        target, target_source = self.effective_target()
    except Exception:
        target, target_source = (None, '')
    if live is None or target is None:
        return {'ready': False, 'live': live, 'target': target, 'velocity_1s': 0.0, 'velocity_3s': 0.0, 'distance': 0.0, 'crossed': False}
    live = float(live)
    target = float(target)
    hist = list(getattr(self, '_v229_target_motion', []) or [])
    hist.append((now, live))
    hist = [(t, p) for t, p in hist if now - float(t) <= 5.0][-80:]
    self._v229_target_motion = hist

    def velocity_for(horizon):
        older = None
        for t, p in hist:
            if now - float(t) >= horizon:
                older = (float(t), float(p))
        if older is None and len(hist) >= 2:
            older = (float(hist[0][0]), float(hist[0][1]))
        if older is None:
            return 0.0
        dt = max(0.05, now - older[0])
        return (live - older[1]) / dt
    v1 = velocity_for(0.75)
    v3 = velocity_for(2.25)
    distance = live - target
    crossed = False
    if len(hist) >= 2:
        old_dist = float(hist[0][1]) - target
        crossed = old_dist <= 0 < distance or old_dist >= 0 > distance
    return {'ready': True, 'live': live, 'target': target, 'distance': distance, 'velocity_1s': v1, 'velocity_3s': v3, 'crossed': crossed, 'live_source': live_source, 'target_source': target_source}

def _v212_team_breakout_read(self, sig, candles, base_trend, now=None):
    """
    V21.29 enhancement of V21.2 team referee.

    The existing independent-family score remains the foundation. This adds
    one explicit Kalshi-target + Bookmap-motion family so genuine price travel
    through/away from the settlement target is recognized earlier.
    """
    now = float(now or time.time())
    out = dict(_V229_BASE_TEAM_BREAKOUT(self, sig, candles, base_trend, now) or {})
    if not out.get('ready'):
        return out
    defended = str(out.get('defended', 'WAIT')).upper()
    attack = str(out.get('attack', 'WAIT')).upper()
    if defended not in ('UP', 'DOWN') or attack not in ('UP', 'DOWN'):
        return out
    motion = _v229_target_motion_snapshot(self, now=now)
    out['target_motion'] = motion
    if not motion.get('ready'):
        return out
    sign = 1.0 if attack == 'UP' else -1.0
    distance_attack = float(motion.get('distance', 0.0) or 0.0) * sign
    v1_attack = float(motion.get('velocity_1s', 0.0) or 0.0) * sign
    v3_attack = float(motion.get('velocity_3s', 0.0) or 0.0) * sign
    target_strength = max(0.0, min(1.0, distance_attack / 22.0))
    fast_strength = max(0.0, min(1.0, v1_attack / 10.0))
    sustained_strength = max(0.0, min(1.0, v3_attack / 6.0))
    family_active = distance_attack >= -5.0 and (v1_attack >= 3.0 or v3_attack >= 2.0 or (distance_attack >= 4.0 and v3_attack >= 0.75))
    score = float(out.get('score', 0.0) or 0.0)
    families = int(out.get('families', 0) or 0)
    names = list(out.get('family_names') or ())
    age = float(out.get('age', 0.0) or 0.0)
    boost = 0.0
    if family_active:
        if 'TARGET + BOOKMAP MOTION' not in names:
            names.append('TARGET + BOOKMAP MOTION')
            families += 1
        boost = 5.0 + target_strength * 8.0 + fast_strength * 6.0 + sustained_strength * 6.0
        if bool(motion.get('crossed')):
            boost += 4.0
        score = max(0.0, min(100.0, score + boost))
    old_stage = str(out.get('stage', 'NONE')).upper()
    stage = old_stage
    if family_active:
        target_cleared = distance_attack >= 2.0
        meaningful_motion = v1_attack >= 3.5 or v3_attack >= 2.2
        hard_motion = v1_attack >= 7.0 or v3_attack >= 4.0
        if target_cleared and hard_motion and (families >= 4) and (score >= 64.0) and (age >= 0.18):
            stage = 'CONFIRMED'
        elif target_cleared and meaningful_motion and (families >= 3) and (score >= 56.0):
            stage = 'LIKELY'
        elif families >= 2 and score >= 43.0:
            stage = 'FORMING'
        elif score >= 31.0:
            stage = 'WATCH'
    rank = {'NONE': 0, 'WATCH': 1, 'FORMING': 2, 'LIKELY': 3, 'CONFIRMED': 4}
    if rank.get(stage, 0) < rank.get(old_stage, 0):
        stage = old_stage
    out['score'] = score
    out['families'] = families
    out['family_names'] = tuple(names)
    out['stage'] = stage
    out['confirmed'] = stage == 'CONFIRMED'
    out['target_motion_boost'] = boost
    out['detail'] = f"{defended} thesis → {attack} {stage} {score:.0f}/100 • {families} families [{', '.join(names) or 'none'}] • Kalshi target {float(motion['target']):,.2f} • Bookmap {float(motion['live']):,.2f} ({float(motion['distance']):+.1f}$) • motion {float(motion['velocity_1s']):+.2f}$/s / {float(motion['velocity_3s']):+.2f}$/s"
    return out
