def _v230_find_text_widget(root, exact_text):
    try:
        children = list(root.winfo_children())
    except Exception:
        return None
    for child in children:
        try:
            if str(child.cget('text') or '') == exact_text:
                return child
        except Exception:
            pass
        found = _v230_find_text_widget(child, exact_text)
        if found is not None:
            return found
    return None

def _v230_find_header(self):
    lbl = _v230_find_text_widget(getattr(self, 'page_frame', self.root), 'CHART KING // V97 SIDE ADVISOR')
    if lbl is None:
        return None
    brand = getattr(lbl, 'master', None)
    return getattr(brand, 'master', None) if brand is not None else None

def _v230_find_setup(self):
    header = _v230_find_header(self)
