            tk.Label(seg, text='No rush • Mastermind may stay UNLOCKED / FORMULATING until its evidence truly agrees.', bg=PANEL2, fg=MUTED, font=('Segoe UI Variable', 9), anchor='w', justify='left', wraplength=1450).pack(fill='x', pady=(2, 0))
            self._v230_mm_lock_box_done = True
            self._v230_mm_lock_box = seg
