def _v231_newhedge_reader(self, now=None):
    """
    Use the authenticated/read-only NewHedge embed/API bridge when the saved
    Advanced payload supports it, and fall back to the known-good V21.2 export
    reader otherwise. Always returns a visible diagnostic rather than silently
    sitting at 'building'.
    """
    now = float(now or time.time())
    try:
        raw = str(getattr(self, 'newhedge_api_code_text', '') or '')
        embeds = _v218_parse_exact_embeds(raw)
    except Exception:
        embeds = ()
    if embeds:
        try:
            t = getattr(self, '_v218_thread', None)
            if t is None or not t.is_alive():
                _v218_start_bridge(self, raw)
            out = dict(_v218_newhedge_future_read(self, now) or {})
            out['transport'] = 'ADVANCED_READ_ONLY_BRIDGE'
            return out
        except Exception as exc:
            bridge_error = str(exc)[:160]
    else:
        bridge_error = 'No recognized Advanced embed payload saved.'
    try:
        out = dict(_V2111_TRUE_NH_READER(self, now) or {})
    except Exception as exc:
        out = {'ready': False, 'direction': 'WAIT', 'signed': 0.0, 'strength': 0.0, 'quality': 0.0, 'families': 0, 'aligned_families': 0, 'evidence': (), 'reason': f'NewHedge fallback reader error: {str(exc)[:140]}'}
    out['transport'] = 'KNOWN_GOOD_EXPORT_FALLBACK'
    if not out.get('ready'):
        out['reason'] = f"{out.get('reason', 'No readable NewHedge data')} • Advanced bridge: {bridge_error}"
    return out

def _v231_newhedge_heartbeat(self):
    """Refresh NewHedge display/lock independently of Mastermind panel cadence."""
    try:
        now = time.time()
        nh = _v231_newhedge_reader(self, now)
        direction = str(nh.get('direction', 'WAIT')).upper()
        strength = float(nh.get('strength', 0) or 0)
        quality = float(nh.get('quality', 0) or 0)
        fam = int(nh.get('families', 0) or 0)
        aligned = int(nh.get('aligned_families', 0) or 0)
        evidence = tuple(nh.get('evidence') or ())
        transport = str(nh.get('transport', '--'))
        if nh.get('ready'):
            obs = f'WHAT NEWHEDGE SEES: {direction} • strength {strength:.0f}% • quality {quality * 100:.0f}% • {aligned}/{fam} aligned • {transport}'
            if evidence:
                obs += ' • ' + ' | '.join((str(x) for x in evidence[:6]))
            interp = f"INTERPRETATION: live NewHedge read {direction} • signal {float(nh.get('signed', 0) or 0):+.2f} • age {float(nh.get('age', 0) or 0):.1f}s"
        else:
            obs = f'WHAT NEWHEDGE SEES: WAITING • {transport}'
            interp = f"INTERPRETATION: {nh.get('reason', 'waiting for NewHedge data')}"
        self._set_var_if_changed(self.newhedge_observation_var, obs)
        self._set_var_if_changed(self.newhedge_interpretation_var, interp)
        mm_stub = {'newhedge': nh}
        lock = _v228_formulate_newhedge_lock(self, mm_stub, now=now)
        if hasattr(self, 'newhedge_lock_var'):
            self._set_var_if_changed(self.newhedge_lock_var, lock['text'])
    except Exception as exc:
        try:
            self._set_var_if_changed(self.newhedge_observation_var, f'WHAT NEWHEDGE SEES: READER ERROR • {str(exc)[:150]}')
        except Exception:
            pass
    try:
        self.root.after(500, lambda s=self: _v231_newhedge_heartbeat(s))
    except Exception:
        pass

