def _v231_update_reversal_panel(self, d, lock_state=None, trend_state=None):
    if _v231_preopen_neutral(self):
        self.trend_reversal_risk_value = 0.0
        try:
            self._set_var_if_changed(self.trend_reversal_status_var, 'NEUTRAL • WAITING FOR BOOKMAP OPEN LOCK')
            self._set_var_if_changed(self.trend_reversal_risk_var, 'BREAKOUT / REVERSAL RISK: OBSERVING • NO DEFENDED SIDE')
            self._set_var_if_changed(self.trend_reversal_detail_var, 'Open Lock has not decided yet • risk engine has ZERO defensive authority.')
            if getattr(self, 'trend_reversal_status_label', None) is not None:
                self.trend_reversal_status_label.configure(fg=MUTED)
            try:
                self._draw_trend_risk_bar()
            except Exception:
                pass
        except Exception:
            pass
        return None
    return _V231_BASE_REVERSAL_PANEL(self, d, lock_state=lock_state, trend_state=trend_state)

