_V234_BASE_INIT = ChartKingPro.__init__


def _v234_remove_paper_lab(self):
    """Remove the V21.33 Accuracy Paper Lab widget without disabling its backend."""
    try:
        w = getattr(self, '_v233_lab_box', None)
        if w is not None and int(w.winfo_exists()):
            w.destroy()
    except Exception:
        pass

    # V21.33 did not originally save the outer box reference, so locate it by title.
    root = getattr(self, 'page_frame', None)
    if root is None:
        return

    doomed = []
    def walk(widget):
        try:
            children = list(widget.winfo_children())
        except Exception:
            return
        for child in children:
            try:
                txt = str(child.cget('text') or '')
                if txt.startswith('V21.33 ACCURACY PAPER LAB'):
                    parent = getattr(child, 'master', None)
                    if parent is not None:
                        doomed.append(parent)
            except Exception:
                pass
            walk(child)

    walk(root)
    for box in doomed:
        try:
            box.destroy()
        except Exception:
            pass


def _v234_find_open_box(self):
    """Find the actual BOOKMAP OPEN LOCK shell if V21.31/32 already created it."""
    root = getattr(self, 'page_frame', None)
    if root is None:
        return None

    found = []
    def walk(widget):
        try:
            children = list(widget.winfo_children())
        except Exception:
            return
        for child in children:
            try:
                if str(child.cget('text') or '') == 'BOOKMAP OPEN LOCK':
                    parent = getattr(child, 'master', None)
                    if parent is not None:
                        found.append(parent)
            except Exception:
                pass
            walk(child)
    walk(root)
    return found[0] if found else None


