def _v235_sticky_price_tick(self):
    """Single sticky DISPLAY writer; analysis still uses raw live values."""
    now = time.time()
    cache = dict(getattr(self, '_v235_price_cache', {}) or {})

    try:
        live, live_src = self.effective_live_price()
    except Exception:
        live, live_src = None, ''
    try:
        target, target_src = self.effective_target()
    except Exception:
        target, target_src = None, ''

    if live is not None:
        try:
            live = float(live)
            prev = cache.get('live')
            last_write = float(cache.get('live_write_ts', 0.0) or 0.0)
            if prev is None or abs(live - float(prev)) >= 0.50 or now - last_write >= 0.18:
                cache['live'] = live
                cache['live_src'] = str(live_src or 'BOOKMAP')
                cache['live_write_ts'] = now
                cache['live_valid_ts'] = now
        except Exception:
            pass

    if target is not None:
        try:
            cache['target'] = float(target)
            cache['target_src'] = str(target_src or 'KALSHI')
            cache['target_valid_ts'] = now
        except Exception:
            pass

    self._v235_price_cache = cache
    shown_live = cache.get('live')
    shown_target = cache.get('target')

    try:
        if shown_live is not None:
            txt = f'BOOKMAP LIVE BTC {money(float(shown_live))} • {cache.get("live_src","BOOKMAP")}'
            if str(self.btc_price_var.get() or '') != txt:
                self.btc_price_var.set(txt)
        elif not str(self.btc_price_var.get() or '').strip():
            self.btc_price_var.set('BOOKMAP LIVE BTC • acquiring first valid read')
    except Exception:
        pass

    try:
        if shown_target is not None:
            if shown_live is not None:
                delta = float(shown_live) - float(shown_target)
                txt = (
                    f'KALSHI TARGET {money(float(shown_target))} • '
                    f'{cache.get("target_src","KALSHI")} • distance {delta:+,.1f}$'
                )
            else:
                txt = f'KALSHI TARGET {money(float(shown_target))} • {cache.get("target_src","KALSHI")}'
            if str(self.target_var.get() or '') != txt:
                self.target_var.set(txt)
        elif not str(self.target_var.get() or '').strip():
            self.target_var.set('KALSHI TARGET • acquiring first valid read')
    except Exception:
        pass

    try:
        self.root.after(100, lambda s=self: _v235_sticky_price_tick(s))
    except Exception:
        pass


def _v235_accuracy_rows(self):
    data = {'stats': [], 'open': [], 'recent': [], 'wins': []}
    try:
        with self.stockpile_db_lock:
            with self._stockpile_connect() as conn:
                data['stats'] = conn.execute("""
                    SELECT bot,COUNT(*),
                           SUM(CASE WHEN result='WIN' THEN 1 ELSE 0 END),
                           SUM(CASE WHEN result='LOSS' THEN 1 ELSE 0 END),
                           COALESCE(SUM(pnl),0)
                    FROM v233_accuracy_trades
                    WHERE status='CLOSED'
                    GROUP BY bot
                """).fetchall()
                data['open'] = conn.execute("""
                    SELECT bot,side,entry_contract,lock_grade,entry_btc,target,
                           quote_source,quote_age,deep_score,guardian_winrate,
                           guardian_n,recross_risk
                    FROM v233_accuracy_trades
                    WHERE status='OPEN'
                    ORDER BY id
                """).fetchall()
                data['recent'] = conn.execute("""
                    SELECT id,bot,side,result,entry_contract,pnl,lock_grade,
                           final_outcome,entry_btc,target
                    FROM v233_accuracy_trades
                    WHERE status='CLOSED'
                    ORDER BY id DESC LIMIT 40
                """).fetchall()
                data['wins'] = conn.execute("""
                    SELECT id,bot,side,entry_contract,pnl,lock_grade,bucket
                    FROM v233_accuracy_trades
                    WHERE result='WIN'
                    ORDER BY id DESC
                """).fetchall()
    except Exception:
        pass
    return data


def _v235_bot_status_line(self, bot, rows):
    open_rows = [r for r in rows['open'] if str(r[0]) == bot]
    stat_rows = [r for r in rows['stats'] if str(r[0]) == bot]

    if stat_rows:
        _, n, w, l, pnl = stat_rows[0]
        n=int(n or 0); w=int(w or 0); l=int(l or 0)
        wr=(100.0*w/n) if n else 0.0
        record=f'RECORD {w}-{l} • {wr:.1f}% • P&L ${float(pnl or 0):+.2f}'
    else:
        record='RECORD 0-0 • waiting for completed calls'

    if not open_rows:
        if bot == 'BOOKMAP KING':
            snap=getattr(self,'opening_lock_snapshot',None) or {}
            side=str(snap.get('lock_side','WAIT')).upper()
            current=f'Open Lock {side}' if side in ('UP','DOWN') else 'waiting for BOOKMAP OPEN LOCK'
        else:
            st=dict(getattr(self,'_v228_mm_lock_state',{}) or {})
            side=_v228_side(st.get('locked'))
            current=f'Team MM3 Lock {side}' if side in ('UP','DOWN') else 'waiting for TEAM MM3 LOCK'
        return f'{record}\nCURRENT: {current} • waiting for fresh exact ASK'

    r=open_rows[-1]
    _, side, entry, grade, entry_btc, target, qsrc, qage, deep, gwr, gn, rr = r
    cushion=float(entry_btc)-float(target)
    side_cushion=cushion if str(side).upper()=='UP' else -cushion
    guardian=(f'{float(gwr)*100:.1f}% n={int(gn or 0)}' if gwr is not None else 'memory building')
    return (
        f'{record}\nOPEN {str(side).upper()} @ {float(entry)*100:.1f}¢ EXACT ASK • {grade} • '
        f'BTC {float(entry_btc):,.2f} vs target {float(target):,.2f} • '
        f'side cushion {side_cushion:+.1f}$ • deep {float(deep or 0):+.2f} • '
        f'guardian {guardian} • recross {float(rr or 0):.0f}% • {qsrc} age {float(qage or 0):.2f}s'
    )


def _v235_set_text(widget, value):
    if widget is None:
        return
    try:
        current=widget.get('1.0','end-1c')
        if current==value:
            return
        widget.configure(state='normal')
        widget.delete('1.0','end')
        widget.insert('1.0',value)
        widget.configure(state='disabled')
    except Exception:
        pass


def _v235_refresh_paper_desk(self):
    try:
        rows=_v235_accuracy_rows(self)
        total_n=total_w=total_l=0
        total_pnl=0.0
        pieces=[]

        for bot,n,w,l,pnl in rows['stats']:
            n=int(n or 0); w=int(w or 0); l=int(l or 0)
            total_n+=n; total_w+=w; total_l+=l; total_pnl+=float(pnl or 0)
            wr=(100.0*w/n) if n else 0.0
            pieces.append(f'{bot} {w}-{l} ({wr:.1f}%) ${float(pnl or 0):+.2f}')

        wr=(100.0*total_w/total_n) if total_n else 0.0
        headline=f'COMBINED RECORD {total_w}-{total_l} • {wr:.1f}% • P&L ${total_pnl:+.2f}'
        if pieces:
            headline += '  |  ' + '  |  '.join(pieces)
        else:
            headline += ' • waiting for first completed exact-ASK call'
        self.v235_paper_summary_var.set(headline)

        self.v235_bookmap_paper_var.set(_v235_bot_status_line(self,'BOOKMAP KING',rows))
        self.v235_mm3_paper_var.set(_v235_bot_status_line(self,'TEAM MM3',rows))

        open_lines=[]
        for r in rows['open']:
            bot,side,entry,grade,entry_btc,target,qsrc,qage,deep,gwr,gn,rr=r
            open_lines.append(
                f'{bot} • {side} @ {float(entry)*100:.1f}¢ EXACT ASK • {grade} • '
                f'BTC {float(entry_btc):,.2f} • target {float(target):,.2f} • '
                f'{qsrc} age {float(qage or 0):.2f}s'
            )
        self.v235_open_calls_var.set('\n'.join(open_lines) if open_lines else 'No open paper calls')

        recent_lines=[
            f'#{tid} {bot} • {side} @ {float(entry)*100:.1f}¢ • {result} • '
            f'${float(pnl or 0):+.2f} • {grade} • finish {outcome} • '
            f'BTC {float(entry_btc):,.2f} vs {float(target):,.2f}'
            for tid,bot,side,result,entry,pnl,grade,outcome,entry_btc,target in rows['recent']
        ]
        recent='\n'.join(recent_lines) if recent_lines else 'No completed paper calls yet'
        self.v235_recent_calls_var.set(recent)
        _v235_set_text(getattr(self,'_v235_recent_text',None),recent)

        win_lines=[
            f'#{tid} {bot} • {side} @ {float(entry)*100:.1f}¢ • +${float(pnl or 0):.2f} • {grade} • bucket {bucket}'
            for tid,bot,side,entry,pnl,grade,bucket in rows['wins']
        ]
        wins='\n'.join(win_lines) if win_lines else 'No logged wins yet'
        self.v235_logged_wins_var.set(wins)
        _v235_set_text(getattr(self,'_v235_wins_text',None),wins)
    except Exception:
        pass

    try:
        self.root.after(400,lambda s=self:_v235_refresh_paper_desk(s))
    except Exception:
        pass


def _v235_remove_legacy_paper_if_reintroduced(self):
    """Kill any old delayed paper card, but never touch the V21.35 desk."""
    root=getattr(self,'page_frame',None)
    if root is None:
        return

    legacy={'PAPER TRADE LAB','AUTO PAPER TRADE','LIVE AUTO TRADE','AUTO PAPER EXIT / SCALP'}
    doomed=[]

    def walk(w):
        try:
            kids=list(w.winfo_children())
        except Exception:
            return
        for c in kids:
            try:
                txt=str(c.cget('text') or '')
                if txt in legacy:
                    p=getattr(c,'master',None)
                    while p is not None and getattr(p,'master',None) is not getattr(self,'center_content',None):
                        if p is getattr(self,'_v235_paper_desk',None):
                            p=None
                            break
                        p=getattr(p,'master',None)
                    if p is not None:
                        doomed.append(p)
            except Exception:
                pass
            walk(c)

    walk(root)
    for w in doomed:
        try:
            if w is not getattr(self,'_v235_paper_desk',None):
                w.destroy()
        except Exception:
            pass


def _v235_init(self,*args,**kwargs):
    self._v235_price_cache={}
    _V235_BASE_INIT(self,*args,**kwargs)

    # Remove V21.33 giant lab and any delayed legacy paper widgets.
