def _v236_smooth_value(current, raw, alpha=0.24, max_step=7.5):
    """
    Display-only easing.
    Engine/raw market data is never modified.
    """
    raw = float(raw)
    if current is None:
        return raw
    current = float(current)
    delta = raw - current
    eased = current + delta * float(alpha)
    step = eased - current
    if step > max_step:
        eased = current + max_step
    elif step < -max_step:
        eased = current - max_step
    return eased


def _v236_butter_price_tick(self):
    """
    One isolated visible-price owner.

    IMPORTANT:
      btc_price_var / target_var / distance_var remain raw engine vars.
      Visible widgets are bound to v236_display_* vars, so no older feed loop
      can visually overwrite this controller.

    Visual behavior:
      • sample raw feed frequently
      • retain last valid read through missing polls
      • low-pass / ease BTC movement
      • repaint at 400ms max (2.5 Hz)
      • fixed-format text, no arrows and no changing source suffix
      • target changes only when actual target changes
    """
    now = time.time()
    st = dict(getattr(self, '_v236_display_state', {}) or {})

    try:
        raw_live, _raw_live_src = self.effective_live_price()
    except Exception:
        raw_live = None
    try:
        raw_target, _raw_target_src = self.effective_target()
    except Exception:
        raw_target = None

    if raw_live is not None:
        try:
            raw_live = float(raw_live)
            if math.isfinite(raw_live) and raw_live > 0:
                st['last_valid_live'] = raw_live
                st['last_valid_live_ts'] = now
        except Exception:
            pass

    if raw_target is not None:
        try:
            raw_target = float(raw_target)
            if math.isfinite(raw_target) and raw_target > 0:
                st['last_valid_target'] = raw_target
                st['last_valid_target_ts'] = now
        except Exception:
            pass

    last_live = st.get('last_valid_live')
    last_target = st.get('last_valid_target')

    # Smooth internal DISPLAY state every sample. No Tk repaint yet.
    if last_live is not None:
        visual = st.get('visual_live')
        # Stronger smoothing near target because tiny recross jitter is visually noisy.
        alpha = 0.20
        if last_target is not None and abs(float(last_live) - float(last_target)) < 20.0:
            alpha = 0.16
        st['visual_live'] = _v236_smooth_value(
            visual, last_live, alpha=alpha, max_step=6.0
        )

    self._v236_display_state = st

    last_paint = float(st.get('last_paint_ts', 0.0) or 0.0)
    if now - last_paint >= 0.40:
        visual_live = st.get('visual_live')

        if visual_live is not None:
            # Fixed two-decimal format. No source/arrow text that changes width.
            btc_txt = f'BTC {float(visual_live):,.2f}'
            try:
                if str(self.v236_display_btc_var.get() or '') != btc_txt:
                    self.v236_display_btc_var.set(btc_txt)
            except Exception:
                pass

        if last_target is not None:
            target_txt = f'TARGET {float(last_target):,.2f}'
            try:
                if str(self.v236_display_target_var.get() or '') != target_txt:
                    self.v236_display_target_var.set(target_txt)
            except Exception:
                pass

        if visual_live is not None and last_target is not None:
            distance = float(visual_live) - float(last_target)
            dist_txt = f'DISTANCE {distance:+,.2f}'
            try:
                if str(self.v236_display_distance_var.get() or '') != dist_txt:
                    self.v236_display_distance_var.set(dist_txt)
            except Exception:
                pass

        st['last_paint_ts'] = now
        self._v236_display_state = st

    try:
        self.root.after(80, lambda s=self: _v236_butter_price_tick(s))
    except Exception:
        pass


def _v236_ensure_mm3_under_open(self):
    """
    Runtime defense-in-depth:
    if a delayed legacy UI mutation destroys/hides the MM3-under-Open box,
    recreate it immediately after the actual Open Lock box.
    """
    try:
        box = getattr(self, '_v236_mm3_under_open_box', None)
        if box is not None and int(box.winfo_exists()):
            # Keep it directly after Open Lock in packing order.
            open_box = getattr(self, '_v231_open_lock_box', None) or getattr(self, '_v234_open_box', None)
            try:
                if open_box is not None:
                    box.pack_configure(after=open_box)
            except Exception:
                pass
            return True
    except Exception:
        pass

    page = getattr(self, 'page_frame', None)
    if page is None:
        return False

    open_box = getattr(self, '_v231_open_lock_box', None) or getattr(self, '_v234_open_box', None)
    if open_box is None:
        return False

    try:
        shell = tk.Frame(
            page, bg=PANEL2, padx=10, pady=8,
            highlightthickness=2, highlightbackground=PINK
        )
        shell.pack(fill='x', padx=10, pady=(0, 6), after=open_box)

        tk.Label(
            shell, text='TEAM MM3 LOCK',
            bg=PANEL2, fg=PINK2,
            font=('Segoe UI Variable', 11, 'bold'),
            anchor='w'
        ).pack(fill='x')
        tk.Label(
            shell, textvariable=self.mastermind_lock_var,
            bg=PANEL2, fg=TEXT,
            font=('Segoe UI Variable', 10, 'bold'),
            anchor='w', justify='left', wraplength=1450
        ).pack(fill='x', pady=(4, 0))
        if not hasattr(self, 'v233_mm3_grade_var'):
            self.v233_mm3_grade_var = tk.StringVar(value='TEAM MM3 LOCK QUALITY: ANALYZING')
        tk.Label(
            shell, textvariable=self.v233_mm3_grade_var,
            bg=PANEL2, fg=YELLOW,
            font=('Segoe UI Variable', 9, 'bold'),
            anchor='w', justify='left', wraplength=1450
        ).pack(fill='x', pady=(3, 0))
        tk.Label(
            shell,
            text='TEAM MM3 • independent 15m read • may remain UNLOCKED / COIN FLIP until evidence matures.',
            bg=PANEL2, fg=MUTED,
            font=('Segoe UI Variable', 9),
            anchor='w', justify='left', wraplength=1450
        ).pack(fill='x', pady=(2, 0))
        self._v236_mm3_under_open_box = shell
        return True
    except Exception:
        return False


