def _v237_api_preview_control(self):
    """
    Restored API submit-style control as a PREVIEW/DRY-RUN action.
    It does not transmit a real-money order.
    """
    try:
        # Reuse the newest exact-ask paper/preview context where available.
        now = time.time()
        bk = _v233_paper_lock(self, 'BOOKMAP KING', now=now)
        mm = _v233_paper_lock(self, 'TEAM MM3', now=now)

        lines = ['API PREVIEW / DRY RUN', '']
        for label, lock in (('BOOKMAP KING', bk), ('TEAM MM3', mm)):
            side = str(lock.get('side', 'WAIT')).upper()
            if not lock.get('ready') or side not in ('UP','DOWN'):
                lines.append(f'{label}: no earned directional lock yet')
                continue
            q = _v233_exact_ask(self, side)
            if q is None:
                lines.append(f'{label}: {side} lock • no fresh executable Kalshi ASK')
                continue
            lines.append(
                f'{label}: {side} • {float(q["contract"])*100:.1f}¢ exact ask • '
                f'{lock.get("grade","")} • source {q.get("source")} • age {float(q.get("age",0)):.2f}s'
            )

        msg = '\n'.join(lines)

        try:
            self.paper_status_var.set(msg.replace('\n', ' • '))
        except Exception:
            pass

        win = tk.Toplevel(self.root)
        win.title('API SUBMIT / PREVIEW')
        win.configure(bg=PANEL2)
        win.geometry('700x260')

        tk.Label(
            win,
            text='API SUBMIT / PREVIEW — DRY RUN',
            bg=PANEL2, fg=YELLOW,
            font=('Segoe UI Variable', 12, 'bold')
        ).pack(anchor='w', padx=12, pady=(12, 6))

        tk.Label(
            win,
            text=msg,
            bg=PANEL2, fg=TEXT,
            font=('Consolas', 10),
            anchor='nw', justify='left',
            wraplength=660
        ).pack(fill='both', expand=True, padx=12, pady=(4, 8))

        ttk.Button(win, text='CLOSE', command=win.destroy).pack(
            anchor='e', padx=12, pady=(0, 10)
        )
        return True
    except Exception:
        return False


def _v237_init(self, *args, **kwargs):
    _V237_BASE_INIT(self, *args, **kwargs)
    try:
        self.root.title(
            'BOOKMAP KING V21.37 — QUICKER OPEN + RESTORED TOP CONTROLS'
        )
    except Exception:
        pass


ChartKingPro._v237_open_api_key_control = _v237_open_api_key_control
