# ============================================================================
# BOOKMAP KING V21.38
# REPEATING BREAKOUT-DEFENSE ROTATION STATE MACHINE
#
# Behavior:
#   defend A
#   -> confirmed breakout B
#   -> brief red confirmation
#   -> immediately rotate live defense to B
#   -> risk bar returns to normal
#   -> if B is later confirmed broken by A
#   -> red again
#   -> rotate defense back to A
#   -> repeat for the rest of the 15m round
#
# Opening Lock itself is NOT rewritten; it remains historical opening context.
# ============================================================================

_V238_BASE_INIT = ChartKingPro.__init__
_V238_BASE_STICKY = ChartKingPro._sticky_survival_lock_snapshot
_V238_BASE_REV_PANEL = ChartKingPro._update_reversal_panel
_V238_BASE_BREAKOUT_LATCH_UPDATE = _v228_breakout_latch_update


def _v238_bucket(now=None):
    now = float(now or time.time())
    return int(now // 900) * 900


def _v238_current_defense(self, now=None):
    """
    Return the live defended side.
    A confirmed-breakout rotation override has priority over the original
    earned Open Lock. It resets automatically each 15m bucket.
    """
    now = float(now or time.time())
    bucket = _v238_bucket(now)
    st = dict(getattr(self, '_v238_defense_rotation', {}) or {})

    if int(st.get('bucket', -1) or -1) == bucket:
        side = _v228_side(st.get('side'))
        if side in ('UP', 'DOWN'):
            return side

    try:
        snap = _V238_BASE_STICKY(self)
    except Exception:
        snap = None
    side = _v228_side((snap or {}).get('lock_side'))
    return side if side in ('UP', 'DOWN') else 'WAIT'


def _v238_sticky_survival_lock_snapshot(self):
    """
    Live survival/risk authority follows confirmed breakout rotations.

    The original BOOKMAP OPEN LOCK remains unchanged and visible as the opening
    thesis; this returned snapshot is the LIVE DEFENDED SIDE used by risk logic.
    """
    now = time.time()
    bucket = _v238_bucket(now)
    rot = dict(getattr(self, '_v238_defense_rotation', {}) or {})

    if int(rot.get('bucket', -1) or -1) == bucket:
        side = _v228_side(rot.get('side'))
        if side in ('UP', 'DOWN'):
            base = dict(getattr(self, '_survival_lock_snapshot', {}) or {})
            if not base:
                base = dict(getattr(self, 'opening_lock_snapshot', {}) or {})
            base['lock_side'] = side
            base['survival_latched_bucket'] = bucket
            base['survival_latched_ts'] = float(rot.get('rotated_ts', now) or now)
            base['source'] = 'CONFIRMED BREAKOUT ROTATION'
            base['rotation_count'] = int(rot.get('count', 0) or 0)
            base['rotation_from'] = rot.get('from')
            base['rotation_to'] = side
            base['rotation_reason'] = rot.get('reason', 'confirmed breakout')
            self._survival_lock_snapshot = dict(base)
            self._survival_lock_bucket = bucket
            return dict(base)

    return _V238_BASE_STICKY(self)


def _v238_breakout_latch_update(self, trend_state, now=None):
    """
    Only latch a breakout when it breaks AGAINST the currently defended side.

    This prevents a just-confirmed breakout from re-latching forever after
    V21.38 rotates defense to that breakout side.
    """
    now = float(now or time.time())
    bucket = _v238_bucket(now)
    trend = dict(trend_state or {})
    status = str(trend.get('status', '') or '').upper()
    flip_to = _v228_side(trend.get('flip_to'))
    risk = float(trend.get('risk', 0) or 0)
    team = dict(trend.get('team_breakout') or {})
    stage = str(team.get('stage', '') or '').upper()
    score = float(team.get('score', 0) or 0)
    families = int(team.get('families', 0) or 0)

    defended = _v238_current_defense(self, now=now)
    point_of_no_return = (
        status == 'BREAKOUT CONFIRMED'
        and flip_to in ('UP', 'DOWN')
        and (stage == 'CONFIRMED' or risk >= 88.0)
        and defended in ('UP', 'DOWN')
        and flip_to != defended
    )

    st = dict(getattr(self, '_v228_breakout_latch', {}) or {})
    if int(st.get('bucket', -1) or -1) != bucket:
        st = {
            'bucket': bucket,
            'active': False,
            'side': 'WAIT',
            'latched_ts': 0.0,
            'score': 0.0,
            'families': 0,
        }

    if point_of_no_return:
        if (
            not st.get('active')
            or _v228_side(st.get('side')) != flip_to
        ):
            st.update({
                'active': True,
                'side': flip_to,
                'from_side': defended,
                'latched_ts': now,
                'score': score,
                'families': families,
            })
        else:
            st['score'] = max(float(st.get('score', 0) or 0), score)
            st['families'] = max(int(st.get('families', 0) or 0), families)
    else:
        # A stale same-side confirmed trend must not keep a latch red after
        # that side has become the new defense.
        if (
            st.get('active')
            and _v228_side(st.get('side')) == defended
        ):
            st['active'] = False
            st['normalized_ts'] = now

    self._v228_breakout_latch = st
    return st


def _v238_rotate_to_breakout(self, side, latch=None, now=None):
    """
    Promote a confirmed breakout side to the new LIVE DEFENDED SIDE.
    """
    now = float(now or time.time())
    bucket = _v238_bucket(now)
    side = _v228_side(side)
    if side not in ('UP', 'DOWN'):
        return False

    current = _v238_current_defense(self, now=now)
    if current == side:
        return False

    old = dict(getattr(self, '_v238_defense_rotation', {}) or {})
    count = (
        int(old.get('count', 0) or 0) + 1
        if int(old.get('bucket', -1) or -1) == bucket
        else 1
    )

    self._v238_defense_rotation = {
        'bucket': bucket,
        'side': side,
        'from': current,
        'rotated_ts': now,
        'count': count,
        'reason': 'CONFIRMED BREAKOUT',
        'score': float((latch or {}).get('score', 0) or 0),
        'families': int((latch or {}).get('families', 0) or 0),
    }

    # Immediately rebuild the survival snapshot around the new defended side.
    snap = dict(getattr(self, '_survival_lock_snapshot', {}) or {})
    if not snap:
        snap = dict(getattr(self, 'opening_lock_snapshot', {}) or {})
    snap['lock_side'] = side
    snap['survival_latched_bucket'] = bucket
    snap['survival_latched_ts'] = now
    snap['source'] = 'CONFIRMED BREAKOUT ROTATION'
    snap['rotation_count'] = count
    snap['rotation_from'] = current
    snap['rotation_to'] = side
    self._survival_lock_snapshot = snap
    self._survival_lock_bucket = bucket

    # Clear old red latch: the breakout is now the defended baseline.
    lat = dict(getattr(self, '_v228_breakout_latch', {}) or {})
    lat['active'] = False
    lat['normalized_ts'] = now
    lat['normalized_to'] = side
    lat['rotation_count'] = count
    self._v228_breakout_latch = lat

    # Reset risk visuals to a neutral/normal monitoring state immediately.
    self.trend_reversal_risk_value = 0.0
    try:
        self.trend_risk_smoothed = 0.0
    except Exception:
        pass

    try:
        self.trend_reversal_status_var.set(
            f'DEFENDING {side} • BREAKOUT CONFIRMED / DEFENSE ROTATED'
        )
        self.trend_reversal_risk_var.set(
            f'BREAKOUT / REVERSAL RISK: NORMAL • DEFENDING {side}'
        )
        self.trend_reversal_detail_var.set(
            f'{current} was broken by a CONFIRMED {side} breakout • '
            f'live defense instantly rotated to {side} • breakout meter reset • '
            f'next red event requires a confirmed breakout AGAINST {side}.'
        )
        if getattr(self, 'trend_reversal_status_label', None) is not None:
            self.trend_reversal_status_label.configure(fg=GREEN)
        try:
            _V228_BASE_DRAW_RISK(self)
        except Exception:
            try:
                self._draw_trend_risk_bar()
            except Exception:
                pass
    except Exception:
        pass

    # Survival also gets a clean baseline around the NEW defended side;
    # normal engine calculations take over on the very next update.
    try:
        current_survival = float(
            getattr(self, 'flip_survival_value', 50.0) or 50.0
        )
        baseline = max(50.0, min(72.0, current_survival))
        self.flip_survival_value = baseline
        self.flip_survival_smoothed = baseline
        self.flip_survival_var.set(
            f'FLIP SURVIVAL {baseline:.0f}/100 • NOW DEFENDING {side}'
        )
        self.flip_survival_detail_var.set(
            f'Confirmed breakout rotation complete • {side} is now the defended side.'
        )
        self._draw_flip_survival_bar()
    except Exception:
        pass

    return True


def _v238_update_reversal_panel(
    self, d, lock_state=None, trend_state=None
):
    """
    Let the inherited engine detect/render the breakout first, then immediately
    turn the confirmed breakout side into the new defended baseline.
    """
    trend_state = dict(trend_state or {})

    # Existing panel performs all normal detection first.
    out = _V238_BASE_REV_PANEL(
        self,
        d,
        lock_state=lock_state,
        trend_state=trend_state,
    )

    latch = dict(getattr(self, '_v228_breakout_latch', {}) or {})
    if latch.get('active'):
        side = _v228_side(latch.get('side'))
        defended = _v238_current_defense(self)
        if (
            side in ('UP', 'DOWN')
            and defended in ('UP', 'DOWN')
            and side != defended
        ):
            _v238_rotate_to_breakout(
                self,
                side,
                latch=latch,
                now=time.time(),
            )

    return out


def _v238_rotation_heartbeat(self):
    """
    Keep visible defended-side text consistent even if no full reversal-panel
    repaint occurred during the exact rotation tick.
    """
    try:
        bucket = _v238_bucket()
        rot = dict(getattr(self, '_v238_defense_rotation', {}) or {})
        if int(rot.get('bucket', -1) or -1) != bucket:
            self._v238_defense_rotation = {}
    except Exception:
        pass

    try:
        self.root.after(
            250,
            lambda s=self: _v238_rotation_heartbeat(s),
        )
    except Exception:
        pass


def _v238_init(self, *args, **kwargs):
    self._v238_defense_rotation = {}
    _V238_BASE_INIT(self, *args, **kwargs)

    try:
        self.root.after(
            180,
            lambda s=self: _v238_rotation_heartbeat(s),
        )
    except Exception:
        pass

    try:
        self.root.title(
            'BOOKMAP KING V21.38 — REPEATING BREAKOUT DEFENSE ROTATION'
        )
    except Exception:
        pass


# Latest authority bindings.
_v228_breakout_latch_update = _v238_breakout_latch_update
ChartKingPro._sticky_survival_lock_snapshot = _v238_sticky_survival_lock_snapshot
ChartKingPro._update_reversal_panel = _v238_update_reversal_panel
ChartKingPro.__init__ = _v238_init


# ============================================================================
# BOOKMAP KING V21.39
# FLIP RISK COMMAND CENTER + FASTER BOOKMAP / TEAM MM3 LOCKS
# ============================================================================

_V239_BASE_INIT = ChartKingPro.__init__


def _v239_clip(v, lo=-1.0, hi=1.0):
    try:
        return max(lo, min(hi, float(v)))
    except Exception:
        return 0.0


def _v239_family(name, group, signed_up, weight, ready=True, detail=''):
    return {
        'name': str(name),
        'group': str(group),
        'signed_up': _v239_clip(signed_up),
        'weight': max(0.05, float(weight)),
        'ready': bool(ready),
        'detail': str(detail or ''),
    }


def _v239_build_families(self, now=None):
    """
    Build independent reversal evidence families.

    Important:
    correlated micro-signals are grouped later, so confidence is not inflated
    by five versions of the same underlying signal.
    """
    now = float(now or time.time())
    defended = _v238_current_defense(self, now=now)

    if defended not in ('UP', 'DOWN'):
        return {
            'ready': False,
            'defended': 'WAIT',
            'attack': 'WAIT',
            'families': [],
        }

    attack = 'DOWN' if defended == 'UP' else 'UP'
    families = []

    try:
        sig = getattr(self, 'last_signal', None) or {}
    except Exception:
        sig = {}
    try:
        candles = getattr(self, '_last_analysis_candles', None) or []
    except Exception:
        candles = []

    # --------------------------------------------------------
    # Deep feature stack
    # --------------------------------------------------------
    try:
        mm = _v214_mm3_read(
            self,
            sig=sig,
            candles=candles,
            now=now
        )
    except Exception:
        mm = {}

    try:
        f = _v233_base_features(self, now=now, mm=mm)
    except Exception:
        f = {}

    def fv(name):
        try:
            return float(f.get(name, 0.0) or 0.0)
        except Exception:
            return 0.0

    families.append(_v239_family(
        'BOOKMAP EXECUTED FLOW',
        'FLOW',
        fv('flow'),
        1.45,
        True,
        f"deep flow {fv('flow'):+.2f}"
    ))

    families.append(_v239_family(
        'TARGET GEOMETRY / CUSHION',
        'GEOMETRY',
        fv('cushion'),
        1.20,
        True,
        f"cushion {fv('cushion'):+.2f}"
    ))

    motion = _v239_clip(
        fv('motion1') * 0.60 + fv('motion3') * 0.40
    )
    families.append(_v239_family(
        'TARGET MOTION / VELOCITY',
        'MOTION',
        motion,
        1.15,
        True,
        f"1s {fv('motion1'):+.2f} • 3s {fv('motion3'):+.2f}"
    ))

    families.append(_v239_family(
        'MULTI-TIMEFRAME CANDLES',
        'STRUCTURE',
        fv('candle'),
        1.25,
        True,
        f"MTF candle read {fv('candle'):+.2f}"
    ))

    families.append(_v239_family(
        'TEAM MM3 SETTLEMENT READ',
        'MM3',
        fv('mm3'),
        1.15,
        True,
        f"MM3 deep input {fv('mm3'):+.2f}"
    ))

    families.append(_v239_family(
        'NEWHEDGE FUTURES CONTEXT',
        'NEWHEDGE',
        fv('newhedge'),
        0.80,
        abs(fv('newhedge')) > 0.01,
        f"NewHedge {fv('newhedge'):+.2f}"
    ))

    families.append(_v239_family(
        'BREAKOUT ATTACK FAMILY',
        'BREAKOUT',
        fv('breakout'),
        1.25,
        abs(fv('breakout')) > 0.01,
        f"breakout input {fv('breakout'):+.2f}"
    ))

    # --------------------------------------------------------
    # Microstructure family
    # --------------------------------------------------------
    try:
        micro = self._micro_flip_intelligence()
    except Exception:
        micro = {}
    try:
        tf = self._micro_timeframe_read()
    except Exception:
        tf = {}

    micro_signed = 0.0
    micro_detail = []
    try:
        rev_to = str(tf.get('reverse_to', 'WAIT')).upper()
        rev_risk = float(tf.get('reverse_risk', 0.0) or 0.0)
        if rev_to in ('UP', 'DOWN'):
            micro_signed += (
                1.0 if rev_to == 'UP' else -1.0
            ) * min(1.0, rev_risk / 100.0) * 0.65
        micro_detail.append(
            f"1m/5m reverse {rev_to} {rev_risk:.0f}%"
        )
    except Exception:
        pass

    try:
        danger = float(micro.get('danger_score', 0.0) or 0.0)
        if micro.get('both_confirmed'):
            target_side = str(
                tf.get('reverse_to', 'WAIT')
            ).upper()
            if target_side in ('UP', 'DOWN'):
                micro_signed += (
                    1.0 if target_side == 'UP' else -1.0
                ) * min(1.0, danger / 100.0) * 0.55
        micro_detail.append(
            f"micro danger {danger:.0f}"
        )
    except Exception:
        pass

    families.append(_v239_family(
        'MICROSTRUCTURE / 1M-5M',
        'MICRO',
        _v239_clip(micro_signed),
        1.10,
        True,
        ' • '.join(micro_detail)
    ))

    # --------------------------------------------------------
    # Whale / orderbook family
    # --------------------------------------------------------
    try:
        whale = self._bookmap_whale_read()
    except Exception:
        whale = {}

    whale_dir = str(whale.get('direction', 'NEUTRAL')).upper()
    whale_strength = float(
        whale.get(
            'likelihood',
            whale.get('strength', 0.0)
        ) or 0.0
    )
    whale_signed = (
        min(1.0, whale_strength / 100.0)
        if whale_dir == 'UP'
        else -min(1.0, whale_strength / 100.0)
        if whale_dir == 'DOWN'
        else 0.0
    )

    families.append(_v239_family(
        'WHALE / LARGE EXECUTION PRESSURE',
        'WHALE',
        whale_signed,
        1.20,
        bool(whale.get('ready')),
        f"{whale_dir} • likelihood {whale_strength:.0f}%"
    ))

    try:
        persistence = self._orderbook_persistence_read()
    except Exception:
        persistence = {}

    pdir = str(persistence.get('direction', 'WAIT')).upper()
    pcons = float(persistence.get('consistency', 0.0) or 0.0)
    psigned = (
        min(1.0, pcons)
        if pdir == 'UP'
        else -min(1.0, pcons)
        if pdir == 'DOWN'
        else 0.0
    )

    families.append(_v239_family(
        'ORDERBOOK PERSISTENCE',
        'ORDERBOOK',
        psigned,
        1.05,
        bool(persistence.get('ready')),
        f"{pdir} • consistency {pcons * 100:.0f}%"
    ))

    # --------------------------------------------------------
    # Historical analog / recross family
    # --------------------------------------------------------
    try:
        deep_def = _v233_deep_read(
            self,
            side=defended,
            now=now,
            mm=mm
        )
    except Exception:
        deep_def = {}

    analog = deep_def.get('analog') or {}
    analog_ready = bool(analog.get('ready'))
    analog_rate = analog.get('rate')
    analog_signed = 0.0
    if analog_rate is not None:
        # rate = chance historical analogs finished in defended side.
        defense_bias = (float(analog_rate) - 0.5) * 2.0
        analog_signed = (
            defense_bias
            if defended == 'UP'
            else -defense_bias
        )

    families.append(_v239_family(
        'HISTORICAL ANALOG MEMORY',
        'MEMORY',
        analog_signed,
        0.90,
        analog_ready,
        (
            f"defended analog rate {float(analog_rate) * 100:.1f}% "
            f"n={int(analog.get('n', 0) or 0)}"
            if analog_rate is not None
            else 'memory building'
        )
    ))

    recross = float(
        deep_def.get('recross_risk', 50.0) or 50.0
    )
    # High recross risk points against defended side.
    recross_attack = max(-1.0, min(1.0, (recross - 50.0) / 50.0))
    recross_signed = (
        -recross_attack
        if defended == 'UP'
        else recross_attack
    )
    families.append(_v239_family(
        'RECROSS / TARGET FAILURE RISK',
        'RECROSS',
        recross_signed,
        1.00,
        True,
        f"recross risk {recross:.0f}%"
    ))

    # --------------------------------------------------------
    # Learned model probability
    # --------------------------------------------------------
    try:
        pup = _v233_model_probability(self, f)
        learned_signed = (float(pup) - 0.5) * 2.0
        learned_ready = True
    except Exception:
        pup = 0.5
        learned_signed = 0.0
        learned_ready = False

    families.append(_v239_family(
        'LEARNED FINISH MODEL',
        'LEARNED',
        learned_signed,
        0.85,
        learned_ready,
        f"model UP {pup * 100:.1f}%"
    ))

    return {
        'ready': True,
        'defended': defended,
        'attack': attack,
        'families': families,
        'features': f,
        'mm': mm,
    }


def _v239_score(self, now=None):
    """
    Score HOLD vs FLIP with independence grouping.

    Multiple correlated families in one group are collapsed to one group vote.
    This prevents confidence inflation from duplicate versions of the same idea.
    """
    now = float(now or time.time())
    built = _v239_build_families(self, now=now)

    if not built.get('ready'):
        return {
            'ready': False,
            'hold': 50.0,
            'flip': 50.0,
            'reliability': 0.0,
            'stage': 'WAITING',
            'families': [],
            'groups': [],
            'defended': 'WAIT',
            'attack': 'WAIT',
        }

    defended = built['defended']
    attack = built['attack']
    defense_sign = 1.0 if defended == 'UP' else -1.0

    ready = [
        f for f in built['families']
        if f.get('ready')
    ]

    grouped = {}
    for f in ready:
        g = f['group']
        support_def = (
            float(f['signed_up']) * defense_sign
        )
        item = dict(f)
        item['support_defended'] = _v239_clip(support_def)
        grouped.setdefault(g, []).append(item)

    group_rows = []
    for group, rows in grouped.items():
        # Take strongest member plus modest corroboration, not raw sum.
        rows = sorted(
            rows,
            key=lambda x: abs(x['support_defended']) * x['weight'],
            reverse=True,
        )
        primary = rows[0]
        base = primary['support_defended']
        weight = primary['weight']

        if len(rows) > 1:
            corroboration = sum(
                r['support_defended'] * r['weight']
                for r in rows[1:]
            ) / max(
                1e-9,
                sum(r['weight'] for r in rows[1:])
            )
            base = _v239_clip(base * 0.80 + corroboration * 0.20)

        group_rows.append({
            'group': group,
            'vote': base,
            'weight': weight,
            'members': rows,
        })

    total_w = sum(g['weight'] for g in group_rows) or 1.0
    signed_hold = sum(
        g['vote'] * g['weight']
        for g in group_rows
    ) / total_w
    signed_hold = _v239_clip(signed_hold)

    raw_hold = 50.0 + signed_hold * 44.0
    raw_flip = 100.0 - raw_hold

    # Breadth of independent agreement.
    hold_groups = sum(
        1 for g in group_rows if g['vote'] >= 0.18
    )
    flip_groups = sum(
        1 for g in group_rows if g['vote'] <= -0.18
    )
    neutral_groups = len(group_rows) - hold_groups - flip_groups

    # Reliability rewards breadth + decisive separation, penalizes contradiction.
    breadth = min(1.0, len(group_rows) / 9.0)
    separation = min(1.0, abs(signed_hold) / 0.55)
    contradiction = min(1.0, min(hold_groups, flip_groups) / 4.0)
    reliability = (
        32.0
        + breadth * 34.0
        + separation * 30.0
        - contradiction * 20.0
    )
    reliability = max(10.0, min(98.0, reliability))

    # Do not display extreme confidence when reliability is weak.
    shrink = 0.45 + 0.55 * (reliability / 100.0)
    hold = 50.0 + (raw_hold - 50.0) * shrink
    flip = 100.0 - hold

    # Historical recross and confirmed breakout can add urgency.
    try:
        latch = dict(
            getattr(self, '_v228_breakout_latch', {}) or {}
        )
    except Exception:
        latch = {}

    if latch.get('active'):
        side = _v228_side(latch.get('side'))
        if side == attack:
            flip = max(flip, 90.0)
            hold = 100.0 - flip
            reliability = max(reliability, 88.0)

    # Stage labels.
    if flip >= 88.0 and reliability >= 70.0:
        stage = 'FLIP CONFIRMED'
    elif flip >= 74.0 and reliability >= 62.0:
        stage = 'FLIP LIKELY'
    elif flip >= 61.0:
        stage = 'FLIP FORMING'
    elif flip >= 52.0:
        stage = 'FLIP WATCH'
    elif hold >= 72.0 and reliability >= 60.0:
        stage = 'HOLDING STRONG'
    else:
        stage = 'MIXED / HOLD WATCH'

    return {
        'ready': True,
        'hold': max(0.0, min(100.0, hold)),
        'flip': max(0.0, min(100.0, flip)),
        'reliability': reliability,
        'stage': stage,
        'families': ready,
        'groups': sorted(
            group_rows,
            key=lambda g: abs(g['vote']) * g['weight'],
            reverse=True,
        ),
        'hold_groups': hold_groups,
        'flip_groups': flip_groups,
        'neutral_groups': neutral_groups,
        'defended': defended,
        'attack': attack,
        'signed_hold': signed_hold,
    }


def _v239_risk_velocity(self, read, now=None):
    now = float(now or time.time())
    hist = list(
        getattr(self, '_v239_risk_history', []) or []
    )
    hist.append((now, float(read.get('flip', 50.0))))
    hist = [
        (t, v)
        for t, v in hist
        if now - float(t) <= 6.0
    ][-120:]
    self._v239_risk_history = hist

    def velocity(horizon):
        if len(hist) < 2:
            return 0.0
        old = None
        for t, v in hist:
            if now - float(t) >= horizon:
                old = (float(t), float(v))
        if old is None:
            old = (
                float(hist[0][0]),
                float(hist[0][1])
            )
        dt = max(0.10, now - old[0])
        return (
            float(read.get('flip', 50.0)) - old[1]
        ) / dt

    v1 = velocity(1.0)
    v3 = velocity(3.0)

    if v1 >= 8.0 or v3 >= 5.0:
        label = 'RISK ACCELERATING FAST'
    elif v1 >= 3.5 or v3 >= 2.0:
        label = 'RISK ACCELERATING'
    elif v1 <= -5.0 or v3 <= -3.0:
        label = 'FLIP RISK COOLING'
    else:
        label = 'RISK VELOCITY STABLE'

    return {
        'v1': v1,
        'v3': v3,
        'label': label,
    }


def _v239_family_lines(read):
    defended = read.get('defended', 'WAIT')
    attack = read.get('attack', 'WAIT')
    lines = []

    for g in read.get('groups', []):
        vote = float(g.get('vote', 0.0) or 0.0)
        if vote >= 0.18:
            verdict = f'HOLD {defended}'
        elif vote <= -0.18:
            verdict = f'FLIP {attack}'
        else:
            verdict = 'NEUTRAL / MIXED'

        members = g.get('members') or []
        details = []
        for m in members[:3]:
            details.append(
                f"{m.get('name')}: {m.get('detail','')}"
            )

        lines.append(
            f"[{verdict:<12}] "
            f"{g.get('group'):<11} "
            f"vote {vote:+.2f} • "
            + " | ".join(details)
        )

    return lines


def _v239_explanation(read, vel):
    defended = read.get('defended', 'WAIT')
    attack = read.get('attack', 'WAIT')
    flip = float(read.get('flip', 50.0))
    hold = float(read.get('hold', 50.0))
    reliability = float(read.get('reliability', 0.0))
    hg = int(read.get('hold_groups', 0))
    fg = int(read.get('flip_groups', 0))

    top_hold = [
        g for g in read.get('groups', [])
        if float(g.get('vote', 0)) >= 0.18
    ][:3]
    top_flip = [
        g for g in read.get('groups', [])
        if float(g.get('vote', 0)) <= -0.18
    ][:3]

    hold_names = ', '.join(
        g['group'] for g in top_hold
    ) or 'none strongly'
    flip_names = ', '.join(
        g['group'] for g in top_flip
    ) or 'none strongly'

    if flip >= 74:
        core = (
            f"The referee sees a real attack on {defended}. "
            f"{fg} independent groups support {attack}; "
            f"strongest flip groups: {flip_names}."
        )
    elif hold >= 70:
        core = (
            f"{defended} is still defending well. "
            f"{hg} independent groups support the hold; "
            f"strongest hold groups: {hold_names}."
        )
    else:
        core = (
            f"The market is mixed. {hg} independent groups defend {defended} "
            f"while {fg} attack toward {attack}. "
            f"Do not treat the current read as a clean reversal yet."
        )

    confirm = (
        f"Flip confirmation strengthens if FLOW + STRUCTURE/MICRO + "
        f"GEOMETRY/MOTION independently align toward {attack}. "
        f"The flip thesis weakens if target cushion recovers, Bookmap flow "
        f"returns to {defended}, and micro/structure stop confirming the attack."
    )

    return (
        f"{core} Reliability {reliability:.0f}%. "
        f"{vel.get('label')} "
        f"({vel.get('v1',0):+.1f} pts/s 1s, "
        f"{vel.get('v3',0):+.1f} pts/s 3s). "
        + confirm
    )


def _v239_draw_flip_bar(self):
    canvas = getattr(self, '_v239_flip_bar', None)
    read = dict(
        getattr(self, '_v239_last_read', {}) or {}
    )
    if canvas is None:
        return

    try:
        w = max(240, int(canvas.winfo_width()))
        h = max(24, int(canvas.winfo_height()))
    except Exception:
        w, h = 600, 28

    hold = float(read.get('hold', 50.0) or 50.0)
    flip = float(read.get('flip', 50.0) or 50.0)
    split = max(1, min(w - 1, int(w * hold / 100.0)))

    canvas.delete('all')
    canvas.create_rectangle(
        1, 1, split, h - 1,
        fill=GREEN, outline=''
    )
    canvas.create_rectangle(
        split, 1, w - 1, h - 1,
        fill=RED, outline=''
    )
    canvas.create_text(
        w / 2, h / 2,
        text=f'HOLD {hold:.0f}%  |  FLIP {flip:.0f}%',
        fill=TEXT,
        font=('Segoe UI', 10, 'bold')
    )


def _v239_set_family_text(self, text):
    widget = getattr(self, '_v239_family_text', None)
    if widget is None:
        return
    try:
        old = widget.get('1.0', 'end-1c')
        if old == text:
            return
        widget.configure(state='normal')
        widget.delete('1.0', 'end')
        widget.insert('1.0', text)
        widget.configure(state='disabled')
    except Exception:
        pass


def _v239_command_center_tick(self):
    try:
        now = time.time()
        read = _v239_score(self, now=now)

        if not read.get('ready'):
            self.v239_flip_headline_var.set(
                'FLIP RISK COMMAND CENTER • waiting for BOOKMAP defended side'
            )
            self.v239_flip_confidence_var.set(
                'HOLD -- • FLIP -- • RELIABILITY --'
            )
            self.v239_flip_stage_var.set(
                'STAGE: WAITING FOR LOCK'
            )
            self.v239_flip_accel_var.set(
                'RISK VELOCITY: waiting for defended side'
            )
            self.v239_flip_explain_var.set(
                'No reversal score is allowed until Bookmap has an earned defended side.'
            )
            _v239_set_family_text(
                self,
                'Waiting for Bookmap Open Lock / live defended side.'
            )
        else:
            vel = _v239_risk_velocity(self, read, now=now)
            self._v239_last_read = dict(read)

            defended = read['defended']
            attack = read['attack']
            self.v239_flip_headline_var.set(
                f'DEFENDING {defended} • REVERSAL TARGET {attack} • '
                f'{read["flip_groups"]} FLIP groups vs '
                f'{read["hold_groups"]} HOLD groups'
            )
            self.v239_flip_confidence_var.set(
                f'HOLD {read["hold"]:.0f}% • '
                f'FLIP {read["flip"]:.0f}% • '
                f'RELIABILITY {read["reliability"]:.0f}%'
            )
            self.v239_flip_stage_var.set(
                f'STAGE: {read["stage"]}'
            )
            self.v239_flip_accel_var.set(
                f'{vel["label"]} • '
                f'1s {vel["v1"]:+.1f} pts/s • '
                f'3s {vel["v3"]:+.1f} pts/s'
            )

            lines = _v239_family_lines(read)
            _v239_set_family_text(
                self,
                '\n'.join(lines)
                if lines
                else 'No ready evidence families yet.'
            )

            self.v239_flip_explain_var.set(
                _v239_explanation(read, vel)
            )
            _v239_draw_flip_bar(self)

    except Exception as exc:
        try:
            self.v239_flip_headline_var.set(
                f'FLIP RISK COMMAND CENTER • read error: {str(exc)[:120]}'
            )
        except Exception:
            pass

    try:
        self.root.after(
            300,
            lambda s=self: _v239_command_center_tick(s)
        )
    except Exception:
        pass


def _v239_init(self, *args, **kwargs):
    self._v239_last_read = {}
    self._v239_risk_history = []
    _V239_BASE_INIT(self, *args, **kwargs)

    try:
        self.root.after(
            250,
            lambda s=self: _v239_command_center_tick(s)
        )
    except Exception:
        pass

    try:
        self.root.title(
            'BOOKMAP KING V21.39 — FLIP RISK COMMAND CENTER / FASTER LOCKS'
        )
    except Exception:
        pass


ChartKingPro.__init__ = _v239_init


