_V240_BASE_INIT = ChartKingPro.__init__
_V240_BASE_BOOKMAP_OPEN = ChartKingPro._bookmap_opening_lock_tick
_V240_BASE_RESET_CONTROL = getattr(ChartKingPro, '_v237_reset_round_control', None)


def _v240_bucket(now=None):
    now = float(now or time.time())
    return int(now // 900) * 900


def _v240_capture_earned_open(self, snap, now=None):
    """
    Persist the first genuinely earned BOOKMAP OPEN LOCK for this 15m bucket.

    This is opening-call history only. V21.38's live defended-side rotation
    remains independent and may rotate after confirmed breakouts.
    """
    now = float(now or time.time())
    if not isinstance(snap, dict):
        return None

    side = str(snap.get('lock_side', 'WAIT')).upper()
    if side not in ('UP', 'DOWN'):
        return None

    bucket = _v240_bucket(now)
    saved = dict(getattr(self, '_v240_earned_open_lock', {}) or {})

    # First earned lock of the bucket wins and becomes immutable opening history.
    if int(saved.get('bucket', -1) or -1) != bucket:
        saved = dict(snap)
        saved['bucket'] = bucket
        saved['v240_earned_ts'] = now
        saved['v240_immutable_opening_call'] = True
        self._v240_earned_open_lock = saved

    return dict(self._v240_earned_open_lock)


def _v240_restore_earned_open(self, now=None):
    """
    Restore the earned Open Lock if any inherited/legacy wrapper temporarily
    clears opening_lock_snapshot during the same 15m market.
    """
    now = float(now or time.time())
    bucket = _v240_bucket(now)
    saved = dict(getattr(self, '_v240_earned_open_lock', {}) or {})

    if int(saved.get('bucket', -1) or -1) != bucket:
        return None

    side = str(saved.get('lock_side', 'WAIT')).upper()
    if side not in ('UP', 'DOWN'):
        return None

    current = getattr(self, 'opening_lock_snapshot', None)
    current_side = str((current or {}).get('lock_side', 'WAIT')).upper()

    if current_side not in ('UP', 'DOWN'):
        self.opening_lock_snapshot = dict(saved)
        self.opening_lock_candidate = None
        self.opening_lock_candidate_since = 0.0

        try:
            price = float(saved.get('price', 0.0) or 0.0)
            score = float(saved.get('forecast_score', 0.0) or 0.0)
            self.opening_lock_var.set(
                f'OPEN LOCK: {side} LOCKED @ {money(price)} • '
                f'EARNED / FROZEN FOR ROUND • score {score:+.1f}'
            )
        except Exception:
            pass

    return dict(saved)


def _v240_bookmap_open(self, warm, now=None):
    """
    Correct Bookmap Open Lock lifecycle:

      BEFORE LOCK:
        Coin-flip filter may block an early lock.

      AFTER LOCK:
        The earned opening lock can NEVER be revoked by a later coin-flip read.
        It remains frozen until the 15m bucket changes or user explicitly resets.

    Confirmed-breakout live-defense rotation remains handled by V21.38 and does
    NOT rewrite this historical opening call.
    """
    now = float(now or time.time())
    bucket = _v240_bucket(now)

    saved = dict(getattr(self, '_v240_earned_open_lock', {}) or {})
    if int(saved.get('bucket', -1) or -1) != bucket:
        self._v240_earned_open_lock = {}
        saved = {}

    # If already earned, return it BEFORE the V21.33 coin-flip gate can run.
    restored = _v240_restore_earned_open(self, now=now)
    if restored:
        side = str(restored.get('lock_side', 'WAIT')).upper()
        try:
            dr = _v233_deep_read(self, side=side, now=now)
            self.v233_bookmap_grade_var.set(
                _v233_lock_text(dr, 'BOOKMAP')
            )
        except Exception:
            pass
        return dict(restored)

    # No earned lock yet: use the existing full V21.39 logic, including the
    # coin-flip no-early-lock filter and the faster patient formulation.
    snap = _V240_BASE_BOOKMAP_OPEN(self, warm, now=now)

    if snap:
        frozen = _v240_capture_earned_open(self, snap, now=now)
        if frozen:
            self.opening_lock_snapshot = dict(frozen)
            return dict(frozen)

    return snap


def _v240_lock_watchdog(self):
    """
    Defense-in-depth continuity watchdog.

    It does NOT create a lock.
    It only restores a lock that was previously and legitimately earned during
    this exact 15m bucket if some older callback clears the live reference.
    """
    try:
        _v240_restore_earned_open(self, now=time.time())
    except Exception:
        pass

    try:
        self.root.after(
            150,
            lambda s=self: _v240_lock_watchdog(s)
        )
    except Exception:
        pass


def _v240_reset_round_control(self):
    """
    Explicit RESET ROUND is allowed to forget the frozen opening call.
    """
    self._v240_earned_open_lock = {}

    if callable(_V240_BASE_RESET_CONTROL):
        try:
            return _V240_BASE_RESET_CONTROL(self)
        except Exception:
            pass

    try:
        self.opening_lock_snapshot = None
        self.opening_lock_candidate = None
        self.opening_lock_candidate_since = 0.0
        self.opening_lock_bucket = None
        self._v229_open_state = {}
        self._v229_target_motion = []
        self._v228_breakout_latch = {}
        self._v228_mm_lock_state = {}
        self._v238_defense_rotation = {}
        self.opening_lock_var.set(
            'OPEN LOCK: RESET • rebuilding'
        )
        return True
    except Exception:
        return False


def _v240_init(self, *args, **kwargs):
    self._v240_earned_open_lock = {}
    _V240_BASE_INIT(self, *args, **kwargs)

    # If startup inherited an already-earned snapshot, archive it immediately.
    try:
        snap = getattr(self, 'opening_lock_snapshot', None)
        if snap:
            _v240_capture_earned_open(
                self,
                snap,
                now=time.time()
            )
    except Exception:
        pass

    try:
        self.root.after(
            120,
            lambda s=self: _v240_lock_watchdog(s)
        )
    except Exception:
        pass

    try:
        self.root.title(
            'BOOKMAP KING V21.40 — PERMANENT OPEN LOCK / COMMAND CENTER CONTINUITY'
        )
    except Exception:
        pass


ChartKingPro._bookmap_opening_lock_tick = _v240_bookmap_open
ChartKingPro._v237_reset_round_control = _v240_reset_round_control
ChartKingPro.__init__ = _v240_init


