_V243_BASE_INIT = ChartKingPro.__init__


def _v243_bookmap_opening_lock_tick(self, warm, now=None):
    """
    Bookmap Open Lock with NO elapsed-time/countdown gate.

    The lock is earned from evidence quality + consecutive observations.
    Clean straight-shot evidence retains the snipe lane.
    Once earned, V21.40 keeps the lock frozen for the round.
    """
    now = float(now or time.time())
    bucket = int(now // 900) * 900

    if self.opening_lock_bucket != bucket:
        self.opening_lock_bucket = bucket
        self.opening_lock_snapshot = None
        self.opening_lock_candidate = None
        self.opening_lock_candidate_since = 0.0
        self._v229_open_state = {
            'bucket': bucket, 'candidate': 'WAIT', 'since': 0.0,
            'samples': 0, 'ema': 0.0, 'flips': 0, 'last_live': None,
            'last_ts': now, 'velocity_ema': 0.0, 'target_signed': 0.0
        }
        self.opening_lock_var.set(
            'OPEN LOCK: BUILDING • evidence-driven • waiting for Bookmap evidence to mature'
        )

    if self.opening_lock_snapshot:
        return dict(self.opening_lock_snapshot)

    if not warm or not warm.get('ready'):
        self.opening_lock_var.set(
            'OPEN LOCK: BUILDING • waiting for native Bookmap flow'
        )
        return None

    live = float(warm.get('live', 0.0) or 0.0)
    signed = max(-1.0, min(1.0, float(warm.get('signed', 0.0) or 0.0)))
    st = dict(getattr(self, '_v229_open_state', {}) or {})
    if st.get('bucket') != bucket:
        st = {
            'bucket': bucket, 'candidate': 'WAIT', 'since': 0.0,
            'samples': 0, 'ema': 0.0, 'flips': 0, 'last_live': None,
            'last_ts': now, 'velocity_ema': 0.0, 'target_signed': 0.0
        }

    prev_live = st.get('last_live')
    prev_ts = float(st.get('last_ts', now) or now)
    dt = max(0.05, now - prev_ts)
    velocity = 0.0 if prev_live is None else (live - float(prev_live)) / dt
    velocity_ema = float(st.get('velocity_ema', 0.0) or 0.0) * 0.72 + velocity * 0.28

    target = None
    target_signed = 0.0
    target_distance = 0.0
    try:
        target, _ = self.effective_target()
    except Exception:
        target = None

    range_ref = 25.0
    try:
        if self.btc_15m:
            c = self.btc_15m[-1]
            range_ref = max(
                25.0,
                float(c.get('high', live)) - float(c.get('low', live)),
                abs(live - float(c.get('open', live)))
            )
    except Exception:
        pass

    if target is not None and live > 0:
        target = float(target)
        target_distance = live - target
        target_signed = max(
            -2.0, min(2.0, target_distance / max(range_ref, 1e-9))
        )

    velocity_norm = max(-1.0, min(1.0, velocity_ema / 12.0))
    composite = (
        signed * 0.68
        + max(-1.0, min(1.0, target_signed)) * 0.20
        + velocity_norm * 0.12
    )
    ema = float(st.get('ema', 0.0) or 0.0) * 0.74 + composite * 0.26
    candidate = 'UP' if ema >= 0.30 else 'DOWN' if ema <= -0.30 else 'WAIT'
    previous_candidate = str(st.get('candidate', 'WAIT')).upper()

    if candidate == 'WAIT':
        st['samples'] = max(0, int(st.get('samples', 0) or 0) - 1)
        st['ema'] = ema
        st['last_live'] = live
        st['last_ts'] = now
        st['velocity_ema'] = velocity_ema
        st['target_signed'] = target_signed
        self._v229_open_state = st
        self.opening_lock_candidate = None
        self.opening_lock_candidate_since = 0.0
        self.opening_lock_var.set(
            f'OPEN LOCK: BUILDING • evidence {ema:+.2f} • '
            f'target {target_distance:+.1f}$ • motion {velocity_ema:+.2f}$/s'
        )
        return None

    if previous_candidate != candidate:
        if previous_candidate in ('UP', 'DOWN'):
            st['flips'] = int(st.get('flips', 0) or 0) + 1
        st['candidate'] = candidate
        st['since'] = now
        st['samples'] = 1
    else:
        st['samples'] = int(st.get('samples', 0) or 0) + 1

    st['ema'] = ema
    st['last_live'] = live
    st['last_ts'] = now
    st['velocity_ema'] = velocity_ema
    st['target_signed'] = target_signed
    self._v229_open_state = st
    self.opening_lock_candidate = candidate
    self.opening_lock_candidate_since = float(st.get('since', now) or now)

    samples = int(st.get('samples', 0) or 0)
    flips = int(st.get('flips', 0) or 0)
    direction_sign = 1.0 if candidate == 'UP' else -1.0
    flow_support = signed * direction_sign
    target_support = target_signed * direction_sign if target is not None else 0.0
    motion_support = velocity_norm * direction_sign
    strength = abs(ema)

    supports = 0
    if flow_support >= 0.24:
        supports += 1
    if target is None or target_support >= -0.12:
        supports += 1
    if motion_support >= -0.08:
        supports += 1
    if target is not None and target_support >= 0.18:
        supports += 1
    if motion_support >= 0.18:
        supports += 1

    try:
        structure_ctx = _v242_structure_context(self, now=now, live=live)
    except Exception:
        structure_ctx = {}

    ob_signed_up = float(structure_ctx.get('order_block_signed_up', 0.0) or 0.0)
    ob_support = ob_signed_up * direction_sign
    hostile_order_block = (
        bool(structure_ctx.get('inside_order_block'))
        and ob_support <= -0.28
    )

    # No clock timer. Samples/evidence are the persistence mechanism.
    required_samples = 9 + min(14, flips * 2)
    if strength < 0.42:
        required_samples += 3
    if strength < 0.35:
        required_samples += 3
    if hostile_order_block:
        required_samples += 3

    clean_snipe = (
        flips == 0
        and strength >= 0.54
        and flow_support >= 0.44
        and supports >= 4
        and (target is None or target_support >= 0.14)
        and motion_support >= 0.08
        and not hostile_order_block
    )
    if clean_snipe:
        required_samples = min(required_samples, 6)

    mature = (
        samples >= required_samples
        and strength >= 0.30
        and flow_support >= 0.20
        and supports >= 3
    )

    if not mature:
        self.opening_lock_var.set(
            f'OPEN LOCK: FORMULATING {candidate} • '
            f'{"CLEAN SNIPE" if clean_snipe else "EVIDENCE CHECK"} • '
            f'{samples}/{required_samples} confirmations • evidence {ema:+.2f} • '
            f'target {target_distance:+.1f}$ • motion {velocity_ema:+.2f}$/s'
            + (' • HOSTILE ORDER BLOCK: PROVE IT' if hostile_order_block else '')
        )
        return None

    score = ema * 10.0
    reasons = [
        f'Bookmap flow {signed:+.2f}',
        f'target geometry {target_signed:+.2f}',
        f'Bookmap motion {velocity_ema:+.2f}$/s',
        f'{"CLEAN SNIPE" if clean_snipe else "EVIDENCE"} {samples} confirmations',
        str(structure_ctx.get('summary', 'structure neutral'))
    ]
    snap = {
        'time': now, 'price': live, 'lock_side': candidate,
        'lock_remaining': 'OPEN', 'lock_minute': 0,
        'forecast_score': score, 'forecast_threshold': 3.0,
        'forecast_reasons': ' • '.join(reasons),
        'source': 'BOOKMAP OPEN/NOW • EVIDENCE-DRIVEN'
    }
    self.opening_lock_snapshot = snap
    self.opening_lock_candidate = None
    self.opening_lock_candidate_since = 0.0
    self.opening_lock_var.set(
        f'OPEN LOCK: {candidate} LOCKED @ {money(live)} • '
        f'{"CLEAN SNIPE" if clean_snipe else "EVIDENCE LOCK"} • '
        f'{samples} confirmations • score {score:+.1f}'
    )
    try:
        self._checkpoint_status_summary()
    except Exception:
        pass
    return dict(snap)


def _v243_mm3_lock_core(self, mm, now=None):
    """
    MM3 lock core with NO elapsed-time/countdown gate.
    Quality gates are unchanged; consecutive qualifying observations replace
    the clock timer.
    """
    now = float(now or time.time())
    bucket = _v228_bucket(now)
    st = dict(getattr(self, '_v228_mm_lock_state', {}) or {})
    if st.get('bucket') != bucket:
        st = _v228_reset_lock_state(st, bucket)

    committed = _v228_side((mm or {}).get(
        'committed_side', (mm or {}).get('settlement_side')
    ))
    settle = _v228_side((mm or {}).get('settlement_side'))
    early = _v228_side((mm or {}).get('early_side', settle))
    score = float((mm or {}).get(
        'settlement_score', (mm or {}).get('score', 0)
    ) or 0)
    early_score = float((mm or {}).get('early_score', score) or 0)
    conv = int((mm or {}).get('settlement_convergence', 0) or 0)
    fam = int((mm or {}).get('family_count', 0) or 0)
    straight = bool((mm or {}).get('straight_shot'))

    side = committed if committed in ('UP', 'DOWN') else settle
    aligned = (
        side in ('UP', 'DOWN')
        and settle == side
        and (early == side or early == 'WAIT' or early_score >= 84)
    )
    usable = aligned and score >= 84.0 and (conv >= 2 or fam >= 4)
    strong = aligned and score >= 93.0 and conv >= 2

    locked = _v228_side(st.get('locked'))

    if locked == 'WAIT':
        if usable:
            if _v228_side(st.get('candidate')) != side:
                st['candidate'] = side
                st['candidate_since'] = now
                st['candidate_samples'] = 1
            else:
                st['candidate_samples'] = int(
                    st.get('candidate_samples', 0) or 0
                ) + 1

            needed_samples = 4 if (strong or straight) else 7
            if int(st.get('candidate_samples', 0) or 0) >= needed_samples:
                st['locked'] = side
                st['locked_ts'] = now
                st['candidate'] = 'WAIT'
                st['candidate_since'] = 0.0
                st['candidate_samples'] = 0
                st['last_reason'] = (
                    f'score {score:.0f}/100 • convergence {conv}/3 • '
                    f'families {fam}'
                )
        else:
            st['candidate'] = 'WAIT'
            st['candidate_since'] = 0.0
            st['candidate_samples'] = 0
    else:
        # Hold the MM3 lock. Do not use a countdown to rotate it.
        # A genuinely opposite read must persist through confirmations.
        opposite = 'DOWN' if locked == 'UP' else 'UP'
        flip_ok = (
            side == opposite and settle == opposite
            and score >= 91.0 and conv >= 2
            and (early == opposite or early_score >= 90)
        )
        if flip_ok:
            if _v228_side(st.get('flip_candidate')) != opposite:
                st['flip_candidate'] = opposite
                st['flip_since'] = now
                st['flip_samples'] = 1
            else:
                st['flip_samples'] = int(st.get('flip_samples', 0) or 0) + 1

            needed_flip_samples = 7 if score >= 96 else 10
            if int(st.get('flip_samples', 0) or 0) >= needed_flip_samples:
                st['locked'] = opposite
                st['locked_ts'] = now
                st['flip_candidate'] = 'WAIT'
                st['flip_since'] = 0.0
                st['flip_samples'] = 0
                st['last_reason'] = (
                    f'confirmed MM rotation • score {score:.0f}/100 • '
                    f'convergence {conv}/3'
                )
        else:
            st['flip_candidate'] = 'WAIT'
            st['flip_since'] = 0.0
            st['flip_samples'] = 0

    self._v228_mm_lock_state = st
    locked = _v228_side(st.get('locked'))

    if locked in ('UP', 'DOWN'):
        text = (
            f'MASTERMIND LOCK: {locked} LOCKED • settlement {score:.0f}/100 • '
            f'convergence {conv}/3 • families {fam}'
        )
        if _v228_side(st.get('flip_candidate')) in ('UP', 'DOWN'):
            text += (
                f' • opposite {_v228_side(st.get("flip_candidate"))} '
                f'confirming {int(st.get("flip_samples", 0) or 0)} observations'
            )
    elif usable:
        needed_samples = 4 if (strong or straight) else 7
        text = (
            f'MASTERMIND LOCK: FORMULATING {side} • '
            f'{int(st.get("candidate_samples", 0) or 0)}/{needed_samples} confirmations • '
            f'score {score:.0f}/100 • convergence {conv}/3 • families {fam}'
        )
    else:
        text = (
            f'MASTERMIND LOCK: UNLOCKED • evidence not ready • '
            f'committed {committed} • settlement {score:.0f}/100 • '
            f'convergence {conv}/3'
        )

    return {'side': locked, 'text': text, 'state': st}


def _v243_mm3_deep_lock(self, mm, now=None):
    """
    V21.42 structure-aware MM3 wrapper, but removes the T-5/countdown gate.
    Coin-flip reads simply remain unqualified until evidence improves.
    """
    now = float(now or time.time())
    raw = dict(mm or {})
    settle = str(raw.get('settlement_side', 'WAIT')).upper()

    try:
        ctx = _v242_structure_context(self, now=now)
    except Exception:
        ctx = {}

    sign = 1.0 if settle == 'UP' else -1.0 if settle == 'DOWN' else 0.0
    structural = float(ctx.get('signed_up', 0.0) or 0.0) * sign
    score = float(raw.get('settlement_score', raw.get('score', 0.0)) or 0.0)

    if settle in ('UP', 'DOWN'):
        if structural <= -0.34:
            raw['settlement_score'] = max(
                0.0, score - min(7.0, abs(structural) * 9.0)
            )
            if bool(ctx.get('inside_order_block')):
                raw['settlement_convergence'] = max(
                    0, int(raw.get('settlement_convergence', 0) or 0) - 1
                )
            raw['_v243_structure_note'] = 'HOSTILE ORDER-BLOCK / DOJI CONTEXT'
        elif structural >= 0.34:
            raw['settlement_score'] = min(
                100.0, score + min(3.5, structural * 4.5)
            )
            raw['_v243_structure_note'] = 'STRUCTURE CONFIRMS'
        else:
            raw['_v243_structure_note'] = 'STRUCTURE MIXED'

    dr = _v233_deep_read(self, side=settle, now=now, mm=raw)
    try:
        self.v233_mm3_grade_var.set(_v233_lock_text(dr, 'TEAM MM3'))
    except Exception:
        pass

    # No "wait until T-5". Coin flip is an evidence state, not a timer.
    if dr.get('grade') == 'COIN FLIP':
        st = dict(getattr(self, '_v228_mm_lock_state', {}) or {})
        if _v228_side(st.get('locked')) == 'WAIT':
            st['candidate'] = 'WAIT'
            st['candidate_since'] = 0.0
            st['candidate_samples'] = 0
            self._v228_mm_lock_state = st
            return {
                'side': 'WAIT',
                'text': (
                    'TEAM MM3 LOCK: UNLOCKED • COIN FLIP • '
                    'waiting for stronger evidence — NO TIMER'
                ),
                'state': st
            }

    signed = float(dr.get('signed', 0.0) or 0.0)
    side_sign = 1.0 if settle == 'UP' else -1.0 if settle == 'DOWN' else 0.0
    support = signed * side_sign

    if settle in ('UP', 'DOWN'):
        score = float(raw.get('settlement_score', raw.get('score', 0.0)) or 0.0)
        if support >= 0.22:
            raw['settlement_score'] = min(
                100.0, score + min(10.0, support * 18.0)
            )
            raw['family_count'] = int(raw.get('family_count', 0) or 0) + 1
        elif support <= -0.22:
            raw['settlement_score'] = max(
                0.0, score - min(18.0, abs(support) * 24.0)
            )
            raw['settlement_convergence'] = max(
                0, int(raw.get('settlement_convergence', 0) or 0) - 1
            )

    out = _v243_mm3_lock_core(self, raw, now=now)
    out = dict(out or {})
    out['text'] = str(out.get('text', '')).replace(
        'MASTERMIND LOCK:', 'TEAM MM3 LOCK:'
    )

    note = str(raw.get('_v243_structure_note', ''))
    if note:
        out['text'] += f' • {note}'

    if str(out.get('side', 'WAIT')).upper() in ('UP', 'DOWN'):
        locked = str(out.get('side')).upper()
        lr = _v233_deep_read(self, side=locked, now=now, mm=raw)
        out['text'] += f' • {lr.get("grade")}'
        try:
            self.v233_mm3_grade_var.set(_v233_lock_text(lr, 'TEAM MM3'))
        except Exception:
            pass

    return out


