# ============================================================================

_V244_BASE_INIT = ChartKingPro.__init__
_V244_BASE_REVERSAL_PANEL = ChartKingPro._update_reversal_panel
_V244_BASE_SURVIVAL_PANEL = ChartKingPro._update_flip_survival_panel


def _v244_bucket(now=None):
    now = float(now or time.time())
    return int(now // 900) * 900


def _v244_command_context(self, now=None):
    """
    Pull the already-existing Flip Risk Command Center as corroboration.
    This does not replace the breakout engine; it only helps decide whether
    a raw breakout spike has broad enough support to deserve escalation.
    """
    try:
        read = dict(getattr(self, '_v239_last_read', {}) or {})
    except Exception:
        read = {}

    return {
        'ready': bool(read.get('ready')),
        'flip': float(read.get('raw_flip', read.get('flip', 50.0)) or 50.0),
        'reliability': float(
            read.get('raw_reliability', read.get('reliability', 0.0)) or 0.0
        ),
        'flip_groups': int(read.get('flip_groups', 0) or 0),
        'hold_groups': int(read.get('hold_groups', 0) or 0),
        'attack': str(read.get('attack', 'WAIT')).upper(),
    }


def _v244_filter_trend_state(self, trend_state=None, now=None):
    """
    Stabilize the actual Breakout/Reversal authority.

    Goals:
      - tiny raw risk changes do not move the visible risk meter
      - WATCH requires persistent, multi-family evidence
      - CONFIRMED requires stronger persistence + breadth
      - a single doji/order-block/whale/micro event cannot confirm breakout
      - real threats still accelerate once independently corroborated
    """
    now = float(now or time.time())
    raw = dict(trend_state or {})
    bucket = _v244_bucket(now)

    state = dict(getattr(self, '_v244_break_state', {}) or {})
    if int(state.get('bucket', -1) or -1) != bucket:
        state = {
            'bucket': bucket,
            'risk': 8.0,
            'watch_side': 'WAIT',
            'watch_samples': 0,
            'confirm_side': 'WAIT',
            'confirm_samples': 0,
            'clear_samples': 0,
            'mode': 'CALM',
        }

    defended = _v242_original_defense(self, now=now)
    raw_risk = max(0.0, min(100.0, float(raw.get('risk', 0.0) or 0.0)))
    raw_status = str(raw.get('status', 'HEALTHY') or 'HEALTHY').upper()
    flip_to = _v228_side(raw.get('flip_to'))
    team = dict(raw.get('team_breakout') or {})
    team_stage = str(team.get('stage', 'NONE') or 'NONE').upper()
    team_score = max(0.0, min(100.0, float(team.get('score', 0.0) or 0.0)))
    team_families = int(team.get('families', 0) or 0)

    cc = _v244_command_context(self, now=now)
    cc_matches = (
        cc.get('ready')
        and flip_to in ('UP', 'DOWN')
        and cc.get('attack') == flip_to
    )

    # Independent breadth gates. "Real threat" deliberately needs more than
    # one source family.
    broad_team = team_families >= 3 and team_score >= 64.0
    broad_command = (
        cc_matches
        and cc['flip_groups'] >= 3
        and cc['reliability'] >= 60.0
        and cc['flip'] >= 64.0
    )
    very_broad_command = (
        cc_matches
        and cc['flip_groups'] >= 4
        and cc['reliability'] >= 70.0
        and cc['flip'] >= 76.0
    )

    against_defense = (
        defended in ('UP', 'DOWN')
        and flip_to in ('UP', 'DOWN')
        and flip_to != defended
    )

    watch_candidate = (
        against_defense
        and raw_risk >= 60.0
        and (broad_team or broad_command)
    )

    confirm_candidate = (
        against_defense
        and (
            raw_status == 'BREAKOUT CONFIRMED'
            or team_stage == 'CONFIRMED'
            or raw_risk >= 88.0
        )
        and raw_risk >= 78.0
        and (
            (team_families >= 4 and team_score >= 76.0)
            or very_broad_command
            or (
                team_families >= 3
                and team_score >= 82.0
                and broad_command
            )
        )
    )

    # Persist WATCH.
    if watch_candidate:
        if state.get('watch_side') == flip_to:
            state['watch_samples'] = int(state.get('watch_samples', 0) or 0) + 1
        else:
            state['watch_side'] = flip_to
            state['watch_samples'] = 1
    else:
        state['watch_side'] = 'WAIT'
        state['watch_samples'] = 0

    # Persist CONFIRMED separately and more strictly.
    if confirm_candidate:
        if state.get('confirm_side') == flip_to:
            state['confirm_samples'] = int(state.get('confirm_samples', 0) or 0) + 1
        else:
            state['confirm_side'] = flip_to
            state['confirm_samples'] = 1
    else:
        state['confirm_side'] = 'WAIT'
        state['confirm_samples'] = 0

    watch_ready = bool(
        watch_candidate
        and int(state.get('watch_samples', 0) or 0) >= 4
    )
    confirmed_ready = bool(
        confirm_candidate
        and int(state.get('confirm_samples', 0) or 0) >= 6
    )

    # Stable visible risk.
    prev = float(state.get('risk', 8.0) or 8.0)
    target = raw_risk

    # Unsupported spikes are capped and heavily damped.
    if not watch_candidate:
        target = min(target, 54.0)

    # Candidate threat can rise, but not jump.
    if watch_candidate and not watch_ready:
        target = min(target, 66.0)

    # WATCH can rise further.
    if watch_ready and not confirmed_ready:
        target = min(max(target, 58.0), 84.0)

    # Only a confirmed real threat may occupy the hard-red range.
    if confirmed_ready:
        target = max(target, 88.0)

    delta = target - prev

    # Deadband.
    if abs(delta) < 4.0:
        visible = prev
    elif delta > 0:
        if confirmed_ready:
            # Real confirmed danger is allowed to move decisively.
            step = min(delta, 10.0)
        elif watch_ready:
            step = min(delta, 5.0)
        else:
            step = min(delta, 2.5)
        visible = prev + step
    else:
        # Risk does not instantly vanish either; require stable improvement.
        if raw_risk <= 42.0 or not watch_candidate:
            state['clear_samples'] = int(state.get('clear_samples', 0) or 0) + 1
        else:
            state['clear_samples'] = 0

        if int(state.get('clear_samples', 0) or 0) >= 3:
            visible = prev + max(delta, -5.0)
        else:
            visible = prev + max(delta, -2.0)

    visible = max(0.0, min(100.0, visible))
    state['risk'] = visible

    if confirmed_ready:
        mode = 'CONFIRMED'
    elif watch_ready:
        mode = 'WATCH'
    elif watch_candidate:
        mode = 'FORMING'
    else:
        mode = 'CALM'
    state['mode'] = mode
    self._v244_break_state = state

    out = dict(raw)
    out['risk'] = visible

    # The filtered state owns escalation. A raw CONFIRMED spike may not leak
    # through before persistence has been earned.
    if confirmed_ready:
        out['status'] = 'BREAKOUT CONFIRMED'
        out['flip_to'] = flip_to
        team2 = dict(team)
        team2['stage'] = 'CONFIRMED'
        out['team_breakout'] = team2
    elif watch_ready:
        out['status'] = 'WATCH'
        out['flip_to'] = flip_to
        team2 = dict(team)
        if str(team2.get('stage', '')).upper() == 'CONFIRMED':
            team2['stage'] = 'LIKELY'
        out['team_breakout'] = team2
    elif watch_candidate:
        out['status'] = 'HEALTHY'
        team2 = dict(team)
        if str(team2.get('stage', '')).upper() in ('LIKELY', 'CONFIRMED'):
            team2['stage'] = 'FORMING'
        out['team_breakout'] = team2
    else:
        out['status'] = 'HEALTHY'

    detail = str(raw.get('detail', '') or '')
    calm_note = (
        f'V21.44 CALM FILTER • {mode} • raw {raw_risk:.0f} → stable {visible:.0f} • '
        f'team {team_families} fam/{team_score:.0f} • '
        f'flip-center {cc["flip_groups"]} groups/{cc["reliability"]:.0f}% rel • '
        f'watch {int(state.get("watch_samples",0) or 0)}/4 • '
        f'confirm {int(state.get("confirm_samples",0) or 0)}/6'
    )
    out['detail'] = (detail + ' • ' + calm_note).strip(' •')

    return out


def _v244_stabilize_survival(self, read=None, now=None):
    """
    Calm Flip Survival.

    Survival is allowed to drop sharply only when the stabilized breakout
    authority has actually established a real WATCH/CONFIRMED threat.
    Otherwise it moves through a deadband with capped step sizes.
    """
    now = float(now or time.time())
    raw = dict(read or {})
    bucket = _v244_bucket(now)
    state = dict(getattr(self, '_v244_survival_state', {}) or {})

    if int(state.get('bucket', -1) or -1) != bucket:
        state = {
            'bucket': bucket,
            'value': 50.0,
            'danger_samples': 0,
            'recovery_samples': 0,
        }

    raw_value = max(0.0, min(100.0, float(raw.get('value', 50.0) or 50.0)))
    prev = float(state.get('value', raw_value) or raw_value)

    break_state = dict(getattr(self, '_v244_break_state', {}) or {})
    mode = str(break_state.get('mode', 'CALM')).upper()
    stable_risk = float(break_state.get('risk', 0.0) or 0.0)

    hard_danger = mode == 'CONFIRMED' and stable_risk >= 82.0
    real_watch = mode in ('WATCH', 'CONFIRMED') and stable_risk >= 58.0

    if real_watch:
        state['danger_samples'] = int(state.get('danger_samples', 0) or 0) + 1
    else:
        state['danger_samples'] = 0

    if raw_value >= prev + 5.0 and not real_watch:
        state['recovery_samples'] = int(state.get('recovery_samples', 0) or 0) + 1
    else:
        state['recovery_samples'] = 0

    target = raw_value

    # A raw survival collapse without an established threat is treated as noise.
    if not real_watch and target < prev - 6.0:
        target = max(target, prev - 4.0)

    delta = target - prev

    if abs(delta) < 4.0:
        visible = prev
    elif delta < 0:
        if hard_danger and int(state.get('danger_samples', 0) or 0) >= 3:
            step = max(delta, -10.0)
        elif real_watch and int(state.get('danger_samples', 0) or 0) >= 3:
            step = max(delta, -5.0)
        else:
            step = max(delta, -2.5)
        visible = prev + step
    else:
        # Recovery is intentionally slower than a genuine confirmed collapse.
        if int(state.get('recovery_samples', 0) or 0) >= 3:
            step = min(delta, 4.0)
        else:
            step = min(delta, 2.0)
        visible = prev + step

    visible = max(0.0, min(100.0, visible))
    state['value'] = visible
    self._v244_survival_state = state

    out = dict(raw)
    out['value'] = visible

    label = str(raw.get('label', 'SAFE') or 'SAFE')
    if hard_danger:
        label = 'REAL BREAKOUT THREAT'
    elif real_watch:
        label = 'UNDER REAL PRESSURE'
    elif visible >= 68:
        label = 'HOLDING'
    elif visible >= 48:
        label = 'WATCHING'
    else:
        label = 'WEAKENING'
    out['label'] = label

    detail = str(raw.get('detail', '') or '')
    out['detail'] = (
        detail
        + f' • V21.44 CALM SURVIVAL • raw {raw_value:.0f} → stable {visible:.0f}'
        + f' • breakout mode {mode} / {stable_risk:.0f}'
    ).strip(' •')

    return out


def _v244_update_reversal_panel(self, d, lock_state=None, trend_state=None):
    # Preserve neutral pre-lock behavior.
    if _v231_preopen_neutral(self):
        return _V244_BASE_REVERSAL_PANEL(
            self, d, lock_state=lock_state, trend_state=trend_state
        )

    stable = _v244_filter_trend_state(
        self, trend_state=trend_state, now=time.time()
    )
    return _V244_BASE_REVERSAL_PANEL(
        self, d, lock_state=lock_state, trend_state=stable
    )


def _v244_update_survival_panel(self, read):
    if _v231_preopen_neutral(self):
        return _V244_BASE_SURVIVAL_PANEL(self, read)

    stable = _v244_stabilize_survival(self, read=read, now=time.time())
    return _V244_BASE_SURVIVAL_PANEL(self, stable)


def _v244_init(self, *args, **kwargs):
    self._v244_break_state = {}
    self._v244_survival_state = {}
    _V244_BASE_INIT(self, *args, **kwargs)

    try:
        self.root.title(
            'BOOKMAP KING V21.44 — CALM BREAKOUT + SURVIVAL / REAL THREATS ONLY'
        )
    except Exception:
        pass


ChartKingPro._update_reversal_panel = _v244_update_reversal_panel
ChartKingPro._update_flip_survival_panel = _v244_update_survival_panel
ChartKingPro.__init__ = _v244_init


