# ============================================================================
# BOOKMAP KING V21.46
# DESKTOP PERFORMANCE + BOOKMAP CONNECTION STABILITY
#
# IMPORTANT:
# - V21.45 strategy/lock/MM3/HOLD/FLIP calculations are unchanged.
# - This patch only improves Bookmap transport, connection debouncing, and
#   high-rate data storage/copying behavior.
# - The known-good V21.45 Bookmap startup/main block below is left untouched.
# ============================================================================

_V246_BASE_INIT = ChartKingPro.__init__
_V246_BASE_CHILD_APPLY = _bk_child_apply_event
_V246_BASE_SUBSCRIBE = bk_subscribe
_V246_BASE_UPDATE_BOOKMAP_PANEL = ChartKingPro._update_bookmap_panel
_V246_BASE_QUOTE_DIAG = _bk_quote_mesh_diagnostic

_V246_DEPTH_LOCK = threading.RLock()
_V246_DEPTH_LATEST = {}
_V246_DEPTH_THREAD_STARTED = False
_V246_DEPTH_THREAD_LOCK = threading.Lock()

_V246_PENDING_FLUSH_LOCK = threading.Lock()
_V246_PENDING_FLUSHING = False

_V246_HEARTBEAT_STARTED = False
_V246_HEARTBEAT_LOCK = threading.Lock()

_V246_UNSUB_LOCK = threading.Lock()
_V246_UNSUB_TOKEN = 0
_V246_PENDING_UNSUB_ALIAS = None


def _v246_send_raw(event):
    try:
        BK_SEND_SOCK.sendto(
            json.dumps(event, separators=(',', ':')).encode('utf-8'),
            (BK_UI_HOST, BK_DATA_PORT)
        )
        return True
    except Exception:
        return False


def _v246_depth_sender_worker():
    """Coalesce depth churn while preserving every trade separately."""
    while True:
        if not BK_UI_READY.is_set():
            time.sleep(0.03)
            continue

        batch = []
        with _V246_DEPTH_LOCK:
            if _V246_DEPTH_LATEST:
                # Keep callback latency bounded: newest state per price wins.
                keys = list(_V246_DEPTH_LATEST.keys())[:500]
                for key in keys:
                    event = _V246_DEPTH_LATEST.pop(key, None)
                    if event is not None:
                        batch.append(event)

        if not batch:
            time.sleep(0.015)
            continue

        for event in batch:
            if not _v246_send_raw(event):
                # UDP localhost failures are unusual; retain only newest state.
                key = (
                    str(event.get('alias', '')),
                    str(event.get('side', '')),
                    float(event.get('price', 0.0) or 0.0),
                )
                with _V246_DEPTH_LOCK:
                    _V246_DEPTH_LATEST[key] = event
                break

        # At most ~20ms depth batching. Trades are still immediate/in-order.
        time.sleep(0.008)


def _v246_ensure_depth_thread():
    global _V246_DEPTH_THREAD_STARTED
    if _V246_DEPTH_THREAD_STARTED:
        return
    with _V246_DEPTH_THREAD_LOCK:
        if _V246_DEPTH_THREAD_STARTED:
            return
        t = threading.Thread(
            target=_v246_depth_sender_worker,
            name='BookmapKingV21_46-DepthCoalescer',
            daemon=True
        )
        t.start()
        _V246_DEPTH_THREAD_STARTED = True


def bk_on_depth(addon, alias, is_bid, price_level, size_level):
    """
    V21.46: Bookmap callbacks no longer JSON/send every depth mutation inline.
    Latest state for each price is coalesced for a few milliseconds, preventing
    the Python bridge from falling behind in very fast books.
    """
    try:
        _v246_ensure_depth_thread()
        event = {
            'type': 'depth',
            'alias': alias,
            'side': 'bid' if bool(is_bid) else 'ask',
            'price': _bk_actual_price(alias, price_level),
            'size': _bk_actual_size(alias, size_level),
            'ts': time.time(),
        }
        key = (
            str(event['alias']),
            str(event['side']),
            float(event['price']),
        )
        with _V246_DEPTH_LOCK:
            _V246_DEPTH_LATEST[key] = event
    except Exception as exc:
        print('[Bookmap King V21.46] depth warning:', exc, flush=True)


def _bk_send_to_ui(event):
    """
    Preserve trade/hello ordering during startup instead of dumping a giant
    synchronous backlog into the UI the instant it says READY.
    """
    global _V246_PENDING_FLUSHING

    kind = str((event or {}).get('type', '')).lower()

    # Depth is handled by the coalescing bridge.
    if kind == 'depth':
        key = (
            str(event.get('alias', '')),
            str(event.get('side', '')),
            float(event.get('price', 0.0) or 0.0),
        )
        with _V246_DEPTH_LOCK:
            _V246_DEPTH_LATEST[key] = dict(event)
        _v246_ensure_depth_thread()
        return

    if (not BK_UI_READY.is_set()) or _V246_PENDING_FLUSHING:
        BK_PENDING_EVENTS.append(dict(event))
        return

    if not _v246_send_raw(event):
        BK_PENDING_EVENTS.append(dict(event))


def _v246_pending_flush_worker():
    global _V246_PENDING_FLUSHING
    try:
        while BK_UI_READY.is_set():
            sent = 0
            while BK_PENDING_EVENTS and sent < 300:
                event = BK_PENDING_EVENTS.popleft()
                if not _v246_send_raw(event):
                    BK_PENDING_EVENTS.appendleft(event)
                    time.sleep(0.03)
                    break
                sent += 1
            if not BK_PENDING_EVENTS:
                break
            time.sleep(0.008)
    finally:
        _V246_PENDING_FLUSHING = False


def _bk_flush_pending():
    global _V246_PENDING_FLUSHING
    with _V246_PENDING_FLUSH_LOCK:
        if _V246_PENDING_FLUSHING:
            return
        _V246_PENDING_FLUSHING = True
        threading.Thread(
            target=_v246_pending_flush_worker,
            name='BookmapKingV21_46-PendingFlush',
            daemon=True
        ).start()


def _v246_heartbeat_worker():
    """Transport heartbeat; does not pretend to be a trade/depth update."""
    while True:
        try:
            if BK_UI_READY.is_set() and BK_ACTIVE_ALIAS:
                _v246_send_raw({
                    'type': 'heartbeat',
                    'alias': BK_ACTIVE_ALIAS,
                    'ts': time.time(),
                })
        except Exception:
            pass
        time.sleep(0.35)


def _v246_ensure_heartbeat():
    global _V246_HEARTBEAT_STARTED
    if _V246_HEARTBEAT_STARTED:
        return
    with _V246_HEARTBEAT_LOCK:
        if _V246_HEARTBEAT_STARTED:
            return
        threading.Thread(
            target=_v246_heartbeat_worker,
            name='BookmapKingV21_46-Heartbeat',
            daemon=True
        ).start()
        _V246_HEARTBEAT_STARTED = True


_V246_BASE_CONTROL_LISTENER = _bk_control_listener


def _bk_control_listener():
    _v246_ensure_depth_thread()
    _v246_ensure_heartbeat()
    return _V246_BASE_CONTROL_LISTENER()


def _v246_finalize_unsubscribe(alias, token):
    global BK_ACTIVE_ALIAS, _V246_PENDING_UNSUB_ALIAS

    with _V246_UNSUB_LOCK:
        if token != _V246_UNSUB_TOKEN:
            return
        if _V246_PENDING_UNSUB_ALIAS != alias:
            return
        _V246_PENDING_UNSUB_ALIAS = None

    if BK_ACTIVE_ALIAS != alias:
        return

    print(
        f'[Bookmap King V21.46] DISCONNECTED CONFIRMED after grace: {alias}',
        flush=True
    )
    BK_ACTIVE_ALIAS = None
    BK_META.pop(alias, None)
    BK_INDICATORS.pop(alias, None)
    BK_INTERVAL_TICKS.pop(alias, None)
    _bk_send_to_ui({'type': 'bye', 'alias': alias, 'ts': time.time()})


def bk_unsubscribe(addon, alias):
    """
    Debounce Bookmap's brief unsubscribe/resubscribe lifecycle blips.

    A ~1 second transient no longer tears down the UI/brain connection state.
    A real disconnect still finalizes after 1.75 seconds.
    """
    global _V246_UNSUB_TOKEN, _V246_PENDING_UNSUB_ALIAS

    with _V246_UNSUB_LOCK:
        _V246_UNSUB_TOKEN += 1
        token = _V246_UNSUB_TOKEN
        _V246_PENDING_UNSUB_ALIAS = alias

    print(
        f'[Bookmap King V21.46] transient disconnect watch: {alias} '
        f'• holding state for 1.75s',
        flush=True
    )
    timer = threading.Timer(
        1.75,
        _v246_finalize_unsubscribe,
        args=(alias, token)
    )
    timer.daemon = True
    timer.start()


def bk_subscribe(
    addon, alias, full_name, is_crypto, pips,
    size_multiplier, instrument_multiplier, supported_features
):
    global _V246_UNSUB_TOKEN, _V246_PENDING_UNSUB_ALIAS, BK_ACTIVE_ALIAS

    # Cancel a brief disconnect if the same instrument returns.
    with _V246_UNSUB_LOCK:
        pending = _V246_PENDING_UNSUB_ALIAS
        _V246_UNSUB_TOKEN += 1
        _V246_PENDING_UNSUB_ALIAS = None

    if pending == alias:
        print(
            f'[Bookmap King V21.46] reconnect absorbed without resetting state: '
            f'{alias}',
            flush=True
        )
    elif pending and pending != alias and BK_ACTIVE_ALIAS == pending:
        # Real instrument switch during the grace window.
        BK_META.pop(pending, None)
        BK_INDICATORS.pop(pending, None)
        BK_INTERVAL_TICKS.pop(pending, None)
        BK_ACTIVE_ALIAS = None

    return _V246_BASE_SUBSCRIBE(
        addon, alias, full_name, is_crypto, pips,
        size_multiplier, instrument_multiplier, supported_features
    )


def _bk_child_apply_event(app, root, event):
    kind = str((event or {}).get('type', '')).lower().strip()
    now = time.time()

    if kind == 'heartbeat':
        try:
            app.bookmap_connected = True
            app.bookmap_transport_last_ts = now
        except Exception:
            pass
        return

    if kind == 'bye':
        try:
            app.bookmap_connected = False
            app.bookmap_transport_last_ts = now
        except Exception:
            pass
        return

    try:
        app.bookmap_transport_last_ts = now
        app.bookmap_last_data_event_ts = now
    except Exception:
        pass

    return _V246_BASE_CHILD_APPLY(app, root, event)


def _bk_child_receiver(app, root):
    """
    Larger localhost receive buffer + batch drain.

    This prevents high-rate depth bursts from starving newer packets and
    eliminates the appearance of a one-second disconnect caused by backlog.
    """
    sock = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
    sock.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
    try:
        sock.setsockopt(socket.SOL_SOCKET, socket.SO_RCVBUF, 4 * 1024 * 1024)
    except Exception:
        pass
    sock.bind((BK_UI_HOST, BK_DATA_PORT))
    sock.settimeout(0.35)

    _bk_send_control({
        'type': 'ready',
        'pid': os.getpid(),
        'ts': time.time()
    })

    while True:
        try:
            raw, _ = sock.recvfrom(65535)
        except socket.timeout:
            try:
                if not root.winfo_exists():
                    break
            except Exception:
                break
            continue
        except Exception:
            break

        packets = [raw]

        # Drain an already-arrived burst without blocking for the next packet.
        try:
            sock.setblocking(False)
            for _i in range(255):
                try:
                    more, _ = sock.recvfrom(65535)
                    packets.append(more)
                except BlockingIOError:
                    break
                except Exception:
                    break
        finally:
            try:
                sock.setblocking(True)
                sock.settimeout(0.35)
            except Exception:
                pass

        # Within one burst, only the latest depth mutation at each price matters.
        # Every trade/hello/heartbeat remains in order.
        depth_latest = {}
        ordered = []

        for packet in packets:
            try:
                event = json.loads(packet.decode('utf-8', errors='ignore'))
            except Exception:
                continue

            kind = str(event.get('type', '')).lower()
            if kind == 'depth':
                key = (
                    str(event.get('alias', '')),
                    str(event.get('side', '')),
                    float(event.get('price', 0.0) or 0.0),
                )
                depth_latest[key] = event
            else:
                ordered.append(event)

        # Keep every executed trade in the native tape, but aggregate the
        # redundant multi-timeframe candle mutations once per event-second.
        # A busy tape previously performed four OHLC writes per trade and
        # could monopolize the Python runtime long enough to starve Tk.
        if not _v256_apply_ordered_events(app, root, ordered):
            try:
                sock.close()
            except Exception:
                pass
            return

        for event in depth_latest.values():
            _bk_child_apply_event(app, root, event)

        # Explicitly yield after a drained burst.  recvfrom() normally yields
        # naturally, but a permanently full localhost socket otherwise lets
        # JSON/depth processing run back-to-back indefinitely.
        try:
            time.sleep(0.001 if len(packets) >= 16 else 0.0)
        except Exception:
            pass

    try:
        sock.close()
    except Exception:
        pass


def _bk_quote_mesh_diagnostic(self):
    now = time.time()
    transport_ts = float(
        getattr(self, 'bookmap_transport_last_ts', 0.0) or 0.0
    )
    data_ts = float(
        getattr(self, 'bookmap_last_data_event_ts', 0.0)
        or getattr(self, 'bookmap_last_event_ts', 0.0)
        or 0.0
    )
    transport_age = max(0.0, now - transport_ts) if transport_ts else 999.0
    data_age = max(0.0, now - data_ts) if data_ts else 999.0
    return (
        f"BOOKMAP {getattr(self, 'bookmap_alias', '--')} • "
        f"events {int(getattr(self, 'bookmap_events_received', 0))} • "
        f"link {transport_age:.2f}s • data {data_age:.2f}s"
    )


def _v246_update_bookmap_panel(self, read=None):
    result = _V246_BASE_UPDATE_BOOKMAP_PANEL(self, read)

    # Do not show a false disconnect simply because the tape/depth did not
    # change for a moment. Brain readiness still depends on real market data.
    try:
        now = time.time()
        transport_ts = float(
            getattr(self, 'bookmap_transport_last_ts', 0.0) or 0.0
        )
        transport_age = (
            max(0.0, now - transport_ts) if transport_ts else 999.0
        )
        if transport_age <= 1.5 and BK_UI_READY.is_set():
            data_ts = float(
                getattr(self, 'bookmap_last_data_event_ts', 0.0)
                or getattr(self, 'bookmap_last_event_ts', 0.0)
                or 0.0
            )
            data_age = max(0.0, now - data_ts) if data_ts else 999.0
            alias = str(getattr(self, 'bookmap_alias', '--'))
            self._set_var_if_changed(
                self.bookmap_status_var,
                f'BOOKMAP: LIVE • {alias} • link {transport_age:.2f}s '
                f'• data {data_age:.2f}s'
            )
    except Exception:
        pass

    return result


ChartKingPro._update_bookmap_panel = _v246_update_bookmap_panel


