import gc as _v247_gc

# Less frequent cyclic-GC scans. V21.46 already bounds high-rate data stores.
try:
    _v247_gc.set_threshold(5000, 50, 50)
except Exception:
    pass

_V247_BASE_INIT = ChartKingPro.__init__
_V247_BASE_UI_TICK = ChartKingPro._ui_tick
_V247_BASE_DRAW_CHART = ChartKingPro.draw_chart

def _v247_init(self, *args, **kwargs):
    _V247_BASE_INIT(self, *args, **kwargs)

    # Performance telemetry only.
    self._v247_tick_ema_ms = 0.0
    self._v247_tick_peak_ms = 0.0
    self._v247_perf_mode = 'FULL'
    self._v247_last_perf_adjust = 0.0
    self._v247_last_gc_hint = time.time()

    # Baselines. These are presentation-only values.
    self._v247_base_bookmap_panel_interval = max(
        float(getattr(self, 'bookmap_panel_interval', 0.55)), 0.60
    )
    self._v247_base_heatmap_interval = max(
        float(getattr(self, 'bookmap_heatmap_interval', 1.10)), 1.10
    )
    self._v247_base_heatmap_draw_interval = max(
        float(getattr(self, 'bookmap_heatmap_draw_interval', 1.35)), 1.35
    )
    self._v247_base_live_draw_interval = max(
        float(getattr(self, 'live_draw_interval', 0.18)), 0.18
    )

    # Keep the app from doing inactive web-state work in normal desktop mode.
    if not bool(getattr(self, 'web_only_mode', False)):
        try:
            self.web_state_interval = 30.0
            self.web_full_chart_interval = 30.0
        except Exception:
            pass

    try:
        self.root.title(
            'BOOKMAP KING V21.47 — ULTRA SMOOTH DESKTOP / V21.45 BRAIN'
        )
    except Exception:
        pass


def _v247_apply_perf_mode(self, mode):
    """
    Dynamic presentation governor.
    Never changes:
      brain_update_interval
      bookmap_whale_calc_interval
      bookmap_wave_calc_interval
      bookmap_warmup_interval
      decision/lock logic
    """
    mode = str(mode or 'FULL').upper()

    if mode == 'FULL':
        panel = self._v247_base_bookmap_panel_interval
        heat = self._v247_base_heatmap_interval
        heat_draw = self._v247_base_heatmap_draw_interval
        live_draw = self._v247_base_live_draw_interval
    elif mode == 'BALANCED':
        panel = max(self._v247_base_bookmap_panel_interval, 0.78)
        heat = max(self._v247_base_heatmap_interval, 1.45)
        heat_draw = max(self._v247_base_heatmap_draw_interval, 1.75)
        live_draw = max(self._v247_base_live_draw_interval, 0.23)
    else:  # PROTECT
        panel = max(self._v247_base_bookmap_panel_interval, 1.00)
        heat = max(self._v247_base_heatmap_interval, 1.85)
        heat_draw = max(self._v247_base_heatmap_draw_interval, 2.25)
        live_draw = max(self._v247_base_live_draw_interval, 0.28)

    self.bookmap_panel_interval = panel
    self.bookmap_heatmap_interval = heat
    self.bookmap_heatmap_draw_interval = heat_draw
    self.live_draw_interval = live_draw
    self._v247_perf_mode = mode


def _v247_ui_tick(self):
    started = time.perf_counter()
    try:
        return _V247_BASE_UI_TICK(self)
    finally:
        elapsed_ms = (time.perf_counter() - started) * 1000.0

        prev = float(getattr(self, '_v247_tick_ema_ms', 0.0) or 0.0)
        ema = elapsed_ms if prev <= 0 else (prev * 0.92 + elapsed_ms * 0.08)
        self._v247_tick_ema_ms = ema
        self._v247_tick_peak_ms = max(
            elapsed_ms,
            float(getattr(self, '_v247_tick_peak_ms', 0.0) or 0.0) * 0.995
        )

        now = time.time()
        last_adj = float(getattr(self, '_v247_last_perf_adjust', 0.0) or 0.0)

        # Do not flap modes; require 2.5 seconds between changes.
        if now - last_adj >= 2.5:
            current = str(getattr(self, '_v247_perf_mode', 'FULL'))

            # ~65ms UI heartbeat means a 25ms+ tick is already expensive.
            if ema >= 32.0:
                wanted = 'PROTECT'
            elif ema >= 20.0:
                wanted = 'BALANCED'
            elif ema <= 11.0:
                wanted = 'FULL'
            else:
                wanted = current

            if wanted != current:
                self._v247_apply_perf_mode(wanted)
                self._v247_last_perf_adjust = now

        # Tiny gen0-only GC hint every ~45s. Avoid full-generation pauses.
        if now - float(getattr(self, '_v247_last_gc_hint', now)) >= 45.0:
            self._v247_last_gc_hint = now
            try:
                _v247_gc.collect(0)
            except Exception:
                pass


ChartKingPro.__init__ = _v247_init
ChartKingPro._ui_tick = _v247_ui_tick


# ---------------------------------------------------------------------------
# Tk variable setter accelerator for PROGRAMMATIC status variables only.
# Instead of globally monkey-patching Tk variables (unsafe for user-editable
# inputs), provide a cache helper used by performance status updates.
# ---------------------------------------------------------------------------
def _v247_set_if_changed(var, value):
    try:
        value = str(value)
        if var.get() != value:
            var.set(value)
    except Exception:
        try:
            var.set(value)
        except Exception:
            pass


