# ============================================================================
# BOOKMAP KING V21.50 — BREAKOUT PERSISTENCE + FAST-RECLAIM INTELLIGENCE
#
# Purpose:
# A breakout event and a breakout that is likely to PERSIST are not the same.
#
# This layer does NOT submit real-money orders.
# It classifies the threat for the existing signal/paper system:
#
#   FAKEOUT / FAST RECLAIM
#   DIP RECOVERY WATCH
#   CONTESTED BREAK
#   PERSISTENCE BUILDING
#   PERSISTENT BREAKOUT
#
# Core concept:
#   Momentum starts the move.
#   Structure + retest + persistence decide whether the move earned respect.
#
# Uses existing data only; no new network feed and no high-rate background loop.
# ============================================================================

_V250_BASE_INIT = ChartKingPro.__init__
_V250_BASE_FILTER_TREND = _v244_filter_trend_state
_V250_BASE_SURVIVAL_STABLE = _v244_stabilize_survival
_V250_BASE_REV_PANEL = ChartKingPro._update_reversal_panel
_V250_BASE_SURV_PANEL = ChartKingPro._update_flip_survival_panel


def _v250_clip(v, lo=0.0, hi=100.0):
    try:
        return max(lo, min(hi, float(v)))
    except Exception:
        return lo


def _v250_side(v):
    v = str(v or 'WAIT').upper()
    return v if v in ('UP', 'DOWN') else 'WAIT'


def _v250_breakout_persistence_read(self, trend_state=None, now=None):
    """
    Separate "did it break?" from "did the break earn continuation?"

    Persistence evidence:
      • amount/time held beyond original defended lock
      • 1m + 5m structure agreement
      • 5m gets more weight than 1m
      • existing Team Breakout family breadth
      • Kalshi/order-book persistence
      • native Bookmap whale/chart fusion
      • order-block + contextual-doji structure
      • raw breakout confirmation

    Recovery evidence:
      • quick reclaim of the original defended level
      • 1m returning first while 5m never rotated
      • 5m remaining with original thesis
      • order-book persistence returning to defense
      • Bookmap fusion returning to defense
      • supportive order-block / rejection context

    This is an advisory classifier, not an execution engine.
    """
    now = float(now or time.time())
    raw = dict(trend_state or {})
    bucket = int(now // 900) * 900

    state = dict(getattr(self, '_v250_break_state', {}) or {})
    if int(state.get('bucket', -1) or -1) != bucket:
        state = {
            'bucket': bucket,
            'attack_side': 'WAIT',
            'attack_started': 0.0,
            'beyond_started': 0.0,
            'reclaim_ts': 0.0,
            'max_beyond': 0.0,
            'persist_ema': 0.0,
            'recover_ema': 0.0,
            'class': 'CALM',
            'class_samples': 0,
            'last_live': None,
        }

    defended = _v242_original_defense(self, now=now)
    if defended not in ('UP', 'DOWN'):
        out = {
            'ready': False,
            'class': 'LOCK BUILDING',
            'persistence': 0.0,
            'recovery': 0.0,
            'attack_side': 'WAIT',
            'defended_side': 'WAIT',
            'detail': 'Waiting for original Bookmap lock before judging breakout persistence.',
            'reclaimed': False,
            'held_seconds': 0.0,
        }
        self._v250_break_state = state
        self._v250_break_last = out
        return out

    attack = 'DOWN' if defended == 'UP' else 'UP'
    flip_to = _v250_side(raw.get('flip_to'))
    team = dict(raw.get('team_breakout') or {})
    team_score = _v250_clip(team.get('score', 0.0))
    team_fams = int(team.get('families', 0) or 0)
    team_stage = str(team.get('stage', 'NONE') or 'NONE').upper()
    raw_status = str(raw.get('status', 'HEALTHY') or 'HEALTHY').upper()
    raw_risk = _v250_clip(raw.get('raw_risk', raw.get('risk', 0.0)))
    lock_breakout = dict(raw.get('lock_breakout') or {})
    attack_score = _v250_clip(lock_breakout.get('score', 0.0))
    attack_groups = int(lock_breakout.get('categories', 0) or 0)
    attack_confirmed = bool(lock_breakout.get('confirmed', False))

    # Live / original lock anchor.
    try:
        live = float(self.effective_live_price()[0])
    except Exception:
        live = None

    lock = self._sticky_survival_lock_snapshot() or {}
    try:
        anchor = float(lock.get('lock_price'))
    except Exception:
        anchor = None

    # ATR-sized normalization for excursion.
    atr = 25.0
    try:
        candles = list(getattr(self, '_last_analysis_candles', None) or [])
        if candles:
            recent = candles[-12:]
            ranges = [
                max(1.0, float(c.get('high', 0.0)) - float(c.get('low', 0.0)))
                for c in recent
            ]
            atr = max(12.0, sum(ranges) / max(1, len(ranges)))
    except Exception:
        pass

    beyond = 0.0
    reclaimed = False
    if live is not None and anchor is not None:
        if attack == 'DOWN':
            beyond = max(0.0, anchor - live)
            reclaimed = live >= anchor
        else:
            beyond = max(0.0, live - anchor)
            reclaimed = live <= anchor
    beyond_atr = beyond / max(atr, 1.0)

    active_attack = (
        flip_to == attack
        or attack_score >= 28.0
        or raw_risk >= 48.0
        or raw_status in ('WATCH', 'BREAKOUT CONFIRMED')
    )

    if active_attack:
        if state.get('attack_side') != attack:
            state['attack_side'] = attack
            state['attack_started'] = now
            state['beyond_started'] = now if beyond > 0 else 0.0
            state['reclaim_ts'] = 0.0
            state['max_beyond'] = beyond_atr
        else:
            state['max_beyond'] = max(
                float(state.get('max_beyond', 0.0) or 0.0),
                beyond_atr
            )
            if beyond > 0 and not float(state.get('beyond_started', 0.0) or 0.0):
                state['beyond_started'] = now
    else:
        # Keep recent attack history briefly so a fast reclaim can be recognized.
        attack_age = now - float(state.get('attack_started', 0.0) or 0.0)
        if attack_age > 7.0:
            state['attack_side'] = 'WAIT'
            state['attack_started'] = 0.0
            state['beyond_started'] = 0.0
            state['max_beyond'] = 0.0

    attack_age = (
        now - float(state.get('attack_started', 0.0) or 0.0)
        if float(state.get('attack_started', 0.0) or 0.0) else 0.0
    )
    held_seconds = (
        now - float(state.get('beyond_started', 0.0) or 0.0)
        if beyond > 0 and float(state.get('beyond_started', 0.0) or 0.0)
        else 0.0
    )

    if reclaimed and float(state.get('attack_started', 0.0) or 0.0):
        if not float(state.get('reclaim_ts', 0.0) or 0.0):
            state['reclaim_ts'] = now
    elif beyond > 0:
        state['reclaim_ts'] = 0.0

    # 1m/5m: 5m = context; 1m = immediate action.
    try:
        micro = self._micro_timeframe_read() or {}
    except Exception:
        micro = {}
    one = _v250_side((micro.get('one') or {}).get('direction'))
    five = _v250_side((micro.get('five') or {}).get('direction'))

    # Existing order-book persistence.
    try:
        bookp = self._orderbook_persistence_read() or {}
    except Exception:
        bookp = {}
    book_dir = _v250_side(bookp.get('direction'))
    book_cons = float(bookp.get('consistency', 0.0) or 0.0)

    # Existing native Bookmap whale + chart fusion.
    try:
        whale = self._bookmap_whale_read() or {}
    except Exception:
        whale = {}
    try:
        fusion = self._bookmap_chart_fusion(
            getattr(self, 'last_signal', None) or {},
            getattr(self, '_last_analysis_candles', None) or [],
            whale=whale
        ) or {}
    except Exception:
        fusion = {}
    fusion_dir = _v250_side(fusion.get('direction'))
    fusion_state = str(fusion.get('state', 'MIXED') or 'MIXED').upper()
    whale_like = _v250_clip(whale.get('likelihood', 0.0))

    # Order-block + contextual-doji structure.
    try:
        ctx = _v242_structure_context(self, now=now, live=live) or {}
    except Exception:
        ctx = {}
    signed_up = float(ctx.get('signed_up', 0.0) or 0.0)
    attack_sign = 1.0 if attack == 'UP' else -1.0
    defend_sign = 1.0 if defended == 'UP' else -1.0
    attack_struct = signed_up * attack_sign
    defend_struct = signed_up * defend_sign

    persist = 0.0
    recover = 0.0
    preasons = []
    rreasons = []

    # 1) TIME + EXCURSION: real breaks have to live outside.
    if beyond_atr >= 0.22:
        persist += 18.0
        preasons.append(f'{beyond_atr:.2f} ATR beyond lock')
    elif beyond_atr >= 0.10:
        persist += 11.0
    elif beyond_atr >= 0.04:
        persist += 5.0

    if held_seconds >= 3.0:
        persist += 18.0
        preasons.append(f'held beyond {held_seconds:.1f}s')
    elif held_seconds >= 1.5:
        persist += 11.0
        preasons.append(f'holding {held_seconds:.1f}s')
    elif held_seconds >= 0.7:
        persist += 5.0

    # A very quick reclaim is direct evidence against persistence.
    if reclaimed and 0.0 < attack_age <= 3.0:
        recover += 30.0
        persist -= 18.0
        rreasons.append(f'FAST RECLAIM in {attack_age:.1f}s')
    elif reclaimed and 0.0 < attack_age <= 5.5:
        recover += 20.0
        persist -= 10.0
        rreasons.append(f'reclaimed defended level in {attack_age:.1f}s')

    # 2) 5m context > 1m reaction.
    if five == attack:
        persist += 20.0
        preasons.append(f'5m structure {attack}')
    elif five == defended:
        recover += 22.0
        persist -= 8.0
        rreasons.append(f'5m still {defended}')

    if one == attack:
        persist += 9.0
    elif one == defended:
        recover += 12.0
        rreasons.append(f'1m reaction back {defended}')

    if one == attack and five == attack:
        persist += 8.0
        preasons.append('1m+5m attack aligned')
    elif one == defended and five == defended:
        recover += 8.0
        rreasons.append('1m+5m defense aligned')
    elif one == defended and five == attack:
        # Classic retest / contested break: 1m bounced but 5m has rotated.
        recover += 4.0
        persist += 5.0

    # 3) Existing multi-family breakout authority.
    if attack_groups >= 4 and attack_score >= 72.0:
        persist += 15.0
        preasons.append(f'{attack_groups} breakout groups')
    elif attack_groups >= 3 and attack_score >= 58.0:
        persist += 10.0
    elif attack_groups >= 2 and attack_score >= 42.0:
        persist += 5.0

    if team_fams >= 4 and team_score >= 76.0:
        persist += 12.0
        preasons.append(f'team breakout {team_fams} fam/{team_score:.0f}')
    elif team_fams >= 3 and team_score >= 64.0:
        persist += 7.0

    if team_stage == 'CONFIRMED':
        persist += 7.0
    elif team_stage == 'FORMING':
        recover += 2.0

    # 4) Order-book persistence.
    if book_dir == attack and book_cons >= 0.70:
        persist += 14.0
        preasons.append(f'book persists {attack} {book_cons:.0%}')
    elif book_dir == attack and book_cons >= 0.58:
        persist += 8.0
    elif book_dir == defended and book_cons >= 0.66:
        recover += 14.0
        rreasons.append(f'book returned {defended} {book_cons:.0%}')
    elif book_dir == defended and book_cons >= 0.56:
        recover += 8.0

    # 5) Bookmap whale + chart fusion.
    if fusion_dir == attack:
        if fusion_state == 'ALIGNED' and whale_like >= 70.0:
            persist += 15.0
            preasons.append(f'Bookmap fusion {attack}/{whale_like:.0f}')
        elif fusion_state in ('ALIGNED', 'LEAN ALIGNED') and whale_like >= 58.0:
            persist += 8.0
    elif fusion_dir == defended:
        if fusion_state == 'ALIGNED' and whale_like >= 66.0:
            recover += 13.0
            rreasons.append(f'Bookmap reclaimed {defended}/{whale_like:.0f}')
        elif whale_like >= 56.0:
            recover += 7.0

    # 6) Structural reaction at order blocks / contextual doji.
    if attack_struct >= 0.34:
        persist += 11.0
        preasons.append('OB/doji structure supports break')
    elif defend_struct >= 0.34:
        recover += 13.0
        rreasons.append('OB/doji structure supports recovery')

    if bool(ctx.get('inside_order_block')):
        if defend_struct >= 0.20:
            recover += 5.0
        elif attack_struct >= 0.20:
            persist += 5.0

    # 7) Raw confirmed event matters, but cannot decide persistence alone.
    if attack_confirmed or raw_status == 'BREAKOUT CONFIRMED':
        persist += 8.0
    if raw_risk >= 88.0:
        persist += 6.0

    persist = _v250_clip(persist)
    recover = _v250_clip(recover)

    # EMA prevents a single snapshot from flipping the new classifier.
    prev_p = float(state.get('persist_ema', persist) or persist)
    prev_r = float(state.get('recover_ema', recover) or recover)
    p_alpha = 0.46 if persist > prev_p else 0.34
    r_alpha = 0.50 if recover > prev_r else 0.36
    p_ema = prev_p + (persist - prev_p) * p_alpha
    r_ema = prev_r + (recover - prev_r) * r_alpha
    state['persist_ema'] = _v250_clip(p_ema)
    state['recover_ema'] = _v250_clip(r_ema)

    p = state['persist_ema']
    r = state['recover_ema']

    # Classification candidates.
    # "Persistent" specifically needs time/structure, not score alone.
    persistent_ready = (
        p >= 72.0
        and r <= 44.0
        and (
            held_seconds >= 1.5
            or five == attack
            or (book_dir == attack and book_cons >= 0.66)
        )
        and (
            attack_groups >= 3
            or (one == attack and five == attack)
            or (fusion_dir == attack and whale_like >= 66.0)
        )
    )

    fast_fakeout = (
        r >= 66.0
        and p <= 62.0
        and reclaimed
        and 0.0 < attack_age <= 4.0
    )

    dip_recovery = (
        r >= 56.0
        and p < 68.0
        and (
            reclaimed
            or five == defended
            or (book_dir == defended and book_cons >= 0.60)
        )
    )

    if persistent_ready:
        candidate = 'PERSISTENT BREAKOUT'
    elif fast_fakeout:
        candidate = 'FAKEOUT / FAST RECLAIM'
    elif dip_recovery:
        candidate = 'DIP RECOVERY WATCH'
    elif p >= 58.0 and p >= r + 10.0:
        candidate = 'PERSISTENCE BUILDING'
    elif max(p, r) >= 42.0:
        candidate = 'CONTESTED BREAK'
    else:
        candidate = 'CALM'

    # Class persistence: two consecutive observations, except fast reclaim
    # can announce immediately because the reclaim itself is the event.
    old_class = str(state.get('class', 'CALM') or 'CALM')
    if candidate == old_class:
        state['class_samples'] = int(state.get('class_samples', 0) or 0) + 1
    else:
        state['class_samples'] = 1

    if candidate == 'FAKEOUT / FAST RECLAIM':
        final_class = candidate
    elif int(state.get('class_samples', 0) or 0) >= 2:
        final_class = candidate
    else:
        final_class = old_class

    state['class'] = final_class
    state['last_live'] = live
    self._v250_break_state = state

    if final_class == 'PERSISTENT BREAKOUT':
        indication = 'BREAK HAS EARNED RESPECT'
    elif final_class == 'FAKEOUT / FAST RECLAIM':
        indication = 'RECOVERY-FAVORABLE SIGNAL'
    elif final_class == 'DIP RECOVERY WATCH':
        indication = 'RECOVERY SETUP FORMING'
    elif final_class == 'PERSISTENCE BUILDING':
        indication = 'DO NOT ASSUME RECOVERY YET'
    elif final_class == 'CONTESTED BREAK':
        indication = 'WAIT FOR RETEST / RECLAIM'
    else:
        indication = 'NO PERSISTENT BREAK THREAT'

    detail = (
        f'{final_class} • persistence {p:.0f}/100 • recovery {r:.0f}/100 • '
        f'{defended} defense vs {attack} attack'
    )
    if held_seconds > 0:
        detail += f' • outside {held_seconds:.1f}s'
    if preasons:
        detail += ' • PERSIST: ' + ', '.join(preasons[:4])
    if rreasons:
        detail += ' • RECOVER: ' + ', '.join(rreasons[:4])

    out = {
        'ready': True,
        'class': final_class,
        'persistence': p,
        'recovery': r,
        'attack_side': attack,
        'defended_side': defended,
        'detail': detail,
        'indication': indication,
        'reclaimed': reclaimed,
        'attack_age': attack_age,
        'held_seconds': held_seconds,
        'beyond_atr': beyond_atr,
        'one': one,
        'five': five,
        'book_direction': book_dir,
        'book_consistency': book_cons,
        'fusion_direction': fusion_dir,
        'whale_likelihood': whale_like,
    }
    self._v250_break_last = out
    return out


def _v250_filter_trend_state(self, trend_state=None, now=None):
    """
    V21.44 calm filter remains first authority.
    V21.50 then asks whether that threat is persisting or being reclaimed.
    """
    now = float(now or time.time())
    stable = dict(_V250_BASE_FILTER_TREND(self, trend_state=trend_state, now=now) or {})
    bp = _v250_breakout_persistence_read(self, stable, now=now)
    stable['persistence_read'] = bp

    if not bp.get('ready'):
        return stable

    cls = str(bp.get('class', 'CALM'))
    p = float(bp.get('persistence', 0.0) or 0.0)
    r = float(bp.get('recovery', 0.0) or 0.0)
    risk = float(stable.get('risk', 0.0) or 0.0)

    # A breakout detector may have fired, but a FAST RECLAIM must prevent
    # the visible risk segment from behaving like a lasting confirmed break.
    if cls == 'FAKEOUT / FAST RECLAIM':
        stable['status'] = 'WATCH'
        stable['risk'] = min(risk, max(38.0, 58.0 - r * 0.12))
        stable['breakout_persistence'] = 'FAILED / RECLAIMED'
    elif cls == 'DIP RECOVERY WATCH':
        if stable.get('status') == 'BREAKOUT CONFIRMED' and p < 62.0:
            stable['status'] = 'WATCH'
        stable['risk'] = min(float(stable.get('risk', risk)), 66.0)
        stable['breakout_persistence'] = 'RECOVERY FORMING'
    elif cls == 'PERSISTENT BREAKOUT':
        # Only persistence-qualified breaks own the hardest danger state.
        stable['status'] = 'BREAKOUT CONFIRMED'
        stable['risk'] = max(float(stable.get('risk', risk)), 86.0)
        stable['breakout_persistence'] = 'PERSISTENT'
    elif cls == 'PERSISTENCE BUILDING':
        stable['breakout_persistence'] = 'BUILDING'
    else:
        stable['breakout_persistence'] = cls

    stable['risk'] = _v250_clip(stable.get('risk', risk))

    detail = str(stable.get('detail', '') or '')
    stable['detail'] = (
        detail
        + f' • V21.50 {bp.get("class")} '
        + f'• persist {p:.0f}/100 vs recovery {r:.0f}/100 '
        + f'• {bp.get("indication","")}'
    ).strip(' •')
    return stable


def _v250_stabilize_survival(self, read=None, now=None):
    """
    Survival is now recovery-aware.

    Fake breakout / fast reclaim:
      survival is prevented from collapsing further and may recover promptly.

    Persistent breakout:
      survival may fall hard because continuation has been independently earned.
    """
    now = float(now or time.time())
    stable = dict(_V250_BASE_SURVIVAL_STABLE(self, read=read, now=now) or {})
    bp = dict(getattr(self, '_v250_break_last', {}) or {})

    if not bp.get('ready'):
        return stable

    cls = str(bp.get('class', 'CALM'))
    p = float(bp.get('persistence', 0.0) or 0.0)
    r = float(bp.get('recovery', 0.0) or 0.0)
    value = float(stable.get('value', 50.0) or 50.0)

    if cls == 'FAKEOUT / FAST RECLAIM':
        # Do not leave Survival buried because of a threat already reclaimed.
        target_floor = min(88.0, 58.0 + r * 0.34)
        value = max(value, target_floor)
        stable['label'] = 'FAST RECLAIM • RECOVERY'
    elif cls == 'DIP RECOVERY WATCH':
        target_floor = min(78.0, 48.0 + r * 0.28)
        value = max(value, target_floor)
        stable['label'] = 'RECOVERY WATCH'
    elif cls == 'PERSISTENT BREAKOUT':
        # Persistence-qualified threat may suppress Survival decisively.
        cap = max(8.0, 34.0 - max(0.0, p - 72.0) * 0.55)
        value = min(value, cap)
        stable['label'] = 'PERSISTENT BREAKOUT THREAT'
    elif cls == 'PERSISTENCE BUILDING' and p >= 62.0:
        value = min(value, 62.0)
        stable['label'] = 'BREAKOUT TRYING TO STICK'

    stable['value'] = _v250_clip(value)
    detail = str(stable.get('detail', '') or '')
    stable['detail'] = (
        detail
        + f' • PERSISTENCE {p:.0f} / RECOVERY {r:.0f}'
        + f' • {bp.get("class","CALM")}'
    ).strip(' •')
    return stable


def _v250_update_reversal_panel(self, d, lock_state=None, trend_state=None):
    """
    Show persistence/recovery classification in the EXISTING risk segment.
    No new continuously-redrawing widget is created (performance-safe).
    """
    stable = _v250_filter_trend_state(
        self, trend_state=trend_state, now=time.time()
    )
    result = _V250_BASE_REV_PANEL(
        self, d, lock_state=lock_state, trend_state=stable
    )

    bp = dict(stable.get('persistence_read') or getattr(self, '_v250_break_last', {}) or {})
    if bp.get('ready'):
        cls = str(bp.get('class', 'CALM'))
        p = float(bp.get('persistence', 0.0) or 0.0)
        r = float(bp.get('recovery', 0.0) or 0.0)

        self._set_var_if_changed(
            self.breakout_var,
            f'BREAKOUT QUALITY: {cls} • PERSIST {p:.0f}/100 • RECOVERY {r:.0f}/100'
        )

        # Use the main risk line to make the distinction obvious.
        risk = float(stable.get('risk', 0.0) or 0.0)
        if cls == 'PERSISTENT BREAKOUT':
            risk_label = 'PERSISTENT'
        elif cls == 'FAKEOUT / FAST RECLAIM':
            risk_label = 'RECLAIMED'
        elif cls == 'DIP RECOVERY WATCH':
            risk_label = 'RECOVERY WATCH'
        elif cls == 'PERSISTENCE BUILDING':
            risk_label = 'TRYING TO STICK'
        else:
            risk_label = cls

        self._set_var_if_changed(
            self.trend_reversal_risk_var,
            f'FLIP / BREAKOUT RISK {risk:.0f}/100 • {risk_label}'
        )

        self._set_var_if_changed(
            self.trend_reversal_detail_var,
            str(bp.get('detail', stable.get('detail', '')))
        )

    return result


def _v250_update_survival_panel(self, read):
    stable = _v250_stabilize_survival(self, read=read, now=time.time())
    return _V250_BASE_SURV_PANEL(self, stable)


def _v250_init(self, *args, **kwargs):
    self._v250_break_state = {}
    self._v250_break_last = {}
    _V250_BASE_INIT(self, *args, **kwargs)

    try:
        self.root.title(
            'BOOKMAP KING V21.50 — BREAKOUT PERSISTENCE + RECOVERY INTELLIGENCE'
        )
    except Exception:
        pass


