# ------------------------- UI destruction helpers ----------------------------

def _v251_text_of(widget):
    try:
        return str(widget.cget('text') or '')
    except Exception:
        return ''


def _v251_walk(parent):
    try:
        children = list(parent.winfo_children())
    except Exception:
        return
    for child in children:
        yield child
        yield from _v251_walk(child)


def _v251_destroy_newhedge_widgets(self):
    """
    Removes legacy NewHedge controls/labels if any older constructor created
    them before V21.51's final cleanup runs.
    """
    root = getattr(self, 'root', None)
    if root is None:
        return

    doomed = []
    for w in list(_v251_walk(root)):
        txt = _v251_text_of(w).upper()
        if 'NEWHEDGE' in txt or 'NEW HEDGE' in txt:
            doomed.append(w)

    # Destroy highest containers where possible, avoiding duplicate errors.
    for w in doomed:
        try:
            master = w.master
            # If this is a small dedicated frame/card, destroy that frame.
            if master is not None and master is not root:
                sibling_text = ' '.join(
                    _v251_text_of(x).upper()
                    for x in master.winfo_children()
                )
                if 'NEWHEDGE' in sibling_text or 'NEW HEDGE' in sibling_text:
                    master.destroy()
                    continue
            w.destroy()
        except Exception:
            pass


def _v251_remove_learning_center(self):
    """
    Destroy the entire Learning Center parent instead of individually hiding
    Gallery/Snapshot widgets. This reclaims the center-page vertical space.
    """
    candidates = [
        getattr(self, 'learning_gallery_label', None),
        getattr(self, 'learning_snapshot_canvas', None),
        getattr(self, 'learning_snapshot_title_label', None),
        getattr(self, 'learning_snapshot_body_label', None),
    ]
    for child in candidates:
        if child is None:
            continue
        try:
            parent = child.master
            if parent is not None and parent.winfo_exists():
                parent.destroy()
                break
        except Exception:
            pass

    # Remove the now-useless "LEARNING CENTER ↓" toolbar button.
    toolbar_parent = None
    try:
        for w in _v251_walk(self.root):
            if _v251_text_of(w).strip().upper().startswith('LEARNING CENTER'):
                try:
                    w.destroy()
                except Exception:
                    pass
    except Exception:
        pass


