# ============================================================================
# BOOKMAP KING V21.52 — SIMPLE EDGE / FULL DATA CEILING
#
# DESIGN CONTRACT
#   DATA LAYER: keep native Bookmap tape, whale, chart structure, target motion,
#               history, settlement journal, and breakout/recovery analytics.
#   DECISION LAYER: only four Bookmap families and three Team MM3 families may
#                   earn a call.  No stacked score may vote a second time.
#   PRICE LAYER: Kalshi odds decide fill/value only; they never choose UP/DOWN.
#   SAFETY: exact executable asks, one paper entry per bot/market, <= 70c,
#           live order submission remains disabled/preview-only.
#
# The original V21.51 file remains untouched.  This final patch replaces only
# active decision authority; it does not remove high-value collection feeds.
# ============================================================================

_V252_VERSION = 'V21.52 SIMPLE EDGE'
_V252_MAX_ENTRY = 0.70
_V252_BOOK_WEIGHTS = {
    'tape': 0.38,
    'whale': 0.22,
    'structure': 0.20,
    'target': 0.20,
}
_V252_MM_WEIGHTS = {
    'model': 0.46,
    'tape': 0.32,
    'context': 0.22,
}


def _v252_clip(value, lo=-1.0, hi=1.0):
    try:
        return max(float(lo), min(float(hi), float(value)))
    except Exception:
        return float(lo)


def _v252_side(value):
    value = str(value or 'WAIT').upper()
    return value if value in ('UP', 'DOWN') else 'WAIT'


def _v252_blend(items):
    """Availability-aware weighted blend used inside one evidence family."""
    live = [(float(v), float(w)) for v, w, ok in items if ok and float(w) > 0]
    if not live:
        return 0.0, False
    den = sum(w for _, w in live)
    return _v252_clip(sum(v * w for v, w in live) / max(den, 1e-9)), True


def _v252_scorecard(
    families,
    weights,
    threshold=0.26,
    support_threshold=0.14,
    oppose_threshold=0.20,
):
    """
    Collapse independent evidence families exactly once.

    A single extreme family cannot make a call: two available families must
    support the same side, and no more than one may materially oppose it.
    """
    usable = []
    for name, weight in weights.items():
        row = dict(families.get(name) or {})
        if not row.get('available'):
            continue
        usable.append((name, _v252_clip(row.get('score', 0.0)), float(weight)))

    if not usable:
        return {
            'side': 'WAIT', 'edge': 0.0, 'support': 0, 'oppose': 0,
            'available': 0, 'scores': {}, 'reason': 'no ready evidence families',
        }

    den = sum(weight for _, _, weight in usable)
    edge = _v252_clip(
        sum(score * weight for _, score, weight in usable) / max(den, 1e-9)
    )
    direction = 1.0 if edge > 0 else -1.0 if edge < 0 else 0.0
    support = sum(
        1 for _, score, _ in usable
        if score * direction >= float(support_threshold)
    ) if direction else 0
    oppose = sum(
        1 for _, score, _ in usable
        if score * direction <= -float(oppose_threshold)
    ) if direction else 0

    side = 'WAIT'
    if abs(edge) >= float(threshold) and support >= 2 and oppose <= 1:
        side = 'UP' if edge > 0 else 'DOWN'

    scores = {name: score for name, score, _ in usable}
    compact = ' '.join(f'{name[:3].upper()} {score:+.2f}' for name, score, _ in usable)
    return {
        'side': side,
        'edge': edge,
        'support': support,
        'oppose': oppose,
        'available': len(usable),
        'scores': scores,
        'reason': compact,
    }


def _v252_quote_gate(price, ceiling=_V252_MAX_ENTRY):
    """Pure price/value gate.  Direction is intentionally not an argument."""
    try:
        px = float(price)
    except Exception:
        return False, 'NO QUOTE'
    if not 0.0 < px < 1.0:
        return False, 'BAD QUOTE'
    if px > float(ceiling):
        return False, f'WAIT {px * 100:.1f}c > {float(ceiling) * 100:.0f}c'
    if px <= 0.20:
        grade = 'DEEP VALUE'
    elif px <= 0.40:
        grade = 'VALUE'
    elif px <= 0.55:
        grade = 'FAIR'
    else:
        grade = 'PATIENT'
    return True, f'{grade} {px * 100:.1f}c'


def _v252_data_ceiling(self, warm=None, now=None):
    """
    Preserve the data ceiling, but expose four non-overlapping decision groups.

      TAPE      aggressive fills + impulse + displayed depth
      WHALE     relative-size walls/MBO/absorption/whale memory
      STRUCTURE multi-timeframe candles + order-block/doji context
      TARGET    settlement geometry + causal Bookmap motion

    Kalshi contract odds are deliberately absent from this function.
    """
    now = float(now or time.time())
    if warm is None:
        try:
            warm = self._bookmap_fast_warmup_read(now=now)
        except Exception:
            warm = {}
    warm = dict(warm or {})
    wave = dict(warm.get('wave') or getattr(self, 'bookmap_wave_last', {}) or {})
    whale = dict(warm.get('whale') or getattr(self, 'bookmap_whale_last', {}) or {})

    # TAPE: use raw components, not warm['signed'], so whale is not counted twice.
    tape_score = _v252_clip(
        _v252_clip(wave.get('flow_2s', 0.0)) * 0.40
        + _v252_clip(wave.get('flow_6s', 0.0)) * 0.20
        + math.tanh(float(wave.get('move_2s_bp', 0.0) or 0.0) / 1.6) * 0.30
        + _v252_clip(wave.get('depth_imbalance', 0.0)) * 0.10
    )
    tape_ready = bool(wave.get('ready'))

    # WHALE: the existing detector already collapses walls, MBO, absorption,
    # spoof-like cancellations, and learned analog bias into one signed read.
    whale_score = _v252_clip(float(whale.get('signed_score', 0.0) or 0.0) / 100.0)
    whale_ready = bool(whale.get('ready'))

    try:
        structure = dict(_v242_structure_context(self, now=now) or {})
    except Exception:
        structure = {}
    try:
        candles = dict(_v232_candle_intelligence(self, now=now) or {})
    except Exception:
        candles = {}
    candle_ready = any(
        bool(row.get('ready')) for row in tuple(candles.get('timeframes') or ())
    )
    structure_score, structure_ready = _v252_blend((
        (float(candles.get('signed', 0.0) or 0.0), 0.62, candle_ready),
        (float(structure.get('signed_up', 0.0) or 0.0), 0.38,
         bool((structure.get('order_block') or {}).get('ready')
              or (structure.get('doji') or {}).get('ready'))),
    ))

    try:
        motion = dict(_v229_target_motion_snapshot(self, now=now) or {})
    except Exception:
        motion = {}
    live = motion.get('live', warm.get('live'))
    target = motion.get('target')
    if target is None:
        try:
            target = self.effective_target()[0]
        except Exception:
            target = None

    target_ready = live is not None and target is not None
    target_distance = 0.0
    range_ref = 25.0
    if target_ready:
        live = float(live)
        target = float(target)
        target_distance = live - target
        try:
            if self.btc_15m:
                c = self.btc_15m[-1]
                range_ref = max(
                    25.0,
                    float(c.get('high', live)) - float(c.get('low', live)),
                    abs(live - float(c.get('open', live))),
                )
        except Exception:
            pass
    geometry = _v252_clip(target_distance / max(range_ref, 1.0))
    velocity = math.tanh(float(motion.get('velocity_3s', 0.0) or 0.0) / 5.0)
    target_score = _v252_clip(geometry * 0.68 + velocity * 0.32)

    families = {
        'tape': {'score': tape_score, 'available': tape_ready},
        'whale': {'score': whale_score, 'available': whale_ready},
        'structure': {'score': structure_score, 'available': structure_ready},
        'target': {'score': target_score, 'available': target_ready},
    }
    return {
        'families': families,
        'live': None if live is None else float(live),
        'target': None if target is None else float(target),
        'distance': target_distance,
        'motion': motion,
        'wave': wave,
        'whale': whale,
        'structure': structure,
        'candles': candles,
    }


def _v252_bookmap_open(self, warm, now=None):
    """Fast, stable four-family Open Lock.  V21.40 freezes the first earn."""
    now = float(now or time.time())
    bucket = _v240_bucket(now)
    state = dict(getattr(self, '_v252_book_state', {}) or {})
    if int(state.get('bucket', -1) or -1) != bucket:
        state = {
            'bucket': bucket, 'candidate': 'WAIT', 'samples': 0,
            'edge_ema': 0.0, 'flips': 0, 'last_eval': 0.0,
        }
        self._v252_bookmap_last = {}
        self.opening_lock_bucket = bucket
        self.opening_lock_snapshot = None
        self.opening_lock_candidate = None
        self.opening_lock_candidate_since = 0.0

    # Multiple inherited UI paths may ask for the lock in one frame.  Count the
    # market observation once, not once per caller.
    if now - float(state.get('last_eval', 0.0) or 0.0) < 0.12:
        return None

    data = _v252_data_ceiling(self, warm=warm, now=now)
    card = _v252_scorecard(data['families'], _V252_BOOK_WEIGHTS)
    if not bool(data['families']['tape'].get('available')):
        state['candidate'] = 'WAIT'
        state['samples'] = 0
        state['last_eval'] = now
        self._v252_book_state = state
        self.opening_lock_candidate = None
        self.opening_lock_candidate_since = 0.0
        self.opening_lock_var.set(
            'OPEN LOCK: BUILDING • waiting for fresh native Bookmap tape'
        )
        return None
    prior_ema = float(state.get('edge_ema', 0.0) or 0.0)
    edge = float(card.get('edge', 0.0) or 0.0)
    alpha = 0.36 if abs(edge) >= abs(prior_ema) else 0.24
    edge_ema = _v252_clip(prior_ema + (edge - prior_ema) * alpha)

    candidate = 'WAIT'
    if (
        abs(edge_ema) >= 0.26
        and int(card.get('support', 0)) >= 2
        and int(card.get('oppose', 0)) <= 1
    ):
        candidate = 'UP' if edge_ema > 0 else 'DOWN'

    old_candidate = _v252_side(state.get('candidate'))
    if candidate == 'WAIT':
        state['candidate'] = 'WAIT'
        state['samples'] = max(0, int(state.get('samples', 0) or 0) - 1)
    elif candidate != old_candidate:
        if old_candidate in ('UP', 'DOWN'):
            state['flips'] = int(state.get('flips', 0) or 0) + 1
        state['candidate'] = candidate
        state['samples'] = 1
    else:
        state['samples'] = int(state.get('samples', 0) or 0) + 1

    state['edge_ema'] = edge_ema
    state['last_eval'] = now
    self._v252_book_state = state
    self.opening_lock_candidate = candidate if candidate in ('UP', 'DOWN') else None
    self.opening_lock_candidate_since = now if candidate in ('UP', 'DOWN') else 0.0

    needed = 4 if abs(edge_ema) >= 0.48 and int(card.get('support', 0)) >= 3 else 7
    needed += min(4, int(state.get('flips', 0) or 0))
    last = {
        **card,
        'edge_ema': edge_ema,
        'candidate': candidate,
        'samples': int(state.get('samples', 0) or 0),
        'needed': needed,
        'families': data['families'],
        'live': data.get('live'),
        'target': data.get('target'),
        'distance': data.get('distance', 0.0),
        'data': data,
    }
    self._v252_bookmap_last = last

    if candidate == 'WAIT':
        self.opening_lock_var.set(
            f'OPEN LOCK: BUILDING • SIMPLE EDGE {edge_ema:+.2f} • '
            f'{card.get("support", 0)} support / {card.get("oppose", 0)} oppose • '
            f'{card.get("reason", "")}'
        )
        return None

    if int(state.get('samples', 0) or 0) < needed:
        self.opening_lock_var.set(
            f'OPEN LOCK: FORMULATING {candidate} • '
            f'{int(state.get("samples", 0))}/{needed} clean observations • '
            f'edge {edge_ema:+.2f} • {card.get("reason", "")}'
        )
        return None

    live = data.get('live')
    if live is None:
        return None
    grade = 'STRAIGHT' if needed <= 4 else 'LEAN'
    snap = {
        'time': now,
        'price': float(live),
        'lock_side': candidate,
        'lock_remaining': 'OPEN',
        'lock_minute': 0,
        'forecast_score': edge_ema * 10.0,
        'forecast_threshold': 2.6,
        'forecast_reasons': (
            f'V21.52 {grade} • {card.get("reason", "")} • '
            f'{card.get("support", 0)} independent families agree'
        ),
        'source': 'BOOKMAP OPEN/NOW • V21.52 SIMPLE EDGE',
    }
    self.opening_lock_snapshot = dict(snap)
    self.opening_lock_candidate = None
    self.opening_lock_candidate_since = 0.0
    self.opening_lock_var.set(
        f'OPEN LOCK: {candidate} LOCKED @ {money(live)} • V21.52 {grade} • '
        f'edge {edge_ema:+.2f} • {card.get("support", 0)} families'
    )
    self._v252_bookmap_frozen = dict(last)
    try:
        self._checkpoint_status_summary()
    except Exception:
        pass
    return snap


def _v252_mm3_lock(self, mm, now=None):
    """
    Team MM3 reduced to three authorities: model, Bookmap tape, and context.

    The first earned Team MM3 lock stays fixed for the 15-minute market.  Later
    opposite pressure is a guardian warning, not a silent rewrite of the call.
    """
    now = float(now or time.time())
    bucket = _v228_bucket(now)
    state = dict(getattr(self, '_v228_mm_lock_state', {}) or {})
    if int(state.get('bucket', -1) or -1) != bucket:
        state = _v228_reset_lock_state(state, bucket)
        state['candidate_samples'] = 0
        self._v252_mm_last = {}
        self._v252_mm_frozen = {}

    if (
        int(getattr(self, '_v252_mm_output_bucket', -1) or -1) == bucket
        and now - float(getattr(self, '_v252_mm_last_eval', 0.0) or 0.0) < 0.18
    ):
        cached = dict(getattr(self, '_v252_mm_output', {}) or {})
        if cached:
            return cached

    raw = dict(mm or {})
    settle = _v252_side(raw.get('settlement_side'))
    committed = _v252_side(raw.get('committed_side', settle))
    score = float(raw.get('settlement_score', raw.get('score', 0.0)) or 0.0)
    conv = int(raw.get('settlement_convergence', 0) or 0)
    fam = int(raw.get('family_count', 0) or 0)
    sign = 1.0 if settle == 'UP' else -1.0 if settle == 'DOWN' else 0.0

    # Convergence/family breadth calibrates the single MODEL family.  It does
    # not become another vote later in the chain.
    breadth = min(1.0, 0.70 + min(3, conv) * 0.08 + min(4, fam) * 0.035)
    model_score = sign * _v252_clip((score - 50.0) / 38.0, 0.0, 1.0) * breadth
    model_ready = settle in ('UP', 'DOWN') and score >= 50.0

    data = _v252_data_ceiling(self, warm=None, now=now)
    df = data['families']
    tape_score, tape_ready = _v252_blend((
        (df['tape']['score'], 0.66, df['tape']['available']),
        (df['whale']['score'], 0.34, df['whale']['available']),
    ))
    context_score, context_ready = _v252_blend((
        (df['structure']['score'], 0.56, df['structure']['available']),
        (df['target']['score'], 0.44, df['target']['available']),
    ))
    families = {
        'model': {'score': model_score, 'available': model_ready},
        'tape': {'score': tape_score, 'available': tape_ready},
        'context': {'score': context_score, 'available': context_ready},
    }
    card = _v252_scorecard(
        families,
        _V252_MM_WEIGHTS,
        threshold=0.24,
        support_threshold=0.12,
        oppose_threshold=0.22,
    )

    locked = _v252_side(state.get('locked'))
    candidate = 'WAIT'
    if (
        settle in ('UP', 'DOWN')
        and committed in (settle, 'WAIT')
        and score >= 68.0
        and card.get('side') == settle
        and int(card.get('support', 0)) >= 2
    ):
        candidate = settle

    if locked == 'WAIT':
        old_candidate = _v252_side(state.get('candidate'))
        if candidate == 'WAIT':
            state['candidate'] = 'WAIT'
            state['candidate_samples'] = 0
        elif candidate != old_candidate:
            state['candidate'] = candidate
            state['candidate_samples'] = 1
        else:
            state['candidate_samples'] = int(state.get('candidate_samples', 0) or 0) + 1

        strong = (
            score >= 85.0
            and abs(float(card.get('edge', 0.0))) >= 0.42
            and int(card.get('support', 0)) >= 3
            and int(card.get('oppose', 0)) == 0
        )
        needed = 3 if strong else 5
        if candidate in ('UP', 'DOWN') and int(state.get('candidate_samples', 0)) >= needed:
            state['locked'] = candidate
            state['locked_ts'] = now
            state['candidate'] = 'WAIT'
            state['candidate_samples'] = 0
            state['last_reason'] = (
                f'model {score:.0f}/100 • simple edge {float(card.get("edge", 0)):+.2f} • '
                f'{card.get("support", 0)} of 3 families'
            )
            state['locked_grade'] = 'STRAIGHT' if strong else 'LEAN'
            state['locked_edge'] = float(card.get('edge', 0.0) or 0.0)
            state['locked_support'] = int(card.get('support', 0) or 0)
            locked = candidate
    else:
        # Deliberately immutable for the round.  Do not erase historical calls.
        state['candidate'] = 'WAIT'
        state['candidate_samples'] = 0
        state['flip_candidate'] = 'WAIT'
        state['flip_since'] = 0.0

    self._v228_mm_lock_state = state
    locked = _v252_side(state.get('locked'))
    grade = (
        'STRAIGHT'
        if abs(float(card.get('edge', 0.0))) >= 0.48
        and int(card.get('support', 0)) >= 3
        and int(card.get('oppose', 0)) == 0
        else 'LEAN'
        if candidate in ('UP', 'DOWN') or locked in ('UP', 'DOWN')
        else 'MIXED'
    )
    last = {
        **card,
        'grade': grade,
        'families': families,
        'model_side': settle,
        'model_score': score,
        'locked': locked,
        'data': data,
    }
    self._v252_mm_last = last
    if locked in ('UP', 'DOWN') and not getattr(self, '_v252_mm_frozen', None):
        self._v252_mm_frozen = dict(last)

    if locked in ('UP', 'DOWN'):
        grade = str(state.get('locked_grade', grade) or grade)
        opposite = 'DOWN' if locked == 'UP' else 'UP'
        pressure = (
            card.get('side') == opposite
            and abs(float(card.get('edge', 0.0))) >= 0.34
        )
        text = (
            f'TEAM MM3 LOCK: {locked} LOCKED • V21.52 {grade} • '
            f'FIRST CALL FROZEN • model {score:.0f} • edge {float(card.get("edge", 0)):+.2f}'
        )
        if pressure:
            text += f' • OPPOSITE {opposite} PRESSURE WATCH'
    elif candidate in ('UP', 'DOWN'):
        strong = (
            score >= 85.0
            and abs(float(card.get('edge', 0.0))) >= 0.42
            and int(card.get('support', 0)) >= 3
            and int(card.get('oppose', 0)) == 0
        )
        needed = 3 if strong else 5
        text = (
            f'TEAM MM3 LOCK: FORMULATING {candidate} • '
            f'{int(state.get("candidate_samples", 0))}/{needed} observations • '
            f'model {score:.0f} • {card.get("reason", "")}'
        )
    else:
        text = (
            f'TEAM MM3 LOCK: UNLOCKED • SIMPLE 3-FAMILY READ • '
            f'model {settle} {score:.0f} • edge {float(card.get("edge", 0)):+.2f} • '
            f'{card.get("support", 0)} support / {card.get("oppose", 0)} oppose'
        )

    try:
        self.v233_mm3_grade_var.set(
            f'TEAM MM3 QUALITY: V21.52 {grade} • MODEL / TAPE / CONTEXT • '
            f'{card.get("reason", "")}'
        )
    except Exception:
        pass

    out = {'side': locked, 'text': text, 'state': state}
    self._v252_mm_last_eval = now
    self._v252_mm_output_bucket = bucket
    self._v252_mm_output = dict(out)
    return out


def _v252_deep_payload(self, snapshot, side, now=None):
    """Compatibility payload for the honest paper journal; not an authority."""
    now = float(now or time.time())
    snap = dict(snapshot or {})
    data = dict(snap.get('data') or {})
    fams = dict(snap.get('families') or {})
    motion = dict(data.get('motion') or {})
    side = _v252_side(side)
    sign = 1.0 if side == 'UP' else -1.0 if side == 'DOWN' else 0.0

    # Preserve the historical feature schema for learning/settlement research,
    # while keeping learned weights out of the live call decision.
    if 'model' not in fams:
        tape = float(fams['tape'].get('score', 0.0) or 0.0)
        structure = float((fams.get('structure') or {}).get('score', 0.0) or 0.0)
        target_score = float((fams.get('target') or {}).get('score', 0.0) or 0.0)
        mm_signed = 0.0
    else:
        tape = float((fams.get('tape') or {}).get('score', 0.0) or 0.0)
        structure = float((fams.get('context') or {}).get('score', 0.0) or 0.0)
        target_score = structure
        mm_signed = float((fams.get('model') or {}).get('score', 0.0) or 0.0)

    live = data.get('live')
    target = data.get('target')
    cushion = 0.0 if live is None or target is None else float(live) - float(target)
    features = {
        'bias': 1.0,
        'candle': _v252_clip(structure),
        'flow': _v252_clip(tape),
        'cushion': _v252_clip(target_score),
        'motion1': _v252_clip(float(motion.get('velocity_1s', 0.0) or 0.0) / 10.0),
        'motion3': _v252_clip(float(motion.get('velocity_3s', 0.0) or 0.0) / 7.0),
        'mm3': _v252_clip(mm_signed),
        'newhedge': 0.0,
        'breakout': 0.0,
        '_live': live,
        '_target': target,
        '_cushion_raw': cushion,
    }
    try:
        bp = dict(getattr(self, '_v250_break_last', {}) or {})
        attack = _v252_side(bp.get('attack_side'))
        if attack in ('UP', 'DOWN'):
            attack_sign = 1.0 if attack == 'UP' else -1.0
            features['breakout'] = _v252_clip(
                attack_sign * float(bp.get('persistence', 0.0) or 0.0) / 100.0
            )
    except Exception:
        pass

    edge = float(snap.get('edge_ema', snap.get('edge', 0.0)) or 0.0)
    recross = _v252_clip(
        50.0 - sign * target_score * 24.0 - sign * tape * 18.0,
        0.0,
        100.0,
    )
    grade = (
        'V21.52 STRAIGHT'
        if abs(edge) >= 0.48 and int(snap.get('support', 0)) >= 3
        else 'V21.52 LEAN'
    )
    return {
        'side': side,
        'signed': edge,
        'features': features,
        'analog': {'ready': False, 'rate': None, 'n': 0, 'similarity': 0.0},
        'recross_risk': recross,
        'align': int(snap.get('support', 0)),
        'oppose': int(snap.get('oppose', 0)),
        'grade': grade,
    }


def _v233_paper_lock(self, bot, now=None):
    """Paper follows only the two frozen V21.52 locks."""
    now = float(now or time.time())
    name = str(bot or '').upper()
    if name == 'BOOKMAP KING':
        snap = dict(getattr(self, 'opening_lock_snapshot', None) or {})
        side = _v252_side(snap.get('lock_side'))
        if side == 'WAIT':
            return {'ready': False, 'side': 'WAIT', 'reason': 'Open Lock not earned'}
        read = dict(
            getattr(self, '_v252_bookmap_frozen', {})
            or getattr(self, '_v252_bookmap_last', {})
            or {}
        )
    else:
        state = dict(getattr(self, '_v228_mm_lock_state', {}) or {})
        side = _v252_side(state.get('locked'))
        if side == 'WAIT':
            return {'ready': False, 'side': 'WAIT', 'reason': 'TEAM MM3 lock not earned'}
        read = dict(
            getattr(self, '_v252_mm_frozen', {})
            or getattr(self, '_v252_mm_last', {})
            or {}
        )

    deep = _v252_deep_payload(self, read, side, now=now)
    return {
        'ready': True,
        'side': side,
        'grade': deep.get('grade'),
        'deep': deep,
        'strategy': _V252_VERSION,
    }


def _v233_open_accuracy_paper(self, bot, lock, now=None):
    """
    Honest paper fill: two fresh executable asks and a 70c cap for BOTH bots.
    No midpoint, synthetic fill, capped pretend fill, or odds-based direction.
    """
    now = float(now or time.time())
    bucket = _v233_bucket(now)
    try:
        with self.stockpile_db_lock:
            with self._stockpile_connect() as conn:
                row = conn.execute(
                    'SELECT id,status FROM v233_accuracy_trades WHERE bot=? AND bucket=?',
                    (bot, bucket),
                ).fetchone()
        if row:
            return False
    except Exception:
        return False

    side = _v252_side((lock or {}).get('side'))
    if side == 'WAIT':
        return False
    quote1 = _v233_exact_ask(self, side)
    quote2 = _v233_exact_ask(self, side)
    if quote1 is None or quote2 is None:
        return False
    allowed, value_grade = _v252_quote_gate(quote2.get('contract'))
    if not allowed:
        try:
            self._v249_mm3_late_skip_px = float(quote2.get('contract'))
            self._v249_mm3_late_skip_ts = now
            self.paper_status_var.set(
                f'{bot} VALUE WAIT • {side} exact ask • {value_grade} • hard cap 70c'
            )
        except Exception:
            pass
        return False

    try:
        stake = float(self._paper_parse_stake() or 10.0)
    except Exception:
        stake = 10.0
    stake = max(0.01, stake)
    px = float(quote2['contract'])
    contracts = stake / max(px, 0.01)
    deep = dict((lock or {}).get('deep') or {})
    features = dict(deep.get('features') or {})
    live = features.get('_live')
    target = features.get('_target')
    if live is None or target is None:
        return False

    try:
        with self.stockpile_db_lock:
            with self._stockpile_connect() as conn:
                conn.execute(
                    '''
                    INSERT INTO v233_accuracy_trades(
                        status,bot,bucket,ticker,side,lock_grade,
                        entry_ts,entry_btc,target,cushion,entry_contract,entry_yes,
                        quote_source,quote_age,stake,contracts,deep_score,
                        guardian_winrate,guardian_n,recross_risk,features_json
                    ) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)
                    ''',
                    (
                        'OPEN', bot, bucket, _v221_current_ticker(self), side,
                        f'{lock.get("grade", "V21.52")} • {value_grade}',
                        now, float(live), float(target), float(live) - float(target),
                        px, float(quote2['yes']), str(quote2['source']),
                        float(quote2['age']), stake, contracts,
                        float(deep.get('signed', 0.0) or 0.0), None, 0,
                        float(deep.get('recross_risk', 50.0) or 50.0),
                        json.dumps({
                            name: float(features.get(name, 0.0) or 0.0)
                            for name in _V233_FEATURE_NAMES
                        }),
                    ),
                )
        return True
    except Exception:
        return False


def _v233_guardian_tick(self):
    """One compact guardian: thesis health, entry value, and flip watch."""
    try:
        now = time.time()
        snap = dict(getattr(self, 'opening_lock_snapshot', None) or {})
        side = _v252_side(snap.get('lock_side'))
        read = dict(getattr(self, '_v252_bookmap_last', {}) or {})
        edge = float(read.get('edge_ema', read.get('edge', 0.0)) or 0.0)
        bp = dict(getattr(self, '_v250_break_last', {}) or {})
        break_class = str(bp.get('class', 'CALM') or 'CALM')

        if side in ('UP', 'DOWN'):
            quote = _v233_exact_ask(self, side)
            if quote:
                allowed, value = _v252_quote_gate(quote.get('contract'))
                entry = value if allowed else value + ' BLOCKED'
            else:
                entry = 'WAITING FOR EXACT ASK'
            self.v233_guardian_var.set(
                f'EDGE GUARDIAN: {side} FROZEN • simple edge {edge:+.2f} • '
                f'{entry} • breakout {break_class}'
            )
            deep = _v252_deep_payload(self, read, side, now=now)
            self.v233_recross_var.set(
                f'RECROSS RISK: {float(deep.get("recross_risk", 50)):.0f}% • '
                f'{read.get("support", 0)} support / {read.get("oppose", 0)} oppose'
            )

            opposite = 'DOWN' if side == 'UP' else 'UP'
            opp_quote = _v233_exact_ask(self, opposite)
            persistent_flip = (
                str(bp.get('class', '')).upper() == 'PERSISTENT BREAKOUT'
                and _v252_side(bp.get('attack_side')) == opposite
            )
            if opp_quote and float(opp_quote.get('contract', 1.0)) <= 0.30:
                if persistent_flip:
                    scalp = (
                        f'FLIP WATCH: {opposite} {float(opp_quote["contract"]) * 100:.1f}c • '
                        'persistent breakout confirmed • advisory only'
                    )
                else:
                    scalp = (
                        f'CHEAP OPPOSITE: {opposite} {float(opp_quote["contract"]) * 100:.1f}c • '
                        'NO TRADE until persistent breakout confirms'
                    )
                try:
                    self.scalp_radar_var.set(scalp)
                except Exception:
                    pass
        else:
            self.v233_guardian_var.set(
                'EDGE GUARDIAN: neutral • waiting for two independent families to agree'
            )
            self.v233_recross_var.set('RECROSS RISK: waiting for a frozen thesis')
    except Exception:
        pass
    try:
        self.root.after(500, lambda s=self: _v233_guardian_tick(s))
    except Exception:
        pass


