# ============================================================================
# BOOKMAP KING V21.53 — READ-ONLY KALSHI POSITION COACH
#
# This layer intentionally has no execution method.  It reads the authenticated
# position/fill endpoints, reconstructs the open cost basis, and converts the
# existing V21.52 evidence + V21.50 breakout state into a personal instruction.
# The frozen strategy call and the live position instruction are separate.
# ============================================================================

_V253_VERSION = 'V21.53 POSITION COACH'
_V253_POSITION_PATH = '/portfolio/positions'
_V253_FILLS_PATH = '/portfolio/fills'


def _v253_float(value, default=None):
    try:
        if value in (None, ''):
            return default
        return float(value)
    except Exception:
        return default


def _v253_fill_time(row):
    ts = _v253_float((row or {}).get('ts'))
    if ts is not None:
        return ts / 1000.0 if ts > 10_000_000_000 else ts
    return parse_iso((row or {}).get('created_time'))


def _v253_rebuild_cost_basis(fills, expected_position=None):
    """Rebuild signed YES(+)/NO(-) lots and open-side average cost."""
    qty = 0.0
    avg = None
    for row in sorted((dict(x) for x in (fills or [])), key=_v253_fill_time):
        count = _v253_float(row.get('count_fp'), _v253_float(row.get('count'), 0.0))
        if not count or count <= 0:
            continue
        side = str(row.get('side') or row.get('outcome_side') or '').lower()
        action = str(row.get('action') or 'buy').lower()
        if side not in ('yes', 'no') or action not in ('buy', 'sell'):
            continue
        yes_px = _v253_float(row.get('yes_price_dollars'))
        no_px = _v253_float(row.get('no_price_dollars'))
        if yes_px is None:
            raw = _v253_float(row.get('yes_price'))
            yes_px = raw / 100.0 if raw is not None and raw > 1 else raw
        if no_px is None:
            raw = _v253_float(row.get('no_price'))
            no_px = raw / 100.0 if raw is not None and raw > 1 else raw
        if yes_px is None and no_px is not None:
            yes_px = 1.0 - no_px
        if no_px is None and yes_px is not None:
            no_px = 1.0 - yes_px
        if yes_px is None or no_px is None:
            continue

        # Buy YES / sell NO increases YES-equivalent exposure; the opposite
        # decreases it.  Entry cost is expressed in the contract now held.
        delta = count * (1.0 if (side == 'yes') == (action == 'buy') else -1.0)
        entry_px = yes_px if delta > 0 else no_px
        if qty == 0 or qty * delta > 0:
            old_abs = abs(qty)
            new_abs = abs(delta)
            avg = ((avg or 0.0) * old_abs + entry_px * new_abs) / max(old_abs + new_abs, 1e-9)
            qty += delta
        else:
            old_qty = qty
            qty += delta
            if abs(qty) < 1e-9:
                qty, avg = 0.0, None
            elif old_qty * qty < 0:
                avg = entry_px
            # A partial reduction preserves the remaining lot's cost basis.

    expected = _v253_float(expected_position)
    if expected is not None and abs(expected) > 1e-9:
        # Fills can cross Kalshi's historical cutoff.  Never attach a cost basis
        # reconstructed for a different quantity/direction.
        tolerance = max(0.02, abs(expected) * 0.002)
        if qty * expected <= 0 or abs(abs(qty) - abs(expected)) > tolerance:
            avg = None
        qty = expected
    return {'signed_contracts': qty, 'average_entry': avg}


def _v253_parse_account_position(positions_payload, fills_payload, ticker):
    ticker = str(ticker or '').upper()
    rows = list((positions_payload or {}).get('market_positions') or [])
    row = next((dict(x) for x in rows if str(x.get('ticker') or x.get('market_ticker') or '').upper() == ticker), None)
    if not row:
        return None
    signed = _v253_float(row.get('position_fp'), _v253_float(row.get('position'), 0.0)) or 0.0
    if abs(signed) < 1e-9:
        return None
    fills = [
        x for x in list((fills_payload or {}).get('fills') or [])
        if str(x.get('ticker') or x.get('market_ticker') or '').upper() == ticker
    ]
    basis = _v253_rebuild_cost_basis(fills, expected_position=signed)
    return {
        'ticker': ticker,
        'side': 'UP' if signed > 0 else 'DOWN',
        'contracts': abs(signed),
        'signed_contracts': signed,
        'average_entry': basis.get('average_entry'),
        'last_updated_ts': row.get('last_updated_ts'),
        'fees_paid': _v253_float(row.get('fees_paid_dollars')),
        'realized_pnl': _v253_float(row.get('realized_pnl_dollars')),
    }


def _v253_coach_decision(position, market, breakout, seconds_left, peak_exit=None):
    """Pure, testable personal-action state machine.  Advisory only."""
    position = dict(position or {})
    market = dict(market or {})
    breakout = dict(breakout or {})
    side = _v252_side(position.get('side'))
    if side == 'WAIT' or float(position.get('contracts', 0.0) or 0.0) <= 0:
        return {
            'action': 'NO OPEN POSITION', 'severity': 'neutral',
            'reason': 'Connect Kalshi and open a position to activate personal coaching.',
        }

    opposite = 'DOWN' if side == 'UP' else 'UP'
    market_side = _v252_side(market.get('side'))
    edge = abs(float(market.get('edge', 0.0) or 0.0))
    support = int(market.get('support', 0) or 0)
    flip_confirmed = bool(market.get('flip_confirmed')) or (
        str(breakout.get('class', '')).upper() == 'PERSISTENT BREAKOUT'
        and _v252_side(breakout.get('attack_side')) == opposite
    )
    if flip_confirmed:
        return {
            'action': f'CUT LOSS — {opposite} FLIP CONFIRMED', 'severity': 'danger',
            'reason': (
                f'The live read flipped {opposite} against your {side} position. '
                f'Persistent breakout evidence is confirmed; the frozen original call is not being rewritten.'
            ),
        }

    exit_px = _v253_float(position.get('exit_price'))
    avg = _v253_float(position.get('average_entry'))
    pnl = None if exit_px is None or avg is None else (exit_px - avg) * float(position.get('contracts', 0.0) or 0.0)
    if exit_px is not None and exit_px >= 0.85 and (pnl is None or pnl > 0) and float(seconds_left) > 30:
        return {
            'action': 'BANK PROFIT — PRICE IS RICH', 'severity': 'profit',
            'reason': f'Your executable exit is {exit_px * 100:.1f}c with {int(seconds_left)}s left; protect the high-probability payout instead of sweating the full dollar.',
        }
    if exit_px is not None and peak_exit is not None and pnl is not None and pnl > 0 and float(peak_exit) - exit_px >= 0.08:
        return {
            'action': 'CASH OUT — PROFIT GIVING BACK', 'severity': 'warn',
            'reason': f'Exit price fell {(float(peak_exit) - exit_px) * 100:.1f}c from its round peak while the position is still profitable.',
        }

    sign = 1.0 if side == 'UP' else -1.0
    cushion = sign * float(market.get('distance', 0.0) or 0.0)
    velocity = sign * float(market.get('velocity_3s', 0.0) or 0.0)
    eta = cushion / max(-velocity, 1e-9) if cushion > 0 and velocity < -0.05 else None
    attack = market_side == opposite or float(market.get('signed_edge', 0.0) or 0.0) * sign <= -0.20
    if eta is not None and attack and eta <= float(seconds_left):
        return {
            'action': 'CASH OUT — LEAD MELTING', 'severity': 'danger',
            'reason': f'Your side still leads by ${cushion:.2f}, but current opposing drift projects a line cross in about {max(1, int(eta))}s ({int(seconds_left)}s remain).',
        }
    if market_side == opposite and edge >= 0.24 and support >= 2:
        return {
            'action': f'WATCH CLOSELY — {opposite} PRESSURE', 'severity': 'warn',
            'reason': f'{support} independent evidence families lean against your {side}; no persistent flip is confirmed yet.',
        }
    if market_side == side:
        return {
            'action': 'HOLD — LIVE READ SUPPORTS YOU', 'severity': 'good',
            'reason': f'{support} independent evidence families support {side}; live edge {edge:.2f}.',
        }
    return {
        'action': 'HOLD / WAIT — NO CONFIRMED THREAT', 'severity': 'neutral',
        'reason': 'The live evidence is mixed. No opposite persistent breakout has earned a cut signal.',
    }


def _v253_fetch_position(self, ticker):
    ticker = str(ticker or '').strip().upper()
    if not ticker:
        return None
    positions = self._kalshi_authenticated_get(
        _V253_POSITION_PATH,
        {'ticker': ticker, 'count_filter': 'position', 'limit': 10},
    )
    rows = list((positions or {}).get('market_positions') or [])
    if not any(str(x.get('ticker') or x.get('market_ticker') or '').upper() == ticker and abs(_v253_float(x.get('position_fp'), _v253_float(x.get('position'), 0.0)) or 0.0) > 0 for x in rows):
        return None
    fills = self._kalshi_authenticated_get(
        _V253_FILLS_PATH,
        {'ticker': ticker, 'limit': 1000},
    )
    return _v253_parse_account_position(positions, fills, ticker)


def _v253_market_read(self, now=None):
    now = float(now or time.time())
    try:
        data = _v252_data_ceiling(self, warm=None, now=now)
        card = _v252_scorecard(data.get('families') or {}, _V252_BOOK_WEIGHTS)
    except Exception:
        data, card = {}, {'side': 'WAIT', 'edge': 0.0, 'support': 0, 'oppose': 0, 'available': 0, 'reason': 'feeds building'}
    signed_edge = float(card.get('edge', 0.0) or 0.0)
    side = _v252_side(card.get('side'))
    state = dict(getattr(self, '_v253_flip_state', {}) or {})
    bucket = int(now // 900) * 900
    if int(state.get('bucket', -1) or -1) != bucket:
        state = {'bucket': bucket, 'candidate': 'WAIT', 'samples': 0}
    strong = side in ('UP', 'DOWN') and abs(signed_edge) >= 0.48 and int(card.get('support', 0) or 0) >= 3
    if strong and side == state.get('candidate'):
        state['samples'] = int(state.get('samples', 0) or 0) + 1
    elif strong:
        state['candidate'], state['samples'] = side, 1
    else:
        state['candidate'], state['samples'] = 'WAIT', 0
    self._v253_flip_state = state
    flip_confirmed = strong and int(state.get('samples', 0) or 0) >= 2
    motion = dict(data.get('motion') or {})
    confidence = min(95.0, 50.0 + abs(signed_edge) * 45.0)
    return {
        **card,
        'side': side,
        'signed_edge': signed_edge,
        'confidence': confidence,
        'flip_confirmed': flip_confirmed,
        'distance': float(data.get('distance', 0.0) or 0.0),
        'velocity_3s': float(motion.get('velocity_3s', 0.0) or 0.0),
    }


def _v253_request_refresh(self):
    self._v253_next_position_poll = 0.0
    try:
        self.position_coach_sync_var.set('POSITION SYNC: refresh requested')
    except Exception:
        pass


def _v253_position_poll(self, now=None):
    now = float(now or time.time())
    if getattr(self, '_v253_position_inflight', False) or now < float(getattr(self, '_v253_next_position_poll', 0.0) or 0.0):
        return
    self._v253_next_position_poll = now + 2.0
    if not getattr(self, 'kalshi_credentials_verified', False):
        self.position_coach_sync_var.set('POSITION SYNC: connect + verify Kalshi API (read-only GET)')
        return
    ticker = str((getattr(self, 'kalshi_market', {}) or {}).get('ticker') or getattr(self, 'kalshi_ticker', '') or self.ticker_var.get() or '').strip().upper()
    if not ticker:
        self.position_coach_sync_var.set('POSITION SYNC: waiting for active Kalshi ticker')
        return
    self._v253_position_inflight = True

    def worker():
        pos, err = None, None
        try:
            pos = _v253_fetch_position(self, ticker)
        except Exception as exc:
            err = str(exc)
        def finish():
            self._v253_position_inflight = False
            if err:
                self.position_coach_sync_var.set(f'POSITION SYNC: error • {err[:120]}')
                return
            self._v253_account_position = pos
            self.position_coach_sync_var.set(
                f'POSITION SYNC: live • {ticker} • updated every 2s'
                if pos else f'POSITION SYNC: live • no open position in {ticker}'
            )
        try:
            self.root.after(0, finish)
        except Exception:
            self._v253_position_inflight = False
    threading.Thread(target=worker, daemon=True, name='BookmapKingPositionCoach').start()


def _v253_render_coach(self, now=None):
    now = float(now or time.time())
    _v253_position_poll(self, now=now)
    market = _v253_market_read(self, now=now)
    breakout = dict(getattr(self, '_v250_break_last', {}) or {})
    pos = dict(getattr(self, '_v253_account_position', None) or {})
    if pos:
        try:
            exit_px, _yes, source, age = self._kalshi_paper_price(pos['side'], 'EXIT', max_age=3.0)
        except Exception:
            exit_px, source, age = None, 'WAITING', None
        pos['exit_price'] = exit_px
        key = (pos.get('ticker'), pos.get('side'))
        if key != getattr(self, '_v253_peak_key', None):
            self._v253_peak_key, self._v253_peak_exit = key, exit_px
        elif exit_px is not None:
            self._v253_peak_exit = max(float(getattr(self, '_v253_peak_exit', exit_px) or exit_px), float(exit_px))
        pos['quote_source'], pos['quote_age'] = source, age
        self._v253_account_position = pos
    seconds_left = max(0.0, 900.0 - now % 900.0)
    decision = _v253_coach_decision(pos, market, breakout, seconds_left, getattr(self, '_v253_peak_exit', None))

    market_side = _v252_side(market.get('side'))
    if market_side == 'WAIT':
        market_title = 'LIVE READ: FORMING / MIXED'
    elif market.get('flip_confirmed'):
        market_title = f'LIVE FLIP: {market_side} CONFIRMED'
    else:
        market_title = f'LIVE READ: LEANING {market_side}'
    self.position_coach_market_var.set(
        f'{market_title} • evidence {float(market.get("confidence", 50)):.0f}/95 • '
        f'{market.get("support", 0)} support / {market.get("oppose", 0)} oppose\n'
        f'{market.get("reason", "feeds building")} • breakout {breakout.get("class", "building")}'
    )
    self.position_coach_action_var.set(str(decision.get('action')))
    self.position_coach_reason_var.set(str(decision.get('reason')))

    if pos:
        avg = pos.get('average_entry')
        exit_px = pos.get('exit_price')
        pnl = None if avg is None or exit_px is None else (float(exit_px) - float(avg)) * float(pos.get('contracts', 0.0))
        avg_text = '--' if avg is None else f'{float(avg) * 100:.2f}c'
        exit_text = '--' if exit_px is None else f'{float(exit_px) * 100:.1f}c'
        pnl_text = '--' if pnl is None else f'${pnl:+.2f} est.'
        self.position_coach_position_var.set(
            f'YOU: {float(pos.get("contracts", 0)):.2f}x {pos.get("side")} @ {avg_text} • '
            f'exit {exit_text} • P&L {pnl_text}'
        )
    else:
        self.position_coach_position_var.set('YOU: no open position detected in this round')

    colors = {'danger': RED, 'warn': YELLOW, 'profit': GREEN, 'good': GREEN, 'neutral': MUTED}
    try:
        self._v253_action_label.configure(fg=colors.get(decision.get('severity'), TEXT))
    except Exception:
        pass
    old_action = str(getattr(self, '_v253_last_action', '') or '')
    new_action = str(decision.get('action') or '')
    if new_action != old_action:
        self._v253_last_action = new_action
        urgent = new_action.startswith(('CUT LOSS', 'CASH OUT'))
        if urgent and bool(self.position_coach_sound_var.get()):
            try:
                self.root.bell()
            except Exception:
                pass


def _v253_tick(self):
    try:
        _v253_render_coach(self)
    except Exception as exc:
        try:
            self.position_coach_sync_var.set(f'POSITION COACH: recovering • {str(exc)[:100]}')
        except Exception:
            pass
    try:
        self.root.after(500, lambda s=self: _v253_tick(s))
    except Exception:
        pass


def _v253_mount_panel(self):
    side = getattr(self, 'brain_content', None)
    if side is None:
        return False
    old = getattr(self, '_v253_coach_card', None)
    try:
        if old is not None and old.winfo_exists():
            return True
    except Exception:
        pass
    outer = tk.Frame(side, bg=PINK_DARK, highlightthickness=2, highlightbackground=GREEN, bd=0)
    outer.pack(fill='x', pady=(10, 0))
    shell = tk.Frame(outer, bg=PANEL2, padx=11, pady=10)
    shell.pack(fill='x', padx=2, pady=2)
    tk.Label(shell, text='KALSHI LIVE POSITION COACH • READ ONLY', bg=PANEL2, fg=GREEN, font=('Segoe UI Variable', 10, 'bold'), anchor='w').pack(fill='x')
    tk.Label(shell, textvariable=self.position_coach_market_var, bg=PANEL2, fg=TEXT, font=('Cascadia Mono', 8), wraplength=330, justify='left', anchor='w').pack(fill='x', pady=(7, 7))
    self._v253_action_label = tk.Label(shell, textvariable=self.position_coach_action_var, bg=PANEL, fg=TEXT, font=('Segoe UI Variable', 16, 'bold'), wraplength=330, justify='left', anchor='w', padx=9, pady=8)
    self._v253_action_label.pack(fill='x')
    tk.Label(shell, textvariable=self.position_coach_reason_var, bg=PANEL2, fg=TEXT, font=('Segoe UI', 9), wraplength=330, justify='left', anchor='w').pack(fill='x', pady=(7, 7))
    tk.Label(shell, textvariable=self.position_coach_position_var, bg=PANEL, fg=PINK2, font=('Cascadia Mono', 8, 'bold'), wraplength=330, justify='left', anchor='w', padx=8, pady=7).pack(fill='x')
    tk.Label(shell, textvariable=self.position_coach_sync_var, bg=PANEL2, fg=MUTED, font=('Cascadia Mono', 7), wraplength=330, justify='left', anchor='w').pack(fill='x', pady=(6, 4))
    controls = tk.Frame(shell, bg=PANEL2)
    controls.pack(fill='x')
    ttk.Button(controls, text='ANALYZE NOW', command=lambda s=self: _v253_request_refresh(s)).pack(side='left')
    ttk.Checkbutton(controls, text='URGENT SOUND', variable=self.position_coach_sound_var).pack(side='right')
    tk.Label(shell, text='Advisory only • position/fills are read with authenticated GET • no coach action places or cancels orders.', bg=PANEL2, fg=MUTED, font=('Segoe UI', 7), wraplength=330, justify='left', anchor='w').pack(fill='x', pady=(7, 0))
    self._v253_coach_card = outer
    return True


