def _v254_render_coach(self, now=None):
    now = float(now or time.time())
    scan = _v254_scan_all(self, now=now)
    _V254_BASE_COACH_RENDER(self, now=now)
    active = dict(scan.get('active') or {})
    if not active:
        return
    position = dict(getattr(self, '_v253_account_position', None) or {})
    quote = _v254_entry_quote(self, active.get('side'))
    instruction = _v254_reverse_instruction(active, position, quote, scan.get('seconds_left', 0.0))
    if not instruction:
        return
    self.position_coach_action_var.set(instruction['action'])
    self.position_coach_reason_var.set(instruction['reason'])
    frame = (scan.get('frames') or {}).get(active.get('tf')) or {}
    prior = self.position_coach_market_var.get()
    self.position_coach_market_var.set(
        f'GAINZ MTF REVERSAL: {active.get("side")} CONFIRMED • {active.get("tf")} closed • '
        f'{active.get("score")}/10 • MTF {active.get("support")} support / {active.get("oppose")} oppose\n'
        f'{frame.get("reason", active.get("reason", ""))}\n{prior.splitlines()[0] if prior else ""}'
    )
    colors = {'danger': RED, 'warn': YELLOW, 'good': GREEN}
    try:
        self._v253_action_label.configure(fg=colors.get(instruction.get('severity'), TEXT))
    except Exception:
        pass


