# ============================================================================
# BOOKMAP KING V21.55 — ALWAYS-ON CANDLES + HARD ROUND ROLLOVER
#
# Reliability layer for unattended streaming:
# - Bookmap trades are bucket-upserted even if UDP packets arrive out of order.
# - The chart always owns a synthetic live candle, including quiet/no-trade bars.
# - Invalid/duplicate OHLC rows are repaired before every paint.
# - A separate watchdog retries a full paint if only the lightweight price line
#   is moving or the most recent candle bucket did not advance.
# - The OPEN lock and every transient strategy latch reset on each UTC 15m
#   boundary (and on a genuine Kalshi ticker change inside the same bucket).
# ============================================================================

_V255_BASE_INIT = ChartKingPro.__init__
_V255_BASE_UI_TICK = ChartKingPro._ui_tick
_V255_BASE_DRAW_CHART = ChartKingPro.draw_chart
_V255_BASE_CHART_CANDLES = ChartKingPro._chart_candles
_V255_BASE_RESET_MARKET = ChartKingPro.reset_market_state


def _v255_event_ts(value, fallback=None):
    """Normalize Bookmap timestamps without trusting transport order."""
    fallback = float(fallback or time.time())
    try:
        ts = float(value)
    except Exception:
        return fallback
    if ts > 1e16:
        ts /= 1e9
    elif ts > 1e12:
        ts /= 1e3
    if not math.isfinite(ts) or ts <= 0:
        return fallback
    # A broken exchange timestamp must not create a far-future chart bucket.
    if ts > fallback + 120.0:
        return fallback
    return ts


def _bk_update_ohlc(rows, seconds, ts, price, size, max_rows=1600):
    """Order-independent OHLC upsert used by the native Bookmap child."""
    seconds = max(1, int(seconds))
    ts = _v255_event_ts(ts)
    price = float(price)
    size = max(0.0, float(size or 0.0))
    if not math.isfinite(price) or price <= 0:
        return False
    bucket = int(ts // seconds) * seconds

    found = None
    for row in reversed(rows):
        try:
            row_bucket = int(row.get('time', -1))
        except Exception:
            continue
        if row_bucket == bucket:
            found = row
            break
        if row_bucket < bucket:
            break
    if found is not None:
        found['high'] = max(float(found.get('high', price)), price)
        found['low'] = min(float(found.get('low', price)), price)
        first_ts = float(found.get('_first_ts', found.get('time', ts)) or ts)
        last_ts = float(found.get('_last_ts', first_ts) or first_ts)
        if ts <= first_ts:
            found['open'] = price
            found['_first_ts'] = ts
        if ts >= last_ts:
            found['close'] = price
            found['_last_ts'] = ts
        found['volume'] = float(found.get('volume', 0.0) or 0.0) + size
        return True

    new_row = {
        'time': bucket, 'open': price, 'high': price, 'low': price,
        'close': price, 'volume': size, '_first_ts': ts, '_last_ts': ts,
    }
    if not rows or bucket > int(rows[-1].get('time', -1)):
        rows.append(new_row)
        if len(rows) > max(2, int(max_rows)):
            del rows[:-max(2, int(max_rows))]
        return True
    rows.append(new_row)

    # UDP can reorder packets. Rebuild by bucket so the newest candle cannot
    # get stranded behind a late packet and stop receiving updates.
    by_bucket = {}
    for raw in rows:
        try:
            key = int(raw.get('time'))
            op = float(raw.get('open'))
            hi = float(raw.get('high'))
            lo = float(raw.get('low'))
            cl = float(raw.get('close'))
        except Exception:
            continue
        if not all(math.isfinite(x) for x in (op, hi, lo, cl)):
            continue
        prior = by_bucket.get(key)
        if prior is None:
            by_bucket[key] = {
                **dict(raw), 'time': key, 'open': op,
                'high': max(hi, op, cl), 'low': min(lo, op, cl),
                'close': cl, 'volume': max(0.0, float(raw.get('volume', 0.0) or 0.0)),
            }
        else:
            raw_first = float(raw.get('_first_ts', key) or key)
            raw_last = float(raw.get('_last_ts', raw_first) or raw_first)
            prior_first = float(prior.get('_first_ts', key) or key)
            prior_last = float(prior.get('_last_ts', prior_first) or prior_first)
            prior['high'] = max(float(prior['high']), hi, op, cl)
            prior['low'] = min(float(prior['low']), lo, op, cl)
            if raw_first < prior_first:
                prior['open'] = op
                prior['_first_ts'] = raw_first
            if raw_last >= prior_last:
                prior['close'] = cl
                prior['_last_ts'] = raw_last
            prior['volume'] = max(
                float(prior.get('volume', 0.0) or 0.0),
                float(raw.get('volume', 0.0) or 0.0),
            )
    ordered = [by_bucket[key] for key in sorted(by_bucket)][-max(2, int(max_rows)):]
    rows[:] = ordered
    return True


def _v255_clean_chart_rows(rows, seconds, now=None):
    """Return sorted, unique, finite candles and repair OHLC containment."""
    now = float(now or time.time())
    seconds = max(1, int(seconds))
    future_limit = int(now // seconds) * seconds
    clean = {}
    for raw in rows or []:
        try:
            bucket = int(float(raw.get('time')) // seconds) * seconds
            if bucket > future_limit:
                continue
            op = float(raw.get('open'))
            hi = float(raw.get('high'))
            lo = float(raw.get('low'))
            cl = float(raw.get('close'))
            vol = max(0.0, float(raw.get('volume', 0.0) or 0.0))
        except Exception:
            continue
        if not all(math.isfinite(x) for x in (op, hi, lo, cl, vol)):
            continue
        prior = clean.get(bucket)
        if prior is None:
            clean[bucket] = {
                **dict(raw), 'time': bucket, 'open': op,
                'high': max(hi, op, cl), 'low': min(lo, op, cl),
                'close': cl, 'volume': vol,
            }
        else:
            prior['high'] = max(float(prior['high']), hi, op, cl)
            prior['low'] = min(float(prior['low']), lo, op, cl)
            prior['close'] = cl
            prior['volume'] = max(float(prior.get('volume', 0.0)), vol)
    return [clean[key] for key in sorted(clean)]


def _v255_chart_candles(self):
    """Self-healing chart source with one guaranteed current live candle."""
    now = time.time()
    seconds = max(1, int(getattr(self, 'chart_interval_seconds', 900) or 900))
    try:
        rows = list(_V255_BASE_CHART_CANDLES(self) or [])
    except Exception as exc:
        self._v255_candle_recoveries = int(getattr(self, '_v255_candle_recoveries', 0)) + 1
        self._v255_last_candle_error = str(exc)[:180]
        try:
            rows = list(self._history_for_interval(seconds) or [])
        except Exception:
            rows = []
    rows = _v255_clean_chart_rows(rows, seconds, now=now)
    bucket = int(now // seconds) * seconds
    current = next((row for row in reversed(rows) if int(row['time']) == bucket), None)
    live, source = self.effective_live_price()
    if live is None and rows:
        live = float(rows[-1]['close'])
        source = 'LAST GOOD CLOSE / QUIET BAR'
    if live is not None:
        live = float(live)
        key = (seconds, bucket)
        opens = getattr(self, '_v255_live_opens', {})
        if key not in opens:
            samples = [
                float(price) for ts, price in (getattr(self, 'live_prices', []) or [])
                if bucket <= float(ts) <= now
            ]
            previous = next((row for row in reversed(rows) if int(row['time']) < bucket), None)
            opens[key] = samples[0] if samples else float(previous['close']) if previous else live
            # Keep only recent buckets across all visible timeframes.
            if len(opens) > 80:
                for old_key in sorted(opens, key=lambda x: x[1])[:-60]:
                    opens.pop(old_key, None)
            self._v255_live_opens = opens
        open_price = float(opens[key])
        if current is None:
            current = {
                'time': bucket, 'open': open_price, 'high': max(open_price, live),
                'low': min(open_price, live), 'close': live, 'volume': 0.0,
                '_open_source': 'V21.55 PERSISTENT LIVE OPEN', '_live_source': source,
            }
            rows.append(current)
        else:
            current['open'] = open_price
            current['high'] = max(float(current['high']), open_price, live)
            current['low'] = min(float(current['low']), open_price, live)
            current['close'] = live
            current['_live_source'] = source
    rows = _v255_clean_chart_rows(rows, seconds, now=now)
    self._v255_last_candle_rows = [dict(row) for row in rows]
    self._v255_last_candle_bucket = int(rows[-1]['time']) if rows else None
    self._v255_last_candle_close = float(rows[-1]['close']) if rows else None
    return rows


def _v255_round_identity(self, now=None):
    now = float(now or time.time())
    bucket = int(now // 900) * 900
    ticker = str(
        ((getattr(self, 'kalshi_market', None) or {}).get('ticker'))
        or getattr(self, 'kalshi_ticker', '') or ''
    ).strip().upper()
    return bucket, ticker


def _v255_finalize_old_round(self, old_bucket):
    """Preserve settled learning before the hard unattended reset."""
    if old_bucket is None:
        return
    try:
        candles = list(getattr(self, 'btc_15m', []) or [])
        self._finalize_independent_checkpoints(int(old_bucket), candles)
        old_snap = getattr(self, 'checkpoint_snapshot', None)
        if old_snap is not None:
            self._stockpile_finalize_market(int(old_bucket), old_snap, candles)
    except Exception:
        pass


def _v255_rollover_guard(self, now=None):
    """Reset every transient/open lock exactly once per real 15m identity."""
    now = float(now or time.time())
    identity = _v255_round_identity(self, now=now)
    prior = getattr(self, '_v255_round_identity_current', None)
    if prior is None:
        self._v255_round_identity_current = identity
        return False
    bucket_changed = int(identity[0]) != int(prior[0])
    ticker_changed = bool(identity[1] and prior[1] and identity[1] != prior[1])
    if not bucket_changed and not ticker_changed:
        # Adopt a ticker discovered just after startup/rollover without treating
        # normal market discovery as a second round reset.
        if identity[1] and not prior[1]:
            self._v255_round_identity_current = identity
        return False
    if bucket_changed:
        _v255_finalize_old_round(self, prior[0])
    try:
        _V255_BASE_RESET_MARKET(self)
    except Exception:
        # The OPEN lock is the non-negotiable reset even if a legacy panel
        # happens to fail during the broader transient reset.
        self.opening_lock_snapshot = None
        self.opening_lock_candidate = None
        self.opening_lock_candidate_since = 0.0
        self.opening_lock_bucket = None
    self._v255_round_identity_current = identity
    self._v255_live_opens = {}
    self._v255_last_candle_bucket = None
    # Claim the new checkpoint bucket here so the legacy checkpoint engine
    # does not finalize/reset the old round a second time on its next pass.
    try:
        self.checkpoint_bucket = int(identity[0])
        self.checkpoint_snapshot = None
        self.checkpoint_snapshots = {}
        self.checkpoint_health_states = {}
        self.checkpoint_missed = set()
        self._sync_selected_checkpoint_snapshot()
        self._checkpoint_status_summary()
    except Exception:
        pass
    self._last_live_draw = 0.0
    self._last_chart_render_key = None
    reason = 'AUTO NEW 15M ROUND' if bucket_changed else 'AUTO KALSHI MARKET CHANGE'
    self.last_market_reset_ts = now
    self.last_market_reset_reason = reason
    try:
        self.market_reset_var.set(f'ROUND STATE: RESET • {reason} • OPEN LOCK CLEARED')
        self.opening_lock_var.set('OPEN LOCK: NEW ROUND • REBUILDING FROM LIVE BOOKMAP')
    except Exception:
        pass
    return True


def _v255_draw_chart(self, *args, **kwargs):
    try:
        result = _V255_BASE_DRAW_CHART(self, *args, **kwargs)
        rows = list(getattr(self, '_v255_last_candle_rows', []) or [])
        if rows:
            self._v255_last_good_draw = time.time()
            self._v255_last_draw_bucket = int(rows[-1]['time'])
            self._v255_last_draw_close = float(rows[-1]['close'])
            self._v255_consecutive_draw_errors = 0
        return result
    except Exception as exc:
        self._v255_consecutive_draw_errors = int(getattr(self, '_v255_consecutive_draw_errors', 0)) + 1
        self._v255_last_draw_error = f'{type(exc).__name__}: {exc}'[:220]
        self._last_chart_render_key = None
        self._last_live_draw = 0.0
        raise


def _v255_watchdog_tick(self):
    """Independent paint/round watchdog for hours-long unattended streams."""
    now = time.time()
    try:
        _v255_rollover_guard(self, now=now)
        seconds = max(1, int(getattr(self, 'chart_interval_seconds', 900) or 900))
        expected = int(now // seconds) * seconds
        drawn = getattr(self, '_v255_last_draw_bucket', None)
        stale = now - float(getattr(self, '_v255_last_good_draw', 0.0) or 0.0) > 3.0
        wrong_bucket = drawn is not None and int(drawn) != expected
        if not bool(getattr(self, 'web_only_mode', False)) and (stale or wrong_bucket):
            self._last_chart_render_key = None
            self._last_live_draw = 0.0
            try:
                self.draw_chart()
                self._v255_watchdog_repairs = int(getattr(self, '_v255_watchdog_repairs', 0)) + 1
            except Exception:
                pass
    finally:
        try:
            self.root.after(750, lambda s=self: _v255_watchdog_tick(s))
        except Exception:
            pass


def _v255_ui_tick(self):
    try:
        _v255_rollover_guard(self)
    except Exception:
        pass
    return _V255_BASE_UI_TICK(self)


def _v255_reset_market_state(self):
    result = _V255_BASE_RESET_MARKET(self)
    self._v255_round_identity_current = _v255_round_identity(self)
    self._v255_live_opens = {}
    self._last_live_draw = 0.0
    self._last_chart_render_key = None
    return result


def _v255_init(self, *args, **kwargs):
    _V255_BASE_INIT(self, *args, **kwargs)
    self._v255_round_identity_current = _v255_round_identity(self)
    self._v255_live_opens = {}
    self._v255_last_candle_rows = []
    self._v255_last_candle_bucket = None
    self._v255_last_candle_close = None
    self._v255_last_good_draw = 0.0
    self._v255_last_draw_bucket = None
    self._v255_last_draw_close = None
    self._v255_last_draw_error = ''
    self._v255_last_candle_error = ''
    self._v255_consecutive_draw_errors = 0
    self._v255_candle_recoveries = 0
    self._v255_watchdog_repairs = 0
    try:
        self.root.title('BOOKMAP KING V21.55 — ALWAYS-ON CANDLES + GAINZ REVERSAL COACH')
        self.chart_tf_status_var.set(
            'All intervals • live candle watchdog ON • OPEN lock auto-resets every 15m'
        )
        self.root.after(900, lambda s=self: _v255_watchdog_tick(s))
    except Exception:
        pass


ChartKingPro._chart_candles = _v255_chart_candles
ChartKingPro.draw_chart = _v255_draw_chart
ChartKingPro._ui_tick = _v255_ui_tick
ChartKingPro.reset_market_state = _v255_reset_market_state
ChartKingPro.__init__ = _v255_init


# ============================================================================
# BOOKMAP KING V21.56 — ZERO-FREEZE RUNTIME
#
# Runtime reliability layer for long unattended streams:
# - removes a recursive Bookmap lock path that could deadlock the whole window;
# - bounds the active MBO universe while preserving nearest, largest, newest,
#   oldest/persistent, and representative orders;
# - snapshots only the decision-relevant MBO working set on Tk's thread;
# - keeps every executed trade for tape/whale logic while batching redundant
#   multi-timeframe OHLC mutations once per event-second;
# - yields between saturated UDP bursts so Tk always gets interpreter time;
# - replaces duplicated legacy presentation heartbeats with one budgeted pulse;
# - pauses expensive cosmetic/DB/chart work while scrolling or recovering from
#   an overloaded UI tick, without pausing data ingestion or the live coach.
# ============================================================================

import heapq as _v256_heapq

_V256_VERSION = 'V21.56 ZERO-FREEZE RUNTIME'
_V256_MBO_TRIGGER = 7500
_V256_MBO_TARGET = 5200
_V256_MBO_SNAPSHOT = 2600
_V256_DEPTH_TARGET = 2800
_V256_PULSE_MS = 125


def _v256_finite(value, default=None):
    try:
        value = float(value)
        return value if math.isfinite(value) else default
    except Exception:
        return default


def _v256_var(var, value):
    """Set a Tk variable only when its rendered value actually changed."""
    if var is None:
        return False
    value = str(value)
    try:
        if str(var.get()) == value:
            return False
        var.set(value)
        return True
    except Exception:
        return False


def _v256_book_reference_locked(self):
    """Return a Bookmap reference without recursively acquiring its lock."""
    ref = _v256_finite(getattr(self, 'current_spot', None))
    if ref is not None and ref > 0:
        return ref
    bbo = dict(getattr(self, 'bookmap_bbo', {}) or {})
    bid = _v256_finite(bbo.get('bid'))
    ask = _v256_finite(bbo.get('ask'))
    if bid is not None and ask is not None and ask >= bid:
        return (bid + ask) / 2.0
    trades = getattr(self, 'bookmap_trades', None)
    try:
        if trades:
            ref = _v256_finite(trades[-1].get('price'))
            if ref is not None and ref > 0:
                return ref
    except Exception:
        pass
    return None


def _v256_take(items, count, key, largest=False):
    items = list(items or ())
    count = max(0, int(count))
    if count <= 0:
        return []
    if len(items) <= count:
        return items
    fn = _v256_heapq.nlargest if largest else _v256_heapq.nsmallest
    try:
        return fn(count, items, key=key)
    except Exception:
        return items[:count]


def _v256_mbo_snapshot_locked(self, now, reference=None):
    """
    Small, representative MBO snapshot for the whale reader.

    Called with bookmap_lock already held.  It retains proximity, true size,
    freshness, persistence, and a deterministic distribution sample, so the
    data ceiling remains broad without copying every active order into Tk.
    """
    raw = list(getattr(self, 'bookmap_mbo_orders', {}).items())
    valid = []
    for oid, row in raw:
        if not isinstance(row, dict):
            continue
        price = _v256_finite(row.get('price'))
        size = _v256_finite(row.get('size'), 0.0)
        if price is None or size is None or price <= 0 or size <= 0:
            continue
        valid.append((oid, row))
    if len(valid) <= _V256_MBO_SNAPSHOT:
        return {oid: dict(row) for oid, row in valid}

    ref = _v256_finite(reference)
    chosen = {}

    # A deterministic even sample keeps the ordinary-size distribution used
    # for the MBO median; selecting only whales would bias the denominator.
    stride = max(1, len(valid) // 800)
    for oid, row in valid[::stride][:800]:
        chosen[oid] = row

    if ref is not None and ref > 0:
        proximity = _v256_take(
            valid, 900,
            key=lambda item: abs(float(item[1].get('price', ref)) - ref),
        )
    else:
        proximity = _v256_take(
            valid, 900,
            key=lambda item: float(item[1].get('updated', 0.0) or 0.0),
            largest=True,
        )
    for oid, row in proximity:
        chosen[oid] = row
    for oid, row in _v256_take(
        valid, 300,
        key=lambda item: float(item[1].get('size', 0.0) or 0.0),
        largest=True,
    ):
        chosen[oid] = row
    for oid, row in _v256_take(
        valid, 300,
        key=lambda item: float(item[1].get('updated', 0.0) or 0.0),
        largest=True,
    ):
        chosen[oid] = row
    for oid, row in _v256_take(
        valid, 300,
        key=lambda item: float(item[1].get('first_seen', now) or now),
    ):
        chosen[oid] = row

    # Union size is <=2600 by construction; this guard keeps that invariant if
    # the selection mix changes in a later local edit.
    rows = list(chosen.items())
    if len(rows) > _V256_MBO_SNAPSHOT:
        rows = rows[:_V256_MBO_SNAPSHOT]
    return {oid: dict(row) for oid, row in rows}


def _v256_prune_depth_locked(book, reference):
    if not isinstance(book, dict) or len(book) <= _V256_DEPTH_TARGET:
        return 0
    before = len(book)
    items = list(book.items())
    ref = _v256_finite(reference)
    chosen = {}
    if ref is not None and ref > 0:
        for price, row in _v256_take(
            items, 2100,
            key=lambda item: abs(float(item[0]) - ref),
        ):
            chosen[price] = row
    else:
        for price, row in _v256_take(
            items, 2100,
            key=lambda item: float((item[1] or {}).get('updated', 0.0) or 0.0),
            largest=True,
        ):
            chosen[price] = row
    for price, row in _v256_take(
        items, 700,
        key=lambda item: float((item[1] or {}).get('size', 0.0) or 0.0),
        largest=True,
    ):
        chosen[price] = row
    if len(chosen) > _V256_DEPTH_TARGET:
        chosen = dict(list(chosen.items())[:_V256_DEPTH_TARGET])
    book.clear()
    book.update(chosen)
    return max(0, before - len(book))


def _v256_prune_mbo_locked(self, now, reference):
    orders = getattr(self, 'bookmap_mbo_orders', None)
    if not isinstance(orders, dict) or len(orders) <= _V256_MBO_TRIGGER:
        return 0
    before = len(orders)
    items = [item for item in orders.items() if isinstance(item[1], dict)]
    ref = _v256_finite(reference)
    chosen = {}

    if ref is not None and ref > 0:
        core = _v256_take(
            items, 3200,
            key=lambda item: abs(float(item[1].get('price', ref)) - ref),
        )
    else:
        core = _v256_take(
            items, 3200,
            key=lambda item: float(item[1].get('updated', 0.0) or 0.0),
            largest=True,
        )
    for oid, row in core:
        chosen[oid] = row
    for oid, row in _v256_take(
        items, 800,
        key=lambda item: float(item[1].get('size', 0.0) or 0.0),
        largest=True,
    ):
        chosen[oid] = row
    for oid, row in _v256_take(
        items, 600,
        key=lambda item: float(item[1].get('updated', 0.0) or 0.0),
        largest=True,
    ):
        chosen[oid] = row
    for oid, row in _v256_take(
        items, 600,
        key=lambda item: float(item[1].get('first_seen', now) or now),
    ):
        chosen[oid] = row

    rows = list(chosen.items())[:_V256_MBO_TARGET]
    orders.clear()
    orders.update(rows)
    return max(0, before - len(orders))


def _v256_prune_bookmap_state(self, now=None, force=False):
    """Non-blocking, receiver-side bounds; never makes Tk wait for pruning."""
    now = float(now or time.time())
    lock = getattr(self, 'bookmap_lock', None)
    if lock is None:
        return {'acquired': False}
    try:
        acquired = lock.acquire(blocking=False)
    except TypeError:
        acquired = lock.acquire(False)
    except Exception:
        acquired = False
    if not acquired:
        return {'acquired': False}
    try:
        bids = getattr(self, 'bookmap_bids', {})
        asks = getattr(self, 'bookmap_asks', {})
        mbo = getattr(self, 'bookmap_mbo_orders', {})
        highwater = max(
            int(getattr(self, '_v256_mbo_highwater', 0) or 0),
            len(mbo) if isinstance(mbo, dict) else 0,
        )
        self._v256_mbo_highwater = highwater
        due = now - float(getattr(self, '_v256_last_prune_ts', 0.0) or 0.0) >= 0.75
        oversized = (
            (isinstance(mbo, dict) and len(mbo) > _V256_MBO_TRIGGER)
            or (isinstance(bids, dict) and len(bids) > 5000)
            or (isinstance(asks, dict) and len(asks) > 5000)
        )
        if not force and not due and not oversized:
            return {'acquired': True, 'skipped': True}
        reference = _v256_book_reference_locked(self)
        removed_depth = (
            _v256_prune_depth_locked(bids, reference)
            + _v256_prune_depth_locked(asks, reference)
        )
        removed_mbo = _v256_prune_mbo_locked(self, now, reference)
        self._v256_last_prune_ts = now
        self._v256_pruned_depth = int(getattr(self, '_v256_pruned_depth', 0) or 0) + removed_depth
        self._v256_pruned_mbo = int(getattr(self, '_v256_pruned_mbo', 0) or 0) + removed_mbo
        return {
            'acquired': True,
            'removed_depth': removed_depth,
            'removed_mbo': removed_mbo,
            'mbo': len(mbo) if isinstance(mbo, dict) else 0,
            'bids': len(bids) if isinstance(bids, dict) else 0,
            'asks': len(asks) if isinstance(asks, dict) else 0,
        }
    finally:
        try:
            lock.release()
        except Exception:
            pass


_V256_BASE_INGEST_BOOKMAP = ChartKingPro._ingest_bookmap_event


def _v256_ingest_bookmap_event(self, event):
    result = _V256_BASE_INGEST_BOOKMAP(self, event)
    kind = str((event or {}).get('type', '')).lower().strip()
    if kind in ('depth', 'mbo_send', 'mbo_replace', 'mbo_cancel'):
        now = time.time()
        last = float(getattr(self, '_v256_last_prune_request', 0.0) or 0.0)
        mbo_count = len(getattr(self, 'bookmap_mbo_orders', {}) or {})
        force = mbo_count > _V256_MBO_TRIGGER
        if force or now - last >= 0.75:
            self._v256_last_prune_request = now
            _v256_prune_bookmap_state(self, now=now, force=force)
    return result


def _v256_trade_fields(event, fallback):
    try:
        ts = _v255_event_ts(event.get('ts'), fallback=fallback)
        price = float(event.get('price'))
        size = max(0.0, float(event.get('size', 0.0) or 0.0))
        if not math.isfinite(price) or price <= 0:
            return None
        return ts, price, size
    except Exception:
        return None


def _v256_apply_trade_batch(app, events):
    """Keep the full tape; compress only redundant OHLC/list mutations."""
    now = time.time()
    valid = []
    for index, event in enumerate(events or ()):
        try:
            app._ingest_bookmap_event(event)
        except Exception:
            continue
        row = _v256_trade_fields(event, now)
        if row is not None:
            ts, price, size = row
            valid.append({'index': index, 'ts': ts, 'price': price, 'size': size})
    if not valid:
        return 0

    try:
        app.bookmap_transport_last_ts = now
        app.bookmap_last_data_event_ts = now
    except Exception:
        pass

    by_second = {}
    for row in valid:
        by_second.setdefault(int(row['ts']), []).append(row)

    retained_points = []
    for second in sorted(by_second):
        group = sorted(by_second[second], key=lambda row: (row['ts'], row['index']))
        first = group[0]
        last = group[-1]
        high = max(group, key=lambda row: row['price'])
        low = min(group, key=lambda row: row['price'])
        points = {
            int(first['index']): first,
            int(last['index']): last,
            int(high['index']): high,
            int(low['index']): low,
        }
        ordered = sorted(points.values(), key=lambda row: (row['ts'], row['index']))
        total_volume = sum(float(row['size']) for row in group)
        for point_index, point in enumerate(ordered):
            try:
                _bk_refresh_v97_candles(
                    app,
                    point['ts'],
                    point['price'],
                    total_volume if point_index == 0 else 0.0,
                )
            except Exception:
                pass
            retained_points.append((point['ts'], point['price']))

    latest = max(valid, key=lambda row: (row['ts'], row['index']))
    try:
        app.current_spot = latest['price']
        app.quote_mesh_last = latest['ts']
        app.quote_mesh_price = latest['price']
        app.quote_mesh_source = 'BOOKMAP EXECUTIONS'
        app.live_stream_source = 'BOOKMAP EXECUTIONS'
        app.kraken_tick_ts = latest['ts']
        app.kraken_price = latest['price']
        app.live_prices.extend(retained_points)
        if len(app.live_prices) > 12000:
            cutoff = latest['ts'] - 6 * 3600
            app.live_prices = [x for x in app.live_prices if x[0] >= cutoff][-12000:]
    except Exception:
        pass
    app._v256_trade_events = int(getattr(app, '_v256_trade_events', 0) or 0) + len(valid)
    app._v256_candle_points = int(getattr(app, '_v256_candle_points', 0) or 0) + len(retained_points)
    return len(valid)


def _v256_apply_ordered_events(app, root, events):
    """Apply a UDP burst while batching only consecutive trade mutations."""
    trade_run = []

    def flush():
        if trade_run:
            _v256_apply_trade_batch(app, trade_run)
            trade_run.clear()

    for event in events or ():
        kind = str((event or {}).get('type', '')).lower().strip()
        if kind == 'trade':
            trade_run.append(event)
            continue
        flush()
        if kind == 'shutdown':
            try:
                root.after(0, root.destroy)
            except Exception:
                pass
            return False
        _bk_child_apply_event(app, root, event)
    flush()
    return True


_V256_BASE_MARKET_READ = _v253_market_read


def _v256_market_read(self, now=None):
    out = _V256_BASE_MARKET_READ(self, now=now)
    self._v256_market_last = dict(out or {})
    self._v256_market_last_ts = float(now or time.time())
    return out


def _v256_defended_side(self):
    try:
        side = _v238_current_defense(self)
    except Exception:
        side = 'WAIT'
    side = _v252_side(side)
    if side == 'WAIT':
        side = _v252_side(
            (getattr(self, 'opening_lock_snapshot', None) or {}).get('lock_side')
        )
    return side


def _v256_command_center_once(self, now=None):
    """Render the legacy panel exclusively from the rebuilt V21.59 engine."""
    now = float(now or time.time())
    radar = dict(getattr(self, '_v259_flip_last', {}) or {})
    defended = _v252_side(radar.get('defended'))
    attack = _v252_side(radar.get('target'))
    stage = str(radar.get('stage', 'BUILDING'))
    flip = max(0.0, min(100.0, float(radar.get('score', 0.0) or 0.0)))
    hold = 100.0 - flip
    if stage == 'FAKEOUT / RECLAIM' and attack == defended:
        hold, flip = flip, hold
    families = list(radar.get('families') or [])
    reliability = max(0.0, min(100.0, 50.0 + abs(float(radar.get('margin', 0.0) or 0.0))))
    read = {
        'ready': stage != 'BUILDING', 'defended': defended, 'attack': attack,
        'hold': hold, 'flip': flip, 'reliability': reliability,
        'stage': stage, 'hold_groups': 0, 'flip_groups': len(families),
    }
    vel = _v239_risk_velocity(self, read, now=now)
    self._v239_last_read = dict(read)
    _v256_var(
        getattr(self, 'v239_flip_headline_var', None),
        f'V21.59 FLIP ENGINE • DEFENDING {defended} • TARGET {attack} • '
        f'{len(families)} LIVE FAMILIES',
    )
    _v256_var(
        getattr(self, 'v239_flip_confidence_var', None),
        f'HOLD {hold:.0f}% • FLIP {flip:.0f}% • RELIABILITY {reliability:.0f}%',
    )
    _v256_var(getattr(self, 'v239_flip_stage_var', None), f'STAGE: {stage}')
    _v256_var(
        getattr(self, 'v239_flip_accel_var', None),
        f'{vel["label"]} • 1s {vel["v1"]:+.1f} pts/s • 3s {vel["v3"]:+.1f} pts/s',
    )
    _v239_set_family_text(
        self,
        'TWO-SIDED • AVAILABLE-FEED NORMALIZED • REAL BREAK vs RECLAIM\n'
        f'{", ".join(families) if families else "No clean opposing evidence yet"}\n'
        f'{(radar.get("liquidity") or {}).get("detail", "Liquidity map building")}',
    )
    _v256_var(
        getattr(self, 'v239_flip_explain_var', None),
        str(radar.get('detail', 'New flip engine is building live evidence.')),
    )
    try:
        canvas = getattr(self, '_v239_flip_bar', None)
        width = int(canvas.winfo_width()) if canvas is not None else 0
    except Exception:
        width = 0
    render_key = (round(hold), round(flip), width)
    last_draw = float(getattr(self, '_v256_last_flip_bar_draw', 0.0) or 0.0)
    if render_key != getattr(self, '_v256_flip_bar_key', None) or now - last_draw >= 1.5:
        self._v256_flip_bar_key = render_key
        self._v256_last_flip_bar_draw = now
        _v239_draw_flip_bar(self)


def _v256_guardian_once(self, now=None):
    now = float(now or time.time())
    market = dict(getattr(self, '_v256_market_last', {}) or {})
    side = _v256_defended_side(self)
    edge = float(market.get('signed_edge', market.get('edge', 0.0)) or 0.0)
    if side not in ('UP', 'DOWN'):
        _v256_var(getattr(self, 'v233_guardian_var', None),
                  'EDGE GUARDIAN: neutral • waiting for two independent families to agree')
        _v256_var(getattr(self, 'v233_recross_var', None),
                  'RECROSS RISK: waiting for a frozen thesis')
        return
    quote = None
    try:
        quote = _v233_exact_ask(self, side)
    except Exception:
        pass
    if quote:
        allowed, value = _v252_quote_gate(quote.get('contract'))
        entry = value if allowed else value + ' BLOCKED'
    else:
        entry = 'WAITING FOR EXACT ASK'
    distance = float(market.get('distance', 0.0) or 0.0)
    velocity = float(market.get('velocity_3s', 0.0) or 0.0)
    sign = 1.0 if side == 'UP' else -1.0
    cushion = distance * sign
    against = max(0.0, -velocity * sign)
    recross = max(0.0, min(100.0, 52.0 - cushion * 0.75 + against * 5.0))
    _v256_var(
        getattr(self, 'v233_guardian_var', None),
        f'EDGE GUARDIAN: {side} FROZEN • simple edge {edge:+.2f} • {entry}',
    )
    _v256_var(
        getattr(self, 'v233_recross_var', None),
        f'RECROSS RISK: {recross:.0f}% • side cushion {cushion:+.2f}$ • opposing drift {against:.2f}$/s',
    )


def _v256_accuracy_paper_once(self, now=None, allow_heavy=True):
    """Paper decisions stay live; hidden historical UI queries stay off Tk."""
    now = float(now or time.time())
    try:
        enabled = bool(self.auto_paper_enabled_var.get())
    except Exception:
        enabled = False
    bucket = _v233_bucket(now)
    if getattr(self, '_v256_paper_bucket', None) != bucket:
        self._v256_paper_bucket = bucket
        self._v256_opened_this_bucket = set()
        self._v256_last_mm3_check = 0.0

    # The accuracy journal remains useful, but the user-facing paper desk must
    # also own a real simulated position.  V21.57 routes only a fully qualified
    # SCALP verdict into the existing visible paper-trade implementation.
    try:
        _v257_visible_paper_once(self, now=now)
    except Exception:
        pass

    # Closed-candle pattern learning is a low-frequency storage lane. Keep it
    # off the hot 300ms flip path and pause it while scrolling/protect mode runs.
    if allow_heavy:
        try:
            _v260_pattern_memory_once(self, now=now)
        except Exception:
            pass

    if enabled:
        opened = set(getattr(self, '_v256_opened_this_bucket', set()) or set())
        for bot in ('BOOKMAP KING', 'TEAM MM3'):
            if bot in opened:
                continue
            if bot == 'TEAM MM3' and now - float(getattr(self, '_v256_last_mm3_check', 0.0) or 0.0) < 1.0:
                continue
            if bot == 'TEAM MM3':
                self._v256_last_mm3_check = now
            try:
                lock = _v233_paper_lock(self, bot, now=now)
                if lock.get('ready') and _v233_open_accuracy_paper(self, bot, lock, now=now):
                    opened.add(bot)
            except Exception:
                pass
        self._v256_opened_this_bucket = opened

    if allow_heavy and now - float(getattr(self, '_v256_last_paper_housekeeping', 0.0) or 0.0) >= 3.0:
        self._v256_last_paper_housekeeping = now
        try:
            _v233_settle_accuracy_paper(self, now=now)
            _v233_learn_completed_market(self, now=now)
        except Exception:
            pass


def _v256_chart_watchdog_once(self, now=None, allow_draw=True):
    now = float(now or time.time())
    try:
        _v255_rollover_guard(self, now=now)
    except Exception:
        pass
    if not allow_draw or bool(getattr(self, 'web_only_mode', False)):
        return False
    seconds = max(1, int(getattr(self, 'chart_interval_seconds', 900) or 900))
    expected = int(now // seconds) * seconds
    drawn = getattr(self, '_v255_last_draw_bucket', None)
    stale = now - float(getattr(self, '_v255_last_good_draw', 0.0) or 0.0) > 4.0
    wrong_bucket = drawn is not None and int(drawn) != expected
    if not (stale or wrong_bucket):
        return False
    self._last_chart_render_key = None
    self._last_live_draw = 0.0
    try:
        self.draw_chart()
        self._v255_watchdog_repairs = int(getattr(self, '_v255_watchdog_repairs', 0) or 0) + 1
        return True
    except Exception:
        return False


def _v256_pulse(self):
    """One cooperative supervisor for formerly duplicated presentation loops."""
    mono = time.monotonic()
    now = time.time()
    expected = float(getattr(self, '_v256_pulse_expected', mono) or mono)
    lag = max(0.0, mono - expected)
    self._v256_pulse_lag_ms = lag * 1000.0
    self._v256_pulse_peak_lag_ms = max(
        float(getattr(self, '_v256_pulse_peak_lag_ms', 0.0) or 0.0) * 0.997,
        lag * 1000.0,
    )
    if lag >= 0.18:
        self._v256_protect_until = max(
            float(getattr(self, '_v256_protect_until', 0.0) or 0.0),
            now + 1.5,
        )
        self._v256_lag_events = int(getattr(self, '_v256_lag_events', 0) or 0) + 1

    scrolling = now < float(getattr(self, '_scroll_active_until', 0.0) or 0.0)
    protected = now < float(getattr(self, '_v256_protect_until', 0.0) or 0.0)

    # One compact scalp/structure pass reuses already-snapshotted data.  It is
    # decision-facing, cheap, and remains live while cosmetic lanes back off.
    if now - float(getattr(self, '_v257_last_tick', 0.0) or 0.0) >= 0.30:
        self._v257_last_tick = now
        try:
            _v257_update(self, now=now)
        except Exception:
            pass

    # Position coaching is decision-critical and stays live even while the
    # cosmetic lanes are paused.  It also produces the one simple-edge market
    # read reused by the command center below.
    if now - float(getattr(self, '_v256_last_coach', 0.0) or 0.0) >= 0.50:
        self._v256_last_coach = now
        try:
            _v253_render_coach(self, now=now)
        except Exception as exc:
            try:
                self.position_coach_sync_var.set(
                    f'POSITION COACH: recovering • {str(exc)[:100]}'
                )
            except Exception:
                pass
    if now - float(getattr(self, '_v256_last_command_center', 0.0) or 0.0) >= (0.85 if scrolling else 0.50):
        self._v256_last_command_center = now
        try:
            _v256_command_center_once(self, now=now)
        except Exception:
            pass
    if now - float(getattr(self, '_v256_last_guardian', 0.0) or 0.0) >= 0.75:
        self._v256_last_guardian = now
        try:
            _v256_guardian_once(self, now=now)
        except Exception:
            pass
    if now - float(getattr(self, '_v256_last_lock_guard', 0.0) or 0.0) >= 0.50:
        self._v256_last_lock_guard = now
        try:
            _v240_restore_earned_open(self, now=now)
        except Exception:
            pass
    if now - float(getattr(self, '_v256_last_rotation_guard', 0.0) or 0.0) >= 1.0:
        self._v256_last_rotation_guard = now
        try:
            bucket = _v238_bucket(now)
            rot = dict(getattr(self, '_v238_defense_rotation', {}) or {})
            if int(rot.get('bucket', -1) or -1) != bucket:
                self._v238_defense_rotation = {}
        except Exception:
            pass
    if now - float(getattr(self, '_v256_last_accuracy_paper', 0.0) or 0.0) >= 0.75:
        self._v256_last_accuracy_paper = now
        try:
            _v256_accuracy_paper_once(
                self, now=now, allow_heavy=not scrolling and not protected
            )
        except Exception:
            pass
    if now - float(getattr(self, '_v256_last_chart_guard', 0.0) or 0.0) >= 1.0:
        self._v256_last_chart_guard = now
        try:
            _v256_chart_watchdog_once(
                self, now=now, allow_draw=not scrolling and not protected
            )
        except Exception:
            pass

    self._v256_pulse_expected = time.monotonic() + _V256_PULSE_MS / 1000.0
    try:
        self.root.after(_V256_PULSE_MS, lambda s=self: _v256_pulse(s))
    except Exception:
        pass


def _v256_legacy_noop(*_args, **_kwargs):
    """Let an already-queued legacy callback fire once, then end its chain."""
    return None


# Every lambda in the inherited init chain resolves these globals at execution
# time.  Rebinding them here terminates duplicate self-rescheduling chains after
# their one already-queued call; V21.56's single pulse owns the same duties.
_v233_guardian_tick = _v256_legacy_noop
_v233_accuracy_paper_tick = _v256_legacy_noop
_v233_wins_text_tick = _v256_legacy_noop
_v235_sticky_price_tick = _v256_legacy_noop
