_v240_lock_watchdog = _v256_legacy_noop
_v241_command_center_tick = _v256_legacy_noop
_v253_tick = _v256_legacy_noop
_v255_watchdog_tick = _v256_legacy_noop


_V256_BASE_UI_TICK = ChartKingPro._ui_tick


def _v256_ui_tick(self):
    """Protect Tk interaction while leaving the data/decision pipeline live."""
    now = time.time()
    scrolling = now < float(getattr(self, '_scroll_active_until', 0.0) or 0.0)
    protected = now < float(getattr(self, '_v256_protect_until', 0.0) or 0.0)
    if scrolling or protected:
        # These are presentation/storage lanes.  Core defense analysis and the
        # read-only position coach are deliberately not suppressed.
        self._last_right_panel_update = now
        self._last_bookmap_panel_update = now
        self._last_chart_commentary_step = now
        self._last_paper_housekeeping = now
        self._last_web_state_write = now
        if scrolling:
            self._last_live_draw = now

    started = time.perf_counter()
    try:
        return _V256_BASE_UI_TICK(self)
    finally:
        elapsed_ms = (time.perf_counter() - started) * 1000.0
        prior = float(getattr(self, '_v256_ui_ema_ms', 0.0) or 0.0)
        self._v256_ui_ema_ms = elapsed_ms if prior <= 0 else prior * 0.90 + elapsed_ms * 0.10
        self._v256_ui_peak_ms = max(
            elapsed_ms,
            float(getattr(self, '_v256_ui_peak_ms', 0.0) or 0.0) * 0.997,
        )
        if elapsed_ms >= 55.0 or self._v256_ui_ema_ms >= 28.0:
            self._v256_protect_until = max(
                float(getattr(self, '_v256_protect_until', 0.0) or 0.0),
                time.time() + 1.5,
            )


