# V21.56 HOTFIX — VISIBLE KALSHI CREDENTIAL CONTROL + LIVE CHART PRICE
#
# Presentation-only repair:
# - keeps a prominent API/private-key submit button above the crowded header;
# - routes every API button to the existing signed read-only verification UI;
# - restores a high-contrast live-price line and numeric pill on the chart;
# - does not change locks, Gainz detection, MM3, paper decisions, or execution.
# ============================================================================

def _v256_hotfix_mount_credentials(self):
    """Keep the full credential dialog one obvious click away."""
    try:
        existing = getattr(self, '_v256_hotfix_credentials_bar', None)
        if existing is not None and bool(existing.winfo_exists()):
            return True
    except Exception:
        pass

    page = getattr(self, 'page_frame', None)
    if page is None:
        return False
    try:
        bar = tk.Frame(
            page, bg=PANEL2, bd=0,
            highlightthickness=2, highlightbackground=CYAN,
        )
        children = [w for w in page.winfo_children() if w is not bar]
        before = next(
            (w for w in children if str(w.winfo_manager()) == 'pack'),
            None,
        )
        pack_args = dict(fill='x', padx=10, pady=(6, 3))
        if before is not None:
            pack_args['before'] = before
        bar.pack(**pack_args)

        button = tk.Button(
            bar,
            text='KALSHI API + PRIVATE KEY',
            command=self.open_kalshi_auth_dialog,
            bg='#17333a', fg=CYAN,
            activebackground=CYAN, activeforeground='#071013',
            relief='flat', bd=0, padx=14, pady=7,
            font=('Segoe UI Variable', 9, 'bold'), cursor='hand2',
        )
        button.pack(side='left', padx=6, pady=5)
        ttk.Label(
            bar,
            textvariable=self.kalshi_auth_status_var,
            style='Muted.Card.TLabel',
        ).pack(side='left', padx=(8, 6))
        self._v256_hotfix_credentials_bar = bar
        self.kalshi_api_private_key_button = button
        return True
    except Exception:
        return False


def _v256_hotfix_live_chart_overlay(self, price=None, source=None):
    """Draw a readable, continuously moving live-price guide on the chart."""
    c = getattr(self, 'canvas', None)
    scale = dict(getattr(self, '_v82_chart_scale', {}) or {})
    if c is None or not scale:
        return
    if price is None:
        try:
            price, source = self.effective_live_price()
        except Exception:
            return
    try:
        price = float(price)
        lo = float(scale['lo'])
        hi = float(scale['hi'])
        top = float(scale['top'])
        ph = float(scale['ph'])
        left = float(scale['left'])
        plot_right = float(scale['plot_right'])
    except Exception:
        return
    if not math.isfinite(price) or hi <= lo:
        return

    yy = top + (hi - price) / (hi - lo) * ph
    yy = max(top + 1.0, min(top + ph - 1.0, yy))
    label_y = max(top + 13.0, min(top + ph - 13.0, yy))
    label_w = max(142.0, min(205.0, (plot_right - left) * 0.30))
    label_left = max(left + 3.0, plot_right - label_w)
    source_text = str(source or 'BOOKMAP')
    source_text = 'BOOKMAP' if 'BOOKMAP' in source_text.upper() else source_text[:18]
    label = f'LIVE {money(price)}  |  {source_text}'

    items = getattr(self, '_v82_live_overlay_items', None)
    valid = False
    if items and len(items) == 4:
        try:
            valid = all(c.type(item) for item in items)
        except Exception:
            valid = False
    if not valid:
        try:
            c.delete('v82_live')
        except Exception:
            pass
        shadow = c.create_line(
            left, yy, plot_right, yy, fill='#092b31', width=5,
            tags=('v82_live', 'live_price'),
        )
        line = c.create_line(
            left, yy, plot_right, yy, fill=CYAN, width=2, dash=(7, 4),
            tags=('v82_live', 'live_price'),
        )
        pill = c.create_rectangle(
            label_left, label_y - 12, plot_right - 2, label_y + 12,
            fill='#07171b', outline=CYAN, width=2,
            tags=('v82_live', 'live_price'),
        )
        text_item = c.create_text(
            plot_right - 9, label_y, text=label, fill=CYAN, anchor='e',
            font=('Cascadia Mono', 8, 'bold'),
            tags=('v82_live', 'live_price'),
        )
        items = (shadow, line, pill, text_item)
        self._v82_live_overlay_items = items

    try:
        shadow, line, pill, text_item = items
        c.coords(shadow, left, yy, plot_right, yy)
        c.coords(line, left, yy, plot_right, yy)
        c.coords(pill, label_left, label_y - 12, plot_right - 2, label_y + 12)
        c.coords(text_item, plot_right - 9, label_y)
        c.itemconfigure(text_item, text=label)
        c.tag_raise('v82_live')
    except Exception:
        self._v82_live_overlay_items = None


# ============================================================================
# V21.57 FEATURE LAYER — ONE-VERDICT SCALP + STRUCTURE/TRAP READER
#
# Original implementation built from the bot's existing Bookmap, candle, FVG,
# and Kalshi feeds.  The scalp verdict is guidance only and never submits an
# order.  AUTO PAPER may mirror a qualified verdict into simulation.
# ============================================================================

_V257_FINAL_MUTE_SECONDS = 180.0
_V257_PAPER_CAP = 0.70


def _v257_sign(value, threshold):
    try:
        value = float(value)
    except Exception:
        return 0
    return 1 if value >= float(threshold) else -1 if value <= -float(threshold) else 0


def _v257_clean_rows(rows, limit=100):
    clean = []
    for raw in list(rows or [])[-max(8, int(limit)):]:
        try:
            row = {
                'time': float(raw.get('time', 0.0) or 0.0),
                'open': float(raw['open']), 'high': float(raw['high']),
                'low': float(raw['low']), 'close': float(raw['close']),
                'volume': float(raw.get('volume', 0.0) or 0.0),
            }
        except Exception:
            continue
        if not all(math.isfinite(row[k]) for k in ('open', 'high', 'low', 'close')):
            continue
        row['high'] = max(row['high'], row['open'], row['close'])
        row['low'] = min(row['low'], row['open'], row['close'])
        clean.append(row)
    return clean


def _v257_candle_confirmation(rows, demand, supply):
    """Recognize the demand/supply confirmations shown in the references."""
    if len(rows) < 4:
        return {'side': 'WAIT', 'name': 'BUILDING', 'strength': 0}
    a, b, c = rows[-3], rows[-2], rows[-1]
    rng = max(c['high'] - c['low'], 1e-9)
    body = abs(c['close'] - c['open'])
    upper = c['high'] - max(c['open'], c['close'])
    lower = min(c['open'], c['close']) - c['low']
    at_demand = c['low'] <= float(demand['high']) and c['close'] >= float(demand['low'])
    at_supply = c['high'] >= float(supply['low']) and c['close'] <= float(supply['high'])
    bull_engulf = b['close'] < b['open'] and c['close'] > c['open'] and c['close'] >= b['open'] and c['open'] <= b['close']
    bear_engulf = b['close'] > b['open'] and c['close'] < c['open'] and c['close'] <= b['open'] and c['open'] >= b['close']
    bull_pin = c['close'] > c['open'] and lower >= max(body * 1.4, rng * 0.42)
    bear_pin = c['close'] < c['open'] and upper >= max(body * 1.4, rng * 0.42)
    morning = a['close'] < a['open'] and abs(b['close'] - b['open']) <= max(a['high'] - a['low'], 1e-9) * 0.35 and c['close'] > c['open'] and c['close'] >= (a['open'] + a['close']) / 2.0
    evening = a['close'] > a['open'] and abs(b['close'] - b['open']) <= max(a['high'] - a['low'], 1e-9) * 0.35 and c['close'] < c['open'] and c['close'] <= (a['open'] + a['close']) / 2.0
    three_up = all(x['close'] > x['open'] for x in (a, b, c)) and a['close'] < b['close'] < c['close']
    three_down = all(x['close'] < x['open'] for x in (a, b, c)) and a['close'] > b['close'] > c['close']
    if at_demand:
        if morning:
            return {'side': 'UP', 'name': 'MORNING STAR @ DEMAND', 'strength': 3}
        if bull_engulf:
            return {'side': 'UP', 'name': 'BULLISH ENGULFING @ DEMAND', 'strength': 3}
        if bull_pin:
            return {'side': 'UP', 'name': 'BULLISH PIN BAR @ DEMAND', 'strength': 2}
        if three_up:
            return {'side': 'UP', 'name': 'THREE SOLDIERS @ DEMAND', 'strength': 3}
    if at_supply:
        if evening:
            return {'side': 'DOWN', 'name': 'EVENING STAR @ SUPPLY', 'strength': 3}
        if bear_engulf:
            return {'side': 'DOWN', 'name': 'BEARISH ENGULFING @ SUPPLY', 'strength': 3}
        if bear_pin:
            return {'side': 'DOWN', 'name': 'BEARISH PIN BAR @ SUPPLY', 'strength': 2}
        if three_down:
            return {'side': 'DOWN', 'name': 'THREE SOLDIERS DOWN @ SUPPLY', 'strength': 3}
    return {'side': 'WAIT', 'name': 'NO ZONE CONFIRMATION', 'strength': 0}


def _v257_structure_read(self, rows=None, market=None):
    """Separate acceptance, retest, likely break, and liquidity-sweep fakeout."""
    rows = _v257_clean_rows(rows if rows is not None else self._chart_candles(), 100)
    if len(rows) < 12:
        return {'ready': False, 'class': 'BUILDING', 'side': 'WAIT', 'score': 0.0,
                'detail': 'Need at least 12 candles for demand/supply structure.'}
    market = dict(market or getattr(self, '_v256_market_last', {}) or {})
    # Freeze the level map before the last three candles.  Otherwise the very
    # candle testing resistance/support would move the level and make genuine
    # break + retest recognition mathematically impossible.
    prior = rows[-27:-3]
    if len(prior) < 6:
        prior = rows[:-3]
    tr = _v254_true_ranges(rows)
    atr = max(0.01, sum(tr[-14:]) / min(14, len(tr)))
    median_range = max(0.01, _v254_median(tr[-24:])) if '_v254_median' in globals() else max(0.01, sorted(tr[-24:])[len(tr[-24:]) // 2])
    width = max(atr * 0.14, median_range * 0.10)

    highs = [r['high'] for r in prior]
    lows = [r['low'] for r in prior]
    resistance = max(highs[-14:])
    support = min(lows[-14:])
    supply = {'low': resistance - width, 'high': resistance + width * 0.35, 'mid': resistance}
    demand = {'low': support - width * 0.35, 'high': support + width, 'mid': support}

    c, p = rows[-1], rows[-2]
    rng = max(c['high'] - c['low'], 1e-9)
    body_quality = abs(c['close'] - c['open']) / rng
    close_pos = (c['close'] - c['low']) / rng
    velocity = float(market.get('velocity_3s', 0.0) or 0.0)
    flow = float(market.get('signed_edge', market.get('edge', 0.0)) or 0.0)
    momentum = (c['close'] - rows[-4]['close']) / atr
    up_agree = sum((velocity >= 0.10, flow >= 0.16, momentum >= 0.16, close_pos >= 0.68))
    down_agree = sum((velocity <= -0.10, flow <= -0.16, momentum <= -0.16, close_pos <= 0.32))

    upside_sweep = c['high'] > supply['high'] and c['close'] < supply['low']
    downside_sweep = c['low'] < demand['low'] and c['close'] > demand['high']
    upside_failed = p['close'] > supply['high'] and c['close'] < supply['low']
    downside_failed = p['close'] < demand['low'] and c['close'] > demand['high']
    up_accept = (
        (p['close'] > supply['high'] and c['close'] > supply['high'])
        or (c['close'] > supply['high'] + atr * 0.08 and body_quality >= 0.56 and up_agree >= 3)
    )
    down_accept = (
        (p['close'] < demand['low'] and c['close'] < demand['low'])
        or (c['close'] < demand['low'] - atr * 0.08 and body_quality >= 0.56 and down_agree >= 3)
    )
    up_retest = p['close'] > supply['high'] and c['low'] <= supply['high'] and c['close'] > supply['high']
    down_retest = p['close'] < demand['low'] and c['high'] >= demand['low'] and c['close'] < demand['low']
    near_supply = c['high'] >= supply['low'] - atr * 0.10
    near_demand = c['low'] <= demand['high'] + atr * 0.10
    up_likely = near_supply and c['close'] <= supply['high'] and up_agree == 4
    down_likely = near_demand and c['close'] >= demand['low'] and down_agree == 4
    confirm = _v257_candle_confirmation(rows, demand, supply)

    klass, side, score = 'RANGE / LEVELS HOLDING', 'WAIT', 35.0
    if upside_sweep or upside_failed:
        klass, side, score = 'BULL TRAP / UPSIDE FAKEOUT', 'DOWN', 92.0 if down_agree >= 2 else 82.0
    elif downside_sweep or downside_failed:
        klass, side, score = 'BEAR TRAP / DOWNSIDE FAKEOUT', 'UP', 92.0 if up_agree >= 2 else 82.0
    elif up_retest:
        klass, side, score = 'UPSIDE BREAK + RETEST HELD', 'UP', 94.0
    elif down_retest:
        klass, side, score = 'DOWNSIDE BREAK + RETEST HELD', 'DOWN', 94.0
    elif up_accept:
        klass, side, score = 'CLEAN UPSIDE BREAKOUT', 'UP', 86.0 + min(10.0, up_agree * 2.0)
    elif down_accept:
        klass, side, score = 'CLEAN DOWNSIDE BREAKOUT', 'DOWN', 86.0 + min(10.0, down_agree * 2.0)
    elif up_likely:
        klass, side, score = 'RESISTANCE BREAK LIKELY', 'UP', 72.0
    elif down_likely:
        klass, side, score = 'SUPPORT BREAK LIKELY', 'DOWN', 72.0
    elif confirm['side'] in ('UP', 'DOWN'):
        klass, side, score = confirm['name'], confirm['side'], 68.0 + confirm['strength'] * 6.0

    # Weak pullback into supply during a downtrend is the bearish complex
    # pullback shown in the reference: retrace, stall, then rejection.
    ema9 = _v254_ema([r['close'] for r in rows], 9)[-1]
    ema21 = _v254_ema([r['close'] for r in rows], 21)[-1]
    weak_pullback = (
        ema9 < ema21 and near_supply and c['close'] < c['open']
        and p['close'] >= rows[-3]['close'] and body_quality >= 0.42
    )
    if weak_pullback and klass == 'RANGE / LEVELS HOLDING':
        klass, side, score = 'BEARISH COMPLEX PULLBACK @ SUPPLY', 'DOWN', 78.0

    detail = (
        f'{klass} • demand {money(demand["low"])}–{money(demand["high"])} • '
        f'supply {money(supply["low"])}–{money(supply["high"])} • '
        f'acceptance UP {up_agree}/4 DOWN {down_agree}/4 • {confirm["name"]}'
    )
    return {
        'ready': True, 'class': klass, 'side': side, 'score': min(100.0, score),
        'support': support, 'resistance': resistance, 'demand': demand,
        'supply': supply, 'atr': atr, 'up_agree': up_agree,
        'down_agree': down_agree, 'confirmation': confirm, 'detail': detail,
    }


def _v257_kalshi_move(self, now):
    tape = getattr(self, '_v257_kalshi_tape', None)
    if tape is None:
        tape = deque(maxlen=120)
        self._v257_kalshi_tape = tape
    try:
        yes = self.kalshi_yes_price()
        yes = None if yes is None else float(yes)
    except Exception:
        yes = None
    if yes is not None and 0.0 < yes < 1.0:
        tape.append((float(now), yes))
    while tape and float(now) - float(tape[0][0]) > 20.0:
        tape.popleft()
    if not tape:
        return {'ready': False, 'delta3': 0.0, 'delta8': 0.0, 'side': 0}

    def older(age):
        choices = [row for row in tape if float(row[0]) <= float(now) - age]
        return choices[-1][1] if choices else None
    old3 = older(2.5)
    old8 = older(6.5)
    current = float(tape[-1][1])
    delta3 = 0.0 if old3 is None else current - float(old3)
    delta8 = 0.0 if old8 is None else current - float(old8)
    signed = delta3 * 0.72 + delta8 * 0.28
    return {'ready': old3 is not None, 'delta3': delta3, 'delta8': delta8,
            'side': _v257_sign(signed, 0.0045), 'yes': current}


def _v257_scalp_read(self, now=None):
    """One verdict; pace, flow, momentum, weather and Kalshi must agree."""
    now = float(now or time.time())
    seconds_left = max(0.0, 900.0 - now % 900.0)
    market = dict(getattr(self, '_v256_market_last', {}) or {})
    wave = dict(getattr(self, 'bookmap_wave_last', {}) or {})
    try:
        rows = list(getattr(self, 'btc_1m', []) or [])
        current = self._current_bucket_for_interval(60)
        if current:
            rows = [dict(r) for r in rows if int(r.get('time', 0)) < int(current['time'])] + [dict(current)]
    except Exception:
        rows = list(getattr(self, 'btc_1m', []) or [])
    rows = _v257_clean_rows(rows, 80)
    structure = _v257_structure_read(self, rows=rows, market=market)
    self._v257_structure_last = dict(structure)

    if len(rows) < 8:
        return {'verdict': 'WAIT', 'side': 'WAIT', 'score': 0.0, 'hard_wait': True,
                'detail': 'WAIT • momentum candles still building', 'structure': structure}
    tr = _v254_true_ranges(rows)
    atr = max(0.01, sum(tr[-14:]) / min(14, len(tr)))
    momentum = (rows[-1]['close'] - rows[-4]['close']) / atr
    pace = float(market.get('velocity_3s', 0.0) or 0.0)
    if abs(pace) < 0.01:
        pace = float(wave.get('move_2s_bp', 0.0) or 0.0) * 0.45
    flow = 0.68 * float(wave.get('flow_2s', 0.0) or 0.0) + 0.32 * float(wave.get('flow_6s', 0.0) or 0.0)
    if abs(flow) < 0.01:
        flow = float(market.get('signed_edge', market.get('edge', 0.0)) or 0.0)
    kalshi = _v257_kalshi_move(self, now)
    pace_side = _v257_sign(pace, 0.10)
    flow_side = _v257_sign(flow, 0.12)
    momentum_side = _v257_sign(momentum, 0.16)
    kalshi_side = int(kalshi.get('side', 0) or 0)

    recent_ratio = tr[-1] / max(0.01, sorted(tr[-20:])[len(tr[-20:]) // 2])
    risk_text = ' '.join((
        str((getattr(self, 'last_signal', {}) or {}).get('risk', '')),
        str((getattr(self, 'last_signal', {}) or {}).get('regime', '')),
    )).upper()
    feed_age = now - float(getattr(self, 'bookmap_last_event_ts', now) or now)
    bad_reasons = []
    if seconds_left <= _V257_FINAL_MUTE_SECONDS:
        bad_reasons.append('FINAL 3 MINUTES')
    if 'WHIPSAW' in risk_text or 'CHOP' in risk_text:
        bad_reasons.append('CHOP/WHIPSAW')
    if recent_ratio < 0.30:
        bad_reasons.append('DEAD PACE')
    elif recent_ratio > 3.40:
        bad_reasons.append('VOLATILITY SHOCK')
    if bool(getattr(self, 'bookmap_connected', False)) and feed_age > 2.0:
        bad_reasons.append('STALE BOOKMAP')
    if int(market.get('oppose', 0) or 0) >= 2:
        bad_reasons.append('CONFLICTING FAMILIES')
    if structure.get('class') in ('BULL TRAP / UPSIDE FAKEOUT', 'BEAR TRAP / DOWNSIDE FAKEOUT'):
        trap_sign = 1 if structure.get('side') == 'UP' else -1
        if pace_side and pace_side != trap_sign:
            bad_reasons.append('TRAP CONFLICT')
    weather_good = not bad_reasons
    sides = (pace_side, flow_side, momentum_side, kalshi_side)
    agreed = sides[0] if all(side != 0 and side == sides[0] for side in sides) else 0

    raw_side = 'UP' if agreed > 0 else 'DOWN' if agreed < 0 else 'WAIT'
    if raw_side != 'WAIT' and structure.get('side') in ('UP', 'DOWN') and structure.get('score', 0) >= 82 and structure.get('side') != raw_side:
        bad_reasons.append(f'{structure.get("class")} OPPOSES')
        weather_good = False
    if not kalshi.get('ready'):
        bad_reasons.append('KALSHI MOVEMENT BUILDING')
        weather_good = False

    if raw_side == 'WAIT' or not weather_good:
        self._v257_scalp_candidate = None
        self._v257_scalp_candidate_since = 0.0
        reason = ', '.join(bad_reasons) if bad_reasons else 'inputs do not all agree'
        return {
            'verdict': 'WAIT', 'side': 'WAIT', 'score': 0.0, 'hard_wait': bool(bad_reasons),
            'detail': f'WAIT • {reason} • pace {pace_side:+d} flow {flow_side:+d} momentum {momentum_side:+d} Kalshi {kalshi_side:+d}',
            'structure': structure, 'weather': 'BAD' if bad_reasons else 'MIXED',
            'seconds_left': seconds_left, 'kalshi': kalshi,
        }

    if getattr(self, '_v257_scalp_candidate', None) != raw_side:
        self._v257_scalp_candidate = raw_side
        self._v257_scalp_candidate_since = now
    held = now - float(getattr(self, '_v257_scalp_candidate_since', now) or now)
    if held < 0.65:
        return {
            'verdict': 'WAIT', 'side': 'WAIT', 'score': 55.0,
            'detail': f'WAIT • {raw_side} alignment confirming {held:.1f}/0.7s',
            'structure': structure, 'weather': 'GOOD', 'seconds_left': seconds_left,
            'kalshi': kalshi,
        }
    strength = min(99.0, 70.0 + min(9.0, abs(pace) * 4.0) + min(8.0, abs(flow) * 12.0) + min(7.0, abs(momentum) * 5.0) + min(5.0, abs(float(kalshi.get('delta3', 0.0))) * 300.0))
    verdict = f'SCALP {raw_side} ' + ('▲' if raw_side == 'UP' else '▼')
    return {
        'verdict': verdict, 'side': raw_side, 'score': strength, 'hard_wait': False,
        'detail': f'{verdict} • {strength:.0f}/100 • pace, flow, momentum, weather + Kalshi agree • guidance only',
        'structure': structure, 'weather': 'GOOD', 'seconds_left': seconds_left,
        'kalshi': kalshi,
    }


def _v258_liquidity_read(rows, target='WAIT'):
    """Map resting equal-high/low pools and separate grabs from accepted breaks."""
    rows = _v257_clean_rows(rows, 80)
    target = _v252_side(target)
    if len(rows) < 12:
        return {'ready': False, 'state': 'BUILDING', 'side': 'WAIT', 'score': 0.0}
    tr = _v254_true_ranges(rows)
    atr = max(0.01, sum(tr[-14:]) / min(14, len(tr)))
    tolerance = max(atr * 0.14, 0.01)
    history = rows[-30:-2]

    def clustered(values, high=True):
        ordered = sorted(values, reverse=high)
        for anchor in ordered:
            group = [v for v in values if abs(v - anchor) <= tolerance]
            if len(group) >= 2:
                return sum(group) / len(group), len(group)
        return (max(values) if high else min(values)), 1

    buy_pool, buy_touches = clustered([r['high'] for r in history], True)
    sell_pool, sell_touches = clustered([r['low'] for r in history], False)
    c, p = rows[-1], rows[-2]
    cr = max(c['high'] - c['low'], 1e-9)
    cb = abs(c['close'] - c['open'])
    upper = c['high'] - max(c['open'], c['close'])
    lower = min(c['open'], c['close']) - c['low']

    buy_run = c['high'] > buy_pool + tolerance * 0.20
    sell_run = c['low'] < sell_pool - tolerance * 0.20
    buy_reclaim = buy_run and c['close'] < buy_pool
    sell_reclaim = sell_run and c['close'] > sell_pool
    buy_accept = p['close'] > buy_pool + tolerance and c['close'] > buy_pool + tolerance
    sell_accept = p['close'] < sell_pool - tolerance and c['close'] < sell_pool - tolerance
    near_buy = 0.0 <= buy_pool - c['close'] <= atr * 0.35
    near_sell = 0.0 <= c['close'] - sell_pool <= atr * 0.35
    buy_stall = near_buy and buy_touches >= 2 and upper >= max(cb * 0.75, cr * 0.25) and c['close'] <= p['close'] + atr * 0.05
    sell_stall = near_sell and sell_touches >= 2 and lower >= max(cb * 0.75, cr * 0.25) and c['close'] >= p['close'] - atr * 0.05

    side, state, score = 'WAIT', 'LIQUIDITY POOLS MAPPED', 0.0
    if buy_accept:
        side, state, score = 'UP', 'BUY-SIDE LIQUIDITY BREAK ACCEPTED', 88.0
    elif sell_accept:
        side, state, score = 'DOWN', 'SELL-SIDE LIQUIDITY BREAK ACCEPTED', 88.0
    elif buy_reclaim:
        side, state, score = 'DOWN', 'BUY-SIDE SWEEP + RECLAIM', 94.0
    elif sell_reclaim:
        side, state, score = 'UP', 'SELL-SIDE SWEEP + RECLAIM', 94.0
    elif buy_run:
        side, state, score = 'DOWN', 'BUY-SIDE SWEEP IN PROGRESS', 78.0
    elif sell_run:
        side, state, score = 'UP', 'SELL-SIDE SWEEP IN PROGRESS', 78.0
    elif buy_stall:
        side, state, score = 'DOWN', 'BUY-SIDE LIQUIDITY GRAB SETUP', 62.0
    elif sell_stall:
        side, state, score = 'UP', 'SELL-SIDE LIQUIDITY GRAB SETUP', 62.0
    aligned = side == target
    detail = (f'{state} • buy pool {money(buy_pool)} ({buy_touches} touches) • '
              f'sell pool {money(sell_pool)} ({sell_touches} touches)')
    return {'ready': True, 'state': state, 'side': side, 'score': score,
            'aligned': aligned, 'buy_pool': buy_pool, 'sell_pool': sell_pool,
            'buy_touches': buy_touches, 'sell_touches': sell_touches,
            'accepted': 'ACCEPTED' in state, 'reclaimed': 'RECLAIM' in state,
            'detail': detail}


def _v260_single_candle_catalog(rows):
    """Classify the 11 single-candle shapes with trend-aware meaning."""
    rows = _v257_clean_rows(rows, 40)
    if len(rows) < 4:
        return []
    s = _v232_candle_shape(rows[-1])
    prior = rows[-8:-1]
    avg_range = sum(max(r['high'] - r['low'], 1e-9) for r in prior) / max(len(prior), 1)
    trend_move = (prior[-1]['close'] - prior[0]['close']) / max(avg_range, 1e-9)
    trend = 1 if trend_move >= 0.55 else -1 if trend_move <= -0.55 else 0
    out = []

    def add(name, bias, role, quality, note):
        out.append({'name': name, 'bias': int(bias), 'role': role,
                    'quality': float(quality), 'trend_before': trend,
                    'trend_move': float(trend_move), 'body_frac': s['body_frac'],
                    'upper_frac': s['upper_frac'], 'lower_frac': s['lower_frac'],
                    'note': note})

    doji = s['body_frac'] <= 0.10
    if doji:
        if s['lower_frac'] >= 0.58 and s['upper_frac'] <= 0.12:
            add('DRAGONFLY DOJI', 1, 'REVERSAL', 0.72,
                'Lower-price rejection; bullish only with decline/demand/reclaim context.')
        elif s['upper_frac'] >= 0.58 and s['lower_frac'] <= 0.12:
            add('GRAVESTONE DOJI', -1, 'REVERSAL', 0.72,
                'Higher-price rejection; bearish only with advance/supply/reclaim context.')
        elif s['upper_frac'] >= 0.28 and s['lower_frac'] >= 0.28:
            add('LONG-LEGGED DOJI', 0, 'INDECISION', 0.54,
                'Two-sided rejection; direction must come from the next break.')
        else:
            add('DOJI', 0, 'INDECISION', 0.46,
                'Balanced open/close; transition evidence, never a direction by itself.')
        return out

    if s['body_frac'] >= 0.78 and s['upper_frac'] <= 0.12 and s['lower_frac'] <= 0.12:
        add('BULLISH MARUBOZU' if s['bull'] else 'BEARISH MARUBOZU',
            1 if s['bull'] else -1, 'CONTINUATION', 0.78,
            'Directional acceptance candle; reversal only if it confirms other setup evidence.')
    if 0.10 < s['body_frac'] <= 0.32 and s['upper_frac'] >= 0.22 and s['lower_frac'] >= 0.22:
        add('SPINNING TOP', 0, 'INDECISION', 0.48,
            'Compression/indecision; wait for directional confirmation.')
    long_lower = s['lower'] >= max(s['body'] * 2.0, s['range'] * 0.50) and s['upper_frac'] <= 0.20
    long_upper = s['upper'] >= max(s['body'] * 2.0, s['range'] * 0.50) and s['lower_frac'] <= 0.20
    if long_lower:
        if trend < 0:
            add('HAMMER', 1, 'REVERSAL', 0.74, 'Bullish reversal candidate after a decline.')
        elif trend > 0:
            add('HANGING MAN', -1, 'REVERSAL', 0.66, 'Bearish exhaustion candidate after an advance.')
    if long_upper:
        if trend < 0:
            add('INVERTED HAMMER', 1, 'REVERSAL', 0.64, 'Bullish reversal candidate after a decline.')
        elif trend > 0:
            add('SHOOTING STAR', -1, 'REVERSAL', 0.74, 'Bearish rejection after an advance.')
    return out


def _v260_init_pattern_memory(self):
    """Migrate a context-rich, outcome-settled candlestick memory table."""
    try:
        with self.stockpile_db_lock:
            with self._stockpile_connect() as conn:
                conn.execute('''
                    CREATE TABLE IF NOT EXISTS v260_candle_reversal_memory (
                        timeframe INTEGER NOT NULL,
                        candle_ts INTEGER NOT NULL,
                        pattern TEXT NOT NULL,
                        bias INTEGER NOT NULL,
                        role TEXT NOT NULL,
                        observed_ts REAL,
                        observed_price REAL,
                        atr REAL,
                        body_frac REAL,
                        upper_frac REAL,
                        lower_frac REAL,
                        trend_before INTEGER,
                        trend_move REAL,
                        location TEXT,
                        liquidity_state TEXT,
                        structure_state TEXT,
                        flip_stage TEXT,
                        outcome_1_atr REAL,
                        outcome_3_atr REAL,
                        result_1 TEXT,
                        result_3 TEXT,
                        PRIMARY KEY (timeframe, candle_ts, pattern)
                    )
                ''')
                conn.execute('''
                    CREATE TABLE IF NOT EXISTS v260_candle_pattern_catalog (
                        pattern TEXT PRIMARY KEY,
                        bias INTEGER NOT NULL,
                        role TEXT NOT NULL,
                        geometry TEXT NOT NULL,
                        best_context TEXT NOT NULL
                    )
                ''')
                catalog = (
                    ('HAMMER', 1, 'REVERSAL', 'long lower wick; compact body near high', 'after decline at demand/sell-side sweep'),
                    ('INVERTED HAMMER', 1, 'REVERSAL', 'long upper wick; compact body near low', 'after decline with bullish confirmation'),
                    ('HANGING MAN', -1, 'REVERSAL', 'long lower wick; compact body near high', 'after advance at supply'),
                    ('SHOOTING STAR', -1, 'REVERSAL', 'long upper wick; compact body near low', 'after advance at supply/buy-side sweep'),
                    ('DOJI', 0, 'INDECISION', 'open approximately equals close', 'requires next directional break'),
                    ('DRAGONFLY DOJI', 1, 'REVERSAL', 'doji body near high; long lower wick', 'after decline at demand'),
                    ('GRAVESTONE DOJI', -1, 'REVERSAL', 'doji body near low; long upper wick', 'after advance at supply'),
                    ('LONG-LEGGED DOJI', 0, 'INDECISION', 'doji with long upper and lower wicks', 'two-sided rejection; wait'),
                    ('BULLISH MARUBOZU', 1, 'CONTINUATION', 'large bull body with minimal wicks', 'directional acceptance'),
                    ('BEARISH MARUBOZU', -1, 'CONTINUATION', 'large bear body with minimal wicks', 'directional acceptance'),
                    ('SPINNING TOP', 0, 'INDECISION', 'small body with upper and lower wicks', 'compression; wait for confirmation'),
                )
                conn.executemany(
                    'INSERT OR REPLACE INTO v260_candle_pattern_catalog VALUES (?,?,?,?,?)',
                    catalog,
                )
                conn.execute('CREATE INDEX IF NOT EXISTS idx_v260_pattern_result ON v260_candle_reversal_memory(pattern,bias,result_3)')
        self._v260_pattern_stats = {}
        self._v260_last_pattern_scan = 0.0
        self._v260_last_closed_by_tf = {}
    except Exception:
        self._v260_pattern_stats = {}


def _v260_pattern_location(rows, structure, liquidity):
    if not rows:
        return 'UNKNOWN'
    c = rows[-1]
    demand = dict((structure or {}).get('demand') or {})
    supply = dict((structure or {}).get('supply') or {})
    if demand and c['low'] <= float(demand.get('high', c['low'])) and c['high'] >= float(demand.get('low', c['high'])):
        return 'DEMAND'
    if supply and c['high'] >= float(supply.get('low', c['high'])) and c['low'] <= float(supply.get('high', c['low'])):
        return 'SUPPLY'
    state = str((liquidity or {}).get('state', ''))
    if 'BUY-SIDE' in state:
        return 'BUY-SIDE LIQUIDITY'
    if 'SELL-SIDE' in state:
        return 'SELL-SIDE LIQUIDITY'
    return 'MID-RANGE'


def _v260_pattern_memory_once(self, now=None):
    """Store each newly closed pattern and settle its 1/3-bar outcome."""
    now = float(now or time.time())
    if now - float(getattr(self, '_v260_last_pattern_scan', 0.0) or 0.0) < 2.0:
        return False
    self._v260_last_pattern_scan = now
    inserts = []
    histories = {}
    completed = {}
    for sec in (15, 30, 60, 180, 300, 900):
        try:
            rows = [r for r in _v257_clean_rows(self._history_for_interval(sec), 120) if r['time'] + sec <= now]
        except Exception:
            rows = []
        if len(rows) < 8:
            continue
        histories[sec] = rows
        candle_ts = int(rows[-1]['time'])
        if int((getattr(self, '_v260_last_closed_by_tf', {}) or {}).get(sec, -1)) == candle_ts:
            continue
        completed[sec] = candle_ts
        structure = _v257_structure_read(self, rows=rows)
        liquidity = _v258_liquidity_read(rows)
        location = _v260_pattern_location(rows, structure, liquidity)
        atr = max(0.01, sum(_v254_true_ranges(rows)[-14:]) / min(14, len(rows)))
        flip_stage = str((getattr(self, '_v259_flip_last', {}) or {}).get('stage', 'BUILDING'))
        for pat in _v260_single_candle_catalog(rows):
            inserts.append((sec, candle_ts, pat['name'], pat['bias'], pat['role'], now,
                            rows[-1]['close'], atr, pat['body_frac'], pat['upper_frac'],
                            pat['lower_frac'], pat['trend_before'], pat['trend_move'], location,
                            str(liquidity.get('state', '')), str(structure.get('class', '')), flip_stage))
    try:
        with self.stockpile_db_lock:
            with self._stockpile_connect() as conn:
                if inserts:
                    conn.executemany('''
                        INSERT OR IGNORE INTO v260_candle_reversal_memory (
                            timeframe,candle_ts,pattern,bias,role,observed_ts,observed_price,atr,
                            body_frac,upper_frac,lower_frac,trend_before,trend_move,location,
                            liquidity_state,structure_state,flip_stage
                        ) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)
                    ''', inserts)
                pending = conn.execute('''
                    SELECT timeframe,candle_ts,pattern,bias,observed_price,atr
                    FROM v260_candle_reversal_memory
                    WHERE result_3 IS NULL
                    ORDER BY candle_ts DESC LIMIT 300
                ''').fetchall()
                for sec, candle_ts, pattern, bias, observed, atr in pending:
                    series = histories.get(int(sec))
                    if not series:
                        continue
                    index = next((i for i, row in enumerate(series) if int(row['time']) == int(candle_ts)), None)
                    if index is None:
                        continue
                    values = []
                    for bars in (1, 3):
                        if index + bars >= len(series) or int(series[index + bars]['time']) != int(candle_ts) + bars * int(sec):
                            values.extend((None, None))
                            continue
                        move = (float(series[index + bars]['close']) - float(observed)) / max(float(atr), 0.01)
                        directed = move * int(bias) if int(bias) else abs(move)
                        result = 'HIT' if int(bias) and directed >= 0.18 else 'FAILED' if int(bias) and directed <= -0.18 else 'MIXED'
                        values.extend((directed, result))
                    conn.execute('''
                        UPDATE v260_candle_reversal_memory
                        SET outcome_1_atr=COALESCE(?,outcome_1_atr), result_1=COALESCE(?,result_1),
                            outcome_3_atr=COALESCE(?,outcome_3_atr), result_3=COALESCE(?,result_3)
                        WHERE timeframe=? AND candle_ts=? AND pattern=?
                    ''', (values[0], values[1], values[2], values[3], sec, candle_ts, pattern))
                stats = conn.execute('''
                    SELECT pattern,bias,COUNT(*),
                           AVG(CASE WHEN result_3='HIT' THEN 1.0 WHEN result_3='FAILED' THEN 0.0 ELSE 0.5 END)
                    FROM v260_candle_reversal_memory WHERE result_3 IS NOT NULL AND bias != 0
                    GROUP BY pattern,bias
                ''').fetchall()
        self._v260_last_closed_by_tf.update(completed)
        self._v260_pattern_stats = {(str(n), int(b)): {'n': int(count), 'hit_rate': float(rate if rate is not None else 0.5)}
                                    for n, b, count, rate in stats}
        return bool(inserts)
    except Exception:
        return False


def _v260_pattern_signal(self, rows, target, structure=None, liquidity=None):
    """Return a cautious current-pattern vote, improved by settled local history."""
    target = _v252_side(target)
    sign = 1 if target == 'UP' else -1 if target == 'DOWN' else 0
    patterns = _v260_single_candle_catalog(rows)
    aligned = [p for p in patterns if int(p.get('bias', 0)) == sign]
    if not aligned:
        return {'strength': 0.0, 'names': [p['name'] for p in patterns], 'n': 0, 'hit_rate': 0.5}
    best = max(aligned, key=lambda p: p['quality'])
    stats = dict((getattr(self, '_v260_pattern_stats', {}) or {}).get((best['name'], sign), {}) or {})
    n = int(stats.get('n', 0) or 0)
    hit = float(stats.get('hit_rate', 0.5))
    learned = ((hit * n) + 0.5 * 8.0) / (n + 8.0)
    context = _v260_pattern_location(rows, structure or {}, liquidity or {})
    location_boost = 0.10 if ((sign > 0 and ('DEMAND' in context or 'SELL-SIDE' in context))
                              or (sign < 0 and ('SUPPLY' in context or 'BUY-SIDE' in context))) else 0.0
    strength = max(0.0, min(1.0, best['quality'] * 0.62 + learned * 0.28 + location_boost))
    return {'strength': strength, 'names': [p['name'] for p in aligned], 'pattern': best['name'],
            'n': n, 'hit_rate': hit, 'location': context, 'role': best['role']}


def _v259_flip_radar_read(self, now=None, rows=None, market=None, structure=None, kalshi=None):
    """Independent two-sided early flip detector and real/fakeout classifier.

    Unlike V21.58, this does not require an opening lock, four simultaneous
    families, a ready Kalshi tape, or a completed one-minute breakout candle.
    It scores both hypotheses against available evidence, while acceptance and
    reclaim remain mutually exclusive classification triggers.
    """
    now = float(now or time.time())
    market = dict(market or getattr(self, '_v256_market_last', {}) or {})
    wave = dict(getattr(self, 'bookmap_wave_last', {}) or {})
    if rows is None:
        try:
            rows = list(getattr(self, 'btc_1m', []) or [])
            current = self._current_bucket_for_interval(60)
            if current:
                rows = [dict(r) for r in rows if int(r.get('time', 0)) < int(current['time'])] + [dict(current)]
        except Exception:
            rows = list(getattr(self, 'btc_1m', []) or [])
    rows = _v257_clean_rows(rows, 80)
    structure = dict(structure or getattr(self, '_v257_structure_last', {}) or {})
    if not structure.get('ready') and len(rows) >= 12:
        structure = _v257_structure_read(self, rows=rows, market=market)
    kalshi = dict(kalshi or _v257_kalshi_move(self, now))

    if len(rows) < 8:
        return {'stage': 'BUILDING', 'side': 'WAIT', 'target': 'WAIT', 'defended': 'WAIT',
                'score': 0.0, 'families': [], 'detail': 'FLIP ENGINE • building live candle context'}

    defended = _v256_defended_side(self)
    closes = [r['close'] for r in rows]
    tr = _v254_true_ranges(rows)
    atr = max(0.01, sum(tr[-14:]) / min(14, len(tr)))
    if defended == 'WAIT':
        slope = (closes[-1] - closes[-6]) / atr
        defended = 'UP' if slope >= 0.35 else 'DOWN' if slope <= -0.35 else _v252_side(market.get('side'))

    # Live feature history makes acceleration visible before a candle closes.
    pace = float(market.get('velocity_3s', 0.0) or 0.0)
    fast_pace = float(market.get('velocity_1s', pace) or pace)
    if abs(pace) < 0.01:
        pace = float(wave.get('move_2s_bp', 0.0) or 0.0) * 0.45
    flow = 0.68 * float(wave.get('flow_2s', 0.0) or 0.0) + 0.32 * float(wave.get('flow_6s', 0.0) or 0.0)
    if abs(flow) < 0.01:
        flow = float(market.get('signed_edge', market.get('edge', 0.0)) or 0.0)
    edge = float(market.get('signed_edge', market.get('edge', 0.0)) or 0.0)
    tape = getattr(self, '_v259_flip_tape', None)
    if tape is None:
        tape = deque(maxlen=48)
        self._v259_flip_tape = tape
    tape.append((now, pace, fast_pace, flow, edge))
    while tape and now - float(tape[0][0]) > 8.0:
        tape.popleft()
    old = next((x for x in tape if now - float(x[0]) >= 1.2), tape[0])
    pace_accel = pace - float(old[1])
    flow_accel = flow - float(old[3])

    c, p, q = rows[-1], rows[-2], rows[-3]
    cr = max(c['high'] - c['low'], 1e-9)
    cb = abs(c['close'] - c['open'])
    pb = abs(p['close'] - p['open'])
    qb = abs(q['close'] - q['open'])
    upper = c['high'] - max(c['open'], c['close'])
    lower = min(c['open'], c['close']) - c['low']
    shrinking = cb <= max(pb, 1e-9) * 0.72 and pb <= max(qb, 1e-9) * 1.15
    candle_momentum = (c['close'] - rows[-4]['close']) / atr
    klass = str(structure.get('class', '')).upper()
    structure_side = _v252_side(structure.get('side'))
    structure_accept = 'CLEAN ' in klass or 'RETEST HELD' in klass
    structure_fakeout = 'TRAP' in klass or 'FAKEOUT' in klass

    hypotheses = {}
    for target in ('UP', 'DOWN'):
        sign = 1.0 if target == 'UP' else -1.0
        liquidity = _v258_liquidity_read(rows, target=target)
        strengths = {}
        # Every available family stays in the denominator; weak evidence does
        # not vanish, while an unavailable Kalshi feed no longer blocks calls.
        strengths['LIVE PACE'] = max(0.0, min(1.0, max(pace * sign / 0.34, fast_pace * sign / 0.42,
                                                        pace_accel * sign / 0.24)))
        strengths['EXECUTED FLOW'] = max(0.0, min(1.0, max(flow * sign / 0.34,
                                                            flow_accel * sign / 0.24,
                                                            edge * sign / 0.42)))
        rejection = (target == 'DOWN' and upper >= max(cb * 0.9, cr * 0.30)) or (target == 'UP' and lower >= max(cb * 0.9, cr * 0.30))
        failed_extend = ((target == 'DOWN' and c['high'] <= p['high'] and c['close'] < p['close'])
                         or (target == 'UP' and c['low'] >= p['low'] and c['close'] > p['close']))
        candle_dir = (c['close'] - c['open']) * sign
        strengths['CANDLE TURN'] = max(0.0, min(1.0,
            0.72 if rejection else 0.58 if failed_extend else 0.46 if candle_dir > 0 and shrinking else
            max(0.0, candle_momentum * sign / 0.85)))
        if liquidity.get('ready'):
            strengths['LIQUIDITY'] = (min(1.0, float(liquidity.get('score', 0.0)) / 88.0)
                                      if liquidity.get('side') == target else 0.0)
        if structure.get('ready'):
            strengths['STRUCTURE'] = (min(1.0, float(structure.get('score', 0.0)) / 86.0)
                                      if structure_side == target else 0.0)
        if bool(kalshi.get('ready')):
            delta = float(kalshi.get('delta3', 0.0) or 0.0) * 0.72 + float(kalshi.get('delta8', 0.0) or 0.0) * 0.28
            strengths['KALSHI LEAD'] = max(0.0, min(1.0, delta * sign / 0.018))
        pattern_read = _v260_pattern_signal(self, rows, target, structure=structure, liquidity=liquidity)
        if pattern_read.get('pattern'):
            strengths['PATTERN MEMORY'] = float(pattern_read.get('strength', 0.0) or 0.0)
        weights = {'LIVE PACE': 20.0, 'EXECUTED FLOW': 24.0, 'CANDLE TURN': 17.0,
                   'LIQUIDITY': 19.0, 'STRUCTURE': 14.0, 'KALSHI LEAD': 6.0,
                   'PATTERN MEMORY': 8.0}
        available = sum(weights[name] for name in strengths)
        score = 100.0 * sum(weights[name] * value for name, value in strengths.items()) / max(available, 1.0)
        families = [name for name, value in strengths.items() if value >= 0.34]
        triggers = [name for name, value in strengths.items()
                    if name in ('LIVE PACE', 'EXECUTED FLOW', 'LIQUIDITY', 'STRUCTURE') and value >= 0.58]
        hypotheses[target] = {'side': target, 'score': score, 'families': families,
                              'strengths': strengths, 'triggers': triggers, 'liquidity': liquidity,
                              'pattern': pattern_read}

    up, down = hypotheses['UP'], hypotheses['DOWN']
    directional_winner = up if up['score'] >= down['score'] else down
    # With a defended thesis, reversal warnings evaluate the opposite side.
    # A reclaim may point back into the defended side and is still surfaced as
    # a fakeout/hold event rather than being mislabeled as a flip.
    reclaim_hypotheses = [h for h in (up, down) if h['liquidity'].get('reclaimed')]
    if structure_fakeout and structure_side in hypotheses:
        reclaim_hypotheses.append(hypotheses[structure_side])
    if reclaim_hypotheses:
        winner = max(reclaim_hypotheses, key=lambda h: h['score'])
    elif defended in ('UP', 'DOWN'):
        winner = hypotheses['DOWN' if defended == 'UP' else 'UP']
    else:
        winner = directional_winner
    loser = down if winner is up else up
    target = winner['side']
    score = float(winner['score'])
    margin = score - float(loser['score'])
    families = list(winner['families'])
    liquidity = dict(winner['liquidity'])
    accepted = ((liquidity.get('accepted') and liquidity.get('side') == target)
                or (structure_accept and structure_side == target)
                or (bool(market.get('flip_confirmed')) and _v252_side(market.get('side')) == target))
    fakeout = (not accepted) and (
        (liquidity.get('reclaimed') and liquidity.get('side') == target)
        or (structure_fakeout and structure_side == target)
    )
    against_thesis = defended == 'WAIT' or target != defended

    if fakeout and len(families) >= 2:
        proposed = 'FAKEOUT / RECLAIM'
        score = max(score, 76.0)
    elif accepted and against_thesis and score >= 52.0 and len(families) >= 2:
        proposed = 'REAL FLIP'
        score = max(score, 84.0)
    elif score >= 58.0 and margin >= 10.0 and len(families) >= 3 and winner['triggers']:
        proposed = 'INCOMING FLIP'
    elif score >= 40.0 and margin >= 6.0 and len(families) >= 2:
        proposed = 'REVERSAL PRESSURE'
    else:
        proposed = 'NO CLEAN FLIP'

    # Latch classifications briefly, not weak predictions. This prevents a
    # reclaim/real-break label from disappearing on the very next 300ms tick.
    prior = dict(getattr(self, '_v259_flip_last', {}) or {})
    latched_until = float(getattr(self, '_v259_flip_latched_until', 0.0) or 0.0)
    if proposed in ('REAL FLIP', 'FAKEOUT / RECLAIM'):
        self._v259_flip_latched_until = now + 2.5
    elif now < latched_until and prior.get('stage') in ('REAL FLIP', 'FAKEOUT / RECLAIM'):
        proposed = str(prior['stage'])
        target = str(prior.get('target', target))
        score = max(score, float(prior.get('score', score)) * 0.94)
        families = list(prior.get('families', families))
        liquidity = dict(prior.get('liquidity', liquidity))

    seconds_left = max(0.0, 900.0 - now % 900.0)
    late = ' • FINAL 3M: EXIT WARNING ONLY / NO NEW ENTRY' if seconds_left <= _V257_FINAL_MUTE_SECONDS else ''
    evidence = ', '.join(families) if families else 'no independent reversal families yet'
    side = target if proposed not in ('NO CLEAN FLIP', 'BUILDING') else 'WAIT'
    result = {'stage': proposed, 'side': side,
            'target': target, 'defended': defended, 'score': min(100.0, score),
            'margin': margin, 'families': families, 'family_count': len(families),
            'confirmed': proposed == 'REAL FLIP', 'fakeout': proposed == 'FAKEOUT / RECLAIM',
            'seconds_left': seconds_left, 'liquidity': liquidity, 'hypotheses': hypotheses,
            'detail': f'{proposed} → {target} • {score:.0f}/100 • edge {margin:+.0f} • {evidence} • '
                      f'{liquidity.get("state", "LIQUIDITY BUILDING")}{late} • guidance, not an order'}
    self._v259_flip_last = dict(result)
    return result


def _v257_update(self, now=None):
    now = float(now or time.time())
    read = _v257_scalp_read(self, now=now)
    self._v257_scalp_last = dict(read)
    preflip = _v259_flip_radar_read(
        self, now=now, structure=read.get('structure'), kalshi=read.get('kalshi')
    )
    self._v259_flip_display_last = dict(preflip)
    verdict = str(read.get('verdict', 'WAIT'))
    try:
        self.scalp_verdict_var.set(verdict)
        self.scalp_detail_var.set(str(read.get('detail', 'WAIT')))
        structure = dict(read.get('structure') or {})
        self.structure_verdict_var.set('STRUCTURE: ' + str(structure.get('detail', 'building')))
        self.flip_radar_verdict_var.set(
            f'{preflip.get("stage", "BUILDING")} → {preflip.get("target", "WAIT")}  '
            f'{float(preflip.get("score", 0.0)):.0f}/100'
        )
        self.flip_radar_detail_var.set(str(preflip.get('detail', 'NEW FLIP ENGINE: building')))
        label = getattr(self, '_v257_verdict_label', None)
        if label is not None:
            fg = GREEN if read.get('side') == 'UP' else RED if read.get('side') == 'DOWN' else YELLOW
            label.configure(fg=fg)
        preflip_label = getattr(self, '_v259_flip_label', None)
        if preflip_label is not None:
            pside = _v252_side(preflip.get('side'))
            pstage = str(preflip.get('stage', ''))
            pcolor = '#ffb347' if 'FAKEOUT' in pstage else CYAN if 'INCOMING' in pstage else GREEN if pside == 'UP' else RED if pside == 'DOWN' else '#ffb347'
            preflip_label.configure(fg=pcolor)
    except Exception:
        pass
    return read


def _v257_visible_paper_once(self, now=None):
    """Open the visible simulated trade from a confirmed scalp verdict."""
    now = float(now or time.time())
    try:
        if not bool(self.auto_paper_enabled_var.get()):
            return False
    except Exception:
        return False
    if getattr(self, 'paper_active_trade', None) is not None:
        return False
    bucket = int(now // 900) * 900
    if getattr(self, '_v257_visible_paper_bucket', None) == bucket or getattr(self, 'auto_paper_last_bucket', None) == bucket:
        return False
    read = dict(getattr(self, '_v257_scalp_last', {}) or {})
    side = _v252_side(read.get('side'))
    if side == 'WAIT' or not str(read.get('verdict', '')).startswith('SCALP '):
        return False
    if float(read.get('seconds_left', 0.0) or 0.0) <= _V257_FINAL_MUTE_SECONDS:
        return False
    try:
        quote = _v233_exact_ask(self, side)
    except Exception:
        quote = None
    if not quote:
        self.paper_status_var.set(f'AUTO PAPER {side} READY • waiting for fresh executable Kalshi ask')
        return False
    allowed, value = _v252_quote_gate(quote.get('contract'), ceiling=_V257_PAPER_CAP)
    if not allowed:
        self.paper_status_var.set(f'AUTO PAPER VALUE WAIT • {side} • {value}')
        return False
    opened = self._paper_open(
        side, entry_source='AUTO', auto_score=float(read.get('score', 0.0) or 0.0),
        auto_reason=f'{read.get("verdict")} • five-way agreement • {read.get("structure", {}).get("class", "STRUCTURE")}',
    )
    if opened:
        self._v257_visible_paper_bucket = bucket
        self.auto_paper_last_bucket = bucket
        self.auto_paper_reason_var.set(
            f'VISIBLE PAPER ENTERED {side} • {read.get("verdict")} • {value}'
        )
    return bool(opened)


def _v257_mount_panel(self):
    try:
        old = getattr(self, '_v257_scalp_panel', None)
        if old is not None and bool(old.winfo_exists()):
            return True
    except Exception:
        pass
    page = getattr(self, 'page_frame', None)
    if page is None:
        return False
    try:
        panel = tk.Frame(page, bg='#100b12', highlightthickness=2, highlightbackground=PINK2)
        after = getattr(self, '_v256_hotfix_credentials_bar', None)
        if after is not None and bool(after.winfo_exists()):
            panel.pack(fill='x', padx=10, pady=(2, 5), after=after)
        else:
            panel.pack(fill='x', padx=10, pady=(2, 5))
        verdict = tk.Label(
            panel, textvariable=self.scalp_verdict_var, bg='#100b12', fg=YELLOW,
            font=('Segoe UI Variable', 22, 'bold'), anchor='w', padx=12, pady=6,
        )
        verdict.grid(row=0, column=0, rowspan=4, sticky='nsew')
        panel.columnconfigure(1, weight=1)
        tk.Label(panel, textvariable=self.scalp_detail_var, bg='#100b12', fg=TEXT,
                 font=('Segoe UI Variable', 9, 'bold'), anchor='w').grid(row=0, column=1, sticky='ew', padx=8, pady=(6, 1))
        tk.Label(panel, textvariable=self.structure_verdict_var, bg='#100b12', fg=MUTED,
                 font=('Cascadia Mono', 8, 'bold'), anchor='w').grid(row=1, column=1, sticky='ew', padx=8, pady=(1, 6))
        preflip = tk.Label(panel, textvariable=self.flip_radar_verdict_var, bg='#100b12', fg='#ffb347',
                          font=('Segoe UI Variable', 13, 'bold'), anchor='w')
        preflip.grid(row=2, column=1, sticky='ew', padx=8, pady=(2, 0))
        tk.Label(panel, textvariable=self.flip_radar_detail_var, bg='#100b12', fg=TEXT,
                 font=('Cascadia Mono', 8, 'bold'), anchor='w').grid(row=3, column=1, sticky='ew', padx=8, pady=(1, 7))
        controls = tk.Frame(panel, bg='#100b12')
        controls.grid(row=0, column=2, rowspan=4, sticky='e', padx=8)
        ttk.Label(controls, text='PAPER $', style='Muted.Card.TLabel').pack(side='left')
        ttk.Entry(controls, textvariable=self.paper_stake_var, width=7).pack(side='left', padx=(3, 5))
        ttk.Button(controls, text='PAPER UP', command=lambda: self._paper_open('UP')).pack(side='left', padx=2)
        ttk.Button(controls, text='PAPER DOWN', command=lambda: self._paper_open('DOWN')).pack(side='left', padx=2)
        ttk.Button(controls, text='CLOSE PAPER', command=self._paper_close_manual).pack(side='left', padx=2)
        ttk.Checkbutton(controls, text='AUTO', variable=self.auto_paper_enabled_var).pack(side='left', padx=(6, 0))
        self._v257_verdict_label = verdict
        self._v259_flip_label = preflip
        self._v257_scalp_panel = panel
        return True
    except Exception:
        return False


def _v257_draw_structure_boxes(self):
    c = getattr(self, 'canvas', None)
    scale = dict(getattr(self, '_v82_chart_scale', {}) or {})
    if c is None or not scale:
        return
    try:
        rows = _v257_clean_rows(self._chart_candles(), int(getattr(self, 'visible_count', 80) or 80))
        read = _v257_structure_read(self, rows=rows)
        self._v257_structure_last = dict(read)
        if not read.get('ready'):
            return
        left = float(scale['left']); right = float(scale['plot_right'])
        top = float(scale['top']); ph = float(scale['ph'])
        lo = float(scale['lo']); hi = float(scale['hi'])
        def y(price):
            raw = top + (hi - float(price)) / max(hi - lo, 1e-9) * ph
            return max(top + 1.0, min(top + ph - 1.0, raw))
        c.delete('v257_zones')
        zone_left = left + (right - left) * 0.28
        demand = read['demand']; supply = read['supply']
        for zone, fill, outline, label in (
            (demand, '#123d31', GREEN, 'DEMAND / SUPPORT'),
            (supply, '#4b1f32', RED, 'SUPPLY / RESISTANCE'),
        ):
            y1, y2 = y(zone['high']), y(zone['low'])
            c.create_rectangle(zone_left, min(y1, y2), right - 3, max(y1, y2),
                               fill=fill, outline=outline, width=2, stipple='gray25', tags=('v257_zones',))
            c.create_text(zone_left + 6, min(y1, y2) + 9, text=label, fill=outline,
                          anchor='w', font=('Cascadia Mono', 7, 'bold'), tags=('v257_zones',))

        try:
            gaps = list(self.chart_fair_value_gaps(rows) or [])
        except Exception:
            gaps = []
        step = max(2.0, (right - left) / max(len(rows), 1))
        for gap in [g for g in gaps if g.get('active')][-6:]:
            x1 = max(left, left + int(gap.get('left_index', 0)) * step)
            y1, y2 = y(gap['high']), y(gap['low'])
            bull = str(gap.get('type')) == 'bull'
            fill, outline = ('#173629', '#51d09a') if bull else ('#451d35', '#ff5a9d')
            c.create_rectangle(x1, min(y1, y2), right - 3, max(y1, y2), fill=fill,
                               outline=outline, width=2, stipple='gray25', tags=('v257_zones',))
            c.create_text(x1 + 5, min(y1, y2) + 9,
                          text='BULL FVG / DEMAND' if bull else 'BEAR FVG / SUPPLY',
                          fill=outline, anchor='w', font=('Cascadia Mono', 7, 'bold'), tags=('v257_zones',))

        liquidity = dict((getattr(self, '_v259_flip_display_last', {}) or {}).get('liquidity') or {})
        for key, label, color in (
            ('buy_pool', 'BUY-SIDE LIQUIDITY', '#ffb347'),
            ('sell_pool', 'SELL-SIDE LIQUIDITY', '#65c7ff'),
        ):
            level = liquidity.get(key)
            if level is None:
                continue
            ly = y(level)
            c.create_line(zone_left, ly, right - 3, ly, fill=color, width=1,
                          dash=(3, 3), tags=('v257_zones',))
            c.create_text(right - 7, ly - 7, text=label, fill=color, anchor='e',
                          font=('Cascadia Mono', 7, 'bold'), tags=('v257_zones',))

        klass = str(read.get('class', 'STRUCTURE BUILDING'))
        side = _v252_side(read.get('side'))
        color = GREEN if side == 'UP' else RED if side == 'DOWN' else YELLOW
        box_left = left + 8
        box_right = min(right - 8, box_left + 360)
        c.create_rectangle(box_left, top + 62, box_right, top + 104, fill='#09070b',
                           outline=color, width=2, tags=('v257_zones',))
        c.create_text(box_left + 9, top + 74, text=klass, fill=color, anchor='nw',
                      font=('Segoe UI', 9, 'bold'), tags=('v257_zones',))
        c.create_text(box_left + 9, top + 91,
                      text=f'BREAK READ {float(read.get("score", 0)):.0f}/100 • close + follow-through + flow + retest',
                      fill=TEXT, anchor='nw', font=('Cascadia Mono', 7, 'bold'), tags=('v257_zones',))
        scalp = dict(getattr(self, '_v257_scalp_last', {}) or {})
        scalp_text = str(scalp.get('verdict', 'WAIT'))
        scalp_side = _v252_side(scalp.get('side'))
        scalp_color = GREEN if scalp_side == 'UP' else RED if scalp_side == 'DOWN' else YELLOW
        c.create_rectangle(right - 224, top + ph - 44, right - 4, top + ph - 8,
                           fill='#09070b', outline=scalp_color, width=2, tags=('v257_zones',))
        c.create_text(right - 114, top + ph - 26, text=scalp_text, fill=scalp_color,
                      anchor='center', font=('Segoe UI Variable', 13, 'bold'), tags=('v257_zones',))
        preflip = dict(getattr(self, '_v259_flip_display_last', {}) or {})
        preflip_side = _v252_side(preflip.get('side'))
        preflip_stage = str(preflip.get('stage', ''))
        preflip_color = '#ffb347' if 'FAKEOUT' in preflip_stage else CYAN if 'INCOMING' in preflip_stage else GREEN if preflip_side == 'UP' else RED if preflip_side == 'DOWN' else '#ffb347'
        preflip_text = f'{preflip.get("stage", "BUILDING")} → {preflip.get("target", "WAIT")} {float(preflip.get("score", 0.0)):.0f}'
        c.create_rectangle(right - 324, top + 10, right - 4, top + 48,
                           fill='#09070b', outline=preflip_color, width=2, tags=('v257_zones',))
        c.create_text(right - 164, top + 29, text=preflip_text, fill=preflip_color,
                      anchor='center', font=('Segoe UI Variable', 11, 'bold'), tags=('v257_zones',))
        c.tag_raise('v254_labels')
        c.tag_raise('v82_live')
    except Exception:
        pass


_V257_BASE_DRAW_CHART = ChartKingPro.draw_chart


def _v257_draw_chart(self, *args, **kwargs):
    result = _V257_BASE_DRAW_CHART(self, *args, **kwargs)
    if result is False:
        return result
    _v257_draw_structure_boxes(self)
    return result


