# BEGIN V21.61 SOURCE ENGINE
"""Bookmap King V21.61: source-derived Pine calculations, no broker I/O.

Ports the supplied default Gainz, Cipher reconstruction, Scout and Flow rules.
PAC's internal/swing structure, wick sweeps and order-block detection are ported;
optional decorative/HTF projections are not trading inputs. See PORT_NOTES.md.
"""
import copy
import math
from collections import deque


def _pclip(x, lo, hi):
    if not math.isfinite(x):
        return float('nan')
    return max(lo, min(hi, x))


def _pvalid(x):
    return isinstance(x, (int, float)) and math.isfinite(x)


class PineSignalCore:
    """One timeframe; commit each closed bar once, preview on a disposable copy.

    The caller owns symbol identity, missing-bar policy and closed-bar boundaries.
    No state may be committed by an intrabar preview.
    """
    def __init__(self, seconds=60, tick=0.01):
        self.seconds, self.tick = int(seconds), float(tick)
        self.rows = deque(maxlen=2105)
        self.series = {}
        self.filters = {}
        self.index = -1
        self.round = None
        self.gainz_last = 0
        self.gainz_levels = {}
        self.flow_last, self.flow_bar = 0, -100000
        self.watch = None
        self.active, self.active_stop, self.scout_bar = 0, None, -100000
        self.structures = {n: {'os': 0, 'top': None, 'bottom': None, 'trend': 0,
                               'top_cross': True, 'bottom_cross': True} for n in (5, 10, 50)}
        self.pools = []
        self.blocks = []
        self.trend_pivots = {'high':deque(maxlen=3),'low':deque(maxlen=3)}
        self.last = {}
        self.events = deque(maxlen=300)
        self.plots = deque(maxlen=200)

    def put(self, name, value):
        self.series.setdefault(name, deque(maxlen=2105)).append(value)
        return value

    def val(self, name, ago=0):
        seq = self.series.get(name, ())
        return seq[-1-ago] if len(seq) > ago else float('nan')

    def sma(self, name, length):
        values = [x for x in self.series.get(name, ()) if _pvalid(x)][-length:]
        return sum(values) / length if len(values) == length else float('nan')

    def smooth(self, name, value, length, rma=False):
        state = self.filters.setdefault(name, {'value': float('nan'), 'seed': []})
        if not _pvalid(value):
            return state['value']
        if not _pvalid(state['value']):
            if rma:
                state['seed'].append(value)
                if len(state['seed']) < length:
                    return float('nan')
                state['value'] = sum(state['seed']) / length
                state['seed'] = []
            else:
                state['value'] = value
        else:
            alpha = 1.0 / length if rma else 2.0 / (length + 1)
            state['value'] = alpha * value + (1.0-alpha) * state['value']
        return state['value']

    def cross(self, a, b, direction=1):
        return (self.val(a)*direction > self.val(b)*direction
                and self.val(a, 1)*direction <= self.val(b, 1)*direction)

    def preview(self, bar, target=None, now=None):
        return copy.deepcopy(self).step(bar, target=target, now=now, developing=True)

    def step(self, bar, target=None, now=None, developing=False):
        bar = {k: float(bar.get(k) if bar.get(k) is not None else float('nan')) for k in ('time', 'open', 'high', 'low', 'close', 'volume')}
        if not all(math.isfinite(bar[k]) for k in ('time', 'open', 'high', 'low', 'close')):
            raise ValueError('Non-finite candle')
        if not (bar['low'] <= min(bar['open'], bar['close']) <= max(bar['open'], bar['close']) <= bar['high']):
            raise ValueError('Invalid OHLC geometry')
        if self.rows and bar['time'] <= self.rows[-1]['time']:
            raise ValueError('Closed bars must have unique increasing timestamps')
        self.index += 1
        self.rows.append(bar)
        o, h, l, c, v = (bar[k] for k in ('open', 'high', 'low', 'close', 'volume'))
        rows = list(self.rows)
        for k in ('open', 'high', 'low', 'close', 'volume'):
            self.put(k, bar[k])
        pc, po = self.val('close', 1), self.val('open', 1)
        tr = max(h-l, abs(h-pc), abs(l-pc)) if _pvalid(pc) else h-l
        atr = self.put('atr', self.smooth('atr14', tr, 14, True))
        for n in (5, 9, 11, 13, 15, 18, 20, 21, 25, 29, 33):
            self.put('ema'+str(n), self.smooth('ema'+str(n), c, n))
        for n in (7, 14):
            change = c-pc
            gain = self.smooth('rsi_gain'+str(n), max(change, 0) if _pvalid(change) else change, n, True)
            loss = self.smooth('rsi_loss'+str(n), max(-change, 0) if _pvalid(change) else change, n, True)
            rsi = (100.0 if loss == 0 and gain > 0 else 0.0 if gain == 0 and loss > 0
                   else 100-100/(1+gain/loss) if loss > 0 else float('nan'))
            self.put('rsi'+str(n), rsi)
        self.put('atr200', self.smooth('atr200', tr, 200, True))
        self.put('atr10', self.smooth('atr10', tr, 10, True))
        newround = int(bar['time']//900)*900 != self.round
        if newround:
            self.round = int(bar['time']//900)*900
            self.round_open, self.pv, self.rv = o, 0.0, 0.0
            self.watch = None
            self.active, self.active_stop, self.scout_bar = 0, None, -100000
            self.flow_last, self.flow_bar = 0, -100000
        volumeweight = v if _pvalid(v) and v > 0 else 1.0
        self.pv += (h+l+c)/3 * volumeweight
        self.rv += volumeweight
        target = float(target) if _pvalid(target) and target > 0 else self.round_open
        left = max(0, self.round+900-(now if developing and now is not None else bar['time']+self.seconds))
        stable = tr > 0 and abs(c-o)/tr > .70
        gb = pc < po and c > o and c > po and stable and self.val('rsi14') < 80 and c < self.val('close', 10)
        gs = pc > po and c < o and c < po and stable and self.val('rsi14') > 20 and c > self.val('close', 10)
        raw_gainz = 1 if gb else -1 if gs else 0
        gainz = raw_gainz if raw_gainz != self.gainz_last else 0
        levels = {}
        if gainz:
            self.gainz_last = gainz
            if _pvalid(atr):
                levels = {'entry': c, 'stop': math.ceil((c-gainz*atr)*100)/100,
                          'target': math.ceil((c+gainz*atr*2)*100)/100}
                self.gainz_levels=dict(levels,side=gainz,time=bar['time'])
        cipher = self._cipher(o, h, l, c)
        scout = self._scout(rows, atr, target, left)
        flow = self._flow(rows, atr, target, raw_gainz, tr)
        pac = self._pac(rows)
        result = {'time': bar['time'], 'seconds': self.seconds, 'developing': developing,
                  'ready': len(rows) >= 81, 'atr': atr, 'close': c,
                  'gainz': {'raw': raw_gainz, 'signal': gainz, **self.gainz_levels},
                  'cipher': cipher, 'scout': scout, 'flow': flow, 'pac': pac,
                  'seconds_left': left, 'target': target}
        if not developing:
            self.plots.append({'time':bar['time'],'ribbon':cipher['ribbon'],
                               'wave_fast':cipher['wave_fast'],'wave_slow':cipher['wave_slow'],
                               'pressure':cipher['candle_pressure']})
            for name, side in [('GAINZ', gainz), ('SCOUT', scout['reversal']), ('FLOW', flow['signal'])]:
                if side:
                    self.events.append({'time': bar['time'], 'price': c, 'source': name, 'side': side,
                                        'label': name+' '+('UP' if side > 0 else 'DOWN'),
                                        'action': scout.get('action') if name == 'SCOUT' else 'SOURCE SIGNAL'})
            for event in pac['events'] + pac['sweeps']:
                self.events.append({'time': bar['time'], 'price': c, 'source': 'STRUCTURE', **event})
        self.last = result
        return result

    def _cipher(self, o, h, l, c):
        src = (h+l+c)/3
        esa = self.smooth('cipher_esa', src, 9)
        dev = self.smooth('cipher_dev', abs(src-esa), 9)
        wt1 = self.put('wt1', self.smooth('cipher_wt', (src-esa)/(.015*dev) if dev else 0, 12))
        wt2 = self.put('wt2', self.sma('wt1', 3))
        self.put('cipher_mf', (c-o)/(h-l)*200 if h != l else 0)
        mf = self.sma('cipher_mf', 60)-2.25
        stoch = {}
        for n in (40, 81):
            highs, lows = list(self.series['high'])[-n:], list(self.series['low'])[-n:]
            span = max(highs)-min(lows)
            self.put('stoch'+str(n), (c-min(lows))/span*100 if span else float('nan'))
            stoch[n] = self.sma('stoch'+str(n), 2)
        e = lambda n: self.val('ema'+str(n))
        wave = wt1-wt2
        yellow = max(o, c) > e(5) and e(5) > e(11) and e(5) > e(33) and wave > 0
        redx = self.cross('ema5', 'ema11', -1)
        redd = self.cross('wt1', 'wt2', -1)
        flags = {
            'yellowDiamond': yellow,
            'blueTriangle': self.cross('ema5', 'ema25') and wave > 0 and (wt1 > -15 or wt2 > -25) and stoch[81] < 80 and not self.cross('ema11', 'ema33'),
            'greenDot': self.cross('ema11', 'ema33') and yellow,
            'redX': redx, 'redDiamond': redd,
            'yellowX': redd and wt1 < -40 and stoch[81] < 20,
            'bloodDiamond': redx and redd,
            'oscillatorGreenDot': self.cross('wt1', 'wt2') and wt1 < -60,
        }
        translations = {'yellowDiamond': 'Uptrend has momentum', 'blueTriangle': 'Early upward turn',
                        'greenDot': 'Uptrend crossover', 'redX': 'Fast trend turned down',
                        'redDiamond': 'Momentum crossed down', 'yellowX': 'Downward cross at a low extreme',
                        'bloodDiamond': 'Trend and momentum turned down together',
                        'oscillatorGreenDot': 'Momentum turned up from a low extreme'}
        return {'wave_fast': wt1, 'wave_slow': wt2, 'wave_gap': wave,
                'candle_pressure': mf, 'price_stochastic40': stoch[40], 'price_stochastic81': stoch[81],
                'flags': flags, 'labels': [translations[k] for k, yes in flags.items() if yes],
                'ribbon': {n: e(n) for n in (5, 11, 15, 18, 21, 25, 29, 33)},
                'sma21': self.sma('close', 21), 'cross_up': self.cross('wt1', 'wt2'),
                'cross_down': redd}

    def _scout(self, rows, atr, target, left):
        b = rows[-1]; o,h,l,c,v = (b[k] for k in ('open','high','low','close','volume'))
        prior = rows[-7:-1]
        low = min((r['low'] for r in prior), default=float('nan'))
        high = max((r['high'] for r in prior), default=float('nan'))
        support = min((r['low'] for r in rows[-21:-1]), default=float('nan'))
        resistance = max((r['high'] for r in rows[-21:-1]), default=float('nan'))
        rng, body = max(h-l,self.tick), abs(c-o)
        pc,po = self.val('close',1),self.val('open',1)
        rsi,prsi = self.val('rsi7'),self.val('rsi7',1)
        mom = self.put('scout_momentum', self.val('ema5')-self.val('ema13'))
        pmom = self.val('scout_momentum',1)
        avgvol = self.sma('volume',20)
        volume = _pvalid(v) and avgvol > 0 and v >= avgvol*1.1
        vwap = self.pv/self.rv
        oldrsi = [r for r in list(self.series['rsi7'])[-7:-1] if _pvalid(r)]
        scores, watches, strong, evidence = {}, {}, {}, {}
        for side in (1,-1):
            bull = side == 1
            sweep = l < low and c > low if bull else h > high and c < high
            wick = min(o,c)-l if bull else h-max(o,c)
            rejection = wick >= rng*.35 and wick >= body*1.2
            engulf = c>o and pc<po and c>=po and o<=pc if bull else c<o and pc>po and c<=po and o>=pc
            extreme = rsi<=38 or (prsi<=38 and rsi>prsi) if bull else rsi>=62 or (prsi>=62 and rsi<prsi)
            stretch = l<=self.val('ema20')-.35*atr if bull else h>=self.val('ema20')+.35*atr
            turn = (mom-pmom)*side > 0
            reclaim = l<vwap and c>vwap if bull else h>vwap and c<vwap
            near = l<=support+.15*atr if bull else h>=resistance-.15*atr
            divergence = bool(oldrsi) and sweep and (rsi>min(oldrsi) if bull else rsi<max(oldrsi))
            parts = {'sweep': 2*int(sweep), 'wick_rejection': int(rejection), 'engulfing': 2*int(engulf),
                     'rsi_turn':int(extreme), 'stretch':int(stretch), 'momentum_turn':int(turn),
                     'volume_expansion':int(volume), 'round_vwap_reclaim':int(reclaim),
                     'near_level':int(near), 'divergence':int(divergence)}
            scores[side] = min(10,sum(parts.values()))
            watches[side] = sweep or rejection or engulf or (stretch and extreme)
            strong[side] = scores[side]>=7 and (sweep or engulf) and (c-o)*side>0 and (c-(h+l)/2)*side>0 and turn
            evidence[side] = parts
        self.put('logreturn', math.log(c/pc) if pc>0 and c>0 else 0.0)
        logs = list(self.series['logreturn'])[-20:]
        sigma = math.sqrt(sum((x-sum(logs)/20)**2 for x in logs)/20)*c if len(logs)==20 else float('nan')
        expected = max(atr*.35, sigma*math.sqrt(max(1,left/max(self.seconds,1)))) if _pvalid(sigma) and _pvalid(atr) else float('nan')
        z = (c-target)/expected if expected>0 else 0.0
        proxy = 100/(1+math.exp(-1.7*_pclip(z,-8,8)))
        reversal, cashouts, failed, action = 0, [], False, 'WAIT'
        supported = self.seconds in (60,180,300)
        if supported:
            cooldown = self.index-self.scout_bar>2
            if self.active and (c-self.active_stop)*self.active<0:
                cashouts.append(self.active); self.active=0; self.active_stop=None
            if self.watch:
                w = self.watch; side=w['side']
                broke = l<w['stop']-.05*atr if side>0 else h>w['stop']+.05*atr
                if self.index-w['bar']>2 or broke:
                    failed=bool(broke); self.watch=None
                elif self.index>w['bar'] and (c-w['trigger'])*side>0 and (c-o)*side>0 and (mom-pmom)*side>0 and max(scores[side],w['score'])>=6:
                    reversal=side; self.watch=None
            if not reversal and cooldown:
                for side in (1,-1):
                    if strong[side] and scores[side]>scores[-side] and self.active!=side:
                        reversal=side; self.watch=None; break
            if not reversal and self.watch is None and cooldown:
                for side in (1,-1):
                    if watches[side] and scores[side]>=4 and scores[side]>scores[-side] and self.active!=side:
                        self.watch={'side':side,'bar':self.index,'trigger':h if side>0 else l,
                                    'stop':l if side>0 else h,'score':scores[side]}; break
            if reversal:
                self.scout_bar=self.index; self.watch=None
                if self.active==-reversal:
                    cashouts.append(self.active); self.active=0
                if left<75 or (c-target)*reversal<0 and abs(z)>2.2:
                    action='NO ENTRY'
                elif (proxy if reversal>0 else 100-proxy)>70:
                    action='NO CHASE (MODEL PRICE)'
                elif self.active!=reversal:
                    action='SOURCE BUY'; self.active=reversal
                    self.active_stop=l-.08*atr if reversal>0 else h+.08*atr
        return {'scores':scores, 'evidence':evidence, 'watch':copy.deepcopy(self.watch),
                'reversal':reversal,'active':self.active,'invalidation':self.active_stop,
                'watch_failed':failed,'cashouts':cashouts,'action':action,'supported':supported,
                'model_up_cents':proxy,'round_vwap':vwap,'support':support,'resistance':resistance,
                'setup_side':1 if watches[1] and scores[1]>=4 and scores[1]>scores[-1] else -1 if watches[-1] and scores[-1]>=4 and scores[-1]>scores[1] else 0}

    def _flow(self, rows, atr, target, gainz, tr):
        o,h,l,c,v=(rows[-1][k] for k in ('open','high','low','close','volume'))
        a=max(atr,self.tick) if _pvalid(atr) else self.tick
        left=max(0,self.round+900-rows[-1]['time']-self.seconds)
        elapsed=900-left
        final,late,middle=left<=60,left<=300,left<=600
        e9,e21=self.val('ema9'),self.val('ema21')
        bull,bear=e9>e21 and c>=e9,e9<e21 and c<=e9
        fast=(c-self.val('close',3))/a; slow=(c-self.val('close',8))/a
        tol=.15*a
        reclaim=l<=target+tol and c>target+.2*tol and c>o
        reject=h>=target-tol and c<target-.2*tol and c<o
        above=all(self.val('close',i)>target for i in range(3))
        below=all(self.val('close',i)<target for i in range(3))
        higher=h>self.val('high',1)>self.val('high',2) and l>self.val('low',1)
        lower=l<self.val('low',1)<self.val('low',2) and h<self.val('high',1)
        prior=rows[-6:-1]
        bup=bool(prior) and c>max(r['high'] for r in prior)
        bdn=bool(prior) and c<min(r['low'] for r in prior)
        compact=max(r['high'] for r in rows[-4:])-min(r['low'] for r in rows[-4:])<a*1.35
        flagup=self.val('close',4)-self.val('close',10)>a*1.5 and compact and self.sma('close',3)>=self.sma('close',6)
        flagdn=self.val('close',10)-self.val('close',4)>a*1.5 and compact and self.sma('close',3)<=self.sma('close',6)
        expected=max(a*math.sqrt(max(left/max(self.seconds,1),1)),self.tick)
        settlement=self.sma('close',max(1,int(math.floor(60/max(self.seconds,1)+.5))))
        z=((settlement if final else c)-target)/expected
        weight=46 if final else 38 if late else 29 if middle else 22
        context=.55 if final else .72 if late else .90 if middle else 1
        rsi=self.val('rsi14')
        parts={'target':_pclip(z*weight,-weight,weight),
               'trend':((13 if bull else -13 if bear else 0)+_pclip((rsi-50)/3.5,-6,6))*context,
               'momentum':(_pclip(fast*5,-8,8)+_pclip(slow*2.5,-6,6))*(1.15 if final else 1),
               'structure':(7 if higher else -7 if lower else 0)+(5 if bup else -5 if bdn else 0),
               'target_behavior':(9 if reclaim else -9 if reject else 0)+(4 if above else -4 if below else 0),
               'volume':(5 if c>self.val('close',2) else -5) if v>self.sma('volume',20)*1.2 else 0,
               'patterns':gainz*12+(4 if flagup else -4 if flagdn else 0)}
        ready=_pvalid(rsi) and len(rows)>=15
        doji=tr>0 and abs(c-o)/tr<=.12
        edge=_pclip(sum(parts.values())*(.72 if doji else 1),-49,49) if ready else 0.0
        up=max(1,min(99,int(math.floor(50+edge+.5))))
        scoring=settlement if final else c
        near=abs(scoring-target)<=expected*.18
        chop=abs(edge)<8 or near and not (bull or bear) or doji and near
        threshold=max(68,82 if final else 74 if late else 69 if middle else 72)
        gateup=(settlement>target+max(.5*tol,.08*a) and c>target) if final else (c>target or reclaim) if late else (fast>0 and (bull or reclaim)) if middle else bull or reclaim
        gatedn=(settlement<target-max(.5*tol,.08*a) and c<target) if final else (c<target or reject) if late else (fast<0 and (bear or reject)) if middle else bear or reject
        qualified={1:up>=threshold and gateup, -1:100-up>=threshold and gatedn}
        signal=0
        if ready and self.seconds<=60 and elapsed>=30 and left>20 and not chop and self.index-self.flow_bar>=3:
            if gainz and qualified[gainz] and gainz!=self.flow_last:
                signal=gainz; self.flow_last=signal; self.flow_bar=self.index
        return {'ready':ready,'signal':signal,'up_score':up,'down_score':100-up,'edge':edge,
                'parts':parts,'threshold':threshold,'chop':chop,'supported':self.seconds<=60,
                'break_up':bup,'break_down':bdn,'seconds_left':left,'target':target}

    def _pac(self, rows):
        b=rows[-1]; c,h,l=b['close'],b['high'],b['low']; pc=self.val('close',1)
        events=[]
        previous_levels={n:{k:(s[k]['price'] if s[k] else None) for k in ('top','bottom')} for n,s in self.structures.items()}
        kept=[]
        for block in self.blocks:
            if block['breaker'] and (h>block['top'] if block['side']>0 else l<block['bottom']):
                continue
            if not block['breaker'] and (l<block['bottom'] if block['side']>0 else h>block['top']):
                block['breaker']=True; block['break_time']=b['time']
            kept.append(block)
        self.blocks=kept
        for length,state in self.structures.items():
            if len(rows)>length:
                candidate=rows[-length-1]
                os=0 if candidate['high']>max(r['high'] for r in rows[-length:]) else 1 if candidate['low']<min(r['low'] for r in rows[-length:]) else state['os']
                if os!=state['os']:
                    key='top' if os==0 else 'bottom'
                    state[key]={'price':candidate['high' if os==0 else 'low'],'index':self.index-length,'time':candidate['time']}
                    state[key+'_cross']=True
                state['os']=os
        for length,state in self.structures.items():
            for side,key in ((1,'top'),(-1,'bottom')):
                pivot=state[key]
                swing=self.structures[50][key]
                eligible=not (length==5 and swing and pivot and swing['price']==pivot['price'])
                previous=previous_levels[length][key]
                crosses=pivot and (c-pivot['price'])*side>0 and (length==10 or previous is not None and (pc-previous)*side<=0)
                if eligible and state[key+'_cross'] and crosses:
                    kind='TURN' if state['trend']==-side else 'BREAK'
                    state[key+'_cross']=False; state['trend']=side
                    if length!=10:
                        events.append({'side':side,'kind':kind,'level':pivot['price'],'scale':length,
                                       'label':('Short-term' if length==5 else 'Major')+' '+('trend turned ' if kind=='TURN' else 'level broke ')+('up' if side>0 else 'down')})
                    else:
                        distance=self.index-pivot['index']
                        segment=rows[-distance:-1]
                        if segment:
                            zone=min(segment,key=lambda r:r['low']) if side>0 else max(segment,key=lambda r:r['high'])
                            if zone['high']-zone['low']<=self.val('atr10')*10:
                                self.blocks.insert(0,{'side':side,'top':zone['high'],'bottom':zone['low'],
                                                     'time':zone['time'],'confirmed_time':b['time'],'breaker':False,
                                                     'volume':sum(r['volume'] for r in rows[-3:]),
                                                     'high_volume':sum(r['volume'] for r in rows[-2:]) if side>0 else rows[-3]['volume'],
                                                     'low_volume':rows[-3]['volume'] if side>0 else sum(r['volume'] for r in rows[-2:])})
            # Bounds below are exposed as original source values for machine consumers.
        # Default auto-trendline anchors: latest and third latest confirmed
        # symmetric 20/20 pivots, with ATR(200)/2 channel thickness.
        if len(rows)>=41:
            center=rows[-21]
            for key in ('high','low'):
                val=center[key]; older=rows[-41:-21]; newer=rows[-20:]
                is_pivot=all(val>=r[key] for r in older) and all(val>r[key] for r in newer) if key=='high' else all(val<=r[key] for r in older) and all(val<r[key] for r in newer)
                if is_pivot:
                    self.trend_pivots[key].append({'index':self.index-20,'time':center['time'],'price':val})
        trendlines=[]
        for key,seq in self.trend_pivots.items():
            if len(seq)==3:
                a,z=seq[0],seq[-1]
                slope=(z['price']-a['price'])/(z['index']-a['index'])
                trendlines.append({'kind':key,'start':dict(a),'end':dict(z),'slope':slope,
                                   'current':z['price']+slope*(self.index-z['index']),
                                   'width':self.val('atr200')/2})
        # PAC wick-only sweeps use a pivot confirmed six bars later.
        if len(rows)>=13:
            center=rows[-7]
            for side,key in ((-1,'high'),(1,'low')):
                older=rows[-13:-7]; newer=rows[-6:]
                val=center[key]
                is_pivot=all(val>=r[key] for r in older) and all(val>r[key] for r in newer) if key=='high' else all(val<=r[key] for r in older) and all(val<r[key] for r in newer)
                if is_pivot:
                    self.pools.append({'side':side,'price':val,'index':self.index-6,'time':center['time'],'swept':False})
        sweeps=[]; remaining=[]
        for pool in self.pools:
            side,p=pool['side'],pool['price']
            mitigated=c>p if side<0 else c<p
            if mitigated or self.index-pool['index']>2000:
                continue
            swept=h>p and c<p if side<0 else l<p and c>p
            if swept and not pool['swept']:
                pool['swept']=True
                sweeps.append({'side':side,'level':p,'label':'High swept, price back below' if side<0 else 'Low swept, price back above'})
            remaining.append(pool)
        self.pools=remaining[-300:]
        counts={1:0,-1:0}; kept=[]
        for block in self.blocks:
            counts[block['side']]+=1
            if counts[block['side']]<=30:
                kept.append(block)
        self.blocks=kept
        return {'events':events,'sweeps':sweeps,'pools':copy.deepcopy(self.pools[-30:]),'trendlines':trendlines,
                'blocks':copy.deepcopy(self.blocks[:10]),'internal_trend':self.structures[5]['trend'],
                'swing_trend':self.structures[50]['trend'],
                'levels':{n:{k:(s[k]['price'] if s[k] else None) for k in ('top','bottom')} for n,s in self.structures.items()}}


class PineFlipRead:
    """Bookmap adaptation, separate from the five original source results.

    Evidence counts are not probabilities. A fixed broken level can fail later.
    No pulse count, score latch or Kalshi-odds threshold is needed for a warning.
    """
    def __init__(self):
        self.breakout = None
        self.last_time = None
        self.round = None
        self.failure = None

    def read(self, closed, preview=None, defended='WAIT', now=None):
        if not closed or not closed.get('ready'):
            return self.empty('BUILDING', 'Loading source candle history')
        now = closed['time']+closed['seconds'] if now is None else now
        current=preview or closed
        round_id=int(now//900)
        if round_id!=self.round:
            self.round=round_id; self.breakout=None; self.failure=None
        # Never revive the previous round's break as a new-round thesis.
        in_round=int(closed['time']//900)==round_id
        new_closed=self.last_time!=closed['time']
        if new_closed:
            self.last_time=closed['time']; self.failure=None
            if self.breakout:
                b=self.breakout
                if (closed['close']-b['level'])*b['side']<=0:
                    self.failure={**b}; self.breakout=None
                else:
                    b['holds']+=1
            events=closed['pac']['events']
            if in_round and events:
                event=next((x for x in reversed(events) if x['scale']==5),events[-1])
                # A failure remains visible on its own closing bar, even if it starts a new break.
                self.breakout={**event,'time':closed['time'],'holds':0}
            if self.breakout and closed['time']-self.breakout['time']>5*closed['seconds']:
                self.breakout=None
        sign=lambda value: 1 if value>0 else -1 if value<0 else 0
        def evidence(packet,side):
            sc,ci,pa=packet['scout'],packet['cipher'],packet['pac']
            out=[]
            if sc['setup_side']==side or sc['reversal']==side or sc['watch'] and sc['watch']['side']==side:
                out.append('Reversal setup')
            if (ci['cross_up'] if side>0 else ci['cross_down']) or ci['wave_gap']*side>0 and ci['candle_pressure']*side>0:
                out.append('Momentum + candle pressure')
            if any(x['side']==side for x in pa['events']+pa['sweeps']):
                out.append('Price structure')
            # Flow contains Gainz: count them as one correlated source family.
            if packet['gainz']['signal']==side or packet['flow']['signal']==side:
                out.append('Engulfing signal')
            return out
        hypotheses={s:evidence(current,s) for s in (1,-1)}
        chosen=1 if len(hypotheses[1])>len(hypotheses[-1]) else -1 if len(hypotheses[-1])>len(hypotheses[1]) else 0
        confirmed_votes={s:evidence(closed,s) for s in (1,-1)}
        status,side='WAIT',0
        why='No clear reversal setup'
        sweeps=current['pac']['sweeps']
        if self.failure and in_round:
            side=-self.failure['side']; status='BREAK FAILED'
            why=f"Closed back through {self.failure['level']:.2f}; prior break invalidated"
        elif in_round and self.breakout and (current['close']-self.breakout['level'])*self.breakout['side']<=0:
            side=-self.breakout['side']; status='RECLAIM FORMING'
            why=f"Back through {self.breakout['level']:.2f} intrabar; waiting for close"
        elif chosen and self.breakout and chosen==-self.breakout['side'] and len(hypotheses[chosen])>=2:
            side=chosen; status='SETUP AGAINST BREAK'
            why='Opposing reversal setup is forming; broken level has not failed yet'
        elif in_round and self.breakout and self.breakout['holds']>=1:
            side=self.breakout['side']; status='BREAK HOLDING'
            why=f"{self.breakout['holds']} later close(s) held beyond {self.breakout['level']:.2f}"
        elif in_round and (closed['scout']['reversal'] or any(e['kind']=='TURN' for e in closed['pac']['events'])):
            candidate=closed['scout']['reversal'] or next(e['side'] for e in closed['pac']['events'] if e['kind']=='TURN')
            if len(confirmed_votes[candidate])>=2:
                side=candidate; status='TURN CONFIRMED'
                why='Closed-bar reversal trigger with supporting source evidence'
            else:
                side=candidate; status='TURN WATCH'
                why='Source reversal trigger; supporting evidence is mixed'
        elif sweeps and len({s['side'] for s in sweeps})==1:
            side=sweeps[-1]['side']; status='SWEEP FORMING' if preview else 'SWEEP RECLAIMED'
            why=sweeps[-1]['label']+('; candle still open' if preview else '; candle closed')
        elif chosen:
            side=chosen
            status='SETUP FORMING' if preview else 'TURN WATCH'
            why=' + '.join(hypotheses[chosen])+('; candle still open' if preview else '')
        if status=='WAIT' and self.breakout:
            side=self.breakout['side']; status='BREAK TESTING'; why='First close beyond level; waiting for another close'
        target='UP' if side>0 else 'DOWN' if side<0 else 'WAIT'
        families=hypotheses.get(side,[]) if preview else confirmed_votes.get(side,[])
        defending=1 if defended=='UP' else -1 if defended=='DOWN' else 0
        attack_count=len(hypotheses.get(-defending,[])) if defending else 0
        hold_count=len(hypotheses.get(defending,[])) if defending else 0
        left=900-now%900
        result={'stage':status,'side':target,'target':target,'defended':defended,
                'score':25*len(families),'families':families,'family_count':len(families),
                'margin':25*(len(hypotheses[1])-len(hypotheses[-1])),
                'confirmed':status in ('TURN CONFIRMED','BREAK HOLDING'),
                'fakeout':status=='BREAK FAILED','developing':bool(preview),
                'seconds_left':left,'hypotheses':hypotheses,
                'hold_evidence':hold_count,'opposing_evidence':attack_count,
                'breakout':copy.deepcopy(self.breakout),
                'liquidity':{'state':status if 'SWEEP' in status else 'LEVEL MAP', 'detail':why},
                'detail':why+(' • Final 3m: no new scalp entry' if left<=180 else '')+' • Guidance only'}
        return result

    @staticmethod
    def empty(stage, detail):
        return {'stage':stage,'side':'WAIT','target':'WAIT','defended':'WAIT','score':0,
                'families':[],'family_count':0,'margin':0,'confirmed':False,'fakeout':False,
                'hold_evidence':0,'opposing_evidence':0,'seconds_left':0,'detail':detail,
                'liquidity':{},'hypotheses':{},'breakout':None}


# V21.61 adapter. This file is embedded in the runnable single-file release.
# All Tk operations stay on the existing supervisor thread; Pine replay is a
# single bounded background job. Source calls never place a live or paper order.

def _v261_identity(self, now):
    try:
        ticker = _v221_current_ticker(self)
    except Exception:
        ticker = ''
    return (str(ticker), int(now//900), float(getattr(self, 'target_price', 0) or 0))


def _v261_source_schedule(self, now):
    if getattr(self, '_v261_worker_busy', False):
        return
    if now-float(getattr(self, '_v261_last_schedule', 0)) < .5:
        return
    self._v261_last_schedule=now
    identity=_v261_identity(self, now)
    selected=int(getattr(self, 'chart_interval_seconds', 60) or 60)
    snapshots={}
    # Main reversal engine stays at 1m; chart source values follow selected TF.
    for sec in dict.fromkeys((60, selected, 900, 14400)):
        try:
            history=list(self._history_for_interval(sec))[-600:]
            current=self._current_bucket_for_interval(sec)
            merged={int(r['time']):dict(r) for r in history}
            if current:
                merged[int(current['time'])]=dict(current)
            rows=_v257_clean_rows([merged[k] for k in sorted(merged)], 601)
            for row in rows:
                volume=merged[int(row['time'])].get('volume')
                if volume is None or not _pvalid(volume):
                    row['volume']=float('nan')
            closed=[r for r in rows if r['time']+sec<=now]
            live=next((r for r in reversed(rows) if r['time']<=now<r['time']+sec),None)
            snapshots[sec]=(closed,live)
        except Exception:
            snapshots[sec]=([],None)
    self._v261_worker_busy=True
    def compute():
        try:
            cache=getattr(self,'_v261_engine_cache',{}) if getattr(self,'_v261_cache_identity',None)==identity else {}
            packets={}
            for sec,(closed,live) in snapshots.items():
                entry=cache.get(sec)
                engine=entry['engine'] if entry else PineSignalCore(sec)
                recent={int(r['time']):r for r in closed[-4:]}
                # Rebuild on a provider correction; do not quietly mutate past commits.
                def signature(row):
                    return tuple(row[k] if _pvalid(row[k]) else None for k in ('time','open','high','low','close','volume'))
                corrected=any(int(r['time']) in recent and signature(r)!=signature(recent[int(r['time'])]) for r in list(engine.rows)[-4:])
                if corrected:
                    engine=PineSignalCore(sec)
                for bar in closed:
                    if engine.rows and bar['time']<=engine.rows[-1]['time']:
                        continue
                    if engine.rows and bar['time']-engine.rows[-1]['time']>sec*1.01:
                        engine=PineSignalCore(sec)
                    # Historical rounds use their own opening proxy, never today's strike.
                    target=identity[2] if int(bar['time']//900)==identity[1] and identity[2]>0 else None
                    engine.step(bar,target=target)
                preview=engine.preview(live,target=identity[2] or None,now=now) if live and (not engine.rows or live['time']>engine.rows[-1]['time']) else None
                packets[sec]={'closed':copy.deepcopy(engine.last),'preview':preview,
                              'events':list(engine.events),'plots':list(engine.plots),
                              'patterns':_v260_single_candle_catalog(list(engine.rows))}
                cache[sec]={'engine':engine}
            self._v261_engine_cache=cache
            self._v261_cache_identity=identity
            self._v261_source_packet={'identity':identity,'time':now,'selected':selected,'frames':packets}
        except Exception as exc:
            self._v261_source_packet={'identity':identity,'time':now,'error':str(exc),'frames':{}}
        finally:
            self._v261_worker_busy=False
    threading.Thread(target=compute,name='BookmapKing-PineSources',daemon=True).start()


def _v261_flip_radar_read(self, now=None, **unused):
    now=float(now or time.time())
    _v261_source_schedule(self,now)
    packet=getattr(self,'_v261_source_packet',{}) or {}
    identity=_v261_identity(self,now)
    data_ts=max(float(getattr(self,'quote_mesh_last',0) or 0),
                float(getattr(self,'bookmap_last_data_event_ts',0) or 0))
    if packet.get('identity')!=identity or now-packet.get('time',0)>5:
        read=PineFlipRead.empty('BUILDING','Updating source calculations for this market')
    elif packet.get('error'):
        read=PineFlipRead.empty('SOURCE ERROR',packet['error'])
    elif not data_ts or now-data_ts>5:
        read=PineFlipRead.empty('DATA STALE','Waiting for fresh price data; previous warning cleared')
    else:
        if getattr(self,'_v261_verdict_identity',None)!=identity:
            self._v261_verdict_engine=PineFlipRead(); self._v261_verdict_identity=identity
        primary=packet.get('frames',{}).get(60,{})
        read=self._v261_verdict_engine.read(primary.get('closed'),primary.get('preview'),
                                          defended=_v256_defended_side(self),now=now)
    self._v261_source_last=packet
    self._v259_flip_last=read
    return read


def _v261_survival_read(self, *args, **kwargs):
    r=getattr(self,'_v259_flip_last',{}) or {}
    holds=int(r.get('hold_evidence',0)); attacks=int(r.get('opposing_evidence',0))
    # Meter expresses observed supporting source families, not survival odds.
    value=holds/4*100
    return {'ready':r.get('stage') not in (None,'BUILDING','DATA STALE','SOURCE ERROR'),
            'value':value,'label':r.get('stage','BUILDING'),'side':r.get('defended','WAIT'),
            'detail':f'{holds}/4 supporting • {attacks}/4 opposing source families • '+r.get('detail',''),
            'source_read':r}


def _v261_command_center_once(self, now=None):
    r=getattr(self,'_v259_flip_last',{}) or {}
    holds=int(r.get('hold_evidence',0)); attacks=int(r.get('opposing_evidence',0))
    defended=r.get('defended','WAIT'); stage=r.get('stage','BUILDING')
    self._v239_last_read={'ready':stage not in ('BUILDING','DATA STALE','SOURCE ERROR'),
                        'hold':holds*25,'flip':attacks*25,'reliability':0,
                        'defended':defended,'attack':r.get('target','WAIT'),'stage':stage,
                        'hold_groups':holds,'flip_groups':attacks,'source_read':r}
    for name,value in {
        'v239_flip_headline_var':f'V21.61 SOURCE ENGINE • DEFENDING {defended} • {stage}',
        'v239_flip_confidence_var':f'{holds}/4 SUPPORTING • {attacks}/4 OPPOSING • evidence, not odds',
        'v239_flip_stage_var':f'{stage} → {r.get("target","WAIT")}',
        'v239_flip_accel_var':'Early warning can change; confirmed triggers use closed candles',
        'v239_flip_explain_var':r.get('detail','Loading'),
        'breakout_var':f'BREAKOUT: {stage} • '+r.get('detail',''),
        'trend_reversal_risk_var':f'FLIP WATCH: {r.get("target","WAIT")} • {stage}',
        'trend_reversal_detail_var':r.get('detail',''),
        'flip_survival_var':f'DEFENSE SUPPORT: {holds}/4 • {attacks}/4 opposing • not win odds',
        'flip_survival_detail_var':r.get('detail',''),
    }.items():
        _v256_var(getattr(self,name,None),value)
    self.flip_survival_value=holds*25
    try:
        _v239_set_family_text(self,'SOURCE REASONS: '+(', '.join(r.get('families',[])) or 'No clear setup'))
        self._draw_flip_survival_bar()
        _v261_draw_evidence_bar(self)
        canvas=getattr(self,'flip_survival_canvas',None)
        if canvas and getattr(self,'_flip_bar_items',None):
            canvas.itemconfigure(self._flip_bar_items[2],text=f'SUPPORT {holds}/4 • OPPOSING {attacks}/4')
    except Exception:
        pass
    market=getattr(self,'_v256_market_last',None)
    if isinstance(market,dict):
        market['pine_sources']=getattr(self,'_v261_source_last',{})
        market['pine_flip']=r
    _v261_source_panel(self)


def _v261_draw_evidence_bar(self):
    canvas=getattr(self,'_v239_flip_bar',None)
    if canvas is None:
        return
    r=getattr(self,'_v259_flip_last',{}) or {}
    holds,attacks=r.get('hold_evidence',0),r.get('opposing_evidence',0)
    w=max(240,canvas.winfo_width()); h=max(24,canvas.winfo_height())
    key=(w,h,holds,attacks)
    if key==getattr(self,'_v261_evidence_bar_key',None):
        return
    self._v261_evidence_bar_key=key
    canvas.delete('all')
    canvas.create_rectangle(1,1,w-1,h-1,fill='#182332',outline='')
    for i in range(4):
        x=2+i*w/8
        canvas.create_rectangle(x,2,x+w/8-3,h-2,fill=GREEN if i<holds else '#263746',outline='')
        x=w/2+i*w/8
        canvas.create_rectangle(x,2,x+w/8-3,h-2,fill=RED if i<attacks else '#263746',outline='')
    canvas.create_text(w/2,h/2,text=f'SUPPORT {holds}/4 | OPPOSING {attacks}/4 — not probabilities',
                       fill=TEXT,font=('Segoe UI',9,'bold'))


def _v261_source_panel(self):
    try:
        panel=getattr(self,'_v261_panel',None)
        if panel is None:
            page=getattr(self,'page_frame',None)
            if page is None:
                return
            panel=tk.Frame(page,bg='#0b101b',highlightthickness=1,highlightbackground='#438dba')
            after=getattr(self,'_v257_scalp_panel',None)
            panel.pack(fill='x',padx=10,pady=4,**({'after':after} if after else {}))
            self._v261_panel=panel
            self._v261_source_text=tk.StringVar(value='Loading source indicators')
            tk.Label(panel,textvariable=self._v261_source_text,bg='#0b101b',fg='#dcecff',
                     justify='left',anchor='w',font=('Segoe UI',10),wraplength=1050).pack(fill='x',padx=10,pady=6)
            self._v261_oscillator=tk.Canvas(panel,height=105,bg='#0b101b',highlightthickness=0)
            self._v261_oscillator.pack(fill='x',padx=10,pady=(0,6))
        source=getattr(self,'_v261_source_packet',{}) or {}
        sec=int(getattr(self,'chart_interval_seconds',60))
        packet=source.get('frames',{}).get(sec,{})
        data=packet.get('preview') or packet.get('closed')
        if not data:
            self._v261_source_text.set('V21.61 • Loading source candles for selected chart')
            return
        ci,sc,flow,pa=(data[k] for k in ('cipher','scout','flow','pac'))
        arrow=lambda s:'UP' if s>0 else 'DOWN' if s<0 else 'WAIT'
        state='DEVELOPING — may change' if data.get('developing') else 'CLOSED CANDLE'
        names=' / '.join(ci['labels']) or 'No new momentum crossover'
        watch=sc.get('watch')
        gainz=data['gainz']
        gainzline=(f'Last engulfing call {arrow(gainz["side"])} • underlying stop {gainz["stop"]:.2f} / target {gainz["target"]:.2f}'
                   if gainz.get('side') else 'Engulfing call: waiting')
        shapes=', '.join(p['name'].title() for p in packet.get('patterns',[])) or 'No single-candle pattern'
        self._v261_source_text.set(
            f'V21.62 SOURCE INDICATORS • {sec}s chart • {state}\n'
            f'MOMENTUM: {names} • CANDLE PRESSURE: {ci["candle_pressure"]:+.1f} (not executed order flow)\n'
            f'REVERSAL SCOUT: UP {sc["scores"][1]}/10 • DOWN {sc["scores"][-1]}/10 • '
            +(f'Watch {arrow(watch["side"])} beyond {watch["trigger"]:.2f}' if watch else sc['action'])
            +(' • Scout calls require 1m, 3m or 5m' if not sc['supported'] else '')+'\n'
            f'PRICE STRUCTURE: short-term {arrow(pa["internal_trend"])} • major {arrow(pa["swing_trend"])} • '
            f'15m FLOW SCORE: {flow["up_score"]} UP / {flow["down_score"]} DOWN (not odds)'
            +(' • Flow entries require 1m or faster' if not flow['supported'] else '')
            +'\n'+gainzline+' • Candle context: '+shapes
        )
        canvas=self._v261_oscillator
        w=max(300,canvas.winfo_width()); h=105
        key=(source.get('time'),sec,w)
        if key==getattr(self,'_v261_osc_key',None):
            return
        self._v261_osc_key=key
        canvas.delete('all')
        values=packet.get('plots',[])[-100:]
        if not values:
            return
        y=lambda value:h/2-_pclip(value,-120,120)/120*(h/2-8)
        for level in (-60,0,60):
            canvas.create_line(0,y(level),w,y(level),fill='#29394b',dash=(3,3))
        for k,color in (('wave_fast','#90caf9'),('wave_slow','#277fff'),('pressure','#48d997')):
            points=[]
            for i,row in enumerate(values):
                if _pvalid(row[k]):
                    points.extend((i*w/max(1,len(values)-1),y(row[k])))
            if len(points)>=4:
                canvas.create_line(*points,fill=color,width=2)
        canvas.create_text(6,5,anchor='nw',text='Fast momentum / Slow momentum / Candle pressure • closed bars',fill='#cadcec',font=('Segoe UI',8))
    except Exception as exc:
        self._v261_panel_error=str(exc)


def _v261_update_reversal_panel(self, *args, **kwargs):
    _v261_command_center_once(self)


def _v261_update_survival_panel(self, *args, **kwargs):
    _v261_command_center_once(self)


def _v261_filter_trend_state(self, trend_state=None, now=None):
    r=getattr(self,'_v259_flip_last',{}) or {}
    return {**dict(trend_state or {}),'risk':25*r.get('opposing_evidence',0),
            'status':'BREAKOUT CONFIRMED' if r.get('confirmed') else 'WATCH',
            'detail':r.get('detail','Loading'),'pine_sources':getattr(self,'_v261_source_last',{}),
            'pine_flip':r,'breakout_persistence':r.get('stage','BUILDING')}


_V261_PATTERN_WRITE=_v260_pattern_memory_once


def _v261_pattern_memory_once(self, now=None):
    now=float(now or time.time())
    if getattr(self,'_v261_memory_busy',False) or now-float(getattr(self,'_v261_memory_scan',0))<3:
        return False
    self._v261_memory_scan=now
    histories={}
    for sec in (15,30,60,180,300,900):
        try:
            histories[sec]=[dict(r) for r in list(self._history_for_interval(sec))[-120:] if float(r['time'])+sec<=now]
        except Exception:
            histories[sec]=[]
    self._v261_memory_busy=True
    def write():
        try:
            import types
            proxy=types.SimpleNamespace(
                _v260_last_pattern_scan=0, _v260_last_closed_by_tf=dict(getattr(self,'_v260_last_closed_by_tf',{})),
                _v260_pattern_stats={}, _history_for_interval=lambda sec:histories.get(sec,[]),
                _v256_market_last={}, bookmap_wave_last={}, _v259_flip_last={},
                stockpile_db_lock=self.stockpile_db_lock, _stockpile_connect=self._stockpile_connect)
            _V261_PATTERN_WRITE(proxy,now=now)
            self._v260_last_closed_by_tf=proxy._v260_last_closed_by_tf
            self._v260_pattern_stats=proxy._v260_pattern_stats
        finally:
            self._v261_memory_busy=False
    threading.Thread(target=write,name='BookmapKing-CandleMemory',daemon=True).start()
    return True


_V261_BASE_DRAW_CHART=ChartKingPro.draw_chart


def _v261_draw_chart(self,*args,**kwargs):
    result=_V261_BASE_DRAW_CHART(self,*args,**kwargs)
    if result is False:
        return result
    c=getattr(self,'canvas',None); scale=getattr(self,'_v82_chart_scale',{}) or {}
    if c is None or not scale:
        return result
    try:
        c.delete('v261_sources')
        sec=int(getattr(self,'chart_interval_seconds',60))
        packet=(getattr(self,'_v261_source_packet',{}) or {}).get('frames',{}).get(sec,{})
        data=packet.get('preview') or packet.get('closed') or {}
        rows=_v257_clean_rows(self._chart_candles(),int(getattr(self,'visible_count',80)))
        if not data or not rows:
            return result
        left,right,top,ph,lo,hi=(float(scale[k]) for k in ('left','plot_right','top','ph','lo','hi'))
        step=(right-left)/max(1,len(rows))
        positions={int(r['time']):left+(i+.5)*step for i,r in enumerate(rows)}
        def y(p):
            return top+(hi-float(p))/max(hi-lo,1e-9)*ph
        def visible(p):
            return _pvalid(p) and lo<=p<=hi
        plots=packet.get('plots',[])
        for n,color in zip((5,11,15,18,21,25,29,33),('#00a8ff','#249eff','#48adff','#68bfff','#91cfff','#addcff','#c8e7ff','#ddecff')):
            points=[]
            for item in plots:
                x=positions.get(int(item['time'])); p=item['ribbon'][n]
                if x is not None and visible(p):
                    points.extend((x,y(p)))
            if len(points)>=4:
                c.create_line(*points,fill=color,width=1,tags=('v261_sources',))
        allframes=(getattr(self,'_v261_source_packet',{}) or {}).get('frames',{})
        zones=[]
        for frame in (14400,900,60):
            if frame<sec:
                continue
            p=allframes.get(frame,{})
            value=p.get('closed') or {}
            zones.extend(dict(z,seconds=frame) for z in value.get('pac',{}).get('blocks',[])[:10])
        for zone in zones:
            if zone['breaker'] or zone['top']<lo or zone['bottom']>hi:
                continue
            x=positions.get(int(zone['time']),left)
            if zone['time']>rows[-1]['time']:
                continue
            color='#55cc99' if zone['side']>0 else '#ff6599'
            c.create_rectangle(x,y(min(hi,zone['top'])),right,y(max(lo,zone['bottom'])),
                               outline=color,stipple='gray12',fill=color,tags=('v261_sources',))
            c.create_text(right-5,y(min(hi,zone['top']))+8,anchor='e',fill=color,
                          text=f'{zone["seconds"]//60}m '+('BUYER ORIGIN ZONE' if zone['side']>0 else 'SELLER ORIGIN ZONE'),
                          font=('Segoe UI',8),tags=('v261_sources',))
        for line in data.get('pac',{}).get('trendlines',[]):
            if not _pvalid(line['width']):
                continue
            color='#a55365' if line['kind']=='high' else '#599977'
            endtime=data['time']; starttime=max(rows[0]['time'],line['start']['time'])
            if starttime>endtime:
                continue
            p1=line['current']-line['slope']*(endtime-starttime)/sec
            x1=left+(starttime-rows[0]['time'])/sec*step
            x2=positions.get(int(endtime),right)
            for delta in (0,line['width']*(1 if line['kind']=='high' else -1)):
                # Clip to the existing chart range; these overlays never rescale candles.
                c.create_line(x1,y(_pclip(p1+delta,lo,hi)),x2,y(_pclip(line['current']+delta,lo,hi)),
                              fill=color,dash=(4,2),tags=('v261_sources',))
        for event in packet.get('events',[])[-35:]:
            x=positions.get(int(event['time'])); price=event.get('price')
            if x is None or not visible(price):
                continue
            side=event['side']; label=event['label']
            if event.get('source')=='SCOUT' and event.get('action')!='SOURCE BUY':
                label+=' • '+str(event.get('action','WAIT'))
            c.create_text(x,max(top+8,min(top+ph-8,y(price)+18*side)),text=label,
                          fill='#57eead' if side>0 else '#ff78a8',anchor='n' if side>0 else 's',
                          font=('Segoe UI',8,'bold'),tags=('v261_sources',))
        ci=data['cipher']; sc=data['scout']; pa=data['pac']
        plain=' / '.join(ci['labels']) or ('Momentum leaning up' if ci['wave_gap']>0 else 'Momentum leaning down')
        label=f'V21.61 • {sec}s SOURCES • '+('DEVELOPING' if data.get('developing') else 'CLOSED')
        text=label+'\n'+plain+f' • Reversal setup UP {sc["scores"][1]}/10 / DOWN {sc["scores"][-1]}/10'
        c.create_rectangle(left+5,top+110,min(right-5,left+650),top+158,fill='#0b101b',outline='#438dba',tags=('v261_sources',))
        c.create_text(left+12,top+119,text=text,anchor='nw',fill='#dcecff',
                      font=('Segoe UI',9),width=max(100,min(630,right-left-30)),tags=('v261_sources',))
        c.tag_raise('v82_live')
    except Exception as exc:
        self._v261_chart_error=str(exc)
    return result


