# BEGIN V21.62 LOCK METER UI FIX
# V21.62: keep the real Open Lock visible independently of Pine warmup.
# Presentation-only: target acquisition, lock rules and Pine calculations stay unchanged.

def _v262_open_lock(self, now):
    bucket=int(now//900)*900
    for attr in ('_v240_earned_open_lock','opening_lock_snapshot'):
        snap=dict(getattr(self,attr,None) or {})
        side=_v252_side(snap.get('lock_side'))
        stamp=snap.get('bucket')
        if stamp is None and snap.get('time') is not None:
            stamp=int(float(snap['time'])//900)*900
        if stamp is None and attr=='opening_lock_snapshot':
            stamp=getattr(self,'opening_lock_bucket',None)
        if side in ('UP','DOWN') and stamp is not None and int(stamp)==bucket:
            return snap
    return {}


def _v262_meter_read(self, now=None, radar=None):
    now=float(time.time() if now is None else now)
    r=dict(getattr(self,'_v259_flip_last',{}) if radar is None else radar)
    snap=_v262_open_lock(self,now)
    opened=_v252_side(snap.get('lock_side'))
    defended=opened
    # Keep the established distinction if an existing confirmed rotation is active.
    rotation=dict(getattr(self,'_v238_defense_rotation',{}) or {})
    if opened!='WAIT' and rotation.get('bucket')==int(now//900)*900:
        rotated=_v252_side(rotation.get('side'))
        if rotated!='WAIT':
            defended=rotated
    stage=str(r.get('stage') or 'BUILDING')
    identity=getattr(self,'_v261_verdict_identity',None)
    if identity and (identity[1]!=int(now//900) or identity!=_v261_identity(self,now)):
        # No previous-market evidence leaks into a newly earned opening call.
        r=PineFlipRead.empty('BUILDING','Loading evidence for this market')
        stage='BUILDING'
    evidence_ready=stage not in ('BUILDING','DATA STALE','SOURCE ERROR')
    sign=1 if defended=='UP' else -1 if defended=='DOWN' else 0
    hypotheses=r.get('hypotheses') or {}
    if sign and evidence_ready:
        supporting=list(hypotheses.get(sign,hypotheses.get(str(sign),[])) or [])
        opposing=list(hypotheses.get(-sign,hypotheses.get(str(-sign),[])) or [])
    else:
        supporting,opposing=[],[]
    r.update(open_lock_side=opened,defended=defended,lock_ready=bool(snap),
             evidence_ready=evidence_ready,hold_evidence=min(4,len(supporting)),
             opposing_evidence=min(4,len(opposing)),supporting_families=supporting,
             opposing_families=opposing)
    self._v262_meter_last=r
    return r


def _v262_context(r):
    if not r['lock_ready']:
        return 'OPEN LOCK: WAITING'
    if r['open_lock_side']!=r['defended']:
        return f'OPEN {r["open_lock_side"]} • DEFENDING {r["defended"]}'
    return f'OPEN {r["open_lock_side"]} LOCKED • DEFENDING {r["defended"]}'


def _v262_evidence_text(r):
    if not r['lock_ready']:
        return 'Waiting for an earned Open Lock'
    if not r['evidence_ready']:
        return {'DATA STALE':'Live data stale — evidence paused',
                'SOURCE ERROR':'Source calculation unavailable — evidence paused'}.get(
                    r['stage'],'Pine history warming up — evidence pending')
    return f'{r["hold_evidence"]}/4 supporting • {r["opposing_evidence"]}/4 opposing'


_V262_BASE_RADAR=_v261_flip_radar_read


def _v262_flip_radar_read(self,now=None,**kwargs):
    now=float(time.time() if now is None else now)
    raw=_V262_BASE_RADAR(self,now=now,**kwargs)
    read=_v262_meter_read(self,now=now,radar=raw)
    self._v259_flip_last=read
    return read


def _v262_survival_read(self,*args,**kwargs):
    r=_v262_meter_read(self,now=kwargs.get('now'))
    ready=r['lock_ready'] and r['evidence_ready']
    return {'ready':ready,'value':r['hold_evidence']*25 if ready else 50.0,
            'label':r['stage'],'side':r['defended'],
            'detail':_v262_context(r)+' • '+_v262_evidence_text(r),
            'source_read':r}


def _v262_draw_meter(self,canvas_attr,kind,now=None):
    canvas=getattr(self,canvas_attr,None)
    if canvas is None:
        return
    r=_v262_meter_read(self,now=now)
    width=max(160,int(canvas.winfo_width()))
    height=max(24,int(canvas.winfo_height()))
    side=r['defended']
    ready=r['lock_ready'] and r['evidence_ready']
    hold,attack=r['hold_evidence'],r['opposing_evidence']
    if not r['lock_ready']:
        caption='OPEN LOCK: WAITING'
    elif not ready:
        caption=f'{side} LOCKED • '+('DATA STALE' if r['stage']=='DATA STALE' else 'SOURCE ERROR' if r['stage']=='SOURCE ERROR' else 'EVIDENCE WARMING UP')
    elif kind=='support':
        caption=f'DEFENDING {side} • SUPPORT {hold}/4'
    elif kind=='attack':
        caption=f'AGAINST {side} • PRESSURE {attack}/4'
    else:
        caption=f'DEFENDING {side} • SUPPORT {hold}/4 | AGAINST {attack}/4'
    key=(id(canvas),width,height,caption,hold,attack,ready)
    cache=getattr(self,'_v262_meter_draw_keys',None)
    if cache is None:
        cache={}; self._v262_meter_draw_keys=cache
    if cache.get(canvas_attr)==key:
        return
    cache[canvas_attr]=key
    canvas.delete('all')
    canvas.create_rectangle(1,1,width-1,height-1,fill='#1a2432',outline='')
    if ready:
        counts=[(hold,'#24816b'),(attack,'#97475b')] if kind=='both' else [(hold,'#24816b')] if kind=='support' else [(attack,'#97475b')]
        segments=4*len(counts)
        for group,(count,color) in enumerate(counts):
            for i in range(4):
                x=2+(group*4+i)*(width-4)/segments
                canvas.create_rectangle(x,2,x+(width-4)/segments-2,height-2,
                    fill=color if i<count else '#263746',outline='')
    canvas.create_text(width/2,height/2,text=caption,fill='#e5edf8',font=('Segoe UI',9,'bold'))


def _v262_draw_survival_bar(self):
    _v262_draw_meter(self,'flip_survival_canvas','support')


def _v262_draw_trend_bar(self):
    _v262_draw_meter(self,'trend_reversal_risk_canvas','attack')


def _v262_draw_evidence_bar(self):
    _v262_draw_meter(self,'_v239_flip_bar','both')


def _v262_radar_labels(self,r):
    target=_v252_side(r.get('target'))
    headline=(_v262_context(r)+'\n'+r['stage']+(f' → {target}' if target!='WAIT' else ''))
    _v256_var(getattr(self,'flip_radar_verdict_var',None),headline)
    _v256_var(getattr(self,'flip_radar_detail_var',None),_v262_evidence_text(r)+' • '+r.get('detail',''))


def _v262_command_center_once(self,now=None):
    now=float(time.time() if now is None else now)
    r=_v262_meter_read(self,now=now)
    hold,attack=r['hold_evidence'],r['opposing_evidence']
    context=_v262_context(r); evidence=_v262_evidence_text(r)
    stage=r['stage']; defended=r['defended']
    ready=r['lock_ready'] and r['evidence_ready']
    self._v239_last_read={'ready':ready,'hold':hold*25,'flip':attack*25,'reliability':0,
                        'defended':defended,'attack':r.get('target','WAIT'),'stage':stage,
                        'hold_groups':hold,'flip_groups':attack,'source_read':r}
    fields={
        'v239_flip_headline_var':f'V21.62 • {context}',
        'v239_flip_confidence_var':evidence+' • evidence, not odds',
        'v239_flip_stage_var':stage,
        'v239_flip_accel_var':'Open Lock remains visible while source evidence warms up',
        'v239_flip_explain_var':r.get('detail','Loading source evidence'),
        'trend_reversal_status_var':context+'\n'+stage,
        'breakout_var':f'BREAKOUT • {context} • {stage}',
        'trend_reversal_risk_var':f'AGAINST {defended}: {attack}/4 source families' if ready else context+' • '+evidence,
        'trend_reversal_detail_var':context+' • '+r.get('detail',''),
        'flip_survival_var':f'FLIP SURVIVAL • DEFENDING {defended}' if r['lock_ready'] else 'FLIP SURVIVAL • OPEN LOCK WAITING',
        'flip_survival_detail_var':evidence+' • '+r.get('detail',''),
    }
    for name,value in fields.items():
        _v256_var(getattr(self,name,None),value)
    # Neutral backing values keep old presentation callbacks from displaying danger
    # merely because no source data exists; the visible meters explicitly say pending.
    self.flip_survival_value=hold*25 if ready else 50.0
    self.trend_reversal_risk_value=attack*25 if ready else 0.0
    label=getattr(self,'trend_reversal_status_label',None)
    if label is not None:
        try:
            label.configure(fg='#ffac68' if ready and attack>hold else '#6fc7ff' if r['lock_ready'] else '#b4bfcd')
        except Exception:
            pass
    for attr,kind in (('flip_survival_canvas','support'),('trend_reversal_risk_canvas','attack'),('_v239_flip_bar','both')):
        try:
            _v262_draw_meter(self,attr,kind,now=now)
        except Exception:
            pass
    _v262_radar_labels(self,r)
    try:
        _v239_set_family_text(self,'SUPPORT: '+(', '.join(r['supporting_families']) or 'none available')+
                             '\nOPPOSING: '+(', '.join(r['opposing_families']) or 'none available'))
    except Exception:
        pass
    market=getattr(self,'_v256_market_last',None)
    if isinstance(market,dict):
        market['pine_sources']=getattr(self,'_v261_source_last',{})
        market['pine_flip']=r
    _v261_source_panel(self)


def _v262_update_reversal_panel(self,*args,**kwargs):
    _v262_command_center_once(self)


def _v262_update_survival_panel(self,*args,**kwargs):
    _v262_command_center_once(self)


_V262_BASE_WARMUP=ChartKingPro._update_bookmap_warmup_meters


def _v262_update_warmup(self,*args,**kwargs):
    try:
        return _V262_BASE_WARMUP(self,*args,**kwargs)
    finally:
        # Existing warmup still updates its confidence/checkpoints. It cannot leave
        # its old percentage captions on top of the new source meters.
        _v262_command_center_once(self)


_V262_BASE_UPDATE=_v257_update


def _v262_update(self,now=None):
    result=_V262_BASE_UPDATE(self,now=now)
    _v262_radar_labels(self,_v262_meter_read(self,now=now))
    return result


