ChartKingPro._v257_update=_v262_update

# END V21.62 LOCK METER UI FIX


# BEGIN V21.63 BALANCED DESTINATION FUSION
# V21.63 BALANCED DESTINATION FUSION
#
# Adds source-derived indicator context to the existing whole-round decision
# without turning the bot into a reactive indicator vote counter.
#
# Design contract:
# - V21.52 Bookmap TAPE / WHALE / STRUCTURE / TARGET remain the core authority.
# - Pine-derived structure/path, momentum/money-flow and reversal/trigger reads
#   are collapsed into ONE capped destination-context modifier.
# - Correlated indicators cannot become separate votes.
# - The Pine modifier may strengthen, weaken or delay a call, but core Bookmap
#   evidence must still support the side.
# - Accumulation/distribution and chart/candlestick patterns are contextual
#   evidence, never guaranteed forecasts.

_V263_VERSION = 'V21.63 BALANCED DESTINATION FUSION'
_V263_PINE_CAP = 0.65
_V263_OPEN_MODIFIER = 0.12
_V263_CONTEXT_WEIGHT = 0.24


def _v263_signed(side):
    side = str(side or 'WAIT').upper()
    return 1.0 if side == 'UP' else -1.0 if side == 'DOWN' else 0.0


def _v263_mean(values, default=0.0):
    vals = [float(x) for x in values if _pvalid(x)]
    return sum(vals) / len(vals) if vals else float(default)


def _v263_history_rows(self, seconds, now=None, limit=96):
    """Cheap closed-bar fetch. Never fabricates missing bars."""
    now = float(now or time.time())
    try:
        rows = [dict(r) for r in list(self._history_for_interval(int(seconds)))[-int(limit):]]
        rows = _v257_clean_rows(rows, int(limit))
        return [r for r in rows if float(r.get('time', 0.0)) + int(seconds) <= now + 0.001]
    except Exception:
        return []


def _v263_true_range_rows(rows):
    out = []
    for i, row in enumerate(rows or []):
        h = float(row['high']); l = float(row['low'])
        pc = float((rows[i-1] if i else row)['close'])
        out.append(max(h-l, abs(h-pc), abs(l-pc)))
    return out


def _v263_cup_handle_read(rows):
    """Detect cup/handle and inverse cup/handle as a broad path pattern.

    This is deliberately conservative. A rounded cup without a controlled
    handle is reported as a developing rounded structure, not a confirmed
    cup-and-handle breakout.
    """
    rows = [dict(r) for r in (rows or [])][-64:]
    if len(rows) < 26:
        return {'ready': False, 'side': 'WAIT', 'score': 0.0, 'name': 'NONE', 'stage': 'BUILDING'}
    tr = _v263_true_range_rows(rows)
    atr = max(1e-9, _v263_mean(tr[-14:], 1.0))
    n = min(48, len(rows))
    w = rows[-n:]
    close = float(w[-1]['close'])
    cup_n = max(20, int(n * 0.76))
    cup = w[:cup_n]
    handle = w[cup_n-1:]
    if len(handle) < 4:
        return {'ready': False, 'side': 'WAIT', 'score': 0.0, 'name': 'NONE', 'stage': 'BUILDING'}

    def bullish():
        q = max(4, len(cup)//4)
        left = max(float(r['high']) for r in cup[:q])
        right = max(float(r['high']) for r in cup[-q:])
        bottom_i = min(range(len(cup)), key=lambda i: float(cup[i]['low']))
        bottom = float(cup[bottom_i]['low'])
        depth = min(left, right) - bottom
        middle_ok = len(cup)*0.22 <= bottom_i <= len(cup)*0.78
        rims_ok = abs(left-right) <= max(atr*0.90, depth*0.28)
        depth_ok = atr*1.05 <= depth <= atr*16.0
        recovered = right-bottom >= depth*0.72
        handle_low = min(float(r['low']) for r in handle)
        handle_high = max(float(r['high']) for r in handle)
        handle_depth = max(0.0, max(left, right)-handle_low)
        handle_ok = handle_depth <= max(depth*0.46, atr*1.15) and handle_low >= bottom + depth*0.48
        trigger = max(left, right)
        confirmed = close > trigger + atr*0.04
        if not (middle_ok and rims_ok and depth_ok and recovered and handle_ok):
            return None
        quality = 0.64
        quality += 0.08 if abs(left-right) <= max(atr*0.55, depth*0.18) else 0.0
        quality += 0.07 if handle_depth <= depth*0.32 else 0.0
        quality += 0.12 if confirmed else 0.0
        return {'ready': True, 'side': 'UP', 'score': min(0.94, quality),
                'name': 'CUP AND HANDLE', 'stage': 'TRIGGER CONFIRMED' if confirmed else 'HANDLE FORMING',
                'trigger': trigger, 'invalidation': handle_low,
                'detail': f'rounded base depth {depth/atr:.1f} ATR • handle {handle_depth/max(depth,1e-9)*100:.0f}% of cup depth'}

    def bearish():
        q = max(4, len(cup)//4)
        left = min(float(r['low']) for r in cup[:q])
        right = min(float(r['low']) for r in cup[-q:])
        top_i = max(range(len(cup)), key=lambda i: float(cup[i]['high']))
        top = float(cup[top_i]['high'])
        depth = top - max(left, right)
        middle_ok = len(cup)*0.22 <= top_i <= len(cup)*0.78
        rims_ok = abs(left-right) <= max(atr*0.90, depth*0.28)
        depth_ok = atr*1.05 <= depth <= atr*16.0
        recovered = top-right >= depth*0.72
        handle_high = max(float(r['high']) for r in handle)
        handle_low = min(float(r['low']) for r in handle)
        handle_depth = max(0.0, handle_high-min(left, right))
        handle_ok = handle_depth <= max(depth*0.46, atr*1.15) and handle_high <= top - depth*0.48
        trigger = min(left, right)
        confirmed = close < trigger - atr*0.04
        if not (middle_ok and rims_ok and depth_ok and recovered and handle_ok):
            return None
        quality = 0.64
        quality += 0.08 if abs(left-right) <= max(atr*0.55, depth*0.18) else 0.0
        quality += 0.07 if handle_depth <= depth*0.32 else 0.0
        quality += 0.12 if confirmed else 0.0
        return {'ready': True, 'side': 'DOWN', 'score': min(0.94, quality),
                'name': 'INVERSE CUP AND HANDLE', 'stage': 'TRIGGER CONFIRMED' if confirmed else 'HANDLE FORMING',
                'trigger': trigger, 'invalidation': handle_high,
                'detail': f'rounded top depth {depth/atr:.1f} ATR • handle {handle_depth/max(depth,1e-9)*100:.0f}% of cup depth'}

    bull = bullish(); bear = bearish()
    if bull and bear:
        return bull if bull['score'] >= bear['score'] else bear
    return bull or bear or {'ready': False, 'side': 'WAIT', 'score': 0.0, 'name': 'NONE', 'stage': 'NO CLEAN HANDLE'}


def _v263_accumulation_distribution(self, warm=None, now=None):
    """Heuristic effort-vs-result read for accumulation/distribution.

    It combines a recent auction range with rejection, failed price progress,
    volume effort and *small* Bookmap effort-vs-result/depth context. It does not
    claim to identify hidden inventory with certainty.
    """
    now = float(now or time.time())
    rows = _v263_history_rows(self, 15, now=now, limit=56)
    seconds = 15
    if len(rows) < 18:
        rows = _v263_history_rows(self, 30, now=now, limit=48); seconds = 30
    if len(rows) < 16:
        rows = _v263_history_rows(self, 60, now=now, limit=40); seconds = 60
    if len(rows) < 14:
        return {'ready': False, 'state': 'BUILDING', 'side': 'WAIT', 'score': 0.0, 'confidence': 0.0,
                'detail': 'Need more short-horizon auction history'}

    recent = rows[-min(20, len(rows)):]
    prior = rows[-min(40, len(rows)):-len(recent)]
    if len(prior) < 8:
        prior = rows[:-len(recent)//2] or rows[:8]
    trs = _v263_true_range_rows(rows)
    atr = max(1e-9, _v263_mean(trs[-14:], 1.0))
    high = max(float(r['high']) for r in recent)
    low = min(float(r['low']) for r in recent)
    span = max(high-low, atr*0.25)
    prior_span = max((max(float(r['high']) for r in prior)-min(float(r['low']) for r in prior)) if prior else span, atr*0.25)
    compression = span/prior_span
    first = float(recent[0]['close']); last = float(recent[-1]['close'])
    net = (last-first)/span
    close_loc = (last-low)/span
    tol = max(atr*0.28, span*0.045)
    floor_touches = sum(1 for r in recent if float(r['low']) <= low+tol)
    ceil_touches = sum(1 for r in recent if float(r['high']) >= high-tol)

    lower_reject = 0; upper_reject = 0
    for r in recent:
        o=float(r['open']); c=float(r['close']); h=float(r['high']); l=float(r['low'])
        rng=max(h-l,1e-9); body=max(abs(c-o), rng*0.04)
        lower=min(o,c)-l; upper=h-max(o,c)
        if lower >= max(body*1.15, rng*0.34) and c >= l+rng*0.55:
            lower_reject += 1
        if upper >= max(body*1.15, rng*0.34) and c <= l+rng*0.45:
            upper_reject += 1

    lows=[float(r['low']) for r in recent]; highs=[float(r['high']) for r in recent]
    third=max(3,len(recent)//3)
    low_progress=(min(lows[-third:])-min(lows[:third]))/atr
    high_progress=(max(highs[-third:])-max(highs[:third]))/atr
    prior_trend = 0.0
    if prior:
        pspan=max(max(float(r['high']) for r in prior)-min(float(r['low']) for r in prior),atr)
        prior_trend=(float(prior[-1]['close'])-float(prior[0]['close']))/pspan

    vols=[float(r.get('volume', float('nan'))) for r in recent]
    pvols=[float(r.get('volume', float('nan'))) for r in prior]
    vnow=_v263_mean(vols,0.0); vprior=_v263_mean(pvols,0.0)
    effort = vprior>0 and vnow/vprior >= 1.12 and abs(net) <= 0.42

    wave = dict((warm or {}).get('wave') or getattr(self,'bookmap_wave_last',{}) or {})
    flow2 = float(wave.get('flow_2s',0.0) or 0.0)
    flow6 = float(wave.get('flow_6s',0.0) or 0.0)
    movebp = float(wave.get('move_2s_bp',0.0) or 0.0)
    depth = float(wave.get('depth_imbalance',0.0) or 0.0)
    flow = _v252_clip(flow2*0.62+flow6*0.38)

    acc = 0.0; dist = 0.0; acc_reasons=[]; dist_reasons=[]
    if compression <= 0.92:
        acc += .10; dist += .10; acc_reasons.append('range compression'); dist_reasons.append('range compression')
    if floor_touches >= 2:
        acc += min(.16,.055*floor_touches); acc_reasons.append(f'{floor_touches} floor tests')
    if ceil_touches >= 2:
        dist += min(.16,.055*ceil_touches); dist_reasons.append(f'{ceil_touches} ceiling tests')
    if lower_reject >= 2:
        acc += min(.20,.055*lower_reject); acc_reasons.append(f'{lower_reject} lower rejections')
    if upper_reject >= 2:
        dist += min(.20,.055*upper_reject); dist_reasons.append(f'{upper_reject} upper rejections')
    if low_progress >= -0.20:
        acc += .10; acc_reasons.append('downside progress failing')
    if high_progress <= 0.20:
        dist += .10; dist_reasons.append('upside progress failing')
    if close_loc >= .56:
        acc += .08
    if close_loc <= .44:
        dist += .08
    if effort:
        acc += .06; dist += .06
        acc_reasons.append('volume effort / limited result'); dist_reasons.append('volume effort / limited result')
    # Aggressive selling with little downside result is accumulation-like;
    # aggressive buying with little upside result is distribution-like.
    if flow <= -.18 and movebp >= -.35:
        acc += .18; acc_reasons.append('sell effort absorbed')
    if flow >= .18 and movebp <= .35:
        dist += .18; dist_reasons.append('buy effort absorbed')
    if depth >= .16:
        acc += .05
    elif depth <= -.16:
        dist += .05
    if abs(net) <= .38:
        acc += .05; dist += .05

    # Prior trend names re-accumulation / re-distribution, but does not force it.
    acc = min(1.0, acc); dist = min(1.0, dist)
    side='WAIT'; state='BALANCED AUCTION'; confidence=max(acc,dist)*100
    if acc >= .46 and acc >= dist+.07:
        side='UP'; state='POSSIBLE RE-ACCUMULATION' if prior_trend > .28 else 'POSSIBLE ACCUMULATION'
        signed=acc
        reasons=acc_reasons
    elif dist >= .46 and dist >= acc+.07:
        side='DOWN'; state='POSSIBLE RE-DISTRIBUTION' if prior_trend < -.28 else 'POSSIBLE DISTRIBUTION'
        signed=-dist
        reasons=dist_reasons
    else:
        signed=_v252_clip((acc-dist)*0.55)
        reasons=(acc_reasons if acc>=dist else dist_reasons)
    return {'ready': True,'state':state,'side':side,'score':_v252_clip(signed),'confidence':confidence,
            'accumulation':acc,'distribution':dist,'timeframe':seconds,'compression':compression,
            'floor_touches':floor_touches,'ceiling_touches':ceil_touches,
            'detail':state+' • '+(' • '.join(reasons[-4:]) if reasons else 'two-sided auction')}


def _v263_pattern_context(self, now=None):
    now=float(now or time.time())
    rows=_v263_history_rows(self,60,now=now,limit=88)
    if len(rows)<8:
        return {'ready':False,'score':0.0,'side':'WAIT','patterns':[],'cup_handle':{'ready':False}}
    candidates=[]
    try:
        ranked,_stage=self.expanded_pattern_scan(rows)
        for p in ranked[:5]:
            bias=int(p.get('bias',0) or 0); score=float(p.get('score',0) or 0)
            if bias:
                candidates.append({'name':str(p.get('name','PATTERN')),'side':'UP' if bias>0 else 'DOWN',
                                   'signed':(1 if bias>0 else -1)*_v252_clip((score-50.0)/45.0,0.0,.92),
                                   'strength':score/100.0,'stage':str(p.get('stage','DEVELOPING'))})
    except Exception:
        pass
    try:
        candles=_v260_single_candle_catalog(rows)
        for p in candles:
            bias=int(p.get('bias',0) or 0); q=float(p.get('quality',0) or 0)
            if bias and q>=.58:
                candidates.append({'name':str(p.get('name','CANDLE')),'side':'UP' if bias>0 else 'DOWN',
                                   'signed':(1 if bias>0 else -1)*min(.78,q),
                                   'strength':q,'stage':str(p.get('role','REVERSAL'))})
    except Exception:
        candles=[]
    cup=_v263_cup_handle_read(rows)
    if cup.get('ready'):
        candidates.append({'name':cup['name'],'side':cup['side'],
                           'signed':_v263_signed(cup['side'])*float(cup['score']),
                           'strength':float(cup['score']),'stage':cup.get('stage','DEVELOPING')})
    if not candidates:
        return {'ready':True,'score':0.0,'side':'WAIT','patterns':[],'cup_handle':cup}
    # Use the strongest bull and bear pattern once each; do not stack correlated shapes.
    bulls=sorted((x for x in candidates if x['signed']>0),key=lambda x:abs(x['signed']),reverse=True)
    bears=sorted((x for x in candidates if x['signed']<0),key=lambda x:abs(x['signed']),reverse=True)
    bull=abs(bulls[0]['signed']) if bulls else 0.0
    bear=abs(bears[0]['signed']) if bears else 0.0
    score=_v252_clip((bull-bear)*0.82,-.90,.90)
    side='UP' if score>=.16 else 'DOWN' if score<=-.16 else 'WAIT'
    top=[]
    if bulls: top.append(bulls[0])
    if bears: top.append(bears[0])
    top=sorted(top,key=lambda x:abs(x['signed']),reverse=True)
    return {'ready':True,'score':score,'side':side,'patterns':top,'cup_handle':cup}


def _v263_destination_context(self, warm=None, now=None):
    """One capped indicator family for the whole-round/path forecast."""
    now=float(now or time.time())
    bucket=int(now//900)*900
    cache=dict(getattr(self,'_v263_destination_cache',{}) or {})
    if int(cache.get('bucket',-1) or -1)==bucket and now-float(cache.get('ts',0) or 0)<.45:
        return dict(cache.get('value') or {})
    try:
        _v261_source_schedule(self,now)
    except Exception:
        pass
    packet=dict(getattr(self,'_v261_source_packet',{}) or {})
    primary=dict((packet.get('frames') or {}).get(60) or {})
    closed=dict(primary.get('closed') or {})
    preview=dict(primary.get('preview') or {})
    source=closed if closed.get('ready') else (preview if preview.get('ready') else closed)
    source_ready=bool(source and source.get('ready'))

    accum=_v263_accumulation_distribution(self,warm=warm,now=now)
    patterns=_v263_pattern_context(self,now=now)

    structure_parts=[]; structure_reasons=[]
    momentum_parts=[]; momentum_reasons=[]
    reversal_parts=[]; reversal_reasons=[]
    if source_ready:
        pac=dict(source.get('pac') or {})
        it=int(pac.get('internal_trend',0) or 0); st=int(pac.get('swing_trend',0) or 0)
        if it:
            structure_parts.append((_v252_clip(it),.34)); structure_reasons.append('PAC short '+('UP' if it>0 else 'DOWN'))
        if st:
            structure_parts.append((_v252_clip(st),.38)); structure_reasons.append('PAC major '+('UP' if st>0 else 'DOWN'))
        events=list(pac.get('events') or [])
        if events:
            side=float(events[-1].get('side',0) or 0)
            structure_parts.append((_v252_clip(side),.20)); structure_reasons.append(str(events[-1].get('label','structure event')))
        sweeps=list(pac.get('sweeps') or [])
        if sweeps:
            side=float(sweeps[-1].get('side',0) or 0)
            structure_parts.append((_v252_clip(side),.18)); structure_reasons.append(str(sweeps[-1].get('label','liquidity sweep')))

        ci=dict(source.get('cipher') or {})
        gap=float(ci.get('wave_gap',0.0) or 0.0); pressure=float(ci.get('candle_pressure',0.0) or 0.0)
        momentum_parts.append((math.tanh(gap/28.0),.42)); momentum_parts.append((math.tanh(pressure/38.0),.28))
        if ci.get('cross_up'): momentum_parts.append((.78,.18)); momentum_reasons.append('Cipher turn UP')
        if ci.get('cross_down'): momentum_parts.append((-.78,.18)); momentum_reasons.append('Cipher turn DOWN')
        flow=dict(source.get('flow') or {})
        fparts=dict(flow.get('parts') or {})
        fm=float(fparts.get('trend',0.0) or 0.0)+float(fparts.get('momentum',0.0) or 0.0)
        momentum_parts.append((math.tanh(fm/18.0),.30))
        if gap*pressure>0 and abs(gap)>2:
            momentum_reasons.append('wave + pressure aligned '+('UP' if gap>0 else 'DOWN'))

        scout=dict(source.get('scout') or {})
        scores=scout.get('scores') or {}
        su=float(scores.get(1,0) or 0); sd=float(scores.get(-1,0) or 0)
        reversal_parts.append((_v252_clip((su-sd)/7.0),.38))
        rside=int(scout.get('reversal',0) or 0); setup=int(scout.get('setup_side',0) or 0)
        if rside:
            reversal_parts.append((_v252_clip(rside),.34)); reversal_reasons.append('Scout confirmed '+('UP' if rside>0 else 'DOWN'))
        elif setup:
            reversal_parts.append((_v252_clip(setup)*.62,.22)); reversal_reasons.append('Scout setup '+('UP' if setup>0 else 'DOWN'))
        gainz=dict(source.get('gainz') or {})
        g=int(gainz.get('signal',0) or gainz.get('raw',0) or 0)
        if g:
            reversal_parts.append((_v252_clip(g)*.76,.28)); reversal_reasons.append('engulfing '+('UP' if g>0 else 'DOWN'))

    if accum.get('ready'):
        structure_parts.append((float(accum.get('score',0.0) or 0.0),.30))
        if accum.get('side') in ('UP','DOWN'):
            structure_reasons.append(str(accum.get('state')))
    if patterns.get('ready'):
        pscore=float(patterns.get('score',0.0) or 0.0)
        structure_parts.append((pscore,.18))
        reversal_parts.append((pscore,.18))
        for p in patterns.get('patterns',[])[:2]:
            reversal_reasons.append(str(p.get('name')))

    def collapse(parts):
        live=[(float(v),float(w)) for v,w in parts if _pvalid(v) and w>0]
        if not live: return 0.0,False
        den=sum(w for _,w in live)
        return _v252_clip(sum(v*w for v,w in live)/max(den,1e-9)),True
    structure,structure_ready=collapse(structure_parts)
    momentum,momentum_ready=collapse(momentum_parts)
    reversal,reversal_ready=collapse(reversal_parts)
    sub={'structure_path':{'score':structure,'available':structure_ready},
         'momentum_flow':{'score':momentum,'available':momentum_ready},
         'reversal_trigger':{'score':reversal,'available':reversal_ready}}
    score,available=_v252_blend(((structure,.44,structure_ready),(momentum,.30,momentum_ready),(reversal,.26,reversal_ready)))
    score=_v252_clip(score,-_V263_PINE_CAP,_V263_PINE_CAP) if available else 0.0
    side='UP' if score>=.12 else 'DOWN' if score<=-.12 else 'WAIT'
    reasons=[]
    reasons.extend(structure_reasons[-2:]); reasons.extend(momentum_reasons[-1:]); reasons.extend(reversal_reasons[-2:])
    value={'ready':bool(available),'side':side,'score':score,'subfamilies':sub,
           'accumulation_distribution':accum,'patterns':patterns,
           'reason':' • '.join(reasons[-5:]) or 'indicator context mixed',
           'source_ready':source_ready,'ts':now}
    self._v263_destination_last=value
    self._v263_destination_cache={'bucket':bucket,'ts':now,'value':dict(value)}
    return value


_V263_BASE_DATA_CEILING = _v252_data_ceiling


def _v263_data_ceiling(self, warm=None, now=None):
    data=dict(_V263_BASE_DATA_CEILING(self,warm=warm,now=now) or {})
    dest=_v263_destination_context(self,warm=warm,now=now)
    data['destination_context']=dest
    return data


def _v263_bookmap_open(self, warm, now=None):
    """V21.52 core authority + one bounded destination-context modifier."""
    now=float(now or time.time())
    bucket=_v240_bucket(now)
    state=dict(getattr(self,'_v252_book_state',{}) or {})
    if int(state.get('bucket',-1) or -1)!=bucket:
        state={'bucket':bucket,'candidate':'WAIT','samples':0,'edge_ema':0.0,'flips':0,'last_eval':0.0}
        self._v252_bookmap_last={}; self.opening_lock_bucket=bucket
        self.opening_lock_snapshot=None; self.opening_lock_candidate=None; self.opening_lock_candidate_since=0.0
    if now-float(state.get('last_eval',0.0) or 0.0)<.12:
        return None

    data=_v263_data_ceiling(self,warm=warm,now=now)
    card=_v252_scorecard(data['families'],_V252_BOOK_WEIGHTS)
    if not bool(data['families']['tape'].get('available')):
        state['candidate']='WAIT'; state['samples']=0; state['last_eval']=now; self._v252_book_state=state
        self.opening_lock_candidate=None; self.opening_lock_candidate_since=0.0
        self.opening_lock_var.set('OPEN LOCK: BUILDING • waiting for fresh native Bookmap tape')
        return None

    core_edge=float(card.get('edge',0.0) or 0.0)
    dest=dict(data.get('destination_context') or {})
    pine=float(dest.get('score',0.0) or 0.0) if dest.get('ready') else 0.0
    final_edge=_v252_clip(core_edge + pine*_V263_OPEN_MODIFIER)
    # Preserve path authority: Pine can help a near-threshold core thesis, but it
    # cannot manufacture a call without two core families or while core evidence
    # materially points the other way.
    direction=1.0 if final_edge>0 else -1.0 if final_edge<0 else 0.0
    core_support=sum(1 for row in data['families'].values() if row.get('available') and float(row.get('score',0))*direction>=.14) if direction else 0
    core_oppose=sum(1 for row in data['families'].values() if row.get('available') and float(row.get('score',0))*direction<=-.20) if direction else 0
    path_support=any(data['families'][name].get('available') and float(data['families'][name].get('score',0))*direction>=.10 for name in ('structure','target')) if direction else False

    prior_ema=float(state.get('edge_ema',0.0) or 0.0)
    alpha=.36 if abs(final_edge)>=abs(prior_ema) else .24
    edge_ema=_v252_clip(prior_ema+(final_edge-prior_ema)*alpha)
    candidate='WAIT'
    if abs(edge_ema)>=.26 and core_support>=2 and core_oppose<=1 and path_support:
        candidate='UP' if edge_ema>0 else 'DOWN'
    old=_v252_side(state.get('candidate'))
    if candidate=='WAIT':
        state['candidate']='WAIT'; state['samples']=max(0,int(state.get('samples',0) or 0)-1)
    elif candidate!=old:
        if old in ('UP','DOWN'): state['flips']=int(state.get('flips',0) or 0)+1
        state['candidate']=candidate; state['samples']=1
    else:
        state['samples']=int(state.get('samples',0) or 0)+1
    state['edge_ema']=edge_ema; state['last_eval']=now; self._v252_book_state=state
    self.opening_lock_candidate=candidate if candidate in ('UP','DOWN') else None
    self.opening_lock_candidate_since=now if candidate in ('UP','DOWN') else 0.0
    needed=4 if abs(edge_ema)>=.48 and core_support>=3 else 7
    needed+=min(4,int(state.get('flips',0) or 0))
    last={**card,'core_edge':core_edge,'destination_score':pine,'edge':final_edge,'edge_ema':edge_ema,
          'candidate':candidate,'samples':int(state.get('samples',0) or 0),'needed':needed,
          'families':data['families'],'live':data.get('live'),'target':data.get('target'),'distance':data.get('distance',0.0),'data':data}
    self._v252_bookmap_last=last
    ad=dict(dest.get('accumulation_distribution') or {})
    context_tag=str(ad.get('state','')) if ad.get('side') in ('UP','DOWN') else ''
    pine_text=f'PINE {pine:+.2f}' if dest.get('ready') else 'PINE warming'
    if candidate=='WAIT':
        self.opening_lock_var.set(f'OPEN LOCK: BUILDING • DESTINATION EDGE {edge_ema:+.2f} • core {core_edge:+.2f} • {pine_text} • {core_support} core support / {core_oppose} oppose'+(f' • {context_tag}' if context_tag else ''))
        return None
    if int(state.get('samples',0) or 0)<needed:
        self.opening_lock_var.set(f'OPEN LOCK: FORMULATING {candidate} • {int(state.get("samples",0))}/{needed} clean observations • destination {edge_ema:+.2f} • core {core_edge:+.2f} • {pine_text}'+(f' • {context_tag}' if context_tag else ''))
        return None
    live=data.get('live')
    if live is None: return None
    grade='STRAIGHT' if needed<=4 else 'LEAN'
    reasons=f'V21.63 {grade} • core {card.get("reason","")} • destination context {pine:+.2f} {dest.get("reason","")} • {core_support} core families agree'
    snap={'time':now,'price':float(live),'lock_side':candidate,'lock_remaining':'OPEN','lock_minute':0,
          'forecast_score':edge_ema*10.0,'forecast_threshold':2.6,'forecast_reasons':reasons,
          'source':'BOOKMAP OPEN/NOW • V21.63 BALANCED DESTINATION'}
    self.opening_lock_snapshot=dict(snap); self.opening_lock_candidate=None; self.opening_lock_candidate_since=0.0
    self.opening_lock_var.set(f'OPEN LOCK: {candidate} LOCKED @ {money(live)} • V21.63 {grade} • destination {edge_ema:+.2f} • core {core_edge:+.2f} • {pine_text}')
    self._v252_bookmap_frozen=dict(last)
    try: self._checkpoint_status_summary()
    except Exception: pass
    return snap


def _v263_mm3_lock(self, mm, now=None):
    """Keep MODEL/TAPE/CONTEXT; Pine lives inside CONTEXT rather than a new vote."""
    now=float(now or time.time()); bucket=_v228_bucket(now)
    state=dict(getattr(self,'_v228_mm_lock_state',{}) or {})
    if int(state.get('bucket',-1) or -1)!=bucket:
        state=_v228_reset_lock_state(state,bucket); state['candidate_samples']=0
        self._v252_mm_last={}; self._v252_mm_frozen={}
    if int(getattr(self,'_v252_mm_output_bucket',-1) or -1)==bucket and now-float(getattr(self,'_v252_mm_last_eval',0.0) or 0.0)<.18:
        cached=dict(getattr(self,'_v252_mm_output',{}) or {})
        if cached: return cached
    raw=dict(mm or {}); settle=_v252_side(raw.get('settlement_side')); committed=_v252_side(raw.get('committed_side',settle))
    score=float(raw.get('settlement_score',raw.get('score',0.0)) or 0.0); conv=int(raw.get('settlement_convergence',0) or 0); fam=int(raw.get('family_count',0) or 0)
    sign=_v263_signed(settle); breadth=min(1.0,.70+min(3,conv)*.08+min(4,fam)*.035)
    model_score=sign*_v252_clip((score-50.0)/38.0,0.0,1.0)*breadth; model_ready=settle in ('UP','DOWN') and score>=50
    data=_v263_data_ceiling(self,warm=None,now=now); df=data['families']
    tape_score,tape_ready=_v252_blend(((df['tape']['score'],.66,df['tape']['available']),(df['whale']['score'],.34,df['whale']['available'])))
    core_context,core_context_ready=_v252_blend(((df['structure']['score'],.56,df['structure']['available']),(df['target']['score'],.44,df['target']['available'])))
    dest=dict(data.get('destination_context') or {}); pine=float(dest.get('score',0.0) or 0.0)
    context_score,context_ready=_v252_blend(((core_context,1.0-_V263_CONTEXT_WEIGHT,core_context_ready),(pine,_V263_CONTEXT_WEIGHT,bool(dest.get('ready')))))
    families={'model':{'score':model_score,'available':model_ready},'tape':{'score':tape_score,'available':tape_ready},'context':{'score':context_score,'available':context_ready}}
    card=_v252_scorecard(families,_V252_MM_WEIGHTS,threshold=.24,support_threshold=.12,oppose_threshold=.22)
    locked=_v252_side(state.get('locked')); candidate='WAIT'
    if settle in ('UP','DOWN') and committed in (settle,'WAIT') and score>=68 and card.get('side')==settle and int(card.get('support',0))>=2:
        candidate=settle
    if locked=='WAIT':
        old=_v252_side(state.get('candidate'))
        if candidate=='WAIT': state['candidate']='WAIT'; state['candidate_samples']=0
        elif candidate!=old: state['candidate']=candidate; state['candidate_samples']=1
        else: state['candidate_samples']=int(state.get('candidate_samples',0) or 0)+1
        strong=score>=85 and abs(float(card.get('edge',0)))>=.42 and int(card.get('support',0))>=3 and int(card.get('oppose',0))==0
        needed=3 if strong else 5
        if candidate in ('UP','DOWN') and int(state.get('candidate_samples',0))>=needed:
            state['locked']=candidate; state['locked_ts']=now; state['candidate']='WAIT'; state['candidate_samples']=0
            state['last_reason']=f'model {score:.0f}/100 • balanced edge {float(card.get("edge",0)):+.2f} • destination {pine:+.2f} • {card.get("support",0)} of 3 families'
            state['locked_grade']='STRAIGHT' if strong else 'LEAN'; state['locked_edge']=float(card.get('edge',0) or 0); state['locked_support']=int(card.get('support',0) or 0); locked=candidate
    else:
        state['candidate']='WAIT'; state['candidate_samples']=0; state['flip_candidate']='WAIT'; state['flip_since']=0.0
    self._v228_mm_lock_state=state; locked=_v252_side(state.get('locked'))
    grade='STRAIGHT' if abs(float(card.get('edge',0)))>=.48 and int(card.get('support',0))>=3 and int(card.get('oppose',0))==0 else 'LEAN' if candidate in ('UP','DOWN') or locked in ('UP','DOWN') else 'MIXED'
    last={**card,'grade':grade,'families':families,'model_side':settle,'model_score':score,'locked':locked,'destination_score':pine,'data':data}
    self._v252_mm_last=last
    if locked in ('UP','DOWN') and not getattr(self,'_v252_mm_frozen',None): self._v252_mm_frozen=dict(last)
    if locked in ('UP','DOWN'):
        grade=str(state.get('locked_grade',grade) or grade); opposite='DOWN' if locked=='UP' else 'UP'; pressure=card.get('side')==opposite and abs(float(card.get('edge',0)))>=.34
        text=f'TEAM MM3 LOCK: {locked} LOCKED • V21.63 {grade} • FIRST CALL FROZEN • model {score:.0f} • edge {float(card.get("edge",0)):+.2f} • destination {pine:+.2f}'
        if pressure: text+=f' • OPPOSITE {opposite} PRESSURE WATCH'
    elif candidate in ('UP','DOWN'):
        strong=score>=85 and abs(float(card.get('edge',0)))>=.42 and int(card.get('support',0))>=3 and int(card.get('oppose',0))==0; needed=3 if strong else 5
        text=f'TEAM MM3 LOCK: FORMULATING {candidate} • {int(state.get("candidate_samples",0))}/{needed} observations • model {score:.0f} • destination {pine:+.2f} • {card.get("reason","")}'
    else:
        text=f'TEAM MM3 LOCK: UNLOCKED • MODEL / TAPE / BALANCED CONTEXT • model {settle} {score:.0f} • edge {float(card.get("edge",0)):+.2f} • destination {pine:+.2f}'
    try:
        ad=dict(dest.get('accumulation_distribution') or {}); pnames=', '.join(str(p.get('name')) for p in (dest.get('patterns') or {}).get('patterns',[])[:2]) or 'mixed patterns'
        self.v233_mm3_grade_var.set(f'TEAM MM3 QUALITY: V21.63 {grade} • MODEL / TAPE / CONTEXT • PINE {pine:+.2f} • {ad.get("state","auction building")} • {pnames}')
    except Exception: pass
    out={'side':locked,'text':text,'state':state}; self._v252_mm_last_eval=now; self._v252_mm_output_bucket=bucket; self._v252_mm_output=dict(out); return out


