# ============================================================================
# BOOKMAP KING V21.64 — BOOKMAP MASTER EXECUTION + LIVE KALSHI PAPER JOURNAL
# ============================================================================
# Goals:
# - Keep V21.63 destination/pathing brain untouched.
# - One PAPER authority: BOOKMAP MASTER (the frozen Bookmap whole-round thesis).
# - Live Kalshi executable prices come from YES bid/ask, never midpoint fills.
# - WebSocket orderbook uses use_yes_price=True correctly; NO-side levels are
#   already on the YES price scale and therefore MUST NOT be flipped twice.
# - REST market/orderbook is an always-on watchdog/fallback so stationary books
#   do not become "stale" simply because no WebSocket price changed.
# - Paper fills, marks, exits, settlement and journal events are transactional.
# - V8.6 live-order TRANSPORT is restored only as an optional mirror of the
#   BOOKMAP MASTER paper events. It never supplies trading decisions.
# - LIVE AUTO is OFF by default and still requires the existing SUBMIT + VERIFY
#   credentials flow plus an explicit arm confirmation.
# ============================================================================

_V264_MAX_PAPER_ENTRY = 0.70
_V264_LIVE_STAKE_MAX = 10.0
_V264_DEFAULT_SLIP = 0.02
_V264_QUOTE_DIVERGENCE = 0.025
_V264_ENTRY_QUOTE_MAX_AGE = 2.75
_V264_EXIT_QUOTE_MAX_AGE = 4.0


def _v264_clip(v, lo=0.0, hi=1.0):
    try:
        return max(lo, min(hi, float(v)))
    except Exception:
        return lo


def _v264_level_dict(rows):
    out = {}
    for row in rows or []:
        try:
            p = float(row[0]); q = float(row[1])
        except Exception:
            continue
        if 0.0 < p < 1.0 and q > 0:
            out[round(p, 10)] = q
    return out


def _v264_book_from_yes_scaled(yes_levels, no_yes_levels):
    """Normalize WS orderbook when use_yes_price=True.

    YES-side prices are YES bids.
    NO-side prices are already expressed on YES scale; therefore the BEST NO
    bid corresponds to the LOWEST YES-scale NO level (the executable YES ask).
    """
    y = {float(p): float(q) for p, q in dict(yes_levels or {}).items() if float(q) > 0}
    n = {float(p): float(q) for p, q in dict(no_yes_levels or {}).items() if float(q) > 0}
    yes_bid = max(y, default=None)
    yes_ask = min(n, default=None)
    no_bid = (1.0 - yes_ask) if yes_ask is not None else None
    no_ask = (1.0 - yes_bid) if yes_bid is not None else None
    return yes_bid, yes_ask, no_bid, no_ask


def _v264_book_from_legacy_bids(yes_levels, no_levels):
    """Normalize REST orderbook, whose NO levels are still NO-leg bid prices."""
    y = {float(p): float(q) for p, q in dict(yes_levels or {}).items() if float(q) > 0}
    n = {float(p): float(q) for p, q in dict(no_levels or {}).items() if float(q) > 0}
    yes_bid = max(y, default=None)
    no_bid = max(n, default=None)
    yes_ask = (1.0 - no_bid) if no_bid is not None else None
    no_ask = (1.0 - yes_bid) if yes_bid is not None else None
    return yes_bid, yes_ask, no_bid, no_ask


def _v264_publish_normalized_book(self, ticker, yes_bid, yes_ask, no_bid, no_ask,
                                  source, *, yes_depth=0.0, no_depth=0.0,
                                  heartbeat_ts=None, last_yes=None):
    now = time.time()
    ticker = str(ticker or '').strip().upper()
    if not ticker:
        return {}
    old = dict(getattr(self, 'kalshi_orderbook', {}) or {})
    bid = _v75_prob(yes_bid); ask = _v75_prob(yes_ask)
    nb = _v75_prob(no_bid); na = _v75_prob(no_ask)
    if bid is not None and ask is not None and bid > ask + 1e-9:
        return old
    snap = dict(old)
    snap.update({
        'ticker': ticker,
        'ts': now,
        'heartbeat_ts': float(heartbeat_ts or now),
        'source': str(source),
        'best_yes_bid': bid,
        'yes_ask': ask,
        'best_no_bid': nb,
        'no_ask': na,
        'spread': (ask - bid) if bid is not None and ask is not None else None,
        'yes_depth': float(yes_depth or 0.0),
        'no_depth': float(no_depth or 0.0),
    })
    if last_yes is not None:
        snap['last_yes'] = _v75_prob(last_yes)
        snap['last_trade_ts'] = now
    with self.kalshi_book_lock:
        self.kalshi_orderbook = snap
        self.kalshi_orderbook_ts = now
        hist = list(getattr(self, 'kalshi_orderbook_history', []) or [])
        hist.append(dict(snap))
        cutoff = now - 120.0
        self.kalshi_orderbook_history = [x for x in hist[-800:] if float(x.get('ts', 0) or 0) >= cutoff and str(x.get('ticker', '')).upper() == ticker]
    return snap


def _v264_apply_ticker(self, msg, source='KALSHI WS TICKER'):
    ticker = str(msg.get('market_ticker') or msg.get('ticker') or '').strip().upper()
    if not ticker or ticker != _v75_current_ticker(self):
        return
    bid = _v75_prob(msg.get('yes_bid_dollars') if msg.get('yes_bid_dollars') is not None else msg.get('yes_bid'))
    ask = _v75_prob(msg.get('yes_ask_dollars') if msg.get('yes_ask_dollars') is not None else msg.get('yes_ask'))
    last = _v75_prob(msg.get('price_dollars') if msg.get('price_dollars') is not None else msg.get('last_price_dollars'))
    now = time.time()
    if bid is None and ask is None and last is None:
        return
    q = {'ticker': ticker, 'bid': bid, 'ask': ask, 'last': last, 'ts': now, 'source': source}
    self._v264_ticker_quote = q
    self._v264_ws_last_message_ts = now
    # Direct ticker bid/ask is authoritative for executable top-of-book.
    old = dict(getattr(self, 'kalshi_orderbook', {}) or {})
    yb = bid if bid is not None else old.get('best_yes_bid')
    ya = ask if ask is not None else old.get('yes_ask')
    nb = (1.0 - ya) if ya is not None else old.get('best_no_bid')
    na = (1.0 - yb) if yb is not None else old.get('no_ask')
    _v264_publish_normalized_book(self, ticker, yb, ya, nb, na, source,
                                  heartbeat_ts=now, last_yes=last)
    m = dict(self.kalshi_market or {})
    m['ticker'] = ticker
    if bid is not None:
        m['yes_bid_dollars'] = bid; m['no_ask_dollars'] = 1.0 - bid
    if ask is not None:
        m['yes_ask_dollars'] = ask; m['no_bid_dollars'] = 1.0 - ask
    if last is not None:
        m['last_price_dollars'] = last
    self.kalshi_market = m


def _v264_orderbook_ws_worker(self):
    try:
        import websocket
    except Exception as exc:
        self.kalshi_book_ws_error = f'websocket-client unavailable: {exc}'
        return
    while getattr(self, 'running', False):
        ticker = _v75_current_ticker(self)
        if not ticker or not self.kalshi_key_id_text or not self.kalshi_private_key_text:
            self.kalshi_book_ws_connected = False
            time.sleep(0.45)
            continue
        ws = None
        try:
            ws = websocket.create_connection(KALSHI_WS_URL, header=self._kalshi_orderbook_ws_headers(), timeout=10)
            ws.settimeout(4)
            ws.send(json.dumps({'id': 6401, 'cmd': 'subscribe', 'params': {'channels': ['orderbook_delta'], 'market_ticker': ticker, 'use_yes_price': True}}))
            ws.send(json.dumps({'id': 6402, 'cmd': 'subscribe', 'params': {'channels': ['ticker'], 'market_ticker': ticker}}))
            ws.send(json.dumps({'id': 6403, 'cmd': 'subscribe', 'params': {'channels': ['trade'], 'market_ticker': ticker}}))
            self.kalshi_book_ws_connected = True
            self.kalshi_book_ws_ticker = ticker
            self.kalshi_book_ws_error = ''
            self._v264_ws_last_message_ts = time.time()
            yes_levels = {}; no_yes_levels = {}
            while getattr(self, 'running', False) and _v75_current_ticker(self) == ticker:
                try:
                    raw = ws.recv()
                except Exception as exc:
                    if 'timed out' in str(exc).lower():
                        continue
                    raise
                if not raw:
                    continue
                message = json.loads(raw)
                mtype = str(message.get('type') or '')
                msg = message.get('msg') or {}
                self._v264_ws_last_message_ts = time.time()
                if mtype == 'error':
                    raise RuntimeError(msg.get('msg') or f'Kalshi WS error: {msg}')
                if mtype == 'ticker':
                    _v264_apply_ticker(self, msg)
                    self.kalshi_book_ws_updates += 1
                    continue
                if mtype == 'trade':
                    last = _v75_prob(msg.get('yes_price_dollars') or msg.get('price_dollars'))
                    if last is not None:
                        q = dict(getattr(self, '_v264_ticker_quote', {}) or {})
                        q.update({'ticker': ticker, 'last': last, 'ts': time.time(), 'source': 'KALSHI WS TRADE'})
                        self._v264_ticker_quote = q
                    self.kalshi_book_ws_updates += 1
                    continue
                if mtype == 'orderbook_snapshot':
                    if str(msg.get('market_ticker', '')).upper() != ticker:
                        continue
                    yes_levels = _v264_level_dict(msg.get('yes_dollars_fp') or msg.get('yes_dollars') or [])
                    # IMPORTANT: use_yes_price=True means these NO-side prices are
                    # already YES-scale asks. Do not 1-price them here.
                    no_yes_levels = _v264_level_dict(msg.get('no_dollars_fp') or msg.get('no_dollars') or [])
                elif mtype == 'orderbook_delta':
                    if str(msg.get('market_ticker', '')).upper() != ticker:
                        continue
                    side = str(msg.get('side', '')).lower()
                    if side not in ('yes', 'no'):
                        continue
                    try:
                        p = float(msg.get('price_dollars') if msg.get('price_dollars') is not None else msg.get('price'))
                        d = float(msg.get('delta_fp') if msg.get('delta_fp') is not None else msg.get('delta'))
                    except Exception:
                        continue
                    levels = yes_levels if side == 'yes' else no_yes_levels
                    qty = float(levels.get(p, 0.0)) + d
                    if qty <= 0:
                        levels.pop(p, None)
                    else:
                        levels[p] = qty
                else:
                    continue
                yb, ya, nb, na = _v264_book_from_yes_scaled(yes_levels, no_yes_levels)
                ydepth = sum(float(q) for p, q in yes_levels.items() if yb is not None and yb - float(p) <= .05)
                nbest = nb
                ndepth = sum(float(q) for p, q in no_yes_levels.items() if nbest is not None and nbest - (1.0-float(p)) <= .05)
                self._v264_book_quote = {'ticker': ticker, 'bid': yb, 'ask': ya, 'ts': time.time(), 'source': 'KALSHI WS ORDERBOOK'}
                _v264_publish_normalized_book(self, ticker, yb, ya, nb, na, 'KALSHI WS ORDERBOOK', yes_depth=ydepth, no_depth=ndepth, heartbeat_ts=self._v264_ws_last_message_ts)
                self.kalshi_book_ws_updates += 1
        except Exception as exc:
            self.kalshi_book_ws_error = str(exc)
        finally:
            self.kalshi_book_ws_connected = False
            if ws is not None:
                try: ws.close()
                except Exception: pass
        time.sleep(0.55)


def _v264_rest_refresh(self):
    ticker = _v75_current_ticker(self)
    if not ticker:
        return False
    now = time.time()
    direct = {}
    try:
        market = self._get_kalshi_market(ticker)
        if isinstance(market, dict):
            direct = dict(market)
    except Exception:
        try:
            data = http_json(KALSHI_BASE + '/markets/' + urllib.parse.quote(ticker), timeout=3.0)
            direct = dict(data.get('market') or data or {})
        except Exception as exc:
            self.kalshi_orderbook_error = str(exc)
    bid = _v75_prob(direct.get('yes_bid_dollars') or direct.get('yes_bid'))
    ask = _v75_prob(direct.get('yes_ask_dollars') or direct.get('yes_ask'))
    last = _v75_prob(direct.get('last_price_dollars') or direct.get('last_price'))
    if bid is not None or ask is not None:
        # Keep REST independent from the WebSocket ticker. It is a watchdog /
        # cross-check, not a replacement for a fresh WS quote. Only publish it
        # into the legacy/UI book when WS market data is unavailable or stale.
        self._v264_rest_quote = {'ticker': ticker, 'bid': bid, 'ask': ask, 'last': last, 'ts': now, 'source': 'KALSHI REST MARKET'}
        m = dict(self.kalshi_market or {})
        m.update(direct)
        m['ticker'] = ticker
        if bid is not None:
            m['yes_bid_dollars'] = bid; m['no_ask_dollars'] = 1.0-bid
        if ask is not None:
            m['yes_ask_dollars'] = ask; m['no_bid_dollars'] = 1.0-ask
        if last is not None:
            m['last_price_dollars'] = last
        self.kalshi_market = m
        ws_age = max(0.0, now-float(getattr(self,'_v264_ws_last_message_ts',0.0) or 0.0))
        if not getattr(self,'kalshi_book_ws_connected',False) or ws_age > 5.0:
            old = dict(getattr(self,'kalshi_orderbook',{}) or {})
            yb = bid if bid is not None else old.get('best_yes_bid')
            ya = ask if ask is not None else old.get('yes_ask')
            nb = (1.0-ya) if ya is not None else old.get('best_no_bid')
            na = (1.0-yb) if yb is not None else old.get('no_ask')
            _v264_publish_normalized_book(self,ticker,yb,ya,nb,na,'KALSHI REST MARKET',heartbeat_ts=now,last_yes=last)
    # Independent REST book cross-check. REST NO levels use NO-leg pricing.
    try:
        data = http_json(KALSHI_BASE + '/markets/' + urllib.parse.quote(ticker) + '/orderbook', {'depth': 30}, timeout=3.0)
        ob = dict(data.get('orderbook_fp') or data.get('orderbook') or {})
        yl = _v264_level_dict(ob.get('yes_dollars') or ob.get('yes_dollars_fp') or [])
        nl = _v264_level_dict(ob.get('no_dollars') or ob.get('no_dollars_fp') or [])
        yb, ya, nb, na = _v264_book_from_legacy_bids(yl, nl)
        self._v264_rest_book_quote = {'ticker': ticker, 'bid': yb, 'ask': ya, 'ts': now, 'source': 'KALSHI REST ORDERBOOK'}
    except Exception:
        pass
    return bid is not None or ask is not None


def _v264_quote_snapshot(self, max_age=3.0):
    ticker = _v75_current_ticker(self)
    if not ticker:
        return {}
    now = time.time()
    candidates = []
    for name in ('_v264_ticker_quote', '_v264_book_quote', '_v264_rest_quote', '_v264_rest_book_quote'):
        q = dict(getattr(self, name, {}) or {})
        if str(q.get('ticker', '')).upper() != ticker:
            continue
        age = max(0.0, now - float(q.get('ts', 0.0) or 0.0))
        if age <= float(max_age):
            q['age'] = age; candidates.append(q)
    # An unchanged WS book can remain executable; require recent WS traffic or a
    # fresh REST heartbeat rather than using the age of the last price change.
    ws_age = max(0.0, now - float(getattr(self, '_v264_ws_last_message_ts', 0.0) or 0.0))
    if not candidates and getattr(self, 'kalshi_book_ws_connected', False) and ws_age <= 5.0:
        try:
            with self.kalshi_book_lock:
                old = dict(self.kalshi_orderbook or {})
            if str(old.get('ticker', '')).upper() == ticker:
                candidates.append({'ticker': ticker, 'bid': old.get('best_yes_bid'), 'ask': old.get('yes_ask'), 'age': ws_age, 'ts': now-ws_age, 'source': 'KALSHI WS STATIONARY BOOK'})
        except Exception:
            pass
    if not candidates:
        return {}
    priority = {'KALSHI WS TICKER': 0, 'KALSHI REST MARKET': 1, 'KALSHI WS ORDERBOOK': 2, 'KALSHI REST ORDERBOOK': 3, 'KALSHI WS STATIONARY BOOK': 4}
    candidates.sort(key=lambda q: (priority.get(str(q.get('source')), 9), float(q.get('age', 999))))
    primary = candidates[0]
    bid = _v75_prob(primary.get('bid')); ask = _v75_prob(primary.get('ask'))
    if bid is None or ask is None or bid > ask:
        # Fill missing side from the freshest compatible source.
        for q in candidates[1:]:
            qb = _v75_prob(q.get('bid')); qa = _v75_prob(q.get('ask'))
            if bid is None and qb is not None: bid = qb
            if ask is None and qa is not None: ask = qa
            if bid is not None and ask is not None and bid <= ask: break
    if bid is None or ask is None or bid > ask:
        return {}
    healthy = True; divergence = 0.0; compared = []
    for q in candidates[1:]:
        qb = _v75_prob(q.get('bid')); qa = _v75_prob(q.get('ask'))
        if qb is None or qa is None: continue
        d = max(abs(qb-bid), abs(qa-ask)); divergence = max(divergence, d)
        compared.append(str(q.get('source')))
    if divergence > _V264_QUOTE_DIVERGENCE:
        healthy = False
    return {'ticker': ticker, 'yes_bid': float(bid), 'yes_ask': float(ask),
            'no_bid': 1.0-float(ask), 'no_ask': 1.0-float(bid),
            'spread': float(ask)-float(bid), 'age': float(primary.get('age', 0.0)),
            'source': str(primary.get('source') or 'KALSHI LIVE'),
            'healthy': bool(healthy), 'divergence': float(divergence),
            'cross_checked': compared}


def _v264_paper_price(self, direction, action='ENTER', max_age=3.0):
    q = _v264_quote_snapshot(self, max_age=max_age)
    if not q:
        return (None, None, 'NO FRESH KALSHI BBO', 999.0)
    direction = str(direction).upper(); action = str(action).upper()
    # Block NEW entries on a materially divergent feed. Exits are still allowed
    # from the freshest direct BBO so a safety exit is never trapped by audit.
    if action == 'ENTER' and not q.get('healthy', True):
        return (None, None, f"QUOTE CROSS-CHECK MISMATCH {q.get('divergence',0)*100:.1f}¢", q.get('age', 999.0))
    bid = float(q['yes_bid']); ask = float(q['yes_ask'])
    if direction == 'UP':
        contract = ask if action == 'ENTER' else bid
        yes_equiv = ask if action == 'ENTER' else bid
    elif direction == 'DOWN':
        contract = (1.0-bid) if action == 'ENTER' else (1.0-ask)
        yes_equiv = bid if action == 'ENTER' else ask
    else:
        return (None, None, q['source'], q['age'])
    if not 0.0 < contract < 1.0:
        return (None, None, q['source'], q['age'])
    return (float(contract), float(yes_equiv), q['source'], float(q['age']))


def _v264_odds_worker(self):
    last_market = 0.0; last_rest = 0.0
    while True:
        if not getattr(self, 'running', False):
            time.sleep(.30); continue
        now = time.time()
        if now-last_market >= 1.5:
            try: self._refresh_auto_kalshi_market()
            except Exception as exc: self.auto_market_error = str(exc)
            last_market = now
        try: self._start_kalshi_orderbook_ws()
        except Exception: pass
        # REST heartbeat runs even when WS is connected. This is deliberate:
        # it validates stationary top-of-book and makes PAPER usable before API
        # credentials are submitted.
        if now-last_rest >= .85:
            try: _v264_rest_refresh(self)
            except Exception as exc: self.kalshi_orderbook_error = str(exc)
            last_rest = now
        time.sleep(.14)


def _v264_start_odds_worker(self):
    t = getattr(self, 'kalshi_live_odds_thread', None)
    if t is not None and t.is_alive(): return
    self.kalshi_live_odds_thread = threading.Thread(target=_v264_odds_worker, args=(self,), name='BookmapKingV2164-LiveKalshiBBO', daemon=True)
    self.kalshi_live_odds_thread.start()


def _v264_init_paper_trading(self):
    try:
        _V264_BASE_INIT_PAPER(self)
    except Exception:
        pass
    with self.stockpile_db_lock:
        with self._stockpile_connect() as conn:
            cols = {r[1] for r in conn.execute('PRAGMA table_info(paper_trades)').fetchall()}
            migrations = {
                'bot_name':'TEXT','authority_name':'TEXT','quote_source':'TEXT','quote_age':'REAL',
                'entry_yes_bid':'REAL','entry_yes_ask':'REAL','exit_yes_bid':'REAL','exit_yes_ask':'REAL',
                'path_roughness':'REAL','path_state':'TEXT','value_hunt_target':'REAL',
                'decision_snapshot_json':'TEXT','settlement_source':'TEXT','audit_state':'TEXT DEFAULT "OK"',
                'created_version':'TEXT DEFAULT "V21.64"'
            }
            for col, ddl in migrations.items():
                if col not in cols:
                    conn.execute(f'ALTER TABLE paper_trades ADD COLUMN {col} {ddl}')
            conn.execute('''CREATE TABLE IF NOT EXISTS paper_trade_events (
                id INTEGER PRIMARY KEY AUTOINCREMENT, trade_id INTEGER NOT NULL,
                ts REAL NOT NULL, event_type TEXT NOT NULL, payload_json TEXT,
                FOREIGN KEY(trade_id) REFERENCES paper_trades(id))''')
            conn.execute('CREATE INDEX IF NOT EXISTS idx_paper_events_trade ON paper_trade_events(trade_id)')
            conn.execute('''CREATE TABLE IF NOT EXISTS live_auto_orders (
                id INTEGER PRIMARY KEY AUTOINCREMENT, client_order_id TEXT UNIQUE,
                order_id TEXT, paper_trade_id INTEGER, ts REAL NOT NULL,
                ticker TEXT, direction TEXT, intent TEXT, book_side TEXT,
                requested_count REAL, requested_yes_price REAL, status TEXT,
                fill_count REAL, average_fill_price REAL, response_json TEXT, error TEXT)''')
            conn.execute('CREATE INDEX IF NOT EXISTS idx_live_auto_ticker ON live_auto_orders(ticker)')


def _v264_event(self, trade_id, event_type, payload):
    if not trade_id: return
    try:
        with self.stockpile_db_lock:
            with self._stockpile_connect() as conn:
                conn.execute('INSERT INTO paper_trade_events(trade_id,ts,event_type,payload_json) VALUES(?,?,?,?)',
                             (int(trade_id), time.time(), str(event_type), json.dumps(payload or {}, separators=(',',':'), default=str)))
    except Exception:
        pass


def _v264_load_active_paper_trade(self):
    self.paper_active_trade = None
    try:
        with self.stockpile_db_lock:
            with self._stockpile_connect() as conn:
                row = conn.execute('''SELECT id,direction,entry_ts,market_ticker,bucket,target,entry_btc,
                    entry_yes,entry_contract,stake,shares,mfe_cents,mae_cents,entry_source,
                    path_roughness,path_state,value_hunt_target
                    FROM paper_trades WHERE status='OPEN' AND authority_name='BOOKMAP MASTER'
                    ORDER BY id DESC LIMIT 1''').fetchone()
        if row:
            self.paper_active_trade = {'id':row[0],'direction':row[1],'entry_ts':row[2],'market_ticker':row[3],
                'bucket':row[4],'target':row[5],'entry_btc':row[6],'entry_yes':row[7],'entry_contract':row[8],
                'stake':row[9],'shares':row[10],'mfe_cents':float(row[11] or 0),'mae_cents':float(row[12] or 0),
                'entry_source':row[13],'path_roughness':float(row[14] or 0),'path_state':row[15],
                'value_hunt_target':row[16]}
            try: self._paper_update_live_mark(force=True)
            except Exception: pass
        else:
            self.paper_active_var.set('No active BOOKMAP MASTER paper trade')
    except Exception as exc:
        self.paper_status_var.set(f'Bookmap Master paper load error: {exc}')


def _v264_master_read(self, now=None):
    now = float(now or time.time())
    snap = None
    for getter in (
        lambda: getattr(self, 'opening_lock_snapshot', None),
        lambda: self._sticky_survival_lock_snapshot() if hasattr(self, '_sticky_survival_lock_snapshot') else None,
        lambda: self._selected_checkpoint_snapshot() if hasattr(self, '_selected_checkpoint_snapshot') else None,
    ):
        try:
            s = getter()
            if s and str(s.get('lock_side','WAIT')).upper() in ('UP','DOWN'):
                snap = dict(s); break
        except Exception: pass
    if not snap:
        return {'ready':False,'side':'WAIT','reason':'waiting for Bookmap whole-round lock'}
    side = str(snap.get('lock_side')).upper(); opposite = 'DOWN' if side=='UP' else 'UP'
    try: warm = dict(self._bookmap_fast_warmup_read(now=now) or {})
    except Exception: warm = {}
    try: dest = dict(_v263_destination_context(self, warm=warm, now=now) or {})
    except Exception: dest = {}
    wave = dict(warm.get('wave') or {}); whale = dict(warm.get('whale') or {})
    flow2 = float(wave.get('flow_2s',0) or 0); flow6 = float(wave.get('flow_6s',0) or 0)
    flow_signed = .62*flow2 + .38*flow6
    flow_side = 'UP' if flow_signed>.08 else 'DOWN' if flow_signed<-.08 else 'WAIT'
    warm_side = str(warm.get('favored','WAIT')).upper()
    wave_side = str(wave.get('raw_direction', wave.get('direction','WAIT'))).upper()
    whale_side = str(whale.get('direction','WAIT')).upper()
    whale_conf = float(whale.get('likelihood',0) or 0)
    dest_side = str(dest.get('side','WAIT')).upper(); dest_score = float(dest.get('score',0) or 0)
    risk = float(getattr(self,'trend_reversal_risk_value',0) or 0)
    survival = float(getattr(self,'flip_survival_value',96) or 96)
    rough = .18; health = .88; reasons=[]
    for label, s, weight in (('warm',warm_side,.18),('wave',wave_side,.14),('flow',flow_side,.18)):
        if s == opposite: rough += weight; health -= weight*.65; reasons.append(label+' against')
        elif s == side: rough -= weight*.45; health += weight*.20
    if whale_side == opposite and whale_conf >= 70: rough += .14; health -= .12; reasons.append('whale against')
    elif whale_side == side and whale_conf >= 65: rough -= .05; health += .04
    if dest_side == opposite and abs(dest_score) >= .28: rough += .18; health -= .18; reasons.append('destination context against')
    elif dest_side == side: rough -= min(.12, abs(dest_score)*.15); health += min(.08,abs(dest_score)*.10)
    ad = dict(dest.get('accumulation_distribution') or {})
    ad_state = str(ad.get('state',''))
    if side=='UP' and 'ACCUMULATION' in ad_state: rough += .12; reasons.append('accumulation path')
    if side=='DOWN' and 'DISTRIBUTION' in ad_state: rough += .12; reasons.append('distribution path')
    if 28 <= risk <= 58: rough += .10
    elif risk > 58: rough += .20; health -= .20; reasons.append('flip risk elevated')
    if survival < 58: health -= .18; rough += .15
    if survival < 42: health -= .22
    rough = _v264_clip(rough,0,1); health = _v264_clip(health,0,1)
    seconds_left = max(0.0, 900.0-(now%900.0))
    road = 'ROUGH / VALUE HUNT' if rough>=.55 else 'BUMPY' if rough>=.36 else 'CLEANER ROAD'
    invalidated = health < .34 or (risk>=78 and survival<=35 and warm_side==opposite and flow_side==opposite)
    return {'ready':not invalidated,'side':side,'lock':snap,'roughness':rough,'health':health,
            'road':road,'seconds_left':seconds_left,'warm_side':warm_side,'flow_side':flow_side,
            'dest_side':dest_side,'dest_score':dest_score,'risk':risk,'survival':survival,
            'accumulation_distribution':ad_state,'reason':' • '.join(reasons[-5:]) or 'whole-round thesis intact'}


def _v264_value_plan(self, master, ask, now=None):
    now=float(now or time.time()); ask=float(ask); side=str(master.get('side','WAIT'))
    bucket=int(now//900)*900; rough=float(master.get('roughness',0)); health=float(master.get('health',0)); left=float(master.get('seconds_left',0))
    st=dict(getattr(self,'_v264_value_state',{}) or {})
    if int(st.get('bucket',-1) or -1)!=bucket or st.get('side')!=side:
        st={'bucket':bucket,'side':side,'start':now,'anchor':ask,'best':ask,'target':ask,'entered':False}
    st['best']=min(float(st.get('best',ask)),ask)
    age=max(0.0,now-float(st.get('start',now)))
    if ask > _V264_MAX_PAPER_ENTRY:
        st['target']=min(float(st.get('target',ask)),_V264_MAX_PAPER_ENTRY)
        self._v264_value_state=st
        return {'enter':False,'target':st['target'],'state':'NO CHASE >70¢','age':age}
    # Already cheap: don't get cute and miss a strong call.
    if ask <= .45 and health >= .55:
        st['target']=ask; self._v264_value_state=st
        return {'enter':True,'target':ask,'state':'CHEAP NOW','age':age}
    if rough < .38:
        st['target']=min(_V264_MAX_PAPER_ENTRY,ask); self._v264_value_state=st
        return {'enter':health>=.52,'target':st['target'],'state':'CLEAN ROAD / TAKE EXECUTABLE ASK','age':age}
    improvement=.025 + .065*rough
    target=max(.08,min(.60,float(st.get('anchor',ask))-improvement))
    st['target']=target
    max_wait=28.0+62.0*rough
    # When the model itself expects turbulence, let the contract come to us.
    hit = ask <= target + .002
    deadline = age >= max_wait or left <= 300
    if hit and health>=.50:
        state='VALUE DIP HIT'
        enter=True
    elif deadline and ask <= min(.65,float(st.get('anchor',ask))) and health>=.64:
        state='VALUE WINDOW EXPIRED / THESIS STILL STRONG'
        enter=True
    else:
        state=f'ROUGH ROAD VALUE HUNT • waiting <= {target*100:.1f}¢'
        enter=False
    self._v264_value_state=st
    return {'enter':enter,'target':target,'state':state,'age':age,'best':st['best'],'max_wait':max_wait}


def _v264_paper_open(self, direction, entry_source='MANUAL', auto_score=None, auto_reason=None):
    direction=str(direction).upper()
    if direction not in ('UP','DOWN') or self.paper_active_trade is not None: return False
    contract, yes_equiv, qsrc, qage = _v264_paper_price(self,direction,'ENTER',_V264_ENTRY_QUOTE_MAX_AGE)
    q = _v264_quote_snapshot(self,_V264_ENTRY_QUOTE_MAX_AGE)
    if contract is None or yes_equiv is None or not q:
        self.paper_status_var.set('BOOKMAP MASTER: waiting for healthy executable Kalshi ask')
        return False
    requested_stake=self._paper_parse_stake()
    if requested_stake is None: self.paper_status_var.set('Enter a valid paper stake above $0.'); return False
    fractional=bool((self.kalshi_market or {}).get('fractional_trading_enabled',False))
    raw_shares=float(requested_stake)/float(contract)
    shares=(math.floor(raw_shares*100.0+1e-9)/100.0) if fractional else float(math.floor(raw_shares+1e-9))
    min_shares=.01 if fractional else 1.0
    if shares < min_shares:
        self.paper_status_var.set('BOOKMAP MASTER: paper stake too small for the current executable contract price')
        return False
    stake=float(shares)*float(contract)  # actual simulated capital deployed
    now=time.time(); bucket=int(now//900)*900
    live_btc,_=self.effective_live_price(); target,_=self.effective_target(); ticker=_v75_current_ticker(self)
    master=_v264_master_read(self,now=now); plan=dict(getattr(self,'_v264_last_plan',{}) or {})
    sig=dict(getattr(self,'last_signal',{}) or {}); pat=dict(sig.get('pattern') or {})
    decision={'master':master,'plan':plan,'destination':dict(getattr(self,'_v263_destination_last',{}) or {}),'quote':q,
              'requested_stake':float(requested_stake),'deployed_stake':float(stake),'fractional_trading_enabled':fractional}
    values=('OPEN',direction,now,ticker,bucket,float(target) if target is not None else None,
            float(live_btc) if live_btc is not None else None,float(yes_equiv),float(contract),float(stake),float(shares),
            pat.get('name'),pat.get('stage'),float(pat.get('score',0) or 0),direction,
            float(sig.get('fast_net',0) or 0),float(sig.get('pro_net',0) or 0),
            'BOOKMAP MASTER',0.0,direction,0,15,'BOOKMAP MASTER',str(entry_source).upper(),
            float(auto_score) if auto_score is not None else None,str(auto_reason or ''),
            max(50.0,float(master.get('health',.5))*100),100.0*float(master.get('health',.5)))
    try:
        with self.stockpile_db_lock:
            with self._stockpile_connect() as conn:
                cur=conn.execute('''INSERT INTO paper_trades(status,direction,entry_ts,market_ticker,bucket,target,entry_btc,
                    entry_yes,entry_contract,stake,shares,pattern,pattern_stage,pattern_score,model_lean,fast_net,pro_net,
                    sniper_status,sniper_conf,lock_side,lock_minute,lock_remaining,trend_status,entry_source,auto_score,auto_reason,
                    entry_confidence,market_quality,bot_name,authority_name,quote_source,quote_age,entry_yes_bid,entry_yes_ask,
                    path_roughness,path_state,value_hunt_target,decision_snapshot_json,settlement_source,audit_state,created_version)
                    VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)''',
                    values + ('BOOKMAP MASTER','BOOKMAP MASTER',qsrc,float(qage),float(q['yes_bid']),float(q['yes_ask']),
                              float(master.get('roughness',0)),str(master.get('road','')),
                              float(plan.get('target')) if plan.get('target') is not None else None,
                              json.dumps(decision,separators=(',',':'),default=str),'','OK','V21.64'))
                trade_id=int(cur.lastrowid)
                conn.execute('INSERT INTO paper_trade_events(trade_id,ts,event_type,payload_json) VALUES(?,?,?,?)',
                             (trade_id,now,'ENTRY',json.dumps({'direction':direction,'contract':contract,'yes_equiv':yes_equiv,'quote':q,'master':master,'plan':plan},separators=(',',':'),default=str)))
        self.paper_active_trade={'id':trade_id,'direction':direction,'entry_ts':now,'market_ticker':ticker,'bucket':bucket,
            'target':float(target) if target is not None else None,'entry_btc':float(live_btc) if live_btc is not None else None,
            'entry_yes':float(yes_equiv),'entry_contract':float(contract),'stake':float(stake),'shares':float(shares),
            'entry_source':str(entry_source).upper(),'mfe_cents':0.0,'mae_cents':0.0,
            'path_roughness':float(master.get('roughness',0)),'path_state':str(master.get('road','')),
            'value_hunt_target':plan.get('target')}
        self.auto_paper_last_bucket=bucket
        self.paper_status_var.set(f'BOOKMAP MASTER PAPER ENTERED {direction} @ {contract*100:.1f}¢ ASK • {master.get("road")} • {qsrc} age {qage:.2f}s')
        self._paper_update_live_mark(force=True); self._refresh_paper_stats()
        if self.live_auto_enabled_var.get():
            self._v86_live_submit_entry(direction,paper_contract_px=contract,reason='BOOKMAP MASTER PAPER MIRROR')
        return True
    except Exception as exc:
        self.paper_status_var.set(f'BOOKMAP MASTER paper entry error: {exc}')
        return False


def _v264_paper_finalize(self, exit_yes=None, market_result=None, reason='CLOSED'):
    trade=dict(self.paper_active_trade or {})
    if not trade: return False
    direction=str(trade.get('direction')).upper(); market_result_norm=str(market_result).lower() if market_result is not None else None
    q=_v264_quote_snapshot(self,_V264_EXIT_QUOTE_MAX_AGE)
    if market_result_norm in ('yes','no'):
        won=(direction=='UP' and market_result_norm=='yes') or (direction=='DOWN' and market_result_norm=='no')
        exit_contract=1.0 if won else 0.0; exit_yes_val=1.0 if market_result_norm=='yes' else 0.0
        settlement_source='KALSHI OFFICIAL RESULT'
    else:
        if exit_yes is None:
            contract, exit_yes, qsrc, qage=_v264_paper_price(self,direction,'EXIT',_V264_EXIT_QUOTE_MAX_AGE)
            if contract is None or exit_yes is None: return False
        exit_yes_val=float(exit_yes); exit_contract=exit_yes_val if direction=='UP' else 1.0-exit_yes_val
        settlement_source='LIVE EXECUTABLE BID'
    pnl=float(trade['shares'])*(float(exit_contract)-float(trade['entry_contract']))
    result='WIN' if pnl>.005 else 'LOSS' if pnl<-.005 else 'FLAT'
    live_btc,_=self.effective_live_price(); now=time.time()
    try:
        with self.stockpile_db_lock:
            with self._stockpile_connect() as conn:
                conn.execute('''UPDATE paper_trades SET status='CLOSED',exit_ts=?,exit_btc=?,exit_yes=?,exit_contract=?,pnl=?,result=?,
                    market_result=?,exit_reason=?,exit_yes_bid=?,exit_yes_ask=?,settlement_source=?,audit_state='OK'
                    WHERE id=? AND status='OPEN' ''',
                    (now,float(live_btc) if live_btc is not None else None,float(exit_yes_val),float(exit_contract),float(pnl),result,
                     market_result_norm,str(reason),float(q.get('yes_bid')) if q else None,float(q.get('yes_ask')) if q else None,
                     settlement_source,int(trade['id'])))
                conn.execute('INSERT INTO paper_trade_events(trade_id,ts,event_type,payload_json) VALUES(?,?,?,?)',
                    (int(trade['id']),now,'SETTLEMENT' if market_result_norm in ('yes','no') else 'EXIT',
                     json.dumps({'exit_yes':exit_yes_val,'exit_contract':exit_contract,'pnl':pnl,'result':result,'reason':reason,'market_result':market_result_norm,'quote':q},separators=(',',':'),default=str)))
        self.paper_active_trade=None; self.paper_active_var.set('No active BOOKMAP MASTER paper trade')
        self.paper_settlement_check_inflight=False
        sign='+' if pnl>=0 else '-'; self.paper_status_var.set(f'BOOKMAP MASTER {direction} {result} • {sign}${abs(pnl):,.2f} • {reason}')
        self._refresh_paper_stats()
        if market_result_norm in ('yes','no'):
            # Kalshi settles a live position itself at official resolution. Do
            # not submit a redundant close into a resolved market.
            try:
                with self.live_trade_lock:
                    live=dict(self.live_active_trade or {})
                    if str(live.get('ticker','')).upper()==str(trade.get('market_ticker','')).upper():
                        self.live_active_trade=None
                        self.live_order_inflight=False
                if live:
                    self._v86_live_set(f'LIVE POSITION: official {market_result_norm.upper()} settlement recorded','LIVE POSITION: none')
            except Exception:
                pass
        elif self.live_auto_enabled_var.get():
            self._v86_live_submit_exit(reason)
        return True
    except Exception as exc:
        self.paper_status_var.set(f'BOOKMAP MASTER close error: {exc}'); return False


def _v264_paper_mark(self, force=False):
    now=time.time()
    if not force and now-float(getattr(self,'paper_last_live_mark',0) or 0)<.35: return
    self.paper_last_live_mark=now; trade=self.paper_active_trade
    if not trade:
        self.paper_active_var.set('No active BOOKMAP MASTER paper trade'); return
    contract, yes_equiv, src, age=_v264_paper_price(self,trade['direction'],'EXIT',_V264_EXIT_QUOTE_MAX_AGE)
    if contract is None:
        self.paper_active_var.set(f"OPEN {trade['direction']} • entry {trade['entry_contract']*100:.1f}¢ • waiting live Kalshi bid"); return
    move=(float(contract)-float(trade['entry_contract']))*100
    trade['mfe_cents']=max(float(trade.get('mfe_cents',0)),move); trade['mae_cents']=min(float(trade.get('mae_cents',0)),move)
    pnl=float(trade['shares'])*(float(contract)-float(trade['entry_contract']))
    try:
        with self.stockpile_db_lock:
            with self._stockpile_connect() as conn:
                conn.execute('UPDATE paper_trades SET mfe_cents=?,mae_cents=? WHERE id=? AND status="OPEN"',
                             (trade['mfe_cents'],trade['mae_cents'],int(trade['id'])))
    except Exception: pass
    sign='+' if pnl>=0 else '-'
    self.paper_active_var.set(f"OPEN BOOKMAP MASTER {trade['direction']} • {trade['entry_contract']*100:.1f}¢ → BID {contract*100:.1f}¢ • {sign}${abs(pnl):,.2f} • MFE {trade['mfe_cents']:+.1f}¢ / MAE {trade['mae_cents']:+.1f}¢ • {src}")


def _v264_refresh_paper_stats(self):
    try:
        with self.stockpile_db_lock:
            with self._stockpile_connect() as conn:
                bm=conn.execute('''SELECT COUNT(*),SUM(CASE WHEN result='WIN' THEN 1 ELSE 0 END),SUM(CASE WHEN result='LOSS' THEN 1 ELSE 0 END),COALESCE(SUM(pnl),0) FROM paper_trades WHERE status='CLOSED' AND authority_name='BOOKMAP MASTER' ''').fetchone()
                alln=conn.execute("SELECT COUNT(*) FROM paper_trades WHERE status='CLOSED'").fetchone()[0]
                recent=conn.execute('''SELECT id,direction,result,pnl,entry_contract,exit_contract,market_ticker,exit_reason,path_state,quote_source FROM paper_trades WHERE authority_name='BOOKMAP MASTER' ORDER BY id DESC LIMIT 12''').fetchall()
        total=int(bm[0] or 0); wins=int(bm[1] or 0); losses=int(bm[2] or 0); pnl=float(bm[3] or 0); wr=100*wins/total if total else 0
        audit=dict(getattr(self,'_v264_journal_health',{}) or {})
        issue_count=len(audit.get('issues') or [])
        audit_text='AUDIT OK' if issue_count==0 else f'AUDIT {issue_count} ISSUE(S)'
        self.paper_stats_var.set(f'BOOKMAP MASTER • {total} closed • W {wins} / L {losses} • WR {wr:.1f}% • P/L {pnl:+.2f} • all journal rows {int(alln or 0)} • {audit_text}')
        lines=[]
        for r in recent:
            lines.append(f"#{r[0]} {r[1]} {r[2] or 'OPEN'} • {float(r[4] or 0)*100:.1f}¢→{float(r[5] or 0)*100:.1f}¢ • ${float(r[3] or 0):+.2f} • {r[6] or '--'} • {r[8] or ''} • {r[7] or ''}")
        self.paper_recent_var.set('\n'.join(lines) if lines else 'BOOKMAP MASTER trades: none yet')
    except Exception as exc:
        self.paper_stats_var.set(f'Paper journal stats error: {exc}')


def _v264_journal_audit(self, reconcile=True):
    issues=[]; repaired=0
    try:
        with self.stockpile_db_lock:
            with self._stockpile_connect() as conn:
                rows=conn.execute("SELECT id,status,direction,entry_ts,exit_ts,market_ticker,entry_contract,exit_contract,result,authority_name FROM paper_trades ORDER BY id").fetchall()
                for row in rows:
                    tid,status,direction,ets,xts,ticker,ep,xp,result,auth=row
                    bad=False
                    if not ets or not direction or ep is None:
                        issues.append(f'#{tid} missing entry core'); bad=True
                    if status=='CLOSED' and (xts is None or xp is None or result not in ('WIN','LOSS','FLAT')):
                        issues.append(f'#{tid} incomplete close'); bad=True
                    if bad:
                        conn.execute('UPDATE paper_trades SET audit_state=? WHERE id=?',('NEEDS_REVIEW',tid))
                    elif auth=='BOOKMAP MASTER':
                        conn.execute('UPDATE paper_trades SET audit_state=COALESCE(NULLIF(audit_state,""),"OK") WHERE id=?',(tid,))
                    if auth=='BOOKMAP MASTER':
                        cnt=conn.execute("SELECT COUNT(*) FROM paper_trade_events WHERE trade_id=? AND event_type='ENTRY'",(tid,)).fetchone()[0]
                        if not cnt:
                            conn.execute('INSERT INTO paper_trade_events(trade_id,ts,event_type,payload_json) VALUES(?,?,?,?)',(tid,float(ets or time.time()),'ENTRY',json.dumps({'audit_backfill':True}))); repaired+=1
                        if status=='CLOSED':
                            cnt=conn.execute("SELECT COUNT(*) FROM paper_trade_events WHERE trade_id=? AND event_type IN ('EXIT','SETTLEMENT')",(tid,)).fetchone()[0]
                            if not cnt:
                                conn.execute('INSERT INTO paper_trade_events(trade_id,ts,event_type,payload_json) VALUES(?,?,?,?)',(tid,float(xts or time.time()),'EXIT',json.dumps({'audit_backfill':True,'result':result}))); repaired+=1
        self._v264_journal_health={'issues':issues,'repaired':repaired,'ts':time.time()}
        return self._v264_journal_health
    except Exception as exc:
        return {'issues':[str(exc)],'repaired':0,'ts':time.time()}


def _v264_reconcile_settlement_async(self):
    trade=dict(self.paper_active_trade or {})
    if not trade or getattr(self,'paper_settlement_check_inflight',False): return
    now=time.time(); ticker=str(trade.get('market_ticker') or '')
    if not ticker or now-float(getattr(self,'paper_last_settlement_check',0) or 0)<3.0: return
    self.paper_last_settlement_check=now; self.paper_settlement_check_inflight=True; tid=int(trade['id'])
    def worker():
        result=''; status=''; err=''
        try:
            m=self._get_kalshi_market(ticker); result=str(m.get('result') or '').lower(); status=str(m.get('status') or '').lower()
        except Exception as exc: err=str(exc)
        def apply():
            self.paper_settlement_check_inflight=False
            if not self.paper_active_trade or int(self.paper_active_trade.get('id',-1))!=tid: return
            if result in ('yes','no'):
                _v264_paper_finalize(self,market_result=result,reason='KALSHI OFFICIAL SETTLEMENT')
            elif err:
                self.paper_status_var.set(f'BOOKMAP MASTER settlement check waiting • {err}')
            elif status in ('closed','determined','finalized','settled'):
                self.paper_status_var.set(f'BOOKMAP MASTER market {status} • waiting official result')
        try: self.root.after(0,apply)
        except Exception: self.paper_settlement_check_inflight=False
    threading.Thread(target=worker,name='BookmapKingV2164-Settlement',daemon=True).start()


def _v264_should_exit(self, master):
    trade=self.paper_active_trade
    if not trade: return (False,'')
    side=str(trade.get('direction')).upper(); opposite='DOWN' if side=='UP' else 'UP'
    try:
        sig=dict(getattr(self,'last_signal',{}) or {}); trend=dict(sig.get('trend_reversal') or {})
        if str(trend.get('status','')).upper()=='BREAKOUT CONFIRMED' and str(trend.get('flip_to','')).upper()==opposite:
            return True,f'BOOKMAP MASTER confirmed breakout {opposite}'
    except Exception: pass
    if master and str(master.get('side','')).upper()!=side and float(master.get('health',1))<.38:
        return True,'BOOKMAP MASTER thesis invalidated'
    if master and float(master.get('risk',0))>=82 and float(master.get('survival',100))<=30:
        return True,'BOOKMAP MASTER survival failure'
    return (False,'')


def _v264_master_step(self, warm=None, sig=None, candles=None, now=None, mode='LIVE'):
    now=float(now or time.time())
    if now-float(getattr(self,'_v264_last_step',0) or 0)<.09: return False
    self._v264_last_step=now
    try: _v264_paper_mark(self)
    except Exception: pass
    if self.paper_active_trade:
        trade=dict(self.paper_active_trade); bucket=int(trade.get('bucket',0) or 0); current=int(now//900)*900
        if bucket < current:
            _v264_reconcile_settlement_async(self); return False
        master=_v264_master_read(self,now)
        do_exit,reason=_v264_should_exit(self,master)
        if do_exit and self.paper_auto_exit_var.get():
            contract,yes_equiv,_,_=_v264_paper_price(self,trade['direction'],'EXIT',_V264_EXIT_QUOTE_MAX_AGE)
            if yes_equiv is not None: return bool(_v264_paper_finalize(self,exit_yes=yes_equiv,reason=reason))
        return False
    if not self.auto_paper_enabled_var.get():
        self._set_var_if_changed(self.auto_paper_score_var,'BOOKMAP MASTER AUTO PAPER: OFF'); return False
    bucket=int(now//900)*900
    if self.auto_paper_last_bucket==bucket:
        self._set_var_if_changed(self.auto_paper_reason_var,'BOOKMAP MASTER already traded this 15m round'); return False
    master=_v264_master_read(self,now)
    if not master.get('ready'):
        self._set_var_if_changed(self.auto_paper_reason_var,'BOOKMAP MASTER WAIT • '+master.get('reason','building whole-round thesis')); return False
    side=master['side']; ask,_,qsrc,qage=_v264_paper_price(self,side,'ENTER',_V264_ENTRY_QUOTE_MAX_AGE)
    if ask is None:
        self._set_var_if_changed(self.auto_paper_reason_var,'BOOKMAP MASTER '+side+' • waiting healthy live Kalshi executable ask'); return False
    plan=_v264_value_plan(self,master,ask,now); self._v264_last_plan=dict(plan)
    self._set_var_if_changed(self.auto_paper_score_var,f"BOOKMAP MASTER {side} • health {master['health']*100:.0f}/100 • rough {master['roughness']*100:.0f}/100 • ASK {ask*100:.1f}¢")
    self._set_var_if_changed(self.auto_paper_reason_var,f"{master['road']} • {plan['state']} • live {qsrc} age {qage:.2f}s • {master['reason']}")
    if not plan.get('enter'): return False
    return bool(_v264_paper_open(self,side,entry_source='BOOKMAP MASTER AUTO',auto_score=master['health']*100,auto_reason=f"{master['road']} • {plan['state']} • {master['reason']}"))


def _v264_live_stake(self):
    try: v=float(str(self.live_trade_stake_var.get()).replace('$','').strip())
    except Exception: v=10.0
    return max(.01,min(_V264_LIVE_STAKE_MAX,v))


def _v264_live_slip(self):
    try: v=float(str(self.live_slippage_cents_var.get()).replace('¢','').strip())/100.0
    except Exception: v=_V264_DEFAULT_SLIP
    return max(0.0,min(.05,v))


def _v264_post_order(self, *, ticker, side, count, price, reduce_only=False, client_order_id=None, paper_trade_id=None, direction='', intent='ENTRY'):
    api_path='/trade-api/v2/portfolio/events/orders'; cid=str(client_order_id or uuid.uuid4())
    payload={'ticker':str(ticker).strip().upper(),'client_order_id':cid,'side':str(side).lower(),
             'count':f'{float(count):.2f}','price':f'{float(price):.4f}','time_in_force':'immediate_or_cancel',
             'self_trade_prevention_type':'taker_at_cross','post_only':False,'cancel_order_on_pause':True,
             'reduce_only':bool(reduce_only),'subaccount':0,'exchange_index':0}
    log_id=None
    try:
        with self.stockpile_db_lock:
            with self._stockpile_connect() as conn:
                cur=conn.execute('''INSERT OR IGNORE INTO live_auto_orders(client_order_id,paper_trade_id,ts,ticker,direction,intent,book_side,requested_count,requested_yes_price,status)
                    VALUES(?,?,?,?,?,?,?,?,?,?)''',(cid,paper_trade_id,time.time(),payload['ticker'],direction,intent,payload['side'],float(count),float(price),'PENDING'))
                log_id=cur.lastrowid
    except Exception: pass
    body=json.dumps(payload,separators=(',',':')).encode('utf-8')
    req=urllib.request.Request('https://external-api.kalshi.com'+api_path,data=body,headers=self._v86_sign_headers('POST',api_path,content_type=True),method='POST')
    try:
        with urllib.request.urlopen(req,timeout=6) as response:
            raw=response.read().decode('utf-8'); data=json.loads(raw) if raw else {}
            data['_http_status']=int(getattr(response,'status',201) or 201); data['_request']=payload
        try:
            with self.stockpile_db_lock:
                with self._stockpile_connect() as conn:
                    conn.execute('''UPDATE live_auto_orders SET order_id=?,status=?,fill_count=?,average_fill_price=?,response_json=? WHERE client_order_id=?''',
                        (str(data.get('order_id') or ''),'FILLED' if float(data.get('fill_count',0) or 0)>0 else 'NO_FILL',
                         float(data.get('fill_count',0) or 0),float(data.get('average_fill_price')) if data.get('average_fill_price') not in (None,'') else None,
                         json.dumps(data,separators=(',',':'),default=str),cid))
        except Exception: pass
        return data
    except Exception as exc:
        try:
            with self.stockpile_db_lock:
                with self._stockpile_connect() as conn:
                    conn.execute('UPDATE live_auto_orders SET status=?,error=? WHERE client_order_id=?',('ERROR',str(exc)[:1000],cid))
        except Exception: pass
        raise


def _v264_live_toggle_requested(self):
    requested=bool(self.live_auto_enabled_var.get())
    if not requested:
        self.live_auto_status_var.set('LIVE AUTO: OFF • existing live position is not auto-closed'); return
    if not getattr(self,'kalshi_credentials_verified',False):
        self.live_auto_enabled_var.set(False); self.live_auto_status_var.set('LIVE AUTO: BLOCKED • SUBMIT + VERIFY Kalshi credentials first')
        try: messagebox.showwarning('Live Auto Blocked','Use the existing SUBMIT + VERIFY button for your Kalshi API Key ID + private key first.')
        except Exception: pass
        return
    stake=_v264_live_stake(self)
    try:
        ok=messagebox.askyesno('Arm BOOKMAP MASTER LIVE AUTO?',
            f'BOOKMAP MASTER will mirror ONLY its real-time paper ENTRY/EXIT events with Kalshi IOC orders.\n\nMax live risk: ${stake:.2f} per 15-minute market\nHard entry cap: 70¢\nValue-hunt timing is controlled by the paper engine.\n\nArm live trading now?')
    except Exception: ok=False
    if not ok:
        self.live_auto_enabled_var.set(False); self.live_auto_status_var.set('LIVE AUTO: OFF • arming cancelled'); return
    self.live_trade_stake_var.set(f'{stake:.2f}')
    self.live_auto_status_var.set(f'LIVE AUTO: ARMED • BOOKMAP MASTER PAPER MIRROR • max ${stake:.2f}/market')


def _v264_live_submit_entry(self, direction, paper_contract_px=None, reason='AUTO'):
    direction=str(direction).upper()
    if direction not in ('UP','DOWN') or not self.live_auto_enabled_var.get(): return False
    if not getattr(self,'kalshi_credentials_verified',False):
        self.live_auto_enabled_var.set(False); self._v86_live_set('LIVE AUTO DISARMED • credentials not verified'); return False
    ticker=_v75_current_ticker(self); bucket=int(time.time()//900)*900
    if not ticker: self._v86_live_set('LIVE AUTO BLOCKED • no current Kalshi ticker'); return False
    with self.live_trade_lock:
        if self.live_order_inflight or self.live_active_trade is not None or self.live_entry_bucket==bucket: return False
        self.live_order_inflight=True; self.live_entry_bucket=bucket
    contract,yes_equiv,qsrc,qage=_v264_paper_price(self,direction,'ENTER',_V264_ENTRY_QUOTE_MAX_AGE)
    if contract is None or yes_equiv is None:
        with self.live_trade_lock: self.live_order_inflight=False; self.live_entry_bucket=None
        self._v86_live_set('LIVE AUTO waiting • executable quote unavailable'); return False
    stake=_v264_live_stake(self); slip=_v264_live_slip(self)
    current_contract=float(contract)
    paper_ref=float(paper_contract_px) if paper_contract_px not in (None,'') else current_contract
    # A millisecond quote jump must never turn the live mirror into a chase.
    # Cap worst live cost at both the hard 70c rule and paper fill + allowed slip.
    max_contract=min(_V264_MAX_PAPER_ENTRY, paper_ref+slip)
    if current_contract > max_contract + 1e-9:
        with self.live_trade_lock: self.live_order_inflight=False; self.live_entry_bucket=None
        self._v86_live_set(f'LIVE AUTO SKIP • quote moved to {current_contract*100:.1f}¢ above max {max_contract*100:.1f}¢','LIVE POSITION: none')
        return False
    if direction=='UP':
        book_side='bid'; limit_yes=min(.99,max_contract,float(yes_equiv)+slip); worst=limit_yes
    else:
        book_side='ask'; limit_yes=max(.01,1.0-max_contract,float(yes_equiv)-slip); worst=1.0-limit_yes
    fractional=bool((self.kalshi_market or {}).get('fractional_trading_enabled',False))
    raw=stake/max(worst,.01); count=math.floor(raw*100)/100.0 if fractional else float(math.floor(raw+1e-9))
    if count<(.01 if fractional else 1.0):
        with self.live_trade_lock: self.live_order_inflight=False; self.live_entry_bucket=None
        self._v86_live_set('LIVE AUTO BLOCKED • stake too small for current contract'); return False
    cid=str(uuid.uuid4()); paper_id=int((self.paper_active_trade or {}).get('id',0) or 0)
    self._v86_live_set(f'LIVE AUTO SENDING {direction} • {count:g} • IOC • YES limit {limit_yes*100:.1f}¢',f'LIVE POSITION: ENTRY PENDING {direction} • {ticker}')
    def worker():
        try:
            res=_v264_post_order(self,ticker=ticker,side=book_side,count=count,price=limit_yes,reduce_only=False,client_order_id=cid,paper_trade_id=paper_id,direction=direction,intent='ENTRY')
            filled=float(res.get('fill_count',0) or 0); avg=float(res.get('average_fill_price')) if res.get('average_fill_price') not in (None,'') else limit_yes
            if filled<=0:
                with self.live_trade_lock: self.live_order_inflight=False; self.live_entry_bucket=None
                self._v86_live_set('LIVE AUTO IOC NOT FILLED • paper remains simulated','LIVE POSITION: none'); return
            entry_contract=avg if direction=='UP' else 1.0-avg
            trade={'direction':direction,'ticker':ticker,'bucket':bucket,'count':filled,'entry_yes':avg,'entry_contract':entry_contract,
                   'order_id':str(res.get('order_id') or ''),'client_order_id':cid,'entry_ts':time.time(),'reason':reason,'paper_trade_id':paper_id}
            queued=None
            with self.live_trade_lock:
                self.live_active_trade=trade; self.live_order_inflight=False; queued=self.live_exit_queued_reason; self.live_exit_queued_reason=None
            self._v86_live_set(f'LIVE AUTO FILLED {direction} • {filled:g} @ {entry_contract*100:.1f}¢',f'LIVE POSITION: {direction} {filled:g} • {ticker}')
            if queued: _v264_live_submit_exit(self,queued)
        except Exception as exc:
            with self.live_trade_lock: self.live_order_inflight=False; self.live_entry_bucket=None
            try: self.root.after(0,lambda:self.live_auto_enabled_var.set(False))
            except Exception: pass
            self._v86_live_set(f'LIVE AUTO DISARMED • order error: {exc}')
    threading.Thread(target=worker,name='BookmapKingV2164-LiveEntry',daemon=True).start(); return True


def _v264_live_submit_exit(self, reason='AUTO EXIT'):
    with self.live_trade_lock:
        trade=dict(self.live_active_trade or {}); inflight=bool(self.live_order_inflight)
        if not trade:
            if inflight: self.live_exit_queued_reason=str(reason)
            return False
        if inflight: self.live_exit_queued_reason=str(reason); return False
        self.live_order_inflight=True
    direction=str(trade.get('direction','')).upper(); count=float(trade.get('count',0) or 0); ticker=str(trade.get('ticker','')).upper()
    contract,yes_equiv,_,_=_v264_paper_price(self,direction,'EXIT',_V264_EXIT_QUOTE_MAX_AGE)
    if yes_equiv is None:
        with self.live_trade_lock: self.live_order_inflight=False
        self._v86_live_set('LIVE EXIT waiting • executable quote unavailable'); return False
    slip=_v264_live_slip(self)
    if direction=='UP': side='ask'; limit_yes=max(.01,float(yes_equiv)-slip)
    else: side='bid'; limit_yes=min(.99,float(yes_equiv)+slip)
    cid=str(uuid.uuid4()); paper_id=int(trade.get('paper_trade_id',0) or 0)
    def worker():
        try:
            res=_v264_post_order(self,ticker=ticker,side=side,count=count,price=limit_yes,reduce_only=True,client_order_id=cid,paper_trade_id=paper_id,direction=direction,intent='EXIT')
            filled=float(res.get('fill_count',0) or 0); remaining=max(0.0,count-filled)
            with self.live_trade_lock:
                self.live_active_trade=None if remaining<=1e-9 else dict(trade,count=remaining); self.live_order_inflight=False
            self._v86_live_set(f'LIVE EXIT {"FILLED" if remaining<=1e-9 else "PARTIAL"} • {filled:g}/{count:g} • {reason}',
                               'LIVE POSITION: none' if remaining<=1e-9 else f'LIVE POSITION: {direction} {remaining:g} remain')
        except Exception as exc:
            with self.live_trade_lock: self.live_order_inflight=False
            self._v86_live_set(f'LIVE EXIT ERROR • position may still be open • {exc}')
    threading.Thread(target=worker,name='BookmapKingV2164-LiveExit',daemon=True).start(); return True


def _v264_live_kill_and_exit(self):
    # Safety control only: disarm future entries, then flatten the local mirror
    # using the same V2 transport. This does not add any decision logic.
    try: self.live_auto_enabled_var.set(False)
    except Exception: pass
    self._v86_live_set('LIVE AUTO: DISARMED • KILL/EXIT requested')
    return _v264_live_submit_exit(self,'USER KILL / EXIT')


def _v264_build_ui(self):
    _V264_BASE_BUILD_UI(self)
    try:
        if hasattr(self,'paper_bet_brain_var'): self.paper_bet_brain_var.set('BOOKMAP KING')
        if hasattr(self,'live_bet_brain_var'): self.live_bet_brain_var.set('BOOKMAP KING')
        self.paper_status_var.set('BOOKMAP MASTER PAPER • live executable Kalshi ask/bid • value-entry pathing')
        self.live_auto_status_var.set('LIVE AUTO: OFF • BOOKMAP MASTER paper mirror • SUBMIT + VERIFY first')
        stack=[self.root]
        while stack:
            w=stack.pop()
            try: stack.extend(list(w.winfo_children()))
            except Exception: pass
            try: txt=str(w.cget('text') or '')
            except Exception: txt=''
            if 'PREVIEW ONLY' in txt:
                try: w.configure(text='BOOKMAP MASTER MIRROR • IOC • OFF until armed')
                except Exception: pass
            if txt in ('PAPER BRAIN','LIVE BRAIN'):
                try: w.configure(text='BOOKMAP MASTER')
                except Exception: pass
    except Exception: pass


def _v264_init(self,*args,**kwargs):
    self._v264_ticker_quote={}; self._v264_book_quote={}; self._v264_rest_quote={}; self._v264_rest_book_quote={}
    self._v264_ws_last_message_ts=0.0; self._v264_value_state={}; self._v264_last_plan={}; self._v264_last_step=0.0
    self._v264_journal_health={}
    _V264_BASE_INIT(self,*args,**kwargs)
    if not hasattr(self,'live_slippage_cents_var'): self.live_slippage_cents_var=tk.StringVar(value='2.0')
    try: _v264_journal_audit(self)
    except Exception: pass
    try: self.root.after(350,lambda:_v264_heartbeat(self))
    except Exception: pass


def _v264_heartbeat(self):
    try:
        _v264_master_step(self,now=time.time())
        if int(time.time())%15==0 and time.time()-float(getattr(self,'_v264_last_audit',0) or 0)>10:
            self._v264_last_audit=time.time(); _v264_journal_audit(self)
    finally:
        try: self.root.after(120,lambda:_v264_heartbeat(self))
        except Exception: pass


def _v264_legacy_paper_heartbeat_disabled(self):
    # Final authority is BOOKMAP MASTER only. Do not reschedule legacy NH/BK dual paper.
    return None


