# ============================================================================
# BOOKMAP KING V21.66 — PERMANENT EXECUTION CONTROL + PAPER AUTO HARD FIX
# ============================================================================
# This patch does NOT modify the V21.63 destination/pathing brain.
# It makes execution impossible to hide behind legacy UI cleanup:
#   * permanent top-of-page PAPER AUTO + LIVE AUTO controls
#   * PAPER AUTO defaults ON (simulation only)
#   * exact Bookmap Master blocker/plan/BBO diagnostics
#   * same paper_trades journal remains the single paper source of truth
#   * direct fresh Kalshi market BBO is a fallback if the dedicated quote mesh
#     has not populated yet
#   * LIVE AUTO uses ONLY the V9.3-style credential/order transport and mirrors
#     a successfully logged Bookmap Master paper entry/exit

_V266_RELEASE = 'V21.66'
_V266_BASE_INIT = ChartKingPro.__init__
_V266_BASE_BUILD_UI = ChartKingPro._build_ui
_V266_BASE_QUOTE_SNAPSHOT = _v264_quote_snapshot


def _v266_direct_market_quote(self, max_age=3.0):
    """Fresh public Kalshi market BBO fallback; never synthesize a midpoint."""
    try:
        ticker = _v75_current_ticker(self)
        if not ticker:
            return {}
        m = dict(getattr(self, 'kalshi_market', {}) or {})
        if str(m.get('ticker') or ticker).strip().upper() != str(ticker).strip().upper():
            return {}
        ts = float(getattr(self, 'auto_market_last_refresh', 0.0) or 0.0)
        age = max(0.0, time.time() - ts) if ts > 0 else 999.0
        if age > float(max_age):
            return {}
        bid = _v75_prob(m.get('yes_bid_dollars') if m.get('yes_bid_dollars') is not None else m.get('yes_bid'))
        ask = _v75_prob(m.get('yes_ask_dollars') if m.get('yes_ask_dollars') is not None else m.get('yes_ask'))
        if bid is None or ask is None:
            return {}
        bid = float(bid); ask = float(ask)
        if not (0.0 < bid < 1.0 and 0.0 < ask < 1.0 and bid <= ask):
            return {}
        return {
            'ticker': str(ticker).upper(), 'yes_bid': bid, 'yes_ask': ask,
            'no_bid': 1.0-ask, 'no_ask': 1.0-bid, 'spread': ask-bid,
            'age': age, 'source': 'KALSHI DIRECT MARKET BBO', 'healthy': True,
            'divergence': 0.0, 'cross_checked': []
        }
    except Exception:
        return {}


def _v266_quote_snapshot(self, max_age=3.0):
    q = {}
    try:
        q = dict(_V266_BASE_QUOTE_SNAPSHOT(self, max_age=max_age) or {})
    except Exception:
        q = {}
    if q:
        return q
    # The dedicated mesh can be a few heartbeats behind immediately after a
    # market rollover. Use only a genuinely fresh official Kalshi market BBO.
    return _v266_direct_market_quote(self, max_age=max_age)


def _v266_toggle_paper(self):
    enabled = bool(self.auto_paper_enabled_var.get())
    if enabled:
        self.paper_status_var.set('PAPER AUTO: ON • BOOKMAP MASTER controls entries • simulation only')
        self.auto_paper_reason_var.set('Paper auto armed • waiting for Bookmap Master + executable Kalshi ask')
    else:
        self.paper_status_var.set('PAPER AUTO: OFF • existing paper position is not auto-closed')
        self.auto_paper_reason_var.set('Paper auto disabled from permanent execution control')


def _v266_paper_exit_now(self):
    if not getattr(self, 'paper_active_trade', None):
        self.paper_status_var.set('PAPER EXIT: no open Bookmap Master paper position')
        return False
    try:
        return bool(_v264_paper_finalize(self, reason='MANUAL PAPER EXIT'))
    except Exception as exc:
        self.paper_status_var.set(f'PAPER EXIT ERROR: {exc}')
        return False


def _v266_test_paper_pipeline(self):
    """Simulation-only diagnostic entry using the current Bookmap Master side."""
    if getattr(self, 'paper_active_trade', None):
        self.paper_status_var.set('PAPER TEST: blocked • a paper position is already open')
        return False
    master = _v264_master_read(self, now=time.time())
    if not master.get('ready') or str(master.get('side','WAIT')).upper() not in ('UP','DOWN'):
        self.paper_status_var.set('PAPER TEST: waiting for a real Bookmap Master whole-round side')
        return False
    side = str(master['side']).upper()
    px, _yes, src, age = _v264_paper_price(self, side, 'ENTER', _V264_ENTRY_QUOTE_MAX_AGE)
    if px is None:
        self.paper_status_var.set(f'PAPER TEST: no executable {side} Kalshi ask • {src}')
        return False
    if float(px) > _V264_MAX_PAPER_ENTRY:
        self.paper_status_var.set(f'PAPER TEST: NO CHASE • {side} ask {float(px)*100:.1f}¢ > 70¢')
        return False
    # Diagnostic entry still uses the normal durable journal function. It is
    # explicitly tagged so history can distinguish it from automatic entries.
    return bool(_v264_paper_open(
        self, side, entry_source='BOOKMAP MASTER TEST',
        auto_score=float(master.get('health',0))*100.0,
        auto_reason=f"SIMULATION PIPELINE TEST • {master.get('road','')} • {src} age {age:.2f}s"
    ))


def _v266_ensure_execution_card(self):
    page = getattr(self, 'page_frame', None)
    if page is None:
        return False
    old = getattr(self, '_v266_execution_card', None)
    try:
        if old is not None and int(old.winfo_exists()):
            # Delayed legacy builders can add/reorder packed rows after our first
            # build. Reassert this card as the FIRST packed row every defense pass.
            try:
                packed_now = [w for w in page.pack_slaves() if w is not old]
                if packed_now:
                    old.pack_configure(before=packed_now[0])
            except Exception:
                pass
            return True
    except Exception:
        pass

    # Variables exist before _build_ui in the canonical ChartKing init, but keep
    # defensive fallbacks for imported/test harnesses.
    if not hasattr(self, 'v266_bbo_var'):
        self.v266_bbo_var = tk.StringVar(value='KALSHI BBO: waiting')
    if not hasattr(self, 'v266_master_exec_var'):
        self.v266_master_exec_var = tk.StringVar(value='BOOKMAP MASTER EXECUTION: waiting')
    if not hasattr(self, 'v266_journal_var'):
        self.v266_journal_var = tk.StringVar(value='PAPER JOURNAL: waiting')

    box = tk.Frame(page, bg=PANEL2, padx=12, pady=10, highlightthickness=2, highlightbackground=GREEN)
    self._v266_execution_card = box
    try:
        kids = [w for w in page.winfo_children() if w is not box]
        # page_frame mixes place + pack from historical UI generations.  Tk's
        # `before` only orders widgets managed by the SAME packer, so anchor to
        # the first already-packed child instead of blindly using kids[0].
        packed = [w for w in kids if str(w.winfo_manager()) == 'pack']
        box.pack(fill='x', padx=10, pady=(8,6))
        if packed:
            box.pack_configure(before=packed[0])
    except Exception:
        box.pack(fill='x', padx=10, pady=(8,6))

    head = tk.Frame(box, bg=PANEL2)
    head.pack(fill='x')
    tk.Label(head, text='EXECUTION CONTROL // BOOKMAP MASTER', bg=PANEL2, fg=GREEN,
             font=('Segoe UI Variable', 12, 'bold'), anchor='w').pack(side='left')
    tk.Label(head, text='PAPER = SIMULATION • LIVE = REAL KALSHI', bg=PANEL2, fg=YELLOW,
             font=('Segoe UI Variable', 9, 'bold'), anchor='e').pack(side='right')

    paper_row = tk.Frame(box, bg=PANEL2)
    paper_row.pack(fill='x', pady=(8,4))
    ttk.Checkbutton(paper_row, text='PAPER AUTO (BOOKMAP MASTER)',
                    variable=self.auto_paper_enabled_var, command=lambda s=self: _v266_toggle_paper(s)).pack(side='left')
    ttk.Label(paper_row, text='Paper stake $', style='Muted.Card.TLabel').pack(side='left', padx=(12,4))
    ttk.Entry(paper_row, textvariable=self.paper_stake_var, width=8).pack(side='left')
    tk.Button(paper_row, text='TEST PAPER PIPELINE', command=lambda s=self: _v266_test_paper_pipeline(s),
              bg=PANEL, fg=CYAN, activebackground=PINK_DARK, activeforeground=CYAN,
              relief='flat', bd=0, padx=9, pady=4, font=('Segoe UI', 9, 'bold')).pack(side='left', padx=(10,5))
    tk.Button(paper_row, text='EXIT PAPER NOW', command=lambda s=self: _v266_paper_exit_now(s),
              bg=PANEL, fg=ORANGE, activebackground=PINK_DARK, activeforeground=ORANGE,
              relief='flat', bd=0, padx=9, pady=4, font=('Segoe UI', 9, 'bold')).pack(side='left', padx=(5,5))
