def _v266_refresh_execution_card(self):
    try:
        _v266_ensure_execution_card(self)
        q = _v266_quote_snapshot(self, max_age=4.0)
        if q:
            self.v266_bbo_var.set(
                f"KALSHI BBO • YES {float(q['yes_bid'])*100:.1f}¢ / {float(q['yes_ask'])*100:.1f}¢ • "
                f"NO {float(q['no_bid'])*100:.1f}¢ / {float(q['no_ask'])*100:.1f}¢ • "
                f"{q.get('source','KALSHI')} • age {float(q.get('age',0)):.2f}s"
            )
        else:
            self.v266_bbo_var.set('KALSHI BBO: WAITING FOR FRESH EXECUTABLE BID/ASK')
        master = _v264_master_read(self, now=time.time())
        side = str(master.get('side','WAIT')).upper()
        self.v266_master_exec_var.set(
            f"BOOKMAP MASTER • {side} • {'READY' if master.get('ready') else 'WAIT'} • "
            f"health {float(master.get('health',0))*100:.0f}/100 • rough {float(master.get('roughness',0))*100:.0f}/100 • "
            f"{master.get('road','building')} • PAPER {'ON' if self.auto_paper_enabled_var.get() else 'OFF'}"
        )
        d = _v265_visible_rows(self)
        total,wins,losses,pnl = d['stats']
        if d['open']:
            r=d['open']
            self.v266_journal_var.set(
                f"PAPER JOURNAL • OPEN #{r[0]} {r[1]} @ {float(r[2])*100:.1f}¢ • "
                f"{float(r[4]):g} contracts • {d['events']} events"
            )
        else:
            self.v266_journal_var.set(
                f"PAPER JOURNAL • no open trade • completed {total} • {wins}-{losses} • P/L ${pnl:+.2f} • {d['events']} events"
            )
    except Exception as exc:
        try:
            self.v266_master_exec_var.set(f'EXECUTION CONTROL ERROR: {exc}')
        except Exception:
            pass
    try:
        self.root.after(250, lambda s=self: _v266_refresh_execution_card(s))
    except Exception:
        pass


def _v266_build_ui(self):
    _V266_BASE_BUILD_UI(self)
    # Build directly on page_frame; never depend on or search for legacy paper UI.
    _v266_ensure_execution_card(self)


def _v266_init(self, *args, **kwargs):
    self._v266_execution_card = None
    self._v266_refresh_started = False
    _V266_BASE_INIT(self, *args, **kwargs)
    # PAPER is simulation and should actually run unless the user turns it off.
    try:
        self.auto_paper_enabled_var.set(True)
        self.paper_status_var.set('PAPER AUTO: ON • BOOKMAP MASTER controls entries • simulation only')
    except Exception:
        pass
    # Defense in depth against all delayed historical UI mutations.
    for delay in (40, 180, 600, 1600, 3200):
        try:
            self.root.after(delay, lambda s=self: _v266_ensure_execution_card(s))
        except Exception:
            pass
    if not getattr(self, '_v266_refresh_started', False):
        self._v266_refresh_started = True
        try:
            self.root.after(120, lambda s=self: _v266_refresh_execution_card(s))
        except Exception:
            pass


