# ============================================================================
# BOOKMAP KING V21.67 — OPEN LOCK PAPER EXECUTION AUTHORITY
# ============================================================================
# ENTRY PHILOSOPHY:
#   * OPEN LOCK chooses the PAPER side. No second confidence/health confirmation.
#   * The execution layer may only optimize the executable Kalshi price.
#   * Clean/cheap roads enter immediately.
#   * Rough roads get a SHORT bounded value window, then enter if <= 70c.
#   * Runtime heartbeat dispatches through the FINAL active paper method.
#   * LIVE rail is preview/alert only in this build; it never submits a real order.
# ============================================================================

_V267_RELEASE = 'V21.67'
_V267_BASE_INIT = ChartKingPro.__init__
_V267_BASE_BUILD_UI = ChartKingPro._build_ui
_V267_BASE_V266_ENSURE = _v266_ensure_execution_card


def _v267_current_open_lock(self, now=None):
    now = float(now or time.time())
    bucket = int(now // 900) * 900
    snap = dict(getattr(self, 'opening_lock_snapshot', None) or {})
    side = str(snap.get('lock_side', 'WAIT')).upper()
    if side not in ('UP', 'DOWN'):
        return None
    lock_bucket = getattr(self, 'opening_lock_bucket', None)
    if lock_bucket not in (None, ''):
        try:
            if int(lock_bucket) != bucket:
                return None
        except Exception:
            pass
    try:
        lock_ts = float(snap.get('time', 0.0) or 0.0)
        if lock_ts and int(lock_ts // 900) * 900 != bucket:
            return None
    except Exception:
        pass
    return snap


def _v267_open_lock_master(self, now=None):
    """Execution read: frozen OPEN LOCK is authoritative for PAPER entry side."""
    now = float(now or time.time())
    snap = _v267_current_open_lock(self, now)
    if not snap:
        return {'ready': False, 'side': 'WAIT', 'reason': 'waiting for frozen OPEN LOCK'}
    side = str(snap.get('lock_side')).upper()
    try:
        base = dict(_v264_master_read(self, now=now) or {})
    except Exception:
        base = {}
    # Preserve path/roughness diagnostics, but do NOT let current confidence,
    # health, flip-risk, or momentary flow veto a side already frozen by Open Lock.
    base.update({
        'ready': True,
        'side': side,
        'lock': snap,
        'entry_authority': 'OPEN LOCK',
        'lock_forecast_score': float(snap.get('forecast_score', 0.0) or 0.0),
        'roughness': float(base.get('roughness', 0.30) or 0.30),
        'health': float(base.get('health', 0.50) or 0.50),
        'road': str(base.get('road') or 'OPEN LOCK ROAD'),
        'seconds_left': max(0.0, 900.0 - (now % 900.0)),
    })
    detail = str(base.get('reason') or '').strip()
    base['reason'] = 'OPEN LOCK FROZEN • no confidence re-check' + (f' • {detail}' if detail else '')
    return base


def _v267_round_has_master_trade(self, bucket):
    """Only real automatic/manual BOOKMAP MASTER entries block another auto entry.
    Diagnostic TEST PAPER PIPELINE rows do not poison the whole round after close.
    """
    try:
        with self.stockpile_db_lock:
            with self._stockpile_connect() as conn:
                row = conn.execute(
                    """SELECT id,status,entry_source FROM paper_trades
                       WHERE authority_name='BOOKMAP MASTER' AND bucket=?
                         AND COALESCE(entry_source,'') <> 'BOOKMAP MASTER TEST'
                       ORDER BY id DESC LIMIT 1""",
                    (int(bucket),)
                ).fetchone()
        return bool(row)
    except Exception:
        return int(getattr(self, '_v267_traded_bucket', -1) or -1) == int(bucket)


def _v267_open_lock_value_plan(self, master, ask, now=None):
    """Price optimization only. It never re-votes on the Open Lock direction."""
    now = float(now or time.time())
    ask = float(ask)
    side = str(master.get('side', 'WAIT')).upper()
    rough = max(0.0, min(1.0, float(master.get('roughness', 0.0) or 0.0)))
    left = float(master.get('seconds_left', 0.0) or 0.0)
    bucket = int(now // 900) * 900
    st = dict(getattr(self, '_v267_open_value_state', {}) or {})
    if int(st.get('bucket', -1) or -1) != bucket or str(st.get('side', '')).upper() != side:
        st = {'bucket': bucket, 'side': side, 'start': now, 'anchor': ask, 'best': ask, 'target': ask, 'last_ask': ask}
    anchor = float(st.get('anchor', ask) or ask)
    best = min(float(st.get('best', ask) or ask), ask)
    st['best'] = best
    st['last_ask'] = ask
    age = max(0.0, now - float(st.get('start', now) or now))

    if ask > _V264_MAX_PAPER_ENTRY:
        st['target'] = _V264_MAX_PAPER_ENTRY
        self._v267_open_value_state = st
        return {'enter': False, 'target': _V264_MAX_PAPER_ENTRY, 'state': 'OPEN LOCK READY • NO CHASE >70¢', 'age': age, 'best': best, 'max_wait': 0.0}

    # Cheap contract or cleaner path: Open Lock fires straight into paper.
    if ask <= .50 or rough < .45 or left <= 420:
        st['target'] = ask
        self._v267_open_value_state = st
        return {'enter': True, 'target': ask, 'state': 'OPEN LOCK → TAKE EXECUTABLE ASK', 'age': age, 'best': best, 'max_wait': 0.0}

    # Rough path: a SHORT value hunt only. No confidence/health thresholds here.
    improvement = .018 + .030 * rough       # about 3.2c-4.8c on rough roads
    target = max(.08, min(.68, anchor - improvement))
    max_wait = min(10.0, 4.0 + 7.0 * rough) # <= 10 seconds, never 48 seconds
    st['target'] = target
    hit = ask <= target + .002
    improved = (anchor - best) >= .012
    rebound = improved and ask >= best + .008 and ask <= min(.70, anchor + .002)
    deadline = age >= max_wait

    if hit:
        enter, state = True, 'OPEN LOCK VALUE DIP HIT'
    elif rebound:
        enter, state = True, f'OPEN LOCK VALUE REBOUND • best {best*100:.1f}¢'
    elif deadline:
        enter, state = True, 'OPEN LOCK VALUE WINDOW DONE → TAKE ASK'
    else:
        enter, state = False, f'OPEN LOCK {side} • SHORT VALUE HUNT <= {target*100:.1f}¢ • {max_wait-age:.1f}s max'
    self._v267_open_value_state = st
    return {'enter': enter, 'target': target, 'state': state, 'age': age, 'best': best, 'max_wait': max_wait}


def _v267_master_step(self, warm=None, sig=None, candles=None, now=None, mode='LIVE'):
    """Final PAPER execution loop. Open Lock picks side; price layer picks fill timing."""
    now = float(now or time.time())
    if now - float(getattr(self, '_v267_last_step', 0.0) or 0.0) < .09:
        return False
    self._v267_last_step = now
    try:
        _v264_paper_mark(self)
    except Exception:
        pass

    if self.paper_active_trade:
        trade = dict(self.paper_active_trade)
        bucket = int(trade.get('bucket', 0) or 0)
        current = int(now // 900) * 900
        if bucket < current:
            _v264_reconcile_settlement_async(self)
            return False
        # Existing exit protection remains independent from entry authority.
        master = _v264_master_read(self, now)
        do_exit, reason = _v264_should_exit(self, master)
        if do_exit and bool(self.paper_auto_exit_var.get()):
            _contract, yes_equiv, _src, _age = _v264_paper_price(self, trade['direction'], 'EXIT', _V264_EXIT_QUOTE_MAX_AGE)
            if yes_equiv is not None:
                return bool(_v264_paper_finalize(self, exit_yes=yes_equiv, reason=reason))
        return False

    if not bool(self.auto_paper_enabled_var.get()):
        self._set_var_if_changed(self.auto_paper_score_var, 'PAPER AUTO: OFF')
        self._set_var_if_changed(self.auto_paper_reason_var, 'Enable PAPER AUTO in EXECUTION CONTROL.')
        return False

    bucket = int(now // 900) * 900
    if _v267_round_has_master_trade(self, bucket):
        self._v267_traded_bucket = bucket
        self._set_var_if_changed(self.auto_paper_score_var, 'OPEN LOCK PAPER: ROUND ALREADY TRADED')
        self._set_var_if_changed(self.auto_paper_reason_var, 'One automatic Bookmap Master entry maximum per 15-minute market.')
        return False

    master = _v267_open_lock_master(self, now)
    if not master.get('ready'):
        self._set_var_if_changed(self.auto_paper_score_var, 'OPEN LOCK PAPER: WAITING FOR LOCK')
        self._set_var_if_changed(self.auto_paper_reason_var, master.get('reason', 'waiting for frozen OPEN LOCK'))
        return False

    side = str(master['side']).upper()
    ask, _yes, qsrc, qage = _v264_paper_price(self, side, 'ENTER', _V264_ENTRY_QUOTE_MAX_AGE)
    if ask is None:
        self._set_var_if_changed(self.auto_paper_score_var, f'OPEN LOCK {side} → EXECUTION READY • BBO WAIT')
        self._set_var_if_changed(self.auto_paper_reason_var, f'Lock is authoritative; waiting only for a fresh executable Kalshi {side} ask • {qsrc}')
        return False

    plan = _v267_open_lock_value_plan(self, master, ask, now)
    self._v264_last_plan = dict(plan)
    self._set_var_if_changed(self.auto_paper_score_var, f'OPEN LOCK {side} → PAPER EXECUTION • ASK {ask*100:.1f}¢')
    self._set_var_if_changed(self.auto_paper_reason_var, f"{plan['state']} • {qsrc} age {qage:.2f}s • NO CONFIDENCE RE-CHECK")
    if not plan.get('enter'):
        return False

    opened = bool(_v264_paper_open(
        self,
        side,
        entry_source='BOOKMAP MASTER AUTO',
        auto_score=float(master.get('lock_forecast_score', 0.0) or 0.0),
        auto_reason=f"OPEN LOCK AUTHORITY • {plan['state']} • {master.get('road','')}"
    ))
    if opened:
        self._v267_traded_bucket = bucket
        self._set_var_if_changed(self.auto_paper_reason_var, f'PAPER ENTRY LOGGED • OPEN LOCK {side} • {plan["state"]} • {qsrc}')
    return opened


def _v267_heartbeat(self):
    """Critical fix: dispatch to the FINAL active execution method, never V21.64."""
    try:
        tick = getattr(self, '_auto_paper_unified_tick', None)
        if callable(tick):
            tick(now=time.time())
        if int(time.time()) % 15 == 0 and time.time() - float(getattr(self, '_v264_last_audit', 0) or 0) > 10:
            self._v264_last_audit = time.time()
            _v264_journal_audit(self)
    finally:
        try:
            self.root.after(120, lambda s=self: _v267_heartbeat(s))
        except Exception:
            pass


# ---------------- LIVE MIRROR PREVIEW / ALERT ONLY ----------------
def _v267_live_toggle_requested(self):
    requested = bool(self.live_auto_enabled_var.get())
    if requested:
        self.live_auto_status_var.set('LIVE MIRROR PREVIEW: ARMED • no real order submission • mirrors Open Lock paper entries')
    else:
        self.live_auto_status_var.set('LIVE MIRROR PREVIEW: OFF')


def _v267_live_preview_entry(self, direction, paper_contract_px=None, reason='AUTO'):
    direction = str(direction).upper()
    if direction not in ('UP', 'DOWN') or not bool(self.live_auto_enabled_var.get()):
        return False
    ticker = _v75_current_ticker(self)
    contract, yes_equiv, src, age = _v264_paper_price(self, direction, 'ENTER', _V264_ENTRY_QUOTE_MAX_AGE)
    if contract is None or yes_equiv is None:
        self._v86_live_set('LIVE MIRROR PREVIEW: waiting for executable quote')
        return False
    stake = _v264_live_stake(self)
    count = stake / max(float(contract), .01)
    self._v86_live_set(
        f'LIVE MIRROR PREVIEW • WOULD ENTER {direction} @ {float(contract)*100:.1f}¢ • ${stake:.2f} • {src} age {float(age):.2f}s',
        f'LIVE PREVIEW: {direction} • {ticker} • ~{count:.2f} contracts • NO ORDER SENT'
    )
    return True


def _v267_live_preview_exit(self, reason='AUTO EXIT'):
    self._v86_live_set(f'LIVE MIRROR PREVIEW • WOULD EXIT • {reason}', 'LIVE PREVIEW: no real position tracked')
    return True


def _v267_live_clear(self):
    try:
        self.live_auto_enabled_var.set(False)
    except Exception:
        pass
    self._v86_live_set('LIVE MIRROR PREVIEW: CLEARED', 'LIVE PREVIEW: none')
    return True


def _v267_relabel_execution_card(self):
    try:
        card = getattr(self, '_v266_execution_card', None)
        if card is None:
            return
        stack = [card]
        while stack:
            w = stack.pop()
            try:
                stack.extend(list(w.winfo_children()))
            except Exception:
                pass
            try:
                txt = str(w.cget('text') or '')
            except Exception:
                txt = ''
            if txt == 'PAPER AUTO (BOOKMAP MASTER)':
                try: w.configure(text='PAPER AUTO — ENTER OPEN LOCK')
                except Exception: pass
            elif txt == 'LIVE AUTO (REAL KALSHI)':
                try: w.configure(text='LIVE MIRROR PREVIEW (NO ORDER SUBMIT)')
                except Exception: pass
            elif txt == 'KILL LIVE + EXIT':
                try: w.configure(text='CLEAR LIVE PREVIEW', command=lambda s=self: _v267_live_clear(s))
                except Exception: pass
        try:
            self.paper_status_var.set('PAPER AUTO: ON • OPEN LOCK is entry authority • no confidence re-check')
            self.live_auto_status_var.set('LIVE MIRROR PREVIEW: OFF • paper execution is automatic')
        except Exception:
            pass
    except Exception:
        pass


def _v267_build_ui(self):
    _V267_BASE_BUILD_UI(self)
    try:
        _v267_relabel_execution_card(self)
    except Exception:
        pass


def _v267_init(self, *args, **kwargs):
    self._v267_last_step = 0.0
    self._v267_traded_bucket = None
    self._v267_open_value_state = {}
    _V267_BASE_INIT(self, *args, **kwargs)
    # CRITICAL RUNTIME FIX: V21.33's historical initializer mutates the class
    # during construction and replaces _auto_paper_unified_tick with a no-op.
    # Re-pin the final executor AFTER the entire legacy init chain returns, and
    # bind it on this instance so no later class mutation can silently disable it.
    ChartKingPro._auto_paper_unified_tick = _v267_master_step
    try:
        self._auto_paper_unified_tick = _v267_master_step.__get__(self, ChartKingPro)
    except Exception:
        pass
    try:
        self.auto_paper_enabled_var.set(True)
        self.paper_status_var.set('PAPER AUTO: ON • OPEN LOCK is entry authority • no confidence re-check')
    except Exception:
        pass
    for delay in (80, 300, 900, 2200, 4200):
        try:
            self.root.after(delay, lambda s=self: _v267_relabel_execution_card(s))
        except Exception:
            pass


# Fix the stale V21.64 heartbeat by replacing the global target that its already-
# scheduled callbacks resolve at runtime.
_v264_heartbeat = _v267_heartbeat

ChartKingPro._auto_paper_unified_tick = _v267_master_step
ChartKingPro._v267_open_lock_master = _v267_open_lock_master
ChartKingPro._v267_open_lock_value_plan = _v267_open_lock_value_plan
ChartKingPro._v267_round_has_master_trade = _v267_round_has_master_trade
ChartKingPro._live_toggle_requested = _v267_live_toggle_requested
ChartKingPro._v86_live_submit_entry = _v267_live_preview_entry
ChartKingPro._v86_live_submit_exit = _v267_live_preview_exit
ChartKingPro._live_kill_and_exit = _v267_live_clear
ChartKingPro._build_ui = _v267_build_ui
ChartKingPro.__init__ = _v267_init



def _v267_test_paper_pipeline(self):
    if self.paper_active_trade:
        self.paper_status_var.set('TEST PAPER: blocked • an active paper trade already exists')
        return False
    master = _v267_open_lock_master(self, now=time.time())
    if not master.get('ready'):
        self.paper_status_var.set('TEST PAPER: waiting for a frozen OPEN LOCK')
        return False
    side = str(master.get('side','WAIT')).upper()
    ask, _yes, src, age = _v264_paper_price(self, side, 'ENTER', _V264_ENTRY_QUOTE_MAX_AGE)
    if ask is None:
        self.paper_status_var.set(f'TEST PAPER: OPEN LOCK {side} ready • waiting executable Kalshi ask')
        return False
    return bool(_v264_paper_open(
        self, side, entry_source='BOOKMAP MASTER TEST',
        auto_score=float(master.get('lock_forecast_score',0.0) or 0.0),
        auto_reason=f'OPEN LOCK PIPELINE TEST • {src} age {float(age):.2f}s'
    ))


def _v267_refresh_execution_card(self):
    try:
        _v266_ensure_execution_card(self)
        _v267_relabel_execution_card(self)
        q = _v266_quote_snapshot(self, max_age=4.0)
        if q:
            self.v266_bbo_var.set(
                f"KALSHI BBO • YES {float(q['yes_bid'])*100:.1f}¢ / {float(q['yes_ask'])*100:.1f}¢ • "
                f"NO {float(q['no_bid'])*100:.1f}¢ / {float(q['no_ask'])*100:.1f}¢ • "
                f"{q.get('source','KALSHI')} • age {float(q.get('age',0)):.2f}s"
            )
        else:
            self.v266_bbo_var.set('KALSHI BBO: WAITING FOR FRESH EXECUTABLE BID/ASK')
        master = _v267_open_lock_master(self, now=time.time())
        side = str(master.get('side','WAIT')).upper()
        self.v266_master_exec_var.set(
            f"ENTRY AUTHORITY: OPEN LOCK • {side} • {'ARMED' if master.get('ready') else 'WAIT'} • "
            f"rough {float(master.get('roughness',0))*100:.0f}/100 • {master.get('road','building')} • "
            f"PAPER {'ON' if self.auto_paper_enabled_var.get() else 'OFF'} • NO CONFIDENCE RE-CHECK"
        )
        d = _v265_visible_rows(self)
        total,wins,losses,pnl = d['stats']
        if d['open']:
            r=d['open']
            self.v266_journal_var.set(
                f"PAPER JOURNAL • OPEN #{r[0]} {r[1]} @ {float(r[2])*100:.1f}¢ • "
                f"{float(r[4]):g} contracts • {d['events']} events"
            )
        else:
            self.v266_journal_var.set(
                f"PAPER JOURNAL • no open trade • completed {total} • {wins}-{losses} • P/L ${pnl:+.2f} • {d['events']} events"
            )
    except Exception as exc:
        try:
            self.v266_master_exec_var.set(f'EXECUTION CONTROL ERROR: {exc}')
        except Exception:
            pass
    try:
        self.root.after(250, lambda s=self: _v267_refresh_execution_card(s))
    except Exception:
        pass


