    try:
        _v2672_ensure_vars(self)
        self.root.after(350, lambda s=self: _v2672_sidecar_tick(s))
        self.root.title('BOOKMAP KING V21.67.2 — GOLD MASTER + QUEST SIDECAR')
    except Exception:
        pass


