_V2673_RELEASE = 'V21.67.3'
_V2673_BASE_INIT = ChartKingPro.__init__
_V2673_BASE_BUILD_UI = ChartKingPro._build_ui


def _v2673_num(value, default=None):
    try:
        value = float(value)
        return value if math.isfinite(value) else default
    except Exception:
        return default


def _v2673_clip01(value):
    try:
        return max(0.0, min(1.0, float(value)))
    except Exception:
        return 0.0


def _v2673_side_sign(side):
    side = str(side or 'WAIT').upper()
    return 1.0 if side == 'UP' else -1.0 if side == 'DOWN' else 0.0


def _v2673_ensure_vars(self):
    if not hasattr(self, 'v2673_head_var'):
        self.v2673_head_var = tk.StringVar(value='15M JOURNEY MAPPER: waiting for Gold Master lock')
        self.v2673_stage_var = tk.StringVar(value='QUEST STAGE: BUILDING')
        self.v2673_route_var = tk.StringVar(value='EXPECTED QUEST: collecting native Bookmap path evidence')
        self.v2673_checkpoint_var = tk.StringVar(value='NEXT CHECKPOINT: --')
        self.v2673_reversion_var = tk.StringVar(value='MEAN REVERSION: building fair-value map')
        self.v2673_finish_var = tk.StringVar(value='PROJECTED SETTLEMENT: --')
        self.v2673_evidence_var = tk.StringVar(value='RAW EVIDENCE: --')
        self.v2673_integrity_var = tk.StringVar(value='READ-ONLY NAVIGATOR • GOLD MASTER OPEN LOCK UNTOUCHED')
    if not hasattr(self, 'v2673_canvas'):
        self.v2673_canvas = None
    if not hasattr(self, '_v2673_card'):
        self._v2673_card = None
    if not hasattr(self, '_v2673_context_cache'):
        self._v2673_context_cache = {}
    if not hasattr(self, '_v2673_last_render_key'):
        self._v2673_last_render_key = None
    if not hasattr(self, '_v2673_last_map'):
        self._v2673_last_map = {}


def _v2673_micro_rows(self, seconds, now=None, limit=120, include_forming=True):
    now = float(now or time.time())
    seconds = int(seconds)
    try:
        with self.bookmap_lock:
            rows = [dict(r) for r in list(getattr(self, 'bookmap_micro_candles', {}).get(seconds, ()))[-int(limit):]]
    except Exception:
        rows = [dict(r) for r in list(getattr(self, 'bookmap_micro_candles', {}).get(seconds, ()))[-int(limit):]]
    out = []
    for row in rows:
        try:
            ts = float(row.get('time', 0.0) or 0.0)
            if now - ts > max(600.0, seconds * limit * 1.5):
                continue
            if (not include_forming) and ts + seconds > now:
                continue
            for key in ('open', 'high', 'low', 'close'):
                if not math.isfinite(float(row[key])):
                    raise ValueError('bad price')
            out.append(row)
        except Exception:
            continue
    return out


def _v2673_weighted_fair(rows):
    """Executed-volume weighted typical price; arithmetic fallback when volume is absent."""
    vals = []
    weighted = []
    for r in rows or []:
        try:
            typ = (float(r['high']) + float(r['low']) + float(r['close'])) / 3.0
            vol = max(0.0, float(r.get('volume', 0.0) or 0.0))
            vals.append(typ)
            if vol > 0:
                weighted.append((typ, vol))
        except Exception:
            continue
    if weighted:
        den = sum(w for _p, w in weighted)
        if den > 0:
            return sum(p * w for p, w in weighted) / den
    return (sum(vals) / len(vals)) if vals else None


def _v2673_body_read(row):
    try:
        op = float(row['open']); hi = float(row['high']); lo = float(row['low']); cl = float(row['close'])
        rng = max(hi - lo, 1e-9)
        if cl >= op:
            excursion = max(hi - op, 1e-9)
            retain = max(0.0, min(1.0, (cl - op) / excursion))
            giveback = max(0.0, hi - cl)
            side = 'UP' if cl > op else 'FLAT'
        else:
            excursion = max(op - lo, 1e-9)
            retain = max(0.0, min(1.0, (op - cl) / excursion))
            giveback = max(0.0, cl - lo)
            side = 'DOWN'
        close_pos = (cl - lo) / rng
        return {'ready': True, 'side': side, 'retain': retain, 'giveback': giveback,
                'excursion': excursion, 'range': rng, 'close_pos': close_pos,
                'open': op, 'close': cl, 'high': hi, 'low': lo}
    except Exception:
        return {'ready': False, 'side': 'FLAT', 'retain': 0.0, 'giveback': 0.0, 'excursion': 0.0}


def _v2673_micro_read(self, now=None):
    now = float(now or time.time())
    stats = _v2672_movement_stats(self, now)
    quantum = max(0.25, float(stats.get('quantum_5s', 1.0) or 1.0)) if stats.get('ready') else 1.0
    out = {'ready': False, 'score': 0.0, 'velocity': 0.0, 'acceleration': 0.0,
           'retain': 0.0, 'body_side': 'FLAT', 'quantum': quantum,
           'activity': float(stats.get('activity', 1.0) or 1.0) if stats.get('ready') else 1.0}
    parts = []
    velocities = []
    acceleration_parts = []
    latest_body = None
    for sec, weight in ((3, 0.58), (5, 0.42)):
        rows_all = _v2673_micro_rows(self, sec, now=now, limit=30, include_forming=True)
        closed = [r for r in rows_all if float(r.get('time', 0) or 0) + sec <= now]
        if len(closed) < 4:
            continue
        take = closed[-min(len(closed), 7):]
        first = float(take[0]['close']); last = float(take[-1]['close'])
        dt = max(float(sec), float(take[-1]['time']) - float(take[0]['time']) + sec)
        net = last - first
        vel = net / dt
        scale = max(quantum * (1.45 if sec == 3 else 1.70), 1.0)
        parts.append((math.tanh(net / scale), weight))
        velocities.append((vel, weight))
        if len(take) >= 6:
            half = max(2, len(take)//2)
            a = take[-2*half:-half]
            b = take[-half:]
            if len(a) >= 2 and len(b) >= 2:
                av = (float(a[-1]['close']) - float(a[0]['close'])) / max(sec, (float(a[-1]['time']) - float(a[0]['time']) + sec))
                bv = (float(b[-1]['close']) - float(b[0]['close'])) / max(sec, (float(b[-1]['time']) - float(b[0]['time']) + sec))
                acceleration_parts.append(((bv-av) / max(quantum/sec, 1e-6), weight))
        if rows_all:
            body = _v2673_body_read(rows_all[-1])
            if body.get('ready') and (latest_body is None or sec == 3):
                latest_body = body
    if not parts:
        return out
    den = sum(w for _v, w in parts)
    score = sum(v*w for v,w in parts) / max(den,1e-9)
    vden = sum(w for _v,w in velocities) or 1.0
    velocity = sum(v*w for v,w in velocities) / vden
    acceleration = 0.0
    if acceleration_parts:
        aden = sum(w for _v,w in acceleration_parts) or 1.0
        acceleration = max(-2.0, min(2.0, sum(v*w for v,w in acceleration_parts)/aden))
    out.update({'ready': True, 'score': max(-1.0,min(1.0,score)), 'velocity': velocity,
                'acceleration': acceleration})
    if latest_body:
        out['retain'] = float(latest_body.get('retain',0.0) or 0.0)
        out['body_side'] = str(latest_body.get('side','FLAT'))
        out['body'] = latest_body
    return out


def _v2673_context(self, now=None):
    """Slower structure packet. Cached so the navigator cannot bog down the UI."""
    now = float(now or time.time())
    cache = dict(getattr(self, '_v2673_context_cache', {}) or {})
    if now - float(cache.get('ts', 0.0) or 0.0) < 1.20 and cache.get('value'):
        return dict(cache['value'])
    live, target, source = _v2672_target_and_live(self)
    lock = dict(getattr(self, 'opening_lock_snapshot', None) or {})
    lock_side = str(lock.get('lock_side','WAIT')).upper()
    try:
        data = dict(_v263_data_ceiling(self, warm=None, now=now) or {})
    except Exception:
        data = {}
    try:
        dest = dict(_v263_destination_context(self, warm=None, now=now) or {})
    except Exception:
        dest = dict(data.get('destination_context') or {})
    sig = dict(getattr(self, 'last_signal', {}) or {})
    if not sig.get('ready'):
        sig = {}
    seconds = 15
    try:
        rows = _v263_history_rows(self, 15, now=now, limit=72)
    except Exception:
        rows = []
    if len(rows) < 12:
        seconds = 30
        try: rows = _v263_history_rows(self, 30, now=now, limit=60)
        except Exception: rows = []
    if len(rows) < 10:
        seconds = 60
        try: rows = _v263_history_rows(self, 60, now=now, limit=48)
        except Exception: rows = []
    liquidity = {}
    reaction = {}
    fvgs = []
    trend_overlay = {}
    if len(rows) >= 10:
        try:
            liquidity = dict(_v258_liquidity_read(rows, target=lock_side) or {})
        except Exception:
            liquidity = {}
        try:
            fvgs = list(self._web_chart_fvgs(rows, seconds) or [])
        except Exception:
            fvgs = []
        try:
            trend_overlay = dict(self.chart_trendline_overlays(rows) or {})
        except Exception:
            trend_overlay = {}
        try:
            reaction = dict(self._chart_reaction_levels(rows, seconds, sig=sig or None,
                                                        chart_fvgs=fvgs, trend_overlay=trend_overlay,
                                                        live_price=live) or {})
        except Exception:
            reaction = {}
    value = {'live': live, 'target': target, 'source': source, 'lock': lock, 'lock_side': lock_side,
             'data': data, 'dest': dest, 'sig': sig, 'rows': rows, 'seconds': seconds,
             'liquidity': liquidity, 'reaction': reaction, 'fvgs': fvgs,
             'trend_overlay': trend_overlay}
    self._v2673_context_cache = {'ts': now, 'value': value}
    return dict(value)


def _v2673_fair_value(self, ctx, micro, now=None):
    now = float(now or time.time())
    live = _v2673_num(ctx.get('live'))
    target = _v2673_num(ctx.get('target'))
    sig = dict(ctx.get('sig') or {})
    round_start = int(now // 900) * 900
    rows5 = _v2673_micro_rows(self, 5, now=now, limit=190, include_forming=True)
    round_rows = [r for r in rows5 if float(r.get('time',0) or 0) >= round_start]
    round_fair = _v2673_weighted_fair(round_rows)
    chart_vwap = _v2673_num(sig.get('vwap'))
    prices = []
    if round_fair is not None: prices.append((round_fair, 0.52, 'round executed VWAP'))
    if chart_vwap is not None: prices.append((chart_vwap, 0.28, 'chart VWAP'))
    if target is not None: prices.append((target, 0.12, 'Kalshi target'))
    if round_rows:
        med = _v2672_median([float(r['close']) for r in round_rows[-36:]], live if live is not None else 0.0)
        if med: prices.append((med, 0.08, 'micro value median'))
    if not prices:
        return {'ready': False}
    den = sum(w for _p,w,_n in prices)
    fair = sum(p*w for p,w,_n in prices)/max(den,1e-9)
    atr = _v2673_num(sig.get('atr'))
    q = max(0.5, float(micro.get('quantum',1.0) or 1.0))
    if atr is None:
        atr = max(q*5.0, _v2673_num((ctx.get('reaction') or {}).get('atr'), q*5.0))
    width = max(q*1.20, float(atr)*0.10, 2.0)
    stretch_scale = max(width*1.6, q*2.8, float(atr)*0.16)
    stretch = 0.0 if live is None else (live-fair)/max(stretch_scale,1e-9)
    return {'ready': True, 'fair': fair, 'low': fair-width, 'high': fair+width,
            'width': width, 'stretch': stretch, 'atr': atr,
            'sources': [n for _p,_w,n in prices], 'round_vwap': round_fair,
            'chart_vwap': chart_vwap}


def _v2673_core_score_for_side(data, side):
    sign = _v2673_side_sign(side)
    fam = dict((data or {}).get('families') or {})
    vals = []
    weights = {'tape':0.34,'whale':0.22,'structure':0.24,'target':0.20}
    for name,w in weights.items():
        row = dict(fam.get(name) or {})
        if row.get('available'):
            vals.append((float(row.get('score',0.0) or 0.0)*sign,w))
    if not vals:
        return 0.0
    den=sum(w for _v,w in vals)
    return max(-1.0,min(1.0,sum(v*w for v,w in vals)/max(den,1e-9)))


def _v2673_reversion_read(self, ctx, fair, micro, tug, move, now=None):
    now = float(now or time.time())
    live = _v2673_num(ctx.get('live'))
    if live is None or not fair.get('ready'):
        return {'ready':False,'state':'BUILDING','side':'WAIT','strength':0.0,'eta_low':None,'eta_high':None}
    stretch = float(fair.get('stretch',0.0) or 0.0)
    if abs(stretch) < 0.38:
        return {'ready':True,'state':'AT FAIR VALUE','side':'WAIT','strength':15.0,'eta_low':None,'eta_high':None,
                'zone_low':fair['low'],'zone_high':fair['high'],'distance':0.0,'trigger':0.0}
    side = 'DOWN' if stretch > 0 else 'UP'
    sign = _v2673_side_sign(side)
    whale = dict((ctx.get('data') or {}).get('whale') or (tug.get('whale') or {}))
    absorption = str(whale.get('absorption','NONE') or 'NONE').upper()
    absorption_score = 0.0
    if side == 'UP' and absorption == 'BUYER ABSORPTION': absorption_score = 1.0
    if side == 'DOWN' and absorption == 'SELLER ABSORPTION': absorption_score = 1.0
    if side == 'UP' and absorption == 'SELLER ABSORPTION': absorption_score = -0.45
    if side == 'DOWN' and absorption == 'BUYER ABSORPTION': absorption_score = -0.45

    micro_score = float(micro.get('score',0.0) or 0.0) * sign
    micro_vel = float(micro.get('velocity',0.0) or 0.0) * sign
    micro_acc = float(micro.get('acceleration',0.0) or 0.0) * sign
    body_side = str(micro.get('body_side','FLAT'))
    body_toward = 1.0 if body_side == side else -0.35 if body_side in ('UP','DOWN') else 0.0
    body_retain = float(micro.get('retain',0.0) or 0.0)

    dest = dict(ctx.get('dest') or {})
    rev = dict((dest.get('subfamilies') or {}).get('reversal_trigger') or {})
    dest_rev = float(rev.get('score',0.0) or 0.0)*sign if rev.get('available') else 0.0
    ad = dict(dest.get('accumulation_distribution') or {})
    ad_score = float(ad.get('score',0.0) or 0.0)*sign if ad.get('ready') else 0.0

    reaction = dict(ctx.get('reaction') or {})
    reaction_score = 0.0
    reaction_target = None
    rr = reaction.get('bounce') if side=='UP' else reaction.get('reject')
    if rr:
        reaction_target = _v2673_num(rr.get('price'))
        rscore = float(rr.get('score',0.0) or 0.0)/100.0
        dist = abs(live-reaction_target) if reaction_target is not None else 1e9
        scale = max(float(fair.get('atr',10.0))*0.55, float(micro.get('quantum',1.0))*4.0, 5.0)
        proximity = max(0.0, 1.0-dist/max(scale,1e-9))
        reaction_score = rscore*proximity

    tug_align = float(tug.get('fused',0.0) or 0.0)*sign if tug.get('ready') else 0.0
    activity = float(move.get('activity', micro.get('activity',1.0)) or 1.0)
    stretch_score = _v2673_clip01((abs(stretch)-0.35)/1.65)
    trigger = (
        0.24*stretch_score +
        0.17*max(0.0,micro_score) +
        0.08*max(0.0,math.tanh(micro_vel/max(float(micro.get('quantum',1.0))/5.0,1e-6))) +
        0.08*max(0.0,micro_acc/1.5) +
        0.10*max(0.0,body_toward*body_retain) +
        0.12*max(0.0,absorption_score) +
        0.08*max(0.0,dest_rev) +
        0.05*max(0.0,ad_score) +
        0.05*max(0.0,reaction_score) +
        0.03*max(0.0,tug_align)
    )
    trigger -= 0.07*max(0.0,-micro_score)
    trigger -= 0.05*max(0.0,-absorption_score)
    trigger = _v2673_clip01(trigger)
    strength = max(5.0,min(99.0,100.0*(0.48*stretch_score + 0.34*trigger + 0.18*_v2673_clip01(activity/1.6))))

    if trigger >= 0.68:
        state='HAPPENING NOW'; eta_low,eta_high=0,15
    elif trigger >= 0.52:
        state='IMMINENT'; eta=max(8.0, min(55.0, 48.0*(1.0-trigger)/max(0.65,activity)))
        eta_low=max(5,int(eta*0.55)); eta_high=max(eta_low+5,int(eta*1.25))
    elif trigger >= 0.34:
        state='BUILDING'; eta=max(25.0,min(120.0,95.0*(1.0-trigger)/max(0.55,activity)))
        eta_low=max(15,int(eta*0.65)); eta_high=max(eta_low+10,int(eta*1.35))
    else:
        state='STRETCHED • NO TRIGGER'; eta_low=eta_high=None
    distance = max(0.0, abs(live-float(fair['fair']))-float(fair['width'])*0.35)
    return {'ready':True,'state':state,'side':side,'strength':strength,'eta_low':eta_low,'eta_high':eta_high,
            'zone_low':fair['low'],'zone_high':fair['high'],'distance':distance,'trigger':trigger,
            'stretch':stretch,'absorption':absorption,'reaction_target':reaction_target,
            'micro_align':micro_score,'dest_reversal':dest_rev,'tug_align':tug_align}


def _v2673_journey_read(self, now=None):
    now=float(now or time.time())
    ctx=_v2673_context(self,now)
    live=_v2673_num(ctx.get('live')); target=_v2673_num(ctx.get('target'))
    lock_side=str(ctx.get('lock_side','WAIT')).upper(); sign=_v2673_side_sign(lock_side)
    tug=_v2672_tug_read(self,now=now)
    move=_v2672_move_budget_read(self,now=now)
    micro=_v2673_micro_read(self,now=now)
    fair=_v2673_fair_value(self,ctx,micro,now=now)
    reversion=_v2673_reversion_read(self,ctx,fair,micro,tug,move,now=now)
    sec_left=max(0.0,900.0-(now%900.0))
    if live is None or target is None:
        return {'ready':False,'headline':'15M JOURNEY MAPPER: waiting for live Bookmap + target','stage':'BUILDING',
                'route_text':'Need exact target and live Bookmap price.','checkpoint_text':'NEXT CHECKPOINT: --',
                'reversion':reversion,'finish_text':'PROJECTED SETTLEMENT: --','evidence_text':'RAW EVIDENCE: building'}
    if lock_side not in ('UP','DOWN'):
        return {'ready':False,'headline':'15M JOURNEY MAPPER: waiting for GOLD MASTER OPEN LOCK','stage':'LOCK FORMING',
                'route_text':'Navigator stays neutral until the frozen Gold Master side exists.','checkpoint_text':'NEXT CHECKPOINT: wait for lock',
                'reversion':reversion,'finish_text':'PROJECTED SETTLEMENT: --','evidence_text':'RAW EVIDENCE: sensors live • no lock authority yet'}

    data=dict(ctx.get('data') or {}); dest=dict(ctx.get('dest') or {})
    core_align=_v2673_core_score_for_side(data,lock_side)
    dest_align=float(dest.get('score',0.0) or 0.0)*sign if dest.get('ready') else 0.0
    tug_align=float(tug.get('fused',0.0) or 0.0)*sign if tug.get('ready') else 0.0
    micro_align=float(micro.get('score',0.0) or 0.0)*sign if micro.get('ready') else 0.0
    survival=max(0.0,min(100.0,float(getattr(self,'flip_survival_value',96.0) or 96.0)))
    flip_risk=max(0.0,min(100.0,float(getattr(self,'trend_reversal_risk_value',0.0) or 0.0)))
    viability=float(move.get('viability',50.0) or 50.0) if move.get('ready') else 50.0
    budget=max(1.0,float(move.get('budget',max(20.0,abs(live-target))) or max(20.0,abs(live-target))))

    reversion_lock = 0.0
    if reversion.get('ready') and reversion.get('side') in ('UP','DOWN'):
        reversion_lock = _v2673_side_sign(reversion.get('side'))*sign*(float(reversion.get('trigger',0.0) or 0.0))

    # Route quality: Open Lock is the anchor; every other family is context.
    aligned_score = (
        0.30*core_align + 0.20*dest_align + 0.15*tug_align + 0.13*micro_align +
        0.09*((survival-50.0)/50.0) - 0.07*(flip_risk/100.0) + 0.06*reversion_lock
    )
    aligned_score=max(-1.0,min(1.0,aligned_score))
    route_match=max(3.0,min(99.0,62.0 + aligned_score*30.0 + (viability-50.0)*0.10))

    # Projected settlement is a distribution, not a magic single number.
    drift_fraction=max(0.05,min(0.66,0.16 + 0.36*max(0.0,aligned_score) + 0.10*(viability/100.0)))
    drift=sign*budget*drift_fraction
    mean_component=0.0
    if fair.get('ready'):
        toward=float(fair['fair'])-live
        rev_prob=float(reversion.get('trigger',0.0) or 0.0) if reversion.get('ready') else 0.0
        mean_component=toward*min(0.72,0.30+0.55*rev_prob)
    center=live+drift+mean_component
    uncertainty=budget*(0.19+0.28*(1.0-route_match/100.0)) + max(2.0,float(micro.get('quantum',1.0))*1.4)
    proj_low=center-uncertainty; proj_high=center+uncertainty
    finish_delta=center-target
    settle_side='UP' if center>target else 'DOWN' if center<target else 'LINE'

    # Build context-aware checkpoint candidates. They are route waypoints, not
    # guaranteed touches. Dedupe nearby levels so raw evidence is not double-counted.
    cps=[]
    def add_cp(price,label,kind='PATH',score=50.0):
        p=_v2673_num(price)
        if p is None: return
        tol=max(2.0,float(micro.get('quantum',1.0))*0.55)
        for row in cps:
            if abs(float(row['price'])-p)<=tol:
                if float(score)>float(row.get('score',0)):
                    row.update({'price':p,'label':label,'kind':kind,'score':score})
                return
        cps.append({'price':p,'label':label,'kind':kind,'score':float(score)})

    reaction=dict(ctx.get('reaction') or {})
    bounce=dict(reaction.get('bounce') or {}); reject=dict(reaction.get('reject') or {})
    # If the immediate micro leg is AGAINST the lock, explicitly map the likely
    # adverse test first instead of drawing a fantasy straight line to the target.
    if micro.get('ready') and micro_align < -0.10:
        adverse = bounce if lock_side=='UP' else reject
        if adverse.get('price') is not None:
            add_cp(adverse.get('price'),'ADVERSE TEST / ABSORPTION ZONE','ADVERSE',adverse.get('score',65))
    if fair.get('ready'):
        if (lock_side=='UP' and live < fair['low']) or (lock_side=='DOWN' and live > fair['high']):
            add_cp(fair['fair'],'MEAN-REVERSION VALUE','REVERSION',72+float(reversion.get('strength',0))*0.15)
        elif reversion.get('side') in ('UP','DOWN') and reversion.get('side') != lock_side and float(reversion.get('trigger',0) or 0)>=0.34:
            add_cp(fair['fair'],'COUNTER-TREND MEAN REVERSION','PULLBACK',65+float(reversion.get('strength',0))*0.12)
    if (lock_side=='UP' and live<target) or (lock_side=='DOWN' and live>target):
        add_cp(target,'KALSHI TARGET RECLAIM' if lock_side=='UP' else 'KALSHI TARGET LOSS','TARGET',90)
    else:
        add_cp(target,'TARGET RETEST / DEFENSE','TARGET',70)

    liq=dict(ctx.get('liquidity') or {})
    if lock_side=='UP':
        if reject.get('price') is not None and float(reject.get('price'))>live:
            add_cp(reject.get('price'),'NEXT RESISTANCE / REJECTION TEST','STRUCTURE',reject.get('score',60))
        if liq.get('buy_pool') is not None and float(liq.get('buy_pool'))>live:
            add_cp(liq.get('buy_pool'),'BUY-SIDE LIQUIDITY POOL','LIQUIDITY',float(liq.get('score',55) or 55))
    else:
        if bounce.get('price') is not None and float(bounce.get('price'))<live:
            add_cp(bounce.get('price'),'NEXT SUPPORT / BOUNCE TEST','STRUCTURE',bounce.get('score',60))
        if liq.get('sell_pool') is not None and float(liq.get('sell_pool'))<live:
            add_cp(liq.get('sell_pool'),'SELL-SIDE LIQUIDITY POOL','LIQUIDITY',float(liq.get('score',55) or 55))
    add_cp(center,'PROJECTED SETTLEMENT CENTER','FINISH',80)

    # Order the journey. Adverse/pullback checkpoints can come first; the rest
    # progress in the frozen lock direction from current price.
    first=[c for c in cps if c['kind'] in ('ADVERSE','PULLBACK','REVERSION') and ((lock_side=='UP' and c['price']<=live) or (lock_side=='DOWN' and c['price']>=live))]
    along=[c for c in cps if c not in first]
    first=sorted(first,key=lambda c:abs(c['price']-live))[:2]
    along=sorted(along,key=lambda c:(c['price'] if lock_side=='UP' else -c['price']))
    along=[c for c in along if (lock_side=='UP' and c['price']>=min(live,target)-budget*0.25) or (lock_side=='DOWN' and c['price']<=max(live,target)+budget*0.25)]
    ordered=(first+along)[:5]

    # Stage is deliberately descriptive rather than a second trading decision.
    target_cleared=(lock_side=='UP' and live>=target) or (lock_side=='DOWN' and live<=target)
    if reversion.get('state') in ('HAPPENING NOW','IMMINENT') and reversion.get('side')==lock_side:
        stage='ADVERSE LEG EXHAUSTING → LOCK-SIDE REVERSION'
    elif reversion.get('state') in ('HAPPENING NOW','IMMINENT') and reversion.get('side') not in ('WAIT',lock_side):
        stage='COUNTER-TREND REVERSION / PULLBACK EXPECTED'
    elif not target_cleared:
        stage='TARGET RECLAIM QUEST'
    elif micro_align>=0.14 and tug_align>=-0.05:
        stage='TARGET CLEARED → EXTENSION LEG'
    elif micro_align<-0.14:
        stage='TARGET CLEARED → RETEST / DEFENSE'
    else:
        stage='TARGET AREA → PATH DEVELOPING'
    if flip_risk>=35 or survival<=65:
        stage += ' • THESIS PRESSURE RISING'

    # Current / next checkpoint = nearest useful unpassed waypoint.
    next_cp=None
    if ordered:
        if first:
            next_cp=first[0]
        else:
            candidates=[c for c in ordered if (lock_side=='UP' and c['price']>=live-2) or (lock_side=='DOWN' and c['price']<=live+2)]
            next_cp=(candidates[0] if candidates else ordered[-1])
    cp_text='NEXT CHECKPOINT: --'
    if next_cp:
        cp_text=f"NEXT CHECKPOINT: {next_cp['label']} @ {money(next_cp['price'])} • {abs(next_cp['price']-live):.0f}$ away"

    quest=' → '.join(f"{c['label']} {c['price']-target:+.0f}$" for c in ordered) if ordered else 'route building'
    reversion_text='MEAN REVERSION: building'
    if reversion.get('ready'):
        if reversion.get('side')=='WAIT':
            reversion_text=f"MEAN REVERSION: {reversion.get('state')} • fair {money(fair.get('fair')) if fair.get('ready') else '--'}"
        else:
            eta='no timing trigger'
            if reversion.get('eta_low') is not None:
                eta=f"~{int(reversion['eta_low'])}-{int(reversion['eta_high'])}s"
            reversion_text=(f"MEAN REVERSION {reversion.get('side')} • {reversion.get('state')} • {float(reversion.get('strength',0)):.0f}/100 • {eta} • "
                            f"value zone {money(reversion.get('zone_low'))}-{money(reversion.get('zone_high'))} • expected pull ~${float(reversion.get('distance',0)):.0f}")
    finish_text=(f"PROJECTED SETTLEMENT: {money(proj_low)} → {money(proj_high)} • center {money(center)} "
                 f"({finish_delta:+.0f}$ vs target) • map says {settle_side} • {sec_left/60.0:.1f}m left")
    evidence_text=(f"RAW EVIDENCE: core {core_align:+.2f} • destination {dest_align:+.2f} • tug {tug_align:+.2f} • "
                   f"micro {micro_align:+.2f} • survival {survival:.0f} • flip risk {flip_risk:.0f} • gas {move.get('gas','--')} {viability:.0f}/100")
    headline=f"15M JOURNEY MAPPER: {lock_side} • ROUTE MATCH {route_match:.0f}/100 • {stage}"
    return {'ready':True,'headline':headline,'stage':stage,'lock_side':lock_side,'route_match':route_match,
            'route_text':'EXPECTED QUEST: '+quest,'checkpoint_text':cp_text,'reversion':reversion,
            'reversion_text':reversion_text,'finish_text':finish_text,'evidence_text':evidence_text,
            'live':live,'target':target,'fair':fair,'projected_low':proj_low,'projected_high':proj_high,
            'projected_center':center,'checkpoints':ordered,'move':move,'tug':tug,'micro':micro,
            'core_align':core_align,'dest_align':dest_align,'tug_align':tug_align,'micro_align':micro_align,
            'survival':survival,'flip_risk':flip_risk,'viability':viability,'seconds_left':sec_left}


def _v2673_draw_map(self, state=None):
    c=getattr(self,'v2673_canvas',None)
    if c is None: return
    state=dict(state or getattr(self,'_v2673_last_map',{}) or {})
    if not state.get('ready'): return
    try:
        w=max(220,int(c.winfo_width())); h=max(70,int(c.winfo_height()))
        c.delete('all')
        vals=[]
        for k in ('live','target','projected_low','projected_high','projected_center'):
            v=_v2673_num(state.get(k))
            if v is not None: vals.append(v)
        fair=dict(state.get('fair') or {})
        for k in ('low','high','fair'):
            v=_v2673_num(fair.get(k))
            if v is not None: vals.append(v)
        for cp in state.get('checkpoints') or []:
            v=_v2673_num(cp.get('price'))
            if v is not None: vals.append(v)
        if len(vals)<2: return
        lo=min(vals); hi=max(vals); pad=max(5.0,(hi-lo)*0.12); lo-=pad; hi+=pad
        x0=14; x1=w-14; y=h*0.52
        def xp(p): return x0+(float(p)-lo)/max(hi-lo,1e-9)*(x1-x0)
        c.create_line(x0,y,x1,y,fill=MUTED,width=2)
        # projected settlement distribution
        pl=_v2673_num(state.get('projected_low')); ph=_v2673_num(state.get('projected_high'))
        if pl is not None and ph is not None:
            c.create_rectangle(xp(pl),y-12,xp(ph),y+12,fill='#162a36',outline=CYAN,width=1)
        if fair.get('ready'):
            c.create_rectangle(xp(fair['low']),y-21,xp(fair['high']),y+21,fill='#1f2430',outline=YELLOW,width=1)
            c.create_text(xp(fair['fair']),y+30,text='FAIR',fill=YELLOW,font=('Cascadia Mono',7,'bold'))
        target=_v2673_num(state.get('target')); live=_v2673_num(state.get('live'))
        if target is not None:
            c.create_line(xp(target),y-28,xp(target),y+28,fill=PINK2,width=2)
            c.create_text(xp(target),y-34,text='TARGET',fill=PINK2,font=('Cascadia Mono',7,'bold'))
        if live is not None:
            c.create_oval(xp(live)-5,y-5,xp(live)+5,y+5,fill=GREEN if state.get('lock_side')=='UP' else RED,outline='')
            c.create_text(xp(live),y-17,text='NOW',fill=TEXT,font=('Cascadia Mono',7,'bold'))
        for i,cp in enumerate((state.get('checkpoints') or [])[:5],1):
            p=float(cp['price']); xx=xp(p)
            c.create_line(xx,y-8,xx,y+8,fill=CYAN,width=1)
            c.create_text(xx,y+16,text=str(i),fill=CYAN,font=('Cascadia Mono',7,'bold'))
    except Exception:
        pass


def _v2673_tick(self):
    try:
        _v2673_ensure_vars(self)
        state=_v2673_journey_read(self,now=time.time())
        self._v2673_last_map=dict(state)
        rev_text=state.get('reversion_text')
        if not rev_text:
            rev=dict(state.get('reversion') or {})
            rev_text='MEAN REVERSION: '+str(rev.get('state','building'))
        key=(state.get('headline'),state.get('route_text'),state.get('checkpoint_text'),rev_text,
             state.get('finish_text'),state.get('evidence_text'))
        if key!=getattr(self,'_v2673_last_render_key',None):
            self._v2673_last_render_key=key
            self.v2673_head_var.set(str(state.get('headline','15M JOURNEY MAPPER: building')))
            self.v2673_stage_var.set('QUEST STAGE: '+str(state.get('stage','BUILDING')))
            self.v2673_route_var.set(str(state.get('route_text','EXPECTED QUEST: building')))
            self.v2673_checkpoint_var.set(str(state.get('checkpoint_text','NEXT CHECKPOINT: --')))
            self.v2673_reversion_var.set(str(rev_text))
            self.v2673_finish_var.set(str(state.get('finish_text','PROJECTED SETTLEMENT: --')))
            self.v2673_evidence_var.set(str(state.get('evidence_text','RAW EVIDENCE: building')))
            _v2673_draw_map(self,state)
    except Exception:
        # Instrument failure is isolated from every winner loop.
        pass
    finally:
        try: self.root.after(500,lambda s=self:_v2673_tick(s))
        except Exception: pass


def _v2673_build_ui(self):
    _V2673_BASE_BUILD_UI(self)
    try:
        _v2673_ensure_vars(self)
        parent=getattr(self,'center_content',None)
        if parent is None or getattr(self,'_v2673_card',None) is not None: return
        card=ttk.Frame(parent,style='Card.TFrame',padding=12); self._v2673_card=card
        before=getattr(self,'_v2672_card',None)
        try:
            if before is not None: card.pack(fill='x',pady=(10,0),before=before)
            else: card.pack(fill='x',pady=(10,0))
        except Exception: card.pack(fill='x',pady=(10,0))
        head=ttk.Frame(card,style='Card.TFrame'); head.pack(fill='x',pady=(0,6))
        ttk.Label(head,text='LECHART JAMES // 15M JOURNEY MAPPER',style='Title.Card.TLabel').pack(side='left')
        ttk.Label(head,text='NAVIGATOR ONLY • ZERO OPEN-LOCK AUTHORITY',style='Muted.Card.TLabel').pack(side='right')
        box=tk.Frame(card,bg=PANEL2,padx=10,pady=9,highlightthickness=1,highlightbackground=CYAN)
        box.pack(fill='x')
        tk.Label(box,textvariable=self.v2673_head_var,bg=PANEL2,fg=TEXT,font=('Segoe UI Variable',12,'bold'),anchor='w',justify='left',wraplength=1400).pack(fill='x')
        tk.Label(box,textvariable=self.v2673_stage_var,bg=PANEL2,fg=PINK2,font=('Cascadia Mono',9,'bold'),anchor='w',justify='left',wraplength=1400).pack(fill='x',pady=(3,1))
        self.v2673_canvas=tk.Canvas(box,bg=PANEL2,height=82,highlightthickness=0)
        self.v2673_canvas.pack(fill='x',pady=(4,5)); self.v2673_canvas.bind('<Configure>',lambda e,s=self:_v2673_draw_map(s))
        tk.Label(box,textvariable=self.v2673_route_var,bg=PANEL2,fg=CYAN,font=('Cascadia Mono',8,'bold'),anchor='w',justify='left',wraplength=1450).pack(fill='x',pady=(1,2))
        tk.Label(box,textvariable=self.v2673_checkpoint_var,bg=PANEL2,fg=GREEN,font=('Cascadia Mono',8,'bold'),anchor='w',justify='left',wraplength=1450).pack(fill='x',pady=(1,2))
        tk.Label(box,textvariable=self.v2673_reversion_var,bg=PANEL2,fg=YELLOW,font=('Cascadia Mono',8,'bold'),anchor='w',justify='left',wraplength=1450).pack(fill='x',pady=(1,2))
        tk.Label(box,textvariable=self.v2673_finish_var,bg=PANEL2,fg=TEXT,font=('Cascadia Mono',8,'bold'),anchor='w',justify='left',wraplength=1450).pack(fill='x',pady=(1,2))
        tk.Label(box,textvariable=self.v2673_evidence_var,bg=PANEL2,fg=MUTED,font=('Cascadia Mono',8),anchor='w',justify='left',wraplength=1450).pack(fill='x',pady=(2,1))
        tk.Label(box,textvariable=self.v2673_integrity_var,bg=PANEL2,fg=PINK2,font=('Cascadia Mono',8,'bold'),anchor='w',justify='left').pack(fill='x',pady=(5,0))
    except Exception:
        pass


def _v2673_init(self,*args,**kwargs):
    self._v2673_card=None; self._v2673_context_cache={}; self._v2673_last_render_key=None; self._v2673_last_map={}
    _V2673_BASE_INIT(self,*args,**kwargs)
    try:
        _v2673_ensure_vars(self)
        self.root.after(450,lambda s=self:_v2673_tick(s))
        self.root.title('BOOKMAP KING V21.67.3 — GOLD MASTER + 15M JOURNEY MAPPER')
    except Exception: pass


