BK_MULTI_TARGET = {a: None for a in _V2674_ASSETS}
BK_MULTI_STATUS = {a: {'asset': a, 'lock': 'WAIT', 'price': None, 'ts': 0.0} for a in _V2674_ASSETS}
BK_MULTI_UI_READY = {a: threading.Event() for a in _V2674_ASSETS}
