def _v2674_asset_floor(self, btc_floor):
    """Convert a BTC-dollar floor into same-order percentage floor for SOL/DOGE."""
    asset=str(getattr(self,'asset_symbol','BTC')).upper()
    if asset=='BTC': return float(btc_floor)
    try:
        px=abs(float(getattr(self,'current_spot',0.0) or 0.0))
    except Exception:
        px=0.0
    # BTC Gold Master was tuned around roughly six-figure BTC. Scale floors as
    # a percentage of the current asset, not as literal dollars.
    return max(px*(float(btc_floor)/100000.0), 1e-9)


def _v2674_movement_stats(self, now=None):
    asset=str(getattr(self,'asset_symbol','BTC')).upper()
    if asset=='BTC': return _V2674_BASE_MOVE_STATS(self,now)
    now=float(now or time.time()); rows=_v2672_micro_snapshot(self,now)
    if len(rows)<6: return {'ready':False,'rows':len(rows)}
    closed=[r for r in rows if float(r.get('time',0) or 0)+5.0<=now]
    if len(closed)<5: return {'ready':False,'rows':len(closed)}
    closed=closed[-72:]
    ranges=[max(0.0,float(r.get('high',0))-float(r.get('low',0))) for r in closed]
    steps=[abs(float(b.get('close',0))-float(a.get('close',0))) for a,b in zip(closed[:-1],closed[1:])]
    med_range=_v2672_median(ranges[-36:],0.0); med_step=_v2672_median(steps[-36:],med_range*0.5)
    quantum=max(_v2674_asset_floor(self,0.05), med_step+0.35*med_range)
    recent=closed[-6:]; baseline=closed[-60:]
    recent_vol=_v2672_median([r.get('volume',0.0) for r in recent],0.0); base_vol=_v2672_median([r.get('volume',0.0) for r in baseline],recent_vol or 1.0)
    vol_ratio=recent_vol/max(base_vol,1e-12)
    recent_trades=_v2672_median([r.get('_trade_count',0) for r in recent],0.0); base_trades=_v2672_median([r.get('_trade_count',0) for r in baseline],recent_trades or 1.0)
    trade_ratio=recent_trades/max(base_trades,1e-12); activity=_v2672_clip(0.55*vol_ratio+0.45*trade_ratio,0.25,2.25)
    span=min(7,len(closed)); first=closed[-span]; last=closed[-1]; dt=max(5.0,float(last.get('time',0))-float(first.get('time',0)))
    net=float(last.get('close',0))-float(first.get('close',0)); velocity=net/dt
    recent_range=max(float(r.get('high',0)) for r in closed[-36:])-min(float(r.get('low',0)) for r in closed[-36:])
    return {'ready':True,'rows':len(closed),'quantum_5s':quantum,'med_range_5s':med_range,'med_step_5s':med_step,
            'activity':activity,'vol_ratio':vol_ratio,'trade_ratio':trade_ratio,'velocity_30s':velocity,'recent_range':max(0.0,recent_range)}


def _v2674_move_budget_read(self, now=None):
    asset=str(getattr(self,'asset_symbol','BTC')).upper()
    if asset=='BTC': return _V2674_BASE_MOVE_BUDGET(self,now)
    now=float(now or time.time()); live,target,source=_v2672_target_and_live(self); stats=_v2674_movement_stats(self,now)
    sec_left=max(0.0,900.0-(now%900.0)); lock=dict(getattr(self,'opening_lock_snapshot',None) or {}); side=str(lock.get('lock_side','WAIT')).upper()
    if live is None or target is None or not stats.get('ready'):
        return {'ready':False,'side':side,'seconds_left':sec_left,'live':live,'target':target,'stats':stats,'headline':f'{asset} MOVE BUDGET: building raw 5s movement','detail':'Need target + native Bookmap micro candles.'}
    delta=live-target; needed=max(0.0,target-live) if side=='UP' else max(0.0,live-target) if side=='DOWN' else abs(delta)
    steps_left=max(1.0,sec_left/5.0); activity=float(stats.get('activity',1.0) or 1.0); quantum=float(stats.get('quantum_5s',0.0) or 0.0)
    stochastic=quantum*math.sqrt(steps_left)*(1.45+0.22*math.sqrt(activity)); drift=abs(float(stats.get('velocity_30s',0.0) or 0.0))*min(sec_left,90.0)*0.28; drift=min(drift,stochastic*0.85)
    budget=max(_v2674_asset_floor(self,0.05),stochastic+drift)
    if needed<=_v2674_asset_floor(self,0.01): viability=93.0; relation='TARGET CURRENTLY CLEARED'
    else:
        ratio=budget/max(needed,1e-12); viability=100.0/(1.0+math.exp(-3.0*(ratio-0.92))); viability*=_v2672_clip(0.72+0.25*activity,0.58,1.08); viability=_v2672_clip(viability,2.0,98.0); relation=f'needs {_v2674_price_fmt(needed)} to target'
    gas='DEAD' if activity<0.48 else 'LOW' if activity<0.78 else 'NORMAL' if activity<1.28 else 'HIGH' if activity<1.75 else 'VERY HIGH'
    status='PATH HAS ENOUGH GAS' if viability>=78 else 'PATH REACHABLE • CLOCK MATTERS' if viability>=55 else 'THESIS MAY BE RIGHT • MOVE BUDGET TIGHT' if viability>=34 else 'THESIS MAY BE RIGHT • ROUND MAY EXPIRE FIRST'
    return {'ready':True,'side':side,'seconds_left':sec_left,'live':live,'target':target,'delta':delta,'needed':needed,'budget':budget,'signed_budget':budget if side!='DOWN' else -budget,'viability':viability,'activity':activity,'gas':gas,'status':status,'relation':relation,'stats':stats,'source':source,'headline':f'{asset} SETTLEMENT VIABILITY {viability:.0f}/100 • {status}','detail':f'{side} lock • {sec_left/60.0:.1f}m left • {relation} • est. remaining move budget {_v2674_price_fmt(budget)} • gas {gas} ({activity:.2f}x local activity)'}


def _v2674_tug_read(self, now=None):
    asset=str(getattr(self,'asset_symbol','BTC')).upper()
    if asset=='BTC': return _V2674_BASE_TUG(self,now)
    now=float(now or time.time()); live,target,source=_v2672_target_and_live(self); stats=_v2674_movement_stats(self,now); flow=_v2672_round_flow(self,now)
    price_ready=live is not None and target is not None; price_score=0.0
