            app.running=True; app.status_var.set(f'{asset} KING READY • waiting for {asset} Bookmap instrument')
            app.auto_market_status_var.set(f'{asset} DATA SOURCE: waiting for Bookmap')
            app.odds_feed_status_var.set(f'{asset} KALSHI LAYER: optional/manual • Bookmap brain independent')
