# ============================================================================
# BOOKMAP KING V21.67.5 — TRI-KING AUTO KALSHI TARGETS
# BTC / SOL / DOGE exact 15-minute Kalshi target discovery per round.
#
# SAFETY / PARITY CONTRACT
#   * BTC Gold Master decision, reversal, survival and Open-Lock code is untouched.
#   * SOL uses Kalshi series KXSOL15M; DOGE uses KXDOGE15M.
#   * Each non-BTC child discovers its OWN live Kalshi market and target.
#   * The existing Bookmap round-open target remains only a temporary fallback
#     until the official Kalshi target arrives.
#   * Existing Kalshi BBO worker can now follow the correct SOL/DOGE ticker too,
#     which also gives Tug of War the correct asset's executable odds.
#   * Paper auto remains OFF for SOL/DOGE in this build.
# ============================================================================

_V2675_RELEASE = 'V21.67.5'
_V2675_SERIES = {'BTC': 'KXBTC15M', 'SOL': 'KXSOL15M', 'DOGE': 'KXDOGE15M'}
_V2675_BASE_DISCOVER = ChartKingPro._discover_current_kalshi_market
_V2675_BASE_EXTRACT_TARGET = ChartKingPro._extract_target
_V2675_BASE_APPLY_MARKET = ChartKingPro._apply_kalshi_market
_V2675_BASE_FIND_MARKET = ChartKingPro.find_current_kalshi_market_now
_V2675_BASE_INIT = ChartKingPro.__init__


def _v2675_asset(self):
    a = str(getattr(self, 'asset_symbol', _V2674_CHILD_ASSET) or 'BTC').upper()
    return a if a in _V2674_ASSETS else 'BTC'


def _v2675_target_ok(asset, value):
    try:
        x = float(value)
    except Exception:
        return False
    if not math.isfinite(x) or x <= 0:
        return False
    asset = str(asset).upper()
    if asset == 'BTC':
        return x > 1000
    if asset == 'SOL':
        return 0.10 < x < 100000.0
    if asset == 'DOGE':
        return 0.000001 < x < 100.0
    return x > 0


def _v2675_float(raw):
    try:
        if raw is None or isinstance(raw, bool):
            return None
        s = str(raw).strip().replace('$', '').replace(',', '')
        if not s:
            return None
        return float(s)
    except Exception:
        return None


def _v2675_extract_target(self, market):
    """Asset-aware extraction of the official 15-minute Kalshi reference price."""
    asset = _v2675_asset(self)
    if asset == 'BTC':
        return _V2675_BASE_EXTRACT_TARGET(self, market)
    if not market:
        return None

    # Prefer explicit numeric strike/reference fields.  The 15m contracts use a
    # published reference/strike price; unlike the old BTC-only extractor we do
    # NOT impose a >$1000 floor, because SOL and DOGE are lower nominal prices.
    strike_type = str(market.get('strike_type') or '').lower()
    if strike_type in ('greater', 'greater_than', 'above'):
        strike_keys = ('floor_strike', 'functional_strike', 'cap_strike')
    elif strike_type in ('less', 'less_than', 'below'):
        strike_keys = ('cap_strike', 'functional_strike', 'floor_strike')
    else:
        strike_keys = ('floor_strike', 'functional_strike', 'cap_strike')

    explicit_keys = strike_keys + (
        'target_price', 'reference_price', 'price_to_beat', 'reference_value',
        'strike', 'strike_price', 'threshold', 'value',
    )
    seen = set()
    for key in explicit_keys:
        if key in seen:
            continue
        seen.add(key)
        x = _v2675_float(market.get(key))
        if x is not None and _v2675_target_ok(asset, x):
            return float(x)

    # Text fallback is deliberately context-bound: only numbers adjacent to
    # words such as target/reference/price-to-beat are accepted.  This avoids
    # accidentally grabbing odds, volume, dates, or the '15' in '15 min'.
    text = ' '.join(str(market.get(k, '') or '') for k in (
        'title', 'subtitle', 'yes_sub_title', 'no_sub_title',
        'rules_primary', 'rules_secondary', 'description'
    ))
    patterns = (
        r'(?:target(?:\s+price)?|price\s+to\s+beat|reference(?:\s+price)?)\s*[:=·\-]?\s*\$?\s*([0-9][0-9,]*(?:\.[0-9]+)?)',
        r'\$?\s*([0-9][0-9,]*(?:\.[0-9]+)?)\s*(?:target|price\s+to\s+beat|reference(?:\s+price)?)',
    )
    for pat in patterns:
        for m in re.finditer(pat, text, flags=re.I):
            x = _v2675_float(m.group(1))
            if x is not None and _v2675_target_ok(asset, x):
                return float(x)
    return None


def _v2675_discover_current_kalshi_market(self):
    """Discover the current asset's own 15m Kalshi market."""
    asset = _v2675_asset(self)
    if asset == 'BTC':
        return _V2675_BASE_DISCOVER(self)
    series = _V2675_SERIES[asset]
    data = self.kalshi_get('/markets', {'series_ticker': series, 'status': 'open', 'limit': 100})
    markets = data.get('markets') or []
    if not markets:
        raise RuntimeError(f'Kalshi returned no open {series} markets')
    now = time.time()
    active, future = [], []
    for market in markets:
        open_ts = self._parse_iso_ts(market.get('open_time'))
        close_ts = self._parse_iso_ts(
            market.get('close_time') or market.get('expected_expiration_time') or market.get('expiration_time')
        )
        if close_ts is not None and close_ts > now:
            future.append((close_ts, market))
        if open_ts is not None and close_ts is not None and open_ts <= now < close_ts:
            active.append((close_ts, market))
    if active:
        active.sort(key=lambda item: item[0])
        return active[0][1]
    if future:
        future.sort(key=lambda item: item[0])
        return future[0][1]
    return markets[0]


def _v2675_apply_kalshi_market(self, market, source='AUTO'):
    asset = _v2675_asset(self)
    if asset == 'BTC':
        return _V2675_BASE_APPLY_MARKET(self, market, source)
    ok = _V2675_BASE_APPLY_MARKET(self, market, source)
    if not ok:
        return ok
    series = _V2675_SERIES[asset]
    target = _v2675_extract_target(self, market)
    ticker = str((market or {}).get('ticker') or '').strip().upper()
    if target is not None:
        self.target_price = float(target)
        self._v2674_target_source = f'KALSHI {series} • {source}'
        try:
            self.auto_target_status_var.set(
                f'AUTO {asset} TARGET: {_v2674_price_fmt(target)} • {series} • {source}'
            )
        except Exception:
            pass
    else:
        # Do not erase the first-trade fallback while Kalshi is briefly between
        # markets/TBD at rollover.  It is replaced immediately when target lands.
        try:
            self.auto_target_status_var.set(
                f'AUTO {asset} TARGET: waiting for published target • {ticker or series}'
            )
        except Exception:
            pass
    try:
        self.auto_market_status_var.set(f'AUTO {asset}15M: {ticker or series} • {source}')
    except Exception:
        pass
    return ok


def _v2675_find_current_kalshi_market_now(self):
    asset = _v2675_asset(self)
    if asset == 'BTC':
        return _V2675_BASE_FIND_MARKET(self)
    series = _V2675_SERIES[asset]
    try:
        self.auto_market_status_var.set(f'AUTO {asset}15M: searching {series}...')
        self.auto_target_status_var.set(f'AUTO {asset} TARGET: searching...')
    except Exception:
        pass

    def worker():
        try:
            market = self._refresh_auto_kalshi_market()
            ticker = str((market or {}).get('ticker') or series)
            target = self.target_price
            msg = f'{asset} {ticker} • target {_v2674_price_fmt(target)}' if target is not None else f'{asset} {ticker} • target pending'
            try:
                self.root.after(0, lambda m=msg: self.status_var.set(m))
            except Exception:
                pass
        except Exception as exc:
            self.auto_market_error = str(exc)
            try:
                self.root.after(0, lambda e=str(exc): self.auto_market_status_var.set(f'AUTO {asset}15M ERROR: {e}'))
            except Exception:
                pass
    threading.Thread(target=worker, name=f'LeChartJames-{asset}-FindKalshi15M', daemon=True).start()


def _v2675_arm_asset_kalshi(self):
    """Turn on the same continuous market/target rollover loop BTC already uses."""
    asset = _v2675_asset(self)
    if asset not in ('SOL', 'DOGE'):
        return
    series = _V2675_SERIES[asset]
    try:
        self.auto_market_enabled_var.set(True)
        self.auto_market_status_var.set(f'AUTO {asset}15M: armed • {series}')
        self.auto_target_status_var.set(f'AUTO {asset} TARGET: waiting for Kalshi {series}')
        self.odds_feed_status_var.set(f'{asset} KALSHI BBO: connecting • {series}')
        # Keep simulation/live execution disabled; this upgrade is market data +
        # target/BBO discovery only for the new assets.
        self.auto_paper_enabled_var.set(False)
        self.paper_status_var.set(f'PAPER AUTO: OFF for {asset} • market data/target auto-detect ON')
        self.root.title(f'LECHART JAMES V21.67.5 — {asset} KING • AUTO TARGET')
    except Exception:
        pass
    try:
        self._start_kalshi_live_odds_worker()
    except Exception:
        pass
    try:
        self.find_current_kalshi_market_now()
    except Exception:
        pass


def _v2675_init(self, *args, **kwargs):
    _V2675_BASE_INIT(self, *args, **kwargs)
    # _V2674_CHILD_ASSET is selected from argv before each child constructs the
    # app, so it is safe to assign here.  The V21.67.4 runner will assign it again.
    try:
        self.asset_symbol = str(_V2674_CHILD_ASSET or 'BTC').upper()
        self.asset_name = _v2674_asset_name(self.asset_symbol)
    except Exception:
        pass
    if str(getattr(self, 'asset_symbol', 'BTC')).upper() in ('SOL', 'DOGE'):
        try:
            self.root.after(700, lambda s=self: _v2675_arm_asset_kalshi(s))
        except Exception:
            pass


ChartKingPro._extract_target = _v2675_extract_target
ChartKingPro._discover_current_kalshi_market = _v2675_discover_current_kalshi_market
ChartKingPro._apply_kalshi_market = _v2675_apply_kalshi_market
ChartKingPro.find_current_kalshi_market_now = _v2675_find_current_kalshi_market_now
ChartKingPro.__init__ = _v2675_init

# END V21.67.5 TRI-KING AUTO KALSHI TARGETS

