_V2676_PANEL = '#0b141e'
_V2676_PANEL2 = '#0d1823'
_V2676_BORDER = '#26394b'
_V2676_BORDER2 = '#314c62'
_V2676_TEXT = '#e7edf5'
_V2676_MUTED = '#8492a2'
_V2676_GREEN = '#2ce5a0'
_V2676_GREEN_DARK = '#113b31'
_V2676_RED = '#ff6f83'
_V2676_RED_DARK = '#41212a'
_V2676_BLUE = '#57a7ff'
