def _v2676_toggle_legacy(app):
    try:
        shell = getattr(app, 'v2676_shell', None)
        if shell is None: return
        showing = bool(getattr(app, '_v2676_showing', True))
        if showing:
            shell.place_forget()
            app._v2676_showing = False
            btn = getattr(app, 'v2676_return_button', None)
            if btn is not None:
                btn.place(relx=0.995, y=7, anchor='ne'); btn.lift()
        else:
            shell.place(x=0, y=0, relwidth=1, relheight=1)
            shell.lift(); app._v2676_showing = True
            btn = getattr(app, 'v2676_return_button', None)
            if btn is not None: btn.place_forget()
            try: app.draw_chart()
            except Exception: pass
    except Exception:
        pass


def _v2676_relabel_chart_after_draw(app):
    try:
        c = getattr(app, 'canvas', None)
        if c is None: return
        asset = str(getattr(app, 'asset_symbol', 'BTC')).upper()
        if asset == 'BTC': return
        for item in c.find_all():
            try:
                if c.type(item) != 'text': continue
                text = c.itemcget(item, 'text')
                if 'BTC/USD' in text:
                    c.itemconfigure(item, text=text.replace('BTC/USD', f'{asset}/USD'))
                elif 'LIVE BTC' in text:
                    c.itemconfigure(item, text=text.replace('LIVE BTC', f'LIVE {asset}'))
            except Exception:
                pass
    except Exception:
        pass


def _v2676_draw_chart_proxy(self):
    result = _V2676_BASE_DRAW_CHART(self)
    _v2676_relabel_chart_after_draw(self)
    return result


ChartKingPro.draw_chart = _v2676_draw_chart_proxy


def _v2676_update_market_cards(app, statuses=None, selected=None):
    try:
        statuses = dict(statuses or getattr(app, '_v2676_multi_status', {}) or {})
        selected = str(selected or getattr(app, 'asset_symbol', 'BTC')).upper()
        app._v2676_multi_status = statuses
        bullish = bearish = ready = 0
        for asset in _V2674_ASSETS:
            st = dict(statuses.get(asset) or {})
            card = getattr(app, 'v2676_market_cards', {}).get(asset)
            if not card: continue
            lock = str(st.get('lock','WAIT')).upper()
            px = st.get('price')
            route = st.get('route_match')
            age = time.time() - float(st.get('ts',0.0) or 0.0)
            offline = age > 3.5
            if asset == selected:
                try:
                    lock = str((getattr(app,'opening_lock_snapshot',None) or {}).get('lock_side',lock)).upper()
                    px = getattr(app,'current_spot',px)
                    route = (getattr(app,'_v2673_last_map',{}) or {}).get('route_match',route)
                except Exception: pass
            if lock == 'UP': bullish += 1; ready += 1
            elif lock == 'DOWN': bearish += 1; ready += 1
            card['price'].set(_v2676_money(asset, px) if px is not None else '--')
            card['lock'].set(('OFFLINE' if offline else f'LOCK: {lock}'))
            card['score'].set(f'{float(route):.0f}%' if route is not None else '--')
            active = asset == selected
            frame = card['frame']
            frame.configure(highlightbackground=_V2676_BLUE if active else _V2676_BORDER,
                            bg=_V2676_PANEL)
            col = _V2676_GREEN if lock == 'UP' else _V2676_RED if lock == 'DOWN' else _V2676_MUTED
            # lock label is second label under left/top; safest recolor by walking textvariable match is not needed.
            for ch in frame.winfo_children():
                try:
                    for sub in ch.winfo_children():
                        try:
                            if str(sub.cget('textvariable')) == str(card['lock']): sub.configure(fg=col)
                        except Exception: pass
                except Exception: pass
        if hasattr(app,'v2676_tri_status_var'):
            if ready:
                side = 'BULLISH' if bullish > bearish else 'BEARISH' if bearish > bullish else 'MIXED'
                app.v2676_tri_status_var.set(f'{bullish}/{max(ready,1)} BULLISH • {side}')
            else:
                app.v2676_tri_status_var.set('3 INDEPENDENT MINDS • BUILDING')
    except Exception:
        pass


def _v2676_update_switcher(app, statuses, selected):
    _V2676_BASE_UPDATE_SWITCHER(app, statuses, selected)
    try:
        _v2676_update_market_cards(app, statuses, selected)
    except Exception:
        pass


_v2674_update_switcher = _v2676_update_switcher


def _v2676_draw_journey(app):
    c = getattr(app, 'v2676_journey_canvas', None)
    if c is None: return
    try:
        c.delete('all')
        w=max(280,c.winfo_width()); h=max(58,c.winfo_height())
        state=dict(getattr(app,'_v2673_last_map',{}) or {})
        labels=('Adverse\ndip','Absorption\nzone','Reclaim\ntarget','Resistance\ntest','Projected\nfinish')
        stage=str(state.get('stage','')).upper()
        idx=1
        if 'ABSORP' in stage: idx=2
        elif 'RECLAIM' in stage or 'REVERSION' in stage: idx=3
        elif 'EXTENSION' in stage or 'RETEST' in stage or 'RESIST' in stage: idx=4
        elif 'FINISH' in stage or 'SETTLE' in stage: idx=5
        margin=28; y=22
        xs=[margin+i*(w-2*margin)/4 for i in range(5)]
        c.create_line(xs[0],y,xs[-1],y,fill='#294053',width=3)
        for i,(x,label) in enumerate(zip(xs,labels),1):
            done=i<idx; active=i==idx
            fill=_V2676_GREEN if done else _V2676_BLUE if active else '#263543'
            c.create_oval(x-11,y-11,x+11,y+11,fill=fill,outline='')
            c.create_text(x,y,text=str(i),fill=_V2676_VOID if done or active else _V2676_MUTED,font=('Cascadia Mono',8,'bold'))
            c.create_text(x,y+28,text=label,fill=_V2676_TEXT if active else _V2676_MUTED,font=('Cascadia Mono',7,'bold'),justify='center')
    except Exception:
        pass


def _v2676_tick(app):
    try:
        app._v274_ui_tick_count=int(getattr(app,'_v274_ui_tick_count',0) or 0)+1
        if not getattr(app, '_v2676_showing', True):
            app.root.after(100, lambda a=app: _v2676_tick(a)); return
        asset=str(getattr(app,'asset_symbol','BTC')).upper()
        lock=dict(getattr(app,'opening_lock_snapshot',None) or {})
        side=str(lock.get('lock_side','WAIT')).upper()
        surv=max(0.0,min(100.0,_v2676_num(getattr(app,'flip_survival_value',50.0),50.0)))
        risk=max(0.0,min(100.0,_v2676_num(getattr(app,'trend_reversal_risk_value',0.0),0.0)))
        journey=dict(getattr(app,'_v2673_last_map',{}) or {})
        tug_up=max(0.0,min(100.0,_v2676_num(getattr(app,'v2672_tug_value',50.0),50.0)))
        tug_side='BUYERS' if tug_up>52 else 'SELLERS' if tug_up<48 else 'DEAD EVEN'
        tug_show=tug_up if tug_side!='SELLERS' else 100.0-tug_up
        move=dict(journey.get('move') or {})
        viability=max(0.0,min(100.0,_v2676_num(journey.get('viability', move.get('viability',0.0)),0.0)))
        reversion=dict(journey.get('reversion') or {})
        rev_state=str(reversion.get('state','BUILDING')).upper()
        rev_side=str(reversion.get('side','WAIT')).upper()
        rev_strength=max(0.0,min(100.0,_v2676_num(reversion.get('strength',0.0),0.0)))
        live=getattr(app,'current_spot',None)
        try: target,_target_source=app.effective_target()
        except Exception: target,_target_source=getattr(app,'target_price',None),'--'
        delta=(float(live)-float(target)) if live is not None and target is not None else None
        route_match=_v2676_num(journey.get('route_match',0.0),0.0)

        # Header / selected market.
        app.v2676_active_asset_var.set(asset)
        app.v2676_active_price_var.set(_v2676_money(asset,live))
        app.v2676_active_delta_var.set((f'{delta:+,.2f} vs target' if delta is not None else 'waiting for target'))
        app.v2676_open_var.set(side)
        app.v2676_open_meta_var.set(f'Gold Master lock • route {route_match:.0f}/100')
        app.v2676_flip_var.set(f'{risk:.0f}%')
        app.v2676_flip_meta_var.set('NO FLIP SIGNAL' if risk<12 else 'THESIS PRESSURE' if risk<45 else 'FLIP / BREAKOUT RISK')
        app.v2676_survival_var.set(f'{surv:.0f}%')
        app.v2676_survival_meta_var.set('still valid' if surv>=70 else 'under pressure' if surv>=45 else 'thesis endangered')
        app.v2676_tug_var.set(f'{tug_side} {tug_show:.0f}%')
        app.v2676_tug_meta_var.set(_v2676_txt(getattr(app,'v2672_tug_detail_var','raw Bookmap evidence')))
        app.v2676_move_var.set(f'{viability:.0f} / 100')
        app.v2676_move_meta_var.set(f"{move.get('gas','BUILDING')} • {_v2676_txt(getattr(app,'v2672_move_clock_var',''))}")
        if rev_side in ('UP','DOWN'):
            app.v2676_reversion_var.set(f'{rev_side} • {rev_state}')
        else:
            app.v2676_reversion_var.set(rev_state)
        app.v2676_reversion_meta_var.set(f'{rev_strength:.0f}/100 strength • {_v2676_txt(journey.get("checkpoint_text","fair-value map building"))}')
        center=journey.get('projected_center'); lo=journey.get('projected_low'); hi=journey.get('projected_high')
        if center is not None and target is not None:
            app.v2676_settle_var.set(f'{float(center)-float(target):+,.2f} vs target')
            app.v2676_settle_meta_var.set(f'center {_v2676_money(asset,center)} • range {_v2676_money(asset,lo)}–{_v2676_money(asset,hi)}')
        else:
            app.v2676_settle_var.set('BUILDING')
            app.v2676_settle_meta_var.set(_v2676_txt(journey.get('finish_text','waiting for route')))
        whale=dict(getattr(app,'bookmap_whale_last',{}) or {})
        absorption=str(whale.get('absorption','NONE')).replace('_',' ')
        wdir=str(whale.get('direction','NEUTRAL')).upper(); wscore=_v2676_num(whale.get('likelihood',0.0),0.0)
        app.v2676_whale_var.set(absorption if absorption not in ('','NONE') else f'{wdir} {wscore:.0f}/100')
        app.v2676_whale_meta_var.set(_v2676_txt(whale.get('detail',getattr(app,'whale_detail_var','building'))))
        app.v2676_target_var.set(_v2676_money(asset,target))
        app.v2676_target_meta_var.set(_v2676_txt(getattr(app,'auto_target_status_var',_target_source)))

        # Bottom intelligence row.
        app.v2676_whale_pressure_var.set(f'{wdir} {wscore:.0f}/100')
        app.v2676_whale_pressure_meta.set(absorption if absorption not in ('','NONE') else _v2676_txt(getattr(app,'whale_flow_var','building')))
        flow=dict((journey.get('tug') or {}).get('flow') or {})
        buy_ratio=max(0.0,min(1.0,_v2676_num(flow.get('buy_ratio',0.5),0.5)))
        app.v2676_flow_var.set(f'{buy_ratio*100:.0f}% BUY • {(1-buy_ratio)*100:.0f}% SELL')
        app.v2676_flow_meta.set(f"{int(flow.get('count',0) or 0):,} executed prints this round")
        sig=dict(getattr(app,'last_signal',{}) or {})
        support=sig.get('support'); resistance=sig.get('resistance')
        app.v2676_sr_var.set(f'R {_v2676_money(asset,resistance)}   •   S {_v2676_money(asset,support)}')
        app.v2676_sr_meta.set(_v2676_txt(getattr(app,'sr_quality_var','structure developing')))
        pat=sig.get('pattern') or {}
        pname=str(pat.get('name') or _v2676_txt(getattr(app,'pattern_var','PATTERN BUILDING')))
        pstage=str(pat.get('stage') or _v2676_txt(getattr(app,'pattern_state_var','')))
        app.v2676_pattern_var.set(pname[:56])
        app.v2676_pattern_meta.set(pstage[:96])
        app.v2676_journey_head.set(f'Path {"intact" if surv>=65 and risk<35 else "under pressure"} • Route match {route_match:.0f}/100')
        app.v2676_journey_route.set(_v2676_txt(journey.get('route_text','EXPECTED QUEST: building')))
        app.v2676_journey_next.set(_v2676_txt(journey.get('checkpoint_text','NEXT CHECKPOINT: --')))
        _v2676_draw_journey(app)
        _v2676_draw_meter(app.v2676_flip_canvas,risk,blocks=True)
        _v2676_draw_meter(app.v2676_survival_canvas,surv)
        _v2676_draw_meter(app.v2676_tug_canvas,tug_up)
        _v2676_draw_meter(app.v2676_move_canvas,viability)
        _v2676_update_market_cards(app)
        statuses=dict(getattr(app,'_v2676_multi_status',{}) or {})
        for aa in _V2674_ASSETS:
            st=dict(statuses.get(aa) or {})
            if aa==asset:
                st={'lock':side,'price':live,'route_match':route_match,'ts':time.time()}
            lk=str(st.get('lock','WAIT')).upper(); rm=st.get('route_match'); px=st.get('price')
            suffix=(f' • {float(rm):.0f}%' if rm is not None else '')
            app.v2676_all_lines[aa].set(f'{aa}  {lk}  {_v2676_money(aa,px) if px is not None else "--"}{suffix}')
        # V21.74: do NOT full-redraw the chart from the cockpit refresh loop.
        # The live candle renderer and adaptive structure renderer own painting;
        # this prevents duplicate 30 Hz full redraws and keeps the UI responsive.
    except Exception:
        pass
    finally:
        try: app.root.after(33, lambda a=app: _v2676_tick(a))
        except Exception: pass


def _v2676_mount_cockpit(app, root, asset):
    if getattr(app,'v2676_shell',None) is not None:
        return
    try:
        asset=str(asset or getattr(app,'asset_symbol','BTC')).upper()
        sw=max(1200, root.winfo_screenwidth()); sh=max(760, root.winfo_screenheight())
        ww=min(1880, max(1280, sw-40)); wh=min(980, max(760, sh-80))
        root.geometry(f'{ww}x{wh}')
        root.minsize(1180, 720)
        root.configure(bg=_V2676_BG)
    except Exception:
        pass

    app._v2676_showing=True
    app._v2676_multi_status={}
    app.v2676_market_cards={}
    shell=tk.Frame(root,bg=_V2676_BG); app.v2676_shell=shell
    shell.place(x=0,y=0,relwidth=1,relheight=1); shell.lift()
    shell.grid_columnconfigure(0,weight=1)
    shell.grid_rowconfigure(2,weight=1)

    # Header -----------------------------------------------------------------
    header=tk.Frame(shell,bg=_V2676_BG,padx=16,pady=7); header.grid(row=0,column=0,sticky='ew')
    left=tk.Frame(header,bg=_V2676_BG); left.pack(side='left')
