    tk.Label(title,text='  👑  TRI-KING',bg=_V2676_BG,fg=_V2676_GOLD,font=('Cascadia Mono',11,'bold')).pack(side='left',padx=(5,0))
    tk.Label(left,text='THREE MARKETS • THREE INDEPENDENT MINDS • ONE COCKPIT',bg=_V2676_BG,fg=_V2676_MUTED,
             font=('Cascadia Mono',7,'bold')).pack(anchor='w',pady=(0,1))
    right=tk.Frame(header,bg=_V2676_BG); right.pack(side='right')
