    tk.Label(right,text='● LIVE',bg=_V2676_GREEN_DARK,fg=_V2676_GREEN,font=('Cascadia Mono',8,'bold'),padx=9,pady=5).pack(side='left',padx=3)
    tk.Button(right,text='⚙',command=lambda:_v2676_open_status_popup(app),bg=_V2676_PANEL,fg=_V2676_MUTED,
              activebackground=_V2676_PANEL2,activeforeground=_V2676_TEXT,relief='flat',font=('Segoe UI Symbol',13),padx=10,pady=2).pack(side='left',padx=3)
    tk.Button(right,text='☰',command=lambda:_v2676_open_advanced_popup(app),bg=_V2676_PANEL,fg=_V2676_TEXT,
              activebackground=_V2676_PANEL2,activeforeground=_V2676_TEXT,relief='flat',font=('Segoe UI Symbol',13),padx=10,pady=2).pack(side='left',padx=3)
    tk.Button(right,text='LEGACY',command=lambda:_v2676_toggle_legacy(app),bg=_V2676_PANEL,fg=_V2676_MUTED,
              activebackground=_V2676_PANEL2,activeforeground=_V2676_TEXT,relief='flat',font=('Cascadia Mono',7,'bold'),padx=9,pady=6).pack(side='left',padx=(6,0))

    # Market strip -----------------------------------------------------------
    markets=tk.Frame(shell,bg=_V2676_BG,padx=16,pady=2); markets.grid(row=1,column=0,sticky='ew')
    for i in range(4): markets.grid_columnconfigure(i,weight=1)
    for i,a in enumerate(_V2674_ASSETS):
        _v2676_asset_card(markets,app,a).grid(row=0,column=i,sticky='nsew',padx=(0 if i==0 else 5,5))
    tri=tk.Frame(markets,bg=_V2676_PANEL,highlightthickness=1,highlightbackground=_V2676_BORDER,padx=12,pady=8)
