    app.v2676_move_var=tk.StringVar(value='--'); app.v2676_move_meta_var=tk.StringVar(value='building')
    _v2676_value_label(move_card,app.v2676_move_var,_V2676_TEXT,13); app.v2676_move_canvas=tk.Canvas(move_card,bg=_V2676_PANEL,height=16,highlightthickness=0); app.v2676_move_canvas.pack(fill='x',pady=(5,1)); _v2676_mini_label(move_card,app.v2676_move_meta_var,wrap=260)

    rev_card=_v2676_card(side,'〰 MEAN REVERSION',_V2676_BORDER); rev_card.grid(row=3,column=0,sticky='nsew',padx=(0,4),pady=(5,0))
    app.v2676_reversion_var=tk.StringVar(value='BUILDING'); app.v2676_reversion_meta_var=tk.StringVar(value='fair-value map')
    _v2676_value_label(rev_card,app.v2676_reversion_var,_V2676_CYAN,11); _v2676_mini_label(rev_card,app.v2676_reversion_meta_var,wrap=260)

    settle=_v2676_card(side,'◎ PROJECTED SETTLEMENT',_V2676_BORDER); settle.grid(row=3,column=1,sticky='nsew',padx=(4,0),pady=5)
    app.v2676_settle_var=tk.StringVar(value='BUILDING'); app.v2676_settle_meta_var=tk.StringVar(value='journey mapper')
    _v2676_value_label(settle,app.v2676_settle_var,_V2676_GREEN,11); _v2676_mini_label(settle,app.v2676_settle_meta_var,wrap=260)

    whale_side=_v2676_card(side,'🐋 WHALE / ABSORPTION',_V2676_BORDER); whale_side.grid(row=4,column=0,sticky='nsew',padx=(0,4),pady=(5,0))
    app.v2676_whale_var=tk.StringVar(value='BUILDING'); app.v2676_whale_meta_var=tk.StringVar(value='native Bookmap')
