    _v2676_value_label(target_side,app.v2676_target_var,_V2676_GREEN,11); _v2676_mini_label(target_side,app.v2676_target_meta_var,wrap=260)

    # V21.74 cockpit handles + hard compact presentation.  This is the ACTUAL
