# ============================================================================
# BOOKMAP KING V21.67.7 — TRI-KING NATIVE FEED / TARGET / LEGACY CHART FIX
# SOL + DOGE STARTUP HISTORY PARITY • LIVE BOOKMAP PRICE PARITY • TARGET WATCHDOG
# LEGACY CHART RESTORE • F10/F11 SAFE TOGGLE
#
# INTEGRITY CONTRACT
#   * BTC Gold Master decision/Open-Lock/reversal/survival math is untouched.
#   * BTC startup/history/live-price behavior calls the exact pre-existing path.
#   * SOL/DOGE get the SAME architecture: asset-correct startup candles, then
#     native Bookmap executions/depth for live state, plus their own Kalshi 15m
#     target discovery/rollover.
#   * Startup history is only a chart seed. Live native state remains Bookmap.
# ============================================================================

_V2677_RELEASE = 'V21.67.7'
_V2677_PRODUCTS = {'BTC':'BTC-USD', 'SOL':'SOL-USD', 'DOGE':'DOGE-USD'}
_V2677_BASE_INIT = ChartKingPro.__init__
_V2677_BASE_PRELOAD = ChartKingPro._preload_btc_context
_V2677_BASE_EFFECTIVE_LIVE = ChartKingPro.effective_live_price
_V2677_BASE_EXTRACT_TARGET = ChartKingPro._extract_target
_V2677_BASE_DISCOVER = ChartKingPro._discover_current_kalshi_market
_V2677_BASE_APPLY = ChartKingPro._apply_kalshi_market
_V2677_BASE_SANITIZE = ChartKingPro._sanitize_ticker
_V2677_BASE_CHILD_APPLY = _bk_child_apply_event
_V2677_BASE_CHILD_STATUS = _v2674_child_status_heartbeat
_V2677_BASE_COCKPIT_TICK = _v2676_tick
_V2677_BASE_MOUNT_COCKPIT = _v2676_mount_cockpit


def _v2677_asset(self=None):
    try:
        a = str(getattr(self, 'asset_symbol', _V2674_CHILD_ASSET) or _V2674_CHILD_ASSET or 'BTC').upper()
    except Exception:
        a = str(_V2674_CHILD_ASSET or 'BTC').upper()
    return a if a in _V2674_ASSETS else 'BTC'


def _v2677_product(self=None):
    return _V2677_PRODUCTS.get(_v2677_asset(self), 'BTC-USD')


def _v2677_public_candle_seed(self, granularity):
    """Asset-correct startup history. Display/context seed only; live = Bookmap."""
    product = _v2677_product(self)
    url = f'https://api.exchange.coinbase.com/products/{product}/candles'
    return _v211_parse_candles(http_json(url, {'granularity': int(granularity)}, timeout=6))


def _v2677_public_recent_trade_seed(self):
    """Recent prints only to pre-populate 3s/5s/15s/30s before Bookmap's next print."""
    product = _v2677_product(self)
    try:
        raw = http_json(f'https://api.exchange.coinbase.com/products/{product}/trades', {'limit': 1000}, timeout=6)
    except Exception:
        return []
    out = []
    for row in raw or []:
        try:
            ts = datetime.fromisoformat(str(row.get('time','')).replace('Z','+00:00')).timestamp()
            px = float(row.get('price'))
            size = max(0.0, float(row.get('size', 0.0) or 0.0))
            if px > 0 and math.isfinite(px):
                out.append({'ts':float(ts),'price':px,'size':size})
        except Exception:
            pass
    out.sort(key=lambda x:x['ts'])
    return out


def _v2677_seed_micro(self, trades):
    if not trades:
        return
    for sec in (3, 5):
        seeded = []
        for t in trades:
            try:
                _bk_update_ohlc(seeded, sec, float(t['ts']), float(t['price']), float(t.get('size',0.0)), 1600 if sec==3 else 1000)
            except Exception:
                pass
        for r in seeded:
            r['_trade_count'] = max(1, int(r.get('_trade_count', 1) or 1))
            r['_open_source'] = 'COINBASE STARTUP SEED'
            r['_live_source'] = 'STARTUP SEED • LIVE = BOOKMAP'
        try:
            with self.bookmap_lock:
                dq = self.bookmap_micro_candles.get(sec)
                existing = [dict(r) for r in (dq or ())]
                merged = {int(r.get('time',0)):dict(r) for r in seeded}
                # Any native Bookmap row already received wins the same bucket.
                for r in existing:
                    merged[int(r.get('time',0))] = dict(r)
                rows = [merged[k] for k in sorted(merged)]
                if dq is not None:
                    maxlen = getattr(dq, 'maxlen', None) or (1500 if sec==3 else 900)
                    dq.clear(); dq.extend(rows[-maxlen:])
        except Exception:
            pass


def _v2677_preload_asset_context(self):
    asset = _v2677_asset(self)
    if asset == 'BTC':
        # Absolute Gold-Master parity: BTC calls the exact existing preloader.
        return _V2677_BASE_PRELOAD(self)
    loaded = []
    try:
        one = _v2677_public_candle_seed(self, 60)
        self.btc_1m = _v211_merge_seed(getattr(self,'btc_1m',[]), one, 2400)
        loaded.append(f'1m {len(self.btc_1m)}')
    except Exception as exc:
        self.last_error = f'{asset} 1m startup history: {exc}'
    for attr, sec, maxrows, label in (
        ('btc_5m',300,1600,'5m'), ('btc_15m',900,1200,'15m'), ('btc_1h',3600,900,'1H')):
        try:
            seed = _v2677_public_candle_seed(self, sec)
            setattr(self, attr, _v211_merge_seed(getattr(self,attr,[]), seed, maxrows))
            loaded.append(f'{label} {len(getattr(self,attr))}')
        except Exception:
            pass
    try:
        trades = _v2677_public_recent_trade_seed(self)
        if trades:
            cutoff = time.time() - 7200
            seed_points = [(t['ts'],t['price']) for t in trades if t['ts'] >= cutoff]
            native = list(getattr(self,'live_prices',[]) or [])
            both = seed_points + native
            both.sort(key=lambda x:x[0])
            ded=[]; seen=set()
            precision = 6 if asset=='DOGE' else 4 if asset=='SOL' else 2
            for ts,px in both:
                if ts < cutoff: continue
                key=(int(float(ts)*1000), round(float(px),precision))
                if key in seen: continue
                seen.add(key); ded.append((float(ts),float(px)))
            self.live_prices = ded[-30000:]
            _v2677_seed_micro(self, trades)
            loaded.append(f'3s/5s recent seed {len(trades)} prints')
    except Exception:
        pass
    try:
        self._set_var_if_changed(
            self.chart_tf_status_var,
            f'{asset} startup history loaded • ' + ' • '.join(loaded) + ' • LIVE = BOOKMAP'
        )
        self._last_chart_render_key = None
        self.root.after(0, self.draw_chart)
    except Exception:
        pass
    return bool(loaded)


ChartKingPro._preload_btc_context = _v2677_preload_asset_context


def _v2677_effective_live_price(self):
    asset = _v2677_asset(self)
    if asset == 'BTC':
        return _V2677_BASE_EFFECTIVE_LIVE(self)
    now = time.time()
    trade_ts = float(getattr(self,'_v2677_last_native_trade_ts',0.0) or 0.0)
    px = getattr(self,'current_spot',None)
    # Native executed trade is primary while fresh.
    if px is not None and trade_ts > 0 and now-trade_ts <= 2.5:
        return (float(px), f'{asset} BOOKMAP EXECUTED TRADE ({now-trade_ts:.2f}s)')
    # If no trade just printed, Bookmap depth keeps the display/asset brain live.
    try:
        with self.bookmap_lock:
            bid = max(self.bookmap_bids) if self.bookmap_bids else None
            ask = min(self.bookmap_asks) if self.bookmap_asks else None
        if bid is not None and ask is not None and float(ask) >= float(bid):
            return ((float(bid)+float(ask))*0.5, f'{asset} BOOKMAP BBO MID')
    except Exception:
        pass
    if px is not None:
        age = now-trade_ts if trade_ts > 0 else 999.0
        return (float(px), f'{asset} BOOKMAP LAST TRADE ({age:.1f}s)')
    return (None, f'WAITING FOR {asset} BOOKMAP')


ChartKingPro.effective_live_price = _v2677_effective_live_price


def _v2677_nested_target_candidates(obj, path=''):
    """Yield only target/strike/reference-context numeric candidates."""
    if isinstance(obj, dict):
        for k,v in obj.items():
            kp = f'{path}.{k}' if path else str(k)
            kl = str(k).lower()
            if any(tok in kl for tok in ('target','reference','strike','price_to_beat','threshold')):
                if isinstance(v,(int,float,str)) and not isinstance(v,bool):
                    yield kp, v
            if isinstance(v,(dict,list,tuple)):
                yield from _v2677_nested_target_candidates(v,kp)
    elif isinstance(obj,(list,tuple)):
        for i,v in enumerate(obj):
            if isinstance(v,(dict,list,tuple)):
                yield from _v2677_nested_target_candidates(v,f'{path}[{i}]')


def _v2677_extract_target(self, market):
    asset = _v2677_asset(self)
    if asset == 'BTC':
        return _V2677_BASE_EXTRACT_TARGET(self, market)
    # First preserve the V21.67.5 extractor.
    try:
        x = _V2677_BASE_EXTRACT_TARGET(self, market)
        if x is not None and _v2675_target_ok(asset,x):
            return float(x)
    except Exception:
        pass
    if not market:
        return None
    # Newer API variants can nest strike/reference information.
    for _path, raw in _v2677_nested_target_candidates(market):
        x = _v2675_float(raw)
        if x is not None and _v2675_target_ok(asset,x):
            return float(x)
    # Last safe fallback: only numbers immediately adjacent to TARGET language.
    strings=[]
    def collect(o):
        if isinstance(o,dict):
            for v in o.values(): collect(v)
        elif isinstance(o,(list,tuple)):
            for v in o: collect(v)
        elif isinstance(o,str): strings.append(o)
    collect(market)
    text=' '.join(strings)
    patterns=(
        r'(?:target(?:\s+price)?|price\s+to\s+beat|reference(?:\s+price)?)\s*[:=·\-]?\s*\$?\s*([0-9][0-9,]*(?:\.[0-9]+)?)',
        r'\$?\s*([0-9][0-9,]*(?:\.[0-9]+)?)\s*(?:target|price\s+to\s+beat|reference(?:\s+price)?)',
    )
    for pat in patterns:
        for m in re.finditer(pat,text,flags=re.I):
            x=_v2675_float(m.group(1))
            if x is not None and _v2675_target_ok(asset,x): return float(x)
    return None


ChartKingPro._extract_target = _v2677_extract_target


def _v2677_discover_current_kalshi_market(self):
    asset = _v2677_asset(self)
    if asset == 'BTC':
        return _V2677_BASE_DISCOVER(self)
    series = _V2675_SERIES[asset]
    data = self.kalshi_get('/markets', {'series_ticker':series,'status':'open','limit':200})
    markets = data.get('markets') or []
    if not markets:
        raise RuntimeError(f'Kalshi returned no open {series} markets')
    now=time.time(); active=[]; future=[]
    for m in markets:
        open_ts=self._parse_iso_ts(m.get('open_time'))
        close_ts=self._parse_iso_ts(m.get('close_time') or m.get('expected_expiration_time') or m.get('expiration_time'))
        if close_ts is not None and close_ts>now: future.append((close_ts,m))
        if open_ts is not None and close_ts is not None and open_ts<=now<close_ts: active.append((close_ts,m))
    chosen = sorted(active,key=lambda x:x[0])[0][1] if active else sorted(future,key=lambda x:x[0])[0][1] if future else markets[0]
    # Fetch the full market record when list response is missing target fields.
    if _v2677_extract_target(self,chosen) is None:
        ticker=str(chosen.get('ticker') or '').strip().upper()
        if ticker:
            try:
                full=self._get_kalshi_market(ticker)
                if full:
                    merged=dict(chosen); merged.update(full); chosen=merged
            except Exception:
                pass
    return chosen


ChartKingPro._discover_current_kalshi_market = _v2677_discover_current_kalshi_market


def _v2677_sanitize_ticker(self, raw):
    asset=_v2677_asset(self)
    if asset=='BTC': return _V2677_BASE_SANITIZE(self,raw)
    raw=str(raw or '').strip(); upper=raw.upper()
    if not upper: return ''
    series=_V2675_SERIES.get(asset,'')
    m=re.search(rf'({re.escape(series)}-[A-Z0-9-]+)',upper)
    if m:
        return re.split(r'[/?#&=%\s]',m.group(1))[0]
    generic=re.search(r'\b([A-Z][A-Z0-9]{2,}(?:-[A-Z0-9]+){2,})\b',upper)
    return generic.group(1) if generic else ('' if 'KALSHI.COM' in upper or upper.startswith('HTTP') else upper)


ChartKingPro._sanitize_ticker = _v2677_sanitize_ticker


def _v2677_target_watchdog(self):
    asset=_v2677_asset(self)
    if asset not in ('SOL','DOGE'): return
    now=time.time(); bucket=int(now//900)*900
    source=str(getattr(self,'_v2674_target_source','') or '')
    target=getattr(self,'target_price',None)
    locked=(getattr(self,'_v2677_target_locked_bucket',None)==bucket and target is not None and 'KALSHI' in source.upper())
    if not locked and not getattr(self,'_v2677_target_fetch_running',False):
        self._v2677_target_fetch_running=True
        def worker():
            try:
                market=_v2677_discover_current_kalshi_market(self)
                target=_v2677_extract_target(self,market)
                if market:
                    self._apply_kalshi_market(market,'AUTO-ROUND-LOCK')
                if target is not None:
                    self.target_price=float(target)
                    self._v2674_target_source=f'KALSHI {_V2675_SERIES[asset]} • ROUND LOCK'
                    self._v2677_target_locked_bucket=bucket
                    ticker=str((market or {}).get('ticker') or _V2675_SERIES[asset])
                    try:
                        self.root.after(0, lambda t=float(target),tkx=ticker,a=asset:
                            self.auto_target_status_var.set(f'AUTO {a} TARGET: {_v2674_price_fmt(t)} • LOCKED THIS ROUND • {tkx}'))
                    except Exception: pass
            except Exception as exc:
                self._v2677_target_error=str(exc)
            finally:
                self._v2677_target_fetch_running=False
        threading.Thread(target=worker,name=f'LeChartJames-{asset}-TargetLock',daemon=True).start()
    delay=420 if (now-bucket)<12 or not locked else 1400
    try: self.root.after(delay,lambda s=self:_v2677_target_watchdog(s))
    except Exception: pass


def _v2677_init(self,*args,**kwargs):
    # Critical: set asset BEFORE the inherited init starts threads/preload/target
    # callbacks. V21.67.5 did this after init, which let SOL briefly behave as BTC.
    try:
        self.asset_symbol=str(_V2674_CHILD_ASSET or 'BTC').upper()
        self.asset_name=_v2674_asset_name(self.asset_symbol)
    except Exception:
        pass
    _V2677_BASE_INIT(self,*args,**kwargs)
    asset=_v2677_asset(self)
    try:
        self.asset_symbol=asset; self.asset_name=_v2674_asset_name(asset)
        self.root.title(f'LECHART JAMES V21.67.7 — {asset} KING • NATIVE BOOKMAP + AUTO TARGET')
        self._v2677_last_native_trade_ts=0.0
        self._v2677_target_locked_bucket=None
        self._v2677_target_fetch_running=False
        self._v2677_target_error=''
    except Exception: pass
    if asset in ('SOL','DOGE'):
        try:
            self.auto_market_enabled_var.set(True)
            self.root.after(120,lambda s=self:_v2675_arm_asset_kalshi(s))
            self.root.after(180,lambda s=self:_v2677_target_watchdog(s))
        except Exception: pass


ChartKingPro.__init__ = _v2677_init


def _bk_child_apply_event(app, root, event):
    kind=str((event or {}).get('type','')).lower().strip()
    asset=_v2677_asset(app)
    if kind=='trade' and asset in ('SOL','DOGE'):
        try: app._v2677_last_native_trade_ts=float(event.get('ts',time.time()) or time.time())
        except Exception: app._v2677_last_native_trade_ts=time.time()
    result=_V2677_BASE_CHILD_APPLY(app,root,event)
    if asset in ('SOL','DOGE') and kind in ('trade','depth'):
        try:
            live,src=app.effective_live_price()
            if live is not None:
                app.current_spot=float(live)
                app.quote_mesh_price=float(live); app.quote_mesh_last=time.time(); app.quote_mesh_source=str(src)
                app.price_source_var.set(str(src))
        except Exception: pass
    return result


def _v2677_child_status_heartbeat(app, root):
    asset=_v2677_asset(app)
    try:
        lock=dict(getattr(app,'opening_lock_snapshot',None) or {}); side=str(lock.get('lock_side','WAIT')).upper()
        try: px,pxsrc=app.effective_live_price()
        except Exception: px,pxsrc=getattr(app,'current_spot',None),'--'
        tug={}
        try: tug=dict(_v2672_tug_read(app,now=time.time()) or {})
        except Exception: pass
        journey=dict(getattr(app,'_v2673_last_map',{}) or {})
        _v2674_send_control({'type':'asset_status','asset':asset,'lock':side,'price':px,'price_source':pxsrc,
                             'bookmap_alias':getattr(app,'bookmap_alias','--'),'tug':tug.get('side','--'),'tug_force':tug.get('force'),
                             'journey_stage':journey.get('stage','--'),'route_match':journey.get('route_match'),'ts':time.time()})
    except Exception: pass
    try: root.after(500,lambda:_v2677_child_status_heartbeat(app,root))
    except Exception: pass


_v2674_child_status_heartbeat = _v2677_child_status_heartbeat


def _v2677_cockpit_tick(app):
    if _v2677_asset(app) in ('SOL','DOGE'):
        try:
            live,src=app.effective_live_price()
            if live is not None:
                app.current_spot=float(live)
                app.price_source_var.set(str(src))
        except Exception: pass
    return _V2677_BASE_COCKPIT_TICK(app)


_v2676_tick = _v2677_cockpit_tick


def _v2677_restore_chart_canvas(app, legacy):
    try:
        canvas = getattr(app,'_v2676_legacy_canvas',None) if legacy else getattr(app,'_v2676_cockpit_canvas',None)
        if canvas is not None and canvas.winfo_exists():
            app.canvas=canvas
            app._last_chart_render_key=None
            try: app.root.after_idle(app.draw_chart)
            except Exception: pass
            return True
    except Exception:
        pass
    return False


def _v2676_toggle_legacy(app):
    """Safe two-way cockpit/legacy switch. F10 and F11 both work."""
    try:
        shell=getattr(app,'v2676_shell',None)
        if shell is None: return
        showing=bool(getattr(app,'_v2676_showing',True))
        if showing:
            # Save cockpit renderer and give the old desk its ORIGINAL canvas back
            # before exposing it. This fixes the blank legacy chart + freeze loop.
            if getattr(app,'_v2676_cockpit_canvas',None) is None:
                app._v2676_cockpit_canvas=getattr(app,'canvas',None)
            _v2677_restore_chart_canvas(app, True)
            shell.place_forget(); app._v2676_showing=False
            btn=getattr(app,'v2676_return_button',None)
            if btn is not None:
                btn.place(relx=0.995,y=7,anchor='ne'); btn.lift()
            try:
                app.root.update_idletasks()
                app.root.after(80,app.draw_chart)
            except Exception: pass
        else:
            _v2677_restore_chart_canvas(app, False)
            shell.place(x=0,y=0,relwidth=1,relheight=1); shell.lift(); app._v2676_showing=True
            btn=getattr(app,'v2676_return_button',None)
            if btn is not None: btn.place_forget()
            try:
                app.root.update_idletasks(); app.root.after(40,app.draw_chart)
            except Exception: pass
    except Exception:
        try:
            Path.home().joinpath('Downloads','LECHART_V2677_UI_TOGGLE_ERROR.txt').write_text(traceback.format_exc(),encoding='utf-8')
        except Exception: pass


def _v2677_mount_cockpit(app, root, asset):
    _V2677_BASE_MOUNT_COCKPIT(app,root,asset)
    try:
        app._v2676_cockpit_canvas=getattr(app,'canvas',None)
        root.bind('<F10>',lambda e:_v2676_toggle_legacy(app))
        root.bind('<F11>',lambda e:_v2676_toggle_legacy(app))
    except Exception: pass


_v2676_mount_cockpit = _v2677_mount_cockpit

