def _v26710_asset(self):
    try:
        a=str(getattr(self,'asset_symbol','BTC') or 'BTC').upper()
    except Exception:
        a='BTC'
    return a if a in ('BTC','SOL','DOGE') else 'BTC'


def _v26710_floor(self, btc_dollars):
    try:
        return max(1e-9,float(_v2674_asset_floor(self,float(btc_dollars))))
    except Exception:
        try:
            px=abs(float(getattr(self,'current_spot',0.0) or 0.0))
        except Exception:
            px=0.0
        return max(1e-9, float(btc_dollars) if _v26710_asset(self)=='BTC' else px*(float(btc_dollars)/100000.0))


def _v26710_median(values, default=0.0):
    vals=[]
    for v in values:
        try:
            f=float(v)
            if math.isfinite(f): vals.append(f)
        except Exception:
            pass
    if not vals: return float(default)
    vals.sort(); n=len(vals); m=n//2
    return vals[m] if n%2 else (vals[m-1]+vals[m])/2.0


def _v26710_rows(self, seconds=60, limit=220):
    try:
        rows=self._web_interval_candles(int(seconds),limit=int(limit))
        return [dict(r) for r in rows if r and all(k in r for k in ('open','high','low','close'))]
    except Exception:
        return []


def _v26710_supply_demand_read(self, now=None):
    """Completed-candle impulse/base/impulse zones; display + bounded destination context."""
    now=float(now or time.time())
    rows=_v26710_rows(self,60,220)
    if len(rows)<14:
        return {'ready':False,'zones':[],'demand':None,'supply':None,'text':'S/D: building completed 1m structure'}
    # Do not use a forming 1m candle as a confirmed base/impulse.
    closed=[r for r in rows if float(r.get('time',0) or 0)+60.0<=now]
    if len(closed)<12: closed=rows[:-1]
    try:
        live,_=self.effective_live_price(); live=float(live)
    except Exception:
        live=float(closed[-1]['close'])
    tr=[max(_v26710_floor(self,.02),float(r['high'])-float(r['low'])) for r in closed[-50:]]
    atr=max(_v26710_floor(self,.5),_v26710_median(tr,_v26710_floor(self,2.0)))
    zones=[]
    # 1-3 candle bases. Require a real impulse into and out of the base.
    for base_len in (1,2,3):
        for i in range(2,len(closed)-base_len-1):
            base=closed[i:i+base_len]; prev=closed[i-1]; nxt=closed[i+base_len]
            blo=min(float(x['low']) for x in base); bhi=max(float(x['high']) for x in base)
            br=bhi-blo
            bbody=sum(abs(float(x['close'])-float(x['open'])) for x in base)/base_len
            pin=float(prev['close'])-float(prev['open']); pout=float(nxt['close'])-float(nxt['open'])
            if br>atr*(1.05+.18*base_len) or bbody>atr*.44: continue
            if abs(pin)<atr*.48 or abs(pout)<atr*.62: continue
            a='R' if pin>0 else 'D'; z='R' if pout>0 else 'D'
            code=f'{a}B{z}'
            patt=f'{"Rally" if a=="R" else "Drop"}-Base-{"Rally" if z=="R" else "Drop"}'
            side='DEMAND' if z=='R' else 'SUPPLY'
            end_i=i+base_len
            age=max(0,len(closed)-end_i-1)
            # Penalize zones that were decisively pierced after creation.
            future=closed[end_i+1:]
            broken=False; touches=0
            for q in future:
                qlo=float(q['low']); qhi=float(q['high'])
                if not (qhi<blo or qlo>bhi): touches+=1
                if side=='DEMAND' and qlo < blo-atr*.28: broken=True; break
                if side=='SUPPLY' and qhi > bhi+atr*.28: broken=True; break
            if broken: continue
            impulse=(abs(pin)+abs(pout))/max(2*atr,1e-9)
            freshness=max(.20,1.0-age/150.0)
            retest=max(.25,1.0-min(touches,4)*.16)
            continuation=1.08 if a==z else 1.0
            score=max(32.0,min(97.0,(43+25*min(1.5,impulse)+22*freshness)*retest*continuation))
            zones.append({'side':side,'pattern':patt,'code':code,'low':blo,'high':bhi,'mid':(blo+bhi)/2,
                          'score':score,'age':age,'touches':touches,'base_len':base_len})
    # Merge overlapping same-side zones, strongest/freshest survives.
    ded=[]
    for z in sorted(zones,key=lambda q:(q['age'],-q['score'])):
        found=None
        for d in ded:
            if d['side']==z['side'] and not (z['high']<d['low']-atr*.22 or z['low']>d['high']+atr*.22):
                found=d; break
        if found is None: ded.append(dict(z))
        elif z['score']>found['score']: found.update(z)
    demand_pool=[z for z in ded if z['side']=='DEMAND' and z['high']<=live+atr*.9]
    supply_pool=[z for z in ded if z['side']=='SUPPLY' and z['low']>=live-atr*.9]
    demand=min(demand_pool,key=lambda z:abs(live-z['mid'])) if demand_pool else None
    supply=min(supply_pool,key=lambda z:abs(live-z['mid'])) if supply_pool else None
    bits=[]
    if demand: bits.append(f"DEMAND {demand['code']} {money(demand['low'])}-{money(demand['high'])} {demand['score']:.0f}/100")
    if supply: bits.append(f"SUPPLY {supply['code']} {money(supply['low'])}-{money(supply['high'])} {supply['score']:.0f}/100")
    return {'ready':bool(demand or supply),'zones':ded[-24:],'demand':demand,'supply':supply,'atr':atr,'live':live,
            'text':' • '.join(bits) if bits else 'S/D: no clean fresh zone nearby'}


def _v26710_tiger_balance_read(self, now=None):
    """TigerPack concept: balance means persistence, not an automatic 50/50 reset."""
    now=float(now or time.time())
    try: wave=dict(self._bookmap_wave_read(now=now) or {})
    except Exception: wave=dict(getattr(self,'bookmap_wave_last',{}) or {})
    try: whale=dict(self._bookmap_whale_read(now=now) or {})
    except Exception: whale=dict(getattr(self,'bookmap_whale_last',{}) or {})
    depth=float(wave.get('depth_imbalance',0.0) or 0.0)
    rows=_v26710_rows(self,5,100)
    path='WAIT'; strength=0.0
    if len(rows)>=10:
        r=rows[-18:]
        closes=[float(x['close']) for x in r]
        ranges=[max(_v26710_floor(self,.01),float(x['high'])-float(x['low'])) for x in r]
        q=max(_v26710_floor(self,.03),_v26710_median(ranges,_v26710_floor(self,.5)))
        # Two-horizon path: avoids calling a single spike the prevailing state.
        m1=closes[-1]-closes[max(0,len(closes)-7)]
        m2=closes[-1]-closes[0]
        signed=(.58*m1+.42*m2)/max(q*4.0,1e-9)
        if abs(signed)>=.14:
            path='UP' if signed>0 else 'DOWN'; strength=min(1.0,abs(signed))
    wdir=str(whale.get('direction','NEUTRAL') or 'NEUTRAL').upper()
    wlike=float(whale.get('likelihood',0.0) or 0.0)
    wsigned=float(whale.get('signed_score',0.0) or 0.0)
    balanced=abs(depth)<=.10
    opposite_whale=(path in ('UP','DOWN') and wdir in ('UP','DOWN') and wdir!=path and
                    (wlike>=65.0 or abs(wsigned)>=56.0))
    inertia='WAIT'
    if balanced and path in ('UP','DOWN') and not opposite_whale:
        inertia=path
    score=(1 if inertia=='UP' else -1 if inertia=='DOWN' else 0)*min(.105,.035+.070*strength)
    # This is deliberately tiny: Tiger state is one contextual family, never lock authority.
    if balanced:
        if opposite_whale:
            text=f'TIGER: BOOK BALANCED {depth:+.2f} • {path} path • OPPOSITE WHALE {wdir} {wlike:.0f}% → INERTIA CANCELLED'
        elif path in ('UP','DOWN'):
            text=f'TIGER: BOOK BALANCED {depth:+.2f} • preserve {path} path unless opposite whale displaces it'
        else:
            text=f'TIGER: BOOK BALANCED {depth:+.2f} • no established path yet'
    else:
        text=f'TIGER: BOOK IMBALANCE {depth:+.2f} • persistence rule idle'
    return {'ready':True,'balanced':balanced,'depth_imbalance':depth,'path':path,'path_strength':strength,
            'whale_direction':wdir,'whale_likelihood':wlike,'whale_signed':wsigned,'opposite_whale':opposite_whale,
            'inertia_side':inertia,'score':score,'text':text}


def _v26710_destination_context(self, warm=None, now=None):
    base=dict(_V26710_BASE_DESTINATION(self,warm=warm,now=now) or {})
    sd=_v26710_supply_demand_read(self,now=now)
    tiger=_v26710_tiger_balance_read(self,now=now)
    original=float(base.get('score',0.0) or 0.0)
    modifier=0.0; why=[]
    live=sd.get('live'); atr=max(_v26710_floor(self,.1),float(sd.get('atr',_v26710_floor(self,1.0)) or _v26710_floor(self,1.0)))
    d=sd.get('demand'); s=sd.get('supply')
    if d and live is not None:
        dist=max(0.0,float(live)-float(d['high']))
        near=max(0.0,1.0-dist/max(atr*3.6,1e-9))
        modifier += .105*near*(float(d.get('score',50))/100.0)
        if near>.22: why.append('fresh demand '+str(d.get('code')))
    if s and live is not None:
        dist=max(0.0,float(s['low'])-float(live))
        near=max(0.0,1.0-dist/max(atr*3.6,1e-9))
        modifier -= .105*near*(float(s.get('score',50))/100.0)
        if near>.22: why.append('fresh supply '+str(s.get('code')))
    modifier += float(tiger.get('score',0.0) or 0.0)
    modifier=max(-.18,min(.18,modifier))
    score=_v252_clip(original+modifier,-_V263_PINE_CAP,_V263_PINE_CAP)
    side='UP' if score>=.12 else 'DOWN' if score<=-.12 else 'WAIT'
    reason_parts=[]
    if base.get('reason'): reason_parts.append(str(base.get('reason')))
    reason_parts.extend(why)
    reason_parts.append(str(tiger.get('text','')))
    base.update({'score':score,'side':side,'supply_demand':sd,'tiger_balance':tiger,
                 'v26710_modifier':modifier,'v26710_base_score':original,
                 'reason':' • '.join(x for x in reason_parts if x).strip(' •')})
    self._v263_destination_last=base
    return base

# Global lookup is intentional: V21.63 Open Lock / data ceiling already resolves
