_v263_destination_context = _v26710_destination_context
ChartKingPro._v26710_supply_demand_read = _v26710_supply_demand_read
ChartKingPro._v26710_tiger_balance_read = _v26710_tiger_balance_read


def _v26710_breakout_prediction(self, now=None):
    now=float(now or time.time())
    rows=_v26710_rows(self,60,160)
    closed=[r for r in rows if float(r.get('time',0) or 0)+60.0<=now]
    if len(closed)<12:
        return {'ready':False,'text':'BREAKOUT MAP: building completed 1m structure'}
    try: live,_=self.effective_live_price(); live=float(live)
    except Exception: live=float(closed[-1]['close'])
    recent=closed[-36:]
    atr=max(_v26710_floor(self,.5),_v26710_median([max(_v26710_floor(self,.02),float(r['high'])-float(r['low'])) for r in recent],_v26710_floor(self,2.0)))
    sd=_v26710_supply_demand_read(self,now=now)
    # Local structural levels: ignore current candle and use repeated/swing extremes.
    highs=sorted(float(r['high']) for r in recent[:-1])
    lows=sorted(float(r['low']) for r in recent[:-1])
    local_hi=highs[-2] if len(highs)>=2 else highs[-1]
    local_lo=lows[1] if len(lows)>=2 else lows[0]
    s=sd.get('supply'); d=sd.get('demand')
    raw_up=max(local_hi,float(s['high']) if s else local_hi)
    raw_down=min(local_lo,float(d['low']) if d else local_lo)
    buffer=max(_v26710_floor(self,.8),min(_v26710_floor(self,14.0),atr*.13))
    up=raw_up+buffer; down=raw_down-buffer
    try: dest=dict(_v26710_destination_context(self,now=now) or {})
    except Exception: dest={}
    try: tug=dict(_v2672_tug_read(self,now=now) or {})
    except Exception: tug={}
    dscore=float(dest.get('score',0.0) or 0.0)
    up_force=float(tug.get('up_force',50.0) or 50.0)
    tiger=dict(dest.get('tiger_balance') or {})
    tiger_adj=float(tiger.get('score',0.0) or 0.0)*45.0
    up_conf=max(5.0,min(95.0,50.0+dscore*34.0+(up_force-50.0)*.30+tiger_adj))
    down_conf=100.0-up_conf
    primary='UP' if up_conf>=58 else 'DOWN' if down_conf>=58 else 'WAIT / TWO-SIDED'
    text=f'BREAK MAP: UP > {money(up)} {up_conf:.0f}% • DOWN < {money(down)} {down_conf:.0f}% • {primary}'
    return {'ready':True,'live':live,'up_trigger':up,'down_trigger':down,'up_confidence':up_conf,
            'down_confidence':down_conf,'primary':primary,'buffer':buffer,'atr':atr,'supply_demand':sd,
            'text':text,'note':'structure/zone trigger + volatility buffer; not guaranteed future price'}

ChartKingPro._v26710_breakout_prediction = _v26710_breakout_prediction


def _v26710_draw_overlays(self):
    c=getattr(self,'canvas',None)
    scale=dict(getattr(self,'_v82_chart_scale',{}) or {})
    if c is None or not scale: return
    try:
        c.delete('v26710')
        lo=float(scale['lo']); hi=float(scale['hi']); top=float(scale['top']); ph=float(scale['ph'])
        left=float(scale['left']); right=float(scale['plot_right'])
        def yy(p): return top+(hi-float(p))/max(hi-lo,1e-12)*ph
        sd=_v26710_supply_demand_read(self)
        # Draw nearest active demand and supply as translucent-like stippled bands.
        for z,fill,outline,label in ((sd.get('demand'),'#123d31','#61e2aa','DEMAND'),(sd.get('supply'),'#4b1f32','#ff668e','SUPPLY')):
            if not z: continue
            y1=yy(z['high']); y2=yy(z['low'])
            c.create_rectangle(left,min(y1,y2),right,max(y1,y2),fill=fill,stipple='gray50',outline=outline,width=2,tags='v26710')
            c.create_text(left+8,min(y1,y2)+10,text=f"{label} {z['code']} • {z['score']:.0f}/100",fill=outline,anchor='w',font=('Cascadia Mono',7,'bold'),tags='v26710')
        bo=_v26710_breakout_prediction(self)
        if bo.get('ready'):
            uy=yy(bo['up_trigger']); dy=yy(bo['down_trigger'])
            c.create_line(left,uy,right,uy,fill='#61e2aa',dash=(9,4),width=2,tags='v26710')
            c.create_line(left,dy,right,dy,fill='#ff668e',dash=(9,4),width=2,tags='v26710')
            c.create_text(right-8,uy-8,text=f"UP BREAK > {money(bo['up_trigger'])} • {bo['up_confidence']:.0f}%",fill='#61e2aa',anchor='e',font=('Cascadia Mono',8,'bold'),tags='v26710')
            c.create_text(right-8,dy+9,text=f"DOWN BREAK < {money(bo['down_trigger'])} • {bo['down_confidence']:.0f}%",fill='#ff668e',anchor='e',font=('Cascadia Mono',8,'bold'),tags='v26710')
        tiger=_v26710_tiger_balance_read(self)
        txt=str(tiger.get('text',''))
        if txt:
            c.create_rectangle(left+8,top+28,min(right-8,left+720),top+56,fill='#0b1016',outline='#d9a441',width=1,tags='v26710')
            c.create_text(left+16,top+42,text=txt[:150],fill='#f2c14e',anchor='w',font=('Cascadia Mono',7,'bold'),tags='v26710')
        # Explicit invariant on-screen so current leader cannot be confused with destination lock.
        c.create_text(left+8,top+66,text='SETTLEMENT LOCK ≠ CURRENT LEADER',fill='#9aa8b6',anchor='w',font=('Cascadia Mono',7,'bold'),tags='v26710')
    except Exception:
        pass


