def _v26710_bind_chart_pan(self):
    c=getattr(self,'canvas',None)
    if c is None or getattr(self,'_v26710_pan_bound',False): return
    self._v26710_pan_bound=True
    self.chart_pan_offset=max(0,int(getattr(self,'chart_pan_offset',0) or 0))
    self._v26710_pan_anchor=None
    def down(e):
        self._v26710_pan_anchor=(int(e.x),int(self.chart_pan_offset))
        try: c.configure(cursor='fleur')
        except Exception: pass
        return 'break'
    def move(e):
        if not self._v26710_pan_anchor: return 'break'
        try:
            width=max(300,int(c.winfo_width())); px=max(4.0,width/max(8,int(self.visible_count)))
            delta=int(round((int(e.x)-self._v26710_pan_anchor[0])/px))
            self.chart_pan_offset=max(0,self._v26710_pan_anchor[1]+delta)
            rows=self._chart_candles() or []
            self.chart_pan_offset=min(self.chart_pan_offset,max(0,len(rows)-max(5,int(self.visible_count))))
            self._last_chart_render_key=None; self.draw_chart()
        except Exception: pass
        return 'break'
    def up(e):
        self._v26710_pan_anchor=None
        try: c.configure(cursor='')
        except Exception: pass
        return 'break'
    def live(e=None):
        self.chart_pan_offset=0; self._v26710_pan_anchor=None; self._last_chart_render_key=None
        try: self.draw_chart()
        except Exception: pass
        return 'break'
    c.bind('<ButtonPress-1>',down,add='+')
    c.bind('<B1-Motion>',move,add='+')
    c.bind('<ButtonRelease-1>',up,add='+')
    c.bind('<Double-Button-1>',live,add='+')


def _v26710_btc_target_matches_bucket(self, market, bucket):
    try:
        close_ts=self._parse_iso_ts((market or {}).get('close_time') or (market or {}).get('expected_expiration_time') or (market or {}).get('expiration_time'))
        if close_ts is None: return True
        expected=float(bucket)+900.0
        return abs(float(close_ts)-expected)<=180.0
    except Exception:
        return True


def _v26710_btc_target_worker(self, bucket):
    """Independent target capture: first valid CURRENT-round Kalshi BTC strike becomes immutable."""
    for attempt in range(90):
        if int(time.time()//900)*900!=int(bucket): return
        if getattr(self,'_v26710_target_lock',None) is not None: return
        try:
            market=self._discover_current_kalshi_market()
            target=self._extract_target(market) if market else None
            if target is not None and float(target)>1000 and _v26710_btc_target_matches_bucket(self,market,bucket):
                target=float(target)
                try: self._apply_kalshi_market(market,'V21.67.10 ROUND LOCK')
                except Exception: pass
                self.target_price=target
                self._v26710_target_lock_bucket=int(bucket)
                self._v26710_target_lock=target
                self._v217_target_captured_bucket=int(bucket)
                try:
                    ticker=str((market or {}).get('ticker') or '')
                    self.root.after(0,lambda t=target,tkx=ticker:self.auto_target_status_var.set(f'AUTO TARGET: {money(t)} • V21.67.10 ROUND LOCK • {tkx}'))
                except Exception: pass
                return
        except Exception as exc:
            self._v26710_target_error=str(exc)
        time.sleep(.18 if attempt<25 else .42)


def _v26710_target_guard_tick(self):
    # SOL/DOGE already use V21.67.8 hard-target watchdog. This adds the missing
    # independent BTC boundary guard without disturbing those asset-specific paths.
    if _v26710_asset(self)!='BTC':
        try: self.root.after(240,lambda s=self:_v26710_target_guard_tick(s))
        except Exception: pass
        return
    now=time.time(); bucket=int(now//900)*900
    if getattr(self,'_v26710_seen_bucket',None)!=bucket:
        self._v26710_seen_bucket=bucket
        self._v26710_target_lock_bucket=bucket
        self._v26710_target_lock=None
        self.target_price=None
        self._v217_target_bucket=bucket
        self._v217_target_captured_bucket=None
        self._v217_target_sniper_running=False
        try:
            self.auto_target_status_var.set('AUTO TARGET: NEW ROUND • CAPTURING FRESH KALSHI STRIKE...')
            self.auto_market_status_var.set('AUTO MARKET: NEW 15M • boundary watchdog active')
        except Exception: pass
        threading.Thread(target=_v26710_btc_target_worker,args=(self,bucket),name='LeChartJames-BTC-RoundTarget',daemon=True).start()
    try: self.root.after(120,lambda s=self:_v26710_target_guard_tick(s))
    except Exception: pass


def _v26710_effective_target(self):
    # Manual target remains explicit user authority.
    try:
        if self.use_manual_target_var.get(): return _V26710_BASE_EFFECTIVE_TARGET(self)
    except Exception: pass
    if _v26710_asset(self)=='BTC':
        bucket=int(time.time()//900)*900
        if int(getattr(self,'_v26710_target_lock_bucket',-1) or -1)==bucket:
            lock=getattr(self,'_v26710_target_lock',None)
            try:
                if lock is not None and float(lock)>1000: return float(lock),'V21.67.10 AUTO ROUND LOCK'
            except Exception: pass
        return None,'AWAITING FRESH BTC ROUND TARGET'
    return _V26710_BASE_EFFECTIVE_TARGET(self)

ChartKingPro.effective_target = _v26710_effective_target


