# ============================================================================
# LECHART JAMES V21.67.13 — TIGER STAT PROBABILITY BRAIN
# Adds a bounded statistical settlement-probability family to the existing
# destination brain. It estimates P(settle above target) from:
#   * live Bookmap price vs immutable Kalshi target
#   * time remaining in the 15m round
#   * realized 1m log-return volatility
#   * heavily-shrunk/capped recent drift
# It also compares the model probability with fresh Kalshi BBO when available.
#
# SAFETY / INVARIANT:
#   * This is ONE bounded context family, never sole lock authority.
#   * Current price location cannot directly force OPEN LOCK.
#   * Maximum destination modifier from this family is +/-0.10.
#   * Kalshi market price is DISPLAY/EDGE context only and is NOT fed back into
#     the destination modifier (avoids circular "odds say odds" logic).
# ============================================================================
_V26713_RELEASE = 'V21.67.13'
_V26713_BASE_DESTINATION = _v263_destination_context
_V26713_BASE_DRAW = ChartKingPro.draw_chart

def _v26713_norm_cdf(z):
    try:
        return 0.5 * (1.0 + math.erf(float(z) / math.sqrt(2.0)))
    except Exception:
        return 0.5

def _v26713_stat_probability(self, now=None):
    now = float(now or time.time())
    target = getattr(self, 'target_price', None)
    try:
        live, live_source = self.effective_live_price()
        live = float(live)
    except Exception:
        live = None
        live_source = 'WAITING'
    try:
        target = float(target)
    except Exception:
        target = None

    remaining = max(0.0, 900.0 - (now % 900.0))
    if not live or live <= 0 or not target or target <= 0:
        return {'ready': False, 'reason': 'waiting for live Bookmap price + Kalshi target',
                'remaining_sec': remaining}

    rows = _v26710_rows(self, 60, 90)
    closed = [r for r in rows if float(r.get('time', 0) or 0) + 60.0 <= now]
    if len(closed) < 22:
        return {'ready': False, 'reason': 'building realized-volatility sample',
                'remaining_sec': remaining, 'live': live, 'target': target}

    closes = [float(r['close']) for r in closed[-46:] if float(r.get('close', 0) or 0) > 0]
    rets = [math.log(closes[i] / closes[i-1]) for i in range(1, len(closes))
            if closes[i] > 0 and closes[i-1] > 0]
    if len(rets) < 20:
        return {'ready': False, 'reason': 'not enough clean 1m returns',
                'remaining_sec': remaining, 'live': live, 'target': target}

    # Robust-ish realized 1m volatility: trim only extreme 5% tails when enough
    # samples exist, then use sample standard deviation.
    rr = sorted(rets[-40:])
    if len(rr) >= 30:
        k = max(1, int(len(rr) * 0.05))
        rr = rr[k:-k] if len(rr) > 2*k else rr
    mean_r = sum(rr) / len(rr)
    var = sum((x - mean_r) ** 2 for x in rr) / max(1, len(rr) - 1)
    sigma_1m = max(1e-8, math.sqrt(max(0.0, var)))

    # Drift is deliberately distrusted in a 15m market: only 20% survives and
    # it can never exceed 0.35 sigma per minute.
    raw_mu = sum(rets[-12:]) / max(1, len(rets[-12:]))
    mu_1m = max(-0.35*sigma_1m, min(0.35*sigma_1m, raw_mu * 0.20))

    n_min = max(1.0/60.0, remaining / 60.0)
    sigma_T = sigma_1m * math.sqrt(n_min)
    mu_T = mu_1m * n_min
    log_barrier = math.log(target / live)
    z = (log_barrier - mu_T) / max(sigma_T, 1e-9)
    p_up_raw = 1.0 - _v26713_norm_cdf(z)

    # Pull extreme model outputs slightly toward 50% because BTC short-horizon
    # returns are not perfectly normal and volatility itself changes.
    p_up = 0.50 + (p_up_raw - 0.50) * 0.88
    p_up = max(0.03, min(0.97, p_up))
    p_down = 1.0 - p_up

    # Reliability is sample/time aware. Near zero remaining time, the model is
    # descriptive but we keep its authority bounded; it never becomes the lock.
    sample_rel = min(1.0, len(rets) / 36.0)
    time_rel = 0.70 + 0.30 * min(1.0, remaining / 180.0)
    reliability = max(0.35, min(1.0, sample_rel * time_rel))

    signed = (p_up - 0.50) * 2.0
    modifier = max(-0.10, min(0.10, signed * 0.10 * reliability))

    q = None
    try:
        q = _v266_quote_snapshot(self, max_age=4.0)
    except Exception:
        try:
            q = _v264_quote_snapshot(self, max_age=4.0)
        except Exception:
            q = None
    kalshi_mid = None
    edge = None
    if q:
        try:
            kalshi_mid = (float(q['yes_bid']) + float(q['yes_ask'])) * 0.5
            edge = p_up - kalshi_mid
        except Exception:
            kalshi_mid = None
            edge = None

    side = 'UP' if p_up >= 0.53 else 'DOWN' if p_up <= 0.47 else 'WAIT'
    vol_dollars_1m = live * sigma_1m
    exp_move = live * sigma_T
    reason = (f"STAT {side} {max(p_up,p_down)*100:.0f}% • z {z:+.2f} • "
              f"1m σ≈${vol_dollars_1m:,.1f} • {remaining:.0f}s left")
    if edge is not None:
        reason += f" • model-vs-Kalshi {edge*100:+.1f}pp"

    return {
        'ready': True, 'side': side, 'p_up': p_up, 'p_down': p_down,
        'z': z, 'sigma_1m': sigma_1m, 'vol_dollars_1m': vol_dollars_1m,
        'expected_move_dollars': exp_move, 'mu_1m': mu_1m,
        'remaining_sec': remaining, 'reliability': reliability,
        'modifier': modifier, 'kalshi_mid': kalshi_mid, 'edge': edge,
        'live': live, 'target': target, 'live_source': str(live_source),
        'reason': reason,
        'note': 'bounded settlement probability family; never sole lock authority'
    }

ChartKingPro._v26713_stat_probability = _v26713_stat_probability

def _v26713_destination_context(self, warm=None, now=None):
    base = dict(_V26713_BASE_DESTINATION(self, warm=warm, now=now) or {})
    stat = _v26713_stat_probability(self, now=now)
    original = float(base.get('score', 0.0) or 0.0)
    modifier = float(stat.get('modifier', 0.0) or 0.0) if stat.get('ready') else 0.0
    score = _v252_clip(original + modifier, -_V263_PINE_CAP, _V263_PINE_CAP)
    side = 'UP' if score >= .12 else 'DOWN' if score <= -.12 else 'WAIT'
    reason = str(base.get('reason', '') or '')
    if stat.get('ready'):
        reason = (reason + ' • ' + str(stat.get('reason', ''))).strip(' •')
    base.update({
        'score': score, 'side': side, 'stat_probability': stat,
        'v26713_stat_modifier': modifier, 'v26713_pre_stat_score': original,
        'reason': reason
    })
    self._v263_destination_last = base
    return base

# Open Lock / settlement brain resolves this global dynamically.
_v263_destination_context = _v26713_destination_context

def _v26713_draw_stat(self):
    c = getattr(self, 'canvas', None)
    scale = dict(getattr(self, '_v82_chart_scale', {}) or {})
    if c is None or not scale:
        return
    try:
        c.delete('v26713')
        x = float(scale['left']) + 8
        y = float(scale['top']) + 144
        st = _v26713_stat_probability(self)
        side = str(st.get('side', 'WAIT'))
        accent = '#61e2aa' if side == 'UP' else '#ff668e' if side == 'DOWN' else '#f2c14e'
        c.create_rectangle(x, y, x+430, y+60, fill='#090e14', outline=accent, width=2, tags='v26713')
        if not st.get('ready'):
            c.create_text(x+10, y+18, text='TIGER STAT BRAIN • BUILDING', fill=accent,
                          anchor='w', font=('Cascadia Mono',8,'bold'), tags='v26713')
            c.create_text(x+10, y+40, text=str(st.get('reason',''))[:62], fill='#c9d3dc',
                          anchor='w', font=('Cascadia Mono',7), tags='v26713')
            return
        pu = float(st['p_up']) * 100.0
        pd = float(st['p_down']) * 100.0
        c.create_text(x+10, y+13, text=f"TIGER STAT • UP {pu:.0f}% / DOWN {pd:.0f}%",
                      fill=accent, anchor='w', font=('Cascadia Mono',8,'bold'), tags='v26713')
        c.create_text(x+10, y+29,
                      text=f"z {float(st['z']):+.2f} • 1m σ≈${float(st['vol_dollars_1m']):,.1f} • {float(st['remaining_sec']):.0f}s left",
                      fill='#c9d3dc', anchor='w', font=('Cascadia Mono',7), tags='v26713')
        edge = st.get('edge')
        if edge is None:
            line = f"DEST MOD {float(st['modifier']):+.3f} • Kalshi edge waiting"
        else:
            line = f"MODEL EDGE {float(edge)*100:+.1f}pp • DEST MOD {float(st['modifier']):+.3f}"
        c.create_text(x+10, y+47, text=line, fill=accent, anchor='w',
                      font=('Cascadia Mono',8,'bold'), tags='v26713')
    except Exception:
        pass

def _v26713_draw_chart(self, *args, **kwargs):
    out = _V26713_BASE_DRAW(self, *args, **kwargs)
    try:
        _v26713_draw_stat(self)
    except Exception:
        pass
    return out

ChartKingPro.draw_chart = _v26713_draw_chart
