# ============================================================================
# LECHART JAMES V21.67.14 — BOOKMAP HARD-FREEZE FIREWALL
#
# Goal: keep Bookmap's native Python callback thread extremely small.
# V21.67.12 still launched a subprocess from bk_subscribe and then referenced
# an undefined BK_MULTI_READY name inside a 450ms wait loop.  In addition,
# every executed trade was JSON-encoded + UDP-sent directly inside Bookmap's
# trade callback, while the depth worker could emit thousands of UDP packets.
#
# This patch changes TRANSPORT ONLY. Strategy / Open Lock / Gold Master /
# Journey / Tug / Reversal Read / Tiger Stat math are untouched.
#   1) subscribe callback never waits and never launches a child inline;
#   2) cockpit launch happens on a daemon thread;
#   3) trades are queued in O(1) callback work and sent in compact batches;
#   4) depth remains latest-per-price, but is sent in compact batches at a
#      bounded cadence instead of one UDP packet per price mutation;
#   5) child expands the transport batches before the existing V21.59 event
#      engine, preserving trade ordering and the existing candle batching.
# ============================================================================
_V26714_RELEASE = 'V21.67.14'
_V26714_BASE_SUBSCRIBE = _V26712_BASE_SUBSCRIBE
_V26714_TRADE_Q = queue.SimpleQueue()
_V26714_TRADE_WORKER_STARTED = False
_V26714_TRADE_WORKER_LOCK = threading.Lock()
_V26714_LAUNCHING = set()
_V26714_LAUNCH_LOCK = threading.RLock()


def _v26714_launch_asset_async(asset):
    asset = str(asset or '').upper()
    if asset not in _V2674_ASSETS:
        return
    with _V26714_LAUNCH_LOCK:
        if _v26712_child_alive(asset) or asset in _V26714_LAUNCHING:
            return
        _V26714_LAUNCHING.add(asset)

    def worker():
        try:
            _v26712_launch_asset(asset)
        finally:
            with _V26714_LAUNCH_LOCK:
                _V26714_LAUNCHING.discard(asset)
    threading.Thread(target=worker, name=f'LeChartJames-{asset}-Launch', daemon=True).start()


def bk_subscribe(addon, alias, full_name, is_crypto, pips, size_multiplier, instrument_multiplier, supported_features):
    """Never block Bookmap's subscribe callback on UI/process startup."""
    asset = _v2674_detect_asset(alias, full_name)
    if asset in _V2674_ASSETS:
        _v26714_launch_asset_async(asset)
    # The existing transport queues hello/trade messages until the child says READY,
    # so there is no reason to sleep/wait inside Bookmap's callback thread.
    return _V26714_BASE_SUBSCRIBE(
        addon, alias, full_name, is_crypto, pips,
        size_multiplier, instrument_multiplier, supported_features
    )


def _v26714_trade_sender_worker():
    """Serialize/send outside Bookmap callbacks; preserve every queued trade."""
    while True:
        try:
            first_asset, first_event = _V26714_TRADE_Q.get()
        except Exception:
            time.sleep(0.01)
            continue

        grouped = {str(first_asset).upper(): [first_event]}
        # One localhost datagram stays comfortably below UDP's practical limit.
        # 96 compact trade rows are usually only a few KB.
        for _ in range(95):
            try:
                asset, ev = _V26714_TRADE_Q.get_nowait()
            except Exception:
                break
            grouped.setdefault(str(asset).upper(), []).append(ev)

        for asset, trades in grouped.items():
            if asset not in _V2674_ASSETS or not trades:
                continue
            payload = {
                'type': 'trade_batch',
                'asset': asset,
                'trades': trades,
                'ts': float(trades[-1].get('ts', time.time()) or time.time()),
            }
            _v2674_send_asset(asset, payload, queue_if_not_ready=True)


def _v26714_ensure_trade_worker():
    global _V26714_TRADE_WORKER_STARTED
    if _V26714_TRADE_WORKER_STARTED:
        return
    with _V26714_TRADE_WORKER_LOCK:
        if _V26714_TRADE_WORKER_STARTED:
            return
        threading.Thread(
            target=_v26714_trade_sender_worker,
            name='LeChartJames-TradeBatchSender', daemon=True
        ).start()
        _V26714_TRADE_WORKER_STARTED = True


def bk_on_trade(addon, alias, price_level, size_level, is_otc, is_bid,
                is_execution_start, is_execution_end, aggressor_order_id, passive_order_id):
    """Bookmap callback: numeric conversion + deque append + queue.put only."""
    try:
        asset = BK_MULTI_ALIAS_ASSET.get(alias)
        if asset not in _V2674_ASSETS:
            return
        ts = time.time()
        price = _bk_actual_price(alias, price_level)
        size = _bk_actual_size(alias, size_level)
        aggressor = 'buy' if bool(is_bid) else 'sell'
        ev = {
            'type': 'trade', 'asset': asset, 'alias': alias,
            'price': price, 'size': size, 'aggressor': aggressor, 'ts': ts
        }
        # Parent 10s Bookmap flow indicator still reads this exact tape.
        BK_PARENT_TRADES_BY_ALIAS.setdefault(alias, deque(maxlen=12000)).append({
            'ts': ts, 'price': price, 'size': size, 'aggressor': aggressor
        })
        _v26714_ensure_trade_worker()
        _V26714_TRADE_Q.put((asset, ev))
    except Exception as exc:
        print('[LeChart James V21.67.14] trade callback warning:', exc, flush=True)


def _v26714_depth_sender_worker():
    """Bounded latest-per-price depth transport with batched UDP payloads."""
    while True:
        # 25 Hz is far faster than the visual/decision consumers and prevents
        # the bridge thread from chewing a CPU core during a depth storm.
        time.sleep(0.040)
        batch = []
        with BK_MULTI_DEPTH_LOCK:
            if BK_MULTI_DEPTH_LATEST:
                # Rotate through the dictionary instead of trying to empty an
                # arbitrarily large book in one burst. Newer values overwrite
                # older values at the same price before they are sent.
                keys = list(BK_MULTI_DEPTH_LATEST.keys())[:360]
                for key in keys:
                    ev = BK_MULTI_DEPTH_LATEST.pop(key, None)
                    if ev is not None:
                        batch.append(ev)
        if not batch:
            continue

        grouped = {}
        for ev in batch:
            asset = str(ev.get('asset', '')).upper()
            if asset in _V2674_ASSETS:
                grouped.setdefault(asset, []).append(ev)

        for asset, rows in grouped.items():
            # Keep packets small enough for localhost UDP even with long aliases.
            for i in range(0, len(rows), 72):
                chunk = rows[i:i+72]
                _v2674_send_asset(asset, {
                    'type': 'depth_batch', 'asset': asset,
                    'depth': chunk,
                    'ts': float(chunk[-1].get('ts', time.time()) or time.time())
                }, queue_if_not_ready=False)


# _v2674_ensure_depth_thread resolves its target by global name when the control
# listener starts, which occurs only after this patch is defined in __main__.
_v2674_depth_sender_worker = _v26714_depth_sender_worker


_V26714_BASE_APPLY_ORDERED = _v256_apply_ordered_events

def _v26714_apply_ordered_events(app, root, events):
    """Expand transport batches, then hand data to the untouched V21.59 engine."""
    expanded = []
    for event in events or ():
        kind = str((event or {}).get('type', '')).lower().strip()
        if kind == 'trade_batch':
            for ev in (event.get('trades') or ()):
                if isinstance(ev, dict):
                    expanded.append(ev)
        elif kind == 'depth_batch':
            for ev in (event.get('depth') or ()):
                if isinstance(ev, dict):
                    expanded.append(ev)
        else:
            expanded.append(event)
    return _V26714_BASE_APPLY_ORDERED(app, root, expanded)

_v256_apply_ordered_events = _v26714_apply_ordered_events

