_V26717_RED = '#ff5b72'
_V26717_CYAN = '#35c8ff'
_V26717_GOLD = '#f6c85f'
_V26717_PURPLE = '#b884ff'


def _v26717_num(v, default=None):
    try:
        x=float(v)
        return x if math.isfinite(x) else default
    except Exception:
        return default


def _v26717_text(v, default='--'):
    try:
        s=str(v).strip()
        return s if s else default
    except Exception:
        return default


def _v26717_safe(fn, default=None):
    try:
        return fn()
    except Exception:
        return default


def _v26717_collect(app):
    now=time.time()
    live, live_src = _v26717_safe(lambda: app.effective_live_price(), (None,'WAITING'))
    target, target_src = _v26717_safe(lambda: app.effective_target(), (None,'WAITING'))
    live=_v26717_num(live); target=_v26717_num(target)
    stat=dict(_v26717_safe(lambda: _v26713_stat_probability(app,now=now), {}) or {})
    rev=dict(_v26717_safe(lambda: _v26711_reversal_read(app,now=now), {}) or {})
    tug=dict(_v26717_safe(lambda: _v2672_tug_read(app,now=now), {}) or {})
    move=dict(_v26717_safe(lambda: _v2672_move_budget_read(app,now=now), {}) or {})
    journey=dict(_v26717_safe(lambda: _v2673_journey_read(app,now=now), {}) or {})
    tiger=dict(_v26717_safe(lambda: _v26710_tiger_balance_read(app,now=now), {}) or {})
    sd=dict(_v26717_safe(lambda: _v26710_supply_demand_read(app,now=now), {}) or {})
    whale=dict(_v26717_safe(lambda: app._bookmap_whale_read(now=now), {}) or {})
    sig=dict(getattr(app,'last_signal',{}) or {})
    lock=dict(getattr(app,'opening_lock_snapshot',{}) or {})
    lock_side=str(lock.get('lock_side','WAIT') or 'WAIT').upper()
    if lock_side not in ('UP','DOWN'):
        lock_side=_v26717_text(getattr(getattr(app,'v2676_open_var',None),'get',lambda:'WAIT')()).upper()
    support=_v26717_num(sig.get('support'))
    resistance=_v26717_num(sig.get('resistance'))
    demand=sd.get('demand') if isinstance(sd.get('demand'),dict) else None
    supply=sd.get('supply') if isinstance(sd.get('supply'),dict) else None
    sec_left=max(0.0,900.0-(now%900.0))
    distance=(live-target) if live is not None and target is not None else None
    exp_move=_v26717_num(stat.get('expected_move_dollars'))
    if exp_move is None:
        exp_move=_v26717_num(move.get('budget'))
    flow=dict(tug.get('flow') or {})
    buy_ratio=_v26717_num(flow.get('buy_ratio'),0.5)
    up_force=_v26717_num(tug.get('up_force'),50.0)
    whale_dir=str(whale.get('direction','NEUTRAL') or 'NEUTRAL').upper()
    whale_like=_v26717_num(whale.get('likelihood'),0.0)
    absorption=str(whale.get('absorption','NONE') or 'NONE').upper()
    p_up=_v26717_num(stat.get('p_up'))
    if p_up is not None and p_up <= 1.0: p_up*=100.0
    p_down=None if p_up is None else 100.0-p_up
    return {
        'now':now,'live':live,'live_src':live_src,'target':target,'target_src':target_src,
        'sec_left':sec_left,'distance':distance,'stat':stat,'rev':rev,'tug':tug,'move':move,
        'journey':journey,'tiger':tiger,'sd':sd,'whale':whale,'sig':sig,'lock':lock_side,
        'support':support,'resistance':resistance,'demand':demand,'supply':supply,
        'exp_move':exp_move,'buy_ratio':buy_ratio,'up_force':up_force,
        'whale_dir':whale_dir,'whale_like':whale_like,'absorption':absorption,
        'p_up':p_up,'p_down':p_down,
    }


def _v26717_label(parent,text,fg=_V26717_TEXT,size=9,bold=False,anchor='w'):
    return tk.Label(parent,text=text,bg=_V26717_PANEL,fg=fg,
                    font=('Cascadia Mono',size,'bold' if bold else 'normal'),anchor=anchor)


def _v26717_card(parent,title,accent=_V26717_GRID):
    f=tk.Frame(parent,bg=_V26717_PANEL,highlightthickness=1,highlightbackground=accent,padx=10,pady=8)
    _v26717_label(f,title,_V26717_MUTED,8,True).pack(anchor='w')
    return f


