    app._v26717_top_vars=[]
    titles=['TARGET','LIVE','DISTANCE','TIME LEFT','P(UP)','OPEN LOCK']
    accents=[_V26717_GOLD,_V26717_CYAN,_V26717_TEXT,_V26717_TEXT,_V26717_GREEN,_V26717_PURPLE]
    for i,(title,accent) in enumerate(zip(titles,accents)):
        c=_v26717_card(top,title,accent); c.grid(row=0,column=i,sticky='nsew',padx=(0 if i==0 else 4,0 if i==5 else 4))
        v=tk.StringVar(value='--'); app._v26717_top_vars.append(v)
        tk.Label(c,textvariable=v,bg=_V26717_PANEL,fg=accent,font=('Segoe UI Variable',16,'bold')).pack(anchor='w',pady=(4,0))

    body=tk.Frame(shell,bg=_V26717_BG); body.pack(fill='both',expand=True)
    body.grid_columnconfigure(0,weight=5,minsize=780); body.grid_columnconfigure(1,weight=2,minsize=320)
    body.grid_rowconfigure(0,weight=1)
    left=tk.Frame(body,bg=_V26717_PANEL,highlightthickness=1,highlightbackground=_V26717_GRID)
    left.grid(row=0,column=0,sticky='nsew',padx=(0,8)); left.grid_rowconfigure(1,weight=1); left.grid_columnconfigure(0,weight=1)
    lh=tk.Frame(left,bg=_V26717_PANEL,padx=10,pady=8); lh.grid(row=0,column=0,sticky='ew')
    tk.Label(lh,text='PRICE LADDER / PRESSURE MAP',bg=_V26717_PANEL,fg=_V26717_TEXT,font=('Cascadia Mono',9,'bold')).pack(side='left')
    app._v26717_subhead=tk.StringVar(value='waiting for live Bookmap + target')
    tk.Label(lh,textvariable=app._v26717_subhead,bg=_V26717_PANEL,fg=_V26717_MUTED,font=('Cascadia Mono',8)).pack(side='right')
    cv=tk.Canvas(left,bg=_V26717_BG,highlightthickness=0); cv.grid(row=1,column=0,sticky='nsew')
    app._v26717_canvas=cv

    side=tk.Frame(body,bg=_V26717_BG); side.grid(row=0,column=1,sticky='nsew')
    side.grid_columnconfigure(0,weight=1); side.grid_rowconfigure(0,weight=1); side.grid_rowconfigure(1,weight=1); side.grid_rowconfigure(2,weight=1); side.grid_rowconfigure(3,weight=1)
    app._v26717_side_vars=[]
    side_specs=[
        ('SETTLEMENT REGIME',_V26717_PURPLE),
        ('BOOKMAP FLOW / WHALE',_V26717_CYAN),
        ('REVERSAL / PATH',_V26717_GOLD),
        ('MOVE BUDGET / EXPECTED MOVE',_V26717_GREEN),
    ]
    for r,(title,accent) in enumerate(side_specs):
        c=_v26717_card(side,title,accent); c.grid(row=r,column=0,sticky='nsew',pady=(0 if r==0 else 5,0 if r==3 else 5))
        big=tk.StringVar(value='BUILDING'); small=tk.StringVar(value='--'); app._v26717_side_vars.append((big,small))
        tk.Label(c,textvariable=big,bg=_V26717_PANEL,fg=accent,font=('Segoe UI Variable',12,'bold'),justify='left',anchor='w',wraplength=350).pack(fill='x',pady=(5,2))
        tk.Label(c,textvariable=small,bg=_V26717_PANEL,fg=_V26717_MUTED,font=('Cascadia Mono',8),justify='left',anchor='w',wraplength=350).pack(fill='x')

