def _v26717_bar(cv,x0,x1,y,h,val,color):
    val=max(0.0,min(1.0,float(val)))
    cv.create_rectangle(x0,y-h/2,x1,y+h/2,fill='#111a25',outline='')
    if x1>=x0:
        cv.create_rectangle(x0,y-h/2,x0+(x1-x0)*val,y+h/2,fill=color,outline='')


def _v26717_draw(app,data=None):
    cv=getattr(app,'_v26717_canvas',None)
    if cv is None: return
    try:
        if not cv.winfo_exists(): return
    except Exception:return
    data=data or _v26717_collect(app)
    cv.delete('all')
    w=max(760,int(cv.winfo_width())); h=max(520,int(cv.winfo_height()))
    live=data.get('live'); target=data.get('target')
    if live is None or target is None:
        cv.create_text(w/2,h/2,text='WAITING FOR LIVE BOOKMAP + KALSHI TARGET',fill=_V26717_MUTED,font=('Cascadia Mono',14,'bold'))
        return
    exp=max(12.0,_v26717_num(data.get('exp_move'),40.0) or 40.0)
    vals=[live,target]
    for v in (data.get('support'),data.get('resistance')):
        if v is not None: vals.append(v)
    for zname in ('demand','supply'):
        z=data.get(zname)
        if isinstance(z,dict):
            for k in ('low','high'):
                vv=_v26717_num(z.get(k));
                if vv is not None: vals.append(vv)
    lo=min(min(vals)-exp*0.75,target-exp*1.35)
    hi=max(max(vals)+exp*0.75,target+exp*1.35)
    if hi-lo<80: lo-=40;hi+=40
    left=80; right=w-90; center=(left+right)/2
    lane_left=center-70; lane_right=center+70
    top=48; bottom=h-32
    def yy(price): return top+(hi-price)/(hi-lo)*(bottom-top)

    # Column headings.
    cv.create_text(left+90,22,text='DOWN PRESSURE',fill=_V26717_RED,font=('Cascadia Mono',8,'bold'))
    cv.create_text(center,22,text='PRICE',fill=_V26717_TEXT,font=('Cascadia Mono',8,'bold'))
    cv.create_text(right-90,22,text='UP PRESSURE',fill=_V26717_GREEN,font=('Cascadia Mono',8,'bold'))
    cv.create_line(center,top-8,center,bottom,fill=_V26717_GRID,width=1)

    # Grid levels centered on target and expected move.
    grid_prices=[]
    step=max(10.0,round(exp/3.0/5.0)*5.0)
    for k in range(-6,7): grid_prices.append(target+k*step)
    # Add meaningful exact levels.
    named=[]
    named.append((target,'TARGET',_V26717_GOLD))
    named.append((live,'LIVE',_V26717_CYAN))
    for v,name,col in [
        (data.get('support'),'SUPPORT',_V26717_GREEN),(data.get('resistance'),'RESIST',_V26717_RED)]:
        if v is not None: named.append((v,name,col))
    d=data.get('demand'); s=data.get('supply')
    if isinstance(d,dict):
        for k in ('low','high'):
            v=_v26717_num(d.get(k));
            if v is not None:named.append((v,'DEMAND',_V26717_GREEN))
    if isinstance(s,dict):
        for k in ('low','high'):
            v=_v26717_num(s.get(k));
            if v is not None:named.append((v,'SUPPLY',_V26717_RED))

    # Global pressures from independent families. These are bot-native proxies,
    # deliberately NOT labelled gamma/GEX.
    up=max(0.0,min(1.0,(data.get('up_force',50.0) or 50.0)/100.0))
    flow=max(0.0,min(1.0,data.get('buy_ratio',0.5) or 0.5))
    whale=data.get('whale',{}) or {}; ws=_v26717_num(whale.get('signed_score'),0.0) or 0.0
    whale_up=max(0.0,min(1.0,0.5+ws/160.0))
    rev=data.get('rev',{}) or {}; rside=str(rev.get('side','WAIT')).upper(); rconf=(_v26717_num(rev.get('confidence'),0.0) or 0.0)/100.0
    rev_up=0.5+(rconf/2 if rside=='UP' else -rconf/2 if rside=='DOWN' else 0)
    p_up=data.get('p_up'); stat_up=(p_up/100.0 if p_up is not None else 0.5)
    composite=max(0.02,min(0.98,0.28*up+0.22*flow+0.17*whale_up+0.15*rev_up+0.18*stat_up))

    for p in grid_prices:
        if p<lo or p>hi: continue
        y=yy(p)
        cv.create_line(left,y,right,y,fill='#172131',width=1)
        cv.create_text(center,y,text=f'{p:,.0f}',fill=_V26717_MUTED,font=('Cascadia Mono',7),anchor='c')
        # Pressure gets stronger near current/target corridor, fades outward.
        prox=max(0.18,1.0-abs(p-live)/max(exp*1.8,1.0))
        upv=max(0.03,min(1.0,composite*prox+0.10*(1-prox)))
        dnv=max(0.03,min(1.0,(1-composite)*prox+0.10*(1-prox)))
        _v26717_bar(cv,left,lane_left-12,y,9,dnv,_V26717_RED)
        _v26717_bar(cv,lane_right+12,right,y,9,upv,_V26717_GREEN)

    # Expected move bands.
    for mult,col,label in [(0.5,_V26717_PURPLE,'0.5× EM'),(1.0,_V26717_CYAN,'1.0× EM')]:
        for sign in (-1,1):
            p=live+sign*exp*mult
            if lo<=p<=hi:
                y=yy(p); cv.create_line(left,y,right,y,fill=col,dash=(3,5),width=1)
                cv.create_text(right-4,y-8,text=label,fill=col,font=('Cascadia Mono',7),anchor='e')

    # Named exact levels, on top.
    occupied=[]
    for p,name,col in sorted(named,key=lambda x:x[0],reverse=True):
        if p<lo or p>hi: continue
        y=yy(p); cv.create_line(left,y,right,y,fill=col,width=2)
        ty=y
        while any(abs(ty-o)<14 for o in occupied): ty+=14
        occupied.append(ty)
        cv.create_rectangle(center-90,ty-9,center+90,ty+9,fill=_V26717_PANEL2,outline=col,width=1)
        cv.create_text(center,ty,text=f'{name}  {p:,.2f}',fill=col,font=('Cascadia Mono',8,'bold'))

    # Live marker arrow.
    ly=yy(live)
    cv.create_polygon(center-8,ly,center-22,ly-7,center-22,ly+7,fill=_V26717_CYAN,outline='')
    cv.create_text(left,bottom+14,text=f'Composite UP pressure {composite*100:.0f}%  •  DOWN {(1-composite)*100:.0f}%',
                   fill=_V26717_TEXT,font=('Cascadia Mono',8,'bold'),anchor='w')


def _v26717_schedule_draw(app):
    try:
        if getattr(app,'_v26717_draw_after',None): app.root.after_cancel(app._v26717_draw_after)
    except Exception: pass
    try: app._v26717_draw_after=app.root.after(90,lambda:_v26717_draw(app))
    except Exception: pass


def _v26717_tick(app):
    win=getattr(app,'_v26717_window',None)
    try:
        if win is None or not win.winfo_exists(): return
        if str(win.state())=='withdrawn':
            app.root.after(700,lambda:_v26717_tick(app)); return
    except Exception:return
    d=_v26717_collect(app)
    try:
        app._v26717_clock.set(time.strftime('%H:%M:%S'))
        vals=[
            f"${d['target']:,.2f}" if d['target'] is not None else '--',
            f"${d['live']:,.2f}" if d['live'] is not None else '--',
            f"{d['distance']:+.2f}" if d['distance'] is not None else '--',
            f"{int(d['sec_left']//60):02d}:{int(d['sec_left']%60):02d}",
            f"{d['p_up']:.0f}%" if d['p_up'] is not None else '--',
            d.get('lock','WAIT'),
        ]
        for v,s in zip(app._v26717_top_vars,vals): v.set(s)
        app._v26717_subhead.set(f"{d.get('live_src','--')} • target {d.get('target_src','--')}")
        s0,s1,s2,s3=app._v26717_side_vars
        side=str(d.get('tug',{}).get('side','EVEN')).upper(); force=_v26717_num(d.get('tug',{}).get('force'),50.0) or 50.0
        s0[0].set(f"{side} FORCE {force:.0f}% • LOCK {d.get('lock','WAIT')}")
        ptxt=(f"STAT {d['p_up']:.0f}% UP / {d['p_down']:.0f}% DOWN" if d.get('p_up') is not None else 'STAT BUILDING')
        s0[1].set(ptxt+'\n'+_v26717_text(d.get('tiger',{}).get('text'),'Tiger balance building'))
        flow=d.get('buy_ratio',0.5)*100.0
        s1[0].set(f"FLOW {flow:.0f}% BUY / {100-flow:.0f}% SELL")
        s1[1].set(f"WHALE {d.get('whale_dir','NEUTRAL')} {d.get('whale_like',0):.0f}% • {d.get('absorption','NONE')}")
        rr=d.get('rev',{}); rs=str(rr.get('side','WAIT')).upper(); rc=_v26717_num(rr.get('confidence'),0.0) or 0.0
        s2[0].set(f"REVERSAL {rs} {rc:.0f}%")
        s2[1].set(_v26717_text(rr.get('reason'),'building')+'\n'+_v26717_text(d.get('journey',{}).get('route_text'),'Journey building'))
        mv=d.get('move',{}); viability=_v26717_num(mv.get('viability'))
        em=d.get('exp_move')
        s3[0].set((f"VIABILITY {viability:.0f}/100" if viability is not None else 'VIABILITY BUILDING') + (f" • EM ${em:.0f}" if em is not None else ''))
        s3[1].set(_v26717_text(mv.get('status'),'Move budget building')+'\n'+_v26717_text(mv.get('detail'),'--'))
        app._v26717_footer.set('15M MATRIX • bot-native pressure proxies • no dealer gamma is inferred • 2 Hz refresh')
        _v26717_draw(app,d)
    except Exception:
        pass
    try: app.root.after(500,lambda:_v26717_tick(app))
    except Exception: pass


def _v26717_find_header_and_add_button(app):
    # Add a visible MATRIX button to the existing cockpit header without
    # rewriting V21.67.16 layout. If traversal fails, F9 still works.
    try:
        def walk(w):
            out=[]
            for ch in w.winfo_children():
                out.append(ch); out.extend(walk(ch))
            return out
        for w in walk(app.root):
            try:
                if isinstance(w,tk.Label) and 'PATHS • NOT PREDICTIONS' in str(w.cget('text')):
                    parent=w.master
                    b=tk.Button(parent,text='15M MATRIX',command=lambda:_v26717_build_window(app),
                                bg='#162536',fg=_V26717_CYAN,activebackground='#21364e',activeforeground='white',
                                relief='flat',padx=9,pady=4,font=('Cascadia Mono',8,'bold'))
                    b.pack(side='right',padx=(8,0)); app._v26717_button=b; return True
            except Exception: pass
    except Exception: pass
    return False


_V26717_BASE_INIT = ChartKingPro.__init__
def _v26717_init(self,*args,**kwargs):
    _V26717_BASE_INIT(self,*args,**kwargs)
    self._v26717_window=None; self._v26717_button=None; self._v26717_draw_after=None
    try:
        self.root.bind('<F9>',lambda e:_v26717_build_window(self),add='+')
        self.root.after(350,lambda:_v26717_find_header_and_add_button(self))
    except Exception: pass
ChartKingPro.__init__=_v26717_init

