# ============================================================================
# LECHART JAMES V21.67.19 — PRO GEOMETRY + PATIENT OPEN LOCK + BREAKOUT AUDIT
# ============================================================================
# Goals:
#   1) Give OPEN LOCK a little more time to observe/map the round before the
#      first immutable settlement thesis freezes.
#   2) Build trader-style support/resistance/path lines from meaningful swing
#      wicks and draw them directly on the main chart.
#   3) Upgrade breakout classification so one wick through a level is not enough:
#      require displacement/hold/reclaim evidence plus flow/context agreement.
#   4) Feed geometry into destination only as a bounded independent family.
#      Geometry can help the lock; it can never become sole authority.
#   5) Preserve all Bookmap transport, target, Tiger Stat, Journey, Reversal,
#      Settlement Matrix, and smooth-chart work from V21.67.18.
# ============================================================================

_V26719_RELEASE = 'V21.67.19'
_V26719_BASE_DRAW = ChartKingPro.draw_chart
_V26719_BASE_DESTINATION = _v263_destination_context
_V26719_BASE_BREAKOUT = _v26710_breakout_prediction
_V26719_BASE_OPEN_CORE = _V240_BASE_BOOKMAP_OPEN


def _v26719_clip(v, lo=-1.0, hi=1.0):
    try: return max(lo, min(hi, float(v)))
    except Exception: return 0.0


def _v26719_closed_1m(self, now=None, limit=120):
    now=float(now or time.time())
    rows=_v26710_rows(self,60,max(60,int(limit)+5))
    out=[]
    for r in rows:
        try:
            if float(r.get('time',0) or 0)+60.0<=now:
                q=dict(r)
                for k in ('open','high','low','close'): q[k]=float(q[k])
                q['time']=float(q.get('time',0) or 0)
                out.append(q)
        except Exception:
            continue
    return out[-int(limit):]


def _v26719_true_range_atr(self, rows):
    if not rows: return _v26710_floor(self,2.0)
    vals=[]; prev=None
    for r in rows[-40:]:
        try:
            hi=float(r['high']); lo=float(r['low']); cl=float(r['close'])
            tr=hi-lo if prev is None else max(hi-lo,abs(hi-prev),abs(lo-prev))
            vals.append(max(_v26710_floor(self,.02),tr)); prev=cl
        except Exception: pass
    return max(_v26710_floor(self,.5),_v26710_median(vals,_v26710_floor(self,2.0)))


def _v26719_swings(self, rows, atr):
    """Meaningful wick pivots; avoid treating every tiny zigzag as structure."""
    hi=[]; lo=[]
    if len(rows)<7: return hi,lo
    prom=max(_v26710_floor(self,.25),float(atr)*.16)
    for i in range(2,len(rows)-2):
        r=rows[i]; H=float(r['high']); L=float(r['low']); op=float(r['open']); cl=float(r['close'])
        left=rows[i-2:i]; right=rows[i+1:i+3]
        neigh_hi=max(float(x['high']) for x in left+right)
        neigh_lo=min(float(x['low']) for x in left+right)
        upper=H-max(op,cl); lower=min(op,cl)-L
        rng=max(H-L,_v26710_floor(self,.02))
        # prominence OR a pronounced rejection wick can make a pivot meaningful.
        if H>=neigh_hi and ((H-neigh_hi)>=prom or upper/rng>=.36):
            hi.append({'i':i,'time':float(r['time']),'price':H,'wick':upper/rng})
        if L<=neigh_lo and ((neigh_lo-L)>=prom or lower/rng>=.36):
            lo.append({'i':i,'time':float(r['time']),'price':L,'wick':lower/rng})
    return hi[-10:],lo[-10:]


def _v26719_line_candidates(self, points, rows, atr, kind):
    """Select a line the way a trader would: recent meaningful pivots + touches + few violations."""
    pts=list(points or [])[-7:]
    if len(pts)<2: return None
    tol=max(_v26710_floor(self,.45),atr*.22)
    viol=max(_v26710_floor(self,.8),atr*.38)
    best=None
    for a in range(max(0,len(pts)-6),len(pts)-1):
        for b in range(a+1,len(pts)):
            p1,p2=pts[a],pts[b]
            dt=max(60.0,float(p2['time'])-float(p1['time']))
            slope=(float(p2['price'])-float(p1['price']))/dt
            # Reject absurdly steep two-point noise lines.
            if abs(slope)*60.0 > max(atr*2.6,_v26710_floor(self,18.0)): continue
            touches=0; violations=0; near=[]
            for r in rows[max(0,int(p1['i'])-1):]:
                t=float(r['time']); y=float(p1['price'])+slope*(t-float(p1['time']))
                wick=float(r['low']) if kind=='support' else float(r['high'])
                d=wick-y
                if abs(d)<=tol:
                    touches+=1; near.append(abs(d))
                if kind=='support' and wick<y-viol: violations+=1
                if kind=='resistance' and wick>y+viol: violations+=1
            age=max(0,len(rows)-1-int(p2['i']))
            recency=max(0.0,1.0-age/40.0)
            avgerr=(sum(near)/len(near)) if near else tol*2
            quality=36+12*min(touches,4)+12*recency+8*min(float(p1.get('wick',0))+float(p2.get('wick',0)),1.4)-18*violations-10*min(1.0,avgerr/max(tol,1e-9))
            quality=max(0.0,min(100.0,quality))
            cand={'kind':kind,'p1':p1,'p2':p2,'slope_per_sec':slope,'touches':touches,'violations':violations,'quality':quality,'tol':tol}
            if best is None or cand['quality']>best['quality']: best=cand
    return best


def _v26719_line_price(line, ts):
    if not line: return None
    try:
        p=line['p1']; return float(p['price'])+float(line['slope_per_sec'])*(float(ts)-float(p['time']))
    except Exception: return None


def _v26719_rejection_level(self, rows, pivots, atr, kind):
    """Find a persistent horizontal floor/ceiling from repeated rejection around swing wicks."""
    pts=list(pivots or [])[-8:]
    if not pts: return None
    tol=max(_v26710_floor(self,.55),atr*.28)
    best=None
    for p in pts:
        lvl=float(p['price']); hits=0; hard=0
        for r in rows[-50:]:
            wick=float(r['low']) if kind=='floor' else float(r['high'])
            if abs(wick-lvl)<=tol: hits+=1
            if kind=='floor' and float(r['close'])<lvl-tol*.7: hard+=1
            if kind=='ceiling' and float(r['close'])>lvl+tol*.7: hard+=1
        q=max(0.0,min(100.0,38+13*min(hits,4)+18*float(p.get('wick',0))-22*hard))
        cand={'kind':kind,'price':lvl,'touches':hits,'violations':hard,'quality':q}
        if best is None or q>best['quality']: best=cand
    return best


def _v26719_micro_hold(self, level, side, now=None):
    now=float(now or time.time())
    rows=_v2673_micro_rows(self,5,now=now,limit=18,include_forming=False)
    if not rows: return {'count':0,'ratio':0.0,'reclaim':False}
    recent=rows[-8:]
    closes=[float(r['close']) for r in recent]
    if side=='UP':
        good=sum(1 for c in closes if c>float(level)); reclaim=(min(closes)<float(level) and closes[-1]>float(level)) if len(closes)>=3 else False
    else:
        good=sum(1 for c in closes if c<float(level)); reclaim=(max(closes)>float(level) and closes[-1]<float(level)) if len(closes)>=3 else False
    return {'count':good,'ratio':good/max(1,len(closes)),'reclaim':bool(reclaim),'last':closes[-1]}


def _v26719_pro_geometry_read(self, now=None):
    now=float(now or time.time()); bucket=int(now//900)*900
    cache=dict(getattr(self,'_v26719_geometry_cache',{}) or {})
    if int(cache.get('bucket',-1) or -1)==bucket and now-float(cache.get('ts',0) or 0)<.35:
        return dict(cache.get('value') or {})
    rows=_v26719_closed_1m(self,now=now,limit=96)
    if len(rows)<14:
        val={'ready':False,'text':'PRO MAP: building completed 1m pivots','score':0.0,'side':'WAIT'}
        self._v26719_geometry_cache={'bucket':bucket,'ts':now,'value':val}; return val
    atr=_v26719_true_range_atr(self,rows)
    highs,lows=_v26719_swings(self,rows,atr)
    support=_v26719_line_candidates(self,lows,rows,atr,'support')
    resistance=_v26719_line_candidates(self,highs,rows,atr,'resistance')
    floor=_v26719_rejection_level(self,rows,lows,atr,'floor')
    ceiling=_v26719_rejection_level(self,rows,highs,atr,'ceiling')
    try: live,_src=self.effective_live_price(); live=float(live)
    except Exception: live=float(rows[-1]['close'])
    tnow=now
    sup_now=_v26719_line_price(support,tnow); res_now=_v26719_line_price(resistance,tnow)
    # Price structure from recent meaningful pivots.
    struct=0.0; tags=[]
    if len(lows)>=2:
        dl=float(lows[-1]['price'])-float(lows[-2]['price'])
        if dl>atr*.10: struct+=.24; tags.append('HL')
        elif dl<-atr*.10: struct-=.24; tags.append('LL')
    if len(highs)>=2:
        dh=float(highs[-1]['price'])-float(highs[-2]['price'])
        if dh>atr*.10: struct+=.24; tags.append('HH')
        elif dh<-atr*.10: struct-=.24; tags.append('LH')
    slope_score=0.0
    if support and support['quality']>=45:
        slope_score += math.tanh(float(support['slope_per_sec'])*60/max(atr*.55,1e-9))*.22
    if resistance and resistance['quality']>=45:
        slope_score += math.tanh(float(resistance['slope_per_sec'])*60/max(atr*.55,1e-9))*.22
    level_score=0.0
    if floor and floor['quality']>=58 and live>=float(floor['price']):
        d=(live-float(floor['price']))/max(atr,1e-9)
        level_score += max(0.0,.18*(1-min(d/5.0,1.0)))
    if ceiling and ceiling['quality']>=58 and live<=float(ceiling['price']):
        d=(float(ceiling['price'])-live)/max(atr,1e-9)
        level_score -= max(0.0,.18*(1-min(d/5.0,1.0)))
    channel=0.0
    if sup_now is not None and res_now is not None and res_now>sup_now:
        pos=(live-sup_now)/max(res_now-sup_now,1e-9)
        # proximity to a boundary is context, not an automatic reversal vote.
        channel=max(-1.0,min(1.0,(pos-.5)*2.0))*.08
    score=_v26719_clip(struct+slope_score+level_score+channel,-.85,.85)
    side='UP' if score>=.14 else 'DOWN' if score<=-.14 else 'WAIT'
    # Candidate structural breakout boundaries.
    up_levels=[x for x in (res_now, float(ceiling['price']) if ceiling else None) if x is not None]
    dn_levels=[x for x in (sup_now, float(floor['price']) if floor else None) if x is not None]
    up_boundary=max(up_levels) if up_levels else max(float(r['high']) for r in rows[-18:-1])
    dn_boundary=min(dn_levels) if dn_levels else min(float(r['low']) for r in rows[-18:-1])
    buffer=max(_v26710_floor(self,.65),min(_v26710_floor(self,12.0),atr*.11))
    up_hold=_v26719_micro_hold(self,up_boundary+buffer,'UP',now)
    dn_hold=_v26719_micro_hold(self,dn_boundary-buffer,'DOWN',now)
    try: tug=dict(_v2672_tug_read(self,now=now) or {})
    except Exception: tug={}
    up_force=float(tug.get('up_force',50.0) or 50.0)
    try: whale=dict(self._bookmap_whale_read(now=now) or {})
    except Exception: whale={}
    wdir=str(whale.get('direction','NEUTRAL') or 'NEUTRAL').upper(); wlike=float(whale.get('likelihood',0.0) or 0.0)
    # Breakout confirmation: distance + repeated 5s acceptance/reclaim + independent flow support.
    up_dist=(live-(up_boundary+buffer))/max(atr,1e-9)
    dn_dist=((dn_boundary-buffer)-live)/max(atr,1e-9)
    up_flow=(up_force>=56 or (wdir=='UP' and wlike>=58))
    dn_flow=(up_force<=44 or (wdir=='DOWN' and wlike>=58))
    up_confirm=up_dist>0 and (up_hold['ratio']>=.50 or up_hold['reclaim']) and up_flow
    dn_confirm=dn_dist>0 and (dn_hold['ratio']>=.50 or dn_hold['reclaim']) and dn_flow
    breakout='UP CONFIRMED' if up_confirm else 'DOWN CONFIRMED' if dn_confirm else 'UP WATCH' if live>=up_boundary-buffer*.4 else 'DOWN WATCH' if live<=dn_boundary+buffer*.4 else 'INSIDE STRUCTURE'
    qvals=[x['quality'] for x in (support,resistance,floor,ceiling) if x]
    quality=(sum(qvals)/len(qvals)) if qvals else 0.0
    val={'ready':True,'score':score,'side':side,'quality':quality,'atr':atr,'live':live,
         'support_line':support,'resistance_line':resistance,'support_now':sup_now,'resistance_now':res_now,
         'floor':floor,'ceiling':ceiling,'swing_highs':highs,'swing_lows':lows,
         'up_boundary':up_boundary,'down_boundary':dn_boundary,'buffer':buffer,
         'up_hold':up_hold,'down_hold':dn_hold,'up_confirmed':up_confirm,'down_confirmed':dn_confirm,
         'breakout_state':breakout,'up_force':up_force,'whale_direction':wdir,'whale_likelihood':wlike,
         'text':f"PRO MAP: {side} {score:+.2f} • {'+'.join(tags[-2:]) or 'mixed swings'} • {breakout} • map quality {quality:.0f}/100"}
    self._v26719_geometry_cache={'bucket':bucket,'ts':now,'value':dict(val)}
    self._v26719_geometry_last=dict(val)
    return val


# Bounded geometry family inside destination context. It cannot manufacture a lock.
def _v26719_destination_context(self, warm=None, now=None):
    base=dict(_V26719_BASE_DESTINATION(self,warm=warm,now=now) or {})
    geo=_v26719_pro_geometry_read(self,now=now)
    original=float(base.get('score',0.0) or 0.0)
    mod=0.0
    if geo.get('ready'):
        g=float(geo.get('score',0.0) or 0.0)
        q=max(0.0,min(1.0,float(geo.get('quality',0.0) or 0.0)/100.0))
        mod=g*(.055+.055*q)  # hard family cap ~ +/-0.094
        if geo.get('up_confirmed'): mod+=.025
        if geo.get('down_confirmed'): mod-=.025
    mod=max(-.11,min(.11,mod))
    score=_v252_clip(original+mod,-_V263_PINE_CAP,_V263_PINE_CAP)
    side='UP' if score>=.12 else 'DOWN' if score<=-.12 else 'WAIT'
    why=str(base.get('reason',''))
    if geo.get('ready'): why=(why+' • '+str(geo.get('text',''))).strip(' •')
    base.update({'score':score,'side':side,'pro_geometry':geo,'v26719_geometry_modifier':mod,
                 'v26719_base_score':original,'reason':why})
    self._v263_destination_last=base
    return base


# Longer mapping gate BEFORE the immutable Open Lock core is allowed to freeze.
def _v26719_patient_open_core(self, warm, now=None):
    now=float(now or time.time()); bucket=_v240_bucket(now)
    st=dict(getattr(self,'_v26719_open_gate',{}) or {})
    if int(st.get('bucket',-1) or -1)!=bucket:
        st={'bucket':bucket,'first_ready':0.0,'map_side':'WAIT','map_side_since':0.0,'last_geo':'WAIT'}
    # Never interfere with an already-earned frozen opening call.
    if getattr(self,'opening_lock_snapshot',None):
        self._v26719_open_gate=st
        return _V26719_BASE_OPEN_CORE(self,warm,now=now)
    try: live,_=self.effective_live_price()
    except Exception: live=None
    try: target,_=self.effective_target()
    except Exception: target=None
    geo=_v26719_pro_geometry_read(self,now=now)
    try: data=_v263_data_ceiling(self,warm=warm,now=now)
    except Exception: data={}
    tape_ready=bool((data.get('families') or {}).get('tape',{}).get('available'))
    ready=(live is not None and target is not None and tape_ready)
    if not ready:
        st['first_ready']=0.0; st['map_side_since']=0.0; st['map_side']='WAIT'; self._v26719_open_gate=st
        try: self.opening_lock_var.set('OPEN LOCK: PRO MAPPING • waiting for live Bookmap + target + fresh tape')
        except Exception: pass
        return None
    if not st.get('first_ready'): st['first_ready']=now
    observed=max(0.0,now-float(st['first_ready']))
    # Monitor the combined map side. A flip restarts the short stability timer.
    try:
        card=_v252_scorecard(data.get('families',{}),_V252_BOOK_WEIGHTS)
        core=float(card.get('edge',0.0) or 0.0)
    except Exception: core=0.0
    try: dest=float((_v26719_destination_context(self,warm=warm,now=now) or {}).get('score',0.0) or 0.0)
    except Exception: dest=0.0
    ge=float(geo.get('score',0.0) or 0.0) if geo.get('ready') else 0.0
    combined=.62*core+.25*dest+.13*ge
    mside='UP' if combined>=.18 else 'DOWN' if combined<=-.18 else 'WAIT'
    if mside!=st.get('map_side'):
        st['map_side']=mside; st['map_side_since']=now
    stable=max(0.0,now-float(st.get('map_side_since',now) or now)) if mside in ('UP','DOWN') else 0.0
    st['last_geo']=str(geo.get('side','WAIT')); self._v26719_open_gate=st
    # Give the market enough time to actually print a route. Strong clean maps can
    # pass at ~6.5s; mixed maps get ~9s before the old core begins formulation.
    geo_q=float(geo.get('quality',0.0) or 0.0)
    need_obs=6.5 if geo.get('ready') and geo_q>=62 and mside in ('UP','DOWN') else 8.8
    need_stable=2.0 if abs(combined)>=.42 else 3.0
    # If geometry is unavailable, do not deadlock startup forever.
    if observed<need_obs or (mside in ('UP','DOWN') and stable<need_stable):
        try:
            self.opening_lock_var.set(f'OPEN LOCK: PRO MAPPING {observed:.1f}/{need_obs:.1f}s • map {mside} {combined:+.2f} • stability {stable:.1f}/{need_stable:.1f}s • {geo.get("text","geometry building")}')
        except Exception: pass
        return None
    # Now allow the proven V21.63 core to formulate/freeze. Its own family breadth
    # and clean-observation requirements remain intact.
    return _V26719_BASE_OPEN_CORE(self,warm,now=now)


# Better breakout map: structural boundary + acceptance + flow, not "second high + buffer" alone.
def _v26719_breakout_prediction(self, now=None):
    now=float(now or time.time())
    geo=_v26719_pro_geometry_read(self,now=now)
    if not geo.get('ready'):
        return _V26719_BASE_BREAKOUT(self,now=now)
    try: base=dict(_V26719_BASE_BREAKOUT(self,now=now) or {})
    except Exception: base={}
    up=float(geo['up_boundary'])+float(geo['buffer']); down=float(geo['down_boundary'])-float(geo['buffer'])
    score=float(geo.get('score',0.0) or 0.0); up_force=float(geo.get('up_force',50.0) or 50.0)
    up_hold=dict(geo.get('up_hold') or {}); dn_hold=dict(geo.get('down_hold') or {})
    # Confidence rewards independent agreement and actual acceptance beyond boundary.
    up_conf=50+score*24+(up_force-50)*.34+float(up_hold.get('ratio',0))*14-float(dn_hold.get('ratio',0))*6
    if geo.get('up_confirmed'): up_conf+=12
    if geo.get('down_confirmed'): up_conf-=12
    up_conf=max(4.0,min(96.0,up_conf)); down_conf=100-up_conf
    primary='UP CONFIRMED' if geo.get('up_confirmed') else 'DOWN CONFIRMED' if geo.get('down_confirmed') else 'UP WATCH' if up_conf>=60 else 'DOWN WATCH' if down_conf>=60 else 'WAIT / TWO-SIDED'
    text=(f'PRO BREAK MAP: UP > {money(up)} {up_conf:.0f}% • DOWN < {money(down)} {down_conf:.0f}% • {primary} • '
          f'5s hold U {float(up_hold.get("ratio",0))*100:.0f}% / D {float(dn_hold.get("ratio",0))*100:.0f}%')
    base.update({'ready':True,'live':geo.get('live'),'up_trigger':up,'down_trigger':down,
                 'up_confidence':up_conf,'down_confidence':down_conf,'primary':primary,
                 'buffer':geo.get('buffer'),'atr':geo.get('atr'),'pro_geometry':geo,'text':text,
                 'note':'pivot/channel boundary + 5s acceptance/reclaim + Bookmap flow; single wick is NOT confirmation'})
    return base


def _v26719_draw_geometry(self):
    c=getattr(self,'canvas',None); scale=dict(getattr(self,'_v82_chart_scale',{}) or {})
    if c is None or not scale: return
    try:
        c.delete('v26719')
        geo=_v26719_pro_geometry_read(self)
        if not geo.get('ready'): return
        lo=float(scale['lo']); hi=float(scale['hi']); top=float(scale['top']); ph=float(scale['ph'])
        left=float(scale['left']); right=float(scale['plot_right'])
        rows=_v26719_closed_1m(self,limit=96); now=time.time()
        if not rows: return
        t0=float(rows[max(0,len(rows)-55)]['time']); t1=now+180.0
        def yy(p): return top+(hi-float(p))/max(hi-lo,1e-12)*ph
        def xx(t): return left+(float(t)-t0)/max(t1-t0,1.0)*(right-left)
        # Pro-style dynamic support/resistance path lines extended slightly forward.
        for line,color,label in ((geo.get('support_line'),'#35d6ff','PRO SUPPORT PATH'),(geo.get('resistance_line'),'#8d7cff','PRO RESIST PATH')):
            if not line or float(line.get('quality',0))<38: continue
            ta=max(t0,float(line['p1']['time'])); tb=t1
            pa=_v26719_line_price(line,ta); pb=_v26719_line_price(line,tb)
            if pa is None or pb is None: continue
            c.create_line(xx(ta),yy(pa),xx(tb),yy(pb),fill=color,width=2,dash=(10,4),tags='v26719')
            c.create_text(right-8,yy(pb)-8,text=f"{label} • {float(line.get('quality',0)):.0f}/100",fill=color,anchor='e',font=('Cascadia Mono',7,'bold'),tags='v26719')
        # Horizontal floor / ceiling built from rejection wicks.
        for z,color,label in ((geo.get('floor'),'#20e39a','WICK FLOOR'),(geo.get('ceiling'),'#ff667f','WICK CEILING')):
            if not z or float(z.get('quality',0))<45: continue
            y=yy(float(z['price']))
            c.create_line(left,y,right,y,fill=color,width=1,dash=(4,5),tags='v26719')
            c.create_text(left+8,y-7,text=f"{label} {money(z['price'])} • {int(z.get('touches',0))} tests",fill=color,anchor='w',font=('Cascadia Mono',7,'bold'),tags='v26719')
        # Pivot anchors, small and unobtrusive.
        for p in (geo.get('swing_lows') or [])[-5:]:
            if t0<=float(p['time'])<=now:
                x=xx(p['time']); y=yy(p['price']); c.create_oval(x-3,y-3,x+3,y+3,fill='#20e39a',outline='',tags='v26719')
        for p in (geo.get('swing_highs') or [])[-5:]:
            if t0<=float(p['time'])<=now:
                x=xx(p['time']); y=yy(p['price']); c.create_oval(x-3,y-3,x+3,y+3,fill='#ff667f',outline='',tags='v26719')
        # Compact live read so the user can see exactly what geometry thinks.
        txt=str(geo.get('text',''))
        c.create_rectangle(left+8,top+82,min(right-8,left+720),top+106,fill='#07131b',outline='#35d6ff',width=1,tags='v26719')
        c.create_text(left+16,top+94,text=txt[:155],fill='#d8f5ff',anchor='w',font=('Cascadia Mono',7,'bold'),tags='v26719')
    except Exception:
        pass


def _v26719_draw_chart(self,*args,**kwargs):
    out=_V26719_BASE_DRAW(self,*args,**kwargs)
    try: _v26719_draw_geometry(self)
    except Exception: pass
    return out


def _v26719_reset_geo(self):
    self._v26719_geometry_cache={}; self._v26719_geometry_last={}; self._v26719_open_gate={}


_V26719_BASE_RESET_CONTROL = ChartKingPro._v237_reset_round_control
_V26719_BASE_RESET_MARKET = ChartKingPro.reset_market_state

