# ============================================================================
# LECHART JAMES V21.67.20 — ADAPTIVE OPEN LOCK SPEED FIX
# ============================================================================
# V21.67.19 made the map gate too patient: a directional map flip could keep
# restarting a 2-3 second stability timer, so normal noisy 15m opens could sit
# in PRO MAPPING far longer than intended.  V21.67.20 keeps the geometry-first
# idea but makes it adaptive and gives the proven V21.63 core a hard handoff.
#
# IMPORTANT: this does NOT force a lock and does not alter an already frozen
# Open Lock.  It only controls how long the geometry pre-map is allowed to hold
# the existing evidence core back.
# ============================================================================

_V26720_RELEASE = 'V21.67.20'


def _v26720_fast_patient_open_core(self, warm, now=None):
    now=float(now or time.time()); bucket=_v240_bucket(now)
    st=dict(getattr(self,'_v26720_open_gate',{}) or {})
    if int(st.get('bucket',-1) or -1)!=bucket:
        st={'bucket':bucket,'first_ready':0.0,'dir_side':'WAIT','dir_since':0.0,
            'last_dir_ts':0.0,'last_combined':0.0}

    # Frozen means frozen. Never re-map an earned opening thesis.
    if getattr(self,'opening_lock_snapshot',None):
        self._v26720_open_gate=st
        return _V26719_BASE_OPEN_CORE(self,warm,now=now)

    try: live,_=self.effective_live_price()
    except Exception: live=None
    try: target,_=self.effective_target()
    except Exception: target=None
    try: data=_v263_data_ceiling(self,warm=warm,now=now)
    except Exception: data={}
    tape_ready=bool((data.get('families') or {}).get('tape',{}).get('available'))

    if live is None or target is None or not tape_ready:
        st['first_ready']=0.0; st['dir_side']='WAIT'; st['dir_since']=0.0; st['last_dir_ts']=0.0
        self._v26720_open_gate=st
        try: self.opening_lock_var.set('OPEN LOCK: FAST MAP • waiting for live Bookmap + target + fresh tape')
        except Exception: pass
        return None

    if not st.get('first_ready'): st['first_ready']=now
    observed=max(0.0,now-float(st['first_ready']))

    geo=_v26719_pro_geometry_read(self,now=now)
    try:
        card=_v252_scorecard(data.get('families',{}),_V252_BOOK_WEIGHTS)
        core=float(card.get('edge',0.0) or 0.0)
    except Exception: core=0.0
    try: dest=float((_v26719_destination_context(self,warm=warm,now=now) or {}).get('score',0.0) or 0.0)
    except Exception: dest=0.0
    ge=float(geo.get('score',0.0) or 0.0) if geo.get('ready') else 0.0
    combined=.64*core+.24*dest+.12*ge
    st['last_combined']=combined

    # A brief neutral wobble should not erase a useful directional map. Only an
    # actual opposite directional read restarts the stability timer.
    raw_side='UP' if combined>=.16 else 'DOWN' if combined<=-.16 else 'WAIT'
    current=str(st.get('dir_side','WAIT')).upper()
    if raw_side in ('UP','DOWN'):
        if current not in ('UP','DOWN') or raw_side!=current:
            st['dir_side']=raw_side; st['dir_since']=now
        st['last_dir_ts']=now
    elif current in ('UP','DOWN') and now-float(st.get('last_dir_ts',0.0) or 0.0)>1.10:
        # Only forget the directional map after a genuinely neutral spell.
        st['dir_side']='WAIT'; st['dir_since']=0.0

    directional=str(st.get('dir_side','WAIT')).upper()
    stable=(max(0.0,now-float(st.get('dir_since',now) or now))
            if directional in ('UP','DOWN') else 0.0)
    self._v26720_open_gate=st

    q=float(geo.get('quality',0.0) or 0.0)
    strength=abs(combined)
    if geo.get('ready') and q>=66 and strength>=.34:
        need_obs,need_stable=2.0,.65
    elif strength>=.25:
        need_obs,need_stable=2.8,.90
    else:
        need_obs,need_stable=3.6,1.10

    # Absolute deadline: geometry is an observation aid, never a deadlock. Once
    # fresh target+tape have existed for 4.5s, hand authority to the existing
    # V21.63 evidence core even if the shape is still choppy.
    hard_release=4.5
    gate_ready=(observed>=need_obs and (directional=='WAIT' or stable>=need_stable))
    if not gate_ready and observed<hard_release:
        try:
            self.opening_lock_var.set(
                f'OPEN LOCK: FAST MAP {observed:.1f}/{need_obs:.1f}s • '
                f'map {directional} {combined:+.2f} • stability {stable:.1f}/{need_stable:.1f}s • '
                f'{geo.get("text","geometry building")}'
            )
        except Exception: pass
        return None

    # Hand off immediately to the proven evidence core. That core still decides
    # whether the evidence is strong enough to earn an immutable lock.
    return _V26719_BASE_OPEN_CORE(self,warm,now=now)


def _v26720_reset_geo(self):
    self._v26720_open_gate={}


_V26720_BASE_RESET_CONTROL = ChartKingPro._v237_reset_round_control
_V26720_BASE_RESET_MARKET = ChartKingPro.reset_market_state

