# ============================================================================
# LECHART JAMES V21.67.21 — OPEN LOCK FORMULATION / GOLD ROUTE FIX
# ============================================================================
# V21.67.20 fixed the geometry deadlock, but the inherited V21.63 core could
# still remain at BUILDING forever when its strict two-family + path thresholds
# never crossed together.  That left Journey/Gold Route at 0/100 because the
# Journey Mapper intentionally waits for an earned Open Lock.
#
# V21.67.21 preserves the patient pre-map, then adds a bounded formulation
# assist.  It cannot lock from one sensor, cannot override strong opposition,
# and cannot use Kalshi odds.  It merely lets broad moderate evidence formulate
# instead of demanding two unusually strong core-family prints at the same tick.
# ============================================================================

_V26721_RELEASE = 'V21.67.21'


def _v26721_sign(side):
    s=str(side or 'WAIT').upper()
    return 1.0 if s=='UP' else -1.0 if s=='DOWN' else 0.0


def _v26721_open_formulation_assist(self, warm, now=None):
    now=float(now or time.time()); bucket=_v240_bucket(now)

    # First preserve V20's patient map gate and the proven V21.63 lock path.
    snap=_v26720_fast_patient_open_core(self,warm,now=now)
    if snap or getattr(self,'opening_lock_snapshot',None):
        return snap

    gate=dict(getattr(self,'_v26720_open_gate',{}) or {})
    if int(gate.get('bucket',-1) or -1)!=bucket or not gate.get('first_ready'):
        return None
    observed=max(0.0,now-float(gate.get('first_ready',now) or now))

    # Do not interfere while V20 is still intentionally mapping the opening.
    if observed < 2.0:
        return None

    last=dict(getattr(self,'_v252_bookmap_last',{}) or {})
    data=dict(last.get('data') or {})
    families=dict(last.get('families') or data.get('families') or {})
    if not families:
        try:
            data=_v263_data_ceiling(self,warm=warm,now=now)
            families=dict(data.get('families') or {})
        except Exception:
            return None

    tape=dict(families.get('tape') or {})
    if not tape.get('available'):
        return None

    # If the legacy core is already FORMULATING a real candidate, leave it alone.
    base_candidate=str(last.get('candidate','WAIT') or 'WAIT').upper()
    if base_candidate in ('UP','DOWN'):
        return None

    try:
        card=_v252_scorecard(families,_V252_BOOK_WEIGHTS,threshold=.18,
                             support_threshold=.09,oppose_threshold=.24)
    except Exception:
        card={}
    core=float(last.get('edge_ema',last.get('core_edge',card.get('edge',0.0))) or 0.0)

    try: dest=dict(_v26719_destination_context(self,warm=warm,now=now) or {})
    except Exception: dest={}
    dscore=float(dest.get('score',0.0) or 0.0) if dest.get('ready',True) else 0.0

    try: geo=dict(_v26719_pro_geometry_read(self,now=now) or {})
    except Exception: geo={}
    gscore=float(geo.get('score',0.0) or 0.0) if geo.get('ready') else 0.0

    try: tug=dict(_v2672_tug_read(self,now=now) or {})
    except Exception: tug={}
    tscore=float(tug.get('fused',0.0) or 0.0) if tug.get('ready') else 0.0

    # Core remains authority. Destination/geometry/Tug only help a near-threshold
    # core thesis become formulatable; their combined influence is deliberately
    # bounded so they cannot manufacture a side from a flat core.
    context=max(-.24,min(.24,.11*dscore + .08*gscore + .05*tscore))
    assist=max(-1.0,min(1.0,.86*core + context))

    side='UP' if assist>=.15 else 'DOWN' if assist<=-.15 else 'WAIT'
    sign=_v26721_sign(side)

    aligned=0; opposed=0; available=0
    scores={}
    for name in ('tape','whale','structure','target'):
        row=dict(families.get(name) or {})
        if not row.get('available'): continue
        available+=1
        sc=float(row.get('score',0.0) or 0.0); scores[name]=sc
        if sign and sc*sign>=.075: aligned+=1
        if sign and sc*sign<=-.26: opposed+=1

    path_ok=False
    if sign:
        for name in ('structure','target'):
            row=dict(families.get(name) or {})
            if row.get('available') and float(row.get('score',0.0) or 0.0)*sign>=.055:
                path_ok=True
        if geo.get('ready') and gscore*sign>=.10: path_ok=True
        if dscore*sign>=.10: path_ok=True

    # By ~4.5s the V20 geometry gate has already yielded.  Moderate, broad,
    # coherent evidence is enough to FORMULATE, but never if opposition is broad.
    qualified=(side in ('UP','DOWN') and available>=2 and aligned>=1 and opposed<=1 and path_ok)
    if observed>=5.5 and side in ('UP','DOWN') and available>=3 and opposed==0 and abs(assist)>=.13:
        qualified=True

    st=dict(getattr(self,'_v26721_assist_state',{}) or {})
    if int(st.get('bucket',-1) or -1)!=bucket:
        st={'bucket':bucket,'candidate':'WAIT','samples':0,'since':0.0,'assist':0.0}

    if not qualified:
        st['candidate']='WAIT'; st['samples']=max(0,int(st.get('samples',0) or 0)-1); st['since']=0.0
        st['assist']=assist; self._v26721_assist_state=st
        # Make the reason visible instead of a mysterious Gold Route 0/100.
        try:
            self.opening_lock_var.set(
                f'OPEN LOCK: BUILDING • route preflight {assist:+.2f} • '
                f'{aligned} aligned / {opposed} oppose / {available} ready • '
                f'waiting for coherent path evidence'
            )
        except Exception: pass
        return None

    old=str(st.get('candidate','WAIT') or 'WAIT').upper()
    if old!=side:
        st['candidate']=side; st['samples']=1; st['since']=now
    else:
        st['samples']=int(st.get('samples',0) or 0)+1
    st['assist']=assist; self._v26721_assist_state=st

    # Strong broad agreement locks after ~4 clean ticks; a weaker assist gets 6.
    strong=(abs(assist)>=.30 and aligned>=2 and opposed==0)
    needed=4 if strong else 6
    self.opening_lock_candidate=side
    if not float(getattr(self,'opening_lock_candidate_since',0.0) or 0.0):
        self.opening_lock_candidate_since=float(st.get('since',now) or now)

    try:
        self.opening_lock_var.set(
            f'OPEN LOCK: FORMULATING {side} • {int(st["samples"])}/{needed} clean observations • '
            f'route {assist:+.2f} • {aligned} aligned / {opposed} oppose • '
            f'geo {gscore:+.2f} • dest {dscore:+.2f}'
        )
    except Exception: pass

    if int(st['samples']) < needed:
        return None

    try: live,_=self.effective_live_price()
    except Exception: live=None
    if live is None:
        return None

    grade='STRAIGHT' if strong else 'LEAN'
    reasons=(f'V21.67.21 {grade} • patient map completed • formulation assist {assist:+.2f} • '
             f'{aligned} aligned / {opposed} oppose / {available} ready • '
             f'core {core:+.2f} • destination {dscore:+.2f} • geometry {gscore:+.2f} • tug {tscore:+.2f}')
    snap={'time':now,'price':float(live),'lock_side':side,'lock_remaining':'OPEN','lock_minute':0,
          'forecast_score':assist*10.0,'forecast_threshold':1.5,'forecast_reasons':reasons,
          'source':'BOOKMAP OPEN/NOW • V21.67.21 PATIENT FORMULATION'}
    self.opening_lock_snapshot=dict(snap)
    self.opening_lock_candidate=None; self.opening_lock_candidate_since=0.0

    # Keep the downstream Journey/Matrix read populated so Gold Route starts
    # immediately instead of displaying 0/100 after the lock appears.
    enriched=dict(last)
    enriched.update({'candidate':side,'edge':assist,'edge_ema':assist,
                     'support':aligned,'oppose':opposed,'available':available,
                     'v26721_assist':True,'v26721_scores':scores,'data':data,'families':families})
    self._v252_bookmap_last=enriched
    self._v252_bookmap_frozen=dict(enriched)
    try:
        self.opening_lock_var.set(
            f'OPEN LOCK: {side} LOCKED @ {money(live)} • V21.67.21 {grade} • '
            f'route {assist:+.2f} • {aligned} aligned / {opposed} oppose'
        )
    except Exception: pass
    try: self._checkpoint_status_summary()
    except Exception: pass
    return snap


