# ============================================================================
# LECHART JAMES V21.67.16 — WIDE CHART + SILKY LIVE CANDLE
# UI-only/performance layer. Trading brain, Open Lock, target acquisition,
# Bookmap native transport, Reversal Read, Journey/Tug, and Tiger Stat remain
# untouched.  The expensive full chart stays throttled; only the forming candle
# and live-price marker are animated at a light 16 FPS cadence.
# ============================================================================
_V26716_RELEASE = 'V21.67.16'
_V26716_BASE_DRAW_CHART = ChartKingPro.draw_chart
_V26716_BASE_INIT = ChartKingPro.__init__


def _v26716_visible_rows(self):
    try:
        rows = list(self._chart_candles() or [])
        if not rows:
            return []
        pan = max(0, int(getattr(self, 'chart_pan_offset', 0) or 0))
        end = max(1, len(rows) - pan)
        start = max(0, end - int(getattr(self, 'visible_count', 40) or 40))
        return rows[start:end]
    except Exception:
        return []


def _v26716_refresh_fast_geometry(self):
    """Cache only geometry needed to animate the forming candle cheaply."""
    try:
        c = getattr(self, 'canvas', None)
        scale = dict(getattr(self, '_v82_chart_scale', {}) or {})
        rows = _v26716_visible_rows(self)
        if c is None or not scale or not rows:
            self._v26716_fast_geometry = None
            return None
        w = max(float(c.winfo_width()), 300.0)
        left = float(scale['left'])
        plot_right = float(scale['plot_right'])
        top = float(scale['top'])
        ph = float(scale['ph'])
        lo = float(scale['lo'])
        hi = float(scale['hi'])
        future_space = max(90.0, min(190.0, (plot_right-left)*0.14))
        pw = max(plot_right-left-future_space, 50.0)
        n = max(1, len(rows))
        step = pw / n
        last_x = left + (n - 0.5) * step
        geom = {
            'canvas': c, 'left': left, 'plot_right': plot_right,
            'top': top, 'ph': ph, 'lo': lo, 'hi': hi,
            'step': step, 'last_x': last_x,
            'bucket': int(rows[-1].get('time', 0) or 0),
            'pan': max(0, int(getattr(self, 'chart_pan_offset', 0) or 0)),
        }
        self._v26716_fast_geometry = geom
        return geom
    except Exception:
        self._v26716_fast_geometry = None
        return None


def _v26716_draw_chart(self, *args, **kwargs):
    out = _V26716_BASE_DRAW_CHART(self, *args, **kwargs)
    try:
        _v26716_refresh_fast_geometry(self)
        self._v26716_full_draw_bucket = int(time.time() // max(1, int(getattr(self, 'chart_interval_seconds', 60) or 60)))
    except Exception:
        pass
    return out


def _v26716_fast_live_candle(self):
    """Animate only two Tk items + the existing live-price line; no full redraw."""
    try:
        if bool(getattr(self, 'web_only_mode', False)):
            return False
        if time.time() < float(getattr(self, '_scroll_active_until', 0.0) or 0.0):
            return False
        # When the cockpit is hidden, don't spend paint work on it.
        if hasattr(self, '_v2676_showing') and not bool(getattr(self, '_v2676_showing', True)):
            return False
        g = getattr(self, '_v26716_fast_geometry', None)
        c = getattr(self, 'canvas', None)
        if not g or c is None or g.get('canvas') is not c:
            g = _v26716_refresh_fast_geometry(self)
        if not g or int(g.get('pan', 0) or 0) != 0:
            return False

        sec = max(1, int(getattr(self, 'chart_interval_seconds', 60) or 60))
        try:
            row = dict(self._current_bucket_for_interval(sec) or {})
        except Exception:
            rows = _v26716_visible_rows(self)
            row = dict(rows[-1]) if rows else {}
        if not row:
            return False
        bucket = int(row.get('time', 0) or 0)
        # A new candle needs one normal redraw so axes/overlays/history advance.
        if bucket and bucket != int(g.get('bucket', 0) or 0):
            if bucket != int(getattr(self, '_v26716_redraw_requested_bucket', -1) or -1):
                self._v26716_redraw_requested_bucket = bucket
                self._last_chart_render_key = None
                try:
                    self.root.after_idle(self.draw_chart)
                except Exception:
                    pass
            return False

        lo, hi = float(g['lo']), float(g['hi'])
        if hi <= lo:
            return False
        top, ph = float(g['top']), float(g['ph'])
        def yy(p):
            y = top + (hi - float(p)) / (hi - lo) * ph
            return max(top, min(top + ph, y))

        op = float(row.get('open', row.get('close', 0.0)) or 0.0)
        hi_p = float(row.get('high', op) or op)
        lo_p = float(row.get('low', op) or op)
        cl = float(row.get('close', op) or op)
        x = float(g['last_x'])
        half = max(2.0, min(10.0, float(g['step']) * 0.31))
        yo, yh, yl, yc = yy(op), yy(hi_p), yy(lo_p), yy(cl)
        body_top, body_bottom = min(yo, yc), max(yo, yc)
        if body_bottom - body_top < 2.0:
            body_bottom = body_top + 2.0
        bull = cl >= op
        fill = '#16c784' if bull else '#ea3943'
        outline = '#72f2b2' if bull else '#ff7f94'

        ids = getattr(self, '_v26716_live_candle_items', None)
        valid = False
        if ids:
            try:
                valid = all(c.type(i) for i in ids)
            except Exception:
                valid = False
        if not valid:
            try: c.delete('v26716_live_candle')
            except Exception: pass
            wick = c.create_line(x, yh, x, yl, fill=outline, width=2, tags=('v26716_live_candle',))
            body = c.create_rectangle(x-half, body_top, x+half, body_bottom,
                                      fill=fill, outline=outline, width=1,
                                      tags=('v26716_live_candle',))
            ids = (wick, body)
            self._v26716_live_candle_items = ids
        wick, body = ids
        c.coords(wick, x, yh, x, yl)
        c.coords(body, x-half, body_top, x+half, body_bottom)
        c.itemconfigure(wick, fill=outline)
        c.itemconfigure(body, fill=fill, outline=outline)
        c.tag_raise('v26716_live_candle')
        try:
            live, source = self.effective_live_price()
            if live is not None:
                self._v82_update_live_chart_overlay(float(live), source)
                c.tag_raise('v82_live')
        except Exception:
            pass
        return True
    except Exception:
        return False


def _v26716_animation_tick(self):
    started = time.perf_counter()
    try:
        _v26716_fast_live_candle(self)
    except Exception:
        pass
    elapsed = (time.perf_counter() - started) * 1000.0
    prior = float(getattr(self, '_v26716_anim_ema_ms', 0.0) or 0.0)
    self._v26716_anim_ema_ms = elapsed if prior <= 0 else prior * .92 + elapsed * .08
    # Self-throttle if Tk is under load.  Normally ~16 FPS; backs off to 10/7 FPS.
    delay = 60
    if self._v26716_anim_ema_ms >= 10.0:
        delay = 95
    if self._v26716_anim_ema_ms >= 18.0 or time.time() < float(getattr(self, '_v256_protect_until', 0.0) or 0.0):
        delay = 140
    try:
        self.root.after(delay, lambda s=self: _v26716_animation_tick(s))
    except Exception:
        pass


def _v26716_init(self, *args, **kwargs):
    _V26716_BASE_INIT(self, *args, **kwargs)
    self._v26716_fast_geometry = None
    self._v26716_live_candle_items = None
    self._v26716_redraw_requested_bucket = -1
    self._v26716_anim_ema_ms = 0.0
    # Cosmetics can update slower; decision/Bookmap ingestion cadences are unchanged.
    try:
        self.right_panel_interval = max(float(getattr(self, 'right_panel_interval', 1.25) or 1.25), 1.45)
    except Exception:
        pass
    try:
        self.root.after(450, lambda s=self: (_v26716_refresh_fast_geometry(s), _v26716_animation_tick(s)))
    except Exception:
        pass


ChartKingPro.draw_chart = _v26716_draw_chart
ChartKingPro.__init__ = _v26716_init

