# ========================= V21.67.18 MATRIX VISIBLE FIX =========================
# V21.67.17's matrix code was defined before the later V21.67.16 __init__ wrapper.
# That later assignment replaced the V17 init hook, so the F9 binding/button setup
# never ran. Re-hook AFTER every earlier wrapper and give the matrix a guaranteed
# visible launcher + one-time auto-open.

_V26718_BASE_INIT = ChartKingPro.__init__

def _v26718_show_matrix(app):
    try:
        return _v26717_build_window(app)
    except Exception as exc:
        try:
            print(f'V21.67.18 MATRIX OPEN ERROR: {exc}', flush=True)
        except Exception:
            pass
        return None


def _v26718_install_matrix_launcher(app):
    try:
        old = getattr(app, '_v26718_matrix_button', None)
        if old is not None:
            try:
                if int(old.winfo_exists()):
                    return True
            except Exception:
                pass

        # Guaranteed launcher: place directly on the cockpit root instead of
        # depending on fragile widget-tree/header discovery.
        b = tk.Button(
            app.root,
            text='15M MATRIX',
            command=lambda a=app: _v26718_show_matrix(a),
            bg='#123a46', fg='#8ff7ff', activebackground='#185466',
            activeforeground='white', relief='raised', bd=1,
            font=('Cascadia Mono', 9, 'bold'), padx=10, pady=4,
            cursor='hand2'
        )
        b.place(relx=0.985, y=8, anchor='ne')
        try: b.lift()
        except Exception: pass
        app._v26718_matrix_button = b
        return True
    except Exception as exc:
        try: print(f'V21.67.18 MATRIX BUTTON ERROR: {exc}', flush=True)
        except Exception: pass
        return False


def _v26718_init(self, *args, **kwargs):
    _V26718_BASE_INIT(self, *args, **kwargs)
    try:
        self.root.bind('<F9>', lambda e, s=self: _v26718_show_matrix(s), add='+')
    except Exception:
        pass
    try:
        self.root.after(250, lambda s=self: _v26718_install_matrix_launcher(s))
    except Exception:
        pass
    # Open it automatically once so the user cannot miss it. If they close it,
    # the 15M MATRIX button/F9 can reopen it without touching Bookmap ingestion.
    try:
        self.root.after(900, lambda s=self: _v26718_show_matrix(s))
    except Exception:
        pass

ChartKingPro.__init__ = _v26718_init

