# ============================================================================
# LECHART JAMES V21.67.22 — FAST PATH LOCK + WICK GEOMETRY CONSENSUS
# ============================================================================
# V21.67.19-.21 made geometry richer but allowed the formulation chain to be
# too selective. V21.67.22 makes a bounded, explicit opening decision from
# native Bookmap + target + trader-style path geometry once the minimum data
# is actually present. It still refuses to invent a lock when Bookmap/target
# are unavailable, but it will not sit in BUILDING for an entire round.
# ============================================================================

_V26722_RELEASE = 'V21.67.22'


def _v26722_clip(v, lo=-1.0, hi=1.0):
    try: return max(lo, min(hi, float(v)))
    except Exception: return 0.0


def _v26722_path_consensus(self, warm=None, now=None):
    """Trader-style path read: swings, wick ladders, projected paths and levels.

    This is deliberately structural rather than predictive magic. Higher/lower
    wicks are treated as evidence only when they occur at meaningful pivots or
    repeated rejection zones. The return is bounded to [-1, 1].
    """
    now=float(now or time.time())
    try: geo=dict(_v26719_pro_geometry_read(self,now=now) or {})
    except Exception: geo={}
    if not geo.get('ready'):
        return {'ready':False,'score':0.0,'side':'WAIT','quality':0.0,'reason':'geometry warming'}

    atr=max(float(geo.get('atr',0.0) or 0.0),0.01)
    live=float(geo.get('live',0.0) or 0.0)
    highs=list(geo.get('swing_highs') or [])[-5:]
    lows=list(geo.get('swing_lows') or [])[-5:]
    score=0.0; parts=[]

    # Swing progression: HH/HL vs LH/LL.
    if len(lows)>=2:
        dl=(float(lows[-1]['price'])-float(lows[-2]['price']))/atr
        s=_v26722_clip(dl/0.65,-1,1)*.20; score+=s
        parts.append(('HL' if dl>0.10 else 'LL' if dl<-0.10 else 'L=')+f' {s:+.2f}')
    if len(highs)>=2:
        dh=(float(highs[-1]['price'])-float(highs[-2]['price']))/atr
        s=_v26722_clip(dh/0.65,-1,1)*.20; score+=s
        parts.append(('HH' if dh>0.10 else 'LH' if dh<-0.10 else 'H=')+f' {s:+.2f}')

    # Wick ladder: progressively higher rejection lows are bullish; progressively
    # lower rejection highs are bearish. Weight pronounced wick pivots more.
    if len(lows)>=3:
        a,b,c=lows[-3:]
        d1=(float(b['price'])-float(a['price']))/atr; d2=(float(c['price'])-float(b['price']))/atr
        wickq=min(1.0,(float(a.get('wick',0))+float(b.get('wick',0))+float(c.get('wick',0)))/1.15)
        if d1>0.06 and d2>0.06:
            w=.16*(.55+.45*wickq); score+=w; parts.append(f'higher lower-wicks +{w:.2f}')
        elif d1<-0.06 and d2<-0.06:
            w=.16*(.55+.45*wickq); score-=w; parts.append(f'lower lower-wicks -{w:.2f}')
    if len(highs)>=3:
        a,b,c=highs[-3:]
        d1=(float(b['price'])-float(a['price']))/atr; d2=(float(c['price'])-float(b['price']))/atr
        wickq=min(1.0,(float(a.get('wick',0))+float(b.get('wick',0))+float(c.get('wick',0)))/1.15)
        if d1>0.06 and d2>0.06:
            w=.14*(.55+.45*wickq); score+=w; parts.append(f'higher upper-wicks +{w:.2f}')
        elif d1<-0.06 and d2<-0.06:
            w=.14*(.55+.45*wickq); score-=w; parts.append(f'lower upper-wicks -{w:.2f}')

    # Projected diagonal support/resistance paths. A rising respected support path
    # or rising resistance path is bullish context; falling paths bearish.
    for key,label in (('support_line','SUP'),('resistance_line','RES')):
        ln=geo.get(key)
        if ln and float(ln.get('quality',0) or 0)>=42:
            q=min(1.0,float(ln.get('quality',0) or 0)/85.0)
            slope=float(ln.get('slope_per_sec',0) or 0)*60.0/atr
            s=math.tanh(slope/0.60)*(.13*q)
            score+=s; parts.append(f'{label} path {s:+.2f}')

    # Position vs projected path: holding above support is useful; remaining under
    # resistance is a headwind. Keep this light so proximity never becomes a vote.
    sup=geo.get('support_now'); res=geo.get('resistance_now')
    tol=max(atr*.20,0.5)
    if sup is not None:
        d=(live-float(sup))/atr
        if -0.20<=d<=2.5: score+=.07; parts.append('holding support path')
        elif d<-0.25: score-=.09; parts.append('lost support path')
    if res is not None:
        d=(float(res)-live)/atr
        if -0.20<=d<=2.5: score-=.06; parts.append('under resistance path')
        elif d<-0.25: score+=.10; parts.append('cleared resistance path')

    # Persistent horizontal wick floors/ceilings: repeated rejection is real
    # structure, but repeated tests are not treated as infinite strength.
    floor=geo.get('floor'); ceil=geo.get('ceiling')
    if floor and float(floor.get('quality',0) or 0)>=55:
        d=(live-float(floor['price']))/atr
        if 0<=d<=3.0:
            w=.08*min(1.0,float(floor.get('quality',0))/80.0); score+=w; parts.append(f'wick floor +{w:.2f}')
    if ceil and float(ceil.get('quality',0) or 0)>=55:
        d=(float(ceil['price'])-live)/atr
        if 0<=d<=3.0:
            w=.08*min(1.0,float(ceil.get('quality',0))/80.0); score-=w; parts.append(f'wick ceiling -{w:.2f}')

    # A confirmed structural break gets extra weight; a watch state does not.
    if geo.get('up_confirmed'): score+=.18; parts.append('UP acceptance')
    if geo.get('down_confirmed'): score-=.18; parts.append('DOWN acceptance')

    score=_v26722_clip(score,-1,1)
    side='UP' if score>=.08 else 'DOWN' if score<=-.08 else 'WAIT'
    quality=float(geo.get('quality',0.0) or 0.0)
    return {'ready':True,'score':score,'side':side,'quality':quality,'reason':' • '.join(parts[-7:]),'geometry':geo}


def _v26722_fast_open_lock(self, warm, now=None):
    """Fast but evidence-based opening decision.

    Typical lock target: ~1.4-2.4 s after live Bookmap + target + tape are ready.
    Hard decision window: ~3.2 s, provided minimum live evidence exists.
    """
    now=float(now or time.time()); bucket=_v240_bucket(now)
    if getattr(self,'opening_lock_snapshot',None):
        return dict(self.opening_lock_snapshot)

    st=dict(getattr(self,'_v26722_lock_state',{}) or {})
    if int(st.get('bucket',-1) or -1)!=bucket:
        st={'bucket':bucket,'first_ready':0.0,'candidate':'WAIT','candidate_since':0.0,
            'samples':0,'edge_ema':0.0,'last_eval':0.0,'flips':0}

    if now-float(st.get('last_eval',0.0) or 0.0)<.10:
        self._v26722_lock_state=st
        return None
    st['last_eval']=now

    try: live,_=self.effective_live_price(); live=float(live)
    except Exception: live=None
    try: target,_=self.effective_target(); target=float(target)
    except Exception: target=None
    try: data=dict(_v263_data_ceiling(self,warm=warm,now=now) or {})
    except Exception: data={}
    fam=dict(data.get('families') or {})
    tape=dict(fam.get('tape') or {})
    tape_ready=bool(tape.get('available'))

    if live is None or target is None or not tape_ready:
        st['first_ready']=0.0; st['candidate']='WAIT'; st['samples']=0; st['candidate_since']=0.0
        self._v26722_lock_state=st
        try: self.opening_lock_var.set('OPEN LOCK: FAST MAP • waiting for Bookmap + target + fresh tape')
        except Exception: pass
        return None

    if not st.get('first_ready'): st['first_ready']=now
    age=max(0.0,now-float(st['first_ready']))

    # Native family scorecard.
    try: card=_v252_scorecard(fam,_V252_BOOK_WEIGHTS,threshold=.14,support_threshold=.065,oppose_threshold=.25)
    except Exception: card={}
    core=float(card.get('edge',0.0) or 0.0)
    try: dest=dict(_v26719_destination_context(self,warm=warm,now=now) or {})
    except Exception: dest={}
    dscore=float(dest.get('score',0.0) or 0.0) if dest.get('ready',True) else 0.0
    path=_v26722_path_consensus(self,warm=warm,now=now)
    pscore=float(path.get('score',0.0) or 0.0) if path.get('ready') else 0.0
    try: tug=dict(_v2672_tug_read(self,now=now) or {})
    except Exception: tug={}
    tscore=float(tug.get('fused',0.0) or 0.0) if tug.get('ready') else 0.0

    # Target geometry is useful near settlement target, but never dominant.
    try:
        atr=max(float((path.get('geometry') or {}).get('atr',0.0) or 0.0),1.0)
        target_score=_v26722_clip((live-target)/(atr*2.25),-.34,.34)
    except Exception: target_score=0.0

    # Explicit evidence blend. Bookmap/core stays largest family; trader path is
    # now a real contributor rather than a decorative sidecar.
    raw=.50*core + .22*pscore + .14*dscore + .09*tscore + .05*target_score
    raw=_v26722_clip(raw,-1,1)
    prev=float(st.get('edge_ema',0.0) or 0.0)
    alpha=.58 if age<1.2 else .48
    edge=prev+(raw-prev)*alpha
    st['edge_ema']=edge

    # Breadth/opposition in the direction of the proposed side.
    side='UP' if edge>=.055 else 'DOWN' if edge<=-.055 else 'WAIT'
    # If nearly neutral after the normal decision window, choose the sign of the
    # best-supported raw route instead of remaining WAIT indefinitely.
    if side=='WAIT' and age>=2.65:
        fallback=raw if abs(raw)>=.025 else (core*.62+pscore*.38)
        if abs(fallback)>=.020: side='UP' if fallback>0 else 'DOWN'

    sign=1.0 if side=='UP' else -1.0 if side=='DOWN' else 0.0
    aligned=0; opposed=0; available=0
    family_scores={}
    for name in ('tape','whale','structure','target'):
        row=dict(fam.get(name) or {})
        if not row.get('available'): continue
        available+=1; sc=float(row.get('score',0.0) or 0.0); family_scores[name]=sc
        if sign and sc*sign>=.055: aligned+=1
        if sign and sc*sign<=-.28: opposed+=1
    if path.get('ready'):
        available+=1; family_scores['pro_path']=pscore
        if sign and pscore*sign>=.07: aligned+=1
        if sign and pscore*sign<=-.30: opposed+=1

    if side!=st.get('candidate'):
        if st.get('candidate') in ('UP','DOWN') and side in ('UP','DOWN'): st['flips']=int(st.get('flips',0))+1
        st['candidate']=side; st['candidate_since']=now; st['samples']=1 if side in ('UP','DOWN') else 0
    elif side in ('UP','DOWN'):
        st['samples']=int(st.get('samples',0))+1
    else:
        st['samples']=max(0,int(st.get('samples',0))-1)

    # Fast path: minimum ~1.15s + 3 coherent evaluations. Ordinary path by ~2s.
    # Hard path by ~3.2s, but still requires fresh tape, target and at least two
    # available evidence families. Broad strong opposition can delay hard lock.
    strong=(abs(edge)>=.18 and aligned>=2 and opposed==0)
    normal=(abs(edge)>=.095 and aligned>=1 and opposed<=1)
    min_age=1.15 if strong else 1.65
    needed=3 if strong else 4
    hard=(age>=3.20 and side in ('UP','DOWN') and available>=2 and opposed<=1)
    qualified=(side in ('UP','DOWN') and available>=2 and age>=min_age and int(st.get('samples',0))>=needed and (strong or normal)) or hard

    self._v26722_lock_state=st
    try:
        if side in ('UP','DOWN'):
            self.opening_lock_candidate=side
            self.opening_lock_candidate_since=float(st.get('candidate_since',now) or now)
            self.opening_lock_var.set(
                f'OPEN LOCK: FORMULATING {side} • {int(st.get("samples",0))}/{needed} • '
                f'path {pscore:+.2f} • core {core:+.2f} • edge {edge:+.2f} • '
                f'{aligned} align / {opposed} oppose • {age:.1f}s'
            )
        else:
            self.opening_lock_candidate=None; self.opening_lock_candidate_since=0.0
            self.opening_lock_var.set(
                f'OPEN LOCK: FAST MAP • path {pscore:+.2f} • core {core:+.2f} • '
                f'edge {edge:+.2f} • deciding • {age:.1f}s'
            )
    except Exception: pass

    if not qualified:
        return None

    grade='STRAIGHT' if strong else 'ROUTE'
    reasons=(f'V21.67.22 {grade} • native Bookmap core {core:+.2f} • pro path {pscore:+.2f} • '
             f'destination {dscore:+.2f} • tug {tscore:+.2f} • target geometry {target_score:+.2f} • '
             f'{aligned} aligned / {opposed} opposed • {path.get("reason","")}')
    snap={'time':now,'price':live,'lock_side':side,'lock_remaining':'OPEN','lock_minute':0,
          'forecast_score':edge*10.0,'forecast_threshold':0.95,'forecast_reasons':reasons,
          'source':'BOOKMAP OPEN/NOW • V21.67.22 FAST PRO PATH'}
    self.opening_lock_snapshot=dict(snap)
    self.opening_lock_candidate=None; self.opening_lock_candidate_since=0.0

    enriched={**card,'core_edge':core,'edge':edge,'edge_ema':edge,'candidate':side,
              'samples':int(st.get('samples',0)),'needed':needed,'support':aligned,'oppose':opposed,
              'available':available,'families':fam,'live':live,'target':target,'data':data,
              'v26722_path':path,'v26722_family_scores':family_scores,'destination_score':dscore}
    self._v252_bookmap_last=dict(enriched); self._v252_bookmap_frozen=dict(enriched)
    try:
        self.opening_lock_var.set(
            f'OPEN LOCK: {side} LOCKED @ {money(live)} • V21.67.22 {grade} • '
            f'path {pscore:+.2f} • core {core:+.2f} • edge {edge:+.2f}'
        )
    except Exception: pass
    try: self._checkpoint_status_summary()
    except Exception: pass
    return snap


def _v26722_reset(self):
    self._v26722_lock_state={}

_V26722_BASE_RESET_CONTROL=ChartKingPro._v237_reset_round_control
_V26722_BASE_RESET_MARKET=ChartKingPro.reset_market_state

def _v26722_reset_round_control(self):
    _v26722_reset(self)
    return _V26722_BASE_RESET_CONTROL(self)

def _v26722_reset_market_state(self):
    _v26722_reset(self)
    return _V26722_BASE_RESET_MARKET(self)

# Final opening authority. _v240_bookmap_open dynamically calls this global and
# still supplies the immutable-per-round capture/restore wrapper around it.
_V240_BASE_BOOKMAP_OPEN=_v26722_fast_open_lock
ChartKingPro._v237_reset_round_control=_v26722_reset_round_control
ChartKingPro.reset_market_state=_v26722_reset_market_state
try:
    _V26718_RELEASE=_V26722_RELEASE
except Exception:
    pass

# END LECHART JAMES V21.67.22


# ============================================================================
# LECHART JAMES V21.67.24 — OPEN LOCK BRAIN RESTORE / NO-DEADLOCK AUTHORITY
# ============================================================================
# V21.67.19-.22 accidentally made the opening authority depend on a downstream
# family availability chain that can remain false even while the native Bookmap
# warmup read is live.  Result: no candidate, no frozen Open Lock, and Journey /
# Gold Route remains 0/100.  V23 restores the correct authority order:
#
#   1) native Bookmap warmup is the required live sensor;
#   2) pro geometry / higher-lower wick pathing is additive evidence, NEVER a gate;
#   3) destination/structure/whale families help when available, NEVER deadlock;
#   4) the bot forms a side quickly, verifies briefly, then freezes the first earn.
#
# This keeps the V21.40 immutable-per-round wrapper.  It does not rewrite an
# already earned Open Lock.
# ============================================================================

_V26723_RELEASE = 'V21.67.24'


def _v26723_clip(v, lo=-1.0, hi=1.0):
    try:
        return max(lo, min(hi, float(v)))
    except Exception:
        return 0.0


def _v26723_pick_side(value, fallback='WAIT'):
    try:
        v=float(value)
    except Exception:
        v=0.0
    if v>0: return 'UP'
    if v<0: return 'DOWN'
    fb=str(fallback or 'WAIT').upper()
    return fb if fb in ('UP','DOWN') else 'WAIT'


def _v26723_open_lock(self, warm, now=None):
    """Fast, live-Bookmap-first Open Lock with pro path confirmation.

    Geometry can improve or challenge the call, but it can never prevent the
    opening authority from thinking.  A live native warmup read is sufficient
    to start formulation.  Normal locks occur around 1.0-1.8 s of coherent
    evidence; a bounded hard decision occurs by ~2.6 s once live Bookmap exists.
    """
    now=float(now or time.time())
    bucket=_v240_bucket(now)

    if getattr(self,'opening_lock_snapshot',None):
        return dict(self.opening_lock_snapshot)

    st=dict(getattr(self,'_v26723_lock_state',{}) or {})
    if int(st.get('bucket',-1) or -1)!=bucket:
        st={'bucket':bucket,'first_live':0.0,'candidate':'WAIT','candidate_since':0.0,
            'samples':0,'edge_ema':0.0,'best_edge':0.0,'last_eval':0.0,'opposite_hits':0}
        self.opening_lock_bucket=bucket
        self.opening_lock_snapshot=None
        self.opening_lock_candidate=None
        self.opening_lock_candidate_since=0.0

    # One market observation per ~100 ms, regardless of how many UI callers ask.
    if now-float(st.get('last_eval',0.0) or 0.0)<0.10:
        self._v26723_lock_state=st
        return None
    st['last_eval']=now

    # The caller normally supplies the warmup packet. Re-read only as a recovery
    # path so a stale/empty caller packet cannot leave the lock brain inert.
    w=dict(warm or {})
    if not w.get('ready'):
        try:
            w=dict(self._bookmap_fast_warmup_read(now=now, force=True) or {})
        except Exception:
            w={}

    try:
        live=float(w.get('live')) if w.get('live') is not None else float(self.effective_live_price()[0])
    except Exception:
        live=None
    try:
        target=float(self.effective_target()[0])
    except Exception:
        target=None

    # This is the only true startup gate: we need an actual live Bookmap read.
    # Target is desirable but not required to begin thinking.
    if not w.get('ready') or live is None:
        st['first_live']=0.0
        self._v26723_lock_state=st
        self.opening_lock_candidate=None
        self.opening_lock_candidate_since=0.0
        try:
            self.opening_lock_var.set('OPEN LOCK: BRAIN LIVE • waiting for native Bookmap executed flow')
        except Exception:
            pass
        return None

    if not st.get('first_live'):
        st['first_live']=now
    age=max(0.0,now-float(st['first_live']))

    # ------------------------------------------------------------------
    # 1) NATIVE BOOKMAP: primary live evidence. This is never replaced by a
    #    downstream family availability bit.
    # ------------------------------------------------------------------
    warm_signed=_v26723_clip(w.get('signed',0.0))
    favored=str(w.get('favored','WAIT') or 'WAIT').upper()
    if favored not in ('UP','DOWN'):
        favored='UP' if warm_signed>=0 else 'DOWN'

    # ------------------------------------------------------------------
    # 2) FULL FAMILY SCORECARD: additive only. If tape/whale/structure is not
    #    marked available yet, the missing row contributes zero instead of
    #    shutting the entire brain off.
    # ------------------------------------------------------------------
    try:
        data=dict(_v263_data_ceiling(self,warm=w,now=now) or {})
    except Exception:
        data={}
    fam=dict(data.get('families') or {})
    try:
        card=dict(_v252_scorecard(fam,_V252_BOOK_WEIGHTS,threshold=.12,
                                  support_threshold=.05,oppose_threshold=.30) or {})
    except Exception:
        card={}
    core=_v26723_clip(card.get('edge',0.0))
    fam_available=sum(1 for r in fam.values() if dict(r or {}).get('available'))

    # ------------------------------------------------------------------
    # 3) PRO PATH / WICKS: swing highs/lows, HH-HL/LH-LL, rising/falling wick
    #    ladders, repeated floors/ceilings, projected support/resistance paths.
    #    It is meaningful evidence when ready, but NEVER a prerequisite.
    # ------------------------------------------------------------------
    try:
        path=dict(_v26722_path_consensus(self,warm=w,now=now) or {})
    except Exception:
        path={}
    pscore=_v26723_clip(path.get('score',0.0)) if path.get('ready') else 0.0
    pquality=float(path.get('quality',0.0) or 0.0) if path.get('ready') else 0.0

    # Destination context remains bounded and secondary.
    try:
        dest=dict(_v26719_destination_context(self,warm=w,now=now) or {})
    except Exception:
        dest={}
    dscore=_v26723_clip(dest.get('score',0.0)) if dest.get('ready',False) else 0.0

    # Target geometry is settlement-specific context. Normalize with actual
    # 1m/pro-geometry ATR if available, otherwise a conservative $25 reference.
    target_score=0.0
    if target is not None:
        try:
            atr=max(float((path.get('geometry') or {}).get('atr',0.0) or 0.0),25.0)
        except Exception:
            atr=25.0
        target_score=_v26723_clip((live-target)/(atr*1.8),-.55,.55)

    # Dynamic weighted blend: missing optional families do not dilute the live
    # native read.  Bookmap warmup always owns the largest weight.
    pieces=[(warm_signed,.46,'bookmap')]
    if fam_available:
        pieces.append((core,.22,'core'))
    if path.get('ready'):
        # Scale path contribution modestly by geometry quality.
        pq=max(.45,min(1.0,pquality/78.0))
        pieces.append((pscore,.20*pq,'path'))
    if dest.get('ready',False):
        pieces.append((dscore,.07,'destination'))
    if target is not None:
        pieces.append((target_score,.10,'target'))
    den=sum(wt for _v,wt,_n in pieces) or 1.0
    raw=sum(v*wt for v,wt,_n in pieces)/den
    raw=_v26723_clip(raw)

    # Responsive EMA. Do not erase a coherent candidate because of one neutral
    # micro-tick; genuine opposite pressure must actually cross through zero.
    prev=float(st.get('edge_ema',0.0) or 0.0)
    alpha=.64 if age<1.0 else .52
    edge=_v26723_clip(prev+(raw-prev)*alpha)
    st['edge_ema']=edge
    if abs(edge)>=abs(float(st.get('best_edge',0.0) or 0.0)):
        st['best_edge']=edge

    # Candidate threshold is intentionally low enough to THINK early; the brief
    # persistence check below is what separates formulation from the frozen lock.
    proposed='UP' if edge>=.045 else 'DOWN' if edge<=-.045 else 'WAIT'
    if proposed=='WAIT' and age>=1.35:
        fallback=.56*warm_signed + .24*pscore + .20*target_score
        proposed=_v26723_pick_side(fallback,favored)

    old=str(st.get('candidate','WAIT') or 'WAIT').upper()
    if proposed in ('UP','DOWN'):
        if old not in ('UP','DOWN'):
            st['candidate']=proposed; st['candidate_since']=now; st['samples']=1; st['opposite_hits']=0
        elif proposed==old:
            st['samples']=int(st.get('samples',0) or 0)+1
            st['opposite_hits']=0
        else:
            # Do not flip the forming thesis on one twitch. Require two genuine
            # opposite reads, except for an obviously strong reversal.
            opp=int(st.get('opposite_hits',0) or 0)+1
            st['opposite_hits']=opp
            if opp>=2 or abs(edge)>=.22:
                st['candidate']=proposed; st['candidate_since']=now; st['samples']=1; st['opposite_hits']=0
    else:
        # Neutral evidence does NOT clear an already-forming candidate.
        if old not in ('UP','DOWN'):
            st['candidate']='WAIT'; st['samples']=0

    candidate=str(st.get('candidate','WAIT') or 'WAIT').upper()
    cand_age=max(0.0,now-float(st.get('candidate_since',now) or now)) if candidate in ('UP','DOWN') else 0.0

    # Broad contradiction check. This can demand a little more verification but
    # cannot produce an infinite WAIT state.
    sign=1.0 if candidate=='UP' else -1.0 if candidate=='DOWN' else 0.0
    aligned=0; opposed=0
    for name,row0 in fam.items():
        row=dict(row0 or {})
        if not row.get('available') or not sign: continue
        sc=float(row.get('score',0.0) or 0.0)
        if sc*sign>=.06: aligned+=1
        if sc*sign<=-.32: opposed+=1
    if path.get('ready') and sign:
        if pscore*sign>=.07: aligned+=1
        if pscore*sign<=-.34: opposed+=1

    # Normal: ~1.0-1.8 sec. Strong evidence can lock sooner. A hard bounded
    # decision at 2.6 sec uses the best coherent side already observed.
    strong=(candidate in ('UP','DOWN') and abs(edge)>=.18 and opposed==0)
    normal=(candidate in ('UP','DOWN') and abs(edge)>=.075 and opposed<=1)
    verify=0.72 if strong else 1.05
    needed=3 if strong else 4
    qualified=(candidate in ('UP','DOWN') and age>=.85 and cand_age>=verify and
               int(st.get('samples',0) or 0)>=needed and (strong or normal))

    hard=False
    if not qualified and age>=2.60:
        # If candidate is still absent, select from the best live information.
        if candidate not in ('UP','DOWN'):
            hard_basis=float(st.get('best_edge',0.0) or 0.0)
            if abs(hard_basis)<.01:
                hard_basis=.60*warm_signed + .22*pscore + .18*target_score
            candidate=_v26723_pick_side(hard_basis,favored)
            if candidate in ('UP','DOWN'):
                st['candidate']=candidate
                st['candidate_since']=now
                st['samples']=max(1,int(st.get('samples',0) or 0))
                sign=1.0 if candidate=='UP' else -1.0
        # Only an extreme broad contradiction can postpone the hard earn briefly.
        hard=(candidate in ('UP','DOWN') and opposed<3)

    self._v26723_lock_state=st
    self.opening_lock_candidate=candidate if candidate in ('UP','DOWN') else None
    self.opening_lock_candidate_since=float(st.get('candidate_since',0.0) or 0.0) if candidate in ('UP','DOWN') else 0.0

    try:
        if candidate in ('UP','DOWN'):
            self.opening_lock_var.set(
                f'OPEN LOCK: FORMULATING {candidate} • {int(st.get("samples",0))}/{needed} • '
                f'Bookmap {warm_signed:+.2f} • path {pscore:+.2f} • core {core:+.2f} • '
                f'edge {edge:+.2f} • {aligned} align/{opposed} oppose • {age:.1f}s'
            )
        else:
            self.opening_lock_var.set(
                f'OPEN LOCK: THINKING • Bookmap {warm_signed:+.2f} • path {pscore:+.2f} • '
                f'core {core:+.2f} • target {target_score:+.2f} • {age:.1f}s'
            )
    except Exception:
        pass

    if not (qualified or hard):
        return None

    # Freeze first legitimately earned call for the round. The V21.40 wrapper
    # immediately copies this into _v240_earned_open_lock as well.
    grade='FAST STRAIGHT' if strong else 'PRO ROUTE' if not hard else 'BOUNDED ROUTE'
    lock_edge=edge
    if candidate=='UP' and lock_edge<=0: lock_edge=max(.02,abs(float(st.get('best_edge',0.0) or 0.0)))
    if candidate=='DOWN' and lock_edge>=0: lock_edge=-max(.02,abs(float(st.get('best_edge',0.0) or 0.0)))
    reasons=(f'V21.67.24 {grade} • native Bookmap {warm_signed:+.2f} • core {core:+.2f} • '
             f'pro path {pscore:+.2f} • destination {dscore:+.2f} • target {target_score:+.2f} • '
             f'{aligned} aligned / {opposed} opposed • {path.get("reason","")}')
    snap={'time':now,'price':float(live),'lock_side':candidate,'lock_remaining':'OPEN','lock_minute':0,
          'forecast_score':lock_edge*10.0,'forecast_threshold':0.45,'forecast_reasons':reasons,
          'source':'BOOKMAP OPEN/NOW • V21.67.24 BRAIN RESTORE'}
    self.opening_lock_snapshot=dict(snap)
    self.opening_lock_candidate=None
    self.opening_lock_candidate_since=0.0

    # Populate the exact downstream fields Journey/Gold Route reads. This is a
    # handoff packet, not a second decision engine.
    enriched={**card,'core_edge':core,'edge':lock_edge,'edge_ema':lock_edge,
              'candidate':candidate,'samples':int(st.get('samples',0) or 0),'needed':needed,
              'support':aligned,'oppose':opposed,'available':fam_available,
              'families':fam,'live':live,'target':target,
              'distance':(float(live)-float(target)) if target is not None else 0.0,
              'data':data,'v26723_path':path,'destination_score':dscore,
              'warm_signed':warm_signed,'grade':grade}
    self._v252_bookmap_last=dict(enriched)
    self._v252_bookmap_frozen=dict(enriched)

    try:
        self.opening_lock_var.set(
            f'OPEN LOCK: {candidate} LOCKED @ {money(live)} • V21.67.24 {grade} • '
            f'Bookmap {warm_signed:+.2f} • path {pscore:+.2f} • edge {lock_edge:+.2f}'
        )
    except Exception:
        pass
    try:
        self._v2673_context_cache={}
        self._v2673_last_map={}
    except Exception:
        pass
    try:
        self._checkpoint_status_summary()
    except Exception:
        pass
    return dict(snap)


