        _v268_var_set(self,'lock_distance_var','LOCK SYSTEM REMOVED • target is one bounded evidence family')
        _v268_var_set(self,'lock_minute_status_var','TIMED LOCKS DISABLED • V21.68 CONTINUOUS ROUTE')
