# ============================================================================
# V21.69 EARNED LOCK REBUILD
# Reintroduces a lock as a high-confidence COMMITMENT LAYER over V21.68's
# continuous route model. Unlike the historical frozen lock, this lock must be
# earned, is continuously audited, and can break/re-arm/flip when the thesis
# genuinely fails. The goal is fewer low-quality commitments without becoming
# blind to reversals.
# ============================================================================

def _v269_lock_state_reset(self):
    self._v269_lock_state = {
        'bucket': -1, 'status': 'WATCH', 'side': 'WAIT', 'candidate': 'WAIT',
        'candidate_since': 0.0, 'candidate_samples': 0, 'locked_since': 0.0,
        'break_since': 0.0, 'cooldown_until': 0.0, 'strength': 0.0,
        'last_reason': 'building evidence', 'last': {}, 'history': deque(maxlen=500),
    }


def _v269_family_counts(d, side):
    sign=_v268_sign(side); fam=dict(d.get('families') or {})
    agree=[]; oppose=[]; fast_agree=[]; fast_oppose=[]
    for name,row0 in fam.items():
        row=dict(row0 or {})
        if not row.get('available'): continue
        sc=float(row.get('score',0.0) or 0.0)
        if sc*sign >= .14:
            agree.append(name)
            if row.get('fast'): fast_agree.append(name)
        elif sc*sign <= -.14:
            oppose.append(name)
            if row.get('fast'): fast_oppose.append(name)
    return agree,oppose,fast_agree,fast_oppose


def _v269_lock_read(self, now=None, state=None, force=False):
    """Earned/revocable lock layered over the continuously updating V21.68 route."""
    now=float(now or time.time()); bucket=int(now//900)*900
    if not hasattr(self,'_v269_lock_state') or not isinstance(getattr(self,'_v269_lock_state',None),dict):
        _v269_lock_state_reset(self)
    st=dict(self._v269_lock_state or {})
    if int(st.get('bucket',-1) or -1)!=bucket:
        _v269_lock_state_reset(self); st=dict(self._v269_lock_state); st['bucket']=bucket
    d=dict(state or _v268_dynamic_read(self,now=now,force=force))
    route=str(d.get('route_side','NEUTRAL')).upper(); ema=float(d.get('ema',0) or 0)
    fast=float(d.get('fast_ema',0) or 0); conf=float(d.get('route_confidence',50) or 50)
    quality=float(d.get('quality',0) or 0); coherence=float(d.get('coherence',0) or 0)
    feed=dict(d.get('feed') or {}); feed_health=float(feed.get('health',.6) or .6)
    status=str(st.get('status','WATCH')).upper(); lock_side=str(st.get('side','WAIT')).upper()

    def score_for(side):
        sign=_v268_sign(side); agree,oppose,fa,fo=_v269_family_counts(d,side)
        aligned=max(0.0,sign*ema); fast_aligned=max(0.0,sign*fast)
        breadth=min(1.0,len(agree)/5.0); fastbreadth=min(1.0,len(fa)/2.0)
        penalty=min(.35,.07*len(oppose)+.08*len(fo))
        s=(.26*(conf/100.0)+.22*(quality/100.0)+.16*coherence+
           .16*min(1.0,aligned/0.55)+.10*min(1.0,fast_aligned/0.55)+
           .07*breadth+.03*fastbreadth-penalty)
        # Poor source agreement cannot itself kill a lock because most evidence
        # families are relative, but it raises the bar modestly.
        s-=max(0.0,.42-feed_health)*.12
        return _v268_clip(s,0,1),agree,oppose,fa,fo

    # Audit an existing lock first. It remains a commitment only while evidence
    # continues to support the thesis. No historical "defend it at all costs" rule.
    if status=='LOCKED' and lock_side in ('UP','DOWN'):
        strength,agree,oppose,fa,fo=score_for(lock_side)
        opposite='DOWN' if lock_side=='UP' else 'UP'
        sign=_v268_sign(lock_side)
        x=_v268_exit_read(self,lock_side,now=now,state=d)
        hard_break=(bool(x.get('exit')) and float(x.get('risk',0) or 0)>=72) or \
                   (route==opposite and conf>=63 and sign*ema<=-.18 and len(oppose)>=3)
        soft_break=(sign*fast<=-.24 and sign*ema<=-.10 and len(oppose)>=3) or strength<.43
        if hard_break:
            st.update({'status':'BROKEN','side':'WAIT','break_since':now,'cooldown_until':now+.35,
                       'strength':strength,'last_reason':f'HARD BREAK • {x.get("reason","")}'})
            self.opening_lock_snapshot=None
        elif soft_break:
            if not float(st.get('break_since',0) or 0): st['break_since']=now
            if now-float(st.get('break_since',now) or now)>=.55:
                st.update({'status':'BROKEN','side':'WAIT','cooldown_until':now+.45,'strength':strength,
                           'last_reason':f'LOCK INVALIDATED • fast {fast:+.2f} • edge {ema:+.2f} • oppose {len(oppose)}'})
                self.opening_lock_snapshot=None
            else:
                st['strength']=strength; st['last_reason']=f'LOCK UNDER REVIEW • {len(oppose)} opposing families'
        else:
            st['break_since']=0.0; st['strength']=strength
            st['last_reason']=f'LOCK HEALTHY • agree {len(agree)} • fast agree {len(fa)} • edge {ema:+.2f}'

    status=str(st.get('status','WATCH')).upper(); lock_side=str(st.get('side','WAIT')).upper()
    # Search for a new earned lock whenever unlocked/broken.
    if status!='LOCKED':
        candidate=route if route in ('UP','DOWN') else 'WAIT'
        strength=0.0; agree=[]; oppose=[]; fa=[]; fo=[]
        if candidate in ('UP','DOWN'):
            strength,agree,oppose,fa,fo=score_for(candidate)
        sign=_v268_sign(candidate)
        # Thresholds intentionally require breadth + route quality + fast tape not
        # fighting the candidate. This replaces the old timer-based first call.
        qualifies=(candidate in ('UP','DOWN') and now>=float(st.get('cooldown_until',0) or 0) and
                   conf>=62 and quality>=56 and coherence>=.50 and abs(ema)>=.18 and
                   sign*fast>=-.05 and len(agree)>=3 and len(fa)>=1 and len(oppose)<=2 and
                   strength>=.61)
        if qualifies:
            if str(st.get('candidate','WAIT')).upper()!=candidate:
                st.update({'candidate':candidate,'candidate_since':now,'candidate_samples':1})
            else:
                st['candidate_samples']=int(st.get('candidate_samples',0) or 0)+1
            age=max(0.0,now-float(st.get('candidate_since',now) or now))
            # Obvious broad consensus earns faster; marginal cases need more proof.
            decisive=(strength>=.74 and conf>=70 and len(agree)>=4 and len(fa)>=2 and abs(ema)>=.30)
            need_age=.45 if decisive else .95
            need_samples=3 if decisive else 5
            st['status']='ARMING'; st['strength']=strength
            st['last_reason']=f'{candidate} ARMING • {strength*100:.0f}/100 • agree {len(agree)} • {age:.2f}s {st["candidate_samples"]}/{need_samples}'
            if age>=need_age and int(st.get('candidate_samples',0) or 0)>=need_samples:
                st.update({'status':'LOCKED','side':candidate,'locked_since':now,'break_since':0.0,
                           'candidate':'WAIT','candidate_since':0.0,'candidate_samples':0,
                           'last_reason':f'EARNED {candidate} • strength {strength*100:.0f} • agree {len(agree)} • fast {len(fa)}'})
                live=d.get('live')
                snap={'time':now,'price':live,'lock_side':candidate,'lock_remaining':'EARNED','lock_minute':int((now%900)//60),
                      'forecast_score':strength*10.0,'forecast_threshold':6.1,
                      'forecast_reasons':st['last_reason'],'source':'V21.69 EARNED LOCK',
                      'strength':strength*100.0,'revocable':True,'route_confidence':conf,'quality':quality}
                self.opening_lock_snapshot=dict(snap)
        else:
            # Candidate failure must reset formulation; no stale side earns later.
            st['candidate']='WAIT'; st['candidate_since']=0.0; st['candidate_samples']=0
            if status!='BROKEN': st['status']='WATCH'
            st['strength']=strength
            st['last_reason']=(f'WATCH • route {route} {conf:.0f} • quality {quality:.0f} • '
                               f'edge {ema:+.2f} • fast {fast:+.2f} • agree {len(agree)}')
            if status=='BROKEN' and now>=float(st.get('cooldown_until',0) or 0): st['status']='WATCH'

    status=str(st.get('status','WATCH')).upper(); lock_side=str(st.get('side','WAIT')).upper()
    if status=='LOCKED' and lock_side in ('UP','DOWN'):
        if not getattr(self,'opening_lock_snapshot',None) or str(self.opening_lock_snapshot.get('lock_side','')).upper()!=lock_side:
            self.opening_lock_snapshot={'time':float(st.get('locked_since',now) or now),'price':d.get('live'),'lock_side':lock_side,
                'lock_remaining':'EARNED','lock_minute':int((now%900)//60),'forecast_score':float(st.get('strength',0))*10,
                'forecast_threshold':6.1,'forecast_reasons':st.get('last_reason',''),'source':'V21.69 EARNED LOCK',
                'strength':float(st.get('strength',0))*100,'revocable':True}
    else:
        self.opening_lock_snapshot=None

    out={'ready':status=='LOCKED','status':status,'side':lock_side if status=='LOCKED' else 'WAIT',
         'lock_side':lock_side if status=='LOCKED' else 'WAIT','strength':float(st.get('strength',0))*100,
         'reason':st.get('last_reason',''),'candidate':st.get('candidate','WAIT'),
         'candidate_samples':int(st.get('candidate_samples',0) or 0),
         'candidate_age':max(0.0,now-float(st.get('candidate_since',now) or now)) if st.get('candidate_since') else 0.0,
         'locked_age':max(0.0,now-float(st.get('locked_since',now) or now)) if status=='LOCKED' else 0.0,
         'dynamic':d,'snapshot':dict(self.opening_lock_snapshot) if self.opening_lock_snapshot else None}
    st['last']=dict(out)
    try: st['history'].append({'ts':now,'status':status,'side':out['side'],'strength':out['strength'],'route':route,'ema':ema,'fast':fast})
    except Exception: pass
    self._v269_lock_state=st; self._v269_last_lock=dict(out)
    return out


def _v269_open_lock_tick(self, warm=None, now=None):
    lk=_v269_lock_read(self,now=now)
    if lk['status']=='LOCKED':
        _v268_var_set(self,'opening_lock_var',f"EARNED LOCK: {lk['side']} • {lk['strength']:.0f}/100 • REVOCABLE • {lk['reason']}")
        return dict(lk.get('snapshot') or {})
    if lk['status']=='ARMING':
        _v268_var_set(self,'opening_lock_var',f"LOCK ARMING: {lk['candidate']} • {lk['strength']:.0f}/100 • {lk['reason']}")
    elif lk['status']=='BROKEN':
        _v268_var_set(self,'opening_lock_var',f"LOCK BROKEN • RE-MAPPING • {lk['reason']}")
    else:
        _v268_var_set(self,'opening_lock_var',f"LOCK WATCH: {lk['reason']}")
    return None


def _v269_master_read(self, now=None):
    now=float(now or time.time()); d=_v268_dynamic_read(self,now=now); lk=_v269_lock_read(self,now=now,state=d)
    side=str(lk.get('side','WAIT')).upper(); ready=bool(lk.get('ready')) and side in ('UP','DOWN')
    conf=float(d.get('route_confidence',50) or 50); quality=float(d.get('quality',0) or 0); coherence=float(d.get('coherence',0) or 0)
    rough=_v268_clip(1.0-(.50*coherence+.30*min(1.0,abs(float(d.get('ema',0)))*1.8)+.20*float(lk.get('strength',0))/100.0),0,1)
    health=_v268_clip(.30*(conf/100.0)+.28*(quality/100.0)+.22*coherence+.20*(float(lk.get('strength',0))/100.0),0,1)
    return {'ready':ready,'side':side if ready else 'WAIT','entry_authority':'V21.69 EARNED REVOCABLE LOCK',
            'roughness':rough,'health':health,'road':'EARNED LOCK' if ready else 'WAIT FOR LOCK',
            'seconds_left':float(d.get('seconds_left',0) or 0),'risk':float(d.get('flip_risk',0) or 0),
            'survival':float(d.get('survival',100) or 100),'dynamic':d,'lock':lk,
            'reason':f"{lk.get('status','WATCH')} • {lk.get('reason','building')} • route {d.get('route_side','NEUTRAL')} {conf:.0f}/100"}


def _v269_master_step(self, warm=None, sig=None, candles=None, now=None, mode='LIVE'):
    """V21.69 paper loop: entries require an earned lock; exits remain live and can break it."""
    now=float(now or time.time())
    if now-float(getattr(self,'_v269_last_step',0.0) or 0.0)<.10: return False
    self._v269_last_step=now
    try:_v264_paper_mark(self)
    except Exception:pass
    d=_v268_dynamic_read(self,now=now); lk=_v269_lock_read(self,now=now,state=d)
    if getattr(self,'paper_active_trade',None):
        trade=dict(self.paper_active_trade); bucket=int(trade.get('bucket',0) or 0); current=int(now//900)*900
        if bucket<current: _v264_reconcile_settlement_async(self); return False
        x=_v268_exit_read(self,trade.get('direction'),now=now,state=d); self._v268_last_exit=dict(x)
        # If lock itself broke for the held side, elevate protective response even
        # if the generic exit engine is a fraction slower.
        held=str(trade.get('direction','WAIT')).upper()
        lock_broke=(str(lk.get('status','')).upper()=='BROKEN' or (lk.get('ready') and str(lk.get('side')).upper()!=held))
        _v268_var_set(self,'paper_exit_status_var',f"V21.69 {x['state']} • risk {x['risk']:.0f}/100 • lock {lk.get('status')}")
        _v268_var_set(self,'auto_paper_reason_var',x.get('reason',''))
        if (x.get('exit') or (lock_broke and float(x.get('risk',0) or 0)>=58)) and bool(self.paper_auto_exit_var.get()):
            _contract,yes_equiv,_src,_age=_v264_paper_price(self,trade['direction'],'EXIT',_V264_EXIT_QUOTE_MAX_AGE)
            if yes_equiv is not None:
                return bool(_v264_paper_finalize(self,exit_yes=yes_equiv,reason='V21.69 LOCK/EXIT • '+x.get('state','EXIT')+' • '+x.get('reason','')))
        return False
    if not bool(self.auto_paper_enabled_var.get()):
        _v268_var_set(self,'auto_paper_score_var','V21.69 PAPER AUTO: OFF'); return False
    bucket=int(now//900)*900
    if _v268_round_has_trade(self,bucket):
        self._v267_traded_bucket=bucket; _v268_var_set(self,'auto_paper_score_var','V21.69 PAPER: ROUND ALREADY TRADED'); return False
    master=_v269_master_read(self,now=now)
    if not master.get('ready'):
        _v268_var_set(self,'auto_paper_score_var',f"V21.69 {lk.get('status')} • {lk.get('candidate','WAIT')} • strength {float(lk.get('strength',0)):.0f}/100 • WAIT")
        _v268_var_set(self,'auto_paper_reason_var',master.get('reason','building earned lock')); return False
    side=str(master['side']).upper(); ask,_yes,qsrc,qage=_v264_paper_price(self,side,'ENTER',_V264_ENTRY_QUOTE_MAX_AGE)
    if ask is None:
        _v268_var_set(self,'auto_paper_score_var',f'V21.69 {side} LOCK READY • KALSHI BBO WAIT'); return False
    plan=_v264_value_plan(self,master,ask,now); self._v264_last_plan=dict(plan)
    _v268_var_set(self,'auto_paper_score_var',f"V21.69 EARNED {side} LOCK • {float(lk.get('strength',0)):.0f}/100 • ASK {ask*100:.1f}c")
    _v268_var_set(self,'auto_paper_reason_var',f"{plan.get('state','WAIT')} • {master.get('reason','')} • {qsrc} age {float(qage or 0):.2f}s")
    if not plan.get('enter'): return False
    freshd=_v268_dynamic_read(self,now=time.time(),force=True); freshlk=_v269_lock_read(self,now=time.time(),state=freshd,force=True)
    if not freshlk.get('ready') or str(freshlk.get('side','WAIT')).upper()!=side:
        _v268_var_set(self,'auto_paper_reason_var','ENTRY CANCELLED • earned lock invalidated during final execution check'); return False
    opened=bool(_v264_paper_open(self,side,entry_source='V21.69 EARNED LOCK AUTO',auto_score=float(freshlk.get('strength',0)),
        auto_reason=f"V21.69 earned revocable lock • {freshlk.get('reason','')} • {plan.get('state','')}"))
    if opened:self._v267_traded_bucket=bucket
    return opened


