# ============================================================================
# V21.70 MULTI-TIMESCALE TREND-REGIME GOVERNOR
# Sits ABOVE V21.69's earned-lock engine. The dynamic route may still detect a
# countertrend bounce, but a lock cannot be earned against a clear Bookmap-native
# trend until reversal structure is actually demonstrated. This specifically
# prevents repeated "UP" commitments inside an intact DOWN trend (and vice versa).
# ============================================================================

def _v270_median(values, default=0.0):
    vals=sorted(float(x) for x in values if x is not None)
    if not vals:return float(default)
    n=len(vals); m=n//2
    return vals[m] if n%2 else (vals[m-1]+vals[m])*.5


def _v270_ema(values, period):
    vals=[float(x) for x in values]
    if not vals:return 0.0
    a=2.0/(max(1,int(period))+1.0); e=vals[0]
    for x in vals[1:]: e=e+a*(x-e)
    return e


def _v270_rows(self, seconds, now=None, limit=30):
    """Bookmap-native OHLC rows only; no public exchange history dependency."""
    now=float(now or time.time()); seconds=int(seconds)
    try:
        if seconds in (3,5,15,30) and hasattr(self,'_subminute_history'):
            rows=list(self._subminute_history(seconds,include_current=True) or [])
        elif seconds==60:
            rows=list(getattr(self,'btc_1m',[]) or [])
        elif seconds==300:
            rows=list(getattr(self,'btc_5m',[]) or [])
        elif seconds==900:
            rows=list(getattr(self,'btc_15m',[]) or [])
        elif seconds==3600:
            rows=list(getattr(self,'btc_1h',[]) or [])
        else:
            rows=[]
    except Exception:
        rows=[]
    clean=[]
    for r0 in rows[-max(8,int(limit)*2):]:
        try:
            r=dict(r0); ts=float(r.get('time',0) or 0)
            o=float(r['open']); h=float(r['high']); l=float(r['low']); c=float(r['close'])
            if ts<=now+seconds and h>=l:
                clean.append({'time':ts,'open':o,'high':h,'low':l,'close':c})
        except Exception: pass
    clean.sort(key=lambda r:r['time'])
    return clean[-int(limit):]


def _v270_tf_metric(rows, seconds):
    rows=list(rows or [])
    if len(rows)<4:
        return {'ready':False,'seconds':int(seconds),'score':0.0,'readability':0.0,'efficiency':0.0,
                'structure':0.0,'break_side':'NONE','n':len(rows),'reason':f'{len(rows)}/4 candles'}
    rows=rows[-min(18,len(rows)):]
    closes=[float(r['close']) for r in rows]
    highs=[float(r['high']) for r in rows]
    lows=[float(r['low']) for r in rows]
    ranges=[max(.01,h-l) for h,l in zip(highs,lows)]
    diffs=[closes[i]-closes[i-1] for i in range(1,len(closes))]
    atr=max(.01,_v270_median(ranges[-10:],.01),_v270_median([abs(x) for x in diffs[-10:]],.01)*1.35)
    n=len(closes); xm=(n-1)*.5; ym=sum(closes)/n
    den=sum((i-xm)**2 for i in range(n)) or 1.0
    slope=sum((i-xm)*(closes[i]-ym) for i in range(n))/den
    slope_score=math.tanh((slope/atr)*1.35)
    fast=_v270_ema(closes,4); slow=_v270_ema(closes,9 if n>=9 else max(5,n))
    ema_score=math.tanh(((fast-slow)/atr)*1.20)
    up=down=0.0
    for i in range(1,n):
        if closes[i]>closes[i-1]:up+=.45
        elif closes[i]<closes[i-1]:down+=.45
        if highs[i]>highs[i-1]:up+=.30
        elif highs[i]<highs[i-1]:down+=.30
        if lows[i]>lows[i-1]:up+=.25
        elif lows[i]<lows[i-1]:down+=.25
    structure=(up-down)/max(1.0,(n-1))
    structure=_v268_clip(structure,-1,1)
    path=sum(abs(x) for x in diffs) or .01
    net=closes[-1]-closes[0]
    efficiency=min(1.0,abs(net)/path)
    directional_eff=(1.0 if net>0 else -1.0 if net<0 else 0.0)*efficiency
    net_score=math.tanh(net/(atr*max(1.5,(n-1)*.55)))
    score=_v268_clip(.30*slope_score+.23*ema_score+.27*structure+.12*directional_eff+.08*net_score)
    readability=_v268_clip(.42*efficiency+.30*abs(structure)+.18*min(1.0,abs(slope)/atr)+.10*min(1.0,abs(fast-slow)/atr),0,1)
    break_side='NONE'
    if n>=6:
        prev=rows[-6:-1]; last=rows[-1]
        prior_hi=max(float(r['high']) for r in prev); prior_lo=min(float(r['low']) for r in prev)
        pad=max(.25,atr*.08)
        if float(last['close'])>prior_hi+pad:break_side='UP'
        elif float(last['close'])<prior_lo-pad:break_side='DOWN'
    return {'ready':True,'seconds':int(seconds),'score':score,'readability':readability,'efficiency':efficiency,
            'structure':structure,'slope_atr':slope/atr,'ema_gap_atr':(fast-slow)/atr,'break_side':break_side,
            'n':n,'last':closes[-1],'atr':atr,'reason':f'score {score:+.2f} • eff {efficiency:.2f} • structure {structure:+.2f}'}


def _v270_trend_regime_read(self, now=None, force=False):
    now=float(now or time.time())
    cache=dict(getattr(self,'_v270_trend_cache',{}) or {})
    if (not force) and cache and now-float(cache.get('ts',0) or 0)<.35:
        return dict(cache)
    specs=((30,.10),(60,.40),(300,.34),(900,.16))
    frames={}; active=[]
    for sec,w in specs:
        met=_v270_tf_metric(_v270_rows(self,sec,now=now,limit=24),sec)
        frames[str(sec)]=met
        if met.get('ready'):
            # Sparse slower frames get proportionally less authority until mature.
            maturity=min(1.0,max(.45,(int(met.get('n',0))-3)/6.0))
            active.append((sec,w*maturity,met))
    den=sum(w for _s,w,_m in active)
    if den<=0:
        out={'ready':False,'side':'NEUTRAL','regime':'BUILDING','score':0.0,'strength':0.0,'agreement':0.0,
             'readability':0.0,'lockable':False,'strong':False,'frames':frames,'short_score':0.0,'slow_score':0.0,
             'reason':'TREND GOVERNOR BUILDING • waiting for Bookmap-native candles','ts':now}
        self._v270_trend_cache=dict(out); return out
    composite=sum(w*float(m.get('score',0) or 0) for _s,w,m in active)/den
    readability=sum(w*float(m.get('readability',0) or 0) for _s,w,m in active)/den
    sign=1 if composite>0 else -1 if composite<0 else 0
    agreeing=sum(w for _s,w,m in active if sign and float(m.get('score',0) or 0)*sign>=.10)
    directional=sum(w for _s,w,m in active if abs(float(m.get('score',0) or 0))>=.10)
    agreement=agreeing/max(den*.65,directional,1e-9) if sign else 0.0
    agreement=_v268_clip(agreement,0,1)
    short_rows=[(w,m) for s,w,m in active if s<=60]
    slow_rows=[(w,m) for s,w,m in active if s>=300]
    def wscore(rows):
        dd=sum(w for w,_m in rows)
        return sum(w*float(m.get('score',0) or 0) for w,m in rows)/dd if dd else 0.0
    short_score=wscore(short_rows); slow_score=wscore(slow_rows)
    abs_score=abs(composite)
    side='UP' if composite>=.20 and agreement>=.52 else 'DOWN' if composite<=-.20 and agreement>=.52 else 'NEUTRAL'
    strong=side in ('UP','DOWN') and abs_score>=.34 and agreement>=.60 and readability>=.36
    conflict=(directional>0 and agreeing/max(directional,1e-9)<.46)
    unreadable=(readability<.22) or (conflict and abs_score<.24)
    lockable=not unreadable
    regime=('UPTREND' if side=='UP' else 'DOWNTREND' if side=='DOWN' else 'MIXED' if conflict else 'RANGE/TRANSITION')
    strength=_v268_clip(abs_score*(.65+.35*agreement)*(.72+.28*readability),0,1)
    breaks=[m.get('break_side','NONE') for _s,_w,m in active]
    out={'ready':True,'side':side,'regime':regime,'score':composite,'strength':strength,'agreement':agreement,
         'readability':readability,'lockable':lockable,'strong':strong,'conflict':conflict,'frames':frames,
         'short_score':short_score,'slow_score':slow_score,'breaks':breaks,'ts':now,
         'reason':f'{regime} • trend {composite:+.2f} • agree {agreement*100:.0f}% • readable {readability*100:.0f}%'}
    self._v270_trend_cache=dict(out); return out


def _v270_reversal_proof(self, candidate, dynamic, trend):
    side=str(candidate or 'WAIT').upper(); sign=_v268_sign(side)
    if side not in ('UP','DOWN') or not sign:
        return {'confirmed':False,'score':0.0,'reason':'no reversal candidate'}
    agree,oppose,fa,fo=_v269_family_counts(dynamic,side)
    ema=sign*float(dynamic.get('ema',0) or 0); fast=sign*float(dynamic.get('fast_ema',0) or 0)
    fam=dict(dynamic.get('families') or {})
    path=sign*float((fam.get('STRUCTURE_PATH') or {}).get('score',0) or 0)
    dest=sign*float((fam.get('DESTINATION') or {}).get('score',0) or 0)
    short=sign*float(trend.get('short_score',0) or 0)
    slow=sign*float(trend.get('slow_score',0) or 0)
    f60=dict((trend.get('frames') or {}).get('60') or {})
    f30=dict((trend.get('frames') or {}).get('30') or {})
    structure_break=(str(f60.get('break_side','NONE')).upper()==side or str(f30.get('break_side','NONE')).upper()==side)
    breadth=min(1.0,len(agree)/5.0); fastbreadth=min(1.0,len(fa)/2.0)
    structural=max(0.0,max(path,dest)); short_flip=max(0.0,short)
    slow_relief=max(0.0,min(1.0,(slow+.35)/.70))
    score=_v268_clip(.24*min(1.0,max(0.0,fast)/.65)+.18*min(1.0,max(0.0,ema)/.50)+
                     .16*breadth+.10*fastbreadth+.15*min(1.0,short_flip/.55)+.09*min(1.0,structural/.50)+
                     .08*slow_relief + (.08 if structure_break else 0.0),0,1)
    route_ok=str(dynamic.get('route_side','NEUTRAL')).upper()==side and float(dynamic.get('route_confidence',50) or 50)>=66
    one_min=sign*float(f60.get('score',0) or 0)
    # A single wick/close through prior structure is not enough. Countertrend permission
    # needs either broad short-TF rotation or a 1m structure break with the 1m trend
    # itself already rotating materially toward the candidate.
    short_ok=short>=.28 or (structure_break and one_min>=.16)
    structural_ok=structural>=.18 or structure_break
    confirmed=(score>=.69 and route_ok and fast>=.34 and ema>=.20 and len(agree)>=4 and len(fa)>=2 and short_ok and structural_ok)
    return {'confirmed':bool(confirmed),'score':score,'structure_break':structure_break,'short':short,'slow':slow,'one_min':one_min,
            'agree':agree,'oppose':oppose,'fast_agree':fa,'fast_oppose':fo,
            'reason':f'reversal proof {score*100:.0f}/100 • 1m {one_min:+.2f} • short {short:+.2f} • fast {fast:+.2f} • edge {ema:+.2f} • agree {len(agree)} • break {structure_break}'}


_V270_BASE_LOCK_READ=_v269_lock_read

def _v270_lock_read(self, now=None, state=None, force=False):
    """V21.69 earned lock + V21.70 market-regime / countertrend governor."""
    now=float(now or time.time()); d=dict(state or _v268_dynamic_read(self,now=now,force=force))
    trend=_v270_trend_regime_read(self,now=now,force=force)
    lk=dict(_V270_BASE_LOCK_READ(self,now=now,state=d,force=force) or {})
    st=dict(getattr(self,'_v269_lock_state',{}) or {})
    status=str(lk.get('status','WATCH')).upper()
    candidate=str(lk.get('side') if lk.get('ready') else lk.get('candidate','WAIT')).upper()
    tside=str(trend.get('side','NEUTRAL')).upper()
    clear_trend=bool(trend.get('strong')) and tside in ('UP','DOWN')
    counter=(candidate in ('UP','DOWN') and clear_trend and candidate!=tside)
    proof=_v270_reversal_proof(self,candidate,d,trend) if counter else {'confirmed':False,'score':0.0,'reason':'trend-aligned or no strong regime'}

    # New locks are forbidden in unreadable tape. Existing locks remain managed by
    # the live exit engine rather than being killed merely because readability fell.
    if not trend.get('lockable',True) and status in ('ARMING','WATCH'):
        st.update({'status':'WATCH','side':'WAIT','candidate':'WAIT','candidate_since':0.0,'candidate_samples':0,
                   'last_reason':'NO LOCK — STRUCTURE UNREADABLE • '+str(trend.get('reason',''))})
        self.opening_lock_snapshot=None
        lk.update({'ready':False,'status':'WATCH','side':'WAIT','lock_side':'WAIT','candidate':'WAIT','candidate_samples':0,'candidate_age':0.0,'strength':0.0,
                   'reason':st['last_reason'],'snapshot':None})
    elif counter and status in ('ARMING','LOCKED') and not proof.get('confirmed'):
        # If base just tried to form a countertrend lock, veto immediately. If an
        # older countertrend lock loses reversal proof, require persistence before
        # breaking it so a single trend tick cannot whipsaw the position.
        locked_age=float(lk.get('locked_age',0) or 0)
        gov=dict(getattr(self,'_v270_governor_state',{}) or {})
        if status=='ARMING' or locked_age<.20:
            st.update({'status':'WATCH','side':'WAIT','candidate':'WAIT','candidate_since':0.0,'candidate_samples':0,
                       'break_since':0.0,'last_reason':f'COUNTERTREND {candidate} BLOCKED • {trend.get("regime")} intact • {proof.get("reason")}'})
            self.opening_lock_snapshot=None
            lk.update({'ready':False,'status':'WATCH','side':'WAIT','lock_side':'WAIT','candidate':'WAIT','candidate_samples':0,'candidate_age':0.0,'strength':float(lk.get('strength',0) or 0),
                       'reason':st['last_reason'],'snapshot':None})
            gov['counter_fail_since']=0.0
        else:
            if not float(gov.get('counter_fail_since',0) or 0):gov['counter_fail_since']=now
            age=now-float(gov.get('counter_fail_since',now) or now)
            hard=(str(d.get('route_side','NEUTRAL')).upper()==tside and float(d.get('route_confidence',50) or 50)>=66 and float(trend.get('strength',0) or 0)>=.46)
            if age>=(.28 if hard else .75):
                st.update({'status':'BROKEN','side':'WAIT','candidate':'WAIT','candidate_since':0.0,'candidate_samples':0,
                           'break_since':now,'cooldown_until':now+.45,
                           'last_reason':f'COUNTERTREND LOCK BROKEN • {trend.get("regime")} reasserted • {proof.get("reason")}'})
                self.opening_lock_snapshot=None
                lk.update({'ready':False,'status':'BROKEN','side':'WAIT','lock_side':'WAIT','candidate':'WAIT',
                           'reason':st['last_reason'],'snapshot':None})
            else:
                lk['reason']=f'COUNTERTREND LOCK UNDER GOVERNOR REVIEW {age:.2f}s • {proof.get("reason")}'
        self._v270_governor_state=gov
    else:
        try:self._v270_governor_state['counter_fail_since']=0.0
        except Exception:self._v270_governor_state={'counter_fail_since':0.0}
        if status=='LOCKED' and candidate in ('UP','DOWN'):
            if clear_trend and candidate==tside:
                lk['reason']=f'TREND-ALIGNED • {trend.get("regime")} {trend.get("strength",0)*100:.0f}/100 • '+str(lk.get('reason',''))
            elif counter and proof.get('confirmed'):
                lk['reason']=f'COUNTERTREND REVERSAL CONFIRMED {proof.get("score",0)*100:.0f}/100 • '+str(lk.get('reason',''))
        elif status=='ARMING' and candidate in ('UP','DOWN') and clear_trend and candidate==tside:
            lk['reason']=f'TREND-ALIGNED ARMING • {trend.get("regime")} • '+str(lk.get('reason',''))

    st['last']=dict(lk); self._v269_lock_state=st; self._v269_last_lock=dict(lk)
    lk['trend']=trend; lk['reversal_proof']=proof
    self._v270_last_governor={'trend':trend,'lock':dict(lk),'proof':proof}
    return lk


def _v270_master_read(self, now=None):
    now=float(now or time.time()); d=_v268_dynamic_read(self,now=now); lk=_v270_lock_read(self,now=now,state=d)
    trend=dict(lk.get('trend') or {}); side=str(lk.get('side','WAIT')).upper(); ready=bool(lk.get('ready')) and side in ('UP','DOWN')
    conf=float(d.get('route_confidence',50) or 50); quality=float(d.get('quality',0) or 0); coherence=float(d.get('coherence',0) or 0)
    rough=_v268_clip(1.0-(.42*coherence+.24*min(1.0,abs(float(d.get('ema',0)))*1.8)+.18*float(lk.get('strength',0))/100.0+.16*float(trend.get('readability',0) or 0)),0,1)
    health=_v268_clip(.25*(conf/100.0)+.23*(quality/100.0)+.18*coherence+.18*(float(lk.get('strength',0))/100.0)+.16*float(trend.get('readability',0) or 0),0,1)
    return {'ready':ready,'side':side if ready else 'WAIT','entry_authority':'V21.70 EARNED LOCK + TREND GOVERNOR',
            'roughness':rough,'health':health,'road':'EARNED LOCK' if ready else 'WAIT FOR GOVERNOR/LOCK',
            'seconds_left':float(d.get('seconds_left',0) or 0),'risk':float(d.get('flip_risk',0) or 0),
            'survival':float(d.get('survival',100) or 100),'dynamic':d,'lock':lk,'trend':trend,
            'reason':f"{lk.get('status','WATCH')} • {lk.get('reason','building')} • trend {trend.get('regime','BUILDING')} • route {d.get('route_side','NEUTRAL')} {conf:.0f}/100"}


def _v270_master_step(self, warm=None, sig=None, candles=None, now=None, mode='LIVE'):
    now=float(now or time.time())
