    opened=bool(_v264_paper_open(self,side,entry_source='V21.70 TREND-GOVERNED EARNED LOCK AUTO',auto_score=float(freshlk.get('strength',0)),
        auto_reason=f"V21.70 governed lock • {freshlk.get('reason','')} • {plan.get('state','')}"))
    if opened:self._v267_traded_bucket=bucket
    return opened


