# ============================================================================
# LECHART JAMES V21.71 — TURBO HIGH-HZ CHART RENDERER
#
# VISUAL/PERFORMANCE ONLY.  Trading / V21.70 trend-governed earned-lock logic
# is untouched.
#
# What changes:
# - Replaces the old ~16 FPS forming-candle timer with a display-aware high-Hz
#   incremental renderer (60-360 Hz; Windows monitor refresh detected when
#   available, env BOOKMAP_KING_RENDER_HZ can override).
# - Keeps a tiny native-Bookmap visual OHLC cache so the high-Hz path does not
#   repeatedly rescan full candle history.
# - Redraws only the two forming-candle Canvas items + live-price marker at the
#   high-Hz cadence.  Historical candles/overlays stay on an adaptive full-draw
#   cadence so the trading brain cannot be starved by paint work.
# - Full chart redraw target rises from ~0.9-1.5 sec to as fast as the existing
#   65 ms UI heartbeat (~15 Hz) when draw cost is cheap, and backs off only if
#   measured Tk draw time becomes expensive.
# - Triggers an immediate full redraw if the forming candle escapes the cached
#   y-scale, preventing a fast move from being visually clipped.
#
# Tk Canvas itself is software-rendered; this patch maximizes the current UI
# architecture without changing the Bookmap/trading runtime or adding fragile
# third-party GPU dependencies.
# ============================================================================

_V271_RELEASE = 'V21.71'
_V271_BASE_INIT = ChartKingPro.__init__
_V271_BASE_DRAW = ChartKingPro.draw_chart
_V271_BASE_INGEST = ChartKingPro._ingest_bookmap_event
_V271_BASE_CHART_INTERVAL = ChartKingPro._chart_draw_interval
_V271_BASE_FAST_LIVE = _v26716_fast_live_candle

_V271_TFS = (3, 5, 15, 30, 60, 180, 300, 900, 1800, 3600, 14400)


def _v271_detect_display_hz():
    """Best-effort Windows refresh-rate detection; safe fallback elsewhere."""
    try:
        forced = float(os.environ.get('BOOKMAP_KING_RENDER_HZ', '0') or 0)
        if forced > 0:
            return max(30.0, min(360.0, forced))
    except Exception:
        pass
    try:
        import ctypes
        user32 = ctypes.windll.user32
        gdi32 = ctypes.windll.gdi32
        hdc = user32.GetDC(0)
        try:
            # VREFRESH = 116.  Usually returns the active desktop refresh rate.
            hz = float(gdi32.GetDeviceCaps(hdc, 116) or 0)
        finally:
            user32.ReleaseDC(0, hdc)
        if 30.0 <= hz <= 500.0:
            return max(60.0, min(360.0, hz))
    except Exception:
        pass
    # High-refresh fallback; adaptive scheduler will automatically back off if
    # the event loop cannot sustain it.
    return 144.0


def _v271_visual_lock(self):
    lk = getattr(self, '_v271_visual_cache_lock', None)
    if lk is None:
        try:
            lk = threading.RLock()
        except Exception:
            lk = None
        self._v271_visual_cache_lock = lk
    return lk


def _v271_normalize_event_ts(value):
    now = time.time()
    try:
        ts = float(value if value is not None else now)
    except Exception:
        ts = now
    if ts > 1e16:
        ts /= 1000000000.0
    elif ts > 1000000000000.0:
        ts /= 1000.0
    return ts


def _v271_ingest_bookmap_event(self, event):
    """Preserve native ingestion, then update a tiny display-only OHLC cache."""
    out = _V271_BASE_INGEST(self, event)
    try:
        if not isinstance(event, dict) or str(event.get('type', '')).lower().strip() != 'trade':
            return out
        px = float(event.get('price'))
        size = max(0.0, float(event.get('size', 0.0) or 0.0))
        ts = _v271_normalize_event_ts(event.get('ts'))
        if not math.isfinite(px) or px <= 0:
            return out
        lk = _v271_visual_lock(self)
        if lk is None:
            return out
        with lk:
            cache = getattr(self, '_v271_visual_ohlc', None)
            if not isinstance(cache, dict):
                cache = {}
                self._v271_visual_ohlc = cache
            seq = int(getattr(self, '_v271_visual_seq', 0) or 0) + 1
            self._v271_visual_seq = seq
            self._v271_last_trade_px = px
            self._v271_last_trade_ts = ts
            for sec in _V271_TFS:
                bucket = int(ts // sec) * sec
                row = cache.get(sec)
                if not row or int(row.get('time', -1) or -1) != bucket:
                    cache[sec] = {
                        'time': bucket,
                        'open': px,
                        'high': px,
                        'low': px,
                        'close': px,
                        'volume': size,
                        '_seeded': False,
                        '_seq': seq,
                        '_last_ts': ts,
                        '_live_source': 'BOOKMAP EXECUTIONS • V21.71 VISUAL CACHE',
                    }
                else:
                    row['high'] = max(float(row.get('high', px) or px), px)
                    row['low'] = min(float(row.get('low', px) or px), px)
                    row['close'] = px
                    row['volume'] = float(row.get('volume', 0.0) or 0.0) + size
                    row['_seq'] = seq
                    row['_last_ts'] = ts
    except Exception:
        pass
    return out


def _v271_seed_visual_row(self, sec):
    """One expensive seed per candle; subsequent frames are O(1)."""
    sec = max(1, int(sec))
    try:
        base = dict(self._current_bucket_for_interval(sec) or {})
    except Exception:
        base = {}
    if not base:
        return None
    try:
        bucket = int(base.get('time', 0) or 0)
        lk = _v271_visual_lock(self)
        if lk is None:
            return base
        with lk:
            cache = getattr(self, '_v271_visual_ohlc', None)
            if not isinstance(cache, dict):
                cache = {}
                self._v271_visual_ohlc = cache
            live = cache.get(sec)
            if live and int(live.get('time', -1) or -1) == bucket:
                # Base includes all public/native history known to the canonical
                # chart. Merge any trade that landed while the seed was built.
                base['high'] = max(float(base.get('high', 0) or 0), float(live.get('high', 0) or 0))
                lows = [x for x in (base.get('low'), live.get('low')) if x is not None]
                if lows:
                    base['low'] = min(float(x) for x in lows)
                if float(live.get('_last_ts', 0) or 0) >= float(getattr(self, '_v271_seed_started_ts', 0) or 0):
                    base['close'] = float(live.get('close', base.get('close', 0)) or base.get('close', 0))
                base['volume'] = max(float(base.get('volume', 0) or 0), float(live.get('volume', 0) or 0))
                base['_seq'] = max(int(live.get('_seq', 0) or 0), int(getattr(self, '_v271_visual_seq', 0) or 0))
            base['_seeded'] = True
            base['_live_source'] = 'BOOKMAP EXECUTIONS • V21.71 TURBO'
            cache[sec] = dict(base)
            return dict(base)
    except Exception:
        return base


def _v271_visual_row(self, sec):
    sec = max(1, int(sec))
    now = time.time()
    bucket = int(now // sec) * sec
    lk = _v271_visual_lock(self)
    row = None
    try:
        if lk is not None:
            with lk:
                cached = (getattr(self, '_v271_visual_ohlc', {}) or {}).get(sec)
                if cached and int(cached.get('time', -1) or -1) == bucket and bool(cached.get('_seeded')):
                    row = dict(cached)
    except Exception:
        row = None
    if row is None:
        self._v271_seed_started_ts = now
        row = _v271_seed_visual_row(self, sec)
    return row


def _v271_fast_live_candle(self):
    """High-Hz O(1) paint path: forming candle + live price marker only."""
    try:
        if bool(getattr(self, 'web_only_mode', False)):
            return False
        if time.time() < float(getattr(self, '_scroll_active_until', 0.0) or 0.0):
            return False
        if hasattr(self, '_v2676_showing') and not bool(getattr(self, '_v2676_showing', True)):
            return False
        g = getattr(self, '_v26716_fast_geometry', None)
        c = getattr(self, 'canvas', None)
        if not g or c is None or g.get('canvas') is not c:
            g = _v26716_refresh_fast_geometry(self)
        if not g or int(g.get('pan', 0) or 0) != 0:
            return False

        sec = max(1, int(getattr(self, 'chart_interval_seconds', 60) or 60))
        row = _v271_visual_row(self, sec)
        if not row:
            return _V271_BASE_FAST_LIVE(self)
        bucket = int(row.get('time', 0) or 0)
        if bucket and bucket != int(g.get('bucket', 0) or 0):
            if bucket != int(getattr(self, '_v26716_redraw_requested_bucket', -1) or -1):
                self._v26716_redraw_requested_bucket = bucket
                self._last_chart_render_key = None
                try:
                    self.root.after_idle(self.draw_chart)
                except Exception:
                    pass
            return False

        lo, hi = float(g['lo']), float(g['hi'])
        if hi <= lo:
            return False
        hi_p = float(row.get('high', row.get('close', 0.0)) or 0.0)
        lo_p = float(row.get('low', row.get('close', 0.0)) or 0.0)
        # If price escaped the scale, request a fast geometry redraw instead of
        # clipping the candle at the chart edge.
        pad = max(0.5, (hi - lo) * 0.003)
        if hi_p > hi - pad or lo_p < lo + pad:
            now = time.time()
            if now - float(getattr(self, '_v271_last_scale_redraw', 0.0) or 0.0) >= 0.08:
                self._v271_last_scale_redraw = now
                self._last_chart_render_key = None
                try:
                    self.root.after_idle(self.draw_chart)
                except Exception:
                    pass

        top, ph = float(g['top']), float(g['ph'])
        def yy(p):
            y = top + (hi - float(p)) / (hi - lo) * ph
            return max(top, min(top + ph, y))

        op = float(row.get('open', row.get('close', 0.0)) or 0.0)
        cl = float(row.get('close', op) or op)
        x = float(g['last_x'])
        half = max(2.0, min(10.0, float(g['step']) * 0.31))
        yo, yh, yl, yc = yy(op), yy(hi_p), yy(lo_p), yy(cl)
        body_top, body_bottom = min(yo, yc), max(yo, yc)
        if body_bottom - body_top < 2.0:
            body_bottom = body_top + 2.0
        bull = cl >= op
        fill = '#16c784' if bull else '#ea3943'
        outline = '#72f2b2' if bull else '#ff7f94'

        ids = getattr(self, '_v26716_live_candle_items', None)
        valid = False
        if ids:
            try:
                valid = all(c.type(i) for i in ids)
            except Exception:
                valid = False
        if not valid:
            try:
                c.delete('v26716_live_candle')
            except Exception:
                pass
            wick = c.create_line(x, yh, x, yl, fill=outline, width=2, tags=('v26716_live_candle',))
            body = c.create_rectangle(x-half, body_top, x+half, body_bottom,
                                      fill=fill, outline=outline, width=1,
                                      tags=('v26716_live_candle',))
            ids = (wick, body)
            self._v26716_live_candle_items = ids
        wick, body = ids
        c.coords(wick, x, yh, x, yl)
        c.coords(body, x-half, body_top, x+half, body_bottom)
        c.itemconfigure(wick, fill=outline)
        c.itemconfigure(body, fill=fill, outline=outline)
        c.tag_raise('v26716_live_candle')
        try:
            live = float(row.get('close', cl) or cl)
            source = str(row.get('_live_source', 'BOOKMAP V21.71 TURBO'))
            self._v82_update_live_chart_overlay(live, source)
            c.tag_raise('v82_live')
        except Exception:
            pass
        self._v271_last_painted_seq = int(row.get('_seq', getattr(self, '_v271_visual_seq', 0)) or 0)
        self._v271_frames_painted = int(getattr(self, '_v271_frames_painted', 0) or 0) + 1
        return True
    except Exception:
        return False


def _v271_animation_tick(self):
    """Display-aware high-Hz scheduler with measured event-loop protection."""
    tick_start = time.perf_counter()
    target = float(getattr(self, '_v271_target_hz', 144.0) or 144.0)
    target = max(30.0, min(360.0, target))
    expected = float(getattr(self, '_v271_expected_frame', tick_start) or tick_start)
    lag_ms = max(0.0, (tick_start - expected) * 1000.0)
    lag_ema = float(getattr(self, '_v271_lag_ema_ms', 0.0) or 0.0)
    self._v271_lag_ema_ms = lag_ms if lag_ema <= 0 else lag_ema * 0.92 + lag_ms * 0.08

    # Event driven: schedule at monitor Hz, but skip redundant Canvas writes if
    # no native trade changed the forming candle. Force a heartbeat paint every
    # 100 ms so the price marker/canvas never appears stale.
    seq = int(getattr(self, '_v271_visual_seq', 0) or 0)
    last_seq = int(getattr(self, '_v271_last_painted_seq', -1) or -1)
    now_wall = time.time()
    force = now_wall - float(getattr(self, '_v271_last_visual_heartbeat', 0.0) or 0.0) >= 0.10
    painted = False
    if True:
        try:
            painted = bool(_v271_fast_live_candle(self))
        except Exception:
            painted = False
        if force:
            self._v271_last_visual_heartbeat = now_wall

    elapsed_ms = (time.perf_counter() - tick_start) * 1000.0
    prior = float(getattr(self, '_v271_anim_ema_ms', 0.0) or 0.0)
    self._v271_anim_ema_ms = elapsed_ms if prior <= 0 else prior * 0.92 + elapsed_ms * 0.08

    frame_budget = 1000.0 / target
    effective = target
    # Protect Tk only when measured work/lag proves the requested rate cannot be
    # sustained. This does not touch Bookmap ingestion or trading logic.
    if self._v271_anim_ema_ms > frame_budget * 0.75 or self._v271_lag_ema_ms > frame_budget * 1.50:
        effective = max(45.0, target * 0.50)
    elif self._v271_anim_ema_ms > frame_budget * 0.45 or self._v271_lag_ema_ms > frame_budget * 0.80:
        effective = max(60.0, target * 0.75)
    if time.time() < float(getattr(self, '_v256_protect_until', 0.0) or 0.0):
        effective = min(effective, 60.0)
    self._v271_effective_hz = effective

    delay_ms = max(1, int(round(1000.0 / effective - elapsed_ms)))
    self._v271_expected_frame = time.perf_counter() + delay_ms / 1000.0
    try:
        self.root.after(delay_ms, lambda s=self: _v271_animation_tick(s))
    except Exception:
        pass


def _v271_draw_chart(self, *args, **kwargs):
    started = time.perf_counter()
    try:
        return _V271_BASE_DRAW(self, *args, **kwargs)
    finally:
        elapsed = (time.perf_counter() - started) * 1000.0
        prior = float(getattr(self, '_v271_full_draw_ema_ms', 0.0) or 0.0)
        self._v271_full_draw_ema_ms = elapsed if prior <= 0 else prior * 0.88 + elapsed * 0.12
        self._v271_full_draw_peak_ms = max(elapsed, float(getattr(self, '_v271_full_draw_peak_ms', 0.0) or 0.0) * 0.995)
        try:
            _v26716_refresh_fast_geometry(self)
        except Exception:
            pass


def _v271_chart_draw_interval(self):
    """Adaptive full-chart cadence; max is the existing ~15.4 Hz UI heartbeat."""
    ms = float(getattr(self, '_v271_full_draw_ema_ms', 0.0) or 0.0)
    if ms <= 0:
        return 0.065
    if ms <= 7.0:
        return 0.065
    if ms <= 12.0:
        return 0.095
    if ms <= 20.0:
        return 0.145
    if ms <= 32.0:
        return 0.220
    return 0.360


def _v271_render_status(self):
    try:
        target = float(getattr(self, '_v271_target_hz', 0.0) or 0.0)
        effective = float(getattr(self, '_v271_effective_hz', target) or target)
        draw = float(getattr(self, '_v271_full_draw_ema_ms', 0.0) or 0.0)
        anim = float(getattr(self, '_v271_anim_ema_ms', 0.0) or 0.0)
        lag = float(getattr(self, '_v271_lag_ema_ms', 0.0) or 0.0)
        text = (
            f'{getattr(self, "chart_tf_var", None).get() if getattr(self, "chart_tf_var", None) else "CHART"} • '
            f'V21.71 TURBO {effective:.0f}/{target:.0f}Hz live • full draw {draw:.1f}ms • frame {anim:.2f}ms • lag {lag:.1f}ms'
        )
        _v268_var_set(self, 'chart_tf_status_var', text)
    except Exception:
        pass
    try:
        self.root.after(900, lambda s=self: _v271_render_status(s))
    except Exception:
        pass


def _v271_init(self, *args, **kwargs):
    # Fields are initialized before the inherited ~450 ms animation start fires.
    self._v271_visual_ohlc = {}
    self._v271_visual_cache_lock = threading.RLock()
    self._v271_visual_seq = 0
    self._v271_last_painted_seq = -1
    self._v271_last_trade_px = None
    self._v271_last_trade_ts = 0.0
    self._v271_target_hz = _v271_detect_display_hz()
    self._v271_effective_hz = self._v271_target_hz
    self._v271_expected_frame = time.perf_counter()
    self._v271_anim_ema_ms = 0.0
    self._v271_lag_ema_ms = 0.0
    self._v271_full_draw_ema_ms = 0.0
    self._v271_full_draw_peak_ms = 0.0
    self._v271_last_scale_redraw = 0.0
    self._v271_last_visual_heartbeat = 0.0
    self._v271_frames_painted = 0
    _V271_BASE_INIT(self, *args, **kwargs)
    try:
        self.live_draw_interval = 0.065
        # Bookmap heatmap/panel are still heavier than the two-item candle path.
        # Raise them substantially, but keep them bounded and let older protect
        # logic slow them if the Tk event loop becomes stressed.
        self.bookmap_panel_interval = min(float(getattr(self, 'bookmap_panel_interval', 0.45) or 0.45), 0.14)
        self.bookmap_heatmap_interval = min(float(getattr(self, 'bookmap_heatmap_interval', 0.85) or 0.85), 0.12)
        self.bookmap_heatmap_draw_interval = min(float(getattr(self, 'bookmap_heatmap_draw_interval', 1.0) or 1.0), 0.12)
        self.root.title(
            f'BOOKMAP KING V21.71 — TREND GOVERNOR + TURBO {self._v271_target_hz:.0f}HZ CHART'
        )
        self.root.after(700, lambda s=self: _v271_render_status(s))
    except Exception:
        pass


# Rebind the old scheduled animation symbol.  V21.67.16's inherited init uses
# this global name at execution time, so this upgrades the existing single
# animation loop instead of accidentally starting a second competing loop.
_v26716_animation_tick = _v271_animation_tick
_v26716_fast_live_candle = _v271_fast_live_candle
ChartKingPro._ingest_bookmap_event = _v271_ingest_bookmap_event
ChartKingPro.draw_chart = _v271_draw_chart
ChartKingPro._chart_draw_interval = _v271_chart_draw_interval
ChartKingPro.__init__ = _v271_init

# END V21.71 TURBO HIGH-HZ CHART RENDERER

# ============================================================================
# LECHART JAMES V21.72 — MAIN FORECAST LOCK / PROJECTED SETTLEMENT AUTHORITY
#
# FIXES THE V21.69/V21.70 ARCHITECTURE ERROR:
#   * route_side describes what current evidence is doing NOW.
#   * route_side is no longer allowed to choose the MAIN LOCK.
#   * MAIN LOCK now comes from a forward settlement projection.
#
# AUTHORITY ORDER:
#   1) Forecast remaining 15m path from multi-TF trend + structural path +
#      destination + fair-value/reversion + remaining movement budget.
#   2) Project a settlement center / uncertainty band relative to Kalshi target.
#   3) Earn MAIN FORECAST LOCK from projected settlement side, with persistence.
#   4) Audit that forecast continuously; break only when the projected finish
#      genuinely invalidates — not merely because a 2-6s flow burst flips.
#   5) Fast route remains useful for timing / exits / warnings, never lock authority.
# ============================================================================

_V272_RELEASE = 'V21.72.1'
_V272_BASE_INIT = ChartKingPro.__init__
_V272_BASE_RESET_CONTROL = ChartKingPro._v237_reset_round_control
_V272_BASE_RESET_MARKET = ChartKingPro.reset_market_state


def _v272_clip(x, lo=-1.0, hi=1.0):
    try: return max(float(lo), min(float(hi), float(x)))
    except Exception: return 0.0


def _v272_sign(side):
    side=str(side or 'WAIT').upper()
    return 1.0 if side=='UP' else -1.0 if side=='DOWN' else 0.0


def _v272_reset(self):
    now=time.time(); bucket=int(now//900)*900
    self._v272_forecast_cache={}
    self._v272_lock_state={
        'bucket':bucket,'status':'WATCH','side':'WAIT','candidate':'WAIT',
        'candidate_since':0.0,'candidate_samples':0,'locked_since':0.0,
        'break_since':0.0,'cooldown_until':0.0,'strength':0.0,
        'last_reason':'FORECAST BUILDING','history':deque(maxlen=900),'last':{}
    }
    self._v272_last_forecast={}; self._v272_last_lock={}; self.opening_lock_snapshot=None


def _v272_budget(self, now=None):
    now=float(now or time.time()); sec_left=max(0.0,900.0-(now%900.0))
    try: stats=dict(_v2672_movement_stats(self,now=now) or {})
    except Exception: stats={}
    if not stats.get('ready'):
        return {'ready':False,'seconds_left':sec_left,'budget':0.0,'activity':1.0,'quantum':0.0,'stats':stats}
    q=max(.05,float(stats.get('quantum_5s',0.0) or 0.0))
    activity=max(.25,min(2.25,float(stats.get('activity',1.0) or 1.0)))
    steps=max(1.0,sec_left/5.0)
    stochastic=q*math.sqrt(steps)*(1.45+.22*math.sqrt(activity))
    drift=abs(float(stats.get('velocity_30s',0.0) or 0.0))*min(sec_left,90.0)*.22
    drift=min(drift,stochastic*.70)
    budget=max(1.0,stochastic+drift)
    return {'ready':True,'seconds_left':sec_left,'budget':budget,'activity':activity,'quantum':q,'stats':stats}


def _v272_forecast_read(self, now=None, force=False):
    """Forward 15m path + settlement projection. Current winner is OUTPUT ONLY."""
    now=float(now or time.time()); bucket=int(now//900)*900
    cache=dict(getattr(self,'_v272_forecast_cache',{}) or {})
    if (not force and int(cache.get('bucket',-1) or -1)==bucket and cache.get('value') and
            now-float(cache.get('ts',0.0) or 0.0)<.16):
        return dict(cache['value'])

    try: live,target,live_src,target_src=_v268_target_live(self)
    except Exception:
        try:
            live,target,live_src=_v2672_target_and_live(self); target_src='KALSHI TARGET'
        except Exception:
            live=target=None; live_src=target_src='WAIT'
    try: live=float(live) if live is not None else None
    except Exception: live=None
    try: target=float(target) if target is not None else None
    except Exception: target=None
    if live is None or target is None:
        out={'ready':False,'settlement_side':'WAIT','path_side':'WAIT','confidence':50.0,'quality':0.0,
             'reason':'FORECAST BUILDING • need live Bookmap price + exact target','live':live,'target':target}
        self._v272_forecast_cache={'bucket':bucket,'ts':now,'value':dict(out)}; return out

    try: dyn=dict(_v268_dynamic_read(self,now=now,force=force) or {})
    except Exception: dyn={}
    try: trend=dict(_v270_trend_regime_read(self,now=now,force=force) or {})
    except Exception: trend={}
    try: path=dict(_v26722_path_consensus(self,warm=(dyn.get('warm') or {}),now=now) or {})
    except Exception: path=dict(dyn.get('path') or {})
    try: dest=dict(_v26719_destination_context(self,warm=(dyn.get('warm') or {}),now=now) or {})
    except Exception: dest=dict(dyn.get('dest') or {})
    budget=_v272_budget(self,now=now)

    # Independent fair-value/reversion anchor. Fair-value construction itself does
    # not use the lock side; it uses native Bookmap micro candles / VWAP / target.
    fair={}; fair_pull=0.0; fair_delta=0.0
    try:
        micro=dict(_v2673_micro_read(self,now=now) or {})
        ctx=dict(_v2673_context(self,now=now) or {})
        fair=dict(_v2673_fair_value(self,ctx,micro,now=now) or {})
        if fair.get('ready'):
            fair_delta=float(fair.get('fair',live))-live
            scale=max(8.0,float(budget.get('budget',0) or 0)*.34,float(fair.get('atr',0) or 0)*.22)
            fair_pull=math.tanh(fair_delta/max(scale,1e-9))
    except Exception:
        micro={}; fair={}

    fam=dict(dyn.get('families') or {})
    def fs(name):
        r=dict(fam.get(name) or {})
        return float(r.get('score',0.0) or 0.0) if r.get('available') else 0.0
    struct=float(path.get('score',fs('STRUCTURE_PATH')) or 0.0) if path.get('ready') else fs('STRUCTURE_PATH')
    dscore=float(dest.get('score',fs('DESTINATION')) or 0.0) if dest.get('ready',False) else fs('DESTINATION')
    tscore=float(trend.get('score',0.0) or 0.0) if trend.get('ready') else 0.0
    # Fast flow is intentionally tiny. It can refine timing, not decide the 15m destination.
    fast_vals=[]
    for n,w in (('EXEC_FLOW',.46),('MICRO_3S5S',.34),('WHALE_ABSORB',.20)):
        r=dict(fam.get(n) or {})
        if r.get('available'): fast_vals.append((float(r.get('score',0.0) or 0.0),w))
    fden=sum(w for _v,w in fast_vals); fast=sum(v*w for v,w in fast_vals)/fden if fden else 0.0

    components=[]
    def add(name,val,wt,available=True):
        if available and wt>0: components.append((name,_v272_clip(val),float(wt)))
    add('MULTI_TF_TREND',tscore,.34,bool(trend.get('ready')))
    add('STRUCTURE_PATH',struct,.27,bool(path.get('ready') or (fam.get('STRUCTURE_PATH') or {}).get('available')))
    add('DESTINATION',dscore,.20,bool(dest.get('ready') or (fam.get('DESTINATION') or {}).get('available')))
    add('FAIR_REVERSION',fair_pull,.11,bool(fair.get('ready')))
    add('FAST_CONFIRM',fast,.08,bool(fast_vals))
    den=sum(w for _n,_v,w in components)
    raw_path=sum(v*w for _n,v,w in components)/den if den else 0.0

    # Strong established trend is a governor on the projected PATH, not a direct
    # Kalshi-side veto. A settlement can still be UP while path is DOWN if the
    # target cushion is projected to survive the remaining move.
    reversal={}
    path_side0='UP' if raw_path>=.11 else 'DOWN' if raw_path<=-.11 else 'WAIT'
    tside=str(trend.get('side','NEUTRAL')).upper(); tstrong=bool(trend.get('strong')) and tside in ('UP','DOWN')
    if path_side0 in ('UP','DOWN') and tstrong and path_side0!=tside:
        try: reversal=dict(_v270_reversal_proof(self,path_side0,dyn,trend) or {})
        except Exception: reversal={}
        if not reversal.get('confirmed'):
            raw_path*=.46
    raw_path=_v272_clip(raw_path)
    path_side='UP' if raw_path>=.10 else 'DOWN' if raw_path<=-.10 else ('UP' if tscore>.18 else 'DOWN' if tscore<-.18 else 'WAIT')

    b=max(1.0,float(budget.get('budget',0) or max(15.0,abs(live-target))))
    q=max(.5,float(budget.get('quantum',0) or 1.0))
    # Forward drift uses remaining movement capacity. This is deliberately not
    # "live-target" sign and therefore cannot simply mirror the current winner.
    drift_frac=.18+.38*min(1.0,abs(raw_path))
    path_drift=raw_path*b*drift_frac
    # Small independent mean-reversion pull; never enough to overpower structure alone.
    mean_component=fair_delta*min(.24,.08+.16*abs(fair_pull)) if fair.get('ready') else 0.0
    center=live+path_drift+mean_component

    trend_read=float(trend.get('readability',0.0) or 0.0)
    path_q=min(1.0,max(0.0,float(path.get('quality',0.0) or 0.0)/100.0)) if path.get('ready') else 0.0
    dyn_q=min(1.0,max(0.0,float(dyn.get('quality',0.0) or 0.0)/100.0))
    coherence=min(1.0,max(0.0,float(dyn.get('coherence',0.0) or 0.0)))
    coverage=min(1.0,len(components)/5.0)
    quality=_v272_clip(.28*trend_read+.24*path_q+.22*dyn_q+.16*coherence+.10*coverage,0,1)
    if not budget.get('ready'): quality*=.72
    uncertainty=max(q*2.2,b*(.50-.22*quality))
    proj_low=center-uncertainty; proj_high=center+uncertainty
    finish_delta=center-target
    settle_score=math.tanh(finish_delta/max(uncertainty*.78,5.0))
    settlement_side='UP' if settle_score>=.12 else 'DOWN' if settle_score<=-.12 else 'WAIT'
    confidence=50.0+min(47.0,abs(settle_score)*49.0*(.66+.34*quality))
    if proj_low<=target<=proj_high: confidence-=min(9.0,9.0*(1.0-abs(settle_score)))
    confidence=max(50.0,min(97.0,confidence))
    current_winner='UP' if live>target else 'DOWN' if live<target else 'LINE'

    reason=(f'PROJECTED FINISH {center-target:+.0f}$ vs target • PATH {path_side} {raw_path:+.2f} • '
            f'trend {tscore:+.2f} • structure {struct:+.2f} • destination {dscore:+.2f} • '
            f'fair {fair_pull:+.2f} • fast confirm {fast:+.2f} • current winner {current_winner} (NOT AUTHORITY)')
    out={'ready':bool(components) and budget.get('ready',False),'live':live,'target':target,
         'live_source':live_src,'target_source':target_src,'seconds_left':float(budget.get('seconds_left',0) or 0),
         'budget':b,'activity':float(budget.get('activity',1.0) or 1.0),'quantum':q,
         'path_score':raw_path,'path_side':path_side,'settlement_score':settle_score,
         'settlement_side':settlement_side,'confidence':confidence,'quality':quality*100.0,
         'projected_center':center,'projected_low':proj_low,'projected_high':proj_high,
         'finish_delta':finish_delta,'current_winner':current_winner,'trend':trend,'path':path,'dest':dest,
         'fair':fair,'dynamic':dyn,'components':{n:{'score':v,'weight':w} for n,v,w in components},
         'reversal_proof':reversal,'reason':reason}
    self._v272_forecast_cache={'bucket':bucket,'ts':now,'value':dict(out)}
    self._v272_last_forecast=dict(out)
    return out


def _v272_lock_read(self, now=None, state=None, force=False):
    """Main lock comes ONLY from projected settlement, never route_side."""
    now=float(now or time.time()); bucket=int(now//900)*900
    if not isinstance(getattr(self,'_v272_lock_state',None),dict): _v272_reset(self)
    st=dict(self._v272_lock_state or {})
    if int(st.get('bucket',-1) or -1)!=bucket:
        _v272_reset(self); st=dict(self._v272_lock_state); st['bucket']=bucket
    # Compatibility: older callers may pass a V21.68 dynamic-route packet as `state`.
    # That packet must NEVER become forecast authority; ignore it unless it is a V21.72 projection.
    if isinstance(state,dict) and 'settlement_side' in state:
        fc=dict(state)
    else:
        fc=dict(_v272_forecast_read(self,now=now,force=force) or {})
    status=str(st.get('status','WATCH')).upper(); side=str(st.get('side','WAIT')).upper()
    cand=str(fc.get('settlement_side','WAIT')).upper(); conf=float(fc.get('confidence',50) or 50)
    qual=float(fc.get('quality',0) or 0); edge=float(fc.get('settlement_score',0) or 0)
    sec=float(fc.get('seconds_left',0) or 0); current=str(fc.get('current_winner','LINE')).upper()

    # Audit an existing forecast lock. Opposite fast route alone does NOT kill it.
    if status=='LOCKED' and side in ('UP','DOWN'):
        sign=_v272_sign(side); opp='DOWN' if side=='UP' else 'UP'
        signed=sign*edge
        projected_opp=(str(fc.get('settlement_side','WAIT')).upper()==opp and conf>=65 and signed<=-.20)
        deep_opp=(signed<=-.40 and conf>=70)
        # Near settlement current price matters only when the forward model ALSO invalidates.
        late_pressure=(sec<=75 and current==opp and signed<=-.10)
        hard=bool(projected_opp and (deep_opp or late_pressure or abs(float(fc.get('finish_delta',0) or 0))>=max(6.0,float(fc.get('quantum',1))*2.0)))
        soft=(signed<=-.10 and str(fc.get('settlement_side','WAIT')).upper()==opp)
        if hard:
            st.update({'status':'BROKEN','side':'WAIT','break_since':now,'cooldown_until':now+.40,
                       'strength':max(0.0,conf),'last_reason':f'FORECAST INVALIDATED • projected finish flipped {opp} • {fc.get("reason","")}'})
            self.opening_lock_snapshot=None
        elif soft:
            if not float(st.get('break_since',0) or 0): st['break_since']=now
            age=now-float(st.get('break_since',now) or now)
            if age>=.72:
                st.update({'status':'BROKEN','side':'WAIT','cooldown_until':now+.45,'strength':conf,
                           'last_reason':f'FORECAST BROKEN • opposite projected finish persisted {age:.2f}s • {fc.get("reason","")}'})
                self.opening_lock_snapshot=None
            else:
                st['last_reason']=f'FORECAST UNDER REVIEW {age:.2f}s • projected finish threatening {opp}'
        else:
            st['break_since']=0.0; st['strength']=conf
            st['last_reason']=(f'FORECAST HEALTHY • {side} finish still projected • PATH {fc.get("path_side","WAIT")} • '
                               f'center {float(fc.get("finish_delta",0) or 0):+.0f}$ vs target • current winner {current} ≠ authority')

    status=str(st.get('status','WATCH')).upper()
    if status!='LOCKED':
        # Candidate source is PROJECTED SETTLEMENT SIDE. Never route_side.
        cand=str(fc.get('settlement_side','WAIT')).upper() if fc.get('ready') else 'WAIT'
        sign=_v272_sign(cand)
        signed=sign*edge if sign else 0.0
        trend=dict(fc.get('trend') or {})
        readable=float(trend.get('readability',0) or 0)
        decisive=(cand in ('UP','DOWN') and conf>=76 and abs(edge)>=.48 and qual>=55)
        # A huge projected target cushion can still be forecastable in noisy structure;
        # otherwise require at least moderate structural readability.
        structure_ok=(readable>=.22 or abs(edge)>=.58)
        qualifies=(cand in ('UP','DOWN') and now>=float(st.get('cooldown_until',0) or 0) and
                   conf>=63 and qual>=43 and abs(edge)>=.22 and structure_ok)
        if qualifies:
            if str(st.get('candidate','WAIT')).upper()!=cand:
                st.update({'candidate':cand,'candidate_since':now,'candidate_samples':1})
            else: st['candidate_samples']=int(st.get('candidate_samples',0) or 0)+1
            age=max(0.0,now-float(st.get('candidate_since',now) or now))
            need_age=.55 if decisive else 1.10; need_samples=3 if decisive else 5
            st['status']='ARMING'; st['strength']=conf
            st['last_reason']=(f'{cand} FORECAST ARMING • {conf:.0f}/100 • projected center '
                               f'{float(fc.get("finish_delta",0) or 0):+.0f}$ vs target • PATH {fc.get("path_side","WAIT")} • '
                               f'{age:.2f}s {st["candidate_samples"]}/{need_samples} • current winner {current} NOT authority')
            if age>=need_age and int(st.get('candidate_samples',0) or 0)>=need_samples:
                st.update({'status':'LOCKED','side':cand,'locked_since':now,'break_since':0.0,
                           'candidate':'WAIT','candidate_since':0.0,'candidate_samples':0,
                           'last_reason':f'MAIN FORECAST EARNED {cand} • {conf:.0f}/100 • PATH {fc.get("path_side","WAIT")} • projected finish {float(fc.get("finish_delta",0) or 0):+.0f}$'})
                snap={'time':now,'price':fc.get('live'),'lock_side':cand,'lock_remaining':'FORECAST','lock_minute':int((now%900)//60),
                      'forecast_score':edge*10.0,'forecast_threshold':2.2,'forecast_reasons':st['last_reason'],
                      'source':'V21.72 MAIN FORECAST LOCK','strength':conf,'revocable':True,
                      'projected_center':fc.get('projected_center'),'projected_low':fc.get('projected_low'),
                      'projected_high':fc.get('projected_high'),'path_side':fc.get('path_side'),'current_winner':current}
                self.opening_lock_snapshot=dict(snap)
        else:
            st['candidate']='WAIT'; st['candidate_since']=0.0; st['candidate_samples']=0
            if status!='BROKEN': st['status']='WATCH'
            st['strength']=conf if fc.get('ready') else 0.0
            st['last_reason']=(f'FORECAST WATCH • settle {cand} {conf:.0f}/100 • PATH {fc.get("path_side","WAIT")} • '
                               f'edge {edge:+.2f} • quality {qual:.0f} • current winner {current} NOT authority')
            if status=='BROKEN' and now>=float(st.get('cooldown_until',0) or 0): st['status']='WATCH'

    status=str(st.get('status','WATCH')).upper(); side=str(st.get('side','WAIT')).upper()
    if status=='LOCKED' and side in ('UP','DOWN'):
        if not getattr(self,'opening_lock_snapshot',None) or str(self.opening_lock_snapshot.get('lock_side','')).upper()!=side:
            self.opening_lock_snapshot={'time':float(st.get('locked_since',now) or now),'price':fc.get('live'),'lock_side':side,
                'lock_remaining':'FORECAST','lock_minute':int((now%900)//60),'forecast_score':edge*10.0,
                'forecast_threshold':2.2,'forecast_reasons':st.get('last_reason',''),'source':'V21.72 MAIN FORECAST LOCK',
                'strength':float(st.get('strength',0) or 0),'revocable':True,'projected_center':fc.get('projected_center'),
                'path_side':fc.get('path_side'),'current_winner':current}
    else: self.opening_lock_snapshot=None

    out={'ready':status=='LOCKED','status':status,'side':side if status=='LOCKED' else 'WAIT',
         'lock_side':side if status=='LOCKED' else 'WAIT','candidate':st.get('candidate','WAIT'),
         'strength':float(st.get('strength',0) or 0),'reason':st.get('last_reason',''),
         'candidate_samples':int(st.get('candidate_samples',0) or 0),
         'candidate_age':max(0.0,now-float(st.get('candidate_since',now) or now)) if st.get('candidate_since') else 0.0,
         'locked_age':max(0.0,now-float(st.get('locked_since',now) or now)) if status=='LOCKED' else 0.0,
         'forecast':fc,'snapshot':dict(self.opening_lock_snapshot) if self.opening_lock_snapshot else None}
    st['last']=dict(out)
    try: st['history'].append({'ts':now,'status':status,'side':out['side'],'candidate':out['candidate'],'forecast_side':cand,'edge':edge,'conf':conf,'path':fc.get('path_side')})
    except Exception: pass
    self._v272_lock_state=st; self._v272_last_lock=dict(out)
    return out


def _v272_exit_read(self, trade_side, now=None, forecast=None, lock=None):
    now=float(now or time.time()); side=str(trade_side or 'WAIT').upper()
    if side not in ('UP','DOWN'): return {'exit':False,'state':'NO POSITION','risk':0.0,'reason':'no position'}
    fc=dict(forecast or _v272_forecast_read(self,now=now) or {})
    lk=dict(lock or _v272_lock_read(self,now=now,state=fc) or {})
    sign=_v272_sign(side); score=sign*float(fc.get('settlement_score',0) or 0)
    opp='DOWN' if side=='UP' else 'UP'; pred=str(fc.get('settlement_side','WAIT')).upper()
    conf=float(fc.get('confidence',50) or 50); sec=float(fc.get('seconds_left',0) or 0)
    current=str(fc.get('current_winner','LINE')).upper()
    legacy={}
    try: legacy=dict(_v268_exit_read(self,side,now=now,state=fc.get('dynamic')) or {})
    except Exception: legacy={}
    forecast_flip=(pred==opp and conf>=65 and score<=-.18)
    broken=str(lk.get('status','')).upper()=='BROKEN'
    emergency=bool(sec<=70 and current==opp and legacy.get('exit') and float(legacy.get('risk',0) or 0)>=78 and score<=-.05)
    risk=_v272_clip(.64*max(0.0,-score)+.22*(float(legacy.get('risk',0) or 0)/100.0)+.14*(1.0 if broken else 0.0),0,1)*100.0
    if broken or (forecast_flip and (score<=-.32 or conf>=72)) or emergency:
        state=f'FLIP CONFIRMED → {opp} • EXIT NOW' if forecast_flip else 'EXIT NOW • FORECAST BROKEN'
        return {'exit':True,'state':state,'risk':max(risk,74.0),'reason':f'projected settlement invalidated {side} • {fc.get("reason","")}' }
    if forecast_flip or score<=-.06:
        return {'exit':False,'state':'CAUTION — FORECAST FLIP BUILDING','risk':max(risk,38.0),'reason':f'projected finish weakening {side} • {fc.get("reason","")}' }
    return {'exit':False,'state':'HOLD — FORECAST INTACT','risk':risk,'reason':f'{side} projected finish intact • PATH {fc.get("path_side","WAIT")} • center {float(fc.get("finish_delta",0) or 0):+.0f}$ vs target'}


def _v272_open_lock_tick(self, warm=None, now=None):
    lk=_v272_lock_read(self,now=now)
    fc=dict(lk.get('forecast') or {})
    if lk.get('status')=='LOCKED':
        _v268_var_set(self,'opening_lock_var',f"MAIN FORECAST LOCK: {lk['side']} {lk['strength']:.0f}/100 • PATH {fc.get('path_side','WAIT')} • finish {float(fc.get('finish_delta',0) or 0):+.0f}$ vs target")
        return dict(lk.get('snapshot') or {})
    if lk.get('status')=='ARMING':
        _v268_var_set(self,'opening_lock_var',f"FORECAST ARMING: {lk.get('candidate','WAIT')} {lk['strength']:.0f}/100 • PATH {fc.get('path_side','WAIT')} • current winner {fc.get('current_winner','--')} NOT authority")
    elif lk.get('status')=='BROKEN':
        _v268_var_set(self,'opening_lock_var','MAIN FORECAST LOCK BROKEN • RE-PROJECTING • '+str(lk.get('reason','')))
    else:
        _v268_var_set(self,'opening_lock_var','FORECAST WATCH • '+str(lk.get('reason','')))
    return None


def _v272_master_read(self, now=None):
    now=float(now or time.time()); fc=_v272_forecast_read(self,now=now); lk=_v272_lock_read(self,now=now,state=fc)
    side=str(lk.get('side','WAIT')).upper(); ready=bool(lk.get('ready')) and side in ('UP','DOWN')
    return {'ready':ready,'side':side if ready else 'WAIT','entry_authority':'V21.72 MAIN FORECAST LOCK',
            'roughness':1.0-min(1.0,float(fc.get('quality',0) or 0)/100.0),'health':min(1.0,float(fc.get('confidence',50) or 50)/100.0),
            'road':'PROJECTED SETTLEMENT LOCK' if ready else 'WAIT FOR FORWARD FORECAST','seconds_left':fc.get('seconds_left',0),
            'risk':0.0,'survival':100.0,'forecast':fc,'lock':lk,
            'reason':f"{lk.get('status','WATCH')} • {lk.get('reason','')}"}


def _v272_master_step(self, warm=None, sig=None, candles=None, now=None, mode='LIVE'):
    now=float(now or time.time())
    if now-float(getattr(self,'_v272_last_step',0.0) or 0.0)<.10:return False
    self._v272_last_step=now
    try:_v264_paper_mark(self)
    except Exception:pass
    fc=_v272_forecast_read(self,now=now); lk=_v272_lock_read(self,now=now,state=fc)
    if getattr(self,'paper_active_trade',None):
        trade=dict(self.paper_active_trade); bucket=int(trade.get('bucket',0) or 0); current=int(now//900)*900
        if bucket<current:_v264_reconcile_settlement_async(self); return False
        x=_v272_exit_read(self,trade.get('direction'),now=now,forecast=fc,lock=lk); self._v268_last_exit=dict(x)
        _v268_var_set(self,'paper_exit_status_var',f"V21.72 {x['state']} • risk {x['risk']:.0f}/100 • projected {fc.get('settlement_side','WAIT')} • PATH {fc.get('path_side','WAIT')}")
        _v268_var_set(self,'auto_paper_reason_var',x.get('reason',''))
        if x.get('exit') and bool(self.paper_auto_exit_var.get()):
            _contract,yes_equiv,_src,_age=_v264_paper_price(self,trade['direction'],'EXIT',_V264_EXIT_QUOTE_MAX_AGE)
            if yes_equiv is not None:return bool(_v264_paper_finalize(self,exit_yes=yes_equiv,reason='V21.72 FORECAST EXIT • '+x.get('state','EXIT')+' • '+x.get('reason','')))
        return False
    if not bool(self.auto_paper_enabled_var.get()):
        _v268_var_set(self,'auto_paper_score_var','V21.72 PAPER AUTO: OFF'); return False
    bucket=int(now//900)*900
    if _v268_round_has_trade(self,bucket):
        self._v267_traded_bucket=bucket; _v268_var_set(self,'auto_paper_score_var','V21.72 PAPER: ROUND ALREADY TRADED'); return False
    master=_v272_master_read(self,now=now)
    if not master.get('ready'):
        _v268_var_set(self,'auto_paper_score_var',f"V21.72 {lk.get('status')} • FORECAST {fc.get('settlement_side','WAIT')} • PATH {fc.get('path_side','WAIT')} • WAIT")
        _v268_var_set(self,'auto_paper_reason_var',master.get('reason','building forward forecast')); return False
    side=str(master['side']).upper(); ask,_yes,qsrc,qage=_v264_paper_price(self,side,'ENTER',_V264_ENTRY_QUOTE_MAX_AGE)
    if ask is None:
        _v268_var_set(self,'auto_paper_score_var',f'V21.72 {side} FORECAST LOCK READY • KALSHI BBO WAIT'); return False
    plan=_v264_value_plan(self,master,ask,now); self._v264_last_plan=dict(plan)
    _v268_var_set(self,'auto_paper_score_var',f"V21.72 MAIN {side} • PATH {fc.get('path_side','WAIT')} • PROJECTED {float(fc.get('finish_delta',0) or 0):+.0f}$ • ASK {ask*100:.1f}c")
    _v268_var_set(self,'auto_paper_reason_var',f"{plan.get('state','WAIT')} • {master.get('reason','')} • {qsrc} age {float(qage or 0):.2f}s")
    if not plan.get('enter'):return False
    freshfc=_v272_forecast_read(self,now=time.time(),force=True); freshlk=_v272_lock_read(self,now=time.time(),state=freshfc,force=True)
    if not freshlk.get('ready') or str(freshlk.get('side','WAIT')).upper()!=side:
        _v268_var_set(self,'auto_paper_reason_var','ENTRY CANCELLED • projected settlement changed during final check'); return False
    opened=bool(_v264_paper_open(self,side,entry_source='V21.72 MAIN FORECAST LOCK AUTO',auto_score=float(freshlk.get('strength',0)),
        auto_reason=f"V21.72 projected settlement • PATH {freshfc.get('path_side','WAIT')} • {freshlk.get('reason','')} • {plan.get('state','')}"))
    if opened:self._v267_traded_bucket=bucket
    return opened


def _v272_journey_read(self, now=None):
    fc=_v272_forecast_read(self,now=now); lk=_v272_lock_read(self,now=now,state=fc)
    if not fc.get('ready'):
        return {'ready':False,'headline':'15M FORECAST MAPPER: building forward projection','stage':'BUILDING',
                'route_text':fc.get('reason','building'),'checkpoint_text':'NEXT CHECKPOINT: --','finish_text':'PROJECTED SETTLEMENT: --','evidence_text':'FORWARD EVIDENCE: building'}
    live=float(fc['live']); target=float(fc['target']); center=float(fc['projected_center']); lo=float(fc['projected_low']); hi=float(fc['projected_high'])
    path=str(fc.get('path_side','WAIT')); settle=str(fc.get('settlement_side','WAIT')); lockside=str(lk.get('side','WAIT')) if lk.get('ready') else settle
    checkpoints=[]
    # If projected path traverses the target, make that explicit; otherwise target is a defense line.
    if (live-target)*(center-target)<=0:
        checkpoints.append({'price':target,'label':'PROJECTED TARGET CROSS','kind':'TARGET','score':90})
    else:
        checkpoints.append({'price':target,'label':'TARGET DEFENSE LINE','kind':'TARGET','score':75})
    fair=dict(fc.get('fair') or {})
    if fair.get('ready'):
        fp=float(fair.get('fair')); 
        if min(live,center)<=fp<=max(live,center): checkpoints.append({'price':fp,'label':'FAIR-VALUE WAYPOINT','kind':'REVERSION','score':65})
    checkpoints.append({'price':center,'label':'PROJECTED SETTLEMENT CENTER','kind':'FINISH','score':90})
    checkpoints=sorted(checkpoints,key=lambda c:abs(float(c['price'])-live))[:5]
    cp=checkpoints[0] if checkpoints else None
    cptext=f"NEXT CHECKPOINT: {cp['label']} @ {money(cp['price'])} • {abs(float(cp['price'])-live):.0f}$ away" if cp else 'NEXT CHECKPOINT: --'
    stage='MAIN FORECAST LOCKED' if lk.get('ready') else 'FORWARD FORECAST FORMING'
    headline=f"15M FORECAST: SETTLE {settle} {float(fc.get('confidence',50)):.0f}/100 • PATH {path} • LOCK {lk.get('status','WATCH')} {lockside}"
    route_text=(f"EXPECTED PATH: {path} • now {money(live)} → projected center {money(center)} • "
                f"current winner {fc.get('current_winner','--')} is NOT lock authority")
    finish_text=f"PROJECTED SETTLEMENT: {money(lo)} → {money(hi)} • center {money(center)} ({center-target:+.0f}$ vs target) • forecast {settle}"
    evidence='FORWARD EVIDENCE: '+fc.get('reason','')
    return {'ready':True,'headline':headline,'stage':stage,'lock_side':lockside,'route_side':path,'route_match':float(fc.get('confidence',50)),
            'route_text':route_text,'checkpoint_text':cptext,'reversion_text':'MEAN REVERSION: included as bounded forward component',
            'finish_text':finish_text,'evidence_text':evidence,'live':live,'target':target,'fair':fair,
            'projected_low':lo,'projected_high':hi,'projected_center':center,'checkpoints':checkpoints,
            'seconds_left':fc.get('seconds_left',0),'forecast':fc,'lock':lk}


def _v272_ui_tick(self):
    try:
        fc=_v272_forecast_read(self,now=time.time()); lk=_v272_lock_read(self,now=time.time(),state=fc)
        lkst=str(lk.get('status','WATCH')).upper(); side=str(lk.get('side','WAIT')).upper(); cand=str(lk.get('candidate','WAIT')).upper()
        conf=float(fc.get('confidence',50) or 50); path=str(fc.get('path_side','WAIT')); settle=str(fc.get('settlement_side','WAIT')); curr=str(fc.get('current_winner','--'))
        if lkst=='LOCKED': headline=f'MAIN FORECAST LOCK: {side} {float(lk.get("strength",0)):.0f}/100 • PATH {path} • projected {float(fc.get("finish_delta",0) or 0):+.0f}$'
        elif lkst=='ARMING': headline=f'FORECAST ARMING: {cand} {float(lk.get("strength",0)):.0f}/100 • PATH {path}'
        elif lkst=='BROKEN': headline='MAIN FORECAST LOCK BROKEN • RE-PROJECTING'
        else: headline=f'FORECAST WATCH • projected {settle} {conf:.0f}/100 • PATH {path}'
        _v268_var_set(self,'opening_lock_var',headline+' • '+str(lk.get('reason','')))
        _v268_var_set(self,'lock_pick_var',f'{lkst} • {side if lkst=="LOCKED" else cand} • FORECAST {settle} {conf:.0f}/100')
        _v268_var_set(self,'lock_distance_var',f'PROJECTED CENTER {float(fc.get("finish_delta",0) or 0):+.0f}$ vs target • PATH {path} {float(fc.get("path_score",0)):+.2f}')
        _v268_var_set(self,'lock_minute_status_var','V21.72 MAIN LOCK = PROJECTED SETTLEMENT • current winner/route cannot choose it')
        _v268_var_set(self,'lock_matrix_var',f'FORECAST {settle} • PATH {path} • CURRENT {curr} • quality {float(fc.get("quality",0)):.0f}')
        _v268_var_set(self,'lock_forecast_why_var','FORECAST WHY: '+str(fc.get('reason','')))
        _v268_var_set(self,'reversal_status_var',f'LOCK {lkst} • FORECAST {settle} • PATH {path} • CURRENT {curr}')
        _v268_var_set(self,'reversal_action_var','CURRENT WINNER ≠ AUTHORITY • exit only when projected settlement thesis invalidates')
        self.last_direction_truth={'up':max(5,min(95,50+float(fc.get('settlement_score',0))*45)),
            'down':max(5,min(95,50-float(fc.get('settlement_score',0))*45)),
            'raw_favored':side if lkst=='LOCKED' else settle,'edge':f'V21.72 settle {float(fc.get("settlement_score",0)):+.2f}',
            'reason':fc.get('reason',''),'regime':f'V21.72 PATH {path}','lock_side':side if lkst=='LOCKED' else 'WAIT'}
    except Exception: pass
    finally:
        try:self.root.after(180,lambda s=self:_v272_ui_tick(s))
        except Exception:pass


