def _v272_init(self,*args,**kwargs):
    # BOOT-SAFE: the V21.72 forecast layer is never allowed to prevent the UI from opening.
    self._v272_forecast_cache={}; self._v272_lock_state={}; self._v272_last_forecast={}; self._v272_last_lock={}; self._v272_last_step=0.0
    _V272_BASE_INIT(self,*args,**kwargs)
    try:
        _v272_reset(self)
        self._auto_paper_unified_tick=_v272_master_step.__get__(self,ChartKingPro)
        self._v272_boot_ok=True
        self._v272_boot_error=''
    except Exception as exc:
        self._v272_boot_ok=False
        self._v272_boot_error=str(exc)
        try:
            self._v272_forecast_cache={}
            self._v272_lock_state={'status':'WATCH','side':'WAIT','candidate':'WAIT','history':deque(maxlen=900),'last_reason':'FORECAST BOOT FALLBACK'}
        except Exception:
            pass
        try:
            self.root.after(0, lambda e=str(exc), s=self: _v268_var_set(s,'opening_lock_var','V21.72 FORECAST BOOT FALLBACK • '+e))
        except Exception:
            pass
    try:
        self.paper_status_var.set('PAPER AUTO: V21.72.1 BOOT-SAFE MAIN FORECAST LOCK')
        self.root.title(f'BOOKMAP KING V21.72.1 — BOOT-SAFE MAIN FORECAST + V21.71 TURBO {float(getattr(self,"_v271_target_hz",0) or 0):.0f}HZ')
    except Exception:
        pass


