# ============================================================================
# LECHART JAMES V21.73 — CLEAN 60HZ CHART + SLIM SIDEBAR
#
# UI / RENDER ONLY. V21.72.1 forecast-lock / paper-trading authority is kept.
# - 60 Hz live forming candle / live-price path by default (30 Hz hard floor).
# - ~30 Hz full structure redraw when measured draw cost is cheap enough.
# - Slim fixed right sidebar; reclaimed width is given to the chart column.
# - Clean-chart presentation hides large advisory boxes and duplicate labels
#   while preserving candles, live price, target, trend/SR lines and geometry.
# - Removes the visual RSI subpanel + duplicate story rows from the chart card
#   and gives that vertical space back to the main candle canvas.
# ============================================================================

_V273_RELEASE = 'V21.73'
_V273_BASE_INIT = ChartKingPro.__init__
_V273_BASE_DRAW = ChartKingPro.draw_chart
_V273_BASE_FIT = ChartKingPro._v84_fit_horizontal_width


def _v273_target_live_hz():
    """Stable default for Tk Canvas: 60 Hz live paint, never below 30 Hz."""
    try:
        forced = float(os.environ.get('BOOKMAP_KING_RENDER_HZ', '60') or 60)
    except Exception:
        forced = 60.0
    return max(30.0, min(120.0, forced))


def _v273_is_descendant(widget, ancestor):
    try:
        cur = widget
        while cur is not None:
            if cur is ancestor:
                return True
            cur = getattr(cur, 'master', None)
    except Exception:
        pass
    return False


def _v273_apply_column_widths(self):
    """Keep right evidence rail slim and donate released pixels to chart."""
    try:
        center_canvas = getattr(self, 'center_scroll_canvas', None)
        brain_canvas = getattr(self, 'brain_canvas', None)
        if center_canvas is None or brain_canvas is None:
            return False
        center_outer = center_canvas.master
        side_outer = brain_canvas.master
        body = center_outer.master
        body.update_idletasks()
        W = max(900, int(body.winfo_width() or 0))

        # Keep the left control column untouched. Only reclaim width from right.
        cx = int(center_outer.winfo_x() or 0)
        right_w = int(max(220, min(270, W * 0.135)))
        gap = 6
        right_x = max(cx + 520, W - right_w)
        center_w = max(520, right_x - cx - gap)

        if str(center_outer.winfo_manager()) == 'place':
            center_outer.place_configure(x=cx, width=center_w)
        else:
            center_outer.configure(width=center_w)
        if str(side_outer.winfo_manager()) == 'place':
            side_outer.place_configure(x=right_x, width=right_w)
        else:
            side_outer.configure(width=right_w)

        # Re-run the saved horizontal geometry only for descendants of the
        # center/right columns. This preserves V8.2's anti-jitter frozen layout.
        records = getattr(self, '_v84_horizontal_records', None) or []
        assigned = {str(center_outer): center_w, str(side_outer): right_w}
        center_window = getattr(self, 'center_scroll_window', None)
        center_content = getattr(self, 'center_content', None)
        brain_window = getattr(self, 'brain_window', None)
        brain_content = getattr(self, 'brain_content', None)

        for row in records:
            child = row.get('child')
            parent = row.get('parent')
            if child is None or parent is None:
                continue
            if child is center_outer or child is side_outer:
                continue
            if not (_v273_is_descendant(child, center_outer) or _v273_is_descendant(child, side_outer)):
                continue
            try:
                if not child.winfo_exists() or not parent.winfo_exists():
                    continue
                pkey = str(parent)
                current_parent_width = max(1, int(assigned.get(pkey, parent.winfo_width() or 1)))
                base_parent_width = max(1, int(row.get('parent_width', current_parent_width) or current_parent_width))
                ratio = current_parent_width / float(base_parent_width)
                new_x = int(round(int(row.get('x', 0) or 0) * ratio))
                new_w = max(1, int(round(int(row.get('width', 1) or 1) * ratio)))
                if str(child.winfo_manager()) == 'place':
                    child.place_configure(x=new_x, width=new_w)
                assigned[str(child)] = new_w
                if child is center_canvas:
                    if center_window is not None:
                        center_canvas.itemconfigure(center_window, width=new_w)
                    if center_content is not None:
                        center_content.configure(width=new_w)
                        assigned[str(center_content)] = new_w
                elif child is brain_canvas:
                    if brain_window is not None:
                        brain_canvas.itemconfigure(brain_window, width=new_w)
                    if brain_content is not None:
                        brain_content.configure(width=new_w)
                        assigned[str(brain_content)] = new_w
            except Exception:
                continue

        # Make the compact right card actually wrap to the slim rail.
        try:
            inner_w = max(165, int(right_w - 34))
            if brain_content is not None:
                brain_content.configure(width=max(180, right_w - 18))
                for w in _v251_walk(brain_content):
                    try:
                        cls = w.winfo_class()
                        if cls in ('Label', 'TLabel'):
                            try:
                                old_wrap = int(float(w.cget('wraplength') or 0))
                            except Exception:
                                old_wrap = 0
                            if old_wrap > 0:
                                w.configure(wraplength=inner_w)
                    except Exception:
                        pass
        except Exception:
            pass
        self._v273_right_width = right_w
        self._v273_center_width = center_w
        return True
    except Exception:
        return False


def _v273_find_textvar_widget(parent, var):
    target = str(var)
    try:
        for w in _v251_walk(parent):
            try:
                if str(w.cget('textvariable') or '') == target:
                    return w
            except Exception:
                pass
    except Exception:
        pass
    return None


def _v273_reclaim_chart_height(self):
    """Hide duplicate prose/RSI visuals and expand the actual candle canvas."""
    try:
        c = getattr(self, 'canvas', None)
        if c is None:
            return False
        wrap = c.master
        wrap.update_idletasks()

        # Duplicate long prose already exists elsewhere in the UI. Hide it here.
        for name in ('chart_overlay_story_var', 'chart_trend_story_var'):
            var = getattr(self, name, None)
            if var is None:
                continue
            w = _v273_find_textvar_widget(wrap, var)
            if w is not None:
                try:
                    if str(w.winfo_manager()) == 'place':
                        w.place_forget()
                    elif str(w.winfo_manager()) == 'pack':
                        w.pack_forget()
                    elif str(w.winfo_manager()) == 'grid':
                        w.grid_forget()
                except Exception:
                    pass

        # In the frozen layout the RSI divergence block is the first sibling
        # below the main chart canvas. Hide presentation only; analytics remain.
        cy = int(c.winfo_y() or 0)
        ch = int(c.winfo_height() or 0)
        for w in list(wrap.winfo_children()):
            if w is c:
                continue
            try:
                wy = int(w.winfo_y() or 0)
                if wy >= cy + max(20, ch - 4):
                    # keep no lower presentation panels inside the chart card
                    if str(w.winfo_manager()) == 'place':
                        w.place_forget()
            except Exception:
                pass

        # Move canvas up into the two hidden story rows and stretch downward.
        siblings = []
        for w in wrap.winfo_children():
            if w is c:
                continue
            try:
                if str(w.winfo_manager()) == 'place' and w.winfo_ismapped():
                    siblings.append((int(w.winfo_y()), int(w.winfo_height())))
            except Exception:
                pass
        # Toolbar sits above the chart; use the lowest visible block ending
        # before the old canvas top as our new top anchor.
        ends = [y+h for y,h in siblings if y < cy]
        new_y = (max(ends) + 4) if ends else cy
        total_h = max(300, int(wrap.winfo_height() or (cy + ch)))
        new_h = max(260, total_h - new_y - 8)
        if str(c.winfo_manager()) == 'place':
            c.place_configure(y=new_y, height=new_h)
        self._last_chart_render_key = None
        try:
            self.root.after_idle(self.draw_chart)
        except Exception:
            pass
        return True
    except Exception:
        return False


def _v273_clean_canvas(self):
    """Remove presentation clutter while preserving decision-useful geometry."""
    c = getattr(self, 'canvas', None)
    if c is None:
        return
    # Big overlapping advisory cards add no geometry information.
    for tag in ('v254_labels', 'v26711', 'v26713', 'v261_sources'):
        try:
            c.itemconfigure(tag, state='hidden')
        except Exception:
            pass

    # Keep the actual geometry, hide duplicate text/filled boxes.
    rules = {
        'v26710': {'text', 'rectangle'},   # keep breakout/target lines
        'v26719': {'text'},                # keep trend/SR lines + pivot dots
        'v257_zones': {'text', 'rectangle'}, # keep trigger lines, lose big cards
        'v254_shadow': {'text'},            # keep forward shadow/path, lose caption
    }
    for tag, hidden_types in rules.items():
        try:
            ids = c.find_withtag(tag)
        except Exception:
            ids = ()
        for item in ids:
            try:
                if str(c.type(item)) in hidden_types:
                    c.itemconfigure(item, state='hidden')
            except Exception:
                pass
    # Keep live candle/price visually on top after cleanup.
    for tag in ('v26716_live_candle', 'v82_live'):
        try:
            c.tag_raise(tag)
        except Exception:
            pass


def _v273_draw_chart(self, *args, **kwargs):
    out = _V273_BASE_DRAW(self, *args, **kwargs)
    try:
        _v273_clean_canvas(self)
    except Exception:
        pass
    return out


def _v273_chart_draw_interval(self):
    """Aim for ~30 Hz structure paint when draw cost supports it."""
    ms = float(getattr(self, '_v271_full_draw_ema_ms', 0.0) or 0.0)
    if ms <= 0 or ms <= 20.0:
        return 1.0 / 30.0
    if ms <= 26.0:
        return 0.040   # 25 Hz
    if ms <= 32.0:
        return 0.050   # 20 Hz
    if ms <= 40.0:
        return 0.067   # ~15 Hz
    if ms <= 40.0:
        return 0.100
    return 0.180



def _v273_structure_tick(self):
    """Independent adaptive structure renderer: 30 Hz when the Canvas can sustain it."""
    try:
        now = time.time()
        ms = float(getattr(self, '_v271_full_draw_ema_ms', 0.0) or 0.0)
        if ms <= 20.0:
            hz = 30.0
        elif ms <= 26.0:
            hz = 25.0
        elif ms <= 32.0:
            hz = 20.0
        elif ms <= 40.0:
            hz = 15.0
        else:
            hz = 10.0
        if time.time() < float(getattr(self, '_v256_protect_until', 0.0) or 0.0):
            hz = min(hz, 15.0)
        self._v273_structure_hz_effective = hz
        seq = int(getattr(self, '_v271_visual_seq', 0) or 0)
        last_seq = int(getattr(self, '_v273_structure_seq', -1) or -1)
        last = float(getattr(self, '_v273_last_structure_draw', 0.0) or 0.0)
        due = now - last >= (1.0 / max(1.0, hz))
        changed = seq != last_seq
        heartbeat = now - last >= 0.20
        visible = bool(self._chart_is_visible()) if hasattr(self, '_chart_is_visible') else True
        if (not bool(getattr(self, 'web_only_mode', False)) and visible and
                now >= float(getattr(self, '_scroll_active_until', 0.0) or 0.0) and
                due and (changed or heartbeat)):
            self._v273_last_structure_draw = now
            self._v273_structure_seq = seq
            self._last_live_draw = now
            try:
                self.draw_chart()
            except Exception:
                pass
    except Exception:
        pass
    finally:
        try:
            hz = float(getattr(self, '_v273_structure_hz_effective', 30.0) or 30.0)
            delay = max(16, int(round(1000.0 / max(1.0, hz))))
            self.root.after(delay, lambda s=self: _v273_structure_tick(s))
        except Exception:
            pass


def _v273_fit_horizontal_width(self, viewport_width=None):
    try:
        _V273_BASE_FIT(self, viewport_width)
    finally:
        try:
            _v273_apply_column_widths(self)
        except Exception:
            pass


def _v273_render_status(self):
    try:
        target = float(getattr(self, '_v271_target_hz', 60.0) or 60.0)
        effective = float(getattr(self, '_v271_effective_hz', target) or target)
        draw = float(getattr(self, '_v271_full_draw_ema_ms', 0.0) or 0.0)
        struct = float(getattr(self, '_v273_structure_hz_effective', 30.0) or 30.0)
        _v268_var_set(
            self, 'chart_tf_status_var',
            f'{getattr(self,"chart_tf_var",None).get() if getattr(self,"chart_tf_var",None) else "CHART"} • '
            f'LIVE {effective:.0f}/{target:.0f}Hz • STRUCTURE {struct:.0f}/30Hz • clean mode • draw {draw:.1f}ms'
        )
    except Exception:
        pass
    try:
        self.root.after(900, lambda s=self: _v273_render_status(s))
    except Exception:
        pass


def _v273_init(self, *args, **kwargs):
    _V273_BASE_INIT(self, *args, **kwargs)
    # Do not alter V21.72 forecast / lock state. Presentation only.
    try:
        self._v271_target_hz = _v273_target_live_hz()
        self._v271_effective_hz = self._v271_target_hz
        self.live_draw_interval = min(float(getattr(self, 'live_draw_interval', 0.065) or 0.065), 1.0/30.0)
        self._v273_clean_mode = True
        self.root.title(
            f'BOOKMAP KING V21.73 — MAIN FORECAST LOCK • CLEAN {self._v271_target_hz:.0f}HZ CHART'
        )
        self.root.after(350, lambda s=self: _v273_apply_column_widths(s))
        self.root.after(550, lambda s=self: _v273_reclaim_chart_height(s))
        self.root.after(750, lambda s=self: _v273_clean_canvas(s))
        self._v273_structure_seq = -1
        self._v273_last_structure_draw = 0.0
        self._v273_structure_hz_effective = 30.0
        self.root.after(650, lambda s=self: _v273_structure_tick(s))
        self.root.after(850, lambda s=self: _v273_render_status(s))
    except Exception:
        pass


# Final V21.73 presentation hooks. Forecast/lock/trading methods are unchanged.
ChartKingPro.draw_chart = _v273_draw_chart
ChartKingPro._chart_draw_interval = _v273_chart_draw_interval
ChartKingPro._v84_fit_horizontal_width = _v273_fit_horizontal_width
ChartKingPro.__init__ = _v273_init

# END V21.73 CLEAN 60HZ CHART + SLIM SIDEBAR



# ============================================================================
# BOOKMAP KING V21.74 — HARD 60HZ / COMPACT COCKPIT RUNTIME
#
# Fixes the real V21.67.6+ TRI-KING cockpit rather than the hidden legacy UI.
# - Live forming candle: 60Hz minimum target; monitor-aware up to 144Hz.
# - Cockpit text/meters: 30Hz.
# - Structure/full geometry: adaptive up to 30Hz.
# - Actual right intelligence rail: hard 220px width.
# - Direct on-chart measured renderer badge.
# - No forecast/lock/trading authority changes.
# ============================================================================

_V274_RELEASE='V21.74'
_V274_BASE_INIT=ChartKingPro.__init__


def _v274_detect_target_hz():
    try:
        forced=float(os.environ.get('BOOKMAP_KING_RENDER_HZ','0') or 0)
        if forced>0:
            return max(60.0,min(144.0,forced))
    except Exception:
        pass
    try:
        hz=float(_v271_detect_display_hz())
        return max(60.0,min(144.0,hz))
    except Exception:
        return 60.0


def _v274_force_real_cockpit_layout(self):
    """Hard-enforce the visible TRI-KING cockpit geometry after every resize."""
    try:
        main=getattr(self,'v274_cockpit_main',None)
        side=getattr(self,'v274_right_rail',None)
        chart=getattr(self,'v274_chart_card',None)
        if main is None or side is None or chart is None:
            return False
        main.grid_columnconfigure(0,weight=1,minsize=0)
        main.grid_columnconfigure(1,weight=0,minsize=220)
        side.configure(width=220)
        side.grid_propagate(False)
        side.grid_configure(sticky='ns',padx=(4,0))
        chart.grid_configure(sticky='nsew',padx=(0,4))
        self._last_chart_render_key=None
        return True
    except Exception:
        return False


def _v274_perf_tick(self):
    """Display measured live-paint FPS and UI callback Hz in the visible cockpit."""
    try:
        now=time.perf_counter()
        last=float(getattr(self,'_v274_perf_last_t',0.0) or 0.0)
        paints=int(getattr(self,'_v271_frames_painted',0) or 0)
        ui=int(getattr(self,'_v274_ui_tick_count',0) or 0)
        if last<=0:
            self._v274_perf_last_t=now
            self._v274_perf_last_paints=paints
            self._v274_perf_last_ui=ui
        else:
            dt=max(0.001,now-last)
            pfps=(paints-int(getattr(self,'_v274_perf_last_paints',paints) or paints))/dt
            uihz=(ui-int(getattr(self,'_v274_perf_last_ui',ui) or ui))/dt
            # Small EMA makes the badge readable instead of jittery.
            p0=float(getattr(self,'_v274_measured_fps',pfps) or pfps)
            u0=float(getattr(self,'_v274_measured_ui_hz',uihz) or uihz)
            self._v274_measured_fps=p0*.65+pfps*.35
            self._v274_measured_ui_hz=u0*.65+uihz*.35
            self._v274_perf_last_t=now
            self._v274_perf_last_paints=paints
            self._v274_perf_last_ui=ui
            target=float(getattr(self,'_v271_target_hz',60.0) or 60.0)
            struct=float(getattr(self,'_v273_structure_hz_effective',30.0) or 30.0)
            draw=float(getattr(self,'_v271_full_draw_ema_ms',0.0) or 0.0)
            text=(f'LIVE {self._v274_measured_fps:.0f}/{target:.0f} FPS  •  '
                  f'UI {self._v274_measured_ui_hz:.0f}/30 Hz  •  STRUCT {struct:.0f} Hz  •  {draw:.1f}ms')
            try:
                self.v274_perf_var.set(text)
                self.v274_perf_badge.lift()
            except Exception:
                pass
    except Exception:
        pass
    try:
        self.root.after(500,lambda s=self:_v274_perf_tick(s))
    except Exception:
        pass


def _v274_resize_enforcer(self,event=None):
    try:
        if event is not None and getattr(event,'widget',None) is not self.root:
            return
        pending=getattr(self,'_v274_resize_after',None)
        if pending:
            try:self.root.after_cancel(pending)
            except Exception:pass
        self._v274_resize_after=self.root.after(35,lambda s=self:_v274_force_real_cockpit_layout(s))
    except Exception:
        pass


def _v274_init(self,*args,**kwargs):
    _V274_BASE_INIT(self,*args,**kwargs)
    try:
        # Real fast path: use monitor rate where sensible, never under 60Hz.
        self._v271_target_hz=_v274_detect_target_hz()
        self._v271_effective_hz=self._v271_target_hz
        self.live_draw_interval=1.0/self._v271_target_hz
        # High-frequency UI remains separated from expensive analytics.
        self.bookmap_panel_interval=min(float(getattr(self,'bookmap_panel_interval',.14) or .14),1.0/30.0)
        self.bookmap_heatmap_interval=min(float(getattr(self,'bookmap_heatmap_interval',.12) or .12),1.0/30.0)
        self.bookmap_heatmap_draw_interval=min(float(getattr(self,'bookmap_heatmap_draw_interval',.12) or .12),1.0/30.0)
        self._v274_ui_tick_count=0
        self._v274_perf_last_t=0.0
        self.root.title(f'BOOKMAP KING V21.74 — MAIN FORECAST LOCK • HARD {self._v271_target_hz:.0f}HZ • COMPACT 220PX RAIL')
        self.root.bind('<Configure>',lambda e,s=self:_v274_resize_enforcer(s,e),add='+')
        self.root.after(150,lambda s=self:_v274_force_real_cockpit_layout(s))
        self.root.after(700,lambda s=self:_v274_perf_tick(s))
    except Exception:
        pass


ChartKingPro.__init__=_v274_init

# END V21.74 HARD 60HZ / COMPACT COCKPIT RUNTIME


# ============================================================================
# BOOKMAP KING V21.75 — FIXED 60 FPS CHART CLOCK
#
# Visual/runtime only. V21.72 projected-settlement forecast/lock authority is
# unchanged. This replaces the adaptive 60-144Hz live scheduler with a fixed
# 60.000 FPS deadline clock so the visible chart does not wander between rates.
# - Absolute 16.667 ms deadlines with drift correction.
# - Late frames are skipped, never burst-rendered, so latency stays bounded.
# - 1 ms Windows timer resolution in the UI process where available.
# - Live candle + live price overlay paint every visual frame.
# - Heavy cockpit/analytics remain decoupled at ~30 Hz to protect the 60 FPS
#   chart budget.
# ============================================================================

_V275_RELEASE = 'V21.75'
_V275_FIXED_HZ = 60.0
_V275_PERIOD = 1.0 / _V275_FIXED_HZ
_V275_BASE_INIT = ChartKingPro.__init__


def _v274_detect_target_hz():
    """V21.75 hard override: chart target is always exactly 60 FPS."""
    return _V275_FIXED_HZ


def _v275_enable_timer_resolution(self):
    if getattr(self, '_v275_timer_resolution_enabled', False):
        return
    self._v275_timer_resolution_enabled = True
    try:
        if sys.platform.startswith('win'):
            import ctypes
            rc = int(ctypes.windll.winmm.timeBeginPeriod(1))
            self._v275_time_begin_period_rc = rc
            if rc == 0:
                try:
                    import atexit
                    atexit.register(lambda: ctypes.windll.winmm.timeEndPeriod(1))
                except Exception:
                    pass
    except Exception:
        pass


def _v275_animation_tick(self):
    """Fixed 60 FPS Tk scheduler using absolute deadlines, not adaptive Hz."""
    now = time.perf_counter()
    deadline = float(getattr(self, '_v275_frame_deadline', 0.0) or 0.0)
    if deadline <= 0.0:
        deadline = now

    # If Tk woke us slightly early, do not paint early; schedule the remainder.
    if now + 0.00035 < deadline:
        remaining = max(0.0005, deadline - now)
        delay_ms = max(1, int(remaining * 1000.0))
        try:
            self.root.after(delay_ms, lambda s=self: _v275_animation_tick(s))
        except Exception:
            pass
        return

    frame_start = now
    lag_ms = max(0.0, (now - deadline) * 1000.0)
    lag0 = float(getattr(self, '_v271_lag_ema_ms', 0.0) or 0.0)
    self._v271_lag_ema_ms = lag_ms if lag0 <= 0 else lag0 * 0.92 + lag_ms * 0.08

    try:
        _v271_fast_live_candle(self)
    except Exception:
        pass

    elapsed_ms = (time.perf_counter() - frame_start) * 1000.0
    e0 = float(getattr(self, '_v271_anim_ema_ms', 0.0) or 0.0)
    self._v271_anim_ema_ms = elapsed_ms if e0 <= 0 else e0 * 0.92 + elapsed_ms * 0.08
    self._v271_target_hz = _V275_FIXED_HZ
    self._v271_effective_hz = _V275_FIXED_HZ

    # Advance from the old deadline, not from 'now', so timer jitter cannot
    # permanently drift the chart below 60 FPS. If we are more than one frame
    # late, skip missed visual deadlines instead of drawing a burst of stale
    # frames and blocking Bookmap/Tk.
    next_deadline = deadline + _V275_PERIOD
    now2 = time.perf_counter()
    if next_deadline <= now2:
        missed = int((now2 - next_deadline) / _V275_PERIOD) + 1
        next_deadline += missed * _V275_PERIOD
        self._v275_skipped_frames = int(getattr(self, '_v275_skipped_frames', 0) or 0) + missed
    self._v275_frame_deadline = next_deadline

    remaining = max(0.0005, next_deadline - time.perf_counter())
    # Floor intentionally wakes Tk a hair early; the early-wake branch above
    # waits out the remainder. This is steadier than accumulating rounded 17ms.
    delay_ms = max(1, int(remaining * 1000.0))
    try:
        self.root.after(delay_ms, lambda s=self: _v275_animation_tick(s))
    except Exception:
        pass


def _v275_perf_tick(self):
    """V21.75 badge: make the fixed 60 FPS contract obvious on the real chart."""
    try:
        now = time.perf_counter()
        last = float(getattr(self, '_v274_perf_last_t', 0.0) or 0.0)
        paints = int(getattr(self, '_v271_frames_painted', 0) or 0)
        ui = int(getattr(self, '_v274_ui_tick_count', 0) or 0)
        if last <= 0:
            self._v274_perf_last_t = now
            self._v274_perf_last_paints = paints
            self._v274_perf_last_ui = ui
        else:
            dt = max(0.001, now - last)
            pfps = (paints - int(getattr(self, '_v274_perf_last_paints', paints) or paints)) / dt
            uihz = (ui - int(getattr(self, '_v274_perf_last_ui', ui) or ui)) / dt
            p0 = float(getattr(self, '_v274_measured_fps', pfps) or pfps)
            u0 = float(getattr(self, '_v274_measured_ui_hz', uihz) or uihz)
            self._v274_measured_fps = p0 * .55 + pfps * .45
            self._v274_measured_ui_hz = u0 * .65 + uihz * .35
            self._v274_perf_last_t = now
            self._v274_perf_last_paints = paints
            self._v274_perf_last_ui = ui
            struct = float(getattr(self, '_v273_structure_hz_effective', 30.0) or 30.0)
            draw = float(getattr(self, '_v271_full_draw_ema_ms', 0.0) or 0.0)
            lag = float(getattr(self, '_v271_lag_ema_ms', 0.0) or 0.0)
            skipped = int(getattr(self, '_v275_skipped_frames', 0) or 0)
            text = (f'CHART {self._v274_measured_fps:.0f}/60 FPS FIXED  •  '
                    f'UI {self._v274_measured_ui_hz:.0f}/30 Hz  •  '
                    f'STRUCT {struct:.0f} Hz  •  lag {lag:.1f}ms  •  skip {skipped}')
            try:
                self.v274_perf_var.set(text)
                self.v274_perf_badge.lift()
            except Exception:
                pass
    except Exception:
        pass
    try:
        self.root.after(500, lambda s=self: _v275_perf_tick(s))
    except Exception:
        pass



def _v275_resync_after_startup(self):
    """Discard one-time startup stalls and start a clean 60 FPS deadline epoch."""
    try:
        self._v275_frame_deadline = time.perf_counter() + _V275_PERIOD
        self._v275_skipped_frames = 0
        self._v271_lag_ema_ms = 0.0
        self._v271_anim_ema_ms = 0.0
        self._v274_perf_last_t = 0.0
    except Exception:
        pass


def _v275_init(self, *args, **kwargs):
    _V275_BASE_INIT(self, *args, **kwargs)
    try:
        _v275_enable_timer_resolution(self)
        self._v271_target_hz = _V275_FIXED_HZ
        self._v271_effective_hz = _V275_FIXED_HZ
        self.live_draw_interval = _V275_PERIOD
        self._v275_frame_deadline = time.perf_counter() + _V275_PERIOD
        self._v275_skipped_frames = 0
        # Keep heavy work out of the 16.667 ms chart frame budget.
        self.bookmap_panel_interval = max(1.0 / 30.0, float(getattr(self, 'bookmap_panel_interval', 1.0 / 30.0) or 1.0 / 30.0))
        self.bookmap_heatmap_interval = max(1.0 / 30.0, float(getattr(self, 'bookmap_heatmap_interval', 1.0 / 30.0) or 1.0 / 30.0))
        self.bookmap_heatmap_draw_interval = max(1.0 / 30.0, float(getattr(self, 'bookmap_heatmap_draw_interval', 1.0 / 30.0) or 1.0 / 30.0))
        self.root.title('BOOKMAP KING V21.76 — MAIN FORECAST LOCK • BUTTER 60FPS • FAST RESET/TARGET')
        # V21.74's already-scheduled badge callback is rebound globally below,
        # so there is exactly one performance-badge loop.
        self.root.after(2400, lambda s=self: _v275_resync_after_startup(s))
    except Exception:
        pass


