# ============================================================================
# BOOKMAP KING V21.76 — BUTTER-SMOOTH UI + HARD ROUND RESET + TARGET PREFETCH
#
# Runtime / UI / round-boundary only. V21.72 projected-settlement lock authority
# remains unchanged.
#
# Goals:
# - Preserve the fixed 60 FPS live chart lane from V21.75.
# - Stop static/heavy geometry and sidebar canvases from stealing that frame budget.
# - Reuse meter/journey canvas objects rather than delete/recreate at 30 Hz.
# - Keep cockpit text at ~30 Hz but avoid redundant widget configuration.
# - Reset every 15-minute round immediately on bucket rollover.
# - Prefetch the NEXT Kalshi target before rollover when Kalshi publishes it;
#   atomically promote it at the boundary, otherwise start a fast parallel race.
# ============================================================================

_V276_RELEASE = 'V21.76'
_V276_BASE_INIT = ChartKingPro.__init__
_V276_BASE_RESET_CONTROL = ChartKingPro._v237_reset_round_control
_V276_BASE_RESET_MARKET = ChartKingPro.reset_market_state
_V276_BASE_DRAW = ChartKingPro.draw_chart
_V276_BASE_TARGET_WORKER = _v26710_btc_target_worker


def _v276_canvas_alive(c, item):
    try:
        return bool(item and c.type(item))
    except Exception:
        return False


def _v276_draw_meter(canvas, value, good_left=False, blocks=False):
    """Allocation-free meter paint after first frame."""
    try:
        w=max(40,int(canvas.winfo_width())); h=max(14,int(canvas.winfo_height()))
        v=max(0.0,min(100.0,float(value)))
        mode='blocks' if blocks else 'bar'
        state=getattr(canvas,'_v276_meter_state',None)
        if not isinstance(state,dict) or state.get('mode')!=mode or state.get('size')!=(w,h):
            canvas.delete('all')
            state={'mode':mode,'size':(w,h),'last':None}
            if blocks:
                n=8; gap=4; bw=max(4,(w-gap*(n-1))/n)
                ids=[]
                for i in range(n):
                    x1=i*(bw+gap); x2=x1+bw
                    ids.append(canvas.create_rectangle(x1,2,x2,h-2,fill='#142230',outline='#263849'))
                state['ids']=ids
            else:
                state['bg']=canvas.create_rectangle(0,3,w,h-3,fill='#111d28',outline='')
                state['fg']=canvas.create_rectangle(0,3,0,h-3,fill=_V2676_RED,outline='')
            canvas._v276_meter_state=state
        key=(round(v,2),bool(good_left))
        if state.get('last')==key:
            return
        state['last']=key
        if blocks:
            ids=state.get('ids') or []
            active=int(math.ceil(v/100.0*8-1e-9)) if v>0 else 0
            for i,item in enumerate(ids):
                fill=_V2676_RED if i<active else '#142230'
                canvas.itemconfigure(item,fill=fill)
        else:
            x=max(0,min(w,w*v/100.0))
            col=_V2676_GREEN if good_left else (_V2676_GREEN if v>=50 else _V2676_RED)
            canvas.coords(state['fg'],0,3,x,h-3)
            canvas.itemconfigure(state['fg'],fill=col)
    except Exception:
        pass


def _v276_draw_journey(app):
    """Reuse journey geometry; only recolor/reposition when stage/size changes."""
    c=getattr(app,'v2676_journey_canvas',None)
    if c is None:return
    try:
        w=max(280,int(c.winfo_width())); h=max(58,int(c.winfo_height()))
        state=dict(getattr(app,'_v2673_last_map',{}) or {})
        stage=str(state.get('stage','')).upper()
        idx=1
        if 'ABSORP' in stage: idx=2
        elif 'RECLAIM' in stage or 'REVERSION' in stage: idx=3
        elif 'EXTENSION' in stage or 'RETEST' in stage or 'RESIST' in stage: idx=4
        elif 'FINISH' in stage or 'SETTLE' in stage: idx=5
        cache=getattr(c,'_v276_journey_state',None)
        if not isinstance(cache,dict) or cache.get('size')!=(w,h):
            c.delete('all')
            margin=28; y=22; xs=[margin+i*(w-2*margin)/4 for i in range(5)]
            labels=('Adverse\ndip','Absorption\nzone','Reclaim\ntarget','Resistance\ntest','Projected\nfinish')
            line=c.create_line(xs[0],y,xs[-1],y,fill='#294053',width=3)
            nodes=[]
            for i,(x,label) in enumerate(zip(xs,labels),1):
                oval=c.create_oval(x-11,y-11,x+11,y+11,fill='#263543',outline='')
                num=c.create_text(x,y,text=str(i),fill=_V2676_MUTED,font=('Cascadia Mono',8,'bold'))
                txt=c.create_text(x,y+28,text=label,fill=_V2676_MUTED,font=('Cascadia Mono',7,'bold'),justify='center')
                nodes.append((oval,num,txt))
            cache={'size':(w,h),'line':line,'nodes':nodes,'idx':None}
            c._v276_journey_state=cache
        if cache.get('idx')==idx:
            return
        cache['idx']=idx
        for i,(oval,num,txt) in enumerate(cache['nodes'],1):
            done=i<idx; active=i==idx
            fill=_V2676_GREEN if done else _V2676_BLUE if active else '#263543'
            c.itemconfigure(oval,fill=fill)
            c.itemconfigure(num,fill=_V2676_VOID if done or active else _V2676_MUTED)
            c.itemconfigure(txt,fill=_V2676_TEXT if active else _V2676_MUTED)
    except Exception:
        pass


def _v276_update_market_cards(app, statuses=None, selected=None):
    """No widget-tree walk per frame; update cards only when their visible state changes."""
    try:
        statuses=dict(statuses or getattr(app,'_v2676_multi_status',{}) or {})
        selected=str(selected or getattr(app,'asset_symbol','BTC')).upper()
        app._v2676_multi_status=statuses
        bullish=bearish=ready=0
        for asset in _V2674_ASSETS:
            st=dict(statuses.get(asset) or {}); card=getattr(app,'v2676_market_cards',{}).get(asset)
            if not card:continue
            lock=str(st.get('lock','WAIT')).upper(); px=st.get('price'); route=st.get('route_match')
            age=time.time()-float(st.get('ts',0.0) or 0.0); offline=age>3.5
            if asset==selected:
                try:
                    lock=str((getattr(app,'opening_lock_snapshot',None) or {}).get('lock_side',lock)).upper()
                    px=getattr(app,'current_spot',px)
                    route=(getattr(app,'_v2673_last_map',{}) or {}).get('route_match',route)
                except Exception:pass
            if lock=='UP':bullish+=1;ready+=1
            elif lock=='DOWN':bearish+=1;ready+=1
            ptxt=_v2676_money(asset,px) if px is not None else '--'
            ltxt='OFFLINE' if offline else f'LOCK: {lock}'
            stxt=f'{float(route):.0f}%' if route is not None else '--'
            active=asset==selected
            key=(ptxt,ltxt,stxt,active,lock)
            if card.get('_v276_key')==key:continue
            card['_v276_key']=key
            try:
                if card['price'].get()!=ptxt:card['price'].set(ptxt)
                if card['lock'].get()!=ltxt:card['lock'].set(ltxt)
                if card['score'].get()!=stxt:card['score'].set(stxt)
            except Exception:pass
            try:card['frame'].configure(highlightbackground=_V2676_BLUE if active else _V2676_BORDER)
            except Exception:pass
            col=_V2676_GREEN if lock=='UP' else _V2676_RED if lock=='DOWN' else _V2676_MUTED
            lab=card.get('_v276_lock_label')
            if lab is None:
                try:
                    for ch in card['frame'].winfo_children():
                        for sub in ch.winfo_children():
                            try:
                                if str(sub.cget('textvariable'))==str(card['lock']):
                                    lab=sub;break
                            except Exception:pass
                        if lab is not None:break
                    card['_v276_lock_label']=lab
                except Exception:lab=None
            if lab is not None:
                try:lab.configure(fg=col)
                except Exception:pass
        if hasattr(app,'v2676_tri_status_var'):
            txt=(f'{bullish}/{max(ready,1)} BULLISH • '+('BULLISH' if bullish>bearish else 'BEARISH' if bearish>bullish else 'MIXED')) if ready else '3 INDEPENDENT MINDS • BUILDING'
            try:
                if app.v2676_tri_status_var.get()!=txt:app.v2676_tri_status_var.set(txt)
            except Exception:pass
    except Exception:
        pass


# The existing cockpit resolves these globals every 33 ms, so rebinding here
