_v2676_draw_meter = _v276_draw_meter
_v2676_draw_journey = _v276_draw_journey
_v2676_update_market_cards = _v276_update_market_cards


def _v276_structure_tick(self):
    """Static geometry is event-driven and frame-budgeted; live motion remains 60 FPS."""
    try:
        now=time.perf_counter(); wall=time.time()
        draw_ms=float(getattr(self,'_v271_full_draw_ema_ms',0.0) or 0.0)
        # Full-chart rebuilds are expensive. 15 Hz is more than enough for S/R,
        # path and labels while leaving the 16.67 ms live-frame lane clean.
        hz=15.0 if draw_ms<=8.5 else 12.0 if draw_ms<=13.0 else 10.0 if draw_ms<=20.0 else 7.5
        self._v273_structure_hz_effective=hz
        seq=int(getattr(self,'_v271_visual_seq',0) or 0)
        last_seq=int(getattr(self,'_v276_structure_seq',-1) or -1)
        last=float(getattr(self,'_v276_last_structure_draw',0.0) or 0.0)
        due=now-last>=1.0/max(1.0,hz)
        force=(getattr(self,'_last_chart_render_key',None) is None)
        heartbeat=now-last>=0.35
        changed=seq!=last_seq
        visible=bool(self._chart_is_visible()) if hasattr(self,'_chart_is_visible') else True
        if (not bool(getattr(self,'web_only_mode',False)) and visible and
            wall>=float(getattr(self,'_scroll_active_until',0.0) or 0.0) and due and (changed or force or heartbeat)):
            self._v276_last_structure_draw=now; self._v276_structure_seq=seq
            self._last_live_draw=wall
            try:self.draw_chart()
            except Exception:pass
    except Exception:
        pass
    finally:
        try:self.root.after(16,lambda s=self:_v276_structure_tick(s))
        except Exception:pass


# Existing scheduled structure callback resolves this global by name.
_v273_structure_tick = _v276_structure_tick


def _v276_market_for_bucket(self, bucket):
    """One direct Kalshi list call; choose the market that settles this exact 15m bucket."""
    data=self.kalshi_get('/markets',{'series_ticker':'KXBTC15M','status':'open','limit':100})
    markets=list((data or {}).get('markets') or [])
    if not markets:return None
    expected=float(bucket)+900.0
    ranked=[]
    for m in markets:
        close_ts=self._parse_iso_ts(m.get('close_time') or m.get('expected_expiration_time') or m.get('expiration_time'))
        if close_ts is None:continue
        ranked.append((abs(float(close_ts)-expected),float(close_ts),m))
    if not ranked:return None
    ranked.sort(key=lambda x:(x[0],x[1]))
    if ranked[0][0]>210.0:return None
    m=dict(ranked[0][2])
    if self._extract_target(m) is None:
        ticker=str(m.get('ticker') or '').strip().upper()
        if ticker:
            try:
                full=self._get_kalshi_market(ticker)
                if full:m.update(full)
            except Exception:pass
    return m


def _v276_accept_target(self, bucket, market, source='V21.76 FAST TARGET'):
    try:
        if int(time.time()//900)*900!=int(bucket):return False
        target=self._extract_target(market) if market else None
        if target is None or float(target)<=1000:return False
        target=float(target)
        lock=getattr(self,'_v276_target_commit_lock',None)
        if lock is None:
            lock=threading.Lock();self._v276_target_commit_lock=lock
        with lock:
            if int(getattr(self,'_v26710_target_lock_bucket',-1) or -1)==int(bucket) and getattr(self,'_v26710_target_lock',None) is not None:
                return True
            self.target_price=target
            self._v26710_target_lock_bucket=int(bucket);self._v26710_target_lock=target
            self._v26710_seen_bucket=int(bucket);self._v217_target_bucket=int(bucket);self._v217_target_captured_bucket=int(bucket)
            self._v276_target_acquired_at=time.perf_counter()
            self._v276_target_acquire_ms=max(0.0,(self._v276_target_acquired_at-float(getattr(self,'_v276_round_started_perf',self._v276_target_acquired_at) or self._v276_target_acquired_at))*1000.0)
        def apply_ui():
            try:self._apply_kalshi_market(market,source)
            except Exception:pass
            try:
                ticker=str((market or {}).get('ticker') or '')
                self.auto_target_status_var.set(f'AUTO TARGET: {money(target)} • {source} • {self._v276_target_acquire_ms:.0f}ms • {ticker}')
            except Exception:pass
        try:self.root.after(0,apply_ui)
        except Exception:pass
        return True
    except Exception:
        return False


def _v276_target_prefetch_worker(self, next_bucket):
    try:
        market=_v276_market_for_bucket(self,next_bucket)
        target=self._extract_target(market) if market else None
        if target is not None and float(target)>1000:
            self._v276_prefetched_target={'bucket':int(next_bucket),'target':float(target),'market':dict(market),'ts':time.time()}
    except Exception as exc:
        self._v276_prefetch_error=str(exc)
    finally:
        self._v276_prefetch_running=False


def _v276_fast_target_race(self, bucket):
    """Two independent current-round probes; first valid exact-bucket target wins."""
    if getattr(self,'_v276_target_race_bucket',None)==int(bucket) and getattr(self,'_v276_target_race_running',False):return
    self._v276_target_race_bucket=int(bucket);self._v276_target_race_running=True
    def direct_lane():
        try:
            for attempt in range(60):
                if int(time.time()//900)*900!=int(bucket):return
                if getattr(self,'_v26710_target_lock',None) is not None:return
                try:
                    m=_v276_market_for_bucket(self,bucket)
                    if m and _v276_accept_target(self,bucket,m,'V21.76 DIRECT ROUND TARGET'):return
                except Exception:pass
                time.sleep(.08 if attempt<20 else .18)
        finally:
            pass
    def legacy_lane():
        try:
            for attempt in range(40):
                if int(time.time()//900)*900!=int(bucket):return
                if getattr(self,'_v26710_target_lock',None) is not None:return
                try:
                    m=self._discover_current_kalshi_market()
                    if m and _v26710_btc_target_matches_bucket(self,m,bucket) and _v276_accept_target(self,bucket,m,'V21.76 FAST DISCOVERY'):return
                except Exception:pass
                time.sleep(.10 if attempt<15 else .22)
        finally:
            pass
    def supervisor():
        a=threading.Thread(target=direct_lane,name='LeChartJames-V276-TargetDirect',daemon=True)
        b=threading.Thread(target=legacy_lane,name='LeChartJames-V276-TargetDiscover',daemon=True)
        a.start();b.start();a.join(15);b.join(15)
        self._v276_target_race_running=False
    threading.Thread(target=supervisor,name='LeChartJames-V276-TargetRace',daemon=True).start()


def _v276_hard_round_reset(self, bucket):
    """One atomic round reset. All inherited lock/dynamic reset chains run once."""
    self._v276_round_started_perf=time.perf_counter();self._v276_round_reset_ms=0.0
    t0=time.perf_counter()
    try:_V276_BASE_RESET_CONTROL(self)
    except Exception:
        try:_v272_reset(self)
        except Exception:pass
    # Clear caches that are intentionally outside the inherited reset chain.
    for name,value in (
        ('_v270_trend_cache',{}),('_v2673_last_map',{}),('_v271_visual_ohlc',{}),
        ('_v26716_fast_geometry',None),('_v26716_live_candle_items',None),
        ('_v276_structure_seq',-1),('_v276_last_structure_draw',0.0),
    ):
        try:setattr(self,name,value)
        except Exception:pass
    try:
        self._last_chart_render_key=None;self.chart_pan_offset=0
        self.opening_lock_snapshot=None
        self.trend_reversal_risk_value=0.0;self.flip_survival_value=100.0
    except Exception:pass
    # Target must be fresh for the new bucket; never carry old strike across.
    self._v26710_seen_bucket=int(bucket);self._v26710_target_lock_bucket=int(bucket);self._v26710_target_lock=None
    self._v217_target_bucket=int(bucket);self._v217_target_captured_bucket=None;self._v217_target_sniper_running=False
    self.target_price=None
    self._v276_round_reset_ms=(time.perf_counter()-t0)*1000.0
    try:
        self.market_reset_var.set(f'ROUND RESET: V21.76 COMPLETE • {self._v276_round_reset_ms:.1f}ms • target race armed')
        self.auto_target_status_var.set('AUTO TARGET: NEW ROUND • PREFETCH/RACE ACQUIRING...')
    except Exception:pass
    # Promote staged target immediately if Kalshi published the next contract early.
    pre=dict(getattr(self,'_v276_prefetched_target',{}) or {})
    if int(pre.get('bucket',-1) or -1)==int(bucket) and pre.get('market'):
        if _v276_accept_target(self,bucket,pre['market'],'V21.76 PREFETCHED TARGET'):
            self._v276_prefetched_target={}
    if getattr(self,'_v26710_target_lock',None) is None:
        _v276_fast_target_race(self,bucket)
    try:self.root.after_idle(self.draw_chart)
    except Exception:pass
    return True


def _v276_target_guard_tick(self):
    """50 ms round sentinel; prefetch next target before the boundary."""
    try:
        if _v26710_asset(self)!='BTC':
            # Preserve SOL/DOGE hard-target path; this release focuses BTC.
            try:_v2678_target_watchdog(self)
            except Exception:pass
            return
        now=time.time();bucket=int(now//900)*900;into=now-bucket;left=900.0-into
        seen=int(getattr(self,'_v276_round_bucket',bucket) or bucket)
        if not hasattr(self,'_v276_round_bucket'):
            self._v276_round_bucket=bucket
            # Ensure startup has a current target race if no valid lock exists.
            if not (int(getattr(self,'_v26710_target_lock_bucket',-1) or -1)==bucket and getattr(self,'_v26710_target_lock',None) is not None):
                _v276_fast_target_race(self,bucket)
        elif seen!=bucket:
            self._v276_round_bucket=bucket
            _v276_hard_round_reset(self,bucket)
        # Stage the next round during the final 12 seconds. One request at a time,
        # at most about once per second, so this is fast without hammering Kalshi.
        if left<=12.0:
            nb=bucket+900
            pre=dict(getattr(self,'_v276_prefetched_target',{}) or {})
            last=float(getattr(self,'_v276_prefetch_last_try',0.0) or 0.0)
            if int(pre.get('bucket',-1) or -1)!=nb and not getattr(self,'_v276_prefetch_running',False) and now-last>=.9:
                self._v276_prefetch_last_try=now;self._v276_prefetch_running=True
                threading.Thread(target=_v276_target_prefetch_worker,args=(self,nb),name='LeChartJames-V276-NextTargetPrefetch',daemon=True).start()
        # 20 ms sentinel in the final second / first second, otherwise 50 ms.
        delay=20 if left<=1.0 or into<=1.0 else 50
        self.root.after(delay,lambda s=self:_v276_target_guard_tick(s))
    except Exception:
        try:self.root.after(80,lambda s=self:_v276_target_guard_tick(s))
        except Exception:pass


