def _v276_perf_tick(self):
    """Visible smoothness + reset/target latency telemetry."""
    try:
        now=time.perf_counter();last=float(getattr(self,'_v274_perf_last_t',0.0) or 0.0)
        paints=int(getattr(self,'_v271_frames_painted',0) or 0);ui=int(getattr(self,'_v274_ui_tick_count',0) or 0)
        if last<=0:
            self._v274_perf_last_t=now;self._v274_perf_last_paints=paints;self._v274_perf_last_ui=ui
        else:
            dt=max(.001,now-last);pfps=(paints-int(getattr(self,'_v274_perf_last_paints',paints) or paints))/dt
            uihz=(ui-int(getattr(self,'_v274_perf_last_ui',ui) or ui))/dt
            p0=float(getattr(self,'_v274_measured_fps',pfps) or pfps);u0=float(getattr(self,'_v274_measured_ui_hz',uihz) or uihz)
            self._v274_measured_fps=p0*.55+pfps*.45;self._v274_measured_ui_hz=u0*.65+uihz*.35
            self._v274_perf_last_t=now;self._v274_perf_last_paints=paints;self._v274_perf_last_ui=ui
            self._v276_last_perf_text=(f'CHART {self._v274_measured_fps:.0f}/60 FPS • UI {self._v274_measured_ui_hz:.0f}/30 Hz • '
                f'STRUCT {float(getattr(self,"_v273_structure_hz_effective",0) or 0):.0f} Hz • '
                f'RESET {float(getattr(self,"_v276_round_reset_ms",0) or 0):.1f}ms • '
                f'TARGET {float(getattr(self,"_v276_target_acquire_ms",0) or 0):.0f}ms')
            try:self.v274_perf_var.set(self._v276_last_perf_text);self.v274_perf_badge.lift()
            except Exception:pass
    except Exception:pass
    try:self.root.after(500,lambda s=self:_v276_perf_tick(s))
    except Exception:pass


_v274_perf_tick = _v276_perf_tick


