# END V21.76 BUTTER-SMOOTH UI + HARD ROUND RESET + TARGET PREFETCH


# ============================================================================
# LECHART JAMES V21.77 — 30-60 SECOND OPENING MAPPING GATE
# Keeps V21.76 instant round reset / target capture and V21.72 forward-settlement
# authority, but deliberately prevents MAIN LOCK commitment during the noisy first
# seconds of a fresh 15-minute round.
#
# POLICY
#   • 0-30s: HARD OBSERVATION. Never arm or lock. Forecast keeps collecting.
#   • 30-60s: EARLY RELEASE only after an 8s stable projected-settlement window.
#   • >=60s: Gate is open, but the normal V21.72 quality/confidence/edge rules still
#            decide whether a lock may actually arm and earn.
#   • If target/forecast data arrives late, require a minimum ready-data sample age
#     before early release. There is never a forced directional lock at 60 seconds.
# ============================================================================

_V277_RELEASE = 'V21.77'
_V277_OBSERVE_MIN_S = 30.0
_V277_OBSERVE_MAX_S = 60.0
_V277_STABLE_WINDOW_S = 8.0
_V277_MIN_READY_AGE_S = 8.0
_V277_BASE_LOCK_READ = _v272_lock_read
_V277_BASE_INIT = ChartKingPro.__init__
_V277_BASE_HARD_ROUND_RESET = _v276_hard_round_reset


def _v277_mapping_reset(self, bucket=None):
    now=time.time()
    if bucket is None: bucket=int(now//900)*900
    self._v277_mapping={
        'bucket':int(bucket),'started_at':float(bucket),'first_ready_ts':0.0,
        'samples':deque(maxlen=1200),'released':False,'released_at':0.0,
        'release_reason':'','last':{}
    }
    return self._v277_mapping


def _v277_mapping_read(self, now=None, forecast=None):
    now=float(now or time.time()); bucket=int(now//900)*900; into=max(0.0,now-bucket)
    mp=getattr(self,'_v277_mapping',None)
    if not isinstance(mp,dict) or int(mp.get('bucket',-1) or -1)!=bucket:
        mp=_v277_mapping_reset(self,bucket)
    fc=dict(forecast or {})
    ready=bool(fc.get('ready'))
    settle=str(fc.get('settlement_side','WAIT')).upper()
    path=str(fc.get('path_side','WAIT')).upper()
    conf=float(fc.get('confidence',50.0) or 50.0)
    qual=float(fc.get('quality',0.0) or 0.0)
    edge=float(fc.get('settlement_score',0.0) or 0.0)
    target=fc.get('target')
    if ready and settle in ('UP','DOWN') and target is not None:
        if not float(mp.get('first_ready_ts',0.0) or 0.0): mp['first_ready_ts']=now
        samples=mp.get('samples')
        if not isinstance(samples,deque):
            samples=deque(maxlen=1200);mp['samples']=samples
        # De-duplicate ultra-fast repeated reads at the exact same timestamp zone.
        last=samples[-1] if samples else None
        if not last or now-float(last.get('ts',0.0) or 0.0)>=.08:
            samples.append({'ts':now,'side':settle,'path':path,'conf':conf,'quality':qual,'edge':edge})
    samples=list(mp.get('samples') or [])
    recent=[s for s in samples if now-float(s.get('ts',0.0) or 0.0)<=_V277_STABLE_WINDOW_S]
    sides=[str(s.get('side','WAIT')).upper() for s in recent if str(s.get('side','WAIT')).upper() in ('UP','DOWN')]
    majority='WAIT'; agreement=0.0
    if sides:
        ups=sum(1 for s in sides if s=='UP');dns=len(sides)-ups
        majority='UP' if ups>=dns else 'DOWN';agreement=max(ups,dns)/max(1,len(sides))
    same=[s for s in recent if str(s.get('side','WAIT')).upper()==majority]
    avg_conf=sum(float(s.get('conf',0) or 0) for s in same)/len(same) if same else 0.0
    avg_qual=sum(float(s.get('quality',0) or 0) for s in same)/len(same) if same else 0.0
    avg_edge=sum(abs(float(s.get('edge',0) or 0)) for s in same)/len(same) if same else 0.0
    ready_age=max(0.0,now-float(mp.get('first_ready_ts',now) or now)) if mp.get('first_ready_ts') else 0.0
    span=(float(recent[-1]['ts'])-float(recent[0]['ts'])) if len(recent)>=2 else 0.0
    # Require enough actual time coverage, not merely a burst of repeated callbacks.
    stable=(len(recent)>=12 and span>=6.0 and majority in ('UP','DOWN') and
            settle==majority and agreement>=.80 and avg_conf>=67.0 and
            avg_qual>=46.0 and avg_edge>=.26 and ready_age>=_V277_MIN_READY_AGE_S)
    if into < _V277_OBSERVE_MIN_S:
        gate=True; phase='HARD_MAPPING'; remaining=_V277_OBSERVE_MIN_S-into
        release_reason='hard 30s opening observation'
    elif into < _V277_OBSERVE_MAX_S and not stable:
        gate=True; phase='STABILITY_MAPPING'; remaining=_V277_OBSERVE_MAX_S-into
        release_reason='waiting for stable 8s projected-settlement evidence'
    else:
        gate=False; phase='RELEASED'; remaining=0.0
        release_reason=('stable opening forecast earned early release' if into<_V277_OBSERVE_MAX_S and stable
                        else '60s observation ceiling complete')
        if not mp.get('released'):
            mp['released']=True;mp['released_at']=now;mp['release_reason']=release_reason
    out={'gate':gate,'phase':phase,'bucket':bucket,'seconds_into_round':into,'remaining':remaining,
         'stable':stable,'majority':majority,'agreement':agreement,'avg_conf':avg_conf,
         'avg_quality':avg_qual,'avg_edge':avg_edge,'ready_age':ready_age,'sample_count':len(recent),
         'window_span':span,'release_reason':release_reason}
    mp['last']=dict(out);self._v277_mapping=mp
    return out


def _v277_lock_read(self, now=None, state=None, force=False):
    """V21.72 projected-settlement lock, gated by 30-60s opening observation."""
    now=float(now or time.time());bucket=int(now//900)*900
    # Ignore legacy dynamic-route packets exactly as V21.72 does.
    if isinstance(state,dict) and 'settlement_side' in state:
        fc=dict(state)
    else:
        fc=dict(_v272_forecast_read(self,now=now,force=force) or {})
    # Ensure the underlying V21.72 lock state is a fresh WATCH for this bucket,
    # without letting its arming timer accumulate during the observation period.
    st=getattr(self,'_v272_lock_state',None)
    if not isinstance(st,dict) or int(st.get('bucket',-1) or -1)!=bucket:
        _v272_reset(self);st=self._v272_lock_state
    gate=_v277_mapping_read(self,now=now,forecast=fc)
    if gate.get('gate'):
        st=dict(getattr(self,'_v272_lock_state',{}) or {})
        st.update({'bucket':bucket,'status':'WATCH','side':'WAIT','candidate':'WAIT',
                   'candidate_since':0.0,'candidate_samples':0,'locked_since':0.0,
                   'break_since':0.0,'strength':float(fc.get('confidence',0) or 0) if fc.get('ready') else 0.0})
        into=float(gate.get('seconds_into_round',0) or 0)
        if gate.get('phase')=='HARD_MAPPING':
            reason=(f'ROUND MAPPING {into:.0f}/{_V277_OBSERVE_MIN_S:.0f}s • hard observation • '
                    f'forecast {fc.get("settlement_side","WAIT")} {float(fc.get("confidence",50) or 50):.0f}/100 • '
                    f'PATH {fc.get("path_side","WAIT")} • collecting opening tape')
        else:
            reason=(f'ROUND MAPPING {into:.0f}/{_V277_OBSERVE_MAX_S:.0f}s • waiting for stable forecast • '
                    f'{gate.get("majority","WAIT")} agreement {float(gate.get("agreement",0))*100:.0f}% • '
                    f'conf {float(gate.get("avg_conf",0)):.0f} • quality {float(gate.get("avg_quality",0)):.0f} • '
                    f'edge {float(gate.get("avg_edge",0)):.2f}')
        st['last_reason']=reason
        try: st['history'].append({'ts':now,'status':'MAPPING','side':'WAIT','candidate':'WAIT',
                                  'forecast_side':fc.get('settlement_side','WAIT'),'edge':fc.get('settlement_score',0),
                                  'conf':fc.get('confidence',50),'path':fc.get('path_side','WAIT')})
        except Exception: pass
        self._v272_lock_state=st;self.opening_lock_snapshot=None
        out={'ready':False,'status':'MAPPING','side':'WAIT','lock_side':'WAIT','candidate':'WAIT',
             'strength':float(st.get('strength',0) or 0),'reason':reason,'candidate_samples':0,
             'candidate_age':0.0,'locked_age':0.0,'forecast':fc,'snapshot':None,'mapping':gate}
        st['last']=dict(out);self._v272_last_lock=dict(out)
        return out
    out=dict(_V277_BASE_LOCK_READ(self,now=now,state=fc,force=force) or {})
    out['mapping']=gate
    return out


def _v277_open_lock_tick(self, warm=None, now=None):
    lk=_v277_lock_read(self,now=now);fc=dict(lk.get('forecast') or {})
    status=str(lk.get('status','WATCH')).upper()
    if status=='MAPPING':
        m=dict(lk.get('mapping') or {});into=float(m.get('seconds_into_round',0) or 0)
        ceiling=_V277_OBSERVE_MIN_S if m.get('phase')=='HARD_MAPPING' else _V277_OBSERVE_MAX_S
        _v268_var_set(self,'opening_lock_var',
            f'ROUND MAPPING: {into:.0f}/{ceiling:.0f}s • FORECAST {fc.get("settlement_side","WAIT")} '
            f'{float(fc.get("confidence",50) or 50):.0f}/100 • PATH {fc.get("path_side","WAIT")} • NO LOCK YET')
        return None
    return _V277_BASE_OPEN_LOCK_TICK(self,warm=warm,now=now)


# Save the V21.72 open tick before rebinding its global lock read below.
_V277_BASE_OPEN_LOCK_TICK = _v272_open_lock_tick


def _v277_ui_tick(self):
    try:
        now=time.time();fc=_v272_forecast_read(self,now=now);lk=_v277_lock_read(self,now=now,state=fc)
        status=str(lk.get('status','WATCH')).upper()
        if status=='MAPPING':
            m=dict(lk.get('mapping') or {});into=float(m.get('seconds_into_round',0) or 0)
            cap=_V277_OBSERVE_MIN_S if m.get('phase')=='HARD_MAPPING' else _V277_OBSERVE_MAX_S
            settle=str(fc.get('settlement_side','WAIT'));path=str(fc.get('path_side','WAIT'))
            headline=(f'ROUND MAPPING {into:.0f}/{cap:.0f}s • projected {settle} '
                      f'{float(fc.get("confidence",50) or 50):.0f}/100 • PATH {path} • MAIN LOCK DISABLED')
            _v268_var_set(self,'opening_lock_var',headline+' • '+str(lk.get('reason','')))
            _v268_var_set(self,'lock_pick_var',f'MAPPING • NO LOCK • FORECAST {settle} • PATH {path}')
            _v268_var_set(self,'lock_minute_status_var','V21.77 OBSERVATION GATE • 30s hard minimum • stable early release by 60s')
            _v268_var_set(self,'lock_matrix_var',f'OPENING MAP • agreement {float(m.get("agreement",0))*100:.0f}% • samples {int(m.get("sample_count",0))} • ready age {float(m.get("ready_age",0)):.1f}s')
            _v268_var_set(self,'reversal_status_var',f'OPENING MAP • current winner {fc.get("current_winner","--")} is evidence only')
            _v268_var_set(self,'reversal_action_var','COLLECTING OPENING TAPE • lock authority intentionally paused')
            return
        # Reuse V21.72's presentation once observation is complete.
        fc2=fc;lkst=status;side=str(lk.get('side','WAIT')).upper();cand=str(lk.get('candidate','WAIT')).upper()
        conf=float(fc2.get('confidence',50) or 50);path=str(fc2.get('path_side','WAIT'));settle=str(fc2.get('settlement_side','WAIT'));curr=str(fc2.get('current_winner','--'))
        if lkst=='LOCKED': headline=f'MAIN FORECAST LOCK: {side} {float(lk.get("strength",0)):.0f}/100 • PATH {path} • projected {float(fc2.get("finish_delta",0) or 0):+.0f}$'
        elif lkst=='ARMING': headline=f'FORECAST ARMING: {cand} {float(lk.get("strength",0)):.0f}/100 • PATH {path}'
        elif lkst=='BROKEN': headline='MAIN FORECAST LOCK BROKEN • RE-PROJECTING'
        else: headline=f'FORECAST WATCH • projected {settle} {conf:.0f}/100 • PATH {path}'
        _v268_var_set(self,'opening_lock_var',headline+' • '+str(lk.get('reason','')))
        _v268_var_set(self,'lock_pick_var',f'{lkst} • {side if lkst=="LOCKED" else cand} • FORECAST {settle} {conf:.0f}/100')
        _v268_var_set(self,'lock_distance_var',f'PROJECTED CENTER {float(fc2.get("finish_delta",0) or 0):+.0f}$ vs target • PATH {path} {float(fc2.get("path_score",0)):+.2f}')
        _v268_var_set(self,'lock_minute_status_var','V21.77 MAIN LOCK = V21.72 PROJECTED SETTLEMENT after opening mapping gate')
        _v268_var_set(self,'lock_matrix_var',f'FORECAST {settle} • PATH {path} • CURRENT {curr} • quality {float(fc2.get("quality",0)):.0f}')
        _v268_var_set(self,'lock_forecast_why_var','FORECAST WHY: '+str(fc2.get('reason','')))
    except Exception: pass
    finally:
        try:self.root.after(150,lambda s=self:_v269_ui_tick(s))
        except Exception:pass


def _v277_hard_round_reset(self,bucket):
    r=_V277_BASE_HARD_ROUND_RESET(self,bucket)
    try:_v277_mapping_reset(self,bucket)
    except Exception:pass
    try:
        self.market_reset_var.set(f'ROUND RESET: V21.77 COMPLETE • target ready/racing • 30-60s observation gate started')
    except Exception:pass
    return r


def _v277_init(self,*args,**kwargs):
    _V277_BASE_INIT(self,*args,**kwargs)
    try:
        bucket=int(time.time()//900)*900;_v277_mapping_reset(self,bucket)
        self.root.title('BOOKMAP KING V21.77 — MAIN FORECAST LOCK • 30-60S OPENING MAP • BUTTER 60FPS')
        self.paper_status_var.set('PAPER AUTO: V21.77 • 30-60s opening map before MAIN LOCK')
    except Exception:pass


# FINAL V21.77 AUTHORITY / COMPATIBILITY REBINDS.
# Every existing V21.72 caller resolves the wrapper below at runtime.
_v272_lock_read = _v277_lock_read
_v269_lock_read = _v277_lock_read
_v269_ui_tick = _v277_ui_tick
_v276_hard_round_reset = _v277_hard_round_reset
ChartKingPro._bookmap_opening_lock_tick = _v277_open_lock_tick
ChartKingPro._v269_lock_read = _v277_lock_read
ChartKingPro._v270_lock_read = _v277_lock_read
ChartKingPro._v272_lock_read = _v277_lock_read
ChartKingPro.__init__ = _v277_init

# END V21.77 30-60 SECOND OPENING MAPPING GATE


# ============================================================================
# LECHART JAMES V21.78 — ATOMIC ROUND LOCK EXPIRY / ZERO-STALE AUTHORITY
#
# PURPOSE
#   The previous round's MAIN LOCK must become unusable the instant the 15-minute
#   market rolls. V21.77 correctly reset the underlying lock state, but some Tk
#   StringVars / legacy snapshot consumers could continue SHOWING the old lock
#   until their next UI callback. V21.78 makes rollover atomic at three layers:
#
#   1) STATE: prior snapshot/candidate/forecast-lock caches are invalidated first.
#   2) DISPLAY: visible lock fields immediately say NEW ROUND / NO LOCK.
#   3) AUTHORITY: a lock snapshot is tagged with its 15m bucket; a previous-bucket
#      snapshot can never be returned as current authority.
#
# The 60 FPS animation clock also watches the wall-clock bucket, so rollover is
# detected within one chart frame (~16.7 ms) rather than waiting only on the
# target watchdog. Target prefetch/race and the V21.77 30-60s mapping gate remain.
# ============================================================================

_V278_RELEASE = 'V21.78'
_V278_BASE_HARD_ROUND_RESET = _v277_hard_round_reset
_V278_BASE_ANIMATION_TICK = _v275_animation_tick
_V278_BASE_LOCK_READ = _v277_lock_read
_V278_BASE_INIT = ChartKingPro.__init__


def _v278_var_set_now(self, name, value):
    try:
        v=getattr(self,name,None)
        if v is not None and hasattr(v,'set'): v.set(value)
    except Exception:
        pass


def _v278_clear_round_authority(self, bucket, paint=True, reason='NEW 15M MARKET'):
    """Invalidate every previous-round lock surface before any new-round work."""
    bucket=int(bucket)
    self._v278_authority_bucket=bucket
    self._v278_last_clear_ts=time.time()
    self._v278_last_clear_reason=str(reason)

    # Hard authority/state invalidation. Keep this independent from target capture.
    try:self.opening_lock_snapshot=None
    except Exception:pass
    try:self.opening_lock_candidate=None;self.opening_lock_candidate_since=0.0
    except Exception:pass
    try:self.opening_lock_bucket=bucket
    except Exception:pass
    try:self._v240_earned_open_lock={}
    except Exception:pass
    try:self._v26723_lock_state={}
    except Exception:pass
    try:self._v269_lock_state={};self._v269_last_lock={}
    except Exception:pass
    try:self._v268_last_lock={};self._v268_last_exit={}
    except Exception:pass
    try:self._v272_forecast_cache={};self._v272_last_forecast={};self._v272_last_lock={}
    except Exception:pass
    try:
        _v272_reset(self)
        # _v272_reset derives the same wall-clock bucket, but force the supplied
        # bucket so tests/replay and exact boundary handling cannot disagree.
        if isinstance(getattr(self,'_v272_lock_state',None),dict):
            self._v272_lock_state['bucket']=bucket
    except Exception:
        try:
            self._v272_lock_state={'bucket':bucket,'status':'WATCH','side':'WAIT','candidate':'WAIT',
                'candidate_since':0.0,'candidate_samples':0,'locked_since':0.0,'break_since':0.0,
                'cooldown_until':0.0,'strength':0.0,'last_reason':'NEW ROUND — OLD LOCK EXPIRED',
                'history':deque(maxlen=900),'last':{}}
        except Exception:pass
    try:_v277_mapping_reset(self,bucket)
    except Exception:pass

    # Paint an unmistakable neutral state immediately. No old directional word
    # survives in the main lock/card fields after market rollover.
    if paint:
        _v278_var_set_now(self,'opening_lock_var','NEW ROUND • OLD LOCK CLEARED • MAPPING 0/30s • NO LOCK')
        _v278_var_set_now(self,'lock_pick_var','NEW ROUND • NO LOCK • PRIOR PICK EXPIRED')
        _v278_var_set_now(self,'lock_distance_var','FRESH ROUND • rebuilding projected settlement')
        _v278_var_set_now(self,'lock_minute_status_var','V21.78 ROUND GUARD • PREVIOUS MAIN LOCK INVALID')
        _v278_var_set_now(self,'lock_matrix_var','NEW ROUND • COLLECTING FRESH TAPE • NO DIRECTIONAL AUTHORITY')
        _v278_var_set_now(self,'lock_forecast_why_var','FORECAST WHY: new market — waiting for fresh round data')
        _v278_var_set_now(self,'reversal_status_var','NEW ROUND • PREVIOUS THESIS EXPIRED')
        _v278_var_set_now(self,'reversal_action_var','MAP FRESH ROUND • DO NOT USE PRIOR LOCK')
        _v278_var_set_now(self,'auto_paper_score_var','V21.78 NEW ROUND • ENTRY AUTHORITY PAUSED')
        _v278_var_set_now(self,'auto_paper_reason_var','Previous-round lock expired • 30-60s opening map starts fresh')
        try:
            if not getattr(self,'paper_active_trade',None):
                _v278_var_set_now(self,'paper_exit_status_var','NEW ROUND • NO ACTIVE LOCK AUTHORITY')
        except Exception:pass
        # Once per boundary this is safe and makes the visual clear happen before
        # longer reset/target callbacks continue.
        try:self.root.update_idletasks()
        except Exception:pass
    return True


def _v278_hard_round_reset(self, bucket):
    """Clear OLD lock first, then run V21.77/V21.76 reset + target machinery."""
    bucket=int(bucket)
    _v278_clear_round_authority(self,bucket,paint=True,reason='15M BUCKET ROLLOVER')
    try:
        r=_V278_BASE_HARD_ROUND_RESET(self,bucket)
    except Exception:
        r=False
    # Inherited reset chains may touch legacy fields; assert neutral authority once
    # more without disturbing the freshly acquired/prefetched target.
    _v278_clear_round_authority(self,bucket,paint=True,reason='POST RESET AUTHORITY ASSERT')
    try:
        tgt=getattr(self,'target_price',None)
        tgt_txt=(f' • TARGET ${float(tgt):,.2f} READY' if tgt is not None else ' • TARGET ACQUIRING')
        _v278_var_set_now(self,'opening_lock_var','NEW ROUND • OLD LOCK CLEARED • MAPPING 0/30s • NO LOCK'+tgt_txt)
        _v278_var_set_now(self,'market_reset_var','ROUND RESET: V21.78 ATOMIC • OLD LOCK EXPIRED FIRST • 30-60s mapping active')
    except Exception:pass
    return r


def _v278_lock_read(self, now=None, state=None, force=False):
    """Bucket-safe wrapper around the V21.77 projected-settlement lock."""
    now=float(now or time.time());bucket=int(now//900)*900
    auth=int(getattr(self,'_v278_authority_bucket',bucket) or bucket)
    if auth!=bucket:
        _v278_clear_round_authority(self,bucket,paint=True,reason='LOCK READ SAW NEW BUCKET')
    # Refuse any legacy snapshot that is explicitly from another bucket. Snapshots
    # from this release are always tagged below.
    snap=getattr(self,'opening_lock_snapshot',None)
    if isinstance(snap,dict):
        sb=snap.get('bucket',snap.get('market_bucket'))
        if sb is not None:
            try:
                if int(sb)!=bucket:self.opening_lock_snapshot=None
            except Exception:self.opening_lock_snapshot=None
    out=dict(_V278_BASE_LOCK_READ(self,now=now,state=state,force=force) or {})
    status=str(out.get('status','WATCH')).upper()
    if status=='LOCKED' and bool(out.get('ready')):
        snap=dict(out.get('snapshot') or getattr(self,'opening_lock_snapshot',None) or {})
        if snap:
            snap['bucket']=bucket;snap['market_bucket']=bucket;snap['release']=_V278_RELEASE
            self.opening_lock_snapshot=dict(snap);out['snapshot']=dict(snap)
    else:
        # Mapping/watch/arming/broken are never allowed to leave a stale old
        # directional snapshot hanging around for legacy UI consumers.
        self.opening_lock_snapshot=None
        out['snapshot']=None
    out['bucket']=bucket
    return out


def _v278_open_lock_tick(self, warm=None, now=None):
    """V21.77 presentation driven by the bucket-safe V21.78 lock wrapper."""
    lk=_v278_lock_read(self,now=now);fc=dict(lk.get('forecast') or {})
    status=str(lk.get('status','WATCH')).upper()
    if status=='MAPPING':
        m=dict(lk.get('mapping') or {});into=float(m.get('seconds_into_round',0) or 0)
        ceiling=_V277_OBSERVE_MIN_S if m.get('phase')=='HARD_MAPPING' else _V277_OBSERVE_MAX_S
        _v268_var_set(self,'opening_lock_var',
            f'ROUND MAPPING: {into:.0f}/{ceiling:.0f}s • FORECAST {fc.get("settlement_side","WAIT")} '
            f'{float(fc.get("confidence",50) or 50):.0f}/100 • PATH {fc.get("path_side","WAIT")} • NO LOCK YET')
        return None
    if status=='LOCKED':
        _v268_var_set(self,'opening_lock_var',
            f'MAIN FORECAST LOCK: {lk.get("side","WAIT")} {float(lk.get("strength",0) or 0):.0f}/100 • '
            f'PATH {fc.get("path_side","WAIT")} • finish {float(fc.get("finish_delta",0) or 0):+.0f}$ vs target')
        return dict(lk.get('snapshot') or {})
    if status=='ARMING':
        _v268_var_set(self,'opening_lock_var',
            f'FORECAST ARMING: {lk.get("candidate","WAIT")} {float(lk.get("strength",0) or 0):.0f}/100 • '
            f'PATH {fc.get("path_side","WAIT")} • current winner {fc.get("current_winner","--")} NOT authority')
    elif status=='BROKEN':
        _v268_var_set(self,'opening_lock_var','MAIN FORECAST LOCK BROKEN • RE-PROJECTING • '+str(lk.get('reason','')))
    else:
        _v268_var_set(self,'opening_lock_var','FORECAST WATCH • '+str(lk.get('reason','')))
    return None


def _v278_fast_bucket_guard(self):
    """60 FPS rollover sentinel: invalidate the old market within one chart frame."""
    now=time.time();bucket=int(now//900)*900
    seen=getattr(self,'_v278_fast_bucket',None)
    if seen is None:
        self._v278_fast_bucket=bucket;self._v278_authority_bucket=bucket
        return False
    if int(seen)!=bucket:
        self._v278_fast_bucket=bucket
        # Claim the bucket here so the slower target watchdog will not duplicate
        # the same hard reset on its next 20/50 ms callback.
        self._v276_round_bucket=bucket
        _v278_hard_round_reset(self,bucket)
        return True
    # Defensive stale-snapshot scrub even if some legacy callback wrote one.
    snap=getattr(self,'opening_lock_snapshot',None)
    if isinstance(snap,dict):
        sb=snap.get('bucket',snap.get('market_bucket'))
        if sb is not None:
            try:
                if int(sb)!=bucket:
                    _v278_clear_round_authority(self,bucket,paint=True,reason='STALE SNAPSHOT SCRUB')
                    return True
            except Exception:pass
    return False


def _v278_animation_tick(self):
    try:_v278_fast_bucket_guard(self)
    except Exception:pass
    return _V278_BASE_ANIMATION_TICK(self)


def _v278_init(self,*args,**kwargs):
    _V278_BASE_INIT(self,*args,**kwargs)
    try:
        bucket=int(time.time()//900)*900
        self._v278_fast_bucket=bucket;self._v278_authority_bucket=bucket
        # Never inherit a lock display from a previous addon/runtime instance.
        _v278_clear_round_authority(self,bucket,paint=True,reason='V21.78 STARTUP FRESH AUTHORITY')
        self.root.title('BOOKMAP KING V21.78 — ATOMIC LOCK CLEAR • 30-60S MAP • BUTTER 60FPS')
        self.paper_status_var.set('PAPER AUTO: V21.78 • OLD LOCK EXPIRES AT ROUND BOUNDARY • 30-60s fresh map')
    except Exception:pass


# FINAL V21.78 RUNTIME AUTHORITY REBINDS.
# Existing scheduled callbacks resolve these globals at execution time.
_v276_hard_round_reset = _v278_hard_round_reset
_v272_lock_read = _v278_lock_read
_v269_lock_read = _v278_lock_read
_v26716_animation_tick = _v278_animation_tick
_v275_animation_tick = _v278_animation_tick
ChartKingPro._bookmap_opening_lock_tick = _v278_open_lock_tick
ChartKingPro._v269_lock_read = _v278_lock_read
ChartKingPro._v270_lock_read = _v278_lock_read
ChartKingPro._v272_lock_read = _v278_lock_read
ChartKingPro.__init__ = _v278_init

# END V21.78 ATOMIC ROUND LOCK EXPIRY

# ============================================================================
# LECHART JAMES V21.79 — 60S THESIS LOCK / STICKY PLAN-CHANGE AUTHORITY
# First minute builds one opening thesis from the whole observation window.
# At/after 60s, commit a MAIN LOCK from the aggregate projected-settlement map.
# After commitment, temporary contrary flow/route reads cannot switch the lock.
# A switch requires persistent, multi-family evidence that the projected plan
# itself has changed.
# ============================================================================
_V279_RELEASE = 'V21.79 60S THESIS LOCK'
_V279_DELIBERATE_S = 60.0
_V279_SAMPLE_MIN_DT = 0.10
_V279_MIN_VALID_SPAN = 28.0
_V279_MIN_SAMPLES = 24
_V279_SWITCH_WINDOW_S = 6.0
_V279_SWITCH_PERSIST_S = 4.0
_V279_DECISIVE_PERSIST_S = 1.75
_V279_SWITCH_AGREEMENT = 0.80
_V279_BASE_CLEAR = _v278_clear_round_authority
_V279_BASE_HARD_RESET = _v278_hard_round_reset
_V279_BASE_INIT = ChartKingPro.__init__


def _v279_clip(x, lo=-1.0, hi=1.0):
    try:return max(lo,min(hi,float(x)))
    except Exception:return 0.0


def _v279_median(vals, default=0.0):
    vals=sorted(float(x) for x in (vals or []))
    if not vals:return float(default)
    n=len(vals);m=n//2
    return vals[m] if n%2 else .5*(vals[m-1]+vals[m])


def _v279_state_reset(self, bucket=None):
    now=time.time();bucket=int(bucket if bucket is not None else (now//900)*900)
    self._v279_thesis={
        'bucket':bucket,'samples':deque(maxlen=1600),'last_sample_ts':0.0,
        'status':'DELIBERATING','side':'WAIT','strength':0.0,'locked_at':0.0,
        'opening_score':0.0,'opening_consistency':0.0,'opening_vote':0.0,
        'opening_meta':{},'review':deque(maxlen=500),'review_side':'WAIT',
        'review_since':0.0,'switch_count':0,'last_switch_ts':0.0,
        'last_switch_from':'WAIT','last_switch_to':'WAIT','last_switch_reason':'',
        'last_reason':'FIRST MINUTE THESIS MAP','last':{}
    }
    return self._v279_thesis


def _v279_clear_round_authority(self, bucket, paint=True, reason='NEW 15M MARKET'):
    r=_V279_BASE_CLEAR(self,bucket,paint=paint,reason=reason)
    try:_v279_state_reset(self,bucket)
    except Exception:pass
    if paint:
        _v278_var_set_now(self,'opening_lock_var','NEW ROUND • THINKING HARD 0/60s • OLD LOCK CLEARED • NO LOCK')
        _v278_var_set_now(self,'lock_pick_var','60S THESIS MAP • NO LOCK YET')
        _v278_var_set_now(self,'lock_minute_status_var','V21.79 • FULL FIRST MINUTE BUILDS ONE MAIN THESIS')
        _v278_var_set_now(self,'reversal_action_var','COLLECTING OPENING MAP • NO SWITCHING / NO LOCK BEFORE 120s')
    return r


def _v279_collect(self, now, fc):
    bucket=int(now//900)*900
    st=getattr(self,'_v279_thesis',None)
    if not isinstance(st,dict) or int(st.get('bucket',-1) or -1)!=bucket:
        st=_v279_state_reset(self,bucket)
    if not isinstance(fc,dict) or not fc.get('ready') or fc.get('target') is None:
        return st
    last=float(st.get('last_sample_ts',0.0) or 0.0)
    if now-last < _V279_SAMPLE_MIN_DT:return st
    edge=float(fc.get('settlement_score',0.0) or 0.0)
    conf=float(fc.get('confidence',50.0) or 50.0)
    qual=float(fc.get('quality',0.0) or 0.0)
    path=float(fc.get('path_score',0.0) or 0.0)
    tr=dict(fc.get('trend') or {})
    trend=float(tr.get('score',0.0) or 0.0)
    comp=dict(fc.get('components') or {})
    struct=float((comp.get('STRUCTURE_PATH') or {}).get('score',0.0) or 0.0)
    dest=float((comp.get('DESTINATION') or {}).get('score',0.0) or 0.0)
    side=str(fc.get('settlement_side','WAIT')).upper()
    row={'ts':now,'side':side,'edge':edge,'conf':conf,'quality':qual,
         'finish_delta':float(fc.get('finish_delta',0.0) or 0.0),
         'path_side':str(fc.get('path_side','WAIT')).upper(),'path':path,
         'trend_side':str(tr.get('side','NEUTRAL')).upper(),'trend':trend,
         'trend_readability':float(tr.get('readability',0.0) or 0.0),
         'trend_agreement':float(tr.get('agreement',0.0) or 0.0),
         'struct':struct,'dest':dest,'current_winner':str(fc.get('current_winner','LINE')).upper()}
    st['samples'].append(row);st['last_sample_ts']=now;self._v279_thesis=st
    return st


def _v279_opening_map(self, now, fc):
    st=_v279_collect(self,now,fc); bucket=int(now//900)*900
    rows=[r for r in list(st.get('samples') or []) if bucket<=float(r.get('ts',0))<=bucket+_V279_DELIBERATE_S+1.0]
    if not rows:
        return {'ready':False,'side':'WAIT','score':0.0,'strength':0.0,'consistency':0.0,'vote':0.0,'samples':0,'span':0.0,'reason':'no valid opening forecast samples'}
    vals=[];weights=[];votes=[];confs=[];quals=[]
    for r in rows:
        t=max(0.0,min(_V279_DELIBERATE_S,float(r['ts'])-bucket))
        confn=_v279_clip((float(r['conf'])-50.0)/47.0,0,1)
        q=_v279_clip(float(r['quality'])/100.0,0,1)
        # Later opening data gets a little more authority, but cannot erase the
        # first 40 seconds. Settlement edge remains the side authority; path and
        # trend are used mainly to grade conviction, not to confuse direction
        # with Kalshi settlement side.
        time_w=.82+.36*(t/_V279_DELIBERATE_S)
        rel=.52+.27*q+.21*confn
        w=time_w*rel
        edge=_v279_clip(r['edge'])
        vals.append(edge);weights.append(w)
        s=1.0 if r['side']=='UP' else -1.0 if r['side']=='DOWN' else 0.0
        votes.append((s,w));confs.append(float(r['conf']));quals.append(float(r['quality']))
    den=sum(weights) or 1.0
    mean=sum(v*w for v,w in zip(vals,weights))/den
    med=_v279_median(vals,0.0)
    vote=sum(s*w for s,w in votes)/den
    # Robust time-aggregate: mean dominates, median damps one-off spikes, and
    # the persistent settlement-side vote breaks near-zero ties.
    score=_v279_clip(.70*mean+.20*med+.10*vote)
    sign=1 if score>0 else -1 if score<0 else 0
    agree=sum(w for v,w in zip(vals,weights) if sign and v*sign>=0)/den if sign else 0.0
    side='UP' if score>0 else 'DOWN' if score<0 else ('UP' if vote>=0 else 'DOWN')
    span=max(0.0,float(rows[-1]['ts'])-float(rows[0]['ts'])) if len(rows)>=2 else 0.0
    avg_conf=sum(confs)/len(confs);avg_qual=sum(quals)/len(quals)
    # If the aggregate is nearly flat, still honor the user's requested one-lock
    # workflow by choosing the persistent settlement vote once there is enough
    # valid opening data. We never fabricate a lock without target/forecast data.
    enough=(len(rows)>=_V279_MIN_SAMPLES and span>=_V279_MIN_VALID_SPAN and fc.get('target') is not None)
    if abs(score)<.035 and abs(vote)>=.08:side='UP' if vote>0 else 'DOWN'
    strength=max(52.0,min(96.0,50.0+32.0*abs(score)+10.0*agree+4.0*_v279_clip((avg_conf-50)/47,0,1)))
    reason=(f'60S THESIS • {side} score {score:+.2f} • opening agreement {agree*100:.0f}% • '
            f'vote {vote:+.2f} • avg conf {avg_conf:.0f} • quality {avg_qual:.0f} • {len(rows)} samples / {span:.1f}s')
    return {'ready':enough,'side':side,'score':score,'strength':strength,'consistency':agree,'vote':vote,
            'samples':len(rows),'span':span,'avg_conf':avg_conf,'avg_quality':avg_qual,'reason':reason}


def _v279_plan_change_sample(self, now, lock_side, fc):
    side=str(lock_side).upper();opp='DOWN' if side=='UP' else 'UP';sgn=1.0 if side=='UP' else -1.0
    edge=float(fc.get('settlement_score',0.0) or 0.0);signed=sgn*edge
    conf=float(fc.get('confidence',50.0) or 50.0);finish=sgn*float(fc.get('finish_delta',0.0) or 0.0)
    q=max(1.0,float(fc.get('quantum',1.0) or 1.0));path=sgn*float(fc.get('path_score',0.0) or 0.0)
    tr=dict(fc.get('trend') or {});trend=sgn*float(tr.get('score',0.0) or 0.0)
    comp=dict(fc.get('components') or {})
    struct=sgn*float((comp.get('STRUCTURE_PATH') or {}).get('score',0.0) or 0.0)
    dest=sgn*float((comp.get('DESTINATION') or {}).get('score',0.0) or 0.0)
    reasons=[]
    if str(fc.get('settlement_side','WAIT')).upper()==opp and conf>=72 and signed<=-.28:reasons.append('projected settlement flipped')
    if finish<=-max(7.0,q*2.2):reasons.append('projected finish crossed target deeply')
    if str(fc.get('path_side','WAIT')).upper()==opp and path<=-.20:reasons.append('forward path reversed')
    if str(tr.get('side','NEUTRAL')).upper()==opp and trend<=-.24 and float(tr.get('readability',0) or 0)>=.28:reasons.append('multi-timeframe trend reversed')
    if struct<=-.18:reasons.append('structure path reversed')
    if dest<=-.20:reasons.append('destination context reversed')
    opp_edge=max(0.0,-signed);opp_path=max(0.0,-path);opp_trend=max(0.0,-trend);opp_struct=max(0.0,-struct);opp_dest=max(0.0,-dest)
    finish_term=min(1.0,max(0.0,-finish/max(8.0,q*3.0)))
    adverse=_v279_clip(.38*opp_edge+.20*finish_term+.16*opp_path+.11*opp_trend+.08*opp_struct+.07*opp_dest,0,1)
    qualified=(len(reasons)>=4 and str(fc.get('settlement_side','WAIT')).upper()==opp and conf>=74 and signed<=-.30 and finish<=-max(4.0,q*1.2) and adverse>=.42)
    decisive=(qualified and len(reasons)>=5 and conf>=84 and signed<=-.60 and finish<=-max(10.0,q*3.0) and path<=-.26 and trend<=-.24 and adverse>=.63)
    return {'ts':now,'candidate':opp if qualified else 'WAIT','qualified':qualified,'decisive':decisive,
            'reasons':reasons,'adverse':adverse,'conf':conf,'signed_edge':signed,'signed_finish':finish,
            'signed_path':path,'signed_trend':trend}


def _v279_plan_change_read(self, now, lock_side, fc):
    st=getattr(self,'_v279_thesis',None)
    if not isinstance(st,dict):st=_v279_state_reset(self,int(now//900)*900)
    row=_v279_plan_change_sample(self,now,lock_side,fc)
    rv=st.get('review')
    if not isinstance(rv,deque):rv=deque(maxlen=500);st['review']=rv
    last=rv[-1] if rv else None
    if not last or now-float(last.get('ts',0.0) or 0.0)>=.09:rv.append(row)
    recent=[r for r in rv if now-float(r.get('ts',0.0) or 0.0)<=_V279_SWITCH_WINDOW_S]
    opp='DOWN' if str(lock_side).upper()=='UP' else 'UP'
    qualified=[r for r in recent if r.get('qualified') and r.get('candidate')==opp]
    span=(float(qualified[-1]['ts'])-float(qualified[0]['ts'])) if len(qualified)>=2 else 0.0
    agree=(len(qualified)/max(1,len(recent))) if recent else 0.0
    decisive_rows=[r for r in qualified if r.get('decisive')]
    dspan=(float(decisive_rows[-1]['ts'])-float(decisive_rows[0]['ts'])) if len(decisive_rows)>=2 else 0.0
    decisive_agree=(len(decisive_rows)/max(1,len(recent))) if recent else 0.0
    changed=(span>=_V279_SWITCH_PERSIST_S and agree>=_V279_SWITCH_AGREEMENT and len(qualified)>=12)
    changed_fast=(dspan>=_V279_DECISIVE_PERSIST_S and decisive_agree>=.78 and len(decisive_rows)>=7)
    active=bool(row.get('qualified'))
    if active and str(st.get('review_side','WAIT')).upper()!=opp:
        st['review_side']=opp;st['review_since']=now
    elif not active:
        st['review_side']='WAIT';st['review_since']=0.0
    age=max(0.0,now-float(st.get('review_since',now) or now)) if active else 0.0
    out={'changed':bool(changed or changed_fast),'decisive':bool(changed_fast),'candidate':opp if active else 'WAIT',
         'active':active,'age':age,'agreement':agree,'span':span,'reasons':list(row.get('reasons') or []),
         'adverse':float(row.get('adverse',0) or 0),'confidence':float(row.get('conf',0) or 0),
         'reason':('PLAN TRULY CHANGED' if (changed or changed_fast) else
                   f'PLAN CHANGE REVIEW {age:.1f}s • {len(row.get("reasons") or [])} independent reasons • adverse {float(row.get("adverse",0))*100:.0f}%')}
    self._v279_thesis=st
    return out


def _v279_make_snapshot(now, side, strength, fc, source, reason, bucket):
    return {'time':now,'price':fc.get('live'),'lock_side':side,'lock_remaining':'THESIS','lock_minute':int((now%900)//60),
            'forecast_score':float(fc.get('settlement_score',0) or 0)*10.0,'forecast_threshold':'60S THESIS',
            'forecast_reasons':reason,'source':source,'strength':float(strength),'revocable':True,
            'bucket':bucket,'market_bucket':bucket,'release':_V279_RELEASE,'projected_center':fc.get('projected_center'),
            'projected_low':fc.get('projected_low'),'projected_high':fc.get('projected_high'),
            'path_side':fc.get('path_side'),'current_winner':fc.get('current_winner')}


def _v279_lock_read(self, now=None, state=None, force=False):
    """Full-first-minute thesis lock. Switch only on persistent plan-change proof."""
    now=float(now or time.time());bucket=int(now//900)*900;into=max(0.0,now-bucket)
    auth=int(getattr(self,'_v278_authority_bucket',bucket) or bucket)
    if auth!=bucket:_v279_clear_round_authority(self,bucket,paint=True,reason='V21.79 LOCK READ NEW BUCKET')
    st=getattr(self,'_v279_thesis',None)
    if not isinstance(st,dict) or int(st.get('bucket',-1) or -1)!=bucket:st=_v279_state_reset(self,bucket)
    if isinstance(state,dict) and 'settlement_side' in state:fc=dict(state)
    else:fc=dict(_v272_forecast_read(self,now=now,force=force) or {})
    _v279_collect(self,now,fc)

    # Full first minute is deliberation only. There is no early-release path.
    if into < _V279_DELIBERATE_S or str(st.get('side','WAIT')).upper() not in ('UP','DOWN'):
        opening=_v279_opening_map(self,now,fc)
        if into < _V279_DELIBERATE_S:
            st['status']='DELIBERATING';st['side']='WAIT';st['strength']=float(opening.get('strength',0) or 0)
            st['last_reason']=(f'THINKING HARD {into:.0f}/120s • opening thesis {opening.get("side","WAIT")} '
                               f'{float(opening.get("strength",0)):.0f}/100 • agreement {float(opening.get("consistency",0))*100:.0f}% • '
                               f'{int(opening.get("samples",0))} samples • NO LOCK BEFORE 120s')
            self.opening_lock_snapshot=None
        elif opening.get('ready'):
            side=str(opening.get('side','WAIT')).upper()
            st.update({'status':'LOCKED','side':side,'strength':float(opening.get('strength',0) or 0),'locked_at':now,
                       'opening_score':float(opening.get('score',0) or 0),'opening_consistency':float(opening.get('consistency',0) or 0),
                       'opening_vote':float(opening.get('vote',0) or 0),'opening_meta':dict(opening),
                       'last_reason':f'OPENING THESIS COMMITTED • {opening.get("reason","")}'})
            self.opening_lock_snapshot=_v279_make_snapshot(now,side,st['strength'],fc,'V21.79 60S THESIS LOCK',st['last_reason'],bucket)
        else:
            st['status']='DELIBERATING';st['side']='WAIT';st['last_reason']=(f'120S COMPLETE • still waiting for enough valid target/forecast history • '
                                                                            f'{int(opening.get("samples",0))} samples / {float(opening.get("span",0)):.1f}s')
            self.opening_lock_snapshot=None

    # Once committed, hold the thesis. A fast opposite forecast is only a review,
    # never an automatic break. Switch directly only after PLAN CHANGED proof.
    side=str(st.get('side','WAIT')).upper()
    review={}
    if str(st.get('status','')).upper()=='LOCKED' and side in ('UP','DOWN'):
        review=_v279_plan_change_read(self,now,side,fc)
        if review.get('changed'):
            old=side;new='DOWN' if old=='UP' else 'UP'
            st['side']=new;st['strength']=max(float(fc.get('confidence',50) or 50),74.0);st['locked_at']=now
            st['switch_count']=int(st.get('switch_count',0) or 0)+1;st['last_switch_ts']=now
            st['last_switch_from']=old;st['last_switch_to']=new
            st['last_switch_reason']=(f'PLAN CHANGED {old}→{new} • {", ".join(review.get("reasons") or [])} • '
                                      f'adverse {float(review.get("adverse",0))*100:.0f}% • conf {float(review.get("confidence",0)):.0f}')
            st['last_reason']=st['last_switch_reason']
            st['review']=deque(maxlen=500);st['review_side']='WAIT';st['review_since']=0.0
            self.opening_lock_snapshot=_v279_make_snapshot(now,new,st['strength'],fc,'V21.79 PLAN CHANGED SWITCH',st['last_reason'],bucket)
            side=new;review={'changed':True,'active':False,'reason':st['last_reason'],'reasons':[],'adverse':0.0,'age':0.0}
        else:
            if review.get('active'):
                st['last_reason']=(f'MAIN LOCK {side} HELD • {review.get("reason","")} • temporary disagreement cannot switch thesis')
            else:
                st['last_reason']=(f'MAIN LOCK {side} STICKY • projected {fc.get("settlement_side","WAIT")} '
                                   f'{float(fc.get("confidence",50) or 50):.0f}/100 • PATH {fc.get("path_side","WAIT")} • '
                                   f'only PLAN CHANGED proof can switch')
            # Keep strength anchored to opening thesis with a modest live-health blend.
            st['strength']=max(50.0,min(97.0,.72*float(st.get('strength',0) or 0)+.28*float(fc.get('confidence',50) or 50)))
            snap=getattr(self,'opening_lock_snapshot',None)
            if not isinstance(snap,dict) or str(snap.get('lock_side','')).upper()!=side or int(snap.get('bucket',-1) or -1)!=bucket:
                self.opening_lock_snapshot=_v279_make_snapshot(float(st.get('locked_at',now) or now),side,st['strength'],fc,'V21.79 60S THESIS LOCK',st['last_reason'],bucket)
            else:
                snap=dict(snap);snap['strength']=st['strength'];snap['forecast_reasons']=st['last_reason'];self.opening_lock_snapshot=snap

    status=str(st.get('status','DELIBERATING')).upper();side=str(st.get('side','WAIT')).upper()
    ready=status=='LOCKED' and side in ('UP','DOWN')
    out={'ready':ready,'status':status,'side':side if ready else 'WAIT','lock_side':side if ready else 'WAIT',
         'candidate':side if ready else str((_v279_opening_map(self,now,fc) or {}).get('side','WAIT')),
         'strength':float(st.get('strength',0) or 0),'reason':st.get('last_reason',''),'forecast':fc,
         'snapshot':dict(self.opening_lock_snapshot) if ready and self.opening_lock_snapshot else None,
         'bucket':bucket,'seconds_into_round':into,'opening':dict(st.get('opening_meta') or {}),'plan_change':review,
         'switch_count':int(st.get('switch_count',0) or 0),'last_switch_from':st.get('last_switch_from','WAIT'),
         'last_switch_to':st.get('last_switch_to','WAIT')}
    st['last']=dict(out);self._v279_thesis=st;self._v272_last_lock=dict(out)
    return out


def _v279_open_lock_tick(self, warm=None, now=None):
    lk=_v279_lock_read(self,now=now);fc=dict(lk.get('forecast') or {});status=str(lk.get('status','')).upper()
    if status=='DELIBERATING':
        into=float(lk.get('seconds_into_round',0) or 0);cand=str(lk.get('candidate','WAIT')).upper()
        _v268_var_set(self,'opening_lock_var',f'THINKING HARD: {into:.0f}/60s • OPENING THESIS {cand} • NO LOCK YET • '+str(lk.get('reason','')))
        return None
    if status=='LOCKED':
        side=str(lk.get('side','WAIT')).upper();pc=dict(lk.get('plan_change') or {})
        if pc.get('active'):
            text=(f'MAIN LOCK: {side} {float(lk.get("strength",0)):.0f}/100 • HOLDING • PLAN CHANGE REVIEW '
                  f'{float(pc.get("age",0)):.1f}/{_V279_SWITCH_PERSIST_S:.0f}s • {len(pc.get("reasons") or [])} reasons')
        else:
            recent=(time.time()-float(getattr(self,'_v279_thesis',{}).get('last_switch_ts',0) or 0))<5.0
            if recent and int(lk.get('switch_count',0) or 0)>0:
                text=f'MAIN LOCK SWITCHED: {lk.get("last_switch_from","WAIT")} → {side} • PLAN TRULY CHANGED'
            else:
                text=(f'MAIN LOCK: {side} {float(lk.get("strength",0)):.0f}/100 • STICKY THESIS • '
                      f'PATH {fc.get("path_side","WAIT")} • switch only on PLAN CHANGED proof')
