            _v268_var_set(self,'lock_distance_var',f'PROJECTED FINISH {float(fc.get("finish_delta",0) or 0):+.0f}$ vs target • PATH {fc.get("path_side","WAIT")} {float(fc.get("path_score",0) or 0):+.2f}')
            _v268_var_set(self,'lock_minute_status_var','V21.79 STICKY THESIS • switch requires persistent multi-family PLAN CHANGED proof')
            _v268_var_set(self,'lock_matrix_var',f'LOCK {side} • live forecast {fc.get("settlement_side","WAIT")} • current winner {fc.get("current_winner","--")} is NOT authority')
            _v268_var_set(self,'reversal_status_var',str(lk.get('reason','')))
