def _v280_detect_asset(alias='', full_name=''):
    """BTC only. Non-BTC Bookmap instruments are intentionally ignored."""
    text=(str(alias or '')+' '+str(full_name or '')).upper()
    if any(tok in text for tok in ('BTC','XBT','BITCOIN')):
        return 'BTC'
    return None


