def _v280_history_for_interval(self, seconds):
    seconds=int(seconds)
    if seconds==600:
        base=list(getattr(self,'btc_1m',[]) or [])
        if not base:
            base=list(getattr(self,'btc_5m',[]) or [])
        try:return self._resample_history(base,600)
        except Exception:return []
    return _V280_BASE_HISTORY_FOR_INTERVAL(self,seconds)


ChartKingPro._history_for_interval = _v280_history_for_interval


def _v280_rows(self, seconds, now=None, limit=48):
    now=float(now or time.time());seconds=int(seconds)
    try:
        rows=list(self._history_for_interval(seconds) or [])
        cur=dict(self._current_bucket_for_interval(seconds) or {})
        cb=int(cur.get('time',0) or 0)
        clean=[]
        for r0 in rows:
            try:
                r=dict(r0);ts=int(float(r.get('time',0) or 0))
                if ts==cb:continue
                o=float(r['open']);h=float(r['high']);l=float(r['low']);c=float(r['close'])
                if h>=l and ts<=now+seconds:clean.append({'time':ts,'open':o,'high':h,'low':l,'close':c,'volume':float(r.get('volume',0) or 0)})
            except Exception:pass
        if cur:
            try:
                clean.append({'time':float(cur.get('time',0) or 0),'open':float(cur['open']),'high':float(cur['high']),'low':float(cur['low']),'close':float(cur['close']),'volume':float(cur.get('volume',0) or 0)})
            except Exception:pass
        clean.sort(key=lambda r:r['time'])
        return clean[-int(limit):]
    except Exception:
        return []


def _v280_wedge_read(self, rows):
    """Use the proven wedge scanner, then grade formation vs actual break."""
    rows=list(rows or [])
    if len(rows)<25:
        return {'ready':False,'name':'NONE','bias':0,'score':0.0,'signed':0.0,'confirmed':False,'trigger':None}
    # Detect shape using bars before the newest bar so the newest close can act as
    # independent breakout confirmation rather than helping draw its own wedge.
    shape_rows=rows[:-1]
    pats=[]
    try:
        pats,_stage=self.expanded_pattern_scan(shape_rows)
    except Exception:
        pats=[]
    wedges=[dict(p) for p in pats if str(p.get('name','')).upper() in ('RISING WEDGE','FALLING WEDGE')]
    # If the pre-last sample is not yet long/clean enough, allow a forming read on
    # the full window, but never label that fallback as a confirmed break.
    fallback=False
    if not wedges:
        try:
            pats,_stage=self.expanded_pattern_scan(rows)
            wedges=[dict(p) for p in pats if str(p.get('name','')).upper() in ('RISING WEDGE','FALLING WEDGE')]
            fallback=True
        except Exception:
            wedges=[]
    if not wedges:
        return {'ready':False,'name':'NONE','bias':0,'score':0.0,'signed':0.0,'confirmed':False,'trigger':None}
    p=max(wedges,key=lambda x:float(x.get('score',0) or 0))
    name=str(p.get('name','')).upper();bias=1 if name=='FALLING WEDGE' else -1
    score=max(0.0,min(100.0,float(p.get('score',0) or 0)))
    trigger=p.get('trigger');confirmed=False
    try:
        last=float(rows[-1]['close']);tr=float(trigger)
        confirmed=(not fallback) and ((bias>0 and last>tr) or (bias<0 and last<tr))
    except Exception:
        confirmed=False
    norm=max(0.0,min(1.0,(score-50.0)/50.0))
    # Formation is intentionally moderate. Confirmed break becomes meaningful,
    # but remains only one structural family among the complete decision stack.
    signed=bias*norm*(1.0 if confirmed else .55)
    return {'ready':True,'name':name,'bias':bias,'score':score,'signed':signed,'confirmed':confirmed,
            'trigger':trigger,'stage':'BREAK CONFIRMED' if confirmed else 'FORMING',
            'reason':f'{name} {"BREAK" if confirmed else "FORMING"} {score:.0f}/100'}


def _v280_exact_mtf_read(self, now=None, force=False):
    now=float(now or time.time())
    cache=dict(getattr(self,'_v280_mtf_cache',{}) or {})
    if (not force) and cache and now-float(cache.get('ts',0) or 0)<.30:
        return dict(cache)
    frames={};active=[];wedge_rows=[]
    total_weight=sum(w for _l,_s,w in _V280_TF_SPECS)
    for label,sec,w in _V280_TF_SPECS:
        rows=_v280_rows(self,sec,now=now,limit=48)
        met=_v270_tf_metric(rows,sec)
        wedge=_v280_wedge_read(self,rows)
        if met.get('ready'):
            maturity=min(1.0,max(.40,(int(met.get('n',0))-3)/8.0))
            ww=w*maturity
            base=float(met.get('score',0) or 0)
            ws=float(wedge.get('signed',0) or 0) if wedge.get('ready') else 0.0
            wedge_mix=.22 if wedge.get('confirmed') else .14 if wedge.get('ready') else 0.0
            combined=_v279_clip((1.0-wedge_mix)*base+wedge_mix*ws)
            active.append((label,ww,combined,met,wedge))
            if wedge.get('ready'):
                wedge_rows.append({'tf':label,**wedge})
        else:
            combined=0.0
        frames[label]={'ready':bool(met.get('ready')),'score':combined,'trend_score':float(met.get('score',0) or 0),
                       'readability':float(met.get('readability',0) or 0),'n':int(met.get('n',0) or 0),
                       'break_side':met.get('break_side','NONE'),'wedge':wedge}
    den=sum(w for _l,w,_c,_m,_wg in active)
    if den<=0:
        out={'ready':False,'score':0.0,'side':'MIXED','agreement':0.0,'readability':0.0,'coverage':0.0,
             'frames':frames,'wedges':wedge_rows,'confirmed_wedges':[],'ts':now,'reason':'EXACT 6-TF stack building'}
        self._v280_mtf_cache=dict(out);return out
    score=sum(w*c for _l,w,c,_m,_wg in active)/den
    readability=sum(w*float(m.get('readability',0) or 0) for _l,w,_c,m,_wg in active)/den
    sign=1 if score>0 else -1 if score<0 else 0
    directional=sum(w for _l,w,c,_m,_wg in active if abs(c)>=.08)
    agreeing=sum(w for _l,w,c,_m,_wg in active if sign and c*sign>=.08)
    agreement=agreeing/max(directional,1e-9) if sign else 0.0
    coverage=min(1.0,den/max(total_weight,1e-9))
    side='UP' if score>=.12 and agreement>=.52 else 'DOWN' if score<=-.12 and agreement>=.52 else 'MIXED'
    confirmed=[r for r in wedge_rows if r.get('confirmed')]
    wedge_text=' | '.join(f"{r['tf']} {r['name']} {'BREAK' if r.get('confirmed') else 'forming'}" for r in wedge_rows[:4]) or 'no wedge'
    out={'ready':True,'score':_v279_clip(score),'side':side,'agreement':max(0.0,min(1.0,agreement)),
         'readability':max(0.0,min(1.0,readability)),'coverage':coverage,'frames':frames,
         'wedges':wedge_rows,'confirmed_wedges':confirmed,'ts':now,
         'reason':f'6TF {side} {score:+.2f} • agree {agreement*100:.0f}% • readable {readability*100:.0f}% • {wedge_text}'}
    self._v280_mtf_cache=dict(out);return out


ChartKingPro._v280_exact_mtf_read = _v280_exact_mtf_read

# ---- Feed exact 6-TF + wedges into projected settlement ---------------------
def _v280_forecast_read(self, now=None, force=False):
    now=float(now or time.time())
    fc=dict(_V280_BASE_FORECAST_READ(self,now=now,force=force) or {})
    mtf=dict(_v280_exact_mtf_read(self,now=now,force=force) or {})
    fc['exact_mtf']=mtf
    if not fc.get('ready') or not mtf.get('ready'):
        return fc
    old=float(fc.get('path_score',0) or 0);m=float(mtf.get('score',0) or 0)
    quality=max(0.0,min(1.0,float(mtf.get('readability',0) or 0)))
    coverage=max(0.0,min(1.0,float(mtf.get('coverage',0) or 0)))
    agreement=max(0.0,min(1.0,float(mtf.get('agreement',0) or 0)))
    # Exact requested timeframes get meaningful but not dominant path authority.
    # 5m/10m/15m are already the heaviest members inside the packet.
    blend=.12+.12*coverage*(.55+.45*quality)
    blend*=.78+.22*agreement
    blend=max(.10,min(.25,blend))
    new_path=_v279_clip((1.0-blend)*old+blend*m)
    b=max(1.0,float(fc.get('budget',1.0) or 1.0))
    shift=(new_path-old)*b*(.22+.16*min(1.0,abs(new_path)))
    old_center=float(fc.get('projected_center',fc.get('live',0)) or 0)
    center=old_center+shift
    low=float(fc.get('projected_low',center) or center)+shift
    high=float(fc.get('projected_high',center) or center)+shift
    target=float(fc.get('target',0) or 0)
    finish=center-target
    uncertainty=max(5.0,(high-low)*.5)
    settle_score=math.tanh(finish/max(uncertainty*.78,5.0))
    settle_side='UP' if settle_score>=.12 else 'DOWN' if settle_score<=-.12 else 'WAIT'
    base_quality=max(0.0,min(1.0,float(fc.get('quality',0) or 0)/100.0))
    combined_quality=max(0.0,min(1.0,.78*base_quality+.22*quality*coverage))
    confidence=50.0+min(47.0,abs(settle_score)*49.0*(.66+.34*combined_quality))
    if low<=target<=high:confidence-=min(9.0,9.0*(1.0-abs(settle_score)))
    confidence=max(50.0,min(97.0,confidence))
    fc.update({'path_score':new_path,'path_side':'UP' if new_path>=.10 else 'DOWN' if new_path<=-.10 else 'WAIT',
               'projected_center':center,'projected_low':low,'projected_high':high,'finish_delta':finish,
               'settlement_score':settle_score,'settlement_side':settle_side,'confidence':confidence,
               'quality':combined_quality*100.0})
    comps=dict(fc.get('components') or {})
    comps['EXACT_6TF_WEDGE']={'score':m,'weight':blend,'side':mtf.get('side'),'agreement':agreement,'coverage':coverage}
    fc['components']=comps
    fc['reason']=(str(fc.get('reason',''))+f' • EXACT 3m/5m/10m/15m/1h/4h {mtf.get("side","MIXED")} {m:+.2f} '
                  f'({agreement*100:.0f}% agree) • '+(' / '.join(f"{w.get("tf")} {w.get("name")} {"BREAK" if w.get("confirmed") else "FORMING"}" for w in (mtf.get('wedges') or [])[:3]) or 'no wedge'))
    return fc


_v272_forecast_read = _v280_forecast_read
ChartKingPro._v272_forecast_read = _v280_forecast_read

# ---- PLAN CHANGED also consumes exact 6-TF + wedges -------------------------
def _v280_plan_change_sample(self, now, lock_side, fc):
    row=dict(_V280_BASE_PLAN_CHANGE_SAMPLE(self,now,lock_side,fc) or {})
    mtf=dict(fc.get('exact_mtf') or _v280_exact_mtf_read(self,now=now) or {})
    side=str(lock_side).upper();opp='DOWN' if side=='UP' else 'UP';sgn=1.0 if side=='UP' else -1.0
    m_signed=sgn*float(mtf.get('score',0) or 0)
    reasons=list(row.get('reasons') or [])
    if mtf.get('ready') and str(mtf.get('side','MIXED')).upper()==opp and m_signed<=-.20 and float(mtf.get('agreement',0) or 0)>=.64:
        reasons.append('exact 3m/5m/10m/15m/1h/4h stack reversed')
    opp_confirmed=[]
    for w in mtf.get('confirmed_wedges') or []:
        bias=int(w.get('bias',0) or 0)
        wside='UP' if bias>0 else 'DOWN' if bias<0 else 'WAIT'
        if wside==opp:opp_confirmed.append(w)
    if opp_confirmed:
        reasons.append('confirmed '+', '.join(f"{w.get('tf')} {w.get('name')}" for w in opp_confirmed[:2]))
    # De-duplicate while preserving audit order.
    reasons=list(dict.fromkeys(reasons))
    adverse=float(row.get('adverse',0) or 0)
    adverse=min(1.0,adverse + (max(0.0,-m_signed)*.09 if mtf.get('ready') else 0.0) + (.05 if opp_confirmed else 0.0))
    conf=float(row.get('conf',0) or 0);signed=float(row.get('signed_edge',0) or 0);finish=float(row.get('signed_finish',0) or 0)
    q=max(1.0,float(fc.get('quantum',1.0) or 1.0))
    # Preserve V21.79's high burden of proof; extra TF/wedge reasons can help breadth
    # but settlement itself still must actually flip against the lock.
    qualified=(len(reasons)>=4 and str(fc.get('settlement_side','WAIT')).upper()==opp and conf>=74 and signed<=-.30 and finish<=-max(4.0,q*1.2) and adverse>=.42)
    decisive=(qualified and len(reasons)>=5 and conf>=84 and signed<=-.60 and finish<=-max(10.0,q*3.0) and adverse>=.63)
    row.update({'reasons':reasons,'adverse':adverse,'qualified':qualified,'decisive':decisive,
                'candidate':opp if qualified else 'WAIT','exact_mtf_signed':m_signed,'opposite_confirmed_wedges':opp_confirmed})
    return row


_v279_plan_change_sample = _v280_plan_change_sample

