def _v282_aggregate_1s(self, include_current=False, now=None, limit=5400):
    """True 1s OHLCV from native Bookmap executions, with quote fallback only before trades arrive."""
    now=float(now or time.time()); current=int(now)
    try:
        with self.bookmap_lock:
            trades=[dict(t) for t in list(getattr(self,'bookmap_trades',()))]
    except Exception:
        trades=[dict(t) for t in list(getattr(self,'bookmap_trades',()))]
    rows={}
    for t in trades:
        try:
            ts=float(t.get('ts',t.get('received',0)) or 0); px=float(t.get('price')); sz=max(0.0,float(t.get('size',0) or 0))
            if ts>1e16: ts/=1e9
            elif ts>1e12: ts/=1e3
            if ts < now-float(limit)-2: continue
            b=int(ts)
            if b==current and not include_current: continue
            if b>current: continue
            r=rows.get(b)
            if r is None:
                rows[b]={'time':b,'open':px,'high':px,'low':px,'close':px,'volume':sz,
                         '_first_ts':ts,'_last_ts':ts,'_open_source':'BOOKMAP EXECUTION',
                         '_live_source':'BOOKMAP EXECUTIONS'}
            else:
                r['high']=max(float(r['high']),px); r['low']=min(float(r['low']),px)
                r['volume']=float(r.get('volume',0) or 0)+sz
                if ts<float(r.get('_first_ts',ts) or ts): r['open']=px; r['_first_ts']=ts
                if ts>=float(r.get('_last_ts',ts) or ts): r['close']=px; r['_last_ts']=ts
        except Exception:
            pass
    if rows:
        return [rows[k] for k in sorted(rows)][-int(limit):]
    # Startup fallback: use the existing live Bookmap/quote sample stream. This
    # never patches ingestion and disappears naturally once native trades exist.
    try:
        samples=sorted((float(ts),float(px)) for ts,px in list(getattr(self,'live_prices',())) if now-float(ts)<=float(limit)+2)
    except Exception:
        samples=[]
    for ts,px in samples:
        b=int(ts)
        if b==current and not include_current: continue
        if b>current: continue
        r=rows.get(b)
        if r is None: rows[b]={'time':b,'open':px,'high':px,'low':px,'close':px,'volume':0.0,'_open_source':'LIVE FALLBACK','_live_source':'LIVE FALLBACK'}
        else: r['high']=max(float(r['high']),px);r['low']=min(float(r['low']),px);r['close']=px
    return [rows[k] for k in sorted(rows)][-int(limit):]


def _v282_history_for_interval(self, seconds):
    seconds=int(seconds)
    if seconds==1:
        return _v282_aggregate_1s(self,include_current=False)
    return _V282_BASE_HISTORY(self,seconds)


def _v282_current_bucket(self, seconds):
    seconds=int(seconds)
    if seconds!=1:
        return _V282_BASE_CURRENT(self,seconds)
    now=time.time(); bucket=int(now)
    rows=_v282_aggregate_1s(self,include_current=True,now=now,limit=120)
    for r in reversed(rows):
        if int(r.get('time',-1))==bucket:return dict(r)
    try: live,src=self.effective_live_price(); live=float(live or 0.0)
    except Exception: live=0.0;src='WAIT'
    return {'time':bucket,'open':live,'high':live,'low':live,'close':live,'volume':0.0,'_open_source':'LIVE SEED','_live_source':src}


ChartKingPro._history_for_interval = _v282_history_for_interval
ChartKingPro._current_bucket_for_interval = _v282_current_bucket


def _v282_contract_trend(self, now=None, force=False):
    """Contract-relevant trend. 3m/5m/10m/15m dominate; 1h/4h are context only."""
    now=float(now or time.time())
    try: mtf=dict(_v280_exact_mtf_read(self,now=now,force=force) or {})
    except Exception: mtf={}
    frames=dict(mtf.get('frames') or {})
    specs=(('3M',.18),('5M',.28),('10M',.28),('15M',.26))
    active=[]
    for label,w in specs:
        f=dict(frames.get(label) or {})
        if f.get('ready'):
            active.append((label,w,float(f.get('score',0) or 0),float(f.get('readability',0) or 0),str(f.get('break_side','NONE')).upper()))
    den=sum(w for _l,w,_s,_r,_b in active)
    if den<=0:
        return {'ready':False,'clear':False,'side':'MIXED','score':0.0,'agreement':0.0,'readability':0.0,'frames':frames,'mtf':mtf,'reason':'contract trend building'}
    score=sum(w*s for _l,w,s,_r,_b in active)/den
    read=sum(w*r for _l,w,_s,r,_b in active)/den
    sign=1 if score>0 else -1 if score<0 else 0
    directional=sum(w for _l,w,s,_r,_b in active if abs(s)>=.10)
    agreeing=sum(w for _l,w,s,_r,_b in active if sign and s*sign>=.10)
    agreement=agreeing/max(directional,1e-9) if sign else 0.0
    side='UP' if score>=.16 and agreement>=.58 else 'DOWN' if score<=-.16 and agreement>=.58 else 'MIXED'
    clear=(side in ('UP','DOWN') and abs(score)>=.27 and agreement>=.70 and read>=.24 and len(active)>=3)
    return {'ready':True,'clear':clear,'side':side,'score':score,'agreement':agreement,'readability':read,
            'frames':frames,'mtf':mtf,'active':len(active),
            'reason':f'CONTRACT TREND {side} {score:+.2f} • {agreement*100:.0f}% agree • readable {read*100:.0f}% • {len(active)}/4 frames'}


def _v282_countertrend_reversal(fc, gov):
    """Countertrend lock permission requires actual rotation, not one bullish/bearish burst."""
    trend=str(gov.get('side','MIXED')).upper(); want=str(fc.get('settlement_side','WAIT')).upper()
    if trend not in ('UP','DOWN') or want not in ('UP','DOWN') or trend==want:
        return {'confirmed':True,'reasons':['aligned with contract trend']}
    sgn=1.0 if want=='UP' else -1.0
    reasons=[]
    path=sgn*float(fc.get('path_score',0) or 0)
    if str(fc.get('path_side','WAIT')).upper()==want and path>=.20: reasons.append('forward path rotated')
    comp=dict(fc.get('components') or {})
    struct=sgn*float((comp.get('STRUCTURE_PATH') or {}).get('score',0) or 0)
    dest=sgn*float((comp.get('DESTINATION') or {}).get('score',0) or 0)
    if struct>=.16: reasons.append('structure rotated')
    if dest>=.16: reasons.append('destination rotated')
    frames=dict(gov.get('frames') or {})
    short=[]; breaks=[]
    for label in ('3M','5M','10M'):
        f=dict(frames.get(label) or {})
        sc=sgn*float(f.get('score',0) or 0)
        if f.get('ready') and sc>=.16: short.append(label)
        if str(f.get('break_side','NONE')).upper()==want: breaks.append(label)
    if len(short)>=2: reasons.append('2+ short frames reversed')
    if breaks: reasons.append('countertrend structure break')
    wedges=[]
    for w in (gov.get('mtf') or {}).get('confirmed_wedges') or []:
        bias=int(w.get('bias',0) or 0); wside='UP' if bias>0 else 'DOWN' if bias<0 else 'WAIT'
        if wside==want: wedges.append(w)
    if wedges: reasons.append('confirmed countertrend wedge break')
    conf=float(fc.get('confidence',50) or 50)
    # Must have path rotation plus breadth. This prevents target cushion / fair value
    # from producing a countertrend MAIN LOCK while the chart is still stair-stepping.
    confirmed=(('forward path rotated' in reasons) and len(reasons)>=3 and (len(short)>=2 or bool(breaks) or bool(wedges)) and conf>=66)
    return {'confirmed':confirmed,'reasons':reasons,'short_reversed':short,'breaks':breaks,'wedges':wedges}


def _v282_forecast_read(self, now=None, force=False):
    fc=dict(_V282_BASE_FORECAST(self,now=now,force=force) or {})
    if not fc.get('ready'): return fc
    gov=_v282_contract_trend(self,now=now,force=force)
    fc['contract_trend']=gov
    raw_side=str(fc.get('settlement_side','WAIT')).upper()
    if not gov.get('clear') or raw_side not in ('UP','DOWN') or raw_side==str(gov.get('side','MIXED')).upper():
        fc['trend_guard']={'active':False,'vetoed':False,'reason':gov.get('reason','')}
        return fc
    proof=_v282_countertrend_reversal(fc,gov)
    if proof.get('confirmed'):
        fc['trend_guard']={'active':True,'vetoed':False,'reversal_confirmed':True,'proof':proof,
                           'reason':'COUNTERTREND ALLOWED • genuine reversal proof'}
        fc['reason']=str(fc.get('reason',''))+' • COUNTERTREND REVERSAL CONFIRMED: '+', '.join(proof.get('reasons') or [])
        return fc
    # HARD GOVERNOR: preserve raw diagnostics, but the decision packet presented
    # to the 60-second thesis follows the clear contract trend until reversal proof.
    fc['raw_settlement_side']=raw_side
    fc['raw_settlement_score']=float(fc.get('settlement_score',0) or 0)
    fc['raw_finish_delta']=float(fc.get('finish_delta',0) or 0)
    fc['raw_projected_center']=fc.get('projected_center')
    side=str(gov.get('side')).upper(); sign=1.0 if side=='UP' else -1.0
    strength=min(1.0,max(.0,(abs(float(gov.get('score',0) or 0))-.20)/.55))
    agree=float(gov.get('agreement',0) or 0); read=float(gov.get('readability',0) or 0)
    decision_mag=max(.16,min(.72,.16+.34*strength+.12*agree+.10*read))
    target=float(fc.get('target',0) or 0); q=max(1.0,float(fc.get('quantum',1) or 1))
    width=max(8.0,(float(fc.get('projected_high',target) or target)-float(fc.get('projected_low',target) or target))*.5)
    finish=sign*max(6.0,q*1.8,width*decision_mag*.72)
    old_center=float(fc.get('projected_center',target) or target); center=target+finish; shift=center-old_center
    fc['projected_center']=center
    fc['projected_low']=float(fc.get('projected_low',center) or center)+shift
    fc['projected_high']=float(fc.get('projected_high',center) or center)+shift
    fc['finish_delta']=finish
    fc['settlement_score']=sign*decision_mag
    fc['settlement_side']=side
    fc['confidence']=max(58.0,min(92.0,58.0+22.0*strength+8.0*agree+4.0*read))
    # If path was countertrend too, damp it toward the visible contract trend.
    ps=float(fc.get('path_score',0) or 0)
    if ps*sign<0:
        ps=sign*max(.10,min(.55,.18+.40*abs(float(gov.get('score',0) or 0))))
        fc['path_score']=ps;fc['path_side']=side
    fc['trend_guard']={'active':True,'vetoed':True,'raw_side':raw_side,'governed_side':side,'proof':proof,
                       'reason':f'CLEAR {side} CONTRACT TREND VETOED COUNTERTREND {raw_side} • reversal not proven'}
    fc['reason']=(str(fc.get('reason',''))+f' • HARD TREND GUARD: clear {side} 3m/5m/10m/15m '
                  f'({float(gov.get("score",0)):+.2f}, {float(gov.get("agreement",0))*100:.0f}% agree) '
                  f'BLOCKED {raw_side} until reversal proof')
    return fc


