# ============================================================================
# LECHART JAMES V21.84 — RESILIENT 60S THESIS / NO-DEADLOCK LOCK RECOVERY
#
# V21.79 intentionally only used samples from the literal first 60 seconds of
# the 15m bucket. If the Kalshi target/forecast became valid late, or the UI was
# restarted after that opening minute, the lock could remain DELIBERATING for
# the rest of the market because later valid samples were filtered out forever.
#
# V21.84 keeps the user's full opening-minute deliberation when data is ready on
# time, but allows a bounded catch-up observation window when valid data arrives
# late. It NEVER creates an early (<60s) lock.
# ============================================================================
_V284_RELEASE = 'V21.84 RESILIENT 60S THESIS'
_V284_MIN_VALID_SPAN_S = 30.0
_V284_MIN_VALID_SAMPLES = 24
_V284_MAX_OPENING_WINDOW_S = 60.0
_V284_BASE_OPENING_MAP = _v279_opening_map
_V284_BASE_UI_TICK = _v269_ui_tick


def _v284_opening_map(self, now, fc):
    """Build the opening thesis from the first valid evidence window, without deadlocking.

    Normal case: data is valid near bucket open, so the model still consumes the
    opening minute and cannot lock before t+60s.

    Recovery case: if target/forecast becomes valid late (or the UI restarts
    mid-round), start a catch-up evidence window at the first valid sample and
    keep collecting until there is >=30s of real evidence. The normal lock-read
    still enforces the absolute 60-second no-lock floor.
    """
    now=float(now or time.time())
    bucket=int(now//900)*900
    st=_v279_collect(self,now,fc)
    rows_all=[r for r in list(st.get('samples') or []) if bucket <= float(r.get('ts',0) or 0) < bucket+900]
    if not rows_all:
        ready_fc=bool(isinstance(fc,dict) and fc.get('ready'))
        has_target=bool(isinstance(fc,dict) and fc.get('target') is not None)
        why='target missing' if not has_target else 'forecast not ready' if not ready_fc else 'waiting for first valid sample'
        return {'ready':False,'side':'WAIT','score':0.0,'strength':0.0,'consistency':0.0,'vote':0.0,
                'samples':0,'span':0.0,'first_valid_ts':0.0,'catchup':False,
                'reason':f'NO VALID OPENING SAMPLES • {why}'}

    first_valid=float(rows_all[0].get('ts',now) or now)
    first_into=max(0.0,first_valid-bucket)
    catchup=first_into > 8.0
    window_end=first_valid+_V284_MAX_OPENING_WINDOW_S
    rows=[r for r in rows_all if first_valid <= float(r.get('ts',0) or 0) <= min(now,window_end)]
    if not rows:
        rows=[rows_all[0]]

    vals=[];weights=[];votes=[];confs=[];quals=[]
    for r in rows:
        # Weight within the VALID evidence window instead of absolute bucket time.
        t=max(0.0,min(_V284_MAX_OPENING_WINDOW_S,float(r.get('ts',first_valid))-first_valid))
        confn=_v279_clip((float(r.get('conf',50.0))-50.0)/47.0,0,1)
        q=_v279_clip(float(r.get('quality',0.0))/100.0,0,1)
        time_w=.82+.36*(t/_V284_MAX_OPENING_WINDOW_S)
        rel=.52+.27*q+.21*confn
        w=time_w*rel
        edge=_v279_clip(r.get('edge',0.0))
        vals.append(edge);weights.append(w)
        rs=str(r.get('side','WAIT')).upper()
        s=1.0 if rs=='UP' else -1.0 if rs=='DOWN' else 0.0
        votes.append((s,w));confs.append(float(r.get('conf',50.0)));quals.append(float(r.get('quality',0.0)))

    den=sum(weights) or 1.0
    mean=sum(v*w for v,w in zip(vals,weights))/den
    med=_v279_median(vals,0.0)
    vote=sum(s*w for s,w in votes)/den
    score=_v279_clip(.70*mean+.20*med+.10*vote)
    sign=1 if score>0 else -1 if score<0 else 0
    agree=sum(w for v,w in zip(vals,weights) if sign and v*sign>=0)/den if sign else 0.0
    side='UP' if score>0 else 'DOWN' if score<0 else ('UP' if vote>=0 else 'DOWN')
    span=max(0.0,float(rows[-1].get('ts',first_valid))-float(rows[0].get('ts',first_valid))) if len(rows)>=2 else 0.0
    avg_conf=sum(confs)/len(confs) if confs else 50.0
    avg_qual=sum(quals)/len(quals) if quals else 0.0
    if abs(score)<.035 and abs(vote)>=.08:
        side='UP' if vote>0 else 'DOWN'

    # Never fabricate authority: valid target/forecast are still required.
    has_target=bool(isinstance(fc,dict) and fc.get('target') is not None)
    ready_fc=bool(isinstance(fc,dict) and fc.get('ready'))
    enough=(len(rows)>=_V284_MIN_VALID_SAMPLES and span>=_V284_MIN_VALID_SPAN_S and has_target and ready_fc)
    strength=max(52.0,min(96.0,50.0+32.0*abs(score)+10.0*agree+4.0*_v279_clip((avg_conf-50)/47,0,1)))
    mode='CATCH-UP MAP' if catchup else 'OPENING MAP'
    reason=(f'{mode} • {side} score {score:+.2f} • agreement {agree*100:.0f}% • vote {vote:+.2f} • '
            f'avg conf {avg_conf:.0f} • quality {avg_qual:.0f} • valid {len(rows)} samples / {span:.1f}s '
            f'(need {_V284_MIN_VALID_SPAN_S:.0f}s)')
    return {'ready':enough,'side':side,'score':score,'strength':strength,'consistency':agree,'vote':vote,
            'samples':len(rows),'span':span,'avg_conf':avg_conf,'avg_quality':avg_qual,'reason':reason,
            'first_valid_ts':first_valid,'first_valid_into':first_into,'catchup':catchup,'window_end':window_end}


