# sticky lock / PLAN CHANGED state machine.
_V279_DELIBERATE_S = _V285_DELIBERATE_S


def _v285_wedge_score(mtf):
    vals=[]
    for w in list((mtf or {}).get('wedges') or []):
        try:
            signed=float(w.get('signed',0.0) or 0.0)
            if not signed:
                bias=int(w.get('bias',0) or 0)
                signed=(1.0 if bias>0 else -1.0 if bias<0 else 0.0)*min(1.0,float(w.get('score',0) or 0)/100.0)
            # Forming wedge = modest structure pressure; confirmed break = stronger.
            vals.append(signed*(1.0 if w.get('confirmed') else .55))
        except Exception:
            pass
    if not vals:return 0.0
    # Median/mean blend stops one noisy wedge detector from hijacking the path.
    return _v279_clip(.60*(sum(vals)/len(vals))+.40*_v279_median(vals,0.0))


def _v285_pro_path_packet(fc):
    """Return a forward 15m thesis packet. CURRENT WINNER IS NEVER AN INPUT."""
    if not isinstance(fc,dict) or not fc.get('ready') or fc.get('target') is None:
        return {'ready':False,'score':0.0,'side':'WAIT','reason':'forward path packet waiting for target/forecast'}
    try:
        finish=float(fc.get('finish_delta',0.0) or 0.0)
        low=float(fc.get('projected_low',fc.get('projected_center',0)) or 0.0)
        high=float(fc.get('projected_high',fc.get('projected_center',0)) or 0.0)
        q=max(1.0,float(fc.get('quantum',1.0) or 1.0))
        budget=max(1.0,float(fc.get('budget',1.0) or 1.0))
        uncertainty=max(5.0,abs(high-low)*.50,q*2.0,budget*.12)
        # This is the model's FUTURE finish relative to target. It is deliberately
        # not sign(live-target), and therefore cannot simply mirror current winner.
        future_finish=math.tanh(finish/max(5.0,uncertainty*.82))
    except Exception:
        future_finish=0.0;uncertainty=5.0

    path=_v279_clip(fc.get('path_score',0.0))
    comp=dict(fc.get('components') or {})
    struct=_v279_clip((comp.get('STRUCTURE_PATH') or {}).get('score',0.0))
    dest=_v279_clip((comp.get('DESTINATION') or {}).get('score',0.0))
    gov=dict(fc.get('contract_trend') or {})
    tr=dict(fc.get('trend') or {})
    contract=_v279_clip(gov.get('score',tr.get('score',0.0)))
    mtf=dict(fc.get('exact_mtf') or (gov.get('mtf') or {}))
    mtf_score=_v279_clip(mtf.get('score',0.0))
    wedge=_v285_wedge_score(mtf)

    # Professional-path hierarchy for a 15-minute binary settlement:
    # future projected finish is the largest single input, but path/trend/structure
    # collectively carry MORE authority than any one settlement snapshot.
    parts=[
        ('PROJECTED_FUTURE_FINISH',future_finish,.36,True),
        ('FORWARD_PATH',path,.20,True),
        ('CONTRACT_TREND',contract,.16,bool(gov.get('ready') or tr.get('ready'))),
        ('STRUCTURE',struct,.09,bool(comp.get('STRUCTURE_PATH'))),
        ('DESTINATION',dest,.07,bool(comp.get('DESTINATION'))),
        ('EXACT_6TF',mtf_score,.09,bool(mtf.get('ready'))),
        ('WEDGE_STRUCTURE',wedge,.03,bool((mtf.get('wedges') or []))),
    ]
    active=[(n,v,w) for n,v,w,a in parts if a and w>0]
    den=sum(w for _n,_v,w in active) or 1.0
    score=_v279_clip(sum(v*w for _n,v,w in active)/den)
    side='UP' if score>=.035 else 'DOWN' if score<=-.035 else 'WAIT'

    # A clear contract trend is a structural governor, not "current winner".
    # Countertrend thesis can still exist only when the already-built reversal
    # proof says the underlying path has actually rotated.
    guard='NONE'
    if gov.get('clear') and str(gov.get('side','MIXED')).upper() in ('UP','DOWN'):
        gside=str(gov.get('side')).upper()
        if side in ('UP','DOWN') and side!=gside:
            proof=_v282_countertrend_reversal(fc,gov)
            if not proof.get('confirmed'):
                score=abs(score)*(1.0 if gside=='UP' else -1.0)
                score=max(.08,min(.72,score)) if gside=='UP' else min(-.08,max(-.72,score))
                side=gside;guard=f'{gside} TREND GOVERNOR'
            else:
                guard='COUNTERTREND REVERSAL PROVEN'

    return {'ready':bool(active),'score':score,'side':side,'future_finish':future_finish,
            'path':path,'contract_trend':contract,'structure':struct,'destination':dest,
            'mtf':mtf_score,'wedge':wedge,'uncertainty':uncertainty,
            'guard':guard,'parts':{n:{'score':v,'weight':w} for n,v,w in active},
            'reason':(f'15M PRO PATH {side} {score:+.2f} • future finish {future_finish:+.2f} • path {path:+.2f} • '
                      f'contract trend {contract:+.2f} • structure {struct:+.2f} • destination {dest:+.2f} • '
                      f'6TF {mtf_score:+.2f} • wedge {wedge:+.2f} • current winner ZERO AUTHORITY')}


def _v285_collect(self, now, fc):
    st=_V285_BASE_COLLECT(self,now,fc)
    try:
        rows=st.get('samples')
        if not rows:return st
        row=rows[-1]
        if abs(float(row.get('ts',0) or 0)-float(now))>.25:return st
        pp=_v285_pro_path_packet(fc)
        row['pro_score']=float(pp.get('score',0) or 0)
        row['pro_side']=str(pp.get('side','WAIT')).upper()
        row['future_finish']=float(pp.get('future_finish',0) or 0)
        row['contract_trend']=float(pp.get('contract_trend',0) or 0)
        row['mtf_score']=float(pp.get('mtf',0) or 0)
        row['wedge']=float(pp.get('wedge',0) or 0)
        row['pro_reason']=str(pp.get('reason',''))
        # Audit only. This field is intentionally NEVER consumed by _v285_opening_map.
        row['current_winner_audit']=str(fc.get('current_winner','LINE')).upper()
    except Exception:
        pass
    return st


def _v285_opening_map(self, now, fc):
    """Two-minute time-aggregate of the FORWARD PATH model, not current winner."""
    now=float(now or time.time());bucket=int(now//900)*900
    st=_v285_collect(self,now,fc)
    rows_all=[r for r in list(st.get('samples') or []) if bucket<=float(r.get('ts',0) or 0)<bucket+900 and 'pro_score' in r]
    if not rows_all:
        has_target=bool(isinstance(fc,dict) and fc.get('target') is not None)
        why='target missing' if not has_target else 'forward forecast not ready'
        return {'ready':False,'side':'WAIT','score':0.0,'strength':0.0,'consistency':0.0,'vote':0.0,
                'samples':0,'span':0.0,'reason':f'120S PRO PATH • {why}'}

    first=float(rows_all[0].get('ts',now) or now);first_into=max(0.0,first-bucket)
    catchup=first_into>_V285_LATE_START_S
    if catchup:
        end=min(now,first+_V285_RECOVERY_WINDOW_S)
        rows=[r for r in rows_all if first<=float(r.get('ts',0) or 0)<=end]
        need_span=_V285_RECOVERY_MIN_VALID_SPAN_S
    else:
        end=min(now,bucket+_V285_DELIBERATE_S)
        rows=[r for r in rows_all if bucket<=float(r.get('ts',0) or 0)<=end]
        need_span=_V285_NORMAL_MIN_VALID_SPAN_S
    if not rows:rows=[rows_all[0]]

    vals=[];weights=[];votes=[];confs=[];quals=[];path_vals=[];finish_vals=[]
    for r in rows:
        rel_t=max(0.0,float(r.get('ts',first))- (first if catchup else bucket))
        window=_V285_RECOVERY_WINDOW_S if catchup else _V285_DELIBERATE_S
        t=max(0.0,min(window,rel_t))
        confn=_v279_clip((float(r.get('conf',50.0))-50.0)/47.0,0,1)
        q=_v279_clip(float(r.get('quality',0.0))/100.0,0,1)
        # Use the entire observation. Later information gets only a mild premium;
        # the final few seconds cannot erase the first ~100 seconds of path study.
        time_w=.88+.24*(t/max(window,1e-9))
        rel=.56+.25*q+.19*confn
        w=time_w*rel
        v=_v279_clip(r.get('pro_score',0.0))
        vals.append(v);weights.append(w);path_vals.append(float(r.get('path',0) or 0));finish_vals.append(float(r.get('future_finish',0) or 0))
        s=1.0 if v>.03 else -1.0 if v<-.03 else 0.0
        votes.append((s,w));confs.append(float(r.get('conf',50.0)));quals.append(float(r.get('quality',0.0)))
    den=sum(weights) or 1.0
    mean=sum(v*w for v,w in zip(vals,weights))/den
    med=_v279_median(vals,0.0)
    vote=sum(s*w for s,w in votes)/den
    # Professional path consensus: robust mean + median + persistence vote.
    score=_v279_clip(.62*mean+.25*med+.13*vote)
    sign=1 if score>0 else -1 if score<0 else 0
    agree=sum(w for v,w in zip(vals,weights) if sign and v*sign>=0)/den if sign else 0.0
    side='UP' if score>=.025 else 'DOWN' if score<=-.025 else ('UP' if vote>0 else 'DOWN' if vote<0 else 'WAIT')
    span=max(0.0,float(rows[-1].get('ts',first))-float(rows[0].get('ts',first))) if len(rows)>=2 else 0.0
    avg_conf=sum(confs)/len(confs) if confs else 50.0;avg_qual=sum(quals)/len(quals) if quals else 0.0
    path_mean=sum(path_vals)/len(path_vals) if path_vals else 0.0
    finish_mean=sum(finish_vals)/len(finish_vals) if finish_vals else 0.0
    has_target=bool(isinstance(fc,dict) and fc.get('target') is not None);ready_fc=bool(isinstance(fc,dict) and fc.get('ready'))
    enough=(len(rows)>=_V285_MIN_VALID_SAMPLES and span>=need_span and has_target and ready_fc and side in ('UP','DOWN'))
    strength=max(52.0,min(97.0,50.0+30.0*abs(score)+11.0*agree+4.0*_v279_clip((avg_conf-50)/47,0,1)+2.0*_v279_clip(avg_qual/100,0,1)))
    mode='CATCH-UP PRO PATH' if catchup else '120S PRO PATH'
    reason=(f'{mode} • {side} score {score:+.2f} • agreement {agree*100:.0f}% • vote {vote:+.2f} • '
            f'avg path {path_mean:+.2f} • avg future finish {finish_mean:+.2f} • conf {avg_conf:.0f} • quality {avg_qual:.0f} • '
            f'{len(rows)} samples / {span:.1f}s • CURRENT WINNER ZERO AUTHORITY')
    return {'ready':enough,'side':side,'score':score,'strength':strength,'consistency':agree,'vote':vote,
            'samples':len(rows),'span':span,'avg_conf':avg_conf,'avg_quality':avg_qual,'reason':reason,
            'first_valid_ts':first,'first_valid_into':first_into,'catchup':catchup,'path_mean':path_mean,
            'future_finish_mean':finish_mean,'current_winner_used':False}


def _v285_make_snapshot(now, side, strength, fc, source, reason, bucket):
    snap=_V285_BASE_SNAPSHOT(now,side,strength,fc,source,reason,bucket)
