def _v286_clip01(x):
    try:return max(0.0,min(1.0,float(x)))
    except Exception:return 0.0


def _v286_mean(xs, default=0.0):
    xs=[float(x) for x in xs if x is not None]
    return sum(xs)/len(xs) if xs else float(default)


def _v286_median(xs, default=0.0):
    try:return float(_v279_median([float(x) for x in xs],default))
    except Exception:return float(default)


def _v286_shapes(rows):
    out=[]
    for r0 in list(rows or []):
        try:
            r=dict(r0); o=float(r['open']); h=float(r['high']); l=float(r['low']); c=float(r['close'])
            rng=max(.01,h-l); body=abs(c-o)
            out.append({'time':float(r.get('time',0) or 0),'o':o,'h':h,'l':l,'c':c,'range':rng,'body':body,
                        'bull':c>o,'bear':c<o,'upper':max(0.0,h-max(o,c)),'lower':max(0.0,min(o,c)-l),
                        'close_pos':(c-l)/rng,'volume':float(r.get('volume',0) or 0)})
        except Exception:
            pass
    return out


def _v286_fast_direction(rows, want):
    s=_v286_shapes(rows)
    if len(s)<3:return {'ready':False,'agree':False,'score':0.0}
    r=s[-4:]
    first=r[0]['c']; last=r[-1]['c']; total_rng=max(.01,_v286_mean([x['range'] for x in r],1.0))
    move=(last-first)/total_rng
    want_up=str(want).upper()=='UP'
    directional=sum(1 for x in r[-3:] if x['bull']==want_up and x['body']>=x['range']*.20)
    hl = (r[-1]['l']>=r[-2]['l'] and r[-2]['l']>=r[-3]['l']) if want_up else (r[-1]['h']<=r[-2]['h'] and r[-2]['h']<=r[-3]['h'])
    aligned=(move>=.25 if want_up else move<=-.25) and directional>=2
    score=min(1.0,abs(move)/1.2)*.65 + (directional/3.0)*.25 + (.10 if hl else 0.0)
    return {'ready':True,'agree':bool(aligned),'score':_v286_clip01(score),'directional':directional,'structure':hl,'move':move}


def _v286_candidate(rows, side, native=None, fast30=None, fast15=None, existing=None):
    """Pure candle/order-flow reversal candidate. side is the REVERSAL direction."""
    side=str(side).upper(); up=side=='UP'; s=_v286_shapes(rows)
    if len(s)<8:
        return {'ready':False,'side':side,'stage':'NONE','score':0.0,'exhaustion':0.0,'confirmation':0.0,'reasons':[],'confirmations':[]}

    # Six bars of trend effort followed by the newest trigger/live bar.
    pre=s[-7:-1]; trigger=s[-1]
    early=pre[:3]; recent=pre[-3:]
    atr=max(.01,_v286_median([x['range'] for x in s[-12:]],1.0))

    # We are measuring exhaustion of the OPPOSITE side.
    def effort(x):
        return max(0.0,x['o']-x['c']) if up else max(0.0,x['c']-x['o'])
    e_early=_v286_mean([effort(x) for x in early]); e_recent=_v286_mean([effort(x) for x in recent])
    r_early=_v286_mean([x['range'] for x in early]); r_recent=_v286_mean([x['range'] for x in recent])
    impulse=e_early/max(atr,.01)
    body_ratio=e_recent/max(e_early,.01)
    range_ratio=r_recent/max(r_early,.01)

    # How much each attempt actually extended the trend extreme.
    ext=[]
    chain=s[-8:-1]
    for a,b in zip(chain[:-1],chain[1:]):
        ext.append(max(0.0,a['l']-b['l']) if up else max(0.0,b['h']-a['h']))
    ext_early=_v286_mean(ext[:3]); ext_recent=_v286_mean(ext[-3:])
    ext_ratio=ext_recent/max(ext_early,.01)

    opp_wicks=[(x['lower'] if up else x['upper'])/max(x['range'],.01) for x in recent]
    wick=_v286_mean(opp_wicks)
    cluster=(max(x['l'] for x in recent)-min(x['l'] for x in recent))/atr if up else (max(x['h'] for x in recent)-min(x['h'] for x in recent))/atr
    level_hold=cluster<=.34

    # Failed continuation in the exhaustion cluster.
    p=pre[-2]; q=pre[-1]
    failed=(q['l']<=p['l'] and q['c']>p['c']) if up else (q['h']>=p['h'] and q['c']<p['c'])

    reasons=[]; exhaust=0.0
    if impulse>=.34:
        exhaust+=10;reasons.append('prior impulse present')
    if e_early>.08*atr and body_ratio<=.68:
        exhaust+=20;reasons.append(f'candle bodies shrinking {body_ratio:.2f}x')
    if r_early>.10*atr and range_ratio<=.76:
        exhaust+=11;reasons.append(f'ranges compressing {range_ratio:.2f}x')
    if ext_early>.02*atr and ext_ratio<=.58:
        exhaust+=17;reasons.append(f'new extreme progress dying {ext_ratio:.2f}x')
    elif ext_recent<=.06*atr:
        exhaust+=10;reasons.append('trend cannot extend its extreme')
    if wick>=.27:
        exhaust+=10;reasons.append('opposing wicks building')
    if level_hold:
        exhaust+=10;reasons.append('same level repeatedly holding')
    if failed:
        exhaust+=14;reasons.append('failed continuation candle')

    native=dict(native or {}); effort_fail=False; flow_turn=False; absorb=False
    try:
        f15=dict(native.get('flow15') or {}); f5=dict(native.get('flow5') or {}); f2=dict(native.get('flow2') or {})
        imb15=float(f15.get('imbalance',0) or 0); move15=float(f15.get('move_bp',0) or 0)
        # UP reversal: sellers are still hitting, but price stops going down. Mirror for DOWN.
        effort_fail=(imb15<=-.12 and move15>=-.55) if up else (imb15>=.12 and move15<=.55)
        flow_turn=(float(f5.get('imbalance',0) or 0)>=.10 or float(f2.get('imbalance',0) or 0)>=.16) if up else (float(f5.get('imbalance',0) or 0)<=-.10 or float(f2.get('imbalance',0) or 0)<=-.16)
        absorb=(str(native.get('absorption_side','NEUTRAL')).upper()==side and float(native.get('absorption_strength',0) or 0)>=.25)
    except Exception:
        pass
    if effort_fail:
        exhaust+=8;reasons.append('aggression producing little price progress')

    # Trigger / confirmation phase.
    confirmations=[]; confirm=0.0
    med_body=max(.01,_v286_median([x['body'] for x in recent],.01))
    expansion=(trigger['bull'] if up else trigger['bear']) and trigger['body']>=max(.22*atr,1.20*med_body) and ((trigger['close_pos']>=.62) if up else (trigger['close_pos']<=.38))
    reclaim=(trigger['c']>max(x['c'] for x in recent[-2:])) if up else (trigger['c']<min(x['c'] for x in recent[-2:]))
    # Two-of-three opposite-color sequence plus improving local structure.
    last3=s[-3:]
    opp_count=sum(1 for x in last3 if (x['bull'] if up else x['bear']))
    seq_structure=(last3[-1]['l']>=last3[-2]['l']) if up else (last3[-1]['h']<=last3[-2]['h'])
    sequence=opp_count>=2 and seq_structure
    fast30r=_v286_fast_direction(fast30 or [],side); fast15r=_v286_fast_direction(fast15 or [],side)
    micro=(fast30r.get('agree') or fast15r.get('agree'))

    if expansion:
        confirm+=25;confirmations.append('opposite expansion candle')
    if reclaim:
        confirm+=21;confirmations.append('micro reclaim')
    if sequence:
        confirm+=17;confirmations.append('reversal candle sequence')
    if failed:
        confirm+=9;confirmations.append('failed continuation')
    if flow_turn:
        confirm+=12;confirmations.append('Bookmap flow turned')
    if absorb:
        confirm+=13;confirmations.append('Bookmap absorption')
    if micro:
        confirm+=10;confirmations.append('15s/30s micro confirms')
    try:
        ex=dict(existing or {})
        if str(ex.get('side','WAIT')).upper()==side and float(ex.get('confidence',0) or 0)>=74:
            confirm+=6;confirmations.append('legacy reversal sidecar agrees')
    except Exception:
        pass

    exhaust=max(0.0,min(100.0,exhaust));confirm=max(0.0,min(100.0,confirm))
    hard=sum(1 for x in (expansion,reclaim,sequence,flow_turn,absorb,micro,failed) if x)
    total=max(0.0,min(100.0,.58*exhaust+.42*confirm))
    stage='NONE'
    if exhaust>=45:stage='WATCH'
    if exhaust>=58:stage='BUILDING'
    # Confirmation deliberately requires sequence breadth. A lone hammer cannot fire it.
    if exhaust>=55 and confirm>=44 and hard>=2 and (expansion or reclaim or sequence) and (failed or flow_turn or absorb or micro or sequence):
        stage='CONFIRMED'
        total=max(total,72.0+min(24.0,(confirm-44)*.30+(exhaust-55)*.18))
    event_ts=float(trigger.get('time',0) or 0)
    return {'ready':True,'side':side,'stage':stage,'score':round(total,1),'exhaustion':round(exhaust,1),'confirmation':round(confirm,1),
            'reasons':reasons,'confirmations':confirmations,'hard_confirms':hard,'event_ts':event_ts,
            'metrics':{'body_ratio':body_ratio,'range_ratio':range_ratio,'extension_ratio':ext_ratio,'wick':wick,
                       'level_hold':level_hold,'failed':failed,'expansion':expansion,'reclaim':reclaim,'sequence':sequence,
                       'effort_fail':effort_fail,'flow_turn':flow_turn,'absorption':absorb,'fast30':fast30r,'fast15':fast15r}}


def _v286_reversal_sequence_read(self, now=None, force=False):
    now=float(now or time.time())
    cache=dict(getattr(self,'_v286_reversal_cache',{}) or {})
    if (not force) and cache and now-float(cache.get('ts',0) or 0)<.16:
        return dict(cache)
    try: one=_v280_rows(self,60,now=now,limit=24)
    except Exception: one=[]
    try: fast30=_v280_rows(self,30,now=now,limit=16)
    except Exception: fast30=[]
    try: fast15=_v280_rows(self,15,now=now,limit=20)
    except Exception: fast15=[]
    try: native=dict(_v19_native_bookmap_metrics(self,now=now) or {})
    except Exception: native={}
    existing={}  # V21.86 deliberately avoids the legacy reversal sidecar in the hot path.
    try: gov=dict(_v282_contract_trend(self,now=now,force=False) or {})
    except Exception: gov={}

    preferred=[]
    gside=str(gov.get('side','MIXED')).upper()
    if gov.get('clear') and gside=='DOWN':preferred=['UP','DOWN']
    elif gov.get('clear') and gside=='UP':preferred=['DOWN','UP']
    else:preferred=['UP','DOWN']
    cand=[_v286_candidate(one,side,native=native,fast30=fast30,fast15=fast15,existing=existing) for side in preferred]
    best=max(cand,key=lambda x:(1 if x.get('stage')=='CONFIRMED' else .65 if x.get('stage')=='BUILDING' else .35 if x.get('stage')=='WATCH' else 0,float(x.get('score',0) or 0))) if cand else {'ready':False,'side':'WAIT','stage':'NONE','score':0.0}
    # Do not emit a weak reversal in the SAME direction as an already-clear trend.
    if gov.get('clear') and str(best.get('side')).upper()==gside and best.get('stage')!='CONFIRMED':
        other=next((x for x in cand if str(x.get('side')).upper()!=gside),best)
        if float(other.get('score',0) or 0)>=float(best.get('score',0) or 0)*.72:best=other
    out=dict(best);out['ts']=now;out['contract_trend']=gside;out['contract_clear']=bool(gov.get('clear'))
    out['headline']=(f'REVERSAL SEQUENCE CONFIRMED -> {out.get("side")}' if out.get('stage')=='CONFIRMED' else
                     f'{"DOWN" if out.get("side")=="UP" else "UP"} MOMENTUM EXHAUSTION -> WATCH {out.get("side")}' if out.get('stage') in ('WATCH','BUILDING') else
                     'NO REVERSAL SEQUENCE')
    self._v286_reversal_cache=dict(out)
    return out


ChartKingPro._v286_reversal_sequence_read = _v286_reversal_sequence_read


# Attach the reversal sequence BEFORE the V21.82 trend governor decides whether
