def _v286_pre_guard_forecast(self, now=None, force=False):
    fc=dict(_V286_BASE_PRE_GUARD_FORECAST(self,now=now,force=force) or {})
    try:fc['reversal_sequence']=dict(_v286_reversal_sequence_read(self,now=now,force=force) or {})
    except Exception:fc['reversal_sequence']={}
    return fc


_V282_BASE_FORECAST = _v286_pre_guard_forecast


def _v286_countertrend_reversal(fc, gov):
    base=dict(_V286_BASE_COUNTERTREND(fc,gov) or {})
    if base.get('confirmed'):return base
    trend=str(gov.get('side','MIXED')).upper(); want=str(fc.get('settlement_side','WAIT')).upper()
    rev=dict(fc.get('reversal_sequence') or {})
    if trend not in ('UP','DOWN') or want not in ('UP','DOWN') or want==trend:return base
    if str(rev.get('stage','NONE')).upper()!='CONFIRMED' or str(rev.get('side','WAIT')).upper()!=want:return base
    sgn=1.0 if want=='UP' else -1.0
    path=sgn*float(fc.get('path_score',0) or 0)
    comp=dict(fc.get('components') or {})
    struct=sgn*float((comp.get('STRUCTURE_PATH') or {}).get('score',0) or 0)
    dest=sgn*float((comp.get('DESTINATION') or {}).get('score',0) or 0)
    conf=float(fc.get('confidence',50) or 50)
    hard=int(rev.get('hard_confirms',0) or 0)
    # This is the early-turn permission the old governor lacked. It still needs
    # a high-grade sequence plus at least some path/structure/destination rotation.
    rotated=(path>=-.03 and (path>=.10 or struct>=.08 or dest>=.08))
    confirmed=(float(rev.get('score',0) or 0)>=72 and float(rev.get('exhaustion',0) or 0)>=55 and
               float(rev.get('confirmation',0) or 0)>=44 and hard>=3 and rotated and conf>=60)
    if not confirmed:return base
    reasons=list(base.get('reasons') or [])
    reasons.append('CONFIRMED candle momentum-exhaustion reversal sequence')
    for r in list(rev.get('confirmations') or [])[:3]:
        if r not in reasons:reasons.append(r)
    return {'confirmed':True,'reasons':reasons,'short_reversed':list(base.get('short_reversed') or []),
            'breaks':list(base.get('breaks') or []),'wedges':list(base.get('wedges') or []),'reversal_sequence':rev,
            'source':'V21.86 EARLY REVERSAL PROOF'}


_v282_countertrend_reversal = _v286_countertrend_reversal


# Let the two-minute pro-path map hear confirmed/budding exhaustion without
# allowing it to dominate the professional settlement model.
def _v286_pro_path_packet(fc):
    base=dict(_V286_BASE_PRO_PATH(fc) or {})
    rev=dict(fc.get('reversal_sequence') or {})
    if not base.get('ready') or not rev.get('ready'):return base
    stage=str(rev.get('stage','NONE')).upper();side=str(rev.get('side','WAIT')).upper()
    if side not in ('UP','DOWN') or stage not in ('BUILDING','CONFIRMED'):return base
    signed=(1.0 if side=='UP' else -1.0)*_v286_clip01(float(rev.get('score',0) or 0)/100.0)
    w=.055 if stage=='BUILDING' else .12
    old=float(base.get('score',0) or 0);new=_v279_clip((1.0-w)*old+w*signed)
    base['score']=new;base['side']='UP' if new>=.035 else 'DOWN' if new<=-.035 else 'WAIT'
    base['reversal_sequence']=rev
    base['reason']=str(base.get('reason',''))+f' • REVSEQ {stage} {side} {float(rev.get("score",0)):.0f}/100'
    parts=dict(base.get('parts') or {});parts['REVERSAL_SEQUENCE']={'score':signed,'weight':w};base['parts']=parts
    return base


_v285_pro_path_packet = _v286_pro_path_packet
