# PLAN CHANGED: a CONFIRMED reversal sequence is one independent family. It can
# move a nearly-qualified review over the line, but never switches by itself.
def _v286_plan_change_sample(self, now, lock_side, fc):
    row=dict(_V286_BASE_PLAN_CHANGE_SAMPLE(self,now,lock_side,fc) or {})
    rev=dict(fc.get('reversal_sequence') or {})
    side=str(lock_side).upper();opp='DOWN' if side=='UP' else 'UP'
    if str(rev.get('stage','NONE')).upper()=='CONFIRMED' and str(rev.get('side','WAIT')).upper()==opp:
        reasons=list(row.get('reasons') or [])
        if 'confirmed momentum-exhaustion reversal sequence' not in reasons:
            reasons.append('confirmed momentum-exhaustion reversal sequence')
        row['reasons']=reasons;row['adverse']=min(1.0,float(row.get('adverse',0) or 0)+.10)
        conf=float(row.get('conf',0) or 0);signed=float(row.get('signed_edge',0) or 0);finish=float(row.get('signed_finish',0) or 0)
        path=float(row.get('signed_path',0) or 0);trend=float(row.get('signed_trend',0) or 0);q=max(1.0,float(fc.get('quantum',1) or 1))
        qualified=(len(reasons)>=4 and str(fc.get('settlement_side','WAIT')).upper()==opp and conf>=74 and signed<=-.30 and
                   finish<=-max(4.0,q*1.2) and float(row.get('adverse',0))>=.42)
        decisive=(qualified and len(reasons)>=5 and conf>=84 and signed<=-.60 and finish<=-max(10.0,q*3.0) and
                  path<=-.26 and trend<=-.24 and float(row.get('adverse',0))>=.63)
        row['qualified']=qualified;row['decisive']=decisive;row['candidate']=opp if qualified else 'WAIT';row['reversal_sequence']=rev
    return row


_v279_plan_change_sample = _v286_plan_change_sample


def _v286_alert_clear(self):
    try:
        c=getattr(self,'canvas',None)
        if c is not None:c.delete('v286_scream')
    except Exception:pass


def _v286_bell_burst(self):
    try:
        root=getattr(self,'root',None)
        if root is None:return
        root.bell();root.after(140,root.bell);root.after(300,root.bell);root.after(520,root.bell)
    except Exception:pass


def _v286_draw_alert(self, rev, now=None):
    now=float(now or time.time());c=getattr(self,'canvas',None)
    if c is None:return
    stage=str(rev.get('stage','NONE')).upper();side=str(rev.get('side','WAIT')).upper()
    if stage not in ('BUILDING','CONFIRMED') or side not in ('UP','DOWN'):
        _v286_alert_clear(self);return
    try:
        w=max(400,int(c.winfo_width() or 1000))
        c.delete('v286_scream')
        confirmed=stage=='CONFIRMED'
        if confirmed:
            flash=(int(now*6)%2)==0
            fill=('#00d991' if side=='UP' else '#ff3158') if flash else '#0b1015'
            outline='#ffffff' if flash else ('#00d991' if side=='UP' else '#ff3158')
            h=84
            c.create_rectangle(4,4,w-4,h,fill=fill,outline=outline,width=4,tags='v286_scream')
            c.create_text(w/2,28,text=f'!!! REVERSAL SEQUENCE CONFIRMED -> {side} !!!',fill='#ffffff',
                          font=('Segoe UI',19,'bold'),anchor='center',tags='v286_scream')
            why=' • '.join(list(rev.get('confirmations') or [])[:4])
            c.create_text(w/2,59,text=f'EXHAUST {float(rev.get("exhaustion",0)):.0f} • CONFIRM {float(rev.get("confirmation",0)):.0f} • {why}'[:150],
                          fill='#ffffff',font=('Cascadia Mono',9,'bold'),anchor='center',tags='v286_scream')
        else:
            h=46
            c.create_rectangle(4,4,w-4,h,fill='#17130a',outline='#ffc857',width=3,tags='v286_scream')
            c.create_text(w/2,25,text=f'!! MOMENTUM EXHAUSTION BUILDING -> REVERSAL WATCH {side} • {float(rev.get("score",0)):.0f}/100 !!',
                          fill='#ffc857',font=('Segoe UI',12,'bold'),anchor='center',tags='v286_scream')
        c.tag_raise('v286_scream')
    except Exception:pass


def _v286_alert_tick(self, rev, now=None):
    now=float(now or time.time());stage=str(rev.get('stage','NONE')).upper();side=str(rev.get('side','WAIT')).upper()
    if stage=='CONFIRMED' and side in ('UP','DOWN'):
        key=f'{side}:{int(float(rev.get("event_ts",0) or 0))}'
        last=str(getattr(self,'_v286_last_scream_key','') or '')
        if key!=last:
            self._v286_last_scream_key=key;self._v286_scream_until=now+8.0
            _v286_bell_burst(self)
            try:
                self.root.title(f'!!! REVERSAL CONFIRMED {side} !!! — LECHART JAMES V21.86')
            except Exception:pass
    if now<float(getattr(self,'_v286_scream_until',0) or 0) and side in ('UP','DOWN'):
        _v286_draw_alert(self,dict(rev,stage='CONFIRMED'),now=now)
    else:
        if stage=='BUILDING':_v286_draw_alert(self,rev,now=now)
        else:_v286_alert_clear(self)
        if float(getattr(self,'_v286_scream_until',0) or 0)>0 and now>=float(getattr(self,'_v286_scream_until',0) or 0):
            self._v286_scream_until=0.0
            try:self.root.title('LECHART JAMES V21.86 — 120S PRO PATH • REVERSAL SCREAM • BTC ONLY • 60FPS')
            except Exception:pass


