# ============================================================================
# LECHART JAMES V21.88 — ANTI-FREEZE TRANSPORT + VISIBLE PRO QUANT DESK
#
# Purpose:
#   1) Stop the long-session hard-freeze path caused by raw high-rate Bookmap
#      depth churn bypassing the older coalescing transport.
#   2) Remove V21.87 quant math + CSV writes from the high-frequency UI wrapper.
#   3) Mount an unmistakable PRO QUANT card in the ACTUAL visible cockpit rail.
#   4) Add UI-backpressure signalling so the Bookmap bridge automatically sheds
#      redundant depth presentation traffic if Tk ever falls behind.
#
# Strategy/lock/reversal/fair-value math is unchanged from V21.87.
# ============================================================================
_V288_RELEASE = 'V21.88'
_V288_BASE_INIT = ChartKingPro.__init__
_V288_BASE_CLEAR = _v287_clear_round_authority
_V288_BASE_HARD_RESET = _v287_hard_round_reset
_V288_BASE_UI_TICK = _V287_BASE_UI_TICK  # V21.86 UI/alert path; quant gets its own pump.
_V288_BASE_CHILD_APPLY = _bk_child_apply_event
_V288_BASE_MOUNT = _v2676_mount_cockpit

import queue as _v288_queue


def _v288_set(var, value):
    try:
        s=str(value)
        if var.get()!=s: var.set(s)
    except Exception:
        pass


def _v288_ingest_depth_batch(app, event):
    """Apply a coalesced depth packet under ONE Bookmap mutex acquisition.

    Each update is [side, price, size, ts]. Deep-book churn is already reduced
    by the bridge; this function keeps the UI receiver from reacquiring the
    Python mutex thousands of times per second.
    """
    updates=list((event or {}).get('updates') or [])
    if not updates:
        return
    now=time.time()
    try:
        live=getattr(app,'current_spot',None)
        if live is not None: live=float(live)
    except Exception:
        live=None
    try:
        with app.bookmap_lock:
            app.bookmap_connected=True
            app.bookmap_last_event_ts=now
            try: app.bookmap_transport_last_ts=now
            except Exception: pass
            try: app.bookmap_last_data_event_ts=now
            except Exception: pass
            app.bookmap_events_received=int(getattr(app,'bookmap_events_received',0) or 0)+len(updates)
            for row in updates:
                try:
                    side=str(row[0]).lower(); price=float(row[1]); size=float(row[2])
                except Exception:
                    continue
                book=app.bookmap_bids if side=='bid' else app.bookmap_asks
                old=book.get(price)
                if size<=0:
                    book.pop(price,None)
                else:
                    first_seen=float(old.get('first_seen',now)) if old and size>=float(old.get('size',0.0))*0.45 else now
                    book[price]={'size':size,'first_seen':first_seen,'updated':now}
            # Keep native books bounded without invoking any method that might
            # recursively acquire the same market-data lock.
            for book in (app.bookmap_bids,app.bookmap_asks):
                if len(book)>4200:
                    if live is not None:
                        keep=sorted(book.items(),key=lambda kv:abs(float(kv[0])-live))[:2200]
                    else:
                        keep=list(book.items())[-2200:]
                    book.clear();book.update(keep)
    except Exception:
        try: app.bookmap_parse_errors=int(getattr(app,'bookmap_parse_errors',0) or 0)+1
        except Exception: pass


def _v288_child_apply_event(app, root, event):
    kind=str((event or {}).get('type','')).lower().strip()
    if kind=='depth_batch':
        _v288_ingest_depth_batch(app,event)
        return
    if kind=='transport_stats':
        try:
            app._v288_transport_stats=dict(event or {})
            app.bookmap_transport_last_ts=time.time()
        except Exception:
            pass
        return
    return _V288_BASE_CHILD_APPLY(app,root,event)


