def _v288_mount_quant_card(app):
    """Mount the quant desk into the real 220px cockpit rail, not legacy UI."""
    try:
        side=getattr(app,'v274_right_rail',None)
        if side is None or not side.winfo_exists():
            return False
        existing=getattr(app,'v288_quant_card',None)
        if existing is not None and existing.winfo_exists():
            return True

        # Insert directly below MAIN LOCK. Existing evidence rows move down one.
        children=[]
        for ch in side.winfo_children():
            try:
                info=ch.grid_info(); row=int(info.get('row',0)); col=int(info.get('column',0)); span=int(info.get('columnspan',1) or 1)
            except Exception:
                continue
            children.append((ch,row,col,span))
        for ch,row,col,span in children:
            if row>=1:
                try: ch.grid_configure(row=row+1)
                except Exception: pass
        for r in range(7):
            try: side.grid_rowconfigure(r,weight=1,minsize=0)
            except Exception: pass

        card=_v2676_card(side,'∑ PRO QUANT FAIR VALUE',_V2676_BLUE,padx=6,pady=5)
        card.grid(row=1,column=0,columnspan=2,sticky='nsew',pady=5)
        app.v288_quant_card=card
        app.v288_quant_fair_var=tk.StringVar(value='FAIR YES --')
        app.v288_quant_edge_var=tk.StringVar(value='WAIT • building independent value')
        app.v288_quant_market_var=tk.StringVar(value='KALSHI YES --/--')
        app.v288_quant_meta_var=tk.StringVar(value='CONF -- • DISP --')
        app.v288_quant_transport_var=tk.StringVar(value='TRANSPORT: warming up')
        tk.Label(card,textvariable=app.v288_quant_fair_var,bg=_V2676_PANEL,fg=_V2676_CYAN,
                 font=('Cascadia Mono',12,'bold'),anchor='w').pack(fill='x',pady=(3,0))
        tk.Label(card,textvariable=app.v288_quant_edge_var,bg=_V2676_PANEL,fg=_V2676_GREEN,
                 font=('Cascadia Mono',8,'bold'),anchor='w',justify='left',wraplength=198).pack(fill='x',pady=(2,0))
        tk.Label(card,textvariable=app.v288_quant_market_var,bg=_V2676_PANEL,fg=_V2676_TEXT,
                 font=('Cascadia Mono',7,'bold'),anchor='w').pack(fill='x',pady=(2,0))
        tk.Label(card,textvariable=app.v288_quant_meta_var,bg=_V2676_PANEL,fg=_V2676_MUTED,
                 font=('Cascadia Mono',7),anchor='w').pack(fill='x')
        tk.Label(card,textvariable=app.v288_quant_transport_var,bg=_V2676_PANEL,fg=_V2676_MUTED,
                 font=('Cascadia Mono',6),anchor='w',wraplength=198).pack(fill='x',pady=(1,0))
        return True
    except Exception:
        return False


