def _v288_render_quant(self,q):
    """Low-allocation visible quant update. Called by the dedicated quant pump."""
    try:
        _v288_mount_quant_card(self)
        if not q or not q.get('ready'):
            if hasattr(self,'v288_quant_fair_var'):
                _v288_set(self.v288_quant_fair_var,'FAIR YES --')
                _v288_set(self.v288_quant_edge_var,'WAIT • '+str((q or {}).get('reason','building independent value'))[:58])
                _v288_set(self.v288_quant_market_var,'KALSHI YES --/--')
                _v288_set(self.v288_quant_meta_var,'CONF -- • DISP --')
            return
        fy=float(q.get('fair_yes',.5))*100.0
        lo=float(q.get('fair_low',q.get('fair_yes',.5)))*100.0
        hi=float(q.get('fair_high',q.get('fair_yes',.5)))*100.0
        rel=float(q.get('reliability',0))*100.0
        disp=float(q.get('dispersion',0))*100.0
        verdict=str(q.get('verdict','WAIT'))
        net=q.get('net_edge')
        side=str(q.get('side','WAIT'))
        edge=(f'{float(net)*100:+.1f}pp {side}' if net is not None else 'NO EXEC EDGE')
        _v288_set(self.v288_quant_fair_var,f'FAIR YES {fy:.1f}¢ [{lo:.0f}-{hi:.0f}]')
        _v288_set(self.v288_quant_edge_var,f'{verdict} • {edge}')
        if q.get('yes_bid') is not None:
            _v288_set(self.v288_quant_market_var,
                      f'YES {float(q.get("yes_bid"))*100:.1f}/{float(q.get("yes_ask"))*100:.1f}¢  •  NO {float(q.get("no_bid"))*100:.1f}/{float(q.get("no_ask"))*100:.1f}¢')
        else:
            _v288_set(self.v288_quant_market_var,'KALSHI BBO: waiting')
        _v288_set(self.v288_quant_meta_var,f'CONF {rel:.0f}/100 • DISP {disp:.1f}pp • {int(q.get("model_count",0) or 0)} MODELS')
        stats=dict(getattr(self,'_v288_transport_stats',{}) or {})
        if stats:
            _v288_set(self.v288_quant_transport_var,
                      f'RX depth {int(stats.get("depth_sent",0) or 0):,} • coalesced {int(stats.get("depth_coalesced",0) or 0):,} • mode {stats.get("mode","NORMAL")}')
        else:
            _v288_set(self.v288_quant_transport_var,'TRANSPORT: coalesced depth • anti-freeze active')
    except Exception:
        pass


def _v288_log_worker(self):
    """Buffered CSV logger. No file open/write occurs on the Tk thread."""
    path=Path.home()/'Downloads'/'LECHART_V21_88_QUANT_LOG.csv'
    fields=['ts','bucket','ticker','seconds_left','live','target','fair_yes','fair_low','fair_high','reliability','dispersion',
            'yes_bid','yes_ask','no_bid','no_ask','spread','raw_yes_edge','raw_no_edge','hurdle','net_yes_edge','net_no_edge','verdict']
    f=None
    try:
        path.parent.mkdir(parents=True,exist_ok=True)
        new=not path.exists()
        f=path.open('a',encoding='utf-8',newline='',buffering=1)
        if new:f.write(','.join(fields)+'\n')
        while not bool(getattr(self,'_v288_stop_workers',False)):
            try:q=self._v288_log_queue.get(timeout=.5)
            except _v288_queue.Empty:continue
            if q is None:continue
            vals=[q.get(k) for k in fields]
            def esc(v):
                if v is None:return ''
                s=str(v)
                if any(c in s for c in ',"\n'):s='"'+s.replace('"','""')+'"'
                return s
            f.write(','.join(esc(v) for v in vals)+'\n')
    except Exception:
        pass
    finally:
        try:
            if f:f.close()
        except Exception:pass


def _v288_queue_log(self,q):
    if not q or not q.get('ready'):return
    now=float(q.get('ts',time.time()) or time.time())
    if now-float(getattr(self,'_v288_last_log_enqueue',0) or 0)<2.0:return
    self._v288_last_log_enqueue=now
    rec={
        'ts':now,'bucket':int(now//900)*900,'ticker':q.get('ticker',''),'seconds_left':q.get('seconds_left'),
        'live':q.get('live'),'target':q.get('target'),'fair_yes':q.get('fair_yes'),'fair_low':q.get('fair_low'),'fair_high':q.get('fair_high'),
        'reliability':q.get('reliability'),'dispersion':q.get('dispersion'),'yes_bid':q.get('yes_bid'),'yes_ask':q.get('yes_ask'),
        'no_bid':q.get('no_bid'),'no_ask':q.get('no_ask'),'spread':q.get('spread'),'raw_yes_edge':q.get('raw_yes_edge'),
        'raw_no_edge':q.get('raw_no_edge'),'hurdle':q.get('hurdle'),'net_yes_edge':q.get('net_yes_edge'),'net_no_edge':q.get('net_no_edge'),
        'verdict':q.get('verdict','')}
    try:self._v288_log_queue.put_nowait(rec)
    except _v288_queue.Full:
        try:self._v288_log_queue.get_nowait()
        except Exception:pass
        try:self._v288_log_queue.put_nowait(rec)
        except Exception:pass


def _v288_quant_pump(self):
    """Quant math at a calm cadence, outside the 30Hz cockpit wrapper."""
    started=time.perf_counter();q={}
    try:
        q=_v287_quant_fair_value(self,now=time.time(),force=True)
        self._v288_quant_snapshot=dict(q or {})
        _v287_update_quant_ui(self,q)  # legacy vars for popups/web state
        _v288_render_quant(self,q)
        _v287_quant_alert(self,q)
        _v288_queue_log(self,q)
    except Exception as exc:
        self._v288_quant_snapshot={'ready':False,'reason':str(exc),'ts':time.time()}
    elapsed=(time.perf_counter()-started)*1000.0
    self._v288_quant_ms=elapsed if float(getattr(self,'_v288_quant_ms',0) or 0)<=0 else float(getattr(self,'_v288_quant_ms',0))*0.85+elapsed*0.15
    # Quant valuation does not need frame-rate cadence. Slow automatically if a
    # model evaluation is expensive so chart motion always wins.
    delay=500 if elapsed<16 else 650 if elapsed<30 else 900 if elapsed<60 else 1300
    try:self.root.after(delay,lambda s=self:_v288_quant_pump(s))
    except Exception:pass


def _v288_ui_tick(self):
    """Deduplicated telemetry path; chart/cockpit have their own schedulers.

    Several historical append layers each scheduled `_v269_ui_tick`. Because
    those lambdas resolve the FINAL global symbol, they could leave multiple
    identical telemetry chains alive forever. Only the first due callback is
    allowed to run/schedule the inherited chain; redundant callbacks return and
    naturally die.
    """
    now=time.perf_counter(); self._v288_ui_heartbeat=now
    last=float(getattr(self,'_v288_last_ui_telemetry',0.0) or 0.0)
    if last and now-last<0.075:
        return None
    self._v288_last_ui_telemetry=now
    return _V288_BASE_UI_TICK(self)


_v269_ui_tick = _v288_ui_tick


def _v288_transport_watchdog(self):
    """Background lag detector. It never touches Tk directly."""
    last_mode='NORMAL'; recover_since=0.0
    while not bool(getattr(self,'_v288_stop_workers',False)):
        now=time.perf_counter(); hb=float(getattr(self,'_v288_ui_heartbeat',now) or now); age=max(0.0,now-hb)
        desired='PROTECT' if age>.70 else 'NORMAL'
        if desired=='NORMAL' and last_mode=='PROTECT':
            if recover_since<=0:recover_since=now
            if now-recover_since<2.0:
                desired='PROTECT'
        else:
            recover_since=0.0
        if desired!=last_mode:
            try:_v2674_send_control({'type':'backpressure','level':desired,'ui_lag':age,'asset':'BTC','ts':time.time()})
            except Exception:pass
            last_mode=desired
        time.sleep(.15)


