def _v288_init(self,*args,**kwargs):
    _V288_BASE_INIT(self,*args,**kwargs)
    try:
        self._v288_ui_heartbeat=time.perf_counter();self._v288_last_ui_telemetry=0.0;self._v288_stop_workers=False
        self._v288_quant_snapshot={};self._v288_quant_ms=0.0;self._v288_transport_stats={}
        self._v288_last_log_enqueue=0.0;self._v288_log_queue=_v288_queue.Queue(maxsize=6)
        threading.Thread(target=_v288_log_worker,args=(self,),name='LeChart-V2188-QuantLogger',daemon=True).start()
        threading.Thread(target=_v288_transport_watchdog,args=(self,),name='LeChart-V2188-FreezeWatchdog',daemon=True).start()
        self.root.after(160,lambda s=self:_v288_mount_quant_card(s))
        self.root.after(500,lambda s=self:_v288_quant_pump(s))
        self.root.title('LECHART JAMES V21.88 — ANTI-FREEZE • VISIBLE PRO QUANT • 120S PRO PATH')
        self.paper_status_var.set('PAPER AUTO: V21.88 • ANTI-FREEZE TRANSPORT • VISIBLE PRO QUANT • MAIN LOCK UNCHANGED')
    except Exception:pass


