def _v289_clip(x, lo=0.0, hi=1.0):
    try:return max(float(lo),min(float(hi),float(x)))
    except Exception:return float(lo)


def _v289_one_sec_tape(self, now=None, lookback=210.0):
    """Compact one-price-per-second native tape. Read-only and bounded."""
    now=float(now or time.time());cut=now-max(30.0,float(lookback))
    try:
        with self.bookmap_lock:
            raw=list(getattr(self,'bookmap_trades',()))[-3500:]
    except Exception:
        raw=list(getattr(self,'bookmap_trades',()))[-3500:]
    sec={}
    for t in raw:
        try:
            ts=float(t.get('ts',0) or 0);px=float(t.get('price'))
            if ts>=cut and math.isfinite(px) and px>0:sec[int(ts)]=(ts,px)
        except Exception:pass
    rows=sorted(sec.values())
    # Quote fallback only if executions are temporarily sparse.
    if len(rows)<8:
        try:
            pts=[(float(ts),float(px)) for ts,px in list(getattr(self,'live_prices',()))[-1200:] if float(ts)>=cut]
            for ts,px in pts:sec[int(ts)]=(ts,px)
            rows=sorted(sec.values())
        except Exception:pass
    return rows


def _v289_price_at(rows, ts):
    if not rows:return None
    best=None
    for t,p in rows:
        if t<=ts:best=p
        else:break
    return float(best if best is not None else rows[0][1])


def _v289_time_window_read(self, now=None, fc=None, force=False):
    """Is the broader trend still fast enough to matter before THIS settlement?

    This is explicitly NOT a current-winner rule. It uses the actual dollar
    distance to target, remaining clock, recent directional efficiency, and the
    time since the trend last made useful progress. A broader DOWN trend may be
    retained while the settlement-window conclusion becomes UP because DOWN is
    now too late for this specific expiry.
    """
    now=float(now or time.time())
    cache=dict(getattr(self,'_v289_time_cache',{}) or {})
    if (not force) and cache and now-float(cache.get('ts',0) or 0)<.40:return cache
    fc=dict(fc or {})
    if not fc.get('ready') or fc.get('target') is None:
        out={'ready':False,'ts':now,'reason':'settlement clock waiting for target/forecast'};self._v289_time_cache=out;return out
    try:
        live=float(fc.get('live') if fc.get('live') is not None else self.effective_live_price()[0])
        target=float(fc.get('target'))
    except Exception:
        out={'ready':False,'ts':now,'reason':'settlement clock waiting for live/target'};self._v289_time_cache=out;return out
    gov=dict(fc.get('contract_trend') or {})
    broad=str(gov.get('side','MIXED')).upper()
    if broad not in ('UP','DOWN'):
        ps=float(fc.get('path_score',0) or 0)
        broad='UP' if ps>=.22 else 'DOWN' if ps<=-.22 else 'MIXED'
    rows=_v289_one_sec_tape(self,now=now,lookback=210)
    if len(rows)<18 or broad not in ('UP','DOWN'):
        out={'ready':False,'ts':now,'broad_side':broad,'reason':'settlement clock building native pace history'};self._v289_time_cache=out;return out

    sign=1.0 if broad=='UP' else -1.0
    cur=float(rows[-1][1]); recent_s=45.0; prior_s=105.0
    recent_start=max(rows[0][0],now-recent_s); prior_start=max(rows[0][0],recent_start-prior_s)
    pr=_v289_price_at(rows,recent_start); pp=_v289_price_at(rows,prior_start)
    recent_dur=max(8.0,rows[-1][0]-recent_start);prior_dur=max(12.0,recent_start-prior_start)
    recent_move=sign*(cur-float(pr));prior_move=sign*(float(pr)-float(pp))
    recent_rate=max(0.0,recent_move/recent_dur);prior_rate=max(0.0,prior_move/prior_dur)
    recent_prices=[p for t,p in rows if t>=recent_start]
    prior_prices=[p for t,p in rows if prior_start<=t<recent_start]
    rr=max(recent_prices)-min(recent_prices) if len(recent_prices)>=2 else 0.0
    prng=max(prior_prices)-min(prior_prices) if len(prior_prices)>=2 else max(rr,1.0)
    efficiency=abs(cur-float(pr))/max(1.0,rr)
    compression=_v289_clip(1.0-rr/max(1.0,prng),0,1)
    decay=1.0-_v289_clip(recent_rate/max(.02,prior_rate*.72),0,1) if prior_rate>.02 else 0.0
    ext_rows=[(t,p) for t,p in rows if t>=now-105]
    if broad=='DOWN':ext_t=min(ext_rows,key=lambda x:x[1])[0]
    else:ext_t=max(ext_rows,key=lambda x:x[1])[0]
    extreme_age=max(0.0,now-float(ext_t))
    age_score=_v289_clip((extreme_age-15.0)/55.0,0,1)
    ineff=_v289_clip((.58-efficiency)/.58,0,1)
    prior_impulse=_v289_clip(prior_rate/.65,0,1)
    stall=_v289_clip(.33*decay+.25*ineff+.20*compression+.22*age_score,0,1)*(.55+.45*prior_impulse)

    sec_left=max(0.0,900.0-(now%900.0))
    # Distance the BROADER trend still has to travel to cross this contract's
    # target. Merely naming which side is currently winning is never consulted.
    need=max(0.0,(target-cur) if broad=='UP' else (cur-target))
    diffs=[]
    for (t0,p0),(t1,p1) in zip(rows[-100:],rows[-99:]):
        dt=max(.15,t1-t0);diffs.append(abs(p1-p0)/dt)
    med_abs=_v279_median(diffs,0.0) if diffs else 0.0
    # In a stall, old impulse velocity is aggressively discounted; a trader
    # should not assume the previous dump/pump simply resumes on schedule.
    achievable=max(.03,recent_rate+prior_rate*(.03+.15*(1.0-stall))+.10*med_abs)
    eta=(need/achievable) if need>0 else 0.0
    eta_ratio=eta/max(1.0,sec_left)
    urgency=_v289_clip((420.0-sec_left)/330.0,0,1)

    # Forward settlement projection during a stall. Recent raw drift is capped so
    # one noisy second cannot manufacture a finish. Blend with the existing model.
    raw_recent=(cur-float(pr))/recent_dur
    cap=max(.05,med_abs*1.35,prior_rate*.90)
    raw_recent=max(-cap,min(cap,raw_recent))
    horizon=min(sec_left,240.0)
    local_finish=cur+raw_recent*horizon*.55
    try:base_center=float(fc.get('projected_center',cur) or cur)
    except Exception:base_center=cur
    projected=.68*local_finish+.32*base_center if stall>=.45 else .35*local_finish+.65*base_center
    projected_delta=projected-target
    projected_side='UP' if projected_delta>0 else 'DOWN' if projected_delta<0 else 'LINE'
    opposite='DOWN' if broad=='UP' else 'UP'

    distance_strain=need/max(8.0,rr*1.25)
    hard_fail=(sec_left<=390.0 and need>max(3.0,float(fc.get('quantum',1) or 1)*.45) and stall>=.56 and projected_side==opposite and
               (eta_ratio>=.70 or (sec_left<=240.0 and stall>=.76 and extreme_age>=28.0 and distance_strain>=1.65)))
    warning=(not hard_fail and sec_left<=480.0 and stall>=.42 and eta_ratio>=.55 and projected_side==opposite)
    intensity=_v289_clip(.36*stall+.34*_v289_clip(eta_ratio/1.25,0,1)+.20*urgency+.10*_v289_clip(abs(projected_delta)/max(8.0,float(fc.get('quantum',1) or 1)*2.0),0,1),0,1)
    score=(1.0 if opposite=='UP' else -1.0)*(0.35+0.55*intensity) if hard_fail else ((1.0 if opposite=='UP' else -1.0)*(.18+.38*intensity) if warning else 0.0)
    status=('TIME-FAILED' if hard_fail else 'STALL WARNING' if warning else 'ON SCHEDULE')
    reason=(f'{broad} broader trend • {status} • stall {stall*100:.0f}% • no useful extreme {extreme_age:.0f}s • '
            f'needs ${need:.0f} in {sec_left:.0f}s • pace ETA {eta:.0f}s • projected finish {projected_delta:+.0f}$ vs target')
    out={'ready':True,'ts':now,'broad_side':broad,'opposite':opposite,'hard_fail':hard_fail,'warning':warning,
         'status':status,'score':score,'stall':stall,'extreme_age':extreme_age,'efficiency':efficiency,'compression':compression,
         'recent_rate':recent_rate,'prior_rate':prior_rate,'achievable_rate':achievable,'need':need,'seconds_left':sec_left,
         'eta':eta,'eta_ratio':eta_ratio,'distance_strain':distance_strain,'projected_finish':projected,'projected_delta':projected_delta,
         'projected_side':projected_side,'reason':reason,'current_winner_used':False}
    self._v289_time_cache=dict(out);return out


def _v289_forecast_read(self, now=None, force=False):
    fc=dict(_V289_BASE_FORECAST(self,now=now,force=force) or {})
    if not fc.get('ready'):return fc
    tw=_v289_time_window_read(self,now=now,fc=fc,force=force);fc['time_window']=tw
    if not tw.get('ready'):
        return fc
    # Keep broader path/trend untouched. Only settlement-window authority may
    # change when the existing trend is demonstrably running out of clock.
    if tw.get('hard_fail'):
        side=str(tw.get('opposite','WAIT')).upper();sign=1.0 if side=='UP' else -1.0
        center=float(tw.get('projected_finish',fc.get('projected_center',fc.get('live',fc.get('target',0)))) or 0)
        target=float(fc.get('target',0) or 0);old_center=float(fc.get('projected_center',center) or center)
        old_lo=float(fc.get('projected_low',old_center) or old_center);old_hi=float(fc.get('projected_high',old_center) or old_center)
        half=max(6.0,abs(old_hi-old_lo)*.50,float(fc.get('quantum',1) or 1)*1.5)
        fc['pre_time_window_settlement_side']=str(fc.get('settlement_side','WAIT')).upper()
        fc['pre_time_window_finish_delta']=float(fc.get('finish_delta',old_center-target) or 0)
        fc['projected_center']=center;fc['projected_low']=center-half;fc['projected_high']=center+half
        fc['finish_delta']=center-target
        mag=max(.18,min(.72,.20+.58*float(tw.get('stall',0) or 0)*float(tw.get('eta_ratio',0) or 0)))
        fc['settlement_side']=side;fc['settlement_score']=sign*mag
        fc['confidence']=max(60.0,min(91.0,float(fc.get('confidence',60) or 60)+8.0*float(tw.get('stall',0) or 0)))
        fc['time_window_override']=True
        fc['reason']=str(fc.get('reason',''))+' • SETTLEMENT CLOCK OVERRIDE: '+str(tw.get('reason',''))+' • broader trend preserved for next-window context'
    elif tw.get('warning'):
        fc['reason']=str(fc.get('reason',''))+' • SETTLEMENT CLOCK WARNING: '+str(tw.get('reason',''))
    return fc


