def _v289_collect(self, now, fc):
    st=_V289_BASE_COLLECT(self,now,fc)
    try:
        rows=st.get('samples') or []
        if not rows:return st
        row=rows[-1]
        if abs(float(row.get('ts',0) or 0)-float(now))>.30:return st
        tw=dict((fc or {}).get('time_window') or _v289_time_window_read(self,now=now,fc=fc) or {})
        if tw.get('ready'):
            ts=float(tw.get('score',0) or 0);base=float(row.get('pro_score',0) or 0)
            w=.25 if tw.get('hard_fail') else .10 if tw.get('warning') else .03
            row['pro_score']=_v279_clip((1.0-w)*base+w*ts)
            row['pro_side']='UP' if row['pro_score']>=.035 else 'DOWN' if row['pro_score']<=-.035 else 'WAIT'
            row['time_window_score']=ts;row['time_window_status']=str(tw.get('status',''))
            row['time_window_reason']=str(tw.get('reason',''))
    except Exception:pass
    return st


