def _v289_plan_change_sample(self, now, lock_side, fc):
    """Allow a settlement-clock plan change even when the broader trend remains intact.

    This is the user's exact time-boxed case: the old trend may resume next
    market, but it has stalled too long to win the CURRENT expiry.
    """
    row=dict(_V289_BASE_PLAN_CHANGE(self,now,lock_side,fc) or {})
    tw=dict((fc or {}).get('time_window') or {})
    side=str(lock_side).upper();opp='DOWN' if side=='UP' else 'UP'
    if not tw.get('hard_fail') or str(tw.get('projected_side','WAIT')).upper()!=opp:
        return row
    reasons=list(row.get('reasons') or [])
    extras=[]
    extras.append('settlement clock says original path is out of time')
    if float(tw.get('stall',0) or 0)>=.62:extras.append('trend progress stalled')
    if float(tw.get('extreme_age',0) or 0)>=28:extras.append('no useful new trend extreme for too long')
    if float(tw.get('eta_ratio',0) or 0)>=.70 or float(tw.get('distance_strain',0) or 0)>=1.65:extras.append('required pace exceeds recent achievable pace')
    if float(tw.get('compression',0) or 0)>=.45:extras.append('price compressed / burned clock')
    for r in extras:
        if r not in reasons:reasons.append(r)
    row['reasons']=reasons
    adverse=min(1.0,float(row.get('adverse',0) or 0)+.14+.12*float(tw.get('stall',0) or 0))
    row['adverse']=adverse;row['time_window']=tw
    try:
        conf=float(row.get('conf',0) or fc.get('confidence',0) or 0);signed=float(row.get('signed_edge',0) or 0)
        finish=float(row.get('signed_finish',0) or 0);q=max(1.0,float(fc.get('quantum',1) or 1))
        # Time-box switch deliberately does NOT require path/trend reversal: that
        # would defeat the whole idea that the broader trend can resume next round.
        qualified=(len(reasons)>=4 and str(fc.get('settlement_side','WAIT')).upper()==opp and conf>=70 and signed<=-.22 and
                   finish<=-max(3.0,q*.9) and adverse>=.40 and float(tw.get('stall',0) or 0)>=.58)
        decisive=(qualified and len(reasons)>=5 and conf>=80 and signed<=-.42 and
                  float(tw.get('stall',0) or 0)>=.72 and float(tw.get('seconds_left',999) or 999)<=240)
        if qualified:
            row['qualified']=True;row['candidate']=opp;row['decisive']=bool(decisive)
    except Exception:pass
    return row


