def _v289_mount_quant_strip(app):
    """Always-visible PRO QUANT strip inside the actual chart card."""
    try:
        old=getattr(app,'v289_quant_strip',None)
        if old is not None and old.winfo_exists():return True
        c=getattr(app,'canvas',None)
        if c is None or not c.winfo_exists():return False
        parent=c.master
        info=c.grid_info()
        if not info:return False
        crow=int(info.get('row',2))
        # Make one permanent row directly above the chart canvas.
        for ch in list(parent.grid_slaves()):
            if ch is c:continue
            try:
                gi=ch.grid_info();r=int(gi.get('row',-1))
                if r>=crow:ch.grid_configure(row=r+1)
            except Exception:pass
        c.grid_configure(row=crow+1)
        try:parent.grid_rowconfigure(crow,weight=0,minsize=54);parent.grid_rowconfigure(crow+1,weight=1)
        except Exception:pass
        strip=tk.Frame(parent,bg='#071521',highlightthickness=2,highlightbackground='#35c8ff',padx=8,pady=5)
        strip.grid(row=crow,column=0,sticky='ew',padx=8,pady=(3,2))
        app.v289_quant_strip=strip
        app.v289_quant_title_var=tk.StringVar(value='∑ PRO QUANT • BUILDING INDEPENDENT FAIR VALUE')
        app.v289_quant_value_var=tk.StringVar(value='FAIR YES --   •   KALSHI --   •   EDGE --')
        app.v289_window_var=tk.StringVar(value='SETTLEMENT CLOCK: building native pace history')
        tk.Label(strip,textvariable=app.v289_quant_title_var,bg='#071521',fg='#35c8ff',font=('Cascadia Mono',9,'bold'),anchor='w').pack(fill='x')
        tk.Label(strip,textvariable=app.v289_quant_value_var,bg='#071521',fg='#ffffff',font=('Cascadia Mono',9,'bold'),anchor='w').pack(fill='x',pady=(1,0))
        tk.Label(strip,textvariable=app.v289_window_var,bg='#071521',fg='#f6c85f',font=('Cascadia Mono',7,'bold'),anchor='w').pack(fill='x',pady=(1,0))
        return True
    except Exception:return False


