def _v289_health_tick(self):
    """Cheap bounded-state maintenance and visible freeze diagnostics."""
    try:
        # Keep old list-based caches bounded even during very active sessions.
        lp=getattr(self,'live_prices',None)
        if isinstance(lp,list) and len(lp)>6500:self.live_prices=lp[-5000:]
        for name in ('btc_1m','btc_15m'):
            rows=getattr(self,name,None)
            if isinstance(rows,list) and len(rows)>4000:setattr(self,name,rows[-2500:])
        # Depth already coalesces upstream; enforce a second absolute bound here.
        lock=getattr(self,'bookmap_lock',None)
        if lock and lock.acquire(timeout=.003):
            try:
                live=float(getattr(self,'current_spot',0) or 0)
                for name in ('bookmap_bids','bookmap_asks'):
                    book=getattr(self,name,None)
                    if isinstance(book,dict) and len(book)>2800:
                        if live>0:keep=sorted(book.items(),key=lambda kv:abs(float(kv[0])-live))[:1800]
                        else:keep=list(book.items())[-1800:]
                        book.clear();book.update(keep)
            finally:lock.release()
        try:
            after_count=len(self.root.tk.call('after','info'))
        except Exception:after_count=-1
        self._v289_after_count=after_count
        # Keep the strip self-healing if another legacy layout callback remounts.
        if not _v289_mount_quant_strip(self):pass
    except Exception:pass
    finally:
        try:self.root.after(2500,lambda s=self:_v289_health_tick(s))
        except Exception:pass


