def _v290_norm_ts(raw, fallback=None):
    try:
        ts=float(raw)
        if ts>1e16: ts/=1e9
        elif ts>1e12: ts/=1e3
        return ts
    except Exception:
        return float(fallback if fallback is not None else time.time())


def _v290_cache_trade_rows(app, events):
    """Incremental native 1s OHLCV. O(number of NEW trades), never O(full tape)."""
    lock=getattr(app,'_v290_1s_lock',None)
    if lock is None:
        return
    now=time.time()
    try:
        with lock:
            mp=app._v290_1s_map; order=app._v290_1s_order
            for ev in events or ():
                if not isinstance(ev,dict): continue
                try:
                    ts=_v290_norm_ts(ev.get('ts'),now); px=float(ev.get('price')); sz=max(0.0,float(ev.get('size',0) or 0))
                    if not math.isfinite(px) or px<=0: continue
                except Exception:
                    continue
                b=int(ts)
                row=mp.get(b)
                if row is None:
                    row={'time':b,'open':px,'high':px,'low':px,'close':px,'volume':sz,
                         '_first_ts':ts,'_last_ts':ts,'_trade_count':1,
                         '_open_source':'BOOKMAP EXECUTION','_live_source':'BOOKMAP EXECUTIONS'}
                    mp[b]=row; order.append(b)
                else:
                    row['high']=max(float(row.get('high',px)),px); row['low']=min(float(row.get('low',px)),px)
                    row['volume']=float(row.get('volume',0) or 0)+sz
                    row['_trade_count']=int(row.get('_trade_count',0) or 0)+1
                    if ts<float(row.get('_first_ts',ts) or ts): row['open']=px; row['_first_ts']=ts
                    if ts>=float(row.get('_last_ts',ts) or ts): row['close']=px; row['_last_ts']=ts
            # Two hours of 1s bars is plenty for every visible/decision use here.
            cutoff=int(now)-7200
            while order and (len(order)>7300 or order[0]<cutoff):
                k=order.popleft(); mp.pop(k,None)
    except Exception:
        pass


def _v290_apply_trade_batch(app, events):
    _v290_cache_trade_rows(app,events)
    return _V290_BASE_TRADE_BATCH(app,events)


# _v289_child_apply_event resolves this global dynamically.
_v256_apply_trade_batch = _v290_apply_trade_batch


def _v290_aggregate_1s(self, include_current=False, now=None, limit=5400):
    now=float(now or time.time()); current=int(now); result=[]
    try:
        with self._v290_1s_lock:
            keys=list(self._v290_1s_order)
            mp=self._v290_1s_map
            # Slice BEFORE copying dictionaries; no full native-trade scan.
            if limit: keys=keys[-min(len(keys),int(limit)+2):]
            for k in keys:
                if k>current or (k==current and not include_current): continue
                r=mp.get(k)
                if r is not None: result.append(dict(r))
    except Exception:
        result=[]
    if result:
        return result[-int(limit):]
    # Very early startup fallback only. Bound the scan tightly so this can never
    # become the old progressive-cost path.
    rows={}
    try:
        with self.bookmap_lock:
            tape=list(getattr(self,'bookmap_trades',()))[-800:]
    except Exception:
        tape=list(getattr(self,'bookmap_trades',()))[-800:]
    for t in tape:
        try:
            ts=_v290_norm_ts(t.get('ts',t.get('received',0)),now); px=float(t.get('price')); sz=max(0.0,float(t.get('size',0) or 0)); b=int(ts)
            if b>current or (b==current and not include_current): continue
            r=rows.get(b)
            if r is None: rows[b]={'time':b,'open':px,'high':px,'low':px,'close':px,'volume':sz,'_first_ts':ts,'_last_ts':ts,'_trade_count':1}
            else:
                r['high']=max(r['high'],px);r['low']=min(r['low'],px);r['close']=px;r['volume']+=sz;r['_trade_count']+=1
        except Exception: pass
    return [rows[k] for k in sorted(rows)][-int(limit):]


# Rebind every route that previously rebuilt 1s bars from the whole trade deque.
_v282_aggregate_1s = _v290_aggregate_1s


def _v290_history_for_interval(self, seconds):
    if int(seconds)==1:
        return _v290_aggregate_1s(self,False)
    return _V290_BASE_HISTORY(self,seconds)


def _v290_current_bucket(self, seconds):
    if int(seconds)!=1:
        return _V290_BASE_CURRENT(self,seconds)
    now=time.time(); b=int(now); rows=_v290_aggregate_1s(self,True,now=now,limit=180)
    for r in reversed(rows):
        if int(r.get('time',-1))==b:return dict(r)
    try: px=float(self.effective_live_price()[0] or 0)
    except Exception: px=0.0
    return {'time':b,'open':px,'high':px,'low':px,'close':px,'volume':0.0,'_open_source':'LIVE SEED','_live_source':'LIVE SEED'}


ChartKingPro._history_for_interval = _v290_history_for_interval
ChartKingPro._current_bucket_for_interval = _v290_current_bucket


def _v290_std(vals):
    vals=[float(x) for x in vals if x is not None]
    if len(vals)<2:return 0.0
    m=sum(vals)/len(vals)
    return math.sqrt(sum((x-m)*(x-m) for x in vals)/max(1,len(vals)-1))


def _v290_pivot(rows, idx, strength, high=True):
    if idx-strength<0 or idx+strength>=len(rows):return False
    key='high' if high else 'low';v=float(rows[idx][key])
    for j in range(idx-strength,idx+strength+1):
        if j==idx:continue
        x=float(rows[j][key])
        if (high and x>v) or ((not high) and x<v):return False
    return True


def _v290_breakout_engine(rows, strong=True, norm_len=100, box_len=14, min_channel_bars=10,
                          retest_bars=6, fakeout_bars=4, pivot_len=5):
    """Pure translation/adaptation of the supplied breakout/retest/sweep idea."""
    rows=[dict(r) for r in (rows or []) if all(k in r for k in ('open','high','low','close'))]
    if len(rows)<max(34,box_len+20):
        return {'ready':False,'reason':f'breakout suite building ({len(rows)} bars)'}
    # Keep enough history for stable normalization while bounding work.
    rows=rows[-max(260,norm_len+box_len+80):]
    n=len(rows); norms=[None]*n; vols=[None]*n
    for i in range(n):
        a=max(0,i-norm_len+1); seg=rows[a:i+1]
        lo=min(float(r['low']) for r in seg); hi=max(float(r['high']) for r in seg); rg=max(hi-lo,1e-9)
        norms[i]=(float(rows[i]['close'])-lo)/rg
        if i>=13: vols[i]=_v290_std(norms[i-13:i+1])
    upper=[None]*n;lower=[None]*n
    for i in range(n):
        if i<box_len or vols[i] is None:continue
        window=vols[i-box_len:i+1]
        if any(v is None for v in window):continue
        imax=max(range(len(window)),key=lambda j:window[j]); imin=min(range(len(window)),key=lambda j:window[j])
        off_max=-(len(window)-1-imax); off_min=-(len(window)-1-imin)
        upper[i]=(off_max+box_len)/float(box_len); lower[i]=(off_min+box_len)/float(box_len)
    last_lower_cross=None; active=None; last_break=None
    for i in range(1,n):
        if None in (upper[i],lower[i],upper[i-1],lower[i-1]):continue
        cross_lower=(lower[i]>upper[i] and lower[i-1]<=upper[i-1])
        cross_upper=(upper[i]>lower[i] and upper[i-1]<=lower[i-1])
        if cross_lower:last_lower_cross=i
        # Resolve the currently active channel before creating a new one.
        if active is not None:
            trig=(float(rows[i]['open'])+float(rows[i]['close']))*.5 if strong else float(rows[i]['close'])
            if trig>active['top']:
                last_break={'side':'UP','index':i,'level':active['top'],'bottom':active['bottom'],'height':active['top']-active['bottom']};active=None
            elif trig<active['bottom']:
                last_break={'side':'DOWN','index':i,'level':active['bottom'],'top':active['top'],'height':active['top']-active['bottom']};active=None
        if cross_upper and last_lower_cross is not None:
            duration=i-last_lower_cross
            if duration>min_channel_bars and active is None:
                a=max(0,i-duration+1);seg=rows[a:i+1]
                active={'start':a,'formed':i,'age':duration,'top':max(float(r['high']) for r in seg),
                        'bottom':min(float(r['low']) for r in seg)}
    # If no AlgoAlpha-style active box is currently alive, still publish a
    # bounded watch channel from recent price acceptance. This keeps the
    # "reversal prices" useful intraround without fabricating a breakout event.
    fallback=False
    if active is None:
        # Exclude the newest bar when constructing the fallback watch channel.
        # Otherwise the very breakout candle expands its own boundary and the
        # level chases price instead of behaving like a reversal trigger.
        width=max(min_channel_bars,box_len)
        prior=rows[-(width+1):-1] if len(rows)>width else rows[:-1]
        if not prior: prior=rows[-width:]
        active={'start':n-1-len(prior),'formed':n-2,'age':len(prior),
                'top':max(float(r['high']) for r in prior),'bottom':min(float(r['low']) for r in prior)}
        fallback=True
        # In fallback mode the newest candle can still produce a genuine break
        # of the already-established acceptance range.
        trig=(float(rows[-1]['open'])+float(rows[-1]['close']))*.5 if strong else float(rows[-1]['close'])
        if trig>active['top']:
            last_break={'side':'UP','index':n-1,'level':active['top'],'bottom':active['bottom'],'height':active['top']-active['bottom']}
        elif trig<active['bottom']:
            last_break={'side':'DOWN','index':n-1,'level':active['bottom'],'top':active['top'],'height':active['top']-active['bottom']}
    # ATR-like tolerance from recent true ranges.
    trs=[]
    for i in range(max(1,n-box_len),n):
        prev=float(rows[i-1]['close']);h=float(rows[i]['high']);l=float(rows[i]['low'])
        trs.append(max(h-l,abs(h-prev),abs(l-prev)))
    atr=sum(trs)/len(trs) if trs else max(1.0,active['top']-active['bottom'])
    tol=atr*.18
    bull_retest=bear_retest=bull_fakeout=bear_fakeout=False
    target1=target2=None
    if last_break is not None:
        since=n-1-int(last_break['index']);level=float(last_break['level']);cur=rows[-1]
        if last_break['side']=='UP':
            if 1<=since<=retest_bars and float(cur['low'])<=level+tol and float(cur['low'])>=level-tol and float(cur['close'])>level:bull_retest=True
            if 1<=since<=fakeout_bars and float(cur['close'])<level:bull_fakeout=True
            target1=level+float(last_break['height'])*.50;target2=level+float(last_break['height'])
        else:
            if 1<=since<=retest_bars and float(cur['high'])>=level-tol and float(cur['high'])<=level+tol and float(cur['close'])<level:bear_retest=True
            if 1<=since<=fakeout_bars and float(cur['close'])>level:bear_fakeout=True
            target1=level-float(last_break['height'])*.50;target2=level-float(last_break['height'])
    # Confirmed pivot liquidity levels + sweep/reclaim on the newest candle.
    last_ph=last_pl=None
    for i in range(pivot_len,n-pivot_len):
        if _v290_pivot(rows,i,pivot_len,True):last_ph=(i,float(rows[i]['high']))
        if _v290_pivot(rows,i,pivot_len,False):last_pl=(i,float(rows[i]['low']))
    cur=rows[-1];min_sweep=atr*.03
    buy_sweep=bool(last_ph and n-1-last_ph[0]<=120 and float(cur['high'])>last_ph[1]+min_sweep and float(cur['close'])<last_ph[1])
    sell_sweep=bool(last_pl and n-1-last_pl[0]<=120 and float(cur['low'])<last_pl[1]-min_sweep and float(cur['close'])>last_pl[1])
    # Evidence bias: positive = reversal/continuation toward UP.
    evidence=[];bias=0.0
    if last_break and last_break['side']=='UP':bias+=.12;evidence.append('bull breakout')
    if last_break and last_break['side']=='DOWN':bias-=.12;evidence.append('bear breakdown')
    if bull_retest:bias+=.18;evidence.append('bull retest held')
    if bear_retest:bias-=.18;evidence.append('bear retest held')
    if bull_fakeout:bias-=.25;evidence.append('bull breakout failed / trap')
    if bear_fakeout:bias+=.25;evidence.append('bear breakdown failed / trap')
    if buy_sweep:bias-=.22;evidence.append('buy-side liquidity swept/rejected')
    if sell_sweep:bias+=.22;evidence.append('sell-side liquidity swept/reclaimed')
    bias=max(-1.0,min(1.0,bias))
    return {'ready':True,'bull_break':float(active['top']),'bear_break':float(active['bottom']),
            'channel_height':float(active['top']-active['bottom']),'channel_age':int(active['age']),
            'fallback_channel':fallback,'last_break':last_break,'bull_retest':bull_retest,'bear_retest':bear_retest,
            'bull_fakeout':bull_fakeout,'bear_fakeout':bear_fakeout,'last_pivot_high':last_ph[1] if last_ph else None,
            'last_pivot_low':last_pl[1] if last_pl else None,'buy_side_sweep':buy_sweep,'sell_side_sweep':sell_sweep,
            'target1':target1,'target2':target2,'atr':atr,'bias':bias,'evidence':evidence,
            'reason':(' • '.join(evidence) if evidence else 'active breakout/reversal prices mapped')}


def _v290_breakout_read(self, now=None, force=False):
    now=float(now or time.time());cache=dict(getattr(self,'_v290_breakout_cache',{}) or {})
    if not force and cache and now-float(cache.get('ts',0) or 0)<.45:return cache
    # 1m is deliberate: the supplied script is a 15m breakout suite, but a 15m
    # Kalshi contract needs intraround levels. 1m preserves the same channel /
    # retest / fakeout / sweep semantics at useful decision speed.
    try:rows=list(self._history_for_interval(60) or [])
    except Exception:rows=[]
    try:
        cur=self._current_bucket_for_interval(60)
        if cur and (not rows or int(cur.get('time',-1))!=int(rows[-1].get('time',-2))):rows=rows+[cur]
    except Exception:pass
    out=_v290_breakout_engine(rows);out['ts']=now;out['timeframe']='1m'
    self._v290_breakout_cache=dict(out);return out


ChartKingPro._v290_breakout_read = _v290_breakout_read


def _v290_forecast_read(self, now=None, force=False):
    fc=dict(_V290_BASE_FORECAST(self,now=now,force=force) or {})
    suite=_v290_breakout_read(self,now=now,force=force)
    fc['breakout_suite']=suite
    if not fc.get('ready') or not suite.get('ready'):return fc
    # Structural evidence gets a small capped vote. It cannot override a clear
    # contract trend, 120s thesis, or sticky-lock plan-change rules by itself.
    b=float(suite.get('bias',0) or 0)
    if abs(b)>=.16:
        old=float(fc.get('path_score',0) or 0);fc['path_score']=max(-1.0,min(1.0,.92*old+.08*b))
        fc['path_side']='UP' if fc['path_score']>=.08 else 'DOWN' if fc['path_score']<=-.08 else str(fc.get('path_side','WAIT'))
        fc['reason']=str(fc.get('reason',''))+' • BREAKOUT/REVERSAL LEVELS: '+str(suite.get('reason',''))
    return fc



# Persistent event state on top of the pure channel calculation. This is what
# lets a break on one 1m bar become a HELD RETEST or FAKEOUT several bars later.
_V290_BASE_BREAKOUT_READ = _v290_breakout_read

def _v290_breakout_read_persistent(self, now=None, force=False):
    now=float(now or time.time())
    base=dict(_V290_BASE_BREAKOUT_READ(self,now=now,force=force) or {})
    if not base.get('ready'):return base
    try:
        rows=list(self._history_for_interval(60) or [])
        cur=self._current_bucket_for_interval(60)
        if cur:
            if not rows or int(rows[-1].get('time',-1))!=int(cur.get('time',-2)):rows.append(cur)
            else:rows[-1]=cur
        if not rows:return base
        c=dict(rows[-1]);bt=int(c.get('time',int(now//60)*60));op=float(c['open']);cl=float(c['close']);hi=float(c['high']);lo=float(c['low']);trig=(op+cl)*.5
        st=getattr(self,'_v290_breakout_state',None)
        if not isinstance(st,dict):st={};self._v290_breakout_state=st
        snap=dict(st.get('snapshot') or {})
        prev_trig=snap.get('trigger');prev_up=snap.get('bull_level');prev_dn=snap.get('bear_level')
        # A crossing uses the prior published level so the trigger cannot chase
        # the breakout candle itself.
        if prev_trig is not None and prev_up is not None and float(prev_trig)<=float(prev_up) and trig>float(prev_up):
            st['last_bull']={'level':float(prev_up),'bar_time':bt,'height':max(1e-9,float(base.get('channel_height',0) or 0))}
        if prev_trig is not None and prev_dn is not None and float(prev_trig)>=float(prev_dn) and trig<float(prev_dn):
            st['last_bear']={'level':float(prev_dn),'bar_time':bt,'height':max(1e-9,float(base.get('channel_height',0) or 0))}
        # The pure engine can detect a break on the very first call; persist it
        # so later bars can become retests/fakeouts even without a prior snapshot.
        pure_break=dict(base.get('last_break') or {})
        if str(pure_break.get('side','')).upper()=='UP':
            st['last_bull']={'level':float(pure_break.get('level')),'bar_time':bt,'height':max(1e-9,float(pure_break.get('height',base.get('channel_height',0)) or 0))}
        elif str(pure_break.get('side','')).upper()=='DOWN':
            st['last_bear']={'level':float(pure_break.get('level')),'bar_time':bt,'height':max(1e-9,float(pure_break.get('height',base.get('channel_height',0)) or 0))}
        atr=max(1e-9,float(base.get('atr',1) or 1));tol=atr*.18
        bull_retest=bear_retest=bull_fakeout=bear_fakeout=False
        lb=st.get('last_bull');lr=st.get('last_bear')
        if lb:
            since=max(0,int((bt-int(lb.get('bar_time',bt)))/60));lev=float(lb['level'])
            if 1<=since<=6 and lo<=lev+tol and lo>=lev-tol and cl>lev:bull_retest=True
            if 1<=since<=4 and cl<lev:bull_fakeout=True
        if lr:
            since=max(0,int((bt-int(lr.get('bar_time',bt)))/60));lev=float(lr['level'])
            if 1<=since<=6 and hi>=lev-tol and hi<=lev+tol and cl<lev:bear_retest=True
            if 1<=since<=4 and cl>lev:bear_fakeout=True
        # Merge persistent events with any event the pure engine found.
        base['bull_retest']=bool(base.get('bull_retest') or bull_retest);base['bear_retest']=bool(base.get('bear_retest') or bear_retest)
        base['bull_fakeout']=bool(base.get('bull_fakeout') or bull_fakeout);base['bear_fakeout']=bool(base.get('bear_fakeout') or bear_fakeout)
        ev=list(base.get('evidence') or []);bias=float(base.get('bias',0) or 0)
        def add(txt,delta):
            nonlocal bias
            if txt not in ev:ev.append(txt);bias+=delta
        if bull_retest:add('bull retest held',.18)
        if bear_retest:add('bear retest held',-.18)
        if bull_fakeout:add('bull breakout failed / trap',-.25)
        if bear_fakeout:add('bear breakdown failed / trap',.25)
        base['evidence']=ev;base['bias']=max(-1.0,min(1.0,bias));base['reason']=' • '.join(ev) if ev else base.get('reason','active breakout/reversal prices mapped')
        # Persist levels and current trigger for the next intrabar/bar transition.
        st['snapshot']={'bar_time':bt,'trigger':trig,'bull_level':float(base.get('bull_break')),'bear_level':float(base.get('bear_break'))}
        # Measured targets from the last persistent breakout are kept visible.
        if lb and (base.get('last_break') is None or str((base.get('last_break') or {}).get('side'))!='UP'):
            lev=float(lb['level']);h=float(lb.get('height',0) or 0)
            if bt-int(lb.get('bar_time',bt))<=6*60:
                base['persistent_bull_break']=dict(lb)
        if lr and (base.get('last_break') is None or str((base.get('last_break') or {}).get('side'))!='DOWN'):
            lev=float(lr['level']);h=float(lr.get('height',0) or 0)
            if bt-int(lr.get('bar_time',bt))<=6*60:
                base['persistent_bear_break']=dict(lr)
        self._v290_breakout_cache=dict(base)
    except Exception:pass
    return base

_v290_breakout_read = _v290_breakout_read_persistent
ChartKingPro._v290_breakout_read = _v290_breakout_read_persistent

_v272_forecast_read = _v290_forecast_read
ChartKingPro._v272_forecast_read = _v290_forecast_read


def _v290_draw_breakout_overlay(self):
    try:
        c=self.canvas;c.delete('v290_levels');suite=_v290_breakout_read(self)
        if not suite.get('ready'):return
        sc=dict(getattr(self,'_v82_chart_scale',{}) or {})
        lo=float(sc.get('lo'));hi=float(sc.get('hi'));top=float(sc.get('top'));ph=float(sc.get('ph'));left=float(sc.get('left'));right=float(sc.get('plot_right'))
        if hi<=lo:return
        def yy(p):return top+(hi-float(p))/(hi-lo)*ph
        def line(price,color,text,dash=(6,4),width=2):
            if price is None or float(price)<lo or float(price)>hi:return
            y=yy(price);c.create_line(left,y,right,y,fill=color,dash=dash,width=width,tags='v290_levels')
            c.create_text(right-5,y-9,text=text,fill=color,anchor='e',font=('Cascadia Mono',7,'bold'),tags='v290_levels')
        line(suite.get('bull_break'),'#00e6a8',f'BULL REVERSAL / BREAK > {float(suite["bull_break"]):,.2f}')
        line(suite.get('bear_break'),'#ff5b72',f'BEAR REVERSAL / BREAK < {float(suite["bear_break"]):,.2f}')
        line(suite.get('last_pivot_high'),'#4da3ff',f'BUY-SIDE LIQ {float(suite["last_pivot_high"]):,.2f}',(2,5),1)
        line(suite.get('last_pivot_low'),'#4da3ff',f'SELL-SIDE LIQ {float(suite["last_pivot_low"]):,.2f}',(2,5),1)
        lb=suite.get('last_break') or {}
        side=str(lb.get('side',''))
        if side and suite.get('target1') is not None:
            col='#00b989' if side=='UP' else '#d9485f'
            line(suite.get('target1'),col,f'{side} TARGET 1 {float(suite["target1"]):,.2f}',(4,5),1)
            line(suite.get('target2'),col,f'{side} TARGET 2 {float(suite["target2"]):,.2f}',(7,4),1)
    except Exception:pass


def _v290_draw_chart(self,*args,**kwargs):
    """Coalesce legacy full-redraw callers; live candle motion remains 60 FPS."""
    if bool(getattr(self,'_v290_draw_busy',False)):return None
    now=time.perf_counter()
    try:key=(str(self.chart_tf_var.get()),int(self.canvas.winfo_width()),int(self.canvas.winfo_height()),int(getattr(self,'visible_count',0) or 0))
    except Exception:key=None
    last=float(getattr(self,'_v290_last_full_draw',0.0) or 0.0);last_key=getattr(self,'_v290_last_draw_key',None)
    force=(key!=last_key or getattr(self,'_last_chart_render_key',None) is None)
    # Adaptive static-geometry cadence. The live candle/price overlay has its own
    # 60 FPS lane; a 50-80ms full redraw must never steal that frame budget 4-10x/s.
    ema=float(getattr(self,'_v290_draw_ema_ms',0.0) or 0.0)
    min_gap=.22 if ema<=14 else .34 if ema<=24 else .50 if ema<=40 else .72
    if (not force) and now-last<min_gap:
        self._v290_draw_coalesced=int(getattr(self,'_v290_draw_coalesced',0) or 0)+1
        return None
    self._v290_draw_busy=True;start=time.perf_counter()
    try:
        r=_V290_BASE_DRAW(self,*args,**kwargs)
        self._v290_last_full_draw=time.perf_counter();self._v290_last_draw_key=key
        _v290_draw_breakout_overlay(self)
        return r
    finally:
        ms=(time.perf_counter()-start)*1000.0;old=float(getattr(self,'_v290_draw_ema_ms',0) or 0)
        self._v290_draw_ema_ms=ms if old<=0 else old*.9+ms*.1
        self._v290_draw_busy=False


ChartKingPro.draw_chart = _v290_draw_chart


