        if getattr(self,'v292_cushion_var',None) is None:
            self.v292_cushion_var=tk.StringVar(value='TARGET CUSHION: mapping distance / volatility / hold probability...')
            tk.Label(strip,textvariable=self.v292_cushion_var,bg='#071521',fg='#6ee7ff',font=('Cascadia Mono',7,'bold'),anchor='w').pack(fill='x',pady=(1,0))
