def _v292_status_tick(self):
    try:
        _v292_mount_status(self)
        try:fc=dict(_v272_forecast_read(self,force=False) or {})
        except Exception:fc={}
        tc=dict(fc.get('target_cushion') or _v292_target_cushion_read(self,fc=fc,force=False) or {})
        if getattr(self,'v292_cushion_var',None) is not None:
            if not tc.get('ready'):
                txt='TARGET CUSHION: '+str(tc.get('reason','building'))
            else:
                d=float(tc.get('distance',0) or 0);direction='ABOVE' if d>0 else 'BELOW' if d<0 else 'AT'
                hold=float(tc.get('hold_prob',.5))*100
                txt=(f'TARGET CUSHION • {abs(d):.0f}$ {direction} • HOLD {hold:.0f}% • {tc.get("status","WAIT")} • '
                     f'{float(tc.get("distance_sigma",0) or 0):.2f}× REMAINING MOVE • {float(tc.get("seconds_left",0) or 0):.0f}s LEFT')
            if self.v292_cushion_var.get()!=txt:self.v292_cushion_var.set(txt)
    except Exception:pass
    finally:
        try:self.root.after(400,lambda s=self:_v292_status_tick(s))
        except Exception:pass


