# ============================================================================
# LECHART JAMES V21.93 — EXACT ALGOALPHA MOMENTUM BIAS INDEX + MORE CHART ROOM
#
# Momentum Bias Index translation/adaptation from the user-supplied
# "Momentum Bias Index [AlgoAlpha]" Pine Script (MPL-2.0).
# Original indicator: © AlgoAlpha, Mozilla Public License 2.0.
#
# This layer intentionally replaces V21.91's approximate MBI math with the
# supplied indicator's actual calculation:
#   momentum = close - close[10]
#   normalized momentum = momentum / EMA(high-low, 10) * 100
#   positive/negative momentum bias = HMA(sum(side, 5), 10)
#   impulse boundary = EMA(avg bias, 30) + stdev(avg bias, 30) * 3.0
#   rollover signal = dominant bias turns down while above impulse boundary
#
# Decision authority remains conservative: exact MBI is structural/momentum
# context. It cannot single-handedly choose or flip MAIN LOCK.
# ============================================================================
_V293_RELEASE = 'V21.93 EXACT ALGOALPHA MBI • COMPACT CHART'
_V293_BASE_INIT = ChartKingPro.__init__
_V293_MOMENTUM_LEN = 10
_V293_BIAS_LEN = 5
_V293_SMOOTH_LEN = 10
_V293_BOUNDARY_LEN = 30
_V293_STD_MULT = 3.0


def _v293_ema_series(vals, n):
    n=max(1,int(n));a=2.0/(n+1.0);out=[];last=None
    for v in vals:
        if v is None or not math.isfinite(float(v)):
            out.append(None);continue
        v=float(v)
        last=v if last is None else last+a*(v-last)
        out.append(last)
    return out


def _v293_wma_at(vals, i, n):
    n=max(1,int(n))
    if i-n+1<0:return None
    seg=vals[i-n+1:i+1]
    if len(seg)!=n or any(v is None for v in seg):return None
    den=n*(n+1)/2.0
    return sum((j+1)*float(v) for j,v in enumerate(seg))/den


def _v293_hma_series(vals, n):
    n=max(1,int(n));half=max(1,int(round(n/2.0)));root=max(1,int(round(math.sqrt(n))))
    diff=[None]*len(vals)
    for i in range(len(vals)):
        a=_v293_wma_at(vals,i,half);b=_v293_wma_at(vals,i,n)
        if a is not None and b is not None:diff[i]=2.0*a-b
    out=[None]*len(vals)
    for i in range(len(vals)):out[i]=_v293_wma_at(diff,i,root)
    return out


def _v293_roll_sum(vals, n):
    n=max(1,int(n));out=[None]*len(vals)
    for i in range(n-1,len(vals)):
        seg=vals[i-n+1:i+1]
        if any(v is None for v in seg):continue
        out[i]=sum(float(v) for v in seg)
    return out


def _v293_roll_stdev(vals, n):
    # Pine ta.stdev defaults to biased=True, i.e. population standard deviation.
    n=max(1,int(n));out=[None]*len(vals)
    for i in range(n-1,len(vals)):
        seg=vals[i-n+1:i+1]
        if any(v is None for v in seg):continue
        seg=[float(v) for v in seg];m=sum(seg)/n
        out[i]=math.sqrt(sum((x-m)*(x-m) for x in seg)/n)
    return out


def _v293_exact_mbi_from_rows(rows):
    """Direct Python translation of the supplied AlgoAlpha MBI defaults."""
    rs=[]
    for r0 in list(rows or []):
        try:
            r=dict(r0);o=float(r['open']);h=float(r['high']);l=float(r['low']);c=float(r['close'])
            if not all(math.isfinite(x) for x in (o,h,l,c)):continue
            rs.append({'time':float(r.get('time',0) or 0),'open':o,'high':h,'low':l,'close':c})
        except Exception:pass
    # Need enough bars for momentum + HMA + 30-bar boundary.
    if len(rs)<58:
        return {'ready':False,'reason':f'exact MBI building ({len(rs)}/58 1m bars)','series':[],
                'source_model':'AlgoAlpha exact defaults'}
    closes=[r['close'] for r in rs]
    ranges=[max(1e-9,r['high']-r['low']) for r in rs]
    range_ema=_v293_ema_series(ranges,_V293_MOMENTUM_LEN)
    momentum=[None]*len(rs);norm=[None]*len(rs);up=[None]*len(rs);down=[None]*len(rs)
    for i in range(len(rs)):
        if i<_V293_MOMENTUM_LEN:continue
        m=closes[i]-closes[i-_V293_MOMENTUM_LEN];den=range_ema[i]
        if den is None or abs(float(den))<1e-12:continue
        sd=m/float(den)*100.0
        momentum[i]=m;norm[i]=sd;up[i]=max(sd,0.0);down[i]=min(sd,0.0)
    up_sum=_v293_roll_sum(up,_V293_BIAS_LEN)
    down_abs=[None if v is None else -float(v) for v in down]
    down_sum=_v293_roll_sum(down_abs,_V293_BIAS_LEN)
    up_hma=_v293_hma_series(up_sum,_V293_SMOOTH_LEN)
    down_hma=_v293_hma_series(down_sum,_V293_SMOOTH_LEN)
    up_bias=[None if v is None else max(float(v),0.0) for v in up_hma]
    down_bias=[None if v is None else max(float(v),0.0) for v in down_hma]
    avg=[None if (u is None or d is None) else .5*(float(u)+float(d)) for u,d in zip(up_bias,down_bias)]
    avg_ema=_v293_ema_series(avg,_V293_BOUNDARY_LEN)
    avg_sd=_v293_roll_stdev(avg,_V293_BOUNDARY_LEN)
    boundary=[None if (e is None or s is None) else float(e)+float(s)*_V293_STD_MULT for e,s in zip(avg_ema,avg_sd)]

    series=[];bull_signal=False;bear_signal=False
    for i,r in enumerate(rs):
        u=up_bias[i];d=down_bias[i];b=boundary[i]
        bull=bear=False
        # Pine: ta.crossunder(bias, bias[1]) => current < previous AND previous >= two-bars-back.
        if i>=2 and u is not None and d is not None and b is not None:
            d1=down_bias[i-1];d2=down_bias[i-2];u1=up_bias[i-1];u2=up_bias[i-2]
            if d1 is not None and d2 is not None:
                bull=(d<d1 and d1>=d2 and d>b and d>u)
            if u1 is not None and u2 is not None:
                bear=(u<u1 and u1>=u2 and u>b and u>d)
        bull_signal=bull_signal or (bull and i==len(rs)-1)
        bear_signal=bear_signal or (bear and i==len(rs)-1)
        series.append({'time':r['time'],'up_bias':u,'down_bias':d,'boundary':b,
                       'bullish_signal':bool(bull),'bearish_signal':bool(bear),'close':r['close']})

    valid=[x for x in series if x['up_bias'] is not None and x['down_bias'] is not None]
    if not valid:return {'ready':False,'reason':'exact MBI waiting for smoothed bias','series':series}
    cur=valid[-1];u=float(cur['up_bias']);d=float(cur['down_bias']);bd=float(cur['boundary'] or 0.0)
    dom=max(u,d,1e-9);diff=(u-d)/dom
    bias_side='UP' if u>d*1.03 else 'DOWN' if d>u*1.03 else 'NEUTRAL'
    state='STEADY';shift='WAIT';conf=0.0
    if bool(cur.get('bullish_signal')):
        state='SHIFT WATCH';shift='UP';conf=min(99.0,68.0+18.0*min(1.0,d/max(bd,1e-9)-1.0)+12.0*min(1.0,(d-u)/max(d,1e-9)))
    elif bool(cur.get('bearish_signal')):
        state='SHIFT WATCH';shift='DOWN';conf=min(99.0,68.0+18.0*min(1.0,u/max(bd,1e-9)-1.0)+12.0*min(1.0,(u-d)/max(u,1e-9)))
    # Bot vote: source indicator has no contract-side output. Use normalized bias
    # only as a small momentum family; exact TP/X signal points toward the rollover side.
    fwd=max(-.72,min(.72,diff*.72))
    if shift=='UP':fwd=max(fwd,.55+.003*conf)
    elif shift=='DOWN':fwd=min(fwd,-(.55+.003*conf))
    return {'ready':True,'series':series,'score':round(diff*100.0,2),'up_bias':round(u,4),'down_bias':round(d,4),
            'boundary':round(bd,4),'bias_side':bias_side,'state':state,'shift_to':shift,
            'shift_confidence':round(conf,1),'forward_score':max(-.85,min(.85,fwd)),
            'bullish_signal':bool(cur.get('bullish_signal')),'bearish_signal':bool(cur.get('bearish_signal')),
            'reason':f'EXACT MBI • UP {u:.1f} • DOWN {d:.1f} • boundary {bd:.1f}',
            'source_model':'AlgoAlpha exact defaults 10/5/10/30 3σ'}


def _v291_momentum_read(self,now=None,force=False):
    """Canonical exact AlgoAlpha MBI on native 1-minute Bookmap candles."""
    now=float(now or time.time());cache=dict(getattr(self,'_v293_mbi_cache',{}) or {})
    if (not force) and cache and now-float(cache.get('ts',0) or 0)<.18:return dict(cache)
    try:rows=list(self._history_for_interval(60) or [])[-180:]
    except Exception:rows=[]
    out=dict(_v293_exact_mbi_from_rows(rows) or {});out['ts']=now;out['timeframe']='1m'
    self._v293_mbi_cache=dict(out);self._v291_mbi_cache=dict(out)
    return out


ChartKingPro._v291_momentum_read=_v291_momentum_read


def _v293_hex_mix(a,b,t):
    try:
        a=a.lstrip('#');b=b.lstrip('#');t=max(0.0,min(1.0,float(t)))
        aa=[int(a[i:i+2],16) for i in (0,2,4)];bb=[int(b[i:i+2],16) for i in (0,2,4)]
        cc=[round(x+(y-x)*t) for x,y in zip(aa,bb)]
        return '#'+''.join(f'{max(0,min(255,c)):02x}' for c in cc)
    except Exception:return '#888888'


def _v291_mount_panel(app):
    """Compact exact-MBI pane. Faithful math/turn markers, less chart-height cost."""
    try:
        old=getattr(app,'v291_mbi_frame',None)
        if old is not None and old.winfo_exists():return True
        c=getattr(app,'canvas',None)
        if c is None or not c.winfo_exists():return False
        parent=c.master;info=c.grid_info()
        if not info:return False
        crow=int(info.get('row',2));newrow=crow+1
        for ch in list(parent.grid_slaves()):
            if ch is c:continue
            try:
                gi=ch.grid_info();r=int(gi.get('row',-1))
                if r>=newrow:ch.grid_configure(row=r+1)
            except Exception:pass
        parent.grid_rowconfigure(crow,weight=1)
        parent.grid_rowconfigure(newrow,weight=0,minsize=72)
        f=tk.Frame(parent,bg='#05080d',highlightthickness=1,highlightbackground='#1b2939')
        f.grid(row=newrow,column=0,sticky='ew',padx=5,pady=(1,2))
        app.v291_mbi_frame=f
        head=tk.Frame(f,bg='#05080d',height=17);head.pack(fill='x',padx=5,pady=(2,0))
        app.v291_mbi_title_var=tk.StringVar(value='MOMENTUM BIAS INDEX [ALGOALPHA] • EXACT 1m • 10/5/10/30 • 3σ')
        app.v291_mbi_alert_var=tk.StringVar(value='BUILDING EXACT MOMENTUM BIAS...')
        tk.Label(head,textvariable=app.v291_mbi_title_var,bg='#05080d',fg='#9eacbd',font=('Cascadia Mono',6,'bold')).pack(side='left')
        tk.Label(head,textvariable=app.v291_mbi_alert_var,bg='#05080d',fg='#f6c85f',font=('Cascadia Mono',7,'bold')).pack(side='right')
        cv=tk.Canvas(f,bg='#030609',height=50,highlightthickness=0,bd=0);cv.pack(fill='x',expand=False,padx=3,pady=(1,2))
        app.v291_mbi_canvas=cv;app.v291_mbi_layers=[];app.v291_mbi_marks=[];app.v293_mbi_boundary_dots=[]
        # 48 time slots × five reusable gradient layers. No create/delete churn.
        for _ in range(48):
            layers=[cv.create_rectangle(0,0,0,0,fill='#00ffbb',outline='') for __ in range(5)]
            app.v291_mbi_layers.append(layers)
            app.v291_mbi_marks.append(cv.create_text(0,0,text='',fill='#ffffff',font=('Cascadia Mono',7,'bold')))
            app.v293_mbi_boundary_dots.append(cv.create_oval(0,0,0,0,fill='#738094',outline=''))
        app.v291_mbi_zero=cv.create_line(0,0,0,0,fill='#344050',width=1)
        app.v291_mbi_status=cv.create_text(5,4,text='',anchor='nw',fill='#7f8ea2',font=('Cascadia Mono',6,'bold'))
        app.v291_mbi_curve=None
        app.v291_mbi_bars=[]
        app.v291_mbi_last_alert=''
        return True
    except Exception:return False


def _v293_hide_layers(app):
    try:
        cv=app.v291_mbi_canvas
        for layers in app.v291_mbi_layers:
            for it in layers:cv.coords(it,0,0,0,0)
        for it in app.v291_mbi_marks:cv.itemconfigure(it,text='')
        for it in app.v293_mbi_boundary_dots:cv.coords(it,0,0,0,0)
    except Exception:pass


def _v291_draw_panel(app,mbi):
    """Render the supplied Pine indicator's column/decay/X/boundary behavior."""
    try:
        if not _v291_mount_panel(app):return
        cv=app.v291_mbi_canvas;w=max(260,int(cv.winfo_width() or 0));h=max(46,int(cv.winfo_height() or 50))
        baseline=h-5;top=13;cv.coords(app.v291_mbi_zero,0,baseline,w,baseline)
        _v293_hide_layers(app)
        ser=[x for x in list((mbi or {}).get('series') or []) if x.get('up_bias') is not None and x.get('down_bias') is not None][-48:]
        if not ser:
            cv.itemconfigure(app.v291_mbi_status,text='exact MBI waiting for 1m history');return
        mx=max([float(x.get('up_bias',0) or 0) for x in ser]+[float(x.get('down_bias',0) or 0) for x in ser]+[float(x.get('boundary',0) or 0) for x in ser]+[1.0])
        usable=max(10.0,baseline-top);bw=max(2.0,(w-8)/48.0);start=48-len(ser)
        green='#00ffbb';green2='#008461';red='#ff1100';red2='#840900'
        for j,p in enumerate(ser):
            i=start+j;x0=4+i*bw;x1=x0+max(1.0,bw-1.0)
            u=float(p.get('up_bias',0) or 0);d=float(p.get('down_bias',0) or 0);bd=float(p.get('boundary',0) or 0)
            prev=ser[j-1] if j else p;pu=float(prev.get('up_bias',u) or u);pd=float(prev.get('down_bias',d) or d)
            # Pine draws both positive bias series; draw the dominant one last, matching visible result.
            candidates=[('UP',u,pu),('DOWN',d,pd)];candidates.sort(key=lambda z:z[1])
            for side,val,pval in candidates:
                if val<=0:continue
                layers=app.v291_mbi_layers[i];basecol=green if side=='UP' else red;secondary=green2 if side=='UP' else red2
                y=baseline-(val/mx)*usable
                rising=val>pval
                if rising:
                    cv.coords(layers[0],x0,y,x1,baseline);cv.itemconfigure(layers[0],fill=basecol)
                else:
                    # Faithful visual analogue to Pine's 100/80/60/40/20% layered fading columns.
                    fracs=(1.0,.80,.60,.40,.20)
                    cols=(_v293_hex_mix('#030609',secondary,.40),_v293_hex_mix('#030609',secondary,.52),
                          _v293_hex_mix('#030609',secondary,.66),_v293_hex_mix('#030609',secondary,.78),
                          _v293_hex_mix('#030609',basecol,.84))
                    for k,(fr,col) in enumerate(zip(fracs,cols)):
                        yy=baseline-(val*fr/mx)*usable
                        cv.coords(layers[k],x0,yy,x1,baseline);cv.itemconfigure(layers[k],fill=col)
            if bd>0:
                by=baseline-(bd/mx)*usable;r=1.4;cx=(x0+x1)/2
                cv.coords(app.v293_mbi_boundary_dots[i],cx-r,by-r,cx+r,by+r)
            bull=bool(p.get('bullish_signal'));bear=bool(p.get('bearish_signal'))
            if bull or bear:
                val=d if bull else u;y=baseline-(val/mx)*usable;cx=(x0+x1)/2
                cv.coords(app.v291_mbi_marks[i],cx,max(top,min(baseline-2,y-6)))
                cv.itemconfigure(app.v291_mbi_marks[i],text='X',fill=green if bull else red)
        up=float(mbi.get('up_bias',0) or 0);down=float(mbi.get('down_bias',0) or 0);bd=float(mbi.get('boundary',0) or 0)
        cv.itemconfigure(app.v291_mbi_status,text=f'UP BIAS {up:.1f} • DOWN BIAS {down:.1f} • IMPULSE BOUNDARY {bd:.1f}')
        state=str(mbi.get('state','STEADY'));to=str(mbi.get('shift_to','WAIT'));conf=float(mbi.get('shift_confidence',0) or 0)
        if state=='SHIFT WATCH' and to in ('UP','DOWN'):
            # This is the exact source's X / TP rollover condition.
            app.v291_mbi_alert_var.set(f'X • MOMENTUM ROLLOVER → {to} • {conf:.0f}/100')
            key=f'{to}:{int(time.time()//60)}'
            if key!=getattr(app,'v291_mbi_last_alert',''):
                app.v291_mbi_last_alert=key
                try:app.root.bell();app.root.after(130,app.root.bell)
                except Exception:pass
        else:
            app.v291_mbi_alert_var.set(f'{str(mbi.get("bias_side","NEUTRAL"))} BIAS • EXACT SOURCE LOGIC')
    except Exception:pass


