_V294_BASE_MBI_TICK=_v291_tick

def _v291_tick(self):
    try:
        now=time.perf_counter();last=float(getattr(self,'_v294_mbi_last',0.0) or 0.0);due=last+_V294_MBI_PERIOD
        pending=getattr(self,'_v294_mbi_after',None)
        if now+0.0005<due:
            if pending is None:
                ms=max(1,int(math.ceil((due-now)*1000.0)))
                self._v294_mbi_after=self.root.after(ms,lambda s=self:_v294_mbi_due(s))
            return None
        self._v294_mbi_after=None
        if bool(getattr(self,'_v294_mbi_running',False)):return None
        self._v294_mbi_running=True;self._v294_mbi_last=now
        self._v294_mbi_runs=int(getattr(self,'_v294_mbi_runs',0) or 0)+1
        return _V294_BASE_MBI_TICK(self)
    except Exception:return None
    finally:
        try:self._v294_mbi_running=False
        except Exception:pass


def _v294_mbi_due(self):
    try:self._v294_mbi_after=None
    except Exception:pass
    return _v291_tick(self)

# ---------------------------------------------------------------------------
# 6) Root resize: only touch layout after a genuine root size change, and debounce
#    at 140ms so text changes cannot cause a resize/configure feedback loop.
# ---------------------------------------------------------------------------
def _v274_resize_enforcer(self,event=None):
    try:
        if event is not None and getattr(event,'widget',None) is not self.root:return
        wh=(int(self.root.winfo_width() or 0),int(self.root.winfo_height() or 0))
        if wh==getattr(self,'_v294_root_wh',None):return
        self._v294_root_wh=wh
        pending=getattr(self,'_v274_resize_after',None)
        if pending:
            try:self.root.after_cancel(pending)
            except Exception:pass
        self._v274_resize_after=self.root.after(140,lambda s=self:_v274_force_real_cockpit_layout(s))
    except Exception:pass

