def _v294_perf_tick(self):
    try:
        now=time.perf_counter();last=float(getattr(self,'_v294_perf_t',0.0) or 0.0)
        frames=int(getattr(self,'_v271_frames_painted',0) or 0);panels=int(getattr(self,'_v294_panel_runs',0) or 0)
        if last>0:
            dt=max(.001,now-last)
            fps=(frames-int(getattr(self,'_v294_perf_frames',frames) or frames))/dt
            phz=(panels-int(getattr(self,'_v294_perf_panels',panels) or panels))/dt
            f0=float(getattr(self,'_v294_measured_chart_fps',fps) or fps);p0=float(getattr(self,'_v294_measured_panel_hz',phz) or phz)
            self._v294_measured_chart_fps=f0*.62+fps*.38;self._v294_measured_panel_hz=p0*.62+phz*.38
            text=(f'CHART {self._v294_measured_chart_fps:.0f}/60 FPS  •  PANELS {self._v294_measured_panel_hz:.0f}/12 Hz  •  '
                  f'STATIC {float(getattr(self,"_v273_structure_hz_effective",0) or 0):.1f} Hz  •  CALM UI')
            try:
                if self.v274_perf_var.get()!=text:self.v274_perf_var.set(text)
                self.v274_perf_badge.lift()
            except Exception:pass
        self._v294_perf_t=now;self._v294_perf_frames=frames;self._v294_perf_panels=panels
    except Exception:pass
    finally:
        try:self.root.after(750,lambda s=self:_v294_perf_tick(s))
        except Exception:pass

