        self._v295_canvas_resize_after=None;self._v295_static_last=0.0;self._v295_static_key_cache=None;self._v295_last_full_draw=0.0;self._v295_last_draw_key=None;self._v295_draw_after=None;self._v295_draw_running=False;self._v295_force_draw=False;self._v295_full_draw_count=0
        # Replace inherited Canvas configure callback instead of adding another.
