def _v297_flip_from_inputs(old_risk, lock_side, rev, fc, mbi=None, switched=False):
    """Pure meter fusion; UI only. It does NOT alter MAIN LOCK authority."""
    try:risk=max(0.0,min(100.0,float(old_risk or 0.0)))
    except Exception:risk=0.0
    lock=str(lock_side or 'WAIT').upper()
    rev=dict(rev or {});fc=dict(fc or {});mbi=dict(mbi or {})
    stage=str(rev.get('stage','NONE')).upper();rside=str(rev.get('side','WAIT')).upper()
    rscore=max(0.0,min(100.0,float(rev.get('score',0) or 0)))
    opposite='DOWN' if lock=='UP' else 'UP' if lock=='DOWN' else 'WAIT'
    flip_side='WAIT';label='NO REVERSAL SIGNAL'

    if switched and lock in ('UP','DOWN'):
        return {'risk':100.0,'side':lock,'state':'MAIN LOCK SWITCHED','confirmed':True}

    # Modern candle/flow reversal engine is the strongest visual authority.
    if stage=='CONFIRMED' and rside in ('UP','DOWN') and (lock not in ('UP','DOWN') or rside==opposite):
        return {'risk':100.0,'side':rside,'state':f'FULL REVERSAL CONFIRMED → {rside}','confirmed':True}
    if stage=='BUILDING' and rside in ('UP','DOWN') and (lock not in ('UP','DOWN') or rside==opposite):
        risk=max(risk,min(94.0,52.0+0.48*rscore));flip_side=rside
        label=f'REVERSAL BUILDING → {rside}'

    # Structural fallback: catches a full rotation even if the exhaustion setup
    # began before James had enough bars to observe the original impulse.
    if lock in ('UP','DOWN') and fc.get('ready'):
        conf=float(fc.get('confidence',50) or 50);settle=str(fc.get('settlement_side','WAIT')).upper();path=str(fc.get('path_side','WAIT')).upper()
        pscore=float(fc.get('path_score',0) or 0);trend=dict(fc.get('trend') or {});tside=str(trend.get('side','NEUTRAL')).upper();read=float(trend.get('readability',0) or 0)
        opp_settle=(settle==opposite and conf>=68)
        opp_path=(path==opposite and abs(pscore)>=.10)
        opp_trend=(tside==opposite and read>=.25)
        mbi_to=str(mbi.get('shift_to','WAIT')).upper();mbi_bias=str(mbi.get('bias_side','NEUTRAL')).upper();mbi_opp=(mbi_to==opposite or mbi_bias==opposite)
        breadth=sum(1 for x in (opp_settle,opp_path,opp_trend,mbi_opp) if x)
        if opp_settle and opp_path and breadth>=3 and conf>=72:
            risk=max(risk,97.0);flip_side=opposite;label=f'FULL STRUCTURAL REVERSAL → {opposite}'
            if stage=='CONFIRMED' and rside==opposite:risk=100.0
        elif opp_settle and (opp_path or opp_trend or mbi_opp):
            risk=max(risk,min(92.0,54.0+(conf-50.0)*1.15+8.0*max(0,breadth-1)));flip_side=opposite
            if label=='NO REVERSAL SIGNAL':label=f'FLIP BUILDING → {opposite}'

    if flip_side=='WAIT' and risk>=45:
        label='THESIS PRESSURE / BREAKOUT RISK'
    elif flip_side=='WAIT' and risk>=15:
        label='EARLY PRESSURE'
    return {'risk':max(0.0,min(100.0,risk)),'side':flip_side,'state':label,'confirmed':risk>=97.0}


def _v297_flip_meter_items(canvas):
    try:
        st=getattr(canvas,'_v297_flip_items',None)
        if isinstance(st,dict):return st
        canvas.delete('all')
        items=[canvas.create_rectangle(0,0,0,0,fill='#142230',outline='#263849') for _ in range(10)]
        st={'items':items,'last':None,'size':None,'side':None,'confirmed':None}
        canvas._v297_flip_items=st
        return st
    except Exception:return None


def _v297_draw_flip_meter(canvas,value,side='WAIT',confirmed=False):
    try:
        st=_v297_flip_meter_items(canvas)
        if not st:return
        w=max(60,int(canvas.winfo_width() or 60));h=max(14,int(canvas.winfo_height() or 14));v=max(0.0,min(100.0,float(value)))
        active=int(math.ceil(v/10.0-1e-9)) if v>0 else 0
        side=str(side or 'WAIT').upper();col=_v297_color_for_side(side,_V2676_RED if v>=45 else _V2676_GOLD)
        if confirmed:col='#ffffff' if int(time.time()*3)%2==0 else _v297_color_for_side(side,_V2676_RED)
        key=(w,h,active,side,bool(confirmed),col)
        if st.get('last')==key:return
        gap=3;bw=max(3,(w-gap*9)/10.0)
        for i,item in enumerate(st['items']):
            x1=i*(bw+gap);x2=x1+bw;canvas.coords(item,x1,2,x2,h-2)
            canvas.itemconfigure(item,fill=col if i<active else '#142230',outline=col if (confirmed and i<active) else '#263849')
        st['last']=key
    except Exception:pass


def _v297_priority_refresh(app):
    try:
        now=time.time(); snap=dict(getattr(app,'opening_lock_snapshot',{}) or {}); lk=dict(getattr(app,'_v272_last_lock',{}) or {})
        side=str(snap.get('lock_side',lk.get('side','WAIT')) or 'WAIT').upper();strength=float(snap.get('strength',lk.get('strength',0)) or 0)
        status=str(lk.get('status','LOCKED' if side in ('UP','DOWN') else 'THINKING')).upper()
        fc=dict(lk.get('forecast') or getattr(app,'_v272_last_forecast',{}) or {})
        if not fc.get('ready'):
            try:fc=dict(_v272_forecast_read(app,now=now) or {})
            except Exception:fc={}
        path=str(fc.get('path_side','WAIT')).upper();settle=str(fc.get('settlement_side','WAIT')).upper();conf=float(fc.get('confidence',50) or 50)

        # LOCK presentation is intentionally short and impossible to clip.
        if side in ('UP','DOWN'):
            app.v297_lock_var.set(side)
            app.v297_lock_label.configure(fg=_v297_color_for_side(side))
            app.v297_lock_card.configure(highlightbackground=_v297_color_for_side(side))
            app.v297_lock_meta_var.set(f'{status} • {strength:.0f}/100 • PATH {path} • projected {settle} {conf:.0f}/100')
        else:
            app.v297_lock_var.set('WAIT')
            app.v297_lock_label.configure(fg=_V2676_CYAN);app.v297_lock_card.configure(highlightbackground=_V2676_CYAN)
            app.v297_lock_meta_var.set(f'{status} • studying 15m path • projected {settle} {conf:.0f}/100')

        # Detect an actual MAIN LOCK side switch and latch the visible meter.
        prev=str(getattr(app,'_v297_prev_lock_side','WAIT') or 'WAIT').upper()
        switched=(prev in ('UP','DOWN') and side in ('UP','DOWN') and prev!=side)
        if switched:
            app._v297_flip_latch_until=now+8.0;app._v297_flip_latch_side=side
        if side in ('UP','DOWN'):app._v297_prev_lock_side=side

        try:rev=dict(_v286_reversal_sequence_read(app,now=now) or {})
        except Exception:rev={}
        try:mbi=dict(_v291_momentum_read(app,now=now) or {})
        except Exception:mbi={}
        fr=_v297_flip_from_inputs(getattr(app,'trend_reversal_risk_value',0.0),side,rev,fc,mbi,switched=switched)
        if now<float(getattr(app,'_v297_flip_latch_until',0.0) or 0.0):
            fr={'risk':100.0,'side':str(getattr(app,'_v297_flip_latch_side',side) or side),'state':'MAIN LOCK SWITCHED • FULL REVERSAL','confirmed':True}
        risk=float(fr.get('risk',0) or 0);fside=str(fr.get('side','WAIT')).upper();state=str(fr.get('state','NO REVERSAL SIGNAL'))
        app._v297_flip_state=dict(fr)
        app.v297_flip_var.set(f'{risk:.0f}%')
        app.v297_flip_meta_var.set(state)
        col=_v297_color_for_side(fside,_V2676_RED if risk>=45 else _V2676_MUTED)
        app.v297_flip_label.configure(fg=col)
        app.v297_flip_card.configure(highlightbackground=('#ffffff' if fr.get('confirmed') else col if risk>=45 else _V2676_BORDER))
        _v297_draw_flip_meter(app.v297_flip_canvas,risk,fside,bool(fr.get('confirmed')))
    except Exception:
        pass


