# 60 Hz deadline stays alive, but blind Canvas writes do not.  A frame is painted
# when a new Bookmap visual sequence arrived, plus a 10 Hz heartbeat so the price
# marker never looks stale. This preserves responsiveness and removes useless Tcl
# traffic when the visual state is identical.
def _v297_animation_tick(self):
    now=time.perf_counter();deadline=float(getattr(self,'_v297_frame_deadline',0.0) or 0.0)
    if deadline<=0.0:deadline=now
    if now+0.00035<deadline:
        try:self.root.after(max(1,int(max(.0005,deadline-now)*1000.0)),lambda s=self:_v297_animation_tick(s))
        except Exception:pass
        return
    frame_start=now
    lag_ms=max(0.0,(now-deadline)*1000.0);lag0=float(getattr(self,'_v271_lag_ema_ms',0.0) or 0.0)
    self._v271_lag_ema_ms=lag_ms if lag0<=0 else lag0*.92+lag_ms*.08
    seq=int(getattr(self,'_v271_visual_seq',0) or 0);_lr=getattr(self,'_v297_last_visual_seq',-1);last=int(-1 if _lr is None else _lr)
    wall=time.time();heartbeat=(wall-float(getattr(self,'_v297_last_heartbeat_paint',0.0) or 0.0))>=.10
    if seq!=last or heartbeat:
        try:
            if _v271_fast_live_candle(self):
                self._v297_last_visual_seq=seq
                if heartbeat:self._v297_last_heartbeat_paint=wall
                self._v297_actual_paints=int(getattr(self,'_v297_actual_paints',0) or 0)+1
        except Exception:pass
    elapsed_ms=(time.perf_counter()-frame_start)*1000.0;e0=float(getattr(self,'_v271_anim_ema_ms',0.0) or 0.0)
    self._v271_anim_ema_ms=elapsed_ms if e0<=0 else e0*.92+elapsed_ms*.08
    self._v271_target_hz=60.0;self._v271_effective_hz=60.0
    next_deadline=deadline+(1.0/60.0);now2=time.perf_counter()
    if next_deadline<=now2:
        missed=int((now2-next_deadline)/(1.0/60.0))+1;next_deadline+=missed*(1.0/60.0)
        self._v275_skipped_frames=int(getattr(self,'_v275_skipped_frames',0) or 0)+missed
    self._v297_frame_deadline=next_deadline
    try:self.root.after(max(1,int(max(.0005,next_deadline-time.perf_counter())*1000.0)),lambda s=self:_v297_animation_tick(s))
    except Exception:pass

# Existing/historical animation names all resolve to the same single low-churn
# deadline loop. This prevents an older self-scheduling symbol from resurrecting
# blind 60-FPS canvas writes.
_v26716_animation_tick=_v297_animation_tick
_v271_animation_tick=_v297_animation_tick
_v275_animation_tick=_v297_animation_tick


# Static-structure inspection does not need a 90ms poll. Four checks/sec is
# enough because completed-candle/target/lock changes are the only reasons for a
# heavyweight canvas rebuild; live motion remains on the 60Hz clock above.
def _v297_structure_tick(self):
    try:
        now=time.perf_counter();wall=time.time()
        visible=bool(self._chart_is_visible()) if hasattr(self,'_chart_is_visible') else True
        if bool(getattr(self,'web_only_mode',False)) or not visible:return
        if wall<float(getattr(self,'_scroll_active_until',0) or 0):return
        last=float(getattr(self,'_v295_static_last',0.0) or 0.0)
        key=_v295_static_key(self);old=getattr(self,'_v295_static_key_cache',None)
        changed=key!=old;due=(now-last)>=_V295_STATIC_MIN_PERIOD;heartbeat=(now-last)>=_V295_STATIC_HEARTBEAT
        force=getattr(self,'_last_chart_render_key',None) is None
        if due and (changed or force or heartbeat):
            self._v295_static_last=now;self._v295_static_key_cache=key
            self._v273_structure_hz_effective=(1.0/_V295_STATIC_MIN_PERIOD if changed else 1.0/_V295_STATIC_HEARTBEAT)
            try:self.draw_chart()
            except Exception:pass
            try:_v26716_refresh_fast_geometry(self)
            except Exception:pass
    except Exception:pass
    finally:
        try:self.root.after(250,lambda s=self:_v297_structure_tick(s))
        except Exception:pass

_v289_structure_tick=_v297_structure_tick
_v276_structure_tick=_v297_structure_tick
_v273_structure_tick=_v297_structure_tick


# A small event-loop watchdog records real UI lag; it performs no rendering.
def _v297_loop_watchdog(self):
    try:
        now=time.perf_counter();expect=float(getattr(self,'_v297_watch_expect',0.0) or 0.0)
        if expect>0:
            lag=max(0.0,(now-expect)*1000.0);old=float(getattr(self,'_v297_loop_lag_ms',0.0) or 0.0)
            self._v297_loop_lag_ms=lag if old<=0 else old*.88+lag*.12
            self._v297_loop_lag_peak=max(lag,float(getattr(self,'_v297_loop_lag_peak',0.0) or 0.0)*.995)
        self._v297_watch_expect=now+.25
    except Exception:pass
    finally:
        try:self._v297_watch_after=self.root.after(250,lambda s=self:_v297_loop_watchdog(s))
        except Exception:pass


