        self._v297_frame_deadline=time.perf_counter()+(1.0/60.0);self._v297_last_visual_seq=-1;self._v297_last_heartbeat_paint=0.0;self._v297_actual_paints=0
        self._v297_watch_expect=0.0;self._v297_loop_lag_ms=0.0;self._v297_loop_lag_peak=0.0
