# ----------------------- adaptive 3-minute opportunity lock -----------------
def _v298_gate(now, op, fc):
    bucket=int(now//900)*900;into=max(0.0,now-bucket)
    pp=dict(_v285_pro_path_packet(fc) or {})
    side=str(op.get('side','WAIT') or 'WAIT').upper()
    score=abs(float(op.get('score',0) or 0));agree=float(op.get('consistency',0) or 0)
    conf=float(op.get('avg_conf',fc.get('confidence',50)) or 50);qual=float(op.get('avg_quality',fc.get('quality',0)) or 0)
    span=float(op.get('span',0) or 0);samples=int(op.get('samples',0) or 0)
    pro_side=str(pp.get('side','WAIT') or 'WAIT').upper();pro_mag=abs(float(pp.get('score',0) or 0))
    settle=str(fc.get('settlement_side','WAIT') or 'WAIT').upper();path=str(fc.get('path_side','WAIT') or 'WAIT').upper()
    path_mag=abs(float(fc.get('path_score',0) or 0))
    target_ok=fc.get('target') is not None;ready=bool(fc.get('ready'))
    # Alignment count is forward-model agreement, never current Kalshi winner.
    aligned=sum(1 for x in (pro_side,settle,path) if x==side)
    veto=bool((fc.get('trend_guard') or {}).get('vetoed')) and str((fc.get('trend_guard') or {}).get('governed_side','')).upper()!=side
    if into<_V298_MIN_EVIDENCE_S:
        return {'earned':False,'phase':'OBSERVE','reason':f'minimum evidence {into:.0f}/{_V298_MIN_EVIDENCE_S:.0f}s','side':side,'into':into}
    if not (target_ok and ready and side in ('UP','DOWN')):
        return {'earned':False,'phase':'WAIT DATA','reason':'waiting for target + forward forecast','side':side,'into':into}
    if veto:
        return {'earned':False,'phase':'TREND VETO','reason':'hard trend governor rejects candidate','side':side,'into':into}
    # Time-decaying standards: very early decisions require exceptional clarity.
    if into<45:
        req=(.58,.88,84,68,10,14,.48,.28,3);phase='EARLY RIP'
    elif into<90:
        req=(.48,.82,80,60,22,22,.40,.24,3);phase='FAST CONFIRM'
    elif into<135:
        req=(.38,.75,74,50,38,30,.32,.19,2);phase='BUILD CONFIRM'
    elif into<=_V298_WINDOW_S:
        req=(.28,.68,69,42,55,36,.24,.14,2);phase='LATE CONFIRM'
    else:
        req=(.20,.60,63,34,65,38,.17,.10,2);phase='180S DEADLINE'
    rscore,ragree,rconf,rqual,rspan,rsamples,rpro,rpath,ralign=req
    earned=(score>=rscore and agree>=ragree and conf>=rconf and qual>=rqual and span>=rspan and samples>=rsamples and
            pro_mag>=rpro and path_mag>=rpath and aligned>=ralign and pro_side==side)
    quality=(score/max(rscore,1e-9)+agree/max(ragree,1e-9)+conf/max(rconf,1e-9)+qual/max(rqual,1e-9)+
             min(2.0,pro_mag/max(rpro,1e-9))+min(2.0,path_mag/max(rpath,1e-9)))/6.0
    reason=(f'{phase} • {side} • score {score:.2f}/{rscore:.2f} • agree {agree*100:.0f}/{ragree*100:.0f}% • '
            f'conf {conf:.0f}/{rconf} • quality {qual:.0f}/{rqual} • span {span:.0f}/{rspan}s • '
            f'pro {pro_mag:.2f}/{rpro:.2f} • path {path_mag:.2f}/{rpath:.2f} • align {aligned}/{ralign}')
    return {'earned':earned,'phase':phase,'reason':reason,'side':side,'into':into,'quality':quality,'aligned':aligned,
            'score':score,'agreement':agree,'confidence':conf,'model_quality':qual,'pro_mag':pro_mag,'path_mag':path_mag}


