def _v298_lock_read(self, now=None, state=None, force=False):
    now=float(now or time.time());bucket=int(now//900)*900;into=max(0.0,now-bucket)
    auth=int(getattr(self,'_v278_authority_bucket',bucket) or bucket)
    if auth!=bucket:_v279_clear_round_authority(self,bucket,paint=True,reason='V21.98 NEW KALSHI ROUND')
    st=getattr(self,'_v279_thesis',None)
    if not isinstance(st,dict) or int(st.get('bucket',-1) or -1)!=bucket:st=_v279_state_reset(self,bucket)
    fc=dict(state) if isinstance(state,dict) and 'settlement_side' in state else dict(_v272_forecast_read(self,now=now,force=force) or {})
    _v279_collect(self,now,fc)

    if str(st.get('side','WAIT')).upper() not in ('UP','DOWN'):
        op=dict(_v285_opening_map(self,now,fc) or {})
        gate=_v298_gate(now,op,fc)
        st['v298_gate']=dict(gate)
        if gate.get('earned'):
            side=str(gate.get('side','WAIT')).upper();strength=max(float(op.get('strength',0) or 0),float(gate.get('confidence',0) or 0))
            st.update({'status':'LOCKED','side':side,'strength':min(97.0,max(55.0,strength)),'locked_at':now,
                       'opening_score':float(op.get('score',0) or 0),'opening_consistency':float(op.get('consistency',0) or 0),
                       'opening_vote':float(op.get('vote',0) or 0),'opening_meta':dict(op),'last_reason':'OPPORTUNITY LOCK EARNED • '+gate['reason']})
            self.opening_lock_snapshot=_v298_make_snapshot(now,side,st['strength'],fc,st['last_reason'],bucket,str(gate.get('phase','LOCK')))
        else:
            st['status']='DELIBERATING';st['side']='WAIT';st['strength']=float(op.get('strength',0) or 0)
            if into<=_V298_WINDOW_S:
                st['last_reason']=f'3M OPPORTUNITY {into:.0f}/{_V298_WINDOW_S:.0f}s • {gate.get("reason","building")} • NO LOCK YET'
            else:
                st['last_reason']='3M WINDOW COMPLETE • NO SAFE LOCK YET • '+str(gate.get('reason','insufficient evidence'))
            self.opening_lock_snapshot=None

    side=str(st.get('side','WAIT')).upper();review={}
    if str(st.get('status','')).upper()=='LOCKED' and side in ('UP','DOWN'):
        review=_v279_plan_change_read(self,now,side,fc)
        if review.get('changed'):
            old=side;new='DOWN' if old=='UP' else 'UP'
            st['side']=new;st['strength']=max(float(fc.get('confidence',50) or 50),74.0);st['locked_at']=now
            st['switch_count']=int(st.get('switch_count',0) or 0)+1;st['last_switch_ts']=now;st['last_switch_from']=old;st['last_switch_to']=new
            st['last_switch_reason']=f'PLAN CHANGED {old}→{new} • '+', '.join(review.get('reasons') or [])
            st['last_reason']=st['last_switch_reason'];st['review']=deque(maxlen=500);st['review_side']='WAIT';st['review_since']=0.0
            self.opening_lock_snapshot=_v298_make_snapshot(now,new,st['strength'],fc,st['last_reason'],bucket,'PLAN CHANGED')
            side=new;review={'changed':True,'active':False,'reason':st['last_reason'],'reasons':[],'adverse':0.0,'age':0.0}
        else:
            if review.get('active'):st['last_reason']=f'MAIN LOCK {side} HELD • {review.get("reason","")}'
            else:st['last_reason']=f'MAIN LOCK {side} STICKY • 3M OPPORTUNITY THESIS • only PLAN CHANGED proof can switch'
            st['strength']=max(50.0,min(97.0,.72*float(st.get('strength',0) or 0)+.28*float(fc.get('confidence',50) or 50)))
            snap=getattr(self,'opening_lock_snapshot',None)
            if not isinstance(snap,dict) or str(snap.get('lock_side','')).upper()!=side or int(snap.get('bucket',-1) or -1)!=bucket:
                self.opening_lock_snapshot=_v298_make_snapshot(float(st.get('locked_at',now) or now),side,st['strength'],fc,st['last_reason'],bucket,'STICKY')
            else:
                snap=dict(snap);snap['strength']=st['strength'];snap['forecast_reasons']=st['last_reason'];self.opening_lock_snapshot=snap

    status=str(st.get('status','DELIBERATING')).upper();side=str(st.get('side','WAIT')).upper();ready=status=='LOCKED' and side in ('UP','DOWN')
    op=dict(st.get('opening_meta') or {}) if ready else dict(_v285_opening_map(self,now,fc) or {})
    gate=dict(st.get('v298_gate') or _v298_gate(now,op,fc))
    out={'ready':ready,'status':status,'side':side if ready else 'WAIT','lock_side':side if ready else 'WAIT',
         'candidate':side if ready else str(op.get('side','WAIT')),'strength':float(st.get('strength',0) or 0),'reason':st.get('last_reason',''),
         'forecast':fc,'snapshot':dict(self.opening_lock_snapshot) if ready and self.opening_lock_snapshot else None,'bucket':bucket,
         'seconds_into_round':into,'opening':op,'opportunity':gate,'plan_change':review,'switch_count':int(st.get('switch_count',0) or 0),
         'last_switch_from':st.get('last_switch_from','WAIT'),'last_switch_to':st.get('last_switch_to','WAIT')}
    st['last']=dict(out);self._v279_thesis=st;self._v272_last_lock=dict(out)
    return out
