# ============================================================================
# V21.98.1 FINAL STANDALONE LANE CORRECTION / TRUE 3-MINUTE WINDOW
#
# Important architecture correction:
#   Kalshi's market candlesticks are contract-probability candles (0.00..1.00),
#   while the KXBTC15M strike is a BTC/USD dollar target.  Never mix those two
#   price scales inside the settlement math.
#
# Therefore:
#   * VISIBLE CHART <= 15m = Kalshi YES contract candles.
#   * KALSHI CONTRACT TA = momentum/structure confirmation only; raw 50c winner
#     level has ZERO authority.
#   * SETTLEMENT / target / target-cushion / exact MBI / 1H+4H context continue
#     to use the BTC underlying lane already built into James.
#   * The adaptive opening map actually observes the full 0..180 seconds.
# ============================================================================
_V298_RELEASE='V21.98.2 STANDALONE KALSHI CANDLES • TRUE 3M OPPORTUNITY LOCK'

# Restore the underlying-BTC analysis lane. V21.98's first draft temporarily
# routed every short TF through contract odds; that can corrupt dollar-based
# fair-value/target math.  Contract candles now have their own explicit route.
ChartKingPro._history_for_interval=_V298_BASE_HISTORY
ChartKingPro._current_bucket_for_interval=_V298_BASE_CURRENT


def _v298_contract_history_for_interval(self, seconds):
    sec=max(1,int(seconds))
    if sec<60:
        return _v298_aggregate_ticks(self,sec,include_current=False,limit=max(240,int(1800/max(sec,1))))
    if sec<=900:
        base=_v298_merge_1m(self)
        try:return self._resample_history(base,sec)
        except Exception:return []
    # A single 15m binary contract has no coherent 1h/4h continuation.  Those
    # buttons intentionally fall back to the BTC settlement/context lane.
    return _V298_BASE_HISTORY(self,sec)


def _v298_contract_current_bucket(self, seconds):
    sec=max(1,int(seconds))
    if sec>900:return _V298_BASE_CURRENT(self,sec)
    now=time.time();bucket=int(now//sec)*sec
    rows=_v298_aggregate_ticks(self,sec,include_current=True,now=now,limit=max(20,int(1200/max(sec,1))))
    for r in reversed(rows):
        if int(r.get('time',-1))==bucket:return dict(r)
    merged=_v298_merge_1m(self)
    for r in reversed(merged):
        if int(float(r.get('time',-1))//sec)*sec==bucket:
            return {'time':bucket,'open':float(r['open']),'high':float(r['high']),'low':float(r['low']),
                    'close':float(r['close']),'volume':float(r.get('volume',0) or 0),
                    '_live_source':'KALSHI OFFICIAL/LIVE SEED'}
    px,src=_v298_contract_live_price(self)
    if px is None:return None
    px=float(px)
    return {'time':bucket,'open':px,'high':px,'low':px,'close':px,'volume':0.0,'_live_source':src}

ChartKingPro._v298_contract_history_for_interval=_v298_contract_history_for_interval
ChartKingPro._v298_contract_current_bucket=_v298_contract_current_bucket


def _v298_chart_candles_contract(self):
    """Visible chart: Kalshi YES candles through 15m; BTC context for 1h/4h."""
    sec=max(1,int(getattr(self,'chart_interval_seconds',900) or 900))
    if sec>900:
        try:return list(_V255_BASE_CHART_CANDLES(self) or [])
        except Exception:return list(_V298_BASE_HISTORY(self,sec) or [])
    now=time.time();bucket=int(now//sec)*sec
    rows=list(_v298_contract_history_for_interval(self,sec) or [])
    cur=_v298_contract_current_bucket(self,sec)
    out=[]
    for r0 in rows:
        try:
            r=dict(r0);ts=int(float(r.get('time',0))//sec)*sec
            if ts>=bucket:continue
            o=float(r['open']);h=float(r['high']);l=float(r['low']);c=float(r['close'])
            if not all(math.isfinite(x) for x in (o,h,l,c)):continue
            out.append({'time':ts,'open':o,'high':max(h,o,c),'low':min(l,o,c),'close':c,
                        'volume':float(r.get('volume',0) or 0),'_live_source':r.get('_live_source','KALSHI')})
        except Exception:pass
    if isinstance(cur,dict):out.append(dict(cur))
    # unique/sorted, bounded
    ded={}
    for r in out:ded[int(r['time'])]=r
    out=[ded[k] for k in sorted(ded)][-max(80,int(getattr(self,'visible_count',80) or 80)+10):]
    self._v255_last_candle_rows=[dict(r) for r in out]
    self._v255_last_candle_bucket=int(out[-1]['time']) if out else None
