def _v298_contract_ta_read(self, now=None, force=False):
    """Price-level-neutral Kalshi candle/tick momentum.

    This deliberately ignores whether YES is above/below 50c.  It only measures
    repricing DIRECTION and persistence, so the current Kalshi winner never gets
    lock authority merely for being the current winner.
    """
    now=float(now or time.time());cache=dict(getattr(self,'_v2981_contract_ta_cache',{}) or {})
    if (not force) and cache and now-float(cache.get('ts',0) or 0)<.20:return dict(cache)
    bucket=int(now//900)*900
    ticks=[]
    for raw in list(getattr(self,'v298_kalshi_ticks',()) or ()):
        try:
            ts=float(raw[0]);px=float(raw[1])
            if bucket<=ts<=now and 0.0<=px<=1.0:ticks.append((ts,px))
        except Exception:pass
    if len(ticks)<5:
        out={'ready':False,'side':'WAIT','score':0.0,'confidence':0.0,'samples':len(ticks),'span':0.0,
             'reason':f'KALSHI CONTRACT TA building ({len(ticks)} ticks) • 50c level ignored','ts':now}
        self._v2981_contract_ta_cache=dict(out);return out
    ticks.sort();span=max(0.0,ticks[-1][0]-ticks[0][0]);cur=ticks[-1][1]
    def at_or_before(age):
        target=now-float(age);best=ticks[0][1]
        for ts,px in ticks:
            if ts<=target:best=px
            else:break
        return best
    # A few probability points is already a meaningful contract move. tanh
    # bounds any one burst so it cannot dominate the forecast stack.
    parts=[]
    for age,w,scale in ((10,.30,.025),(30,.30,.045),(60,.25,.070),(120,.15,.100)):
        if span>=min(age*.55,8.0):
            d=cur-at_or_before(age);parts.append((math.tanh(d/max(scale,1e-6)),w))
    den=sum(w for _v,w in parts) or 1.0;drift=sum(v*w for v,w in parts)/den if parts else 0.0
    diffs=[ticks[i][1]-ticks[i-1][1] for i in range(1,len(ticks)) if ticks[i][0]>ticks[i-1][0]]
    nz=[d for d in diffs[-40:] if abs(d)>=0.00005]
    persist=(sum(1 if d>0 else -1 for d in nz)/len(nz)) if nz else 0.0
    # 15s/30s candle body confirmation from the same contract feed.
    bodies=[]
    for sec,w in ((15,.55),(30,.45)):
        rr=_v298_aggregate_ticks(self,sec,include_current=True,now=now,limit=6)
        if rr:
            r=rr[-1];rng=max(.003,float(r['high'])-float(r['low']))
            bodies.append((((float(r['close'])-float(r['open']))/rng),w))
    bden=sum(w for _v,w in bodies) or 1.0;body=sum(max(-1.0,min(1.0,v))*w for v,w in bodies)/bden if bodies else 0.0
    score=max(-1.0,min(1.0,.58*drift+.24*persist+.18*body))
    side='UP' if score>=.10 else 'DOWN' if score<=-.10 else 'WAIT'
    conf=min(96.0,48.0+38.0*abs(score)+min(10.0,span/9.0))
    out={'ready':span>=8.0 and len(ticks)>=8,'side':side,'score':score,'confidence':conf,'samples':len(ticks),'span':span,
         'drift':drift,'persistence':persist,'body':body,'price':cur,
         'reason':f'KALSHI CONTRACT REPRICING {side} {score:+.2f} • persistence {persist:+.2f} • 50c LEVEL ZERO AUTHORITY',
         'ts':now}
    self._v2981_contract_ta_cache=dict(out);return out

ChartKingPro._v298_contract_ta_read=_v298_contract_ta_read

