def _v298_opening_map_180(self, now, fc):
    """Aggregate forward-path evidence over the ACTUAL full 0..180s window."""
    now=float(now or time.time());bucket=int(now//900)*900
    st=_v285_collect(self,now,fc)
    rows_all=[r for r in list(st.get('samples') or []) if bucket<=float(r.get('ts',0) or 0)<min(bucket+180.001,now+.001) and 'pro_score' in r]
    if not rows_all:
        return {'ready':False,'side':'WAIT','score':0.0,'strength':0.0,'consistency':0.0,'vote':0.0,'samples':0,'span':0.0,
                'avg_conf':float(fc.get('confidence',50) or 50),'avg_quality':float(fc.get('quality',0) or 0),
                'reason':'3M PRO PATH • waiting for valid forward samples'}
    first=float(rows_all[0].get('ts',now) or now);rows=rows_all
    vals=[];weights=[];votes=[];confs=[];quals=[];paths=[];finishes=[]
    for r in rows:
        rel=max(0.0,min(180.0,float(r.get('ts',first))-bucket))
        confn=_v279_clip((float(r.get('conf',50))-50.0)/47.0,0,1);q=_v279_clip(float(r.get('quality',0))/100.0,0,1)
        # Mild late premium only; a late burst cannot erase two minutes of evidence.
        w=(.86+.28*(rel/180.0))*(.56+.25*q+.19*confn)
        v=_v279_clip(float(r.get('pro_score',0) or 0));vals.append(v);weights.append(w)
        votes.append(((1.0 if v>.03 else -1.0 if v<-.03 else 0.0),w));confs.append(float(r.get('conf',50) or 50));quals.append(float(r.get('quality',0) or 0))
        paths.append(float(r.get('path',0) or 0));finishes.append(float(r.get('future_finish',0) or 0))
    den=sum(weights) or 1.0;mean=sum(v*w for v,w in zip(vals,weights))/den;med=_v279_median(vals,0.0);vote=sum(s*w for s,w in votes)/den
    score=_v279_clip(.62*mean+.25*med+.13*vote);sign=1 if score>0 else -1 if score<0 else 0
    agree=sum(w for v,w in zip(vals,weights) if sign and v*sign>=0)/den if sign else 0.0
    side='UP' if score>=.025 else 'DOWN' if score<=-.025 else ('UP' if vote>0 else 'DOWN' if vote<0 else 'WAIT')
    span=max(0.0,float(rows[-1].get('ts',first))-float(rows[0].get('ts',first))) if len(rows)>=2 else 0.0
    avg_conf=sum(confs)/len(confs) if confs else 50.0;avg_qual=sum(quals)/len(quals) if quals else 0.0
    strength=max(52.0,min(97.0,50+30*abs(score)+11*agree+4*_v279_clip((avg_conf-50)/47,0,1)+2*_v279_clip(avg_qual/100,0,1)))
    return {'ready':bool(fc.get('ready')) and fc.get('target') is not None and side in ('UP','DOWN'),
            'side':side,'score':score,'strength':strength,'consistency':agree,'vote':vote,'samples':len(rows),'span':span,
            'avg_conf':avg_conf,'avg_quality':avg_qual,'path_mean':sum(paths)/len(paths) if paths else 0.0,
            'future_finish_mean':sum(finishes)/len(finishes) if finishes else 0.0,'current_winner_used':False,
            'reason':f'3M PRO PATH • {side} {score:+.2f} • agree {agree*100:.0f}% • {len(rows)} samples/{span:.0f}s • current winner ZERO AUTHORITY'}

ChartKingPro._v298_opening_map_180=_v298_opening_map_180


def _v298_gate_final(now, op, fc):
    bucket=int(now//900)*900;into=max(0.0,now-bucket)
    side=str(op.get('side','WAIT') or 'WAIT').upper();score=abs(float(op.get('score',0) or 0));agree=float(op.get('consistency',0) or 0)
    conf=float(op.get('avg_conf',fc.get('confidence',50)) or 50);qual=float(op.get('avg_quality',fc.get('quality',0)) or 0);span=float(op.get('span',0) or 0);samples=int(op.get('samples',0) or 0)
    pp=dict(_v285_pro_path_packet(fc) or {});pro_side=str(pp.get('side','WAIT') or 'WAIT').upper();pro_mag=abs(float(pp.get('score',0) or 0))
    settle=str(fc.get('settlement_side','WAIT') or 'WAIT').upper();path=str(fc.get('path_side','WAIT') or 'WAIT').upper();path_mag=abs(float(fc.get('path_score',0) or 0))
    cta=dict(fc.get('kalshi_contract_ta') or {});cside=str(cta.get('side','WAIT')).upper();cmag=abs(float(cta.get('score',0) or 0));cready=bool(cta.get('ready'))
    if into<_V298_MIN_EVIDENCE_S:return {'earned':False,'phase':'OBSERVE','reason':f'minimum evidence {into:.0f}/{_V298_MIN_EVIDENCE_S:.0f}s','side':side,'into':into}
    if into>182.0:return {'earned':False,'phase':'WINDOW CLOSED','reason':'3-minute opportunity closed without a safe lock','side':side,'into':into}
    if not (fc.get('target') is not None and bool(fc.get('ready')) and side in ('UP','DOWN')):
        return {'earned':False,'phase':'WAIT DATA','reason':'waiting for target + forward forecast','side':side,'into':into}
    veto=bool((fc.get('trend_guard') or {}).get('vetoed')) and str((fc.get('trend_guard') or {}).get('governed_side','')).upper()!=side
    if veto:return {'earned':False,'phase':'TREND VETO','reason':'hard trend governor rejects candidate','side':side,'into':into}
    if into<45:req=(.58,.88,84,68,10,14,.48,.28,3);phase='EARLY RIP'
    elif into<90:req=(.48,.82,80,60,22,22,.40,.24,3);phase='FAST CONFIRM'
    elif into<135:req=(.38,.75,74,50,38,30,.32,.19,2);phase='BUILD CONFIRM'
    else:req=(.25,.65,67,38,50,34,.21,.12,2);phase='FINAL 3M CONFIRM'
    rscore,ragree,rconf,rqual,rspan,rsamples,rpro,rpath,ralign=req
    aligned=sum(1 for x in (pro_side,settle,path) if x==side)
    if cready and cmag>=.12 and cside==side:aligned+=1
    strong_contract_conflict=cready and cmag>=.42 and cside in ('UP','DOWN') and cside!=side
    earned=(score>=rscore and agree>=ragree and conf>=rconf and qual>=rqual and span>=rspan and samples>=rsamples and pro_mag>=rpro and path_mag>=rpath and aligned>=ralign and pro_side==side)
    # Before the final minute, a violently repricing Kalshi contract in the
    # opposite direction is a reason to keep studying, not to force a lock.
    if strong_contract_conflict and into<135:earned=False
    reason=(f'{phase} • {side} • score {score:.2f}/{rscore:.2f} • agree {agree*100:.0f}/{ragree*100:.0f}% • conf {conf:.0f}/{rconf} • '
            f'quality {qual:.0f}/{rqual} • span {span:.0f}/{rspan}s • pro {pro_mag:.2f}/{rpro:.2f} • path {path_mag:.2f}/{rpath:.2f} • '
            f'align {aligned}/{ralign} • Kalshi momentum {cside} {float(cta.get("score",0) or 0):+.2f} (50c level ignored)')
    if strong_contract_conflict and into<135:reason+=' • STRONG CONTRACT REPRICING CONFLICT = WAIT'
    return {'earned':earned,'phase':phase,'reason':reason,'side':side,'into':into,'aligned':aligned,'score':score,'agreement':agree,'confidence':conf,'model_quality':qual,'pro_mag':pro_mag,'path_mag':path_mag,'contract_ta':cta}

