# Round-start target watchdog: the feed already applies every Kalshi market
# object, but this gives target discovery an explicit new-900s-bucket kick.
def _v2981_target_round_watch(self):
    try:
        bucket=int(time.time()//900)*900;last=getattr(self,'_v2981_target_bucket',None)
        if last!=bucket:
            self._v2981_target_bucket=bucket
            def worker(app=self):
                try:
                    m=app._discover_current_kalshi_market();app._apply_kalshi_market(m,'V21.98.1 ROUND-START AUTO TARGET')
                    try:rows=_v298_fetch_official_1m(app,str(m.get('ticker') or ''));app.v298_kalshi_1m=rows or app.v298_kalshi_1m
                    except Exception:pass
                except Exception as exc:
                    try:app.auto_target_status_var.set('AUTO TARGET RETRYING: '+str(exc)[:100])
                    except Exception:pass
            threading.Thread(target=worker,name='LeChartJames-RoundTarget',daemon=True).start()
    except Exception:pass
    finally:
        try:self.root.after(250,lambda s=self:_v2981_target_round_watch(s))
        except Exception:pass

