def _v2985_commit_market(self, market, source='MANUAL TICKER'):
    # Main-thread commit only: this avoids Tk layout/variable mutation from a worker.
    ticker=str((market or {}).get('ticker') or '').strip().upper()
    if not ticker.startswith('KXBTC15M-'):raise ValueError('That is not a KXBTC15M market')
    self._v2984_selected_ticker=ticker;self.kalshi_ticker=ticker;self.kalshi_market=dict(market)
    self.ticker_var.set(ticker)
    target=self._extract_target(market)
    if target is None:
        # Newer/alternate payload fields + context-bound text fallback.
        for key in ('floor_strike','functional_strike','cap_strike','strike','strike_price','target_price','reference_price','price_to_beat'):
            try:
                x=float(str(market.get(key,'')).replace('$','').replace(',','').strip())
                if x>1000:target=x;break
            except Exception:pass
    if target is None:raise ValueError('Market loaded but BTC target/strike was not found')
    self.target_price=float(target);self._v2984_target_ticker=ticker
    bucket=int(time.time()//900)*900
    self._v26710_target_lock_bucket=bucket;self._v26710_target_lock=float(target);self._v26710_seen_bucket=bucket
    self._v26710_target_source='V21.98.5 EXACT KALSHI STRIKE'
    self.auto_target_status_var.set(f'AUTO TARGET: {money(target)} • {ticker}')
    self.auto_market_status_var.set(f'KALSHI MARKET: {ticker} • {source}')
    self.status_var.set(f'{source} LOADED • target {money(target)} • BRTI candles remain BTC dollars')
    self._last_chart_render_key=None;self._v271_visual_seq=int(getattr(self,'_v271_visual_seq',0) or 0)+1


def _v2985_async_load(self, raw=None):
    raw=str(raw if raw is not None else self.ticker_var.get() or '');ticker=self._sanitize_ticker(raw)
    if not ticker:
        self.status_var.set('Paste a KXBTC15M ticker, then press LOAD');return
    self.status_var.set('Loading '+ticker+' ...')
    def worker(app=self,t=ticker):
        try:m=_v2984_market_detail(app,t);app.root.after(0,lambda mm=m,a=app:_v2985_commit_market(a,mm,'MANUAL TICKER'))
        except Exception as exc:app.root.after(0,lambda e=str(exc),a=app:a.status_var.set('LOAD ERROR • '+e[:140]))
    threading.Thread(target=worker,name='LeChartJames-V21985-LoadTicker',daemon=True).start()


def _v2985_auto_current(self):
    self.status_var.set('Finding current KXBTC15M ...')
    def worker(app=self):
        try:m=app._discover_current_kalshi_market();app.root.after(0,lambda mm=m,a=app:_v2985_commit_market(a,mm,'AUTO CURRENT'))
        except Exception as exc:app.root.after(0,lambda e=str(exc),a=app:a.status_var.set('AUTO CURRENT ERROR • '+e[:140]))
    threading.Thread(target=worker,name='LeChartJames-V21985-AutoTicker',daemon=True).start()


def _v2985_round_watch(self):
    try:
        bucket=int(time.time()//900)*900;last=getattr(self,'_v2985_target_bucket',None)
        if last!=bucket:
            self._v2985_target_bucket=bucket
            # Immediately clear first-lock authority for the new round (inherited
            # James does this too), then refresh the currently selected market.
            ticker=str(getattr(self,'_v2984_selected_ticker','') or '').strip().upper()
            if ticker:
                def worker(app=self,t=ticker,b=bucket):
                    try:
                        m=_v2984_market_detail(app,t)
                        close=app._parse_iso_ts(m.get('close_time') or m.get('expected_expiration_time') or m.get('expiration_time'))
                        if close and close<=time.time()+2:
                            # Selected ticker is the prior round; locate the new
                            # KXBTC15M automatically so target is ready at open.
                            m=app._discover_current_kalshi_market();src='ROUND START AUTO CURRENT'
                        else:src='ROUND START REFRESH'
                        app.root.after(0,lambda mm=m,ss=src,a=app:_v2985_commit_market(a,mm,ss))
                    except Exception as exc:app.root.after(0,lambda e=str(exc),a=app:a.auto_target_status_var.set('TARGET RETRY • '+e[:110]))
                threading.Thread(target=worker,name='LeChartJames-V21985-RoundTarget',daemon=True).start()
            else:
                # No manual ticker yet: auto-discover once so target isn't blank.
                _v2985_auto_current(self)
    except Exception:pass
    finally:
        try:self.root.after(1000,lambda s=self:_v2985_round_watch(s))
        except Exception:pass


