def _v2986_target_overlay(self):
    """Keep target obvious before the 15m signal bundle is ready.

    The V21.97 renderer only drew the target inside `if sig:`.  Standalone can
    correctly acquire the target before that signal object exists, so we draw a
    small always-on target overlay using the exact chart scale that was just
    rendered.  If target is outside the current visible range, the label is
    pinned to the closest chart edge instead of vanishing/clipping.
    """
    try:
        c=self.canvas
        c.delete('v2986_target_overlay')
        target,source=self.effective_target()
        if target is None:
            return
        target=float(target)
        if not (1000.0 < target < 10000000.0):
            return
        sc=getattr(self,'_v82_chart_scale',None)
        if not isinstance(sc,dict):
            return
        lo=float(sc['lo']); hi=float(sc['hi']); top=float(sc['top']); ph=float(sc['ph'])
        left=float(sc['left']); right=float(sc['plot_right'])
        if not all(math.isfinite(x) for x in (lo,hi,top,ph,left,right)) or hi<=lo:
            return
        if lo <= target <= hi:
            yy=top+(hi-target)/(hi-lo)*ph
            state=''
        elif target>hi:
            yy=top+2.0; state='  ↑ ABOVE VIEW'
        else:
            yy=top+ph-2.0; state='  ↓ BELOW VIEW'
        # Draw behind a compact label so the target is impossible to miss but
        # never changes layout geometry.
        c.create_line(left,yy,right,yy,fill=YELLOW,dash=(8,5),width=2,
                      tags=('v2986_target_overlay',))
        label=f'KALSHI TARGET {money(target)}{state}'
        # Fixed canvas items: no Tk pack/grid geometry can be affected.
        label_y=max(top+12.0,min(top+ph-12.0,yy-11.0 if yy>top+24 else yy+12.0))
        text_id=c.create_text(left+8,label_y,text=label,fill=YELLOW,anchor='w',
                             font=('Segoe UI',8,'bold'),tags=('v2986_target_overlay',))
        try:
            bb=c.bbox(text_id)
            if bb:
                bg=c.create_rectangle(bb[0]-4,bb[1]-2,bb[2]+4,bb[3]+2,
                                      fill='#171305',outline='#786319',width=1,
                                      tags=('v2986_target_overlay','v2986_target_overlay_bg'))
                c.tag_lower(bg,text_id)
        except Exception:
            pass
    except Exception:
        pass


def _v2986_draw_chart(self):
    # The exact V21.97 renderer remains authoritative; the data source has
    # already been replaced by the BRTI dollar-only adapters above.
    result=_V2986_PREV_DRAW(self)
