def _v2986_scrub_stale_source_copy(app):
    """Replace inherited standalone/Bookmap source labels without remounting UI."""
    swaps=(
        ('ONE JOURNAL • LIVE KALSHI BBO • BOOKMAP MASTER AUTHORITY',
         'ONE JOURNAL • LIVE KALSHI BBO • BRTI BTC/USD PRICE AUTHORITY'),
        ('KALSHI CANDLES: standalone feed starting • Bookmap OFF',
         'KALSHI BRTI: BTC/USD dollar feed starting • Bookmap OFF'),
        ('KALSHI CONTRACT FLOW: starting',
         'KALSHI BBO / QUANT: starting'),
        ('KALSHI MODE: contract candles + BTC settlement lane',
         'KALSHI MODE: BRTI $ candles + KXBTC15M target/quant lane'),
        ('BOOKMAP HEATMAP OFF • KALSHI CONTRACT CANDLES ACTIVE',
         'BOOKMAP OFF • KALSHI CF BRTI $ CANDLES ACTIVE'),
        ('KALSHI CONTRACT CANDLES ACTIVE',
         'KALSHI CF BRTI $ CANDLES ACTIVE'),
        ('KALSHI CONTRACT CANDLES',
         'KALSHI BRTI BTC/USD $ CANDLES'),
        ('contract candles + BTC settlement lane',
         'BRTI BTC/USD $ candles + KXBTC15M target/quant lane'),
    )
    def walk(w):
        try:children=w.winfo_children()
        except Exception:return
        for ch in children:
            try:
                keys=ch.keys()
                if 'text' in keys:
                    txt=str(ch.cget('text') or '')
                    new=txt
                    for a,b in swaps:new=new.replace(a,b)
                    if new!=txt:ch.configure(text=new)
                if 'textvariable' in keys:
                    tv=str(ch.cget('textvariable') or '')
                    if tv:
                        try:
                            txt=str(app.root.getvar(tv) or '')
                            new=txt
                            for a,b in swaps:new=new.replace(a,b)
                            if new!=txt:app.root.setvar(tv,new)
                        except Exception:pass
            except Exception:pass
            walk(ch)
    try:walk(app.root)
    except Exception:pass


def _v2986_freeze_standalone_geometry(app):
    """Freeze the chart/journey vertical split so live text can never move it.

    Inherited Journey Mapper labels change requested height as their text wraps.
    Even with a fixed canvas this could steal 16 px from the chart every few
    seconds.  The real window height is already known, so reserve a fixed 144 px
    Journey slot and give every remaining center-row pixel to the chart.
    """
    try:
        main=getattr(app,'v274_cockpit_main',None)
        journey=getattr(app,'v2676_journey_card',None)
        jc=getattr(app,'v2676_journey_canvas',None)
        if main is not None:
            main.grid_rowconfigure(0,weight=1,minsize=0)
            main.grid_rowconfigure(1,weight=0,minsize=144)
        if journey is not None and journey.winfo_exists():
            journey.configure(height=144)
            try:journey.pack_propagate(False)
            except Exception:pass
            try:journey.grid_propagate(False)
            except Exception:pass
        if jc is not None and jc.winfo_exists():
            try:jc.configure(height=34)
            except Exception:pass
        # Preserve V21.97's fixed 300 px priority rail.
        side=getattr(app,'v274_right_rail',None)
        if main is not None and side is not None:
            main.grid_columnconfigure(1,weight=0,minsize=300)
            try:side.configure(width=300);side.grid_propagate(False)
            except Exception:pass
        return True
    except Exception:
        return False


def _v2986_polish(app):
    try:app.root.title('LECHART JAMES V21.98.6 — KALSHI BRTI BTC/USD $ CANDLES • TRUE 3M OPPORTUNITY')
    except Exception:pass
