# LECHART JAMES V22.0 — ROUTE-FIRST REVERSAL / BARRIER FORECAST REBUILD
# ============================================================================
# GOALS
#   * Cretonne-style continuous reversal meter: 0%=peak thesis, 100%=coin flip,
#     >100%=opposite side now has the edge; 12s velocity + hysteresis.
#   * Current winner / historical trend are CONTEXT, not terminal authority.
#   * Explicit floor/ceiling map with PRE-CONTACT BREAK vs REJECT forecast.
#   * Breakout-hold score after a level is crossed.
#   * Double-top / double-bottom: candidate -> confirmed -> failed, plus a
#     follow-through score instead of treating the shape as destiny.
#   * Bookmap route read uses a noise-filtered price / persistence wrapper.
#   * Heavy chart TFs removed from UI: 3s, 5s, 30s, 4H. (No 1s chart exists.)
#     1s/3s raw motion may remain internal evidence; it is no longer charted.
# ============================================================================

_V220_RELEASE = 'V22.0 ROUTE-FIRST REVERSAL + BARRIER FORECAST'
_V220_SOURCE_MODE = 'KALSHI'


def _v220_clip(v, lo=0.0, hi=100.0):
    try:
        x=float(v)
        if not math.isfinite(x): return lo
        return max(lo,min(hi,x))
    except Exception:
        return lo


def _v220_sgn(side):
    s=str(side or '').upper()
    return 1.0 if s=='UP' else -1.0 if s=='DOWN' else 0.0


def _v220_median(vals):
    vals=sorted(float(x) for x in vals if x is not None and math.isfinite(float(x)))
    if not vals:return None
    n=len(vals); return vals[n//2] if n%2 else (vals[n//2-1]+vals[n//2])*.5


def _v220_atr(rows, n=14):
    rows=list(rows or [])
    if len(rows)<3:return 20.0
    trs=[]
    prev=float(rows[0]['close'])
    for r in rows[1:]:
        h=float(r['high']);l=float(r['low']);c=float(r['close'])
        trs.append(max(h-l,abs(h-prev),abs(l-prev)));prev=c
    use=trs[-n:]
    return max(1.0,sum(use)/max(1,len(use)))


def _v220_filtered_live(self, now=None):
    now=float(now or time.time())
    try: raw,src=self.effective_live_price()
    except Exception: raw,src=None,'WAITING'
    try: raw=float(raw)
    except Exception:return {'ready':False,'price':None,'raw':None,'source':src,'persistence':0.0,'velocity':0.0}
    st=dict(getattr(self,'_v220_noise_state',{}) or {})
    hist=deque(st.get('raw_hist',[]),maxlen=20); hist.append((now,raw));
    while hist and now-hist[0][0]>8.0: hist.popleft()
    med=_v220_median([p for _t,p in list(hist)[-5:]]) or raw
    rows=list(getattr(self,'btc_1m',[]) or [])[-40:]
    atr=_v220_atr(rows)
    prev=st.get('filtered')
    if prev is None: filt=med
    else:
        prev=float(prev); step=med-prev
        # Clip one update to a fraction of 1m ATR. Real moves still pass after
        # persistence; isolated Bookmap shocks cannot teleport the brain.
        cap=max(2.0,atr*(.22 if _V220_SOURCE_MODE=='BOOKMAP' else .45))
        step=max(-cap,min(cap,step))
        alpha=.30 if _V220_SOURCE_MODE=='BOOKMAP' else .52
        filt=prev+alpha*step
    fh=deque(st.get('filt_hist',[]),maxlen=32);fh.append((now,filt))
    while fh and now-fh[0][0]>10.0:fh.popleft()
    velocity=0.0
    if len(fh)>=2:
        dt=fh[-1][0]-fh[0][0]
        if dt>0:velocity=(fh[-1][1]-fh[0][1])/dt
    deltas=[]
    for i in range(1,len(fh)):
        d=fh[i][1]-fh[i-1][1]
        if abs(d)>.05:deltas.append(1 if d>0 else -1)
    persistence=(abs(sum(deltas))/len(deltas)) if deltas else 0.0
    st={'raw_hist':list(hist),'filt_hist':list(fh),'filtered':filt,'ts':now}
    self._v220_noise_state=st
    return {'ready':True,'price':filt,'raw':raw,'source':src,'persistence':persistence,'velocity':velocity,'atr':atr}


def _v220_level_map(self, live=None):
    rows=list(getattr(self,'btc_1m',[]) or [])[-180:]
    if len(rows)<18 or live is None:
        return {'ready':False,'ceiling':None,'floor':None,'atr':_v220_atr(rows)}
    atr=_v220_atr(rows); tol=max(4.0,atr*.22)
    highs=[float(r['high']) for r in rows];lows=[float(r['low']) for r in rows]
    piv=[]
    for i in range(2,len(rows)-2):
        h=highs[i]; l=lows[i]
        if h>=max(highs[i-2:i]+highs[i+1:i+3]):piv.append(('CEILING',h,i))
        if l<=min(lows[i-2:i]+lows[i+1:i+3]):piv.append(('FLOOR',l,i))
    clusters=[]
    for typ,px,idx in piv:
        hit=None
        for c in clusters:
            if c['type']==typ and abs(c['price']-px)<=tol:
                hit=c;break
        if hit is None:
            hit={'type':typ,'price':px,'touches':0,'last_idx':idx,'reject_sum':0.0,'members':[]};clusters.append(hit)
        hit['members'].append(px);hit['touches']+=1;hit['last_idx']=max(hit['last_idx'],idx);hit['price']=sum(hit['members'])/len(hit['members'])
        # Measure the best opposite reaction in the next few 1m candles.
        later=rows[idx+1:min(len(rows),idx+5)]
        if later:
            if typ=='CEILING': rej=max(0.0,px-min(float(x['low']) for x in later))
            else: rej=max(0.0,max(float(x['high']) for x in later)-px)
            hit['reject_sum']+=rej
    for c in clusters:
        avg_rej=c['reject_sum']/max(1,c['touches'])
        recency=1.0-max(0.0,(len(rows)-1-c['last_idx'])/120.0)
        c['rejection_strength']=_v220_clip(avg_rej/max(atr,.01)*45.0 + min(28,c['touches']*5.0)+recency*18.0)
        c['age_bars']=len(rows)-1-c['last_idx']
    ceil=[c for c in clusters if c['type']=='CEILING' and c['price']>live-tol*.25]
    floor=[c for c in clusters if c['type']=='FLOOR' and c['price']<live+tol*.25]
    ceiling=min(ceil,key=lambda c:abs(c['price']-live)) if ceil else None
    fl=max(floor,key=lambda c:c['price']) if floor else None
    return {'ready':True,'ceiling':ceiling,'floor':fl,'atr':atr,'tol':tol,'clusters':clusters}


def _v220_mbi(self, now=None):
    try:return dict(_v291_momentum_read(self,now=now,force=False) or {})
    except Exception:return {}


def _v220_tug(self, now=None):
    try:return dict(_v2672_tug_read(self,now=now) or {})
    except Exception:return {}


def _v220_barrier_forecast(self, level, side, live, noise, mbi, tug):
    # side UP means evaluating ceiling break; side DOWN means evaluating floor break.
    if not level or live is None:return {'ready':False,'break':50.0,'reject':50.0,'hold':50.0,'status':'NO LEVEL'}
    atr=max(1.0,float(noise.get('atr',20.0) or 20.0)); px=float(level['price']);dist=abs(px-live)
    sign=1.0 if side=='UP' else -1.0
    mbi_score=float(mbi.get('forward_score',mbi.get('score',0)) or 0)/100.0
    tug_signed=float(tug.get('signed',tug.get('score',0)) or 0)
    if abs(tug_signed)>1.5:tug_signed/=100.0
    vel=float(noise.get('velocity',0) or 0)
    vel_norm=max(-1.0,min(1.0,vel/max(atr*.18,1.0)))
    persistence=float(noise.get('persistence',0) or 0)
    touches=float(level.get('touches',1) or 1)
    hist_rej=float(level.get('rejection_strength',50) or 50)/100.0
    # Repeated tests weaken a barrier; strong historical ejections strengthen it.
    break_pressure=50 + sign*mbi_score*17 + sign*tug_signed*13 + sign*vel_norm*15 + persistence*6 + min(14,max(0,touches-1)*3.5) - hist_rej*13
    reject_pressure=50 - sign*mbi_score*13 - sign*tug_signed*10 - sign*vel_norm*12 + hist_rej*18 - min(10,max(0,touches-1)*2.5)
    # Price acceptance beyond the level transforms the question into breakout hold.
    beyond=(live-px)*sign
    acceptance=max(-1.0,min(1.0,beyond/max(atr*.35,1.0)))
    hold=50 + acceptance*24 + sign*mbi_score*16 + sign*tug_signed*14 + sign*vel_norm*13 + persistence*7 - hist_rej*10
    break_pressure=_v220_clip(break_pressure);reject_pressure=_v220_clip(reject_pressure);hold=_v220_clip(hold)
    if beyond>0:
        status='BREAK HOLDING' if hold>=62 else 'BREAK WEAK / FAILURE RISK' if hold<45 else 'BREAK TESTING'
    else:
        status='BREAK FAVORED' if break_pressure>=reject_pressure+12 else 'REJECT FAVORED' if reject_pressure>=break_pressure+12 else 'CONTESTED'
    return {'ready':True,'level':px,'distance':dist,'break':break_pressure,'reject':reject_pressure,'hold':hold,'status':status,'touches':int(touches),'hist_reject':hist_rej*100,'beyond':beyond}


def _v220_double_pattern(self, live, mbi, rev_hint=None):
    rows=list(getattr(self,'btc_1m',[]) or [])[-120:]
    if len(rows)<20:return {'ready':False,'name':'NONE','stage':'NONE','score':0.0}
    atr=_v220_atr(rows); highs=[float(x['high']) for x in rows]; lows=[float(x['low']) for x in rows]; close=float(rows[-1]['close'])
    ph=[];pl=[]
    for i in range(2,len(rows)-2):
        if highs[i]>=max(highs[i-2:i]+highs[i+1:i+3]):ph.append(i)
        if lows[i]<=min(lows[i-2:i]+lows[i+1:i+3]):pl.append(i)
    cand=[]
    if len(ph)>=2:
        a,b=ph[-2],ph[-1]
        if b-a>=3 and abs(highs[b]-highs[a])<=atr*.38:
            neck=min(lows[a:b+1]); top=max(highs[a],highs[b]);
            stage='FAILED' if close>top+atr*.15 else 'CONFIRMED' if close<neck-atr*.08 else 'CANDIDATE'
            m=float(mbi.get('forward_score',mbi.get('score',0)) or 0)
            score=50 + max(-25,min(25,-m*.25)) + (18 if stage=='CONFIRMED' else -22 if stage=='FAILED' else 0)
            cand.append({'ready':True,'name':'DOUBLE TOP','stage':stage,'neckline':neck,'extreme':top,'follow_side':'DOWN','score':_v220_clip(score)})
    if len(pl)>=2:
        a,b=pl[-2],pl[-1]
        if b-a>=3 and abs(lows[b]-lows[a])<=atr*.38:
            neck=max(highs[a:b+1]);bot=min(lows[a],lows[b]);
            stage='FAILED' if close<bot-atr*.15 else 'CONFIRMED' if close>neck+atr*.08 else 'CANDIDATE'
            m=float(mbi.get('forward_score',mbi.get('score',0)) or 0)
            score=50 + max(-25,min(25,m*.25)) + (18 if stage=='CONFIRMED' else -22 if stage=='FAILED' else 0)
            cand.append({'ready':True,'name':'DOUBLE BOTTOM','stage':stage,'neckline':neck,'extreme':bot,'follow_side':'UP','score':_v220_clip(score)})
    return cand[-1] if cand else {'ready':False,'name':'NONE','stage':'NONE','score':0.0}


# Keep a reference to the inherited dynamic route. V22 does not throw its work
# away; it makes it one evidence family instead of a trend-follow commandment.
_V220_BASE_DYNAMIC = _v268_dynamic_read


def _v220_terminal_read(self, now=None):
    now=float(now or time.time())
    base=dict(_V220_BASE_DYNAMIC(self,now=now) or {})
    noise=_v220_filtered_live(self,now=now)
    live=noise.get('price')
    levels=_v220_level_map(self,live=live)
    mbi=_v220_mbi(self,now=now);tug=_v220_tug(self,now=now)
    ceil_fc=_v220_barrier_forecast(self,levels.get('ceiling'), 'UP', live, noise, mbi, tug)
    floor_fc=_v220_barrier_forecast(self,levels.get('floor'), 'DOWN', live, noise, mbi, tug)

    # Route viability: UP needs the ceiling to break OR the floor to defend;
    # DOWN needs the floor to break OR the ceiling to reject.
    upv=.58*float(ceil_fc.get('break',50))+.42*float(floor_fc.get('reject',50))
    dnv=.58*float(floor_fc.get('break',50))+.42*float(ceil_fc.get('reject',50))
    barrier_signed=max(-1.0,min(1.0,(upv-dnv)/50.0))
    bside=str(base.get('route_side','NEUTRAL')).upper(); bconf=float(base.get('route_confidence',50) or 50)
    base_signed=_v220_sgn(bside)*max(0.0,min(1.0,(bconf-50)/48.0))
    mbi_signed=max(-1.0,min(1.0,float(mbi.get('forward_score',mbi.get('score',0)) or 0)/100.0))
    tug_signed=float(tug.get('signed',tug.get('score',0)) or 0)
    if abs(tug_signed)>1.5:tug_signed/=100.0
    tug_signed=max(-1.0,min(1.0,tug_signed))

    # IMPORTANT: inherited trend/current-position read is only 42% of terminal
    # score. Barrier journey owns the largest independent modifier.
    signed=max(-1.0,min(1.0,.42*base_signed+.36*barrier_signed+.14*mbi_signed+.08*tug_signed))
    cand='UP' if signed>=.09 else 'DOWN' if signed<=-.09 else 'NEUTRAL'
    st=dict(getattr(self,'_v220_terminal_state',{}) or {})
    old=str(st.get('side','NEUTRAL'))
    if cand in ('UP','DOWN') and cand!=old:
        if st.get('candidate')!=cand:
            st['candidate']=cand;st['candidate_since']=now;st['candidate_samples']=1
        else: st['candidate_samples']=int(st.get('candidate_samples',0) or 0)+1
        need=.55 if abs(signed)>=.34 else 1.15
        if now-float(st.get('candidate_since',now))>=need and st['candidate_samples']>=2:
            old=cand;st['side']=cand;st['side_since']=now;st['candidate']='NEUTRAL';st['candidate_samples']=0
            st['peak_edge']=max(.08,abs(signed));st['rev_hist']=[];st['health']='healthy'
    elif cand==old:
        st['candidate']='NEUTRAL';st['candidate_samples']=0
    elif cand=='NEUTRAL':
        st['candidate']='NEUTRAL';st['candidate_samples']=0
    side=str(st.get('side',old if old in ('UP','DOWN') else cand)).upper()
    if side not in ('UP','DOWN'):side=cand if cand in ('UP','DOWN') else 'NEUTRAL'

    # Cretonne v48 concept: meter measures degradation from the strongest edge
    # achieved after this terminal side was adopted. 100%=back to coin flip;
    # >100%=edge now points to the opposite side.
    sign=_v220_sgn(side);current_edge=signed*sign if sign else 0.0
    peak=max(float(st.get('peak_edge',.08) or .08),current_edge,.08);st['peak_edge']=peak
    reversal=max(0.0,(peak-current_edge)/peak*100.0) if side in ('UP','DOWN') else 0.0
    rh=deque(st.get('rev_hist',[]),maxlen=60);rh.append((now,reversal))
    while rh and now-rh[0][0]>12.0:rh.popleft()
    vel=0.0
    if len(rh)>=3:
        dt=rh[-1][0]-rh[0][0]
        if dt>0:vel=(rh[-1][1]-rh[0][1])/dt
    prev=str(st.get('health','healthy'))
    if prev=='invalid': health='invalid' if reversal>=80 else 'weak' if reversal>=35 else 'healthy'
    elif prev=='weak': health='invalid' if reversal>=100 else 'weak' if reversal>=35 else 'healthy'
    else: health='invalid' if reversal>=100 else 'weak' if reversal>=50 else 'healthy'
    st['health']=health;st['rev_hist']=list(rh);st['last_signed']=signed;self._v220_terminal_state=st

    pattern=_v220_double_pattern(self,live,mbi)
    # A price/odds shock without thesis deterioration is labeled as likely noise,
    # not an automatic reversal alarm.
    fakeout_guard = reversal < 35 and abs(float(noise.get('velocity',0) or 0)) > max(1.0,float(noise.get('atr',20))*0.10) and abs(vel)<4.0
    out={'ready':bool(live is not None),'ts':now,'live':live,'raw_live':noise.get('raw'),'source':noise.get('source'),
         'terminal_side':side,'terminal_signed':signed,'terminal_confidence':50+abs(signed)*48,
         'base_route':bside,'base_confidence':bconf,'levels':levels,'ceiling':ceil_fc,'floor':floor_fc,
         'up_viability':upv,'down_viability':dnv,'mbi':mbi,'tug':tug,'noise':noise,'reversal_pct':reversal,
         'reversal_velocity':vel,'reversal_health':health,'fakeout_guard':fakeout_guard,'pattern':pattern,
         'current_control':str(base.get('route_side','NEUTRAL')),'base':base}
    self._v220_last=out
    return out


def _v220_publish(self, out):
    if not out:return
    side=str(out.get('terminal_side','NEUTRAL'));rev=float(out.get('reversal_pct',0) or 0);vel=float(out.get('reversal_velocity',0) or 0)
    ceil=dict(out.get('ceiling') or {});floor=dict(out.get('floor') or {});pat=dict(out.get('pattern') or {})
    next_fc=ceil if side=='UP' else floor if side=='DOWN' else (ceil if float(ceil.get('distance',1e9))<=float(floor.get('distance',1e9)) else floor)
    level_word='CEILING' if next_fc is ceil else 'FLOOR'
    px=next_fc.get('level')
    breakv=float(next_fc.get('break',50) or 50);reject=float(next_fc.get('reject',50) or 50);hold=float(next_fc.get('hold',50) or 50)
    try:self._set_var_if_changed(self.reversal_score_var,f'TRANSFER METER {rev:.0f}% • {vel:+.1f}%/sec')
    except Exception:pass
    try:self._set_var_if_changed(self.reversal_direction_var,f'TERMINAL {side} • CURRENT CONTROL {out.get("current_control","NEUTRAL")}')
    except Exception:pass
    try:
        ltxt=f'{level_word} {money(px)} • BREAK {breakv:.0f} / REJECT {reject:.0f} • HOLD {hold:.0f}' if px else 'NEXT BARRIER: building'
        self._set_var_if_changed(self.reversal_action_var,ltxt)
    except Exception:pass
    try:
        m=dict(out.get('mbi') or {});fake=' • FAKEOUT GUARD: NO CONTROL TRANSFER' if out.get('fakeout_guard') else ''
        self._set_var_if_changed(self.reversal_evidence_var,f'MBI {float(m.get("forward_score",m.get("score",0)) or 0):+.0f} • route UP {float(out.get("up_viability",50)):.0f} / DOWN {float(out.get("down_viability",50)):.0f}{fake}')
    except Exception:pass
    try:
        ptxt=f'{pat.get("name")} {pat.get("stage")} • follow {pat.get("follow_side","--")} {float(pat.get("score",0)):.0f}/100' if pat.get('ready') else 'Pattern: no validated double-top/bottom setup'
        self._set_var_if_changed(self.pattern_var,ptxt)
        if hasattr(self,'pattern_state_var'):self._set_var_if_changed(self.pattern_state_var,ptxt)
    except Exception:pass
    try:
        self._set_var_if_changed(self.breakout_var,f'{level_word} {next_fc.get("status","BUILDING")} • breakout hold {hold:.0f}/100')
    except Exception:pass
    try:
        c=out.get('levels',{}).get('ceiling');f=out.get('levels',{}).get('floor')
        self._set_var_if_changed(self.sniper_ceiling_var,f'CEILING {money(c.get("price")) if c else "--"} • FLOOR {money(f.get("price")) if f else "--"}')
        self._set_var_if_changed(self.sniper_reason_var,f'ROUTE-FIRST: ceilings/floors decide journey; trend/current winner are context only. {level_word} forecast {next_fc.get("status","building")}.')
    except Exception:pass
    try:
        self._set_var_if_changed(self.projection_var,f'TERMINAL PATH {side} • next {level_word.lower()} {money(px)} • break {breakv:.0f} reject {reject:.0f} • reversal {rev:.0f}%')
    except Exception:pass
    try:
        self._set_var_if_changed(self.all_tf_consensus_var,'TREND = CONTEXT ONLY • route engine owns terminal pick')
    except Exception:pass
    try:
        self.trend_reversal_risk_value=min(100.0,rev)
        self._set_var_if_changed(self.trend_reversal_risk_var,f'CONTROL TRANSFER {rev:.0f}/100+')
        self._set_var_if_changed(self.trend_reversal_status_var,'FLIP CONFIRMED' if rev>=100 else 'REVERSAL BUILDING' if rev>=50 else 'ROUTE HEALTHY')
        self._set_var_if_changed(self.trend_reversal_detail_var,f'Cretonne-style edge decay • {rev:.0f}% • velocity {vel:+.1f}%/sec • {next_fc.get("status","barrier building")}')
        try:self._draw_trend_risk_bar()
        except Exception:pass
    except Exception:pass
    try:
        self._set_var_if_changed(self.ai_next_var,f'END RESULT: {side} • {level_word} {money(px)} • BREAK {breakv:.0f} / REJECT {reject:.0f} • REVERSAL {rev:.0f}%')
    except Exception:pass


# Restrict chart TFs and destroy the costly buttons after inherited UI builds.
def _v220_prune_chart_tfs(self):
    allowed_bookmap={'15s':15,'1m':60,'3m':180,'5m':300,'15m':900,'30m':1800,'1H':3600}
    allowed_kalshi={'1m':60,'3m':180,'5m':300,'15m':900,'30m':1800,'1H':3600}
    self.chart_tf_options=dict(allowed_bookmap if _V220_SOURCE_MODE=='BOOKMAP' else allowed_kalshi)
    self.tf_zoom_memory={k:v for k,v in getattr(self,'tf_zoom_memory',{}).items() if k in self.chart_tf_options}
    if str(self.chart_tf_var.get()) not in self.chart_tf_options:
        self.chart_tf_var.set('15m');self.chart_interval_seconds=900
    kill={'3s','5s','30s','4H','1s'}
    def walk(w):
        try:
            for ch in list(w.winfo_children()):
                try:
                    if isinstance(ch,tk.Button) and str(ch.cget('text')) in kill: ch.destroy();continue
                except Exception:pass
                walk(ch)
        except Exception:pass
    walk(self.root)
    try:self._set_var_if_changed(self.chart_tf_status_var,f'Chart {self.chart_tf_var.get()} • V22 lean TF set • 3s/5s/30s/4H removed')
    except Exception:pass


_V220_BASE_INIT=ChartKingPro.__init__
def _v220_init(self,*a,**kw):
    _V220_BASE_INIT(self,*a,**kw)
    self._v220_terminal_state={'side':'NEUTRAL','candidate':'NEUTRAL','candidate_samples':0,'peak_edge':.08,'rev_hist':[],'health':'healthy'}
    self._v220_noise_state={}
    self._v220_last={}
    self.v220_source_mode=_V220_SOURCE_MODE
    try:self.root.after(50,lambda s=self:_v220_prune_chart_tfs(s))
    except Exception:pass
    try:self.root.title(f'LECHART JAMES V22.0 — ROUTE-FIRST • {_V220_SOURCE_MODE}')
    except Exception:pass
ChartKingPro.__init__=_v220_init


