# ============================================================================
# V22.1 NOISE-HARDENED + CLEAN-CHART PATCH
# ============================================================================
# Goals:
#   * remove ALL sub-minute chart intervals and 4H from the live chart
#   * stop 3s/5s candle aggregation entirely
#   * disable 15s/30s micro-flip authority (major noise source)
#   * harden the Cretonne-style reversal meter with robust time aggregation,
#     persistence, hysteresis and capped step size
#   * keep the same Le Chart James desktop/UI in Bookmap and standalone builds
#   * keep the chart visually clean: candles + target + essential floor/ceiling
# ============================================================================

_V221_ALLOWED_TFS = {'1m':60,'3m':180,'5m':300,'15m':900,'30m':1800,'1H':3600}
_V221_REMOVED_TFS = {'1s','3s','5s','15s','30s','4H'}

# 1) Stop generating exact 3s/5s bars. They are not displayed and no longer
#    feed reversal logic. This removes per-execution candle bookkeeping.
def _v221_no_micro_candle(self, seconds, event_ts, price, size):
    return
ChartKingPro._ingest_bookmap_micro_candle = _v221_no_micro_candle

# 2) Disable all sub-minute micro-flip reads. Keep the method shape so old
#    callers remain safe, but it contributes zero danger/authority.
def _v221_micro_threshold(self, seconds, *args, **kwargs):
    sec = int(seconds or 0)
    if sec < 60:
        return {
            'ready': False, 'seconds': sec, 'crossed': False,
            'confirmed_micro': False, 'danger_score': 0.0,
            'likely_flip_to': None, 'level': None,
            'text': f'{sec}s DISABLED • V22.1 uses 1m+ structure only'
        }
    try:
        return _V221_BASE_MICRO_THRESHOLD(self, seconds, *args, **kwargs)
    except Exception:
        return {'ready': False, 'seconds': sec, 'text': 'micro disabled'}
_V221_BASE_MICRO_THRESHOLD = ChartKingPro._micro_flip_threshold
ChartKingPro._micro_flip_threshold = _v221_micro_threshold

def _v221_micro_intel(self):
    result = {
        'ready': False,
        'fifteen': {'ready': False, 'text': '15s DISABLED'},
        'thirty': {'ready': False, 'text': '30s DISABLED'},
        'danger_score': 0.0, 'both_confirmed': False,
        'text': 'SUB-MINUTE MICRO FLIP DISABLED • 1m+ route/reversal engine owns decisions'
    }
    self.micro_flip_last = result
    return result
ChartKingPro._micro_flip_intelligence = _v221_micro_intel

# 3) Lean timeframe hard gate. This is not just cosmetic: the options map is
#    replaced so hidden second-based intervals cannot be selected internally.
_V221_BASE_SET_TF = ChartKingPro.set_chart_timeframe
def _v221_set_tf(self, label):
    label = str(label)
    if label not in _V221_ALLOWED_TFS:
        try: self.chart_tf_status_var.set(f'{label} disabled • V22.1 chart uses 1m/3m/5m/15m/30m/1H only')
        except Exception: pass
        return
    return _V221_BASE_SET_TF(self, label)
ChartKingPro.set_chart_timeframe = _v221_set_tf

def _v221_prune_tfs(self):
    self.chart_tf_options = dict(_V221_ALLOWED_TFS)
    self.tf_zoom_memory = {k:v for k,v in getattr(self,'tf_zoom_memory',{}).items() if k in _V221_ALLOWED_TFS}
    try:
        current = str(self.chart_tf_var.get())
    except Exception:
        current = '15m'
    if current not in _V221_ALLOWED_TFS:
        try: self.chart_tf_var.set('15m')
        except Exception: pass
        self.chart_interval_seconds = 900
    # remove any already-rendered buttons, including later UI revisions
    def walk(widget):
        try:
            for child in list(widget.winfo_children()):
                try:
                    txt = str(child.cget('text'))
                    if txt in _V221_REMOVED_TFS:
                        child.destroy(); continue
                except Exception:
                    pass
                walk(child)
        except Exception:
            pass
    walk(self.root)
    try:
        self.micro_flip_var.set('MICRO FLIP: OFF • 1m+ only')
        self.micro_flip_detail_var.set('15s/30s reversal authority removed in V22.1 noise-hardened build.')
    except Exception:
        pass
    try: self.chart_tf_status_var.set(f'Chart {self.chart_tf_var.get()} • 1m+ CLEAN TF SET')
    except Exception: pass

# 4) Visual cleanup. Chart-only FVG/trendline overlays are disabled, while the
#    underlying analysis modules remain available to the brain/panels.
_V221_BASE_OVERLAY_BUNDLE = ChartKingPro._chart_overlay_bundle
def _v221_clean_overlay_bundle(self, candles):
    return {'fvgs': [], 'trend': {'support_line': None, 'resistance_line': None, 'story': 'CLEAN CHART • route levels only'}}
ChartKingPro._chart_overlay_bundle = _v221_clean_overlay_bundle

_V221_BASE_FVG_STORY = ChartKingPro.chart_interval_fvg_story
def _v221_blank_fvg_story(self, candles, fvgs):
    return ''
ChartKingPro.chart_interval_fvg_story = _v221_blank_fvg_story

# During chart painting only, suppress the whale/wave HUD. The Bookmap flow
# readers still run normally for the decision engine outside draw_chart().
_V221_BASE_DRAW = ChartKingPro.draw_chart
def _v221_draw_clean(self):
    had_whale = '_bookmap_whale_read' in self.__dict__
    had_wave = '_bookmap_wave_read' in self.__dict__
    old_whale = self.__dict__.get('_bookmap_whale_read')
    old_wave = self.__dict__.get('_bookmap_wave_read')
    try:
        self._bookmap_whale_read = lambda *a, **k: {'ready': False}
        self._bookmap_wave_read = lambda *a, **k: {'ready': False}
        _V221_BASE_DRAW(self)
    finally:
        if had_whale: self.__dict__['_bookmap_whale_read'] = old_whale
        else: self.__dict__.pop('_bookmap_whale_read', None)
        if had_wave: self.__dict__['_bookmap_wave_read'] = old_wave
        else: self.__dict__.pop('_bookmap_wave_read', None)
    # Draw only the two route levels on top of the clean candle chart.
    try:
        snap = dict(getattr(self, '_v220_last', {}) or {})
        levels = dict(snap.get('levels') or {})
        scale = dict(getattr(self, '_v82_chart_scale', {}) or {})
        lo, hi = float(scale['lo']), float(scale['hi'])
        top, ph = float(scale['top']), float(scale['ph'])
        left, right = float(scale['left']), float(scale['plot_right'])
        if hi > lo:
            def yy(px): return top + (hi - float(px)) / (hi - lo) * ph
            for key, color, label in (('ceiling', RED, 'ROUTE CEILING'), ('floor', GREEN, 'ROUTE FLOOR')):
                row = levels.get(key)
                if not row or row.get('price') is None: continue
                px = float(row['price']); y = yy(px)
                if y < top - 4 or y > top + ph + 4: continue
                self.canvas.create_line(left, y, right, y, fill=color, dash=(7,5), width=2)
                self.canvas.create_text(right-6, y-9, text=f'{label} {money(px)}', fill=color, anchor='e', font=('Segoe UI',8,'bold'))
    except Exception:
        pass
ChartKingPro.draw_chart = _v221_draw_clean

# 5) Stronger route/reversal noise filter. The V22 route calculation still
#    produces the raw thesis; V22.1 robustly aggregates it before the terminal
#    side and reversal meter are allowed to move.
_V221_BASE_TERMINAL = _v220_terminal_read

def _v221_median(vals, default=0.0):
    vals = sorted(float(v) for v in vals if v is not None and math.isfinite(float(v)))
    if not vals: return float(default)
    n = len(vals)
    return vals[n//2] if n % 2 else (vals[n//2-1] + vals[n//2]) * 0.5

def _v221_terminal_read(self, now=None):
    now = float(now or time.time())
    raw = dict(_V221_BASE_TERMINAL(self, now=now) or {})
    raw_signed = max(-1.0, min(1.0, float(raw.get('terminal_signed', 0.0) or 0.0)))
    mode = str(getattr(self, 'v220_source_mode', globals().get('_V220_SOURCE_MODE','BOOKMAP'))).upper()
    is_bm = mode == 'BOOKMAP'
    st = dict(getattr(self, '_v221_noise_harden', {}) or {})

    # Robust time aggregation of the route score. Bookmap gets the heavier
    # filter; Kalshi/BRTI stays cleaner/faster by design.
    hist = deque(st.get('signed_hist', []), maxlen=120)
    hist.append((now, raw_signed))
    window = 4.0 if is_bm else 2.0
    while hist and now - hist[0][0] > window:
        hist.popleft()
    recent = [v for t,v in hist if now - t <= (2.6 if is_bm else 1.25)]
    robust = _v221_median(recent, raw_signed)
    prev = float(st.get('stable_signed', robust))
    alpha = 0.22 if is_bm else 0.40
    delta = (robust - prev) * alpha
    # Cap the FINAL filtered move, not the raw delta. This still rejects a
    # one-tick shock via the robust median, but a real persistent control
    # transfer can move the brain meaningfully within several seconds.
    max_step = 0.025 if is_bm else 0.050
    delta = max(-max_step, min(max_step, delta))
    stable = max(-1.0, min(1.0, prev + delta))

    # Persistence is the fraction of recent non-neutral samples agreeing with
    # the robust sign. This prevents a single tick shock from creating a flip.
    signs = [1 if v > .04 else -1 if v < -.04 else 0 for _t,v in hist]
    nz = [s for s in signs if s]
    persistence = abs(sum(nz)) / len(nz) if nz else 0.0

    side = str(st.get('side', raw.get('terminal_side','NEUTRAL'))).upper()
    if side not in ('UP','DOWN'):
        side = 'UP' if stable >= .12 else 'DOWN' if stable <= -.12 else 'NEUTRAL'
    candidate = 'UP' if stable >= .13 else 'DOWN' if stable <= -.13 else 'NEUTRAL'
    if candidate in ('UP','DOWN') and candidate != side:
        if st.get('candidate') != candidate:
            st['candidate'] = candidate; st['candidate_since'] = now; st['candidate_samples'] = 1
        else:
            st['candidate_samples'] = int(st.get('candidate_samples',0) or 0) + 1
        need = 2.25 if is_bm else 1.0
        samples_need = 6 if is_bm else 3
        if (now - float(st.get('candidate_since',now)) >= need and
                int(st.get('candidate_samples',0)) >= samples_need and persistence >= (0.68 if is_bm else 0.58)):
            side = candidate
            st['side'] = side; st['side_since'] = now
            st['candidate'] = 'NEUTRAL'; st['candidate_samples'] = 0
            st['peak_edge'] = max(.10, abs(stable)); st['meter'] = 0.0
            st['meter_hist'] = []; st['raw_rev_hist'] = []
    elif candidate == side:
        st['candidate'] = 'NEUTRAL'; st['candidate_samples'] = 0
    elif candidate == 'NEUTRAL':
        st['candidate'] = 'NEUTRAL'; st['candidate_samples'] = 0

    sign = 1.0 if side == 'UP' else -1.0 if side == 'DOWN' else 0.0
    edge = stable * sign if sign else 0.0
    peak = max(float(st.get('peak_edge', .10) or .10), edge, .10)
    st['peak_edge'] = peak
    raw_rev = max(0.0, (peak - edge) / peak * 100.0) if sign else 0.0

    rr = deque(st.get('raw_rev_hist', []), maxlen=100)
    rr.append((now, raw_rev))
    while rr and now - rr[0][0] > (3.0 if is_bm else 1.8): rr.popleft()
    robust_rev = _v221_median([v for _t,v in rr], raw_rev)
    meter = float(st.get('meter', 0.0) or 0.0)

    # Rise requires persistence and is capped. Fall/repair also happens
    # gradually so the meter cannot chatter around thresholds.
    rising = robust_rev > meter + (6.0 if is_bm else 4.0)
    if rising and persistence >= (0.58 if is_bm else 0.48):
        if not st.get('rise_since'): st['rise_since'] = now
        if now - float(st.get('rise_since', now)) >= (0.85 if is_bm else 0.35):
            max_jump = 4.5 if is_bm else 8.0
            meter += min(max_jump, max(0.0, (robust_rev - meter) * (0.12 if is_bm else 0.24)))
    else:
        st['rise_since'] = None
        if robust_rev < meter:
            meter -= min(3.0 if is_bm else 5.0, max(0.0, (meter - robust_rev) * (0.10 if is_bm else 0.18)))
    meter = max(0.0, min(180.0, meter))

    mh = deque(st.get('meter_hist', []), maxlen=100)
    mh.append((now, meter))
    while mh and now - mh[0][0] > 10.0: mh.popleft()
    vel = 0.0
    if len(mh) >= 3:
        dt = mh[-1][0] - mh[0][0]
        if dt > 0: vel = (mh[-1][1] - mh[0][1]) / dt

    prev_health = str(st.get('health','healthy'))
    if prev_health == 'invalid':
        health = 'invalid' if meter >= 82 else 'weak' if meter >= 38 else 'healthy'
    elif prev_health == 'weak':
        health = 'invalid' if meter >= 103 else 'weak' if meter >= 38 else 'healthy'
    else:
        health = 'invalid' if meter >= 103 else 'weak' if meter >= 55 else 'healthy'

    st.update({'signed_hist':list(hist),'stable_signed':stable,'side':side,
               'raw_rev_hist':list(rr),'meter':meter,'meter_hist':list(mh),
               'health':health})
    self._v221_noise_harden = st

    raw['raw_terminal_signed'] = raw_signed
    raw['terminal_signed'] = stable
    raw['terminal_side'] = side
    raw['terminal_confidence'] = 50.0 + abs(stable) * 48.0
    raw['raw_reversal_pct'] = raw_rev
    raw['reversal_pct'] = meter
    raw['reversal_velocity'] = vel
    raw['reversal_health'] = health
    raw['signal_persistence'] = persistence
    raw['noise_filter_status'] = ('BOOKMAP HARD FILTER' if is_bm else 'KALSHI/BRTI CLEAN FILTER')
    raw['fakeout_guard'] = bool(raw_rev >= 35 and meter < 28) or bool(raw.get('fakeout_guard'))
    return raw
_v220_terminal_read = _v221_terminal_read

# 6) Publish filter status in an existing compact field instead of adding more
#    chart clutter.
_V221_BASE_PUBLISH = _v220_publish
def _v221_publish(self, out):
    _V221_BASE_PUBLISH(self, out)
    try:
        filt = str(out.get('noise_filter_status','FILTER'))
        pers = float(out.get('signal_persistence',0) or 0) * 100.0
        rawr = float(out.get('raw_reversal_pct',0) or 0)
        shown = float(out.get('reversal_pct',0) or 0)
        self._set_var_if_changed(self.reversal_evidence_var,
            f'{self.reversal_evidence_var.get()} • {filt} • persistence {pers:.0f}% • raw meter {rawr:.0f} → filtered {shown:.0f}')
    except Exception:
        pass
_v220_publish = _v221_publish

# 7) Shared UI polish. Standalone and Bookmap intentionally use the same LCJ UI.
_V221_PREV_INIT = ChartKingPro.__init__
def _v221_init(self, *a, **kw):
    _V221_PREV_INIT(self, *a, **kw)
    self._v221_noise_harden = {}
