def _v222_rebuild_tf_bar(app):
    """Destroy every stale timeframe button and rebuild from the final allow-list."""
    try:
        app.chart_tf_options = dict(_V222_ALLOWED_TFS)
        app.tf_zoom_memory = {k:v for k,v in getattr(app,'tf_zoom_memory',{}).items() if k in _V222_ALLOWED_TFS}
        for k,v in {'1m':60,'3m':55,'5m':48,'15m':40,'30m':38,'1H':34}.items():
            app.tf_zoom_memory.setdefault(k,v)
        cur=str(app.chart_tf_var.get())
        if cur not in _V222_ALLOWED_TFS:
            app.chart_tf_var.set('15m');app.chart_interval_seconds=900
    except Exception:
        pass

    # Remove stale buttons anywhere in the widget tree.
    def walk(w):
        try: kids=list(w.winfo_children())
        except Exception:return
        for ch in kids:
            try:
                txt=str(ch.cget('text')).strip()
                if txt in _V222_REMOVED_TFS:
                    ch.destroy();continue
            except Exception:pass
            walk(ch)
    try:walk(app.root)
    except Exception:pass

    # The polished cockpit has its own button dictionary. Rebuild that exact bar.
    try:
        old=dict(getattr(app,'v2676_tf_buttons',{}) or {})
        parent=next((b.master for b in old.values() if b is not None and b.winfo_exists()),None)
        if parent is not None:
            for b in old.values():
                try:b.destroy()
                except Exception:pass
            app.v2676_tf_buttons={}
            selected=str(app.chart_tf_var.get())
            for tf in _V280_TF_UI:
                active=(tf==selected)
                btn=tk.Button(parent,text=tf,command=lambda t=tf:app.set_chart_timeframe(t),
                    bg=_V2676_BLUE_DARK if active else _V2676_PANEL2,
                    fg=_V2676_TEXT if active else _V2676_MUTED,
                    activebackground=_V2676_BLUE_DARK,activeforeground=_V2676_TEXT,
                    relief='flat',highlightthickness=1,
                    highlightbackground=_V2676_BLUE if active else _V2676_BORDER,
                    padx=8,pady=4,font=('Cascadia Mono',8,'bold'))
                btn.pack(side='left',padx=(0,4));app.v2676_tf_buttons[tf]=btn
    except Exception:
        pass

