# Stronger Bookmap shock/persistence filter. The route engine still sees the
# fast tape, but a transient burst cannot immediately switch terminal control.
_V222_BASE_TERMINAL = _v220_terminal_read
def _v222_terminal_read(self, now=None):
    now=float(now or time.time())
    raw=dict(_V222_BASE_TERMINAL(self,now=now) or {})
    mode=str(getattr(self,'v220_source_mode',globals().get('_V220_SOURCE_MODE','BOOKMAP'))).upper()
    is_bm=(mode=='BOOKMAP')
    x=max(-1.0,min(1.0,float(raw.get('terminal_signed',0.0) or 0.0)))
    st=dict(getattr(self,'_v222_filter_state',{}) or {})
    hist=deque(st.get('hist',[]),maxlen=300);hist.append((now,x))
    keep=8.0 if is_bm else 3.5
    while hist and now-hist[0][0]>keep:hist.popleft()
    core_window=5.0 if is_bm else 2.0
    vals=[v for t,v in hist if now-t<=core_window]
    if not vals: vals=[x]
    ordered=sorted(vals)
    trim=max(0,int(len(ordered)*0.15))
    core=ordered[trim:len(ordered)-trim] if len(ordered)-2*trim>=3 else ordered
    robust=sum(core)/max(1,len(core))
    med=ordered[len(ordered)//2]
    robust=0.58*med+0.42*robust
    prev=float(st.get('stable',robust))
    alpha=.10 if is_bm else .28
    max_step=.010 if is_bm else .035
    delta=max(-max_step,min(max_step,(robust-prev)*alpha))
    stable=max(-1.0,min(1.0,prev+delta))
    # Ignore tiny oscillations around neutral.
    if abs(stable)<(.055 if is_bm else .035):stable=0.0
    desired='UP' if stable>=.12 else 'DOWN' if stable<=-.12 else 'NEUTRAL'
    recent=[v for t,v in hist if now-t<=(4.0 if is_bm else 1.6)]
    same=sum(1 for v in recent if (v>.04 and desired=='UP') or (v<-.04 and desired=='DOWN'))
    persistence=same/max(1,len(recent)) if desired!='NEUTRAL' else 0.0
    side=str(st.get('side',raw.get('terminal_side','NEUTRAL'))).upper()
    candidate=str(st.get('candidate','NEUTRAL'));since=float(st.get('candidate_since',0) or 0)
    if desired in ('UP','DOWN') and desired!=side:
        need=.74 if is_bm else .60
        hold=2.2 if is_bm else .65
        if persistence>=need:
            if candidate!=desired:candidate=desired;since=now
            elif now-since>=hold:side=desired;candidate='NEUTRAL';since=0.0
        else:candidate='NEUTRAL';since=0.0
    elif desired==side:
        candidate='NEUTRAL';since=0.0
    elif desired=='NEUTRAL' and abs(stable)<.07:
        # neutral does not instantly erase a valid side; it simply lowers confidence
        candidate='NEUTRAL';since=0.0

    sign=1.0 if side=='UP' else -1.0 if side=='DOWN' else 0.0
    edge=stable*sign if sign else 0.0
    peak=max(.08,float(st.get('peak',.08) or .08),edge)
    raw_rev=max(0.0,(peak-edge)/peak*100.0) if sign else 0.0
    rh=deque(st.get('rev_hist',[]),maxlen=200);rh.append((now,raw_rev))
    while rh and now-rh[0][0]>(5.0 if is_bm else 2.0):rh.popleft()
    rvals=sorted(v for _t,v in rh);rob_rev=rvals[len(rvals)//2] if rvals else raw_rev
    meter=float(st.get('meter',0.0) or 0.0)
    rise=rob_rev>meter+(8 if is_bm else 5)
    rise_since=st.get('rise_since')
    if rise and persistence>=(.68 if is_bm else .50):
        if rise_since is None:rise_since=now
        if now-float(rise_since)>=(1.35 if is_bm else .45):
            meter += min(3.0 if is_bm else 6.0,max(0.0,(rob_rev-meter)*(.08 if is_bm else .18)))
    else:
        rise_since=None
        if rob_rev<meter:meter-=min(2.0 if is_bm else 4.0,max(0.0,(meter-rob_rev)*(.08 if is_bm else .15)))
    meter=max(0.0,min(180.0,meter))
    health='invalid' if meter>=103 else 'weak' if meter>=55 else 'healthy'
    st.update({'hist':list(hist),'stable':stable,'side':side,'candidate':candidate,'candidate_since':since,
               'peak':peak,'rev_hist':list(rh),'meter':meter,'rise_since':rise_since,'health':health})
    self._v222_filter_state=st
    raw.update({'raw_terminal_signed_v222':x,'terminal_signed':stable,'terminal_side':side,
                'terminal_confidence':50+abs(stable)*48,'raw_reversal_pct_v222':raw_rev,
                'reversal_pct':meter,'reversal_health':health,'signal_persistence_v222':persistence,
                'noise_filter_status':'V22.2 PERSISTENCE FILTER'})
    return raw
_v220_terminal_read = _v222_terminal_read

