def _v224_median(vals, default=0.0):
    a=[]
    for v in vals:
        try:
            x=float(v)
            if math.isfinite(x):a.append(x)
        except Exception:pass
    if not a:return float(default)
    a.sort();n=len(a)
    return a[n//2] if n%2 else (a[n//2-1]+a[n//2])*0.5

def _v224_terminal_read(self, now=None):
    now=float(now or time.time());out=dict(_V224_PREV_TERMINAL(self,now=now) or {})
    mode=str(getattr(self,'v220_source_mode',globals().get('_V220_SOURCE_MODE','BOOKMAP'))).upper();is_bm=(mode=='BOOKMAP')
    st=dict(getattr(self,'_v224_meter_filter',{}) or {})
    raw=float(out.get('reversal_pct',0.0) or 0.0);pers=float(out.get('signal_persistence_v222',out.get('signal_persistence',0.0)) or 0.0)
    hist=deque(st.get('hist',[]),maxlen=400);hist.append((now,raw));lookback=7.0 if is_bm else 5.0
    while hist and now-hist[0][0]>lookback:hist.popleft()
    target=_v224_median([v for t,v in hist if now-t<=(5.0 if is_bm else 3.0)],raw)
    shown=float(st.get('shown',0.0) or 0.0);last=float(st.get('ts',now) or now);dt=max(0.0,min(.30,now-last))
    if abs(target-shown)<4.0:target=shown
    need_p=.80 if is_bm else .70
    rising=(target>shown+5.0 and pers>=need_p)
    rs=float(st.get('rise_since',0.0) or 0.0)
    if rising:
        if not rs:rs=now
    else:rs=0.0
    if rising and now-rs>=(1.8 if is_bm else 1.0):
        shown=min(target,shown+(6.0 if is_bm else 9.0)*dt)
    elif target<shown:
        shown=max(target,shown-(4.0 if is_bm else 6.0)*dt)
    cs=float(st.get('cross_since',0.0) or 0.0)
    if target>=110 and pers>=need_p:
        if not cs:cs=now
    else:cs=0.0
    if shown>=99 and not (cs and now-cs>=(2.8 if is_bm else 1.6)):shown=min(shown,99.0)
    shown=max(0.0,min(180.0,shown));st.update({'hist':list(hist),'shown':shown,'ts':now,'rise_since':rs,'cross_since':cs,'raw':raw,'target':target})
    self._v224_meter_filter=st
    out['raw_reversal_pct_v224']=raw;out['reversal_pct']=shown
    out['reversal_health']='invalid' if shown>=100 else 'weak' if shown>=55 else 'healthy'
    return out
_v220_terminal_read=_v224_terminal_read

_V224_BASE_PRIORITY=_v297_priority_refresh

def _v224_slew_ui(app,key,target,up_rate,down_rate,now):
    store=dict(getattr(app,'_v224_ui_slew',{}) or {});row=dict(store.get(key,{}) or {})
    prev=float(row.get('value',target) if row else target);last=float(row.get('ts',now) or now);dt=max(0.0,min(.30,now-last));delta=float(target)-prev
    if abs(delta)<3.0:value=prev
    elif delta>0:value=prev+min(delta,up_rate*dt)
    else:value=prev-max(delta,-down_rate*dt)
    value=max(0.0,min(100.0,value));store[key]={'value':value,'ts':now,'raw':float(target)};app._v224_ui_slew=store;return value

