        flip=_v224_slew_ui(app,'flip',float(raw_flip),4.5 if mode=='BOOKMAP' else 7.0,3.5 if mode=='BOOKMAP' else 5.0,now)
        app.v297_flip_var.set(f'{flip:.0f}%')
