# 1) Stronger target extraction, including plain five/six-digit values in text.
_V225_BASE_EXTRACT_TARGET = ChartKingPro._extract_target
def _v225_extract_target(self, market):
    t=_V225_BASE_EXTRACT_TARGET(self,market)
    if t is not None:return t
    if not isinstance(market,dict):return None
    for k in ('strike','strike_price','target_price','reference_price','price_to_beat','floor_strike','functional_strike','cap_strike'):
        try:
            x=float(str(market.get(k,'')).replace('$','').replace(',','').strip())
            if 1000.0 < x < 10000000.0:return x
        except Exception:pass
    text=' '.join(str(market.get(k,'')) for k in ('title','subtitle','yes_sub_title','no_sub_title','rules_primary','rules_secondary'))
    for s in re.findall(r'(?<!\d)([1-9]\d{4,6}(?:\.\d+)?)(?!\d)',text):
        try:
            x=float(s)
            if 1000.0 < x < 10000000.0:return x
        except Exception:pass
    return None
ChartKingPro._extract_target=_v225_extract_target

# 2) Reuse the credentials the ORIGINAL app already knows about. V22.3/4's
# standalone auth finder ignored these UI-backed values, which is why BRTI died.
_V225_BASE_PREPARE_AUTH=_v2985_prepare_auth
def _v225_prepare_auth(self, force=False):
    try:
        key_id=str(getattr(getattr(self,'kalshi_key_id_var',None),'get',lambda:'' )() or '').strip()
    except Exception:key_id=''
    pem_text=str(getattr(self,'kalshi_private_key_text','') or '').strip()
    try:pem_path=str(getattr(getattr(self,'kalshi_private_key_path_var',None),'get',lambda:'' )() or '').strip()
    except Exception:pem_path=''
    if pem_path and not pem_text:
        try:pem_text=Path(pem_path).read_text(encoding='utf-8').strip()
        except Exception:pass
    if key_id and pem_text:
        try:
            from cryptography.hazmat.primitives import serialization as _ser
            private=_ser.load_pem_private_key(pem_text.encode('utf-8'),password=None)
            auth={'ready':True,'key_id':key_id,'private':private,'pem_path':pem_path,'signer':'','source':'APP CREDENTIALS','error':''}
            self._v2985_auth=auth
            return auth
        except Exception as exc:
            pass
    return _V225_BASE_PREPARE_AUTH(self,force=force)
_v2985_prepare_auth=_v225_prepare_auth

# 3) Native BRTI bridge. Prefer the app's already-proven websocket implementation;
# fall back to signed REST; if auth is absent, keep the chart alive from the
# original public BTC live feed and label it honestly rather than showing nothing.
def _v225_brt_worker(self):
    self._v2985_feed_state='KALSHI BRTI • connecting...'
    used_native=False
    try:
        # Native websocket path uses the same credentials/settings as the original bot.
        self._start_brti_websocket(); used_native=True
    except Exception:
        used_native=False
    last_public_start=0.0
    last_rest=0.0
    while getattr(self,'running',False) and getattr(self,'live_feed_active',False):
        now=time.time(); got=False
        if used_native:
            try:
                # Drain original BRTI packets, then mirror the official index into V22 candle storage.
                if self._drain_brti_ticks():
                    px=float(getattr(self,'brti_price',0) or 0); ts=float(getattr(self,'brti_tick_ts',now) or now)
                    if 1000.0 < px < 10000000.0:
                        _v2985_ingest_points(self,[(ts,px)],bootstrap=False);got=True
                        self._v2985_feed_state=f'KALSHI BRTI LIVE • BTC ${px:,.2f}'
            except Exception:pass
        if not got and now-last_rest>=1.0:
            last_rest=now
            try:
                auth=_v2985_prepare_auth(self)
                if auth.get('ready'):
                    _v2985_fetch_latest(self);px=float(getattr(self,'current_spot',0) or 0)
                    if px>1000:
                        got=True;self._v2985_feed_state=f'KALSHI BRTI LIVE • BTC ${px:,.2f}'
            except Exception as exc:
                self._v2985_feed_state='KALSHI BRTI RETRY • '+str(exc)[:110]
        if not got:
            # Fail-open chart: original public live BTC transport, never mislabeled as Kalshi.
            try:
                if now-last_public_start>5.0:
                    self._start_kraken_live();last_public_start=now
                self._drain_kraken_ticks()
                px=float(getattr(self,'current_spot',0) or 0);ts=float(getattr(self,'kraken_tick_ts',now) or now)
                if px>1000:
                    _v2985_ingest_points(self,[(ts,px)],bootstrap=False)
                    self._v2985_feed_state=f'PUBLIC BTC FALLBACK • ${px:,.2f} • BRTI AUTH WAITING'
            except Exception as exc:
                self._v2985_feed_state='PRICE FEED WAITING • '+str(exc)[:100]
        time.sleep(.20)
_v2985_brt_worker=_v225_brt_worker

# 4) Target watchdog: do not make target acquisition a one-shot round callback.
# Retry until a real Kalshi target exists, and refresh at rollover.
def _v225_target_watch(self):
    try:
        if not getattr(self,'running',False):return
        now=time.time();bucket=int(now//900)*900
        target=getattr(self,'target_price',None)
        valid=False
        try:valid=1000.0<float(target)<10000000.0
        except Exception:valid=False
        current_bucket=getattr(self,'_v225_target_bucket',None)
        need=(not valid) or current_bucket!=bucket
        inflight=bool(getattr(self,'_v225_target_inflight',False))
        if need and not inflight:
            self._v225_target_inflight=True
            def worker(app=self,b=bucket):
                try:
                    m=app._discover_current_kalshi_market()
                    app.root.after(0,lambda mm=m,bb=b,a=app:_v225_commit_auto_target(a,mm,bb))
                except Exception as exc:
                    app.root.after(0,lambda e=str(exc),a=app:_v225_target_error(a,e))
            threading.Thread(target=worker,name='LCJ-V225-TargetWatch',daemon=True).start()
    finally:
        try:self.root.after(2000,lambda s=self:_v225_target_watch(s))
        except Exception:pass

def _v225_commit_auto_target(app,market,bucket):
    try:
        _v2985_commit_market(app,market,'AUTO CURRENT')
        app._v225_target_bucket=bucket
    finally:app._v225_target_inflight=False

def _v225_target_error(app,error):
    app._v225_target_inflight=False
    try:app.auto_target_status_var.set('AUTO TARGET RETRY • '+str(error)[:120])
    except Exception:pass

