        def calm(key,raw,rate=2.2,dead=4.0):
            row=dict(store.get(key,{}) or {});prev=float(row.get('v',raw));last=float(row.get('t',now));dt=max(.0,min(.35,now-last))
            d=float(raw)-prev
            if abs(d)<=dead:v=prev
            else:v=prev+max(-rate*dt,min(rate*dt,d))
