# ============================================================================
# V22.5.1 — TARGET QUEUE FIX + MID-ROUND LOCK FIX
# ============================================================================
# Tkinter cannot safely be scheduled from arbitrary worker threads on every
# Windows build. Workers now publish plain Python results; the Tk heartbeat
# consumes them on the main thread. This directly fixes AUTO target crashes/
# silent failures seen in the standalone build.
def _v2251_target_watch(self):
    try:
        if not getattr(self,'running',False):return
        # Commit worker result on the Tk/main thread.
        pending=getattr(self,'_v2251_target_result',None)
        if pending is not None:
            self._v2251_target_result=None;self._v225_target_inflight=False
            ok,payload,bucket=pending
            if ok:
                try:
                    _v2985_commit_market(self,payload,'AUTO CURRENT')
                    self._v225_target_bucket=bucket
                except Exception as exc:
                    try:self.auto_target_status_var.set('AUTO TARGET COMMIT RETRY • '+str(exc)[:110])
                    except Exception:pass
            else:
                try:self.auto_target_status_var.set('AUTO TARGET RETRY • '+str(payload)[:120])
                except Exception:pass
        now=time.time();bucket=int(now//900)*900
        try:valid=1000.0<float(getattr(self,'target_price',0) or 0)<10000000.0
        except Exception:valid=False
        need=(not valid) or getattr(self,'_v225_target_bucket',None)!=bucket
        if need and not bool(getattr(self,'_v225_target_inflight',False)):
            self._v225_target_inflight=True
            def worker(app=self,b=bucket):
                try:app._v2251_target_result=(True,app._discover_current_kalshi_market(),b)
                except Exception as exc:app._v2251_target_result=(False,str(exc),b)
            threading.Thread(target=worker,name='LCJ-V2251-TargetWatch',daemon=True).start()
    finally:
        try:self.root.after(750,lambda s=self:_v2251_target_watch(s))
        except Exception:pass

# Evaluate the final-confirmation gate even when James was launched after minute
# 3. We cap the gate's *phase clock* at 180s instead of making it permanently WAIT.
def _v2251_gate(now,op,fc):
    n=float(now);bucket=int(n//900)*900
    eval_now=min(n,bucket+180.0)
    return dict(_V2984_BASE_GATE_FINAL(eval_now,op,fc) or {})
_v298_gate_final=_v2251_gate
_v298_gate=_v2251_gate

