# ============================================================================
# V22.6 — LIVE FORMULATION SCORE / DISPLAY REFRESH FIX
# ============================================================================
# Goal: keep MAIN LOCK decision authority unchanged, but make the visible
# "FORMULATING" strength genuinely live instead of echoing a stale forecast
# confidence snapshot.  This score is descriptive, not a lock override.
_V226_RELEASE='V22.6 LIVE FORMULATION SCORE'


def _v226_formulation_read(app):
    snap=dict(getattr(app,'_v220_last',{}) or {})
    signed=float(snap.get('terminal_signed',0.0) or 0.0)
    side=str(snap.get('terminal_side','NEUTRAL') or 'NEUTRAL').upper()
    if side not in ('UP','DOWN'):
        side='UP' if signed>0.015 else 'DOWN' if signed<-0.015 else 'WAIT'
    up=float(snap.get('up_viability',50.0) or 50.0);dn=float(snap.get('down_viability',50.0) or 50.0)
    mbi=dict(snap.get('mbi') or {});tug=dict(snap.get('tug') or {})
    m=float(mbi.get('forward_score',mbi.get('score',0.0)) or 0.0)
    t=float(tug.get('signed',tug.get('score',0.0)) or 0.0)
    if abs(t)>1.5:t/=100.0
    # Live descriptive confidence.  Route edge is primary; barrier separation,
    # MBI and tug provide smaller moving components.  Clamp so WAIT never looks
    # like an already-earned 100/100 lock.
    route=50.0+abs(signed)*38.0
    sep=min(12.0,abs(up-dn)*0.20)
    align=0.0
    sgn=1.0 if side=='UP' else -1.0 if side=='DOWN' else 0.0
    if sgn:
        align=max(-7.0,min(7.0,(m/100.0)*sgn*4.0 + t*sgn*3.0))
    score=max(0.0,min(96.0,route+sep+align)) if side!='WAIT' else max(0.0,min(60.0,route-10.0))
    return side,score,snap

_V226_BASE_PRIORITY=_v297_priority_refresh
