    try:
        snap_lock=dict(getattr(app,'opening_lock_snapshot',{}) or {})
        lk=dict(getattr(app,'_v272_last_lock',{}) or {})
        lock_side=str(snap_lock.get('lock_side',lk.get('side','WAIT')) or 'WAIT').upper()
        if lock_side not in ('UP','DOWN'):
            side,score,route=_v226_formulation_read(app)
            status=str(lk.get('status','FORMULATING') or 'FORMULATING').upper()
            # Keep wording short so the card never clips. Score is live and may
            # move every route refresh even while the actual lock remains WAIT.
            if side in ('UP','DOWN'):
                txt=f'{status} {side} • LIVE {score:.0f}/100 • route edge {float(route.get("terminal_signed",0) or 0):+.2f}'
            else:
                txt=f'{status} • LIVE {score:.0f}/100 • route unresolved'
            try: app.v297_lock_meta_var.set(txt)
            except Exception: pass
    except Exception:
        pass
