# V22.6K — FULL CHART BOOTSTRAP + STABLE LIVE BRTI CANDLE
# ============================================================================
# Live authority stays Kalshi CF BRTI.  Public BTC/USD 1m candles are used only
# to backfill chart history that Kalshi's latest-value stream does not provide.
# As official BRTI points arrive they overwrite/extend the live buckets.
_V226K_RELEASE='V22.6K FULL CHART + STABLE BRTI LIVE CANDLE'


def _v226k_norm_row(r):
    try:
        d=dict(r);o=float(d['open']);h=float(d['high']);l=float(d['low']);c=float(d['close']);t=int(float(d['time']))
        if not all(math.isfinite(x) and 1000.0<x<10000000.0 for x in (o,h,l,c)):return None
        return {'time':t,'open':o,'high':max(h,o,c),'low':min(l,o,c),'close':c,'volume':float(d.get('volume',0) or 0),'_live_source':d.get('_live_source','BTC HISTORY WARMUP')}
    except Exception:return None


def _v226k_fetch_public_1m(self):
    """Fetch enough BTC/USD minute history to make every visible TF a real chart.
    This is history-only warmup. Live price/candle close remains Kalshi BRTI.
    """
    now=int(time.time());rows={}
    # Keep existing inherited BTC history if it is already populated.
    for r0 in list(getattr(self,'btc_1m',[]) or []):
        r=_v226k_norm_row(r0)
        if r:rows[int(r['time'])]=r
    # Coinbase public endpoint caps each request; page backwards in 4h45m chunks.
    try:
        for i in range(5):
            end=now-i*285*60;start=end-285*60
            params={'granularity':60,
                    'start':datetime.fromtimestamp(start,timezone.utc).isoformat().replace('+00:00','Z'),
                    'end':datetime.fromtimestamp(end,timezone.utc).isoformat().replace('+00:00','Z')}
            data=http_json(COINBASE_BASE+'/products/BTC-USD/candles',params,timeout=7)
            if not isinstance(data,list):continue
            for x in data:
                try:
                    # Coinbase: [time, low, high, open, close, volume]
                    t=int(float(x[0]));r={'time':t,'low':float(x[1]),'high':float(x[2]),'open':float(x[3]),'close':float(x[4]),'volume':float(x[5] or 0),'_live_source':'BTC HISTORY WARMUP'}
                    r=_v226k_norm_row(r)
                    if r:rows[t]=r
                except Exception:pass
    except Exception as exc:
        self._v226_history_error=str(exc)[:160]
    out=[rows[k] for k in sorted(rows)][-1500:]
    if out:
        self._v226_history_1m=out
        # Keep inherited context arrays populated for indicators that read them.
        try:self.btc_1m=[dict(r) for r in out]
        except Exception:pass
        try:self.btc_5m=self._resample_history(out,300)
        except Exception:pass
        try:self.btc_15m=self._resample_history(out,900)
        except Exception:pass
        try:self.btc_1h=self._resample_history(out,3600)
        except Exception:pass
        self._v271_visual_seq=int(getattr(self,'_v271_visual_seq',0) or 0)+1
        self._last_chart_render_key=None
    return out


def _v226k_resample(rows,sec):
    sec=max(60,int(sec));buckets={}
    for r0 in rows or []:
        r=_v226k_norm_row(r0)
        if not r:continue
        b=int(r['time']//sec)*sec;q=buckets.get(b)
        if q is None:
            buckets[b]={'time':b,'open':r['open'],'high':r['high'],'low':r['low'],'close':r['close'],'volume':r.get('volume',0.0),'_live_source':r.get('_live_source','BTC HISTORY WARMUP')}
        else:
            q['high']=max(q['high'],r['high']);q['low']=min(q['low'],r['low']);q['close']=r['close'];q['volume']+=float(r.get('volume',0) or 0)
    return [buckets[k] for k in sorted(buckets)]


def _v226k_history_for_interval(self,seconds):
    sec=max(60,int(seconds));now=time.time();cur=int(now//sec)*sec
    warm=list(getattr(self,'_v226_history_1m',[]) or getattr(self,'btc_1m',[]) or [])
    base=_v226k_resample(warm,sec)
    # Overlay any official BRTI buckets we actually possess.
    official=list(_v2985_aggregate(self,sec,include_current=False,now=now,limit=2000) or [])
    merged={int(r['time']):dict(r) for r in base if int(r.get('time',0))<cur}
    for b0 in official:
        b=_v226k_norm_row(b0)
        if not b or int(b['time'])>=cur:continue
        old=merged.get(int(b['time']))
        if old:
            old['high']=max(float(old['high']),float(b['high']));old['low']=min(float(old['low']),float(b['low']));old['close']=float(b['close']);old['_live_source']='KALSHI BRTI + HISTORY'
        else:merged[int(b['time'])]=b
    count=max(100,int(getattr(self,'visible_count',80) or 80)+30)
    return [merged[k] for k in sorted(merged)][-count:]


def _v226k_current_bucket(self,seconds):
    sec=max(60,int(seconds));now=time.time();bucket=int(now//sec)*sec
    warm=list(getattr(self,'_v226_history_1m',[]) or getattr(self,'btc_1m',[]) or [])
    current_hist=[r for r in _v226k_resample(warm,sec) if int(r.get('time',-1))==bucket]
    seed=dict(current_hist[-1]) if current_hist else None
    ticks=[]
    try:ticks=[(float(t),float(p)) for t,p in list(getattr(self,'v2985_brti_ticks',()) or ()) if float(t)>=bucket]
    except Exception:ticks=[]
    if seed is None:
        if ticks:
            p=ticks[0][1];seed={'time':bucket,'open':p,'high':p,'low':p,'close':p,'volume':0.0,'_live_source':'KALSHI BRTI'}
        else:
            p=getattr(self,'current_spot',None)
            if p is None:return None
            p=float(p);seed={'time':bucket,'open':p,'high':p,'low':p,'close':p,'volume':0.0,'_live_source':'KALSHI BRTI SEED'}
    # Important: preserve the true bucket open from history, then let BRTI own
    # the live close. This prevents the giant/chode candle caused by launching
    # halfway through a 15m bucket and treating the first observed tick as open.
    if ticks:
        vals=[p for _,p in ticks];seed['high']=max(float(seed['high']),max(vals));seed['low']=min(float(seed['low']),min(vals));seed['close']=vals[-1];seed['_live_source']='KALSHI CF BRTI LIVE'
    return _v226k_norm_row(seed)


def _v226k_chart_candles(self):
    sec=max(60,int(getattr(self,'chart_interval_seconds',900) or 900));now=time.time();bucket=int(now//sec)*sec
    rows=list(_v226k_history_for_interval(self,sec) or []);cur=_v226k_current_bucket(self,sec)
    ded={int(r['time']):dict(r) for r in rows if int(r.get('time',0))<bucket}
    if isinstance(cur,dict):ded[int(cur['time'])]=dict(cur)
    out=[ded[k] for k in sorted(ded)]
    count=max(80,int(getattr(self,'visible_count',80) or 80)+12);out=out[-count:]
    self._v255_last_candle_rows=[dict(r) for r in out];self._v255_last_candle_bucket=int(out[-1]['time']) if out else None;self._v255_last_candle_close=float(out[-1]['close']) if out else None
    return out

# Bind chart + analysis lanes to the stable hybrid history/live-BRTI adapter.
ChartKingPro._history_for_interval=_v226k_history_for_interval
ChartKingPro._current_bucket_for_interval=_v226k_current_bucket
ChartKingPro._chart_candles=_v226k_chart_candles
