# Final lock wrapper. Let the full inherited V21.85 engine try first. Only after
# 120 seconds does this assist bridge a readiness deadlock, and only when the
# new V22 route engine has persistent asymmetric evidence. A 50/50 route stays
# WAIT indefinitely rather than receiving a fabricated guess.
_V227_BASE_OPEN_TICK = ChartKingPro._bookmap_opening_lock_tick


def _v227_open_lock_tick(self, warm=None, now=None):
    now = float(now or time.time())
    bucket = int(now // 900) * 900

    # Preserve normal lock + plan-change behavior first.
    try:
        snap = _V227_BASE_OPEN_TICK(self, warm=warm, now=now)
    except TypeError:
        snap = _V227_BASE_OPEN_TICK(self, warm, now)
    except Exception:
        snap = None
    if snap or str((getattr(self,'opening_lock_snapshot',{}) or {}).get('lock_side','WAIT')).upper() in ('UP','DOWN'):
        return snap or dict(getattr(self,'opening_lock_snapshot',{}) or {})

    into = max(0.0, now - bucket)
    # Respect the user's desired patient behavior: no assist before 120s.
    if into < 120.0:
        return None

    route = dict(getattr(self, '_v220_last', {}) or {})
    if not route.get('ready') or now - float(route.get('ts', now) or now) > 2.0:
        try: route = dict(_v220_terminal_read(self, now=now) or {})
        except Exception: route = {}
    mode = str(getattr(self,'v220_source_mode',globals().get('_V220_SOURCE_MODE','BOOKMAP'))).upper()
    q = _v227_lock_candidate(route, mode=mode)

    st = dict(getattr(self, '_v227_lock_assist', {}) or {})
    if int(st.get('bucket', -1) or -1) != bucket:
        st = {'bucket': bucket, 'side':'WAIT', 'since':0.0, 'samples':0, 'last_eval':0.0}
    # Time-normalize observations so 60Hz UI calls cannot fake persistence.
    if now - float(st.get('last_eval', 0.0) or 0.0) < .25:
        self._v227_lock_assist = st
        return None
    st['last_eval'] = now

    if not q['qualified']:
        # Decay rather than hard reset for one borderline sample, but a side
        # disagreement resets the candidate immediately.
        if q['side'] != st.get('side') and q['side'] in ('UP','DOWN'):
            st.update({'side':'WAIT','since':0.0,'samples':0})
        else:
            st['samples'] = max(0, int(st.get('samples',0) or 0)-1)
            if st['samples'] == 0:
                st['side']='WAIT'; st['since']=0.0
        self._v227_lock_assist = st
        try:
            self.opening_lock_var.set(
                f'FORMULATING {q["side"] if q["side"] in ("UP","DOWN") else "WAIT"} • '
                f'V22.7 PATIENT MAP • {q["reason"]} • no lock without convergence')
        except Exception: pass
        return None

    if st.get('side') != q['side']:
        st.update({'side':q['side'], 'since':now, 'samples':1})
    else:
        st['samples'] = int(st.get('samples',0) or 0) + 1
    age = max(0.0, now - float(st.get('since', now) or now))
    self._v227_lock_assist = st

    try:
        self.opening_lock_var.set(
            f'FORMULATING {q["side"]} • V22.7 {age:.1f}/{q["need_s"]:.1f}s coherent • '
            f'{q["strength"]:.0f}/100 • {q["reason"]}')
    except Exception: pass

    min_samples = 10 if mode == 'BOOKMAP' else 8
    if age < q['need_s'] or int(st.get('samples',0) or 0) < min_samples:
        return None

    try: live, _ = self.effective_live_price()
    except Exception: live = None
    try: target, _ = self.effective_target()
    except Exception: target = None
    if live is None or target is None:
        return None

    side = q['side']; strength = float(q['strength'])
    # Populate the inherited thesis state so subsequent ticks go through the
    # normal sticky/PLAN CHANGED machinery instead of living in a parallel lock.
    thesis = getattr(self, '_v279_thesis', None)
    if not isinstance(thesis, dict) or int(thesis.get('bucket',-1) or -1) != bucket:
        try: thesis = _v279_state_reset(self, bucket)
        except Exception: thesis = {'bucket':bucket, 'samples':deque(maxlen=2000), 'review':deque(maxlen=500)}
    thesis.update({
        'status':'LOCKED', 'side':side, 'strength':strength, 'locked_at':now,
        'opening_score':float(q['signed']), 'opening_consistency':float(q['persistence']),
        'opening_vote':1.0 if side=='UP' else -1.0,
        'opening_meta':dict(q),
        'last_reason':f'V22.7 PATIENT ROUTE LOCK • {q["reason"]}',
    })
    self._v279_thesis = thesis

    try: fc = dict(_v272_forecast_read(self, now=now) or {})
    except Exception: fc = {}
    fc.setdefault('live', float(live)); fc.setdefault('target', float(target))
    fc.setdefault('path_side', side); fc.setdefault('settlement_side', side)
    fc.setdefault('confidence', strength); fc.setdefault('quality', max(55.0, q['persistence']*100.0))
    fc.setdefault('settlement_score', q['signed'])
    try:
        snap = _v279_make_snapshot(now, side, strength, fc, 'V22.7 PATIENT ROUTE LOCK', thesis['last_reason'], bucket)
    except Exception:
        snap = {'time':now,'price':float(live),'lock_side':side,'strength':strength,'bucket':bucket,
                'market_bucket':bucket,'source':'V22.7 PATIENT ROUTE LOCK','forecast_reasons':thesis['last_reason']}
    self.opening_lock_snapshot = dict(snap)
    try:
        self._v272_last_lock = {
            'ready':True,'status':'LOCKED','side':side,'lock_side':side,'candidate':side,
            'strength':strength,'reason':thesis['last_reason'],'forecast':fc,
            'snapshot':dict(snap),'bucket':bucket,'seconds_into_round':into,
            'opening':dict(q),'plan_change':{},'switch_count':int(thesis.get('switch_count',0) or 0)
        }
    except Exception: pass
    try:
        self.opening_lock_var.set(f'MAIN LOCK: {side} {strength:.0f}/100 • V22.7 PATIENT ROUTE EARNED • {q["reason"]}')
    except Exception: pass
    return dict(snap)


ChartKingPro._bookmap_opening_lock_tick = _v227_open_lock_tick


