# =============================================================================
# V22.8 — ALWAYS-MAPPING JOURNEY + ADAPTIVE EARNED LOCK
# =============================================================================
# Goals:
#   * Map levels and the 15m journey BEFORE a lock exists.
#   * Keep patience in true coin-toss conditions, but never deadlock forever just
#     because the inherited route confidence hovers in the low/mid-50s.
#   * After enough observation, choose the best supported route from barrier
#     viability + MBI + tug/flow rather than waiting for an unrealistically large
#     terminal_signed value.
#   * Preserve V22 reversal/survival machinery after the lock is earned.
# =============================================================================
_V228_RELEASE='V22.8 ALWAYS-MAPPING + ADAPTIVE LOCK'
_V228_BASE_OPEN_TICK=ChartKingPro._bookmap_opening_lock_tick
_V228_BASE_JOURNEY_READ=_v2673_journey_read


def _v228_num(v,d=0.0):
    try:
        x=float(v)
        return x if math.isfinite(x) else d
    except Exception:
        return d


def _v228_lock_packet(route, into, mode='BOOKMAP'):
    r=dict(route or {})
    up=_v228_num(r.get('up_viability'),50.0); dn=_v228_num(r.get('down_viability'),50.0)
    signed=_v228_num(r.get('terminal_signed'),0.0)
    mbi=dict(r.get('mbi') or {}); tug=dict(r.get('tug') or {})
    m=_v228_num(mbi.get('forward_score',mbi.get('score',0.0)),0.0)
    t=_v228_num(tug.get('signed',tug.get('score',0.0)),0.0)
    if abs(t)>1.5:t/=100.0

    # Barrier viability is primary. Terminal signed remains useful, but no longer
    # has to become huge before James can form a thesis.
    barrier=(up-dn)/100.0
    composite=max(-1.0,min(1.0,.52*barrier+.30*signed+.12*max(-1,min(1,m/100.0))+.06*max(-1,min(1,t))))
    side='UP' if composite>0 else 'DOWN' if composite<0 else str(r.get('terminal_side','NEUTRAL')).upper()
    if side not in ('UP','DOWN'):
        side='UP' if up>dn else 'DOWN' if dn>up else 'WAIT'
    sgn=1.0 if side=='UP' else -1.0 if side=='DOWN' else 0.0
    gap=abs(up-dn)
    m_align=m*sgn; t_align=t*sgn

    # Adaptive evidence floor. We stay selective early, then progressively allow
    # a best-path lock as more of the 15m journey is observed.
    if into < 30:
        edge_need=.115; gap_need=8.0; need_s=3.0
    elif into < 75:
        edge_need=.090; gap_need=6.0; need_s=4.0
    elif into < 120:
        edge_need=.070; gap_need=4.5; need_s=4.5
    elif into < 180:
        edge_need=.050; gap_need=3.0; need_s=5.0
    else:
        edge_need=.025; gap_need=1.5; need_s=4.0

    # A strong contrary MBI/flow read can still block a bad lock.
    hard_oppose=(m_align<=-55.0) or (t_align<=-.72)
    level_map=dict(r.get('levels') or {})
    has_levels=bool(level_map.get('ceiling') or level_map.get('floor'))
    qualified=(side in ('UP','DOWN') and has_levels and not hard_oppose and
               (abs(composite)>=edge_need or gap>=gap_need))

    # After 3 minutes, if the market is not literally tied and we have mapped
    # levels, earn the best supported route rather than sit WAIT all round.
    best_path=False
    if into>=180 and side in ('UP','DOWN') and has_levels and not hard_oppose:
        best_path=(abs(composite)>=.012 or gap>=.75 or abs(m_align)>=8 or abs(t_align)>=.08)
        qualified=qualified or best_path

    # Display strength reflects multiple dimensions, not terminal_signed alone.
    strength=50.0 + abs(composite)*105.0 + gap*.65 + min(8.0,abs(m_align)*.07) + min(5.0,abs(t_align)*6.0)
    strength=max(51.0,min(91.0,strength))
    return {'side':side,'qualified':bool(qualified),'best_path':bool(best_path),
            'composite':composite,'gap':gap,'up':up,'down':dn,'mbi_align':m_align,'tug_align':t_align,
            'need_s':need_s,'strength':strength,
            'reason':f'route {composite:+.3f} • barriers UP {up:.0f}/DOWN {dn:.0f} gap {gap:.1f} • MBI {m_align:+.0f} • tug {t_align:+.2f}'}


def _v228_journey_from_route(self, now=None):
    now=float(now or time.time())
    try:base=dict(_V228_BASE_JOURNEY_READ(self,now=now) or {})
    except Exception:base={}
    try:r=dict(getattr(self,'_v220_last',{}) or {})
    except Exception:r={}
    if not r.get('ready'):
        try:r=dict(_v220_terminal_read(self,now=now) or {})
        except Exception:r={}
    if not r.get('ready'):
        return base

    live=_v228_num(r.get('live'),0.0); target=None
    try:target,_=self.effective_target()
    except Exception:target=None
    levels=dict(r.get('levels') or {}); ceil=dict(levels.get('ceiling') or {}); floor=dict(levels.get('floor') or {})
    up=_v228_num(r.get('up_viability'),50.0);dn=_v228_num(r.get('down_viability'),50.0)
    side=str(r.get('terminal_side','NEUTRAL')).upper()
    if side not in ('UP','DOWN'):side='UP' if up>dn else 'DOWN' if dn>up else 'WAIT'
    checkpoints=[]
    def add_level(obj,label,kind):
        p=obj.get('price') if isinstance(obj,dict) else None
        if p is not None:
            checkpoints.append({'price':float(p),'label':label,'kind':kind,'score':80})
    add_level(floor,'ROUTE FLOOR','FLOOR');add_level(ceil,'ROUTE CEILING','CEILING')
    if target is not None:checkpoints.append({'price':float(target),'label':'KALSHI TARGET','kind':'TARGET','score':90})
    checkpoints=sorted(checkpoints,key=lambda c:abs(float(c['price'])-live))[:5] if live else checkpoints[:5]
    cp=checkpoints[0] if checkpoints else None
    ctext=f"NEXT CHECKPOINT: {cp['label']} @ {money(cp['price'])} • {abs(float(cp['price'])-live):.0f}$ away" if cp and live else 'NEXT CHECKPOINT: mapping levels'
    cstat=str((r.get('ceiling') or {}).get('status','BUILDING'));fstat=str((r.get('floor') or {}).get('status','BUILDING'))
    route_text=(f'EXPECTED JOURNEY: {side} • floor {money(floor.get("price")) if floor else "--"} [{fstat}] → '
                f'ceiling {money(ceil.get("price")) if ceil else "--"} [{cstat}] → target {money(target) if target else "--"}')
    match=max(0.0,min(100.0,50.0+abs(_v228_num(r.get('terminal_signed'),0))*35.0+abs(up-dn)*.55))
    out=dict(base)
    out.update({'ready':True,'headline':f'15M JOURNEY MAP • terminal {side} • UP {up:.0f}/DOWN {dn:.0f}',
                'stage':'PRE-LOCK ROUTE MAPPING' if not getattr(self,'opening_lock_snapshot',None) else 'LOCKED ROUTE MAPPING',
                'lock_side':str((getattr(self,'opening_lock_snapshot',{}) or {}).get('lock_side','WAIT')),
                'route_side':side,'route_match':match,'route_text':route_text,'checkpoint_text':ctext,
                'finish_text':f'PROJECTED TERMINAL PATH: {side} • barrier viability UP {up:.0f} / DOWN {dn:.0f}',
                'evidence_text':f'LEVEL MAP: floor {fstat} • ceiling {cstat} • reversal {float(r.get("reversal_pct",0) or 0):.0f}%',
                'live':live,'target':target,'checkpoints':checkpoints,'v228_route':r})
    self._v2673_last_map=dict(out)
    return out


def _v228_open_lock_tick(self,warm=None,now=None):
    now=float(now or time.time());bucket=int(now//900)*900
    # Let all inherited lock machinery try first.
    try:snap=_V228_BASE_OPEN_TICK(self,warm=warm,now=now)
    except TypeError:
        try:snap=_V228_BASE_OPEN_TICK(self,warm,now)
        except Exception:snap=None
    except Exception:snap=None
    existing=dict(getattr(self,'opening_lock_snapshot',{}) or {})
    if snap or str(existing.get('lock_side','WAIT')).upper() in ('UP','DOWN'):
        return snap or existing

    into=max(0.0,now-bucket)
    try:r=dict(getattr(self,'_v220_last',{}) or {})
    except Exception:r={}
    if not r.get('ready') or now-_v228_num(r.get('ts'),now)>1.5:
        try:r=dict(_v220_terminal_read(self,now=now) or {})
        except Exception:r={}
    if not r.get('ready'):return None
    q=_v228_lock_packet(r,into,str(getattr(self,'v220_source_mode','BOOKMAP')).upper())

    st=dict(getattr(self,'_v228_lock_state',{}) or {})
    if int(st.get('bucket',-1) or -1)!=bucket:
        st={'bucket':bucket,'side':'WAIT','since':0.0,'samples':0,'evidence':0.0,'last_eval':0.0}
    if now-_v228_num(st.get('last_eval'),0.0)<.25:
        self._v228_lock_state=st;return None
    st['last_eval']=now

    # Leaky persistence: borderline observations slow progress instead of nuking it.
    if q['qualified']:
        if st.get('side')!=q['side']:
            st.update({'side':q['side'],'since':now,'samples':1,'evidence':1.0})
        else:
            st['samples']=int(st.get('samples',0))+1;st['evidence']=min(40.0,_v228_num(st.get('evidence'),0)+1.0)
    else:
        st['evidence']=max(0.0,_v228_num(st.get('evidence'),0)-.35)
        if q['side'] in ('UP','DOWN') and st.get('side') not in ('WAIT',q['side']):
            st.update({'side':q['side'],'since':now,'samples':1,'evidence':.5})
        elif st['evidence']<=0:
            st.update({'side':'WAIT','since':0.0,'samples':0})
    self._v228_lock_state=st
    age=max(0.0,now-_v228_num(st.get('since'),now)) if st.get('side') in ('UP','DOWN') else 0.0
    live_score=q['strength']
    try:self.opening_lock_var.set(f'FORMULATING {q["side"]} • LIVE {live_score:.0f}/100 • {age:.1f}/{q["need_s"]:.1f}s • {q["reason"]}')
    except Exception:pass

    # Always keep the journey populated while formulating.
    try:_v228_journey_from_route(self,now=now)
    except Exception:pass

    if not q['qualified'] or st.get('side')!=q['side'] or age<q['need_s'] or _v228_num(st.get('evidence'),0)<max(5.0,q['need_s']*2.0):
        return None
    try:live,_=self.effective_live_price();target,_=self.effective_target()
    except Exception:return None
    if live is None or target is None:return None
    side=q['side'];strength=q['strength']
    snap={'time':now,'price':float(live),'lock_side':side,'strength':strength,'bucket':bucket,'market_bucket':bucket,
          'source':'V22.8 ADAPTIVE ROUTE LOCK','forecast_reasons':q['reason'],'forecast_score':q['composite']*10.0,
          'forecast_threshold':0.0,'lock_remaining':'OPEN','lock_minute':int(into//60)}
    self.opening_lock_snapshot=dict(snap);self.opening_lock_candidate=None;self.opening_lock_candidate_since=0.0
    try:
        thesis=getattr(self,'_v279_thesis',None)
        if isinstance(thesis,dict):
            thesis.update({'status':'LOCKED','side':side,'strength':strength,'locked_at':now,'opening_score':q['composite'],'opening_meta':dict(q),'last_reason':'V22.8 '+q['reason']})
            self._v279_thesis=thesis
    except Exception:pass
    try:self.opening_lock_var.set(f'MAIN LOCK: {side} {strength:.0f}/100 • V22.8 EARNED • {q["reason"]}')
    except Exception:pass
    return dict(snap)


