# =============================================================================
# V22.9 — REGIME CLASSIFIER + TRUE 0..180s FIRST-LOCK WINDOW + ALWAYS-MAPPED PATH
# =============================================================================
# User contract:
#   1) James classifies the current 15m market regime continuously.
#   2) Level/journey mapping exists BEFORE a MAIN LOCK and never depends on it.
#   3) A first MAIN LOCK may be earned at ANY point from second 0 through second
#      180 of the 15m round. There is no 30s/60s/120s "permission" boundary.
#   4) Thresholds may adapt with evidence age/regime, but time itself never blocks
#      an otherwise-qualified lock during the first three minutes.
#   5) Near the end of the 3m window James gets progressively more willing to
#      choose the best mapped route, without inventing a side from zero evidence.
#   6) Existing V22 reversal/survival/PLAN CHANGED machinery remains downstream.
# =============================================================================
_V229_RELEASE='V22.9 REGIME + TRUE 0-180 LOCK WINDOW'
_V229_BASE_OPEN_TICK=ChartKingPro._bookmap_opening_lock_tick
_V229_BASE_JOURNEY_READ=_v2673_journey_read
_V229_BASE_PRIORITY=_v297_priority_refresh


def _v229_num(v,d=0.0):
    try:
        x=float(v)
        return x if math.isfinite(x) else d
    except Exception:
        return d


def _v229_rows(self,sec=60,n=18):
    rows=[]
    try: rows=list(self._history_for_interval(int(sec)) or [])
    except Exception:
        try: rows=list(self._chart_candles(int(sec)) or [])
        except Exception: rows=[]
    clean=[]
    for z in rows[-max(4,int(n)):]:
        try:
            r=dict(z); o=float(r['open']);h=float(r['high']);l=float(r['low']);c=float(r['close'])
            if all(math.isfinite(x) for x in (o,h,l,c)) and h>=l:
                clean.append({'open':o,'high':h,'low':l,'close':c,'ts':r.get('ts',r.get('time',0))})
        except Exception: pass
    return clean


def _v229_level_map(self,route=None,now=None):
    """Return a floor/ceiling even when an upstream route packet omitted levels."""
    r=dict(route or {})
    levels=dict(r.get('levels') or {})
    floor=dict(levels.get('floor') or r.get('floor') or {})
    ceil=dict(levels.get('ceiling') or r.get('ceiling') or {})
    def price(obj):
        try:
            p=float(obj.get('price'))
            return p if math.isfinite(p) else None
        except Exception:return None
    fp,cp=price(floor),price(ceil)
    rows=_v229_rows(self,60,20)
    live=_v229_num(r.get('live'),0.0)
    if live<=0:
        try: live=float(self.effective_live_price()[0] or 0)
        except Exception: live=0.0
    if rows:
        lows=sorted(float(x['low']) for x in rows); highs=sorted(float(x['high']) for x in rows)
        # Use robust near-extremes rather than one wick so levels remain useful.
        lo_idx=max(0,int((len(lows)-1)*.15)); hi_idx=min(len(highs)-1,int((len(highs)-1)*.85))
        hist_floor=lows[lo_idx]; hist_ceil=highs[hi_idx]
        below=[x['low'] for x in rows if not live or x['low']<=live]
        above=[x['high'] for x in rows if not live or x['high']>=live]
        if fp is None: fp=max(below) if below else hist_floor
        if cp is None: cp=min(above) if above else hist_ceil
        if fp is not None and cp is not None and fp>=cp:
            fp,cp=min(hist_floor,live or hist_floor),max(hist_ceil,live or hist_ceil)
    out={'floor':dict(floor),'ceiling':dict(ceil)}
    if fp is not None:
        out['floor'].update({'price':float(fp),'status':str(out['floor'].get('status','MAPPED')),'source':str(out['floor'].get('source','V22.9 1M STRUCTURE'))})
    if cp is not None:
        out['ceiling'].update({'price':float(cp),'status':str(out['ceiling'].get('status','MAPPED')),'source':str(out['ceiling'].get('source','V22.9 1M STRUCTURE'))})
    return out


def _v229_regime_read(self,route=None,now=None):
    """Classify the live market without using Kalshi odds as directional authority."""
    now=float(now or time.time()); r=dict(route or {})
    rows=_v229_rows(self,60,14)
    rets=[]; ranges=[]; wick=[]
    for x in rows:
        rg=max(1e-9,x['high']-x['low']); body=abs(x['close']-x['open'])
        ranges.append(rg); wick.append(max(0.0,rg-body)/rg)
    for a,b in zip(rows,rows[1:]): rets.append(float(b['close'])-float(a['close']))
    signs=[1 if x>0 else -1 if x<0 else 0 for x in rets]
    nz=[x for x in signs if x]
    flips=sum(1 for a,b in zip(nz,nz[1:]) if a!=b)
    flip_rate=flips/max(1,len(nz)-1)
    travel=sum(abs(x) for x in rets)
    net=abs((rows[-1]['close']-rows[0]['close'])) if len(rows)>=2 else 0.0
    efficiency=net/max(1e-9,travel) if travel else 0.0
    med_range=0.0
    if ranges:
        sr=sorted(ranges);med_range=sr[len(sr)//2]
    recent_range=(max(x['high'] for x in rows[-4:])-min(x['low'] for x in rows[-4:])) if len(rows)>=4 else (ranges[-1] if ranges else 0.0)
    expansion=recent_range/max(1e-9,med_range*max(1,min(4,len(rows)))) if med_range else 0.0
    wickiness=sum(wick)/len(wick) if wick else 0.0
    signed=_v229_num(r.get('terminal_signed'),0.0)
    persist=_v229_num(r.get('signal_persistence_v222',r.get('signal_persistence',0.0)),0.0)
    rev=_v229_num(r.get('reversal_pct'),0.0)
    up=_v229_num(r.get('up_viability'),50.0);dn=_v229_num(r.get('down_viability'),50.0)
    gap=abs(up-dn)
    lv=_v229_level_map(self,r,now)
    has_both=bool((lv.get('floor') or {}).get('price') is not None and (lv.get('ceiling') or {}).get('price') is not None)
    mbi=dict(r.get('mbi') or {}); m=_v229_num(mbi.get('forward_score',mbi.get('score',0.0)),0.0)
    # Regime priority: transition -> expansion -> trend -> flippy -> range -> chop -> mixed.
    side='UP' if signed>0 else 'DOWN' if signed<0 else ('UP' if up>dn else 'DOWN' if dn>up else 'WAIT')
    if rev>=58 and (persist>=.52 or abs(m)>=28):
        name='REVERSAL TRANSITION'; conf=min(96.0,58+rev*.22+persist*18)
        play='protect old thesis • require replacement-route confirmation'
    elif efficiency>=.62 and expansion>=.72 and abs(signed)>=.10:
        name=f'BREAKOUT / EXPANSION {side}'; conf=min(96.0,62+efficiency*24+min(12,abs(signed)*40))
        play='continuation • break/retest/hold'
    elif efficiency>=.56 and flip_rate<=.34 and (persist>=.55 or abs(signed)>=.08):
        name=f'STRAIGHT SHOT {side}'; conf=min(95.0,60+efficiency*28+(1-flip_rate)*9)
        play='continuation • shallow-pullback route'
    elif flip_rate>=.48 and (expansion>=.55 or rev>=34):
        name='FLIPPY / HIGH-VOL TWO-WAY'; conf=min(95.0,58+flip_rate*26+min(10,rev*.10))
        play='level-to-level • reversal/scalp emphasis'
    elif has_both and efficiency<=.46 and flip_rate>=.28:
        name='RANGE / LEVEL-TO-LEVEL'; conf=min(92.0,60+(1-efficiency)*18+flip_rate*16)
        play='floor/ceiling reactions • do not chase midpoint'
    elif efficiency<=.28 and wickiness>=.48:
        name='CHOP / LOW QUALITY'; conf=min(90.0,58+(1-efficiency)*16+wickiness*14)
        play='raise evidence bar • trust mapped barriers over micro ticks'
    else:
        name='MIXED / DEVELOPING'; conf=max(50.0,min(82.0,52+gap*.45+abs(signed)*35))
        play='map first • wait for route separation'
    return {'name':name,'confidence':conf,'playbook':play,'side':side,'efficiency':efficiency,
            'flip_rate':flip_rate,'expansion':expansion,'wickiness':wickiness,'persistence':persist,
            'reversal':rev,'gap':gap,'levels':lv,'rows':len(rows),'ts':now}


def _v229_lock_packet(self,route,into,mode='BOOKMAP',now=None):
    r=dict(route or {}); now=float(now or time.time())
    reg=_v229_regime_read(self,r,now)
    r['levels']=dict(reg.get('levels') or {})
    up=_v229_num(r.get('up_viability'),50.0);dn=_v229_num(r.get('down_viability'),50.0)
    signed=_v229_num(r.get('terminal_signed'),0.0)
    mbi=dict(r.get('mbi') or {});tug=dict(r.get('tug') or {})
    m=_v229_num(mbi.get('forward_score',mbi.get('score',0.0)),0.0)
    t=_v229_num(tug.get('signed',tug.get('score',0.0)),0.0)
    if abs(t)>1.5:t/=100.0
    barrier=(up-dn)/100.0
    composite=max(-1.0,min(1.0,.46*barrier+.28*signed+.16*max(-1,min(1,m/100.0))+.10*max(-1,min(1,t))))
    side='UP' if composite>0 else 'DOWN' if composite<0 else str(r.get('terminal_side','NEUTRAL')).upper()
    if side not in ('UP','DOWN'):side='UP' if up>dn else 'DOWN' if dn>up else reg.get('side','WAIT')
    sgn=1.0 if side=='UP' else -1.0 if side=='DOWN' else 0.0
    gap=abs(up-dn);m_align=m*sgn;t_align=t*sgn
    hard_oppose=(m_align<=-62.0) or (t_align<=-.78)
    levels=dict(r.get('levels') or {});has_levels=bool((levels.get('floor') or {}).get('price') is not None or (levels.get('ceiling') or {}).get('price') is not None)
    # TRUE 0..180 CONTRACT: no minimum minute boundary. If evidence is already
    # coherent at second 5, second 17, second 63, etc., James may lock there.
    window_open=(0.0<=float(into)<=180.0)
    # Base requirements adapt by regime, not by artificial time gates.
    name=str(reg.get('name','MIXED'))
    edge_need=.060;gap_need=3.0;need_s=1.20
    if name.startswith('BREAKOUT'): edge_need=.052;gap_need=2.5;need_s=.65
    elif name.startswith('STRAIGHT SHOT'): edge_need=.055;gap_need=2.7;need_s=.80
    elif name.startswith('FLIPPY'): edge_need=.048;gap_need=2.2;need_s=1.35
    elif name.startswith('RANGE'): edge_need=.050;gap_need=2.3;need_s=1.20
    elif name.startswith('REVERSAL'): edge_need=.060;gap_need=3.0;need_s=1.45
    elif name.startswith('CHOP'): edge_need=.075;gap_need=4.0;need_s=1.80
    # Progressive deadline relief INSIDE the same 0..180 window. This is not a
    # wait-until rule; it only prevents a mapped round from deadlocking to 180.
    progress=max(0.0,min(1.0,float(into)/180.0))
    edge_need=max(.022,edge_need-.026*progress)
    gap_need=max(1.0,gap_need-1.8*progress)
    need_s=max(.55,need_s-.45*progress)
    qualified=(window_open and side in ('UP','DOWN') and has_levels and not hard_oppose and
               (abs(composite)>=edge_need or gap>=gap_need))
    deadline=False
    if window_open and into>=165 and side in ('UP','DOWN') and has_levels and not hard_oppose:
        deadline=(abs(composite)>=.010 or gap>=.55 or abs(m_align)>=7 or abs(t_align)>=.07)
        qualified=qualified or deadline
    strength=50.0+abs(composite)*120.0+gap*.72+min(9.0,abs(m_align)*.075)+min(6.0,abs(t_align)*7.0)
    strength=max(51.0,min(94.0,strength))
    return {'side':side,'qualified':bool(qualified),'window_open':window_open,'deadline':deadline,
            'composite':composite,'gap':gap,'up':up,'down':dn,'mbi_align':m_align,'tug_align':t_align,
            'need_s':need_s,'strength':strength,'regime':reg,'levels':levels,
            'reason':f'{name} {reg.get("confidence",0):.0f}/100 • route {composite:+.3f} • barriers {up:.0f}/{dn:.0f} • MBI {m_align:+.0f} • tug {t_align:+.2f}'}


def _v229_journey(self,now=None):
    now=float(now or time.time())
    try:r=dict(getattr(self,'_v220_last',{}) or {})
    except Exception:r={}
    if not r.get('ready'):
        try:r=dict(_v220_terminal_read(self,now=now) or {})
        except Exception:r={}
    if not r.get('ready'):
        try:return dict(_V229_BASE_JOURNEY_READ(self,now=now) or {})
        except Exception:return {}
    reg=_v229_regime_read(self,r,now); levels=dict(reg.get('levels') or {});r['levels']=levels
    try:base=dict(_V229_BASE_JOURNEY_READ(self,now=now) or {})
    except Exception:base={}
    live=_v229_num(r.get('live'),0.0)
    if live<=0:
        try:live=float(self.effective_live_price()[0] or 0)
        except Exception:live=0.0
    try:target,_=self.effective_target()
    except Exception:target=None
    floor=dict(levels.get('floor') or {});ceil=dict(levels.get('ceiling') or {})
    fp=floor.get('price');cp=ceil.get('price')
    up=_v229_num(r.get('up_viability'),50);dn=_v229_num(r.get('down_viability'),50)
    side=str((getattr(self,'opening_lock_snapshot',{}) or {}).get('lock_side') or r.get('terminal_side') or reg.get('side','WAIT')).upper()
    if side not in ('UP','DOWN'):side='UP' if up>dn else 'DOWN' if dn>up else 'WAIT'
    checkpoints=[]
    for p,label,kind in ((fp,'ROUTE FLOOR','FLOOR'),(cp,'ROUTE CEILING','CEILING'),(target,'KALSHI TARGET','TARGET')):
        try:
            if p is not None:checkpoints.append({'price':float(p),'label':label,'kind':kind,'score':90 if kind=='TARGET' else 82})
        except Exception:pass
    if live:checkpoints.sort(key=lambda c:abs(c['price']-live))
    nxt=checkpoints[0] if checkpoints else None
    path=[]
    if side=='UP':
        if fp is not None and live and fp<live:path.append(f'floor {money(fp)} hold')
        if cp is not None:path.append(f'ceiling {money(cp)} break/retest')
        if target is not None:path.append(f'target {money(target)} hold/settle')
    elif side=='DOWN':
        if cp is not None and live and cp>live:path.append(f'ceiling {money(cp)} reject')
        if fp is not None:path.append(f'floor {money(fp)} break/retest')
        if target is not None:path.append(f'target {money(target)} loss/settle')
    else:path=['mapping floor/ceiling','waiting for route separation']
    out=dict(base);out.update({
        'ready':True,'headline':f'REGIME: {reg["name"]} • {reg["confidence"]:.0f}/100 • route {side}',
        'stage':'PRE-LOCK 0-180s MAPPING' if not getattr(self,'opening_lock_snapshot',None) else 'LOCKED ROUTE MAPPING',
        'route_side':side,'route_text':'EXPECTED JOURNEY: '+' → '.join(path),
        'checkpoint_text':(f'NEXT CHECKPOINT: {nxt["label"]} @ {money(nxt["price"])} • {abs(nxt["price"]-live):.0f}$ away' if nxt and live else 'NEXT CHECKPOINT: mapping'),
        'finish_text':f'PLAYBOOK: {reg["playbook"]} • viability UP {up:.0f} / DOWN {dn:.0f}',
        'evidence_text':f'LEVELS: floor {money(fp) if fp is not None else "--"} • ceiling {money(cp) if cp is not None else "--"} • flips {reg["flip_rate"]*100:.0f}% • path efficiency {reg["efficiency"]*100:.0f}%',
        'live':live,'target':target,'checkpoints':checkpoints,'regime':reg,'v229_route':r})
    self._v2673_last_map=dict(out)
    return out


def _v229_open_lock_tick(self,warm=None,now=None):
    now=float(now or time.time());bucket=int(now//900)*900;into=max(0.0,now-bucket)
    # Preserve any legitimate lock already earned by inherited logic.
    try:snap=_V229_BASE_OPEN_TICK(self,warm=warm,now=now)
    except TypeError:
        try:snap=_V229_BASE_OPEN_TICK(self,warm,now)
        except Exception:snap=None
    except Exception:snap=None
    existing=dict(getattr(self,'opening_lock_snapshot',{}) or {})
    if snap or str(existing.get('lock_side','WAIT')).upper() in ('UP','DOWN'):
        try:_v229_journey(self,now=now)
        except Exception:pass
        return snap or existing
    try:r=dict(getattr(self,'_v220_last',{}) or {})
    except Exception:r={}
    if not r.get('ready') or now-_v229_num(r.get('ts'),now)>1.5:
        try:r=dict(_v220_terminal_read(self,now=now) or {})
        except Exception:r={}
    if not r.get('ready'):
        try:_v229_journey(self,now=now)
        except Exception:pass
        return None
    q=_v229_lock_packet(self,r,into,str(getattr(self,'v220_source_mode','BOOKMAP')).upper(),now)
    # Explicitly map even if the 3m lock opportunity later closes.
    try:_v229_journey(self,now=now)
    except Exception:pass
    reg=dict(q.get('regime') or {})
    try:
        if hasattr(self,'regime_var'):self.regime_var.set(f'{reg.get("name","MIXED")} • {reg.get("confidence",0):.0f}/100')
        if hasattr(self,'playbook_var'):self.playbook_var.set(f'PLAYBOOK: {reg.get("playbook","map first")}')
    except Exception:pass
    if not q.get('window_open'):
        try:self.opening_lock_var.set(f'FIRST-LOCK WINDOW CLOSED • REGIME {reg.get("name","--")} • journey still mapping')
        except Exception:pass
        return None
    st=dict(getattr(self,'_v229_lock_state',{}) or {})
    if int(st.get('bucket',-1) or -1)!=bucket:st={'bucket':bucket,'side':'WAIT','since':0.0,'evidence':0.0,'last_eval':0.0}
    if now-_v229_num(st.get('last_eval'),0.0)<.20:
        self._v229_lock_state=st;return None
    st['last_eval']=now
    if q['qualified']:
        if st.get('side')!=q['side']:st.update({'side':q['side'],'since':now,'evidence':1.0})
        else:st['evidence']=min(50.0,_v229_num(st.get('evidence'),0)+1.0)
    else:
        st['evidence']=max(0.0,_v229_num(st.get('evidence'),0)-.30)
        # Do not erase a coherent candidate on one borderline read.
        if st['evidence']<=0:st.update({'side':'WAIT','since':0.0})
    self._v229_lock_state=st
    age=max(0.0,now-_v229_num(st.get('since'),now)) if st.get('side') in ('UP','DOWN') else 0.0
    try:self.opening_lock_var.set(f'FORMULATING {q["side"]} • LIVE {q["strength"]:.0f}/100 • 0-180s OPEN • {age:.1f}/{q["need_s"]:.1f}s • {q["reason"]}')
    except Exception:pass
    need_e=max(2.0,q['need_s']*3.0)
    if not q['qualified'] or st.get('side')!=q['side'] or age<q['need_s'] or _v229_num(st.get('evidence'),0)<need_e:return None
    try:live,_=self.effective_live_price();target,_=self.effective_target()
    except Exception:return None
    if live is None or target is None:return None
    side=q['side'];strength=q['strength']
    snap={'time':now,'price':float(live),'lock_side':side,'strength':strength,'bucket':bucket,'market_bucket':bucket,
          'source':'V22.9 TRUE 0-180 REGIME LOCK','forecast_reasons':q['reason'],'forecast_score':q['composite']*10.0,
          'forecast_threshold':0.0,'lock_remaining':'OPEN','lock_minute':int(into//60),'regime':reg.get('name')}
    self.opening_lock_snapshot=dict(snap);self.opening_lock_candidate=None;self.opening_lock_candidate_since=0.0
    try:
        thesis=getattr(self,'_v279_thesis',None)
        if isinstance(thesis,dict):
            thesis.update({'status':'LOCKED','side':side,'strength':strength,'locked_at':now,'opening_score':q['composite'],'opening_meta':dict(q),'last_reason':'V22.9 '+q['reason']})
            self._v279_thesis=thesis
    except Exception:pass
    try:self.opening_lock_var.set(f'MAIN LOCK: {side} {strength:.0f}/100 • EARNED @ {into:.1f}s • {reg.get("name","--")} • {q["reason"]}')
    except Exception:pass
    return dict(snap)


def _v229_priority_refresh(app):
    _V229_BASE_PRIORITY(app)
    try:
        r=dict(getattr(app,'_v220_last',{}) or {});reg=_v229_regime_read(app,r,time.time())
        if hasattr(app,'regime_var'):app.regime_var.set(f'{reg["name"]} • {reg["confidence"]:.0f}/100')
        if hasattr(app,'playbook_var'):app.playbook_var.set(f'PLAYBOOK: {reg["playbook"]}')
        # Put regime directly under the giant MAIN LOCK value so it is visible
        # without opening the legacy diagnostics pane.
        if hasattr(app,'v297_lock_meta_var') and not getattr(app,'opening_lock_snapshot',None):
            into=max(0.0,time.time()-(int(time.time()//900)*900))
            state='0-180s LOCK WINDOW OPEN' if into<=180 else 'FIRST-LOCK WINDOW CLOSED'
            app.v297_lock_meta_var.set(f'{state} • {reg["name"]} {reg["confidence"]:.0f}/100')
    except Exception:pass

_v2673_journey_read=_v229_journey
ChartKingPro._v2673_journey_read=_v229_journey
ChartKingPro._bookmap_opening_lock_tick=_v229_open_lock_tick
_v297_priority_refresh=_v229_priority_refresh

# Avoid adding another __init__ wrapper to the already-deep legacy wrapper chain.
# _v229_lock_state is lazily initialized per 15m bucket in _v229_open_lock_tick.
