# =============================================================================
# V23.0 — TUG-FIRST CONTROL TRANSFER / LOCK CONFLUENCE FIX
# =============================================================================
# Fixes found during full V22.9 audit:
#   1) V22 route/lock code read tug['signed']/tug['score'], while the actual Tug
#      reader publishes tug['fused']. That silently zeroed Tug inside route,
#      barrier and lock decisions even while the UI showed a live Tug card.
#   2) The old round-flow Tug accumulated the WHOLE 15m round, making it too stale
#      for fast flips. V23 uses short native Bookmap horizons (2s/5s/15s), price
#      response, absorption, depth and quote change for decision Tug.
#   3) Reversal % was fundamentally "edge decay from a peak". When the peak edge
#      was small, modest weakening could look like a huge reversal even without
#      coherent opposite control. V23 measures actual replacement-side evidence.
#   4) V22.9 lock qualification used a permissive OR (route OR tiny barrier gap)
#      plus an ultra-loose deadline assist. V23 requires breadth: at least two
#      independent families, with route/barrier/tug providing a real core reason.
#
# Philosophy: fast tape stays fast, belief changes only when multiple independent
# families agree. Kalshi odds remain display context and NEVER directional Tug
# authority in Bookmap mode.
# =============================================================================
_V230_RELEASE='V23.1 TUG/FLOW/FLIP FIXED'
_V230_PREV_TERMINAL=_v220_terminal_read
_V230_PREV_LOCK_PACKET=_v229_lock_packet
_V230_PREV_PRIORITY=_v297_priority_refresh
_V230_PREV_PUBLISH=_v220_publish


def _v230_clip(v,lo=-1.0,hi=1.0):
    try:
        x=float(v)
        if not math.isfinite(x): return 0.0
        return max(float(lo),min(float(hi),x))
    except Exception:return 0.0


def _v230_native_tug(self,now=None):
    """Decision Tug. Bookmap-only authority; no Kalshi odds vote."""
    now=float(now or time.time())
    mode=str(getattr(self,'v220_source_mode',globals().get('_V220_SOURCE_MODE','BOOKMAP'))).upper()
    # Non-Bookmap builds keep the old Tug, but normalize its ACTUAL published key.
    if mode!='BOOKMAP':
        try: old=dict(_v2672_tug_read(self,now=now) or {})
        except Exception: old={}
        s=_v230_clip(old.get('fused',old.get('signed',old.get('score',0.0))))
        out=dict(old);out.update({'signed':s,'raw_signed':s,'persistence':1.0 if abs(s)>=.08 else 0.0,
                                  'decision_source':'LEGACY TUG NORMALIZED','families_live':int(old.get('families',0) or 0)})
        return out
    try:n=dict(_v19_native_bookmap_metrics(self,now=now) or {})
    except Exception:n={}
    if not n.get('ready'):
        try: old=dict(_v2672_tug_read(self,now=now) or {})
        except Exception: old={}
        s=_v230_clip(old.get('fused',0.0))
        out=dict(old);out.update({'signed':s,'raw_signed':s,'persistence':0.0,'decision_source':'LEGACY FALLBACK',
                                  'families_live':int(old.get('families',0) or 0)})
        return out
    f2=dict(n.get('flow2') or {});f5=dict(n.get('flow5') or {});f15=dict(n.get('flow15') or {})
    exec_flow=_v230_clip(.50*float(f2.get('imbalance',0) or 0)+.32*float(f5.get('imbalance',0) or 0)+.18*float(f15.get('imbalance',0) or 0))
    m2=float(f2.get('move_bp',0) or 0);m5=float(f5.get('move_bp',0) or 0);acc=float(n.get('accel_bp',0) or 0)
    price_response=_v230_clip(.50*(m2/2.2)+.32*(m5/3.6)+.18*(acc/2.4))
    absorb_side=str(n.get('absorption_side','NEUTRAL') or 'NEUTRAL').upper();astr=_v230_clip(n.get('absorption_strength',0),0,1)
    absorption=(1.0 if absorb_side=='UP' else -1.0 if absorb_side=='DOWN' else 0.0)*astr
    depth=_v230_clip(n.get('depth_imbalance',0));quote=_v230_clip(float(n.get('quote_delta',0) or 0)*1.35)
    large_side=str(n.get('large_side','NEUTRAL') or 'NEUTRAL').upper();large_mag=_v230_clip(n.get('large_strength',0),0,1)
    large=(1.0 if large_side=='UP' else -1.0 if large_side=='DOWN' else 0.0)*large_mag
    # Effort-vs-result is crucial. Aggressive buys that cannot lift price are not
    # bullish control; aggressive sells that cannot push lower are not bearish.
    effort_fail=0.0
    if exec_flow>=.20 and price_response<=.02: effort_fail=-min(.55,exec_flow*.75+astr*.35)
    elif exec_flow<=-.20 and price_response>=-.02: effort_fail=min(.55,abs(exec_flow)*.75+astr*.35)
    raw=_v230_clip(.28*exec_flow+.29*price_response+.17*absorption+.09*depth+.07*quote+.05*large + .38*effort_fail)
    st=dict(getattr(self,'_v230_tug_state',{}) or {})
    hist=deque(st.get('hist',[]),maxlen=100);hist.append((now,raw))
    while hist and now-hist[0][0]>3.0:hist.popleft()
    vals=[v for t,v in hist if now-t<=1.5]
    med=_v220_median(vals) if vals else raw
    prev=float(st.get('stable',med if med is not None else raw) or 0.0)
    # responsive enough for a true transfer, slow enough to ignore a lone print
    stable=_v230_clip(prev+max(-.08,min(.08,(float(med)-prev)*.34)))
    signs=[1 if v>.06 else -1 if v<-.06 else 0 for _t,v in hist];nz=[s for s in signs if s]
    pers=abs(sum(nz))/len(nz) if nz else 0.0
    st={'hist':list(hist),'stable':stable,'ts':now};self._v230_tug_state=st
    side='UP' if stable>=.08 else 'DOWN' if stable<=-.08 else 'EVEN'
    fam_live=sum(1 for x in (float(f2.get('n',0) or 0)>=2,float(f5.get('n',0) or 0)>=3,abs(depth)>.02,astr>.08,abs(quote)>.03) if x)
    return {'ready':True,'side':side,'signed':stable,'raw_signed':raw,'fused':stable,
            'up_force':50+50*stable,'force':50+50*abs(stable),'persistence':pers,'families_live':fam_live,
            'decision_source':'NATIVE BOOKMAP 2s/5s/15s TUG','exec_flow':exec_flow,'price_response':price_response,
            'absorption_signed':absorption,'depth_signed':depth,'quote_signed':quote,'large_signed':large,
            'effort_fail':effort_fail,'native':n,
            'headline':f'DECISION TUG: {side} {50+50*abs(stable):.0f}% • persistence {pers*100:.0f}%'}


# Critical bug fix: V22 resolves this global dynamically. Return normalized Tug
# fields under the names V22 actually consumes.
def _v220_tug(self,now=None):
    return _v230_native_tug(self,now=now)


def _v230_transfer_features(out):
    side=str(out.get('terminal_side','NEUTRAL') or 'NEUTRAL').upper()
    signed=float(out.get('terminal_signed',0.0) or 0.0)
    tug=dict(out.get('tug') or {});ts=_v230_clip(tug.get('signed',tug.get('fused',0.0)))
    tp=max(0.0,min(1.0,float(tug.get('persistence',0.0) or 0.0)))
    mbi=dict(out.get('mbi') or {});m=_v230_clip(float(mbi.get('forward_score',mbi.get('score',0.0)) or 0)/100.0)
    up=float(out.get('up_viability',50) or 50);dn=float(out.get('down_viability',50) or 50)
    return side,signed,ts,tp,m,up,dn


def _v230_terminal_read(self,now=None):
    now=float(now or time.time());out=dict(_V230_PREV_TERMINAL(self,now=now) or {})
    if not out.get('ready'):return out
    side_raw,signed,tug,tug_p,mbi,up,dn=_v230_transfer_features(out)
    bucket=int(now//900)*900
    st=dict(getattr(self,'_v230_transfer_state',{}) or {})
    if int(st.get('bucket',-1) or -1)!=bucket:
        anchor=str((getattr(self,'opening_lock_snapshot',{}) or {}).get('lock_side') or side_raw).upper()
        if anchor not in ('UP','DOWN'):anchor='UP' if signed>=0 else 'DOWN'
        st={'bucket':bucket,'anchor':anchor,'shown':0.0,'hist':[],'confirm_side':'WAIT','confirm_since':0.0,
            'confirmed_until':0.0,'last_ts':now,'last_target':0.0}
    # Once a real opening lock exists, initialize anchor from it only if this
    # transfer state has not already confirmed a subsequent control transfer.
    lock_side=str((getattr(self,'opening_lock_snapshot',{}) or {}).get('lock_side','WAIT')).upper()
    if lock_side in ('UP','DOWN') and not st.get('ever_confirmed') and str(st.get('anchor'))!=lock_side:
        st['anchor']=lock_side;st['shown']=0.0;st['hist']=[]
    anchor=str(st.get('anchor','UP')).upper();asg=1.0 if anchor=='UP' else -1.0;opp='DOWN' if anchor=='UP' else 'UP';osg=-asg
    # Absolute replacement evidence. No relative-to-small-peak explosion.
    route_opp=max(0.0,min(1.0,((signed*osg)-.025)/.24))
    gap_signed=(dn-up)/20.0 if opp=='DOWN' else (up-dn)/20.0
    barrier_opp=max(0.0,min(1.0,(gap_signed-.05)/.85))
    tug_opp=max(0.0,min(1.0,((tug*osg)-.04)/.46))
    mbi_opp=max(0.0,min(1.0,((mbi*osg)-.06)/.48))
    fam_vals={'ROUTE':route_opp,'BARRIER':barrier_opp,'TUG':tug_opp,'MBI':mbi_opp}
    breadth=sum(1 for v in fam_vals.values() if v>=.24)
    core=sum(1 for k in ('ROUTE','BARRIER','TUG') if fam_vals[k]>=.24)
    score=100.0*(.30*route_opp+.25*barrier_opp+.30*tug_opp+.15*mbi_opp)
    score += max(0,breadth-1)*6.0
    # A single-family burst can alert, but can never look like a true flip.
    if breadth<2 or core<1:score=min(score,38.0)
    if tug_p<.38 and tug_opp>=.24:score=min(score,68.0)
    score=max(0.0,min(135.0,score))
    hist=deque(st.get('hist',[]),maxlen=120);hist.append((now,score))
    while hist and now-hist[0][0]>3.5:hist.popleft()
    recent=[v for t,v in hist if now-t<=1.6];target=_v220_median(recent) if recent else score
    target=float(target if target is not None else score)
    shown=float(st.get('shown',0.0) or 0.0);last=float(st.get('last_ts',now) or now);dt=max(0.0,min(.30,now-last))
    # Time-normalized meter. Strong 3-family transfers can confirm quickly;
    # two-family warnings build slower. Repair is deliberately slower than raw.
    rise_rate=22.0 if breadth>=3 and core>=2 and tug_p>=.55 else 12.0
    fall_rate=8.0
    if target>shown+3.0:shown=min(target,shown+rise_rate*dt)
    elif target<shown-3.0:shown=max(target,shown-fall_rate*dt)
    shown=max(0.0,min(125.0,shown))
    # Confirmation requires replacement-path breadth + real Tug participation.
    confirm_ok=(shown>=100.0 and breadth>=3 and core>=2 and tug_opp>=.28 and tug_p>=.52 and
                (route_opp>=.24 or barrier_opp>=.30))
    cs=float(st.get('confirm_since',0.0) or 0.0);cside=str(st.get('confirm_side','WAIT'))
    if confirm_ok:
        if cside!=opp:cs=now;cside=opp
    else:cs=0.0;cside='WAIT'
    confirmed=bool(confirm_ok and cs and now-cs>=.65)
    if confirmed:
        # Transfer the working anchor, then latch a visible confirmation. The
        # historical MAIN LOCK remains untouched; this is current-control state.
        st['anchor']=opp;st['ever_confirmed']=True;st['confirmed_until']=now+3.0;st['confirmed_side']=opp
        shown=100.0;hist=deque([(now,0.0)],maxlen=120);cs=0.0;cside='WAIT'
        out['terminal_side']=opp
    else:
        out['terminal_side']=anchor
    latched=now<float(st.get('confirmed_until',0.0) or 0.0)
    if latched:
        shown=max(shown,100.0)
    elif st.get('ever_confirmed') and float(st.get('confirmed_until',0.0) or 0.0)>0.0 and now>=float(st.get('confirmed_until',0.0) or 0.0):
        # Confirmation completed a control transfer. Start the next meter from
        # the new anchor instead of leaving a stale 80-95% number on screen.
        shown=0.0;hist=deque([(now,0.0)],maxlen=120);st['confirmed_until']=0.0
    state='FLIP CONFIRMED' if latched else 'FLIP ARMED' if shown>=75 else 'REVERSAL BUILDING' if shown>=35 else 'ROUTE HEALTHY'
    st.update({'shown':shown,'hist':list(hist),'confirm_since':cs,'confirm_side':cside,'last_ts':now,'last_target':target})
    self._v230_transfer_state=st
    out.update({'reversal_pct':shown,'reversal_health':'invalid' if latched else 'weak' if shown>=55 else 'healthy',
                'flip_state_v230':state,'flip_confirmed_v230':latched,'flip_to_v230':str(st.get('confirmed_side',opp) if latched else opp),
                'transfer_target_v230':target,'transfer_breadth_v230':breadth,'transfer_core_v230':core,
                'transfer_families_v230':fam_vals,'decision_tug_v230':dict(out.get('tug') or {}),
                'reversal_velocity':(target-shown), 'current_control':str(st.get('anchor',anchor))})
    self._v220_last=out
    return out

_v220_terminal_read=_v230_terminal_read


def _v230_lock_packet(self,route,into,mode='BOOKMAP',now=None):
    """0..180s lock: breadth beats tiny-threshold OR logic."""
    r=dict(route or {});now=float(now or time.time());reg=_v229_regime_read(self,r,now)
    up=float(r.get('up_viability',50) or 50);dn=float(r.get('down_viability',50) or 50)
    signed=float(r.get('terminal_signed',0) or 0);mbi=dict(r.get('mbi') or {});tug=dict(r.get('tug') or {})
    m=float(mbi.get('forward_score',mbi.get('score',0)) or 0)/100.0;t=_v230_clip(tug.get('signed',tug.get('fused',0.0)))
    tp=max(0.0,min(1.0,float(tug.get('persistence',0.0) or 0.0)))
    barrier=_v230_clip((up-dn)/35.0)
    # Tug gets real weight now because it is a fresh native control read.
    composite=_v230_clip(.34*barrier+.25*signed+.16*_v230_clip(m)+.25*t)
    side='UP' if composite>0 else 'DOWN' if composite<0 else ('UP' if up>dn else 'DOWN' if dn>up else 'WAIT')
    sgn=1.0 if side=='UP' else -1.0 if side=='DOWN' else 0.0
    ba=barrier*sgn;ra=signed*sgn;ma=m*sgn;ta=t*sgn
    fam={'BARRIER':ba>=.08,'ROUTE':ra>=.055,'MBI':ma>=.10,'TUG':ta>=.10 and tp>=.42}
    breadth=sum(1 for v in fam.values() if v);core=sum(1 for k in ('BARRIER','ROUTE','TUG') if fam[k])
    hard_opp=(ma<=-.52) or (ta<=-.42 and tp>=.58)
    window=(0.0<=float(into)<=180.0);progress=max(0.0,min(1.0,float(into)/180.0))
    name=str(reg.get('name','MIXED'))
    edge_need=.050 if name.startswith(('BREAKOUT','STRAIGHT')) else .045 if name.startswith(('FLIPPY','RANGE')) else .055
    edge_need=max(.030,edge_need-.012*progress)
    need_s=.70 if name.startswith('BREAKOUT') else .90 if name.startswith('STRAIGHT') else 1.10 if name.startswith('FLIPPY') else 1.20
    need_s=max(.65,need_s-.25*progress)
    # Never manufacture a side from one lonely family, even at the deadline.
    qualified=bool(window and side in ('UP','DOWN') and not hard_opp and breadth>=2 and core>=1 and
                   (abs(composite)>=edge_need or (breadth>=3 and abs(composite)>=edge_need*.68)))
    # In the final 15 seconds, allow broad 3-family agreement with modest edge,
    # but remove the old "0.55 barrier gap alone" deadline loophole.
    deadline=bool(window and into>=165 and breadth>=3 and core>=2 and not hard_opp and abs(composite)>=.020)
    qualified=qualified or deadline
    strength=max(51.0,min(94.0,50+abs(composite)*145+breadth*3.2+abs(ta)*7+abs(ma)*5))
    levels=dict(r.get('levels') or _v229_level_map(self,r,now))
    return {'side':side,'qualified':qualified,'window_open':window,'deadline':deadline,'composite':composite,
            'gap':abs(up-dn),'up':up,'down':dn,'mbi_align':ma*100,'tug_align':ta,'tug_persistence':tp,
            'need_s':need_s,'strength':strength,'regime':reg,'levels':levels,'breadth':breadth,'core':core,'families':fam,
            'reason':f'{name} • confluence {breadth}/4 core {core}/3 • route {ra:+.2f} • barriers {up:.0f}/{dn:.0f} • MBI {ma*100:+.0f} • TUG {ta:+.2f} ({tp*100:.0f}% persist)'}

_v229_lock_packet=_v230_lock_packet


def _v230_publish(self,out):
    _V230_PREV_PUBLISH(self,out)
    try:
        meter=float(out.get('reversal_pct',0) or 0);state=str(out.get('flip_state_v230','ROUTE HEALTHY'));to=str(out.get('flip_to_v230','WAIT'))
        tug=dict(out.get('tug') or {});breadth=int(out.get('transfer_breadth_v230',0) or 0)
        self.trend_reversal_risk_value=min(100.0,meter)
        self._set_var_if_changed(self.trend_reversal_risk_var,f'CONTROL TRANSFER {meter:.0f}/100')
        self._set_var_if_changed(self.trend_reversal_status_var,state)
        self._set_var_if_changed(self.trend_reversal_detail_var,
            f'{state} → {to} • {breadth}/4 transfer families • decision Tug {float(tug.get("signed",0) or 0):+.2f} • persistence {float(tug.get("persistence",0) or 0)*100:.0f}%')
    except Exception:pass

_v220_publish=_v230_publish


def _v230_priority_refresh(app):
    _V230_PREV_PRIORITY(app)
    try:
        snap=dict(getattr(app,'_v220_last',{}) or {});meter=float(snap.get('reversal_pct',0) or 0)
        state=str(snap.get('flip_state_v230','ROUTE HEALTHY'));to=str(snap.get('flip_to_v230','WAIT'));breadth=int(snap.get('transfer_breadth_v230',0) or 0)
        tug=dict(snap.get('tug') or {});tp=float(tug.get('persistence',0) or 0)
        app.v297_flip_var.set(f'{min(100,meter):.0f}%')
        app.v297_flip_meta_var.set(f'{state} → {to} • {breadth}/4 • TUG {float(tug.get("signed",0) or 0):+.2f} / {tp*100:.0f}%')
        confirmed=bool(snap.get('flip_confirmed_v230'))
        col=_v297_color_for_side(to,_V2676_RED if meter>=45 else _V2676_MUTED)
        app.v297_flip_label.configure(fg=col);app.v297_flip_card.configure(highlightbackground='#ffffff' if confirmed else col if meter>=45 else _V2676_BORDER)
        _v297_draw_flip_meter(app.v297_flip_canvas,min(100,meter),to,confirmed)
        # Put the DECISION Tug on the priority rail. This is the actual short-horizon
        # control signal being used by calls/flips, not the stale whole-round tally.
        if hasattr(app,'v2676_tug_var'):
            s=float(tug.get('signed',0) or 0);side='UP' if s>.06 else 'DOWN' if s<-.06 else 'EVEN'
            app.v2676_tug_var.set(f'{side} {50+50*abs(s):.0f}%')
        if hasattr(app,'v2676_tug_meta_var'):
            app.v2676_tug_meta_var.set(f'2s/5s/15s • {tp*100:.0f}% persist')
    except Exception:pass

_v297_priority_refresh=_v230_priority_refresh


# V23 intentionally adds no __init__ wrapper; state is lazily created to avoid
# deep-wrapper recursion in this legacy codebase.
# END V23.0

# V23 owns FIRST-LOCK creation. V22.9 used to call the entire inherited V22.8 /
# V22.7 lock chain first, which meant an older permissive rule could still earn
# a bad lock before the repaired V23 confluence packet was even evaluated.
_V230_LEGACY_OPEN_TICK=ChartKingPro._bookmap_opening_lock_tick

def _v230_open_lock_tick(self,warm=None,now=None):
    now=float(now or time.time());bucket=int(now//900)*900;into=max(0.0,now-bucket)
    existing=dict(getattr(self,'opening_lock_snapshot',{}) or {})
    if str(existing.get('lock_side','WAIT')).upper() in ('UP','DOWN'):
        # After first lock, preserve inherited downstream/PLAN-CHANGED machinery.
        try:_V230_LEGACY_OPEN_TICK(self,warm=warm,now=now)
        except Exception:pass
        try:_v229_journey(self,now=now)
        except Exception:pass
        return dict(getattr(self,'opening_lock_snapshot',{}) or existing)
    # PRE-LOCK: do NOT let older V22.7/V22.8 thresholds pre-empt V23.
    try:r=dict(getattr(self,'_v220_last',{}) or {})
    except Exception:r={}
    if not r.get('ready') or now-float(r.get('ts',now) or now)>1.5:
        try:r=dict(_v220_terminal_read(self,now=now) or {})
        except Exception:r={}
    if not r.get('ready'):
        try:_v229_journey(self,now=now)
        except Exception:pass
        return None
    q=_v230_lock_packet(self,r,into,str(getattr(self,'v220_source_mode','BOOKMAP')).upper(),now)
    try:_v229_journey(self,now=now)
    except Exception:pass
    reg=dict(q.get('regime') or {})
    if not q.get('window_open'):
        try:self.opening_lock_var.set(f'FIRST-LOCK WINDOW CLOSED • {reg.get("name","--")} • journey still mapping')
        except Exception:pass
        return None
    st=dict(getattr(self,'_v230_lock_state',{}) or {})
    if int(st.get('bucket',-1) or -1)!=bucket:
        st={'bucket':bucket,'side':'WAIT','since':0.0,'evidence':0.0,'last_eval':0.0}
    if now-float(st.get('last_eval',0.0) or 0.0)<.20:
        self._v230_lock_state=st;return None
    st['last_eval']=now
    if q['qualified']:
        if st.get('side')!=q['side']:st.update({'side':q['side'],'since':now,'evidence':1.0})
        else:st['evidence']=min(50.0,float(st.get('evidence',0) or 0)+1.0)
    else:
        st['evidence']=max(0.0,float(st.get('evidence',0) or 0)-.35)
        if st['evidence']<=0:st.update({'side':'WAIT','since':0.0})
    self._v230_lock_state=st
    age=max(0.0,now-float(st.get('since',now) or now)) if st.get('side') in ('UP','DOWN') else 0.0
    try:self.opening_lock_var.set(f'FORMULATING {q["side"]} • {q["strength"]:.0f}/100 • CONFLUENCE {q["breadth"]}/4 • {age:.1f}/{q["need_s"]:.1f}s • {q["reason"]}')
    except Exception:pass
    need_e=max(2.0,q['need_s']*3.0)
    if (not q['qualified'] or st.get('side')!=q['side'] or age<q['need_s'] or float(st.get('evidence',0) or 0)<need_e):return None
    try:live,_=self.effective_live_price();target,_=self.effective_target()
    except Exception:return None
    if live is None or target is None:return None
    side=q['side'];strength=q['strength']
    snap={'time':now,'price':float(live),'lock_side':side,'strength':strength,'bucket':bucket,'market_bucket':bucket,
          'source':'V23.0 CONFLUENCE FIRST LOCK','forecast_reasons':q['reason'],'forecast_score':q['composite']*10.0,
          'forecast_threshold':0.0,'lock_remaining':'OPEN','lock_minute':int(into//60),'regime':reg.get('name')}
    self.opening_lock_snapshot=dict(snap);self.opening_lock_candidate=None;self.opening_lock_candidate_since=0.0
    try:
        thesis=getattr(self,'_v279_thesis',None)
        if isinstance(thesis,dict):
            thesis.update({'status':'LOCKED','side':side,'strength':strength,'locked_at':now,'opening_score':q['composite'],
                           'opening_meta':dict(q),'last_reason':'V23.0 '+q['reason']})
            self._v279_thesis=thesis
    except Exception:pass
    try:self.opening_lock_var.set(f'MAIN LOCK: {side} {strength:.0f}/100 • V23 EARNED @ {into:.1f}s • {q["breadth"]}/4 CONFLUENCE • {q["reason"]}')
    except Exception:pass
    return dict(snap)

ChartKingPro._bookmap_opening_lock_tick=_v230_open_lock_tick



# =============================================================================
# V23.1 — FAST/FAITHFUL TUG + LIVE EXECUTED FLOW + FLIP/SWITCH CONSISTENCY
# =============================================================================
# Live bug fixes from V23.0 field use:
#   • Tug display/decision was over-smoothed and could lag a real transfer.
#   • EXECUTED FLOW cockpit card was still reading the old whole-round Tug flow,
#     so rounded percentages/counts could appear frozen even while native 2s/5s
#     Bookmap flow was changing.
#   • Legacy PLAN CHANGED could still rewrite MAIN LOCK without V23's replacement
#     control transfer having actually confirmed. That could produce a DOWN->UP
#     MAIN LOCK switch while the live V23 Tug/route did not support UP.
#   • V23.0 flip confirmation required the DISPLAY meter itself to crawl to 100.
#     A real 3-family transfer could therefore remain ARMED indefinitely even
#     when the replacement path was already coherent.
#
# V23.1 separates FAST OBSERVATION from BELIEF:
#   raw/native flow updates immediately; decision Tug has short hysteresis;
#   flip confirmation uses persistent replacement evidence, not UI travel time.
# =============================================================================
_V231_RELEASE='V23.1 FAST TUG + LIVE FLOW + GUARDED CONTROL TRANSFER'
_V231_PREV_PRIORITY=_v297_priority_refresh
_V231_PREV_PLAN_CHANGE=_v279_plan_change_sample
_V231_PREV_TERMINAL=_v220_terminal_read


def _v231_sgn(v,dead=.055):
    try:x=float(v)
    except Exception:x=0.0
    return 1 if x>dead else -1 if x<-dead else 0


def _v231_native_tug(self,now=None):
    """Fast native Bookmap Tug with separate raw/display/decision lanes."""
    now=float(now or time.time())
    mode=str(getattr(self,'v220_source_mode',globals().get('_V220_SOURCE_MODE','BOOKMAP'))).upper()
    if mode!='BOOKMAP':
        try:old=dict(_v2672_tug_read(self,now=now) or {})
        except Exception:old={}
        s=_v230_clip(old.get('fused',old.get('signed',old.get('score',0.0))))
        return dict(old, signed=s, raw_signed=s, display_signed=s,
                    persistence=1.0 if abs(s)>=.08 else 0.0,
                    decision_source='LEGACY TUG NORMALIZED')
    try:n=dict(_v19_native_bookmap_metrics(self,now=now) or {})
    except Exception:n={}
    if not n.get('ready'):
        try:old=dict(_v2672_tug_read(self,now=now) or {})
        except Exception:old={}
        s=_v230_clip(old.get('fused',0.0))
        return dict(old,signed=s,raw_signed=s,display_signed=s,persistence=0.0,
                    decision_source='LEGACY FALLBACK')

    f2=dict(n.get('flow2') or {});f5=dict(n.get('flow5') or {});f15=dict(n.get('flow15') or {})
    i2=float(f2.get('imbalance',0) or 0);i5=float(f5.get('imbalance',0) or 0);i15=float(f15.get('imbalance',0) or 0)
    exec_flow=_v230_clip(.56*i2+.29*i5+.15*i15)
    m2=float(f2.get('move_bp',0) or 0);m5=float(f5.get('move_bp',0) or 0);acc=float(n.get('accel_bp',0) or 0)
    price_response=_v230_clip(.55*(m2/2.1)+.30*(m5/3.5)+.15*(acc/2.3))
    absorb_side=str(n.get('absorption_side','NEUTRAL') or 'NEUTRAL').upper();astr=_v230_clip(n.get('absorption_strength',0),0,1)
    absorption=(1.0 if absorb_side=='UP' else -1.0 if absorb_side=='DOWN' else 0.0)*astr
    depth=_v230_clip(n.get('depth_imbalance',0));quote=_v230_clip(float(n.get('quote_delta',0) or 0)*1.25)
    large_side=str(n.get('large_side','NEUTRAL') or 'NEUTRAL').upper();large_mag=_v230_clip(n.get('large_strength',0),0,1)
    large=(1.0 if large_side=='UP' else -1.0 if large_side=='DOWN' else 0.0)*large_mag

    # Effort vs result: aggressive prints without matching price response are
    # absorption evidence for the OTHER side, not continuation evidence.
    effort_fail=0.0
    if exec_flow>=.18 and price_response<=.015:
        effort_fail=-min(.62,exec_flow*.85+astr*.42)
    elif exec_flow<=-.18 and price_response>=-.015:
        effort_fail=min(.62,abs(exec_flow)*.85+astr*.42)

    raw=_v230_clip(.31*exec_flow+.31*price_response+.17*absorption+.07*depth+.05*quote+.04*large+.34*effort_fail)
    st=dict(getattr(self,'_v231_tug_state',{}) or {})
    hist=deque(st.get('hist',[]),maxlen=160);hist.append((now,raw))
    while hist and now-hist[0][0]>1.6:hist.popleft()
    last=float(st.get('ts',now) or now);dt=max(.01,min(.25,now-last))

    # Display lane: ~250ms response, no huge one-frame teleport.
    disp_prev=float(st.get('display',raw) or 0.0)
    a_disp=1.0-math.exp(-dt/.16)
    disp_target=raw
    display=_v230_clip(disp_prev+(disp_target-disp_prev)*a_disp)
    max_disp_step=1.35*dt
    display=_v230_clip(disp_prev+max(-max_disp_step,min(max_disp_step,display-disp_prev)))

    # Decision lane: median over ~0.55s plus a short EMA. This rejects isolated
    # prints but can reverse meaningfully inside ~0.6-1.0s when control transfers.
    vals=[v for t,v in hist if now-t<=.35]
    med=_v220_median(vals) if vals else raw
    dec_prev=float(st.get('decision',med if med is not None else raw) or 0.0)
    a_dec=1.0-math.exp(-dt/.24)
    decision=_v230_clip(dec_prev+(float(med)-dec_prev)*a_dec)
    max_dec_step=1.05*dt
    decision=_v230_clip(dec_prev+max(-max_dec_step,min(max_dec_step,decision-dec_prev)))

    # Persistence = fraction of meaningful recent samples agreeing with CURRENT
    # decision side. Old opposite samples stop suppressing a fresh transfer quickly.
    ds=_v231_sgn(decision,.06)
    recent=[v for t,v in hist if now-t<=.72 and _v231_sgn(v,.05)!=0]
    if ds and recent:
        pers=sum(1 for v in recent if _v231_sgn(v,.05)==ds)/len(recent)
    else:pers=0.0
    side='UP' if decision>=.065 else 'DOWN' if decision<=-.065 else 'EVEN'
    fam_live=sum(1 for x in (float(f2.get('n',0) or 0)>=2,float(f5.get('n',0) or 0)>=3,
                              abs(depth)>.02,astr>.08,abs(quote)>.03) if x)
    st={'hist':list(hist),'display':display,'decision':decision,'ts':now};self._v231_tug_state=st
    return {'ready':True,'side':side,'signed':decision,'raw_signed':raw,'display_signed':display,'fused':decision,
            'up_force':50+50*decision,'force':50+50*abs(decision),'persistence':pers,'families_live':fam_live,
            'decision_source':'V23.1 NATIVE BOOKMAP 2s/5s/15s TUG','exec_flow':exec_flow,'price_response':price_response,
            'absorption_signed':absorption,'depth_signed':depth,'quote_signed':quote,'large_signed':large,
            'effort_fail':effort_fail,'native':n,
            'headline':f'DECISION TUG: {side} {50+50*abs(decision):.0f}% • persistence {pers*100:.0f}%'}


