def _v231_terminal_read(self,now=None):
    """Replacement-side meter that confirms coherent flips without waiting for UI=100."""
    now=float(now or time.time())
    # Call V23.0 terminal then repair confirmation semantics using its normalized
    # feature packet. This preserves all route/barrier mapping work.
    out=dict(_V231_PREV_TERMINAL(self,now=now) or {})
    if not out.get('ready'):return out

    # V23.0 may have already latched a transfer. Preserve that result.
    if bool(out.get('flip_confirmed_v230')):
        try:
            st=dict(getattr(self,'_v231_flip_state',{}) or {})
            st.update({'bucket':int(now//900)*900,'confirmed_side':str(out.get('flip_to_v230','WAIT')),
                       'confirmed_ts':now,'shown':100.0,'confirmed_until':now+2.5})
            self._v231_flip_state=st
        except Exception:pass
        return out

    anchor=str(out.get('current_control') or (getattr(self,'opening_lock_snapshot',{}) or {}).get('lock_side') or out.get('terminal_side','WAIT')).upper()
    if anchor not in ('UP','DOWN'):
        anchor='UP' if float(out.get('terminal_signed',0) or 0)>=0 else 'DOWN'
    opp='DOWN' if anchor=='UP' else 'UP';osg=-1.0 if anchor=='UP' else 1.0
    signed=float(out.get('terminal_signed',0) or 0)
    tug=dict(out.get('tug') or {});ts=_v230_clip(tug.get('signed',tug.get('fused',0.0)));tp=max(0,min(1,float(tug.get('persistence',0) or 0)))
    mbi=dict(out.get('mbi') or {});m=_v230_clip(float(mbi.get('forward_score',mbi.get('score',0)) or 0)/100.0)
    up=float(out.get('up_viability',50) or 50);dn=float(out.get('down_viability',50) or 50)
    route=max(0.0,min(1.0,((signed*osg)-.02)/.23))
    gap=(dn-up)/20.0 if opp=='DOWN' else (up-dn)/20.0
    barrier=max(0.0,min(1.0,(gap-.04)/.82))
    tugopp=max(0.0,min(1.0,((ts*osg)-.035)/.43))
    mbiopp=max(0.0,min(1.0,((m*osg)-.055)/.46))
    fam={'ROUTE':route,'BARRIER':barrier,'TUG':tugopp,'MBI':mbiopp}
    breadth=sum(v>=.23 for v in fam.values());core=sum(fam[k]>=.23 for k in ('ROUTE','BARRIER','TUG'))
    raw=100*(.29*route+.24*barrier+.32*tugopp+.15*mbiopp)+max(0,breadth-1)*5.5
    if breadth<2 or core<1:raw=min(raw,32.0)
    if tugopp>=.23 and tp<.40:raw=min(raw,56.0)
    raw=max(0,min(115,raw))

    st=dict(getattr(self,'_v231_flip_state',{}) or {});bucket=int(now//900)*900
    if int(st.get('bucket',-1) or -1)!=bucket:
        st={'bucket':bucket,'shown':0.0,'candidate':'WAIT','since':0.0,'confirmed_until':0.0,'confirmed_side':'WAIT','last':now}
    last=float(st.get('last',now) or now);dt=max(.01,min(.25,now-last));shown=float(st.get('shown',0) or 0)
    # Smooth enough to ignore a lone print; quick enough for a genuine control transfer.
    rise=34.0 if breadth>=3 and core>=2 and tp>=.50 else 18.0
    fall=15.0
    target=raw
    if target>shown+2:shown=min(target,shown+rise*dt)
    elif target<shown-2:shown=max(target,shown-fall*dt)

    # Confirm from persistent REPLACEMENT EVIDENCE, not from waiting for the
    # rendered meter to physically crawl to 100.
    confirm_basis=(raw>=76 and breadth>=3 and core>=2 and tugopp>=.25 and tp>=.48 and (route>=.22 or barrier>=.27))
    cand=str(st.get('candidate','WAIT'));since=float(st.get('since',0) or 0)
    if confirm_basis:
        if cand!=opp:cand=opp;since=now
    else:cand='WAIT';since=0.0
    confirmed=bool(confirm_basis and cand==opp and since and now-since>=.58)
    if confirmed:
        shown=100.0;st['confirmed_until']=now+2.5;st['confirmed_side']=opp;st['confirmed_ts']=now
        # Current control transfers now; historical opening side remains a record
        # until guarded PLAN CHANGED chooses to rewrite MAIN LOCK.
        out['terminal_side']=opp;out['current_control']=opp
    latched=now<float(st.get('confirmed_until',0) or 0)
    if latched:shown=max(shown,100.0)
    elif float(st.get('confirmed_until',0) or 0)>0 and now>=float(st.get('confirmed_until',0) or 0):
        shown=0.0;st['confirmed_until']=0.0
    state='FLIP CONFIRMED' if latched else 'FLIP ARMED' if shown>=70 else 'REVERSAL BUILDING' if shown>=34 else 'ROUTE HEALTHY'
    st.update({'shown':shown,'candidate':cand,'since':since,'last':now});self._v231_flip_state=st
    out.update({'reversal_pct':shown,'flip_state_v230':state,'flip_confirmed_v230':latched,
                'flip_to_v230':str(st.get('confirmed_side',opp) if latched else opp),
                'transfer_target_v230':raw,'transfer_breadth_v230':breadth,'transfer_core_v230':core,
                'transfer_families_v230':fam,'reversal_health':'invalid' if latched else 'weak' if shown>=55 else 'healthy'})
    self._v220_last=out
    return out

_v220_terminal_read=_v231_terminal_read


def _v231_plan_change_sample(self,now,lock_side,fc):
    """MAIN LOCK cannot switch unless V23 replacement control supports it."""
    row=dict(_V231_PREV_PLAN_CHANGE(self,now,lock_side,fc) or {})
    if not row.get('qualified'):return row
    side=str(lock_side).upper();opp='DOWN' if side=='UP' else 'UP'
    snap=dict(getattr(self,'_v220_last',{}) or {})
    tug=dict(snap.get('tug') or {});ts=float(tug.get('signed',0) or 0);tp=float(tug.get('persistence',0) or 0)
    sgn=1 if opp=='UP' else -1
    fam=dict(snap.get('transfer_families_v230') or {})
    breadth=int(snap.get('transfer_breadth_v230',0) or 0);core=int(snap.get('transfer_core_v230',0) or 0)
    meter=float(snap.get('reversal_pct',0) or 0)
    current=str(snap.get('current_control',snap.get('terminal_side','WAIT'))).upper()
    fs=dict(getattr(self,'_v231_flip_state',{}) or {});cts=float(fs.get('confirmed_ts',0) or 0)
    recent_confirm=(str(fs.get('confirmed_side','WAIT')).upper()==opp and cts and float(now)-cts<=7.0)
    tug_ok=(ts*sgn>=.10 and tp>=.46)
    path_ok=(float(fam.get('ROUTE',0) or 0)>=.22 or float(fam.get('BARRIER',0) or 0)>=.26)
    transfer_ok=bool(current==opp and tug_ok and path_ok and breadth>=3 and core>=2 and (recent_confirm or meter>=70))
    if not transfer_ok:
        row['qualified']=False;row['decisive']=False;row['candidate']='WAIT'
        reasons=list(row.get('reasons') or [])
        reasons.append(f'V23.1 SWITCH VETO: replacement control not confirmed (control {current}, meter {meter:.0f}, breadth {breadth}, TUG {ts:+.2f}/{tp*100:.0f}%)')
        row['reasons']=reasons;row['v231_switch_veto']=True
    else:
        row['v231_switch_gate']='PASS';row['candidate']=opp
    return row

_v279_plan_change_sample=_v231_plan_change_sample


