def _v234_flow_text(flow):
    if not flow.get('ready'):
        return 'WAITING FOR NATIVE BOOKMAP EXECUTIONS • 0 confirmed short-horizon prints'
    f2=flow['flow2'];f5=flow['flow5'];f15=flow['flow15']
    return (f'2s {f2["buy_ratio"]*100:.0f}% BUY / {(1-f2["buy_ratio"])*100:.0f}% SELL • {f2["n"]} prints   |   '
            f'5s {f5["buy_ratio"]*100:.0f}/{(1-f5["buy_ratio"])*100:.0f} • {f5["n"]}   |   '
            f'15s {f15["buy_ratio"]*100:.0f}/{(1-f15["buy_ratio"])*100:.0f} • {f15["n"]}')


