def _v234_update_telemetry(app):
    """Independent telemetry lane: cannot be starved by route/UI exceptions."""
    V=getattr(app,'_v232_vars',{}) or {}; now=time.time()
    if not V:return
    flow=_v232_native_flow(app,now); n,w=_v234_native_telemetry(app,now)
    old=_v232_original_tug(app,now)
    # Executed flow has exactly one source/writer on the visible gold dashboard.
    flowtxt=_v234_flow_text(flow)
    try:V['flowline'].set(flowtxt)
    except Exception:pass

    # ORIGINAL Tug is the only Tug in the bot and the only Tug shown in the UI.
    ou=float(old.get('up_force',50.0) or 50.0); os='UP' if ou>=55 else 'DOWN' if ou<=45 else 'EVEN'
    try:
        V['oldtug'].set(str(old.get('headline') or f'OLD TUG • {os} {max(ou,100-ou):.0f}%'))
        details=[]
        for key in ('price_text','flow_text','kalshi_text','whale_text'):
            v=str(old.get(key,'') or '').strip()
            if v: details.append(v)
        V['oldtugmeta'].set('  |  '.join(details) if details else 'original 4-family fuse building • price / flow / Kalshi / whale')
        _v232_bar(app._v234_old_tug_bar,ou/100.0)
    except Exception:pass

    # Storm Grid — always says what is happening OR what data is missing.
    ready=bool(n.get('ready'))
    whale_dir=str(w.get('direction',n.get('large_side','NEUTRAL')) or 'NEUTRAL').upper()
    whale_like=float(w.get('likelihood',0) or 0); whale_score=float(w.get('signed_score',0) or 0)
    if whale_dir in ('UP','DOWN') and (whale_like>0 or abs(whale_score)>0):
        whale_text=f'{whale_dir} pressure • {max(whale_like,abs(whale_score)):.0f}/100'
    elif ready:
        ls=str(n.get('large_side','NEUTRAL') or 'NEUTRAL').upper(); lm=float(n.get('large_strength',0) or 0)
        whale_text=(f'{ls} large-liquidity pressure • {lm*100:.0f}%' if ls in ('UP','DOWN') and lm>.04 else 'no dominant whale pressure')
    else:whale_text='waiting for Bookmap depth + executions'
    try:V['whale'].set(whale_text)
    except Exception:pass

    accel=float(n.get('accel_bp',0) or 0); f2=dict(n.get('flow2') or {}); f5=dict(n.get('flow5') or {})
    if ready:
        state='BUY ACCEL' if accel>.18 else 'SELL ACCEL' if accel<-.18 else 'BALANCED / SLOW'
        accel_text=f'{state} • {accel:+.2f} bp • 2s imb {float(f2.get("imbalance",0) or 0):+.2f} • 5s {float(f5.get("imbalance",0) or 0):+.2f}'
    else:accel_text='waiting for enough executions to measure acceleration'
    try:V['accel'].set(accel_text)
    except Exception:pass

    di=float(n.get('depth_imbalance',0) or 0); bc=float(n.get('bid_concentration',0) or 0); ac=float(n.get('ask_concentration',0) or 0)
    bd=float(n.get('bid_depth',0) or 0); ad=float(n.get('ask_depth',0) or 0)
    if bd+ad>1e-12:
        if di>.08:wall='BID WALL / BUYERS'
        elif di<-.08:wall='ASK WALL / SELLERS'
        else:wall='DEPTH BALANCED'
        walls_text=f'{wall} • imbalance {di:+.2f} • depth {bd:.2f}/{ad:.2f} • concentration {bc:.2f}/{ac:.2f}'
    else:walls_text='waiting for live Bookmap depth snapshot'
    try:V['walls'].set(walls_text)
    except Exception:pass

    try:lock=dict(getattr(app,'opening_lock_snapshot',{}) or {}); side=str(lock.get('lock_side','WAIT') or 'WAIT').upper()
    except Exception:side='WAIT'
    signed=float(old.get('fused',0) or 0)
    if side not in ('UP','DOWN'):
        attack=f'NO LOCK YET • old Tug {signed:+.2f}'
    else:
        align=signed*(1 if side=='UP' else -1)
        attack=('WITH THE CALL' if align>.08 else 'UNDER ATTACK' if align<-.08 else 'MIXED / NEUTRAL')+f' • Tug alignment {align:+.2f}'
    try:V['attack'].set(attack)
    except Exception:pass

    # Keep the teaching-chart header alive even if the heavier route/dashboard
    # refresh has a temporary exception.
    try:
        route=dict(getattr(app,'_v220_last',{}) or {})
        reg=dict(_v229_regime_read(app,route,now) or {}) if route else {'name':'MIXED / DEVELOPING'}
        mbi=dict(route.get('mbi') or {}); ms=float(mbi.get('forward_score',mbi.get('score',0)) or 0)
        V['mentorread'].set(f'MENTOR READ • {reg.get("name","MIXED")} • MBI {ms:+.0f} • OLD {os} {max(ou,100-ou):.0f}% • NEW {ns} {nf:.0f}%')
        rows=_v234_chart_rows(app,int(getattr(app,'_v232_chart_sec',60) or 60))
        src=str((rows[-1].get('_v234_source','') if rows else '') or 'WAITING')
        V['chartnote'].set(f'{len(rows)} candles • {src} • levels + MBI + dual Tug')
    except Exception:pass
    try:
        live,_=app.effective_live_price(); target,_=app.effective_target()
        if live is not None and target is not None:V['battleline'].set(f'line ${float(target):,.2f} • live ${float(live):,.2f} ({float(live)-float(target):+.2f})')
    except Exception:pass

    # Existing Battle box remains the original Tug so user's trusted read is preserved.
    try:
        up=float(old.get('up_force',50) or 50); side_old='UP' if up>=55 else 'DOWN' if up<=45 else 'EVEN'
        V['battle'].set(f'{side_old} is winning the OLD Tug • {max(up,100-up):.0f}% force' if side_old!='EVEN' else 'OLD TUG is dead even')
        V['tugdetail'].set('OLD/ORIGINAL Tug is MAIN LOCK authority • NEW fast Tug is comparison telemetry only')
        _v232_bar(app._v232_battle_bar,up/100)
        if hasattr(app,'_v232_top_battle_bar'):_v232_bar(app._v232_top_battle_bar,up/100)
    except Exception:pass


def _v234_telemetry_tick(app):
    try:
        if getattr(app,'_v232_shell',None) is None:return
        _v234_update_telemetry(app)
        _v232_draw_mentor_chart(app)
    except Exception as exc:
        try:_v232_add_event(app,'V23.4 telemetry recovered: '+str(exc),_V232_RED)
        except Exception:pass
    finally:
        try:app.root.after(180,lambda a=app:_v234_telemetry_tick(a))
        except Exception:pass

