def _v232_dashboard_tick(app):
    try:
        if getattr(app,'_v232_shell',None) is None:return
        # Legacy layout layers schedule delayed lifts/reflows. V23.2 owns the
        # whole visible surface, so keep the old cockpit buried every refresh.
        try:
            old=getattr(app,'v2676_shell',None)
            if old is not None: old.place_forget()
            app._v2676_showing=False
            app._v232_shell.lift()
        except Exception: pass
        now=time.time();V=app._v232_vars;bucket=int(now//900)*900;into=max(0.0,now-bucket);left=max(0.0,900-(now-bucket))
        try:live,_=app.effective_live_price();live=float(live) if live is not None else None
        except Exception:live=None
        try:target,_=app.effective_target();target=float(target) if target is not None else None
        except Exception:target=None
        lock=dict(getattr(app,'opening_lock_snapshot',{}) or {});side=str(lock.get('lock_side','WAIT') or 'WAIT').upper();strength=float(lock.get('strength',0) or 0)
        route=dict(getattr(app,'_v220_last',{}) or {});reg=dict(_v229_regime_read(app,route,now) or {}) if route else {'name':'MIXED / DEVELOPING','confidence':0}
        tug=_v232_original_tug(app,now);upf=float(tug.get('up_force',50) or 50);tfused=float(tug.get('fused',0) or 0);tp=float(tug.get('persistence',0) or 0)
        flow=_v232_native_flow(app,now);f2=flow['flow2'];f5=flow['flow5'];f15=flow['flow15']
        mode=str(getattr(app,'v220_source_mode',globals().get('_V220_SOURCE_MODE','BOOKMAP'))).upper()
        if mode=='BOOKMAP':V['source'].set('V23.9 • BOOKMAP LIVE' if flow.get('ready') else 'V23.9 • BOOKMAP CONNECTING')
        else:
            ps=str(getattr(getattr(app,'price_source_var',None),'get',lambda:'' )() or '').upper()
            V['source'].set('V23.9 • KALSHI BRTI LIVE' if ('BRTI' in ps and 'WAIT' not in ps and 'NOT CONNECT' not in ps) else 'V23.9 • KALSHI / BTC CONNECTING')
        mbi=dict(route.get('mbi') or {});ms=float(mbi.get('forward_score',mbi.get('score',0)) or 0)
        meter=float(route.get('reversal_pct',0) or 0);fstate=str(route.get('flip_state_v230','ROUTE HEALTHY'));flipto=str(route.get('flip_to_v230','WAIT'))
        levels=dict(route.get('levels') or _v229_level_map(app,route,now));floor=levels.get('floor');ceil=levels.get('ceiling')
        delta=(live-target) if live is not None and target is not None else None
        mins=int(left//60);secs=int(left%60)
        V['strike'].set(f'${target:,.2f}' if target is not None else '--');V['live'].set(f'${live:,.2f}' if live is not None else '--');V['time'].set(f'{mins:02d}:{secs:02d}');V['cushion'].set(f'{delta:+,.2f}' if delta is not None else '--')
        if side in ('UP','DOWN'):
            arr='▲' if side=='UP' else '▼';V['call'].set(f'{arr}  {side}');V['call_meta'].set('THE CALL — LOCKED • LIVE THESIS • GRADED AT SETTLEMENT');V['call_sub'].set(f'locked at ${float(lock.get("price",live or 0)):,.2f} • measured {strength:.0f}/100 • regime {reg.get("name","--")}')
            col=_V232_GREEN if side=='UP' else _V232_RED;app._v232_call_label.configure(fg=col);app._v232_call_card.configure(highlightbackground=col)
        else:
            V['call'].set('◇  WAIT');V['call_meta'].set('THE CALL — FORMULATING INSIDE THE 0–5:00 WINDOW');V['call_sub'].set('James can earn the first lock at any point in the first five minutes');app._v232_call_label.configure(fg=_V232_GOLD2);app._v232_call_card.configure(highlightbackground='#6e5e00')
        V['regime'].set(f'REGIME • {reg.get("name","MIXED")} {float(reg.get("confidence",0) or 0):.0f}/100');V['mbi'].set(f'MBI • {ms:+.0f}');V['flip'].set(f'{fstate} • {meter:.0f}%');V['flowbadge'].set(f'FLOW • 2s {f2["buy_ratio"]*100:.0f}/{(1-f2["buy_ratio"])*100:.0f}')
        V['line_story'].set(('live now: '+(f'{delta:+.2f} vs line' if delta is not None else 'waiting for strike')+f' • original Tug {upf:.0f}% UP / {100-upf:.0f}% DOWN'))
        comp=float(route.get('terminal_signed',0) or 0);V['lane'].set(f'◉ A-LANE — ROUTE EDGE {comp:+.3f} • BARRIERS {float(route.get("up_viability",50) or 50):.0f}/{float(route.get("down_viability",50) or 50):.0f} • {reg.get("name","MIXED")}')
        if meter>=70:
            V['action'].set('CONSIDER EXIT / REASSESS');V['action_meta'].set(f'{fstate}: replacement control is building toward {flipto}')
        elif side in ('UP','DOWN'):V['action'].set('HOLD THESIS / WATCH LEVELS');V['action_meta'].set(f'{side} remains the historical lock • live control is monitored independently')
        else:
            V['action'].set('WAIT FOR THE CALL' if into<=300 else 'FIRST-LOCK WINDOW CLOSED')
            V['action_meta'].set('the five-minute lock window is still open' if into<=300 else 'journey + regime + flip monitoring continue until settlement')
        V['flipwarn'].set(f'⚠ {fstate}' if meter>=34 else '✓ FLIP METER HEALTHY');V['flipmeta'].set(f'{meter:.0f}/100 toward {flipto} • original Tug {tfused:+.2f} • persistence {tp*100:.0f}%')
        tside='UP' if upf>=55 else 'DOWN' if upf<=45 else 'EVEN'
        V['battleline'].set(f'line ${target:,.2f} • live ${live:,.2f} ({delta:+.2f})' if live is not None and target is not None else 'line / live building')
        # V23.4 dedicated telemetry tick exclusively owns visible Tug + flow values/bars.
        # Scalp/watch text is descriptive only.
        if live is not None and floor is not None and abs(live-float(floor))<=max(8.0,abs(live-(target or live))*.25):V['scalp'].set('WATCH FLOOR REACTION');V['scalpmeta'].set(f'near mapped floor ${float(floor):,.0f} • wait for reject/accept before acting')
        elif live is not None and ceil is not None and abs(live-float(ceil))<=max(8.0,abs(live-(target or live))*.25):V['scalp'].set('WATCH CEILING REACTION');V['scalpmeta'].set(f'near mapped ceiling ${float(ceil):,.0f} • wait for reject/accept before acting')
        else:V['scalp'].set('WAIT — NO CLEAN SECOND CHANCE');V['scalpmeta'].set('price is between mapped decision points')
        V['value'].set(f'WINDOW OPEN — {into/60:.1f} / 5.0 MIN' if into<=300 else 'WINDOW CLOSED — T+5:00 REACHED');V['valuemeta'].set('MAIN LOCK can earn at any moment now' if into<=300 else 'no brand-new first lock after five minutes • journey + flips keep running')
        V['toproute'].set(f'Route {side if side in ('UP','DOWN') else 'WAIT'} • edge {comp:+.3f} • reversal {meter:.0f}/100')
        V['toproute2'].set(f'floor {float(floor):,.0f} • ceiling {float(ceil):,.0f} • regime {reg.get('name','MIXED')}' if floor is not None and ceil is not None else f'regime {reg.get('name','MIXED')} • levels still building')
        # V23.4 dedicated telemetry tick owns all Storm Grid fields.
        V['mentorread'].set(f'MENTOR READ • {reg.get("name","MIXED")} • MBI {ms:+.0f} • TUG {tside} {max(upf,100-upf):.0f}%')
        V['engine'].set(f'{side} • {strength:.0f}/100' if side in ('UP','DOWN') else f'WAIT • route {comp:+.2f}')
        mside='UP' if comp>.03 else 'DOWN' if comp<-.03 else 'MIXED';V['auditor'].set(f'{mside} • {float(reg.get("confidence",0) or 0):.0f}/100')
        # Session grade only when a locked bucket actually rolls.
        S=app._v232_session
        if S.get('bucket') is None:S['bucket']=bucket
        if bucket!=S.get('bucket'):
            ps=str(S.get('lock','WAIT'));pt=S.get('target');pl=S.get('last_live')
            if ps in ('UP','DOWN') and pt is not None and pl is not None:
                won=(pl>=pt) if ps=='UP' else (pl<pt)
                if won:S['wins']+=1
                else:S['losses']+=1
                _v232_add_event(app,f'ROUND GRADED • {ps} • {"WIN" if won else "LOSS"} • finish ${pl:,.2f} vs ${pt:,.2f}',_V232_GREEN if won else _V232_RED)
            S.update({'bucket':bucket,'lock':'WAIT','target':None,'last_live':None});app._v232_checkpoints={};app._v232_prev_left=None
        if side in ('UP','DOWN'):S['lock']=side
        if target is not None:S['target']=target
        if live is not None:S['last_live']=live
        tot=S['wins']+S['losses'];V['record'].set(f'SESSION: {(100*S["wins"]/tot):.0f}% • {S["wins"]}W - {S["losses"]}L' if tot else 'SESSION: 0 graded rounds')
        V['recordmeta'].set('measured only from MAIN LOCK at settlement • no synthetic wins are inserted')
        # Checkpoints: capture only when the live clock actually crosses them.
        prev=app._v232_prev_left
        if prev is not None:
            for cp in app._v232_cp_vars:
                if prev>cp>=left and cp not in app._v232_checkpoints and live is not None and target is not None:
                    wside='UP' if live>=target else 'DOWN';app._v232_checkpoints[cp]=(wside,live-target)
        app._v232_prev_left=left
        for cp,var in app._v232_cp_vars.items():
            if cp in app._v232_checkpoints:
                ss,dd=app._v232_checkpoints[cp];var.set(f'{cp//60}:00\n{ss}\n{dd:+.0f}$')
        # Event log on meaningful state changes only.
        key=(side,fstate,tside,str(reg.get('name')), 'B' if f2['buy_ratio']>.57 else 'S' if f2['buy_ratio']<.43 else 'E')
        if key!=getattr(app,'_v232_event_key',None):
            old=getattr(app,'_v232_event_key',None);app._v232_event_key=key
            if old is not None:_v232_add_event(app,f'{fstate} • TUG {tside} • 2s flow {f2["buy_ratio"]*100:.0f}% buyers • regime {reg.get("name","MIXED")}')
        _v232_set_text(app._v232_log,[f'[{t}] {x}' for t,x,_c in list(app._v232_events)[:12]] or ['live event log building...'])
        _v232_draw_mentor_chart(app)
    except Exception as exc:
        try:_v232_add_event(app,'dashboard recovered: '+str(exc),_V232_RED)
        except Exception:pass
    finally:
        try:app.root.after(250,lambda a=app:_v232_dashboard_tick(a))
        except Exception:pass


def _v232_mount_wrapper(app,root,asset):
    out=_V232_BASE_MOUNT(app,root,asset)
    try:root.after(80,lambda a=app,r=root:_v232_mount_dashboard(a,r))
    except Exception:pass
    return out

_v2676_mount_cockpit=_v232_mount_wrapper

