# END V23.2

# =============================================================================
# V23.5 — SINGLE UI / DIRECT DASHBOARD FEED / NEVER-BLANK TELEMETRY
# =============================================================================
# Fixes reported from the live V23.4 run:
#   * legacy cockpits flashed before the gold dashboard and kept UI timers alive;
#   * the gold chart could remain visually blank when history was unavailable;
#   * the Storm Grid could remain at "--" when the heavier telemetry lane stalled;
#   * mouse trail was bound only to the background canvas, so child widgets ate
#     Motion events and the trail appeared missing.
#
# V23.5 makes the gold page the ONLY cockpit mounted by the final UI hook.  The
# underlying James brain remains one process / one state machine; we do not mount
# V2676 / old cockpit UI or its 30Hz UI tick.  A small compatibility-variable shim
# keeps old display writers harmless without constructing old panels.
#
# Dashboard market data gets its own direct capture lane at the localhost packet
# boundary.  That means chart/flow/depth cards update even if a legacy display
# wrapper later has a problem.  MAIN LOCK / Tug / route authority are unchanged.
# =============================================================================
_V2355_RELEASE = 'V23.5 SINGLE GOLD UI + DIRECT LIVE FEED'


def _v2355_sv(app, name, default=''):
    try:
        cur=getattr(app,name,None)
        if cur is not None and hasattr(cur,'set'):
            return cur
    except Exception:
        pass
    try:
        v=tk.StringVar(master=app.root,value=default);setattr(app,name,v);return v
    except Exception:
        return None


def _v2355_prime_compat_vars(app):
    """Variables only.  No old cockpit frames/canvases are constructed."""
    specs={
        'v2676_open_var':'WAIT','v2676_open_meta_var':'building',
        'v2676_flip_var':'0%','v2676_flip_meta_var':'NO FLIP SIGNAL',
        'v2676_survival_var':'--','v2676_survival_meta_var':'building',
        'v2676_tug_var':'DEAD EVEN','v2676_tug_meta_var':'building',
        'v2676_move_var':'--','v2676_move_meta_var':'building',
        'v2676_reversion_var':'BUILDING','v2676_reversion_meta_var':'building',
        'v2676_settle_var':'BUILDING','v2676_settle_meta_var':'building',
        'v2676_whale_var':'BUILDING','v2676_whale_meta_var':'building',
        'v2676_target_var':'--','v2676_target_meta_var':'building',
        'v2676_flow_var':'BUILDING','v2676_flow_meta':'raw prints',
        'v2676_sr_var':'BUILDING','v2676_sr_meta':'structure',
        'v2676_pattern_var':'BUILDING','v2676_pattern_meta':'scanner live',
        'v2676_active_asset_var':'BTC','v2676_active_price_var':'--',
        'v2676_active_delta_var':'waiting for target',
        'v2676_tri_status_var':'BTC KING • LIVE',
        'v297_lock_meta_var':'building',
    }
    for k,v in specs.items():_v2355_sv(app,k,v)
    if not hasattr(app,'v2676_tf_buttons'):app.v2676_tf_buttons={}
    if not hasattr(app,'v2676_market_cards'):app.v2676_market_cards={}
    if not hasattr(app,'v2676_all_lines'):app.v2676_all_lines={}


def _v2355_init_buffers(app):
    if not hasattr(app,'_v2355_dash_trades'):app._v2355_dash_trades=deque(maxlen=80000)
    if not hasattr(app,'_v2355_dash_depth'):app._v2355_dash_depth={'bid':{},'ask':{}}
    if not hasattr(app,'_v2355_dash_1m'):app._v2355_dash_1m={}
    if not hasattr(app,'_v2355_rx'):
        app._v2355_rx={'trade_packets':0,'trades':0,'depth_packets':0,'depth_updates':0,'last_trade':0.0,'last_depth':0.0}


def _v2355_trade_ts(x):
    try:
        ts=float(x.get('ts',x.get('received',time.time())) or time.time())
        if ts>1e16:ts/=1e9
        elif ts>1e12:ts/=1e3
        return ts
    except Exception:return time.time()


def _v2355_capture_trade(app,row):
    _v2355_init_buffers(app)
    try:
        ts=_v2355_trade_ts(row);px=float(row.get('price',0) or 0);sz=max(0.0,float(row.get('size',0) or 0));ag=str(row.get('aggressor','unknown') or 'unknown').lower()
        if not math.isfinite(px) or px<=0:return False
        r={'ts':ts,'price':px,'size':sz,'aggressor':ag};app._v2355_dash_trades.append(r)
        b=int(ts//60)*60;q=app._v2355_dash_1m.get(b)
        if q is None:q={'time':b,'open':px,'high':px,'low':px,'close':px,'volume':sz,'_v234_source':'V23.5 DIRECT BOOKMAP'};app._v2355_dash_1m[b]=q
        else:
            q['high']=max(float(q['high']),px);q['low']=min(float(q['low']),px);q['close']=px;q['volume']=float(q.get('volume',0) or 0)+sz
        # Bound direct candle memory to ~12h.
        if len(app._v2355_dash_1m)>900:
            for k in sorted(app._v2355_dash_1m)[:-720]:app._v2355_dash_1m.pop(k,None)
        app._v2355_rx['trades']+=1;app._v2355_rx['last_trade']=ts
        return True
    except Exception:return False


def _v2355_capture_depth(app,row):
    _v2355_init_buffers(app)
    try:
        if isinstance(row,dict):
            side=str(row.get('side','')).lower();px=float(row.get('price',0) or 0);sz=float(row.get('size',0) or 0);ts=_v2355_trade_ts(row)
        else:
            side=str(row[0]).lower();px=float(row[1]);sz=float(row[2]);ts=float(row[3]) if len(row)>3 else time.time()
        if side not in ('bid','ask') or px<=0:return False
        book=app._v2355_dash_depth[side]
        if sz<=0:book.pop(px,None)
        else:book[px]=(max(0.0,sz),ts)
        if len(book)>2500:
            live=getattr(app,'current_spot',None)
            if live:
                keep=sorted(book.items(),key=lambda kv:abs(float(kv[0])-float(live)))[:1400];book.clear();book.update(keep)
            else:
                for k in list(book)[:1000]:book.pop(k,None)
        app._v2355_rx['depth_updates']+=1;app._v2355_rx['last_depth']=time.time()
        return True
    except Exception:return False


_V2355_BASE_CHILD_APPLY = _bk_child_apply_event

def _bk_child_apply_event(app,root,event):
    """Capture the transport packet for the gold dashboard BEFORE legacy wrappers."""
    try:
        _v2355_init_buffers(app);kind=str((event or {}).get('type','')).lower().strip()
        if kind=='trade_batch':
            rows=[x for x in (event.get('trades') or ()) if isinstance(x,dict)]
            app._v2355_rx['trade_packets']+=1
            for row in rows:_v2355_capture_trade(app,row)
        elif kind=='trade':
            app._v2355_rx['trade_packets']+=1;_v2355_capture_trade(app,event)
        elif kind=='depth_batch':
            rows=list(event.get('updates') or event.get('depth') or ())
            app._v2355_rx['depth_packets']+=1
            for row in rows:_v2355_capture_depth(app,row)
        elif kind=='depth':
            app._v2355_rx['depth_packets']+=1;_v2355_capture_depth(app,event)
        elif kind=='hello':
            try:app._v2355_rx['hello']=time.time()
            except Exception:pass
    except Exception:
        pass
    result=_V2355_BASE_CHILD_APPLY(app,root,event)
    # Gold dashboard owns painting; suppress all hidden legacy chart renderers.
    try:
        if getattr(app,'_v232_shell',None) is not None:app.web_only_mode=True
    except Exception:pass
    return result


def _v2355_direct_rows(app,sec=60):
    _v2355_init_buffers(app);sec=max(60,int(sec));merged={}
    # Existing one-minute history first.
    for src in (list(getattr(app,'btc_1m',[]) or []), list(getattr(app,'_v234_visual_1m',[]) or []), list(getattr(app,'_v2355_dash_1m',{}).values())):
        try:
            for r in _v234_resample_rows(src,sec):merged[int(r['time'])]=dict(r)
        except Exception:pass
    # Direct transport trade tape is authoritative for the newest buckets.
    try:trades=list(getattr(app,'_v2355_dash_trades',()) or ())
    except Exception:trades=[]
    tb={}
    for x in trades:
        try:
            ts=float(x['ts']);px=float(x['price']);sz=float(x.get('size',0) or 0);b=int(ts//sec)*sec;q=tb.get(b)
            if q is None:q={'time':b,'open':px,'high':px,'low':px,'close':px,'volume':sz,'_v234_source':'V23.5 DIRECT BOOKMAP'};tb[b]=q
            else:q['high']=max(q['high'],px);q['low']=min(q['low'],px);q['close']=px;q['volume']+=sz
        except Exception:pass
    for b,r in tb.items():
        old=merged.get(b)
        if old:
            old['high']=max(float(old['high']),float(r['high']));old['low']=min(float(old['low']),float(r['low']));old['close']=float(r['close']);old['_v234_source']='HISTORY + V23.5 LIVE'
        else:merged[b]=r
    # Existing live price cache can still fill gaps on Kalshi standalone.
    try:pts=list(getattr(app,'live_prices',[]) or [])[-30000:]
    except Exception:pts=[]
    for x in pts:
        try:
            ts=float(x[0]);px=float(x[1]);b=int(ts//sec)*sec;q=merged.get(b)
            if q is None:merged[b]={'time':b,'open':px,'high':px,'low':px,'close':px,'volume':0.0,'_v234_source':'LIVE PRICE CACHE'}
            else:q['high']=max(float(q['high']),px);q['low']=min(float(q['low']),px);q['close']=px
        except Exception:pass
    if not merged:
        try:px,_=app.effective_live_price();px=float(px) if px is not None else None
        except Exception:px=None
        if px:
            b=int(time.time()//sec)*sec;merged[b]={'time':b,'open':px,'high':px,'low':px,'close':px,'volume':0.0,'_v234_source':'LIVE SPOT'}
    return [merged[k] for k in sorted(merged)][-120:]

# Final chart source: local/direct first, no remote dependency required.
_v234_chart_rows = _v2355_direct_rows


def _v2355_level_price(v):
    try:
        if isinstance(v,dict):
            for k in ('price','level','mid','center','value'):
                if v.get(k) is not None:
                    return float(v.get(k))
            if v.get('low') is not None and v.get('high') is not None:
                return (float(v.get('low'))+float(v.get('high')))/2.0
            return None
        if v is None:return None
        return float(v)
    except Exception:return None


def _v2355_draw_one_chart(app,c):
    if c is None:return
    try:
        sec=int(getattr(app,'_v232_chart_sec',60) or 60);rows=list(_v2355_direct_rows(app,sec) or [])[-90:]
        c.delete('all');w=max(420,int(c.winfo_width()));h=max(250,int(c.winfo_height()));c.create_rectangle(0,0,w,h,fill='#070b11',outline='')
        if not rows:
            rx=getattr(app,'_v2355_rx',{}) or {};msg=f'WAITING FOR LIVE CANDLES • trade packets {int(rx.get("trade_packets",0))} • trades {int(rx.get("trades",0))}'
            c.create_text(w/2,h/2,text=msg,fill=_V232_MUTED,font=_v232_font(10,True));return
        clean=[]
        for r0 in rows:
            try:
                r=dict(r0);o=float(r['open']);hi=float(r['high']);lo=float(r['low']);cl=float(r['close'])
                if all(math.isfinite(v) for v in (o,hi,lo,cl)):clean.append((o,hi,lo,cl,r))
            except Exception:pass
        if not clean:
            c.create_text(w/2,h/2,text='LIVE FEED PRESENT • candle conversion waiting',fill=_V232_MUTED,font=_v232_font(10,True));return
        target=None
        try:target,_=app.effective_target();target=float(target) if target is not None else None
        except Exception:target=None
        lo=min(x[2] for x in clean);hi=max(x[1] for x in clean)
        if target is not None:lo=min(lo,target);hi=max(hi,target)
        span=max(1.0,hi-lo);lo-=span*.08;hi+=span*.08
        top=18;bottom=h-55;left=16;right=w-16
        def yy(p):return bottom-(float(p)-lo)/(hi-lo)*(bottom-top)
        n=len(clean);step=(right-left)/max(1,n);body=max(3,min(10,step*.58))
        # Light horizontal guides.
        for i in range(1,5):
            gy=top+(bottom-top)*i/5;c.create_line(left,gy,right,gy,fill='#111923')
        for i,(o,hh,ll,cl,_r) in enumerate(clean):
            x=left+(i+.5)*step;col=_V232_GREEN if cl>=o else '#ef6d83';c.create_line(x,yy(hh),x,yy(ll),fill=col,width=1)
            y0,y1=yy(o),yy(cl);c.create_rectangle(x-body/2,min(y0,y1),x+body/2,max(y0,y1)+max(1,body*.10),fill=col,outline='')
        closes=[x[3] for x in clean]
        if len(closes)>=2:
            for arr,col in ((_v232_ema(closes,9),_V232_GOLD2),(_v232_ema(closes,21),'#8d6cff')):
                pts=[]
                for i,v in enumerate(arr):pts.extend((left+(i+.5)*step,yy(v)))
                if len(pts)>=4:c.create_line(*pts,fill=col,width=2,smooth=True)
        if target is not None:
            y=yy(target);c.create_line(left,y,right,y,fill=_V232_GOLD,width=1,dash=(6,4));c.create_text(right-3,y-8,text=f'STRIKE ${target:,.0f}',fill=_V232_GOLD,anchor='e',font=_v232_font(7,True))
        try:levels=_v229_level_map(app,dict(getattr(app,'_v220_last',{}) or {}),time.time())
        except Exception:levels={}
        for key,col,label in (('floor',_V232_GREEN,'SUPPORT'),('ceiling',_V232_RED,'RESISTANCE')):
            p=_v2355_level_price(levels.get(key))
            if p is not None:
                y=yy(p);c.create_line(left,y,right,y,fill=col,width=1,dash=(8,5));c.create_text(right-3,y-7,text=f'{label} ${p:,.0f}',fill=col,anchor='e',font=_v232_font(7,True))
        sep=h-42;c.create_line(left,sep,right,sep,fill='#1f2834')
        route=dict(getattr(app,'_v220_last',{}) or {});mbi=dict(route.get('mbi') or {});ms=float(mbi.get('forward_score',mbi.get('score',0)) or 0)
        old=_v232_original_tug(app,time.time());ou=float(old.get('up_force',50) or 50)
        c.create_text(left+2,h-25,text=f'MBI {ms:+.0f}',fill=_V232_GOLD2,anchor='w',font=_v232_font(8,True))
        c.create_text(right-2,h-25,text=f'ORIGINAL TUG {ou:.0f}/{100-ou:.0f}',fill=_V232_GREEN if ou>=50 else _V232_RED,anchor='e',font=_v232_font(8,True))
        src=str(clean[-1][4].get('_v234_source','LIVE'));status=f'{len(clean)} candles • {src}'
        if len(clean)<3:status+=' • history warming'
        c.create_text(left+2,top+2,text=status,fill=_V232_MUTED,anchor='nw',font=_v232_font(7,True))
    except Exception as exc:
        try:
            c.delete('all');w=max(420,int(c.winfo_width()));h=max(250,int(c.winfo_height()));c.create_text(w/2,h/2,text='CHART RECOVERED • '+str(exc)[:110],fill=_V232_RED,font=_v232_font(8,True))
        except Exception:pass


def _v232_draw_one_chart(app,c):
    return _v2355_draw_one_chart(app,c)


def _v2355_flow_windows(app,now=None):
    _v2355_init_buffers(app);now=float(now or time.time());rows=list(getattr(app,'_v2355_dash_trades',()) or ())
    # Fall back to canonical tape if the direct receiver is not used (Kalshi/tests).
    if not rows:
        try:rows=[dict(x) for x in list(getattr(app,'bookmap_trades',()) or ())]
        except Exception:rows=[]
    def one(sec):
        b=s=0.0;n=0
        for x in reversed(rows):
            try:
                ts=float(x.get('ts',x.get('received',0)) or 0)
                if now-ts>sec:break
                z=max(0.0,float(x.get('size',0) or 0));ag=str(x.get('aggressor','')).lower();n+=1
                if ag.startswith('b'):b+=z
                elif ag.startswith('s'):s+=z
            except Exception:pass
        total=b+s;ratio=b/total if total>1e-12 else .5
        return {'buy':b,'sell':s,'buy_ratio':ratio,'imbalance':2*ratio-1,'n':n}
    return {'flow2':one(2),'flow5':one(5),'flow15':one(15),'flow60':one(60),'ready':bool(rows)}


def _v2355_depth_snapshot(app):
    _v2355_init_buffers(app);live=getattr(app,'current_spot',None)
    try:live=float(live) if live is not None else None
    except Exception:live=None
    bids=dict(getattr(app,'_v2355_dash_depth',{}).get('bid',{}) or {});asks=dict(getattr(app,'_v2355_dash_depth',{}).get('ask',{}) or {})
    if not bids and not asks:
        try:
            with app.bookmap_lock:
                bids={float(p):(float((v or {}).get('size',0) or 0),float((v or {}).get('updated',0) or 0)) for p,v in dict(getattr(app,'bookmap_bids',{}) or {}).items()}
                asks={float(p):(float((v or {}).get('size',0) or 0),float((v or {}).get('updated',0) or 0)) for p,v in dict(getattr(app,'bookmap_asks',{}) or {}).items()}
        except Exception:pass
    if live:
        band=max(20.0,live*.003)
        bids={p:v for p,v in bids.items() if live-band<=p<=live}
        asks={p:v for p,v in asks.items() if live<=p<=live+band}
    def stats(book):
        vals=[max(0.0,float(v[0] if isinstance(v,(tuple,list)) else v)) for v in book.values()]
        vals=[x for x in vals if x>0]
        if not vals:return {'total':0.0,'median':0.0,'max':0.0,'price':None,'ratio':0.0,'n':0}
        ss=sorted(vals);med=ss[len(ss)//2];pair=max(book.items(),key=lambda kv:float(kv[1][0] if isinstance(kv[1],(tuple,list)) else kv[1]));mx=float(pair[1][0] if isinstance(pair[1],(tuple,list)) else pair[1])
        return {'total':sum(vals),'median':med,'max':mx,'price':float(pair[0]),'ratio':mx/max(1e-12,med),'n':len(vals)}
    B=stats(bids);A=stats(asks);tot=B['total']+A['total'];imb=(B['total']-A['total'])/tot if tot>1e-12 else 0.0
    return {'bid':B,'ask':A,'imbalance':imb,'ready':tot>0,'live':live}


def _v2355_dashboard_telemetry(app):
    V=getattr(app,'_v232_vars',{}) or {}
    if not V:return
    now=time.time();fw=_v2355_flow_windows(app,now);f2=fw['flow2'];f5=fw['flow5'];f15=fw['flow15'];f60=fw['flow60'];dep=_v2355_depth_snapshot(app)
    # Flow box always says something useful.
    if fw['ready']:
        V['flowline'].set(f'2s {f2["buy_ratio"]*100:.0f}% BUY / {(1-f2["buy_ratio"])*100:.0f}% SELL • {f2["n"]} prints   |   5s {f5["buy_ratio"]*100:.0f}/{(1-f5["buy_ratio"])*100:.0f} • {f5["n"]}   |   15s {f15["buy_ratio"]*100:.0f}/{(1-f15["buy_ratio"])*100:.0f} • {f15["n"]}')
    else:
        rx=getattr(app,'_v2355_rx',{}) or {};V['flowline'].set(f'WAITING FOR EXECUTIONS • packets {int(rx.get("trade_packets",0))} • trades {int(rx.get("trades",0))}')
    # ORIGINAL Tug is the sole Tug authority. No fast/new Tug is calculated or displayed.
    try:old=dict(_v232_original_tug(app,now) or {})
    except Exception:old={}
    ou=float(old.get('up_force',50) or 50);os='UP' if ou>=55 else 'DOWN' if ou<=45 else 'EVEN';V['oldtug'].set(str(old.get('headline') or f'OLD TUG • {os} {max(ou,100-ou):.0f}%'))
    details=[]
    for key in ('price_text','flow_text','kalshi_text','whale_text'):
        x=str(old.get(key,'') or '').strip()
        if x:details.append(x)
    V['oldtugmeta'].set('  |  '.join(details) if details else f'4-family fuse building • live flow {f15["buy_ratio"]*100:.0f}% buyers • depth {dep["imbalance"]:+.2f}')
    try:_v232_bar(app._v234_old_tug_bar,ou/100.0)
    except Exception:pass
    # Storm Grid direct reads.
    B,A=dep['bid'],dep['ask'];wall_side='BID' if B['ratio']>=A['ratio'] else 'ASK';W=B if wall_side=='BID' else A
    if dep['ready'] and W['price'] is not None:
        V['whale'].set(f'{wall_side} LIQUIDITY • ${W["price"]:,.0f} • {W["ratio"]:.1f}x median • {W["n"]} levels')
        V['walls'].set(f'{wall_side} WALL @ ${W["price"]:,.0f} • size {W["max"]:.3f} • depth imbalance {dep["imbalance"]:+.2f}')
    else:
        rx=getattr(app,'_v2355_rx',{}) or {};V['whale'].set(f'DEPTH WAIT • packets {int(rx.get("depth_packets",0))} • updates {int(rx.get("depth_updates",0))}');V['walls'].set('WAITING FOR BID/ASK DEPTH • chart + flow can still run')
    accel=f2['imbalance']-f15['imbalance'];state='BUY ACCEL' if accel>.10 else 'SELL ACCEL' if accel<-.10 else 'BALANCED';V['accel'].set(f'{state} • Δ {accel:+.2f} • 2s {f2["buy_ratio"]*100:.0f}%B vs 15s {f15["buy_ratio"]*100:.0f}%B • {f2["n"]}/{f15["n"]} prints')
    try:lock=dict(getattr(app,'opening_lock_snapshot',{}) or {});ls=str(lock.get('lock_side','WAIT') or 'WAIT').upper()
    except Exception:ls='WAIT'
    pressure=.55*f15['imbalance']+.45*dep['imbalance'];align=pressure*(1 if ls=='UP' else -1 if ls=='DOWN' else 0)
    if ls not in ('UP','DOWN'):V['attack'].set(f'NO LOCK • tape {pressure:+.2f} • old Tug {float(old.get("fused",0) or 0):+.2f}')
    else:V['attack'].set(('WITH THE CALL' if align>.08 else 'UNDER ATTACK' if align<-.08 else 'MIXED / NEUTRAL')+f' • tape/depth alignment {align:+.2f}')
    # Battle box mirrors OLD Tug.
    try:
        V['battle'].set(f'{os} is winning the OLD Tug • {max(ou,100-ou):.0f}% force' if os!='EVEN' else 'OLD TUG is dead even');V['tugdetail'].set('ORIGINAL Tug = sole Tug authority • no secondary Tug')
        _v232_bar(app._v232_battle_bar,ou/100.0)
    except Exception:pass
    # Feed health text is visible in the chart header / source badge.
    rx=getattr(app,'_v2355_rx',{}) or {};mode=str(getattr(app,'v220_source_mode',globals().get('_V220_SOURCE_MODE','BOOKMAP'))).upper()
    if mode=='BOOKMAP':V['source'].set(f'BOOKMAP LIVE • {int(rx.get("trades",0))} trades • {int(rx.get("depth_updates",0))} depth')
    try:
        rows=_v2355_direct_rows(app,int(getattr(app,'_v232_chart_sec',60) or 60));src=str(rows[-1].get('_v234_source','WAITING')) if rows else 'WAITING';V['chartnote'].set(f'{len(rows)} candles • {src} • direct packet lane')
    except Exception:pass


def _v2355_tick(app):
    try:
        if getattr(app,'_v232_shell',None) is None:return
        _v2355_dashboard_telemetry(app);_v232_draw_mentor_chart(app)
    except Exception as exc:
        try:_v232_add_event(app,'V23.5 feed lane recovered: '+str(exc)[:120],_V232_RED)
        except Exception:pass
    finally:
        try:app.root.after(120,lambda a=app:_v2355_tick(a))
        except Exception:pass


def _v232_install_fx(app,canvas):
    """Cloud background + root-wide subtle green after-trail."""
    app._v232_fx_canvas=canvas;app._v232_fx_clouds=[];app._v232_fx_last_motion=0.0
    def seed(_e=None):
        try:
            w=max(900,int(canvas.winfo_width()));h=max(700,int(canvas.winfo_height()))
            if not app._v232_fx_clouds:
                specs=[(-.08,.05,330,140,'#0b1716'),(.18,.18,430,170,'#0d1c19'),(.65,.06,400,150,'#0c1917'),(.72,.38,470,180,'#0a1514'),(.32,.67,520,190,'#0c1816')]
                for i,(rx,ry,cw,ch,col) in enumerate(specs):
                    iid=canvas.create_oval(w*rx,h*ry,w*rx+cw,h*ry+ch,fill=col,outline='',tags=('v235cloud',));app._v232_fx_clouds.append((iid,rx,ry,cw,ch,.05+i*.012))
            if getattr(app,'_v232_page_win',None) is not None:canvas.tag_lower('v235cloud',app._v232_page_win)
        except Exception:pass
    def cloud_tick():
        try:
            w=max(900,int(canvas.winfo_width()));h=max(700,int(canvas.winfo_height()));t=time.time()
            for iid,rx,ry,cw,ch,speed in app._v232_fx_clouds:
                x=(w*rx+math.sin(t*speed)*90);y=(h*ry+math.cos(t*speed*.7)*35);canvas.coords(iid,x,y,x+cw,y+ch)
            if getattr(app,'_v232_page_win',None) is not None:canvas.tag_lower('v235cloud',app._v232_page_win)
        except Exception:pass
        try:canvas.after(180,cloud_tick)
        except Exception:pass
    def motion(e):
        try:
            now=time.time()
            if now-app._v232_fx_last_motion<.028:return
            app._v232_fx_last_motion=now
            x=float(e.x_root-canvas.winfo_rootx());y=float(e.y_root-canvas.winfo_rooty())+float(canvas.canvasy(0))
            if x<0 or y<float(canvas.canvasy(0))-30 or x>canvas.winfo_width() or y>float(canvas.canvasy(0))+canvas.winfo_height()+30:return
            ids=[]
            for r,col in ((9,'#0d4d3c'),(5,'#117055'),(2.5,'#1a9a6c')):
                ids.append(canvas.create_oval(x-r,y-r,x+r,y+r,fill=col,outline='',tags=('v235trail',)))
            if getattr(app,'_v232_page_win',None) is not None:canvas.tag_raise('v235trail',app._v232_page_win)
            def fade(step):
                try:
                    scale=max(.15,1-step*.21);cols=['#0c4235','#0a3329','#08261f','#061b17'];col=cols[min(step-1,len(cols)-1)]
                    for oid in ids:
                        if not canvas.type(oid):continue
                        x1,y1,x2,y2=canvas.coords(oid);cx=(x1+x2)/2;cy=(y1+y2)/2;r=max(.8,(x2-x1)*scale/2);canvas.coords(oid,cx-r,cy-r,cx+r,cy+r);canvas.itemconfigure(oid,fill=col)
                except Exception:pass
            for step,delay in enumerate((100,200,320,450),1):canvas.after(delay,lambda s=step:fade(s))
            canvas.after(620,lambda:[canvas.delete(i) for i in ids])
        except Exception:pass
    canvas.bind('<Configure>',seed,add='+')
    # Motion arrives on Labels/Frames over the canvas, therefore bind to ALL Tk widgets.
    try:app.root.bind_all('<Motion>',motion,add='+')
    except Exception:pass
    seed();cloud_tick()


