class _V236StickyVar:
    """Delegate to an existing StringVar but refuse useless blank/-- overwrites."""
    def __init__(self,var): self.var=var
    def set(self,value):
        s=str(value if value is not None else '').strip()
        if s in ('','--','—'): return
        try:self.var.set(value)
        except Exception:pass
    def get(self):
        try:return self.var.get()
        except Exception:return ''
    def __str__(self):
        try:return str(self.var)
        except Exception:return ''


def _v236_num(v,d=0.0):
    try:
        z=float(v)
        return z if math.isfinite(z) else d
    except Exception:return d


