def _v236_install_smooth_scroll(app):
    if getattr(app,'_v236_scroll_ready',False):return
    try:
        cv=app._v232_canvas;root=app.root
        # Remove the old step-wise global wheel binding; keep Motion trail untouched.
        try:root.unbind_all('<MouseWheel>')
        except Exception:pass
        try:root.unbind_all('<Button-4>');root.unbind_all('<Button-5>')
        except Exception:pass
        app._v236_scroll_target=0.0;app._v236_scroll_anim=False
        def max_scroll():
            try:
                bb=cv.bbox('all');return max(0.0,float(bb[3]-cv.winfo_height())) if bb else 0.0
            except Exception:return 0.0
        def animate():
            try:
                mx=max_scroll();cur=float(cv.canvasy(0));tar=max(0.0,min(mx,float(app._v236_scroll_target)))
                diff=tar-cur
                if abs(diff)<.8 or mx<=0:
                    if mx>0:cv.yview_moveto(tar/max(1.0,mx+cv.winfo_height()))
                    app._v236_scroll_anim=False;return
                nxt=cur+diff*.26
                cv.yview_moveto(max(0.0,min(1.0,nxt/max(1.0,mx+cv.winfo_height()))))
                root.after(12,animate)
            except Exception:app._v236_scroll_anim=False
        def add(delta_px):
            try:
                mx=max_scroll();cur=float(cv.canvasy(0))
                if not app._v236_scroll_anim:app._v236_scroll_target=cur
                app._v236_scroll_target=max(0.0,min(mx,float(app._v236_scroll_target)+float(delta_px)))
                if not app._v236_scroll_anim:
                    app._v236_scroll_anim=True;animate()
            except Exception:pass
            return 'break'
        def wheel(e):
            d=float(getattr(e,'delta',0) or 0)
            if d==0:return None
            # Windows = 120 notches; precision touchpads can send smaller values.
            step=-d/120.0*145.0
            if abs(step)<18:step=-18 if d>0 else 18
            return add(step)
        def b4(_e):return add(-115)
        def b5(_e):return add(115)
        root.bind_all('<MouseWheel>',wheel,add='+');root.bind_all('<Button-4>',b4,add='+');root.bind_all('<Button-5>',b5,add='+')
        # Bind every visible dashboard child too.  On some Windows/Tk builds a
        # child widget's class binding can swallow MouseWheel before bind_all.
        def bind_tree(w):
            try:
                w.bind('<MouseWheel>',wheel,add='+');w.bind('<Button-4>',b4,add='+');w.bind('<Button-5>',b5,add='+')
                for ch in w.winfo_children():bind_tree(ch)
            except Exception:pass
        bind_tree(getattr(app,'_v232_shell',root))
        app._v236_scroll_ready=True
    except Exception:pass


def _v236_vwap(rows):
    out=[];pv=vv=0.0
    for r in rows:
        tp=(_v236_num(r.get('high'))+_v236_num(r.get('low'))+_v236_num(r.get('close')))/3.0;vol=max(0.0,_v236_num(r.get('volume')))
        if vol<=0:vol=1.0
        pv+=tp*vol;vv+=vol;out.append(pv/max(vv,1e-9))
    return out


def _v236_bands(closes,n=20,k=2.0):
    mid=[];up=[];dn=[]
    for i in range(len(closes)):
        a=closes[max(0,i-n+1):i+1];m=sum(a)/len(a);var=sum((x-m)*(x-m) for x in a)/max(1,len(a));s=math.sqrt(var)
        mid.append(m);up.append(m+k*s);dn.append(m-k*s)
    return mid,up,dn


def _v236_fvgs(rows):
    out=[]
    for i in range(2,len(rows)):
        a=rows[i-2];c=rows[i]
        try:
            if float(c['low'])>float(a['high']):out.append({'i':i,'type':'bull','low':float(a['high']),'high':float(c['low'])})
            elif float(c['high'])<float(a['low']):out.append({'i':i,'type':'bear','low':float(c['high']),'high':float(a['low'])})
        except Exception:pass
    return out[-8:]


def _v236_pivots(rows,kind='low'):
    vals=[]
    key='low' if kind=='low' else 'high'
    for i in range(2,len(rows)-2):
        try:
            v=float(rows[i][key]);nb=[float(rows[j][key]) for j in (i-2,i-1,i+1,i+2)]
            if (kind=='low' and v<=min(nb)) or (kind=='high' and v>=max(nb)):vals.append((i,v))
        except Exception:pass
    return vals[-2:]


