            if len(ps)>=2:
                (i1,p1),(i2,p2)=ps;c.create_line(xx(i1),yy(p1),xx(i2),yy(p2),fill=col,width=2,dash=(9,4));c.create_text(xx(i2),yy(p2)-7 if kind=='high' else yy(p2)+8,text=label,fill=col,anchor='e',font=_v232_font(5,True))
