def _v236_update_storm(app):
    V=getattr(app,'_v232_vars',{}) or {}
    if not all(k in V for k in ('whale','accel','walls','attack')):return
    now=time.time();fw=_v2355_flow_windows(app,now);f2,f5,f15,f60=fw['flow2'],fw['flow5'],fw['flow15'],fw['flow60'];dep=_v2355_depth_snapshot(app);legacy=_v236_legacy_whale(app)
    rx=getattr(app,'_v2355_rx',{}) or {}
    # Incoming whale / liquidity concentration.
    B,A=dep.get('bid',{}),dep.get('ask',{});side='BID' if _v236_num(B.get('ratio'))>=_v236_num(A.get('ratio')) else 'ASK';W=B if side=='BID' else A
    if dep.get('ready') and W.get('price') is not None:
        V['whale'].set(f'{side} LIQUIDITY @ ${float(W["price"]):,.0f} • {float(W.get("ratio",0)):.1f}x median • {int(W.get("n",0))} levels')
    elif legacy:
        d=str(legacy.get('direction','NEUTRAL'));lik=_v236_num(legacy.get('likelihood'));V['whale'].set(f'LEGACY WHALE READ • {d} {lik:.0f}/100 • direct depth warming')
    elif fw.get('ready'):
        V['whale'].set(f'NO LARGE WALL CONFIRMED • tape live {f15["n"]} prints /15s • depth {int(rx.get("depth_updates",0))} updates')
    else:V['whale'].set(f'WAITING FOR BOOKMAP TAPE • trade packets {int(rx.get("trade_packets",0))} • depth packets {int(rx.get("depth_packets",0))}')
    # Flow acceleration.
    accel=.68*(f2['imbalance']-f15['imbalance'])+.32*(f5['imbalance']-f60['imbalance']);state='BUY ACCELERATION' if accel>.08 else 'SELL ACCELERATION' if accel<-.08 else 'BALANCED / ROTATING'
    V['accel'].set(f'{state} • {accel:+.2f} • 2s {f2["buy_ratio"]*100:.0f}%B vs 15s {f15["buy_ratio"]*100:.0f}%B • {f2["n"]}/{f15["n"]} prints')
    # Hidden wall / depth state.
    if dep.get('ready') and W.get('price') is not None:
        V['walls'].set(f'{side} WALL @ ${float(W["price"]):,.0f} • max {float(W.get("max",0)):.3f} • depth imbalance {_v236_num(dep.get("imbalance")):+.2f}')
    elif legacy:
        bw=legacy.get('bid_wall') or {};aw=legacy.get('ask_wall') or {};best=bw if _v236_num(bw.get('ratio'))>=_v236_num(aw.get('ratio')) else aw
        if best.get('price') is not None:V['walls'].set(f'LEGACY WALL @ ${float(best["price"]):,.0f} • x{_v236_num(best.get("ratio")):.1f} • direct depth warming')
        else:V['walls'].set('NO CONCENTRATED WALL CONFIRMED • depth model live')
    else:V['walls'].set(f'DEPTH FEED BUILDING • {int(rx.get("depth_updates",0))} updates • no wall confirmed yet')
    # Pressure versus call uses both Tug + tape/depth, not a decorative placeholder.
    try:old=dict(_v232_original_tug(app,now) or {});of=_v236_num(old.get('fused'))
    except Exception:old={};of=0.0
    pressure=.38*f15['imbalance']+.22*f5['imbalance']+.20*_v236_num(dep.get('imbalance'))+.20*of
    try:lock=dict(getattr(app,'opening_lock_snapshot',{}) or {});ls=str(lock.get('lock_side','WAIT') or 'WAIT').upper()
    except Exception:ls='WAIT'
    if ls in ('UP','DOWN'):
        align=pressure*(1 if ls=='UP' else -1);state='WITH THE CALL' if align>.08 else 'UNDER ATTACK' if align<-.08 else 'CONTESTED';V['attack'].set(f'{state} • {ls} lock • pressure alignment {align:+.2f} • OLD Tug {of:+.2f}')
    else:V['attack'].set(f'NO MAIN LOCK YET • live pressure {pressure:+.2f} • OLD Tug {of:+.2f} • tape {f15["imbalance"]:+.2f}')


def _v236_enhance_ui(app):
    try:_v236_install_chart_controls(app);_v236_install_smooth_scroll(app)
    except Exception:pass
    V=getattr(app,'_v232_vars',{}) or {}
    defaults={'whale':'WAITING FOR BOOKMAP LIQUIDITY','accel':'FLOW ACCELERATION BUILDING','walls':'DEPTH / WALL MAP BUILDING','attack':'WAITING FOR MAIN LOCK + PRESSURE'}
    for k,x in defaults.items():
        try:
            if k in V:
                base=V[k].var if isinstance(V[k],_V236StickyVar) else V[k]
                base.set(x);V[k]=_V236StickyVar(base)
        except Exception:pass
    app._v236_chart_dirty=True


