def _v234_telemetry_tick(app):return None


# Final direct heartbeat: fast telemetry, throttled charts.
def _v2355_tick(app):
    try:
        if getattr(app,'_v232_shell',None) is None:return
        _v2355_dashboard_telemetry(app);_v236_update_storm(app);_v236_maybe_draw_charts(app,False)
    except Exception as exc:
        try:_v232_add_event(app,'V23.6 telemetry recovered: '+str(exc)[:120],_V232_RED)
        except Exception:pass
    finally:
        try:app.root.after(110,lambda a=app:_v2355_tick(a))
        except Exception:pass


