# =============================================================================
# V23.7 — CHART WHEEL ZOOM • EXACT ORIGINAL MBI VISUAL • LONG-RUN UI STABILITY
# =============================================================================
# Fixes three live issues from V23.6:
#   1) chart owns MouseWheel while hovered -> candle zoom instead of page scroll;
#   2) gold chart renders the ORIGINAL V21.93 AlgoAlpha MBI columns/decay/X/boundary
#      visual instead of the temporary up/down wave adaptation;
#   3) remove accumulating FX callbacks / duplicate paint pressure that made Tk
#      smooth for ~1 minute and then progressively lag/smear while scrolling.
# =============================================================================
_V237_RELEASE='V23.7R WHEEL ZOOM + EXACT ORIGINAL MBI + STABLE UI'


def _v237_zoom_count(app,sec=None):
    sec=int(sec or getattr(app,'_v232_chart_sec',60) or 60)
    d=getattr(app,'_v237_zoom_counts',None)
    if not isinstance(d,dict):
        d={60:72,300:64,900:52,3600:42};app._v237_zoom_counts=d
    return max(12,min(180,int(d.get(sec,72))))


def _v237_set_zoom(app,count,sec=None):
    sec=int(sec or getattr(app,'_v232_chart_sec',60) or 60)
    d=getattr(app,'_v237_zoom_counts',None)
    if not isinstance(d,dict):d={60:72,300:64,900:52,3600:42}
    d[sec]=max(12,min(180,int(count)));app._v237_zoom_counts=d;app._v236_chart_dirty=True
    try:
        V=getattr(app,'_v232_vars',{}) or {}
        if 'chartnote' in V:V['chartnote'].set(f'{sec//60 if sec<3600 else 1}{"m" if sec<3600 else "H"} • ZOOM {d[sec]} candles • wheel = zoom')
    except Exception:pass
    try:_v236_maybe_draw_charts(app,True)
    except Exception:pass


def _v237_install_chart_zoom(app):
    if getattr(app,'_v237_zoom_ready',False):return
    def bind_canvas(c):
        if c is None:return
        def wheel(e):
            d=float(getattr(e,'delta',0) or 0)
            if d==0:return 'break'
            sec=int(getattr(app,'_v232_chart_sec',60) or 60);cur=_v237_zoom_count(app,sec)
            # Wheel UP = zoom in (fewer candles), wheel DOWN = zoom out.
            factor=.86 if d>0 else 1.16
            _v237_set_zoom(app,round(cur*factor),sec)
            return 'break'
        def b4(_e):
            sec=int(getattr(app,'_v232_chart_sec',60) or 60);_v237_set_zoom(app,round(_v237_zoom_count(app,sec)*.86),sec);return 'break'
        def b5(_e):
            sec=int(getattr(app,'_v232_chart_sec',60) or 60);_v237_set_zoom(app,round(_v237_zoom_count(app,sec)*1.16),sec);return 'break'
        try:
            c.bind('<MouseWheel>',wheel)
            c.bind('<Button-4>',b4);c.bind('<Button-5>',b5)
        except Exception:pass
    bind_canvas(getattr(app,'_v232_chart',None));bind_canvas(getattr(app,'_v232_chart2',None))
    app._v237_zoom_ready=True


def _v237_install_low_cost_fx(app):
    """Static clouds + fixed-size reusable green trail pool. Zero item accumulation."""
    try:
        root=app.root;cv=getattr(app,'_v232_canvas',None)
        if cv is None:return
        # Stop V23.5's global Motion producer. Its per-move after() fan-out was the
        # primary long-run object/callback accumulator.
        try:root.unbind_all('<Motion>')
        except Exception:pass
        # Make the old moving-cloud closure a no-op on its next scheduled tick.
        app._v232_fx_clouds=[]
        try:cv.delete('v235trail');cv.delete('v235cloud');cv.delete('v232trail');cv.delete('v232cloud')
        except Exception:pass
        # Static cloudy background = same vibe, essentially zero recurring cost.
        w=max(900,int(cv.winfo_width() or 900));h=max(700,int(cv.winfo_height() or 700))
        specs=[(-.06,.04,360,150,'#0a1514'),(.19,.18,440,175,'#0d1b18'),(.63,.06,420,160,'#0b1816'),(.70,.40,500,190,'#091412'),(.30,.69,540,200,'#0b1715')]
        app._v237_cloud_ids=[]
        for rx,ry,cw,ch,col in specs:
            iid=cv.create_oval(w*rx,h*ry,w*rx+cw,h*ry+ch,fill=col,outline='',tags=('v237cloud',));app._v237_cloud_ids.append(iid)
        if getattr(app,'_v232_page_win',None) is not None:
            try:cv.tag_lower('v237cloud',app._v232_page_win)
            except Exception:pass
        # Eight reusable points; movement rotates the pool instead of create/delete.
        app._v237_trail=[];app._v237_trail_i=0;app._v237_last_motion=0.0
        for _ in range(8):
            iid=cv.create_oval(0,0,0,0,fill='#12845f',outline='',state='hidden',tags=('v237trail',));app._v237_trail.append(iid)
        def hide_trail():
            try:
                for iid in app._v237_trail:cv.itemconfigure(iid,state='hidden')
            except Exception:pass
        app._v237_hide_trail=hide_trail
        def motion(e):
            try:
                if getattr(app,'_v237_scrolling',False):return
                now=time.time()
                if now-app._v237_last_motion<.045:return
                app._v237_last_motion=now
                x=float(e.x_root-cv.winfo_rootx());y=float(e.y_root-cv.winfo_rooty())+float(cv.canvasy(0))
                y0=float(cv.canvasy(0));
                if x<0 or x>cv.winfo_width() or y<y0-15 or y>y0+cv.winfo_height()+15:return
                idx=app._v237_trail_i%len(app._v237_trail);app._v237_trail_i+=1;iid=app._v237_trail[idx]
                # Older points fade only when reused; no timer storm.
                ages=[('#16785b',5.0),('#126449',4.1),('#0e503b',3.3),('#0b3d2e',2.7),('#092f24',2.2),('#07251d',1.8),('#061c17',1.4),('#051713',1.1)]
                for j,oid in enumerate(app._v237_trail):
                    age=(app._v237_trail_i-j)%len(app._v237_trail);col,r=ages[min(age,len(ages)-1)]
                    try:cv.itemconfigure(oid,fill=col)
                    except Exception:pass
                cv.coords(iid,x-5,y-5,x+5,y+5);cv.itemconfigure(iid,state='normal',fill='#1aa675')
                if getattr(app,'_v232_page_win',None) is not None:
                    try:cv.tag_raise('v237trail',app._v232_page_win)
                    except Exception:pass
            except Exception:pass
        root.bind_all('<Motion>',motion,add='+')
        # Hide stale trail periodically with ONE timer, not one timer per point.
        def cleanup():
            try:
                if time.time()-float(getattr(app,'_v237_last_motion',0) or 0)>.35:hide_trail()
            except Exception:pass
            try:root.after(220,cleanup)
            except Exception:pass
        root.after(220,cleanup)
    except Exception:pass


def _v237_install_smooth_scroll(app):
    """60-ish Hz eased page scroll that freezes heavy chart paint during motion."""
    if getattr(app,'_v237_scroll_ready',False):return
    try:
        cv=app._v232_canvas;root=app.root
        try:root.unbind_all('<MouseWheel>');root.unbind_all('<Button-4>');root.unbind_all('<Button-5>')
        except Exception:pass
        app._v237_scroll_target=0.0;app._v237_scroll_anim=False;app._v237_scrolling=False
        def max_scroll():
            try:
                bb=cv.bbox('all');return max(0.0,float(bb[3]-cv.winfo_height())) if bb else 0.0
            except Exception:return 0.0
        def finish():
            app._v237_scroll_anim=False;app._v237_scrolling=False;app._v236_chart_dirty=True
            try:root.after(30,lambda a=app:_v236_maybe_draw_charts(a,True))
            except Exception:pass
        def animate():
            try:
                mx=max_scroll();cur=float(cv.canvasy(0));tar=max(0.0,min(mx,float(app._v237_scroll_target)));diff=tar-cur
                if abs(diff)<1.2 or mx<=0:
                    if mx>0:cv.yview_moveto(tar/max(1.0,mx+cv.winfo_height()))
                    finish();return
                nxt=cur+diff*.30;cv.yview_moveto(max(0.0,min(1.0,nxt/max(1.0,mx+cv.winfo_height()))))
                root.after(16,animate)
            except Exception:finish()
        def add(delta):
            try:
                mx=max_scroll();cur=float(cv.canvasy(0))
                if not app._v237_scroll_anim:app._v237_scroll_target=cur
                app._v237_scroll_target=max(0.0,min(mx,float(app._v237_scroll_target)+float(delta)));app._v237_scrolling=True
                try:getattr(app,'_v237_hide_trail',lambda:None)()
                except Exception:pass
                if not app._v237_scroll_anim:app._v237_scroll_anim=True;animate()
            except Exception:pass
            return 'break'
        def wheel(e):
            # Chart widgets own wheel zoom via their widget-level bind and return break.
            d=float(getattr(e,'delta',0) or 0)
            if d==0:return None
            step=-d/120.0*132.0
            if abs(step)<16:step=-16 if d>0 else 16
            return add(step)
        def b4(_e):return add(-108)
        def b5(_e):return add(108)
        root.bind_all('<MouseWheel>',wheel,add='+');root.bind_all('<Button-4>',b4,add='+');root.bind_all('<Button-5>',b5,add='+')
        app._v237_scroll_ready=True
    except Exception:pass


def _v237_exact_mbi(app):
    now=time.time();cache=getattr(app,'_v237_mbi_cache',None)
    if isinstance(cache,dict) and now-float(cache.get('_cache_ts',0) or 0)<.45:return cache
    out={}
    try:
        rows=list(_v2355_direct_rows(app,60) or [])[-180:]
        if len(rows)>=36:out=dict(_v293_exact_mbi_from_rows(rows) or {})
    except Exception:out={}
    if not out.get('ready'):
        try:out=dict(_v291_momentum_read(app,now,False) or {})
        except Exception:out={}
    if isinstance(out,dict):out['_cache_ts']=now;app._v237_mbi_cache=out
    return out

# Exact old Le Chart James visual: columns, decay layers, boundary dots and X.
def _v237_draw_exact_mbi(c,app,left,right,top,bottom):
    c.create_rectangle(left,top,right,bottom,fill='#030609',outline='#17212c')
    baseline=bottom-5;head=top+15;c.create_line(left,baseline,right,baseline,fill='#344050',width=1)
    mbi=_v237_exact_mbi(app);ser=[x for x in list((mbi or {}).get('series') or []) if x.get('up_bias') is not None and x.get('down_bias') is not None][-48:]
    title='MOMENTUM BIAS INDEX [ALGOALPHA] • EXACT 1m • 10/5/10/30 • 3σ'
    c.create_text(left+5,top+4,text=title,fill='#9eacbd',anchor='nw',font=_v232_font(5,True))
    if not ser:
        c.create_text(left+5,top+18,text='exact MBI waiting for 1m history',fill=_V232_MUTED,anchor='nw',font=_v232_font(6,True));return
    mx=max([_v236_num(x.get('up_bias')) for x in ser]+[_v236_num(x.get('down_bias')) for x in ser]+[_v236_num(x.get('boundary')) for x in ser]+[1.0])
    usable=max(10.0,baseline-head);bw=max(2.0,(right-left-8)/48.0);start=48-len(ser);green='#00ffbb';green2='#008461';red='#ff1100';red2='#840900'
    for j,p in enumerate(ser):
        i=start+j;x0=left+4+i*bw;x1=x0+max(1.0,bw-1.0);u=_v236_num(p.get('up_bias'));d=_v236_num(p.get('down_bias'));bd=_v236_num(p.get('boundary'))
        prev=ser[j-1] if j else p;pu=_v236_num(prev.get('up_bias'),u);pd=_v236_num(prev.get('down_bias'),d)
        candidates=[('UP',u,pu),('DOWN',d,pd)];candidates.sort(key=lambda z:z[1])
        for side,val,pval in candidates:
            if val<=0:continue
            basecol=green if side=='UP' else red;secondary=green2 if side=='UP' else red2;rising=val>pval
            if rising:
                y=baseline-(val/mx)*usable;c.create_rectangle(x0,y,x1,baseline,fill=basecol,outline='')
            else:
                fracs=(1.0,.80,.60,.40,.20);cols=(_v293_hex_mix('#030609',secondary,.40),_v293_hex_mix('#030609',secondary,.52),_v293_hex_mix('#030609',secondary,.66),_v293_hex_mix('#030609',secondary,.78),_v293_hex_mix('#030609',basecol,.84))
                for fr,col in zip(fracs,cols):
                    y=baseline-(val*fr/mx)*usable;c.create_rectangle(x0,y,x1,baseline,fill=col,outline='')
        if bd>0:
            by=baseline-(bd/mx)*usable;cx=(x0+x1)/2;c.create_oval(cx-1.3,by-1.3,cx+1.3,by+1.3,fill='#738094',outline='')
        bull=bool(p.get('bullish_signal'));bear=bool(p.get('bearish_signal'))
        if bull or bear:
            val=d if bull else u;y=baseline-(val/mx)*usable;cx=(x0+x1)/2;c.create_text(cx,max(head,min(baseline-2,y-6)),text='X',fill=green if bull else red,font=_v232_font(6,True))
    up=_v236_num(mbi.get('up_bias'));down=_v236_num(mbi.get('down_bias'));bd=_v236_num(mbi.get('boundary'))
    c.create_text(right-5,top+4,text=f'UP {up:.1f} • DOWN {down:.1f} • BOUNDARY {bd:.1f}',fill='#7f8ea2',anchor='ne',font=_v232_font(5,True))
    state=str(mbi.get('state','STEADY'));to=str(mbi.get('shift_to','WAIT'));conf=_v236_num(mbi.get('shift_confidence'))
    if state=='SHIFT WATCH' and to in ('UP','DOWN'):
        c.create_text(right-5,top+17,text=f'X • MOMENTUM ROLLOVER → {to} • {conf:.0f}/100',fill='#f6c85f',anchor='ne',font=_v232_font(5,True))


