def _v236_maybe_draw_charts(app,force=False):
    if getattr(app,'_v237_scrolling',False) and not force:return
    now=time.time();sig=_v236_chart_signature(app);last=getattr(app,'_v237_chart_sig',None)
    top_ts=float(getattr(app,'_v237_top_chart_ts',0) or 0)
    dirty=bool(getattr(app,'_v236_chart_dirty',False)) or sig!=last
    if force or (dirty and now-top_ts>=.32):
        _v237_draw_chart(app,getattr(app,'_v232_chart',None));app._v237_top_chart_ts=now
    if force or dirty:
        app._v237_chart_sig=sig;app._v236_chart_dirty=False

# One telemetry writer at ~6 Hz. The legacy dashboard refresh still updates its
# text/cards but no longer redundantly repaints charts/storm a second time.
def _v2355_tick(app):
    try:
        if getattr(app,'_v232_shell',None) is None:return
        _v2355_dashboard_telemetry(app)
        if time.time()-float(getattr(app,'_v237_storm_ts',0) or 0)>=.22:
            _v236_update_storm(app);app._v237_storm_ts=time.time()
        _v236_maybe_draw_charts(app,False)
    except Exception as exc:
        try:_v232_add_event(app,'V23.7 telemetry recovered: '+str(exc)[:120],_V232_RED)
        except Exception:pass
    finally:
        try:app.root.after(165,lambda a=app:_v2355_tick(a))
        except Exception:pass


def _v232_dashboard_tick(app):
    # Call the pre-V23.6 dashboard refresh. It owns card text + its own scheduler.
    # Do NOT run a second storm/chart paint here.
    return _V236_BASE_DASH_TICK(app)


