# =============================================================================
# V23.9.2 — STABLE FULL-RANGE SCROLL / NO GEOMETRY FEEDBACK LOOP
# =============================================================================
_V2392_RELEASE='V23.9.2 STABLE FULL-RANGE SCROLL'

def _v2392_install_stable_scroll(app):
    if getattr(app,'_v2392_scroll_ready',False):
        return
    try:
        cv=getattr(app,'_v232_canvas',None); page=getattr(app,'_v232_page',None); root=getattr(app,'root',None); win=getattr(app,'_v232_page_win',None)
        if cv is None or page is None or root is None or win is None:
            return
        # Kill inherited global page-wheel handlers. Chart-local zoom bindings are untouched.
        try:
            root.unbind_all('<MouseWheel>'); root.unbind_all('<Button-4>'); root.unbind_all('<Button-5>')
        except Exception:
            pass
        try:
            root.unbind_all('<Home>'); root.unbind_all('<End>')
        except Exception:
            pass
        # Add fixed bottom room once. This is real page content, so Tk's own scroll range can reach it.
        if not getattr(app,'_v2392_bottom_pad_done',False):
            try:
                pad=tk.Frame(page,bg='#06110d',height=220)
                pad.pack(fill='x',side='bottom')
                pad.pack_propagate(False)
                app._v2392_bottom_pad=pad
                app._v2392_bottom_pad_done=True
            except Exception:
                pass
        app._v2392_sync_job=None
        app._v2392_scroll_finish_job=None
        app._v237_scrolling=False
        cv.configure(yscrollincrement=1)

        def sync_region():
            # No update_idletasks loop, no background rebuild, no yview correction here.
            try:
                vw=max(720,int(cv.winfo_width() or 720)); vh=max(1,int(cv.winfo_height() or 1))
                pw=min(1100,max(760,vw-50))
                ph=max(vh+1,int(page.winfo_reqheight() or 0))
                cv.itemconfigure(win,width=pw)
                cv.coords(win,vw/2,0)
                cv.configure(scrollregion=(0,0,vw,ph))
                app._v2392_page_h=ph
                app._v2392_view_h=vh
            except Exception:
                pass

        def schedule_sync(_e=None):
            try:
                job=getattr(app,'_v2392_sync_job',None)
                if job is not None:
                    try:root.after_cancel(job)
                    except Exception:pass
                app._v2392_sync_job=root.after(90,sync_region)
            except Exception:
                pass

        def finish_scroll():
            app._v237_scrolling=False
            try:
                app._v236_chart_dirty=True
                root.after(40,lambda a=app:_v236_maybe_draw_charts(a,True))
            except Exception:
                pass

        def mark_scroll():
            app._v237_scrolling=True
            try:
                job=getattr(app,'_v2392_scroll_finish_job',None)
                if job is not None:
                    root.after_cancel(job)
            except Exception:
                pass
            try:app._v2392_scroll_finish_job=root.after(95,finish_scroll)
            except Exception:pass

        def wheel(e):
            d=float(getattr(e,'delta',0) or 0)
            if d==0:return None
            # Direct pixel scroll = no animated yview feedback loop, so no shaking.
            px=int(round(-d/120.0*115.0))
            if px==0:px=-18 if d>0 else 18
            try:
                mark_scroll(); cv.yview_scroll(px,'units')
            except Exception:
                pass
            return 'break'
        def b4(_e):
            try:mark_scroll();cv.yview_scroll(-105,'units')
            except Exception:pass
            return 'break'
        def b5(_e):
            try:mark_scroll();cv.yview_scroll(105,'units')
            except Exception:pass
            return 'break'
        def home(_e=None):
            try:cv.yview_moveto(0.0);mark_scroll()
            except Exception:pass
            return 'break'
        def end(_e=None):
            try:sync_region();cv.yview_moveto(1.0);mark_scroll()
            except Exception:pass
            return 'break'

        root.bind_all('<MouseWheel>',wheel,add='+')
        root.bind_all('<Button-4>',b4,add='+');root.bind_all('<Button-5>',b5,add='+')
        root.bind_all('<Home>',home,add='+');root.bind_all('<End>',end,add='+')
        # Only debounce when geometry actually changes. No heartbeat, no recursive sync.
        page.bind('<Configure>',schedule_sync,add='+')
        cv.bind('<Configure>',schedule_sync,add='+')
        root.after(120,sync_region)
        root.after(450,sync_region)
        app._v2392_scroll_ready=True
    except Exception:
        pass

_V2392_BASE_MOUNT=_v2355_mount_only
def _v2355_mount_only(app,root,asset='BTC'):
    out=_V2392_BASE_MOUNT(app,root,asset)
    try:
        root.after(250,lambda a=app:_v2392_install_stable_scroll(a))
        root.title('LECHART JAMES V23.9.2 — SINGLE CHART • ZORO • STABLE FULL SCROLL')
    except Exception:pass
    return out
# END V23.9.2


# =============================================================================
# V23.9.3 — BALANCED / DELIBERATE FIRST-LOCK AUDIT
# =============================================================================
# Purpose:
# - remove the near-zero directional trigger that made early tiny positive drift
#   look like an UP candidate;
# - keep the full 0..300s lock window, but require sustained evidence before a
#   lock is earned;
# - make UP/DOWN gates mathematically mirrored;
# - use fresh 5s/15s executed-flow only as a contradiction veto so correlated
#   flow is not double-counted on top of the original Tug;
# - never force a deadline lock just because the clock is near 5:00.
_V2393_RELEASE='V23.9.3 BALANCED DELIBERATE FIRST LOCK'


def _v2393_clip(x, lo=-1.0, hi=1.0):
    try:return max(lo,min(hi,float(x)))
    except Exception:return 0.0


def _v2393_regime_name(reg):
    return str((reg or {}).get('name','MIXED / DEVELOPING') or 'MIXED / DEVELOPING').upper()


def _v2393_lock_packet(self, route, into, mode='BOOKMAP', now=None):
    r=dict(route or {});now=float(now or time.time())
    try:reg=dict(_v229_regime_read(self,r,now) or {})
    except Exception:reg={'name':'MIXED / DEVELOPING','confidence':0}
    name=_v2393_regime_name(reg)
    up=float(r.get('up_viability',50) or 50);dn=float(r.get('down_viability',50) or 50)
    signed=_v2393_clip(r.get('terminal_signed',0.0))
    mbi=dict(r.get('mbi') or {});m=_v2393_clip(float(mbi.get('forward_score',mbi.get('score',0.0)) or 0.0)/100.0)
    # Original Tug remains the brain authority. Pull it fresh so the lock does not
    # depend on a stale route snapshot.
    try:tug=dict(_v232_original_tug(self,now=now) or {})
    except Exception:tug=dict(r.get('tug') or {})
    t=_v2393_clip(tug.get('signed',tug.get('fused',0.0)))
    tp=max(0.0,min(1.0,float(tug.get('persistence',0.0) or 0.0)))
    barrier=_v2393_clip((up-dn)/38.0)

    # Symmetric terminal composite. No directional default and no sign privilege.
    composite=_v2393_clip(.34*barrier + .28*signed + .20*t + .18*m)

    # Explicit neutral band. V23.9.2 picked UP on any composite > 0 and DOWN on
    # any composite < 0. That was too eager around zero.
    progress=max(0.0,min(1.0,float(into)/300.0))
    neutral_band=max(.065, .095 - .020*progress)
    side='WAIT' if abs(composite)<neutral_band else ('UP' if composite>0 else 'DOWN')
    sgn=1.0 if side=='UP' else -1.0 if side=='DOWN' else 0.0
    ba=barrier*sgn;ra=signed*sgn;ta=t*sgn;ma=m*sgn

    # Mirrored independent-family gates.
    fam={
        'BARRIER': ba>=.13,
        'ROUTE':   ra>=.095,
        'TUG':     ta>=.105 and tp>=.40,
        'MBI':     ma>=.16,
    }
    breadth=sum(1 for v in fam.values() if v)
    core=sum(1 for k in ('BARRIER','ROUTE','TUG') if fam[k])

    # Fresh native flow is a sanity veto only (not an extra score family) because
    # the ORIGINAL Tug already contains executed-flow information.
    flow_signed=0.0;flow_ready=False;flow_n=0
    try:
        nf=dict(_v232_native_flow(self,now) or {})
        f5=dict(nf.get('flow5') or {});f15=dict(nf.get('flow15') or {})
        n5=int(f5.get('n',0) or 0);n15=int(f15.get('n',0) or 0);flow_n=n5+n15
        if n5>=3 or n15>=7:
            flow_signed=_v2393_clip(.58*float(f5.get('imbalance',0) or 0)+.42*float(f15.get('imbalance',0) or 0))
            flow_ready=True
    except Exception:pass
    flow_align=flow_signed*sgn if sgn else 0.0
    flow_veto=bool(flow_ready and flow_align<=-.24 and flow_n>=10)

    # Strong opposing momentum/Tug still vetoes an opening lock.
    hard_opp=bool(side in ('UP','DOWN') and (ma<=-.46 or (ta<=-.34 and tp>=.56) or flow_veto))

    # Regime-specific edge requirement. Flippy/range markets need MORE proof,
    # not less. The threshold gently relaxes over the five-minute window, but
    # never falls into the near-zero zone.
    if name.startswith('BREAKOUT'):
        edge_need=.125; base_hold=4.2
    elif name.startswith('STRAIGHT'):
        edge_need=.115; base_hold=4.8
    elif name.startswith(('FLIPPY','RANGE')):
        edge_need=.145; base_hold=7.0
    else:
        edge_need=.135; base_hold=6.2
    edge_need=max(.095,edge_need-.025*progress)

    # Decisive 4-family agreement can lock faster, but there is no fixed lock
    # minute and no deadline forcing. Moderate evidence must persist longer.
    decisive=(breadth>=4 and core>=2 and abs(composite)>=max(.24,edge_need+.08) and not hard_opp)
    strong=(breadth>=3 and core>=2 and abs(composite)>=max(.18,edge_need+.035) and not hard_opp)
    # V23.9.7: slightly more patient. Clean reads still lock quickly, but James
    # now asks for a little more sustained agreement before committing.
    need_s=6.0 if decisive else max(7.5,base_hold+1.0-.30*progress) if strong else max(9.0,base_hold+2.0-.20*progress)

    window=(0.0<=float(into)<=300.0)
    qualified=bool(window and side in ('UP','DOWN') and not hard_opp and breadth>=2 and core>=1 and abs(composite)>=edge_need)
    # If only two families agree, require one of them to be ROUTE/TUG plus a
    # meaningful barrier or MBI contribution instead of accepting a tiny pairing.
    if qualified and breadth==2:
        secondary=max(ba,ma)
        if not (fam['ROUTE'] or fam['TUG']) or secondary<.09:
            qualified=False

    strength=max(50.0,min(94.0,50+abs(composite)*120+breadth*4.0+max(0.0,ta)*5+max(0.0,ma)*4))
    try:levels=dict(r.get('levels') or _v229_level_map(self,r,now) or {})
    except Exception:levels=dict(r.get('levels') or {})
    reason=(f'{name} • BALANCED {side} • edge {composite:+.3f}/{edge_need:.3f} • '
            f'confluence {breadth}/4 core {core}/3 • route {ra:+.2f} • barriers {up:.0f}/{dn:.0f} • '
            f'MBI {ma*100:+.0f} • OLD TUG {ta:+.2f} ({tp*100:.0f}% persist) • '
            f'flow {flow_align:+.2f}{" VETO" if flow_veto else ""}')
    return {'side':side,'qualified':qualified,'window_open':window,'deadline':False,'composite':composite,
            'neutral_band':neutral_band,'gap':abs(up-dn),'up':up,'down':dn,'mbi_align':ma*100,
            'tug_align':ta,'tug_persistence':tp,'flow_align':flow_align,'flow_ready':flow_ready,'flow_veto':flow_veto,
            'need_s':need_s,'strength':strength,'regime':reg,'levels':levels,'breadth':breadth,'core':core,
            'families':fam,'decisive':decisive,'strong':strong,'edge_need':edge_need,'reason':reason}

_v229_lock_packet=_v2393_lock_packet
_v230_lock_packet=_v2393_lock_packet


def _v2393_open_lock_tick(self,warm=None,now=None):
    now=float(now or time.time());bucket=int(now//900)*900;into=max(0.0,now-bucket)
    existing=dict(getattr(self,'opening_lock_snapshot',{}) or {})
    # Never carry a previous 15m opening lock into the new market bucket. The
    # legacy chain can be late clearing it, which can look like a permanent UP
    # preference if the prior round happened to be UP.
    ex_side=str(existing.get('lock_side','WAIT')).upper()
    try: ex_bucket=int(existing.get('bucket',existing.get('market_bucket',-1)) or -1)
    except Exception: ex_bucket=-1
    if ex_side in ('UP','DOWN') and ex_bucket!=bucket:
        try:self.opening_lock_snapshot=None
        except Exception:pass
        existing={}
        try:self._v2393_lock_state={}
        except Exception:pass
        try:self.opening_lock_var.set('NEW 15M ROUND • PRIOR LOCK CLEARED • BALANCED MAPPING')
        except Exception:pass
    if str(existing.get('lock_side','WAIT')).upper() in ('UP','DOWN'):
        # Preserve the existing downstream flip / PLAN CHANGED engine once a real
        # opening thesis has been earned.
        try:_V230_LEGACY_OPEN_TICK(self,warm=warm,now=now)
        except Exception:pass
        try:_v229_journey(self,now=now)
        except Exception:pass
        return dict(getattr(self,'opening_lock_snapshot',{}) or existing)

    try:r=dict(getattr(self,'_v220_last',{}) or {})
    except Exception:r={}
    if not r.get('ready') or now-float(r.get('ts',now) or now)>1.5:
        try:r=dict(_v220_terminal_read(self,now=now) or {})
        except Exception:r={}
    if not r.get('ready'):
        try:_v229_journey(self,now=now)
        except Exception:pass
        return None

    q=_v2393_lock_packet(self,r,into,str(getattr(self,'v220_source_mode','BOOKMAP')).upper(),now)
    try:_v229_journey(self,now=now)
    except Exception:pass
    reg=dict(q.get('regime') or {})
    if not q.get('window_open'):
        try:self.opening_lock_var.set(f'FIRST-LOCK WINDOW CLOSED • {reg.get("name","--")} • journey still mapping')
        except Exception:pass
        return None

    st=dict(getattr(self,'_v2393_lock_state',{}) or {})
    if int(st.get('bucket',-1) or -1)!=bucket:
        st={'bucket':bucket,'side':'WAIT','since':0.0,'evidence_s':0.0,'last_eval':now,'last_q':{}}
    last=float(st.get('last_eval',now) or now);dt=max(.0,min(.35,now-last));st['last_eval']=now

    if q['qualified']:
        if st.get('side')!=q['side']:
            st.update({'side':q['side'],'since':now,'evidence_s':0.0})
        else:
            st['evidence_s']=min(30.0,float(st.get('evidence_s',0) or 0)+dt)
    else:
        # Contradiction decays accumulated evidence rapidly instead of leaving an
        # old candidate alive through a noisy reversal.
        st['evidence_s']=max(0.0,float(st.get('evidence_s',0) or 0)-dt*1.8)
        if st['evidence_s']<=0.05:
            st.update({'side':'WAIT','since':0.0,'evidence_s':0.0})
    st['last_q']=dict(q);self._v2393_lock_state=st

    age=max(0.0,now-float(st.get('since',now) or now)) if st.get('side') in ('UP','DOWN') else 0.0
    ev=float(st.get('evidence_s',0) or 0)
    label=q['side'] if q['side'] in ('UP','DOWN') else 'WAIT'
    try:
        self.opening_lock_var.set(f'FORMULATING {label} • {q["strength"]:.0f}/100 • BALANCED 0-300s • '
                                  f'persist {ev:.1f}/{q["need_s"]:.1f}s • {q["reason"]}')
    except Exception:pass

    if not q['qualified'] or st.get('side')!=q['side'] or ev<q['need_s']:
        return None
    try:live,_=self.effective_live_price();target,_=self.effective_target()
    except Exception:return None
    if live is None or target is None:return None

    side=q['side'];strength=q['strength']
    snap={'time':now,'price':float(live),'lock_side':side,'strength':strength,'bucket':bucket,'market_bucket':bucket,
          'source':'V23.9.3 BALANCED 0-300 FIRST LOCK','forecast_reasons':q['reason'],
          'forecast_score':q['composite']*10.0,'forecast_threshold':q['edge_need']*10.0,
          'lock_remaining':'OPEN','lock_minute':int(into//60),'regime':reg.get('name')}
    self.opening_lock_snapshot=dict(snap);self.opening_lock_candidate=None;self.opening_lock_candidate_since=0.0
    try:
        thesis=getattr(self,'_v279_thesis',None)
        if isinstance(thesis,dict):
            thesis.update({'status':'LOCKED','side':side,'strength':strength,'locked_at':now,'opening_score':q['composite'],
                           'opening_meta':dict(q),'last_reason':'V23.9.3 '+q['reason']})
            self._v279_thesis=thesis
    except Exception:pass
    try:self.opening_lock_var.set(f'MAIN LOCK: {side} {strength:.0f}/100 • BALANCED EARNED @ {into:.1f}s • {q["reason"]}')
    except Exception:pass
    try:_v232_add_event(self,f'FIRST LOCK EARNED • {side} {strength:.0f}/100 • persisted {ev:.1f}s • {q["reason"]}',_V232_GREEN if side=='UP' else _V232_RED)
    except Exception:pass
    return dict(snap)

ChartKingPro._bookmap_opening_lock_tick=_v2393_open_lock_tick

# Neutral is actually neutral before the first lock. Do not let the replacement
# meter cosmetically seed an UP anchor just because an edge equals exactly 0.
_V2393_PREV_TERMINAL=_v220_terminal_read
def _v2393_terminal_read(self,now=None):
    out=dict(_V2393_PREV_TERMINAL(self,now=now) or {})
