# =============================================================================
# V23.9.5 — STATIC EVENT-ONLY FULL-PAGE SCROLL
# Built from V23.9.3 clean branch (NOT V23.9.4) to remove every autonomous
# scroll/animation controller. The page only moves when a real wheel/key/scrollbar
# event occurs. A custom bindtag owns the wheel before Text/Canvas child classes.
# =============================================================================
_V2395_RELEASE='V23.9.5 STATIC EVENT-ONLY SCROLL'


def _v2395_scroll_install(app):
    if getattr(app,'_v2395_scroll_ready',False):
        return
    root=getattr(app,'root',None); cv=getattr(app,'_v232_canvas',None); page=getattr(app,'_v232_page',None)
    chart=getattr(app,'_v232_chart',None)
    if root is None or cv is None or page is None:
        return
    app._v2395_scroll_ready=True
    app._v237_scrolling=False
    app._v236_scroll_anim=False
    app._v237_scroll_anim=False
    # Kill inherited global/root wheel handlers. We replace them with one custom
    # bindtag handler, so a single hardware wheel event can never fire 2-4 paths.
    try: root.unbind_all('<MouseWheel>'); root.unbind_all('<Button-4>'); root.unbind_all('<Button-5>')
    except Exception: pass
    try: root.unbind('<MouseWheel>'); root.unbind('<Button-4>'); root.unbind('<Button-5>')
    except Exception: pass
    try: cv.configure(yscrollincrement=1)
    except Exception: pass

    state={'bottom':1.0,'view_h':1.0,'last_page_h':0,'last_view_h':0}
    app._v2395_scroll_state=state

    def sync_region(_e=None):
        try:
            vw=max(1,int(cv.winfo_width())); vh=max(1,int(cv.winfo_height()))
            # reqheight is the only content authority. Background art/canvas items
            # are deliberately excluded so they cannot expand/contract the range.
            ph=max(int(page.winfo_reqheight()), int(page.winfo_height()), vh)
            bottom=max(vh, ph + 220)  # fixed breathing room below final card
            if ph!=state['last_page_h'] or vh!=state['last_view_h'] or bottom!=state['bottom']:
                state.update({'bottom':float(bottom),'view_h':float(vh),'last_page_h':ph,'last_view_h':vh})
                cv.configure(scrollregion=(0,0,vw,bottom))
        except Exception:
            pass

    def scroll_pixels(px):
        try:
            sync_region()
            bottom=float(state['bottom']); vh=float(state['view_h']); max_top=max(0.0,bottom-vh)
            cur=max(0.0,float(cv.canvasy(0)))
            target=max(0.0,min(max_top,cur+float(px)))
            # one yview command, no after(), no easing, no target accumulator
            cv.yview_moveto(0.0 if bottom<=0 else target/bottom)
            app._scroll_active_until=time.time()+0.06
            return 'break'
        except Exception:
            return 'break'

    def outer_wheel(e):
        d=float(getattr(e,'delta',0) or 0)
        if d==0:return 'break'
        # Windows mouse = 120 multiples, precision touchpads can be smaller.
        units=max(-3.0,min(3.0,d/120.0))
        return scroll_pixels(-units*115.0)
    def b4(_e):return scroll_pixels(-115)
    def b5(_e):return scroll_pixels(115)

    def zoom_wheel(e):
        try:
            d=float(getattr(e,'delta',0) or 0)
            if d==0:return 'break'
            sec=int(getattr(app,'_v232_chart_sec',60) or 60); cur=_v237_zoom_count(app,sec)
            _v237_set_zoom(app,round(cur*(.86 if d>0 else 1.16)),sec)
        except Exception:pass
        return 'break'
    def zoom_b4(_e):
        try:
            sec=int(getattr(app,'_v232_chart_sec',60) or 60);_v237_set_zoom(app,round(_v237_zoom_count(app,sec)*.86),sec)
        except Exception:pass
        return 'break'
    def zoom_b5(_e):
        try:
            sec=int(getattr(app,'_v232_chart_sec',60) or 60);_v237_set_zoom(app,round(_v237_zoom_count(app,sec)*1.16),sec)
        except Exception:pass
        return 'break'

    # Custom bindtags execute before widget/class bindings. This prevents Text,
    # Canvas and nested widgets from creating the old "force field" while also
    # preventing duplicate root/global scroll handlers.
    try:
        root.bind_class('V2395PageScroll','<MouseWheel>',outer_wheel)
        root.bind_class('V2395PageScroll','<Button-4>',b4)
        root.bind_class('V2395PageScroll','<Button-5>',b5)
        root.bind_class('V2395ChartZoom','<MouseWheel>',zoom_wheel)
        root.bind_class('V2395ChartZoom','<Button-4>',zoom_b4)
        root.bind_class('V2395ChartZoom','<Button-5>',zoom_b5)
    except Exception:pass

    def tag_widget(w):
        try:
            tags=list(w.bindtags())
            tags=[t for t in tags if t not in ('V2395PageScroll','V2395ChartZoom')]
            first='V2395ChartZoom' if w is chart else 'V2395PageScroll'
            w.bindtags(tuple([first]+tags))
        except Exception:pass
        try:
            for ch in w.winfo_children():tag_widget(ch)
        except Exception:pass

    def retag_and_sync(_e=None):
        tag_widget(page); tag_widget(cv); tag_widget(root); sync_region()
    try:page.bind('<Configure>',retag_and_sync,add='+')
    except Exception:pass
    try:cv.bind('<Configure>',retag_and_sync,add='+')
    except Exception:pass
    retag_and_sync()

    def home(_e=None):
        try:cv.yview_moveto(0.0)
        except Exception:pass
        return 'break'
    def end(_e=None):
        try:sync_region();cv.yview_moveto(1.0)
        except Exception:pass
        return 'break'
    try:root.bind('<Home>',home);root.bind('<End>',end)
    except Exception:pass


