# V23.9.6 flow micro-optimization: classify each trade into one age bucket,
# then build cumulative 2/5/15/60s windows. One trade = one bucket update.
def _v2355_flow_windows(app,now=None):
    _v2355_init_buffers(app);now=float(now or time.time())
    cache=getattr(app,'_v2396_flow_cache',None)
    try:
        if cache and now-float(cache[0])<.10:return cache[1]
    except Exception:pass
    d=getattr(app,'_v2355_dash_trades',None) or getattr(app,'bookmap_trades',None)
    # exact age bins: <=2, (2,5], (5,15], (15,60]
    bb=[0.0]*4;ss=[0.0]*4;nn=[0]*4;ready=False
    def consume(iterator):
        nonlocal ready
        old_run=0
        for x in iterator:
            try:
                ts=float(x.get('ts',x.get('received',0)) or 0);age=now-ts
                if age<-.5:continue
                if age>60.5:
                    old_run+=1
                    if old_run>=4:break
                    continue
                old_run=0;ready=True
                j=0 if age<=2 else 1 if age<=5 else 2 if age<=15 else 3
                z=max(0.0,float(x.get('size',0) or 0));ag=str(x.get('aggressor','')).lower();nn[j]+=1
                if ag.startswith('b'):bb[j]+=z
                elif ag.startswith('s'):ss[j]+=z
            except Exception:continue
    try:consume(reversed(d))
    except RuntimeError:
        try:consume(reversed(list(d)[-30000:]))
        except Exception:pass
    # cumulative windows from youngest outward
    cb=[];cs=[];cn=[];b=s=0.0;n=0
    for i in range(4):
        b+=bb[i];s+=ss[i];n+=nn[i];cb.append(b);cs.append(s);cn.append(n)
    def pack(i):
        total=cb[i]+cs[i];ratio=cb[i]/total if total>1e-12 else .5
        return {'buy':cb[i],'sell':cs[i],'buy_ratio':ratio,'imbalance':2*ratio-1,'n':cn[i]}
    out={'flow2':pack(0),'flow5':pack(1),'flow15':pack(2),'flow60':pack(3),'ready':bool(ready)}
    app._v2396_flow_cache=(now,out);return out



# V23.9.6 recurring-loop deduper. Several historical mount wrappers can invoke
# the final mount more than once during startup. These guards collapse duplicate
# live-log / journal / watchdog heartbeats into one permanent chain each.
