_V2399_BASE_PACKET=_v2393_lock_packet

def _v2399_lock_packet(self,route,into,mode='BOOKMAP',now=None):
    now=float(now or time.time())
    q=dict(_V2399_BASE_PACKET(self,route,into,mode,now) or {})
    side=str(q.get('side','WAIT') or 'WAIT').upper()
    if side not in ('UP','DOWN'):
        q['need_s']=max(10.0,float(q.get('need_s',10.0) or 10.0));return q
    sgn=1.0 if side=='UP' else -1.0
    try:dest=dict(_v26719_destination_context(self,warm=None,now=now) or {})
    except Exception:
        try:dest=dict(_v263_destination_context(self,warm=None,now=now) or {})
        except Exception:dest={}
    try:journey=dict(_v229_journey(self,now=now) or {})
    except Exception:journey=dict(getattr(self,'_v2673_last_map',{}) or {})
    dscore=float(dest.get('score',0.0) or 0.0);dalign=dscore*sgn
    jside=str(journey.get('route_side',journey.get('lock_side','WAIT')) or 'WAIT').upper()
    checkpoints=list(journey.get('checkpoints') or [])
    route_match=float(journey.get('route_match',0.0) or 0.0)
    path_ready=bool(journey.get('ready')) and len(checkpoints)>=2
    path_align=1.0 if jside==side else -1.0 if jside in ('UP','DOWN') else 0.0
    base_edge=float(q.get('composite',0.0) or 0.0)
    mapped_edge=max(-1.0,min(1.0,.86*base_edge+.14*dscore))
    reg=str((q.get('regime') or {}).get('name','MIXED')).upper()
    if reg.startswith('BREAKOUT'):path_need=.145
    elif reg.startswith('STRAIGHT'):path_need=.135
    elif reg.startswith(('FLIPPY','RANGE')):path_need=.165
    else:path_need=.150
    path_need=max(path_need,float(q.get('edge_need',0.0) or 0.0))
    strong_dest_opp=dalign<=-.18
    route_opp=(path_align<0)
    weak_map=bool(route_match and route_match<56.0)
    map_veto=strong_dest_opp or route_opp or weak_map or (not path_ready)
    qualified=bool(q.get('qualified')) and not map_veto and (mapped_edge*sgn)>=path_need
    decisive=bool(q.get('decisive')) and dalign>=-.02 and path_align>=0 and path_ready
    strong=bool(q.get('strong')) and dalign>=-.08 and path_align>=0 and path_ready
    if decisive:need_s=8.5
    elif strong:need_s=11.0
    else:need_s=14.5
    if reg.startswith(('FLIPPY','RANGE')):need_s+=2.0
    if route_match and route_match<64:need_s+=1.5
    need_s=max(need_s,float(q.get('need_s',0.0) or 0.0))
    q.update({'qualified':qualified,'need_s':need_s,'composite':mapped_edge,'edge_need':path_need,
              'destination_score':dscore,'destination_align':dalign,'journey_side':jside,
              'journey_route_match':route_match,'journey_path_ready':path_ready,'journey_checkpoints':len(checkpoints),
              'path_veto':map_veto})
    q['reason']=(str(q.get('reason',''))+f' • END PATH {jside} • dest {dalign:+.2f} • route-match {route_match:.0f} • checkpoints {len(checkpoints)}'
                 +(' • MAP NOT READY' if not path_ready else '')+(' • PATH VETO' if map_veto else ' • PATH ALIGNED'))
    return q

