def _v23911_regime_family(name):
    x=str(name or 'MIXED').upper()
    if 'FLIPPY' in x:return 'FLIPPY'
    if 'RANGE' in x:return 'RANGE'
    if 'BREAKOUT' in x or 'EXPANSION' in x:return 'BREAKOUT'
    if 'STRAIGHT' in x:return 'STRAIGHT'
    if 'REVERSAL' in x:return 'REVERSAL'
    if 'CHOP' in x:return 'CHOP'
    return 'MIXED'

def _v23911_clip(x,lo=-1.0,hi=1.0):
    try:return max(lo,min(hi,float(x)))
    except Exception:return 0.0

def _v23911_init_memory_db(app):
    if getattr(app,'_v23911_db_ready',False):return
    try:
        with app.stockpile_db_lock:
            with app._stockpile_connect() as conn:
                conn.execute('''CREATE TABLE IF NOT EXISTS v23911_call_memory (
                    bucket INTEGER PRIMARY KEY, side TEXT, won INTEGER,
                    lock_ts REAL, lock_second REAL, lock_price REAL, target REAL,
                    settle_price REAL, regime TEXT, regime_family TEXT,
                    signature_json TEXT, sequence_json TEXT, diagnosis_json TEXT,
                    created_ts REAL)''')
                conn.execute('CREATE INDEX IF NOT EXISTS idx_v23911_won ON v23911_call_memory(won)')
                conn.execute('CREATE INDEX IF NOT EXISTS idx_v23911_regime ON v23911_call_memory(regime_family)')
        app._v23911_db_ready=True;app._v23911_cache_dirty=True
    except Exception as exc:
        try:app._v23911_db_error=str(exc)
        except Exception:pass

def _v23911_signature_from_q(q,into=0.0):
    q=dict(q or {});side=str(q.get('side','WAIT') or 'WAIT').upper();sgn=1.0 if side=='UP' else -1.0 if side=='DOWN' else 0.0
    try:bar=((float(q.get('up',50) or 50)-float(q.get('down',50) or 50))/100.0)*sgn
    except Exception:bar=0.0
    return {'edge':_v23911_clip(float(q.get('composite',0) or 0)*sgn),'barrier':_v23911_clip(bar),
            'tug':_v23911_clip(q.get('tug_align',0)),'tug_p':max(0.0,min(1.0,float(q.get('tug_persistence',0) or 0))),
            'mbi':_v23911_clip(float(q.get('mbi_align',0) or 0)/100.0),'flow':_v23911_clip(q.get('flow_align',0)),
            'dest':_v23911_clip(q.get('destination_align',0)),'route_match':max(0.0,min(1.0,float(q.get('journey_route_match',0) or 0)/100.0)),
            'path_ready':1.0 if q.get('journey_path_ready') else 0.0,'breadth':max(0.0,min(1.0,float(q.get('breadth',0) or 0)/4.0)),
            'core':max(0.0,min(1.0,float(q.get('core',0) or 0)/3.0)),'timing':max(0.0,min(1.0,float(into or 0)/300.0)),
            'strength':max(0.0,min(1.0,float(q.get('strength',50) or 50)/100.0)),
            'regime':str((q.get('regime') or {}).get('name','MIXED')),'side':side}

