def _v23912_regime_path_need(reg):
    name=str((reg or {}).get('name','MIXED') or 'MIXED').upper()
    if name.startswith('BREAKOUT'):return .135
    if name.startswith('STRAIGHT'):return .130
    if name.startswith(('FLIPPY','RANGE')):return .155
    return .145

def _v23912_lock_packet(self,route,into,mode='BOOKMAP',now=None):
    """Patient lock packet that cannot be deadlocked by incomplete path cosmetics.

    Hard requirements stay hard: official strike, non-neutral directional edge,
    Original Tug/route family support, and no strong opposite evidence.  Missing
    optional checkpoints, a merely weak route-match, or loss-memory caution are
    penalties -- not permanent vetoes.
    """
    now=float(now or time.time()); into=max(0.0,float(into or 0.0))
    q=dict(_V23912_BASE_PACKET(self,route,into,mode,now) or {})
    side=str(q.get('side','WAIT') or 'WAIT').upper()
    q['window_open']=bool(0.0<=into<=300.0);q['deadline']=False
    if side not in ('UP','DOWN'):
        q['qualified']=False;q['need_s']=max(9.0,min(15.0,float(q.get('need_s',11.0) or 11.0)))
        q['v23912_blocker']='NEUTRAL EDGE';return q

    # Strike is the only path datum that must exist before a graded call.
    target_locked=bool(q.get('target_locked'))
    if not target_locked:
        try:
            target,_src=self.effective_target();target_locked=target is not None
        except Exception:target_locked=False
    if not target_locked:
        q['qualified']=False;q['need_s']=12.0;q['v23912_blocker']='STRIKE NOT LOCKED';return q

    sgn=1.0 if side=='UP' else -1.0
    aligned=float(q.get('composite',0.0) or 0.0)*sgn
    tug=float(q.get('tug_align',0.0) or 0.0)  # already aligned to candidate side
    tug_p=max(0.0,min(1.0,float(q.get('tug_persistence',0.0) or 0.0)))
    mbi=float(q.get('mbi_align',0.0) or 0.0)/100.0
    flow=float(q.get('flow_align',0.0) or 0.0)
    breadth=int(q.get('breadth',0) or 0);core=int(q.get('core',0) or 0)
    fam=dict(q.get('families') or {})
    dest=float(q.get('destination_align',0.0) or 0.0)
    jside=str(q.get('journey_side','WAIT') or 'WAIT').upper()
    rmatch=max(0.0,min(100.0,float(q.get('journey_route_match',0.0) or 0.0)))
    cps=max(0,int(q.get('journey_checkpoints',0) or 0))

    # IMPORTANT: the old V23.9.9 rule made "<2 checkpoints" an absolute veto.
    # In live Bookmap this frequently leaves only the official target checkpoint
    # while floor/ceiling are still forming, permanently starving the lock.
    # One official target + coherent directional map is enough to continue.
    mapped=bool(cps>=1 or rmatch>=45.0 or abs(dest)>=.08)

    # Only genuinely strong opposite path evidence gets a hard veto.
    dest_hard_opp=dest<=-.27
    route_hard_opp=bool(jside in ('UP','DOWN') and jside!=side and rmatch>=76.0 and dest<=-.03)
    momentum_hard_opp=bool(mbi<=-.46 or (tug<=-.34 and tug_p>=.56) or bool(q.get('flow_veto')))
    hard_opp=dest_hard_opp or route_hard_opp or momentum_hard_opp

    # Base threshold from the end-path regime. Weak/incomplete maps make James
    # wait and ask for a little more edge, but they do not make locking impossible.
    edge_need=_v23912_regime_path_need(q.get('regime') or {})
    if not mapped:edge_need+=.018
    if rmatch and rmatch<48:edge_need+=.012
    if jside in ('UP','DOWN') and jside!=side and not route_hard_opp:edge_need+=.014
    if dest<-.08 and not dest_hard_opp:edge_need+=.010

    # Loss memory teaches caution, never paralysis. Repeated analog failures can
    # add a bounded penalty, but an old memory cannot permanently veto a clean,
    # mature current setup.
    mem=dict(q.get('loss_memory') or {})
    mem_add_s=min(3.0,max(0.0,float(mem.get('added_patience_s',0.0) or 0.0)))
    mem_edge=min(.015,max(0.0,float(mem.get('edge_add',0.0) or 0.0)))
    edge_need+=mem_edge
    mem_fail=float(mem.get('fail_rate',0.0) or 0.0);mem_n=int(mem.get('n',0) or 0);mem_top=float(mem.get('top_sim',0.0) or 0.0)
    exact_bad_analog=bool(mem_n>=8 and mem_fail>=.80 and mem_top>=.88)

    # Full five-minute patience schedule. Early calls require the cleanest map;
    # later in the window James can act on a mature 2-3 family thesis rather than
    # waiting forever for cosmetic checkpoint completeness.
    if into<60:
        phase='EARLY MAP';edge_need+=.018;phase_need=(10.5,12.5,14.0)
        min_breadth=3
    elif into<180:
        phase='PATIENT MAP';phase_need=(9.0,11.0,12.5);min_breadth=2
    elif into<240:
        phase='MATURE MAP';edge_need=max(.118,edge_need-.010);phase_need=(7.5,9.5,11.0);min_breadth=2
    else:
        phase='FINAL 60S';edge_need=max(.112,edge_need-.020);phase_need=(6.0,8.0,9.5);min_breadth=2

    decisive=bool(breadth>=4 and core>=2 and aligned>=edge_need+.07 and not hard_opp)
    strong=bool(breadth>=3 and core>=2 and aligned>=edge_need+.025 and not hard_opp)
    need_s=(phase_need[0] if decisive else phase_need[1] if strong else phase_need[2])+mem_add_s
    if not mapped:need_s+=1.5
    if jside in ('UP','DOWN') and jside!=side and not route_hard_opp:need_s+=1.0
    need_s=min(15.5,max(5.5,need_s))

    # Foundational family requirement. Original Tug is the only Tug authority.
    # Two-family late setups are allowed only when ROUTE or OLD TUG is one of them.
    family_ok=bool(breadth>=min_breadth and core>=1)
    if breadth<=2:
        family_ok=family_ok and bool(fam.get('ROUTE') or fam.get('TUG'))
    tug_or_route=bool((tug>=.075 and tug_p>=.32) or fam.get('ROUTE'))
    if into>=180:family_ok=family_ok and tug_or_route

    # Exact-bad memory analog requires one extra proof family before 4:00; in the
    # final minute a genuinely strong present-tense map may override old history.
    memory_block=bool(exact_bad_analog and into<240 and breadth<3 and not decisive)

    qualified=bool(q['window_open'] and not hard_opp and not memory_block and family_ok and aligned>=edge_need)
    # First minute is deliberately patient: only a genuinely strong/decisive map
    # may lock. The full five-minute window means there is no reason to rush an
    # ordinary two/three-family read in the opening seconds.
    if qualified and into<60 and not strong:qualified=False
    if qualified and into<60 and not mapped and not decisive:qualified=False

    q.update({'qualified':qualified,'decisive':decisive,'strong':strong,'need_s':need_s,
              'edge_need':edge_need,'path_veto':hard_opp,'journey_path_ready':mapped,
              'v23912_phase':phase,'v23912_hard_opp':hard_opp,'v23912_memory_block':memory_block,
              'v23912_exact_bad_analog':exact_bad_analog})
    if hard_opp:blocker='STRONG OPPOSITE PATH'
    elif memory_block:blocker='REPEATED LOSS ANALOG NEEDS 3-FAMILY PROOF'
    elif not family_ok:blocker='CONFLUENCE BUILDING'
    elif aligned<edge_need:blocker=f'EDGE {aligned:.3f} < {edge_need:.3f}'
    elif not qualified:blocker='MAP STILL FORMING'
    else:blocker='QUALIFIED — PERSISTENCE BUILDING'
    q['v23912_blocker']=blocker
    q['reason']=(str(q.get('reason','')).split(' • LOSS MEMORY ')[0]
                 +f' • V23.9.12 {phase} • mapped {"YES" if mapped else "PARTIAL"} • edge {aligned:.3f}/{edge_need:.3f}'
                 +f' • OLD TUG {tug:+.2f} p{tug_p*100:.0f} • persist {need_s:.1f}s'
                 +(f' • MEMORY +{mem_add_s:.1f}s/+{mem_edge:.3f}' if mem.get('ready') else '')
                 +f' • {blocker}')
    return q

