def _v23913_lock_heartbeat(app):
    """Independent first-lock heartbeat.  The lock engine no longer depends on a
    warmup/UI callback happening to fire; this keeps overnight grading alive."""
    try:
        root=getattr(app,'root',None)
        if root is None:return
        now=time.time()
        try:app._bookmap_opening_lock_tick(warm=None,now=now)
        except Exception as exc:
            last=float(getattr(app,'_v23913_hb_err_ts',0) or 0)
            if now-last>30:
                app._v23913_hb_err_ts=now
                try:_v232_add_event(app,'LOCK HEARTBEAT recovered: '+str(exc)[:120],_V232_RED)
                except Exception:pass
    finally:
        try:getattr(app,'root').after(450,lambda a=app:_v23913_lock_heartbeat(a))
        except Exception:pass

