def _v23914_is_recurrent_callback(cb):
    try:
        nm=str(getattr(cb,'__name__','') or '')
        if nm in _V23914_RECURRENT_NAMES:return True
        code=getattr(cb,'__code__',None)
        names=set(getattr(code,'co_names',()) or ()) if code is not None else set()
        return bool(names & _V23914_RECURRENT_NAMES)
    except Exception:return False

def _v23914_run_without_reschedule(app,fn,*args,**kwargs):
    """Run one legacy body while suppressing only its recurring heartbeat callbacks.
    One-shot UI callbacks are left alone. This lets the new scheduler own cadence."""
    root=getattr(app,'root',None)
    if root is None:return None
    try:orig_after=root.after
    except Exception:return fn(*args,**kwargs)
    def filtered_after(ms,func=None,*a):
        try:
            if func is not None and _v23914_is_recurrent_callback(func):
                return 'v23914-suppressed'
        except Exception:pass
        return orig_after(ms,func,*a)
    try:
        root.after=filtered_after
        return fn(*args,**kwargs)
    finally:
        try:root.after=orig_after
        except Exception:pass

# ----- StringVar / Tk Variable repaint deduper --------------------------------
def _v23914_dedupe_var(var):
    try:
        if var is None or getattr(var,'_v23914_deduped',False):return
        orig=var.set; last=[var.get()]
        def smart_set(value,_orig=orig,_last=last):
            try:
                if value==_last[0] or str(value)==str(_last[0]):return
            except Exception:pass
            _last[0]=value
            return _orig(value)
        var.set=smart_set;var._v23914_deduped=True
    except Exception:pass

def _v23914_install_var_dedupe(app):
    try:
        for v in list((getattr(app,'_v232_vars',{}) or {}).values()):_v23914_dedupe_var(v)
    except Exception:pass
    try:
        for _k,v in list(getattr(app,'__dict__',{}).items()):
            if isinstance(v,tk.Variable):_v23914_dedupe_var(v)
    except Exception:pass

