def _v2399_animate(label,frames,delay=82,index=0):
    try:
        if label is None or not label.winfo_exists() or not frames:return
        if len(frames)<=1:
            fr=frames[0];label.configure(image=fr);label.image=fr;return
        # Real animations still animate, but cap the permanent cadence at 10 Hz.
        d=max(100,int(delay or 100));fr=frames[index%len(frames)];label.configure(image=fr);label.image=fr
        label.after(d,lambda l=label,f=frames,dd=d,i=index+1:_v2399_animate(l,f,dd,i))
    except Exception:pass

# ------------------------------ lock schedule --------------------------------
def _v23915_lock_schedule(into):
    into=float(into or 0.0)
    if into<60:return (.69,.110,12.5,17)
    if into<120:return (.66,.096,10.5,16)
    if into<180:return (.63,.084,9.0,14)
    if into<240:return (.60,.074,7.5,12)
    return (.58,.066,6.0,10)

def _v23915_present_alignment(self,q,route,candidate,now):
    # Same safety concept as V23.9.13, with a tiny reduction in the "support"
    # threshold so persistent modest evidence can mature instead of stalling.
    sgn=1.0 if candidate=='UP' else -1.0
    comp=float(q.get('composite',0) or 0)*sgn
    try:tug=dict(_v232_original_tug(self,now=now) or {})
    except Exception:tug={}
    tug_signed=float(tug.get('signed',tug.get('fused',0)) or 0)*sgn
    tug_p=max(0.0,min(1.0,float(tug.get('persistence',0) or 0)))
    route_signed=float((route or {}).get('terminal_signed',0) or 0)*sgn
    mbi=dict((route or {}).get('mbi') or {})
    mbi_signed=float(mbi.get('forward_score',mbi.get('score',0)) or 0)/100.0*sgn
    breadth=int(q.get('breadth',0) or 0);core=int(q.get('core',0) or 0)
    hard_opp=bool(q.get('v23912_hard_opp') or q.get('path_veto') or q.get('flow_veto'))
    current_stop=bool(hard_opp or (tug_signed<=-.40 and tug_p>=.58) or mbi_signed<=-.52 or route_signed<=-.38)
    support=0
    if comp>=.055:support+=1
    if route_signed>=.065:support+=1
    if tug_signed>=.055 and tug_p>=.23:support+=1
    if mbi_signed>=.09:support+=1
    if breadth>=2:support+=1
    return {'comp':comp,'tug':tug_signed,'tug_p':tug_p,'route':route_signed,'mbi':mbi_signed,
            'breadth':breadth,'core':core,'support':support,'hard_stop':current_stop}

def _v23915_open_lock_tick(self,warm=None,now=None):
    now=float(now or time.time());bucket=int(now//900)*900;into=max(0.0,now-bucket)
    existing=dict(getattr(self,'opening_lock_snapshot',{}) or {})
    exside=str(existing.get('lock_side','WAIT') or 'WAIT').upper()
    try:exbucket=int(existing.get('bucket',existing.get('market_bucket',-1)) or -1)
    except Exception:exbucket=-1
    if exside in ('UP','DOWN') and exbucket==bucket:return existing
    if exside in ('UP','DOWN') and exbucket!=bucket:
        self.opening_lock_snapshot=None;existing={}
    st=dict(getattr(self,'_v23915_lock_state',{}) or {})
    if int(st.get('bucket',-1) or -1)!=bucket:
        st={'bucket':bucket,'last_eval':0.0,'samples':deque(maxlen=180),'qual_side':'WAIT','qual_s':0.0,
            'cons_side':'WAIT','cons_s':0.0,'last_q':{},'last_status_ts':0.0}
        try:self.opening_lock_snapshot=None;self.opening_lock_bucket=bucket
        except Exception:pass
    last=float(st.get('last_eval',0) or 0)
    if last and now-last<.25:
        self._v23915_lock_state=st;return None
    dt=.45 if not last else max(.20,min(1.25,now-last));st['last_eval']=now
    if into>300.0:
        try:self.opening_lock_var.set('FIRST-LOCK WINDOW CLOSED • no coherent thesis earned in first 5:00')
        except Exception:pass
        st['last_q']={'side':'WAIT','qualified':False,'v23915_blocker':'5M WINDOW CLOSED'};self._v23915_lock_state=st;return None
    try:r=dict(getattr(self,'_v220_last',{}) or {})
    except Exception:r={}
    if not r.get('ready') or now-float(r.get('ts',now) or now)>1.6:
        try:r=dict(_v220_terminal_read(self,now=now) or {})
        except Exception:r={}
        if r.get('ready'):
            try:self._v220_last=dict(r)
            except Exception:pass
    if not r.get('ready'):
        try:self.opening_lock_var.set(f'MAPPING • {into:.0f}/300s • waiting for terminal route feed')
        except Exception:pass
        st['last_q']={'side':'WAIT','qualified':False,'v23915_blocker':'ROUTE FEED NOT READY'};self._v23915_lock_state=st;return None
    q=_v23913_current_packet(self,r,into,now)
    try:live,_ls=self.effective_live_price();target,_ts=self.effective_target()
    except Exception:live=target=None
    if live is None or target is None:
        q['qualified']=False;q['v23915_blocker']='STRIKE/LIVE NOT READY';st['last_q']=dict(q);self._v23915_lock_state=st
        try:self.opening_lock_var.set(f'MAPPING • {into:.0f}/300s • waiting for official strike/live BTC')
        except Exception:pass
        return None
    side=str(q.get('side','WAIT') or 'WAIT').upper();comp=float(q.get('composite',0) or 0)
    rawside=side
    # Slightly narrower sampling neutral zone than V23.9.13 (.060 -> .055).
    if rawside not in ('UP','DOWN') and abs(comp)>=.055:rawside='UP' if comp>0 else 'DOWN'
    hard=bool(q.get('v23912_hard_opp') or q.get('path_veto'))
    sample={'ts':now,'side':rawside if not hard else 'WAIT','composite':comp,'qualified':bool(q.get('qualified')),
            'breadth':int(q.get('breadth',0) or 0),'mapped':bool(q.get('journey_path_ready'))}
    samples=st.get('samples')
    if not isinstance(samples,deque):samples=deque(list(samples or []),maxlen=180)
    samples.append(sample)
    while samples and now-float(samples[0].get('ts',0) or 0)>75.0:samples.popleft()
    st['samples']=samples;consensus=_v23913_consensus(samples,now);cand=str(consensus.get('side','WAIT'))
    if side in ('UP','DOWN') and q.get('qualified'):
        if st.get('qual_side')!=side:st['qual_side']=side;st['qual_s']=dt
        else:st['qual_s']=min(60.0,float(st.get('qual_s',0) or 0)+dt)
    else:
        st['qual_s']=max(0.0,float(st.get('qual_s',0) or 0)-dt*.50)
        if st['qual_s']<=.05:st['qual_side']='WAIT'
    if cand in ('UP','DOWN'):
        if st.get('cons_side')!=cand:st['cons_side']=cand;st['cons_s']=dt
        else:st['cons_s']=min(90.0,float(st.get('cons_s',0) or 0)+dt)
    else:
        st['cons_s']=max(0.0,float(st.get('cons_s',0) or 0)-dt*.90)
        if st['cons_s']<=.05:st['cons_side']='WAIT'
    share_need,edge_need,cons_need,min_n=_v23915_lock_schedule(into)
    present=_v23915_present_alignment(self,q,r,cand,now) if cand in ('UP','DOWN') else {'hard_stop':False,'support':0,'comp':0,'tug':0,'tug_p':0,'route':0,'breadth':0}
    direct_side=str(st.get('qual_side','WAIT'))
    # ~1 second easier than V23.9.13, still bounded and never an instant lock.
    direct_need=max(6.2,min(11.5,float(q.get('need_s',9.5) or 9.5)-1.0))
    direct_ready=bool(direct_side in ('UP','DOWN') and float(st.get('qual_s',0) or 0)>=direct_need and
                      not _v23915_present_alignment(self,q,r,direct_side,now).get('hard_stop'))
    if direct_ready and into<24 and not bool(q.get('decisive')):direct_ready=False
    consensus_ready=bool(cand in ('UP','DOWN') and consensus.get('directional_n',0)>=min_n and
                         float(consensus.get('share',0) or 0)>=share_need and float(consensus.get('avg_edge',0) or 0)>=edge_need and
                         float(st.get('cons_s',0) or 0)>=cons_need and int(present.get('support',0) or 0)>=2 and not present.get('hard_stop'))
    if consensus_ready and into<60:
        early_now=bool(int(present.get('breadth',0) or 0)>=2 or (float(present.get('route',0) or 0)>=.075 and float(present.get('tug',0) or 0)>=.065))
        if not early_now:consensus_ready=False
    lock_side=direct_side if direct_ready else cand if consensus_ready else 'WAIT'
    q['v23915_consensus_side']=cand;q['v23915_consensus_share']=float(consensus.get('share',.5));q['v23915_consensus_edge']=float(consensus.get('avg_edge',0))
    q['v23915_consensus_s']=float(st.get('cons_s',0) or 0);q['v23915_direct_s']=float(st.get('qual_s',0) or 0)
    q['v23915_blocker']='LOCK READY' if lock_side in ('UP','DOWN') else ('CURRENT CONTRADICTION' if present.get('hard_stop') else 'ROLLING CONSENSUS BUILDING')
    st['last_q']=dict(q);self._v23915_lock_state=st
    self._v2393_lock_state={'bucket':bucket,'side':direct_side if direct_side in ('UP','DOWN') else cand,
                            'since':now-float(st.get('qual_s',0) or 0),'evidence_s':float(st.get('qual_s',0) or 0),
                            'last_eval':now,'last_q':dict(q)}
    try:
        self.opening_lock_var.set(f'FORMULATING {cand} • {into:.0f}/300s • consensus {float(consensus.get("share",.5))*100:.0f}% '
                                  f'edge {float(consensus.get("avg_edge",0)):.3f}/{edge_need:.3f} • '
                                  f'hold {float(st.get("cons_s",0)):.1f}/{cons_need:.1f}s • direct {float(st.get("qual_s",0)):.1f}/{direct_need:.1f}s')
    except Exception:pass
    if now-float(st.get('last_status_ts',0) or 0)>=24.0:
        st['last_status_ts']=now;self._v23915_lock_state=st
        try:_v232_add_event(self,f'LOCK ENGINE • {into:.0f}/300s • {cand} {float(consensus.get("share",.5))*100:.0f}% • '
                           f'edge {float(consensus.get("avg_edge",0)):.3f} • support {int(present.get("support",0) or 0)} • '
                           f'OLD TUG {float(present.get("tug",0)):+.2f} • {q.get("v23915_blocker")}',_V232_GOLD2)
        except Exception:pass
    if lock_side not in ('UP','DOWN'):return None
    fin=_v23915_present_alignment(self,q,r,lock_side,now)
    if fin.get('hard_stop'):return None
    strength=float(q.get('strength',0) or 0);strength=max(55.0,min(94.0,strength+max(0.0,float(consensus.get('share',.5))-.60)*24.0))
    reason=(f'V23.9.15 {"DIRECT" if direct_ready else "ROLLING CONSENSUS"} • {lock_side} • '
            f'{float(consensus.get("share",.5))*100:.0f}% vote • avg edge {float(consensus.get("avg_edge",0)):.3f} • '
            f'current support {int(fin.get("support",0))} • OLD TUG {float(fin.get("tug",0)):+.2f} p{float(fin.get("tug_p",0))*100:.0f} • '
            f'route {float(fin.get("route",0)):+.2f} • '+str(q.get('reason','')))
    snap={'time':now,'price':float(live),'target':float(target),'lock_side':lock_side,'strength':strength,
          'bucket':bucket,'market_bucket':bucket,'source':'V23.9.15 SILKY ROLLING CONSENSUS FIRST LOCK',
          'forecast_reasons':reason,'forecast_score':float(consensus.get('avg_edge',0))*10.0,'forecast_threshold':edge_need*10.0,
          'lock_remaining':'OPEN','lock_minute':int(into//60),'regime':str((q.get('regime') or {}).get('name','MIXED')),
          'consensus_share':float(consensus.get('share',0)),'consensus_edge':float(consensus.get('avg_edge',0))}
    self.opening_lock_snapshot=dict(snap);self.opening_lock_bucket=bucket;self.opening_lock_candidate=None;self.opening_lock_candidate_since=0.0
    try:self.opening_lock_var.set(f'MAIN LOCK: {lock_side} {strength:.0f}/100 • EARNED @ {into:.1f}s • consensus {float(consensus.get("share",0))*100:.0f}%')
    except Exception:pass
    try:_v232_add_event(self,f'FIRST LOCK EARNED • {lock_side} {strength:.0f}/100 • {reason}',_V232_GREEN if lock_side=='UP' else _V232_RED)
    except Exception:pass
    return dict(snap)

