def _v236_maybe_draw_charts(app,force=False):
    now=time.time()
    if not force:
        # Never rebuild hundreds of canvas objects while the user is actively scrolling.
        if bool(getattr(app,'_v237_scrolling',False)) or now<float(getattr(app,'_scroll_active_until',0) or 0):return None
        last=float(getattr(app,'_v23915_chart_gate_ts',0) or 0)
        if now-last<1.00:return None
        app._v23915_chart_gate_ts=now
    return _V23915_CHART_BASE(app,force)

# ------------------------------ single scheduler -----------------------------
_V23915_JOBS=(
    ('lock',.45,_v23915_lock_job,'critical'),
    ('route',.70,_v23915_route_refresh,'sensor'),
    ('target',1.00,_v23915_target_job,'sensor'),
    ('dashfeed',.48,lambda a:_v23915_run_base(a,_V23915_FEED_BASE),'ui'),
    ('dashboard',.72,lambda a:_v23915_run_base(a,_V23915_DASH_BASE),'ui'),
    ('mbi',1.00,lambda a:_v23915_run_base(a,_V23915_MBI_BASE),'ui'),
    ('livegrade',1.00,lambda a:_v23915_run_base(a,_V23915_LIVE_BASE),'ui'),
    ('journal',2.40,lambda a:_v23915_run_base(a,_V23915_JOURNAL_BASE),'ui'),
    ('audit',6.00,lambda a:_v23915_run_base(a,_V23915_AUDIT_BASE),'ui'),
    ('watchdog',60.0,lambda a:_v23915_run_base(a,_V23915_WATCHDOG_BASE),'ui'),
)

def _v23915_run_job(app,key,fn):
    t0=time.perf_counter()
    try:fn(app)
    except Exception as exc:
        try:
            now=time.time();last=float(getattr(app,'_v23915_err_ts',0) or 0)
            if now-last>20:app._v23915_err_ts=now;_v232_add_event(app,'SILKY CORE recovered '+key+': '+str(exc)[:100],_V232_RED)
        except Exception:pass
    ms=(time.perf_counter()-t0)*1000.0
    perf=getattr(app,'_v23915_job_ms',None)
    if not isinstance(perf,dict):perf={};app._v23915_job_ms=perf
    old=float(perf.get(key,ms) or ms);perf[key]=old*.84+ms*.16
    return ms

def _v23915_master_pump(app):
    root=getattr(app,'root',None)
    if root is None:return
    now=time.perf_counter();due=getattr(app,'_v23915_due',None)
    if not isinstance(due,dict):
        due={};offs={'lock':.02,'route':.08,'target':.18,'dashfeed':.12,'dashboard':.28,'mbi':.42,'livegrade':.55,'journal':.85,'audit':1.5,'watchdog':4.0}
        for key,period,fn,kind in _V23915_JOBS:due[key]=now+offs.get(key,.2)
        app._v23915_due=due
    start=time.perf_counter()
    try:
        # Lock gets first claim on the frame budget.
        key,period,fn,kind=_V23915_JOBS[0]
        if now>=float(due.get(key,0) or 0):
            _v23915_run_job(app,key,fn);due[key]=now+period
        # Route/strike sensors alternate: never stack both into every frame.
        sensors=[]
        for key,period,fn,kind in _V23915_JOBS:
            if kind=='sensor' and now>=float(due.get(key,0) or 0):sensors.append((float(due.get(key,0) or 0),key,period,fn))
        if sensors:
            _d,key,period,fn=min(sensors,key=lambda x:x[0]);_v23915_run_job(app,key,fn);due[key]=now+period
        # One cosmetic/telemetry job only when the current frame is still cheap.
        spent=(time.perf_counter()-start)*1000.0
        if spent<7.0:
            ui=[]
            for key,period,fn,kind in _V23915_JOBS:
                if kind=='ui' and now>=float(due.get(key,0) or 0):ui.append((float(due.get(key,0) or 0),key,period,fn))
            if ui:
                _d,key,period,fn=min(ui,key=lambda x:x[0]);ms=_v23915_run_job(app,key,fn);due[key]=now+period
                if ms>24:
                    # Expensive paint: give Tk a clean breath before the next UI job.
                    for k in list(due):
                        if k not in ('lock','route','target') and due[k]<now+.14:due[k]=now+.14
    except Exception:pass
    finally:
        total=(time.perf_counter()-start)*1000.0
        old=float(getattr(app,'_v23915_master_ms',total) or total);app._v23915_master_ms=old*.88+total*.12
        try:app._v23915_master_job=root.after(90,lambda a=app:_v23915_master_pump(a))
        except Exception:pass

