def _v23917_clip(x,lo=-1.0,hi=1.0):
    try:return max(float(lo),min(float(hi),float(x)))
    except Exception:return 0.0


def _v23917_num(x,d=0.0):
    try:
        z=float(x)
        return z if math.isfinite(z) else float(d)
    except Exception:return float(d)


def _v23917_source_1m(app):
    """Merge already-maintained 1m candle stores. Never rescan raw executions."""
    merged={}
    for src in (
        list(getattr(app,'btc_1m',[]) or [])[-720:],
        list(getattr(app,'_v234_visual_1m',[]) or [])[-720:],
        list((getattr(app,'_v2355_dash_1m',{}) or {}).values()),
    ):
        for r0 in src:
            try:
                r=dict(r0);ts=int(float(r.get('time',r.get('ts',0)) or 0)//60)*60
                o=float(r['open']);h=float(r['high']);l=float(r['low']);c=float(r['close']);v=max(0.0,float(r.get('volume',0) or 0))
                if ts<=0 or not all(math.isfinite(x) for x in (o,h,l,c)):continue
                old=merged.get(ts)
                if old is None:
                    merged[ts]={'time':ts,'open':o,'high':h,'low':l,'close':c,'volume':v}
                else:
                    # Newer/live stores may improve the forming candle.
                    old['high']=max(float(old['high']),h);old['low']=min(float(old['low']),l);old['close']=c;old['volume']=max(float(old.get('volume',0) or 0),v)
            except Exception:pass
    rows=[merged[k] for k in sorted(merged)]
    return rows[-650:]


def _v23917_atr_series(rows,length=14):
    n=len(rows);out=[None]*n
    if n<2:return out
    trs=[]
    for i,r in enumerate(rows):
        h=_v23917_num(r.get('high'));l=_v23917_num(r.get('low'));pc=_v23917_num(rows[i-1].get('close')) if i else _v23917_num(r.get('close'))
        trs.append(max(h-l,abs(h-pc),abs(l-pc)))
    if n<length:return out
    seed=sum(trs[:length])/float(length);out[length-1]=seed;prev=seed
    for i in range(length,n):
        prev=(prev*(length-1)+trs[i])/float(length);out[i]=prev
    return out


def _v23917_pivots(rows,left=5,right=5):
    highs=[_v23917_num(r.get('high')) for r in rows];lows=[_v23917_num(r.get('low')) for r in rows];out=[]
    for i in range(left,max(left,len(rows)-right)):
        h=highs[i];l=lows[i];hw=highs[i-left:i+right+1];lw=lows[i-left:i+right+1]
        # Confirmed local turns. Requiring one strict neighbor prevents plateaus
        # from exploding into duplicate pivot levels while preserving the 5/5 idea.
        ph=bool(hw and h>=max(hw) and any(h>x for j,x in enumerate(hw) if j!=left))
        pl=bool(lw and l<=min(lw) and any(l<x for j,x in enumerate(lw) if j!=left))
        if ph:out.append({'price':h,'idx':i,'confirm':i+right,'isHigh':True})
        if pl:out.append({'price':l,'idx':i,'confirm':i+right,'isHigh':False})
    out.sort(key=lambda x:(x['confirm'],0 if x['isHigh'] else 1))
    return out


def _v23917_kmeans_prices(pivots,k=5,iterations=25):
    vals=[_v23917_num(p.get('price')) for p in pivots if _v23917_num(p.get('price'))>0]
    if not vals:return []
    clusters=max(1,min(int(k),len(vals)));lo=min(vals);hi=max(vals)
    cents=[(lo+hi)/2.0] if clusters==1 else [lo+(hi-lo)*i/(clusters-1) for i in range(clusters)]
    for _ in range(max(1,int(iterations))):
        sums=[0.0]*clusters;counts=[0]*clusters
        for v in vals:
            cid=min(range(clusters),key=lambda j:abs(v-cents[j]));sums[cid]+=v;counts[cid]+=1
        for j in range(clusters):
            if counts[j]:cents[j]=sums[j]/counts[j]
    return sorted(cents)


def _v23917_source_sig(app):
    # O(1)-ish signature: do NOT merge hundreds of rows just to discover that
    # the same 1m profile is still current.
    vals=[]
    for name in ('btc_1m','_v234_visual_1m'):
        try:
            src=getattr(app,name,[]) or []; last=src[-1] if src else {}; vals.extend((len(src),int(float(last.get('time',last.get('ts',0)) or 0)//60)*60))
        except Exception:vals.extend((0,0))
    try:
        d=getattr(app,'_v2355_dash_1m',{}) or {}; k=next(reversed(d)) if d else 0; vals.extend((len(d),int(float(k)//60)*60))
    except Exception:vals.extend((0,0))
    return tuple(vals)


def _v23917_recent_rows_fast(app,static):
    rows=[dict(r) for r in list((static or {}).get('recent_rows') or [])]
    candidates=[]
    for name in ('btc_1m','_v234_visual_1m'):
        try:
            src=getattr(app,name,[]) or []
            if src:candidates.append(dict(src[-1]))
        except Exception:pass
    try:
        d=getattr(app,'_v2355_dash_1m',{}) or {}
        if d:candidates.append(dict(d[next(reversed(d))]))
    except Exception:pass
    for r in candidates:
        try:
            ts=int(float(r.get('time',r.get('ts',0)) or 0)//60)*60
            if rows and int(float(rows[-1].get('time',0) or 0)//60)*60==ts:rows[-1]=r
            elif ts>0:rows.append(r)
        except Exception:pass
    return rows[-8:]


def _v23917_build_profile(app):
    sig=_v23917_source_sig(app);cache=getattr(app,'_v23917_profile_cache',None)
    if isinstance(cache,tuple) and len(cache)==2 and cache[0]==sig:return cache[1]
    rows=_v23917_source_1m(app);n=len(rows)
    if n<32:return {'ready':False,'reason':'need >=32 1m candles','rows':n}
    # Static pivot/profile math is minute/history cached. Live touch/reaction state
    # updates separately without rebuilding k-means or all 140 bins.
    last_bucket=int(_v23917_num(rows[-1].get('time'))//60)*60

    left=5;right=5;lookback=600;memory=240;radius=3;nbins=140;atr_len=14;atr_mult=2.0
    atrs=_v23917_atr_series(rows,atr_len);piv_all=_v23917_pivots(rows,left,right)

    # Replay active pivot lines so ATR-overlap filtering and breaks behave like
    # the source indicator instead of inventing generic S/R after the fact.
    events={}
    for p in piv_all:events.setdefault(int(p['confirm']),[]).append(p)
    levels=[]
    for b in range(n):
        evs=events.get(b,())
        for p in evs:
            atr=_v23917_num(atrs[b],0.0);threshold=max(1e-9,atr*atr_mult)
            px=float(p['price'])
            overlap=any((not z.get('isBroken')) and abs(float(z['level'])-px)<=threshold for z in levels)
            if not overlap:
                levels.append({'level':px,'isSupport':not bool(p['isHigh']),'isBroken':False,'start':int(p['idx']),'confirm':b,'broken_at':None})
        close=_v23917_num(rows[b].get('close'))
        for z in levels:
            if z.get('isBroken'):continue
            broke=(not z['isSupport'] and close>float(z['level'])) or (z['isSupport'] and close<float(z['level']))
            if broke:z['isBroken']=True;z['broken_at']=b
        # Pine deletes levels older than lookback and caps the retained line list.
        levels=[z for z in levels if b-int(z.get('start',b))<=lookback]
        if len(levels)>120:levels=levels[-120:]

    # Current profile uses newest pivots subject to both memory and lookback.
    min_idx=max(0,n-1-lookback)
    piv=[p for p in piv_all if int(p['idx'])>=min_idx][-memory:]
    if not piv:return {'ready':False,'reason':'no confirmed pivots','rows':n}
    win=rows[-min(n,lookback+1):];local_hi=max(_v23917_num(r.get('high')) for r in win);local_lo=min(_v23917_num(r.get('low')) for r in win)
    span=max(local_hi-local_lo,1e-9);bin_size=span/float(nbins)
    counts=[0]*nbins;hc=[0]*nbins;lc=[0]*nbins
    for p in piv:
        idx=int(math.floor((float(p['price'])-local_lo)/bin_size));idx=max(0,min(nbins-1,idx))
        for j in range(max(0,idx-radius),min(nbins-1,idx+radius)+1):
            counts[j]+=1
            if p['isHigh']:hc[j]+=1
            else:lc[j]+=1
    mx=max(counts) if counts else 0;poc_i=max(range(nbins),key=lambda i:counts[i]) if mx>0 else 0
    cents=_v23917_kmeans_prices(piv,5,25)
    bins=[]
    for i,cnt in enumerate(counts):
        bot=local_lo+i*bin_size;top=bot+bin_size;prob=(float(cnt)/float(mx)) if mx>0 else 0.0
        dom='BULLISH' if lc[i]>hc[i] else 'BEARISH' if hc[i]>lc[i] else 'MIXED'
        bins.append({'i':i,'low':bot,'high':top,'center':(bot+top)/2.0,'count':cnt,'probability':prob,
                     'high_count':hc[i],'low_count':lc[i],'dominance':dom})
    poc=dict(bins[poc_i]);poc['price']=poc['center'];poc['probability']=1.0 if mx>0 else 0.0

    def prob_at(px):
        i=max(0,min(nbins-1,int(math.floor((float(px)-local_lo)/bin_size))))
        return bins[i]
    for z in levels:
        b=prob_at(z['level']);z['probability']=float(b['probability']);z['dominance']=b['dominance'];z['bin']=int(b['i'])
        z['cluster']=min(range(len(cents)),key=lambda j:abs(float(z['level'])-cents[j])) if cents else 0

    # Merge contiguous >=80% bins into broader high-density reversal zones.
    zones=[];cur=None
    for b in bins:
        if b['probability']>=.80:
            if cur is None:cur={'low':b['low'],'high':b['high'],'max_probability':b['probability'],'high_count':b['high_count'],'low_count':b['low_count'],'bins':[b['i']]}
            else:
                cur['high']=b['high'];cur['max_probability']=max(cur['max_probability'],b['probability']);cur['high_count']+=b['high_count'];cur['low_count']+=b['low_count'];cur['bins'].append(b['i'])
        elif cur is not None:
            zones.append(cur);cur=None
    if cur is not None:zones.append(cur)
    for z in zones:
        z['center']=(z['low']+z['high'])/2.0;z['dominance']='BULLISH' if z['low_count']>z['high_count'] else 'BEARISH' if z['high_count']>z['low_count'] else 'MIXED'

    atr=_v23917_num(atrs[-1],0.0) or max(bin_size*4.0,span/80.0)
    out={'ready':True,'source':'AlgoAlpha RPP port • 1m','rows':n,'pivots':len(piv),'lookback':lookback,'pivot_memory':memory,
         'pivot_left':left,'pivot_right':right,'profile_bins':nbins,'bin_radius':radius,'bin_size':bin_size,
         'local_low':local_lo,'local_high':local_hi,'max_count':mx,'atr':atr,'bins':bins,'poc':poc,'clusters':cents,
         'levels':levels,'active_levels':[dict(z) for z in levels if not z.get('isBroken')],
         'broken_levels':[dict(z) for z in levels if z.get('isBroken')],'zones':zones,'last_bucket':last_bucket,'recent_rows':[dict(r) for r in rows[-8:]]}
    app._v23917_profile_cache=(sig,out);return out


def _v23917_level_state(level,live,atr,rows):
    px=float(level.get('level'));support=bool(level.get('isSupport'));dist=(live-px)/max(atr,1e-9)
    recent=rows[-5:] if rows else []
    rh=max([_v23917_num(r.get('high')) for r in recent] or [live]);rl=min([_v23917_num(r.get('low')) for r in recent] or [live])
    last_close=_v23917_num(recent[-1].get('close'),live) if recent else live
    if support:
        if live<px-.04*atr:return 'DOWNSIDE ACCEPTANCE'
        if rl<=px+.06*atr and last_close>=px+.035*atr:return 'BULLISH REJECTION'
        if abs(live-px)<=.18*atr or rl<=px+.08*atr:return 'TESTING'
        if 0<=dist<=.80:return 'APPROACHING'
    else:
        if live>px+.04*atr:return 'UPSIDE ACCEPTANCE'
        if rh>=px-.06*atr and last_close<=px-.035*atr:return 'BEARISH REJECTION'
        if abs(live-px)<=.18*atr or rh>=px-.08*atr:return 'TESTING'
        if -.80<=dist<=0:return 'APPROACHING'
    return 'DISTANT'


def _v23917_context(app,route=None,now=None):
    now=float(now or time.time());static=_v23917_build_profile(app)
    if not static.get('ready'):return {'ready':False,'signed':0.0,'reason':static.get('reason','warming')}
    try:live,_=app.effective_live_price();live=float(live) if live is not None else None
    except Exception:live=None
    if live is None:
        try:live=float((route or {}).get('live'))
        except Exception:return {'ready':False,'signed':0.0,'reason':'live unavailable'}
    atr=max(1e-9,float(static.get('atr',1.0) or 1.0));bins=list(static.get('bins') or []);lo=float(static['local_low']);bs=float(static['bin_size'])
    bi=max(0,min(len(bins)-1,int(math.floor((live-lo)/max(bs,1e-9))))) if bins else 0;cur=dict(bins[bi]) if bins else {}
    rows=_v23917_recent_rows_fast(app,static)
    active=[dict(z) for z in static.get('active_levels',[])];broken=[dict(z) for z in static.get('broken_levels',[])]
    supports=sorted([z for z in active if z['isSupport'] and float(z['level'])<=live],key=lambda z:live-float(z['level']))
    resists=sorted([z for z in active if (not z['isSupport']) and float(z['level'])>=live],key=lambda z:float(z['level'])-live)
    ns=supports[0] if supports else None;nr=resists[0] if resists else None
    for z in active:
        z['distance_atr']=abs(live-float(z['level']))/atr;z['state']=_v23917_level_state(z,live,atr,rows)
    # refresh nearest refs after state enrichment
    ns=min([z for z in active if z['isSupport'] and float(z['level'])<=live],key=lambda z:live-float(z['level']),default=None)
    nr=min([z for z in active if (not z['isSupport']) and float(z['level'])>=live],key=lambda z:float(z['level'])-live,default=None)

    comps=[]
    # Current bin density/dominance: meaningful only when historical reversals
    # actually cluster here.
    cp=float(cur.get('probability',0) or 0);ch=float(cur.get('high_count',0) or 0);cl=float(cur.get('low_count',0) or 0)
    cdom=(cl-ch)/max(1.0,cl+ch);comps.append(('CURRENT_BIN',cp*cdom*.46))
    # Every active source level contributes with density * distance decay.
    for z in active:
        d=abs(live-float(z['level']))/atr
        if d>4.0:continue
        prox=math.exp(-d/1.20);p=float(z.get('probability',0) or 0);sgn=1.0 if z['isSupport'] else -1.0
        state=str(z.get('state','DISTANT'))
        if state=='BULLISH REJECTION':sgn=1.0;prox*=1.75
        elif state=='BEARISH REJECTION':sgn=-1.0;prox*=1.75
        elif state=='UPSIDE ACCEPTANCE':sgn=1.0;prox*=1.55
        elif state=='DOWNSIDE ACCEPTANCE':sgn=-1.0;prox*=1.55
        comps.append((f'LEVEL@{float(z["level"]):.2f}',sgn*p*prox*.34))
    # High-density profile zones also matter even if no active line is centered
    # exactly there. Direction comes from pivot-low vs pivot-high dominance.
    for z in static.get('zones',[]):
        center=float(z['center']);d=abs(live-center)/atr
        if d>3.2:continue
        p=float(z.get('max_probability',0) or 0);dom=str(z.get('dominance','MIXED'));sgn=1.0 if dom=='BULLISH' else -1.0 if dom=='BEARISH' else 0.0
        if sgn:comps.append((f'ZONE@{center:.2f}',sgn*p*math.exp(-d/1.45)*.26))
    poc=dict(static.get('poc') or {});poc_dom=str(poc.get('dominance','MIXED'));poc_sgn=1.0 if poc_dom=='BULLISH' else -1.0 if poc_dom=='BEARISH' else 0.0
    poc_dist=abs(live-float(poc.get('price',live)))/atr
    if poc_sgn and poc_dist<=2.2:comps.append(('MAX_ZONE',poc_sgn*math.exp(-poc_dist/1.2)*.20))
    raw=sum(v for _k,v in comps);signed=math.tanh(raw*1.35)

    # Path barriers use all nearby active levels / high-density zones. They are
    # directional obstacle maps, not reversal guarantees.
    up_bar=down_bar=up_def=down_def=0.0
    for z in active:
        p=float(z.get('probability',0) or 0);d=abs(live-float(z['level']))/atr;w=p*math.exp(-d/1.5)
        if not z['isSupport'] and float(z['level'])>=live:up_bar=max(up_bar,w)
        if z['isSupport'] and float(z['level'])<=live:down_bar=max(down_bar,w)
        if z['isSupport'] and float(z['level'])<=live:up_def=max(up_def,w)
        if not z['isSupport'] and float(z['level'])>=live:down_def=max(down_def,w)
    for z in static.get('zones',[]):
        d=abs(live-float(z['center']))/atr;w=float(z.get('max_probability',0) or 0)*math.exp(-d/1.6);dom=z.get('dominance')
        if float(z['center'])>=live and dom=='BEARISH':up_bar=max(up_bar,w)
        if float(z['center'])<=live and dom=='BULLISH':down_bar=max(down_bar,w)

    # Most immediate reaction state / confirmation.
    candidates=[z for z in active if abs(live-float(z['level']))/atr<=.35]
    touch=min(candidates,key=lambda z:abs(live-float(z['level'])),default=None)
    state=str(touch.get('state')) if touch else ('MAX ZONE TEST' if cp>=.80 else 'BETWEEN ZONES')
    reaction_side='UP' if state in ('BULLISH REJECTION','UPSIDE ACCEPTANCE') else 'DOWN' if state in ('BEARISH REJECTION','DOWNSIDE ACCEPTANCE') else 'WAIT'
    reaction_confirmed=reaction_side in ('UP','DOWN')
    touch_prob=float(touch.get('probability',cp) if touch else cp)

    # Select strategic display checkpoints, while the score above still considers
    # every active level and every high-density zone in range.
    strategic=[]
    for z in (supports[:4]+resists[:4]):
        zz=dict(z);zz['kind']='RPP_SUPPORT' if z['isSupport'] else 'RPP_RESISTANCE';strategic.append(zz)
    if poc:strategic.append({'level':float(poc.get('price',0)),'probability':1.0,'kind':'RPP_MAX_ZONE','dominance':poc_dom,'state':'MAX ZONE'})
    strategic.sort(key=lambda z:abs(live-float(z.get('level',live))))
    all_impacts=sorted(({'name':k,'impact':v} for k,v in comps),key=lambda x:abs(x['impact']),reverse=True)
    return {'ready':True,'live':live,'atr':atr,'signed':_v23917_clip(signed),'raw_score':raw,'current_bin':cur,
            'current_probability':cp,'current_dominance':cur.get('dominance','MIXED'),'poc':poc,'poc_distance_atr':poc_dist,
            'nearest_support':ns,'nearest_resistance':nr,'state':state,'reaction_side':reaction_side,'reaction_confirmed':reaction_confirmed,
            'touch_probability':touch_prob,'up_barrier':up_bar,'down_barrier':down_bar,'up_defense':up_def,'down_defense':down_def,
            'strategic_levels':strategic,'all_levels':active,'all_profile_bins':bins,'high_density_zones':list(static.get('zones') or []),
            'clusters':list(static.get('clusters') or []),'impacts':all_impacts[:18],'profile':static}


def _v220_terminal_read(self,now=None):
    out=dict(_V23917_BASE_TERMINAL(self,now=now) or {})
    if not out.get('ready'):return out
    try:ctx=_v23917_context(self,out,now)
    except Exception:ctx={'ready':False,'signed':0.0}
    if not ctx.get('ready'):
        out['rpp']=ctx;return out
    old=float(out.get('terminal_signed',0) or 0);rs=float(ctx.get('signed',0) or 0)
    # RPP is meaningful structure, but it does not become the sole brain.
    adj=.18*rs;new=_v23917_clip(old+adj)
    out['terminal_signed_pre_rpp']=old;out['terminal_signed']=new;out['rpp_adjustment']=adj;out['rpp_signed']=rs;out['rpp']=ctx
    # Feed reversal-density barriers into the existing route viability family.
    bump=3.5*rs
    out['up_viability']=max(0.0,min(100.0,float(out.get('up_viability',50) or 50)+bump))
    out['down_viability']=max(0.0,min(100.0,float(out.get('down_viability',50) or 50)-bump))
    # Strong CONFIRMED zone reaction may flip terminal side; density alone may not.
    nside='UP' if new>=.10 else 'DOWN' if new<=-.10 else str(out.get('terminal_side','NEUTRAL')).upper()
    if str(out.get('terminal_side','NEUTRAL')).upper() not in ('UP','DOWN') and nside in ('UP','DOWN'):out['terminal_side']=nside
    elif ctx.get('reaction_confirmed') and abs(new)>=.22 and nside in ('UP','DOWN'):out['terminal_side']=nside
    out['terminal_confidence']=max(50.0,min(98.0,50+abs(new)*48.0))
    self._v220_last=dict(out)
    # Journal only on meaningful RPP state transitions, not every route tick.
    try:
        poc=float((ctx.get('poc') or {}).get('price',0) or 0);sig=(ctx.get('state'),ctx.get('reaction_side'),round(float(ctx.get('current_probability',0) or 0)*10),round(poc/25.0))
        if sig!=getattr(self,'_v23917_event_sig',None):
            self._v23917_event_sig=sig
            if ctx.get('state') not in ('BETWEEN ZONES','DISTANT') or float(ctx.get('current_probability',0) or 0)>=.80:
                _v232_add_event(self,f'RPP • {ctx.get("state")} • density {float(ctx.get("current_probability",0))*100:.0f}% • bias {rs:+.2f} • MAX {poc:,.0f}',_V232_GOLD2)
    except Exception:pass
    return out


def _v229_journey(self,now=None):
    out=dict(_V23917_BASE_JOURNEY(self,now=now) or {})
    try:route=dict(out.get('v229_route') or getattr(self,'_v220_last',{}) or {});ctx=dict(route.get('rpp') or _v23917_context(self,route,now))
    except Exception:ctx={}
    if not ctx.get('ready'):return out
    cps=[dict(x) for x in list(out.get('checkpoints') or [])]
    seen=[]
    for c in cps:
        try:seen.append(float(c.get('price')))
        except Exception:pass
    for z in list(ctx.get('strategic_levels') or [])[:9]:
        try:
            px=float(z.get('level'));prob=float(z.get('probability',0) or 0)
            if any(abs(px-x)<=max(1.0,float(ctx.get('atr',1))*0.08) for x in seen):continue
            kind=str(z.get('kind','RPP_LEVEL'));dom=str(z.get('dominance','MIXED'));state=str(z.get('state',''))
            cps.append({'price':px,'label':f'{kind.replace("RPP_","")} {prob*100:.0f}% {dom}','kind':kind,'score':60+prob*35,'rpp_probability':prob,'rpp_state':state})
            seen.append(px)
        except Exception:pass
    live=float(ctx.get('live',0) or 0);cps.sort(key=lambda c:abs(float(c.get('price',live) or live)-live) if live else 0)
    side=str(out.get('route_side','WAIT') or 'WAIT').upper();sgn=1.0 if side=='UP' else -1.0 if side=='DOWN' else 0.0;align=float(ctx.get('signed',0) or 0)*sgn
    base_match=float(out.get('route_match',0) or 0);out['route_match']=max(0.0,min(100.0,base_match+align*12.0)) if base_match else max(0.0,min(100.0,50+align*30.0))
    out['checkpoints']=cps;out['rpp']=ctx;out['rpp_all_levels']=list(ctx.get('all_levels') or []);out['rpp_profile_bins']=list(ctx.get('all_profile_bins') or [])
    out['rpp_path_align']=align;out['rpp_state']=ctx.get('state');out['rpp_max_zone']=(ctx.get('poc') or {}).get('price')
    oldev=str(out.get('evidence_text',''))
    out['evidence_text']=(oldev+f' • RPP {float(ctx.get("current_probability",0))*100:.0f}% {ctx.get("current_dominance","MIXED")} • '
                          f'MAX {float((ctx.get("poc") or {}).get("price",0) or 0):,.0f} • structure {float(ctx.get("signed",0)):+.2f}')
    out['ready']=bool(out.get('ready') or cps)
    self._v2673_last_map=dict(out);return out


def _v23913_current_packet(self,route,into,now):
    q=dict(_V23917_BASE_PACKET(self,route,into,now) or {});side=str(q.get('side','WAIT') or 'WAIT').upper()
    try:ctx=dict((route or {}).get('rpp') or _v23917_context(self,route,now))
    except Exception:ctx={}
    if not ctx.get('ready'):
        q['rpp']={'ready':False};return q
    sgn=1.0 if side=='UP' else -1.0 if side=='DOWN' else (1.0 if float(q.get('composite',0) or 0)>=0 else -1.0)
    align=float(ctx.get('signed',0) or 0)*sgn
    fam=dict(q.get('families') or {});rpp_family=bool(side in ('UP','DOWN') and align>=.20)
    fam['RPP']=rpp_family;q['families']=fam
    if rpp_family:q['breadth']=int(q.get('breadth',0) or 0)+1
    # Explicit reaction confirmation can help, but only slightly; this prevents
    # the new structure family from undoing the anti-rush work.
    react=str(ctx.get('reaction_side','WAIT'));react_align=(react==side)
    if react_align and float(ctx.get('touch_probability',0) or 0)>=.65:
        q['need_s']=max(5.5,float(q.get('need_s',8.0) or 8.0)-.7)
    # A high-density confirmed reaction AGAINST the candidate is a real barrier.
    # Merely being near a dense bin is not a veto.
    rpp_hard_opp=bool(side in ('UP','DOWN') and react in ('UP','DOWN') and react!=side and
                      float(ctx.get('touch_probability',0) or 0)>=.80 and align<=-.35)
    if align<=-.20:
        q['need_s']=min(15.5,float(q.get('need_s',8.0) or 8.0)+1.0)
        q['edge_need']=float(q.get('edge_need',0) or 0)+.006
    if rpp_hard_opp and not bool(q.get('decisive')):q['qualified']=False
    q['rpp']=ctx;q['rpp_align']=align;q['rpp_family']=rpp_family;q['rpp_hard_opp']=rpp_hard_opp;q['rpp_density']=float(ctx.get('current_probability',0) or 0)
    q['rpp_state']=ctx.get('state');q['rpp_max_zone']=(ctx.get('poc') or {}).get('price')
    q['reason']=str(q.get('reason',''))+f' • RPP {align:+.2f} / density {float(ctx.get("current_probability",0))*100:.0f}% / {ctx.get("state","BETWEEN")}'+(' • RPP REACTION VETO' if rpp_hard_opp else '')
    return q


def _v23915_present_alignment(self,q,route,candidate,now):
    out=dict(_V23917_BASE_ALIGN(self,q,route,candidate,now) or {});sgn=1.0 if candidate=='UP' else -1.0
