def _v23911_similarity(a,b):
    base=float(_V23917_BASE_SIMILARITY(a,b) or 0.0)
    if 'rpp' not in (a or {}) or 'rpp' not in (b or {}):return base
    try:
        rs=math.exp(-abs(float(a.get('rpp',0))-float(b.get('rpp',0)))/.34);ds=math.exp(-abs(float(a.get('rpp_density',0))-float(b.get('rpp_density',0)))/.28)
        ts=1.0 if bool(float(a.get('rpp_touch',0)))==bool(float(b.get('rpp_touch',0))) else .62
        return max(0.0,min(1.0,.82*base+.18*(.50*rs+.35*ds+.15*ts)))
    except Exception:return base


def _v23911_diagnose_loss(side,seq,meta):
    out=dict(_V23917_BASE_DIAGNOSE(side,seq,meta) or {});side=str(side or 'WAIT').upper();events=list(out.get('event_order') or []);diag=list(out.get('diagnosis') or [])
    try:
        bad=[]
        for r in list(seq or []):
            ra=r.get('rpp_align');den=float(r.get('rpp_density',0) or 0)
            if ra is not None and float(ra)<=-.38 and den>=.75:bad.append(r)
        if len(bad)>=2 and 'RPP_REVERSAL_ZONE_IGNORED' not in diag:
            diag.append('RPP_REVERSAL_ZONE_IGNORED')
    except Exception:pass
    out['diagnosis']=diag or ['UNCLASSIFIED'];return out


