def _v23919_clip(x,lo=-1.0,hi=1.0):
    try:return max(float(lo),min(float(hi),float(x)))
    except Exception:return 0.0


def _v23919_mid(rows,i,n):
    try:
        n=max(1,int(n));i=int(i)
        if i-n+1<0:return None
        seg=rows[i-n+1:i+1]
        return (max(float(r['high']) for r in seg)+min(float(r['low']) for r in seg))*0.5
    except Exception:return None


def _v23919_atr_series(rows,n=14):
    rs=list(rows or []);n=max(1,int(n));out=[None]*len(rs)
    if len(rs)<2:return out
    tr=[];prev=float(rs[0]['close'])
    for i,r in enumerate(rs):
        h=float(r['high']);l=float(r['low']);c=float(r['close'])
        x=max(h-l,abs(h-prev),abs(l-prev)) if i else max(h-l,1e-9)
        tr.append(x);prev=c
    if len(tr)<n:return out
    acc=sum(tr[:n])/float(n);out[n-1]=acc
    for i in range(n,len(tr)):
        acc=(acc*(n-1)+tr[i])/float(n);out[i]=acc
    return out


def _v23919_ich_series(rows,conv,base,spanb,disp):
    rs=list(rows or []);N=len(rs)
    ten=[None]*N;kij=[None]*N;sa_raw=[None]*N;sb_raw=[None]*N
    for i in range(N):
        ten[i]=_v23919_mid(rs,i,conv);kij[i]=_v23919_mid(rs,i,base);sb_raw[i]=_v23919_mid(rs,i,spanb)
        if ten[i] is not None and kij[i] is not None:sa_raw[i]=(float(ten[i])+float(kij[i]))*.5
    # What the user sees at bar i is the leading span calculated `disp` bars ago.
    ca=[None]*N;cb=[None]*N
    for i in range(N):
        j=i-int(disp)
        if j>=0:
            ca[i]=sa_raw[j];cb[i]=sb_raw[j]
    return {'tenkan':ten,'kijun':kij,'span_a_raw':sa_raw,'span_b_raw':sb_raw,'cloud_a':ca,'cloud_b':cb}


def _v23919_ich_set(rows,conv,base,spanb,disp):
    rs=list(rows or []);N=len(rs);need=max(spanb+disp+3,2*disp+base+3)
    if N<need:return {'ready':False,'need':need,'bars':N}
    S=_v23919_ich_series(rs,conv,base,spanb,disp);ten=S['tenkan'];kij=S['kijun'];ca=S['cloud_a'];cb=S['cloud_b'];sa=S['span_a_raw'];sb=S['span_b_raw']
    i=N-1;pi=i-1
    if ten[i] is None or kij[i] is None or ca[i] is None or cb[i] is None:return {'ready':False,'need':need,'bars':N}
    close=float(rs[i]['close']);atr=max(1e-9,float(_v220_atr(rs[-80:],14)))
    cloud_a=float(ca[i]);cloud_b=float(cb[i]);cloud_lo=min(cloud_a,cloud_b);cloud_hi=max(cloud_a,cloud_b)
    price_state=1.0 if close>cloud_hi else -1.0 if close<cloud_lo else 0.0
    tkdiff=float(ten[i])-float(kij[i]);tk_state=1.0 if tkdiff>0 else -1.0 if tkdiff<0 else 0.0
    tkprev=0.0
    if ten[pi] is not None and kij[pi] is not None:tkprev=float(ten[pi])-float(kij[pi])
    cross='UP' if tkprev<=0<tkdiff else 'DOWN' if tkprev>=0>tkdiff else 'NONE'
    future_state=0.0
    if sa[i] is not None and sb[i] is not None:future_state=1.0 if sa[i]>sb[i] else -1.0 if sa[i]<sb[i] else 0.0
    hist_i=i-int(disp);hist_close=float(rs[hist_i]['close']);old_cloud_i=i-2*int(disp);past_lo=past_hi=None
    if old_cloud_i>=0 and sa[old_cloud_i] is not None and sb[old_cloud_i] is not None:
        past_lo=min(float(sa[old_cloud_i]),float(sb[old_cloud_i]));past_hi=max(float(sa[old_cloud_i]),float(sb[old_cloud_i]))
    chik=1.0 if close>hist_close else -1.0 if close<hist_close else 0.0
    if past_hi is not None:
        if close>hist_close and close>past_hi:chik=1.0
        elif close<hist_close and close<past_lo:chik=-1.0
        else:chik*=.45
    k2=float(kij[max(0,i-2)]) if kij[max(0,i-2)] is not None else float(kij[i])
    kij_slope=_v23919_clip((float(kij[i])-k2)/(atr*.55))
    thick=abs(cloud_hi-cloud_lo)/atr
    # Cloud-first guide ordering. Cross gets strength only in the correct cloud context.
    cross_strength=0.0
    if cross=='UP':cross_strength=1.0 if price_state>0 else .45 if price_state==0 else .15
    elif cross=='DOWN':cross_strength=-1.0 if price_state<0 else -.45 if price_state==0 else -.15
    # Chop penalty: repeated side changes / time inside cloud make Ichimoku less authoritative.
    recent=[]
    for j in range(max(0,N-10),N):
        if ca[j] is None or cb[j] is None:continue
        lo=min(float(ca[j]),float(cb[j]));hi=max(float(ca[j]),float(cb[j]));cl=float(rs[j]['close'])
        recent.append(1 if cl>hi else -1 if cl<lo else 0)
    inside=sum(1 for x in recent if x==0);flips=sum(1 for a,b in zip(recent,recent[1:]) if a and b and a!=b)
    chop=max(0.0,min(1.0,(inside*.10)+(flips*.18)))
    raw=.36*price_state+.20*tk_state+.18*chik+.12*future_state+.07*kij_slope+.07*cross_strength
    score=_v23919_clip(raw*(1.0-.38*chop))
    strong_side='UP' if price_state>0 and chik>0 and tk_state>0 else 'DOWN' if price_state<0 and chik<0 and tk_state<0 else 'WAIT'
    reversal='UP' if cross=='UP' and price_state>=0 and chik>=0 else 'DOWN' if cross=='DOWN' and price_state<=0 and chik<=0 else 'WAIT'
    return {'ready':True,'score':score,'price_state':price_state,'tk_state':tk_state,'cross':cross,'cross_strength':cross_strength,
            'future_state':future_state,'chikou_state':chik,'tenkan':float(ten[i]),'kijun':float(kij[i]),'cloud_low':cloud_lo,'cloud_high':cloud_hi,
            'future_a':None if sa[i] is None else float(sa[i]),'future_b':None if sb[i] is None else float(sb[i]),'cloud_atr':thick,'cloud_chop':chop,
            'strong_side':strong_side,'reversal_side':reversal,'atr':atr,'bars':N,'series':S}


def _v23919_ichimoku_read(app,now=None):
    now=float(now or time.time());cache=getattr(app,'_v23919_ichi_cache',None)
    try:
        if cache and now-float(cache[0])<.70:return cache[1]
    except Exception:pass
    try:rows=list(_v2355_direct_rows(app,60) or [])[-220:]
    except Exception:rows=[]
    fast=_v23919_ich_set(rows,6,13,26,13);classic=_v23919_ich_set(rows,9,26,52,26)
    if fast.get('ready') and classic.get('ready'):score=.70*float(fast.get('score',0))+.30*float(classic.get('score',0))
    elif fast.get('ready'):score=float(fast.get('score',0))
    elif classic.get('ready'):score=float(classic.get('score',0))
    else:score=0.0
    strong=str(fast.get('strong_side','WAIT')) if fast.get('ready') else 'WAIT';rev=str(fast.get('reversal_side','WAIT')) if fast.get('ready') else 'WAIT'
    if strong in ('UP','DOWN') and classic.get('ready') and str(classic.get('strong_side','WAIT')) not in (strong,'WAIT'):score*=.76
    out={'ready':bool(fast.get('ready') or classic.get('ready')),'score':_v23919_clip(score),'fast':fast,'classic':classic,'strong_side':strong,
         'reversal_side':rev,'source':'BTC15 brain: 1m 6/13/26/13 + classic 9/26/52/26 cloud context'}
    app._v23919_ichi_cache=(now,out);return out


def _v23919_blue_read(app,now=None):
    now=float(now or time.time());cache=getattr(app,'_v23919_blue_cache',None)
    try:
        if cache and now-float(cache[0])<.70:return cache[1]
    except Exception:pass
    try:r1=list(_v2355_direct_rows(app,60) or [])[-150:]
    except Exception:r1=[]
    try:r5=list(_v2355_direct_rows(app,300) or [])[-90:]
    except Exception:r5=[]
    if len(r1)<38:return {'ready':False,'score':0.0,'bars':len(r1)}
    c1=[float(r['close']) for r in r1];hma=_v293_hma_series(c1,21);atr=_v23919_atr_series(r1,14)
    if not hma or hma[-1] is None or hma[-3] is None or atr[-1] is None:return {'ready':False,'score':0.0,'bars':len(r1)}
    mult=2.15;stops=[None]*len(r1)
    for i,c in enumerate(c1):
        a=atr[i]
        if a is None:continue
        loss=mult*float(a)
        if i==0 or stops[i-1] is None:stops[i]=c-loss;continue
        ps=float(stops[i-1]);pc=float(c1[i-1])
        if c>ps and pc>ps:stops[i]=max(ps,c-loss)
        elif c<ps and pc<ps:stops[i]=min(ps,c+loss)
        elif c>ps:stops[i]=c-loss
        else:stops[i]=c+loss
    stop=stops[-1];prevstop=stops[-2] if len(stops)>1 else None
    stop_state=0.0 if stop is None else (1.0 if c1[-1]>stop else -1.0 if c1[-1]<stop else 0.0)
    trigger='NONE'
    if stop is not None and prevstop is not None:
        if c1[-2]<=prevstop and c1[-1]>stop:trigger='BUY'
        elif c1[-2]>=prevstop and c1[-1]<stop:trigger='SELL'
    hma_slope=_v23919_clip((float(hma[-1])-float(hma[-3]))/max(1.0,float(atr[-1])*.55))
    hma_state=1.0 if hma_slope>0 else -1.0 if hma_slope<0 else 0.0
    price_hma=_v23919_clip((c1[-1]-float(hma[-1]))/max(1.0,float(atr[-1])*1.25))
    htf=0.0
    if len(r5)>=14:
        c5=[float(r['close']) for r in r5];h5=_v293_hma_series(c5,9)
        if h5 and h5[-1] is not None and h5[-3] is not None:htf=1.0 if h5[-1]>h5[-3] else -1.0 if h5[-1]<h5[-3] else 0.0
    trig=.16 if trigger=='BUY' else -.16 if trigger=='SELL' else 0.0
    score=_v23919_clip(.31*hma_state+.19*price_hma+.31*stop_state+.13*htf+trig)
    out={'ready':True,'score':score,'hma':float(hma[-1]),'hma_state':hma_state,'hma_slope':hma_slope,'price_hma':price_hma,
         'atr_stop':None if stop is None else float(stop),'stop_state':stop_state,'trigger':trigger,'htf5_state':htf,'atr':float(atr[-1]),
         'hma_series':hma,'stop_series':stops,'rows':r1,
         'source':'BTC15 Blue: 1m HMA21 + ATR14x2.15 ratchet + 5m HMA9 • no lookahead'}
    app._v23919_blue_cache=(now,out);return out


def _v23919_barrier_read(app,route=None,now=None,ichi=None,blue=None):
    now=float(now or time.time());route=dict(route or getattr(app,'_v220_last',{}) or {})
    ichi=ichi or _v23919_ichimoku_read(app,now);blue=blue or _v23919_blue_read(app,now)
    try:live,_=app.effective_live_price();live=float(live)
    except Exception:return {'ready':False,'signed':0.0}
    fast=dict(ichi.get('fast') or {});atr=max(1.0,float(fast.get('atr') or blue.get('atr') or 1.0))
    try:rpp=dict(route.get('rpp') or _v23917_context(app,route,now) or {})
    except Exception:rpp={}
    ichi_s=float(ichi.get('score',0) or 0);blue_s=float(blue.get('score',0) or 0);rpp_s=float(rpp.get('signed',0) or 0)
    up_bar=max(0.0,min(1.0,float(rpp.get('up_barrier',0) or 0)));dn_bar=max(0.0,min(1.0,float(rpp.get('down_barrier',0) or 0)))
    state=str(rpp.get('state','BETWEEN ZONES') or 'BETWEEN ZONES').upper();react=str(rpp.get('reaction_side','WAIT') or 'WAIT').upper()
    accept_up=1.0 if state=='UPSIDE ACCEPTANCE' else 0.0;accept_dn=1.0 if state=='DOWNSIDE ACCEPTANCE' else 0.0
    reject_up=1.0 if state=='BULLISH REJECTION' else 0.0;reject_dn=1.0 if state=='BEARISH REJECTION' else 0.0
    cloud_thick=max(0.0,min(2.5,float(fast.get('cloud_atr',0) or 0)));price_state=float(fast.get('price_state',0) or 0)
    # Opposing cloud thickness only matters while price has not already accepted beyond it.
    cloud_up_block=(max(0.0,min(1.0,cloud_thick/1.4)) if price_state<=0 else 0.0)
    cloud_dn_block=(max(0.0,min(1.0,cloud_thick/1.4)) if price_state>=0 else 0.0)
    up_pass=max(0.0,min(100.0,50+25*ichi_s+16*blue_s+8*rpp_s-20*up_bar-10*cloud_up_block+13*accept_up-12*reject_dn))
    dn_pass=max(0.0,min(100.0,50-25*ichi_s-16*blue_s-8*rpp_s-20*dn_bar-10*cloud_dn_block+13*accept_dn-12*reject_up))
    signed=_v23919_clip((up_pass-dn_pass)/55.0)
    side='UP' if float(route.get('terminal_signed',0) or 0)>=.08 else 'DOWN' if float(route.get('terminal_signed',0) or 0)<=-.08 else 'WAIT'
    active_pass=up_pass if side=='UP' else dn_pass if side=='DOWN' else max(up_pass,dn_pass)
    verdict=('PASSING / ACCEPTING' if active_pass>=64 else 'BARRIER HOLDING' if active_pass<=38 else 'CONTESTED')
    # Nearest structural levels the 15m route should care about.
    levels=[]
    for nm,key in (('CLOUD LOW','cloud_low'),('CLOUD HIGH','cloud_high'),('KIJUN','kijun'),('TENKAN','tenkan')):
        px=fast.get(key)
        if px is not None:levels.append({'name':nm,'price':float(px),'kind':'ICHIMOKU'})
    for nm,key in (('BLUE HMA','hma'),('BLUE ATR STOP','atr_stop')):
        px=blue.get(key)
        if px is not None:levels.append({'name':nm,'price':float(px),'kind':'BLUE'})
    return {'ready':bool(ichi.get('ready') or blue.get('ready')),'signed':signed,'up_pass_score':up_pass,'down_pass_score':dn_pass,
            'active_side':side,'active_pass_score':active_pass,'verdict':verdict,'levels':levels,'rpp_state':state,'rpp_reaction':react,
            'rpp_up_barrier':up_bar,'rpp_down_barrier':dn_bar,'cloud_thickness_atr':cloud_thick,'live':live,'atr':atr}


def _v23919_bundle(app,route=None,now=None):
    now=float(now or time.time());cache=getattr(app,'_v23919_bundle_cache',None)
    # Route includes live RPP reaction state, so keep this cache short.
    try:
        if cache and now-float(cache[0])<.55:return cache[1]
    except Exception:pass
    ichi=_v23919_ichimoku_read(app,now);blue=_v23919_blue_read(app,now);bar=_v23919_barrier_read(app,route,now,ichi,blue)
    score=_v23919_clip(.52*float(ichi.get('score',0) or 0)+.30*float(blue.get('score',0) or 0)+.18*float(bar.get('signed',0) or 0))
    out={'ready':bool(ichi.get('ready') or blue.get('ready')),'score':score,'ichimoku':ichi,'blue':blue,'barrier':bar,'ts':now}
    app._v23919_bundle_cache=(now,out);return out


# -------------------------- end path / journey -------------------------------
def _v220_terminal_read(self,now=None):
    out=dict(_V23919_BASE_TERMINAL(self,now=now) or {})
    try:
        b=_v23919_bundle(self,out,now or time.time());old=float(out.get('terminal_signed',0) or 0)
        ichi=float((b.get('ichimoku') or {}).get('score',0) or 0);blue=float((b.get('blue') or {}).get('score',0) or 0);bar=float((b.get('barrier') or {}).get('signed',0) or 0)
        # Bounded confirmation layer. RPP already lives in the base terminal.
        adj=.085*ichi+.050*blue+.040*bar;new=_v23919_clip(old+adj)
        out['terminal_signed_pre_ichi_blue']=old;out['terminal_signed']=new;out['ichi_blue_adjustment']=adj
        out['ichimoku_15m']=dict(b.get('ichimoku') or {});out['blue_15m']=dict(b.get('blue') or {});out['barrier_fusion_15m']=dict(b.get('barrier') or {});out['indicator_15m_score']=float(b.get('score',0) or 0)
        # Keep side changes conservative: only a coherent non-neutral read can move a neutral terminal.
        if str(out.get('terminal_side','NEUTRAL')).upper() not in ('UP','DOWN') and abs(new)>=.14:out['terminal_side']='UP' if new>0 else 'DOWN'
        out['terminal_confidence']=max(float(out.get('terminal_confidence',50) or 50),min(98.0,50+abs(new)*44.0))
        self._v220_last=dict(out)
    except Exception:pass
    return out


def _v23919_add_checkpoint(cps,seen,px,label,kind,score,atr):
    try:
        px=float(px)
        if not math.isfinite(px):return
        if any(abs(px-x)<=max(1.0,float(atr)*.07) for x in seen):return
        cps.append({'price':px,'label':label,'kind':kind,'score':score});seen.append(px)
    except Exception:pass


def _v229_journey(self,now=None):
    out=dict(_V23919_BASE_JOURNEY(self,now=now) or {})
    try:b=_v23919_bundle(self,out,now or time.time())
    except Exception:b={}
    if not b.get('ready'):return out
    ichi=dict(b.get('ichimoku') or {});fast=dict(ichi.get('fast') or {});blue=dict(b.get('blue') or {});bar=dict(b.get('barrier') or {})
    cps=[dict(x) for x in list(out.get('checkpoints') or [])];seen=[]
    for c in cps:
        try:seen.append(float(c.get('price')))
        except Exception:pass
    atr=max(1.0,float(bar.get('atr') or fast.get('atr') or blue.get('atr') or 1.0))
    _v23919_add_checkpoint(cps,seen,fast.get('cloud_low'),'ICHI CLOUD LOW','ICHI_CLOUD',78,atr)
    _v23919_add_checkpoint(cps,seen,fast.get('cloud_high'),'ICHI CLOUD HIGH','ICHI_CLOUD',78,atr)
    _v23919_add_checkpoint(cps,seen,fast.get('kijun'),'ICHI KIJUN','ICHI_KIJUN',74,atr)
    _v23919_add_checkpoint(cps,seen,fast.get('tenkan'),'ICHI TENKAN','ICHI_TENKAN',62,atr)
    _v23919_add_checkpoint(cps,seen,blue.get('hma'),'BLUE HMA21','BLUE_HMA',60,atr)
    _v23919_add_checkpoint(cps,seen,blue.get('atr_stop'),'BLUE ATR STOP','BLUE_STOP',67,atr)
    live=float(bar.get('live',0) or 0);cps.sort(key=lambda c:abs(float(c.get('price',live) or live)-live) if live else 0)
    side=str(out.get('route_side',out.get('lock_side','WAIT')) or 'WAIT').upper();sgn=1.0 if side=='UP' else -1.0 if side=='DOWN' else 0.0
    align=float(b.get('score',0) or 0)*sgn if sgn else 0.0
    base=float(out.get('route_match',0) or 0);out['route_match']=max(0.0,min(100.0,(base if base else 50.0)+align*8.0))
    out['checkpoints']=cps;out['ichimoku_15m']=ichi;out['blue_15m']=blue;out['barrier_fusion_15m']=bar;out['indicator_path_align']=align
    old=str(out.get('evidence_text','') or '')
    out['evidence_text']=old+f' • ICHI/BLUE {align:+.2f} • {bar.get("verdict","CONTESTED")} • UP-pass {float(bar.get("up_pass_score",50)):.0f} / DOWN-pass {float(bar.get("down_pass_score",50)):.0f}'
    self._v2673_last_map=dict(out);return out


