_v2673_journey_read=_v229_journey
ChartKingPro._v2673_journey_read=_v229_journey


# ------------------------------- lock packet --------------------------------
def _v23913_current_packet(self,route,into,now):
    q=dict(_V23919_BASE_PACKET(self,route,into,now) or {});side=str(q.get('side','WAIT') or 'WAIT').upper()
    try:b=_v23919_bundle(self,route,now)
    except Exception:b={}
    if not b.get('ready'):
        q['ichimoku_15m']={'ready':False};q['blue_15m']={'ready':False};return q
    sgn=1.0 if side=='UP' else -1.0 if side=='DOWN' else 0.0
    ichi=float((b.get('ichimoku') or {}).get('score',0) or 0);blue=float((b.get('blue') or {}).get('score',0) or 0);bar=float((b.get('barrier') or {}).get('signed',0) or 0)
    vals=(ichi*sgn,blue*sgn,bar*sgn) if sgn else (0.0,0.0,0.0);agrees=sum(1 for x in vals if x>=.22);opposes=sum(1 for x in vals if x<=-.28)
    fam=dict(q.get('families') or {});fam['ICHIMOKU']=bool(sgn and vals[0]>=.24);fam['BLUE']=bool(sgn and vals[1]>=.26);cluster=bool(sgn and agrees>=2);fam['ICHI_BLUE']=cluster;q['families']=fam
    # Correlated technical cluster gets at most ONE breadth point.
    if cluster:q['breadth']=int(q.get('breadth',0) or 0)+1
    oldcomp=float(q.get('composite',0) or 0);nudge=.045*ichi+.030*blue+.025*bar;q['composite']=_v23919_clip(oldcomp+nudge)
    if side in ('UP','DOWN'):
        need=float(q.get('need_s',9.0) or 9.0);edge=float(q.get('edge_need',0.0) or 0.0)
        if agrees>=2:need-=.45;edge=max(0.0,edge-.0025)
        elif opposes>=2:need+=.75;edge+=.0045
        q['need_s']=max(5.5,min(15.5,need));q['edge_need']=edge
        # Preserve the son's strong record: supportive indicators never resurrect
        # a packet the core rejected. Strong opposition may make an ordinary,
        # non-decisive packet wait for the next sample.
        if opposes>=2 and not bool(q.get('decisive')) and sum(vals)/3.0<=-.30:q['qualified']=False
    q['ichimoku_15m']=dict(b.get('ichimoku') or {});q['blue_15m']=dict(b.get('blue') or {});q['barrier_fusion_15m']=dict(b.get('barrier') or {})
    q['indicator_15m_score']=float(b.get('score',0) or 0);q['indicator_15m_align']=(float(b.get('score',0) or 0)*sgn if sgn else 0.0);q['indicator_15m_agrees']=agrees;q['indicator_15m_opposes']=opposes
    q['reason']=str(q.get('reason',''))+f' • ICHI {ichi:+.2f} • BLUE {blue:+.2f} • BARRIER {bar:+.2f}'
    return q


def _v23915_present_alignment(self,q,route,candidate,now):
    out=dict(_V23919_BASE_ALIGN(self,q,route,candidate,now) or {});sgn=1.0 if candidate=='UP' else -1.0
    try:
        vals=(float((q.get('ichimoku_15m') or {}).get('score',0) or 0)*sgn,float((q.get('blue_15m') or {}).get('score',0) or 0)*sgn,float((q.get('barrier_fusion_15m') or {}).get('signed',0) or 0)*sgn)
        agrees=sum(1 for x in vals if x>=.22)
        if agrees>=2:out['support']=int(out.get('support',0) or 0)+1
        out['indicator_support']=agrees;out['indicator_align']=sum(vals)/3.0
    except Exception:pass
    return out


