def _v23911_signature_from_q(q,into=0.0):
    out=dict(_V23919_BASE_SIG(q,into) or {});q=dict(q or {});side=str(q.get('side','WAIT') or 'WAIT').upper();sgn=1.0 if side=='UP' else -1.0 if side=='DOWN' else 0.0
