def _v23911_snapshot(app,now=None):
    out=dict(_V23919_BASE_SNAPSHOT(app,now) or {});side=str(out.get('lock_side','WAIT') or 'WAIT').upper();sgn=1.0 if side=='UP' else -1.0 if side=='DOWN' else 0.0
    try:b=_v23919_bundle(app,getattr(app,'_v220_last',{}) or {},now or time.time())
    except Exception:b={}
    out['ichi15']=float((b.get('ichimoku') or {}).get('score',0) or 0);out['blue15']=float((b.get('blue') or {}).get('score',0) or 0);out['barrier15']=float((b.get('barrier') or {}).get('signed',0) or 0)
    out['ichi15_align']=out['ichi15']*sgn if sgn else None;out['blue15_align']=out['blue15']*sgn if sgn else None;out['barrier15_align']=out['barrier15']*sgn if sgn else None
    return out


def _v23911_similarity(a,b):
    base=float(_V23919_BASE_SIMILARITY(a,b) or 0.0)
    try:
        keys=[k for k in ('ichi15','blue15','barrier15') if k in (a or {}) and k in (b or {})]
        if not keys:return base
        sims=[math.exp(-abs(float(a.get(k,0))-float(b.get(k,0)))/.42) for k in keys]
        return max(0.0,min(1.0,.88*base+.12*(sum(sims)/len(sims))))
    except Exception:return base


def _v23911_diagnose_loss(side,seq,meta):
    out=dict(_V23919_BASE_DIAGNOSE(side,seq,meta) or {});post=list(seq or []);tags=list(out.get('diagnosis') or [])
    def twice(key,thr):
        n=0
        for r in post:
            try:
                if r.get(key) is not None and float(r.get(key))<=thr:n+=1
            except Exception:pass
        return n>=2
    if twice('ichi15_align',-.28) and 'ICHIMOKU_REVERSAL' not in tags:tags.append('ICHIMOKU_REVERSAL')
    if twice('blue15_align',-.32) and 'BLUE_SIGNAL_FLIP' not in tags:tags.append('BLUE_SIGNAL_FLIP')
    if twice('barrier15_align',-.34) and 'CLOUD_RPP_BARRIER_HELD' not in tags:tags.append('CLOUD_RPP_BARRIER_HELD')
    out['diagnosis']=tags or ['UNCLASSIFIED'];return out


