def _v23919_chart_scale(app,c,rows):
    w=max(440,int(c.winfo_width()));h=max(320,int(c.winfo_height()));left=54;right=w-18;top=24;mbi_h=78;bottom=max(top+120,h-mbi_h-24)
    closes=[float(r['close']) for r in rows];_bm,bbup,bbdn=_v236_bands(closes,20,2.0);fvgs=_v236_fvgs(rows)
