def _v23920_bucket(now=None):
    n=float(now or time.time());return int(n//900)*900


def _v23920_lock_text(snap):
    try:
        side=str(snap.get('lock_side','WAIT') or 'WAIT').upper();strength=float(snap.get('strength',0) or 0)
        when=float(snap.get('time',0) or 0);bucket=int(snap.get('bucket',snap.get('market_bucket',0)) or 0)
        sec=max(0.0,when-bucket) if bucket else 0.0
        return f'MAIN LOCK: {side} {strength:.0f}/100 • LOCKED FOR ROUND • earned {sec:.1f}s'
    except Exception:return 'MAIN LOCK: LOCKED FOR THIS 15M ROUND'


def _v23920_clear_anchor(app,bucket=None):
    app._v23920_lock_anchor={}
    # Keep the old V21.40 continuity guard from resurrecting a prior-bucket call.
    try:app._v240_earned_open_lock={}
    except Exception:pass
    try:app._v23917_lock_anchor={}
    except Exception:pass
    if bucket is not None:
        try:app.opening_lock_bucket=int(bucket)
        except Exception:pass


def _v23920_latch(app,snap,now=None,source=None):
    now=float(now or time.time());bucket=_v23920_bucket(now);s=dict(snap or {})
    side=str(s.get('lock_side','WAIT') or 'WAIT').upper()
    try:sb=int(s.get('bucket',s.get('market_bucket',bucket)) or bucket)
    except Exception:sb=bucket
    if side not in ('UP','DOWN') or sb!=bucket:return {}
    s['bucket']=bucket;s['market_bucket']=bucket;s['_v23920_latched']=True;s['_v23920_latched_at']=now
    if source:s['source']=str(source)
    app._v23920_lock_anchor=dict(s);app.opening_lock_snapshot=dict(s);app.opening_lock_bucket=bucket
    # Feed the older continuity watchdog too. Some inherited callbacks still know
    # this field and can therefore restore the exact same first call, never WAIT.
    try:app._v240_earned_open_lock=dict(s)
    except Exception:pass
    try:app._v23917_lock_anchor=dict(s)
    except Exception:pass
    try:
        txt=_v23920_lock_text(s)
        if str(app.opening_lock_var.get() or '')!=txt:app.opening_lock_var.set(txt)
    except Exception:pass
    return dict(s)


def _v23920_restore_anchor(app,now=None):
    now=float(now or time.time());bucket=_v23920_bucket(now);anchor=dict(getattr(app,'_v23920_lock_anchor',{}) or {})
    try:ab=int(anchor.get('bucket',anchor.get('market_bucket',-1)) or -1)
    except Exception:ab=-1
    aside=str(anchor.get('lock_side','WAIT') or 'WAIT').upper()
    if aside in ('UP','DOWN') and ab!=bucket:
        _v23920_clear_anchor(app,bucket);anchor={};aside='WAIT'
    if aside not in ('UP','DOWN'):
        cur=dict(getattr(app,'opening_lock_snapshot',{}) or {});cs=str(cur.get('lock_side','WAIT') or 'WAIT').upper()
        try:cb=int(cur.get('bucket',cur.get('market_bucket',-1)) or -1)
        except Exception:cb=-1
        if cs in ('UP','DOWN') and cb==bucket:
            anchor=_v23920_latch(app,cur,now=now);aside=str(anchor.get('lock_side','WAIT')).upper()
    if aside in ('UP','DOWN'):
        cur=dict(getattr(app,'opening_lock_snapshot',{}) or {});cs=str(cur.get('lock_side','WAIT') or 'WAIT').upper()
        try:cb=int(cur.get('bucket',cur.get('market_bucket',-1)) or -1)
        except Exception:cb=-1
        if cs!=aside or cb!=bucket:app.opening_lock_snapshot=dict(anchor);app.opening_lock_bucket=bucket
        try:
            txt=_v23920_lock_text(anchor)
            if str(app.opening_lock_var.get() or '')!=txt:app.opening_lock_var.set(txt)
        except Exception:pass
        return dict(anchor)
    return {}


def _v23920_deadline_read(app,route,q,now):
    """Best-current-evidence arbitration used only at the end of the first 5m.
    It is deliberately not a new prediction model; it compresses the already-live
    V23.9.19 evidence into one signed tie-break score."""
    route=dict(route or {});q=dict(q or {})
    def clip(x):
        try:return max(-1.0,min(1.0,float(x)))
        except Exception:return 0.0
    comp=clip(q.get('composite',0));terminal=clip(route.get('terminal_signed',0))
    try:tug=dict(_v232_original_tug(app,now=now) or {})
    except Exception:tug={}
    tug_signed=clip(tug.get('signed',tug.get('fused',0)));tug_p=max(0.0,min(1.0,float(tug.get('persistence',0) or 0)))
    mbi=dict(route.get('mbi') or {});mbi_signed=clip(float(mbi.get('forward_score',mbi.get('score',0)) or 0)/100.0)
    indicator=clip(q.get('indicator_15m_score',0));rpp=clip((q.get('rpp') or {}).get('signed',q.get('rpp_align',0)))
    # Composite/route carry most authority. Tug is persistence-weighted. The two
    # new technical layers remain small because they are correlated confirmation.
    score=.46*comp+.24*terminal+.15*tug_signed*(.35+.65*tug_p)+.07*mbi_signed+.05*indicator+.03*rpp
    st=dict(getattr(app,'_v23915_lock_state',{}) or {});cons={}
    try:cons=_v23913_consensus(st.get('samples') or [],now)
    except Exception:cons={}
    cside=str(cons.get('side','WAIT') or 'WAIT').upper();share=float(cons.get('share',.5) or .5)
    if cside in ('UP','DOWN') and share>.50:
        score+=(1.0 if cside=='UP' else -1.0)*min(.07,max(0.0,(share-.50)*.28))
    try:live,_=app.effective_live_price();target,_=app.effective_target()
    except Exception:live=target=None
    # Only a final exact tie uses current location versus the official target.
    if abs(score)<.012 and live is not None and target is not None and float(live)!=float(target):
        score=.0125 if float(live)>float(target) else -.0125
    side='UP' if score>=0 else 'DOWN'
    return {'side':side,'score':score,'comp':comp,'terminal':terminal,'tug':tug_signed,'tug_p':tug_p,
            'mbi':mbi_signed,'indicator':indicator,'rpp':rpp,'consensus':cons,'live':live,'target':target}


def _v23920_make_deadline_lock(app,route,q,now,hard=False):
    d=_v23920_deadline_read(app,route,q,now);live=d.get('live');target=d.get('target')
    if live is None or target is None:return None
    score=float(d.get('score',0) or 0);cons=dict(d.get('consensus') or {})
    # Soft deadline (4:45+) still needs a small directional lean. Final 3 seconds
    # always choose the best current side when official strike + live price exist.
    if not hard and abs(score)<.032 and not (str(cons.get('side','WAIT')) in ('UP','DOWN') and float(cons.get('share',.5) or .5)>=.54):
        return None
    side=str(d.get('side','UP'));bucket=_v23920_bucket(now);into=max(0.0,now-bucket)
    strength=max(51.0,min(78.0,52.0+abs(score)*72.0+max(0.0,float(cons.get('share',.5) or .5)-.5)*18.0))
    reason=(f'V23.9.20 5M DEADLINE {"HARD" if hard else "SOFT"} • score {score:+.3f} • '
            f'core {float(d.get("comp",0)):+.2f} • route {float(d.get("terminal",0)):+.2f} • '
            f'OLD TUG {float(d.get("tug",0)):+.2f} p{float(d.get("tug_p",0))*100:.0f} • '
            f'MBI {float(d.get("mbi",0))*100:+.0f} • ICHI/BLUE {float(d.get("indicator",0)):+.2f} • '
            f'RPP {float(d.get("rpp",0)):+.2f}')
    snap={'time':float(now),'price':float(live),'target':float(target),'lock_side':side,'strength':strength,
          'bucket':bucket,'market_bucket':bucket,'source':'V23.9.20 FIRST-5M DEADLINE LOCK',
          'forecast_reasons':reason,'forecast_score':score*10.0,'forecast_threshold':0.0,
          'lock_remaining':'OPEN','lock_minute':int(into//60),'regime':str((q.get('regime') or {}).get('name','MIXED')),
          'deadline_forced':bool(hard),'deadline_score':score}
    return _v23920_latch(app,snap,now=now,source=snap['source'])


def _v23920_open_lock_tick(self,warm=None,now=None):
    now=float(now or time.time());bucket=_v23920_bucket(now);into=max(0.0,now-bucket)
    anchor=_v23920_restore_anchor(self,now)
    if anchor:return anchor
    # Normal V23.9.19 lock logic gets first shot.
    try:out=_V23920_BASE_OPEN_LOCK(self,warm=warm,now=now)
    except TypeError:out=_V23920_BASE_OPEN_LOCK(self,warm,now)
    except Exception:out=None
    cur=dict(getattr(self,'opening_lock_snapshot',{}) or (out if isinstance(out,dict) else {}) or {})
    side=str(cur.get('lock_side','WAIT') or 'WAIT').upper()
    try:cb=int(cur.get('bucket',cur.get('market_bucket',-1)) or -1)
    except Exception:cb=-1
    if side in ('UP','DOWN') and cb==bucket:
        latched=_v23920_latch(self,cur,now=now)
        try:_v232_add_event(self,f'CALL LATCHED • {side} remains the graded call through this 15m round',_V232_GREEN if side=='UP' else _V232_RED)
        except Exception:pass
        return latched
    # Do not let the inherited >300s branch close the window before final
    # arbitration. We start soft selection at 4:45 and guarantee by ~4:57.
    if into>=285.0:
        try:r=dict(getattr(self,'_v220_last',{}) or {})
        except Exception:r={}
        if not r.get('ready') or now-float(r.get('ts',now) or now)>1.8:
            try:r=dict(_v220_terminal_read(self,now=now) or {})
            except Exception:r={}
        try:q=dict(_v23913_current_packet(self,r,into,now) or {})
        except Exception:q={}
        snap=_v23920_make_deadline_lock(self,r,q,now,hard=(into>=297.0))
        if snap:
            try:
                side=str(snap.get('lock_side'));self.opening_lock_var.set(_v23920_lock_text(snap))
                _v232_add_event(self,f'FIRST-5M DEADLINE LOCK • {side} • '+str(snap.get('forecast_reasons','')),_V232_GREEN if side=='UP' else _V232_RED)
            except Exception:pass
            return snap
        if into>=297.0:
            try:self.opening_lock_var.set('5M DEADLINE • waiting only for valid official strike/live BTC')
            except Exception:pass
    return out

ChartKingPro._bookmap_opening_lock_tick=_v23920_open_lock_tick


