# =============================================================================
# V23.9.20 STANDALONE — HARD 15M ROUND RESET + MAIN-THREAD TARGET REACQUIRE
# =============================================================================
# The old V22.5.1 fix used a worker-result mailbox because Tk variables must be
# committed on the Tk/main thread.  V23.9.14/15 later retired that heartbeat as
# part of the loop purge.  Restore the safe architecture under the single silky
# scheduler: clear stale round identity, reacquire current KXBTC15M, then commit
# target/ticker on the UI thread. BRTI live price is also invalidated at rollover
# so the new round cannot inherit a stale spot sample.
# =============================================================================
_V23920_STANDALONE_TARGET_BASE=_V23915_TARGET_BASE


def _v23920_target_valid(x):
    try:return 1000.0<float(x)<10000000.0 and math.isfinite(float(x))
    except Exception:return False


def _v23920_reset_standalone_round(app,bucket,now=None):
    now=float(now or time.time());app._v23920_round_bucket=int(bucket);app._v23920_target_generation=int(getattr(app,'_v23920_target_generation',0) or 0)+1
    app._v23920_target_result=None;app._v23920_target_inflight=False;app._v23920_target_started=0.0;app._v23920_target_retry_at=0.0
    # New market = new first-lock authority.
    _v23920_clear_anchor(app,bucket)
    try:app.opening_lock_snapshot=None;app.opening_lock_candidate=None;app.opening_lock_candidate_since=0.0
    except Exception:pass
    manual=False
    try:manual=bool(app.use_manual_target_var.get())
    except Exception:manual=False
    if not manual:
        app.target_price=None;app.kalshi_market={};app.kalshi_ticker=''
        for nm,val in (('_v2984_selected_ticker',''),('_v2984_target_ticker',''),('_v23910_strike',None),('_v23910_strike_ticker',''),('_v23910_strike_source','')):
            try:setattr(app,nm,val)
            except Exception:pass
        app._v23910_strike_bucket=int(bucket);app._v26710_target_lock_bucket=int(bucket);app._v26710_target_lock=None;app._v26710_seen_bucket=int(bucket)
        try:app.ticker_var.set('')
        except Exception:pass
        try:app.auto_target_status_var.set('NEW 15M ROUND • RESET OLD STRIKE • REACQUIRING CURRENT KXBTC15M...')
        except Exception:pass
        try:app.auto_market_status_var.set('AUTO MARKET: NEW ROUND • DISCOVERING CURRENT CONTRACT')
        except Exception:pass
    # Never carry a previous-round live sample across the boundary. Historical
    # BRTI ticks stay intact for TA; only the NOW price is invalidated/re-fetched.
    try:app.current_spot=None;app._v2985_spot_ts=0.0
    except Exception:pass
    try:app._v2985_feed_state='NEW 15M ROUND • REACQUIRING KALSHI BRTI BTC PRICE...'
    except Exception:pass
    try:_v232_add_event(app,'NEW 15M ROUND • standalone target + live BTC reset • reacquiring current KXBTC15M/BRTI',_V232_GOLD2)
    except Exception:pass


def _v23920_target_worker(app,bucket,generation):
    try:
        market=app._discover_current_kalshi_market();app._v23920_target_result=(int(generation),int(bucket),True,market,time.time())
    except Exception as exc:
        app._v23920_target_result=(int(generation),int(bucket),False,str(exc),time.time())


def _v23920_price_worker(app,generation):
    try:_v2985_fetch_latest(app)
    except Exception as exc:
        try:app._v23920_price_error=str(exc)
        except Exception:pass
    finally:
        try:
            if int(getattr(app,'_v23920_target_generation',0) or 0)==int(generation):app._v23920_price_inflight=False
        except Exception:app._v23920_price_inflight=False


def _v23920_standalone_target_guard(app):
    now=time.time();bucket=_v23920_bucket(now)
    if getattr(app,'_v23920_round_bucket',None)!=bucket:_v23920_reset_standalone_round(app,bucket,now)
    generation=int(getattr(app,'_v23920_target_generation',0) or 0)
    # Main-thread mailbox commit. No worker touches Tk StringVars.
    pending=getattr(app,'_v23920_target_result',None)
    if pending is not None:
        app._v23920_target_result=None;app._v23920_target_inflight=False
        try:gen,b,ok,payload,ts=pending
        except Exception:gen=b=-1;ok=False;payload='bad target result';ts=now
        if int(gen)==generation and int(b)==bucket:
            if ok:
                market=dict(payload or {})
                try:current=bool(_v23910_market_is_current(app,market,bucket))
                except Exception:current=True
                if current:
                    try:
                        # V21.98.5 commit sets standalone market identity/BBO lane;
                        # V23.9.10 freeze supplies the immutable official strike.
                        _v2985_commit_market(app,market,'V23.9.20 ROUND AUTO REACQUIRE')
                        _v23910_freeze_market_target(app,market,'V23.9.20 MAIN-THREAD REACQUIRE')
                        app._v225_target_bucket=bucket
                    except Exception as exc:
                        app._v23920_target_retry_at=now+.45
                        try:app.auto_target_status_var.set('AUTO TARGET COMMIT RETRY • '+str(exc)[:120])
                        except Exception:pass
                else:
                    app._v23920_target_retry_at=now+.35
            else:
                app._v23920_target_retry_at=now+.55
                try:app.auto_target_status_var.set('AUTO TARGET RETRY • '+str(payload)[:120])
                except Exception:pass
    try:target,_src=app.effective_target()
    except Exception:target=None
    target_ok=_v23920_target_valid(target)
    # Stuck-worker breaker: a failed network request cannot suppress retries for
    # the entire five-minute window.
    if bool(getattr(app,'_v23920_target_inflight',False)) and now-float(getattr(app,'_v23920_target_started',now) or now)>5.0:
        app._v23920_target_inflight=False
    if not target_ok and not bool(getattr(app,'_v23920_target_inflight',False)) and now>=float(getattr(app,'_v23920_target_retry_at',0) or 0):
        app._v23920_target_inflight=True;app._v23920_target_started=now;app._v23920_target_retry_at=now+.75
        threading.Thread(target=_v23920_target_worker,args=(app,bucket,generation),name='LeChartJames-V23920-RoundTarget',daemon=True).start()
    # Live BRTI NOW-price freshness is a separate lane from the strike.
    try:px=getattr(app,'current_spot',None);age=now-float(getattr(app,'_v2985_spot_ts',0) or 0) if getattr(app,'_v2985_spot_ts',0) else 999.0
    except Exception:px=None;age=999.0
    if (px is None or age>2.5) and not bool(getattr(app,'_v23920_price_inflight',False)) and now-float(getattr(app,'_v23920_price_retry_at',0) or 0)>=.80:
        app._v23920_price_inflight=True;app._v23920_price_retry_at=now
        threading.Thread(target=_v23920_price_worker,args=(app,generation),name='LeChartJames-V23920-BRTIReacquire',daemon=True).start()
    try:
        if not target_ok:app.auto_target_status_var.set(f'ROUND {time.strftime("%H:%M",time.localtime(bucket))} • REACQUIRING OFFICIAL KXBTC15M STRIKE...')
    except Exception:pass
    return target

# Silky scheduler owns the authoritative target heartbeat at 750ms.
