def _v23921_png_icon():
    try:
        import struct,zlib
        w=h=180
        rows=[]
        for y in range(h):
            row=bytearray([0])
            for x in range(w):
                # dark background + cyan/pink diagonal J-like slash
                r,g,b,a=(8,9,13,255)
                if 25<x<155 and 26<y<48: r,g,b=(85,200,255)
                if 128<x<154 and 26<y<132: r,g,b=(85,200,255)
                if 48<x<154 and 118<y<145 and x < 154-(y-118)*1.5: r,g,b=(255,107,180)
                row.extend((r,g,b,a))
            rows.append(bytes(row))
        raw=b''.join(rows)
        def chunk(t,d):
            return struct.pack('>I',len(d))+t+d+struct.pack('>I',zlib.crc32(t+d)&0xffffffff)
        return b'\x89PNG\r\n\x1a\n'+chunk(b'IHDR',struct.pack('>IIBBBBB',w,h,8,6,0,0,0))+chunk(b'IDAT',zlib.compress(raw,9))+chunk(b'IEND',b'')
    except Exception:
        return b''


def _v23921_lan_ip():
    s=None
