_V239222_BRTI_EFFECTIVE=_v2985_effective_live_price


def _v239222_public_quote_once():
    errors=[]
    # Coinbase first: same public BTC/USD venue used by the standalone history
    # warmup, which keeps the live guide and visible candle history coherent.
    try:
        d=http_json(COINBASE_BASE+'/products/BTC-USD/ticker',timeout=5)
        px=float(d.get('price') or d.get('last') or 0)
        if math.isfinite(px) and 1000.0<px<10000000.0:
            return px,'COINBASE PUBLIC BTC/USD GUIDE'
        errors.append('coinbase invalid')
    except Exception as exc:
        errors.append('coinbase '+str(exc)[:70])
    # Kraken fallback.
    try:
        d=http_json('https://api.kraken.com/0/public/Ticker',{'pair':'XBTUSD'},timeout=5)
        result=(d or {}).get('result') or {}
        row=next(iter(result.values())) if result else {}
        px=float((row.get('c') or [0])[0])
        if math.isfinite(px) and 1000.0<px<10000000.0:
            return px,'KRAKEN PUBLIC XBT/USD GUIDE'
        errors.append('kraken invalid')
    except Exception as exc:
        errors.append('kraken '+str(exc)[:70])
    # Bitstamp fallback.
    try:
        d=http_json('https://www.bitstamp.net/api/v2/ticker/btcusd/',timeout=5)
        px=float((d or {}).get('last') or 0)
        if math.isfinite(px) and 1000.0<px<10000000.0:
            return px,'BITSTAMP PUBLIC BTC/USD GUIDE'
        errors.append('bitstamp invalid')
    except Exception as exc:
        errors.append('bitstamp '+str(exc)[:70])
    raise RuntimeError(' | '.join(errors)[:240] or 'public BTC feeds unavailable')


def _v239222_ingest_public_quote(self,px,source,ts=None):
    ts=float(ts or time.time());px=float(px)
    if not (math.isfinite(px) and 1000.0<px<10000000.0):
        raise ValueError('invalid public BTC quote')
    ticks=getattr(self,'v2985_brti_ticks',None)
    if not isinstance(ticks,deque):
        ticks=deque(maxlen=30000);self.v2985_brti_ticks=ticks
    # Keep timestamps strictly increasing so the inherited current-bucket
    # builder always observes the newest live close.
    if ticks:
        try:ts=max(ts,float(ticks[-1][0])+0.001)
        except Exception:pass
    ticks.append((ts,px))
    self.v2985_brti_last_ts=ts
    self.current_spot=px
    self._v2985_spot_ts=ts
    self.quote_mesh_price=px;self.quote_mesh_last=ts;self.quote_mesh_source=source
    self.kraken_price=px;self.kraken_tick_ts=ts
    self._v239222_public_source=str(source)
    try:
        self.live_prices.append((ts,px))
        if len(self.live_prices)>20000:self.live_prices=self.live_prices[-16000:]
    except Exception:pass
    try:self._v271_visual_seq=int(getattr(self,'_v271_visual_seq',0) or 0)+1
    except Exception:pass
    try:self._last_chart_render_key=None
    except Exception:pass
    try:self.price_source_var.set(str(source)+' • Kalshi settles on BRTI')
    except Exception:pass
    return (ts,px)


def _v239222_fetch_public_latest(self):
    px,source=_v239222_public_quote_once()
    return _v239222_ingest_public_quote(self,px,source,time.time())


def _v2985_fetch_latest(self):
    # Preserve exact BRTI whenever Railway has valid Kalshi signing credentials.
    try:
        auth=_v2985_prepare_auth(self)
        if auth.get('ready'):
            return _V239222_BRTI_FETCH_LATEST(self)
    except Exception:
        pass
    return _v239222_fetch_public_latest(self)


def _v2985_effective_live_price(self):
    px=getattr(self,'current_spot',None);ts=float(getattr(self,'_v2985_spot_ts',0.0) or 0.0)
    if px is not None:
        age=max(0.0,time.time()-ts) if ts else 999.0
        src=str(getattr(self,'_v239222_public_source','') or '')
        if src:
            return (float(px),f'{src} • {age:.1f}s')
        return (float(px),f'KALSHI CF BRTI • {age:.1f}s')
    return (None,'WAITING FOR LIVE BTC/USD')


def _v2985_brt_worker(self):
    # If exact Kalshi BRTI auth exists, retain the original standalone feed.
    try:
        auth=_v2985_prepare_auth(self,force=True)
    except Exception:
        auth={'ready':False}
    if auth.get('ready'):
        self._v239222_public_source=''
        return _V239222_BRTI_WORKER(self)

    # Railway/cloud fallback: public spot updates the same v2985 tick lane that
    # the existing standalone current-candle adapter already consumes.  This is
    # why no decision logic needs to be rewritten.
    self._v239222_public_source='COINBASE PUBLIC BTC/USD GUIDE'
    self._v2985_feed_state='PUBLIC BTC GUIDE • acquiring live quote...'
    failures=0
    while getattr(self,'running',False) and getattr(self,'live_feed_active',False):
        t0=time.time()
        try:
            _v239222_fetch_public_latest(self);failures=0
            px=float(getattr(self,'current_spot'))
            source=str(getattr(self,'_v239222_public_source','PUBLIC BTC/USD GUIDE'))
            self._v2985_feed_state=f'{source} LIVE • BTC ${px:,.2f} • standalone cloud fallback'
        except Exception as exc:
            failures+=1
            self._v2985_feed_state=f'PUBLIC BTC RETRY {failures} • {str(exc)[:135]}'
        # ~1 Hz is enough to keep the 1m/3m/5m/15m candles and the 15m brain
        # continuously moving without hammering a public REST endpoint.
        time.sleep(max(.10,.90-(time.time()-t0)))


