# =============================================================================
# V23.9.22.3 — CLOUD LIVE CANDLE WATCHDOG / SELF-HEALING PUBLIC BTC FEED
# =============================================================================
# DATA-PLUMBING ONLY. No lock, Original Tug, RPP, Ichimoku, Blue, loss-memory,
# route, confidence or settlement logic is changed. This is the standalone OG.
# Bookmap remains OFF and supplies ZERO candles/quotes to this cloud build.
#
# Why this exists:
#   Railway proved that historical Coinbase candles + Kalshi target acquisition
#   work, while the inherited live-price worker can still end up silent.  This
#   watchdog owns a separate cloud quote thread and continuously restarts it if
#   no fresh quote has been ingested.  It writes into the SAME v2985 tick deque
#   consumed by the existing standalone current-candle adapter.
# =============================================================================
_V239223_RELEASE='V23.9.22.3 CLOUD LIVE CANDLE WATCHDOG'


def _v239223_valid_price(x):
    try:
        x=float(x)
        return math.isfinite(x) and 1000.0 < x < 10000000.0
    except Exception:
        return False


def _v239223_coinbase_candle_close():
    """Last-resort live quote from the SAME Coinbase candles API that warms
    the standalone chart.  Railway has already demonstrated this route works.
    """
    now=time.time()
    start=datetime.fromtimestamp(now-180.0,timezone.utc).isoformat().replace('+00:00','Z')
    end=datetime.fromtimestamp(now+5.0,timezone.utc).isoformat().replace('+00:00','Z')
    data=http_json(COINBASE_BASE+'/products/BTC-USD/candles',
                   {'granularity':60,'start':start,'end':end},timeout=6)
    if not isinstance(data,list) or not data:
        raise RuntimeError('Coinbase recent-candle response empty')
    rows=[]
    for x in data:
        try:
            ts=float(x[0]);close=float(x[4])
            if _v239223_valid_price(close):rows.append((ts,close))
        except Exception:pass
    if not rows:raise RuntimeError('Coinbase recent candle had no valid BTC close')
    rows.sort(key=lambda q:q[0])
    return float(rows[-1][1]),'COINBASE 1M LIVE-CANDLE GUIDE'


def _v239223_fetch_quote_once():
    errs=[]
    # Fast Coinbase Exchange ticker.
    try:
        d=http_json(COINBASE_BASE+'/products/BTC-USD/ticker',timeout=5)
        px=float((d or {}).get('price') or (d or {}).get('last') or 0)
        if _v239223_valid_price(px):return px,'COINBASE PUBLIC BTC/USD GUIDE'
        errs.append('cb ticker invalid')
    except Exception as exc:errs.append('cb ticker '+str(exc)[:80])
    # Coinbase retail spot endpoint gives us a second route/domain.
    try:
        d=http_json('https://api.coinbase.com/v2/prices/BTC-USD/spot',timeout=5)
        px=float((((d or {}).get('data') or {}).get('amount')) or 0)
        if _v239223_valid_price(px):return px,'COINBASE SPOT BTC/USD GUIDE'
        errs.append('cb spot invalid')
    except Exception as exc:errs.append('cb spot '+str(exc)[:80])
    # Kraken.
    try:
        d=http_json('https://api.kraken.com/0/public/Ticker',{'pair':'XBTUSD'},timeout=5)
        result=(d or {}).get('result') or {};row=next(iter(result.values())) if result else {}
        px=float((row.get('c') or [0])[0])
        if _v239223_valid_price(px):return px,'KRAKEN PUBLIC XBT/USD GUIDE'
        errs.append('kraken invalid')
    except Exception as exc:errs.append('kraken '+str(exc)[:80])
    # Bitstamp.
    try:
        d=http_json('https://www.bitstamp.net/api/v2/ticker/btcusd/',timeout=5)
        px=float((d or {}).get('last') or 0)
        if _v239223_valid_price(px):return px,'BITSTAMP PUBLIC BTC/USD GUIDE'
        errs.append('bitstamp invalid')
    except Exception as exc:errs.append('bitstamp '+str(exc)[:80])
    # Most important fallback: reuse the already-working Coinbase candles route.
    try:return _v239223_coinbase_candle_close()
    except Exception as exc:errs.append('cb candle '+str(exc)[:100])
    raise RuntimeError(' | '.join(errs)[-420:] or 'all public BTC live routes failed')


def _v239223_ingest(app,px,source,ts=None):
    ts=float(ts or time.time());px=float(px)
    if not _v239223_valid_price(px):raise ValueError('invalid BTC quote')
    ticks=getattr(app,'v2985_brti_ticks',None)
    if not isinstance(ticks,deque):
        ticks=deque(maxlen=30000);app.v2985_brti_ticks=ticks
    # Avoid equal/backwards timestamps so the current bucket close always advances.
    if ticks:
        try:ts=max(ts,float(ticks[-1][0])+0.001)
        except Exception:pass
    ticks.append((ts,px));app.v2985_brti_last_ts=ts
    app.current_spot=px;app._v2985_spot_ts=ts
    app.quote_mesh_price=px;app.quote_mesh_last=ts;app.quote_mesh_source=source
    app._v239222_public_source=str(source);app._v239223_live_ts=ts
    app._v239223_live_source=str(source);app._v239223_live_error=''
    try:
        app.live_prices.append((ts,px))
        if len(app.live_prices)>20000:app.live_prices=app.live_prices[-16000:]
    except Exception:pass
    try:app._v271_visual_seq=int(getattr(app,'_v271_visual_seq',0) or 0)+1
    except Exception:pass
    try:app._last_chart_render_key=None
    except Exception:pass
    try:app.price_source_var.set(f'{source} • LIVE • Kalshi target remains official')
    except Exception:pass
    try:app.btc_price_var.set(f'BTC ${px:,.2f}')
    except Exception:pass
    return px


def _v239223_live_loop(app,generation):
    failures=0
    while getattr(app,'running',False):
        # A newer watchdog generation supersedes this worker cleanly.
        if int(getattr(app,'_v239223_live_generation',0) or 0)!=int(generation):return
        t0=time.time()
        try:
            px,src=_v239223_fetch_quote_once();_v239223_ingest(app,px,src,time.time())
            failures=0;app._v239223_live_state=f'LIVE ${float(px):,.2f} • {src}'
            if not bool(getattr(app,'_v239223_logged_first_live',False)):
                app._v239223_logged_first_live=True
                print(f'CLOUD BTC LIVE CONNECTED • {src} • ${float(px):,.2f}',flush=True)
        except Exception as exc:
            failures+=1;app._v239223_live_error=str(exc)[:420]
            app._v239223_live_state=f'LIVE FEED RETRY {failures} • '+str(exc)[:160]
            try:app.price_source_var.set(app._v239223_live_state)
            except Exception:pass
        # ~1 Hz when healthy; faster retry initially after a miss.
        delay=.90 if failures==0 else min(2.0,.35+.20*failures)
        time.sleep(max(.10,delay-(time.time()-t0)))


def _v239223_start_live_thread(app,reason='startup'):
    app.live_feed_active=True
    app._v239223_live_generation=int(getattr(app,'_v239223_live_generation',0) or 0)+1
    gen=app._v239223_live_generation
    th=threading.Thread(target=_v239223_live_loop,args=(app,gen),
                        name='LeChartJames-CloudPublicBTC',daemon=True)
    app._v239223_live_thread=th;th.start()
    app._v239223_live_state='STARTING CLOUD BTC LIVE FEED • '+str(reason)
    print('CLOUD BTC WATCHDOG STARTED • '+str(reason),flush=True)
    return th


def _v239223_guard(app):
    try:
        if not getattr(app,'running',False):
            return
        now=time.time();ts=float(getattr(app,'_v239223_live_ts',0.0) or 0.0)
        age=(now-ts) if ts else 9999.0
        th=getattr(app,'_v239223_live_thread',None)
        alive=bool(th and th.is_alive())
        # Restart if worker died OR if it has produced no fresh quote for 8 sec.
        # Generation token prevents two workers from fighting over the candle.
        if (not alive) or age>8.0:
            last_restart=float(getattr(app,'_v239223_last_restart',0.0) or 0.0)
            if now-last_restart>4.0:
                app._v239223_last_restart=now
                _v239223_start_live_thread(app,'watchdog restart' if alive else 'worker restart')
        # Keep the visible diagnostic honest even before first quote.
        if ts:
            src=str(getattr(app,'_v239223_live_source','PUBLIC BTC/USD'))
            try:app.price_source_var.set(f'{src} • age {max(0.0,age):.1f}s • CLOUD STANDALONE')
            except Exception:pass
        elif getattr(app,'_v239223_live_error',''):
            try:app.price_source_var.set('LIVE BTC ERROR • '+str(app._v239223_live_error)[:180])
            except Exception:pass
    finally:
        try:app.root.after(1000,lambda a=app:_v239223_guard(a))
        except Exception:pass


# Return the freshest cloud public quote first.  Authenticated BRTI can still be
# used by inherited lanes when configured, but Bookmap is never consulted here.
def _v239223_effective_live_price(self):
    px=getattr(self,'current_spot',None)
    if _v239223_valid_price(px):
        ts=float(getattr(self,'_v239223_live_ts',getattr(self,'_v2985_spot_ts',0.0)) or 0.0)
        age=max(0.0,time.time()-ts) if ts else 999.0
        src=str(getattr(self,'_v239223_live_source','') or getattr(self,'_v239222_public_source','') or 'BTC/USD LIVE')
        return float(px),f'{src} • {age:.1f}s'
    return None,'WAITING FOR CLOUD PUBLIC BTC/USD LIVE'
ChartKingPro.effective_live_price=_v239223_effective_live_price


_V239223_BASE_START=ChartKingPro.start_manual
def _v239223_start_manual(self):
    out=_V239223_BASE_START(self)
    # Explicitly start a SECOND, cloud-owned transport.  This is intentionally
    # independent of the inherited BRTI worker so a legacy feed path can never
    # leave the Railway candle frozen again.
    try:
        self.bookmap_connected=False
        self.bookmap_status_var.set('BOOKMAP OFF • CLOUD STANDALONE')
    except Exception:pass
    self._v239223_live_ts=0.0;self._v239223_live_error='';self._v239223_last_restart=0.0
    _v239223_start_live_thread(self,'start_manual')
    try:self.root.after(1000,lambda a=self:_v239223_guard(a))
    except Exception:pass
    return out
ChartKingPro.start_manual=_v239223_start_manual



# =============================================================================
# V23.9.22.4 — FOOLPROOF CLOUD STANDALONE MARKET-DATA CORE
# =============================================================================
# DATA TRANSPORT / PHONE RENDERING ONLY.
# NO changes to Original Tug, MAIN LOCK, first-five-minute decision logic, RPP,
# Ichimoku, Blue, loss memory, end-path, confidence math, or Kalshi target logic.
#
# This cloud build is the NON-BOOKMAP standalone OG. Bookmap is explicitly OFF.
#
# Three independent public BTC lanes run in parallel:
#   A) Coinbase public WebSocket ticker (when websocket-client is installed)
#   B) Public REST spot/ticker fallback loop
#   C) Coinbase recent 1m candles — same endpoint proven to warm the chart
#
# Every successful live price updates BOTH current_spot and the current 1m OHLC
# row in _v226_history_1m.  Therefore the brain and the phone chart consume the
# same continuously-moving standalone candle instead of waiting on legacy UI
# caches or a BRTI-only adapter.
# =============================================================================
_V239224_RELEASE='V23.9.22.4 FOOLPROOF CLOUD STANDALONE LIVE DATA'
_V239224_PREV_START=ChartKingPro.start_manual
_V239224_PREV_EFFECTIVE=ChartKingPro.effective_live_price
_V239224_PREV_PHONE_START=_v23921_start_phone_web
_V239224_PREV_MOBILE_ENRICH=_v23921_mobile_enrich


def _v239224_valid_price(x):
    try:
        x=float(x)
        return math.isfinite(x) and 1000.0 < x < 10000000.0
    except Exception:
        return False


def _v239224_feed_lock(app):
    lk=getattr(app,'_v239224_lock',None)
    if lk is None:
        lk=threading.RLock();app._v239224_lock=lk
    return lk


def _v239224_set_hist(app,rows):
    clean=[]
    for r in rows or []:
        q=_v226k_norm_row(r)
        if q:clean.append(q)
    clean.sort(key=lambda r:int(r['time']))
    ded={int(r['time']):r for r in clean}
    clean=[ded[k] for k in sorted(ded)][-1800:]
    app._v226_history_1m=[dict(r) for r in clean]
    app.btc_1m=[dict(r) for r in clean]
    try:app.btc_5m=_v226k_resample(clean,300)
    except Exception:pass
    try:app.btc_15m=_v226k_resample(clean,900)
    except Exception:pass
    try:app.btc_1h=_v226k_resample(clean,3600)
    except Exception:pass
    try:app._v271_visual_seq=int(getattr(app,'_v271_visual_seq',0) or 0)+1
    except Exception:pass
    try:app._last_chart_render_key=None
    except Exception:pass
    return clean


def _v239224_merge_1m_candle(app,row,source='COINBASE 1M'):
    q=_v226k_norm_row(row)
    if not q:return None
    with _v239224_feed_lock(app):
        hist=list(getattr(app,'_v226_history_1m',[]) or getattr(app,'btc_1m',[]) or [])
        by={int(r.get('time',0)):dict(r) for r in hist if isinstance(r,dict)}
        old=by.get(int(q['time']))
        if old:
            # Candle endpoint is authoritative for O/H/L/volume. Preserve any
            # newer tick-close/high/low that arrived milliseconds later.
            oldn=_v226k_norm_row(old) or q
            q['high']=max(float(q['high']),float(oldn['high']))
            q['low']=min(float(q['low']),float(oldn['low']))
            # Only preserve the old close if it is from the current minute and
            # the live tick lane is fresher than this REST response.
            cur=int(time.time()//60)*60
            if int(q['time'])==cur and float(getattr(app,'_v239224_last_ts',0.0) or 0.0)>time.time()-8.0:
                try:q['close']=float(oldn['close'])
                except Exception:pass
            q['high']=max(float(q['high']),float(q['open']),float(q['close']))
            q['low']=min(float(q['low']),float(q['open']),float(q['close']))
        q['_live_source']=source
        by[int(q['time'])]=q
        return _v239224_set_hist(app,[by[k] for k in sorted(by)])[-1]


def _v239224_ingest_price(app,px,source,ts=None):
    px=float(px);ts=float(ts or time.time())
    if not _v239224_valid_price(px):raise ValueError('invalid BTC price')
    with _v239224_feed_lock(app):
        app._v239224_last_price=px;app._v239224_last_ts=ts;app._v239224_source=str(source);app._v239224_error=''
        app.current_spot=px;app._v2985_spot_ts=ts;app.v2985_brti_last_ts=ts
        app.quote_mesh_price=px;app.quote_mesh_last=ts;app.quote_mesh_source=str(source)
        app.kraken_price=px;app.kraken_tick_ts=ts
        app._v239222_public_source=str(source)
        ticks=getattr(app,'v2985_brti_ticks',None)
        if not isinstance(ticks,deque):ticks=deque(maxlen=30000);app.v2985_brti_ticks=ticks
        if ticks:
            try:ts=max(ts,float(ticks[-1][0])+0.0001)
            except Exception:pass
        ticks.append((ts,px))
        try:
            app.live_prices.append((ts,px))
            if len(app.live_prices)>20000:app.live_prices=app.live_prices[-16000:]
        except Exception:pass

        # Directly mutate the standalone 1m OHLC history consumed by the brain.
        bucket=int(ts//60)*60
        hist=list(getattr(app,'_v226_history_1m',[]) or getattr(app,'btc_1m',[]) or [])
        by={int(r.get('time',0)):dict(r) for r in hist if isinstance(r,dict)}
        r=_v226k_norm_row(by.get(bucket,{})) if bucket in by else None
        if r is None:
            prev=None
            if by:
                try:prev=_v226k_norm_row(by[max(k for k in by if k<bucket)])
                except Exception:prev=None
            op=float(prev['close']) if prev else px
            r={'time':bucket,'open':op,'high':max(op,px),'low':min(op,px),'close':px,'volume':0.0,'_live_source':source}
        else:
            r['high']=max(float(r['high']),px);r['low']=min(float(r['low']),px);r['close']=px;r['_live_source']=source
        by[bucket]=r
        _v239224_set_hist(app,[by[k] for k in sorted(by)])
    try:app.btc_price_var.set(f'BTC ${px:,.2f}')
    except Exception:pass
    try:app.price_source_var.set(f'{source} • LIVE CLOUD STANDALONE • Kalshi target official')
    except Exception:pass
    return px


def _v239224_recent_candles_once(app):
    now=time.time();start=now-15*60;end=now
    params={'granularity':60,
            'start':datetime.fromtimestamp(start,timezone.utc).isoformat().replace('+00:00','Z'),
            'end':datetime.fromtimestamp(end,timezone.utc).isoformat().replace('+00:00','Z')}
    data=http_json(COINBASE_BASE+'/products/BTC-USD/candles',params,timeout=5)
    if not isinstance(data,list) or not data:raise RuntimeError('recent Coinbase candles empty')
    parsed=[]
    for x in data:
        try:
            parsed.append({'time':int(float(x[0])),'low':float(x[1]),'high':float(x[2]),'open':float(x[3]),'close':float(x[4]),'volume':float(x[5] or 0),'_live_source':'COINBASE RECENT 1M'})
        except Exception:pass
    if not parsed:raise RuntimeError('recent Coinbase candles invalid')
    parsed.sort(key=lambda r:r['time'])
    for r in parsed:_v239224_merge_1m_candle(app,r,'COINBASE RECENT 1M')
    latest=parsed[-1]
    # If the candles endpoint contains the current or immediately previous bar,
    # its close is a safe bootstrap price even before ticker/WebSocket connects.
    age=max(0.0,now-float(latest['time']))
    live_age=now-float(getattr(app,'_v239224_last_ts',0.0) or 0.0) if getattr(app,'_v239224_last_ts',0.0) else 9999.0
    if age<125 and (not _v239224_valid_price(getattr(app,'_v239224_last_price',None)) or live_age>4.0):
        _v239224_ingest_price(app,float(latest['close']),'COINBASE RECENT 1M CANDLE FALLBACK',now)
    app._v239224_candle_ok=time.time();app._v239224_candle_error=''
    return latest


def _v239224_candle_loop(app):
    while getattr(app,'running',False):
        t0=time.time()
        try:_v239224_recent_candles_once(app)
        except Exception as exc:
            app._v239224_candle_error=str(exc)[:300]
        time.sleep(max(.5,3.0-(time.time()-t0)))


def _v239224_rest_quote_once():
    attempts=(
        ('COINBASE EXCHANGE TICKER',lambda: float((http_json(COINBASE_BASE+'/products/BTC-USD/ticker',timeout=3) or {}).get('price') or 0)),
        ('COINBASE SPOT',lambda: float((((http_json('https://api.coinbase.com/v2/prices/BTC-USD/spot',timeout=3) or {}).get('data') or {}).get('amount')) or 0)),
        ('KRAKEN XBTUSD',lambda: float(next(iter(((http_json('https://api.kraken.com/0/public/Ticker',{'pair':'XBTUSD'},timeout=3) or {}).get('result') or {}).values()))['c'][0])),
        ('BITSTAMP BTCUSD',lambda: float((http_json('https://www.bitstamp.net/api/v2/ticker/btcusd/',timeout=3) or {}).get('last') or 0)),
    )
    errs=[]
    for name,fn in attempts:
        try:
            px=fn()
            if _v239224_valid_price(px):return px,name
            errs.append(name+' invalid')
        except Exception as exc:errs.append(name+' '+str(exc)[:80])
    raise RuntimeError(' | '.join(errs)[-500:])


def _v239224_rest_loop(app):
    while getattr(app,'running',False):
        t0=time.time()
        try:
            px,src=_v239224_rest_quote_once();_v239224_ingest_price(app,px,src,time.time())
            app._v239224_rest_ok=time.time();app._v239224_rest_error=''
        except Exception as exc:
            app._v239224_rest_error=str(exc)[:420]
        time.sleep(max(.15,1.1-(time.time()-t0)))


def _v239224_extract_ws_price(msg):
    # Legacy Coinbase Exchange ticker has top-level `price`.
    try:
        if isinstance(msg,dict) and _v239224_valid_price(msg.get('price')):return float(msg['price'])
    except Exception:pass
    # Advanced Trade market-data messages nest tickers inside events.
    try:
        for ev in (msg.get('events') or []):
            for tk0 in (ev.get('tickers') or []):
                px=tk0.get('price') or tk0.get('last_price')
                if _v239224_valid_price(px):return float(px)
    except Exception:pass
    return None


def _v239224_ws_loop(app):
    try:import websocket
    except Exception as exc:
        app._v239224_ws_error='websocket-client unavailable: '+str(exc)[:180];return
    endpoints=[
        ('COINBASE WS','wss://ws-feed.exchange.coinbase.com',{'type':'subscribe','product_ids':['BTC-USD'],'channels':['ticker']}),
        ('COINBASE ADV WS','wss://advanced-trade-ws.coinbase.com',{'type':'subscribe','product_ids':['BTC-USD'],'channel':'ticker'}),
    ]
    while getattr(app,'running',False):
        connected=False
        for name,url,sub in endpoints:
            if not getattr(app,'running',False):return
            ws=None
            try:
                ws=websocket.create_connection(url,timeout=8,enable_multithread=True)
                ws.send(json.dumps(sub,separators=(',',':')));connected=True
                app._v239224_ws_state=name+' CONNECTED';app._v239224_ws_error=''
                print('CLOUD BTC WEBSOCKET CONNECTED • '+name,flush=True)
                try:ws.settimeout(30)
                except Exception:pass
                while getattr(app,'running',False):
                    raw=ws.recv()
                    if raw is None:raise RuntimeError('websocket closed')
                    try:msg=json.loads(raw) if isinstance(raw,(str,bytes,bytearray)) else raw
                    except Exception:continue
                    px=_v239224_extract_ws_price(msg)
                    if px is not None:
                        _v239224_ingest_price(app,px,name,time.time());app._v239224_ws_ok=time.time()
            except Exception as exc:
                app._v239224_ws_error=name+' '+str(exc)[:240]
            finally:
                try:
                    if ws is not None:ws.close()
                except Exception:pass
            if connected:break
        time.sleep(1.0)


def _v239224_start_feed(app,reason='bootstrap'):
    if not getattr(app,'running',False):app.running=True
    app.live_feed_active=True
    # One-time thread ownership; no restart storm / generation race.
    if bool(getattr(app,'_v239224_started',False)):
        # Heal any individual lane that actually died.
        for attr,target,name in (
            ('_v239224_rest_thread',_v239224_rest_loop,'JamesCloud-REST'),
            ('_v239224_candle_thread',_v239224_candle_loop,'JamesCloud-Candles'),
            ('_v239224_ws_thread',_v239224_ws_loop,'JamesCloud-WebSocket')):
            th=getattr(app,attr,None)
            if not (th and th.is_alive()):
                th=threading.Thread(target=target,args=(app,),name=name,daemon=True);setattr(app,attr,th);th.start()
        return
    app._v239224_started=True;app._v239224_start_reason=str(reason);app._v239224_error=''
    app._v239224_last_price=None;app._v239224_last_ts=0.0;app._v239224_source='STARTING'
    app.bookmap_connected=False
    try:app.bookmap_status_var.set('BOOKMAP OFF • CLOUD STANDALONE OG')
    except Exception:pass
    for attr,target,name in (
        ('_v239224_rest_thread',_v239224_rest_loop,'JamesCloud-REST'),
        ('_v239224_candle_thread',_v239224_candle_loop,'JamesCloud-Candles'),
        ('_v239224_ws_thread',_v239224_ws_loop,'JamesCloud-WebSocket')):
        th=threading.Thread(target=target,args=(app,),name=name,daemon=True);setattr(app,attr,th);th.start()
    print('CLOUD STANDALONE LIVE CORE STARTED • '+str(reason),flush=True)


def _v239224_effective_live_price(self):
    px=getattr(self,'_v239224_last_price',None);ts=float(getattr(self,'_v239224_last_ts',0.0) or 0.0)
    if _v239224_valid_price(px):
        return float(px),f'{getattr(self,"_v239224_source","PUBLIC BTC")} • {max(0.0,time.time()-ts):.1f}s'
    # Bootstrap from the freshest standalone current/previous 1m close.
    try:
        hist=list(getattr(self,'_v226_history_1m',[]) or getattr(self,'btc_1m',[]) or [])
        if hist:
            r=_v226k_norm_row(hist[-1]);age=time.time()-float(r['time'])
            if r and age<125:
                return float(r['close']),f'COINBASE 1M BOOTSTRAP • {max(0.0,age):.0f}s candle'
    except Exception:pass
    try:return _V239224_PREV_EFFECTIVE(self)
    except Exception:return None,'WAITING FOR CLOUD BTC FEED'
