def _v239224_tick_candles(app,sec):
    sec=int(sec);ticks=[]
    try:ticks=[(float(t),float(p)) for t,p in list(getattr(app,'v2985_brti_ticks',()) or []) if time.time()-float(t)<3600]
    except Exception:ticks=[]
    buckets={}
    for ts,px in ticks:
        b=int(ts//sec)*sec;r=buckets.get(b)
        if r is None:buckets[b]={'time':b,'open':px,'high':px,'low':px,'close':px,'volume':0.0}
        else:r['high']=max(r['high'],px);r['low']=min(r['low'],px);r['close']=px
    return [buckets[k] for k in sorted(buckets)][-80:]


def _v239224_mobile_chart_rows(app,label):
    if label in ('15s','30s'):
        return _v239224_tick_candles(app,15 if label=='15s' else 30)
    sec={'1m':60,'3m':180,'5m':300,'15m':900}.get(label,60)
    hist=list(getattr(app,'_v226_history_1m',[]) or getattr(app,'btc_1m',[]) or [])
    if not hist:return []
    if sec==60:return [dict(r) for r in hist[-90:]]
    return [dict(r) for r in _v226k_resample(hist,sec)[-90:]]


def _v239224_mobile_enrich(app,state,now):
    state=_V239224_PREV_MOBILE_ENRICH(app,state,now)
    try:
        _v239224_start_feed(app,'state publisher')
    except Exception:pass
    try:
        px,src=app.effective_live_price();target=(state.get('market') or {}).get('target')
        state.setdefault('market',{})['btc']=float(px) if _v239224_valid_price(px) else None
        if _v239224_valid_price(px):
            state.setdefault('engine',{})['source']=str(src)
        else:
            errs=[str(getattr(app,'_v239224_ws_error','') or ''),str(getattr(app,'_v239224_rest_error','') or ''),str(getattr(app,'_v239224_candle_error','') or '')]
            errs=[e for e in errs if e]
            state.setdefault('engine',{})['source']='CLOUD FEED STARTING'+((' • '+(' | '.join(errs))[-220:]) if errs else '')
        if _v239224_valid_price(px) and _v239224_valid_price(target):state['market']['distance']=float(px)-float(target)
    except Exception:pass
    # Bypass inherited desktop chart caching for the phone. The browser gets
    # fresh standalone OHLC directly from the same arrays the OG brain sees.
    charts=state.setdefault('charts',{})
    for label in ('15s','30s','1m','3m','5m','15m'):
        try:
            rows=_v239224_mobile_chart_rows(app,label)
            if rows:
                pack=charts.setdefault(label,{})
                pack['label']=label;pack['seconds']={'15s':15,'30s':30,'1m':60,'3m':180,'5m':300,'15m':900}[label]
                pack['candles']=rows;pack['updated']=time.time()
        except Exception:pass
    diag={
        'release':_V239224_RELEASE,
        'source':str(getattr(app,'_v239224_source','STARTING')),
        'price':getattr(app,'_v239224_last_price',None),
        'age':(time.time()-float(getattr(app,'_v239224_last_ts',0.0) or 0.0)) if getattr(app,'_v239224_last_ts',0.0) else None,
        'ws':str(getattr(app,'_v239224_ws_state','STARTING')),
        'ws_error':str(getattr(app,'_v239224_ws_error','')),
        'rest_error':str(getattr(app,'_v239224_rest_error','')),
        'candle_error':str(getattr(app,'_v239224_candle_error','')),
        'candle_ok':getattr(app,'_v239224_candle_ok',None),
        'bookmap':False,
    }
    state.setdefault('mobile',{})['live_feed']=diag
    state['version']='V23.9.22.4 CLOUD STANDALONE OG • '+str(state.get('version',''))
    return state
_v23921_mobile_enrich=_v239224_mobile_enrich


