def _v239225_valid(x):
    try:
        x=float(x)
        return math.isfinite(x) and 1000.0 < x < 10000000.0
    except Exception:
        return False


def _v239225_json(url, params=None, timeout=5.0):
    """Independent stdlib HTTP transport with explicit headers/retry safety."""
    import urllib.request as _u225_req
    import urllib.parse as _u225_parse
    import ssl as _u225_ssl
    if params:
        qs=_u225_parse.urlencode(params)
        url += ('&' if '?' in url else '?') + qs
    req=_u225_req.Request(url,headers={
        'User-Agent':'LeChartJames/23.9.22.5 (+Railway)',
        'Accept':'application/json',
        'Cache-Control':'no-cache',
        'Connection':'close',
    })
    ctx=_u225_ssl.create_default_context()
    with _u225_req.urlopen(req,timeout=float(timeout),context=ctx) as resp:
        raw=resp.read()
    return json.loads(raw.decode('utf-8','replace'))


