def _v239225_merge_history(app, rows):
    """Merge external 1m rows without touching strategy decisions."""
    with _v239225_hist_lock(app):
        prior=[]
        for src in (getattr(app,'_v226_history_1m',None),getattr(app,'btc_1m',None)):
            if src:
                prior=list(src);break
        by={}
        for rr in prior:
            try:
                r=_v226k_norm_row(rr);by[int(r['time'])]=dict(r)
            except Exception:pass
        for rr in rows or []:
            try:
                r=_v226k_norm_row(rr);by[int(r['time'])]=dict(r)
            except Exception:pass
        merged=[by[k] for k in sorted(by)][-2500:]
        app._v226_history_1m=[dict(r) for r in merged]
        app.btc_1m=[dict(r) for r in merged]
        try:app._v234_visual_1m=[dict(r) for r in merged[-900:]]
        except Exception:pass
    return merged


def _v239225_ingest_tick(app, px, source, ts=None):
    ts=float(ts or time.time());px=float(px)
    if not _v239225_valid(px):return False
    with _v239225_hist_lock(app):
        app._v239225_price=px;app._v239225_ts=ts;app._v239225_source=str(source)
        app.current_spot=px;app._v2985_spot_ts=ts
        app.quote_mesh_price=px;app.quote_mesh_last=ts;app.quote_mesh_source=str(source)
        ticks=getattr(app,'v2985_brti_ticks',None)
        if not isinstance(ticks,deque):
            ticks=deque(maxlen=30000);app.v2985_brti_ticks=ticks
        if ticks:
            try:ts=max(ts,float(ticks[-1][0])+0.0001)
            except Exception:pass
        ticks.append((ts,px));app.v2985_brti_last_ts=ts
        # Directly mutate the current 1m candle used by the standalone OG.
        bucket=int(ts//60)*60
        hist=list(getattr(app,'_v226_history_1m',[]) or getattr(app,'btc_1m',[]) or [])
        by={}
        for rr in hist:
            try:
                r=_v226k_norm_row(rr);by[int(r['time'])]=dict(r)
            except Exception:pass
        cur=by.get(bucket)
        if cur is None:
            # Preserve a sensible bucket open from the latest known close.
            prev=None
            if by:
                try:prev=by[max(by)]
                except Exception:prev=None
            op=float(prev['close']) if isinstance(prev,dict) and _v239225_valid(prev.get('close')) else px
            cur={'time':bucket,'open':op,'high':max(op,px),'low':min(op,px),'close':px,'volume':0.0,'_live_source':source}
        else:
            cur['high']=max(float(cur.get('high',px)),px)
            cur['low']=min(float(cur.get('low',px)),px)
            cur['close']=px;cur['_live_source']=source
        by[bucket]=cur
        merged=[by[k] for k in sorted(by)][-2500:]
        app._v226_history_1m=[dict(r) for r in merged]
        app.btc_1m=[dict(r) for r in merged]
        try:app._v234_visual_1m=[dict(r) for r in merged[-900:]]
        except Exception:pass
    try:app.btc_price_var.set(f'BTC ${px:,.2f}')
    except Exception:pass
    try:app.price_source_var.set(f'{source} • CLOUD OG LIVE • not Kalshi BRTI')
    except Exception:pass
    return True


def _v239225_feed_worker(app):
    """Independent forever-worker. It does NOT depend on app.running or Tk callbacks."""
    next_candles=0.0;failures=0
    print('V23.9.22.5 CLOUD LIVE WORKER STARTED',flush=True)
    while not bool(getattr(app,'_v239225_stop',False)):
        loop_start=time.time();quote_ok=False
        # Quote lane.
        try:
            px,src=_v239225_quote_once()
            _v239225_ingest_tick(app,px,src,time.time())
            app._v239225_quote_error='';app._v239225_quote_ok=time.time();quote_ok=True;failures=0
            if not bool(getattr(app,'_v239225_first_logged',False)):
                app._v239225_first_logged=True
                print(f'V23.9.22.5 LIVE BTC CONNECTED • {src} • ${px:,.2f}',flush=True)
        except Exception as exc:
            failures+=1;app._v239225_quote_error=str(exc)[:700]
        # Direct candle lane every ~2.5 seconds. This is independent of ticker.
        if time.time()>=next_candles:
            next_candles=time.time()+2.5
            try:
                rows=_v239225_recent_1m_once();_v239225_merge_history(app,rows)
                app._v239225_candle_ok=time.time();app._v239225_candle_error=''
                latest=rows[-1]
                # Guaranteed bootstrap when quote endpoints are unavailable.
                if (not quote_ok) and _v239225_valid(latest.get('close')):
                    age=max(0.0,time.time()-float(latest['time']))
                    if age<125:
                        _v239225_ingest_tick(app,float(latest['close']),'COINBASE 1M LIVE FALLBACK',time.time())
            except Exception as exc:
                app._v239225_candle_error=str(exc)[:700]
        # Keep it responsive but respectful of public APIs.
        elapsed=time.time()-loop_start
        delay=0.85 if failures==0 else min(2.0,0.55+failures*0.12)
        time.sleep(max(0.12,delay-elapsed))


def _v239225_start(app, reason='init'):
    th=getattr(app,'_v239225_thread',None)
    if th is not None and th.is_alive():return th
    app._v239225_stop=False;app._v239225_started_reason=str(reason)
    th=threading.Thread(target=_v239225_feed_worker,args=(app,),name='LeChartJames-V239225-CloudFeed',daemon=True)
    app._v239225_thread=th;th.start()
    return th


