def _v239225_mobile_enrich(app,state,now):
    state=_V239225_PREV_MOBILE_ENRICH(app,state,now)
    _v239225_start(app,'phone publisher')
    px,src=app.effective_live_price()
    market=state.setdefault('market',{})
    market['btc']=float(px) if _v239225_valid(px) else None
    target=market.get('target')
    if _v239225_valid(px) and _v239225_valid(target):market['distance']=float(px)-float(target)
    state.setdefault('engine',{})['source']=str(src)
    state['version']=_V239225_RELEASE
    state.setdefault('mobile',{})['build']='23.9.22.5'
    state['mobile']['live_feed']={
        'release':_V239225_RELEASE,
        'price':float(px) if _v239225_valid(px) else None,
        'source':str(src),
        'age':max(0.0,time.time()-float(getattr(app,'_v239225_ts',0.0) or 0.0)) if getattr(app,'_v239225_ts',0.0) else None,
        'quote_error':str(getattr(app,'_v239225_quote_error','')),
        'candle_error':str(getattr(app,'_v239225_candle_error','')),
        'quote_ok':getattr(app,'_v239225_quote_ok',None),
        'candle_ok':getattr(app,'_v239225_candle_ok',None),
        'thread_alive':bool(getattr(app,'_v239225_thread',None) and app._v239225_thread.is_alive()),
        'bookmap':False,
    }
    # Build phone charts directly from the same 1m array used by the OG brain.
    charts=state.setdefault('charts',{})
    base=_v239225_fetch_1m(app)
    for label,sec in (('1m',60),('3m',180),('5m',300),('15m',900)):
        rows=base if sec==60 else _v226k_resample(base,sec)
        if rows:
            charts[label]={'label':label,'seconds':sec,'candles':[dict(r) for r in rows[-90:]],'updated':time.time()}
    # 15s / 30s remain direct tick-derived micro charts.
    for label,sec in (('15s',15),('30s',30)):
        try:
            rows=_v239224_tick_candles(app,sec)
            if rows:charts[label]={'label':label,'seconds':sec,'candles':rows,'updated':time.time()}
        except Exception:pass
    return state
