def _v239226_valid(x):
    try:
        x=float(x)
        return math.isfinite(x) and 1000.0 < x < 10000000.0
    except Exception:
        return False


def _v239226_json(url,params=None,timeout=5.0):
    """Public Coinbase Exchange HTTP transport. No auth, no Bookmap."""
    import urllib.request as _u226_req
    import urllib.parse as _u226_parse
    import ssl as _u226_ssl
    if params:
        qs=_u226_parse.urlencode(params)
        url += ('&' if '?' in url else '?')+qs
    req=_u226_req.Request(url,headers={
        'User-Agent':'LeChartJames-CoinbaseOG/23.9.22.6',
        'Accept':'application/json',
        'Cache-Control':'no-cache',
        'Pragma':'no-cache',
        'Connection':'close',
    })
    with _u226_req.urlopen(req,timeout=float(timeout),context=_u226_ssl.create_default_context()) as resp:
        raw=resp.read()
    return json.loads(raw.decode('utf-8','replace'))


def _v239226_coinbase_trades_once():
    """Latest public Coinbase BTC-USD trades; sorted oldest->newest."""
    data=_v239226_json('https://api.exchange.coinbase.com/products/BTC-USD/trades',{'limit':20},timeout=5)
    if not isinstance(data,list) or not data:
        raise RuntimeError('Coinbase trades returned no rows')
    rows=[]
    for x in data:
        try:
            px=float(x.get('price') or 0.0);size=float(x.get('size') or 0.0)
            if not _v239226_valid(px):continue
            ts=datetime.fromisoformat(str(x.get('time','')).replace('Z','+00:00')).timestamp()
            rows.append({'id':int(x.get('trade_id') or 0),'time':float(ts),'price':px,'size':max(0.0,size)})
        except Exception:pass
    rows.sort(key=lambda r:(r['time'],r['id']))
    if not rows:raise RuntimeError('Coinbase trades were invalid')
    return rows


def _v239226_coinbase_candles_once(minutes=180):
    """Recent Coinbase 1m OHLC. Same public venue as the live trade feed."""
    now=time.time();start=now-max(20,int(minutes))*60
    params={
        'granularity':60,
        'start':datetime.fromtimestamp(start,timezone.utc).isoformat().replace('+00:00','Z'),
        'end':datetime.fromtimestamp(now,timezone.utc).isoformat().replace('+00:00','Z'),
    }
    data=_v239226_json('https://api.exchange.coinbase.com/products/BTC-USD/candles',params,timeout=6)
    if not isinstance(data,list) or not data:
        raise RuntimeError('Coinbase candles returned no rows')
    out=[]
    for x in data:
        try:
            r={'time':int(float(x[0])),'low':float(x[1]),'high':float(x[2]),
               'open':float(x[3]),'close':float(x[4]),'volume':float(x[5] or 0.0),
               '_live_source':'COINBASE BTC-USD 1M'}
            if _v239226_valid(r['close']):out.append(r)
        except Exception:pass
    out.sort(key=lambda r:int(r['time']))
    if not out:raise RuntimeError('Coinbase candle rows invalid')
    return out


def _v239226_lock(app):
    lk=getattr(app,'_v239226_lock',None)
    if lk is None:
        lk=threading.RLock();app._v239226_lock=lk
    return lk


def _v239226_sync_1m(app,rows):
    """Merge Coinbase bars into the exact standalone OG 1m history lane."""
    with _v239226_lock(app):
        by={}
        for src in (getattr(app,'_v226_history_1m',None),getattr(app,'btc_1m',None)):
            if src:
                for rr in list(src):
                    try:
                        r=_v226k_norm_row(rr);by[int(r['time'])]=dict(r)
                    except Exception:pass
                break
        for rr in rows or []:
            try:
                r=_v226k_norm_row(rr);by[int(r['time'])]=dict(r)
            except Exception:pass
        merged=[by[k] for k in sorted(by)][-3000:]
        app._v226_history_1m=[dict(r) for r in merged]
        app.btc_1m=[dict(r) for r in merged]
        try:app._v234_visual_1m=[dict(r) for r in merged[-1200:]]
        except Exception:pass
    return merged


def _v239226_ingest_trade(app,trade):
    """A Coinbase trade directly updates live price + current 1m OHLC."""
    px=float(trade['price']);ts=float(trade['time']);size=float(trade.get('size',0.0) or 0.0)
    if not _v239226_valid(px):return False
    with _v239226_lock(app):
        app._v239226_price=px;app._v239226_ts=ts;app._v239226_source='COINBASE BTC-USD TRADES'
        app.current_spot=px;app.quote_mesh_price=px;app.quote_mesh_last=time.time();app.quote_mesh_source='COINBASE BTC-USD'
        try:app._v2985_spot_ts=time.time()
        except Exception:pass
        ticks=getattr(app,'v2985_brti_ticks',None)
        if not isinstance(ticks,deque):
            ticks=deque(maxlen=30000);app.v2985_brti_ticks=ticks
        ticks.append((ts,px));app.v2985_brti_last_ts=ts
        bucket=int(ts//60)*60
        hist=list(getattr(app,'_v226_history_1m',[]) or getattr(app,'btc_1m',[]) or [])
        by={}
        for rr in hist:
            try:
                r=_v226k_norm_row(rr);by[int(r['time'])]=dict(r)
            except Exception:pass
        cur=by.get(bucket)
        if cur is None:
            prev=by[max(by)] if by else None
            op=float(prev['close']) if isinstance(prev,dict) and _v239226_valid(prev.get('close')) else px
            cur={'time':bucket,'open':op,'high':max(op,px),'low':min(op,px),'close':px,'volume':size,'_live_source':'COINBASE TRADES'}
        else:
            cur['high']=max(float(cur.get('high',px)),px)
            cur['low']=min(float(cur.get('low',px)),px)
            cur['close']=px
            cur['volume']=float(cur.get('volume',0.0) or 0.0)+size
            cur['_live_source']='COINBASE TRADES'
        by[bucket]=cur
        merged=[by[k] for k in sorted(by)][-3000:]
        app._v226_history_1m=[dict(r) for r in merged];app.btc_1m=[dict(r) for r in merged]
        try:app._v234_visual_1m=[dict(r) for r in merged[-1200:]]
        except Exception:pass
    try:app.btc_price_var.set(f'BTC ${px:,.2f}')
    except Exception:pass
    try:app.price_source_var.set('COINBASE BTC-USD LIVE • CLOUD OG')
    except Exception:pass
    return True


def _v239226_feed_worker(app):
    """Coinbase-only forever worker. Independent of Tk/app.running."""
    print('V23.9.22.6 COINBASE FEED WORKER STARTED',flush=True)
    last_trade_id=int(getattr(app,'_v239226_last_trade_id',0) or 0)
    next_candle=0.0;next_trade=0.0
    while not bool(getattr(app,'_v239226_stop',False)):
        now=time.time()
        if now>=next_trade:
            next_trade=now+0.80
            try:
                trades=_v239226_coinbase_trades_once()
                fresh=[t for t in trades if int(t['id'])>last_trade_id] if last_trade_id else trades[-1:]
                for t in fresh:
                    _v239226_ingest_trade(app,t)
                    last_trade_id=max(last_trade_id,int(t['id']))
                app._v239226_last_trade_id=last_trade_id
                app._v239226_trade_ok=time.time();app._v239226_trade_error=''
                if fresh and not bool(getattr(app,'_v239226_connected_logged',False)):
                    app._v239226_connected_logged=True
                    print(f'V23.9.22.6 COINBASE LIVE • ${float(fresh[-1]["price"]):,.2f}',flush=True)
            except Exception as exc:
                app._v239226_trade_error=str(exc)[:700]
        if now>=next_candle:
            next_candle=now+2.0
            try:
                rows=_v239226_coinbase_candles_once(180);_v239226_sync_1m(app,rows)
                app._v239226_candle_ok=time.time();app._v239226_candle_error=''
                # Candle close is an independent bootstrap if trade polling is temporarily unavailable.
                latest=rows[-1];age=max(0.0,time.time()-float(latest['time']))
                if age<125 and (not _v239226_valid(getattr(app,'_v239226_price',None)) or time.time()-float(getattr(app,'_v239226_ts',0.0) or 0.0)>5.0):
                    pseudo={'id':last_trade_id,'time':time.time(),'price':float(latest['close']),'size':0.0}
                    _v239226_ingest_trade(app,pseudo);app._v239226_source='COINBASE BTC-USD 1M'
            except Exception as exc:
                app._v239226_candle_error=str(exc)[:700]
        time.sleep(0.10)


def _v239226_start(app,reason='init'):
    th=getattr(app,'_v239226_thread',None)
    if th is not None and th.is_alive():return th
    app._v239226_stop=False;app._v239226_reason=str(reason)
