def _v23923_parse_iso_ts(value):
    try:
        s=str(value or '').strip()
        if not s:return time.time()
        return datetime.fromisoformat(s.replace('Z','+00:00')).timestamp()
    except Exception:return time.time()


def _v23923_ws_worker(app):
    """Public Coinbase Exchange ticker stream. REST stays only as fallback."""
    try:
        import websocket as _ws
    except Exception as exc:
        app._v23923_ws_error='websocket-client unavailable: '+str(exc)
        return
    app._v23923_ws_started=time.time()
    while not bool(getattr(app,'_v23923_stop',False)):
        app._v23923_ws_open=False
        try:
            def _on_open(ws):
                app._v23923_ws_open=True;app._v23923_ws_error=''
                ws.send(json.dumps({'type':'subscribe','product_ids':['BTC-USD'],'channels':['ticker','heartbeat']}))
                print('V23.9.23 COINBASE WS CONNECTED',flush=True)
            def _on_message(ws,message):
                try:d=json.loads(message)
                except Exception:return
                if str(d.get('type',''))!='ticker' or str(d.get('product_id',''))!='BTC-USD':return
                try:px=float(d.get('price'));size=float(d.get('last_size') or 0.0)
                except Exception:return
                if not _v239226_valid(px):return
                ts=_v23923_parse_iso_ts(d.get('time'))
                tid=int(d.get('trade_id') or d.get('sequence') or int(ts*1000))
                _v239226_ingest_trade(app,{'id':tid,'time':ts,'price':px,'size':size})
                app._v239226_source='COINBASE WS BTC-USD';app._v23923_ws_ok=time.time();app._v23923_ws_price=px
            def _on_error(ws,error):app._v23923_ws_error=str(error)[:500]
            def _on_close(ws,*args):app._v23923_ws_open=False
            ws=_ws.WebSocketApp('wss://ws-feed.exchange.coinbase.com',on_open=_on_open,on_message=_on_message,on_error=_on_error,on_close=_on_close)
            app._v23923_ws_client=ws
            ws.run_forever(ping_interval=20,ping_timeout=8)
        except Exception as exc:app._v23923_ws_error=str(exc)[:500]
        if not bool(getattr(app,'_v23923_stop',False)):time.sleep(.45)


def _v23923_start_ws(app):
    th=getattr(app,'_v23923_ws_thread',None)
    if th is not None and th.is_alive():return th
    app._v23923_stop=False
    th=threading.Thread(target=_v23923_ws_worker,args=(app,),name='LeChartJames-CoinbaseWS',daemon=True)
    app._v23923_ws_thread=th;th.start();return th


