def _v23923_vwap(rows):
    out=[];pv=0.0;vol=0.0
    for r in rows:
        try:
            v=max(0.0,float(r.get('volume',0.0) or 0.0));typ=(float(r['high'])+float(r['low'])+float(r['close']))/3.0
            w=v if v>0 else 1.0;pv+=typ*w;vol+=w;out.append(pv/vol)
        except Exception:out.append(None)
    return out


def _v23923_bands(rows,n=20,mult=2.0):
    cls=[float(r['close']) for r in rows];mid=[None]*len(cls);up=[None]*len(cls);dn=[None]*len(cls)
    for i in range(len(cls)):
        if i+1<n:continue
        s=cls[i-n+1:i+1];m=sum(s)/n;var=sum((x-m)**2 for x in s)/n;sd=math.sqrt(max(0.0,var));mid[i]=m;up[i]=m+mult*sd;dn[i]=m-mult*sd
    return mid,up,dn


