def _v23925_clip(x,lo=-1.0,hi=1.0):
    try:return max(float(lo),min(float(hi),float(x)))
    except Exception:return 0.0


def _v23925_storage_root(app=None):
    raw=str(os.environ.get('RAILWAY_VOLUME_MOUNT_PATH') or os.environ.get('JAMES_DATA_DIR') or '').strip()
    if raw:
        try:
            p=Path(raw);p.mkdir(parents=True,exist_ok=True);return p
        except Exception:pass
    try:
        if app is not None:return Path(getattr(app,'stockpile_db_path')).parent
    except Exception:pass
    return Path(__file__).resolve().parent


def _v23925_init_tables(app):
    if bool(getattr(app,'_v23925_db_ready',False)):return True
    try:
        with app.stockpile_db_lock:
            with app._stockpile_connect() as c:
                c.execute('''CREATE TABLE IF NOT EXISTS rpp_behavior_events (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    bucket INTEGER NOT NULL,
                    start_ts REAL NOT NULL,
                    end_ts REAL NOT NULL,
                    level REAL NOT NULL,
                    level_kind TEXT NOT NULL,
                    probability REAL,
                    density_band INTEGER,
                    break_side TEXT,
                    hold_side TEXT,
                    outcome TEXT,
                    tests INTEGER,
                    approach_atr REAL,
                    flow_score REAL,
                    mbi_score REAL,
                    ichi_score REAL,
                    blue_score REAL,
                    confirmation TEXT,
                    max_break_atr REAL,
                    max_hold_atr REAL,
                    payload TEXT
                )''')
                c.execute('CREATE INDEX IF NOT EXISTS idx_rpp_behavior_kind ON rpp_behavior_events(level_kind,density_band,end_ts)')
                c.execute('''CREATE TABLE IF NOT EXISTS round_decision_replay (
                    bucket INTEGER NOT NULL,
                    sample_slot INTEGER NOT NULL,
                    ts REAL NOT NULL,
                    into_s REAL,
                    price REAL,
                    target REAL,
                    ticker TEXT,
                    lock_side TEXT,
                    candidate TEXT,
                    tug REAL,
                    mbi REAL,
                    rpp_state TEXT,
                    barrier_level REAL,
                    barrier_kind TEXT,
                    break_pressure REAL,
                    hold_pressure REAL,
                    confirmation TEXT,
                    reason TEXT,
                    PRIMARY KEY(bucket,sample_slot)
                )''')
                c.execute('CREATE INDEX IF NOT EXISTS idx_round_replay_bucket ON round_decision_replay(bucket,ts)')
        app._v23925_db_ready=True
        return True
    except Exception as exc:
        app._v23925_db_error=str(exc)[:300]
        return False


def _v23925_atr_1m(rows):
    rs=list(rows or [])[-30:]
    if len(rs)<2:return 20.0
    vals=[]
    try:
        prev=float(rs[0]['close'])
        for r in rs[1:]:
            h=float(r['high']);l=float(r['low']);c=float(r['close'])
            vals.append(max(h-l,abs(h-prev),abs(l-prev)));prev=c
    except Exception:return 20.0
    vals=[x for x in vals[-14:] if math.isfinite(x)]
    return max(1.0,sum(vals)/len(vals)) if vals else 20.0


def _v23925_1m_confirmation(app,now=None):
    try:rows=[dict(r) for r in _v23924_rows(app,'1m')[-8:]]
    except Exception:rows=[]
    if len(rows)<4:return {'ready':False,'side':'WAIT','strength':0.0,'state':'BUILDING','reason':f'Need 4+ 1m candles ({len(rows)})'}
    atr=_v23925_atr_1m(rows);a,b,c=rows[-3],rows[-2],rows[-1]
    try:
        ah,al=float(a['high']),float(a['low']);bh,bl=float(b['high']),float(b['low']);co,cc,ch,cl=map(float,(c['open'],c['close'],c['high'],c['low']))
    except Exception:return {'ready':False,'side':'WAIT','strength':0.0,'state':'BAD DATA','reason':'1m OHLC unavailable'}
    eps=max(1.0,.025*atr);body=abs(cc-co)/atr
    lower_high=bh<ah-eps;higher_low=bl>al+eps;red=cc<co;green=cc>co
    red_follow=red and (cc<float(b['close'])-.055*atr or cc<bl-.015*atr) and body>=.10
    green_follow=green and (cc>float(b['close'])+.055*atr or cc>bh+.015*atr) and body>=.10
    bear_reclaim=lower_high and green and (ch>=bh-eps or cc>float(b['close'])+.05*atr)
    bull_reject=higher_low and red and (cl<=bl+eps or cc<float(b['close'])-.05*atr)
    if lower_high and red_follow:
        strength=min(1.0,.48+min(.30,body*.38)+min(.22,max(0.0,(bl-cc)/atr)*.7))
        return {'ready':True,'side':'DOWN','strength':strength,'state':'LOWER HIGH → RED FOLLOW-THROUGH','reason':'1m lower high confirmed by meaningful red continuation','lower_high':True,'higher_low':False,'atr':atr}
    if higher_low and green_follow:
        strength=min(1.0,.48+min(.30,body*.38)+min(.22,max(0.0,(cc-bh)/atr)*.7))
        return {'ready':True,'side':'UP','strength':strength,'state':'HIGHER LOW → GREEN FOLLOW-THROUGH','reason':'1m higher low confirmed by meaningful green continuation','lower_high':False,'higher_low':True,'atr':atr}
    if bear_reclaim:
        return {'ready':True,'side':'WAIT','strength':.55,'state':'LOWER-HIGH SETUP RECLAIMED','reason':'lower high existed, but the next 1m candle reclaimed upward — bearish confirmation withheld','lower_high':True,'higher_low':False,'atr':atr}
    if bull_reject:
        return {'ready':True,'side':'WAIT','strength':.55,'state':'HIGHER-LOW SETUP REJECTED','reason':'higher low existed, but the next 1m candle rejected downward — bullish confirmation withheld','lower_high':False,'higher_low':True,'atr':atr}
    setup='LOWER HIGH — WAITING FOLLOW-THROUGH' if lower_high else 'HIGHER LOW — WAITING FOLLOW-THROUGH' if higher_low else 'NO CLEAN 1M STRUCTURE TRIGGER'
    return {'ready':True,'side':'WAIT','strength':0.0,'state':setup,'reason':'setup only; James waits for the next candle to confirm','lower_high':lower_high,'higher_low':higher_low,'atr':atr}


def _v23925_nearest_barrier(app,ctx=None,now=None):
    now=float(now or time.time())
    try:ctx=dict(ctx or _v23917_context(app,getattr(app,'_v220_last',{}) or {},now) or {})
    except Exception:ctx={}
    if not ctx.get('ready'):return {'ready':False,'reason':'RPP building'}
    live=float(ctx.get('live',0) or 0);atr=max(1.0,float(ctx.get('atr',1) or 1));levels=list(ctx.get('all_levels') or [])
    if not levels:return {'ready':False,'reason':'No active RPP levels'}
    z=min(levels,key=lambda x:abs(float(x.get('level',live))-live));level=float(z.get('level'));dist=(live-level)/atr
    kind='SUPPORT' if bool(z.get('isSupport')) else 'RESISTANCE';break_side='DOWN' if kind=='SUPPORT' else 'UP';hold_side='UP' if kind=='SUPPORT' else 'DOWN'
    return {'ready':True,'live':live,'atr':atr,'level':level,'kind':kind,'probability':float(z.get('probability',0) or 0),'state':str(z.get('state','')),'distance_atr':dist,'break_side':break_side,'hold_side':hold_side,'ctx':ctx}


