    if len(rows)<3:return 0.0
    try:
        n=min(4,len(rows)-1);old=float(rows[-1-n]['close']);cur=float(rows[-1]['close'])
        return _v23925_clip((cur-old)/max(1.0,float(atr))/max(1.0,float(n)), -.9, .9)
    except Exception:return 0.0


