# =============================================================================
# V23.9.27 — RPP PATH SURVIVAL + EMERGENCY OPPOSITE LOCK
# =============================================================================
# Purpose:
#   1) Hammer the forward RPP logic harder into ordinary MAIN LOCK qualification.
#      Each side gets a path-survival score based on the active reversal points
#      it must break or hold to finish on that side of the Kalshi target.
#   2) Add a separate EMERGENCY LOCK. MAIN LOCK remains the immutable historical
#      first call, but after it exists an accepted RPP breakout in the OPPOSITE
#      direction may latch an emergency end-game call when multiple live families
#      agree that the breakout has transferred control.
#
# Safety / anti-wick rules:
#   * Emergency can only oppose a current-round MAIN LOCK.
#   * It requires an ACTUAL accepted RPP break, not merely a forecast.
#   * Terminal path, forward RPP map, Tug/flow and other sensors must agree.
#   * Evidence must persist briefly; a single wick cannot latch it.
#   * Once earned, Emergency Lock is sticky for that 15m round and resets next.
# =============================================================================
_V23927_RELEASE='V23.9.27 RPP PATH SURVIVAL • EMERGENCY OPPOSITE LOCK'


def _v23927_side_sign(side):
    s=str(side or 'WAIT').upper()
    return 1.0 if s=='UP' else -1.0 if s=='DOWN' else 0.0


def _v23927_path_survival(app,now=None,scenario=None):
    """Score how survivable the UP and DOWN routes are through nearby RPPs.

    This is deliberately a route score, not a literal probability of settlement.
    For resistance, UP needs BREAK while DOWN benefits from HOLD. For support,
    DOWN needs BREAK while UP benefits from HOLD. Relevance/reach determine how
    much each battlefield matters to this round.
    """
    now=float(now or time.time())
    try:sc=dict(scenario or _v23926_rpp_scenario(app,now) or {})
    except Exception as exc:return {'ready':False,'reason':str(exc)[:120]}
    if not sc.get('ready'):return {'ready':False,'reason':str(sc.get('reason','RPP scenario building')),'scenario':sc}
    levels=list(sc.get('levels') or [])
    if not levels:return {'ready':False,'reason':'No forward RPP levels','scenario':sc}
    out={}
    for side in ('UP','DOWN'):
        num=den=0.0;details=[]
        for z in levels:
            try:
                rel=max(.02,min(1.65,float(z.get('relevance',0) or 0)))
                reach=max(.0,min(1.0,float(z.get('reach_score',0) or 0)))
                if str(z.get('break_side'))==side:surv=float(z.get('break_forecast',50) or 50)/100.0;needed='BREAK'
                elif str(z.get('hold_side'))==side:surv=float(z.get('hold_forecast',50) or 50)/100.0;needed='HOLD'
                else:continue
                # Target-path barriers matter most; off-route levels still inform
                # alternate end paths without swamping the corridor.
                w=rel*(.42+.58*reach)*(1.20 if bool(z.get('corridor')) and str(z.get('corridor_side'))==side else 1.0)
                num+=surv*w;den+=w
                details.append({'level':float(z.get('level',0) or 0),'kind':str(z.get('kind','RPP')),'needed':needed,'survival':surv*100.0,'weight':w,'corridor':bool(z.get('corridor'))})
            except Exception:pass
        score=50.0 if den<=1e-9 else max(5.0,min(95.0,100.0*num/den))
        out[side.lower()]={'score':score,'weight':den,'levels':details}
    up=float(out.get('up',{}).get('score',50));dn=float(out.get('down',{}).get('score',50))
    signed=max(-1.0,min(1.0,(up-dn)/50.0))
    return {'ready':True,'up':out.get('up',{}),'down':out.get('down',{}),'signed':signed,'advantage':abs(up-dn),'preferred_side':'UP' if up>dn+3 else 'DOWN' if dn>up+3 else 'WAIT','scenario':sc,'source':'RPP route survival • BREAK/HOLD requirement at every selected forward barrier'}


# Hammer route survival into normal lock qualification on top of V23.9.26.
_V23927_BASE_PACKET=_v23913_current_packet
def _v23913_current_packet(self,route,into,now):
    q=dict(_V23927_BASE_PACKET(self,route,into,now) or {})
    try:ps=_v23927_path_survival(self,now,scenario=q.get('rpp_precontact'))
    except Exception:ps={'ready':False}
    q['rpp_path_survival']=ps;side=str(q.get('side','WAIT') or 'WAIT').upper()
    if ps.get('ready') and side in ('UP','DOWN'):
        own=float((ps.get(side.lower()) or {}).get('score',50) or 50);other=float((ps.get(('down' if side=='UP' else 'up')) or {}).get('score',50) or 50)
        # Alignment captures both absolute survivability and advantage over the
        # opposite route. This intentionally has more authority than V23.9.26's
        # first forward modifier, while remaining bounded.
        align=max(-1.0,min(1.0,((own-50.0)/42.0)+((own-other)/85.0)))
        q['rpp_path_align']=align;q['rpp_path_score']=own;q['rpp_opposite_path_score']=other
        if align>=.15:
            q['composite']=_v23925_clip(float(q.get('composite',0) or 0)+min(.060,.050*align))
            q['need_s']=max(4.6,float(q.get('need_s',9) or 9)-min(1.35,.95*align+.18))
            q['edge_need']=max(0.0,float(q.get('edge_need',0) or 0)-min(.0065,.0055*align))
        elif align<=-.18:
            q['need_s']=min(17.0,float(q.get('need_s',9) or 9)+min(1.75,1.12*abs(align)+.22))
            q['edge_need']=float(q.get('edge_need',0) or 0)+min(.009,.0075*abs(align))
            # A badly obstructed route cannot ordinary-lock unless the inherited
            # packet has already marked the case decisive.
            if own<=34.0 and other>=58.0 and not bool(q.get('decisive')):
                q['qualified']=False;q['v23927_path_veto']=True
        q['reason']=str(q.get('reason',''))+f' • PATH {side} {own:.0f} vs {other:.0f} • align {align:+.2f}'
    return q


def _v23927_main_lock(app,now=None):
    now=float(now or time.time());bucket=_v23920_bucket(now)
    # Prefer immutable V23.9.20 anchor so later display mutations cannot change
    # the historical first call.
    for obj in (getattr(app,'_v23920_lock_anchor',{}),getattr(app,'opening_lock_snapshot',{})):
        try:
            s=dict(obj or {});side=str(s.get('lock_side','WAIT') or 'WAIT').upper();b=int(s.get('bucket',s.get('market_bucket',-1)) or -1)
            if side in ('UP','DOWN') and b==bucket:return side,b,s
        except Exception:pass
    return 'WAIT',bucket,{}


def _v23927_breakout_gate(app,opp,now=None):
    """Require real RPP acceptance through a barrier in the emergency direction."""
    now=float(now or time.time())
    try:bp=dict(_v23925_barrier_pressure(app,now) or {})
    except Exception:bp={}
    if not bp.get('ready'):return {'ready':False,'reason':'No active RPP breakout battle','barrier':bp}
    if str(bp.get('break_side','WAIT'))!=opp:return {'ready':False,'reason':'Nearest RPP break is not opposite MAIN LOCK','barrier':bp}
    # barrier_pressure already carries signed distance in ATR units:
    #   positive = live above level, negative = live below level.
    # Using it directly avoids accidentally treating raw dollars as ATRs.
    try:
        d=float(bp.get('distance_atr',0) or 0);level=float(bp.get('level'))
    except Exception:return {'ready':False,'reason':'Breakout distance unavailable','barrier':bp}
    penetration=d if opp=='UP' else -d
    pressure=float(bp.get('break_pressure',50) or 50)
    accepted=penetration>=.075 and pressure>=66.0 and str(bp.get('verdict',''))=='PASSING / ACCEPTING'
    return {'ready':accepted,'penetration_atr':penetration,'break_pressure':pressure,'level':level,'kind':str(bp.get('kind','RPP')),'barrier':bp,'reason':'accepted breakout' if accepted else f'Need acceptance: penetration {penetration:.2f} ATR • break pressure {pressure:.0f}'}


def _v23927_emergency_read(app,now=None,update=True):
    """Read/update the separate opposite-side Emergency Lock state."""
    now=float(now or time.time());bucket=_v23920_bucket(now);main,_,main_snap=_v23927_main_lock(app,now)
    st=dict(getattr(app,'_v23927_emergency_state',{}) or {})
    if int(st.get('bucket',-1) or -1)!=bucket:st={'bucket':bucket,'status':'WAITING','candidate_since':0.0,'candidate_side':'WAIT','locked':False}
    if bool(st.get('locked')) and str(st.get('side','WAIT')) in ('UP','DOWN'):
        app._v23927_emergency_state=st;return dict(st)
    if main not in ('UP','DOWN'):
        st.update({'status':'WAITING FOR MAIN LOCK','main_side':main,'side':'WAIT','locked':False});app._v23927_emergency_state=st;return dict(st)
    opp='DOWN' if main=='UP' else 'UP';sgn=_v23927_side_sign(opp)
    gate=_v23927_breakout_gate(app,opp,now)
    try:terminal=dict(_v220_terminal_read(app,now=now) or {})
    except Exception:terminal={}
    try:sc=dict(_v23926_rpp_scenario(app,now) or {})
    except Exception:sc={}
    try:ps=dict(_v23927_path_survival(app,now,scenario=sc) or {})
    except Exception:ps={}
    try:sens=dict(_v23925_sensor_snapshot(app,now) or {})
    except Exception:sens={}
    conf=dict(sens.get('confirmation') or {})
    terminal_o=sgn*float(terminal.get('terminal_signed',0) or 0)
    scenario_o=sgn*float(sc.get('signed',0) or 0) if sc.get('ready') else 0.0
    tug_o=sgn*float(sens.get('tug',0) or 0);mbi_o=sgn*float(sens.get('mbi',0) or 0)
    conf_side=str(conf.get('side','WAIT'));conf_o=float(conf.get('strength',0) or 0) if conf_side==opp else -float(conf.get('strength',0) or 0) if conf_side==main else 0.0
    bp=dict(gate.get('barrier') or {});barrier_o=max(-1.0,min(1.0,(float(bp.get('break_pressure',50) or 50)-50.0)/45.0)) if str(bp.get('break_side'))==opp else 0.0
    opp_path=float((ps.get(opp.lower()) or {}).get('score',50) or 50);main_path=float((ps.get(main.lower()) or {}).get('score',50) or 50);path_o=max(-1.0,min(1.0,(opp_path-main_path)/42.0))
    factors=[('END PATH',terminal_o,.25),('RPP FORWARD',scenario_o,.18),('ACCEPTED BREAK',barrier_o,.22),('TUG/FLOW',tug_o,.14),('MBI',mbi_o,.07),('1M CONFIRM',conf_o,.07),('PATH ADVANTAGE',path_o,.07)]
    score=sum(_v23925_clip(v)*w for _,v,w in factors)/sum(w for _,_,w in factors)
    positives=sum(1 for _,v,w in factors if v>=.14 and w>=.07)
    # Emergency is deliberately harder than an ordinary live opinion flip. It
    # needs the actual breakout gate + coherent end-game evidence.
    qualifies=bool(gate.get('ready')) and score>=.40 and positives>=4 and terminal_o>=.18 and (scenario_o>=.10 or path_o>=.18)
    rem=max(0.0,float(bucket+900-now));qualifies=qualifies and rem>=4.0
    if qualifies:
        if str(st.get('candidate_side'))!=opp or float(st.get('candidate_since',0) or 0)<=0:
            st['candidate_side']=opp;st['candidate_since']=now
        age=now-float(st.get('candidate_since',now));need=2.4 if score>=.58 and float(gate.get('penetration_atr',0) or 0)>=.12 else 3.6
        st.update({'status':'ARMED • BREAKOUT CONFIRMING','main_side':main,'side':'WAIT','candidate':opp,'score':score,'strength':50+50*max(0.0,min(1.0,score)),'persistence_s':age,'need_s':need,'breakout':gate,'path_survival':ps,'terminal_side':str(terminal.get('terminal_side','WAIT')),'factors':[{'name':n,'score':float(v),'weight':float(w)} for n,v,w in factors],'time_left_s':rem})
        if update and age>=need:
            st.update({'status':'EMERGENCY LOCKED','locked':True,'side':opp,'locked_at':now,'locked_into_s':now-bucket,'source':'ACCEPTED RPP BREAKOUT + OPPOSITE END-GAME TRANSFER','main_snapshot':main_snap})
            try:_v232_add_event(app,f'EMERGENCY LOCK • {main} → {opp} • RPP breakout accepted • score {score:.2f}',_V232_GOLD2)
            except Exception:pass
    else:
        st.update({'status':'WATCHING OPPOSITE BREAKOUT','main_side':main,'side':'WAIT','candidate':opp,'score':score,'strength':50+50*max(0.0,min(1.0,score)),'persistence_s':0.0,'need_s':3.6,'breakout':gate,'path_survival':ps,'terminal_side':str(terminal.get('terminal_side','WAIT')),'factors':[{'name':n,'score':float(v),'weight':float(w)} for n,v,w in factors],'time_left_s':rem})
        st['candidate_side']='WAIT';st['candidate_since']=0.0
    app._v23927_emergency_state=st;return dict(st)


# Extend the 750ms learning tick with Emergency Lock evaluation. The inherited
# tick remains responsible for scheduling the next call.
